  `base_dish_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '基础菜品名称(特色料理)',
  `character_id` int(0) NULL DEFAULT NULL COMMENT '角色ID(特色料理)',
  `character_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '角色名称(特色料理)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_rarity`(`rarity`) USING BTREE,
  INDEX `idx_foodtype`(`foodtype`) USING BTREE,
  INDEX `idx_filter_type`(`filter_type`) USING BTREE,
  INDEX `idx_character_name`(`character_name`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '原神菜品数据表' ROW_FORMAT = Dynamic;

