  INDEX `idx_materials_sort_rank`(`sort_rank`) USING BTREE,
  INDEX `idx_materials_drop_domain`(`drop_domain_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '原神素材表' ROW_FORMAT = Dynamic;

