INSERT INTO `genshin_character` VALUES (10000020, '雷泽', '狼少年', '住在蒙德地区奔狼领，远离城市与人群，和狼一同生活的少年。直觉锐利，身姿迅捷。', 'WEAPON_CLAYMORE', '双手剑', 'BODY_BOY', '男', 'QUALITY_PURPLE', 4, '9/9', '9月9日', 'ELEMENT_ELECTRO', '雷', '奔狼领', 'ASSOC_MONDSTADT', '蒙德', 'FIGHT_PROP_PHYSICAL_ADD_HURT', '物理伤害加成', '小狼座', '周帅', '托德·哈伯空', '内山昂辉', '金徐暎');
INSERT INTO `genshin_character` VALUES (10000021, '安柏', '飞行冠军', '永远充满活力的女孩，骑士团最优秀，同时也是最后的侦察骑士。', 'WEAPON_BOW', '弓', 'BODY_GIRL', '女', 'QUALITY_PURPLE', 4, '8/10', '8月10日', 'ELEMENT_PYRO', '火', '西风骑士团', 'ASSOC_MONDSTADT', '蒙德', 'FIGHT_PROP_ATTACK_PERCENT', '攻击力', '小兔座', '蔡书瑾', '凯莉·巴斯金', '石见舞菜香', '金延佑');
