INSERT INTO `genshin_character` VALUES (10000023, '香菱', '万民百味', '来自璃月，名声在外的少女厨师，对料理之道极具热情，拿手麻辣菜肴堪称一绝。', 'WEAPON_POLE', '长柄武器', 'BODY_GIRL', '女', 'QUALITY_PURPLE', 4, '11/2', '11月2日', 'ELEMENT_PYRO', '火', '万民堂', 'ASSOC_LIYUE', '璃月', 'FIGHT_PROP_ELEMENT_MASTERY', '元素精通', '长杓座', '小N', '杰基·拉斯塔', '小泽亚李', '尹娥煐');
