INSERT INTO `genshin_character` VALUES (10000041, '莫娜', '星天水镜', '神秘的少女占星术士，声称自己是「伟大的占星术士莫娜」，拥有与名号相符的不俗实力，博学而高傲。', 'WEAPON_CATALYST', '法器', 'BODY_GIRL', '女', 'QUALITY_ORANGE', 5, '8/31', '8月31日', 'ELEMENT_HYDRO', '水', '蒙德城', 'ASSOC_MONDSTADT', '蒙德', 'FIGHT_PROP_CHARGE_EFFICIENCY', '元素充能效率', '映天座', '陈婷婷', '费丽茜娅·安吉尔', '小原好美', '禹贞信');
INSERT INTO `genshin_character` VALUES (10000042, '刻晴', '霆霓快雨', '璃月七星之一，玉衡星。对「帝君一言而决的璃月」颇有微词——但实际上，神挺欣赏她这样的人。', 'WEAPON_SWORD_ONE_HAND', '单手剑', 'BODY_GIRL', '女', 'QUALITY_ORANGE', 5, '11/20', '11月20日', 'ELEMENT_ELECTRO', '雷', '璃月七星', 'ASSOC_LIYUE', '璃月', 'FIGHT_PROP_CRITICAL_HURT', '暴击伤害', '金紫定垂座', '谢莹', '罗茜·戴', '喜多村英梨', '李甫熙');
INSERT INTO `genshin_character` VALUES (10000043, '砂糖', '无害甜度', '对万物充满好奇的炼金术士，「生物炼金」学派的研究者。', 'WEAPON_CATALYST', '法器', 'BODY_GIRL', '女', 'QUALITY_PURPLE', 4, '11/26', '11月26日', 'ELEMENT_ANEMO', '风', '西风骑士团', 'ASSOC_MONDSTADT', '蒙德', 'FIGHT_PROP_WIND_ADD_HURT', '风元素伤害加成', '烧瓶座', '小敢', '玛雅·格雷顿', '藤田茜', '金荷英');
