INSERT INTO `genshin_character` VALUES (10000110, '伊安珊', '熔石百炼', '沃陆之邦健身俱乐部的总教练，闻名纳塔的营养师。', 'WEAPON_POLE', '长柄武器', 'BODY_LOLI', '女', 'QUALITY_PURPLE', 4, '8/8', '8月8日', 'ELEMENT_ELECTRO', '雷', '特特奥坎', 'ASSOC_NATLAN', '纳塔', 'FIGHT_PROP_ATTACK_PERCENT', '攻击力', '牨龙座', '真理', '卡特里娜·索尔兹伯里', '大桥彩香', '李在岘');
INSERT INTO `genshin_character` VALUES (10000111, '瓦雷莎', '悠暇豪劲', '悠悠哉哉，无比松弛的「沃陆之邦」战士兼果园主，喜欢充满力量的英雄，还有巨量美食！', 'WEAPON_CATALYST', '法器', 'BODY_GIRL', '女', 'QUALITY_ORANGE', 5, '11/15', '11月15日', 'ELEMENT_ELECTRO', '雷', '特特奥坎', 'ASSOC_NATLAN', '纳塔', 'FIGHT_PROP_CRITICAL', '暴击率', '斗士假面座', '乔苏', '简·杰克逊', 'M・A・O', '金叡临');
INSERT INTO `genshin_character` VALUES (10000112, '爱可菲', '明绚千韵', '闻名枫丹的前德波大饭店主厨，有着「甜点大校」荣誉的「技术料理」先驱，对烹饪的要求无比严格。', 'WEAPON_POLE', '长柄武器', 'BODY_GIRL', '女', 'QUALITY_ORANGE', 5, '6/8', '6月8日', 'ELEMENT_CRYO', '冰', '枫丹', 'ASSOC_FONTAINE', '枫丹', 'FIGHT_PROP_CRITICAL', '暴击率', '香糕塔座', '蔡海婷', '埃米莉·卡斯', '佐藤聪美', '孙廷旼');
INSERT INTO `genshin_character` VALUES (10000113, '伊法', '蔚风引灵', '来自花羽会的兽医，由衷热爱着与人、动物，以及其他生灵为伴的生活。', 'WEAPON_CATALYST', '法器', 'BODY_MALE', '男', 'QUALITY_PURPLE', 4, '3/23', '3月23日', 'ELEMENT_ANEMO', '风', '特拉洛坎', 'ASSOC_NATLAN', '纳塔', 'FIGHT_PROP_ELEMENT_MASTERY', '元素精通', '佩链座', '吕书君', '乔尼·罗夸斯妥&多米尼克·卡特兰博内', '寺岛惇太&小松昌平', '朴基旭');
INSERT INTO `genshin_character` VALUES (10000114, '丝柯克', '虚渊暗星', '曾现身于深渊裂隙和原始胎海的来访者，教导达达利亚武技的老师。孤身一人的女武者。', 'WEAPON_SWORD_ONE_HAND', '单手剑', 'BODY_GIRL', '女', 'QUALITY_ORANGE', 5, '11/5', '11月5日', 'ELEMENT_CRYO', '冰', '寰宇劫灭', 'ASSOC_OMNI_SCOURGE', '', 'FIGHT_PROP_CRITICAL_HURT', '暴击伤害', '磷星座', '谢莹', '卡特·普罗塔诺', '能登麻美子', '徐多慧');
INSERT INTO `genshin_character` VALUES (10000115, '塔利雅', '颂礼祝祭', '西风教会的助祭，风神在教会的代行人。', 'WEAPON_SWORD_ONE_HAND', '单手剑', 'BODY_BOY', '男', 'QUALITY_PURPLE', 4, '5/25', '5月25日', 'ELEMENT_HYDRO', '水', '西风教会', 'ASSOC_MONDSTADT', '蒙德', 'FIGHT_PROP_HP_PERCENT', '生命值', '礼赞歌座', '风袖', '艾琳·米森', '山本和臣', '石承勋');
INSERT INTO `genshin_character` VALUES (10000116, '伊涅芙', '轰隆雷鸣波', '集成了各国机关部件的全能型机器人，胸口处的秘源核心已历经弥久岁月。', 'WEAPON_POLE', '长柄武器', 'BODY_GIRL', '女', 'QUALITY_ORANGE', 5, '4/2', '4月2日', 'ELEMENT_ELECTRO', '雷', '叮铃哐啷蛋卷工坊', 'ASSOC_NODKRAI', '挪德卡莱', 'FIGHT_PROP_CRITICAL', '暴击率', '香荚兰座', '美加', '安吉丽娜·丹妮尔·卡马', '中岛爱', '成玴沅');
INSERT INTO `genshin_character` VALUES (10000117, '奇偶·男性', '', '笔名「欧科塔维亚」的魔女托付给你和派蒙的人偶，善于探索「千星奇域」中封存的奥秘。', 'WEAPON_SWORD_ONE_HAND', '单手剑', 'BODY_BOY', '男', 'QUALITY_ORANGE_SP', 5, '0/0', '11月30日', 'ELEMENT_NONE', '无', '——', 'ASSOC_MAINACTOR', '', 'FIGHT_PROP_ATTACK_PERCENT', '攻击力', '——', '——', '——', '——', '——');
INSERT INTO `genshin_character` VALUES (10000118, '奇偶·女性', '', '笔名「欧科塔维亚」的魔女托付给你和派蒙的人偶，善于探索「千星奇域」中封存的奥秘。', 'WEAPON_SWORD_ONE_HAND', '单手剑', 'BODY_GIRL', '女', 'QUALITY_ORANGE_SP', 5, '0/0', '11月30日', 'ELEMENT_NONE', '无', '——', 'ASSOC_MAINACTOR', '', 'FIGHT_PROP_ATTACK_PERCENT', '攻击力', '——', '——', '——', '——', '——');
INSERT INTO `genshin_character` VALUES (10000119, '菈乌玛', '永月的祀歌', '被月光与森林祝福的圣女，一个诞生在「霜月之子」中的希望。', 'WEAPON_CATALYST', '法器', 'BODY_LADY', '女', 'QUALITY_ORANGE', 5, '3/1', '3月1日', 'ELEMENT_DENDRO', '草', '霜月之子', 'ASSOC_NODKRAI', '挪德卡莱', 'FIGHT_PROP_ELEMENT_MASTERY', '元素精通', '银鹿座', '张安琪', '亚历山德拉·格尔夫', '桑岛法子', '张䌽延');
INSERT INTO `genshin_character` VALUES (10000120, '菲林斯', '诡灯陌影', '挪德卡莱的「执灯人」，看守着北方小岛上的灯塔与墓地。一位言行举止极富修养的神秘绅士。', 'WEAPON_POLE', '长柄武器', 'BODY_MALE', '男', 'QUALITY_ORANGE', 5, '10/31', '10月31日', 'ELEMENT_ELECTRO', '雷', '执灯人', 'ASSOC_NODKRAI', '挪德卡莱', 'FIGHT_PROP_CRITICAL_HURT', '暴击伤害', '夜行灯座', '马正阳', '尼克·奥尔森', '中村悠一', '慎镛友');
INSERT INTO `genshin_character` VALUES (10000121, '爱诺', '妙械咣咣铛', '挪德卡莱的天才机械发明家，喜欢有趣的机械和甜食。', 'WEAPON_CLAYMORE', '双手剑', 'BODY_LOLI', '女', 'QUALITY_PURPLE', 4, '9/21', '9月21日', 'ELEMENT_HYDRO', '水', '叮铃哐啷蛋卷工坊', 'ASSOC_NODKRAI', '挪德卡莱', 'FIGHT_PROP_ELEMENT_MASTERY', '元素精通', '砰砰盒座', '葛子瑞', '安娜贝尔·布鲁克', '高森奈津美', '赵京洢');
INSERT INTO `genshin_character` VALUES (10000122, '奈芙尔', '湮沙的秘闻', '神通广大的「秘闻馆」之主。', 'WEAPON_CATALYST', '法器', 'BODY_LADY', '女', 'QUALITY_ORANGE', 5, '5/9', '5月9日', 'ELEMENT_DENDRO', '草', '秘闻馆', 'ASSOC_NODKRAI', '挪德卡莱', 'FIGHT_PROP_CRITICAL_HURT', '暴击伤害', '游棋座', '曾彤', '阿什莉·哈达德', '水树奈奈', '元以斯帖');
INSERT INTO `genshin_character` VALUES (10000123, '杜林', '「不熄灭的火」', '在魔女M笔下诞生的龙，最终来到了人类的世界。而他的「故事」，也仍在继续。', 'WEAPON_SWORD_ONE_HAND', '单手剑', 'BODY_BOY', '男', 'QUALITY_ORANGE', 5, '3/14', '3月14日', 'ELEMENT_PYRO', '火', '魔女会', 'ASSOC_MONDSTADT', '蒙德', 'FIGHT_PROP_CRITICAL_HURT', '暴击伤害', '赤龙座', '陶典', '劳利·基纳斯顿', '小林千晃', '金祉汩');
INSERT INTO `genshin_character` VALUES (10000124, '雅珂达', '系风攘影', '十分可靠，无所不能（自称）的「秘闻馆」员工。', 'WEAPON_BOW', '弓', 'BODY_GIRL', '女', 'QUALITY_PURPLE', 4, '1/5', '1月5日', 'ELEMENT_ANEMO', '风', '秘闻馆', 'ASSOC_NODKRAI', '挪德卡莱', 'FIGHT_PROP_HEAL_ADD', '治疗加成', '莓果座', '韩娇娇', '桑妮雅·克鲁格', '稻垣好', '吴捞妸');
INSERT INTO `genshin_character` VALUES (10000125, '哥伦比娅', '空月归乡', '于挪德卡莱诞生的「月之少女」，亦是归乡的空月。', 'WEAPON_CATALYST', '法器', 'BODY_GIRL', '女', 'QUALITY_ORANGE', 5, '1/14', '1月14日', 'ELEMENT_HYDRO', '水', '银月之庭', 'ASSOC_NODKRAI', '挪德卡莱', 'FIGHT_PROP_CRITICAL', '暴击率', '？？？', '杨梦露', '罗元湘', 'Lynn', '刘荣');
INSERT INTO `genshin_character` VALUES (10000126, '兹白', '驹隙隐泉', '璃月传说中的白马仙人，其名为兹白，璃月仙话中最神秘的一位。', 'WEAPON_SWORD_ONE_HAND', '单手剑', 'BODY_LADY', '女', 'QUALITY_ORANGE', 5, '5/15', '5月15日', 'ELEMENT_GEO', '岩', '璃月港', 'ASSOC_NODKRAI_ZIBAI', '', 'FIGHT_PROP_CRITICAL_HURT', '暴击伤害', '白驹座', 'Mace', '劳拉·韦尔什', '福圆美里', '千花');
INSERT INTO `genshin_character` VALUES (10000127, '叶洛亚', '魇夜燃芯', '调查分队「魇夜之莺」成员，执灯人最年轻的分队长。', 'WEAPON_POLE', '长柄武器', 'BODY_BOY', '男', 'QUALITY_PURPLE', 4, '12/23', '12月23日', 'ELEMENT_GEO', '岩', '执灯人', 'ASSOC_NODKRAI', '挪德卡莱', 'FIGHT_PROP_ELEMENT_MASTERY', '元素精通', '金莺座', '昱头', '乔纳森·河', '梅田修一朗', '黄栋炫');
INSERT INTO `genshin_character` VALUES (10000128, '法尔伽', '北风骑士', '西风骑士团大团长，守护蒙德的北风骑士。', 'WEAPON_CLAYMORE', '双手剑', 'BODY_MALE', '男', 'QUALITY_ORANGE', 5, '2/17', '2月17日', 'ELEMENT_ANEMO', '风', '西风骑士团', 'ASSOC_MONDSTADT', '蒙德', 'FIGHT_PROP_CRITICAL_HURT', '暴击伤害', '天狼座', '郝祥海', '约瑟夫·梅', '杉田智和', '朴相薰');
INSERT INTO `genshin_character` VALUES (10000130, '莉奈娅', '博闻异旅', '冒险家协会挪德卡莱分会顾问，博物学家。', 'WEAPON_BOW', '弓', 'BODY_GIRL', '女', 'QUALITY_ORANGE', 5, '5/23', '5月23日', 'ELEMENT_GEO', '岩', '冒险家协会', 'ASSOC_NODKRAI', '挪德卡莱', 'FIGHT_PROP_CRITICAL', '暴击率', '启喻鸟座', '周侗', '萨凡娜·门泽尔', '白石晴香', '朱艺瑨');
