INSERT INTO `genshin_constellation` VALUES (1, 12101, '爱诺', 1, '灰与力场的平衡理论', '爱诺施放元素战技<color=#FFD780FF>妙思捕手或元素爆发<color=#FFD780FF>精密水冷仪后，爱诺自身的元素精通提升80点，附近的当前场上其他角色的元素精通提升80点，持续15秒。\r\n\r\n该命之座提供的元素精通提升效果无法叠加。', '爱诺施放元素战技**妙思捕手**或元素爆发**精密水冷仪**后，爱诺自身的元素精通提升80点，附近的当前场上其他角色的元素精通提升80点，持续15秒。\r\n\r\n该命之座提供的元素精通提升效果无法叠加。');
INSERT INTO `genshin_constellation` VALUES (2, 12101, '爱诺', 2, '齿轮差分的进位原理', '元素爆发<color=#FFD780FF>精密水冷仪中的<color=#FFD780FF>对点水冷域持续期间，若爱诺处于队伍后台，队伍中自己的当前场上角色的攻击命中附近的敌人时，<color=#FFD780FF>「冷静一下鸭」将对该敌人发射一枚额外的水弹，基于爱诺攻击力的25%与元素精通的100%，造成<color=#80C0FFFF>水元素范围伤害。该效果每5秒至多触发一次，且造成的伤害视为元素爆发伤害。', '元素爆发**精密水冷仪**中的对点水冷域持续期间，若爱诺处于队伍后台，队伍中自己的当前场上角色的攻击命中附近的敌人时，「冷静一下鸭」将对该敌人发射一枚额外的水弹，基于爱诺攻击力的25%与元素精通的100%，造成水元素范围伤害。该效果每5秒至多触发一次，且造成的伤害视为元素爆发伤害。');
INSERT INTO `genshin_constellation` VALUES (3, 12101, '爱诺', 3, '蛋糕与机关维修艺术', '元素爆发<color=#FFD780FF>精密水冷仪的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**精密水冷仪**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (4, 12101, '爱诺', 4, '黄油与猫与供能法则', '元素战技<color=#FFD780FF>妙思捕手命中敌人时，将为爱诺恢复10点元素能量，每10秒至多通过这种方式恢复一次元素能量。', '元素战技**妙思捕手**命中敌人时，将为爱诺恢复10点元素能量，每10秒至多通过这种方式恢复一次元素能量。');
INSERT INTO `genshin_constellation` VALUES (5, 12101, '爱诺', 5, '金属与光的不朽涡轮', '元素战技<color=#FFD780FF>妙思捕手的技能等级提高3级。\r\n至多提升至15级。', '元素战技**妙思捕手**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (6, 12101, '爱诺', 6, '天才之为构造之责任', '施放元素爆发<color=#FFD780FF>精密水冷仪后的15秒内，附近的当前场上角色触发的感电、绽放、月感电、月绽放、月结晶造成的伤害提升15%。\r\n<color=#FFD780FF>月兆·满辉：上述反应造成的伤害额外提升20%。', '施放元素爆发**精密水冷仪**后的15秒内，附近的当前场上角色触发的感电、绽放、月感电、月绽放、月结晶造成的伤害提升15%。\r\n月兆·满辉：上述反应造成的伤害额外提升20%。');
INSERT INTO `genshin_constellation` VALUES (7, 3801, '阿贝多', 1, '伊甸之花', '阿贝多的<color=#FFD780FF>创生法·拟造阳华生成的刹那之花绽放时，为阿贝多自己回复1.2点元素能量。', '阿贝多的创生法·拟造阳华生成的刹那之花绽放时，为阿贝多自己回复1.2点元素能量。');
INSERT INTO `genshin_constellation` VALUES (8, 3801, '阿贝多', 2, '显生之宙', '<color=#FFD780FF>创生法·拟造阳华的刹那之花绽放时，会为阿贝多赋予生灭计数效果，持续30秒：\r\n·施放<color=#FFD780FF>诞生式·大地之潮时，清除所有生灭计数效果，并根据清除的层数，提高诞生式·大地之潮的爆发伤害与生灭之花造成的伤害；\r\n·每层生灭计数，会提高等同于阿贝多防御力的30%的伤害；\r\n·该效果至多叠加4次。', '创生法·拟造阳华的刹那之花绽放时，会为阿贝多赋予生灭计数效果，持续30秒：\r\n·施放诞生式·大地之潮时，清除所有生灭计数效果，并根据清除的层数，提高诞生式·大地之潮的爆发伤害与生灭之花造成的伤害；\r\n·每层生灭计数，会提高等同于阿贝多防御力的30%的伤害；\r\n·该效果至多叠加4次。');
INSERT INTO `genshin_constellation` VALUES (9, 3801, '阿贝多', 3, '太阳之华', '<color=#FFD780FF>创生法·拟造阳华的技能等级提高3级。\r\n至多提升至15级。', '创生法·拟造阳华的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (10, 3801, '阿贝多', 4, '神性之陨', '处于阳华的领域中的队伍中当前场上角色，造成的下落攻击伤害提高30%。', '处于阳华的领域中的队伍中当前场上角色，造成的下落攻击伤害提高30%。');
INSERT INTO `genshin_constellation` VALUES (11, 3801, '阿贝多', 5, '冥古之潮', '<color=#FFD780FF>诞生式·大地之潮的技能等级提高3级。\r\n至多提升至15级。', '诞生式·大地之潮的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (12, 3801, '阿贝多', 6, '无垢之土', '处在阳华的领域中的队伍中当前场上角色，若处于结晶反应产生的护盾庇护下，或阳华的领域中存在月笼时，造成的伤害提高17%。', '处在阳华的领域中的队伍中当前场上角色，若处于结晶反应产生的护盾庇护下，或阳华的领域中存在月笼时，造成的伤害提高17%。');
INSERT INTO `genshin_constellation` VALUES (13, 7801, '艾尔海森', 1, '直观', '光幕攻击命中敌人时，将使<color=#FFD780FF>共相·理式摹写的冷却时间减少1.2秒。该效果每1秒至多触发一次。', '光幕攻击命中敌人时，将使共相·理式摹写的冷却时间减少1.2秒。该效果每1秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (14, 7801, '艾尔海森', 2, '辩章', '艾尔海森产生琢光镜时，每1枚产生的琢光镜将使元素精通提升50点，持续8秒。该效果最多叠加4层，每层独立计算持续时间。琢光镜数量达到上限时依然能触发该效果。', '艾尔海森产生琢光镜时，每1枚产生的琢光镜将使元素精通提升50点，持续8秒。该效果最多叠加4层，每层独立计算持续时间。琢光镜数量达到上限时依然能触发该效果。');
INSERT INTO `genshin_constellation` VALUES (15, 7801, '艾尔海森', 3, '遮诠', '<color=#FFD780FF>共相·理式摹写的技能等级提高3级。\r\n至多提升至15级。', '共相·理式摹写的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (16, 7801, '艾尔海森', 4, '义贯', '施放<color=#FFD780FF>殊境·显象缚结时，会依据通过本次施放消耗与产生的琢光镜数量，产生如下效果：\r\n·每消耗1枚琢光镜，使队伍中附近的其他角色元素精通提升30点，持续15秒；\r\n·每产生1枚琢光镜，使艾尔海森获得10%<color=#99FF88FF>草元素伤害加成，持续15秒。\r\n\r\n上述效果的持续期间内重复施放殊境·显象缚结时，将先移除原有的效果。', '施放殊境·显象缚结时，会依据通过本次施放消耗与产生的琢光镜数量，产生如下效果：\r\n·每消耗1枚琢光镜，使队伍中附近的其他角色元素精通提升30点，持续15秒；\r\n·每产生1枚琢光镜，使艾尔海森获得10%草元素伤害加成，持续15秒。\r\n\r\n上述效果的持续期间内重复施放殊境·显象缚结时，将先移除原有的效果。');
INSERT INTO `genshin_constellation` VALUES (17, 7801, '艾尔海森', 5, '智度', '<color=#FFD780FF>殊境·显象缚结的技能等级提高3级。\r\n至多提升至15级。', '殊境·显象缚结的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (18, 7801, '艾尔海森', 6, '正理', '艾尔海森获得如下效果：\r\n·<color=#FFD780FF>殊境·显象缚结施放完成2秒后，将无视消耗琢光镜的个数，固定产生3枚琢光镜；\r\n·艾尔海森产生琢光镜时，若琢光镜数量已达到上限，艾尔海森的暴击率提升10%，暴击伤害提升70%，持续6秒。该效果在持续期间重复触发时，剩余持续时间将增加6秒。', '艾尔海森获得如下效果：\r\n·殊境·显象缚结施放完成2秒后，将无视消耗琢光镜的个数，固定产生3枚琢光镜；\r\n·艾尔海森产生琢光镜时，若琢光镜数量已达到上限，艾尔海森的暴击率提升10%，暴击伤害提升70%，持续6秒。该效果在持续期间重复触发时，剩余持续时间将增加6秒。');
INSERT INTO `genshin_constellation` VALUES (19, 6201, '埃洛伊', 1, '异界之星', '点亮此人一方星空之刻尚未到来。', '点亮此人一方星空之刻尚未到来。');
INSERT INTO `genshin_constellation` VALUES (20, 6201, '埃洛伊', 2, '异界之星', '点亮此人一方星空之刻尚未到来。', '点亮此人一方星空之刻尚未到来。');
INSERT INTO `genshin_constellation` VALUES (21, 6201, '埃洛伊', 3, '异界之星', '点亮此人一方星空之刻尚未到来。', '点亮此人一方星空之刻尚未到来。');
INSERT INTO `genshin_constellation` VALUES (22, 6201, '埃洛伊', 4, '异界之星', '点亮此人一方星空之刻尚未到来。', '点亮此人一方星空之刻尚未到来。');
INSERT INTO `genshin_constellation` VALUES (23, 6201, '埃洛伊', 5, '异界之星', '点亮此人一方星空之刻尚未到来。', '点亮此人一方星空之刻尚未到来。');
INSERT INTO `genshin_constellation` VALUES (24, 6201, '埃洛伊', 6, '异界之星', '点亮此人一方星空之刻尚未到来。', '点亮此人一方星空之刻尚未到来。');
INSERT INTO `genshin_constellation` VALUES (25, 2101, '安柏', 1, '一箭双丘丘！', '<color=#FFD780FF>瞄准射击时，会连续射出2支箭。第二支箭能造成原本20%的伤害。', '瞄准射击时，会连续射出2支箭。第二支箭能造成原本20%的伤害。');
INSERT INTO `genshin_constellation` VALUES (26, 2101, '安柏', 2, '一触即发', '兔兔伯爵进行了全新改良！蓄力完成的瞄准射击命中兔兔伯爵脚部时，能直接引爆兔兔伯爵…\r\n通过这种方式主动引爆兔兔伯爵时，会额外造成200%伤害。', '兔兔伯爵进行了全新改良！蓄力完成的瞄准射击命中兔兔伯爵脚部时，能直接引爆兔兔伯爵…\r\n通过这种方式主动引爆兔兔伯爵时，会额外造成200%伤害。');
INSERT INTO `genshin_constellation` VALUES (27, 2101, '安柏', 3, '烧起来啦！', '<color=#FFD780FF>箭雨的技能等级提高3级。\r\n至多提升至15级。', '箭雨的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (28, 2101, '安柏', 4, '才不是普通的布偶', '<color=#FFD780FF>爆弹玩偶的冷却时间减少20%，并增加1次可使用次数。', '爆弹玩偶的冷却时间减少20%，并增加1次可使用次数。');
INSERT INTO `genshin_constellation` VALUES (29, 2101, '安柏', 5, '是兔兔伯爵！', '<color=#FFD780FF>爆弹玩偶的技能等级提高3级。\r\n至多提升至15级。', '爆弹玩偶的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (30, 2101, '安柏', 6, '疾如野火', '使用<color=#FFD780FF>箭雨后的10秒内，队伍中所有角色的移动速度提升15%，攻击力提升15%。', '使用箭雨后的10秒内，队伍中所有角色的移动速度提升15%，攻击力提升15%。');
INSERT INTO `genshin_constellation` VALUES (31, 5701, '荒泷一斗', 1, '倘若不知，我讲你听', '施放<color=#FFD780FF>最恶鬼王·一斗轰临！！后，荒泷一斗获得2层「乱神之怪力」效果。1秒后，荒泷一斗每0.5秒再获得1层「乱神之怪力」效果，持续1.5秒。', '施放最恶鬼王·一斗轰临！！后，荒泷一斗获得2层「乱神之怪力」效果。1秒后，荒泷一斗每0.5秒再获得1层「乱神之怪力」效果，持续1.5秒。');
INSERT INTO `genshin_constellation` VALUES (32, 5701, '荒泷一斗', 2, '纠集众人，斗倒御岳', '施放<color=#FFD780FF>最恶鬼王·一斗轰临！！后，队伍中每个元素类型为<color=#FFE699FF>岩元素的角色，都将使其冷却时间减少1.5秒，使荒泷一斗的元素能量恢复6点。\r\n通过这种方式，至多减少4.5秒冷却时间，恢复18点元素能量。', '施放最恶鬼王·一斗轰临！！后，队伍中每个元素类型为岩元素的角色，都将使其冷却时间减少1.5秒，使荒泷一斗的元素能量恢复6点。\r\n通过这种方式，至多减少4.5秒冷却时间，恢复18点元素能量。');
INSERT INTO `genshin_constellation` VALUES (33, 5701, '荒泷一斗', 3, '水陆自在，牛王同行', '<color=#FFD780FF>魔杀绝技·赤牛发破！的技能等级提高3级。\r\n至多提升至15级。', '魔杀绝技·赤牛发破！的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (34, 5701, '荒泷一斗', 4, '奉行牢狱，茶饭之所', '<color=#FFD780FF>最恶鬼王·一斗轰临！！施加的「怒目鬼王」状态结束后，附近的队伍中所有角色的防御力提升20%，攻击力提升20%，持续10秒。', '最恶鬼王·一斗轰临！！施加的「怒目鬼王」状态结束后，附近的队伍中所有角色的防御力提升20%，攻击力提升20%，持续10秒。');
INSERT INTO `genshin_constellation` VALUES (35, 5701, '荒泷一斗', 5, '十年花坂，皆知我名', '<color=#FFD780FF>最恶鬼王·一斗轰临！！的技能等级提高3级。\r\n至多提升至15级。', '最恶鬼王·一斗轰临！！的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (36, 5701, '荒泷一斗', 6, '在下荒泷一斗是也', '荒泷一斗的重击的暴击伤害提高70%；此外，施展「荒泷逆袈裟」时，有50%的几率不消耗「乱神之怪力」。', '荒泷一斗的重击的暴击伤害提高70%；此外，施展「荒泷逆袈裟」时，有50%的几率不消耗「乱神之怪力」。');
INSERT INTO `genshin_constellation` VALUES (37, 9601, '阿蕾奇诺', 1, '「所有的仇与债皆由我偿…」', '红死之宴提升进一步提高，提高值为100%；此外，在红死之宴状态下进行普通攻击或重击时，提高阿蕾奇诺的抗打断能力。', '红死之宴提升进一步提高，提高值为100%；此外，在红死之宴状态下进行普通攻击或重击时，提高阿蕾奇诺的抗打断能力。');
INSERT INTO `genshin_constellation` VALUES (38, 9601, '阿蕾奇诺', 2, '「所有的赏与罚皆自我出…」', '<color=#FFD780FF>血偿勒令施加时即为血偿勒令·结。\r\n阿蕾奇诺回收血偿勒令·结时，将在前方唤出厄月血火，造成相当于她的攻击力900%的<color=#FF9999FF>火元素范围伤害，并使她的所有元素抗性与物理抗性提升20%，持续15秒。此效果每10秒至多触发一次。\r\n需要解锁突破天赋「唯苦痛可偿还」。', '血偿勒令施加时即为血偿勒令·结。\r\n阿蕾奇诺回收血偿勒令·结时，将在前方唤出厄月血火，造成相当于她的攻击力900%的火元素范围伤害，并使她的所有元素抗性与物理抗性提升20%，持续15秒。此效果每10秒至多触发一次。\r\n需要解锁突破天赋「唯苦痛可偿还」。');
INSERT INTO `genshin_constellation` VALUES (39, 9601, '阿蕾奇诺', 3, '「你将成为我们新的家人…」', '<color=#FFD780FF>普通攻击·斩首之邀的技能等级提高3级。\r\n至多提升至15级。', '普通攻击·斩首之邀的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (40, 9601, '阿蕾奇诺', 4, '「此后，你们须相爱相护…」', '阿蕾奇诺成功回收血偿勒令时，<color=#FFD780FF>厄月将升的冷却时间缩短2秒，并为她恢复15点元素能量，此效果每10秒至多触发一次。', '阿蕾奇诺成功回收血偿勒令时，厄月将升的冷却时间缩短2秒，并为她恢复15点元素能量，此效果每10秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (41, 9601, '阿蕾奇诺', 5, '「我们已孑然一身，与死无异…」', '<color=#FFD780FF>厄月将升的技能等级提高3级。\r\n至多提升至15级。', '厄月将升的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (42, 9601, '阿蕾奇诺', 6, '「自此以后，我们将共飨新生。」', '<color=#FFD780FF>厄月将升造成的伤害提高，提升值相当于阿蕾奇诺的攻击力乘以当前生命之契百分比的700%。\r\n施放<color=#FFD780FF>万相化灰后的20秒内，阿蕾奇诺的普通攻击与元素爆发的暴击率提升10%、暴击伤害提升70%。该效果每15秒至多触发一次。', '厄月将升造成的伤害提高，提升值相当于阿蕾奇诺的攻击力乘以当前生命之契百分比的700%。\r\n施放万相化灰后的20秒内，阿蕾奇诺的普通攻击与元素爆发的暴击率提升10%、暴击伤害提升70%。该效果每15秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (43, 8201, '白术', 1, '呿吟至微', '<color=#FFD780FF>太素诊要的可使用次数增加1次。', '太素诊要的可使用次数增加1次。');
INSERT INTO `genshin_constellation` VALUES (44, 8201, '白术', 2, '动静精明', '队伍中自己的当前场上角色在攻击命中附近的敌人时，白术将释放游丝徵灵·切。\r\n游丝徵灵·切将在进行至多1次攻击后返回，造成白术攻击力250%的<color=#99FF88FF>草元素伤害与<color=#FFD780FF>太素诊要游丝徵灵的20%回复量。\r\n通过这种方式造成的伤害视为元素战技伤害。\r\n每5秒至多触发一次。', '队伍中自己的当前场上角色在攻击命中附近的敌人时，白术将释放游丝徵灵·切。\r\n游丝徵灵·切将在进行至多1次攻击后返回，造成白术攻击力250%的草元素伤害与太素诊要游丝徵灵的20%回复量。\r\n通过这种方式造成的伤害视为元素战技伤害。\r\n每5秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (45, 8201, '白术', 3, '八正定气', '<color=#FFD780FF>愈气全形论的技能等级提高3级。\r\n至多提升至15级。', '愈气全形论的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (46, 8201, '白术', 4, '法古观冥', '施放<color=#FFD780FF>愈气全形论之后的15秒内，队伍中附近的所有角色元素精通提升80点。', '施放愈气全形论之后的15秒内，队伍中附近的所有角色元素精通提升80点。');
INSERT INTO `genshin_constellation` VALUES (47, 8201, '白术', 5, '盈虚藏象', '<color=#FFD780FF>太素诊要的技能等级提高3级。\r\n至多提升至15级。', '太素诊要的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (48, 8201, '白术', 6, '真邪合离', '<color=#FFD780FF>愈气全形论的灵气脉造成的伤害提高，提升值相当于白术生命值上限的8%。\r\n此外，<color=#FFD780FF>游丝徵灵或游丝徵灵·切在命中敌人时，有100%概率产生<color=#FFD780FF>愈气全形论的无郤气护盾，该效果每个游丝徵灵或游丝徵灵·切只能触发一次。', '愈气全形论的灵气脉造成的伤害提高，提升值相当于白术生命值上限的8%。\r\n此外，游丝徵灵或游丝徵灵·切在命中敌人时，有100%概率产生愈气全形论的无郤气护盾，该效果每个游丝徵灵或游丝徵灵·切只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (49, 1401, '芭芭拉', 1, '彩色歌谣', '芭芭拉每10秒恢复1点元素能量。', '芭芭拉每10秒恢复1点元素能量。');
INSERT INTO `genshin_constellation` VALUES (50, 1401, '芭芭拉', 2, '元气迸发', '<color=#FFD780FF>演唱，开始♪的冷却时间降低15%；\r\n技能持续期间，当前场上自己的角色获得15%<color=#80C0FFFF>水元素伤害加成。', '演唱，开始♪的冷却时间降低15%；\r\n技能持续期间，当前场上自己的角色获得15%水元素伤害加成。');
INSERT INTO `genshin_constellation` VALUES (51, 1401, '芭芭拉', 3, '明日之星', '<color=#FFD780FF>闪耀奇迹♪的技能等级提高3级。\r\n至多提升至15级。', '闪耀奇迹♪的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (52, 1401, '芭芭拉', 4, '努力即魔法', '芭芭拉使用重击时，每命中一个敌人，就恢复1点元素能量。\r\n通过这种方式，一次至多回复5点元素能量。', '芭芭拉使用重击时，每命中一个敌人，就恢复1点元素能量。\r\n通过这种方式，一次至多回复5点元素能量。');
INSERT INTO `genshin_constellation` VALUES (53, 1401, '芭芭拉', 5, '纯真的羁绊', '<color=#FFD780FF>演唱，开始♪的技能等级提高3级。\r\n至多提升至15级。', '演唱，开始♪的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (54, 1401, '芭芭拉', 6, '将一切美好献给你', '芭芭拉处于队伍后台时，队伍中自己的角色倒下时，则立即：\r\n·复苏该角色；\r\n·将该角色生命值恢复至100%。\r\n该效果每15分钟只能触发一次。', '芭芭拉处于队伍后台时，队伍中自己的角色倒下时，则立即：\r\n·复苏该角色；\r\n·将该角色生命值恢复至100%。\r\n该效果每15分钟只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (55, 2401, '北斗', 1, '鱼龙沉四方', '施放<color=#FFD780FF>斫雷时：\r\n生成一个伤害吸收量等于生命值上限16%的护盾，持续15秒。\r\n该护盾对<color=#FFACFFFF>雷元素伤害有250%的吸收效果。', '施放斫雷时：\r\n生成一个伤害吸收量等于生命值上限16%的护盾，持续15秒。\r\n该护盾对雷元素伤害有250%的吸收效果。');
INSERT INTO `genshin_constellation` VALUES (56, 2401, '北斗', 2, '赫赫雷涌起', '<color=#FFD780FF>斫雷的闪雷能额外弹跳2个敌人。', '斫雷的闪雷能额外弹跳2个敌人。');
INSERT INTO `genshin_constellation` VALUES (57, 2401, '北斗', 3, '潮奔蓦引电', '<color=#FFD780FF>捉浪的技能等级提高3级。\r\n至多提升至15级。', '捉浪的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (58, 2401, '北斗', 4, '牵星觅乡岸', '受到攻击后的10秒内，北斗的普通攻击附带20%额外<color=#FFACFFFF>雷元素伤害。', '受到攻击后的10秒内，北斗的普通攻击附带20%额外雷元素伤害。');
INSERT INTO `genshin_constellation` VALUES (59, 2401, '北斗', 5, '踏浪霞连阶', '<color=#FFD780FF>斫雷的技能等级提高3级。\r\n至多提升至15级。', '斫雷的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (60, 2401, '北斗', 6, '北斗祓幽孽', '<color=#FFD780FF>斫雷持续期间，周围敌人的<color=#FFACFFFF>雷元素抗性降低15%。', '斫雷持续期间，周围敌人的雷元素抗性降低15%。');
INSERT INTO `genshin_constellation` VALUES (61, 3201, '班尼特', 1, '冒险憧憬', '<color=#FFD780FF>美妙旅程的攻击力提升效果不再有生命值限制，数值上追加班尼特基础攻击力的20%。', '美妙旅程的攻击力提升效果不再有生命值限制，数值上追加班尼特基础攻击力的20%。');
INSERT INTO `genshin_constellation` VALUES (62, 3201, '班尼特', 2, '踏破绝境', '班尼特的生命值低于70%时，元素充能效率提高30%。', '班尼特的生命值低于70%时，元素充能效率提高30%。');
INSERT INTO `genshin_constellation` VALUES (63, 3201, '班尼特', 3, '火热激情', '<color=#FFD780FF>热情过载的技能等级提高3级。\r\n至多提升至15级。', '热情过载的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (64, 3201, '班尼特', 4, '热情不灭', '施放一段蓄力的<color=#FFD780FF>热情过载时，在技能第二段攻击中进行普通攻击，可以施放额外的追击。\r\n追击的伤害等同于第二段攻击的135%。', '施放一段蓄力的热情过载时，在技能第二段攻击中进行普通攻击，可以施放额外的追击。\r\n追击的伤害等同于第二段攻击的135%。');
INSERT INTO `genshin_constellation` VALUES (65, 3201, '班尼特', 5, '开拓的心魂', '<color=#FFD780FF>美妙旅程的技能等级提高3级。\r\n至多提升至15级。', '美妙旅程的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (66, 3201, '班尼特', 6, '烈火与勇气', '处在<color=#FFD780FF>美妙旅程领域内的队伍中当前场上单手剑、双手剑、长柄武器角色获得15%<color=#FF9999FF>火元素伤害加成，并获得<color=#FF9999FF>火元素附魔。', '处在美妙旅程领域内的队伍中当前场上单手剑、双手剑、长柄武器角色获得15%火元素伤害加成，并获得火元素附魔。');
INSERT INTO `genshin_constellation` VALUES (67, 7201, '坎蒂丝', 1, '赤沙的归嗣', '<color=#FFD780FF>圣仪·灰鸰衒潮的赤冕祝祷状态持续时间延长3秒。', '圣仪·灰鸰衒潮的赤冕祝祷状态持续时间延长3秒。');
INSERT INTO `genshin_constellation` VALUES (68, 7201, '坎蒂丝', 2, '贯月的耀锋', '<color=#FFD780FF>圣仪·苍鹭庇卫命中敌人时，坎蒂丝的生命值上限提升20%，持续15秒。', '圣仪·苍鹭庇卫命中敌人时，坎蒂丝的生命值上限提升20%，持续15秒。');
INSERT INTO `genshin_constellation` VALUES (69, 7201, '坎蒂丝', 3, '织狩的奉祀', '<color=#FFD780FF>圣仪·灰鸰衒潮的技能等级提高3级。\r\n至多提升至15级。', '圣仪·灰鸰衒潮的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (70, 7201, '坎蒂丝', 4, '守戍的誓命', '缩短<color=#FFD780FF>圣仪·苍鹭庇卫长按的冷却时间，使其降低至与点按的冷却时间相同。', '缩短圣仪·苍鹭庇卫长按的冷却时间，使其降低至与点按的冷却时间相同。');
INSERT INTO `genshin_constellation` VALUES (71, 7201, '坎蒂丝', 5, '萦金的苍瞳', '<color=#FFD780FF>圣仪·苍鹭庇卫的技能等级提高3级。\r\n至多提升至15级。', '圣仪·苍鹭庇卫的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (72, 7201, '坎蒂丝', 6, '衍溢的汐潮', '处于<color=#FFD780FF>圣仪·灰鸰衒潮的赤冕祝祷状态下的当前场上角色（不包括坎蒂丝自己），在普通攻击对敌人造成元素伤害时，将释放衍潮冲击，造成相当于坎蒂丝生命值上限15%<color=#80C0FFFF>水元素范围伤害。\r\n该效果每2.3秒至多触发一次，造成的伤害视为元素爆发伤害。', '处于圣仪·灰鸰衒潮的赤冕祝祷状态下的当前场上角色（不包括坎蒂丝自己），在普通攻击对敌人造成元素伤害时，将释放衍潮冲击，造成相当于坎蒂丝生命值上限15%水元素范围伤害。\r\n该效果每2.3秒至多触发一次，造成的伤害视为元素爆发伤害。');
INSERT INTO `genshin_constellation` VALUES (73, 8801, '夏洛蒂', 1, '以核实为约束', '<color=#FFD780FF>定格·全方位确证对角色进行治疗后，将为角色施加「核实」印记，每2秒为角色恢复生命值，回复量相当于夏洛蒂攻击力的80%，该效果持续6秒。', '定格·全方位确证对角色进行治疗后，将为角色施加「核实」印记，每2秒为角色恢复生命值，回复量相当于夏洛蒂攻击力的80%，该效果持续6秒。');
INSERT INTO `genshin_constellation` VALUES (74, 8801, '夏洛蒂', 2, '以求真为职守', '施放<color=#FFD780FF>取景·冰点构图法时，「温亨廷先生」的攻击命中了1/2/3及以上名敌人时，夏洛蒂自身的攻击力提升10%/20%/30%，持续12秒。', '施放取景·冰点构图法时，「温亨廷先生」的攻击命中了1/2/3及以上名敌人时，夏洛蒂自身的攻击力提升10%/20%/30%，持续12秒。');
INSERT INTO `genshin_constellation` VALUES (75, 8801, '夏洛蒂', 3, '以独立为先决', '<color=#FFD780FF>定格·全方位确证的技能等级提高3级。\r\n至多提升至15级。', '定格·全方位确证的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (76, 8801, '夏洛蒂', 4, '以督促为责任', '<color=#FFD780FF>定格·全方位确证命中附有「瞬时剪影」或「聚焦印象」印记的敌人时，造成的伤害提升10%，并且为夏洛蒂自身恢复2点能量。每20秒，至多通过这种方式恢复5次元素能量。', '定格·全方位确证命中附有「瞬时剪影」或「聚焦印象」印记的敌人时，造成的伤害提升10%，并且为夏洛蒂自身恢复2点能量。每20秒，至多通过这种方式恢复5次元素能量。');
INSERT INTO `genshin_constellation` VALUES (77, 8801, '夏洛蒂', 5, '以良知为原则', '<color=#FFD780FF>取景·冰点构图法的技能等级提高3级。\r\n至多提升至15级。', '取景·冰点构图法的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (78, 8801, '夏洛蒂', 6, '以有趣相关为要义', '当前场上角色的普通攻击与重击命中附有<color=#FFD780FF>取景·冰点构图法的「聚焦印象」的敌人后，「温亨廷先生」将进行协同攻击，造成相当于夏洛蒂攻击力180%的<color=#99FFFFFF>冰元素范围伤害，并为攻击范围内的当前场上角色恢复生命值，回复量相当于夏洛蒂攻击力的42%。该效果每6秒至多触发一次，通过这种方式造成的伤害与治疗效果视为夏洛蒂的元素爆发造成的伤害与治疗效果。', '当前场上角色的普通攻击与重击命中附有取景·冰点构图法的「聚焦印象」的敌人后，「温亨廷先生」将进行协同攻击，造成相当于夏洛蒂攻击力180%的冰元素范围伤害，并为攻击范围内的当前场上角色恢复生命值，回复量相当于夏洛蒂攻击力的42%。该效果每6秒至多触发一次，通过这种方式造成的伤害与治疗效果视为夏洛蒂的元素爆发造成的伤害与治疗效果。');
INSERT INTO `genshin_constellation` VALUES (79, 10401, '恰斯卡', 1, '弹匣，躁动的轮盘', '触发突破天赋「子弹的戏法」中的「附灵转化」时，会额外使第二枚装入弹匣的<color=#FFD780FF>追影弹转化为<color=#FFD780FF>焕光追影弹。\r\n触发「附灵转化」的几率增加：若队伍中存在符合元素转化条件的元素类型的角色，则触发「附灵转化」的几率提升33.3%，至多提升至100%。\r\n\r\n需要解锁突破天赋「子弹的戏法」。\r\n此外，不处于战斗状态下时，恰斯卡的夜魂加持状态消耗的夜魂值与燃素降低30%。', '触发突破天赋「子弹的戏法」中的「附灵转化」时，会额外使第二枚装入弹匣的追影弹转化为焕光追影弹。\r\n触发「附灵转化」的几率增加：若队伍中存在符合元素转化条件的元素类型的角色，则触发「附灵转化」的几率提升33.3%，至多提升至100%。\r\n\r\n需要解锁突破天赋「子弹的戏法」。\r\n此外，不处于战斗状态下时，恰斯卡的夜魂加持状态消耗的夜魂值与燃素降低30%。');
INSERT INTO `genshin_constellation` VALUES (80, 10401, '恰斯卡', 2, '枪口，灼烧的轻烟', '恰斯卡登场时，获得一层突破天赋「子弹的戏法」的「焕影之灵」。该效果需要解锁突破天赋「子弹的戏法」。\r\n此外，施放元素战技<color=#FFD780FF>灵缰追影中的<color=#FFD780FF>多重瞄准时，恰斯卡的<color=#FFD780FF>焕光追影弹命中敌人时，会根据<color=#FFD780FF>焕光追影弹的元素类型，造成相当于恰斯卡攻击力400%的对应元素范围伤害，该伤害视为重击伤害。每次施放<color=#FFD780FF>多重瞄准至多触发一次该效果。', '恰斯卡登场时，获得一层突破天赋「子弹的戏法」的「焕影之灵」。该效果需要解锁突破天赋「子弹的戏法」。\r\n此外，施放元素战技灵缰追影中的多重瞄准时，恰斯卡的焕光追影弹命中敌人时，会根据焕光追影弹的元素类型，造成相当于恰斯卡攻击力400%的对应元素范围伤害，该伤害视为重击伤害。每次施放多重瞄准至多触发一次该效果。');
INSERT INTO `genshin_constellation` VALUES (81, 10401, '恰斯卡', 3, '笼绳，缜密的掌控', '元素战技<color=#FFD780FF>灵缰追影的技能等级提高3级。\r\n至多提升至15级。', '元素战技灵缰追影的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (82, 10401, '恰斯卡', 4, '星火，瞬息的击发', '元素爆发<color=#FFD780FF>索魂命袭中的<color=#FFD780FF>溢光索魂弹命中敌人时，将为恰斯卡恢复1.5点元素能量，并会根据<color=#FFD780FF>溢光索魂弹的元素类型，造成相当于恰斯卡攻击力400%的对应元素范围伤害，该伤害视为重击伤害。\r\n上述造成对应元素范围伤害的效果，每次施放<color=#FFD780FF>索魂命袭至多触发1次该效果。', '元素爆发索魂命袭中的溢光索魂弹命中敌人时，将为恰斯卡恢复1.5点元素能量，并会根据溢光索魂弹的元素类型，造成相当于恰斯卡攻击力400%的对应元素范围伤害，该伤害视为重击伤害。\r\n上述造成对应元素范围伤害的效果，每次施放索魂命袭至多触发1次该效果。');
INSERT INTO `genshin_constellation` VALUES (83, 10401, '恰斯卡', 5, '帽檐，沙影的轮廓', '元素爆发<color=#FFD780FF>索魂命袭的技能等级提高3级。\r\n至多提升至15级。', '元素爆发索魂命袭的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (84, 10401, '恰斯卡', 6, '相决，斗争的荣光', '恰斯卡进行<color=#FFD780FF>多重瞄准所需的蓄力时间减少，且触发突破天赋「子弹的戏法」中的「附灵转化」后，恰斯卡将获得「命袭」状态，在接下来的3秒内，恰斯卡下一次施放元素战技<color=#FFD780FF>灵缰追影中的<color=#FFD780FF>多重瞄准时，会立即完成蓄力，并且本次<color=#FFD780FF>多重瞄准中的<color=#FFD780FF>追影弹和<color=#FFD780FF>焕光追影弹的暴击伤害提升120%。每3秒至多获得一次「命袭」效果。\r\n\r\n上述效果需要解锁突破天赋「子弹的戏法」。', '恰斯卡进行多重瞄准所需的蓄力时间减少，且触发突破天赋「子弹的戏法」中的「附灵转化」后，恰斯卡将获得「命袭」状态，在接下来的3秒内，恰斯卡下一次施放元素战技灵缰追影中的多重瞄准时，会立即完成蓄力，并且本次多重瞄准中的追影弹和焕光追影弹的暴击伤害提升120%。每3秒至多获得一次「命袭」效果。\r\n\r\n上述效果需要解锁突破天赋「子弹的戏法」。');
INSERT INTO `genshin_constellation` VALUES (85, 9001, '夏沃蕾', 1, '稳固阵线的魄力', '当前场上处于「协同战法」状态下的角色（不包括夏沃蕾自己）触发超载反应时，将恢复6点元素能量。此效果每10秒至多触发一次。\r\n需要解锁突破天赋「尖兵协同战法」。', '当前场上处于「协同战法」状态下的角色（不包括夏沃蕾自己）触发超载反应时，将恢复6点元素能量。此效果每10秒至多触发一次。\r\n需要解锁突破天赋「尖兵协同战法」。');
INSERT INTO `genshin_constellation` VALUES (86, 9001, '夏沃蕾', 2, '诱导殉爆的狙击', '长按施放<color=#FFD780FF>近迫式急促拦射的射击命中时，将在命中位置附近引发2次连锁殉爆，每次殉爆造成相当于夏沃蕾120%攻击力的<color=#FF9999FF>火元素伤害。此效果每10秒至多触发1次，通过这种方式造成的伤害视为元素战技伤害。', '长按施放近迫式急促拦射的射击命中时，将在命中位置附近引发2次连锁殉爆，每次殉爆造成相当于夏沃蕾120%攻击力的火元素伤害。此效果每10秒至多触发1次，通过这种方式造成的伤害视为元素战技伤害。');
INSERT INTO `genshin_constellation` VALUES (87, 9001, '夏沃蕾', 3, '娴熟复装的技巧', '<color=#FFD780FF>近迫式急促拦射的技能等级提高3级。\r\n至多提升至15级。', '近迫式急促拦射的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (88, 9001, '夏沃蕾', 4, '多重速射的秘诀', '施放<color=#FFD780FF>圆阵掷弹爆轰术后，夏沃蕾长按施放<color=#FFD780FF>近迫式急促拦射不会进入冷却，该效果至多持续6秒，将在长按施放近迫式急促拦射2次后移除。', '施放圆阵掷弹爆轰术后，夏沃蕾长按施放近迫式急促拦射不会进入冷却，该效果至多持续6秒，将在长按施放近迫式急促拦射2次后移除。');
INSERT INTO `genshin_constellation` VALUES (89, 9001, '夏沃蕾', 5, '增量火力的毁伤', '<color=#FFD780FF>圆阵掷弹爆轰术的技能等级提高3级。\r\n至多提升至15级。', '圆阵掷弹爆轰术的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (90, 9001, '夏沃蕾', 6, '终结罪恶的追缉', '<color=#FFD780FF>近迫式急促拦射的治疗效果持续12秒后，将为队伍中附近的所有角色恢复一次生命值，回复量相当于夏沃蕾生命值上限的10%。\r\n队伍中的角色受到「近迫式急促拦射」的治疗后，获得20%<color=#FF9999FF>火元素伤害加成与<color=#FFACFFFF>雷元素伤害加成，持续8秒，此效果至多叠加3层，每层独立计算持续时间。', '近迫式急促拦射的治疗效果持续12秒后，将为队伍中附近的所有角色恢复一次生命值，回复量相当于夏沃蕾生命值上限的10%。\r\n队伍中的角色受到「近迫式急促拦射」的治疗后，获得20%火元素伤害加成与雷元素伤害加成，持续8秒，此效果至多叠加3层，每层独立计算持续时间。');
INSERT INTO `genshin_constellation` VALUES (91, 9401, '千织', 1, '正绢六通', '<color=#FFD780FF>羽袖一触的自动制御人形「袖」的攻击范围提升50%。\r\n此外，如果队伍中存在千织以外的<color=#FFE699FF>岩元素角色，羽袖一触的突进结束时，还将触发以下效果：\r\n·额外唤出一名袖。通过这种方式唤出的千织自己的袖，与通过岩元素创造物额外唤出的千织自己的袖至多同时存在一名；\r\n·触发、突破天赋「锦上添花」，此效果需要解锁突破天赋「锦上添花」。', '羽袖一触的自动制御人形「袖」的攻击范围提升50%。\r\n此外，如果队伍中存在千织以外的岩元素角色，羽袖一触的突进结束时，还将触发以下效果：\r\n·额外唤出一名袖。通过这种方式唤出的千织自己的袖，与通过岩元素创造物额外唤出的千织自己的袖至多同时存在一名；\r\n·触发、突破天赋「锦上添花」，此效果需要解锁突破天赋「锦上添花」。');
INSERT INTO `genshin_constellation` VALUES (92, 9401, '千织', 2, '落染五色', '施放<color=#FFD780FF>二刀之形·比翼后的10秒内，每3秒都将在当前场上自己的角色身边唤出一名简易自动制御人形「绢」。绢将对附近的敌人发起攻击，造成相当于袖170%的<color=#FFE699FF>岩元素范围伤害，通过这种方式造成的伤害视为元素战技伤害。\r\n绢将在进行一次攻击或存在3秒后退场。', '施放二刀之形·比翼后的10秒内，每3秒都将在当前场上自己的角色身边唤出一名简易自动制御人形「绢」。绢将对附近的敌人发起攻击，造成相当于袖170%的岩元素范围伤害，通过这种方式造成的伤害视为元素战技伤害。\r\n绢将在进行一次攻击或存在3秒后退场。');
INSERT INTO `genshin_constellation` VALUES (93, 9401, '千织', 3, '缀锦四分', '<color=#FFD780FF>羽袖一触的技能等级提高3级。\r\n至多提升至15级。', '羽袖一触的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (94, 9401, '千织', 4, '衣裁三礼', '触发突破天赋「量体裁衣」的后续效果后的8秒内，队伍中自己的当前场上角色的普通攻击、重击或下落攻击命中附近的敌人时，将在敌人附近唤出一名简易自动制御人形「绢」。每1秒至多通过上述方式唤出一名绢，一次突破天赋「量体裁衣」的当意即妙或裁锦持续期间，至多通过上述方式唤出3名绢。上述效果每15秒最多触发一次。 \r\n需要解锁突破天赋「量体裁衣」。', '触发突破天赋「量体裁衣」的后续效果后的8秒内，队伍中自己的当前场上角色的普通攻击、重击或下落攻击命中附近的敌人时，将在敌人附近唤出一名简易自动制御人形「绢」。每1秒至多通过上述方式唤出一名绢，一次突破天赋「量体裁衣」的当意即妙或裁锦持续期间，至多通过上述方式唤出3名绢。上述效果每15秒最多触发一次。 \r\n需要解锁突破天赋「量体裁衣」。');
INSERT INTO `genshin_constellation` VALUES (95, 9401, '千织', 5, '绫羽二重', '<color=#FFD780FF>二刀之形·比翼的技能等级提高3级。\r\n至多提升至15级。', '二刀之形·比翼的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (96, 9401, '千织', 6, '万理一空', '触发突破天赋「量体裁衣」的后续效果后，千织自己的<color=#FFD780FF>羽袖一触的冷却时间减少12秒。需要解锁突破天赋「量体裁衣」。\r\n此外，千织自己的普通攻击造成的伤害提升，提升值相当于千织自己的防御力的235%。', '触发突破天赋「量体裁衣」的后续效果后，千织自己的羽袖一触的冷却时间减少12秒。需要解锁突破天赋「量体裁衣」。\r\n此外，千织自己的普通攻击造成的伤害提升，提升值相当于千织自己的防御力的235%。');
INSERT INTO `genshin_constellation` VALUES (97, 3601, '重云', 1, '释凌咏冰', '普通攻击的最后一击会向前方释放三道冰之刃，每道冰之刃对沿途的敌人造成重云50%攻击力的<color=#99FFFFFF>冰元素伤害。', '普通攻击的最后一击会向前方释放三道冰之刃，每道冰之刃对沿途的敌人造成重云50%攻击力的冰元素伤害。');
INSERT INTO `genshin_constellation` VALUES (98, 3601, '重云', 2, '周天运转', '在<color=#FFD780FF>灵刃·重华叠霜领域内施放的元素战技与元素爆发的冷却时间减少15%。', '在灵刃·重华叠霜领域内施放的元素战技与元素爆发的冷却时间减少15%。');
INSERT INTO `genshin_constellation` VALUES (99, 3601, '重云', 3, '云尽光生', '<color=#FFD780FF>灵刃·云开星落的技能等级提高3级。\r\n至多提升至15级。', '灵刃·云开星落的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (100, 3601, '重云', 4, '浮云霜天', '重云的所有攻击命中受到<color=#99FFFFFF>冰元素影响的敌人时，自身将恢复1点元素能量。\r\n该效果每2秒最多触发一次。', '重云的所有攻击命中受到冰元素影响的敌人时，自身将恢复1点元素能量。\r\n该效果每2秒最多触发一次。');
INSERT INTO `genshin_constellation` VALUES (101, 3601, '重云', 5, '真道正理', '<color=#FFD780FF>灵刃·重华叠霜的技能等级提高3级。\r\n至多提升至15级。', '灵刃·重华叠霜的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (102, 3601, '重云', 6, '四灵捧圣', '<color=#FFD780FF>灵刃·云开星落对生命值百分比低于重云的敌人造成伤害时，伤害提升15%；\r\n此外，施放时，会召唤一柄额外的灵刃。', '灵刃·云开星落对生命值百分比低于重云的敌人造成伤害时，伤害提升15%；\r\n此外，施放时，会召唤一柄额外的灵刃。');
INSERT INTO `genshin_constellation` VALUES (103, 10701, '茜特菈莉', 1, '四百星的芒刃', '施放元素战技<color=#FFD780FF>霜昼黑星时，茜特菈莉将获得「白星之裙」效果，持续至伊兹帕帕退场：持续期间，茜特菈莉获得10层「星刃」，除茜特菈莉外的附近的当前场上角色的普通攻击、重击、下落攻击、元素战技或元素爆发造成伤害时，将消耗1层「星刃」，提升造成的伤害，提升值相当于茜特菈莉元素精通的200%。\r\n队伍中附近的角色触发冻结反应或融化反应后，茜特菈莉将额外获得3层「星刃」，该效果每8秒至多触发一次。\r\n\r\n施放元素战技<color=#FFD780FF>霜昼黑星时，「星刃」的层数将会刷新。\r\n此外，茜特菈莉进行腾跃、或是在空中进行瞄准或重击时，消耗的燃素降低45%。', '施放元素战技霜昼黑星时，茜特菈莉将获得「白星之裙」效果，持续至伊兹帕帕退场：持续期间，茜特菈莉获得10层「星刃」，除茜特菈莉外的附近的当前场上角色的普通攻击、重击、下落攻击、元素战技或元素爆发造成伤害时，将消耗1层「星刃」，提升造成的伤害，提升值相当于茜特菈莉元素精通的200%。\r\n队伍中附近的角色触发冻结反应或融化反应后，茜特菈莉将额外获得3层「星刃」，该效果每8秒至多触发一次。\r\n\r\n施放元素战技霜昼黑星时，「星刃」的层数将会刷新。\r\n此外，茜特菈莉进行腾跃、或是在空中进行瞄准或重击时，消耗的燃素降低45%。');
INSERT INTO `genshin_constellation` VALUES (104, 10701, '茜特菈莉', 2, '吞心者的巡行', '茜特菈莉的元素精通提升125点，处于白曜护盾的庇护下或是伊兹帕帕跟随的其他角色的元素精通提升250点。\r\n此外，施放元素战技<color=#FFD780FF>霜昼黑星时，也会为附近的当前场上角色赋予白曜护盾；\r\n\r\n此外，突破天赋「五重天的寒雨」的效果获得提升：\r\n伊兹帕帕存在期间，队伍中附近的角色触发冻结反应或融化反应后，受本次反应影响的敌人的<color=#FF9999FF>火元素与<color=#80C0FFFF>水元素抗性还会额外降低20%，持续12秒，该效果需要解锁突破天赋「五重天的寒雨」。', '茜特菈莉的元素精通提升125点，处于白曜护盾的庇护下或是伊兹帕帕跟随的其他角色的元素精通提升250点。\r\n此外，施放元素战技霜昼黑星时，也会为附近的当前场上角色赋予白曜护盾；\r\n\r\n此外，突破天赋「五重天的寒雨」的效果获得提升：\r\n伊兹帕帕存在期间，队伍中附近的角色触发冻结反应或融化反应后，受本次反应影响的敌人的火元素与水元素抗性还会额外降低20%，持续12秒，该效果需要解锁突破天赋「五重天的寒雨」。');
INSERT INTO `genshin_constellation` VALUES (105, 10701, '茜特菈莉', 3, '云中蛇的羽冠', '元素战技<color=#FFD780FF>霜昼黑星的技能等级提高3级。\r\n至多提升至15级。', '元素战技霜昼黑星的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (106, 10701, '茜特菈莉', 4, '拒亡者的灵髑', '元素战技<color=#FFD780FF>霜昼黑星中，伊兹帕帕的霜陨风暴命中敌人时，会额外召唤一个<color=#FFD780FF>宿灵之髑·黑星，通过这种方式召唤的宿灵之髑发生爆炸时，会造成相当于茜特菈莉元素精通1800%的具有夜魂性质的<color=#99FFFFFF>冰元素范围伤害，并为茜特菈莉恢复16点夜魂值和8点元素能量，该效果每8秒至多触发一次。该伤害不被视为元素爆发伤害。', '元素战技霜昼黑星中，伊兹帕帕的霜陨风暴命中敌人时，会额外召唤一个宿灵之髑·黑星，通过这种方式召唤的宿灵之髑发生爆炸时，会造成相当于茜特菈莉元素精通1800%的具有夜魂性质的冰元素范围伤害，并为茜特菈莉恢复16点夜魂值和8点元素能量，该效果每8秒至多触发一次。该伤害不被视为元素爆发伤害。');
INSERT INTO `genshin_constellation` VALUES (107, 10701, '茜特菈莉', 5, '五恶曜的咒缚', '元素爆发<color=#FFD780FF>诸曜饬令的技能等级提高3级。\r\n至多提升至15级。', '元素爆发诸曜饬令的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (108, 10701, '茜特菈莉', 6, '原动天的密契', '元素战技<color=#FFD780FF>霜昼黑星中召唤的伊兹帕帕将始终为白燧状态，夜魂值耗尽时，伊兹帕帕的白燧状态也不会结束。\r\n此外，施放元素战技<color=#FFD780FF>霜昼黑星时，伊兹帕帕将消耗所有夜魂值，并在存在期间内持续消耗夜魂值；每通过上述方式消耗1点夜魂值，茜特菈莉就会获得1点「秘律之数」。\r\n「秘律之数」上限为40点，基于茜特菈莉持有的「秘律之数」，每1点「秘律之数」会使附近的队伍中所有角色获得1.5%<color=#FF9999FF>火元素与<color=#80C0FFFF>水元素伤害加成，并使茜特菈莉造成的伤害提升2.5%。\r\n伊兹帕帕退场时，或再次施放元素战技时，茜特菈莉持有的「秘律之数」将被移除。', '元素战技霜昼黑星中召唤的伊兹帕帕将始终为白燧状态，夜魂值耗尽时，伊兹帕帕的白燧状态也不会结束。\r\n此外，施放元素战技霜昼黑星时，伊兹帕帕将消耗所有夜魂值，并在存在期间内持续消耗夜魂值；每通过上述方式消耗1点夜魂值，茜特菈莉就会获得1点「秘律之数」。\r\n「秘律之数」上限为40点，基于茜特菈莉持有的「秘律之数」，每1点「秘律之数」会使附近的队伍中所有角色获得1.5%火元素与水元素伤害加成，并使茜特菈莉造成的伤害提升2.5%。\r\n伊兹帕帕退场时，或再次施放元素战技时，茜特菈莉持有的「秘律之数」将被移除。');
INSERT INTO `genshin_constellation` VALUES (109, 9801, '克洛琳德', 1, '「自此，行过烛影之帷」', '<color=#FFD780FF>狩夜之巡的夜巡状态持续期间，克洛琳德的普通攻击造成的<color=#FFACFFFF>雷元素伤害命中敌人时，将在敌人附近唤出夜巡之影进行两次协同攻击，各自造成克洛琳德30%攻击力的<color=#FFACFFFF>雷元素伤害。\r\n此效果每1.2秒至多触发一次，通过这种方式造成的伤害视为普通攻击伤害。', '狩夜之巡的夜巡状态持续期间，克洛琳德的普通攻击造成的雷元素伤害命中敌人时，将在敌人附近唤出夜巡之影进行两次协同攻击，各自造成克洛琳德30%攻击力的雷元素伤害。\r\n此效果每1.2秒至多触发一次，通过这种方式造成的伤害视为普通攻击伤害。');
INSERT INTO `genshin_constellation` VALUES (110, 9801, '克洛琳德', 2, '「自此，直面长夜之危」', '突破天赋「破夜的明焰」的效果获得强化：队伍中附近的角色对敌人触发<color=#FFACFFFF>雷元素相关反应后，将基于克洛琳德攻击力的30%，提升克洛琳德的普通攻击与<color=#FFD780FF>残光将终造成的<color=#FFACFFFF>雷元素伤害。此效果持续15秒，至多叠加3层，每层独立计时。处于3层状态下时，克洛琳德的抗打断能力提升。通过这种方式至多使克洛琳德的上述攻击造成的伤害提升2700。\r\n需要解锁突破天赋「破夜的明焰」。', '突破天赋「破夜的明焰」的效果获得强化：队伍中附近的角色对敌人触发雷元素相关反应后，将基于克洛琳德攻击力的30%，提升克洛琳德的普通攻击与残光将终造成的雷元素伤害。此效果持续15秒，至多叠加3层，每层独立计时。处于3层状态下时，克洛琳德的抗打断能力提升。通过这种方式至多使克洛琳德的上述攻击造成的伤害提升2700。\r\n需要解锁突破天赋「破夜的明焰」。');
INSERT INTO `genshin_constellation` VALUES (111, 9801, '克洛琳德', 3, '「我将铭记白昼的誓言」', '<color=#FFD780FF>狩夜之巡的技能等级提高3级。\r\n至多提升至15级。', '狩夜之巡的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (112, 9801, '克洛琳德', 4, '「铭记泪，生命与仁爱」', '<color=#FFD780FF>残光将终对敌人造成伤害时，将根据克洛琳德的当前生命之契百分比提升此次伤害，每1%生命之契都将使此次<color=#FFD780FF>残光将终造成的伤害提升2%；通过这种方式，至多使<color=#FFD780FF>残光将终造成的伤害提升200%。', '残光将终对敌人造成伤害时，将根据克洛琳德的当前生命之契百分比提升此次伤害，每1%生命之契都将使此次残光将终造成的伤害提升2%；通过这种方式，至多使残光将终造成的伤害提升200%。');
INSERT INTO `genshin_constellation` VALUES (113, 9801, '克洛琳德', 5, '「也铭记黎明终将到来」', '<color=#FFD780FF>残光将终的技能等级提高3级。\r\n至多提升至15级。', '残光将终的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (114, 9801, '克洛琳德', 6, '「为此，勿将希望弃扬」', '施放<color=#FFD780FF>狩夜之巡后的12秒内，克洛琳德的暴击率提升10%，暴击伤害提升70%。\r\n此外，夜巡状态持续期间，明烛之影会在特定条件下出现，进行追击，造成克洛琳德200%攻击力的<color=#FFACFFFF>雷元素伤害，通过这种方式造成的伤害视为普通攻击伤害。\r\n明烛之影会在如下情况下出现：\r\n·克洛琳德即将被攻击命中时；\r\n·克洛琳德进行贯夜·契令时。\r\n每1秒至多通过上述方式唤出1次明烛之影，一次夜巡状态持续期间，至多唤出6次明烛之影。\r\n此外，夜巡状态持续期间，克洛琳德受到的伤害降低80%，抗打断能力提高，该效果将在夜巡状态结束或唤出6次明烛之影的1秒后移除。', '施放狩夜之巡后的12秒内，克洛琳德的暴击率提升10%，暴击伤害提升70%。\r\n此外，夜巡状态持续期间，明烛之影会在特定条件下出现，进行追击，造成克洛琳德200%攻击力的雷元素伤害，通过这种方式造成的伤害视为普通攻击伤害。\r\n明烛之影会在如下情况下出现：\r\n·克洛琳德即将被攻击命中时；\r\n·克洛琳德进行贯夜·契令时。\r\n每1秒至多通过上述方式唤出1次明烛之影，一次夜巡状态持续期间，至多唤出6次明烛之影。\r\n此外，夜巡状态持续期间，克洛琳德受到的伤害降低80%，抗打断能力提高，该效果将在夜巡状态结束或唤出6次明烛之影的1秒后移除。');
INSERT INTO `genshin_constellation` VALUES (115, 6701, '柯莱', 1, '巡护深林', '柯莱处于队伍后台时，元素充能效率提升20%。', '柯莱处于队伍后台时，元素充能效率提升20%。');
INSERT INTO `genshin_constellation` VALUES (116, 6701, '柯莱', 2, '漫行山薮', '突破天赋「飞叶迴斜」转变为：\r\n<color=#FFD780FF>飞叶轮返回时，将为角色赋予突破天赋「飞叶迴斜」的「新叶」状态，持续对身边的敌人造成相当于柯莱攻击力40%的<color=#99FF88FF>草元素伤害，持续3秒。\r\n从施放<color=#FFD780FF>拂花偈叶开始，到此次新叶状态消失前，如果队伍中自己的角色触发了燃烧、原激化、超激化、蔓激化、绽放、超绽放、烈绽放或月绽放反应，则使此次新叶效果的持续时间延长3秒。\r\n新叶效果至多通过这种方式延长一次持续时间；在持续期间再次产生新叶效果时，将移除原有的效果。新叶效果造成的伤害视为元素战技伤害。\r\n需要解锁突破天赋「飞叶迴斜」。', '突破天赋「飞叶迴斜」转变为：\r\n飞叶轮返回时，将为角色赋予突破天赋「飞叶迴斜」的「新叶」状态，持续对身边的敌人造成相当于柯莱攻击力40%的草元素伤害，持续3秒。\r\n从施放拂花偈叶开始，到此次新叶状态消失前，如果队伍中自己的角色触发了燃烧、原激化、超激化、蔓激化、绽放、超绽放、烈绽放或月绽放反应，则使此次新叶效果的持续时间延长3秒。\r\n新叶效果至多通过这种方式延长一次持续时间；在持续期间再次产生新叶效果时，将移除原有的效果。新叶效果造成的伤害视为元素战技伤害。\r\n需要解锁突破天赋「飞叶迴斜」。');
INSERT INTO `genshin_constellation` VALUES (117, 6701, '柯莱', 3, '夏堇芳菲', '<color=#FFD780FF>拂花偈叶的技能等级提高3级。\r\n至多提升至15级。', '拂花偈叶的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (118, 6701, '柯莱', 4, '骞林馈遗', '施放<color=#FFD780FF>猫猫秘宝时，将使队伍中附近的所有角色（不包括柯莱自己）的元素精通提升60点，持续12秒。', '施放猫猫秘宝时，将使队伍中附近的所有角色（不包括柯莱自己）的元素精通提升60点，持续12秒。');
INSERT INTO `genshin_constellation` VALUES (119, 6701, '柯莱', 5, '俱象残火', '<color=#FFD780FF>猫猫秘宝的技能等级提高3级。\r\n至多提升至15级。', '猫猫秘宝的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (120, 6701, '柯莱', 6, '坠镞为林', '<color=#FFD780FF>飞叶轮命中时，会产生一个迷你柯里安巴，造成相当于柯莱攻击力200%的<color=#99FF88FF>草元素伤害。\r\n每次施放<color=#FFD780FF>拂花偈叶至多产生1次迷你柯里安巴。', '飞叶轮命中时，会产生一个迷你柯里安巴，造成相当于柯莱攻击力200%的草元素伤害。\r\n每次施放拂花偈叶至多产生1次迷你柯里安巴。');
INSERT INTO `genshin_constellation` VALUES (121, 12501, '哥伦比娅', 1, '遍照花海，隐入群山', '施放元素战技<color=#FFD780FF>万古潮汐时，还会立刻触发一次等同于<color=#FFD780FF>引力干涉的效果，该效果每15秒至多触发一次。\r\n<color=#FFD780FF>月兆·满辉 \r\n触发引力干涉时，若为哥伦比娅积攒最多引力值的月曜反应类型为：\r\n·<color=#FFD780FF>月感电反应：为队伍中自己的当前场上角色恢复6点元素能量；\r\n·<color=#FFD780FF>月绽放反应：提升队伍中自己的当前场上角色的抗打断能力，持续8秒；\r\n·<color=#FFD780FF>月结晶反应：唤出<color=#FFD780FF>雨海护盾，伤害吸收量受益于哥伦比娅生命值上限的12%，对<color=#80C0FFFF>水元素伤害有250%的吸收效果，持续8秒。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害<color=#FFD780FF>擢升1.5%。', '施放元素战技万古潮汐时，还会立刻触发一次等同于**引力干涉**的效果，该效果每15秒至多触发一次。\r\n月兆·满辉 \r\n触发引力干涉时，若为哥伦比娅积攒最多引力值的月曜反应类型为：\r\n·月感电反应：为队伍中自己的当前场上角色恢复6点元素能量；\r\n·月绽放反应：提升队伍中自己的当前场上角色的抗打断能力，持续8秒；\r\n·月结晶反应：唤出雨海护盾，伤害吸收量受益于哥伦比娅生命值上限的12%，对水元素伤害有250%的吸收效果，持续8秒。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害**擢升**1.5%。');
INSERT INTO `genshin_constellation` VALUES (122, 12501, '哥伦比娅', 2, '为夜增辉，与君遥伴', '<color=#FFD780FF>引力值的积攒速度提升34%。\r\n触发<color=#FFD780FF>引力干涉时，哥伦比娅将获得<color=#FFD780FF>皎辉效果，生命值上限提升40%，持续8秒。\r\n<color=#FFD780FF>月兆·满辉 ：\r\n<color=#FFD780FF>皎辉效果持续期间，若本次触发<color=#FFD780FF>引力干涉时，为哥伦比娅积攒最多引力值的月曜反应类型为：\r\n·<color=#FFD780FF>月感电反应：队伍中自己的当前场上角色攻击力提升，提升值相当于哥伦比娅生命值上限的1%；\r\n·<color=#FFD780FF>月绽放反应：队伍中自己的当前场上角色元素精通提升，提升值相当于哥伦比娅生命值上限的0.35%；\r\n·<color=#FFD780FF>月结晶反应：队伍中自己的当前场上角色防御力提升，提升值相当于哥伦比娅生命值上限的1%。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害<color=#FFD780FF>擢升7%。', '**引力值**的积攒速度提升34%。\r\n触发引力干涉时，哥伦比娅将获得皎辉效果，生命值上限提升40%，持续8秒。\r\n月兆·满辉 ：\r\n皎辉效果持续期间，若本次触发引力干涉时，为哥伦比娅积攒最多引力值的月曜反应类型为：\r\n·月感电反应：队伍中自己的当前场上角色攻击力提升，提升值相当于哥伦比娅生命值上限的1%；\r\n·月绽放反应：队伍中自己的当前场上角色元素精通提升，提升值相当于哥伦比娅生命值上限的0.35%；\r\n·月结晶反应：队伍中自己的当前场上角色防御力提升，提升值相当于哥伦比娅生命值上限的1%。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害**擢升**7%。');
INSERT INTO `genshin_constellation` VALUES (123, 12501, '哥伦比娅', 3, '柔光凝露，梦湖起波', '元素战技<color=#FFD780FF>万古潮汐的技能等级提高3级。\r\n至多提升至15级。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害<color=#FFD780FF>擢升1.5%。', '元素战技**万古潮汐**的技能等级提高3级。\r\n至多提升至15级。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害**擢升**1.5%。');
INSERT INTO `genshin_constellation` VALUES (124, 12501, '哥伦比娅', 4, '花岚云翳，山岩树影', '触发<color=#FFD780FF>引力干涉时，还会为哥伦比娅恢复4点元素能量；\r\n此外，依据为哥伦比娅积攒最多<color=#FFD780FF>引力值的月曜反应类型，若为月感电/月绽放/月结晶反应，则本次引力干涉造成的月曜反应伤害提升，提升值分别相当于哥伦比娅生命值上限的12.5%/2.5%/12.5%。上述效果每15秒至多触发一次。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害<color=#FFD780FF>擢升1.5%。', '触发**引力干涉**时，还会为哥伦比娅恢复4点元素能量；\r\n此外，依据为哥伦比娅积攒最多引力值的月曜反应类型，若为月感电/月绽放/月结晶反应，则本次引力干涉造成的月曜反应伤害提升，提升值分别相当于哥伦比娅生命值上限的12.5%/2.5%/12.5%。上述效果每15秒至多触发一次。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害**擢升**1.5%。');
INSERT INTO `genshin_constellation` VALUES (125, 12501, '哥伦比娅', 5, '万籁俱寂，唯闻君唱', '元素爆发<color=#FFD780FF>她的乡愁的技能等级提高3级。\r\n至多提升至15级。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害<color=#FFD780FF>擢升1.5%。', '元素爆发**她的乡愁**的技能等级提高3级。\r\n至多提升至15级。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害**擢升**1.5%。');
INSERT INTO `genshin_constellation` VALUES (126, 12501, '哥伦比娅', 6, '夜昏且暗，且随月光', '处于<color=#FFD780FF>月之领域中的所有角色触发月曜反应后的8秒内，依据参与反应的元素类型，使队伍中的所有角色造成的对应元素类型伤害的暴击伤害提升80%。同种元素类型的暴击伤害提升效果无法叠加。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害<color=#FFD780FF>擢升7%。', '处于**月之领域**中的所有角色触发月曜反应后的8秒内，依据参与反应的元素类型，使队伍中的所有角色造成的对应元素类型伤害的暴击伤害提升80%。同种元素类型的暴击伤害提升效果无法叠加。\r\n\r\n队伍中附近的所有角色造成的月曜反应伤害**擢升**7%。');
INSERT INTO `genshin_constellation` VALUES (127, 7101, '赛诺', 1, '立仪·俯览昼冥', '施放<color=#FFD780FF>圣仪·煟煌随狼行后，赛诺普通攻击的攻击速度提升20%，持续10秒。若施放<color=#FFD780FF>秘仪·律渊渡魂时触发了突破天赋「落羽的裁择」的「裁定」效果，将刷新该效果的持续时间。\r\n需要解锁突破天赋「落羽的裁择」。', '施放圣仪·煟煌随狼行后，赛诺普通攻击的攻击速度提升20%，持续10秒。若施放秘仪·律渊渡魂时触发了突破天赋「落羽的裁择」的「裁定」效果，将刷新该效果的持续时间。\r\n需要解锁突破天赋「落羽的裁择」。');
INSERT INTO `genshin_constellation` VALUES (128, 7101, '赛诺', 2, '令仪·引谒归灵', '赛诺的普通攻击命中敌人后，<color=#FFACFFFF>雷元素伤害加成提升10%，持续4秒。该效果每0.1秒至多触发一次，至多叠加5层。', '赛诺的普通攻击命中敌人后，雷元素伤害加成提升10%，持续4秒。该效果每0.1秒至多触发一次，至多叠加5层。');
INSERT INTO `genshin_constellation` VALUES (129, 7101, '赛诺', 3, '律仪·行度誓惩', '<color=#FFD780FF>圣仪·煟煌随狼行的技能等级提高3级。\r\n至多提升至15级。', '圣仪·煟煌随狼行的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (130, 7101, '赛诺', 4, '巡仪·蒇护禁罔', '赛诺处于<color=#FFD780FF>圣仪·煟煌随狼行的启途誓使状态下时，触发感电、月感电、超导、超载、原激化、超激化、超绽放、雷元素扩散反应后，将为队伍中附近的所有角色（除了赛诺自己）恢复3点元素能量。\r\n该效果在一次<color=#FFD780FF>圣仪·煟煌随狼行中，至多触发5次。', '赛诺处于圣仪·煟煌随狼行的启途誓使状态下时，触发感电、月感电、超导、超载、原激化、超激化、超绽放、雷元素扩散反应后，将为队伍中附近的所有角色（除了赛诺自己）恢复3点元素能量。\r\n该效果在一次圣仪·煟煌随狼行中，至多触发5次。');
INSERT INTO `genshin_constellation` VALUES (131, 7101, '赛诺', 5, '幽仪·逝往星芒', '<color=#FFD780FF>秘仪·律渊渡魂的技能等级提高3级。\r\n至多提升至15级。', '秘仪·律渊渡魂的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (132, 7101, '赛诺', 6, '羽仪·裁落钧衡', '施放<color=#FFD780FF>圣仪·煟煌随狼行或触发突破天赋「落羽的裁择」的「裁定」后，赛诺将获得4层「豺祭」效果。赛诺的普通攻击命中敌人时，将消耗一层「豺祭」效果，并发射一道渡荒之雷。\r\n「豺祭」持续8秒，至多叠加8层，并将在圣仪·煟煌随狼行的启途誓使状态结束后移除。\r\n每0.4秒至多通过这种方式发射一道渡荒之雷。\r\n需要解锁突破天赋「落羽的裁择」。', '施放圣仪·煟煌随狼行或触发突破天赋「落羽的裁择」的「裁定」后，赛诺将获得4层「豺祭」效果。赛诺的普通攻击命中敌人时，将消耗一层「豺祭」效果，并发射一道渡荒之雷。\r\n「豺祭」持续8秒，至多叠加8层，并将在圣仪·煟煌随狼行的启途誓使状态结束后移除。\r\n每0.4秒至多通过这种方式发射一道渡荒之雷。\r\n需要解锁突破天赋「落羽的裁择」。');
INSERT INTO `genshin_constellation` VALUES (133, 11501, '塔利雅', 1, '无瑕之引', '塔利雅每获得一层元素爆发<color=#FFD780FF>纯耀的祷咏中的「祝颂」效果，都将恢复2.5点元素能量。', '塔利雅每获得一层元素爆发**纯耀的祷咏**中的「祝颂」效果，都将恢复2.5点元素能量。');
INSERT INTO `genshin_constellation` VALUES (134, 11501, '塔利雅', 2, '眷怜启应', '塔利雅消耗元素爆发<color=#FFD780FF>纯耀的祷咏中的「祝颂」效果唤出圣眷护盾后，处于圣眷护盾庇护下的角色，护盾强效提升25%，持续12秒。', '塔利雅消耗元素爆发**纯耀的祷咏**中的「祝颂」效果唤出圣眷护盾后，处于圣眷护盾庇护下的角色，护盾强效提升25%，持续12秒。');
INSERT INTO `genshin_constellation` VALUES (135, 11501, '塔利雅', 3, '风花之奉', '元素爆发<color=#FFD780FF>纯耀的祷咏的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**纯耀的祷咏**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (136, 11501, '塔利雅', 4, '众愿的集祷', '元素爆发<color=#FFD780FF>纯耀的祷咏中的「西风之眷」效果的持续时间延长3秒。', '元素爆发**纯耀的祷咏**中的「西风之眷」效果的持续时间延长3秒。');
INSERT INTO `genshin_constellation` VALUES (137, 11501, '塔利雅', 5, '遂成的狡意', '元素战技<color=#FFD780FF>圣浸的礼典的技能等级提高3级。\r\n至多提升至15级。', '元素战技**圣浸的礼典**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (138, 11501, '塔利雅', 6, '愿一切欢睦陪伴你', '处于元素爆发<color=#FFD780FF>纯耀的祷咏中的「西风之眷」效果影响下的当前场上角色的攻击速度提升10%。\r\n此外，处于西风之眷效果影响下的当前场上角色倒下时，则立即：\r\n·复苏该角色；\r\n·将该角色生命值恢复至100%。\r\n该效果每15分钟只能触发一次。', '处于元素爆发**纯耀的祷咏**中的「西风之眷」效果影响下的当前场上角色的攻击速度提升10%。\r\n此外，处于西风之眷效果影响下的当前场上角色倒下时，则立即：\r\n·复苏该角色；\r\n·将该角色生命值恢复至100%。\r\n该效果每15分钟只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (139, 7901, '迪希雅', 1, '皎洁之火铓辉灿漫', '迪希雅的生命值上限提升20%；此外，基于生命值上限，迪希雅的以下攻击造成的伤害提高：\r\n·<color=#FFD780FF>熔铁流狱伤害提高值：生命值上限的3.6%；\r\n·<color=#FFD780FF>炎啸狮子咬伤害提高值：生命值上限的6%。', '迪希雅的生命值上限提升20%；此外，基于生命值上限，迪希雅的以下攻击造成的伤害提高：\r\n·熔铁流狱伤害提高值：生命值上限的3.6%；\r\n·炎啸狮子咬伤害提高值：生命值上限的6%。');
INSERT INTO `genshin_constellation` VALUES (140, 7901, '迪希雅', 2, '净沙利刃明映万乘', '施放<color=#FFD780FF>熔铁流狱·剑域炽焰时，重新产生的净焰剑狱领域持续时间将延长6秒。\r\n此外，场上存在净焰剑狱领域时，领域内的当前场上角色受到攻击时，将使净焰剑狱下次协同攻击造成的伤害提升50%。', '施放熔铁流狱·剑域炽焰时，重新产生的净焰剑狱领域持续时间将延长6秒。\r\n此外，场上存在净焰剑狱领域时，领域内的当前场上角色受到攻击时，将使净焰剑狱下次协同攻击造成的伤害提升50%。');
INSERT INTO `genshin_constellation` VALUES (141, 7901, '迪希雅', 3, '怒势疾迅如焚掠地', '<color=#FFD780FF>炎啸狮子咬的技能等级提高3级。\r\n至多提升至15级。', '炎啸狮子咬的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (142, 7901, '迪希雅', 4, '服膺誓禁恪守无失', '<color=#FFD780FF>炎啸狮子咬的炽鬃拳与焚落踢命中敌人时，将为迪希雅恢复1.5点元素能量，并基于生命值上限的2.5%，为迪希雅恢复生命值。该效果每0.2秒至多触发一次。', '炎啸狮子咬的炽鬃拳与焚落踢命中敌人时，将为迪希雅恢复1.5点元素能量，并基于生命值上限的2.5%，为迪希雅恢复生命值。该效果每0.2秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (143, 7901, '迪希雅', 5, '猎兽魁首卓荦不羁', '<color=#FFD780FF>熔铁流狱的技能等级提高3级。\r\n至多提升至15级。', '熔铁流狱的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (144, 7901, '迪希雅', 6, '燎燃利爪裂帛斫金', '<color=#FFD780FF>炎啸狮子咬的暴击率提升10%。\r\n此外，在一次炽炎狮子的持续期间，炽鬃拳命中敌人并造成暴击后，将使持续期间内炎啸狮子咬的暴击伤害提升15%，炽炎狮子的持续时间延长0.5秒。该效果每0.2秒至多触发一次，至多通过这种方式使持续时间延长2秒，暴击伤害提升60%。', '炎啸狮子咬的暴击率提升10%。\r\n此外，在一次炽炎狮子的持续期间，炽鬃拳命中敌人并造成暴击后，将使持续期间内炎啸狮子咬的暴击伤害提升15%，炽炎狮子的持续时间延长0.5秒。该效果每0.2秒至多触发一次，至多通过这种方式使持续时间延长2秒，暴击伤害提升60%。');
INSERT INTO `genshin_constellation` VALUES (145, 1601, '迪卢克', 1, '罪罚裁断', '对生命值高于50%的敌人，迪卢克造成的伤害提高15%。', '对生命值高于50%的敌人，迪卢克造成的伤害提高15%。');
INSERT INTO `genshin_constellation` VALUES (146, 1601, '迪卢克', 2, '炙热余烬', '迪卢克受到伤害时，攻击力提高10%，攻击速度提高5%，持续10秒。\r\n该效果至多叠加3次，每1.5秒只能触发一次。', '迪卢克受到伤害时，攻击力提高10%，攻击速度提高5%，持续10秒。\r\n该效果至多叠加3次，每1.5秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (147, 1601, '迪卢克', 3, '钢铁炽焰', '<color=#FFD780FF>逆焰之刃的技能等级提高3级。\r\n至多提升至15级。', '逆焰之刃的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (148, 1601, '迪卢克', 4, '流火焦灼', '有节奏地释放<color=#FFD780FF>逆焰之刃可以大幅提升造成的伤害。\r\n施放<color=#FFD780FF>逆焰之刃的2秒后，使下一段逆焰之刃的伤害提高40%，持续2秒。', '有节奏地释放逆焰之刃可以大幅提升造成的伤害。\r\n施放逆焰之刃的2秒后，使下一段逆焰之刃的伤害提高40%，持续2秒。');
INSERT INTO `genshin_constellation` VALUES (149, 1601, '迪卢克', 5, '昭告黎明的火之鸟', '<color=#FFD780FF>黎明的技能等级提高3级。\r\n至多提升至15级。', '黎明的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (150, 1601, '迪卢克', 6, '清算黑暗的炎之剑', '施放<color=#FFD780FF>逆焰之刃后，接下来6秒内的2次普通攻击速度提升30%，造成的伤害提高30%。\r\n此外，逆焰之刃不再重置普通攻击连击段数。', '施放逆焰之刃后，接下来6秒内的2次普通攻击速度提升30%，造成的伤害提高30%。\r\n此外，逆焰之刃不再重置普通攻击连击段数。');
INSERT INTO `genshin_constellation` VALUES (151, 3901, '迪奥娜', 1, '特调的余韵', '<color=#FFD780FF>最烈特调的效果结束时，为迪奥娜恢复15点元素能量。', '最烈特调的效果结束时，为迪奥娜恢复15点元素能量。');
INSERT INTO `genshin_constellation` VALUES (152, 3901, '迪奥娜', 2, '猫爪冰摇', '<color=#FFD780FF>猫爪冻冻造成的伤害提高15%，护盾的伤害吸收量提高15%；\r\n此外，命中时，将为附近的当前其他场上角色生成一个伤害吸收量为<color=#FFD780FF>猫爪冻冻50%的护盾，持续5秒。', '猫爪冻冻造成的伤害提高15%，护盾的伤害吸收量提高15%；\r\n此外，命中时，将为附近的当前其他场上角色生成一个伤害吸收量为猫爪冻冻50%的护盾，持续5秒。');
INSERT INTO `genshin_constellation` VALUES (153, 3901, '迪奥娜', 3, '还、还要续杯？', '<color=#FFD780FF>最烈特调的技能等级提高3级。\r\n至多提升至15级。', '最烈特调的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (154, 3901, '迪奥娜', 4, '「酒业杀手」', '在<color=#FFD780FF>最烈特调的领域内，迪奥娜的瞄准射击的所需的蓄力时间减少60%。', '在最烈特调的领域内，迪奥娜的瞄准射击的所需的蓄力时间减少60%。');
INSERT INTO `genshin_constellation` VALUES (155, 3901, '迪奥娜', 5, '双份加冰', '<color=#FFD780FF>猫爪冻冻的技能等级提高3级。\r\n至多提升至15级。', '猫爪冻冻的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (156, 3901, '迪奥娜', 6, '猫尾打烊之时', '处在<color=#FFD780FF>最烈特调领域内的角色，依据生命值获得如下效果：\r\n·生命值低于或等于50%时，受治疗加成提升30%；\r\n·生命值高于50%时，元素精通提升200。', '处在最烈特调领域内的角色，依据生命值获得如下效果：\r\n·生命值低于或等于50%时，受治疗加成提升30%；\r\n·生命值高于50%时，元素精通提升200。');
INSERT INTO `genshin_constellation` VALUES (157, 6801, '多莉', 1, '追加投资', '<color=#FFD780FF>断除烦恼炮命中后产生的售后服务弹增加1枚。', '断除烦恼炮命中后产生的售后服务弹增加1枚。');
INSERT INTO `genshin_constellation` VALUES (158, 6801, '多莉', 2, '特许经营', '在战斗状态中，当<color=#FFD780FF>灯中幽精为相连的角色进行治疗时，将从该角色处发射一枚镇灵炮，造成相当于多莉攻击力50%的伤害。', '在战斗状态中，当灯中幽精为相连的角色进行治疗时，将从该角色处发射一枚镇灵炮，造成相当于多莉攻击力50%的伤害。');
INSERT INTO `genshin_constellation` VALUES (159, 6801, '多莉', 3, '百巧千奇', '<color=#FFD780FF>卡萨扎莱宫的无微不至的技能等级提高3级。\r\n至多提升至15级。', '卡萨扎莱宫的无微不至的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (160, 6801, '多莉', 4, '酌盈剂虚', '与<color=#FFD780FF>灯中幽精相连的角色，依据当前的生命值与元素能量，获得以下提升：\r\n·生命值低于50%时，提升50%受治疗加成；\r\n·元素能量低于50%时，提升30%元素充能效率。', '与灯中幽精相连的角色，依据当前的生命值与元素能量，获得以下提升：\r\n·生命值低于50%时，提升50%受治疗加成；\r\n·元素能量低于50%时，提升30%元素充能效率。');
INSERT INTO `genshin_constellation` VALUES (161, 6801, '多莉', 5, '物超所值', '<color=#FFD780FF>镇灵之灯·烦恼解决炮的技能等级提高3级。\r\n至多提升至15级。', '镇灵之灯·烦恼解决炮的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (162, 6801, '多莉', 6, '漫掷万镒', '多莉施放<color=#FFD780FF>镇灵之灯·烦恼解决炮后的3秒内，将获得以下效果：\r\n·<color=#FFACFFFF>雷元素附魔；\r\n·普通攻击命中敌人时，为队伍中附近的所有角色恢复相当于多莉生命值上限4%的生命值，每0.1秒至多通过这种方式恢复一次生命值。', '多莉施放镇灵之灯·烦恼解决炮后的3秒内，将获得以下效果：\r\n·雷元素附魔；\r\n·普通攻击命中敌人时，为队伍中附近的所有角色恢复相当于多莉生命值上限4%的生命值，每0.1秒至多通过这种方式恢复一次生命值。');
INSERT INTO `genshin_constellation` VALUES (163, 12301, '杜林', 1, '红土之逆', '施放元素爆发后，依据杜林施放的元素爆发，会分别造成不同的效果：\r\n·<color=#FFD780FF>白化法·如光流变：队伍中附近的所有其他角色获得20层<color=#FFD780FF>「轮变启迪」，持续20秒。拥有「轮变启迪」的当前场上角色的普通攻击、重击、下落攻击、元素战技或元素爆发造成伤害时，将消耗1层「轮变启迪」，提升造成的伤害，提升值相当于杜林攻击力的60%。队伍中拥有「轮变启迪」的角色，其生效次数单独计算。\r\n·<color=#FFD780FF>黑度法·如星阴燃：杜林获得20层<color=#FFD780FF>「轮变启迪」，持续20秒。杜林造成元素爆发伤害时，将消耗2层「轮变启迪」，提升造成的伤害，提升值相当于杜林攻击力的150%。\r\n\r\n施放元素爆发时，<color=#FFD780FF>「轮变启迪」的层数将会刷新。', '施放元素爆发后，依据杜林施放的元素爆发，会分别造成不同的效果：\r\n·白化法·如光流变：队伍中附近的所有其他角色获得20层「轮变启迪」，持续20秒。拥有「轮变启迪」的当前场上角色的普通攻击、重击、下落攻击、元素战技或元素爆发造成伤害时，将消耗1层「轮变启迪」，提升造成的伤害，提升值相当于杜林攻击力的60%。队伍中拥有「轮变启迪」的角色，其生效次数单独计算。\r\n·黑度法·如星阴燃：杜林获得20层「轮变启迪」，持续20秒。杜林造成元素爆发伤害时，将消耗2层「轮变启迪」，提升造成的伤害，提升值相当于杜林攻击力的150%。\r\n\r\n施放元素爆发时，「轮变启迪」的层数将会刷新。');
INSERT INTO `genshin_constellation` VALUES (164, 12301, '杜林', 2, '无底之想', '杜林施放元素爆发后的20秒内，队伍中附近的角色对敌人触发蒸发、融化、燃烧、超载、火元素扩散或火元素结晶反应后，或对处于燃烧状态下的敌人造成<color=#FF9999FF>火元素伤害或<color=#99FF88FF>草元素伤害时，队伍中附近的角色造成的<color=#FF9999FF>火元素伤害与参与反应的对应元素伤害提升50%，持续6秒。', '杜林施放元素爆发后的20秒内，队伍中附近的角色对敌人触发蒸发、融化、燃烧、超载、火元素扩散或火元素结晶反应后，或对处于燃烧状态下的敌人造成火元素伤害或草元素伤害时，队伍中附近的角色造成的火元素伤害与参与反应的对应元素伤害提升50%，持续6秒。');
INSERT INTO `genshin_constellation` VALUES (165, 12301, '杜林', 3, '焰镜之显', '元素爆发<color=#FFD780FF>白化法·如光流变的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**白化法·如光流变**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (166, 12301, '杜林', 4, '流溢之原', '杜林造成的元素爆发伤害提升40%。此外，触发命之座<color=#FFD780FF>「红土之逆」中消耗<color=#FFD780FF>「轮变启迪」的效果时，有30%几率不会消耗「轮变启迪」。', '杜林造成的元素爆发伤害提升40%。此外，触发命之座**「红土之逆」**中消耗「轮变启迪」的效果时，有30%几率不会消耗「轮变启迪」。');
INSERT INTO `genshin_constellation` VALUES (167, 12301, '杜林', 5, '苦火之裂', '元素战技<color=#FFD780FF>二元式·聚分熔炼的技能等级提高3级。\r\n至多提升至15级。', '元素战技**二元式·聚分熔炼**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (168, 12301, '杜林', 6, '双重诞生', '杜林造成的元素爆发伤害将无视敌人30%的防御力。\r\n此外，杜林的元素爆发<color=#FFD780FF>白化法·如光流变与<color=#FFD780FF>黑度法·如星阴燃分别获得强化：\r\n·元素爆发<color=#FFD780FF>白化法·如光流变与<color=#FFD780FF>「白焰之龙」命中敌人时，该敌人的防御力降低30%，持续6秒；\r\n·元素爆发<color=#FFD780FF>黑度法·如星阴燃与<color=#FFD780FF>「黑蚀之龙」造成的伤害将额外无视敌人40%的防御力。', '杜林造成的元素爆发伤害将无视敌人30%的防御力。\r\n此外，杜林的元素爆发白化法·如光流变与黑度法·如星阴燃分别获得强化：\r\n·元素爆发白化法·如光流变与「白焰之龙」命中敌人时，该敌人的防御力降低30%，持续6秒；\r\n·元素爆发黑度法·如星阴燃与「黑蚀之龙」造成的伤害将额外无视敌人40%的防御力。');
INSERT INTO `genshin_constellation` VALUES (169, 9901, '艾梅莉埃', 1, '淡香浸析', '<color=#FFD780FF>撷萃调香与突破天赋「余薰」的清露香氛造成的伤害提升20%，后者需要解锁突破天赋「余薰」。\r\n此外，队伍中附近的角色对敌人触发燃烧反应或对处于燃烧状态下的敌人造成<color=#99FF88FF>草元素伤害时，会额外生成一枚<color=#FFD780FF>香韵。此效果每2.9秒至多触发一次。', '撷萃调香与突破天赋「余薰」的清露香氛造成的伤害提升20%，后者需要解锁突破天赋「余薰」。\r\n此外，队伍中附近的角色对敌人触发燃烧反应或对处于燃烧状态下的敌人造成草元素伤害时，会额外生成一枚香韵。此效果每2.9秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (170, 9901, '艾梅莉埃', 2, '湖光顶调', '<color=#FFD780FF>撷萃调香、<color=#FFD780FF>香氛演绎或突破天赋「余薰」的清露香氛（需解锁该突破天赋）命中敌人时，该敌人的<color=#99FF88FF>草元素抗性降低30%，持续10秒。', '撷萃调香、香氛演绎或突破天赋「余薰」的清露香氛（需解锁该突破天赋）命中敌人时，该敌人的草元素抗性降低30%，持续10秒。');
INSERT INTO `genshin_constellation` VALUES (171, 9901, '艾梅莉埃', 3, '郁馥臻萃', '<color=#FFD780FF>撷萃调香的技能等级提高3级。\r\n至多提升至15级。', '撷萃调香的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (172, 9901, '艾梅莉埃', 4, '柔灯心韵', '<color=#FFD780FF>香氛演绎的持续时间延长2秒，且每名敌人被香露选为目标的间隔降低0.3秒。', '香氛演绎的持续时间延长2秒，且每名敌人被香露选为目标的间隔降低0.3秒。');
INSERT INTO `genshin_constellation` VALUES (173, 9901, '艾梅莉埃', 5, '纯露凝芳', '<color=#FFD780FF>香氛演绎的技能等级提高3级。\r\n至多提升至15级。', '香氛演绎的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (174, 9901, '艾梅莉埃', 6, '茉洁香迹', '施放<color=#FFD780FF>撷萃调香或<color=#FFD780FF>香氛演绎时，艾梅莉埃将获得「香迹留驻」，持续5秒。\r\n持续期间，艾梅莉埃进行普通攻击或重击后，将会产生一枚香韵，且艾梅莉埃的普通攻击与重击将转为无法被附魔覆盖的<color=#99FF88FF>草元素伤害，并提升造成的伤害，提升值相当于艾梅莉埃攻击力的300%。\r\n\r\n「香迹留驻」效果将在通过这种方式产生4枚香韵或持续时间结束时解除。每12秒至多获得一次「香迹留驻」效果。', '施放撷萃调香或香氛演绎时，艾梅莉埃将获得「香迹留驻」，持续5秒。\r\n持续期间，艾梅莉埃进行普通攻击或重击后，将会产生一枚香韵，且艾梅莉埃的普通攻击与重击将转为无法被附魔覆盖的草元素伤害，并提升造成的伤害，提升值相当于艾梅莉埃攻击力的300%。\r\n\r\n「香迹留驻」效果将在通过这种方式产生4枚香韵或持续时间结束时解除。每12秒至多获得一次「香迹留驻」效果。');
INSERT INTO `genshin_constellation` VALUES (175, 11201, '爱可菲', 1, '味蕾绽放的餐前旋舞', '队伍中4名角色的元素类型均为<color=#80C0FFFF>水元素或<color=#99FFFFFF>冰元素时，爱可菲施放元素战技<color=#FFD780FF>低温烹饪或元素爆发<color=#FFD780FF>花刀技法后的15秒内，队伍中附近的所有角色造成<color=#99FFFFFF>冰元素伤害时的暴击伤害提升60%。\r\n需要解锁突破天赋「灵感浸入调味」。', '队伍中4名角色的元素类型均为水元素或冰元素时，爱可菲施放元素战技**低温烹饪**或元素爆发**花刀技法**后的15秒内，队伍中附近的所有角色造成冰元素伤害时的暴击伤害提升60%。\r\n需要解锁突破天赋「灵感浸入调味」。');
INSERT INTO `genshin_constellation` VALUES (176, 11201, '爱可菲', 2, '鲜香味腴的炖煮艺术', '爱可菲以<color=#FFD780FF>低温冷藏模式启动厨艺机关时，将获得「现制名肴」效果，持续15秒：持续期间，爱可菲获得5层「冷煮」，除爱可菲外的附近的当前场上角色普通攻击、重击、下落攻击、元素战技和元素爆发对敌人造成<color=#99FFFFFF>冰元素伤害时，将消耗1层「冷煮」，提升造成的伤害，提升值相当于爱可菲攻击力的240%。\r\n一次<color=#99FFFFFF>冰元素伤害同时命中多名敌人时，会依据命中敌人的数量消耗「冷煮」的层数。', '爱可菲以**低温冷藏模式**启动厨艺机关时，将获得「现制名肴」效果，持续15秒：持续期间，爱可菲获得5层「冷煮」，除爱可菲外的附近的当前场上角色普通攻击、重击、下落攻击、元素战技和元素爆发对敌人造成冰元素伤害时，将消耗1层「冷煮」，提升造成的伤害，提升值相当于爱可菲攻击力的240%。\r\n一次冰元素伤害同时命中多名敌人时，会依据命中敌人的数量消耗「冷煮」的层数。');
INSERT INTO `genshin_constellation` VALUES (177, 11201, '爱可菲', 3, '焦糖褐变的烘烤魔法', '元素战技<color=#FFD780FF>低温烹饪的技能等级提高3级。\r\n至多提升至15级。', '元素战技**低温烹饪**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (178, 11201, '爱可菲', 4, '迷迭生香的配比秘方', '<color=#FFD780FF>康复食疗的持续时间延长6秒。持续期间，通过<color=#FFD780FF>康复食疗触发治疗时，有几率使治疗量提升100%，并为爱可菲恢复2点元素能量，几率相当于爱可菲自己的暴击率。一次<color=#FFD780FF>康复食疗持续期间，该效果至多触发7次。\r\n需要解锁突破天赋「美食胜过良药」。', '**康复食疗**的持续时间延长6秒。持续期间，通过康复食疗触发治疗时，有几率使治疗量提升100%，并为爱可菲恢复2点元素能量，几率相当于爱可菲自己的暴击率。一次康复食疗持续期间，该效果至多触发7次。\r\n需要解锁突破天赋「美食胜过良药」。');
INSERT INTO `genshin_constellation` VALUES (179, 11201, '爱可菲', 5, '千种酱汁的风味交响', '元素爆发<color=#FFD780FF>花刀技法的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**花刀技法**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (180, 11201, '爱可菲', 6, '虹彩缤纷的甜点茶话', '<color=#FFD780FF>厨艺机关·低温冷藏模式获得强化：\r\n·队伍中自己的当前场上角色的普通攻击、重击或下落攻击命中敌人时，厨艺机关·低温冷藏模式将发射一枚额外的特级冻霜芭菲，造成爱可菲500%攻击力的<color=#99FFFFFF>冰元素范围伤害。该伤害视为元素战技伤害。\r\n该效果每0.5秒至多触发一次，一次厨艺机关·低温冷藏模式持续期间，该效果至多触发6次。', '**厨艺机关·低温冷藏模式**获得强化：\r\n·队伍中自己的当前场上角色的普通攻击、重击或下落攻击命中敌人时，厨艺机关·低温冷藏模式将发射一枚额外的特级冻霜芭菲，造成爱可菲500%攻击力的冰元素范围伤害。该伤害视为元素战技伤害。\r\n该效果每0.5秒至多触发一次，一次厨艺机关·低温冷藏模式持续期间，该效果至多触发6次。');
INSERT INTO `genshin_constellation` VALUES (181, 5101, '优菈', 1, '光潮的幻象', '消耗<color=#FFD780FF>冰潮的涡旋的冷酷之心效果后，优菈的物理伤害加成提高30%，持续6秒，\r\n每消耗一层冷酷之心，都会使这个效果的持续时间延长6秒，最多不会超过18秒。', '消耗冰潮的涡旋的冷酷之心效果后，优菈的物理伤害加成提高30%，持续6秒，\r\n每消耗一层冷酷之心，都会使这个效果的持续时间延长6秒，最多不会超过18秒。');
INSERT INTO `genshin_constellation` VALUES (182, 5101, '优菈', 2, '海沫的少女', '缩短<color=#FFD780FF>冰潮的涡旋长按的冷却时间，使其降低至与点按的冷却时间相同。', '缩短冰潮的涡旋长按的冷却时间，使其降低至与点按的冷却时间相同。');
INSERT INTO `genshin_constellation` VALUES (183, 5101, '优菈', 3, '劳伦斯的血脉', '<color=#FFD780FF>凝浪之光剑的技能等级提高3级。\r\n至多提升至15级。', '凝浪之光剑的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (184, 5101, '优菈', 4, '自卑者的逞强', '对生命值低于50%的敌人，光降之剑造成的伤害提高25%。', '对生命值低于50%的敌人，光降之剑造成的伤害提高25%。');
INSERT INTO `genshin_constellation` VALUES (185, 5101, '优菈', 5, '骑士的素质', '<color=#FFD780FF>冰潮的涡旋的技能等级提高3级。\r\n至多提升至15级。', '冰潮的涡旋的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (186, 5101, '优菈', 6, '高贵者的义务', '<color=#FFD780FF>凝浪之光剑创造的光降之剑立即获得5层能量。普通攻击、元素战技或元素爆发造成伤害使其积蓄能量层数时，有50%的概率额外获得一层。', '凝浪之光剑创造的光降之剑立即获得5层能量。普通攻击、元素战技或元素爆发造成伤害使其积蓄能量层数时，有50%的概率额外获得一层。');
INSERT INTO `genshin_constellation` VALUES (187, 7601, '珐露珊', 1, '舍径求真', '处于一次<color=#FFD780FF>非想风天的「疾风示现」效果下时，珐露珊至多可以通过蓄力完毕的瞄准射击释放2枚「飓烈箭」。', '处于一次非想风天的「疾风示现」效果下时，珐露珊至多可以通过蓄力完毕的瞄准射击释放2枚「飓烈箭」。');
INSERT INTO `genshin_constellation` VALUES (188, 7601, '珐露珊', 2, '忘形炼智', '<color=#FFD780FF>抟风秘道的「赫耀多方面体」的存在时间延长6秒。', '抟风秘道的「赫耀多方面体」的存在时间延长6秒。');
INSERT INTO `genshin_constellation` VALUES (189, 7601, '珐露珊', 3, '漫行灵圃', '<color=#FFD780FF>非想风天的技能等级提高3级。\r\n至多提升至15级。', '非想风天的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (190, 7601, '珐露珊', 4, '神机明悟', '依据命中敌人的数量，<color=#FFD780FF>风压坍陷产生的风涡可以为珐露珊恢复元素能量：命中一名敌人时，将为珐露珊恢复2点元素能量；每额外命中一名敌人，都将进一步为珐露珊恢复0.5点元素能量。\r\n一次风涡，至多通过这种方式为珐露珊恢复4点元素能量。', '依据命中敌人的数量，风压坍陷产生的风涡可以为珐露珊恢复元素能量：命中一名敌人时，将为珐露珊恢复2点元素能量；每额外命中一名敌人，都将进一步为珐露珊恢复0.5点元素能量。\r\n一次风涡，至多通过这种方式为珐露珊恢复4点元素能量。');
INSERT INTO `genshin_constellation` VALUES (191, 7601, '珐露珊', 5, '繁想奇境', '<color=#FFD780FF>抟风秘道的技能等级提高3级。\r\n至多提升至15级。', '抟风秘道的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (192, 7601, '珐露珊', 6, '妙道合真', '处于<color=#FFD780FF>抟风秘道的「祈风之赐」效果影响下的角色，造成<color=#80FFD7FF>风元素伤害时的暴击伤害提升40%；处于「祈风之赐」效果影响下的当前场上角色造成伤害时，将为该敌人施加「风压坍陷」。此效果3秒至多触发一次，队伍中所有角色共享冷却时间。', '处于抟风秘道的「祈风之赐」效果影响下的角色，造成风元素伤害时的暴击伤害提升40%；处于「祈风之赐」效果影响下的当前场上角色造成伤害时，将为该敌人施加「风压坍陷」。此效果3秒至多触发一次，队伍中所有角色共享冷却时间。');
INSERT INTO `genshin_constellation` VALUES (193, 3101, '菲谢尔', 1, '幽邃鸦眼', '奥兹不在战场上时，也会透过鸦眼守望菲谢尔。在菲谢尔对敌人进行普通攻击时，奥兹会通过鸦眼协同攻击，造成22%攻击力的伤害。', '奥兹不在战场上时，也会透过鸦眼守望菲谢尔。在菲谢尔对敌人进行普通攻击时，奥兹会通过鸦眼协同攻击，造成22%攻击力的伤害。');
INSERT INTO `genshin_constellation` VALUES (194, 3101, '菲谢尔', 2, '圣裁影羽', '施放<color=#FFD780FF>夜巡影翼时，能额外造成200%攻击力的伤害，并使影响范围扩大50%。', '施放夜巡影翼时，能额外造成200%攻击力的伤害，并使影响范围扩大50%。');
INSERT INTO `genshin_constellation` VALUES (195, 3101, '菲谢尔', 3, '渊色黑翼', '<color=#FFD780FF>夜巡影翼的技能等级提高3级。\r\n至多提升至15级。', '夜巡影翼的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (196, 3101, '菲谢尔', 4, '皇女幻绮谭', '施放<color=#FFD780FF>至夜幻现时，会对周围的敌人造成222%攻击力的<color=#FFACFFFF>雷元素伤害；\r\n技能效果结束时，会为菲谢尔恢复20%生命值。', '施放至夜幻现时，会对周围的敌人造成222%攻击力的雷元素伤害；\r\n技能效果结束时，会为菲谢尔恢复20%生命值。');
INSERT INTO `genshin_constellation` VALUES (197, 3101, '菲谢尔', 5, '至夜默示录', '<color=#FFD780FF>至夜幻现的技能等级提高3级。\r\n至多提升至15级。', '至夜幻现的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (198, 3101, '菲谢尔', 6, '永夜之禽', '奥兹的存在时间延长2秒。此外，奥兹会协同当前场上自己的角色一起攻击，造成菲谢尔30%攻击力的<color=#FFACFFFF>雷元素伤害。', '奥兹的存在时间延长2秒。此外，奥兹会协同当前场上自己的角色一起攻击，造成菲谢尔30%攻击力的雷元素伤害。');
INSERT INTO `genshin_constellation` VALUES (199, 12001, '菲林斯', 1, '拨开雪翳之幕', '特殊元素战技<color=#FFD780FF>北国枪阵的基础冷却时间缩短为4秒。\r\n此外，队伍中的角色触发月感电反应时，还会为菲林斯恢复8点元素能量，该效果每5.5秒至多触发一次。', '特殊元素战技北国枪阵的基础冷却时间缩短为4秒。\r\n此外，队伍中的角色触发月感电反应时，还会为菲林斯恢复8点元素能量，该效果每5.5秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (200, 12001, '菲林斯', 2, '渡越魍魉之墙', '施放特殊元素战技<color=#FFD780FF>北国枪阵后的6秒内，菲林斯的下一次普通攻击命中敌人时，还会额外造成相当于菲林斯攻击力50%的<color=#FFACFFFF>雷元素范围伤害，该伤害视为月感电反应造成的伤害。\r\n<color=#FFD780FF>月兆·满辉：菲林斯在场上时，菲林斯的元素类型为<color=#FFACFFFF>雷元素的攻击命中敌人后，该敌人的<color=#FFACFFFF>雷元素抗性降低25%，持续7秒。', '施放特殊元素战技北国枪阵后的6秒内，菲林斯的下一次普通攻击命中敌人时，还会额外造成相当于菲林斯攻击力50%的雷元素范围伤害，该伤害视为月感电反应造成的伤害。\r\n月兆·满辉：菲林斯在场上时，菲林斯的元素类型为雷元素的攻击命中敌人后，该敌人的雷元素抗性降低25%，持续7秒。');
INSERT INTO `genshin_constellation` VALUES (201, 12001, '菲林斯', 3, '夜访陌客之沼', '元素爆发<color=#FFD780FF>旧仪·夜客致访的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**旧仪·夜客致访**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (202, 12001, '菲林斯', 4, '荒山嘶啭之夜', '菲林斯的攻击力提升20%。\r\n此外，突破天赋<color=#FFD780FF>「幽焰的呢喃」获得强化：菲林斯的元素精通提升，提升值相当于菲林斯的攻击力的10%。通过这种方式，至多使菲林斯的元素精通提升220点。', '菲林斯的攻击力提升20%。\r\n此外，突破天赋**「幽焰的呢喃」**获得强化：菲林斯的元素精通提升，提升值相当于菲林斯的攻击力的10%。通过这种方式，至多使菲林斯的元素精通提升220点。');
INSERT INTO `genshin_constellation` VALUES (203, 12001, '菲林斯', 5, '逐远避世之影', '元素战技<color=#FFD780FF>古律·孤灯遗秘的技能等级提高3级。\r\n至多提升至15级。', '元素战技**古律·孤灯遗秘**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (204, 12001, '菲林斯', 6, '歌与亡者之舞', '菲林斯对敌人造成的月感电反应伤害<color=#FFD780FF>擢升35%。\r\n<color=#FFD780FF>月兆·满辉：队伍中附近的所有角色造成的月感电反应伤害<color=#FFD780FF>擢升10%。', '菲林斯对敌人造成的月感电反应伤害**擢升**35%。\r\n月兆·满辉：队伍中附近的所有角色造成的月感电反应伤害擢升10%。');
INSERT INTO `genshin_constellation` VALUES (205, 8501, '菲米尼', 1, '深水与泡沫之梦', '<color=#FFD780FF>浮冰增压·高压粉碎的暴击率提高15%。', '浮冰增压·高压粉碎的暴击率提高15%。');
INSERT INTO `genshin_constellation` VALUES (206, 8501, '菲米尼', 2, '企鹅与丰渥之国', '施放<color=#FFD780FF>浮冰增压·高压粉碎将为菲米尼恢复2点元素能量。如果施放的是四阶压力的高压粉碎，则转为恢复3点。', '施放浮冰增压·高压粉碎将为菲米尼恢复2点元素能量。如果施放的是四阶压力的高压粉碎，则转为恢复3点。');
INSERT INTO `genshin_constellation` VALUES (207, 8501, '菲米尼', 3, '洑流与白砂之歌', '<color=#FFD780FF>普通攻击·洑流剑的技能等级提高3级。\r\n至多提升至15级。', '普通攻击·洑流剑的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (208, 8501, '菲米尼', 4, '雪月与芦笛之舞', '菲米尼对敌人触发冰冻、碎冰、超导反应后，攻击力提升9%。该效果持续6秒，至多叠加2次，每0.3秒至多触发一次。', '菲米尼对敌人触发冰冻、碎冰、超导反应后，攻击力提升9%。该效果持续6秒，至多叠加2次，每0.3秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (209, 8501, '菲米尼', 5, '炉火与欢笑之夜', '<color=#FFD780FF>浮冰增压的技能等级提高3级。\r\n至多提升至15级。', '浮冰增压的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (210, 8501, '菲米尼', 6, '梦晓与决意之刻', '菲米尼对敌人触发冰冻、碎冰、超导反应后，暴击伤害提升12%。该效果持续6秒，至多叠加3次，每0.3秒至多触发一次。', '菲米尼对敌人触发冰冻、碎冰、超导反应后，暴击伤害提升12%。该效果持续6秒，至多叠加3次，每0.3秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (211, 8901, '芙宁娜', 1, '「爱是难驯鸟，哀乞亦无用。」', '施放<color=#FFD780FF>万众狂欢时，芙宁娜获得150点「气氛值」。\r\n此外，芙宁娜持有「气氛值」的上限提升100点。', '施放万众狂欢时，芙宁娜获得150点「气氛值」。\r\n此外，芙宁娜持有「气氛值」的上限提升100点。');
INSERT INTO `genshin_constellation` VALUES (212, 8901, '芙宁娜', 2, '「女人皆善变，仿若水中萍。」', '<color=#FFD780FF>万众狂欢持续期间，芙宁娜通过队伍中附近角色的当前生命值提升或降低的方式获得的「气氛值」提升250%。基于「气氛值」超过上限的部分，每1点「气氛值」都将使芙宁娜的生命值上限提升0.35%。至多通过这种方式使芙宁娜的生命值上限提升140%。', '万众狂欢持续期间，芙宁娜通过队伍中附近角色的当前生命值提升或降低的方式获得的「气氛值」提升250%。基于「气氛值」超过上限的部分，每1点「气氛值」都将使芙宁娜的生命值上限提升0.35%。至多通过这种方式使芙宁娜的生命值上限提升140%。');
INSERT INTO `genshin_constellation` VALUES (213, 8901, '芙宁娜', 3, '「秘密藏心间，无人知我名。」', '<color=#FFD780FF>万众狂欢的技能等级提高3级。\r\n至多提升至15级。', '万众狂欢的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (214, 8901, '芙宁娜', 4, '「若非处幽冥，怎知生可贵！」', '<color=#FFD780FF>孤心沙龙的「沙龙成员」命中敌人，或「众水的歌者」为周围的当前场上角色恢复生命值时，芙宁娜获得4点元素能量，该效果每5秒至多触发一次。', '孤心沙龙的「沙龙成员」命中敌人，或「众水的歌者」为周围的当前场上角色恢复生命值时，芙宁娜获得4点元素能量，该效果每5秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (215, 8901, '芙宁娜', 5, '「我已有觉察，他名即是…！」', '<color=#FFD780FF>孤心沙龙的技能等级提高3级。\r\n至多提升至15级。', '孤心沙龙的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (216, 8901, '芙宁娜', 6, '「诸君听我颂，共举爱之杯！」', '施放<color=#FFD780FF>孤心沙龙时，芙宁娜将获得「万众瞩目」，持续10秒。\r\n持续期间，芙宁娜的普通攻击、重击与下落攻击将转为无法被附魔覆盖的<color=#80C0FFFF>水元素伤害，且造成的伤害提升，提升值相当于芙宁娜生命值上限的18%。\r\n持续期间，每0.1秒，芙宁娜的普通攻击（不包括「始基力：圣俗杂座」的攻击）、重击与下落攻击坠地冲击命中敌人后，将根据芙宁娜当前的始基力属性产生不同的效果：\r\n\r\n始基力：荒性\r\n每1秒，基于芙宁娜生命值上限的4%，为附近的队伍中所有角色恢复生命值，持续2.9秒，重复触发将延长持续时间。\r\n始基力：芒性\r\n本次普通攻击（不包括「始基力：圣俗杂座」的攻击）、重击与下落攻击坠地冲击造成的伤害进一步提高，提升值相当于芙宁娜生命值上限的25%，上述攻击命中敌人时，附近的队伍中所有角色将消耗相当于当前生命值1%的生命值。\r\n\r\n一次「万众瞩目」持续期间，上述效果至多触发6次，该效果将在触发次数达到6次或持续时间结束时解除。', '施放孤心沙龙时，芙宁娜将获得「万众瞩目」，持续10秒。\r\n持续期间，芙宁娜的普通攻击、重击与下落攻击将转为无法被附魔覆盖的水元素伤害，且造成的伤害提升，提升值相当于芙宁娜生命值上限的18%。\r\n持续期间，每0.1秒，芙宁娜的普通攻击（不包括「始基力：圣俗杂座」的攻击）、重击与下落攻击坠地冲击命中敌人后，将根据芙宁娜当前的始基力属性产生不同的效果：\r\n\r\n始基力：荒性\r\n每1秒，基于芙宁娜生命值上限的4%，为附近的队伍中所有角色恢复生命值，持续2.9秒，重复触发将延长持续时间。\r\n始基力：芒性\r\n本次普通攻击（不包括「始基力：圣俗杂座」的攻击）、重击与下落攻击坠地冲击造成的伤害进一步提高，提升值相当于芙宁娜生命值上限的25%，上述攻击命中敌人时，附近的队伍中所有角色将消耗相当于当前生命值1%的生命值。\r\n\r\n一次「万众瞩目」持续期间，上述效果至多触发6次，该效果将在触发次数达到6次或持续时间结束时解除。');
INSERT INTO `genshin_constellation` VALUES (217, 9201, '嘉明', 1, '通明庇佑', '<color=#FFD780FF>璨焰金猊舞的猊兽·文仔成功与嘉明会合时，将为嘉明恢复15%生命值。', '璨焰金猊舞的猊兽·文仔成功与嘉明会合时，将为嘉明恢复15%生命值。');
INSERT INTO `genshin_constellation` VALUES (218, 9201, '嘉明', 2, '步踏梅花', '嘉明受到治疗时，若此次治疗回复量溢出，嘉明的攻击力将提升20%，持续5秒。', '嘉明受到治疗时，若此次治疗回复量溢出，嘉明的攻击力将提升20%，持续5秒。');
INSERT INTO `genshin_constellation` VALUES (219, 9201, '嘉明', 3, '醒灵擂震', '<color=#FFD780FF>瑞兽登高楼的技能等级提高3级。\r\n至多提升至15级。', '瑞兽登高楼的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (220, 9201, '嘉明', 4, '云里翻山', '<color=#FFD780FF>瑞兽登高楼的下落攻击·踏云献瑞命中敌人时，将为嘉明恢复2点元素能量。该效果每0.2秒至多触发一次。', '瑞兽登高楼的下落攻击·踏云献瑞命中敌人时，将为嘉明恢复2点元素能量。该效果每0.2秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (221, 9201, '嘉明', 5, '吼法怖魔', '<color=#FFD780FF>璨焰金猊舞的技能等级提高3级。\r\n至多提升至15级。', '璨焰金猊舞的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (222, 9201, '嘉明', 6, '百兽俱驯', '<color=#FFD780FF>瑞兽登高楼的下落攻击·踏云献瑞的暴击率提升20%，暴击伤害提升40%，攻击范围提升。', '瑞兽登高楼的下落攻击·踏云献瑞的暴击率提升20%，暴击伤害提升40%，攻击范围提升。');
INSERT INTO `genshin_constellation` VALUES (223, 3701, '甘雨', 1, '饮露', '二段蓄力重击的霜华矢或霜华绽发命中敌人时，会使敌人的<color=#99FFFFFF>冰元素抗性降低15%，持续6秒；\r\n此外，命中时会为甘雨恢复2点元素能量。每次二段蓄力重击只能触发一次元素能量恢复效果，无论霜华矢或霜华绽发是否都命中目标。', '二段蓄力重击的霜华矢或霜华绽发命中敌人时，会使敌人的冰元素抗性降低15%，持续6秒；\r\n此外，命中时会为甘雨恢复2点元素能量。每次二段蓄力重击只能触发一次元素能量恢复效果，无论霜华矢或霜华绽发是否都命中目标。');
INSERT INTO `genshin_constellation` VALUES (224, 3701, '甘雨', 2, '获麟', '<color=#FFD780FF>山泽麟迹的可使用次数增加1次。', '山泽麟迹的可使用次数增加1次。');
INSERT INTO `genshin_constellation` VALUES (225, 3701, '甘雨', 3, '云行', '<color=#FFD780FF>降众天华的技能等级提高3级。\r\n至多提升至15级。', '降众天华的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (226, 3701, '甘雨', 4, '西狩', '在<color=#FFD780FF>降众天华的领域内，敌人受到的伤害会增加，这个效果会随时间逐步加强。\r\n受伤害加成初始为5%，每3秒提升5%，至多提升至25%。\r\n离开领域后，效果至多持续3秒。', '在降众天华的领域内，敌人受到的伤害会增加，这个效果会随时间逐步加强。\r\n受伤害加成初始为5%，每3秒提升5%，至多提升至25%。\r\n离开领域后，效果至多持续3秒。');
INSERT INTO `genshin_constellation` VALUES (227, 3701, '甘雨', 5, '折草', '<color=#FFD780FF>山泽麟迹的技能等级提高3级。\r\n至多提升至15级。', '山泽麟迹的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (228, 3701, '甘雨', 6, '履虫', '施放<color=#FFD780FF>山泽麟迹后30秒内的第一次霜华矢，无需蓄力即可施放。', '施放山泽麟迹后30秒内的第一次霜华矢，无需蓄力即可施放。');
INSERT INTO `genshin_constellation` VALUES (229, 5501, '五郎', 1, '犬奔·疾如风', '处于五郎自己的<color=#FFD780FF>大将旗指物或<color=#FFD780FF>大将威仪领域中的当前场上角色（除了五郎自己）对敌人造成岩元素伤害后，五郎自己的<color=#FFD780FF>犬坂吠吠方圆阵冷却时间减少2秒。\r\n该效果每10秒至多触发一次。', '处于五郎自己的大将旗指物或大将威仪领域中的当前场上角色（除了五郎自己）对敌人造成岩元素伤害后，五郎自己的犬坂吠吠方圆阵冷却时间减少2秒。\r\n该效果每10秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (230, 5501, '五郎', 2, '犬坐·稳如钟', '在<color=#FFD780FF>大将威仪的持续期间，附近的当前场上角色获取结晶反应产生的晶片或触发月结晶反应后，五郎自己的大将威仪的持续时间延长1秒。\r\n该效果每0.1秒至多触发一次，至多通过这种方式延长3秒持续时间。', '在大将威仪的持续期间，附近的当前场上角色获取结晶反应产生的晶片或触发月结晶反应后，五郎自己的大将威仪的持续时间延长1秒。\r\n该效果每0.1秒至多触发一次，至多通过这种方式延长3秒持续时间。');
INSERT INTO `genshin_constellation` VALUES (231, 5501, '五郎', 3, '犬爪·势如火', '<color=#FFD780FF>犬坂吠吠方圆阵的技能等级提高3级。\r\n至多提升至15级。', '犬坂吠吠方圆阵的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (232, 5501, '五郎', 4, '犬舐·温如水', '<color=#FFD780FF>大将威仪在具有「难破」或「摧碎」的效果时，每1.5秒，为领域内的当前场上角色恢复生命值，回复量相当于五郎自己防御力的50%。', '大将威仪在具有「难破」或「摧碎」的效果时，每1.5秒，为领域内的当前场上角色恢复生命值，回复量相当于五郎自己防御力的50%。');
INSERT INTO `genshin_constellation` VALUES (233, 5501, '五郎', 5, '犬突·动如雷', '<color=#FFD780FF>兽牙逐突形胜战法的技能等级提高3级。\r\n至多提升至15级。', '兽牙逐突形胜战法的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (234, 5501, '五郎', 6, '犬勇·忠如山', '施放<color=#FFD780FF>犬坂吠吠方圆阵或<color=#FFD780FF>兽牙逐突形胜战法后的12秒内，依据施放时的领域等级，提高附近的队伍中所有角色<color=#FFE699FF>岩元素伤害的暴击伤害：\r\n·「坚牢」：提高10%；\r\n·「难破」：提高20%；\r\n·「摧碎」：提高40%。\r\n\r\n该效果无法叠加，以后生效的为准。', '施放犬坂吠吠方圆阵或兽牙逐突形胜战法后的12秒内，依据施放时的领域等级，提高附近的队伍中所有角色岩元素伤害的暴击伤害：\r\n·「坚牢」：提高10%；\r\n·「难破」：提高20%；\r\n·「摧碎」：提高40%。\r\n\r\n该效果无法叠加，以后生效的为准。');
INSERT INTO `genshin_constellation` VALUES (235, 4601, '胡桃', 1, '赤团开时斜飞去', '处于<color=#FFD780FF>蝶引来生施加的<color=#FFD780FF>彼岸蝶舞状态下时，胡桃的重击不会消耗体力。', '处于蝶引来生施加的彼岸蝶舞状态下时，胡桃的重击不会消耗体力。');
INSERT INTO `genshin_constellation` VALUES (236, 4601, '胡桃', 2, '最不安神晴又复雨', '<color=#FFD780FF>血梅香造成的伤害提高，提高值相当于效果附加时胡桃生命值上限的10%。\r\n此外，<color=#FFD780FF>安神秘法会为命中的敌人施加<color=#FFD780FF>血梅香效果。', '血梅香造成的伤害提高，提高值相当于效果附加时胡桃生命值上限的10%。\r\n此外，安神秘法会为命中的敌人施加血梅香效果。');
INSERT INTO `genshin_constellation` VALUES (237, 4601, '胡桃', 3, '逗留采血色', '<color=#FFD780FF>蝶引来生的技能等级提升3级。\r\n至多提升至15级。', '蝶引来生的技能等级提升3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (238, 4601, '胡桃', 4, '伴君眠花房', '处于胡桃自己施加的<color=#FFD780FF>血梅香状态影响下的敌人被击败时，附近的队伍中所有角色（不包括胡桃自己）的暴击率提高12%，持续15秒。', '处于胡桃自己施加的血梅香状态影响下的敌人被击败时，附近的队伍中所有角色（不包括胡桃自己）的暴击率提高12%，持续15秒。');
INSERT INTO `genshin_constellation` VALUES (239, 4601, '胡桃', 5, '无可奈何燃花作香', '<color=#FFD780FF>安神秘法的技能等级提升3级。\r\n至多提升至15级。', '安神秘法的技能等级提升3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (240, 4601, '胡桃', 6, '幽蝶能留一缕芳', '胡桃的生命值降至25%以下，或承受足以使她倒下的伤害时触发：\r\n此次伤害不会使胡桃倒下，并在接下来的10秒内，胡桃的所有元素抗性和物理抗性提高200%，暴击率提高100%，并极大地提高抗打断能力。\r\n这个效果在胡桃生命值为1时会自动触发。\r\n该效果每60秒只能触发一次。', '胡桃的生命值降至25%以下，或承受足以使她倒下的伤害时触发：\r\n此次伤害不会使胡桃倒下，并在接下来的10秒内，胡桃的所有元素抗性和物理抗性提高200%，暴击率提高100%，并极大地提高抗打断能力。\r\n这个效果在胡桃生命值为1时会自动触发。\r\n该效果每60秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (241, 11001, '伊安珊', 1, '万事从来开头难', '在战斗中，伊安珊处于夜魂加持状态下时，每消耗6点夜魂值，将为伊安珊自己恢复15点元素能量，该效果每18秒至多触发一次。', '在战斗中，伊安珊处于夜魂加持状态下时，每消耗6点夜魂值，将为伊安珊自己恢复15点元素能量，该效果每18秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (242, 11001, '伊安珊', 2, '偷懒是健身大忌!', '施放元素爆发<color=#FFD780FF>力的三原理时，伊安珊也会获得突破天赋「强化抗阻练习」中的「标准动作」效果，持续15秒；此外，「标准动作」效果持续期间，若伊安珊处于队伍后台，还会使队伍中自己的当前场上角色的攻击力提升30%。该效果需要解锁突破天赋「强化抗阻练习」。', '施放元素爆发力的三原理时，伊安珊也会获得突破天赋「强化抗阻练习」中的「标准动作」效果，持续15秒；此外，「标准动作」效果持续期间，若伊安珊处于队伍后台，还会使队伍中自己的当前场上角色的攻击力提升30%。该效果需要解锁突破天赋「强化抗阻练习」。');
INSERT INTO `genshin_constellation` VALUES (243, 11001, '伊安珊', 3, '科学的饮食规划', '元素战技<color=#FFD780FF>电掣雷驰的技能等级提高3级。\r\n至多提升至15级。', '元素战技电掣雷驰的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (244, 11001, '伊安珊', 4, '循序渐进是关键', '动能标示存在期间，除伊安珊外的队伍中自己的当前场上角色施放元素爆发后，伊安珊将获得两层「原力激扬」，持续至动能标示退场，每次召唤动能标示至多触发一次该效果；伊安珊通过动能标示恢复夜魂值时，将消耗一层「原力激扬」，为伊安珊额外恢复4点夜魂值。\r\n此外，若动能标示的夜魂值恢复量溢出，伊安珊下一次通过动能标示恢复夜魂值时，还会额外恢复相当于本次溢出量50%的夜魂值。', '动能标示存在期间，除伊安珊外的队伍中自己的当前场上角色施放元素爆发后，伊安珊将获得两层「原力激扬」，持续至动能标示退场，每次召唤动能标示至多触发一次该效果；伊安珊通过动能标示恢复夜魂值时，将消耗一层「原力激扬」，为伊安珊额外恢复4点夜魂值。\r\n此外，若动能标示的夜魂值恢复量溢出，伊安珊下一次通过动能标示恢复夜魂值时，还会额外恢复相当于本次溢出量50%的夜魂值。');
INSERT INTO `genshin_constellation` VALUES (245, 11001, '伊安珊', 5, '还没有到极限呢！', '元素爆发<color=#FFD780FF>力的三原理的技能等级提高3级。\r\n至多提升至15级。', '元素爆发力的三原理的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (246, 11001, '伊安珊', 6, '「沃陆之邦」的训教', '动能标示的持续时间延长3秒。\r\n此外，伊安珊触发恢复夜魂值的效果时，若夜魂值恢复量溢出，将获得「极限发力」效果，使队伍中自己的当前场上角色造成的伤害提升25%，持续3秒。', '动能标示的持续时间延长3秒。\r\n此外，伊安珊触发恢复夜魂值的效果时，若夜魂值恢复量溢出，将获得「极限发力」效果，使队伍中自己的当前场上角色造成的伤害提升25%，持续3秒。');
INSERT INTO `genshin_constellation` VALUES (247, 11301, '伊法', 1, '藤典药剂的备制', '<color=#FFD780FF>「援护射击」命中敌人时，将为伊法恢复6点元素能量。每8秒至多通过这种方式恢复一次元素能量。', '**「援护射击」**命中敌人时，将为伊法恢复6点元素能量。每8秒至多通过这种方式恢复一次元素能量。');
INSERT INTO `genshin_constellation` VALUES (248, 11301, '伊法', 2, '祈祷弹道的助灵', '伊法处于夜魂加持状态下时，基于队伍中所有角色当前夜魂值的总和超过60点的部分，每1点夜魂值都将使伊法额外获得4点<color=#FFD780FF>「救援要义」。\r\n此外，伊法持有「救援要义」的上限提升50点。\r\n需要解锁突破天赋<color=#FFD780FF>场中医者视野。', '伊法处于夜魂加持状态下时，基于队伍中所有角色当前夜魂值的总和超过60点的部分，每1点夜魂值都将使伊法额外获得4点**「救援要义」**。\r\n此外，伊法持有「救援要义」的上限提升50点。\r\n需要解锁突破天赋**场中医者视野**。');
INSERT INTO `genshin_constellation` VALUES (249, 11301, '伊法', 3, '与夜谈判的驳词', '元素战技<color=#FFD780FF>空天疾护的技能等级提高3级。\r\n至多提升至15级。', '元素战技**空天疾护**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (250, 11301, '伊法', 4, '糜烂应体的置换', '元素爆发<color=#FFD780FF>复合镇静域产生的固缚风场的持续时间延长至3秒。\r\n此外，施放元素爆发<color=#FFD780FF>复合镇静域后，伊法的元素精通提升100点，持续15秒。', '元素爆发**复合镇静域**产生的固缚风场的持续时间延长至3秒。\r\n此外，施放元素爆发复合镇静域后，伊法的元素精通提升100点，持续15秒。');
INSERT INTO `genshin_constellation` VALUES (251, 11301, '伊法', 5, '万物同生的共誓', '元素爆发<color=#FFD780FF>复合镇静域的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**复合镇静域**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (252, 11301, '伊法', 6, '羽结所庇的诺言', '伊法长按进行<color=#FFD780FF>「援护射击」时，有50%几率发射一枚额外的秘药弹，造成相当于伊法攻击力120%的风元素伤害。该伤害视为普通攻击伤害。\r\n此外，不处于战斗状态下时，伊法的夜魂加持状态消耗的夜魂值与燃素降低20%。', '伊法长按进行**「援护射击」**时，有50%几率发射一枚额外的秘药弹，造成相当于伊法攻击力120%的风元素伤害。该伤害视为普通攻击伤害。\r\n此外，不处于战斗状态下时，伊法的夜魂加持状态消耗的夜魂值与燃素降低20%。');
INSERT INTO `genshin_constellation` VALUES (253, 12701, '叶洛亚', 1, '告警之雉', '叶洛亚在场上触发<color=#FFE699FF>岩元素相关反应后，将为叶洛亚恢复12点元素能量，该效果每15秒至多触发一次。', '叶洛亚在场上触发岩元素相关反应后，将为叶洛亚恢复12点元素能量，该效果每15秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (254, 12701, '叶洛亚', 2, '噬枝之麋', '元素爆发<color=#FFD780FF>鉴照无影中的「魇夜的莺歌」效果持续期间，每消耗7层<color=#FFD780FF>「夜莺之歌」，叶洛亚都将唤出阿咚，对周围一名敌人造成一次<color=#FFE699FF>岩元素伤害，伤害值基于叶洛亚元素精通的400%与防御力的200%，该伤害视为元素爆发伤害。', '元素爆发**鉴照无影**中的「魇夜的莺歌」效果持续期间，每消耗7层**「夜莺之歌」**，叶洛亚都将唤出阿咚，对周围一名敌人造成一次岩元素伤害，伤害值基于叶洛亚元素精通的400%与防御力的200%，该伤害视为元素爆发伤害。');
INSERT INTO `genshin_constellation` VALUES (255, 12701, '叶洛亚', 3, '山吼之罴', '元素爆发<color=#FFD780FF>鉴照无影的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**鉴照无影**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (256, 12701, '叶洛亚', 4, '逐日之狼', '元素爆发<color=#FFD780FF>鉴照无影中的「魇夜的莺歌」效果持续期间，队伍中附近的当前场上角色防御力提升200点。', '元素爆发**鉴照无影**中的「魇夜的莺歌」效果持续期间，队伍中附近的当前场上角色防御力提升200点。');
INSERT INTO `genshin_constellation` VALUES (257, 12701, '叶洛亚', 5, '啸风之马', '元素战技<color=#FFD780FF>衔莺破晓的技能等级提高3级。\r\n至多提升至15级。', '元素战技**衔莺破晓**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (258, 12701, '叶洛亚', 6, '魇夜之莺', '突破天赋<color=#FFD780FF>铸灯者的盟约中「执灯之誓」的效果获得强化：对敌人造成的<color=#FFE699FF>岩元素伤害，暴击率提升10%，暴击伤害提升30%。\r\n\r\n<color=#FFD780FF>月兆·满辉 \r\n处于「执灯之誓」效果影响下的角色，元素精通提升80点。\r\n需要解锁突破天赋<color=#FFD780FF>铸灯者的盟约。', '突破天赋**铸灯者的盟约**中「执灯之誓」的效果获得强化：对敌人造成的岩元素伤害，暴击率提升10%，暴击伤害提升30%。\r\n\r\n月兆·满辉 \r\n处于「执灯之誓」效果影响下的角色，元素精通提升80点。\r\n需要解锁突破天赋铸灯者的盟约。');
INSERT INTO `genshin_constellation` VALUES (259, 11601, '伊涅芙', 1, '循环整流引擎', '伊涅芙展开光流屏障护盾时，将为队伍中附近的所有角色赋予持续20秒的「载流复合」效果，使月感电反应造成的伤害提升，提升值基于伊涅芙的攻击力：每100点攻击力都将提升2.5%伤害，至多通过这种方式提升50%伤害。', '伊涅芙展开光流屏障护盾时，将为队伍中附近的所有角色赋予持续20秒的「载流复合」效果，使月感电反应造成的伤害提升，提升值基于伊涅芙的攻击力：每100点攻击力都将提升2.5%伤害，至多通过这种方式提升50%伤害。');
INSERT INTO `genshin_constellation` VALUES (260, 11601, '伊涅芙', 2, '辅助清理模块', '元素爆发<color=#FFD780FF>至高律令·全域扫灭命中敌人后，将为其中一名敌人施加「惩戒敕谕」状态：短暂间隔后，或该敌人被击败时，将对其周围的敌人造成相当于伊涅芙攻击力300%的<color=#FFACFFFF>雷元素范围伤害，该伤害视为月感电反应造成的伤害。\r\n此外，施放元素爆发<color=#FFD780FF>至高律令·全域扫灭时，也会为附近的当前场上角色赋予光流屏障护盾。', '元素爆发**至高律令·全域扫灭**命中敌人后，将为其中一名敌人施加「惩戒敕谕」状态：短暂间隔后，或该敌人被击败时，将对其周围的敌人造成相当于伊涅芙攻击力300%的雷元素范围伤害，该伤害视为月感电反应造成的伤害。\r\n此外，施放元素爆发至高律令·全域扫灭时，也会为附近的当前场上角色赋予光流屏障护盾。');
INSERT INTO `genshin_constellation` VALUES (261, 11601, '伊涅芙', 3, '高阶情感固件', '元素战技<color=#FFD780FF>涤净模式·稳态载频的技能等级提高3级。\r\n至多提升至15级。', '元素战技**涤净模式·稳态载频**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (262, 11601, '伊涅芙', 4, '敕谕未至之路', '队伍中自己的角色触发月感电反应时，将恢复5点元素能量，该效果每4秒至多触发一次。', '队伍中自己的角色触发月感电反应时，将恢复5点元素能量，该效果每4秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (263, 11601, '伊涅芙', 5, '超越镜影之梦', '元素爆发<color=#FFD780FF>至高律令·全域扫灭的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**至高律令·全域扫灭**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (264, 11601, '伊涅芙', 6, '献予你的明晨', '伊涅芙处于「载流复合」效果影响下时，附近的雷暴云对敌人进行雷击后，伊涅芙将对当前场上自己的角色周围的敌人造成相当于伊涅芙攻击力135%的<color=#FFACFFFF>雷元素范围伤害，该伤害视为月感电反应造成的伤害，上述效果每3.5秒至多触发一次。', '伊涅芙处于「载流复合」效果影响下时，附近的雷暴云对敌人进行雷击后，伊涅芙将对当前场上自己的角色周围的敌人造成相当于伊涅芙攻击力135%的雷元素范围伤害，该伤害视为月感电反应造成的伤害，上述效果每3.5秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (265, 12401, '雅珂达', 1, '再来一瓶！', '元素战技<color=#FFD780FF>奇策·财富分配方案中，<color=#FFD780FF>呼噜噜秘藏瓶发射的<color=#FFD780FF>软绒绒猫猫球命中敌人时，有50%的概率进行一次弹跳，对附近的敌人造成对应元素伤害。', '元素战技奇策·财富分配方案中，**呼噜噜秘藏瓶**发射的软绒绒猫猫球命中敌人时，有50%的概率进行一次弹跳，对附近的敌人造成对应元素伤害。');
INSERT INTO `genshin_constellation` VALUES (266, 12401, '雅珂达', 2, '律贼的临机应变', '<color=#FFD780FF>月兆·满辉：突破天赋<color=#FFD780FF>「索酬的巧计」中，除角色数量最多的元素类型外，雅珂达还可以偷偷记录剩余元素类型中角色数量最多的元素类型，并使至多两种元素类型对应的效果生效。该效果需要解锁突破天赋「索酬的巧计」。', '月兆·满辉：突破天赋**「索酬的巧计」**中，除角色数量最多的元素类型外，雅珂达还可以偷偷记录剩余元素类型中角色数量最多的元素类型，并使至多两种元素类型对应的效果生效。该效果需要解锁突破天赋「索酬的巧计」。');
INSERT INTO `genshin_constellation` VALUES (267, 12401, '雅珂达', 3, '无所依归的豪赌', '元素爆发<color=#FFD780FF>秘器·猎人的七道具的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**秘器·猎人的七道具**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (268, 12401, '雅珂达', 4, '尘沙之上的野莓', '元素爆发<color=#FFD780FF>秘器·猎人的七道具中的<color=#FFD780FF>猫型家用互助协调器发生元素转化时，将会为雅珂达回复4点元素能量。', '元素爆发秘器·猎人的七道具中的**猫型家用互助协调器**发生元素转化时，将会为雅珂达回复4点元素能量。');
INSERT INTO `genshin_constellation` VALUES (269, 12401, '雅珂达', 5, '最伟大的财宝', '元素战技<color=#FFD780FF>奇策·财富分配方案的技能等级提高3级。\r\n至多提升至15级。', '元素战技**奇策·财富分配方案**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (270, 12401, '雅珂达', 6, '最渺小的幸运', '<color=#FFD780FF>月兆·满辉：元素战技<color=#FFD780FF>奇策·财富分配方案中的<color=#FFD780FF>呼噜噜秘藏瓶装满后的20秒内，队伍中附近的月兆角色的暴击率提升5%，暴击伤害提升40%。', '月兆·满辉：元素战技奇策·财富分配方案中的**呼噜噜秘藏瓶**装满后的20秒内，队伍中附近的月兆角色的暴击率提升5%，暴击伤害提升40%。');
INSERT INTO `genshin_constellation` VALUES (271, 301, '琴', 1, '流转剑脊的暴风', '<color=#FFD780FF>风压剑长按超过1秒后，提升牵引速度，并使造成的伤害提升40%。', '风压剑长按超过1秒后，提升牵引速度，并使造成的伤害提升40%。');
INSERT INTO `genshin_constellation` VALUES (272, 301, '琴', 2, '守护众人的坚盾', '琴获得元素晶球或元素微粒时，队伍中所有角色获得15%攻击速度和15%移动速度提升，持续15秒。', '琴获得元素晶球或元素微粒时，队伍中所有角色获得15%攻击速度和15%移动速度提升，持续15秒。');
INSERT INTO `genshin_constellation` VALUES (273, 301, '琴', 3, '西风吹拂之时', '<color=#FFD780FF>蒲公英之风的技能等级提高3级。\r\n至多提升至15级。', '蒲公英之风的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (274, 301, '琴', 4, '蒲公英的国土', '在<color=#FFD780FF>蒲公英之风的领域内，所有敌人的<color=#80FFD7FF>风元素抗性下降40%。', '在蒲公英之风的领域内，所有敌人的风元素抗性下降40%。');
INSERT INTO `genshin_constellation` VALUES (275, 301, '琴', 5, '须臾一瞬的烈风', '<color=#FFD780FF>风压剑的技能等级提高3级。\r\n至多提升至15级。', '风压剑的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (276, 301, '琴', 6, '恩眷万民的狮牙', '在<color=#FFD780FF>蒲公英之风的领域内，角色受到的伤害降低35%。\r\n离开领域后，这个效果会在承受3次攻击或10秒后消失。', '在蒲公英之风的领域内，角色受到的伤害降低35%。\r\n离开领域后，这个效果会在承受3次攻击或10秒后消失。');
INSERT INTO `genshin_constellation` VALUES (277, 10001, '卡齐娜', 1, '晶片，也是一种宝石', '卡齐娜搭乘或脱离<color=#FFD780FF>冲天转转时，将获取附近的结晶反应产生的晶片。\r\n此外，队伍中的角色获取晶片或触发月结晶反应时，将为卡齐娜恢复3点元素能量，每5秒至多通过这种方式恢复一次元素能量。', '卡齐娜搭乘或脱离冲天转转时，将获取附近的结晶反应产生的晶片。\r\n此外，队伍中的角色获取晶片或触发月结晶反应时，将为卡齐娜恢复3点元素能量，每5秒至多通过这种方式恢复一次元素能量。');
INSERT INTO `genshin_constellation` VALUES (278, 10001, '卡齐娜', 2, '不能少了…冲天转转', '卡齐娜施放<color=#FFD780FF>现在，认真时间！时，将恢复20点夜魂值；若施放时场上没有卡齐娜自己的<color=#FFD780FF>冲天转转，则进入夜魂加持状态并召唤冲天转转。', '卡齐娜施放现在，认真时间！时，将恢复20点夜魂值；若施放时场上没有卡齐娜自己的冲天转转，则进入夜魂加持状态并召唤冲天转转。');
INSERT INTO `genshin_constellation` VALUES (279, 10001, '卡齐娜', 3, '改良型·平衡稳定器', '<color=#FFD780FF>出击，冲天转转！的技能等级提高3级。\r\n至多提升至15级。', '出击，冲天转转！的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (280, 10001, '卡齐娜', 4, '敌人越多，越要小心', '<color=#FFD780FF>现在，认真时间！的超级钻钻领域中，存在的敌人数量为1/2/3/4名或更多时，领域中的队伍中当前场上角色的防御力提升8%/12%/16%/20%。', '现在，认真时间！的超级钻钻领域中，存在的敌人数量为1/2/3/4名或更多时，领域中的队伍中当前场上角色的防御力提升8%/12%/16%/20%。');
INSERT INTO `genshin_constellation` VALUES (281, 10001, '卡齐娜', 5, '迄今为止，所有收藏', '<color=#FFD780FF>现在，认真时间！的技能等级提高3级。\r\n至多提升至15级。', '现在，认真时间！的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (282, 10001, '卡齐娜', 6, '这一次，我一定要赢', '队伍中自己的当前场上角色的护盾因任何原因被替换或摧毁时，卡齐娜将造成相当于她的防御力200%的<color=#FFE699FF>岩元素范围伤害，该效果5秒内至多触发一次。', '队伍中自己的当前场上角色的护盾因任何原因被替换或摧毁时，卡齐娜将造成相当于她的防御力200%的岩元素范围伤害，该效果5秒内至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (283, 4701, '枫原万叶', 1, '千山红遍', '<color=#FFD780FF>千早振的冷却时间减少10%。\r\n施放<color=#FFD780FF>万叶之一刀时，重置<color=#FFD780FF>千早振的冷却时间。', '千早振的冷却时间减少10%。\r\n施放万叶之一刀时，重置千早振的冷却时间。');
INSERT INTO `genshin_constellation` VALUES (284, 4701, '枫原万叶', 2, '山岚残芯', '<color=#FFD780FF>万叶之一刀的流风秋野具有以下效果：\r\n·持续期间内，枫原万叶自己的元素精通提升200点；\r\n·其中的场上角色的元素精通提升200点。\r\n\r\n该命之座提供的元素精通提升效果无法叠加。', '万叶之一刀的流风秋野具有以下效果：\r\n·持续期间内，枫原万叶自己的元素精通提升200点；\r\n·其中的场上角色的元素精通提升200点。\r\n\r\n该命之座提供的元素精通提升效果无法叠加。');
INSERT INTO `genshin_constellation` VALUES (285, 4701, '枫原万叶', 3, '枫袖奇谭', '<color=#FFD780FF>千早振的技能等级提高3级。\r\n至多提升至15级。', '千早振的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (286, 4701, '枫原万叶', 4, '大空幻法', '当枫原万叶的元素能量低于45点时，具有如下效果：\r\n·点按、长按施放<color=#FFD780FF>千早振时，将分别为枫原万叶恢复3、4点元素能量；\r\n·处于滑翔状态下时，每秒为枫原万叶恢复2点元素能量。', '当枫原万叶的元素能量低于45点时，具有如下效果：\r\n·点按、长按施放千早振时，将分别为枫原万叶恢复3、4点元素能量；\r\n·处于滑翔状态下时，每秒为枫原万叶恢复2点元素能量。');
INSERT INTO `genshin_constellation` VALUES (287, 4701, '枫原万叶', 5, '万世之集', '<color=#FFD780FF>万叶之一刀的技能等级提高3级。\r\n至多提升至15级。', '万叶之一刀的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (288, 4701, '枫原万叶', 6, '血赤叶红', '枫原万叶施放<color=#FFD780FF>千早振或<color=#FFD780FF>万叶之一刀后的5秒内，获得<color=#80FFD7FF>风元素附魔，并且枫原万叶的每点元素精通，都会使他的普通攻击、重击、下落攻击造成的伤害提高0.2%。', '枫原万叶施放千早振或万叶之一刀后的5秒内，获得风元素附魔，并且枫原万叶的每点元素精通，都会使他的普通攻击、重击、下落攻击造成的伤害提高0.2%。');
INSERT INTO `genshin_constellation` VALUES (289, 1501, '凯亚', 1, '卓越的血脉', '对受到<color=#99FFFFFF>冰元素影响的敌人，凯亚的普通攻击与重击暴击率提升15%。', '对受到冰元素影响的敌人，凯亚的普通攻击与重击暴击率提升15%。');
INSERT INTO `genshin_constellation` VALUES (290, 1501, '凯亚', 2, '无尽的霜舞', '在<color=#FFD780FF>凛冽轮舞的持续时间内击败敌人时，持续时间延长2.5秒，最多不会超过15秒。', '在凛冽轮舞的持续时间内击败敌人时，持续时间延长2.5秒，最多不会超过15秒。');
INSERT INTO `genshin_constellation` VALUES (291, 1501, '凯亚', 3, '凛冽的冰戏', '<color=#FFD780FF>霜袭的技能等级提高3级。\r\n至多提升至15级。', '霜袭的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (292, 1501, '凯亚', 4, '极寒的轻吻', '凯亚的生命值低于20%时自动触发：\r\n生成一个伤害吸收量等于生命值上限30%的护盾，持续20秒。\r\n该护盾对<color=#99FFFFFF>冰元素伤害有250%的吸收效果。\r\n该效果每60秒只能触发一次。', '凯亚的生命值低于20%时自动触发：\r\n生成一个伤害吸收量等于生命值上限30%的护盾，持续20秒。\r\n该护盾对冰元素伤害有250%的吸收效果。\r\n该效果每60秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (293, 1501, '凯亚', 5, '至冷的拥抱', '<color=#FFD780FF>凛冽轮舞的技能等级提高3级。\r\n至多提升至15级。', '凛冽轮舞的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (294, 1501, '凯亚', 6, '轮旋的冰凌', '<color=#FFD780FF>凛冽轮舞会产生一个额外的寒冰之棱，并在施放时返还15点元素能量。', '凛冽轮舞会产生一个额外的寒冰之棱，并在施放时返还15点元素能量。');
INSERT INTO `genshin_constellation` VALUES (295, 201, '神里绫华', 1, '霜杀墨染樱', '神里绫华的普通攻击或重击对敌人造成<color=#99FFFFFF>冰元素伤害时，有50%的几率使<color=#FFD780FF>神里流·冰华的冷却时间缩减0.3秒。该效果每0.1秒只能触发一次。', '神里绫华的普通攻击或重击对敌人造成冰元素伤害时，有50%的几率使神里流·冰华的冷却时间缩减0.3秒。该效果每0.1秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (296, 201, '神里绫华', 2, '三重雪关扉', '施放<color=#FFD780FF>神里流·霜灭时，会额外释放两股规模较小的霜见雪关扉，各自能造成原本20%的伤害。', '施放神里流·霜灭时，会额外释放两股规模较小的霜见雪关扉，各自能造成原本20%的伤害。');
INSERT INTO `genshin_constellation` VALUES (297, 201, '神里绫华', 3, '花白锦画纸吹雪', '<color=#FFD780FF>神里流·霜灭的技能等级提高3级。\r\n至多提升至15级。', '神里流·霜灭的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (298, 201, '神里绫华', 4, '盈缺流返', '敌人受到<color=#FFD780FF>神里流·霜灭的霜见雪关扉造成的伤害后，防御力降低30%，持续6秒。', '敌人受到神里流·霜灭的霜见雪关扉造成的伤害后，防御力降低30%，持续6秒。');
INSERT INTO `genshin_constellation` VALUES (299, 201, '神里绫华', 5, '花云钟入月', '<color=#FFD780FF>神里流·冰华的技能等级提高3级。\r\n至多提升至15级。', '神里流·冰华的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (300, 201, '神里绫华', 6, '间水月', '每过10秒，神里绫华会获得「薄冰舞踏」，使重击造成的伤害提高298%。薄冰舞踏效果将在重击命中敌人的0.5秒后清除，并重新开始计算时间。', '每过10秒，神里绫华会获得「薄冰舞踏」，使重击造成的伤害提高298%。薄冰舞踏效果将在重击命中敌人的0.5秒后清除，并重新开始计算时间。');
INSERT INTO `genshin_constellation` VALUES (301, 6601, '神里绫人', 1, '镜华风姿', '对于生命值低于或等于50%的敌人，<color=#FFD780FF>瞬水剑造成的伤害提升40%。', '对于生命值低于或等于50%的敌人，瞬水剑造成的伤害提升40%。');
INSERT INTO `genshin_constellation` VALUES (302, 6601, '神里绫人', 2, '世有源泉', '<color=#FFD780FF>浪闪叠加上限提升至5层；神里绫人处于至少3层浪闪状态下时，将提升50%生命值上限。', '浪闪叠加上限提升至5层；神里绫人处于至少3层浪闪状态下时，将提升50%生命值上限。');
INSERT INTO `genshin_constellation` VALUES (303, 6601, '神里绫人', 3, '无意弄花', '<color=#FFD780FF>神里流·镜花的技能等级提高3级。\r\n至多提升至15级。', '神里流·镜花的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (304, 6601, '神里绫人', 4, '不厌细流', '施放<color=#FFD780FF>神里流·水囿后，队伍中附近的角色普通攻击的攻击速度提升15%，持续15秒。', '施放神里流·水囿后，队伍中附近的角色普通攻击的攻击速度提升15%，持续15秒。');
INSERT INTO `genshin_constellation` VALUES (305, 6601, '神里绫人', 5, '万水一露', '<color=#FFD780FF>神里流·水囿的技能等级提高3级。\r\n至多提升至15级。', '神里流·水囿的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (306, 6601, '神里绫人', 6, '滥觞无底', '施放<color=#FFD780FF>神里流·镜花之后，神里绫人的下一次瞬水剑攻击命中敌人时，将进行2次额外的瞬水剑攻击，各自能造成神里绫人攻击力450%的伤害。\r\n此两次瞬水剑攻击不会受到浪闪的增益。', '施放神里流·镜花之后，神里绫人的下一次瞬水剑攻击命中敌人时，将进行2次额外的瞬水剑攻击，各自能造成神里绫人攻击力450%的伤害。\r\n此两次瞬水剑攻击不会受到浪闪的增益。');
INSERT INTO `genshin_constellation` VALUES (307, 8101, '卡维', 1, '高门的谒礼', '施放<color=#FFD780FF>画则巧施后的3秒内，卡维的<color=#99FF88FF>草元素抗性提升50%，受治疗加成提升25%。', '施放画则巧施后的3秒内，卡维的草元素抗性提升50%，受治疗加成提升25%。');
INSERT INTO `genshin_constellation` VALUES (308, 8101, '卡维', 2, '御驿的径迹', '在<color=#FFD780FF>繁绘隅穹持续期间，卡维普通攻击的攻击速度提升15%。', '在繁绘隅穹持续期间，卡维普通攻击的攻击速度提升15%。');
INSERT INTO `genshin_constellation` VALUES (309, 8101, '卡维', 3, '金塔的香献', '<color=#FFD780FF>繁绘隅穹的技能等级提高3级。\r\n至多提升至15级。', '繁绘隅穹的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (310, 8101, '卡维', 4, '百柱的酣宴', '卡维触发绽放或月绽放反应产生的草原核在迸发时造成的伤害提升60%。', '卡维触发绽放或月绽放反应产生的草原核在迸发时造成的伤害提升60%。');
INSERT INTO `genshin_constellation` VALUES (311, 8101, '卡维', 5, '圣古的库藏', '<color=#FFD780FF>画则巧施的技能等级提高3级。\r\n至多提升至15级。', '画则巧施的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (312, 8101, '卡维', 6, '天园的理想', '在<color=#FFD780FF>繁绘隅穹持续期间，卡维的普通攻击、重击或下落攻击命中敌人时，将在敌人的位置释放天园之光，造成卡维攻击力61.8%的<color=#99FF88FF>草元素范围伤害，并使影响范围内的所有草原核迸发。该效果每3秒最多触发一次。', '在繁绘隅穹持续期间，卡维的普通攻击、重击或下落攻击命中敌人时，将在敌人的位置释放天园之光，造成卡维攻击力61.8%的草元素范围伤害，并使影响范围内的所有草原核迸发。该效果每3秒最多触发一次。');
INSERT INTO `genshin_constellation` VALUES (313, 4201, '刻晴', 1, '雷厉', '雷楔存在期间再次施放<color=#FFD780FF>星斗归位时，在刻晴消失与出现的位置造成50%攻击力的<color=#FFACFFFF>雷元素范围伤害。', '雷楔存在期间再次施放星斗归位时，在刻晴消失与出现的位置造成50%攻击力的雷元素范围伤害。');
INSERT INTO `genshin_constellation` VALUES (314, 4201, '刻晴', 2, '苛捐', '刻晴普通攻击与重击命中受到<color=#FFACFFFF>雷元素影响的敌人时，有50%几率产生一个元素微粒。\r\n该效果每5秒只能触发一次。', '刻晴普通攻击与重击命中受到雷元素影响的敌人时，有50%几率产生一个元素微粒。\r\n该效果每5秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (315, 4201, '刻晴', 3, '登楼', '<color=#FFD780FF>天街巡游的技能等级提高3级。\r\n至多提升至15级。', '天街巡游的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (316, 4201, '刻晴', 4, '调律', '刻晴触发<color=#FFACFFFF>雷元素相关反应后的10秒内，攻击力提升25%。', '刻晴触发雷元素相关反应后的10秒内，攻击力提升25%。');
INSERT INTO `genshin_constellation` VALUES (317, 4201, '刻晴', 5, '移灯', '<color=#FFD780FF>星斗归位的技能等级提高3级。\r\n至多提升至15级。', '星斗归位的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (318, 4201, '刻晴', 6, '廉贞', '进行普通攻击、重击、施放元素战技或元素爆发时，刻晴获得6%<color=#FFACFFFF>雷元素伤害加成，持续8秒。\r\n由普通攻击、重击、元素战技或元素爆发引起的效果分别独立存在。', '进行普通攻击、重击、施放元素战技或元素爆发时，刻晴获得6%雷元素伤害加成，持续8秒。\r\n由普通攻击、重击、元素战技或元素爆发引起的效果分别独立存在。');
INSERT INTO `genshin_constellation` VALUES (319, 10101, '基尼奇', 1, '七鹦之喙', '通过<color=#FFD780FF>悬猎·游骋高狩，基尼奇进行空中摆荡落地后，移动速度提升30%，持续6秒。\r\n此外，迴猎贯鳞炮的暴击伤害提升100%。', '通过悬猎·游骋高狩，基尼奇进行空中摆荡落地后，移动速度提升30%，持续6秒。\r\n此外，迴猎贯鳞炮的暴击伤害提升100%。');
INSERT INTO `genshin_constellation` VALUES (320, 10101, '基尼奇', 2, '星虎之掌', '基尼奇的元素战技命中敌人时，将使其<color=#99FF88FF>草元素抗性降低30%，持续6秒。\r\n此外，基尼奇在进入夜魂加持状态下的首次迴猎贯鳞炮的影响范围提升，造成的伤害提升100%。', '基尼奇的元素战技命中敌人时，将使其草元素抗性降低30%，持续6秒。\r\n此外，基尼奇在进入夜魂加持状态下的首次迴猎贯鳞炮的影响范围提升，造成的伤害提升100%。');
INSERT INTO `genshin_constellation` VALUES (321, 10101, '基尼奇', 3, '原鳄之爪', '<color=#FFD780FF>悬猎·游骋高狩的技能等级提高3级。\r\n至多提升至15级。', '悬猎·游骋高狩的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (322, 10101, '基尼奇', 4, '蜂鸟之羽', '处于夜魂加持状态下时，基尼奇进行环绕射击或施放迴猎贯鳞炮后，将为他恢复5点元素能量。每2.8秒至多通过这种方式恢复一次元素能量。\r\n此外，<color=#FFD780FF>向伟大圣龙致意造成的伤害提升70%。', '处于夜魂加持状态下时，基尼奇进行环绕射击或施放迴猎贯鳞炮后，将为他恢复5点元素能量。每2.8秒至多通过这种方式恢复一次元素能量。\r\n此外，向伟大圣龙致意造成的伤害提升70%。');
INSERT INTO `genshin_constellation` VALUES (323, 10101, '基尼奇', 5, '吼猴之尾', '<color=#FFD780FF>向伟大圣龙致意的技能等级提高3级。\r\n至多提升至15级。', '向伟大圣龙致意的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (324, 10101, '基尼奇', 6, '瑞兽之形', '迴猎贯鳞炮在命中敌人后，将在敌人间弹跳一次，造成基尼奇的攻击力700%的<color=#99FF88FF>草元素伤害。\r\n如果本次迴猎贯鳞炮触发了突破天赋「焰灵的契约」或命之座「星虎之掌」对迴猎贯鳞炮的增强效果，它所引发的弹跳攻击也会获得上述效果的增强。', '迴猎贯鳞炮在命中敌人后，将在敌人间弹跳一次，造成基尼奇的攻击力700%的草元素伤害。\r\n如果本次迴猎贯鳞炮触发了突破天赋「焰灵的契约」或命之座「星虎之掌」对迴猎贯鳞炮的增强效果，它所引发的弹跳攻击也会获得上述效果的增强。');
INSERT INTO `genshin_constellation` VALUES (325, 6101, '绮良良', 1, '物器流转', '施放<color=#FFD780FF>秘法·惊喜特派时，绮良良的每8000点生命值上限都将额外生成1枚<color=#FFD780FF>猫草豆蔻，至多通过这种方式额外生成4枚猫草豆蔻。', '施放秘法·惊喜特派时，绮良良的每8000点生命值上限都将额外生成1枚猫草豆蔻，至多通过这种方式额外生成4枚猫草豆蔻。');
INSERT INTO `genshin_constellation` VALUES (326, 6101, '绮良良', 2, '八尖裹术', '绮良良处于<color=#FFD780FF>呜喵町飞足的猫箱急件状态下时，将为冲撞触及的队伍中其他角色施加安全运输护盾·要件。\r\n安全运输护盾·要件的伤害吸收量相当于<color=#FFD780FF>呜喵町飞足的安全运输护盾的吸收量上限的40%，且对<color=#99FF88FF>草元素伤害有250%的吸收效果。\r\n安全运输护盾·要件持续12秒，此效果每10秒对每位角色至多触发一次。', '绮良良处于呜喵町飞足的猫箱急件状态下时，将为冲撞触及的队伍中其他角色施加安全运输护盾·要件。\r\n安全运输护盾·要件的伤害吸收量相当于呜喵町飞足的安全运输护盾的吸收量上限的40%，且对草元素伤害有250%的吸收效果。\r\n安全运输护盾·要件持续12秒，此效果每10秒对每位角色至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (327, 6101, '绮良良', 3, '万户门牌通识', '<color=#FFD780FF>呜喵町飞足的技能等级提高3级。\r\n至多提升至15级。', '呜喵町飞足的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (328, 6101, '绮良良', 4, '韦驮骏足', '处于<color=#FFD780FF>安全运输护盾或<color=#FFD780FF>安全运输护盾·要件的当前场上角色的普通攻击、重击与下落攻击命中敌人后，绮良良将使用<color=#FFD780FF>猫草小豆蔻进行协同攻击，造成相当于绮良良攻击力200%<color=#99FF88FF>草元素伤害，通过这种方式造成的伤害视为元素爆发伤害。此效果每3.8秒至多触发一次，队伍中所有角色共享冷却时间。', '处于安全运输护盾或安全运输护盾·要件的当前场上角色的普通攻击、重击与下落攻击命中敌人后，绮良良将使用猫草小豆蔻进行协同攻击，造成相当于绮良良攻击力200%草元素伤害，通过这种方式造成的伤害视为元素爆发伤害。此效果每3.8秒至多触发一次，队伍中所有角色共享冷却时间。');
INSERT INTO `genshin_constellation` VALUES (329, 6101, '绮良良', 5, '千里一日', '<color=#FFD780FF>秘法·惊喜特派的技能等级提高3级。\r\n至多提升至15级。', '秘法·惊喜特派的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (330, 6101, '绮良良', 6, '沿途百景会心', '绮良良施放元素战技或元素爆发后的15秒内，附近的队伍中所有角色获得12%所有元素伤害加成。', '绮良良施放元素战技或元素爆发后的15秒内，附近的队伍中所有角色获得12%所有元素伤害加成。');
INSERT INTO `genshin_constellation` VALUES (331, 2901, '可莉', 1, '连环轰隆', '攻击与施放技能时，有几率召唤火花轰击敌人，造成相当于<color=#FFD780FF>轰轰火花攻击伤害120%的伤害。', '攻击与施放技能时，有几率召唤火花轰击敌人，造成相当于轰轰火花攻击伤害120%的伤害。');
INSERT INTO `genshin_constellation` VALUES (332, 2901, '可莉', 2, '破破弹片', '<color=#FFD780FF>蹦蹦炸弹的诡雷会使敌人的防御力降低23%，持续10秒。', '蹦蹦炸弹的诡雷会使敌人的防御力降低23%，持续10秒。');
INSERT INTO `genshin_constellation` VALUES (333, 2901, '可莉', 3, '可莉特调', '<color=#FFD780FF>蹦蹦炸弹的技能等级提高3级。\r\n至多提升至15级。', '蹦蹦炸弹的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (334, 2901, '可莉', 4, '一触即发', '如果在<color=#FFD780FF>轰轰火花持续期间内退场，会引发爆炸，造成555%攻击力的<color=#FF9999FF>火元素范围伤害。', '如果在轰轰火花持续期间内退场，会引发爆炸，造成555%攻击力的火元素范围伤害。');
INSERT INTO `genshin_constellation` VALUES (335, 2901, '可莉', 5, '轰击之星', '<color=#FFD780FF>轰轰火花的技能等级提高3级。\r\n至多提升至15级。', '轰轰火花的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (336, 2901, '可莉', 6, '火力全开', '在<color=#FFD780FF>轰轰火花的状态下，可莉每3秒会为队伍中所有角色（不包括可莉自己）恢复3点元素能量；\r\n施放<color=#FFD780FF>轰轰火花后的25秒内，队伍中所有角色获得10%<color=#FF9999FF>火元素伤害加成。', '在轰轰火花的状态下，可莉每3秒会为队伍中所有角色（不包括可莉自己）恢复3点元素能量；\r\n施放轰轰火花后的25秒内，队伍中所有角色获得10%火元素伤害加成。');
INSERT INTO `genshin_constellation` VALUES (337, 5601, '九条裟罗', 1, '乌眼', '天狗咒雷为角色施加攻击力提升效果或命中敌人后，<color=#FFD780FF>鸦羽天狗霆雷召咒的冷却时间减少1秒。\r\n该效果每3秒至多触发一次。', '天狗咒雷为角色施加攻击力提升效果或命中敌人后，鸦羽天狗霆雷召咒的冷却时间减少1秒。\r\n该效果每3秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (338, 5601, '九条裟罗', 2, '鸦羽', '施放<color=#FFD780FF>鸦羽天狗霆雷召咒时，会在九条裟罗原本的位置留下能引发一次较弱的天狗咒雷·伏的「乌羽」，造成原本30%的伤害。', '施放鸦羽天狗霆雷召咒时，会在九条裟罗原本的位置留下能引发一次较弱的天狗咒雷·伏的「乌羽」，造成原本30%的伤害。');
INSERT INTO `genshin_constellation` VALUES (339, 5601, '九条裟罗', 3, '心魔', '<color=#FFD780FF>煌煌千道镇式的技能等级提高3级。\r\n至多提升至15级。', '煌煌千道镇式的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (340, 5601, '九条裟罗', 4, '彻证', '<color=#FFD780FF>煌煌千道镇式释放的天狗咒雷·雷砾增加至6道。', '煌煌千道镇式释放的天狗咒雷·雷砾增加至6道。');
INSERT INTO `genshin_constellation` VALUES (341, 5601, '九条裟罗', 5, '咒咏', '<color=#FFD780FF>鸦羽天狗霆雷召咒的技能等级提高3级。\r\n至多提升至15级。', '鸦羽天狗霆雷召咒的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (342, 5601, '九条裟罗', 6, '我界', '处于天狗咒雷带来的攻击力提升效果状态下的角色，其<color=#FFACFFFF>雷元素伤害的暴击伤害提高60%。', '处于天狗咒雷带来的攻击力提升效果状态下的角色，其雷元素伤害的暴击伤害提高60%。');
INSERT INTO `genshin_constellation` VALUES (343, 6501, '久岐忍', 1, '割舍怜悯之心', '<color=#FFD780FF>御咏鸣神刈山祭的影响范围提升50%。', '御咏鸣神刈山祭的影响范围提升50%。');
INSERT INTO `genshin_constellation` VALUES (344, 6501, '久岐忍', 2, '割舍侥幸之心', '<color=#FFD780FF>越祓草轮的持续时间延长3秒。', '越祓草轮的持续时间延长3秒。');
INSERT INTO `genshin_constellation` VALUES (345, 6501, '久岐忍', 3, '割舍痛苦之心', '<color=#FFD780FF>越祓雷草之轮的技能等级提高3级。\r\n至多提升至15级。', '越祓雷草之轮的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (346, 6501, '久岐忍', 4, '割舍封闭之心', '处于久岐忍自己的<color=#FFD780FF>越祓草轮状态下的角色，在普通攻击、重击或下落攻击命中敌人时，雷草标将落在敌人所在的位置，基于久岐忍生命值上限的9.7%，造成<color=#FFACFFFF>雷元素范围伤害。\r\n该效果每5秒至多触发一次。', '处于久岐忍自己的越祓草轮状态下的角色，在普通攻击、重击或下落攻击命中敌人时，雷草标将落在敌人所在的位置，基于久岐忍生命值上限的9.7%，造成雷元素范围伤害。\r\n该效果每5秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (347, 6501, '久岐忍', 5, '割舍逢迎之心', '<color=#FFD780FF>御咏鸣神刈山祭的技能等级提高3级。\r\n至多提升至15级。', '御咏鸣神刈山祭的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (348, 6501, '久岐忍', 6, '割舍软弱之心', '久岐忍承受足以使她倒下的伤害时，此次伤害不会使她倒下，这个效果在久岐忍生命值为1时会自动触发，该效果每60秒只能触发一次。\r\n久岐忍生命值降至25%以下时，会提升自身150点精通，持续15秒，该效果每60秒只能触发一次。', '久岐忍承受足以使她倒下的伤害时，此次伤害不会使她倒下，这个效果在久岐忍生命值为1时会自动触发，该效果每60秒只能触发一次。\r\n久岐忍生命值降至25%以下时，会提升自身150点精通，持续15秒，该效果每60秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (349, 10801, '蓝砚', 1, '「若有人兮云之际」', '触发突破天赋「四戈封刀灵卜」中的元素转化后，蓝砚在这次元素战技<color=#FFD780FF>凤缕随翦舞中向敌人抛出翦月环时，将额外抛出一枚翦月环。\r\n需要解锁突破天赋「四戈封刀灵卜」。', '触发突破天赋「四戈封刀灵卜」中的元素转化后，蓝砚在这次元素战技凤缕随翦舞中向敌人抛出翦月环时，将额外抛出一枚翦月环。\r\n需要解锁突破天赋「四戈封刀灵卜」。');
INSERT INTO `genshin_constellation` VALUES (350, 10801, '蓝砚', 2, '「舞袂翩兮扬玉霓」', '<color=#FFD780FF>凤缕护盾存在期间，队伍中自己的当前场上角色的普通攻击造成伤害时，会恢复40%凤缕护盾的伤害吸收量，至多恢复至创造护盾时的伤害吸收量，该效果每2秒至多触发一次。', '凤缕护盾存在期间，队伍中自己的当前场上角色的普通攻击造成伤害时，会恢复40%凤缕护盾的伤害吸收量，至多恢复至创造护盾时的伤害吸收量，该效果每2秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (351, 10801, '蓝砚', 3, '「乘白凤兮翦雾縠」', '元素战技<color=#FFD780FF>凤缕随翦舞的技能等级提高3级。\r\n至多提升至15级。', '元素战技凤缕随翦舞的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (352, 10801, '蓝砚', 4, '「揽龙鹰兮结血珠」', '施放元素爆发<color=#FFD780FF>鹍弦踏月出之后的12秒内，队伍中附近所有角色的元素精通提升60点。', '施放元素爆发鹍弦踏月出之后的12秒内，队伍中附近所有角色的元素精通提升60点。');
INSERT INTO `genshin_constellation` VALUES (353, 10801, '蓝砚', 5, '「既见君兮予所欢」', '元素爆发<color=#FFD780FF>鹍弦踏月出的技能等级提高3级。\r\n至多提升至15级。', '元素爆发鹍弦踏月出的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (354, 10801, '蓝砚', 6, '「愿随风兮鸣银鸾」', '<color=#FFD780FF>凤缕随翦舞的可使用次数增加1次。', '凤缕随翦舞的可使用次数增加1次。');
INSERT INTO `genshin_constellation` VALUES (355, 11901, '菈乌玛', 1, '「唇啊，为我纺出歌与吟哦」', '菈乌玛施放元素战技<color=#FFD780FF>圣言述咏·终宵永眠或元素爆发<color=#FFD780FF>圣言述咏·众心为月后，将获得「生之纺线」，持续20秒。\r\n持续期间，队伍中附近的角色触发月绽放反应时，为附近的当前场上角色恢复生命值，回复量相当于菈乌玛元素精通的500%，该效果每1.9秒至多触发一次。\r\n此外，菈乌玛的灵使形态消耗的体力减少40%，最大持续时间延长5秒。', '菈乌玛施放元素战技**圣言述咏·终宵永眠**或元素爆发**圣言述咏·众心为月**后，将获得「生之纺线」，持续20秒。\r\n持续期间，队伍中附近的角色触发月绽放反应时，为附近的当前场上角色恢复生命值，回复量相当于菈乌玛元素精通的500%，该效果每1.9秒至多触发一次。\r\n此外，菈乌玛的灵使形态消耗的体力减少40%，最大持续时间延长5秒。');
INSERT INTO `genshin_constellation` VALUES (356, 11901, '菈乌玛', 2, '「纺出那终北的告诫与述说」', '元素爆发<color=#FFD780FF>圣言述咏·众心为月获得强化：\r\n·<color=#FFD780FF>「苍色祷歌」的效果提升：队伍中附近的所有角色触发绽放、超绽放、烈绽放反应时造成的伤害额外提升，提升值相当于菈乌玛元素精通的500%；队伍中附近的所有角色造成的月绽放反应伤害额外提升，提升值相当于菈乌玛元素精通的400%。\r\n\r\n<color=#FFD780FF>月兆·满辉：队伍中附近的所有角色造成的月绽放反应伤害提升40%。', '元素爆发**圣言述咏·众心为月**获得强化：\r\n·**「苍色祷歌」**的效果提升：队伍中附近的所有角色触发绽放、超绽放、烈绽放反应时造成的伤害额外提升，提升值相当于菈乌玛元素精通的500%；队伍中附近的所有角色造成的月绽放反应伤害额外提升，提升值相当于菈乌玛元素精通的400%。\r\n\r\n月兆·满辉：队伍中附近的所有角色造成的月绽放反应伤害提升40%。');
INSERT INTO `genshin_constellation` VALUES (357, 11901, '菈乌玛', 3, '「汝、切莫贪求狡狐的小径」', '元素爆发<color=#FFD780FF>圣言述咏·众心为月的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**圣言述咏·众心为月**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (358, 11901, '菈乌玛', 4, '「汝、切莫贪恋巨熊的权柄」', '元素战技<color=#FFD780FF>圣言述咏·终宵永眠中的<color=#FFD780FF>霜林圣域的攻击命中敌人时，将为菈乌玛恢复4点元素能量，该效果每5秒至多触发一次。', '元素战技**圣言述咏·终宵永眠**中的**霜林圣域**的攻击命中敌人时，将为菈乌玛恢复4点元素能量，该效果每5秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (359, 11901, '菈乌玛', 5, '「若是得以将真实之物见证」', '元素战技<color=#FFD780FF>圣言述咏·终宵永眠的技能等级提高3级。\r\n至多提升至15级。', '元素战技**圣言述咏·终宵永眠**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (360, 11901, '菈乌玛', 6, '「我愿将这血与泪奉予月明」', '<color=#FFD780FF>霜林圣域攻击敌人时，会额外造成一次视为月绽放反应伤害的<color=#99FF88FF>草元素范围伤害。该伤害基于菈乌玛元素精通的185%，不会消耗<color=#FFD780FF>「苍色祷歌」，而是会使菈乌玛获得2层「苍色祷歌」，并刷新通过这种方式获得的「苍色祷歌」的持续时间。\r\n一次霜林圣域持续期间，该效果至多触发8次；施放元素战技<color=#FFD780FF>圣言述咏·终宵永眠时，将清除通过这种方式获得的「苍色祷歌」。\r\n\r\n此外，菈乌玛在拥有「苍色祷歌」的情况下进行普通攻击时，会消耗一层「苍色祷歌」，转为造成相当于菈乌玛元素精通150%的<color=#99FF88FF>草元素伤害，该伤害视为月绽放反应造成的伤害。\r\n\r\n<color=#FFD780FF>月兆·满辉：队伍中附近的所有角色造成的月绽放反应伤害<color=#FFD780FF>擢升25%。', '**霜林圣域**攻击敌人时，会额外造成一次视为月绽放反应伤害的草元素范围伤害。该伤害基于菈乌玛元素精通的185%，不会消耗**「苍色祷歌」**，而是会使菈乌玛获得2层「苍色祷歌」，并刷新通过这种方式获得的「苍色祷歌」的持续时间。\r\n一次霜林圣域持续期间，该效果至多触发8次；施放元素战技**圣言述咏·终宵永眠**时，将清除通过这种方式获得的「苍色祷歌」。\r\n\r\n此外，菈乌玛在拥有「苍色祷歌」的情况下进行普通攻击时，会消耗一层「苍色祷歌」，转为造成相当于菈乌玛元素精通150%的草元素伤害，该伤害视为月绽放反应造成的伤害。\r\n\r\n月兆·满辉：队伍中附近的所有角色造成的月绽放反应伤害**擢升**25%。');
INSERT INTO `genshin_constellation` VALUES (361, 7401, '莱依拉', 1, '寐领围垣', '<color=#FFD780FF>垂裳端凝之夜的安眠帷幕护盾的伤害吸收量提高20%。\r\n此外，施放垂裳端凝之夜时，将为队伍中附近不处于安眠帷幕护盾庇护下的所有角色生成伤害吸收量为安眠帷幕护盾35%的护盾，该护盾持续12秒，对<color=#99FFFFFF>冰元素伤害有250%的吸收效果。', '垂裳端凝之夜的安眠帷幕护盾的伤害吸收量提高20%。\r\n此外，施放垂裳端凝之夜时，将为队伍中附近不处于安眠帷幕护盾庇护下的所有角色生成伤害吸收量为安眠帷幕护盾35%的护盾，该护盾持续12秒，对冰元素伤害有250%的吸收效果。');
INSERT INTO `genshin_constellation` VALUES (362, 7401, '莱依拉', 2, '归芒携信', '<color=#FFD780FF>垂裳端凝之夜发射的飞星命中敌人时，为莱依拉恢复1点能量。每枚飞星至多通过这种方式为莱依拉恢复一次能量。', '垂裳端凝之夜发射的飞星命中敌人时，为莱依拉恢复1点能量。每枚飞星至多通过这种方式为莱依拉恢复一次能量。');
INSERT INTO `genshin_constellation` VALUES (363, 7401, '莱依拉', 3, '长宵宣秘', '<color=#FFD780FF>垂裳端凝之夜的技能等级提高3级。\r\n至多提升至15级。', '垂裳端凝之夜的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (364, 7401, '莱依拉', 4, '星示昭明', '<color=#FFD780FF>垂裳端凝之夜开始发射一轮飞星时，将为附近的队伍中所有角色赋予「启明」效果，使普通攻击与重击造成的伤害提升，提升值相当于莱依拉生命值上限的5%。\r\n「启明」效果至多持续3秒，将在造成普通攻击或重击伤害后的0.05秒后移除。', '垂裳端凝之夜开始发射一轮飞星时，将为附近的队伍中所有角色赋予「启明」效果，使普通攻击与重击造成的伤害提升，提升值相当于莱依拉生命值上限的5%。\r\n「启明」效果至多持续3秒，将在造成普通攻击或重击伤害后的0.05秒后移除。');
INSERT INTO `genshin_constellation` VALUES (365, 7401, '莱依拉', 5, '悬神系流', '<color=#FFD780FF>星流摇床之梦的技能等级提高3级。\r\n至多提升至15级。', '星流摇床之梦的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (366, 7401, '莱依拉', 6, '曜光灵炬', '<color=#FFD780FF>垂裳端凝之夜的飞星造成的伤害提升40%，<color=#FFD780FF>星流摇床之梦的星光弹造成的伤害提升40%。\r\n此外，垂裳端凝之夜产生晚星的间隔时间减少20%。', '垂裳端凝之夜的飞星造成的伤害提升40%，星流摇床之梦的星光弹造成的伤害提升40%。\r\n此外，垂裳端凝之夜产生晚星的间隔时间减少20%。');
INSERT INTO `genshin_constellation` VALUES (367, 13001, '莉奈娅', 1, '未完成的分类', '施放元素战技<color=#FFD780FF>对策·露米呀吼吼！时，或触发月笼谐奏时，莉奈娅将获得6层<color=#FFD780FF>「历览编录」效果，该效果持续10秒，至多叠加18层。队伍中附近的角色造成月结晶反应伤害时，将消耗一层「历览编录」，提升造成的伤害，提升值相当于莉奈娅防御力的75%。\r\n此外，露米在<color=#FFD780FF>究极厉害形态下使用<color=#FFD780FF>百万吨重锤时，莉奈娅可以消耗至多5层「历览编录」，每层都会使造成的伤害提升，提升值相当于莉奈娅防御力的150%。', '施放元素战技**对策·露米呀吼吼！**时，或触发月笼谐奏时，莉奈娅将获得6层「历览编录」效果，该效果持续10秒，至多叠加18层。队伍中附近的角色造成月结晶反应伤害时，将消耗一层「历览编录」，提升造成的伤害，提升值相当于莉奈娅防御力的75%。\r\n此外，露米在**究极厉害形态**下使用百万吨重锤时，莉奈娅可以消耗至多5层「历览编录」，每层都会使造成的伤害提升，提升值相当于莉奈娅防御力的150%。');
INSERT INTO `genshin_constellation` VALUES (368, 13001, '莉奈娅', 2, '喜或悲的谕告', '触发月笼谐奏后的8秒内，队伍中所有元素类型为<color=#80C0FFFF>水元素与<color=#FFE699FF>岩元素的角色的暴击伤害提升40%，且露米在<color=#FFD780FF>究极厉害形态下使用<color=#FFD780FF>百万吨重锤的暴击伤害额外提升150%。\r\n\r\n<color=#FFD780FF>月兆·满辉：露米在<color=#FFD780FF>超厉害形态下使用<color=#FFD780FF>加力重锤时，或在究极厉害形态下使用<color=#FFD780FF>百万吨重锤时，会触发一次月笼谐奏，且本次月笼谐奏视为队伍中所有元素类型为<color=#80C0FFFF>水元素与<color=#FFE699FF>岩元素的角色均在反应中施加了元素。', '触发月笼谐奏后的8秒内，队伍中所有元素类型为水元素与岩元素的角色的暴击伤害提升40%，且露米在**究极厉害形态**下使用百万吨重锤的暴击伤害额外提升150%。\r\n\r\n月兆·满辉：露米在**超厉害形态**下使用加力重锤时，或在究极厉害形态下使用百万吨重锤时，会触发一次月笼谐奏，且本次月笼谐奏视为队伍中所有元素类型为水元素与岩元素的角色均在反应中施加了元素。');
INSERT INTO `genshin_constellation` VALUES (369, 13001, '莉奈娅', 3, '热闹的记录页', '元素战技<color=#FFD780FF>对策·露米呀吼吼！的技能等级提高3级。\r\n至多提升至15级。', '元素战技**对策·露米呀吼吼！**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (370, 13001, '莉奈娅', 4, '专家的直感觉', '触发月笼谐奏后的5秒内，莉奈娅与队伍中自己的当前场上角色的防御力分别提升25%。莉奈娅在场上时，上述防御力提升效果可叠加。', '触发月笼谐奏后的5秒内，莉奈娅与队伍中自己的当前场上角色的防御力分别提升25%。莉奈娅在场上时，上述防御力提升效果可叠加。');
INSERT INTO `genshin_constellation` VALUES (371, 13001, '莉奈娅', 5, '仙乡的赠别礼', '元素爆发<color=#FFD780FF>备忘·绝境生存指南的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**备忘·绝境生存指南**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (372, 13001, '莉奈娅', 6, '黄金猎犬之梦', '命之座<color=#FFD780FF>「未完成的分类」的效果获得强化：施放元素战技<color=#FFD780FF>对策·露米呀吼吼！时，或触发月笼谐奏时，莉奈娅将直接获得最大层数的<color=#FFD780FF>「历览编录」效果；消耗<color=#FFD780FF>「历览编录」时，将消耗原本2倍的层数，并使伤害提升效果提高至原本的150%。\r\n\r\n<color=#FFD780FF>月兆·满辉：队伍中附近的角色造成的月结晶反应伤害<color=#FFD780FF>擢升25%。', '命之座「未完成的分类」的效果获得强化：施放元素战技**对策·露米呀吼吼！**时，或触发月笼谐奏时，莉奈娅将直接获得最大层数的「历览编录」效果；消耗「历览编录」时，将消耗原本2倍的层数，并使伤害提升效果提高至原本的150%。\r\n\r\n月兆·满辉：队伍中附近的角色造成的月结晶反应伤害**擢升**25%。');
INSERT INTO `genshin_constellation` VALUES (373, 601, '丽莎', 1, '无限的电回路', '<color=#FFD780FF>苍雷长按时，每个命中的敌人都会为丽莎恢复2点元素能量。\r\n通过这种方式，一次至多回复10点元素能量。', '苍雷长按时，每个命中的敌人都会为丽莎恢复2点元素能量。\r\n通过这种方式，一次至多回复10点元素能量。');
INSERT INTO `genshin_constellation` VALUES (374, 601, '丽莎', 2, '空间电势结界', '<color=#FFD780FF>苍雷长按时，具有如下效果：\r\n·防御力提升25%；\r\n·提高丽莎的抗打断能力。', '苍雷长按时，具有如下效果：\r\n·防御力提升25%；\r\n·提高丽莎的抗打断能力。');
INSERT INTO `genshin_constellation` VALUES (375, 601, '丽莎', 3, '谐振的雷光', '<color=#FFD780FF>蔷薇的雷光的技能等级提高3级。\r\n至多提升至15级。', '蔷薇的雷光的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (376, 601, '丽莎', 4, '如雨的电浆', '<color=#FFD780FF>蔷薇的雷光攻击时，放出的闪电增加至1~3道。', '蔷薇的雷光攻击时，放出的闪电增加至1~3道。');
INSERT INTO `genshin_constellation` VALUES (377, 601, '丽莎', 5, '等离态的落雷', '<color=#FFD780FF>苍雷的技能等级提高3级。\r\n至多提升至15级。', '苍雷的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (378, 601, '丽莎', 6, '脉冲的魔女', '丽莎登场时，对附近的敌人施加3层<color=#FFD780FF>苍雷的引雷效果。\r\n该效果每5秒只能触发一次。', '丽莎登场时，对附近的敌人施加3层苍雷的引雷效果。\r\n该效果每5秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (379, 8301, '琳妮特', 1, '如影流露的冷刃', '<color=#FFD780FF>谜影障身法的谜影突刺命中带有刺影征标的敌人时，将在敌人的位置生成风涡，牵引附近的敌人。', '谜影障身法的谜影突刺命中带有刺影征标的敌人时，将在敌人的位置生成风涡，牵引附近的敌人。');
INSERT INTO `genshin_constellation` VALUES (380, 8301, '琳妮特', 2, '层见叠出的谜象', '<color=#FFD780FF>魔术·运变惊奇召唤的惊奇猫猫盒发射彩练术弹时，将额外发射一枚彩练术弹。', '魔术·运变惊奇召唤的惊奇猫猫盒发射彩练术弹时，将额外发射一枚彩练术弹。');
INSERT INTO `genshin_constellation` VALUES (381, 8301, '琳妮特', 3, '倒错知能的视度', '<color=#FFD780FF>魔术·运变惊奇的技能等级提高3级。\r\n至多提升至15级。', '魔术·运变惊奇的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (382, 8301, '琳妮特', 4, '灵犀默应的配合', '<color=#FFD780FF>谜影障身法的可使用次数增加1次。', '谜影障身法的可使用次数增加1次。');
INSERT INTO `genshin_constellation` VALUES (383, 8301, '琳妮特', 5, '暗昧遮目的障法', '<color=#FFD780FF>谜影障身法的技能等级提高3级。\r\n至多提升至15级。', '谜影障身法的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (384, 8301, '琳妮特', 6, '示辨真意的眼', '琳妮特施放<color=#FFD780FF>谜影障身法的谜影突刺时，将获得<color=#80FFD7FF>风元素附魔，<color=#80FFD7FF>风元素伤害加成提升20%，持续6秒。', '琳妮特施放谜影障身法的谜影突刺时，将获得风元素附魔，风元素伤害加成提升20%，持续6秒。');
INSERT INTO `genshin_constellation` VALUES (385, 8401, '林尼', 1, '空取奇思的手艺', '<color=#FFD780FF>怪笑猫猫帽至多可以同时存在2顶。\r\n此外，隐具魔术箭将在命中时召唤2顶怪笑猫猫帽，并额外积累1层「隐具余数」，该效果每15秒至多触发一次。', '怪笑猫猫帽至多可以同时存在2顶。\r\n此外，隐具魔术箭将在命中时召唤2顶怪笑猫猫帽，并额外积累1层「隐具余数」，该效果每15秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (386, 8401, '林尼', 2, '巧言贴耳的诱引', '林尼在场上时，每2秒将获得一层「集意专注」效果，使林尼的暴击伤害提升20%。此效果至多叠加3层，将在林尼退场时解除。', '林尼在场上时，每2秒将获得一层「集意专注」效果，使林尼的暴击伤害提升20%。此效果至多叠加3层，将在林尼退场时解除。');
INSERT INTO `genshin_constellation` VALUES (387, 8401, '林尼', 3, '玄迷灵敏的指法', '<color=#FFD780FF>普通攻击·迫牌易位式的技能等级提高3级。\r\n至多提升至15级。', '普通攻击·迫牌易位式的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (388, 8401, '林尼', 4, '熟稔习练的筹谋', '林尼的元素类型为<color=#FF9999FF>火元素的重击攻击命中敌人后，该敌人的<color=#FF9999FF>火元素抗性降低20%，持续6秒。', '林尼的元素类型为火元素的重击攻击命中敌人后，该敌人的火元素抗性降低20%，持续6秒。');
INSERT INTO `genshin_constellation` VALUES (389, 8401, '林尼', 5, '穿越隐秘的通术', '<color=#FFD780FF>大魔术·灵迹巡游的技能等级提高3级。\r\n至多提升至15级。', '大魔术·灵迹巡游的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (390, 8401, '林尼', 6, '违心的笑', '林尼发射<color=#FFD780FF>隐具魔术箭时，将发射一枚礼花术弹·重奏，造成礼花术弹80%的伤害。该伤害视为重击伤害。', '林尼发射隐具魔术箭时，将发射一枚礼花术弹·重奏，造成礼花术弹80%的伤害。该伤害视为重击伤害。');
INSERT INTO `genshin_constellation` VALUES (391, 10601, '玛薇卡', 1, '夜主的授记', '玛薇卡的夜魂值上限提升为120点，且战意的获取效率提升25%。\r\n此外，获取战意后，玛薇卡的攻击力提升40%，持续8秒。', '玛薇卡的夜魂值上限提升为120点，且战意的获取效率提升25%。\r\n此外，获取战意后，玛薇卡的攻击力提升40%，持续8秒。');
INSERT INTO `genshin_constellation` VALUES (392, 10601, '玛薇卡', 2, '灰烬的代价', '处于夜魂加持状态下时，玛薇卡的基础攻击力提升200点，并根据诸火武装的形态，获得对应效果：\r\n·焚曜之环：附近的敌人的防御力降低20%；\r\n·驰轮车：玛薇卡的普通攻击、重击、元素爆发<color=#FFD780FF>燔天之时中的坠日斩造成的伤害提升，提升值相当于玛薇卡攻击力的60%/90%/120%。', '处于夜魂加持状态下时，玛薇卡的基础攻击力提升200点，并根据诸火武装的形态，获得对应效果：\r\n·焚曜之环：附近的敌人的防御力降低20%；\r\n·驰轮车：玛薇卡的普通攻击、重击、元素爆发燔天之时中的坠日斩造成的伤害提升，提升值相当于玛薇卡攻击力的60%/90%/120%。');
INSERT INTO `genshin_constellation` VALUES (393, 10601, '玛薇卡', 3, '燃烧的太阳', '元素爆发<color=#FFD780FF>燔天之时的技能等级提高3级。\r\n至多提升至15级。', '元素爆发燔天之时的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (394, 10601, '玛薇卡', 4, '「领袖」的觉悟', '突破天赋「基扬戈兹」的效果获得提升：\r\n施放元素爆发<color=#FFD780FF>燔天之时后的伤害提升效果不再随时间降低，并额外获得10%伤害加成。\r\n需要解锁突破天赋「基扬戈兹」。', '突破天赋「基扬戈兹」的效果获得提升：\r\n施放元素爆发燔天之时后的伤害提升效果不再随时间降低，并额外获得10%伤害加成。\r\n需要解锁突破天赋「基扬戈兹」。');
INSERT INTO `genshin_constellation` VALUES (395, 10601, '玛薇卡', 5, '真实的含义', '元素战技<color=#FFD780FF>称名之刻的技能等级提高3级。\r\n至多提升至15级。', '元素战技称名之刻的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (396, 10601, '玛薇卡', 6, '「人之名」解放', '元素战技<color=#FFD780FF>称名之刻中的诸火武装获得完全强化：\r\n·焚曜之环：焚曜之环的攻击命中敌人时，将会有一辆驰轮车撞向被命中的敌人，造成200%攻击力的具有夜魂性质的<color=#FF9999FF>火元素范围伤害；\r\n·驰轮车：玛薇卡驾驶驰轮车时，还会召唤出持续跟随玛薇卡的「焚曜之环·灼象」，使附近的敌人的防御力降低20%，并且每3秒对周围的敌人造成一次500%攻击力的具有夜魂性质的<color=#FF9999FF>火元素范围伤害，且玛薇卡通过各种地形的能力也会进一步提升。\r\n\r\n此外，玛薇卡驾驶驰轮车且不处于战斗状态下时，当玛薇卡的夜魂值降低至5点时，将获得80点夜魂值，该效果每15秒至多触发一次。', '元素战技称名之刻中的诸火武装获得完全强化：\r\n·焚曜之环：焚曜之环的攻击命中敌人时，将会有一辆驰轮车撞向被命中的敌人，造成200%攻击力的具有夜魂性质的火元素范围伤害；\r\n·驰轮车：玛薇卡驾驶驰轮车时，还会召唤出持续跟随玛薇卡的「焚曜之环·灼象」，使附近的敌人的防御力降低20%，并且每3秒对周围的敌人造成一次500%攻击力的具有夜魂性质的火元素范围伤害，且玛薇卡通过各种地形的能力也会进一步提升。\r\n\r\n此外，玛薇卡驾驶驰轮车且不处于战斗状态下时，当玛薇卡的夜魂值降低至5点时，将获得80点夜魂值，该效果每15秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (397, 8001, '米卡', 1, '遇合的因缘', '<color=#FFD780FF>星霜的流旋产生的灵风状态能使<color=#FFD780FF>苍翎的颂愿的鹰翎状态恢复生命值的间隔降低，降低比例等同于灵风状态提供的攻击速度提升比例。', '星霜的流旋产生的灵风状态能使苍翎的颂愿的鹰翎状态恢复生命值的间隔降低，降低比例等同于灵风状态提供的攻击速度提升比例。');
INSERT INTO `genshin_constellation` VALUES (398, 8001, '米卡', 2, '伴行的旅路', '<color=#FFD780FF>星霜的流旋的霜流矢首次命中敌人时，或是冰星信标命中敌人时，将产生1层突破天赋「速射牵制」的侦明效果。\r\n需要解锁突破天赋「速射牵制」。', '星霜的流旋的霜流矢首次命中敌人时，或是冰星信标命中敌人时，将产生1层突破天赋「速射牵制」的侦明效果。\r\n需要解锁突破天赋「速射牵制」。');
INSERT INTO `genshin_constellation` VALUES (399, 8001, '米卡', 3, '游击的心得', '<color=#FFD780FF>苍翎的颂愿的技能等级提高3级。\r\n至多提升至15级。', '苍翎的颂愿的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (400, 8001, '米卡', 4, '晴霜的祝念', '米卡自己的<color=#FFD780FF>苍翎的颂愿的鹰翎状态为队伍中的角色进行治疗时，将为米卡恢复3点元素能量。通过一次施放苍翎的颂愿产生的鹰翎状态，至多恢复5次元素能量。', '米卡自己的苍翎的颂愿的鹰翎状态为队伍中的角色进行治疗时，将为米卡恢复3点元素能量。通过一次施放苍翎的颂愿产生的鹰翎状态，至多恢复5次元素能量。');
INSERT INTO `genshin_constellation` VALUES (401, 8001, '米卡', 5, '引示的铃箭', '<color=#FFD780FF>星霜的流旋的技能等级提高3级。\r\n至多提升至15级。', '星霜的流旋的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (402, 8001, '米卡', 6, '依随的策援', '<color=#FFD780FF>星霜的流旋灵风状态下的侦明效果叠加层数上限提升1层。需要解锁突破天赋「速射牵制」。\r\n此外，处于灵风状态下的当前场上角色，其物理伤害的暴击伤害提高60%。', '星霜的流旋灵风状态下的侦明效果叠加层数上限提升1层。需要解锁突破天赋「速射牵制」。\r\n此外，处于灵风状态下的当前场上角色，其物理伤害的暴击伤害提高60%。');
INSERT INTO `genshin_constellation` VALUES (403, 4101, '莫娜', 1, '沉没的预言', '队伍中自己的角色攻击命中处于星异状态下的敌人后的8秒内，<color=#80C0FFFF>水元素相关反应的效果提升：\r\n·感电反应造成的伤害提升15%，月感电反应造成的伤害提升15%，蒸发反应造成的伤害提升15%，水元素扩散反应造成的伤害提升15%，月结晶反应造成的伤害提升15%；\r\n·冻结反应的持续时间延长15%。', '队伍中自己的角色攻击命中处于星异状态下的敌人后的8秒内，水元素相关反应的效果提升：\r\n·感电反应造成的伤害提升15%，月感电反应造成的伤害提升15%，蒸发反应造成的伤害提升15%，水元素扩散反应造成的伤害提升15%，月结晶反应造成的伤害提升15%；\r\n·冻结反应的持续时间延长15%。');
INSERT INTO `genshin_constellation` VALUES (404, 4101, '莫娜', 2, '星月的连珠', '普通攻击命中时，有20%的几率自动施放一次重击。\r\n该效果每5秒只能触发一次。', '普通攻击命中时，有20%的几率自动施放一次重击。\r\n该效果每5秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (405, 4101, '莫娜', 3, '不休的天象', '<color=#FFD780FF>星命定轨的技能等级提高3级。\r\n至多提升至15级。', '星命定轨的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (406, 4101, '莫娜', 4, '灭绝的预言', '队伍中所有角色攻击处于星异状态下的敌人时，暴击率提升15%。', '队伍中所有角色攻击处于星异状态下的敌人时，暴击率提升15%。');
INSERT INTO `genshin_constellation` VALUES (407, 4101, '莫娜', 5, '命运的嘲弄', '<color=#FFD780FF>水中幻愿的技能等级提高3级。\r\n至多提升至15级。', '水中幻愿的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (408, 4101, '莫娜', 6, '厄运的修辞', '进入<color=#FFD780FF>虚实流动状态后，每移动1秒，莫娜的下一次重击伤害就增加60%，\r\n通过这种方式至多可以获得180%重击伤害加成，该效果至多持续8秒。', '进入虚实流动状态后，每移动1秒，莫娜的下一次重击伤害就增加60%，\r\n通过这种方式至多可以获得180%重击伤害加成，该效果至多持续8秒。');
INSERT INTO `genshin_constellation` VALUES (409, 10201, '玛拉妮', 1, '悠闲的「梅兹特利」…', '进入夜魂加持状态后的第一次巨浪鲨鲨撕咬及它所触发的鲨鲨飞弹造成的伤害提升，提升值相当于玛拉妮生命值上限的66%。此次伤害提升遵循<color=#FFD780FF>踏鲨破浪的伤害衰减规则。\r\n此外，不处于战斗状态下时，玛拉妮的夜魂加持状态消耗的夜魂值与燃素降低30%。', '进入夜魂加持状态后的第一次巨浪鲨鲨撕咬及它所触发的鲨鲨飞弹造成的伤害提升，提升值相当于玛拉妮生命值上限的66%。此次伤害提升遵循踏鲨破浪的伤害衰减规则。\r\n此外，不处于战斗状态下时，玛拉妮的夜魂加持状态消耗的夜魂值与燃素降低30%。');
INSERT INTO `genshin_constellation` VALUES (410, 10201, '玛拉妮', 2, '全力以赴玛拉妮！', '进入夜魂加持状态时，玛拉妮获得2层<color=#FFD780FF>踏鲨破浪的浪势充能；玛拉妮获得豚豚球时，获得1层浪势充能。\r\n此外，玛拉妮在一次夜魂加持期间获得2个豚豚球的2秒内，额外恢复12点夜魂值。该效果需要解锁突破天赋「耐热型淡水豚豚」。', '进入夜魂加持状态时，玛拉妮获得2层踏鲨破浪的浪势充能；玛拉妮获得豚豚球时，获得1层浪势充能。\r\n此外，玛拉妮在一次夜魂加持期间获得2个豚豚球的2秒内，额外恢复12点夜魂值。该效果需要解锁突破天赋「耐热型淡水豚豚」。');
INSERT INTO `genshin_constellation` VALUES (411, 10201, '玛拉妮', 3, '在欢乐海上冲浪', '<color=#FFD780FF>踏鲨破浪的技能等级提高3级。\r\n至多提升至15级。', '踏鲨破浪的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (412, 10201, '玛拉妮', 4, '鲨鲨主食是豚豚。', '获得豚豚球时，玛拉妮恢复8点元素能量；该效果需要解锁突破天赋「耐热型淡水豚豚」。\r\n此外，<color=#FFD780FF>爆瀑飞弹造成的伤害提升75%。', '获得豚豚球时，玛拉妮恢复8点元素能量；该效果需要解锁突破天赋「耐热型淡水豚豚」。\r\n此外，爆瀑飞弹造成的伤害提升75%。');
INSERT INTO `genshin_constellation` VALUES (413, 10201, '玛拉妮', 5, '同款冲浪板有售！', '<color=#FFD780FF>爆瀑飞弹的技能等级提高3级。\r\n至多提升至15级。', '爆瀑飞弹的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (414, 10201, '玛拉妮', 6, '「流泉之众」的精神', '对命之座「悠闲的「梅兹特利」…」的伤害提升效果，移除原本每次夜魂加持只能触发一次的限制。', '对命之座「悠闲的「梅兹特利」…」的伤害提升效果，移除原本每次夜魂加持只能触发一次的限制。');
INSERT INTO `genshin_constellation` VALUES (415, 7301, '纳西妲', 1, '心识蕴藏之种', '展开<color=#FFD780FF>摩耶之殿计算队伍中特定元素类型的角色数量时，额外计入火元素、雷元素、水元素的角色各1名。', '展开摩耶之殿计算队伍中特定元素类型的角色数量时，额外计入火元素、雷元素、水元素的角色各1名。');
INSERT INTO `genshin_constellation` VALUES (416, 7301, '纳西妲', 2, '正等善见之根', '处于纳西妲自身施加的<color=#FFD780FF>蕴种印状态下的敌人，将受到以下效果影响：\r\n·受到的燃烧、绽放、超绽放、烈绽放反应伤害能够造成暴击，暴击率固定为20%，暴击伤害固定为100%，该效果提供的暴击率可以与使对应元素反应能够造成暴击的同类效果提供的暴击率叠加；\r\n·受到原激化、超激化、蔓激化反应影响后的8秒内，防御力降低30%；\r\n·受到月绽放反应伤害的暴击率提升10%，暴击伤害提升20%。', '处于纳西妲自身施加的蕴种印状态下的敌人，将受到以下效果影响：\r\n·受到的燃烧、绽放、超绽放、烈绽放反应伤害能够造成暴击，暴击率固定为20%，暴击伤害固定为100%，该效果提供的暴击率可以与使对应元素反应能够造成暴击的同类效果提供的暴击率叠加；\r\n·受到原激化、超激化、蔓激化反应影响后的8秒内，防御力降低30%；\r\n·受到月绽放反应伤害的暴击率提升10%，暴击伤害提升20%。');
INSERT INTO `genshin_constellation` VALUES (417, 7301, '纳西妲', 3, '熏习成就之芽', '<color=#FFD780FF>所闻遍计的技能等级提高3级。\r\n至多提升至15级。', '所闻遍计的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (418, 7301, '纳西妲', 4, '比量现行之茎', '附近处于<color=#FFD780FF>所闻遍计的蕴种印状态下的敌人数量为1/2/3/4或更多时，纳西妲的元素精通提升100/120/140/160点。', '附近处于所闻遍计的蕴种印状态下的敌人数量为1/2/3/4或更多时，纳西妲的元素精通提升100/120/140/160点。');
INSERT INTO `genshin_constellation` VALUES (419, 7301, '纳西妲', 5, '妙谛破愚之叶', '<color=#FFD780FF>心景幻成的技能等级提高3级。\r\n至多提升至15级。', '心景幻成的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (420, 7301, '纳西妲', 6, '大辨圆成之实', '施放<color=#FFD780FF>心景幻成后，纳西妲的普通攻击或重击命中处于<color=#FFD780FF>所闻遍计的蕴种印状态下的敌人时，将对该敌人及其所处连结中的所有敌人释放灭净三业·业障除，基于纳西妲攻击力的200%与元素精通的400%，造成<color=#99FF88FF>草元素伤害。\r\n灭净三业·业障除造成的伤害视为元素战技伤害，每0.2秒至多触发一次。\r\n该效果至多持续10秒，将在纳西妲释放6次灭净三业·业障除后移除。', '施放心景幻成后，纳西妲的普通攻击或重击命中处于所闻遍计的蕴种印状态下的敌人时，将对该敌人及其所处连结中的所有敌人释放灭净三业·业障除，基于纳西妲攻击力的200%与元素精通的400%，造成草元素伤害。\r\n灭净三业·业障除造成的伤害视为元素战技伤害，每0.2秒至多触发一次。\r\n该效果至多持续10秒，将在纳西妲释放6次灭净三业·业障除后移除。');
INSERT INTO `genshin_constellation` VALUES (421, 9101, '娜维娅', 1, '淑女的距离感守则', '施放<color=#FFD780FF>典仪式晶火时，每消耗1枚「裂晶弹片」，都将为娜维娅恢复3点元素能量，并使<color=#FFD780FF>如霰澄天的鸣礼的冷却时间减少1秒。至多通过这种方式恢复9点元素能量，使「如霰澄天的鸣礼」的冷却时间减少3秒。', '施放典仪式晶火时，每消耗1枚「裂晶弹片」，都将为娜维娅恢复3点元素能量，并使如霰澄天的鸣礼的冷却时间减少1秒。至多通过这种方式恢复9点元素能量，使「如霰澄天的鸣礼」的冷却时间减少3秒。');
INSERT INTO `genshin_constellation` VALUES (422, 9101, '娜维娅', 2, '总指挥的乘胜追击', '施放<color=#FFD780FF>典仪式晶火时，每消耗1枚「裂晶弹片」，都将使本次典仪式晶火的暴击率提升12%，至多通过这种方式使其暴击率提高36%。\r\n此外，典仪式晶火的射击命中敌人时，将在命中的敌人附近降下一次<color=#FFD780FF>如霰澄天的鸣礼的「支援炮击」。每次施放典仪式晶火至多降下一次支援炮击，通过这种方式触发的支援炮击的伤害视为元素爆发伤害。', '施放典仪式晶火时，每消耗1枚「裂晶弹片」，都将使本次典仪式晶火的暴击率提升12%，至多通过这种方式使其暴击率提高36%。\r\n此外，典仪式晶火的射击命中敌人时，将在命中的敌人附近降下一次如霰澄天的鸣礼的「支援炮击」。每次施放典仪式晶火至多降下一次支援炮击，通过这种方式触发的支援炮击的伤害视为元素爆发伤害。');
INSERT INTO `genshin_constellation` VALUES (423, 9101, '娜维娅', 3, '经营家的开阔视野', '<color=#FFD780FF>典仪式晶火的技能等级提高3级。\r\n至多提升至15级。', '典仪式晶火的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (424, 9101, '娜维娅', 4, '铭誓者的绝不姑息', '<color=#FFD780FF>如霰澄天的鸣礼命中敌人时，将使该敌人的<color=#FFE699FF>岩元素抗性降低20%，持续8秒。', '如霰澄天的鸣礼命中敌人时，将使该敌人的岩元素抗性降低20%，持续8秒。');
INSERT INTO `genshin_constellation` VALUES (425, 9101, '娜维娅', 5, '协商人的坚决谈判', '<color=#FFD780FF>如霰澄天的鸣礼的技能等级提高3级。\r\n至多提升至15级。', '如霰澄天的鸣礼的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (426, 9101, '娜维娅', 6, '刺玫会长的灵活手腕', '施放<color=#FFD780FF>典仪式晶火时，若消耗的「裂晶弹片」超过3枚，超过3枚的每枚「裂晶弹片」都将使本次典仪式晶火的暴击伤害提升45%，且消耗的超过3枚的部分将在施放后返还。', '施放典仪式晶火时，若消耗的「裂晶弹片」超过3枚，超过3枚的每枚「裂晶弹片」都将使本次典仪式晶火的暴击伤害提升45%，且消耗的超过3枚的部分将在施放后返还。');
INSERT INTO `genshin_constellation` VALUES (427, 12201, '奈芙尔', 1, '谋篇乃成败之始', '奈芙尔的<color=#FFD780FF>幻戏造成的月绽放反应伤害的基础伤害提升，提升值相当于奈芙尔的元素精通的60%。该效果同样会受到<color=#FFD780FF>「伪秘之帷」的加成。', '奈芙尔的**幻戏**造成的月绽放反应伤害的基础伤害提升，提升值相当于奈芙尔的元素精通的60%。该效果同样会受到**「伪秘之帷」**的加成。');
INSERT INTO `genshin_constellation` VALUES (428, 12201, '奈芙尔', 2, '明察为筹算之先', '突破天赋<color=#FFD780FF>「月下的豪赌」的效果获得强化：<color=#FFD780FF>「伪秘之帷」的持续时间延长5秒，上限提升至5层，且至多使<color=#FFD780FF>幻戏造成原本140%的伤害；奈芙尔施放元素战技<color=#FFD780FF>弈术·千夜一舞时，将立刻获得2层「伪秘之帷」。此外，「伪秘之帷」叠加至5层或5层的持续时间刷新时，奈芙尔的元素精通改为提升200点，持续8秒。\r\n需要解锁突破天赋「月下的豪赌」。', '突破天赋**「月下的豪赌」**的效果获得强化：**「伪秘之帷」**的持续时间延长5秒，上限提升至5层，且至多使**幻戏**造成原本140%的伤害；奈芙尔施放元素战技**弈术·千夜一舞**时，将立刻获得2层「伪秘之帷」。此外，「伪秘之帷」叠加至5层或5层的持续时间刷新时，奈芙尔的元素精通改为提升200点，持续8秒。\r\n需要解锁突破天赋「月下的豪赌」。');
INSERT INTO `genshin_constellation` VALUES (429, 12201, '奈芙尔', 3, '诳言掩虚实之迹', '元素战技<color=#FFD780FF>弈术·千夜一舞的技能等级提高3级。\r\n至多提升至15级。', '元素战技**弈术·千夜一舞**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (430, 12201, '奈芙尔', 4, '眩惑入谜局之网', '奈芙尔在场上且处于<color=#FFD780FF>「影舞」状态下时，获取草露的速度提升25%。\r\n此外，奈芙尔处于「影舞」状态下时，还会使附近敌人的<color=#99FF88FF>草元素抗性降低20%，当奈芙尔不处于「影舞」状态或离开敌人一定距离后，该效果会在4.5秒后移除。', '奈芙尔在场上且处于**「影舞」**状态下时，获取草露的速度提升25%。\r\n此外，奈芙尔处于「影舞」状态下时，还会使附近敌人的草元素抗性降低20%，当奈芙尔不处于「影舞」状态或离开敌人一定距离后，该效果会在4.5秒后移除。');
INSERT INTO `genshin_constellation` VALUES (431, 12201, '奈芙尔', 5, '见机在忽微之间', '元素爆发<color=#FFD780FF>圣约·真眸幻戏的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**圣约·真眸幻戏**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (432, 12201, '奈芙尔', 6, '决胜于逆转之时', '奈芙尔施放<color=#FFD780FF>幻戏时，自身的第二段伤害将转为造成相当于奈芙尔元素精通85%的<color=#99FF88FF>草元素范围伤害；此外，幻戏的攻击结束时，还会造成一次相当于奈芙尔元素精通120%的<color=#99FF88FF>草元素范围伤害。上述伤害均视为由幻戏造成的月绽放反应伤害。\r\n\r\n<color=#FFD780FF>月兆·满辉 \r\n奈芙尔造成的月绽放反应伤害<color=#FFD780FF>擢升15%。', '奈芙尔施放**幻戏**时，自身的第二段伤害将转为造成相当于奈芙尔元素精通85%的草元素范围伤害；此外，幻戏的攻击结束时，还会造成一次相当于奈芙尔元素精通120%的草元素范围伤害。上述伤害均视为由幻戏造成的月绽放反应伤害。\r\n\r\n月兆·满辉 \r\n奈芙尔造成的月绽放反应伤害**擢升**15%。');
INSERT INTO `genshin_constellation` VALUES (433, 8701, '那维莱特', 1, '尊荣的创定', '那维莱特登场时，获得一层突破天赋「古海孑遗的权柄」的「遗龙之荣」。需要解锁突破天赋「古海孑遗的权柄」。\r\n此外，进行重击蓄力·诉论心证与重击·衡平推裁时，提高那维莱特的抗打断能力。', '那维莱特登场时，获得一层突破天赋「古海孑遗的权柄」的「遗龙之荣」。需要解锁突破天赋「古海孑遗的权柄」。\r\n此外，进行重击蓄力·诉论心证与重击·衡平推裁时，提高那维莱特的抗打断能力。');
INSERT INTO `genshin_constellation` VALUES (434, 8701, '那维莱特', 2, '律法的命诫', '突破天赋「古海孑遗的权柄」获得强化：每存在一层「遗龙之荣」，就使重击·衡平推裁的暴击伤害提升14%，至多通过这种方式提升42%。\r\n需要解锁突破天赋「古海孑遗的权柄」。', '突破天赋「古海孑遗的权柄」获得强化：每存在一层「遗龙之荣」，就使重击·衡平推裁的暴击伤害提升14%，至多通过这种方式提升42%。\r\n需要解锁突破天赋「古海孑遗的权柄」。');
INSERT INTO `genshin_constellation` VALUES (435, 8701, '那维莱特', 3, '溯古的拟制', '<color=#FFD780FF>普通攻击·如水从平的技能等级提高3级。\r\n至多提升至15级。', '普通攻击·如水从平的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (436, 8701, '那维莱特', 4, '悲悯的冠冕', '那维莱特处于当前场上并受到治疗时，将产生1枚源水之滴。此效果每4秒至多触发一次。', '那维莱特处于当前场上并受到治疗时，将产生1枚源水之滴。此效果每4秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (437, 8701, '那维莱特', 5, '公理的决裁', '<color=#FFD780FF>潮水啊，我已归来的技能等级提高3级。\r\n至多提升至15级。', '潮水啊，我已归来的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (438, 8701, '那维莱特', 6, '忿怒的报偿', '施放重击·衡平推裁时，那维莱特可以吸收附近一定范围内的源水之滴，每吸收一枚源水之滴，都将使重击·衡平推裁的持续时间延长1秒。\r\n此外，重击·衡平推裁命中敌人时，每2秒，将额外释放两道洪流，每道洪流造成相当于那维莱特生命值上限10%的<color=#80C0FFFF>水元素伤害。通过这种方式造成的伤害视为重击·衡平推裁造成的伤害。', '施放重击·衡平推裁时，那维莱特可以吸收附近一定范围内的源水之滴，每吸收一枚源水之滴，都将使重击·衡平推裁的持续时间延长1秒。\r\n此外，重击·衡平推裁命中敌人时，每2秒，将额外释放两道洪流，每道洪流造成相当于那维莱特生命值上限10%的水元素伤害。通过这种方式造成的伤害视为重击·衡平推裁造成的伤害。');
INSERT INTO `genshin_constellation` VALUES (439, 7001, '妮露', 1, '却月的轻舞', '<color=#FFD780FF>七域舞步获得如下强化：\r\n·水月造成的伤害提升65%；\r\n·净天水环的持续时间延长6秒。', '七域舞步获得如下强化：\r\n·水月造成的伤害提升65%；\r\n·净天水环的持续时间延长6秒。');
INSERT INTO `genshin_constellation` VALUES (440, 7001, '妮露', 2, '星天的花雨', '处于「金杯的丰馈」状态下的角色对敌人造成<color=#80C0FFFF>水元素伤害后，该敌人的<color=#80C0FFFF>水元素抗性降低35%，持续10秒；对敌人造成绽放或月绽放反应伤害后，该敌人的<color=#99FF88FF>草元素抗性降低35%，持续10秒。\r\n需要解锁突破天赋「折旋落英之庭」。', '处于「金杯的丰馈」状态下的角色对敌人造成水元素伤害后，该敌人的水元素抗性降低35%，持续10秒；对敌人造成绽放或月绽放反应伤害后，该敌人的草元素抗性降低35%，持续10秒。\r\n需要解锁突破天赋「折旋落英之庭」。');
INSERT INTO `genshin_constellation` VALUES (441, 7001, '妮露', 3, '倾影的莲步', '<color=#FFD780FF>浮莲舞步·远梦聆泉的技能等级提高3级。\r\n至多提升至15级。', '浮莲舞步·远梦聆泉的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (442, 7001, '妮露', 4, '挽漪的节音', '<color=#FFD780FF>七域舞步的翩转状态下的第三段舞步命中敌人后，将为妮露恢复15点元素能量，并使妮露的<color=#FFD780FF>浮莲舞步·远梦聆泉造成的伤害提升50%，持续8秒。', '七域舞步的翩转状态下的第三段舞步命中敌人后，将为妮露恢复15点元素能量，并使妮露的浮莲舞步·远梦聆泉造成的伤害提升50%，持续8秒。');
INSERT INTO `genshin_constellation` VALUES (443, 7001, '妮露', 5, '翩旋的流光', '<color=#FFD780FF>七域舞步的技能等级提高3级。\r\n至多提升至15级。', '七域舞步的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (444, 7001, '妮露', 6, '断霜的弦歌', '每1000点生命值上限，将使妮露的暴击率提升0.6%，暴击伤害提升1.2%。\r\n通过这种方式，妮露的暴击率至多提升30%，暴击伤害至多提升60%。', '每1000点生命值上限，将使妮露的暴击率提升0.6%，暴击伤害提升1.2%。\r\n通过这种方式，妮露的暴击率至多提升30%，暴击伤害至多提升60%。');
INSERT INTO `genshin_constellation` VALUES (445, 2701, '凝光', 1, '悬星尽散击云碎', '普通攻击命中时，会造成范围伤害。', '普通攻击命中时，会造成范围伤害。');
INSERT INTO `genshin_constellation` VALUES (446, 2701, '凝光', 2, '璇玑合璧镇昆仑', '<color=#FFD780FF>璇玑屏碎裂时，会清除冷却时间。\r\n该效果每6秒只能触发一次。', '璇玑屏碎裂时，会清除冷却时间。\r\n该效果每6秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (447, 2701, '凝光', 3, '星罗宿列天权临', '<color=#FFD780FF>天权崩玉的技能等级提高3级。\r\n至多提升至15级。', '天权崩玉的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (448, 2701, '凝光', 4, '攻守易形著神机', '<color=#FFD780FF>璇玑屏会使周围角色的所有元素抗性提升10%。', '璇玑屏会使周围角色的所有元素抗性提升10%。');
INSERT INTO `genshin_constellation` VALUES (449, 2701, '凝光', 5, '琼屏千扇正天衡', '<color=#FFD780FF>璇玑屏的技能等级提高3级。\r\n至多提升至15级。', '璇玑屏的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (450, 2701, '凝光', 6, '七星璨璨凝流光', '施放<color=#FFD780FF>天权崩玉时，会为凝光生成七枚星璇。', '施放天权崩玉时，会为凝光生成七枚星璇。');
INSERT INTO `genshin_constellation` VALUES (451, 3401, '诺艾尔', 1, '支援就交给我吧', '同时处于<color=#FFD780FF>大扫除与<color=#FFD780FF>护心铠状态时，护心铠的生命值回复效果触发几率提升至100%。', '同时处于大扫除与护心铠状态时，护心铠的生命值回复效果触发几率提升至100%。');
INSERT INTO `genshin_constellation` VALUES (452, 3401, '诺艾尔', 2, '旋风女仆', '诺艾尔的重击的体力消耗降低20%，伤害提升15%。', '诺艾尔的重击的体力消耗降低20%，伤害提升15%。');
INSERT INTO `genshin_constellation` VALUES (453, 3401, '诺艾尔', 3, '女仆不会受伤', '<color=#FFD780FF>护心铠的技能等级提高3级。\r\n至多提升至15级。', '护心铠的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (454, 3401, '诺艾尔', 4, '之后会扫干净的', '<color=#FFD780FF>护心铠在效果结束时，或因伤害破碎时，会对周围的敌人造成400%攻击力的<color=#FFE699FF>岩元素伤害。', '护心铠在效果结束时，或因伤害破碎时，会对周围的敌人造成400%攻击力的岩元素伤害。');
INSERT INTO `genshin_constellation` VALUES (455, 3401, '诺艾尔', 5, '骑士团扫除专家', '<color=#FFD780FF>大扫除的技能等级提高3级。\r\n至多提升至15级。', '大扫除的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (456, 3401, '诺艾尔', 6, '要一尘不染才行', '<color=#FFD780FF>大扫除额外提高诺艾尔防御力50%的攻击力；\r\n此外，在技能持续时间内，每打倒1个敌人，其持续时间将延长1秒，最多不会超过10秒。', '大扫除额外提高诺艾尔防御力50%的攻击力；\r\n此外，在技能持续时间内，每打倒1个敌人，其持续时间将延长1秒，最多不会超过10秒。');
INSERT INTO `genshin_constellation` VALUES (457, 10501, '欧洛伦', 1, '林雾间的行迹', '元素战技<color=#FFD780FF>暝色缒索中的<color=#FFD780FF>宿灵球能额外弹跳2次。\r\n此外，<color=#FFD780FF>宿灵球命中敌人后，将为该敌人施加「夜暝」效果，持续12秒；对处于「夜暝」效果的影响下的敌人，突破天赋「夜翳的通感」触发的「显象超感」造成的伤害提升50%，该效果需要解锁突破天赋「夜翳的通感」。', '元素战技暝色缒索中的宿灵球能额外弹跳2次。\r\n此外，宿灵球命中敌人后，将为该敌人施加「夜暝」效果，持续12秒；对处于「夜暝」效果的影响下的敌人，突破天赋「夜翳的通感」触发的「显象超感」造成的伤害提升50%，该效果需要解锁突破天赋「夜翳的通感」。');
INSERT INTO `genshin_constellation` VALUES (458, 10501, '欧洛伦', 2, '藏蜜酒的王蜂', '施放元素爆发<color=#FFD780FF>黯声回响后，欧洛伦将获得「灵式超感」效果，持续9秒。\r\n\r\n<color=#FFD780FF>灵式超感\r\n获得8%<color=#FFACFFFF>雷元素伤害加成；\r\n此外，持续期间，元素爆发<color=#FFD780FF>黯声回响或<color=#FFD780FF>超音灵眼每额外命中一名敌人，都将进一步使欧洛伦获得8%<color=#FFACFFFF>雷元素伤害加成，至多通过这种方式获得32%<color=#FFACFFFF>雷元素伤害加成。', '施放元素爆发黯声回响后，欧洛伦将获得「灵式超感」效果，持续9秒。\r\n\r\n灵式超感\r\n获得8%雷元素伤害加成；\r\n此外，持续期间，元素爆发黯声回响或超音灵眼每额外命中一名敌人，都将进一步使欧洛伦获得8%雷元素伤害加成，至多通过这种方式获得32%雷元素伤害加成。');
INSERT INTO `genshin_constellation` VALUES (459, 10501, '欧洛伦', 3, '栖地蝠的灵笼', '元素爆发<color=#FFD780FF>黯声回响的技能等级提高3级。\r\n至多提升至15级。', '元素爆发黯声回响的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (460, 10501, '欧洛伦', 4, '如夜风的谜烟', '元素爆发<color=#FFD780FF>黯声回响召唤的<color=#FFD780FF>超音灵眼的旋转速度提升25%。\r\n此外，施放<color=#FFD780FF>黯声回响后，为欧洛伦自己恢复8点元素能量。', '元素爆发黯声回响召唤的超音灵眼的旋转速度提升25%。\r\n此外，施放黯声回响后，为欧洛伦自己恢复8点元素能量。');
INSERT INTO `genshin_constellation` VALUES (461, 10501, '欧洛伦', 5, '为心魂的献礼', '元素战技<color=#FFD780FF>暝色缒索的技能等级提高3级。\r\n至多提升至15级。', '元素战技暝色缒索的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (462, 10501, '欧洛伦', 6, '致深泉的颂赞', '触发突破天赋「夜翳的通感」的「显象超感」后，会使队伍中自己的当前场上角色的攻击力提升10%，持续9秒。该效果至多叠加3层，每层独立计算持续时间。\r\n此外，施放元素爆发<color=#FFD780FF>黯声回响时，将触发一次等同于「显象超感」的效果，造成原本200%的伤害。\r\n该效果需要解锁突破天赋「夜翳的通感」。', '触发突破天赋「夜翳的通感」的「显象超感」后，会使队伍中自己的当前场上角色的攻击力提升10%，持续9秒。该效果至多叠加3层，每层独立计算持续时间。\r\n此外，施放元素爆发黯声回响时，将触发一次等同于「显象超感」的效果，造成原本200%的伤害。\r\n该效果需要解锁突破天赋「夜翳的通感」。');
INSERT INTO `genshin_constellation` VALUES (463, 3501, '七七', 1, '寒苦回向', '寒病鬼差命中被度厄真符标记的敌人时，为七七恢复2点元素能量。', '寒病鬼差命中被度厄真符标记的敌人时，为七七恢复2点元素能量。');
INSERT INTO `genshin_constellation` VALUES (464, 3501, '七七', 2, '冰寒蚀骨', '对受到<color=#99FFFFFF>冰元素影响的敌人，七七的普通攻击与重击造成的伤害提升15%。', '对受到冰元素影响的敌人，七七的普通攻击与重击造成的伤害提升15%。');
INSERT INTO `genshin_constellation` VALUES (465, 3501, '七七', 3, '升天宝诰', '<color=#FFD780FF>仙法·救苦度厄的技能等级提高3级。\r\n至多提升至15级。', '仙法·救苦度厄的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (466, 3501, '七七', 4, '天威压众', '被度厄真符标记的目标，攻击力下降20%。', '被度厄真符标记的目标，攻击力下降20%。');
INSERT INTO `genshin_constellation` VALUES (467, 3501, '七七', 5, '红莲开绽', '<color=#FFD780FF>仙法·寒病鬼差的技能等级提高3级。\r\n至多提升至15级。', '仙法·寒病鬼差的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (468, 3501, '七七', 6, '起死回骸', '施放<color=#FFD780FF>仙法·救苦度厄时，复苏附近队伍中所有倒下的角色，并将其生命值恢复至50%。\r\n该效果每15分钟只能触发一次。', '施放仙法·救苦度厄时，复苏附近队伍中所有倒下的角色，并将其生命值恢复至50%。\r\n该效果每15分钟只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (469, 5201, '雷电将军', 1, '恶曜卜词', '<color=#FFD780FF>诸愿百眼之轮能更加迅速地积攒愿力。元素类型为<color=#FFACFFFF>雷元素的角色施放元素爆发后，积攒的愿力提升80%；其他元素类型的角色施放元素爆发后，积攒的愿力提升20%。', '诸愿百眼之轮能更加迅速地积攒愿力。元素类型为雷元素的角色施放元素爆发后，积攒的愿力提升80%；其他元素类型的角色施放元素爆发后，积攒的愿力提升20%。');
INSERT INTO `genshin_constellation` VALUES (470, 5201, '雷电将军', 2, '斩铁断金', '<color=#FFD780FF>奥义·梦想真说的梦想一刀与梦想一心状态下的雷电将军的攻击将无视敌人60%的防御力。', '奥义·梦想真说的梦想一刀与梦想一心状态下的雷电将军的攻击将无视敌人60%的防御力。');
INSERT INTO `genshin_constellation` VALUES (471, 5201, '雷电将军', 3, '真影旧事', '<color=#FFD780FF>奥义·梦想真说的技能等级提高3级。\r\n至多提升至15级。', '奥义·梦想真说的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (472, 5201, '雷电将军', 4, '誓奉常道', '<color=#FFD780FF>奥义·梦想真说施加的<color=#FFD780FF>梦想一心状态结束后，附近的队伍中所有角色（不包括雷电将军自己）的攻击力提升30%，持续10秒。', '奥义·梦想真说施加的梦想一心状态结束后，附近的队伍中所有角色（不包括雷电将军自己）的攻击力提升30%，持续10秒。');
INSERT INTO `genshin_constellation` VALUES (473, 5201, '雷电将军', 5, '凶将显形', '<color=#FFD780FF>神变·恶曜开眼的技能等级提高3级。\r\n至多提升至15级。', '神变·恶曜开眼的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (474, 5201, '雷电将军', 6, '负愿前行', '处于<color=#FFD780FF>奥义·梦想真说施加的<color=#FFD780FF>梦想一心状态下时，雷电将军的元素爆发伤害命中敌人时，使附近的队伍中所有角色（不包括雷电将军自己）元素爆发的冷却时间缩短1秒。\r\n该效果每1秒至多触发一次，在持续期间内至多触发5次。', '处于奥义·梦想真说施加的梦想一心状态下时，雷电将军的元素爆发伤害命中敌人时，使附近的队伍中所有角色（不包括雷电将军自己）元素爆发的冷却时间缩短1秒。\r\n该效果每1秒至多触发一次，在持续期间内至多触发5次。');
INSERT INTO `genshin_constellation` VALUES (475, 2001, '雷泽', 1, '狼性', '雷泽获取元素晶球或元素微粒后的8秒内，造成的伤害提高10%。', '雷泽获取元素晶球或元素微粒后的8秒内，造成的伤害提高10%。');
INSERT INTO `genshin_constellation` VALUES (476, 2001, '雷泽', 2, '压制', '雷泽攻击生命值低于30%的敌人时，暴击率提高10%。', '雷泽攻击生命值低于30%的敌人时，暴击率提高10%。');
INSERT INTO `genshin_constellation` VALUES (477, 2001, '雷泽', 3, '兽魂', '<color=#FFD780FF>雷牙的技能等级提高3级。\r\n至多提升至15级。', '雷牙的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (478, 2001, '雷泽', 4, '撕咬', '<color=#FFD780FF>利爪与苍雷点按时，会使命中的敌人防御力降低15%，持续7秒。', '利爪与苍雷点按时，会使命中的敌人防御力降低15%，持续7秒。');
INSERT INTO `genshin_constellation` VALUES (479, 2001, '雷泽', 5, '利爪', '<color=#FFD780FF>利爪与苍雷的技能等级提高3级。\r\n至多提升至15级。', '利爪与苍雷的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (480, 2001, '雷泽', 6, '天狼', '每10秒，雷泽的大剑将自动充能，使下一次普通攻击引发落雷，造成100%攻击力的<color=#FFACFFFF>雷元素伤害。\r\n不处于<color=#FFD780FF>雷牙状态下时，若落雷击中敌人，会为雷泽积攒一个<color=#FFD780FF>利爪与苍雷的雷之印。', '每10秒，雷泽的大剑将自动充能，使下一次普通攻击引发落雷，造成100%攻击力的雷元素伤害。\r\n不处于雷牙状态下时，若落雷击中敌人，会为雷泽积攒一个利爪与苍雷的雷之印。');
INSERT INTO `genshin_constellation` VALUES (481, 4501, '罗莎莉亚', 1, '罪之导引', '罗莎莉亚的攻击造成暴击后，自身攻击速度提升10%，普通攻击造成的伤害提升10%，持续4秒。', '罗莎莉亚的攻击造成暴击后，自身攻击速度提升10%，普通攻击造成的伤害提升10%，持续4秒。');
INSERT INTO `genshin_constellation` VALUES (482, 4501, '罗莎莉亚', 2, '无福之地', '<color=#FFD780FF>终命的圣礼创造的冰枪持续时间延长4秒。', '终命的圣礼创造的冰枪持续时间延长4秒。');
INSERT INTO `genshin_constellation` VALUES (483, 4501, '罗莎莉亚', 3, '告解之仪', '<color=#FFD780FF>噬罪的告解的技能等级提高3级。\r\n至多提升至15级。', '噬罪的告解的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (484, 4501, '罗莎莉亚', 4, '苦痛恩典', '<color=#FFD780FF>噬罪的告解造成暴击时，为罗莎莉亚自己恢复5点元素能量。\r\n每次噬罪的告解至多触发1次该效果。', '噬罪的告解造成暴击时，为罗莎莉亚自己恢复5点元素能量。\r\n每次噬罪的告解至多触发1次该效果。');
INSERT INTO `genshin_constellation` VALUES (485, 4501, '罗莎莉亚', 5, '临终祈礼', '<color=#FFD780FF>终命的圣礼的技能等级提高3级。\r\n至多提升至15级。', '终命的圣礼的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (486, 4501, '罗莎莉亚', 6, '代行裁判', '<color=#FFD780FF>终命的圣礼的攻击会使敌人的物理抗性降低20%，持续10秒。', '终命的圣礼的攻击会使敌人的物理抗性降低20%，持续10秒。');
INSERT INTO `genshin_constellation` VALUES (487, 5401, '珊瑚宫心海', 1, '决水于溪', '处于<color=#FFD780FF>海人化羽的仪来羽衣状态下时，珊瑚宫心海普通攻击的最后一击会额外释放一只游鱼，造成相当于珊瑚宫心海生命值上限30%的<color=#80C0FFFF>水元素伤害。\r\n该伤害不被视为普通攻击伤害。', '处于海人化羽的仪来羽衣状态下时，珊瑚宫心海普通攻击的最后一击会额外释放一只游鱼，造成相当于珊瑚宫心海生命值上限30%的水元素伤害。\r\n该伤害不被视为普通攻击伤害。');
INSERT INTO `genshin_constellation` VALUES (488, 5401, '珊瑚宫心海', 2, '波起云海', '基于珊瑚宫心海的生命值上限，珊瑚宫心海对生命值低于或等于50%的角色，通过以下途径进行治疗的回复量获得提升：\r\n·<color=#FFD780FF>海月之誓的化海月：生命值上限的4.5%\r\n·<color=#FFD780FF>海人化羽的普通攻击与重击：生命值上限的0.6%。', '基于珊瑚宫心海的生命值上限，珊瑚宫心海对生命值低于或等于50%的角色，通过以下途径进行治疗的回复量获得提升：\r\n·海月之誓的化海月：生命值上限的4.5%\r\n·海人化羽的普通攻击与重击：生命值上限的0.6%。');
INSERT INTO `genshin_constellation` VALUES (489, 5401, '珊瑚宫心海', 3, '海渚月舟', '<color=#FFD780FF>海人化羽的技能等级提高3级。\r\n至多提升至15级。', '海人化羽的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (490, 5401, '珊瑚宫心海', 4, '月摄千川', '处于<color=#FFD780FF>海人化羽的仪来羽衣状态下时，珊瑚宫心海普通攻击的攻击速度提升10%，并会在普通攻击命中敌人时，恢复0.8点元素能量。\r\n该效果每0.2秒至多触发一次。', '处于海人化羽的仪来羽衣状态下时，珊瑚宫心海普通攻击的攻击速度提升10%，并会在普通攻击命中敌人时，恢复0.8点元素能量。\r\n该效果每0.2秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (491, 5401, '珊瑚宫心海', 5, '百川集海', '<color=#FFD780FF>海月之誓的技能等级提高3级。\r\n至多提升至15级。', '海月之誓的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (492, 5401, '珊瑚宫心海', 6, '珊瑚一心', '处于<color=#FFD780FF>海人化羽的仪来羽衣状态下时，珊瑚宫心海的普通攻击和重击对生命值高于或等于80%的角色进行治疗时，将获得40%<color=#80C0FFFF>水元素伤害加成，持续4秒。', '处于海人化羽的仪来羽衣状态下时，珊瑚宫心海的普通攻击和重击对生命值高于或等于80%的角色进行治疗时，将获得40%水元素伤害加成，持续4秒。');
INSERT INTO `genshin_constellation` VALUES (493, 5301, '早柚', 1, '一心二用之术', '<color=#FFD780FF>呜呼流·影貉缭乱的不倒貉貉的行动将忽视生命值限制，能同时攻击附近的敌人并为角色恢复生命值。', '呜呼流·影貉缭乱的不倒貉貉的行动将忽视生命值限制，能同时攻击附近的敌人并为角色恢复生命值。');
INSERT INTO `genshin_constellation` VALUES (494, 5301, '早柚', 2, '理清逃跑路线', '<color=#FFD780FF>呜呼流·风隐急进获得如下效果：\r\n·点按施放时，风风轮舞踢造成的伤害提高3.3%；\r\n·处于长按施放后的风风轮状态下时，每0.5秒，就会使这次施展的风风轮舞踢造成的伤害提高3.3%。通过这种方式，风风轮舞踢造成的伤害至多可以提高66%。', '呜呼流·风隐急进获得如下效果：\r\n·点按施放时，风风轮舞踢造成的伤害提高3.3%；\r\n·处于长按施放后的风风轮状态下时，每0.5秒，就会使这次施展的风风轮舞踢造成的伤害提高3.3%。通过这种方式，风风轮舞踢造成的伤害至多可以提高66%。');
INSERT INTO `genshin_constellation` VALUES (495, 5301, '早柚', 3, '都交给分身吧', '<color=#FFD780FF>呜呼流·影貉缭乱的技能等级提高3级。\r\n至多提升至15级。', '呜呼流·影貉缭乱的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (496, 5301, '早柚', 4, '偷懒的新方法', '早柚在场上触发扩散反应时，将恢复1.2点元素能量。\r\n该效果每2秒只能触发一次。', '早柚在场上触发扩散反应时，将恢复1.2点元素能量。\r\n该效果每2秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (497, 5301, '早柚', 5, '快是第一奥义', '<color=#FFD780FF>呜呼流·风隐急进的技能等级提高3级。\r\n至多提升至15级。', '呜呼流·风隐急进的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (498, 5301, '早柚', 6, '呼呼大睡时间', '早柚自己通过<color=#FFD780FF>呜呼流·影貉缭乱召唤的不倒貉貉的攻击与回复量，受益于早柚的元素精通。早柚的每点元素精通，能产生如下效果：\r\n·使不倒貉貉的攻击额外造成0.2%攻击力的伤害。通过这种方式至多额外造成400%攻击力的伤害；\r\n·使不倒貉貉的回复量提高3点。通过这种方式，至多提高6000点回复量。', '早柚自己通过呜呼流·影貉缭乱召唤的不倒貉貉的攻击与回复量，受益于早柚的元素精通。早柚的每点元素精通，能产生如下效果：\r\n·使不倒貉貉的攻击额外造成0.2%攻击力的伤害。通过这种方式至多额外造成400%攻击力的伤害；\r\n·使不倒貉貉的回复量提高3点。通过这种方式，至多提高6000点回复量。');
INSERT INTO `genshin_constellation` VALUES (499, 9701, '赛索斯', 1, '封龛谒灵歌', '<color=#FFD780FF>贯影箭的暴击率提升15%。', '贯影箭的暴击率提升15%。');
INSERT INTO `genshin_constellation` VALUES (500, 9701, '赛索斯', 2, '寂秘纸草经', '满足以下任意一项条件时，赛索斯的<color=#FFACFFFF>雷元素伤害加成提升15%，持续10秒，至多叠加2层，每层独立计时：\r\n·通过瞄准射击消耗元素能量，此条件需要解锁突破天赋「黑鸢的密喻」；\r\n·通过<color=#FFD780FF>古仪·鸣砂掣雷触发元素反应恢复元素能量；\r\n·施放<color=#FFD780FF>秘仪·瞑光贯影。', '满足以下任意一项条件时，赛索斯的雷元素伤害加成提升15%，持续10秒，至多叠加2层，每层独立计时：\r\n·通过瞄准射击消耗元素能量，此条件需要解锁突破天赋「黑鸢的密喻」；\r\n·通过古仪·鸣砂掣雷触发元素反应恢复元素能量；\r\n·施放秘仪·瞑光贯影。');
INSERT INTO `genshin_constellation` VALUES (501, 9701, '赛索斯', 3, '月升哲贤颂', '<color=#FFD780FF>普通攻击·王家苇箭术的技能等级提高3级。\r\n至多提升至15级。', '普通攻击·王家苇箭术的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (502, 9701, '赛索斯', 4, '真念鸵羽集', '<color=#FFD780FF>贯影箭或<color=#FFD780FF>瞑弦矢命中2名及以上的敌人时，队伍中附近的所有角色的元素精通提升80点，持续10秒。', '贯影箭或瞑弦矢命中2名及以上的敌人时，队伍中附近的所有角色的元素精通提升80点，持续10秒。');
INSERT INTO `genshin_constellation` VALUES (503, 9701, '赛索斯', 5, '荒神烈沙录', '<color=#FFD780FF>秘仪·瞑光贯影的技能等级提高3级。\r\n至多提升至15级。', '秘仪·瞑光贯影的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (504, 9701, '赛索斯', 6, '巡日塔门书', '<color=#FFD780FF>贯影箭命中敌人后，将返还因突破天赋「黑鸢的密喻」消耗的元素能量，此效果每15秒至多触发一次，需要解锁突破天赋「黑鸢的密喻」。', '贯影箭命中敌人后，将返还因突破天赋「黑鸢的密喻」消耗的元素能量，此效果每15秒至多触发一次，需要解锁突破天赋「黑鸢的密喻」。');
INSERT INTO `genshin_constellation` VALUES (505, 6301, '申鹤', 1, '心斋', '<color=#FFD780FF>仰灵威召将役咒的可使用次数增加1次。', '仰灵威召将役咒的可使用次数增加1次。');
INSERT INTO `genshin_constellation` VALUES (506, 6301, '申鹤', 2, '定蒙', '<color=#FFD780FF>神女遣灵真诀的持续时间延长6秒。领域中的当前场上角色，<color=#99FFFFFF>冰元素伤害的暴击伤害提高15%。', '神女遣灵真诀的持续时间延长6秒。领域中的当前场上角色，冰元素伤害的暴击伤害提高15%。');
INSERT INTO `genshin_constellation` VALUES (507, 6301, '申鹤', 3, '潜虚', '<color=#FFD780FF>仰灵威召将役咒的技能等级提高3级。\r\n至多提升至15级。', '仰灵威召将役咒的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (508, 6301, '申鹤', 4, '洞观', '处于申鹤自己施加的<color=#FFD780FF>「冰翎」状态下的角色，触发「冰翎」的伤害增加时，申鹤将获得一层「霜霄诀」：\r\n·申鹤施放<color=#FFD780FF>仰灵威召将役咒时，将清除所有「霜霄诀」，并根据清除的层数，每层使本次仰灵威召将役咒造成的伤害提高5%；\r\n·该效果至多叠加50次，持续60秒。', '处于申鹤自己施加的「冰翎」状态下的角色，触发「冰翎」的伤害增加时，申鹤将获得一层「霜霄诀」：\r\n·申鹤施放仰灵威召将役咒时，将清除所有「霜霄诀」，并根据清除的层数，每层使本次仰灵威召将役咒造成的伤害提高5%；\r\n·该效果至多叠加50次，持续60秒。');
INSERT INTO `genshin_constellation` VALUES (509, 6301, '申鹤', 5, '化神', '<color=#FFD780FF>神女遣灵真诀的技能等级提高3级。\r\n至多提升至15级。', '神女遣灵真诀的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (510, 6301, '申鹤', 6, '忘玄', '角色通过普通攻击伤害与重击伤害触发<color=#FFD780FF>「冰翎」的效果时，将不再会减少「冰翎」的生效次数。', '角色通过普通攻击伤害与重击伤害触发「冰翎」的效果时，将不再会减少「冰翎」的生效次数。');
INSERT INTO `genshin_constellation` VALUES (511, 5901, '鹿野院平藏', 1, '称名少年事件簿', '鹿野院平藏登场后的5秒内，普通攻击的攻击速度提升15%，并获得1层<color=#FFD780FF>勠心拳的「变格」效果，该效果每10秒最多触发一次。', '鹿野院平藏登场后的5秒内，普通攻击的攻击速度提升15%，并获得1层勠心拳的「变格」效果，该效果每10秒最多触发一次。');
INSERT INTO `genshin_constellation` VALUES (512, 5901, '鹿野院平藏', 2, '殊解诸因探案集', '<color=#FFD780FF>聚风蹴产生的缉拿风穴的牵引效果获得提升，并将持续时间延长至1秒。', '聚风蹴产生的缉拿风穴的牵引效果获得提升，并将持续时间延长至1秒。');
INSERT INTO `genshin_constellation` VALUES (513, 5901, '鹿野院平藏', 3, '暗文隐语谜题册', '<color=#FFD780FF>勠心拳的技能等级提高3级。\r\n至多提升至15级。', '勠心拳的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (514, 5901, '鹿野院平藏', 4, '虚言假说百物语', '在一次<color=#FFD780FF>聚风蹴中，「聚风真眼」在第一次爆发后，将为鹿野院平藏恢复9点元素能量，此后每次爆发，都将分别为鹿野院平藏额外恢复1.5点元素能量，\r\n一次<color=#FFD780FF>聚风蹴，至多通过这种方式为鹿野院平藏恢复13.5点元素能量。', '在一次聚风蹴中，「聚风真眼」在第一次爆发后，将为鹿野院平藏恢复9点元素能量，此后每次爆发，都将分别为鹿野院平藏额外恢复1.5点元素能量，\r\n一次聚风蹴，至多通过这种方式为鹿野院平藏恢复13.5点元素能量。');
INSERT INTO `genshin_constellation` VALUES (515, 5901, '鹿野院平藏', 5, '禁室密所大图鉴', '<color=#FFD780FF>聚风蹴的技能等级提高3级。\r\n至多提升至15级。', '聚风蹴的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (516, 5901, '鹿野院平藏', 6, '奇想天开捕物帐', '施放<color=#FFD780FF>勠心拳时，每层「变格」都将为本次勠心拳提升4%暴击率。拥有「正论」时，本次勠心拳的暴击伤害将提升32%。', '施放勠心拳时，每层「变格」都将为本次勠心拳提升4%暴击率。拥有「正论」时，本次勠心拳的暴击伤害将提升32%。');
INSERT INTO `genshin_constellation` VALUES (517, 9501, '希格雯', 1, '「最快乐的精灵，可否懂得焦虑」', '<color=#FFD780FF>弹跳水疗法的激愈水球能额外弹跳3次；前3次弹跳不会使较大激愈水球变小。\r\n此外，突破天赋「应有适当的休憩」的效果获得提升：激愈水球弹跳时，将为希格雯赋予1层静养计数，并使静养计数产生的伤害值提升改为：希格雯的生命值上限超过30000的部分，每1000点生命值上限将提升100点，通过这种方式，至多提升3500点伤害。此效果需要解锁突破天赋「应有适当的休憩」。', '弹跳水疗法的激愈水球能额外弹跳3次；前3次弹跳不会使较大激愈水球变小。\r\n此外，突破天赋「应有适当的休憩」的效果获得提升：激愈水球弹跳时，将为希格雯赋予1层静养计数，并使静养计数产生的伤害值提升改为：希格雯的生命值上限超过30000的部分，每1000点生命值上限将提升100点，通过这种方式，至多提升3500点伤害。此效果需要解锁突破天赋「应有适当的休憩」。');
INSERT INTO `genshin_constellation` VALUES (518, 9501, '希格雯', 2, '「最仁慈的精灵，可否化解仇敌」', '施放<color=#FFD780FF>弹跳水疗法与<color=#FFD780FF>过饱和心意注射时，将生成一个伤害吸收量等同于生命值上限30%的水球护盾，对<color=#80C0FFFF>水元素伤害有250%的吸收效果，持续直到施放完成。\r\n此外，弹跳水疗法抛出的激愈水球或过饱和心意注射命中敌人后，该敌人的<color=#80C0FFFF>水元素抗性降低35%，持续8秒。', '施放弹跳水疗法与过饱和心意注射时，将生成一个伤害吸收量等同于生命值上限30%的水球护盾，对水元素伤害有250%的吸收效果，持续直到施放完成。\r\n此外，弹跳水疗法抛出的激愈水球或过饱和心意注射命中敌人后，该敌人的水元素抗性降低35%，持续8秒。');
INSERT INTO `genshin_constellation` VALUES (519, 9501, '希格雯', 3, '「最健康的精灵，可否疗愈热症」', '<color=#FFD780FF>弹跳水疗法的技能等级提高3级。\r\n至多提升至15级。', '弹跳水疗法的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (520, 9501, '希格雯', 4, '「最美丽的精灵，可否拒绝衰朽」', '<color=#FFD780FF>过饱和心意注射的持续时间延长3秒。', '过饱和心意注射的持续时间延长3秒。');
INSERT INTO `genshin_constellation` VALUES (521, 9501, '希格雯', 5, '「最幸福的精灵，可否消却折磨」', '<color=#FFD780FF>过饱和心意注射的技能等级提高3级。\r\n至多提升至15级。', '过饱和心意注射的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (522, 9501, '希格雯', 6, '「最光辉的精灵，可否为我祷告」', '希格雯进行治疗时，将基于生命值上限，提升自己的<color=#FFD780FF>过饱和心意注射的暴击率和暴击伤害：每1000点生命值上限都将提升0.4%暴击率与2.2%暴击伤害，持续15秒。至多通过这种方式提升20%暴击率与110%暴击伤害。', '希格雯进行治疗时，将基于生命值上限，提升自己的过饱和心意注射的暴击率和暴击伤害：每1000点生命值上限都将提升0.4%暴击率与2.2%暴击伤害，持续15秒。至多通过这种方式提升20%暴击率与110%暴击伤害。');
INSERT INTO `genshin_constellation` VALUES (523, 11401, '丝柯克', 1, '湮远', '突破天赋<color=#FFD780FF>理外之理的效果获得强化：每汲取一枚虚境裂隙，就将召唤一枚晶刃攻击附近的敌人，造成相当于丝柯克攻击力500%的<color=#99FFFFFF>冰元素伤害，该伤害视为重击伤害。\r\n需要解锁突破天赋「理外之理」。', '突破天赋**理外之理**的效果获得强化：每汲取一枚虚境裂隙，就将召唤一枚晶刃攻击附近的敌人，造成相当于丝柯克攻击力500%的冰元素伤害，该伤害视为重击伤害。\r\n需要解锁突破天赋「理外之理」。');
INSERT INTO `genshin_constellation` VALUES (524, 11401, '丝柯克', 2, '坠渊', '施放元素战技<color=#FFD780FF>极恶技·闪后，丝柯克将额外获得10点<color=#FFD780FF>蛇之狡谋。\r\n施放元素爆发<color=#FFD780FF>极恶技·灭时，提升本次元素爆发伤害的效果，至多额外计入10点蛇之狡谋。\r\n此外，丝柯克施放<color=#FFD780FF>七相一闪模式下的特殊元素爆发<color=#FFD780FF>极恶技·尽后的12.5秒内，攻击力提升70%，该效果会在丝柯克退出七相一闪模式时解除。', '施放元素战技极恶技·闪后，丝柯克将额外获得10点**蛇之狡谋**。\r\n施放元素爆发极恶技·灭时，提升本次元素爆发伤害的效果，至多额外计入10点蛇之狡谋。\r\n此外，丝柯克施放**七相一闪**模式下的特殊元素爆发极恶技·尽后的12.5秒内，攻击力提升70%，该效果会在丝柯克退出七相一闪模式时解除。');
INSERT INTO `genshin_constellation` VALUES (525, 11401, '丝柯克', 3, '罪缘', '元素爆发<color=#FFD780FF>极恶技·灭的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**极恶技·灭**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (526, 11401, '丝柯克', 4, '流断', '突破天赋<color=#FFD780FF>万流归寂的效果获得强化：每层死河渡断效果还会使丝柯克的攻击力提升10%/20%/40%。\r\n需要解锁突破天赋「万流归寂」。', '突破天赋**万流归寂**的效果获得强化：每层死河渡断效果还会使丝柯克的攻击力提升10%/20%/40%。\r\n需要解锁突破天赋「万流归寂」。');
INSERT INTO `genshin_constellation` VALUES (527, 11401, '丝柯克', 5, '结愿', '元素战技<color=#FFD780FF>极恶技·闪的技能等级提高3级。\r\n至多提升至15级', '元素战技**极恶技·闪**的技能等级提高3级。\r\n至多提升至15级');
INSERT INTO `genshin_constellation` VALUES (528, 11401, '丝柯克', 6, '至源', '丝柯克每通过突破天赋<color=#FFD780FF>理外之理的效果汲取一枚虚境裂隙，就会获得一层极恶技·斩效果，丝柯克可以消耗该效果进行协同攻击，并降低在<color=#FFD780FF>七相一闪模式下受到的伤害，该效果持续15秒，至多叠加3层，每层独立计算持续时间。\r\n需要解锁突破天赋「理外之理」。\r\n\r\n<color=#FFD780FF>极恶技·斩\r\n·施放元素爆发<color=#FFD780FF>极恶技·灭时，将消耗所有的<color=#FFD780FF>极恶技·斩层数进行协同攻击，每层<color=#FFD780FF>极恶技·斩会造成相当于丝柯克攻击力750%的<color=#99FFFFFF>冰元素伤害，该伤害视为元素爆发伤害；\r\n·丝柯克在七相一闪模式下进行的普通攻击，第三段攻击或第五段攻击命中敌人时，将消耗一层<color=#FFD780FF>极恶技·斩，进行3次协同攻击，每次协同攻击造成相当于丝柯克攻击力180%的<color=#99FFFFFF>冰元素伤害，该伤害视为普通攻击伤害；\r\n·丝柯克在七相一闪模式下受到伤害时，将消耗一层<color=#FFD780FF>极恶技·斩，使本次受到的伤害降低80%，并对附近的敌人进行3次攻击，每次攻击造成相当于丝柯克攻击力180%的<color=#99FFFFFF>冰元素伤害，该伤害视为重击伤害。', '丝柯克每通过突破天赋**理外之理**的效果汲取一枚虚境裂隙，就会获得一层极恶技·斩效果，丝柯克可以消耗该效果进行协同攻击，并降低在**七相一闪**模式下受到的伤害，该效果持续15秒，至多叠加3层，每层独立计算持续时间。\r\n需要解锁突破天赋「理外之理」。\r\n\r\n极恶技·斩\r\n·施放元素爆发极恶技·灭时，将消耗所有的极恶技·斩层数进行协同攻击，每层极恶技·斩会造成相当于丝柯克攻击力750%的冰元素伤害，该伤害视为元素爆发伤害；\r\n·丝柯克在七相一闪模式下进行的普通攻击，第三段攻击或第五段攻击命中敌人时，将消耗一层极恶技·斩，进行3次协同攻击，每次协同攻击造成相当于丝柯克攻击力180%的冰元素伤害，该伤害视为普通攻击伤害；\r\n·丝柯克在七相一闪模式下受到伤害时，将消耗一层极恶技·斩，使本次受到的伤害降低80%，并对附近的敌人进行3次攻击，每次攻击造成相当于丝柯克攻击力180%的冰元素伤害，该伤害视为重击伤害。');
INSERT INTO `genshin_constellation` VALUES (529, 4301, '砂糖', 1, '堆叠真空域', '<color=#FFD780FF>风灵作成·陆叁零捌的可使用次数增加1次。', '风灵作成·陆叁零捌的可使用次数增加1次。');
INSERT INTO `genshin_constellation` VALUES (530, 4301, '砂糖', 2, '不羁型贝特', '<color=#FFD780FF>禁·风灵作成·柒伍同构贰型的技能持续时间延长2秒。', '禁·风灵作成·柒伍同构贰型的技能持续时间延长2秒。');
INSERT INTO `genshin_constellation` VALUES (531, 4301, '砂糖', 3, '零失误少女', '<color=#FFD780FF>风灵作成·陆叁零捌的技能等级提高3级。\r\n至多提升至15级。', '风灵作成·陆叁零捌的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (532, 4301, '砂糖', 4, '炼金的偏执', '砂糖的普通攻击或者重击累计命中敌人7次，<color=#FFD780FF>风灵作成·陆叁零捌的冷却时间就会随机减少1-7秒。\r\n每0.1秒至多计数一次。', '砂糖的普通攻击或者重击累计命中敌人7次，风灵作成·陆叁零捌的冷却时间就会随机减少1-7秒。\r\n每0.1秒至多计数一次。');
INSERT INTO `genshin_constellation` VALUES (533, 4301, '砂糖', 5, '认真普通瓶', '<color=#FFD780FF>禁·风灵作成·柒伍同构贰型的技能等级提高3级。\r\n至多提升至15级。', '禁·风灵作成·柒伍同构贰型的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (534, 4301, '砂糖', 6, '混元熵增论', '<color=#FFD780FF>禁·风灵作成·柒伍同构贰型如果发生了元素转化，则使队伍中所有角色在技能持续时间内获得20%的对应元素伤害加成。', '禁·风灵作成·柒伍同构贰型如果发生了元素转化，则使队伍中所有角色在技能持续时间内获得20%的对应元素伤害加成。');
INSERT INTO `genshin_constellation` VALUES (535, 3301, '达达利亚', 1, '魔王武装·遏浪', '<color=#FFD780FF>魔王武装·狂澜的冷却时间降低20%。', '魔王武装·狂澜的冷却时间降低20%。');
INSERT INTO `genshin_constellation` VALUES (536, 3301, '达达利亚', 2, '魔王武装·暗流', '处于断流效果影响下的敌人被击败时，为达达利亚恢复4点元素能量。', '处于断流效果影响下的敌人被击败时，为达达利亚恢复4点元素能量。');
INSERT INTO `genshin_constellation` VALUES (537, 3301, '达达利亚', 3, '深渊之灾·纷争涡源', '<color=#FFD780FF>魔王武装·狂澜的技能等级提高3级。\r\n至多提升至15级。', '魔王武装·狂澜的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (538, 3301, '达达利亚', 4, '深渊之灾·凝水盛放', '每4秒，场上存在达达利亚自身施加的断流效果时，若达达利亚当前处于<color=#FFD780FF>魔王武装·狂澜的近战状态，则触发断流·斩；否则，触发断流·闪。\r\n通过此命之座触发的断流·斩与断流·闪不受这两种断流各自的触发间隔限制，也不会影响其触发间隔。', '每4秒，场上存在达达利亚自身施加的断流效果时，若达达利亚当前处于魔王武装·狂澜的近战状态，则触发断流·斩；否则，触发断流·闪。\r\n通过此命之座触发的断流·斩与断流·闪不受这两种断流各自的触发间隔限制，也不会影响其触发间隔。');
INSERT INTO `genshin_constellation` VALUES (539, 3301, '达达利亚', 5, '极恶技·斩水斩雨', '<color=#FFD780FF>极恶技·尽灭闪的技能等级提高3级。\r\n至多提升至15级。', '极恶技·尽灭闪的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (540, 3301, '达达利亚', 6, '极恶技·天使灭尽', '在近战状态下施放<color=#FFD780FF>极恶技·尽灭闪时，清除<color=#FFD780FF>魔王武装·狂澜的冷却时间。\r\n该效果会在回到远程状态后触发。', '在近战状态下施放极恶技·尽灭闪时，清除魔王武装·狂澜的冷却时间。\r\n该效果会在回到远程状态后触发。');
INSERT INTO `genshin_constellation` VALUES (541, 5001, '托马', 1, '同袍的义理', '处于托马自己的<color=#FFD780FF>烈烧佑命护盾庇护下的角色（除了托马自己）受到攻击时，托马自己的<color=#FFD780FF>烈烧佑命之侍护的冷却时间减少3秒，<color=#FFD780FF>真红炽火之大铠的冷却时间减少3秒。\r\n该效果每20秒至多触发一次。', '处于托马自己的烈烧佑命护盾庇护下的角色（除了托马自己）受到攻击时，托马自己的烈烧佑命之侍护的冷却时间减少3秒，真红炽火之大铠的冷却时间减少3秒。\r\n该效果每20秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (542, 5001, '托马', 2, '僚佐的才巧', '<color=#FFD780FF>真红炽火之大铠的持续时间延长3秒。', '真红炽火之大铠的持续时间延长3秒。');
INSERT INTO `genshin_constellation` VALUES (543, 5001, '托马', 3, '御敌的执定', '<color=#FFD780FF>烈烧佑命之侍护的技能等级提高3级。\r\n至多提升至15级。', '烈烧佑命之侍护的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (544, 5001, '托马', 4, '用臣的久计', '施放<color=#FFD780FF>真红炽火之大铠后，为托马恢复15点元素能量。', '施放真红炽火之大铠后，为托马恢复15点元素能量。');
INSERT INTO `genshin_constellation` VALUES (545, 5001, '托马', 5, '野火的豪烈', '<color=#FFD780FF>真红炽火之大铠的技能等级提高3级。\r\n至多提升至15级。', '真红炽火之大铠的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (546, 5001, '托马', 6, '炽烧的至心', '获取或刷新<color=#FFD780FF>烈烧佑命护盾时，队伍中所有角色的普通攻击，重击与下落攻击造成的伤害提升15%，持续6秒。', '获取或刷新烈烧佑命护盾时，队伍中所有角色的普通攻击，重击与下落攻击造成的伤害提升15%，持续6秒。');
INSERT INTO `genshin_constellation` VALUES (547, 6901, '提纳里', 1, '由根须断定肇始', '提纳里重击的暴击率提高15%。', '提纳里重击的暴击率提高15%。');
INSERT INTO `genshin_constellation` VALUES (548, 6901, '提纳里', 2, '由茎干剖析来缘', '当<color=#FFD780FF>识果种雷的识蕴领域中存在敌人时，提纳里获得20%<color=#99FF88FF>草元素伤害加成。\r\n识蕴领域持续时间结束或其中不存在敌人后，该效果至多持续6秒。', '当识果种雷的识蕴领域中存在敌人时，提纳里获得20%草元素伤害加成。\r\n识蕴领域持续时间结束或其中不存在敌人后，该效果至多持续6秒。');
INSERT INTO `genshin_constellation` VALUES (549, 6901, '提纳里', 3, '由枝节知晓造化', '<color=#FFD780FF>造生缠藤箭的技能等级提高3级。\r\n至多提升至15级。', '造生缠藤箭的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (550, 6901, '提纳里', 4, '由片叶管窥枯荣', '施放<color=#FFD780FF>造生缠藤箭时，队伍中附近的所有角色的元素精通提升60点，持续8秒。若造生缠藤箭触发了燃烧、绽放、月绽放、原激化或蔓激化反应，元素精通将进一步提升60点，并刷新该状态的持续时间。', '施放造生缠藤箭时，队伍中附近的所有角色的元素精通提升60点，持续8秒。若造生缠藤箭触发了燃烧、绽放、月绽放、原激化或蔓激化反应，元素精通将进一步提升60点，并刷新该状态的持续时间。');
INSERT INTO `genshin_constellation` VALUES (551, 6901, '提纳里', 5, '由繁花明了悟觉', '<color=#FFD780FF>识果种雷的技能等级提高3级。\r\n至多提升至15级。', '识果种雷的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (552, 6901, '提纳里', 6, '由硕实品论应果', '<color=#FFD780FF>花筥箭所需的蓄力时间减少0.9秒，并在命中后能产生1枚额外的藏蕴花矢，能造成提纳里攻击力150%的伤害。', '花筥箭所需的蓄力时间减少0.9秒，并在命中后能产生1枚额外的藏蕴花矢，能造成提纳里攻击力150%的伤害。');
INSERT INTO `genshin_constellation` VALUES (553, 704, '旅行者 (风元素)', 1, '回转的怒风', '<color=#FFD780FF>风涡剑可将周围5米内的敌人与物体缓慢牵引到角色面前。', '风涡剑可将周围5米内的敌人与物体缓慢牵引到角色面前。');
INSERT INTO `genshin_constellation` VALUES (554, 704, '旅行者 (风元素)', 2, '革新的旋风', '元素充能效率提升16%。', '元素充能效率提升16%。');
INSERT INTO `genshin_constellation` VALUES (555, 704, '旅行者 (风元素)', 3, '天地的刚风', '<color=#FFD780FF>风息激荡的技能等级提高3级。\r\n至多提升至15级。', '风息激荡的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (556, 704, '旅行者 (风元素)', 4, '眷护的和风', '<color=#FFD780FF>风涡剑持续期间，受到的伤害降低10%。', '风涡剑持续期间，受到的伤害降低10%。');
INSERT INTO `genshin_constellation` VALUES (557, 704, '旅行者 (风元素)', 5, '群星的涡风', '<color=#FFD780FF>风涡剑的技能等级提高3级。\r\n至多提升至15级。', '风涡剑的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (558, 704, '旅行者 (风元素)', 6, '纠缠的信风', '受到<color=#FFD780FF>风息激荡伤害的目标，<color=#80FFD7FF>风元素抗性下降20%。\r\n如果产生了元素转化，那么对应元素抗性也下降20%。', '受到风息激荡伤害的目标，风元素抗性下降20%。\r\n如果产生了元素转化，那么对应元素抗性也下降20%。');
INSERT INTO `genshin_constellation` VALUES (559, 708, '旅行者 (草元素)', 1, '寄身的倚草', '<color=#FFD780FF>草缘剑命中敌人后，将为旅行者恢复3.5点元素能量。', '草缘剑命中敌人后，将为旅行者恢复3.5点元素能量。');
INSERT INTO `genshin_constellation` VALUES (560, 708, '旅行者 (草元素)', 2, '健韧的劲草', '<color=#FFD780FF>草灯莲的存在时间延长3秒。', '草灯莲的存在时间延长3秒。');
INSERT INTO `genshin_constellation` VALUES (561, 708, '旅行者 (草元素)', 3, '婆娑的瑶草', '<color=#FFD780FF>草缘剑的技能等级提高3级。\r\n至多提升至15级。', '草缘剑的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (562, 708, '旅行者 (草元素)', 4, '如饴的蜜草', '<color=#FFD780FF>草灯莲发生莲光幻变转化后，将获得5层突破天赋「蔓生的埜草」的莲光遍照效果。\r\n需要解锁突破天赋「蔓生的埜草」。', '草灯莲发生莲光幻变转化后，将获得5层突破天赋「蔓生的埜草」的莲光遍照效果。\r\n需要解锁突破天赋「蔓生的埜草」。');
INSERT INTO `genshin_constellation` VALUES (563, 708, '旅行者 (草元素)', 5, '迅生的丰草', '<color=#FFD780FF>偃草若化的技能等级提高3级。\r\n至多提升至15级。', '偃草若化的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (564, 708, '旅行者 (草元素)', 6, '蕴思的霜草', '处于<color=#FFD780FF>草灯莲的莲光遍照效果影响下的角色获得12%<color=#99FF88FF>草元素伤害加成；若草灯莲发生过莲光幻变转化，还将获得12%对应元素伤害加成。', '处于草灯莲的莲光遍照效果影响下的角色获得12%草元素伤害加成；若草灯莲发生过莲光幻变转化，还将获得12%对应元素伤害加成。');
INSERT INTO `genshin_constellation` VALUES (565, 707, '旅行者 (雷元素)', 1, '丰穰的春雷', '施放<color=#FFD780FF>雷影剑能产生的丰穰勾玉数量提升至3枚。', '施放雷影剑能产生的丰穰勾玉数量提升至3枚。');
INSERT INTO `genshin_constellation` VALUES (566, 707, '旅行者 (雷元素)', 2, '震怒的苍雷', '<color=#FFD780FF>雷轰电转的威光落雷命中敌人后，会使敌人的<color=#FFACFFFF>雷元素抗性降低15%，持续8秒。', '雷轰电转的威光落雷命中敌人后，会使敌人的雷元素抗性降低15%，持续8秒。');
INSERT INTO `genshin_constellation` VALUES (567, 707, '旅行者 (雷元素)', 3, '连延的远雷', '<color=#FFD780FF>雷轰电转的技能等级提高3级。\r\n至多提升至15级。', '雷轰电转的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (568, 707, '旅行者 (雷元素)', 4, '难测的云雷', '角色获取<color=#FFD780FF>雷影剑产生的丰穰勾玉时，若该角色的当前元素能量低于35%，丰穰勾玉恢复的元素能量提高100%。', '角色获取雷影剑产生的丰穰勾玉时，若该角色的当前元素能量低于35%，丰穰勾玉恢复的元素能量提高100%。');
INSERT INTO `genshin_constellation` VALUES (569, 707, '旅行者 (雷元素)', 5, '荒野的霆雷', '<color=#FFD780FF>雷影剑的技能等级提高3级。\r\n至多提升至15级。', '雷影剑的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (570, 707, '旅行者 (雷元素)', 6, '撼世的神雷', '<color=#FFD780FF>雷轰电转每引发2次威光落雷，则大幅增强下一次威光落雷，造成原本200%的伤害，并为当前角色额外恢复1点元素能量。', '雷轰电转每引发2次威光落雷，则大幅增强下一次威光落雷，造成原本200%的伤害，并为当前角色额外恢复1点元素能量。');
INSERT INTO `genshin_constellation` VALUES (571, 706, '旅行者 (岩元素)', 1, '巍然的青岩', '队伍中角色处于<color=#FFD780FF>岩潮叠嶂的岩嶂包围中时，暴击率提升10%，并提高抗打断能力。', '队伍中角色处于岩潮叠嶂的岩嶂包围中时，暴击率提升10%，并提高抗打断能力。');
INSERT INTO `genshin_constellation` VALUES (572, 706, '旅行者 (岩元素)', 2, '不稳的熔岩', '<color=#FFD780FF>星陨剑的荒星被摧毁时会再度发生爆炸，造成等同于星陨剑伤害的额外<color=#FFE699FF>岩元素范围伤害。', '星陨剑的荒星被摧毁时会再度发生爆炸，造成等同于星陨剑伤害的额外岩元素范围伤害。');
INSERT INTO `genshin_constellation` VALUES (573, 706, '旅行者 (岩元素)', 3, '八方之岩', '<color=#FFD780FF>岩潮叠嶂的技能等级提高3级。\r\n至多提升至15级。', '岩潮叠嶂的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (574, 706, '旅行者 (岩元素)', 4, '险峻的重岩', '<color=#FFD780FF>岩潮叠嶂引发的震荡波每击中一个敌人，都会恢复5点元素能量。\r\n通过这种方式，一次至多恢复25点元素能量。', '岩潮叠嶂引发的震荡波每击中一个敌人，都会恢复5点元素能量。\r\n通过这种方式，一次至多恢复25点元素能量。');
INSERT INTO `genshin_constellation` VALUES (575, 706, '旅行者 (岩元素)', 5, '天坠之岩', '<color=#FFD780FF>星陨剑的技能等级提高3级。\r\n至多提升至15级。', '星陨剑的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (576, 706, '旅行者 (岩元素)', 6, '永世的磐岩', '<color=#FFD780FF>岩潮叠嶂的岩嶂持续时间延长5秒；\r\n<color=#FFD780FF>星陨剑的荒星持续时间延长10秒。', '岩潮叠嶂的岩嶂持续时间延长5秒；\r\n星陨剑的荒星持续时间延长10秒。');
INSERT INTO `genshin_constellation` VALUES (577, 703, '旅行者 (水元素)', 1, '微澜的湖水', '拾取源水之滴后，旅行者将恢复2点元素能量。\r\n需要解锁突破天赋「无染的澈水」。', '拾取源水之滴后，旅行者将恢复2点元素能量。\r\n需要解锁突破天赋「无染的澈水」。');
INSERT INTO `genshin_constellation` VALUES (578, 703, '旅行者 (水元素)', 2, '潺涓的碧水', '<color=#FFD780FF>扬水制流的浮水泡沫移动的速度降低30%，持续时间延长3秒。', '扬水制流的浮水泡沫移动的速度降低30%，持续时间延长3秒。');
INSERT INTO `genshin_constellation` VALUES (579, 703, '旅行者 (水元素)', 3, '激荡的波水', '<color=#FFD780FF>水纹剑的技能等级提高3级。\r\n至多提升至15级。', '水纹剑的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (580, 703, '旅行者 (水元素)', 4, '倾落的迸水', '施放<color=#FFD780FF>水纹剑时，将生成一个伤害吸收量等于生命值上限10%的水纹护盾，对<color=#80C0FFFF>水元素伤害有250%的吸收效果，持续直到施放完成。\r\n每2秒一次，露滴命中敌人后，如果旅行者处于水纹护盾的庇护下，则将水纹护盾的伤害吸收量补充至旅行者生命值上限的10%；如果不处于水纹护盾的庇护下，则重新产生水纹护盾。', '施放水纹剑时，将生成一个伤害吸收量等于生命值上限10%的水纹护盾，对水元素伤害有250%的吸收效果，持续直到施放完成。\r\n每2秒一次，露滴命中敌人后，如果旅行者处于水纹护盾的庇护下，则将水纹护盾的伤害吸收量补充至旅行者生命值上限的10%；如果不处于水纹护盾的庇护下，则重新产生水纹护盾。');
INSERT INTO `genshin_constellation` VALUES (581, 703, '旅行者 (水元素)', 5, '洄旋的曲水', '<color=#FFD780FF>扬水制流的技能等级提高3级。\r\n至多提升至15级。', '扬水制流的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (582, 703, '旅行者 (水元素)', 6, '公义的潮水', '旅行者拾取源水之滴时，还将为队伍中附近的生命值百分比最低的角色，基于其生命值上限的6%，恢复生命值。', '旅行者拾取源水之滴时，还将为队伍中附近的生命值百分比最低的角色，基于其生命值上限的6%，恢复生命值。');
INSERT INTO `genshin_constellation` VALUES (583, 702, '旅行者 (火元素)', 1, '流光的星火', '<color=#FFD780FF>焰烈之槛或<color=#FFD780FF>灼火之槛存在期间，当前场上角色造成的伤害提升6%；若当前场上角色处于夜魂加持状态，造成的伤害还会提升9%。', '焰烈之槛或灼火之槛存在期间，当前场上角色造成的伤害提升6%；若当前场上角色处于夜魂加持状态，造成的伤害还会提升9%。');
INSERT INTO `genshin_constellation` VALUES (584, 702, '旅行者 (火元素)', 2, '长明的烛火', '施放元素战技<color=#FFD780FF>流火剑后的12秒内，队伍中附近的角色对敌人触发<color=#FF9999FF>火元素相关反应后，将为旅行者恢复14点夜魂值，每次施放元素战技<color=#FFD780FF>流火剑至多通过这种方式恢复28点夜魂值。', '施放元素战技流火剑后的12秒内，队伍中附近的角色对敌人触发火元素相关反应后，将为旅行者恢复14点夜魂值，每次施放元素战技流火剑至多通过这种方式恢复28点夜魂值。');
INSERT INTO `genshin_constellation` VALUES (585, 702, '旅行者 (火元素)', 3, '燧传的烽火', '元素战技<color=#FFD780FF>流火剑的技能等级提高3级。\r\n至多提升至15级。', '元素战技流火剑的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (586, 702, '旅行者 (火元素)', 4, '燎灼的烈火', '施放元素爆发<color=#FFD780FF>灼火燎原后，旅行者获得20%<color=#FF9999FF>火元素伤害加成，持续9秒。', '施放元素爆发灼火燎原后，旅行者获得20%火元素伤害加成，持续9秒。');
INSERT INTO `genshin_constellation` VALUES (587, 702, '旅行者 (火元素)', 5, '不灭的薪火', '元素爆发<color=#FFD780FF>灼火燎原的技能等级提高3级。\r\n至多提升至15级。', '元素爆发灼火燎原的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (588, 702, '旅行者 (火元素)', 6, '永燃的圣火', '处于夜魂加持状态下时，旅行者的普通攻击、重击与下落攻击将转为具有夜魂性质且无法被附魔覆盖的<color=#FF9999FF>火元素伤害，且这些攻击的暴击伤害提升40%。', '处于夜魂加持状态下时，旅行者的普通攻击、重击与下落攻击将转为具有夜魂性质且无法被附魔覆盖的火元素伤害，且这些攻击的暴击伤害提升40%。');
INSERT INTO `genshin_constellation` VALUES (589, 11101, '瓦雷莎', 1, '终始不熄的热诚', '突破天赋「连势，三重腾跃！」的效果获得强化：\r\n进行特殊下落攻击·大火山狂雷怒卷时，瓦雷莎也会获得「虹色坠击」，持续5秒；\r\n「虹色坠击」持续期间，无论瓦雷莎是否处于炽热激情状态，进行下落攻击时，坠地冲击都会改为额外造成180%攻击力的伤害。该效果需要解锁突破天赋「连势，三重腾跃！」。\r\n\r\n此外，当瓦雷莎处于夜魂加持状态下的「突驰烈进」模式时，消耗的夜魂值或燃素降低30%。', '突破天赋「连势，三重腾跃！」的效果获得强化：\r\n进行特殊下落攻击·大火山狂雷怒卷时，瓦雷莎也会获得「虹色坠击」，持续5秒；\r\n「虹色坠击」持续期间，无论瓦雷莎是否处于炽热激情状态，进行下落攻击时，坠地冲击都会改为额外造成180%攻击力的伤害。该效果需要解锁突破天赋「连势，三重腾跃！」。\r\n\r\n此外，当瓦雷莎处于夜魂加持状态下的「突驰烈进」模式时，消耗的夜魂值或燃素降低30%。');
INSERT INTO `genshin_constellation` VALUES (590, 11101, '瓦雷莎', 2, '逾越天光的极限', '无论是否处于炽热激情状态，瓦雷莎进行下落攻击后，都会进入极限驱动状态。\r\n处于极限驱动状态下时，瓦雷莎的抗打断能力还会进一步提升。\r\n此外，瓦雷莎进行下落攻击时的坠地冲击命中敌人时，会为瓦雷莎恢复11.5点元素能量。', '无论是否处于炽热激情状态，瓦雷莎进行下落攻击后，都会进入极限驱动状态。\r\n处于极限驱动状态下时，瓦雷莎的抗打断能力还会进一步提升。\r\n此外，瓦雷莎进行下落攻击时的坠地冲击命中敌人时，会为瓦雷莎恢复11.5点元素能量。');
INSERT INTO `genshin_constellation` VALUES (591, 11101, '瓦雷莎', 3, '百折不摧的决意', '元素爆发<color=#FFD780FF>闪烈降临！的技能等级提高3级。\r\n至多提升至15级。', '元素爆发闪烈降临！的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (592, 11101, '瓦雷莎', 4, '直面前路的勇气', '施放元素爆发<color=#FFD780FF>闪烈降临！时，依据瓦雷莎的状态，将分别产生对应的强化效果。若瓦雷莎：\r\n·不处于炽热激情状态或极限驱动状态：瓦雷莎获得「精进勇猛」效果，持续15秒，基于瓦雷莎攻击力的500%，提升瓦雷莎进行下落攻击时坠地冲击造成的伤害，至多通过这种方式提升20000；该效果将在坠地冲击命中敌人或持续时间结束时解除。\r\n·处于炽热激情状态或极限驱动状态：本次元素爆发<color=#FFD780FF>闪烈降临！造成的伤害提升100%。', '施放元素爆发闪烈降临！时，依据瓦雷莎的状态，将分别产生对应的强化效果。若瓦雷莎：\r\n·不处于炽热激情状态或极限驱动状态：瓦雷莎获得「精进勇猛」效果，持续15秒，基于瓦雷莎攻击力的500%，提升瓦雷莎进行下落攻击时坠地冲击造成的伤害，至多通过这种方式提升20000；该效果将在坠地冲击命中敌人或持续时间结束时解除。\r\n·处于炽热激情状态或极限驱动状态：本次元素爆发闪烈降临！造成的伤害提升100%。');
INSERT INTO `genshin_constellation` VALUES (593, 11101, '瓦雷莎', 5, '暖风浮漾的心念', '<color=#FFD780FF>普通攻击·角力搏摔的技能等级提高3级。\r\n至多提升至15级。', '普通攻击·角力搏摔的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (594, 11101, '瓦雷莎', 6, '正义英雄的凯旋', '进入极限驱动状态时，将为瓦雷莎恢复30点元素能量。\r\n瓦雷莎的下落攻击与元素爆发<color=#FFD780FF>闪烈降临！的暴击率提升10%，暴击伤害提升100%。\r\n此外，瓦雷莎长按施放元素战技<color=#FFD780FF>夜虹逐跃时，或是在「突驰烈进」模式下点按施放元素战技时，瓦雷莎将恢复夜魂值至上限。', '进入极限驱动状态时，将为瓦雷莎恢复30点元素能量。\r\n瓦雷莎的下落攻击与元素爆发闪烈降临！的暴击率提升10%，暴击伤害提升100%。\r\n此外，瓦雷莎长按施放元素战技夜虹逐跃时，或是在「突驰烈进」模式下点按施放元素战技时，瓦雷莎将恢复夜魂值至上限。');
INSERT INTO `genshin_constellation` VALUES (595, 12801, '法尔伽', 1, '「来吧，朋友，让我们在月下共舞」', '法尔伽切换至<color=#FFD780FF>狂飙突进模式时，将额外获得一次特殊元素战技<color=#FFD780FF>四风将起的可用次数。\r\n此外，切换至<color=#FFD780FF>狂飙突进模式后，法尔伽将获得<color=#FFD780FF>「歌中的佳酿」效果：施放特殊元素战技<color=#FFD780FF>四风将起时，或进行特殊重击<color=#FFD780FF>苍噬时，将消耗该效果，使<color=#FFD780FF>四风将起或<color=#FFD780FF>苍噬造成原本200%的伤害。', '法尔伽切换至**狂飙突进**模式时，将额外获得一次特殊元素战技**四风将起**的可用次数。\r\n此外，切换至狂飙突进模式后，法尔伽将获得「歌中的佳酿」效果：施放特殊元素战技四风将起时，或进行特殊重击苍噬时，将消耗该效果，使四风将起或苍噬造成原本200%的伤害。');
INSERT INTO `genshin_constellation` VALUES (596, 12801, '法尔伽', 2, '「待天光破晓，我们便要踏上征途」', '施放特殊元素战技<color=#FFD780FF>四风将起时，或进行特殊重击<color=#FFD780FF>苍噬时，法尔伽将会进行一次额外攻击，造成800%攻击力的<color=#80FFD7FF>风元素范围伤害。', '施放特殊元素战技**四风将起**时，或进行特殊重击苍噬时，法尔伽将会进行一次额外攻击，造成800%攻击力的风元素范围伤害。');
INSERT INTO `genshin_constellation` VALUES (597, 12801, '法尔伽', 3, '「朋友，莫要再饮令人落泪的苦酒」', '元素战技<color=#FFD780FF>烈风终坠的技能等级提高3级。\r\n至多提升至15级。', '元素战技**烈风终坠**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (598, 12801, '法尔伽', 4, '「因为无人能夺去我们歌唱的自由」', '法尔伽触发扩散反应时，依据参与反应的元素类型，使队伍中附近的所有角色分别获得20%<color=#80FFD7FF>风元素伤害加成与对应元素伤害加成，持续10秒。', '法尔伽触发扩散反应时，依据参与反应的元素类型，使队伍中附近的所有角色分别获得20%风元素伤害加成与对应元素伤害加成，持续10秒。');
INSERT INTO `genshin_constellation` VALUES (599, 12801, '法尔伽', 5, '「斟满杯中佳酿吧，暴君来了又去」', '元素爆发<color=#FFD780FF>我即朔风的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**我即朔风**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (600, 12801, '法尔伽', 6, '「我心爱的蒙德呀，依然屹立如初」', '<color=#FFD780FF>狂飙突进模式获得强化：\r\n·施放特殊元素战技<color=#FFD780FF>四风将起后的短暂时间内，法尔伽可以点按元素战技或长按普通攻击，不消耗四风将起的可用次数，进行一次额外的特殊重击<color=#FFD780FF>苍噬；\r\n·进行特殊重击<color=#FFD780FF>苍噬后的短暂时间内，法尔伽可以点按元素战技，不消耗四风将起的可用次数，施放一次额外的<color=#FFD780FF>四风将起。\r\n通过上述方式进行额外的特殊重击苍噬或施放额外的特殊元素战技四风将起时，无法触发上述效果。\r\n\r\n此外，突破天赋<color=#FFD780FF>「风帜的先引」中<color=#FFD780FF>「苍牙之誓」的效果获得强化：每层<color=#FFD780FF>「苍牙之誓」还会使法尔伽的暴击伤害提升20%。', '**狂飙突进**模式获得强化：\r\n·施放特殊元素战技**四风将起**后的短暂时间内，法尔伽可以点按元素战技或长按普通攻击，不消耗四风将起的可用次数，进行一次额外的特殊重击苍噬；\r\n·进行特殊重击苍噬后的短暂时间内，法尔伽可以点按元素战技，不消耗四风将起的可用次数，施放一次额外的四风将起。\r\n通过上述方式进行额外的特殊重击苍噬或施放额外的特殊元素战技四风将起时，无法触发上述效果。\r\n\r\n此外，突破天赋**「风帜的先引」**中「苍牙之誓」的效果获得强化：每层「苍牙之誓」还会使法尔伽的暴击伤害提升20%。');
INSERT INTO `genshin_constellation` VALUES (601, 2201, '温迪', 1, '弦发的苍风', '<color=#FFD780FF>瞄准射击会额外发射两枚分裂箭，分别造成原本33%的伤害。', '瞄准射击会额外发射两枚分裂箭，分别造成原本33%的伤害。');
INSERT INTO `genshin_constellation` VALUES (602, 2201, '温迪', 2, '眷恋的泠风', '<color=#FFD780FF>高天之歌会使敌人的<color=#80FFD7FF>风元素抗性与物理抗性降低12%，持续10秒。\r\n被<color=#FFD780FF>高天之歌击飞的敌人在落地前，<color=#80FFD7FF>风元素抗性与物理抗性额外降低12%。', '高天之歌会使敌人的风元素抗性与物理抗性降低12%，持续10秒。\r\n被高天之歌击飞的敌人在落地前，风元素抗性与物理抗性额外降低12%。');
INSERT INTO `genshin_constellation` VALUES (603, 2201, '温迪', 3, '千风的诗篇', '<color=#FFD780FF>风神之诗的技能等级提高3级。\r\n至多提升至15级。', '风神之诗的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (604, 2201, '温迪', 4, '自由的凛风', '温迪获取元素晶球或元素微粒后，获得25%<color=#80FFD7FF>风元素伤害加成，持续10秒。', '温迪获取元素晶球或元素微粒后，获得25%风元素伤害加成，持续10秒。');
INSERT INTO `genshin_constellation` VALUES (605, 2201, '温迪', 5, '高天的协奏', '<color=#FFD780FF>高天之歌的技能等级提高3级。\r\n至多提升至15级。', '高天之歌的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (606, 2201, '温迪', 6, '抗争的暴风', '受<color=#FFD780FF>风神之诗伤害的敌人，<color=#80FFD7FF>风元素抗性降低20%；\r\n若产生了元素转化，则使转换的元素抗性也降低20%。', '受风神之诗伤害的敌人，风元素抗性降低20%；\r\n若产生了元素转化，则使转换的元素抗性也降低20%。');
INSERT INTO `genshin_constellation` VALUES (607, 7501, '流浪者', 1, '初番·茂风流羽行', '在<color=#FFD780FF>优风倾姿状态下，流浪者进行空居·不生断与空居·刀风界的攻击速度提升10%。\r\n此外，突破天赋「梦迹一风」发射的风矢能额外造成25%攻击力的伤害，该效果需要解锁突破天赋「梦迹一风」。', '在优风倾姿状态下，流浪者进行空居·不生断与空居·刀风界的攻击速度提升10%。\r\n此外，突破天赋「梦迹一风」发射的风矢能额外造成25%攻击力的伤害，该效果需要解锁突破天赋「梦迹一风」。');
INSERT INTO `genshin_constellation` VALUES (608, 7501, '流浪者', 2, '二番·箙岛廓白浪', '在<color=#FFD780FF>优风倾姿状态下，<color=#FFD780FF>狂言·式乐五番将依据空居力上限与当前的空居力的差值，每1点使此次狂言·式乐五番造成的伤害提升4%。\r\n通过这种方式，至多使狂言·式乐五番造成的伤害提升200%。', '在优风倾姿状态下，狂言·式乐五番将依据空居力上限与当前的空居力的差值，每1点使此次狂言·式乐五番造成的伤害提升4%。\r\n通过这种方式，至多使狂言·式乐五番造成的伤害提升200%。');
INSERT INTO `genshin_constellation` VALUES (609, 7501, '流浪者', 3, '三番·久世舞夕颜', '<color=#FFD780FF>狂言·式乐五番的技能等级提高3级。\r\n至多提升至15级。', '狂言·式乐五番的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (610, 7501, '流浪者', 4, '四番·花月歌浮舟', '施放<color=#FFD780FF>羽画·风姿华歌时，若触发了突破天赋「拾玉得花」依据元素类型强化的效果，还将随机获得1种本次施放未触发的强化效果。同时至多获得3种元素对应的强化效果。\r\n需要解锁突破天赋「拾玉得花」。', '施放羽画·风姿华歌时，若触发了突破天赋「拾玉得花」依据元素类型强化的效果，还将随机获得1种本次施放未触发的强化效果。同时至多获得3种元素对应的强化效果。\r\n需要解锁突破天赋「拾玉得花」。');
INSERT INTO `genshin_constellation` VALUES (611, 7501, '流浪者', 5, '末番·今昔渡来殿', '<color=#FFD780FF>羽画·风姿华歌的技能等级提高3级。\r\n至多提升至15级。', '羽画·风姿华歌的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (612, 7501, '流浪者', 6, '祝言·霞幕倾松风', '在<color=#FFD780FF>优风倾姿状态下，流浪者主动施放的空居·不生断命中敌人时，将产生如下效果：\r\n·在命中的位置额外进行一次空居·不生断，造成原本40%的伤害，该伤害视为普通攻击伤害；\r\n·当流浪者的空居力低于40点时，为流浪者恢复4点空居力。每0.2秒至多通过这种方式恢复1次空居力，在一次优风倾姿的持续期间，至多触发5次。', '在优风倾姿状态下，流浪者主动施放的空居·不生断命中敌人时，将产生如下效果：\r\n·在命中的位置额外进行一次空居·不生断，造成原本40%的伤害，该伤害视为普通攻击伤害；\r\n·当流浪者的空居力低于40点时，为流浪者恢复4点空居力。每0.2秒至多通过这种方式恢复1次空居力，在一次优风倾姿的持续期间，至多触发5次。');
INSERT INTO `genshin_constellation` VALUES (613, 8601, '莱欧斯利', 1, '予行恶者以惩惧', '突破天赋「公理终有辩诉之日」的「恩典之诫」转变为：\r\n莱欧斯利的生命值低于60%，或在<color=#FFD780FF>冰牙突驰的寒烈的惩裁状态持续期间，斥逐拳的第五段攻击命中时，将获得「恩典之诫」，每2.5秒至多获得一次「恩典之诫」效果。\r\n\r\n此外，惩戒·凌跃拳获得以下强化：\r\n·造成的伤害提升进一步提升至200%；\r\n·命中时，若处于寒烈的惩裁状态下，该状态的持续时间延长4秒，在一次寒烈的惩裁状态持续期间，至多通过这种方式延长一次。\r\n\r\n需要解锁突破天赋「公理终有辩诉之日」。', '突破天赋「公理终有辩诉之日」的「恩典之诫」转变为：\r\n莱欧斯利的生命值低于60%，或在冰牙突驰的寒烈的惩裁状态持续期间，斥逐拳的第五段攻击命中时，将获得「恩典之诫」，每2.5秒至多获得一次「恩典之诫」效果。\r\n\r\n此外，惩戒·凌跃拳获得以下强化：\r\n·造成的伤害提升进一步提升至200%；\r\n·命中时，若处于寒烈的惩裁状态下，该状态的持续时间延长4秒，在一次寒烈的惩裁状态持续期间，至多通过这种方式延长一次。\r\n\r\n需要解锁突破天赋「公理终有辩诉之日」。');
INSERT INTO `genshin_constellation` VALUES (614, 8601, '莱欧斯利', 2, '予骄暴者以镣锁', '施放<color=#FFD780FF>黑金狼噬时，突破天赋「罪业终有报偿之时」的每层「检偿之敕」效果都将使造成的伤害提升40%。\r\n需要解锁突破天赋「罪业终有报偿之时」。', '施放黑金狼噬时，突破天赋「罪业终有报偿之时」的每层「检偿之敕」效果都将使造成的伤害提升40%。\r\n需要解锁突破天赋「罪业终有报偿之时」。');
INSERT INTO `genshin_constellation` VALUES (615, 8601, '莱欧斯利', 3, '予婪诈者以谴罚', '<color=#FFD780FF>普通攻击·迅烈倾霜拳的技能等级提高3级。\r\n至多提升至15级。', '普通攻击·迅烈倾霜拳的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (616, 8601, '莱欧斯利', 4, '予贞苦者以拯赎', '惩戒·凌跃拳为莱欧斯利恢复生命值的回复量提升为50%生命值上限，需要解锁突破天赋「公理终有辩诉之日」。\r\n此外，莱欧斯利受到治疗时，若此次治疗回复量溢出，将根据莱欧斯利是否处于当前场上产生不同的效果：处于当前场上时，莱欧斯利的攻击速度提升20%，持续4秒；处于队伍后台时，队伍中所有自己的角色攻击速度提升10%，持续6秒。上述这两种攻击速度提升效果无法叠加。', '惩戒·凌跃拳为莱欧斯利恢复生命值的回复量提升为50%生命值上限，需要解锁突破天赋「公理终有辩诉之日」。\r\n此外，莱欧斯利受到治疗时，若此次治疗回复量溢出，将根据莱欧斯利是否处于当前场上产生不同的效果：处于当前场上时，莱欧斯利的攻击速度提升20%，持续4秒；处于队伍后台时，队伍中所有自己的角色攻击速度提升10%，持续6秒。上述这两种攻击速度提升效果无法叠加。');
INSERT INTO `genshin_constellation` VALUES (617, 8601, '莱欧斯利', 5, '予冤诉者以怜恕', '<color=#FFD780FF>黑金狼噬的技能等级提高3级。\r\n至多提升至15级。', '黑金狼噬的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (618, 8601, '莱欧斯利', 6, '予无罪者以念抚', '惩戒·凌跃拳的暴击率提升10%，暴击伤害提升80%，并能够额外生成冰锥，造成原本100%的<color=#99FFFFFF>冰元素伤害，通过这种方式造成的伤害视为重击伤害。\r\n需要解锁突破天赋「公理终有辩诉之日」。', '惩戒·凌跃拳的暴击率提升10%，暴击伤害提升80%，并能够额外生成冰锥，造成原本100%的冰元素伤害，通过这种方式造成的伤害视为重击伤害。\r\n需要解锁突破天赋「公理终有辩诉之日」。');
INSERT INTO `genshin_constellation` VALUES (619, 2301, '香菱', 1, '外酥里嫩', '受到锅巴攻击的敌人，<color=#FF9999FF>火元素抗性降低15%，持续6秒。', '受到锅巴攻击的敌人，火元素抗性降低15%，持续6秒。');
INSERT INTO `genshin_constellation` VALUES (620, 2301, '香菱', 2, '大火宽油', '普通攻击的最后一击会对敌人施加持续2秒的内爆效果，持续时间结束时会发生爆炸，造成75%攻击力的<color=#FF9999FF>火元素范围伤害。', '普通攻击的最后一击会对敌人施加持续2秒的内爆效果，持续时间结束时会发生爆炸，造成75%攻击力的火元素范围伤害。');
INSERT INTO `genshin_constellation` VALUES (621, 2301, '香菱', 3, '武火急烹', '<color=#FFD780FF>旋火轮的技能等级提高3级。\r\n至多提升至15级。', '旋火轮的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (622, 2301, '香菱', 4, '文火慢煨', '<color=#FFD780FF>旋火轮的持续时间延长40%。', '旋火轮的持续时间延长40%。');
INSERT INTO `genshin_constellation` VALUES (623, 2301, '香菱', 5, '锅巴凶猛', '<color=#FFD780FF>锅巴出击的技能等级提高3级。\r\n至多提升至15级。', '锅巴出击的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (624, 2301, '香菱', 6, '大龙卷旋火轮', '<color=#FFD780FF>旋火轮持续期间，队伍中所有角色获得15%<color=#FF9999FF>火元素伤害加成。', '旋火轮持续期间，队伍中所有角色获得15%火元素伤害加成。');
INSERT INTO `genshin_constellation` VALUES (625, 9301, '闲云', 1, '借风洗尘缘', '<color=#FFD780FF>朝起鹤云的可用次数增加1次。', '朝起鹤云的可用次数增加1次。');
INSERT INTO `genshin_constellation` VALUES (626, 9301, '闲云', 2, '鹤唳远人间', '施放<color=#FFD780FF>朝起鹤云的步天梯后，闲云的攻击力提升20%，持续15秒。\r\n此外，突破天赋「细想应是洞中仙」的效果获得提升：<color=#FFD780FF>暮集竹星的竹星拥有仙力助推时，附近的当前场上角色的下落攻击坠地冲击造成的伤害提升，提升值相当于闲云的攻击力的400%。通过这种方式，至多使附近的当前场上角色的下落攻击坠地冲击伤害提升18000。\r\n一次下落攻击坠地冲击伤害中，只会对一名敌人造成上述伤害提升效果，每个角色每0.4秒至多触发一次。\r\n该效果需要解锁突破天赋「细想应是洞中仙」。', '施放朝起鹤云的步天梯后，闲云的攻击力提升20%，持续15秒。\r\n此外，突破天赋「细想应是洞中仙」的效果获得提升：暮集竹星的竹星拥有仙力助推时，附近的当前场上角色的下落攻击坠地冲击造成的伤害提升，提升值相当于闲云的攻击力的400%。通过这种方式，至多使附近的当前场上角色的下落攻击坠地冲击伤害提升18000。\r\n一次下落攻击坠地冲击伤害中，只会对一名敌人造成上述伤害提升效果，每个角色每0.4秒至多触发一次。\r\n该效果需要解锁突破天赋「细想应是洞中仙」。');
INSERT INTO `genshin_constellation` VALUES (627, 9301, '闲云', 3, '造化有星月', '<color=#FFD780FF>暮集竹星的技能等级提高3级。\r\n至多提升至15级。', '暮集竹星的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (628, 9301, '闲云', 4, '奥妙烹黍珠', '在一次<color=#FFD780FF>朝起鹤云的鹤云幻化期间施展了1/2/3次步天梯后，该次鹤云幻化期间的闲云冲击波命中敌人时，将为队伍中附近的所有角色恢复生命值，回复量相当于闲云攻击力的50%/80%/150%。该效果每5秒至多触发一次。', '在一次朝起鹤云的鹤云幻化期间施展了1/2/3次步天梯后，该次鹤云幻化期间的闲云冲击波命中敌人时，将为队伍中附近的所有角色恢复生命值，回复量相当于闲云攻击力的50%/80%/150%。该效果每5秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (629, 9301, '闲云', 5, '旋步霞蔚上', '<color=#FFD780FF>朝起鹤云的技能等级提高3级。\r\n至多提升至15级。', '朝起鹤云的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (630, 9301, '闲云', 6, '知是留云僊', '在一次<color=#FFD780FF>朝起鹤云的鹤云幻化期间施放了1/2/3次步天梯后，该次鹤云幻化期间的闲云冲击波的暴击伤害提升15%/35%/70%。\r\n闲云施放<color=#FFD780FF>暮集竹星后的16秒内，朝起鹤云将不再进入冷却，该效果将在闲云施放8次朝起鹤云后移除。', '在一次朝起鹤云的鹤云幻化期间施放了1/2/3次步天梯后，该次鹤云幻化期间的闲云冲击波的暴击伤害提升15%/35%/70%。\r\n闲云施放暮集竹星后的16秒内，朝起鹤云将不再进入冷却，该效果将在闲云施放8次朝起鹤云后移除。');
INSERT INTO `genshin_constellation` VALUES (631, 2601, '魈', 1, '坏劫·毁坏三界', '<color=#FFD780FF>风轮两立的可使用次数增加1次。', '风轮两立的可使用次数增加1次。');
INSERT INTO `genshin_constellation` VALUES (632, 2601, '魈', 2, '空劫·虚空华开敷变', '处于队伍后台时，魈自己的元素充能效率提高25%。', '处于队伍后台时，魈自己的元素充能效率提高25%。');
INSERT INTO `genshin_constellation` VALUES (633, 2601, '魈', 3, '降魔·忿怒显相', '<color=#FFD780FF>风轮两立的技能等级提高3级。\r\n至多提升至15级。', '风轮两立的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (634, 2601, '魈', 4, '神通·诸苦灭尽', '魈的生命值低于50%时，获得100%防御力提升。', '魈的生命值低于50%时，获得100%防御力提升。');
INSERT INTO `genshin_constellation` VALUES (635, 2601, '魈', 5, '成劫·无明增长', '<color=#FFD780FF>靖妖傩舞的技能等级提高3级。\r\n至多提升至15级。', '靖妖傩舞的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (636, 2601, '魈', 6, '降魔·护法夜叉', '在<color=#FFD780FF>靖妖傩舞状态下，下落攻击命中至少2个敌人时，<color=#FFD780FF>风轮两立立刻获得1次可使用次数，并且在接下来1秒内，可以无视冷却时间施放风轮两立。', '在靖妖傩舞状态下，下落攻击命中至少2个敌人时，风轮两立立刻获得1次可使用次数，并且在接下来1秒内，可以无视冷却时间施放风轮两立。');
INSERT INTO `genshin_constellation` VALUES (637, 10301, '希诺宁', 1, '献予慵眠的休假日', '希诺宁的夜魂加持状态消耗的夜魂值与燃素降低30%，且夜魂值的时间限制延长45%。\r\n此外，希诺宁的「源音采样」激活时，还将提升队伍中附近的当前场上角色的抗打断能力。', '希诺宁的夜魂加持状态消耗的夜魂值与燃素降低30%，且夜魂值的时间限制延长45%。\r\n此外，希诺宁的「源音采样」激活时，还将提升队伍中附近的当前场上角色的抗打断能力。');
INSERT INTO `genshin_constellation` VALUES (638, 10301, '希诺宁', 2, '献予灼原的五重奏', '希诺宁携带的<color=#FFE699FF>岩元素「源音采样」将始终保持激活状态。此外，希诺宁的「源音采样」激活时，将根据「源音采样」的元素类型，使队伍中附近所有元素类型相同的角色获得对应效果：\r\n·<color=#FFE699FF>岩元素：造成的伤害提升50%；\r\n·<color=#FF9999FF>火元素：攻击力提升45%；\r\n·<color=#80C0FFFF>水元素：生命值上限提升45%；\r\n·<color=#99FFFFFF>冰元素：暴击伤害提升60%；\r\n·<color=#FFACFFFF>雷元素：恢复25点元素能量，且元素爆发的冷却时间缩短6秒。', '希诺宁携带的岩元素「源音采样」将始终保持激活状态。此外，希诺宁的「源音采样」激活时，将根据「源音采样」的元素类型，使队伍中附近所有元素类型相同的角色获得对应效果：\r\n·岩元素：造成的伤害提升50%；\r\n·火元素：攻击力提升45%；\r\n·水元素：生命值上限提升45%；\r\n·冰元素：暴击伤害提升60%；\r\n·雷元素：恢复25点元素能量，且元素爆发的冷却时间缩短6秒。');
INSERT INTO `genshin_constellation` VALUES (639, 10301, '希诺宁', 3, '献予日炎的巡行式', '<color=#FFD780FF>音火锻淬的技能等级提高3级。\r\n至多提升至15级。', '音火锻淬的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (640, 10301, '希诺宁', 4, '献予午后的花之梦', '希诺宁施放<color=#FFD780FF>音火锻淬后，将为队伍中附近的所有角色施加「荣花之赐」效果，持续15秒。\r\n拥有「荣花之赐」的角色的普通攻击、重击与下落攻击造成的伤害提升，提升值相当于希诺宁的防御力的65%。该效果将在生效6次或持续时间结束时解除。\r\n同时命中多名敌人时，会依据命中敌人的数量消耗生效次数；队伍中具有「荣花之赐」的角色，其生效次数单独计算。', '希诺宁施放音火锻淬后，将为队伍中附近的所有角色施加「荣花之赐」效果，持续15秒。\r\n拥有「荣花之赐」的角色的普通攻击、重击与下落攻击造成的伤害提升，提升值相当于希诺宁的防御力的65%。该效果将在生效6次或持续时间结束时解除。\r\n同时命中多名敌人时，会依据命中敌人的数量消耗生效次数；队伍中具有「荣花之赐」的角色，其生效次数单独计算。');
INSERT INTO `genshin_constellation` VALUES (641, 10301, '希诺宁', 5, '献予夕暮的转格调', '<color=#FFD780FF>豹烈律动！的技能等级提高3级。\r\n至多提升至15级。', '豹烈律动！的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (642, 10301, '希诺宁', 6, '献予永夜的狂欢舞', '处于夜魂加持状态下时，希诺宁进行冲刺、腾跃、普通攻击、下落攻击时，将获得「永夜的祝福」，无视夜魂加持状态下的限制，并提升普通攻击与下落攻击造成的伤害，持续5秒。\r\n持续期间：\r\n·暂停希诺宁的夜魂值时间限制计时，希诺宁的夜魂值、燃素、体力将不再下降，且夜魂值达到上限时，希诺宁的夜魂加持也不会结束；\r\n·希诺宁在夜魂加持状态下的普通攻击与下落攻击造成的伤害提升，提升值相当于希诺宁的防御力的300%。\r\n·每1.5秒为附近的队伍中所有角色恢复生命值，回复量相当于希诺宁的防御力的120%。\r\n每15秒至多获得一次「永夜的祝福」。', '处于夜魂加持状态下时，希诺宁进行冲刺、腾跃、普通攻击、下落攻击时，将获得「永夜的祝福」，无视夜魂加持状态下的限制，并提升普通攻击与下落攻击造成的伤害，持续5秒。\r\n持续期间：\r\n·暂停希诺宁的夜魂值时间限制计时，希诺宁的夜魂值、燃素、体力将不再下降，且夜魂值达到上限时，希诺宁的夜魂加持也不会结束；\r\n·希诺宁在夜魂加持状态下的普通攻击与下落攻击造成的伤害提升，提升值相当于希诺宁的防御力的300%。\r\n·每1.5秒为附近的队伍中所有角色恢复生命值，回复量相当于希诺宁的防御力的120%。\r\n每15秒至多获得一次「永夜的祝福」。');
INSERT INTO `genshin_constellation` VALUES (643, 2501, '行秋', 1, '重帘留香', '雨帘剑的最大数量增加1柄。', '雨帘剑的最大数量增加1柄。');
INSERT INTO `genshin_constellation` VALUES (644, 2501, '行秋', 2, '天青现虹', '<color=#FFD780FF>古华剑·裁雨留虹的持续时间延长3秒；\r\n此外，受到剑雨攻击的敌人，<color=#80C0FFFF>水元素抗性降低15%，持续4秒。', '古华剑·裁雨留虹的持续时间延长3秒；\r\n此外，受到剑雨攻击的敌人，水元素抗性降低15%，持续4秒。');
INSERT INTO `genshin_constellation` VALUES (645, 2501, '行秋', 3, '织诗成锦', '<color=#FFD780FF>古华剑·裁雨留虹的技能等级提高3级。\r\n至多提升至15级。', '古华剑·裁雨留虹的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (646, 2501, '行秋', 4, '孤舟斩蛟', '在<color=#FFD780FF>古华剑·裁雨留虹效果持续期间，<color=#FFD780FF>古华剑·画雨笼山造成的伤害提升50%。', '在古华剑·裁雨留虹效果持续期间，古华剑·画雨笼山造成的伤害提升50%。');
INSERT INTO `genshin_constellation` VALUES (647, 2501, '行秋', 5, '雨深闭门', '<color=#FFD780FF>古华剑·画雨笼山的技能等级提高3级。\r\n至多提升至15级。', '古华剑·画雨笼山的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (648, 2501, '行秋', 6, '万文集此', '<color=#FFD780FF>古华剑·裁雨留虹每发动2次剑雨攻击，就大幅增强下一次剑雨攻击，并在命中敌人时为行秋恢复3点元素能量。', '古华剑·裁雨留虹每发动2次剑雨攻击，就大幅增强下一次剑雨攻击，并在命中敌人时为行秋恢复3点元素能量。');
INSERT INTO `genshin_constellation` VALUES (649, 4401, '辛焱', 1, '绝命的加速', '辛焱造成暴击后的5秒内，普通攻击和重击的攻击速度提升12%。\r\n该效果每5秒只能触发一次。', '辛焱造成暴击后的5秒内，普通攻击和重击的攻击速度提升12%。\r\n该效果每5秒只能触发一次。');
INSERT INTO `genshin_constellation` VALUES (650, 4401, '辛焱', 2, '开场即兴段', '<color=#FFD780FF>叛逆刮弦造成的物理伤害暴击率提升100%，并会在施放时形成三级护盾·舞遍节拍。', '叛逆刮弦造成的物理伤害暴击率提升100%，并会在施放时形成三级护盾·舞遍节拍。');
INSERT INTO `genshin_constellation` VALUES (651, 4401, '辛焱', 3, '摭分的指法', '<color=#FFD780FF>热情拂扫的技能等级提高3级。\r\n至多提升至15级。', '热情拂扫的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (652, 4401, '辛焱', 4, '节奏的传染', '<color=#FFD780FF>热情拂扫的挥舞伤害，会使敌人的物理抗性降低15%，持续12秒。', '热情拂扫的挥舞伤害，会使敌人的物理抗性降低15%，持续12秒。');
INSERT INTO `genshin_constellation` VALUES (653, 4401, '辛焱', 5, '返场的高呼', '<color=#FFD780FF>叛逆刮弦的技能等级提高3级。\r\n至多提升至15级。', '叛逆刮弦的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (654, 4401, '辛焱', 6, '地狱里摇摆', '辛焱的重击的体力消耗降低30%；此外，进行重击时，将基于防御力的50%获得攻击力加成。', '辛焱的重击的体力消耗降低30%；此外，进行重击时，将基于防御力的50%获得攻击力加成。');
INSERT INTO `genshin_constellation` VALUES (655, 5801, '八重神子', 1, '野狐供真篇', '<color=#FFD780FF>大密法·天狐显真每引发一次天狐霆雷，都会为八重神子自己恢复8点元素能量。', '大密法·天狐显真每引发一次天狐霆雷，都会为八重神子自己恢复8点元素能量。');
INSERT INTO `genshin_constellation` VALUES (656, 5801, '八重神子', 2, '望月吼哕声', '<color=#FFD780FF>杀生樱创造时的初始位阶提升至贰阶，位阶上限提升至肆阶，攻击范围提升60%。', '杀生樱创造时的初始位阶提升至贰阶，位阶上限提升至肆阶，攻击范围提升60%。');
INSERT INTO `genshin_constellation` VALUES (657, 5801, '八重神子', 3, '七段妙变化', '<color=#FFD780FF>野干役咒·杀生樱的技能等级提高3级。\r\n至多提升至15级。', '野干役咒·杀生樱的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (658, 5801, '八重神子', 4, '绯樱引雷章', '<color=#FFD780FF>杀生樱的落雷命中敌人后，队伍中附近的所有角色获得20%<color=#FFACFFFF>雷元素伤害加成，持续5秒。', '杀生樱的落雷命中敌人后，队伍中附近的所有角色获得20%雷元素伤害加成，持续5秒。');
INSERT INTO `genshin_constellation` VALUES (659, 5801, '八重神子', 5, '暴恶嗤笑面', '<color=#FFD780FF>大密法·天狐显真的技能等级提高3级。\r\n至多提升至15级。', '大密法·天狐显真的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (660, 5801, '八重神子', 6, '大杀生咒禁', '<color=#FFD780FF>杀生樱在攻击时无视敌人60%的防御力。', '杀生樱在攻击时无视敌人60%的防御力。');
INSERT INTO `genshin_constellation` VALUES (661, 4801, '烟绯', 1, '占理不饶人', '烟绯进行重击时，每持有一枚丹火印，都会提高烟绯在咏唱期间的抗打断能力，并额外降低本次重击10%的体力消耗。', '烟绯进行重击时，每持有一枚丹火印，都会提高烟绯在咏唱期间的抗打断能力，并额外降低本次重击10%的体力消耗。');
INSERT INTO `genshin_constellation` VALUES (662, 4801, '烟绯', 2, '最终解释权', '烟绯的重击对于生命值低于50%的敌人，暴击率提高20%。', '烟绯的重击对于生命值低于50%的敌人，暴击率提高20%。');
INSERT INTO `genshin_constellation` VALUES (663, 4801, '烟绯', 3, '真火炼宝印', '<color=#FFD780FF>丹书立约的技能等级提高3级。\r\n至多提升至15级。', '丹书立约的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (664, 4801, '烟绯', 4, '丹书金铁券', '施放<color=#FFD780FF>凭此结契时：\r\n生成一个伤害吸收量等于生命值上限45%的护盾，持续15秒。\r\n该护盾对<color=#FF9999FF>火元素伤害有250%的吸收效果。', '施放凭此结契时：\r\n生成一个伤害吸收量等于生命值上限45%的护盾，持续15秒。\r\n该护盾对火元素伤害有250%的吸收效果。');
INSERT INTO `genshin_constellation` VALUES (665, 4801, '烟绯', 5, '遵法切结书', '<color=#FFD780FF>凭此结契的技能等级提高3级。\r\n至多提升至15级。', '凭此结契的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (666, 4801, '烟绯', 6, '是额外条款', '烟绯持有的丹火印最大数量增加一枚。', '烟绯持有的丹火印最大数量增加一枚。');
INSERT INTO `genshin_constellation` VALUES (667, 7701, '瑶瑶', 1, '妙受琼阁', '<color=#FFD780FF>白玉萝卜炸裂时，处在其影响范围内的当前场上角色获得15%<color=#99FF88FF>草元素伤害加成，持续8秒，并恢复15点体力。每5秒只能通过这种方式恢复1次体力。', '白玉萝卜炸裂时，处在其影响范围内的当前场上角色获得15%草元素伤害加成，持续8秒，并恢复15点体力。每5秒只能通过这种方式恢复1次体力。');
INSERT INTO `genshin_constellation` VALUES (668, 7701, '瑶瑶', 2, '正思无邪', '处于<color=#FFD780FF>玉颗珊珊月中落的桂子仙机状态下时，若白玉萝卜的炸裂伤害命中敌人，瑶瑶将恢复3点元素能量。每0.8秒至多通过这种方式恢复一次元素能量。', '处于玉颗珊珊月中落的桂子仙机状态下时，若白玉萝卜的炸裂伤害命中敌人，瑶瑶将恢复3点元素能量。每0.8秒至多通过这种方式恢复一次元素能量。');
INSERT INTO `genshin_constellation` VALUES (669, 7701, '瑶瑶', 3, '墩墩善道', '<color=#FFD780FF>云台团团降芦菔的技能等级提高3级。\r\n至多提升至15级。', '云台团团降芦菔的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (670, 7701, '瑶瑶', 4, '爰爰可亲', '施放<color=#FFD780FF>云台团团降芦菔或<color=#FFD780FF>玉颗珊珊月中落后，基于瑶瑶生命值上限的0.3%，提升瑶瑶的元素精通，持续8秒。通过这种方式，至多提升120点元素精通。', '施放云台团团降芦菔或玉颗珊珊月中落后，基于瑶瑶生命值上限的0.3%，提升瑶瑶的元素精通，持续8秒。通过这种方式，至多提升120点元素精通。');
INSERT INTO `genshin_constellation` VALUES (671, 7701, '瑶瑶', 5, '恻隐本义', '<color=#FFD780FF>玉颗珊珊月中落的技能等级提高3级。\r\n至多提升至15级。', '玉颗珊珊月中落的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (672, 7701, '瑶瑶', 6, '慈惠仁心', '<color=#FFD780FF>月桂·抛掷型每投掷2次白玉萝卜，就会在下次投掷时额外投掷1枚超厉害·大萝卜。相比白玉萝卜，超厉害·大萝卜炸裂时的影响范围更大，炸裂时产生如下效果：\r\n·基于瑶瑶攻击力的75%，造成<color=#99FF88FF>草元素范围伤害；\r\n·基于瑶瑶生命值上限的7.5%，为其中的当前场上角色恢复生命值。\r\n\r\n每个月桂·抛掷型至多投掷2次超厉害·大萝卜。', '月桂·抛掷型每投掷2次白玉萝卜，就会在下次投掷时额外投掷1枚超厉害·大萝卜。相比白玉萝卜，超厉害·大萝卜炸裂时的影响范围更大，炸裂时产生如下效果：\r\n·基于瑶瑶攻击力的75%，造成草元素范围伤害；\r\n·基于瑶瑶生命值上限的7.5%，为其中的当前场上角色恢复生命值。\r\n\r\n每个月桂·抛掷型至多投掷2次超厉害·大萝卜。');
INSERT INTO `genshin_constellation` VALUES (673, 6001, '夜兰', 1, '与谋者，以局入局', '<color=#FFD780FF>萦络纵命索的可使用次数增加1次。', '萦络纵命索的可使用次数增加1次。');
INSERT INTO `genshin_constellation` VALUES (674, 6001, '夜兰', 2, '入彀者，多多益善', '<color=#FFD780FF>「玄掷玲珑」协同攻击时，会发射一枚额外的水箭，造成相当于夜兰生命值上限14%的水元素伤害。\r\n该效果每1.8秒至多触发一次。', '「玄掷玲珑」协同攻击时，会发射一枚额外的水箭，造成相当于夜兰生命值上限14%的水元素伤害。\r\n该效果每1.8秒至多触发一次。');
INSERT INTO `genshin_constellation` VALUES (675, 6001, '夜兰', 3, '晃盅者，琼畟药骰', '<color=#FFD780FF>渊图玲珑骰的技能等级提高3级。\r\n至多提升至15级。', '渊图玲珑骰的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (676, 6001, '夜兰', 4, '诓惑者，接树移花', '依照<color=#FFD780FF>「络命丝」标记敌人的数量，每次标记将在爆发时使队伍中所有角色的生命值上限提升10%，持续25秒。通过这种方式，生命值上限至多获得40%提升。', '依照「络命丝」标记敌人的数量，每次标记将在爆发时使队伍中所有角色的生命值上限提升10%，持续25秒。通过这种方式，生命值上限至多获得40%提升。');
INSERT INTO `genshin_constellation` VALUES (677, 6001, '夜兰', 5, '坐庄者，三仙戏法', '<color=#FFD780FF>萦络纵命索的技能等级提高3级。\r\n至多提升至15级。', '萦络纵命索的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (678, 6001, '夜兰', 6, '取胜者，大小通吃', '施放<color=#FFD780FF>渊图玲珑骰后，夜兰将进入「运筹帷幄」状态：\r\n夜兰的普通攻击将转为发射特殊的「破局矢」。这种箭矢具有与破局矢近似的特性，造成的伤害视为重击伤害，能造成破局矢156%的伤害。\r\n\r\n「运筹帷幄」状态至多持续20秒，将在夜兰发射5枚箭矢后移除。', '施放渊图玲珑骰后，夜兰将进入「运筹帷幄」状态：\r\n夜兰的普通攻击将转为发射特殊的「破局矢」。这种箭矢具有与破局矢近似的特性，造成的伤害视为重击伤害，能造成破局矢156%的伤害。\r\n\r\n「运筹帷幄」状态至多持续20秒，将在夜兰发射5枚箭矢后移除。');
INSERT INTO `genshin_constellation` VALUES (679, 4901, '宵宫', 1, '赤玉琉金', '<color=#FFD780FF>琉金云间草的琉金火光持续时间延长4秒。\r\n此外，处于宵宫自己的琉金火光影响下的敌人在持续期间内被击败时，宵宫的攻击力提高20%，持续20秒。', '琉金云间草的琉金火光持续时间延长4秒。\r\n此外，处于宵宫自己的琉金火光影响下的敌人在持续期间内被击败时，宵宫的攻击力提高20%，持续20秒。');
INSERT INTO `genshin_constellation` VALUES (680, 4901, '宵宫', 2, '万灯送火', '宵宫的<color=#FF9999FF>火元素伤害造成暴击后的6秒内，宵宫获得25%<color=#FF9999FF>火元素伤害加成。\r\n宵宫处于队伍后台时，同样能获得该效果。', '宵宫的火元素伤害造成暴击后的6秒内，宵宫获得25%火元素伤害加成。\r\n宵宫处于队伍后台时，同样能获得该效果。');
INSERT INTO `genshin_constellation` VALUES (681, 4901, '宵宫', 3, '鼠火戏法', '<color=#FFD780FF>焰硝庭火舞的技能等级提高3级。\r\n至多提升至15级。', '焰硝庭火舞的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (682, 4901, '宵宫', 4, '花火职人心得', '宵宫自己的琉金火光发生爆炸时，<color=#FFD780FF>焰硝庭火舞的冷却时间减少1.2秒。', '宵宫自己的琉金火光发生爆炸时，焰硝庭火舞的冷却时间减少1.2秒。');
INSERT INTO `genshin_constellation` VALUES (683, 4901, '宵宫', 5, '真夏宵祭锦绘', '<color=#FFD780FF>琉金云间草的技能等级提高3级。\r\n至多提升至15级。', '琉金云间草的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (684, 4901, '宵宫', 6, '长野原龙势流星群', '在<color=#FFD780FF>焰硝庭火舞的持续期间内，宵宫主动进行普通攻击时，有50%几率发射一枚额外的炽焰箭，造成原本60%的伤害。该伤害视为普通攻击伤害。', '在焰硝庭火舞的持续期间内，宵宫主动进行普通攻击时，有50%几率发射一枚额外的炽焰箭，造成原本60%的伤害。该伤害视为普通攻击伤害。');
INSERT INTO `genshin_constellation` VALUES (685, 10901, '梦见月瑞希', 1, '宿雾若水遥', '梦见月瑞希处于梦浮状态下时，每3.5秒将对附近的敌人施加持续3秒的「二十三夜待」效果。处于二十三夜待状态下的敌人受到风元素伤害而触发扩散反应时，将移除该效果，使此次扩散反应对该敌人造成的伤害提升，提升值相当于梦见月瑞希元素精通的1100%。', '梦见月瑞希处于梦浮状态下时，每3.5秒将对附近的敌人施加持续3秒的「二十三夜待」效果。处于二十三夜待状态下的敌人受到风元素伤害而触发扩散反应时，将移除该效果，使此次扩散反应对该敌人造成的伤害提升，提升值相当于梦见月瑞希元素精通的1100%。');
INSERT INTO `genshin_constellation` VALUES (686, 10901, '梦见月瑞希', 2, '缠忆君影梦相见', '进入梦浮状态时，梦见月瑞希的每点元素精通，会为附近的队伍中所有其他角色提供0.04%<color=#FF9999FF>火元素、<color=#80C0FFFF>水元素、<color=#99FFFFFF>冰元素与<color=#FFACFFFF>雷元素伤害加成，效果持续至梦浮状态结束。', '进入梦浮状态时，梦见月瑞希的每点元素精通，会为附近的队伍中所有其他角色提供0.04%火元素、水元素、冰元素与雷元素伤害加成，效果持续至梦浮状态结束。');
INSERT INTO `genshin_constellation` VALUES (687, 10901, '梦见月瑞希', 3, '晓月又经宵', '元素战技<color=#FFD780FF>秋沙歌枕巡礼的技能等级提高3级。\r\n至多提升至15级。', '元素战技秋沙歌枕巡礼的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (688, 10901, '梦见月瑞希', 4, '泉轻流花暖', '拾取元素爆发<color=#FFD780FF>安乐秘汤疗法中的<color=#FFD780FF>梦见风名物点心时，将同时造成伤害与治疗，并为梦见月瑞希恢复5点元素能量。一次<color=#FFD780FF>安乐秘汤疗法持续期间，至多通过这种方式恢复4次元素能量。', '拾取元素爆发安乐秘汤疗法中的梦见风名物点心时，将同时造成伤害与治疗，并为梦见月瑞希恢复5点元素能量。一次安乐秘汤疗法持续期间，至多通过这种方式恢复4次元素能量。');
INSERT INTO `genshin_constellation` VALUES (689, 10901, '梦见月瑞希', 5, '岁云暮矣待月归', '元素爆发<color=#FFD780FF>安乐秘汤疗法的技能等级提高3级。\r\n至多提升至15级。', '元素爆发安乐秘汤疗法的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (690, 10901, '梦见月瑞希', 6, '慕念萦心间', '梦见月瑞希处于梦浮状态下时，队伍中附近的角色触发的扩散反应造成的伤害能够造成暴击，暴击率固定为30%，暴击伤害固定为100%。', '梦见月瑞希处于梦浮状态下时，队伍中附近的角色触发的扩散反应造成的伤害能够造成暴击，暴击率固定为30%，暴击伤害固定为100%。');
INSERT INTO `genshin_constellation` VALUES (691, 6401, '云堇', 1, '飞身趟马', '<color=#FFD780FF>旋云开相的冷却时间减少18%。', '旋云开相的冷却时间减少18%。');
INSERT INTO `genshin_constellation` VALUES (692, 6401, '云堇', 2, '诸般切末', '施放<color=#FFD780FF>破嶂见旌仪后，附近队伍中所有角色普通攻击造成的伤害提升15%，持续12秒。', '施放破嶂见旌仪后，附近队伍中所有角色普通攻击造成的伤害提升15%，持续12秒。');
INSERT INTO `genshin_constellation` VALUES (693, 6401, '云堇', 3, '牙纛探海', '<color=#FFD780FF>破嶂见旌仪的技能等级提高3级。\r\n至多提升至15级。', '破嶂见旌仪的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (694, 6401, '云堇', 4, '昇堂吊云', '云堇触发结晶、月结晶反应后，防御力提升20%，持续12秒。', '云堇触发结晶、月结晶反应后，防御力提升20%，持续12秒。');
INSERT INTO `genshin_constellation` VALUES (695, 6401, '云堇', 5, '翘楚名坤', '<color=#FFD780FF>旋云开相的技能等级提高3级。\r\n至多提升至15级。', '旋云开相的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (696, 6401, '云堇', 6, '庄谐并举', '处于<color=#FFD780FF>「飞云旗阵」状态下的角色，普通攻击的攻击速度提升12%。', '处于「飞云旗阵」状态下的角色，普通攻击的攻击速度提升12%。');
INSERT INTO `genshin_constellation` VALUES (697, 3001, '钟离', 1, '岩者，六合引之为骨', '<color=#FFD780FF>地心创造的岩脊至多可以同时存在2个。', '地心创造的岩脊至多可以同时存在2个。');
INSERT INTO `genshin_constellation` VALUES (698, 3001, '钟离', 2, '石者，八荒韫玉而明', '<color=#FFD780FF>天星陨落时，会为附近的当前场上角色赋予玉璋护盾。', '天星陨落时，会为附近的当前场上角色赋予玉璋护盾。');
INSERT INTO `genshin_constellation` VALUES (699, 3001, '钟离', 3, '圭璋，暝仍不移其晖', '<color=#FFD780FF>地心的技能等级提高3级。\r\n至多提升至15级。', '地心的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (700, 3001, '钟离', 4, '黄琮，破而不夺其坚', '<color=#FFD780FF>天星的影响范围扩大20%。\r\n此外，天星的石化效果持续时间延长2秒。', '天星的影响范围扩大20%。\r\n此外，天星的石化效果持续时间延长2秒。');
INSERT INTO `genshin_constellation` VALUES (701, 3001, '钟离', 5, '苍璧，驱之长昭天理', '<color=#FFD780FF>天星的技能等级提高3级。\r\n至多提升至15级。', '天星的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (702, 3001, '钟离', 6, '金玉，礼予天地四方', '玉璋护盾受到伤害时，将为当前角色恢复生命值，回复量为伤害的40%。\r\n单次回复量不超过当前角色最大生命值的8%。', '玉璋护盾受到伤害时，将为当前角色恢复生命值，回复量为伤害的40%。\r\n单次回复量不超过当前角色最大生命值的8%。');
INSERT INTO `genshin_constellation` VALUES (703, 12601, '兹白', 1, '出勃然而入寥然', '施放元素战技<color=#FFD780FF>天地忽然身后，兹白会立即积攒100点<color=#FFD780FF>「时隙浮光」，且<color=#FFD780FF>「月转时隙」模式下<color=#FFD780FF>灵驹飞踏的最大可用次数增加至5次。\r\n此外，每次切换至「月转时隙」模式后，初次施放灵驹飞踏时，第二段攻击造成的月结晶反应伤害提升220%。', '施放元素战技**天地忽然身**后，兹白会立即积攒100点**「时隙浮光」**，且「月转时隙」模式下灵驹飞踏的最大可用次数增加至5次。\r\n此外，每次切换至「月转时隙」模式后，初次施放灵驹飞踏时，第二段攻击造成的月结晶反应伤害提升220%。');
INSERT INTO `genshin_constellation` VALUES (704, 12601, '兹白', 2, '化于生而死于尸', '处于<color=#FFD780FF>「月转时隙」模式下时，队伍中附近的所有角色造成的月结晶反应伤害提升30%。\r\n\r\n<color=#FFD780FF>月兆·满辉：突破天赋<color=#FFD780FF>月下素娥降仙的效果获得提升：<color=#FFD780FF>灵驹飞踏第二段攻击造成的伤害进一步提升，提升值相当于兹白防御力的550%；该效果需要解锁突破天赋月下素娥降仙。', '处于**「月转时隙」**模式下时，队伍中附近的所有角色造成的月结晶反应伤害提升30%。\r\n\r\n月兆·满辉：突破天赋**月下素娥降仙**的效果获得提升：灵驹飞踏第二段攻击造成的伤害进一步提升，提升值相当于兹白防御力的550%；该效果需要解锁突破天赋月下素娥降仙。');
INSERT INTO `genshin_constellation` VALUES (705, 12601, '兹白', 3, '解天韬而堕其帙', '元素战技<color=#FFD780FF>天地忽然身的技能等级提高3级。\r\n至多提升至15级。', '元素战技**天地忽然身**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (706, 12601, '兹白', 4, '魂魄往而身从之', '处于<color=#FFD780FF>「月转时隙」模式下时，兹白的普通攻击连击段数不会重置，且<color=#FFD780FF>灵驹飞踏命中敌人时，兹白将获得<color=#FFD780FF>「月涣华」效果：下一次进行普通攻击时，第四段额外攻击将造成相当于原本250%的月结晶反应伤害。', '处于**「月转时隙」**模式下时，兹白的普通攻击连击段数不会重置，且灵驹飞踏命中敌人时，兹白将获得「月涣华」效果：下一次进行普通攻击时，第四段额外攻击将造成相当于原本250%的月结晶反应伤害。');
INSERT INTO `genshin_constellation` VALUES (707, 12601, '兹白', 5, '明见无值至不论', '元素爆发<color=#FFD780FF>三垣威仪法的技能等级提高3级。\r\n至多提升至15级。', '元素爆发**三垣威仪法**的技能等级提高3级。\r\n至多提升至15级。');
INSERT INTO `genshin_constellation` VALUES (708, 12601, '兹白', 6, '天地忽如一远行', '处于<color=#FFD780FF>「月转时隙」模式下时，兹白积攒<color=#FFD780FF>「时隙浮光」的效率提升50%。\r\n此外，<color=#FFD780FF>灵驹飞踏将转为消耗所有的「时隙浮光」，基于消耗的「时隙浮光」超过70点的部分，每额外消耗1点「时隙浮光」，都会使本次灵驹飞踏与接下来3秒内兹白造成的月结晶反应伤害<color=#FFD780FF>擢升1.6%。该效果无法叠加。', '处于**「月转时隙」**模式下时，兹白积攒「时隙浮光」的效率提升50%。\r\n此外，灵驹飞踏将转为消耗所有的「时隙浮光」，基于消耗的「时隙浮光」超过70点的部分，每额外消耗1点「时隙浮光」，都会使本次灵驹飞踏与接下来3秒内兹白造成的月结晶反应伤害**擢升**1.6%。该效果无法叠加。');
