INSERT INTO `genshin_domain` VALUES (4340, '炼武秘境：沉沙之渊 I', 3, '稻妻', 368, '砂流之庭', 'UI_ABYSSUS_WEAPON_PROMOTE', '武器突破素材', '在砂金永远流淌散落的祭场中，潜伏着难以抵御岩元素攻击的敌人。\r\n若能通过其中的试炼，或许能获得强化装备的物质。', 15, '[\"岩元素\", \"冰元素\"]', 15, '[\"周一\", \"周四\", \"周日\"]', '[\"队伍中所有角色的护盾强效提升40%。\", \"角色获取岩元素反应产生的晶片时，会释放冲击波，对附近的敌人造成伤害。\"]');
