INSERT INTO `genshin_domain` VALUES (4382, '炼武秘境：冥见 I', 6, '纳塔', 1188, '深古瞭望所', 'UI_ABYSSUS_WEAPON_PROMOTE', '武器突破素材', '巨龙曾在大地上竖立诸多构型奇特的建筑。古老的传说中，巨龙的羽翼相互勾连便可遮住天光，或许这形容并未存有夸张之处，又或者这句话其实是他们觊觎天外之域的隐喻。\r\n不过如今远古之龙行迹已绝，现在人们只能从那巨大构造的残型与纹路里，窥得一些古老文明的铸就之法。', 15, '[\"水元素\", \"雷元素\", \"火元素\", \"风元素\"]', 15, '[\"周一\", \"周四\", \"周日\"]', '[\"触发「夜魂迸发」后，队伍中所有角色造成的伤害提升35%，持续10秒。\"]');
