INSERT INTO `genshin_domain` VALUES (4400, '精通秘境：菫染之国 I', 3, '稻妻', 310, '菫色之庭', 'UI_ABYSSUS_AVATAR_PROUD', '天赋培养素材', '在紫樱永远盛放的祭场中，潜伏着擅闯其中的魔物。\r\n若能通过其中的试炼，或许能获得令人天赋成长的物质。', 38, '[\"雷元素\"]', 25, '[\"周一\", \"周四\", \"周日\"]', '[\"队伍中所有角色获得25%雷元素伤害加成。\", \"挑战中存在雷晶实，其中会间歇性涌现「稚雷珠」。角色获取稚雷珠后，普通攻击、重击、下落攻击、元素战技与元素爆发在命中敌人时，会释放落雷，造成雷元素伤害。\"]');
