INSERT INTO `genshin_domain` VALUES (4423, '精通秘境：真葛废都 IV', 3, '稻妻', 310, '菫色之庭', 'UI_ABYSSUS_AVATAR_PROUD', '天赋培养素材', '在紫樱永远盛放的祭场中，潜伏着擅闯其中的魔物。\r\n若能通过其中的试炼，或许能获得令人天赋成长的物质。', 88, '[\"雷元素\"]', 45, '[\"周三\", \"周六\", \"周日\"]', '[\"队伍中所有角色获得25%雷元素伤害加成。\", \"挑战中存在雷晶实，其中会间歇性涌现「稚雷珠」。角色获取稚雷珠后，普通攻击、重击、下落攻击、元素战技与元素爆发在命中敌人时，会释放落雷，造成雷元素伤害。\"]');
INSERT INTO `genshin_domain` VALUES (4430, '精通秘境：圆镜 I', 4, '须弥', 505, '昏识塔', 'UI_ABYSSUS_AVATAR_PROUD', '天赋培养素材', '数百年前曾经点燃森林，最终又被击败的古代机械静静沉睡在地下的废都中。\r\n能够粉碎其中的机关魔物的话，或许能获得令人参悟天赋成长的物资吧。', 38, '[\"草元素\", \"雷元素\", \"火元素\", \"水元素\"]', 25, '[\"周一\", \"周四\", \"周日\"]', '[\"造成元素伤害后的10秒内，队伍中所有角色造成的伤害提高10%。不同类型的元素伤害分别触发的该效果独立计时。至多叠加4次这种伤害提高效果。\"]');
