INSERT INTO `genshin_domain` VALUES (4457, '精通秘境：旋复 IV', 6, '纳塔', 1186, '蕴火的幽墟', 'UI_ABYSSUS_AVATAR_PROUD', '天赋培养素材', '曾为伟大之人的修行之所，如今却被各种宵小之徒所占据。\r\n如果能够将祭场清理干净的话，或许也能获得先人留在此处的启示吧。', 88, '[\"草元素\", \"雷元素\", \"冰元素\", \"水元素\"]', 45, '[\"周三\", \"周六\", \"周日\"]', '[\"角色的夜魂值提升或降低后的6秒内，该角色的暴击伤害提升60%。\"]');
INSERT INTO `genshin_domain` VALUES (4460, '精通秘境：旋韵 I', 5, '枫丹', 865, '苍白的遗荣', 'UI_ABYSSUS_AVATAR_PROUD', '天赋培养素材', '沉没的船舶遗迹，原本应当空无一物的终末之地，如今盘踞着无数神秘的奇异生命体。\r\n能够消灭其中的魔物的话，或许能获得令人参悟天赋成长的物资吧。', 38, '[\"岩元素\", \"水元素\", \"火元素\", \"冰元素\"]', 25, '[\"周一\", \"周四\", \"周日\"]', '[\"角色的当前生命值提升或降低时，当前场上角色的普通攻击、重击和下落攻击造成的伤害提升10%，此效果持续10秒，每0.1秒至多触发一次，至多叠加7层，每层独立计算持续时间。角色退场时，将移除该效果。\"]');
