INSERT INTO `genshin_domain` VALUES (4480, '祝圣秘境：谐律 I', 5, '枫丹', 982, '罪祸的终末', 'UI_ABYSSUS_RELIC', '圣遗物', '枫丹动能工程科学研究院的实验事故发生后，无主的构装体便也失去了控制，茫惚徘徊于临近大湖边境的洞窟中，等待着再也不会到来的指令。\r\n若能破坏其中失控的发条机关，或许能获得珍贵的圣遗物吧。', 59, '[\"水元素\", \"火元素\", \"冰元素\", \"风元素\"]', 30, NULL, '[\"角色的当前生命值提升或降低时，队伍中所有角色的暴击伤害提升7%，此效果持续10秒，每0.1秒至多触发一次，至多叠加10层，每层独立计算持续时间。\"]');
