INSERT INTO `genshin_domain` VALUES (4482, '祝圣秘境：谐律 III', 5, '枫丹', 982, '罪祸的终末', 'UI_ABYSSUS_RELIC', '圣遗物', '枫丹动能工程科学研究院的实验事故发生后，无主的构装体便也失去了控制，茫惚徘徊于临近大湖边境的洞窟中，等待着再也不会到来的指令。\r\n若能破坏其中失控的发条机关，或许能获得珍贵的圣遗物吧。', 80, '[\"水元素\", \"火元素\", \"冰元素\", \"风元素\"]', 40, NULL, '[\"角色的当前生命值提升或降低时，队伍中所有角色的暴击伤害提升7%，此效果持续10秒，每0.1秒至多触发一次，至多叠加10层，每层独立计算持续时间。\"]');
INSERT INTO `genshin_domain` VALUES (4483, '祝圣秘境：谐律 IV', 5, '枫丹', 982, '罪祸的终末', 'UI_ABYSSUS_RELIC', '圣遗物', '枫丹动能工程科学研究院的实验事故发生后，无主的构装体便也失去了控制，茫惚徘徊于临近大湖边境的洞窟中，等待着再也不会到来的指令。\r\n若能破坏其中失控的发条机关，或许能获得珍贵的圣遗物吧。', 90, '[\"水元素\", \"火元素\", \"冰元素\", \"风元素\"]', 45, NULL, '[\"角色的当前生命值提升或降低时，队伍中所有角色的暴击伤害提升7%，此效果持续10秒，每0.1秒至多触发一次，至多叠加10层，每层独立计算持续时间。\"]');
INSERT INTO `genshin_domain` VALUES (4484, '祝圣秘境：朽废的集所 I', 5, '枫丹', 1142, '临瀑之城', 'UI_ABYSSUS_RELIC', '圣遗物', '一度被过去的秘密社团用做临时集会所的古代废都，它曾是更古老的团体所使用的据点之一。\r\n如今占据这里的只有不具语言与智慧的魔物。将它们击败，或许能获得珍贵的圣遗物吧。', 59, '[\"岩元素\"]', 30, NULL, '[\"角色获取结晶反应产生的晶片后，将产生「晶体赋能」状态。处于该状态下的当前场上角色的攻击力提升20%。该状态持续10秒，至多叠加3层，每层效果独立计时；叠加至3层后再次重复获取晶片时，将释放岩元素冲击波，对附近的敌人造成岩元素真实伤害，每10秒至多通过这种方式释放一次冲击波。\"]');
INSERT INTO `genshin_domain` VALUES (4485, '祝圣秘境：朽废的集所 II', 5, '枫丹', 1142, '临瀑之城', 'UI_ABYSSUS_RELIC', '圣遗物', '一度被过去的秘密社团用做临时集会所的古代废都，它曾是更古老的团体所使用的据点之一。\r\n如今占据这里的只有不具语言与智慧的魔物。将它们击败，或许能获得珍贵的圣遗物吧。', 69, '[\"岩元素\"]', 35, NULL, '[\"角色获取结晶反应产生的晶片后，将产生「晶体赋能」状态。处于该状态下的当前场上角色的攻击力提升20%。该状态持续10秒，至多叠加3层，每层效果独立计时；叠加至3层后再次重复获取晶片时，将释放岩元素冲击波，对附近的敌人造成岩元素真实伤害，每10秒至多通过这种方式释放一次冲击波。\"]');
