INSERT INTO `genshin_domain` VALUES (4500, '炼武秘境：匠理 I', 5, '枫丹', 859, '深潮的余响', 'UI_ABYSSUS_WEAPON_PROMOTE', '武器突破素材', '远离执律庭常规巡查路径的海底洞窟被各怀异心的歹人、盗匪与走私者用作据点，他们甚至还窃取了一部分发条机关。\r\n若能战胜盘踞其中的机关及其操纵者，或许能获得强化装备的物质吧。', 15, '[\"水元素\", \"火元素\", \"冰元素\", \"风元素\"]', 15, '[\"周二\", \"周五\", \"周日\"]', '[\"角色对敌人触发水元素相关反应后，队伍中所有角色将获得10%水元素伤害加成，此效果持续10秒，每2秒至多触发一次，至多叠加5层。叠加至最高层数时，将提高角色的抗打断能力。\"]');
