INSERT INTO `genshin_domain` VALUES (4510, '祝圣秘境：变奏 I', 5, '枫丹', 1151, '褪色的剧场', 'UI_ABYSSUS_RELIC', '圣遗物', '先知与君王，勇士与恶龙，黄金时代的宏伟歌剧曾在这里轮番上演。\r\n如今舞台上的演员只剩下不知从何处而来的魔物。将它们击败，或许能获得珍贵的圣遗物吧。', 59, '[\"火元素\", \"雷元素\", \"岩元素\"]', 30, NULL, '[\"生命之契的数值提升或降低时，该角色获得15%所有元素伤害与物理伤害加成，持续10秒。此效果至多叠加4层，每层独立计时。\"]');
INSERT INTO `genshin_domain` VALUES (4511, '祝圣秘境：变奏 II', 5, '枫丹', 1151, '褪色的剧场', 'UI_ABYSSUS_RELIC', '圣遗物', '先知与君王，勇士与恶龙，黄金时代的宏伟歌剧曾在这里轮番上演。\r\n如今舞台上的演员只剩下不知从何处而来的魔物。将它们击败，或许能获得珍贵的圣遗物吧。', 69, '[\"火元素\", \"雷元素\", \"岩元素\"]', 35, NULL, '[\"生命之契的数值提升或降低时，该角色获得15%所有元素伤害与物理伤害加成，持续10秒。此效果至多叠加4层，每层独立计时。\"]');
INSERT INTO `genshin_domain` VALUES (4512, '祝圣秘境：变奏 III', 5, '枫丹', 1151, '褪色的剧场', 'UI_ABYSSUS_RELIC', '圣遗物', '先知与君王，勇士与恶龙，黄金时代的宏伟歌剧曾在这里轮番上演。\r\n如今舞台上的演员只剩下不知从何处而来的魔物。将它们击败，或许能获得珍贵的圣遗物吧。', 80, '[\"火元素\", \"雷元素\", \"岩元素\"]', 40, NULL, '[\"生命之契的数值提升或降低时，该角色获得15%所有元素伤害与物理伤害加成，持续10秒。此效果至多叠加4层，每层独立计时。\"]');
INSERT INTO `genshin_domain` VALUES (4513, '祝圣秘境：变奏 IV', 5, '枫丹', 1151, '褪色的剧场', 'UI_ABYSSUS_RELIC', '圣遗物', '先知与君王，勇士与恶龙，黄金时代的宏伟歌剧曾在这里轮番上演。\r\n如今舞台上的演员只剩下不知从何处而来的魔物。将它们击败，或许能获得珍贵的圣遗物吧。', 90, '[\"火元素\", \"雷元素\", \"岩元素\"]', 45, NULL, '[\"生命之契的数值提升或降低时，该角色获得15%所有元素伤害与物理伤害加成，持续10秒。此效果至多叠加4层，每层独立计时。\"]');
INSERT INTO `genshin_domain` VALUES (4651, '精通秘境：墟都 I', 7, '挪德卡莱', 1690, '无光的深都', 'UI_ABYSSUS_AVATAR_PROUD', '天赋培养素材', '一度繁荣而后衰败的城市的残骸，神秘的结构仿佛暗示那是一个被遗忘的未来。\r\n若能消灭徘徊于此的敌人，或许能获得令天赋成长的启示吧。', 38, '[\"水元素\", \"雷元素\"]', 25, '[\"周一\", \"周四\", \"周日\"]', '[\"角色触发感电、月感电反应时，将会释放冲击波，造成范围伤害，每5秒至多释放一次冲击波。\"]');
INSERT INTO `genshin_domain` VALUES (4652, '精通秘境：墟都 II', 7, '挪德卡莱', 1690, '无光的深都', 'UI_ABYSSUS_AVATAR_PROUD', '天赋培养素材', '一度繁荣而后衰败的城市的残骸，神秘的结构仿佛暗示那是一个被遗忘的未来。\r\n若能消灭徘徊于此的敌人，或许能获得令天赋成长的启示吧。', 54, '[\"水元素\", \"雷元素\"]', 28, '[\"周一\", \"周四\", \"周日\"]', '[\"角色触发感电、月感电反应时，将会释放冲击波，造成范围伤害，每5秒至多释放一次冲击波。\"]');
