INSERT INTO `genshin_domain` VALUES (4665, '祝圣秘境：深衍 I', 7, '挪德卡莱', 1692, '霜凝的机枢', 'UI_ABYSSUS_RELIC', '圣遗物', '为了验证某些理论或是设想而建造的巨大装置群，随着结论既定，装置也失去了运转的意义。\r\n若能战胜占据此处的宵小之辈，或许就能获得珍贵的圣遗物吧。', 59, '[\"草元素\", \"雷元素\", \"水元素\"]', 30, NULL, '[\"队伍的月兆等级至少为初辉时，队伍中所有角色的元素精通提升200点。\"]');
