INSERT INTO `genshin_domain` VALUES (4683, '祝圣秘境：圣库 I', 7, '挪德卡莱', 1811, '月童的库藏', 'UI_ABYSSUS_RELIC', '圣遗物', '这里曾是埋藏着古老文明火种的库藏，如今却被觊觎着圣器的恶徒与魔天的枭鸟所占据。\r\n在月光的护佑之下，驱逐盘踞其间的魔物，或许能获得珍贵的圣遗物吧。', 59, '[\"水元素\", \"岩元素\", \"雷元素\", \"草元素\"]', 30, NULL, '[\"角色触发月感电、月结晶、月绽放反应后的10秒内，队伍内所有角色造成的月感电、月结晶、月绽放伤害提升35%，防御力提升30%。\"]');
