INSERT INTO `genshin_domain` VALUES (5001, '祝圣秘境：净化之炎 I', 1, '蒙德', 35, '仲夏庭园', 'UI_ABYSSUS_RELIC', '圣遗物', '这座远古祝圣祭坛中，聚集着惧怕火元素的魔物。\r\n若能通过其中的试炼，或许能获得珍贵的圣遗物。', 34, '[\"火元素\"]', 20, NULL, '[\"引发融化反应时，会释放能量冲击，对周围的敌人造成伤害。\"]');
INSERT INTO `genshin_domain` VALUES (5002, '祝圣秘境：净化之炎 II', 1, '蒙德', 35, '仲夏庭园', 'UI_ABYSSUS_RELIC', '圣遗物', '这座远古祝圣祭坛中，聚集着惧怕火元素的魔物。\r\n若能通过其中的试炼，或许能获得珍贵的圣遗物。', 47, '[\"火元素\"]', 25, NULL, '[\"引发超载反应时，会释放能量冲击，对周围的敌人造成伤害。\", \"引发超导反应时，会受到高能打击，承受伤害。\"]');
