INSERT INTO `genshin_domain` VALUES (5014, '祝圣秘境：不移 I', 1, '蒙德', 282, '山脊守望', 'UI_ABYSSUS_RELIC', '圣遗物', '精神与躯体足够强韧、面临伤害而不屈服的人，在这间祭场中就能获得护佑。\r\n能成功克服其中试炼者，或许就能获得珍贵的圣遗物，获得实现遥不可及的梦想的助力。', 59, '[\"水元素\", \"冰元素\", \"岩元素\"]', 30, NULL, '[\"敌人的攻击命中处于护盾庇护下的角色时，会进行反噬：在攻击的敌人位置处释放冲击波，造成范围伤害。该效果每2秒只能触发一次。\"]');
