INSERT INTO `genshin_domain` VALUES (5016, '祝圣秘境：不移 III', 1, '蒙德', 282, '山脊守望', 'UI_ABYSSUS_RELIC', '圣遗物', '精神与躯体足够强韧、面临伤害而不屈服的人，在这间祭场中就能获得护佑。\r\n能成功克服其中试炼者，或许就能获得珍贵的圣遗物，获得实现遥不可及的梦想的助力。', 80, '[\"水元素\", \"冰元素\", \"岩元素\"]', 40, NULL, '[\"敌人的攻击命中处于护盾庇护下的角色时，会进行反噬：在攻击的敌人位置处释放冲击波，造成范围伤害。该效果每2秒只能触发一次。\", \"（test)血量+20%\"]');
INSERT INTO `genshin_domain` VALUES (5017, '祝圣秘境：不移 IV', 1, '蒙德', 282, '山脊守望', 'UI_ABYSSUS_RELIC', '圣遗物', '精神与躯体足够强韧、面临伤害而不屈服的人，在这间祭场中就能获得护佑。\r\n能成功克服其中试炼者，或许就能获得珍贵的圣遗物，获得实现遥不可及的梦想的助力。', 90, '[\"岩元素\"]', 45, NULL, '[\"敌人的攻击命中处于护盾庇护下的角色时，会进行反噬：在攻击的敌人位置处释放冲击波，造成范围伤害。该效果每2秒只能触发一次。\", \"（test)血量+50%\"]');
INSERT INTO `genshin_domain` VALUES (5018, '祝圣秘境：茹焰的炼场 I', 6, '纳塔', 1190, '虹灵的净土', 'UI_ABYSSUS_RELIC', '圣遗物', '据说身化虹灵的贤者曾经在此教会各个部族的勇士操使燃素的语言，只不过后来，最初的火神夺取了执掌火焰的权柄，试炼也变得可有可无。\r\n驱逐占用此处的宵小之徒，或许能获得珍贵的圣遗物吧。', 59, '[\"风元素\", \"冰元素\", \"火元素\", \"雷元素\"]', 30, NULL, '[\"角色对敌人触发火元素相关反应时，会在敌人的位置处释放冲击波，造成真实伤害。每5秒至多通过这种方式释放一次冲击波。\"]');
