INSERT INTO `genshin_domain` VALUES (5020, '祝圣秘境：茹焰的炼场 III', 6, '纳塔', 1190, '虹灵的净土', 'UI_ABYSSUS_RELIC', '圣遗物', '据说身化虹灵的贤者曾经在此教会各个部族的勇士操使燃素的语言，只不过后来，最初的火神夺取了执掌火焰的权柄，试炼也变得可有可无。\r\n驱逐占用此处的宵小之徒，或许能获得珍贵的圣遗物吧。', 80, '[\"风元素\", \"冰元素\", \"火元素\", \"雷元素\"]', 40, NULL, '[\"角色对敌人触发火元素相关反应时，会在敌人的位置处释放冲击波，造成真实伤害。每5秒至多通过这种方式释放一次冲击波。\"]');
INSERT INTO `genshin_domain` VALUES (5021, '祝圣秘境：茹焰的炼场 IV', 6, '纳塔', 1190, '虹灵的净土', 'UI_ABYSSUS_RELIC', '圣遗物', '据说身化虹灵的贤者曾经在此教会各个部族的勇士操使燃素的语言，只不过后来，最初的火神夺取了执掌火焰的权柄，试炼也变得可有可无。\r\n驱逐占用此处的宵小之徒，或许能获得珍贵的圣遗物吧。', 90, '[\"火元素\"]', 45, NULL, '[\"角色对敌人触发火元素相关反应时，会在敌人的位置处释放冲击波，造成真实伤害。每5秒至多通过这种方式释放一次冲击波。\"]');
INSERT INTO `genshin_domain` VALUES (5022, '祝圣秘境：深火的构筑 I', 6, '纳塔', 1191, '荒废砌造坞', 'UI_ABYSSUS_RELIC', '圣遗物', '一度宏伟的蓝图在此画下了中折的句点，如今只是深山之内早被废弃的荒凉场所，依稀得见从前巨大造物的影子。\r\n如果能在此处好好搜索，或许能寻得许多向天外祈望者梦寐所求之物吧。', 59, '[\"风元素\", \"火元素\", \"水元素\", \"草元素\"]', 30, NULL, '[\"角色的下落攻击命中敌人后，该角色的暴击伤害提升30%，攻击力提升20%，持续15秒。\"]');
INSERT INTO `genshin_domain` VALUES (5023, '祝圣秘境：深火的构筑 II', 6, '纳塔', 1191, '荒废砌造坞', 'UI_ABYSSUS_RELIC', '圣遗物', '一度宏伟的蓝图在此画下了中折的句点，如今只是深山之内早被废弃的荒凉场所，依稀得见从前巨大造物的影子。\r\n如果能在此处好好搜索，或许能寻得许多向天外祈望者梦寐所求之物吧。', 69, '[\"风元素\", \"雷元素\", \"水元素\", \"草元素\"]', 35, NULL, '[\"角色的下落攻击命中敌人后，该角色的暴击伤害提升30%，攻击力提升20%，持续15秒。\"]');
