INSERT INTO `genshin_domain` VALUES (5025, '祝圣秘境：深火的构筑 IV', 6, '纳塔', 1191, '荒废砌造坞', 'UI_ABYSSUS_RELIC', '圣遗物', '一度宏伟的蓝图在此画下了中折的句点，如今只是深山之内早被废弃的荒凉场所，依稀得见从前巨大造物的影子。\r\n如果能在此处好好搜索，或许能寻得许多向天外祈望者梦寐所求之物吧。', 90, '[\"风元素\", \"雷元素\", \"水元素\", \"草元素\"]', 45, NULL, '[\"角色的下落攻击命中敌人后，该角色的暴击伤害提升30%，攻击力提升20%，持续15秒。\"]');
INSERT INTO `genshin_domain` VALUES (5050, '祝圣秘境：七识 I', 4, '须弥', 507, '缘觉塔', 'UI_ABYSSUS_RELIC', '圣遗物', '来自沙海的贼匪盘踞在此间秘境深处。\r\n利用对元素之奥秘的理解，战胜踞身其中者，或许能获得珍贵的圣遗物吧。', 59, '[\"冰元素\"]', 30, NULL, '[\"队伍中所有角色的元素精通提高，提高值相当于队伍中所有角色的元素精通总和的10%。每20秒，会移除通过这种方式提高的元素精通，并重新计算。\", \"队伍中所有角色的元素精通提高，提高值相当于队伍中所有角色的元素精通总和的10%。每20秒，会移除通过这种方式提高的元素精通，并重新计算。\"]');
INSERT INTO `genshin_domain` VALUES (5051, '祝圣秘境：七识 II', 4, '须弥', 507, '缘觉塔', 'UI_ABYSSUS_RELIC', '圣遗物', '来自沙海的贼匪盘踞在此间秘境深处。\r\n利用对元素之奥秘的理解，战胜踞身其中者，或许能获得珍贵的圣遗物吧。', 69, '[\"雷元素\", \"冰元素\"]', 35, NULL, '[\"队伍中所有角色的元素精通提高，提高值相当于队伍中所有角色的元素精通总和的10%。每20秒，会移除通过这种方式提高的元素精通，并重新计算。\", \"队伍中所有角色的元素精通提高，提高值相当于队伍中所有角色的元素精通总和的10%。每20秒，会移除通过这种方式提高的元素精通，并重新计算。\"]');
INSERT INTO `genshin_domain` VALUES (5052, '祝圣秘境：七识 III', 4, '须弥', 507, '缘觉塔', 'UI_ABYSSUS_RELIC', '圣遗物', '来自沙海的贼匪盘踞在此间秘境深处。\r\n利用对元素之奥秘的理解，战胜踞身其中者，或许能获得珍贵的圣遗物吧。', 80, '[\"雷元素\", \"冰元素\", \"水元素\"]', 40, NULL, '[\"队伍中所有角色的元素精通提高，提高值相当于队伍中所有角色的元素精通总和的10%。每20秒，会移除通过这种方式提高的元素精通，并重新计算。\", \"队伍中所有角色的元素精通提高，提高值相当于队伍中所有角色的元素精通总和的10%。每20秒，会移除通过这种方式提高的元素精通，并重新计算。\"]');
INSERT INTO `genshin_domain` VALUES (5053, '祝圣秘境：七识 IV', 4, '须弥', 507, '缘觉塔', 'UI_ABYSSUS_RELIC', '圣遗物', '来自沙海的贼匪盘踞在此间秘境深处。\r\n利用对元素之奥秘的理解，战胜踞身其中者，或许能获得珍贵的圣遗物吧。', 90, '[\"雷元素\", \"冰元素\", \"水元素\"]', 45, NULL, '[\"队伍中所有角色的元素精通提高，提高值相当于队伍中所有角色的元素精通总和的10%。每20秒，会移除通过这种方式提高的元素精通，并重新计算。\", \"队伍中所有角色的元素精通提高，提高值相当于队伍中所有角色的元素精通总和的10%。每20秒，会移除通过这种方式提高的元素精通，并重新计算。\"]');
INSERT INTO `genshin_domain` VALUES (5060, '祝圣秘境：沙中孤城 I', 4, '须弥', 758, '赤金的城墟', 'UI_ABYSSUS_RELIC', '圣遗物', '被遗忘、被废弃数多世代的城墟已经成为了渺小异物的栖身处。\r\n如沙漠之风一般席卷其中的魔物，或许能获得珍贵的圣遗物吧。', 59, '[\"风元素\"]', 30, NULL, '[\"角色对敌人触发扩散反应后，队伍中所有角色获得50%风元素伤害加成，持续10秒。\"]');
INSERT INTO `genshin_domain` VALUES (5061, '祝圣秘境：沙中孤城 II', 4, '须弥', 758, '赤金的城墟', 'UI_ABYSSUS_RELIC', '圣遗物', '被遗忘、被废弃数多世代的城墟已经成为了渺小异物的栖身处。\r\n如沙漠之风一般席卷其中的魔物，或许能获得珍贵的圣遗物吧。', 69, '[\"风元素\"]', 35, NULL, '[\"角色对敌人触发扩散反应后，队伍中所有角色获得50%风元素伤害加成，持续10秒。\"]');
INSERT INTO `genshin_domain` VALUES (5062, '祝圣秘境：沙中孤城 III', 4, '须弥', 758, '赤金的城墟', 'UI_ABYSSUS_RELIC', '圣遗物', '被遗忘、被废弃数多世代的城墟已经成为了渺小异物的栖身处。\r\n如沙漠之风一般席卷其中的魔物，或许能获得珍贵的圣遗物吧。', 80, '[\"风元素\"]', 40, NULL, '[\"角色对敌人触发扩散反应后，队伍中所有角色获得50%风元素伤害加成，持续10秒。\"]');
INSERT INTO `genshin_domain` VALUES (5063, '祝圣秘境：沙中孤城 IV', 4, '须弥', 758, '赤金的城墟', 'UI_ABYSSUS_RELIC', '圣遗物', '被遗忘、被废弃数多世代的城墟已经成为了渺小异物的栖身处。\r\n如沙漠之风一般席卷其中的魔物，或许能获得珍贵的圣遗物吧。', 90, '[\"风元素\"]', 45, NULL, '[\"角色对敌人触发扩散反应后，队伍中所有角色获得50%风元素伤害加成，持续10秒。\"]');
INSERT INTO `genshin_domain` VALUES (5064, '祝圣秘境：遗世边垒 I', 4, '须弥', 803, '熔铁的孤塞', 'UI_ABYSSUS_RELIC', '圣遗物', '曾经庇护为躲避大疫而流亡至此的沙民们的边城，如今则居住着另外一群无乡的住民。\r\n在草与树的护佑之下，驱逐盘踞其间的魔物，或许能获得珍贵的圣遗物吧。', 59, '[\"草元素\"]', 30, NULL, '[\"队伍中触发草元素相关反应时，队伍中所有角色元素精通提升150点。该效果持续8秒，每1秒至多触发一次。\"]');
INSERT INTO `genshin_domain` VALUES (5065, '祝圣秘境：遗世边垒 II', 4, '须弥', 803, '熔铁的孤塞', 'UI_ABYSSUS_RELIC', '圣遗物', '曾经庇护为躲避大疫而流亡至此的沙民们的边城，如今则居住着另外一群无乡的住民。\r\n在草与树的护佑之下，驱逐盘踞其间的魔物，或许能获得珍贵的圣遗物吧。', 69, '[\"草元素\"]', 35, NULL, '[\"队伍中触发草元素相关反应时，队伍中所有角色元素精通提升150点。该效果持续8秒，每1秒至多触发一次。\"]');
