INSERT INTO `genshin_domain` VALUES (5067, '祝圣秘境：遗世边垒 IV', 4, '须弥', 803, '熔铁的孤塞', 'UI_ABYSSUS_RELIC', '圣遗物', '曾经庇护为躲避大疫而流亡至此的沙民们的边城，如今则居住着另外一群无乡的住民。\r\n在草与树的护佑之下，驱逐盘踞其间的魔物，或许能获得珍贵的圣遗物吧。', 90, '[\"草元素\"]', 45, NULL, '[\"队伍中触发草元素相关反应时，队伍中所有角色元素精通提升150点。该效果持续8秒，每1秒至多触发一次。\"]');
INSERT INTO `genshin_domain` VALUES (5100, '祝圣秘境：惊蛰 I', 2, '璃月', 48, '孤云凌霄之处', 'UI_ABYSSUS_RELIC', '圣遗物', '这座远古地脉祭坛中，聚集着觊觎着其中地脉镇石的魔物。\r\n若能驱使雷元素的力量粉碎魔物，保护镇石不被破坏，或许能获得珍贵的圣遗物。', 34, '[\"雷元素\"]', 20, NULL, '[\"感电反应造成的伤害提高150%，影响范围扩大100%。\"]');
