INSERT INTO `genshin_domain` VALUES (5104, '祝圣秘境：惊蛰 V', 2, '璃月', 48, '孤云凌霄之处', 'UI_ABYSSUS_RELIC', '圣遗物', '这座远古祝圣祭坛中，聚集着惧怕雷元素的魔物。\r\n若能通过其中的试炼，或许能获得珍贵的圣遗物。', 80, '[\"雷元素\"]', 40, NULL, '[\"引发超载反应时，会释放能量冲击，对周围的敌人造成伤害。\"]');
