INSERT INTO `genshin_domain` VALUES (5112, '祝圣秘境：岩牢 I', 2, '璃月', 50, '华池岩岫', 'UI_ABYSSUS_RELIC', '圣遗物', '这座远古祝圣祭坛中，聚集着惧怕岩元素的魔物。\r\n若能通过其中的试炼，或许能获得珍贵的圣遗物。', 69, '[\"岩元素\"]', 35, NULL, '[\"队伍中所有角色造成的岩元素伤害提高75%。\"]');
INSERT INTO `genshin_domain` VALUES (5113, '祝圣秘境：岩牢 II', 2, '璃月', 50, '华池岩岫', 'UI_ABYSSUS_RELIC', '圣遗物', '这座远古祝圣祭坛中，聚集着惧怕岩元素的魔物。\r\n若能通过其中的试炼，或许能获得珍贵的圣遗物。', 80, '[\"岩元素\"]', 40, NULL, '[\"队伍中所有角色造成的岩元素伤害提高75%。\"]');
INSERT INTO `genshin_domain` VALUES (5114, '祝圣秘境：岩牢 III', 2, '璃月', 50, '华池岩岫', 'UI_ABYSSUS_RELIC', '圣遗物', '这座远古祝圣祭坛中，聚集着惧怕岩元素的魔物。\r\n若能通过其中的试炼，或许能获得珍贵的圣遗物。', 90, '[\"岩元素\"]', 45, NULL, '[\"队伍中所有角色造成的岩元素伤害提高75%。\"]');
INSERT INTO `genshin_domain` VALUES (5120, '祝圣秘境：告死之霜 I', 1, '蒙德', 221, '芬德尼尔之顶', 'UI_ABYSSUS_RELIC', '圣遗物', '这里原本是靠近天空的仪式场所，被天降的寒天之钉埋入山体。\r\n涌入的寒气造就了这里独特的环境。要通过试炼，就必须克服其中的严寒…', 59, '[\"火元素\"]', 30, NULL, '[\"挑战平台中的角色会持续积累「严寒」。严寒达到上限时，会损失生命值。\", \"挑战平台中的地面会间歇性变为「温暖」与「极寒」状态。\", \"温暖状态的地面可以削减严寒积累，极寒的地面会加速严寒积累。\"]');
INSERT INTO `genshin_domain` VALUES (5121, '祝圣秘境：告死之霜 II', 1, '蒙德', 221, '芬德尼尔之顶', 'UI_ABYSSUS_RELIC', '圣遗物', '这里原本是靠近天空的仪式场所，被天降的寒天之钉埋入山体。\r\n涌入的寒气造就了这里独特的环境。要通过试炼，就必须克服其中的严寒…', 69, '[\"火元素\"]', 35, NULL, '[\"挑战平台中的角色会持续积累「严寒」。严寒达到上限时，会损失生命值。\", \"挑战平台中的地面会间歇性变为「温暖」与「极寒」状态。\", \"温暖状态的地面可以削减严寒积累，极寒的地面会加速严寒积累。\"]');
INSERT INTO `genshin_domain` VALUES (5122, '祝圣秘境：告死之霜 III', 1, '蒙德', 221, '芬德尼尔之顶', 'UI_ABYSSUS_RELIC', '圣遗物', '这里原本是靠近天空的仪式场所，被天降的寒天之钉埋入山体。\r\n涌入的寒气造就了这里独特的环境。要通过试炼，就必须克服其中的严寒…', 80, '[\"火元素\"]', 40, NULL, '[\"挑战平台中的角色会持续积累「严寒」。严寒达到上限时，会损失生命值。\", \"挑战平台中的地面会间歇性变为「温暖」与「极寒」状态。\", \"温暖状态的地面可以削减严寒积累，极寒的地面会加速严寒积累。\"]');
INSERT INTO `genshin_domain` VALUES (5123, '祝圣秘境：告死之霜 IV', 1, '蒙德', 221, '芬德尼尔之顶', 'UI_ABYSSUS_RELIC', '圣遗物', '这里原本是靠近天空的仪式场所，被天降的寒天之钉埋入山体。\r\n涌入的寒气造就了这里独特的环境。要通过试炼，就必须克服其中的严寒…', 90, '[\"火元素\"]', 45, NULL, '[\"挑战平台中的角色会持续积累「严寒」。严寒达到上限时，会损失生命值。\", \"挑战平台中的地面会间歇性变为「温暖」与「极寒」状态。\", \"温暖状态的地面可以削减严寒积累，极寒的地面会加速严寒积累。\"]');
INSERT INTO `genshin_domain` VALUES (5125, '祝圣秘境：机巢 I', 2, '璃月', 516, '岩中幽谷', 'UI_ABYSSUS_RELIC', '圣遗物', '原本似乎是古代的祭场，如今已经被外来的遗迹机关占据了。\r\n能够战胜踞身其中的机关入侵者的话，或许就能获得珍贵的圣遗物吧。', 59, '[\"火元素\", \"雷元素\", \"岩元素\", \"风元素\"]', 30, NULL, '[\"角色施放元素战技时，将释放冲击波，造成真实伤害。\"]');
INSERT INTO `genshin_domain` VALUES (5126, '祝圣秘境：机巢 II', 2, '璃月', 516, '岩中幽谷', 'UI_ABYSSUS_RELIC', '圣遗物', '原本似乎是古代的祭场，如今已经被外来的遗迹机关占据了。\r\n能够战胜踞身其中的机关入侵者的话，或许就能获得珍贵的圣遗物吧。', 69, '[\"火元素\", \"雷元素\", \"岩元素\", \"风元素\"]', 35, NULL, '[\"角色施放元素战技时，将释放冲击波，造成真实伤害。\"]');
INSERT INTO `genshin_domain` VALUES (5127, '祝圣秘境：机巢 III', 2, '璃月', 516, '岩中幽谷', 'UI_ABYSSUS_RELIC', '圣遗物', '原本似乎是古代的祭场，如今已经被外来的遗迹机关占据了。\r\n能够战胜踞身其中的机关入侵者的话，或许就能获得珍贵的圣遗物吧。', 80, '[\"火元素\", \"雷元素\", \"岩元素\", \"风元素\"]', 40, NULL, '[\"角色施放元素战技时，将释放冲击波，造成真实伤害。\"]');
INSERT INTO `genshin_domain` VALUES (5128, '祝圣秘境：机巢 IV', 2, '璃月', 516, '岩中幽谷', 'UI_ABYSSUS_RELIC', '圣遗物', '原本似乎是古代的祭场，如今已经被外来的遗迹机关占据了。\r\n能够战胜踞身其中的机关入侵者的话，或许就能获得珍贵的圣遗物吧。', 90, '[\"火元素\", \"雷元素\", \"岩元素\", \"风元素\"]', 45, NULL, '[\"角色施放元素战技时，将释放冲击波，造成真实伤害。\"]');
INSERT INTO `genshin_domain` VALUES (5200, '祝圣秘境：椛狩 I', 3, '稻妻', 361, '椛染之庭', 'UI_ABYSSUS_RELIC', '圣遗物', '在红叶飘扬的祭场之中，如同夏秋之分，存在着增强「冰元素」与「火元素」的领域。\r\n能利用各种奥妙，成功克服其中试炼者，或许就能获得珍贵的圣遗物，获得追寻本应切断的因缘的助力。', 59, '[\"火元素\", \"冰元素\"]', 30, NULL, '[\"挑战平台的地面会间歇性地变为「炎祝」与「霜祝」状态。依据状态的不同，处在对应平台上的角色会获得不同的效果。\", \"「炎祝」：其中的当前场上角色获得60%火元素伤害加成。\", \"「霜祝」：其中的当前场上角色获得60%冰元素伤害加成。\"]');
INSERT INTO `genshin_domain` VALUES (5201, '祝圣秘境：椛狩 II', 3, '稻妻', 361, '椛染之庭', 'UI_ABYSSUS_RELIC', '圣遗物', '在红叶飘扬的祭场之中，如同夏秋之分，存在着增强「冰元素」与「火元素」的领域。\r\n能利用各种奥妙，成功克服其中试炼者，或许就能获得珍贵的圣遗物，获得追寻本应切断的因缘的助力。', 69, '[\"火元素\", \"冰元素\"]', 35, NULL, '[\"挑战平台的地面会间歇性地变为「炎祝」与「霜祝」状态。依据状态的不同，处在对应平台上的角色会获得不同的效果。\", \"「炎祝」：其中的当前场上角色获得60%火元素伤害加成。\", \"「霜祝」：其中的当前场上角色获得60%冰元素伤害加成。\"]');
INSERT INTO `genshin_domain` VALUES (5202, '祝圣秘境：椛狩 III', 3, '稻妻', 361, '椛染之庭', 'UI_ABYSSUS_RELIC', '圣遗物', '在红叶飘扬的祭场之中，如同夏秋之分，存在着增强「冰元素」与「火元素」的领域。\r\n能利用各种奥妙，成功克服其中试炼者，或许就能获得珍贵的圣遗物，获得追寻本应切断的因缘的助力。', 80, '[\"火元素\", \"冰元素\"]', 40, NULL, '[\"挑战平台的地面会间歇性地变为「炎祝」与「霜祝」状态。依据状态的不同，处在对应平台上的角色会获得不同的效果。\", \"「炎祝」：其中的当前场上角色获得60%火元素伤害加成。\", \"「霜祝」：其中的当前场上角色获得60%冰元素伤害加成。\"]');
INSERT INTO `genshin_domain` VALUES (5203, '祝圣秘境：椛狩 IV', 3, '稻妻', 361, '椛染之庭', 'UI_ABYSSUS_RELIC', '圣遗物', '在红叶飘扬的祭场之中，如同夏秋之分，存在着增强「冰元素」与「火元素」的领域。\r\n能利用各种奥妙，成功克服其中试炼者，或许就能获得珍贵的圣遗物，获得追寻本应切断的因缘的助力。', 90, '[\"火元素\", \"冰元素\"]', 45, NULL, '[\"挑战平台的地面会间歇性地变为「炎祝」与「霜祝」状态。依据状态的不同，处在对应平台上的角色会获得不同的效果。\", \"「炎祝」：其中的当前场上角色获得60%火元素伤害加成。\", \"「霜祝」：其中的当前场上角色获得60%冰元素伤害加成。\"]');
INSERT INTO `genshin_domain` VALUES (5204, '祝圣秘境：骸馆 I', 3, '稻妻', 433, '沉眠之庭', 'UI_ABYSSUS_RELIC', '圣遗物', '无主的宅邸如今成为了兽境魔物的栖身之所。\r\n能利用永恒之雷，成功克服其中试炼者，或许就能获得珍贵的圣遗物吧。', 59, '[\"雷元素\"]', 30, NULL, '[\"队伍中所有角色获得40%雷元素伤害加成。\", \"当前场上角色使敌人触发感电反应时，会释放冲击波，对敌人造成真实伤害。每3秒至多通过这种方式释放一次冲击波。\"]');
