INSERT INTO `genshin_domain` VALUES (5254, '精通秘境：炽炎祭场 I', 2, '璃月', 46, '太山府', 'UI_ABYSSUS_AVATAR_PROUD', '天赋培养素材', '这座炽热的古代祭祀场中，聚积了大量的火元素之力。\r\n置身其中会受到持续的高热灼烧。\r\n若能通过其中的试炼，或许能获得令人天赋成长的物质。', 38, '[\"水元素\", \"冰元素\", \"雷元素\"]', 25, '[\"周一\", \"周四\", \"周日\"]', '[\"周期性为角色施加「阴燃之火」：在附着的火元素消除之前，持续受到火元素伤害。\"]');
