INSERT INTO `genshin_enemy` VALUES (20010101, 20010101, '草史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '因为充沛的草元素，而发生了生态上的质变的史莱姆。\r\n从生态而言，也获得了草元素的弱点。一旦遇上明火，就会剧烈地燃烧。');
INSERT INTO `genshin_enemy` VALUES (20010201, 20010201, '大型草史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '因为充沛的草元素，而发生了生态上的质变的史莱姆。\r\n但也有人认为，从热衷于通过欺骗性的伪装来偷袭猎物，类似骗骗花的捕猎行为来看，或许是被特殊的植物寄生的史莱姆。从这个角度来看，草史莱姆在某些文化当中，或许被认为具有特别的药用价值…？');
INSERT INTO `genshin_enemy` VALUES (20010301, 20010301, '风史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的风元素凝聚形成的小小魔物。\r\n因为风元素的力量，所以具有一定程度的飘浮能力。');
INSERT INTO `genshin_enemy` VALUES (20010401, 20010401, '大型风史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的风元素凝聚形成的魔物。\r\n相比风史莱姆，因为含有更浓厚的风元素，所以漂浮能力也更强。常年生活在荒野中的丘丘人似乎也会利用这种特性，制作特殊的、以大型风史莱姆为动力的载具，运输不知从何而来的物资。');
INSERT INTO `genshin_enemy` VALUES (20010501, 20010501, '雷史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的雷元素凝聚形成的小小魔物，能够放出微弱的电力。\r\n根据分析，雷史莱姆蹦蹦跳跳的运动方式能反映地面上的电势差。在雷元素极其丰沛的地方，可以通过观察雷史莱姆的异常运动，避开危险。');
INSERT INTO `genshin_enemy` VALUES (20010601, 20010601, '大型雷史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的雷元素凝聚形成的魔物。\r\n因为体内充沛的雷元素，会间歇性向周围放电。目前，已经有人开始尝试利用这种能量去进行有益的生产活动了，新的学科或许不日也将应运而生…？');
INSERT INTO `genshin_enemy` VALUES (20010701, 20010701, '变异雷史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的雷元素凝聚形成的魔物。\r\n雷史莱姆异变产生的，明黄色的史莱姆。因为体内充沛的雷元素，会间歇性向周围放电，并能向附近的雷史莱姆放出电弧；但紫色的雷史莱姆之间并不会通电。由此看来，雷史莱姆似乎具有两极。\r\n以此为基点，或许能成为某种伟大学科的开端…');
INSERT INTO `genshin_enemy` VALUES (20010801, 20010801, '冰史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的冰元素凝聚形成的小小魔物。\r\n过去曾经有竞争对手恶意谣传说，「晨曦酒庄」会利用冰史莱姆来调控酒窖的温度，以此保证酒品的质量。');
INSERT INTO `genshin_enemy` VALUES (20010901, 20010901, '大型冰史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的冰元素凝聚形成的魔物。\r\n会利用体内凝聚的丰沛的冰元素，将大气中的水汽凝结成具有保护性的外壳；也会利用同样的原理，将周围的水面冻结。某种意义上是最自由的史莱姆，可以轻松自在地渡过汪洋大海。');
INSERT INTO `genshin_enemy` VALUES (20011001, 20011001, '水史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的水元素沉积形成的小小魔物。\r\n传说中，有的人会将水史莱姆当作应急用水，在去往水源难寻的干旱地带、深邃的秘境之前储备好水史莱姆。但因为浓厚的水元素，直饮史莱姆其实对人体有害。');
INSERT INTO `genshin_enemy` VALUES (20011101, 20011101, '大型水史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的水元素沉积形成的魔物。\r\n力量更强大、体型更大的水史莱姆，可以产生水泡禁锢敌人。据说在某些力量充沛的地方，尺寸可以成长到非常夸张的程度。在奔狼领就曾有人目击过有一座小土丘那么大的水史莱姆。');
INSERT INTO `genshin_enemy` VALUES (20011201, 20011201, '火史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的火元素沉积形成的小小魔物。\r\n具有非常基础的智能水平，但似乎具有很广泛的用途。对丘丘人而言。');
INSERT INTO `genshin_enemy` VALUES (20011301, 20011301, '大型火史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '逸散在自然之中的火元素沉积形成的魔物。\r\n虽然智能水平并没有随着体型的成长而提高，但真的很热。在干燥的季节，可能会引发野火。愤怒的时候会喷吐炽热的火球，情绪低落的时候会变暗，是表达能力很强的史莱姆。');
INSERT INTO `genshin_enemy` VALUES (20011401, 20011401, '岩史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '大地之中的岩元素凝聚形成的小小魔物。\r\n广义而言，地壳之中蕴含着丰富的岩元素。由此产生的岩史莱姆也让人有着脚踏实地的感觉。');
INSERT INTO `genshin_enemy` VALUES (20011501, 20011501, '大型岩史莱姆', '[\"圆滚滚的元素之力\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '大地之中的岩元素凝聚形成的魔物。\r\n能将体内的力量凝结成岩壳，保护自己不受伤害。过去在盗宝团中一度流传着「大黄金岩史莱姆王」的说法，认为既然不少宝石与矿物中蕴含岩元素，那蕴含岩元素的史莱姆同样很可能是宝石与矿物。');
INSERT INTO `genshin_enemy` VALUES (20020101, 20020101, '狂风之核', '[\"躁动的纯粹元素\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '质量极高的风元素结核后产生的形态。\r\n狂风之核的形成意味着地方的元素地脉阻塞，其中出现了淤积。会肆无忌惮地挥霍狂风的力量，扫荡周围的人，或许也是因为它象征着此间天地的病痛吧。');
INSERT INTO `genshin_enemy` VALUES (20040101, 20040101, '无相之雷', '[\"「阿莱夫」\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '代号为「阿莱夫」的高级雷元素生命。\r\n无相元素是顶尖的元素构造体，会在元素能量喷涌的位置，或元素地脉阻塞的地点形成。\r\n不同的无相元素会基于其元素特性，进化出战斗的方式。');
INSERT INTO `genshin_enemy` VALUES (20040201, 20040201, '无相之风', '[\"「贝特」\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '代号为「贝特」的高级风元素生命。\r\n「无相」指的是抛弃了其他元素生物的形态与生态，达到的纯粹境地。\r\n针对无相元素的研究，主要由须弥教令院的学者主导进行。但由于其危险性，除了代号与命名以外，基本没有取得什么值得参考的研究成果…');
INSERT INTO `genshin_enemy` VALUES (20040301, 20040301, '无相之岩', '[\"「基末尔」\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '代号为「基末尔」的高级岩元素生命。\r\n无相元素本身是超浓缩的构造体，拥有极高的质量。\r\n浓缩成硬质固体的元素超质壳是惰性的，只有内部的核会活跃发生元素反应。');
INSERT INTO `genshin_enemy` VALUES (20040401, 20040401, '无相之水', '[\"「希伊」\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '代号为「希伊」的高级水元素生命。\r\n无相元素有强大的排异本能，会无情地驱逐试探它的人。\r\n排异习性的对象似乎甚至会延展到天然的元素上。');
INSERT INTO `genshin_enemy` VALUES (20040501, 20040501, '无相之冰', '[\"「塔勒特」\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '代号为「塔勒特」的高级冰元素生命。\r\n根据研究，无相元素与常规的元素生物在物质构成上有着细微的差别。而这些细微的成分差别，或许就是它们高度稳定的形态与机械般的行动方式的由来吧。');
INSERT INTO `genshin_enemy` VALUES (20040601, 20040601, '无相之火', '[\"「亚因」\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '代号为「亚因」的高级火元素生命。\r\n根据学者的研究，无相元素与当地元素脉络的异常有着密切的关联。但究竟是无相元素的存在影响了元素脉络，还是异变的元素能量创生了无相元素，就不得而知了。');
INSERT INTO `genshin_enemy` VALUES (20040701, 20040701, '无相之草', '[\"「扎因」\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '代号为「扎因」的高级草元素生命。\r\n依据学者的推想，无相元素具有「学习」的智慧，进而产生了利用「拟态」进行攻击的能力。但能够摄入信息、产生变化，就可能遭受信息的污染。在学习、变化的过程中，原本诞生的目的——尽管如今在学界中仍是未解之谜——或许也会被歪曲、变得无关紧要吧。');
INSERT INTO `genshin_enemy` VALUES (20050101, 20050101, '纯水精灵', '[\"纯水精灵·娅卡丝忒\", \"纯水精灵·阿德蜜特\", \"纯水精灵·爱丝特萝普\", \"纯水精灵·艾蕾特拉\", \"纯水精灵·厄斐拉\", \"纯水精灵·普丽朵拉\", \"纯水精灵·蜜涅丝托\", \"纯水精灵·克利欧\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '极纯的水元素凝结成的生命体，常与水体相伴。\r\n据说，水体越纯净，其中的水元素越丰沛，纯水精灵的力量就越强。又有传说认为，纯水精灵曾是来自异乡的水之亲眷。怀着已殁之神的碎片，流落到了世界各处，或许是为了让她们的神对世界的爱，循着水流广布大地…');
INSERT INTO `genshin_enemy` VALUES (20051001, 20051001, '浊水粉碎幻灵', '[\"无源之水\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '在纯水精灵如今在枫丹已经绝迹的当下，水中出现的奇异元素生命体。\r\n在灾难后才出现的这种元素生灵不具备往昔纯水精灵的优美，因此被称为「浊水」。尽管溶解在水中的毒已经被稀释、净化，但除非何处仍有纯粹之水的容器，枫丹的水中再也不会自然地诞生纯水精灵了。');
INSERT INTO `genshin_enemy` VALUES (20051101, 20051101, '浊水喷吐幻灵', '[\"无源之水\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '在纯水精灵如今在枫丹已经绝迹的当下，水中出现的奇异元素生命体。\r\n据说在厄歌莉娅的时代，纯水精灵常常与人同行，也曾经散布各地的清澈泉水中，借此将世界的水脉相互联系。但她们大多都随她们的神一同死去了，余下的也不再有她们的神。');
INSERT INTO `genshin_enemy` VALUES (20051201, 20051201, '水形幻人', '[\"苏醒的生命\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '由水凝聚成的初具人形的魔物。');
INSERT INTO `genshin_enemy` VALUES (20060101, 20060101, '水飘浮灵', '[\"飘游的元素之灵\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '高浓度的水元素孕育而生的魔物，能够飘浮在空中。\r\n在月夜里，飘荡在河边的水飘浮灵散发着幽光。鬼鬼祟祟的它们常被路过的旅人当作游魂，也因此成为了不少乡间民话的常客。');
INSERT INTO `genshin_enemy` VALUES (20060201, 20060201, '岩飘浮灵', '[\"飘游的元素之灵\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '高浓度的岩元素孕育而生的魔物，能够飘浮在空中。\r\n岩飘浮灵在翅叶闭合时会拟态成某种植物果实的样子。因此在一些古老的传说中，它们被当作天上巨木结出的果实，被认为有着神奇的药用价值。');
INSERT INTO `genshin_enemy` VALUES (20060301, 20060301, '风飘浮灵', '[\"飘游的元素之灵\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '高浓度的风元素孕育而生的魔物，能够飘浮在空中。\r\n从理论上来说，风元素凝固而成的魔物本身就具有一定的飘浮能力。由此看来，它们花瓣一样的翅叶首先应该是一种拟态器官。');
INSERT INTO `genshin_enemy` VALUES (20060401, 20060401, '冰飘浮灵', '[\"飘游的元素之灵\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '高浓度的冰元素孕育而生的魔物，能够飘浮在空中。\r\n曾经有炼金术士调查过飘浮灵。他认为史莱姆和旅行者都能不借用神之眼使用元素，所以飘浮灵应该是史莱姆或者旅行者。他被导师训斥了。');
INSERT INTO `genshin_enemy` VALUES (20060501, 20060501, '雷飘浮灵', '[\"飘游的元素之灵\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '高浓度的雷元素孕育而生的魔物，能够飘浮在空中。\r\n曾经有学者对它们这个物种进行过研究。他认为无相元素有元素特征、会在元素浓度高的区域诞生，和飘浮灵完全一样。所以飘浮灵是一种无相。他后来被调查出了学术腐败。');
INSERT INTO `genshin_enemy` VALUES (20060601, 20060601, '火飘浮灵', '[\"飘游的元素之灵\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '高浓度的火元素孕育而生的魔物，能够飘浮在空中。\r\n曾经有教令院的学生对它们的生态进行过研究。他认为晶蝶能飞、会在元素浓度高的区域诞生，和飘浮灵完全一样。所以飘浮灵是一种晶蝶。他现在也没毕业。');
INSERT INTO `genshin_enemy` VALUES (20060701, 20060701, '草飘浮灵', '[\"飘游的元素之灵\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '高浓度的草元素孕育而生的魔物，能够飘浮在空中。\r\n曾经有因论派的研究员对草飘浮灵的生态特征进行过研究，发现与传说中的「兰那罗」非常相似。他在一番考据后得出结论，所谓兰那罗其实就是草飘浮灵。后来这位研究员成为了籍籍无名的童话作家。');
INSERT INTO `genshin_enemy` VALUES (20070101, 20070101, '雷音权现', '[\"霆雷的忿恨意志\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '异常的雷元素生命。虽然外貌上与纯水精灵有相似之处，却不具备她的智慧与记忆。\r\n驱动雷音权现的是更为原始纯粹的愤怒。\r\n据说这种生物只会随着雷霆降生在遗留着强大忿恨的地方，譬如说支离破碎、雷云黝黝的天云峠。只要土地中的怨恨不消，那雷鸣也不会断绝吧。');
INSERT INTO `genshin_enemy` VALUES (20080101, 20080101, '辉电·霜夜灵嗣', '[\"辉电\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '体态瑰美优雅的元素生命，具备极强的元素亲和力。在漫长的岁月中沐染着高浓度的雷元素，最终演化成了如今的形貌。\r\n性情最为暴烈的形态之一。如同驱使仆役一般驱使着足以震碎钢铁的雷霆，行过之处亦会被电弧留下灾罚般的痕迹。\r\n在终北遗存的祷歌中，它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。或许正是因为如此，它们才会因无法忍受自身的纯白被染上天光的七色，而开始拒斥一切过于接近它们的生灵吧。');
INSERT INTO `genshin_enemy` VALUES (20080201, 20080201, '蔓结·霜夜灵嗣', '[\"蔓结\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '体态瑰美优雅的元素生命，具备极强的元素亲和力。在漫长的岁月中沐染着高浓度的草元素，最终演化成了如今的形貌。\r\n与苍林的草木有着奇妙的共鸣。据说某一任咏月使曾在它们的帮助下与林地立定了契约，自此方才与这片土地上的生灵成为友伴。\r\n在终北遗存的祷歌中，它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。或许正是因为如此，它们才会因无法忍受自身的纯白被染上天光的七色，而开始拒斥一切过于接近它们的生灵吧。');
INSERT INTO `genshin_enemy` VALUES (20080301, 20080301, '灼烜·霜夜灵嗣', '[\"灼烜\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '体态瑰美优雅的元素生命，具备极强的元素亲和力。在漫长的岁月中沐染着高浓度的火元素，最终演化成了如今的形貌。\r\n性情最为暴烈的形态之一。即便是在寒冷的边地，周身依然萦绕着永不熄灭的流火。\r\n在终北遗存的祷歌中，它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。或许正是因为如此，它们才会因无法忍受自身的纯白被染上天光的七色，而开始拒斥一切过于接近它们的生灵吧。');
INSERT INTO `genshin_enemy` VALUES (20080401, 20080401, '凌晶·霜夜灵嗣', '[\"凌晶\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '体态瑰美优雅的元素生命，具备极强的元素亲和力。在漫长的岁月中沐染着高浓度的冰元素，最终演化成了如今的形貌。\r\n据说这是最接近霜夜灵嗣原本姿态的模样。它们用霜雾与冰晶筑起坚壁，也许只是为了将无瑕的源光与月下的世界隔绝开。\r\n在终北遗存的祷歌中，它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。或许正是因为如此，它们才会因无法忍受自身的纯白被染上天光的七色，而开始拒斥一切过于接近它们的生灵吧。');
INSERT INTO `genshin_enemy` VALUES (20080501, 20080501, '涌流·霜夜灵嗣', '[\"涌流\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '体态瑰美优雅的元素生命，具备极强的元素亲和力。在漫长的岁月中沐染着高浓度的水元素，最终演化成了如今的形貌。\r\n澄莹的身躯几乎是由至纯的水露构成。与其他同族相比，性情稍稍温顺一些，但在被激怒时，亦会瞬间凝结出锋利的水刃，刺穿来犯者的防御。\r\n在终北遗存的祷歌中，它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。或许正是因为如此，它们才会因无法忍受自身的纯白被染上天光的七色，而开始拒斥一切过于接近它们的生灵吧。');
INSERT INTO `genshin_enemy` VALUES (20080601, 20080601, '驰岚·霜夜灵嗣', '[\"驰岚\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '体态瑰美优雅的元素生命，具备极强的元素亲和力。在漫长的岁月中沐染着高浓度的风元素，最终演化成了如今的形貌。\r\n流风为它们纺成了额外的羽翼。由于几乎不会在地面上留下足迹，有时也会被称作踏风而过者。\r\n在终北遗存的祷歌中，它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。或许正是因为如此，它们才会因无法忍受自身的纯白被染上天光的七色，而开始拒斥一切过于接近它们的生灵吧。');
INSERT INTO `genshin_enemy` VALUES (20080701, 20080701, '金礞·霜夜灵嗣', '[\"金礞\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '体态瑰美优雅的元素生命，具备极强的元素亲和力。在漫长的岁月中沐染着高浓度的岩元素，最终演化成了如今的形貌。\r\n积聚的岩元素几乎将身躯完全覆盖，坚固的角冠也闪耀着如同金珀般的光芒。\r\n在终北遗存的祷歌中，它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。或许正是因为如此，它们才会因无法忍受自身的纯白被染上天光的七色，而开始拒斥一切过于接近它们的生灵吧。');
INSERT INTO `genshin_enemy` VALUES (20081001, 20081001, '霜夜巡天灵主', '[\"霜夜巡天灵主\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ELEMENTAL', '元素生命', '于月光的残辉中巡行的高傲生灵，使役着如今早已被高天之主驯化的古老力量。\r\n传说这些优雅的灵兽诞生于霜月依然轮转的年岁，又因着神使的偏宠而不会为天光所侵染。时至今日，即便是在霜月的追随者中，它们亦被视作已不存此世的圣兽，沿着月光的秘径隐遁到了世界之外。但正如过去的数十个百年一般，它们依然漫行于月光的影子中，漫行于两个世界的边际，巡护这被灾厄觊觎的土地，与生活在其上的人们——因为这便是它们最初向黄金城的圣徒立定的誓言。');
INSERT INTO `genshin_enemy` VALUES (21010101, 21010101, '丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n与人类轮廓相似，却失去了智能与灵性。据记载，在大地上出没超过千年，却没有历史与文明。\r\n自五百年前漆黑的灾祸以来，便广泛地分布在大地各处。虽然力量弱小，缺乏组织，但有时也能给人们带来不小的麻烦。');
INSERT INTO `genshin_enemy` VALUES (21010201, 21010201, '打手丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n坏脾气的部落战士，朴实地信奉着肌肉的力量。如果肌肉够结实，力量够强，那终有一天也能举起巨大的盾牌，成为「丘丘暴徒」…？');
INSERT INTO `genshin_enemy` VALUES (21010301, 21010301, '木盾丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n拥有木盾的丘丘人战士，木盾不仅是坚固的防具，也是属于部落的珍贵宝物。根据不少人的报告，丘丘人会冲向扎营烹饪的旅人，撵走他们，然后抢走他们的锅盖。');
INSERT INTO `genshin_enemy` VALUES (21010401, 21010401, '射手丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n手持简陋弩机的丘丘人射手。丘丘人实际上并不具备制造弩的工艺水平。因此，一般认为，在丘丘人背后，存在着操控丘丘人，并为它们提供设备物资的组织。而与丘丘人走得很近的深渊法师尤为可疑。');
INSERT INTO `genshin_enemy` VALUES (21010501, 21010501, '火箭丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n手持简陋弩机的射手，箭头上敷了一层薄薄的易燃材料，以便烧灼其目标。前代的艾尔·马斯克认为，这是头脑灵光的丘丘人想要在捕猎时顺便完成烹饪而为的创新之事。');
INSERT INTO `genshin_enemy` VALUES (21010601, 21010601, '爆弹丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n擅长活用火史莱姆的狡猾家伙，把火史莱姆用作迎击来犯者的武器。利用火史莱姆的爆炸，投掷技巧精湛的爆弹丘丘人或许可以一次击碎五根木柱吧。');
INSERT INTO `genshin_enemy` VALUES (21010701, 21010701, '冲锋丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n为了击退来犯的冒险者，会挥舞着熊熊燃烧的棒槌，一往无前地奋勇冲锋。草原或森林中发生野火的话，通常而言，并不是因为某名特别的「骑士」，而是因为这种丘丘人的犯行。');
INSERT INTO `genshin_enemy` VALUES (21010901, 21010901, '冰箭丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n手持简陋弩机的射手，箭头上凝着不化的寒冰。好像听说这种箭头留下的伤口很难愈合，因为寒冷会减缓血液流通的速度。');
INSERT INTO `genshin_enemy` VALUES (21011001, 21011001, '雷箭丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n手持简陋弩机的射手，箭头以电气水晶的碎片磨削而成，以便命中时造成电击。据说射术百里挑一的丘丘人射手可以一次发射五枚箭矢，非常厉害。');
INSERT INTO `genshin_enemy` VALUES (21011201, 21011201, '岩盾丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n岩元素富集的地域中顽强生存的丘丘人，其坚不可摧的盾牌上增生着层层磐岩。');
INSERT INTO `genshin_enemy` VALUES (21011301, 21011301, '冰弹丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n发现了冰史莱姆的妙用，可以高效地保鲜食物。丘丘人有着活用各种史莱姆的智慧，无论是将火史莱姆、冰史莱姆制成炸药桶，还是用风史莱姆制作载具…可能这就是艰难生活带来的思维方式吧。');
INSERT INTO `genshin_enemy` VALUES (21011401, 21011401, '冰盾丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n丘丘人有着强大的环境适应性的证明。在冰元素富集的环境中，能设法利用坚冰制成盾牌保护自己。');
INSERT INTO `genshin_enemy` VALUES (21011501, 21011501, '奇怪的丘丘人', '[\"别墅之灾\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '「Homu, Homu, mimi domu!」');
INSERT INTO `genshin_enemy` VALUES (21011601, 21011601, '雷弹丘丘人', '[\"单纯的魔物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '提瓦特荒野中游荡的原始住民。\r\n对于保持着蒙昧生活的丘丘人而言，雷史莱姆似乎不像火史莱姆、风史莱姆那样用途广泛。或许有一天他们会发现雷史莱姆、变异雷史莱姆之间的元素流动，然后取得突飞猛进的发展…？');
INSERT INTO `genshin_enemy` VALUES (21020101, 21020101, '木盾丘丘暴徒', '[\"「达达·坤达拉」\", \"「耶里卡·多姆」\", \"「达达·米塔」\", \"「莫希·努努」\", \"「莫西·米塔」\", \"「达达·乌列那」\", \"「达达·涅西娜」\", \"「坤达拉·提嘎」\", \"「米塔·布卡」\", \"「马尼·普拉马」\", \"「拉塔·布卡」\", \"「达达·布卡」\", \"「提嘎·贝鲁」\", \"「达达·贝鲁」\", \"「莫沃·米塔」\", \"「尼耶·库查」\", \"「普普·莫西诺」\", \"「普普·欧多姆」\", \"「多姆·萨达」\", \"「达达·莫西诺」\", \"「达达·提嘎」\", \"「普普·马尼」\", \"「比亚·欧多姆」\", \"「达达·普拉马」\", \"「莫沃·提嘎」\", \"「阿巴·欧多姆」\", \"「达达·齐多」\", \"「普拉塔·欧多姆」\", \"「欧多姆·齐多」\", \"「提嘎·欧多姆」\", \"「古鲁·布卡」\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '经历无数战斗历练的丘丘人大块头。\r\n会利用草史莱姆创造坚固的木盾，进行战斗。\r\n拥有强健的肌肉，油亮的鬃毛，可靠的宽厚背影，一顿饭吃下很多肉的豪放，能为丘丘人抵挡毫不留情的冒险者，在部族当中有着相当崇高的地位。');
INSERT INTO `genshin_enemy` VALUES (21020201, 21020201, '火斧丘丘暴徒', '[\"「达达·坤达拉」\", \"「耶里卡·多姆」\", \"「达达·米塔」\", \"「莫希·努努」\", \"「莫西·米塔」\", \"「达达·乌列那」\", \"「达达·涅西娜」\", \"「坤达拉·提嘎」\", \"「米塔·布卡」\", \"「马尼·普拉马」\", \"「拉塔·布卡」\", \"「达达·布卡」\", \"「提嘎·贝鲁」\", \"「达达·贝鲁」\", \"「莫沃·米塔」\", \"「尼耶·库查」\", \"「普普·莫西诺」\", \"「普普·欧多姆」\", \"「多姆·萨达」\", \"「达达·莫西诺」\", \"「达达·提嘎」\", \"「普普·马尼」\", \"「比亚·欧多姆」\", \"「达达·普拉马」\", \"「莫沃·提嘎」\", \"「阿巴·欧多姆」\", \"「达达·齐多」\", \"「普拉塔·欧多姆」\", \"「欧多姆·齐多」\", \"「提嘎·欧多姆」\", \"「古鲁·布卡」\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '手持长柄大斧的丘丘人大块头。\r\n攻击大开大合，会利用火史莱姆为战斧附上火元素，具有强大的破坏力。\r\n通常，像火斧丘丘暴徒这样为武器反复淬火会导致钢铁的硬度下降，进而导致刃口容易受损。但丘丘暴徒的力量足够强大，斧子就算刃口没了也可以当锤子用。');
INSERT INTO `genshin_enemy` VALUES (21020301, 21020301, '岩盾丘丘暴徒', '[\"「达达·坤达拉」\", \"「耶里卡·多姆」\", \"「达达·米塔」\", \"「莫希·努努」\", \"「莫西·米塔」\", \"「达达·乌列那」\", \"「达达·涅西娜」\", \"「坤达拉·提嘎」\", \"「米塔·布卡」\", \"「马尼·普拉马」\", \"「拉塔·布卡」\", \"「达达·布卡」\", \"「提嘎·贝鲁」\", \"「达达·贝鲁」\", \"「莫沃·米塔」\", \"「尼耶·库查」\", \"「普普·莫西诺」\", \"「普普·欧多姆」\", \"「多姆·萨达」\", \"「达达·莫西诺」\", \"「达达·提嘎」\", \"「普普·马尼」\", \"「比亚·欧多姆」\", \"「达达·普拉马」\", \"「莫沃·提嘎」\", \"「阿巴·欧多姆」\", \"「达达·齐多」\", \"「普拉塔·欧多姆」\", \"「欧多姆·齐多」\", \"「提嘎·欧多姆」\", \"「古鲁·布卡」\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '以顽岩为盾的丘丘人大块头。\r\n对于丘丘人而言，最重要的事情就是吃肉和打架，让身体变得强壮。\r\n如果能成为丘丘暴徒这样又大又壮的战士，就能吃更多肉、打更多架、举起（几乎）坚不可摧的巨大岩盾了。');
INSERT INTO `genshin_enemy` VALUES (21020401, 21020401, '丘丘霜铠王', '[\"冰霜刻印的丘丘王者\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '雪雾中漫行的神秘「王者」。\r\n被同胞称为「Lawa」的庞大丘丘人。锻炼至极致的肉身似乎已和环境中满溢的冰元素相互融合，沉默威严有如北国的冰川。');
INSERT INTO `genshin_enemy` VALUES (21020501, 21020501, '丘丘岩盔王', '[\"磐岩刻印的丘丘王者\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '千嶂中漫行的神秘「王者」。\r\n被同胞称为「Lawa」的庞大丘丘人。环境中增生的岩元素化成了它们身体的一部分，仿佛血肉与皮肤皆由不移的山岩雕琢而成。');
INSERT INTO `genshin_enemy` VALUES (21020601, 21020601, '冰盾丘丘暴徒', '[\"「达达·坤达拉」\", \"「耶里卡·多姆」\", \"「达达·米塔」\", \"「莫希·努努」\", \"「莫西·米塔」\", \"「达达·乌列那」\", \"「达达·涅西娜」\", \"「坤达拉·提嘎」\", \"「米塔·布卡」\", \"「马尼·普拉马」\", \"「拉塔·布卡」\", \"「达达·布卡」\", \"「提嘎·贝鲁」\", \"「达达·贝鲁」\", \"「莫沃·米塔」\", \"「尼耶·库查」\", \"「普普·莫西诺」\", \"「普普·欧多姆」\", \"「多姆·萨达」\", \"「达达·莫西诺」\", \"「达达·提嘎」\", \"「普普·马尼」\", \"「比亚·欧多姆」\", \"「达达·普拉马」\", \"「莫沃·提嘎」\", \"「阿巴·欧多姆」\", \"「达达·齐多」\", \"「普拉塔·欧多姆」\", \"「欧多姆·齐多」\", \"「提嘎·欧多姆」\", \"「古鲁·布卡」\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '以严冰为盾的丘丘人大块头，会利用坚冰的巨盾战斗。\r\n普遍而言，体积庞大、活动频繁的生物需要消耗大量的热量来维持生存。由此，当代的艾尔·马斯克提出了「暴徒指数」，根据某地区中活动的丘丘暴徒数量在丘丘人总人口中占的比例，计算这些丘丘人食物获取的丰富、稳定性。');
INSERT INTO `genshin_enemy` VALUES (21020701, 21020701, '雷斧丘丘暴徒', '[\"「达达·坤达拉」\", \"「耶里卡·多姆」\", \"「达达·米塔」\", \"「莫希·努努」\", \"「莫西·米塔」\", \"「达达·乌列那」\", \"「达达·涅西娜」\", \"「坤达拉·提嘎」\", \"「米塔·布卡」\", \"「马尼·普拉马」\", \"「拉塔·布卡」\", \"「达达·布卡」\", \"「提嘎·贝鲁」\", \"「达达·贝鲁」\", \"「莫沃·米塔」\", \"「尼耶·库查」\", \"「普普·莫西诺」\", \"「普普·欧多姆」\", \"「多姆·萨达」\", \"「达达·莫西诺」\", \"「达达·提嘎」\", \"「普普·马尼」\", \"「比亚·欧多姆」\", \"「达达·普拉马」\", \"「莫沃·提嘎」\", \"「阿巴·欧多姆」\", \"「达达·齐多」\", \"「普拉塔·欧多姆」\", \"「欧多姆·齐多」\", \"「提嘎·欧多姆」\", \"「古鲁·布卡」\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '持长柄大斧的丘丘人大块头。\r\n攻击大开大合，会利用雷史莱姆为战斧附上雷元素，具有强大的破坏力。\r\n钢铁锻造的斧头是非常良好的感电材料。高大魁梧的雷斧丘丘暴徒高举大斧，召引天雷的样子对丘丘人而言可是相当雄壮的景象。');
INSERT INTO `genshin_enemy` VALUES (21020801, 21020801, '丘丘雷兜王', '[\"狂雷刻印的丘丘王者\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '雷暴中漫行的神秘「王者」。\r\n被同胞称为「Lawa」的庞大丘丘人。巨像般的身躯充满了丰富的雷元素，散逸出的元素能量以电气水晶的形式从身体的缝隙中生长出来。');
INSERT INTO `genshin_enemy` VALUES (21030101, 21030101, '水丘丘萨满', '[\"「拉塔·莫沃」\", \"「拉塔·莫沃·马尼」\", \"「拉塔·莫沃·多姆」\", \"「拉塔·莫沃·坤达拉」\", \"「拉塔·莫沃·耶里卡」\", \"「拉塔·莫沃·莫西诺」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '嘟嘟囔囔的老年丘丘人，水元素的吟颂者。\r\n在元素掌控方面颇富天资的丘丘人，其能力往往会在年老时达到顶峰。究竟是怎样的过去，令这些愚昧的生物竟能掌握生水唤雨的秘诀？');
INSERT INTO `genshin_enemy` VALUES (21030201, 21030201, '草丘丘萨满', '[\"「古沙·乌努」\", \"「古沙·多姆」\", \"「古沙·乌列那」\", \"「古沙·古沙」\", \"「古沙·欧多姆」\", \"「古沙·坤达拉」\", \"「古沙·莫沃」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '嘟嘟囔囔的老年丘丘人，草元素的唤醒者。\r\n在元素掌控方面颇富天资的丘丘人，其能力往往会在年老时达到顶峰。承载着面具下的不甘，憎恨人心的毒藤随呢喃蔓生而出。');
INSERT INTO `genshin_enemy` VALUES (21030301, 21030301, '风丘丘萨满', '[\"「莫沃·布卡」\", \"「莫沃·萨达」\", \"「莫沃·尼耶」\", \"「莫沃·普普·欧多姆」\", \"「莫沃·乌列那」\", \"「莫沃·贝鲁」\", \"「莫沃·尼尼·马尼」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '嘟嘟囔囔的老年丘丘人，风元素的传信者。\r\n在元素掌控方面颇富天资的丘丘人，其能力往往会在年老时达到顶峰，其牵掣流风的能力，正是来源于黑暗晦暝的失落记忆。');
INSERT INTO `genshin_enemy` VALUES (21030401, 21030401, '岩丘丘萨满', '[\"「萨达·米多诺」\", \"「萨达·马尼」\", \"「萨达·坤达拉」\", \"「萨达·布卡」\", \"「萨达·耶里卡」\", \"「萨达·涅西娜」\", \"「萨达·乌列那」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '嘟嘟囔囔的老年丘丘人，岩元素的倾听者。\r\n在元素掌控方面颇富天资的丘丘人，其能力往往会在年老时达到顶峰。同千古的顽岩相比，即使最年老的丘丘人也不过孩童，但记忆与经验引导它们获得了操使岩石的权能。');
INSERT INTO `genshin_enemy` VALUES (21030501, 21030501, '冰丘丘萨满', '[\"「拉塔·萨达」\", \"「拉塔·达达」\", \"「拉塔·坤达拉」\", \"「拉塔·布卡」\", \"「拉塔·欧多姆」\", \"「拉塔·马尼」\", \"「拉塔·莫西诺」\", \"「拉塔·米多诺」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '嘟嘟囔囔的老年丘丘人，冰元素的呼求者。\r\n在元素掌控方面颇富天资的丘丘人，其能力往往会在年老时达到顶峰。这些萨满熟忆寒霜的低语，更精通将之用于制敌的技艺。');
INSERT INTO `genshin_enemy` VALUES (21030601, 21030601, '雷丘丘萨满', '[\"「乌帕坤达拉·乌努·米多诺」\", \"「乌帕坤达拉·莫沃」\", \"「乌帕坤达拉·塞力」\", \"「乌帕坤达拉·库查·萨玛」\", \"「乌帕坤达拉·提加·乌努」\", \"「乌帕坤达拉·多姆·贝鲁」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '嘟嘟囔囔的老年丘丘人，雷元素的祈求者。\r\n在元素掌控方面颇富天资的丘丘人，其能力往往会在年老时达到顶峰，既然掌握了掣电引雷的高超技艺，便用这霹雳之声谱写挽歌吧。');
INSERT INTO `genshin_enemy` VALUES (21040101, 21040101, '丘丘风行游侠', '[\"永恒异乡人\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '不属于任何部族，似乎是在追寻一族命运之肇始，寻找如今已经失落的光辉的丘丘人流浪者。\r\n假使这些只有简单语言，也不具备文书传承的魔物当中，有史诗、有传奇，它们应当就是其中的主角吧。');
INSERT INTO `genshin_enemy` VALUES (21040201, 21040201, '丘丘水行游侠', '[\"永恒异乡人\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_HILICHURL', '丘丘部族', '不属于任何部族的丘丘人流浪者，如同自我流放一般在荒野中四处漫游。\r\n会在因缘的指引下帮助需要帮助的丘丘人、丘丘聚落，并在完成使命、因缘结束后启程离开。相比寻常的丘丘人似乎有更高的智能水平。');
INSERT INTO `genshin_enemy` VALUES (22010101, 22010101, '火深渊法师', '[\"深渊法师·阿德甫斯\", \"深渊法师·亚白忒\", \"深渊法师·厄各特\", \"深渊法师·赫哈特\", \"深渊法师·维赫末\", \"深渊法师·贡拉德\", \"深渊法师·忒拉\", \"深渊法师·亚忒勒\", \"深渊法师·雅弗略达\", \"深渊法师·特利翁\", \"深渊法师·阿布雷切\", \"深渊法师·乌勒非\", \"深渊法师·古劳\", \"深渊法师·修拜达\", \"深渊法师·别赫迭斯\", \"深渊法师·缪基\", \"深渊法师·路德非加\", \"深渊法师·拿多达\", \"深渊法师·涅非\", \"深渊法师·列别哈德\", \"深渊法师·律忒\", \"深渊法师·律定迦\", \"深渊法师·烈非勒\", \"深渊法师·缅因挪夫\", \"深渊法师·犹尼\", \"深渊法师·英吉迦尔\", \"深渊法师·亚博烈\", \"深渊法师·扫罗法\", \"深渊法师·亚伯迦忒\", \"深渊法师·埃兰别特\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ABYSS', '深渊', '拥有魔力，利用火元素战斗的深渊魔物。\r\n出于某种不为人知的缘由，深渊法师精通丘丘人的笨拙语言，能驾驭它们的心智。据说深渊法师略通如今几乎无人可解的失落古语，并利用这种语言的力量行使魔法。');
INSERT INTO `genshin_enemy` VALUES (22010201, 22010201, '冰深渊法师', '[\"深渊法师·阿德甫斯\", \"深渊法师·亚白忒\", \"深渊法师·厄各特\", \"深渊法师·赫哈特\", \"深渊法师·维赫末\", \"深渊法师·贡拉德\", \"深渊法师·忒拉\", \"深渊法师·亚忒勒\", \"深渊法师·雅弗略达\", \"深渊法师·特利翁\", \"深渊法师·阿布雷切\", \"深渊法师·乌勒非\", \"深渊法师·古劳\", \"深渊法师·修拜达\", \"深渊法师·别赫迭斯\", \"深渊法师·缪基\", \"深渊法师·路德非加\", \"深渊法师·拿多达\", \"深渊法师·涅非\", \"深渊法师·列别哈德\", \"深渊法师·律忒\", \"深渊法师·律定迦\", \"深渊法师·烈非勒\", \"深渊法师·缅因挪夫\", \"深渊法师·犹尼\", \"深渊法师·英吉迦尔\", \"深渊法师·亚博烈\", \"深渊法师·扫罗法\", \"深渊法师·亚伯迦忒\", \"深渊法师·埃兰别特\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ABYSS', '深渊', '驾驭着极寒的冰元素进行战斗的深渊魔物。\r\n尽管染指了强大的力量，甚至能将大气中的水蒸气凝结成冰锥，本身却佝偻而孱弱。一旦保护自身的护罩被打破，就只能任人鱼肉了。');
INSERT INTO `genshin_enemy` VALUES (22010301, 22010301, '水深渊法师', '[\"深渊法师·阿德甫斯\", \"深渊法师·亚白忒\", \"深渊法师·厄各特\", \"深渊法师·赫哈特\", \"深渊法师·维赫末\", \"深渊法师·贡拉德\", \"深渊法师·忒拉\", \"深渊法师·亚忒勒\", \"深渊法师·雅弗略达\", \"深渊法师·特利翁\", \"深渊法师·阿布雷切\", \"深渊法师·乌勒非\", \"深渊法师·古劳\", \"深渊法师·修拜达\", \"深渊法师·别赫迭斯\", \"深渊法师·缪基\", \"深渊法师·路德非加\", \"深渊法师·拿多达\", \"深渊法师·涅非\", \"深渊法师·列别哈德\", \"深渊法师·律忒\", \"深渊法师·律定迦\", \"深渊法师·烈非勒\", \"深渊法师·缅因挪夫\", \"深渊法师·犹尼\", \"深渊法师·英吉迦尔\", \"深渊法师·亚博烈\", \"深渊法师·扫罗法\", \"深渊法师·亚伯迦忒\", \"深渊法师·埃兰别特\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ABYSS', '深渊', '利用水元素战斗的深渊魔物。\r\n在冒险者当中有传说说，深渊法师作为「深渊教团」底层的执行者，活跃在世界各地、从事各种阴谋破坏。尽管他们还戏称这种水深渊法师的最大危害是会导致风湿发作，其实它们有着不容小觑的力量。');
INSERT INTO `genshin_enemy` VALUES (22010401, 22010401, '雷深渊法师', '[\"深渊法师·阿德甫斯\", \"深渊法师·亚白忒\", \"深渊法师·厄各特\", \"深渊法师·赫哈特\", \"深渊法师·维赫末\", \"深渊法师·贡拉德\", \"深渊法师·忒拉\", \"深渊法师·亚忒勒\", \"深渊法师·雅弗略达\", \"深渊法师·特利翁\", \"深渊法师·阿布雷切\", \"深渊法师·乌勒非\", \"深渊法师·古劳\", \"深渊法师·修拜达\", \"深渊法师·别赫迭斯\", \"深渊法师·缪基\", \"深渊法师·路德非加\", \"深渊法师·拿多达\", \"深渊法师·涅非\", \"深渊法师·列别哈德\", \"深渊法师·律忒\", \"深渊法师·律定迦\", \"深渊法师·烈非勒\", \"深渊法师·缅因挪夫\", \"深渊法师·犹尼\", \"深渊法师·英吉迦尔\", \"深渊法师·亚博烈\", \"深渊法师·扫罗法\", \"深渊法师·亚伯迦忒\", \"深渊法师·埃兰别特\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ABYSS', '深渊', '利用雷元素战斗的深渊魔物。\r\n曾经有一名学者阿尔瓦·尼古拉，在教令院学习时曾对雷深渊法师使用的雷元素模型进行过系统的研究，最终提出了名为「尼古拉线圈」的理论武器，可惜至今无人将其付诸实践。一说认为他的研究资料在蕈兽泛滥的时候被吃掉了。');
INSERT INTO `genshin_enemy` VALUES (22020101, 22020101, '深渊使徒·激流', '[\"深渊使徒·梵因弗烈\", \"深渊使徒·盖拉米尔\", \"深渊使徒·吉色迦\", \"深渊使徒·海因默瓦\", \"深渊使徒·黑地里奇\", \"深渊使徒·亚流奥杜斯\", \"深渊使徒·因结麻\", \"深渊使徒·坎乌甫\", \"深渊使徒·迦沃贝\", \"深渊使徒·弗兰柯拜忒\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '利用水元素战斗的魔物，隶属于「深渊教团」。\r\n这些沉默的身影是深渊的先行者，挥舞着席卷一切的浪潮之锋，斩碎一切铠甲的防御与不信的异端之心，向无虑的愚氓降下宿命的惩戒。');
INSERT INTO `genshin_enemy` VALUES (22020201, 22020201, '深渊使徒·霜落', '[\"深渊使徒·梵因弗烈\", \"深渊使徒·盖拉米尔\", \"深渊使徒·吉色迦\", \"深渊使徒·海因默瓦\", \"深渊使徒·黑地里奇\", \"深渊使徒·亚流奥杜斯\", \"深渊使徒·因结麻\", \"深渊使徒·坎乌甫\", \"深渊使徒·迦沃贝\", \"深渊使徒·弗兰柯拜忒\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '以冰霜的锋刃进行战斗的魔物，隶属于「深渊教团」。\r\n既然有散播与礼赞深邃福音的圣徒，那就有将歪曲的颂词导正，将不协音去除的使者。\r\n常有人说穿透身体的钢刀如同冰一般寒冷，但这种漆黑的冰霜据说连灵魂都能冻结。');
INSERT INTO `genshin_enemy` VALUES (22030101, 22030101, '深渊咏者·紫电', '[\"深渊咏者·亚伯托拿\", \"深渊咏者·耶法烈忒\", \"深渊咏者·赫罗摩特\", \"深渊咏者·乌恩赫罗奇\", \"深渊咏者·各摩勒弗\", \"深渊咏者·伐勒迭古尔德\", \"深渊咏者·焚尼赫特\", \"深渊咏者·迦杜范兹\", \"深渊咏者·耶甫勒胡\", \"深渊咏者·奥奇里克\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '驱雷掣电，高颂着漆黑渊薮的魔物，隶属于「深渊教团」。\r\n它们是深渊的布道者、学士。以狂雷将冥冥长夜所扭曲的深黑智慧，灌入不信者的心中，以无边的紫电，昭告侵蚀人智的伟大力量的存在。');
INSERT INTO `genshin_enemy` VALUES (22030201, 22030201, '深渊咏者·渊火', '[\"深渊咏者·亚伯托拿\", \"深渊咏者·耶法烈忒\", \"深渊咏者·赫罗摩特\", \"深渊咏者·乌恩赫罗奇\", \"深渊咏者·各摩勒弗\", \"深渊咏者·伐勒迭古尔德\", \"深渊咏者·焚尼赫特\", \"深渊咏者·迦杜范兹\", \"深渊咏者·耶甫勒胡\", \"深渊咏者·奥奇里克\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '驱使深渊之火，追寻着章典之意义的魔物。隶属于「深渊教团」。\r\n地上之人对他们的称呼其实和本意略有偏差。「咏者」也有「读经士」之意。诵读恩典之章，便会拥有强大的力量。');
INSERT INTO `genshin_enemy` VALUES (22040101, 22040101, '嗜岩·兽境幼兽', '[\"隙间侵入的异兽\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ABYSS', '深渊', '能够侵蚀世界边界的魔血之兽。「黄金」将其命名为「淋溶」。\r\n有伴随渊薮的渗透，吞噬元素的习性。值得庆幸的是这些魔兽如今数量并不多。');
INSERT INTO `genshin_enemy` VALUES (22040201, 22040201, '嗜雷·兽境幼兽', '[\"隙间侵入的异兽\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ABYSS', '深渊', '能够侵蚀世界边界的魔血之兽。「黄金」将其命名为「淋溶」。\r\n曾经的年代里，巨大的魔兽降临之时，会有大量猎犬提前显现，溶解世界的边界，打开通道。');
INSERT INTO `genshin_enemy` VALUES (22050101, 22050101, '嗜岩·兽境猎犬', '[\"隙间侵入的异兽\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '能够侵蚀世界边界的魔血之兽。「黄金」的造物。\r\n会很微妙地表现出生物习性，就如同真正的狼一般。或许是对地上的「近亲」抱有仰慕或嫉妒的感情，而梦想取而代之吧。');
INSERT INTO `genshin_enemy` VALUES (22050201, 22050201, '嗜雷·兽境猎犬', '[\"隙间侵入的异兽\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '能够侵蚀世界边界的魔血之兽。「黄金」的造物。\r\n曾经肆虐大陆，然后遭到反抗与猎捕而一度绝迹。但最近它们却又再度出现了。威胁到了清泉镇与奔狼领的黑狼之群，说的正是它们。');
INSERT INTO `genshin_enemy` VALUES (22060101, 22060101, '黄金王兽', '[\"无名的兽境之王\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ABYSS', '深渊', '来自晦暗的异界，是漆黑群狼之中的王，具有号令隐爪之异兽为它溶解空间，创造通行的裂隙的权能。\r\n王兽并没有名字，因为本身不过是「黄金」无心的造物；正因如此，才会更执着于侵入不属于它的世界，以自己的力量争取名号吧。\r\n但狼群绝非痴钝之物。此前的入侵受挫后，选择了既无人、也无守护者的荒凉远岛，为王兽的降临做准备。');
INSERT INTO `genshin_enemy` VALUES (22070101, 22070101, '黯色空壳·旗令', '[\"黯色空壳·旗令\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '漆黑的士兵。曾经是地下古国的骄傲军人，如今已经失去了一切知觉与记忆吧。\r\n即使如此，也会高举着王家的旗号进行战斗。就算忘记了同侪的模样、王家的祝福，只有这枚旗印，对它而言是绝对不能放下的。');
INSERT INTO `genshin_enemy` VALUES (22070201, 22070201, '黯色空壳·破阵', '[\"黯色空壳·破阵\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '漆黑的士兵。曾经是地下古国的骄傲军人，如今已经不再具备身为「人」的智性了。\r\n为了歼敌、为了守护而陷阵的意志似乎仍然刻在这幅空壳当中，就算已经没有人能告诉它们敌在何方，要守护的又是什么。');
INSERT INTO `genshin_enemy` VALUES (22070301, 22070301, '黯色空壳·近卫', '[\"黯色空壳·近卫\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '漆黑的士兵。曾经是地下古国的骄傲军人，如今不过是一具残留着战斗记忆的空壳罢了。\r\n万物尽头皆是废退，而这种空壳就是「黑蛇骑士」在罪、诅咒、时间的冲刷之下变成的模样。');
INSERT INTO `genshin_enemy` VALUES (22080101, 22080101, '黑蛇骑士·斩风之剑', '[\"黑蛇骑士·阿迭尔吉索\", \"黑蛇骑士·亚达伯德\", \"黑蛇骑士·厄哈尔德\", \"黑蛇骑士·罗德里各\", \"黑蛇骑士·冈特尔\", \"黑蛇骑士·西格\", \"黑蛇骑士·法拉蒙特\", \"黑蛇骑士·非力博德\", \"黑蛇骑士·亚萨斯坦因\", \"黑蛇骑士·爱尔德里克\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '在宫廷当中颇具地位的近卫军人，以名唤「至真之术」的剑斗技巧，扫除王家的敌人。\r\n「末光之剑」也曾是他们当中的一员。在王国的光荣尽数失落、一切都无可挽回之前。');
INSERT INTO `genshin_enemy` VALUES (22080201, 22080201, '黑蛇骑士·摧岩之钺', '[\"黑蛇骑士·阿迭尔吉索\", \"黑蛇骑士·亚达伯德\", \"黑蛇骑士·厄哈尔德\", \"黑蛇骑士·罗德里各\", \"黑蛇骑士·冈特尔\", \"黑蛇骑士·西格\", \"黑蛇骑士·法拉蒙特\", \"黑蛇骑士·非力博德\", \"黑蛇骑士·亚萨斯坦因\", \"黑蛇骑士·爱尔德里克\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '在宫廷当中颇具地位的近卫军人，以名唤「至真之术」的剑斗技巧，扫除王家的敌人——\r\n——虽说至真之术是剑斗技巧，但它的心得可以衍生应用于各种兵器上。在王国最黑暗的时刻，肩负守护职责的武人有时并没有选择的余裕。');
INSERT INTO `genshin_enemy` VALUES (22100501, 22100101, '深罪浸礼者', '[\"漆黑乐园的引路人\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ABYSS', '深渊', '驾驭了多种元素力量的深渊魔物，因为「进化」而获得了多余的肢体。\r\n\r\n「『深渊』之本质归根到底是与元素所不能相容的。但即使是有神的元素也会为其所裹挟、扭曲，成为深邃意志道具。从结果与效益而言，所谓的『深渊』或许与小至盗宝团手中充满元素力量的器皿、大到『神之眼』没有过多的区别吧…」\r\n——谁人遗落在逾渊地墟的笔记');
INSERT INTO `genshin_enemy` VALUES (22110101, 22110101, '大型碎石隙境原体', '[\"异界的生命组织\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '主要出现在厄里那斯的奇异生命体。\r\n在美露莘的认知里，隙境原体是基本上无害的生物，甚至有美露莘认为它十分可爱。\r\n美露莘的视觉感知与人有很大的区别。');
INSERT INTO `genshin_enemy` VALUES (22110201, 22110201, '碎石隙境原体', '[\"异界的生命组织\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '主要出现在厄里那斯的奇异生命体。\r\n在遇到荒性或芒性能量似乎会受到很强的刺激，因此尽管并不具有很强的攻击性与侵略性，这种手段似乎能够有效驱除隙境原体。');
INSERT INTO `genshin_enemy` VALUES (22110301, 22110301, '大型狂蔓隙境原体', '[\"异界的生命组织\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '主要出现在厄里那斯的奇异生命体。\r\n隙境原体在基本的生物特征上超出了已知的范畴：不属于动物、植物、蕈类与元素类。须弥的学者因此关于它到底是什么的争论从未正式结束，直到它一同被禁止作为学术研究课题立项，因为就目前人类的知识体系而言，这个问题与「语言的定义与本质」一样，无法得出有意义的确切结论。');
INSERT INTO `genshin_enemy` VALUES (22110401, 22110402, '狂蔓隙境原体', '[\"异界的生命组织\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '主要出现在厄里那斯的奇异生命体。\r\n在枫丹，最早观测到隙境原体是在灾难过后不久。当时同时留下了隙境原体攻击人与保护人的记录。');
INSERT INTO `genshin_enemy` VALUES (22120101, 22120101, '深邃摹结株·I型', '[\"虚界空想植株\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ABYSS', '深渊', '于深邃晦暗的扭曲异界降临此世的深渊魔物，拥有类似植物的形态。\r\n此种扭曲的魔物已然能够侵蚀入大地的深处，从中提取记忆以供其模仿与驱使。过往的回忆被扭曲成更加污秽与深邃的样貌，它们借由此种行为，逐渐接近世界之树的核心，以此动摇其存在的根本。\r\n据说该种魔物无时无刻不在扭曲光芒中蕴含的种种色彩，并将之转化为漆黑的信息，在张开时仿佛要扎入虚空中的枝节似乎也在佐证这一点…');
INSERT INTO `genshin_enemy` VALUES (22120201, 22120201, '深邃拟覆叶', '[\"虚界浮灭气泡\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '于深邃晦暗的扭曲异界降临此世的深渊魔物，拥有类似植物的形态。\r\n据说在漆黑的浪潮侵蚀之处，就会长出类似植物般黑暗的魔物。但植物只是表象，之所以具备这样的姿态，只不过是为了更接近树状世界的意型以从中汲取所需的概念并进行解析与模仿。\r\n也有失去理智的狂言者说，那些类似叶片般伸展出去的事物，其实是通往异界的门的雏形。');
INSERT INTO `genshin_enemy` VALUES (22130001, 22130001, '荒野幽徒', '[\"荒野幽徒\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_ABYSS', '深渊', '伴随着漆黑的迷雾，徘徊在荒原冻土上的幽魂。他们的出现似乎预兆着更可怕的灾难。\r\n月下的人们怀揣着各自的愿望踏上旅途，但并非所有愿望都能得到注视。怨憎会、爱别离、求不得，因此而无法安息的灵魂，若是被深渊所污染，或许便会化作幽魂，永远迷失在狂猎的浓雾中。');
INSERT INTO `genshin_enemy` VALUES (22131001, 22131001, '荒野狂狩士', '[\"荒野狂狩士\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '伴随着漆黑的迷雾，徘徊在荒原冻土上的幽魂。他们的出现似乎预兆着更可怕的灾难。\r\n在北陆茫茫的冻土之下，掩埋着失落古国的伟大战士。即便存在过的痕迹早已被抹去，勇士们的英魂依旧守护着黄金之国的故土。如今这些灵魂因深渊的污染而苏醒，所有敢于入侵之人都会被他们当作猎物。');
INSERT INTO `genshin_enemy` VALUES (22140101, 22140101, '深黯钓客', '[\"深黯钓客\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_ABYSS', '深渊', '穿过深黯的裂隙，自异界侵入此世的深渊魔物。\r\n曾有古代的贤哲将人类定义为无羽毛的二足走兽，意图以此区分人与无智性的野兽，进而证明灵长的优越性。从某种意义上来说，这些逡巡于寂灭的星海间、身披鳞片而非羽毛的不灭之物，这些如垂钓者般投下钩喙、攫噬各个世界生物质的无名钓客，或许同样符合这般粗浅的「人」的定义。');
INSERT INTO `genshin_enemy` VALUES (22150101, 22150101, '深黯魇语之主', '[\"深黯魇语之主\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_ABYSS', '深渊', '伏行于深黯的裂隙，窥伺此世的深渊魔物。据说那怪异、亵渎的无面形貌不过是投射于世界上的影像，其真实姿态乃是以纯粹深渊能量形式存在的无形之物。\r\n即便是妄图支配这个世界的入侵者，也不得不在一定程度上遵从世界原本的法则。直至高天的面纱破碎、地骨的护堤崩毁，来自群星的失乡者都只能像这般匿避于世界的边缘，以疯狂与谵妄的低语，徒劳无功地渗入此世吧…但世界安稳的秩序，又会持续到何时呢？');
INSERT INTO `genshin_enemy` VALUES (23010101, 23010101, '愚人众先遣队·冰铳重卫士', '[\"愚人众·狄康德\", \"愚人众·罗素\", \"愚人众·阿尔乔姆\", \"愚人众·伊戈尔\", \"愚人众·费奥多尔\", \"愚人众·弗拉基米尔\", \"愚人众·尼柯莱\", \"愚人众·马克西姆\", \"愚人众·尼古拉耶夫\", \"愚人众·约瑟夫\", \"愚人众·舍甫琴科\", \"愚人众·康斯坦丁\", \"愚人众·萨沙\", \"愚人众·亚历山大\", \"愚人众·格里戈尔\", \"愚人众·谢尔盖\", \"愚人众·米哈伊尔\", \"愚人众·帕夫洛维奇\", \"愚人众·伊斯迈洛维奇\", \"愚人众·安德烈\", \"愚人众·伊凡诺夫\", \"愚人众·基里连科\", \"愚人众·叶甫根尼\", \"愚人众·丹尼洛维奇\", \"愚人众·瓦西列夫\", \"愚人众·列奥\", \"愚人众·鲍里亚\", \"愚人众·谢苗\", \"愚人众·帕夫洛\", \"愚人众·彼得罗夫\", \"愚人众·阿列克谢\", \"愚人众·列夫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '愚人众战争机器中的士兵。\r\n配备着能在一定程度上制御元素的装备，可以利用铳形的武器喷射急冻的寒霜。\r\n虽然拥有常人不能企及的元素力量，但这种力量或许也是有其代价的吧…');
INSERT INTO `genshin_enemy` VALUES (23010201, 23010201, '愚人众先遣队·水铳重卫士', '[\"愚人众·狄康德\", \"愚人众·罗素\", \"愚人众·阿尔乔姆\", \"愚人众·伊戈尔\", \"愚人众·费奥多尔\", \"愚人众·弗拉基米尔\", \"愚人众·尼柯莱\", \"愚人众·马克西姆\", \"愚人众·尼古拉耶夫\", \"愚人众·约瑟夫\", \"愚人众·舍甫琴科\", \"愚人众·康斯坦丁\", \"愚人众·萨沙\", \"愚人众·亚历山大\", \"愚人众·格里戈尔\", \"愚人众·谢尔盖\", \"愚人众·米哈伊尔\", \"愚人众·帕夫洛维奇\", \"愚人众·伊斯迈洛维奇\", \"愚人众·安德烈\", \"愚人众·伊凡诺夫\", \"愚人众·基里连科\", \"愚人众·叶甫根尼\", \"愚人众·丹尼洛维奇\", \"愚人众·瓦西列夫\", \"愚人众·列奥\", \"愚人众·鲍里亚\", \"愚人众·谢苗\", \"愚人众·帕夫洛\", \"愚人众·彼得罗夫\", \"愚人众·阿列克谢\", \"愚人众·列夫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '愚人众战争机器中的士兵。\r\n配备着能在一定程度上制御元素的装备，可以利用铳形的武器喷射激烈的水流。\r\n「先遣队」之名意味着生死不问，深入祖国以外的土地完成前期任务，为未来的某些行动夯实基础。');
INSERT INTO `genshin_enemy` VALUES (23010301, 23010301, '愚人众先遣队·雷锤前锋军', '[\"愚人众·狄康德\", \"愚人众·罗素\", \"愚人众·阿尔乔姆\", \"愚人众·伊戈尔\", \"愚人众·费奥多尔\", \"愚人众·弗拉基米尔\", \"愚人众·尼柯莱\", \"愚人众·马克西姆\", \"愚人众·尼古拉耶夫\", \"愚人众·约瑟夫\", \"愚人众·舍甫琴科\", \"愚人众·康斯坦丁\", \"愚人众·萨沙\", \"愚人众·亚历山大\", \"愚人众·格里戈尔\", \"愚人众·谢尔盖\", \"愚人众·米哈伊尔\", \"愚人众·帕夫洛维奇\", \"愚人众·伊斯迈洛维奇\", \"愚人众·安德烈\", \"愚人众·伊凡诺夫\", \"愚人众·基里连科\", \"愚人众·叶甫根尼\", \"愚人众·丹尼洛维奇\", \"愚人众·瓦西列夫\", \"愚人众·列奥\", \"愚人众·鲍里亚\", \"愚人众·谢苗\", \"愚人众·帕夫洛\", \"愚人众·彼得罗夫\", \"愚人众·阿列克谢\", \"愚人众·列夫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '体格健壮的先遣队士兵，装备了附有雷元素的战锤。\r\n成为愚人众的军人意味着优渥的资源：军饷、武装与物资。\r\n但与此同时，也意味着远离故土与亲眷，将余命交给过去不曾谋面的战友。');
INSERT INTO `genshin_enemy` VALUES (23010401, 23010401, '愚人众先遣队·岩使游击兵', '[\"愚人众·狄康德\", \"愚人众·罗素\", \"愚人众·阿尔乔姆\", \"愚人众·伊戈尔\", \"愚人众·费奥多尔\", \"愚人众·弗拉基米尔\", \"愚人众·尼柯莱\", \"愚人众·马克西姆\", \"愚人众·尼古拉耶夫\", \"愚人众·约瑟夫\", \"愚人众·舍甫琴科\", \"愚人众·康斯坦丁\", \"愚人众·萨沙\", \"愚人众·亚历山大\", \"愚人众·格里戈尔\", \"愚人众·谢尔盖\", \"愚人众·米哈伊尔\", \"愚人众·帕夫洛维奇\", \"愚人众·伊斯迈洛维奇\", \"愚人众·安德烈\", \"愚人众·伊凡诺夫\", \"愚人众·基里连科\", \"愚人众·叶甫根尼\", \"愚人众·丹尼洛维奇\", \"愚人众·瓦西列夫\", \"愚人众·列奥\", \"愚人众·鲍里亚\", \"愚人众·谢苗\", \"愚人众·帕夫洛\", \"愚人众·彼得罗夫\", \"愚人众·阿列克谢\", \"愚人众·列夫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '能驱使岩元素构成护罩，保护战友的先遣队士兵。\r\n不同于少数精锐的债务处理人与萤术士，先遣队的单兵实力与装备较为薄弱。\r\n为了完成任务，为了减少人员与物资的损耗，先遣队的战术更讲究团队协作。');
INSERT INTO `genshin_enemy` VALUES (23010501, 23010501, '愚人众先遣队·风拳前锋军', '[\"愚人众·狄康德\", \"愚人众·罗素\", \"愚人众·阿尔乔姆\", \"愚人众·伊戈尔\", \"愚人众·费奥多尔\", \"愚人众·弗拉基米尔\", \"愚人众·尼柯莱\", \"愚人众·马克西姆\", \"愚人众·尼古拉耶夫\", \"愚人众·约瑟夫\", \"愚人众·舍甫琴科\", \"愚人众·康斯坦丁\", \"愚人众·萨沙\", \"愚人众·亚历山大\", \"愚人众·格里戈尔\", \"愚人众·谢尔盖\", \"愚人众·米哈伊尔\", \"愚人众·帕夫洛维奇\", \"愚人众·伊斯迈洛维奇\", \"愚人众·安德烈\", \"愚人众·伊凡诺夫\", \"愚人众·基里连科\", \"愚人众·叶甫根尼\", \"愚人众·丹尼洛维奇\", \"愚人众·瓦西列夫\", \"愚人众·列奥\", \"愚人众·鲍里亚\", \"愚人众·谢苗\", \"愚人众·帕夫洛\", \"愚人众·彼得罗夫\", \"愚人众·阿列克谢\", \"愚人众·列夫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '能利用风的力量，复苏战友的先遣队士兵。\r\n远离故土又为了故乡。告别了亲人却获得了能相托以生死的战友。\r\n——或许他们以任务的名义干着丑恶的勾当时，也带着这样的想法。');
INSERT INTO `genshin_enemy` VALUES (23010601, 23010601, '愚人众先遣队·火铳游击兵', '[\"愚人众·狄康德\", \"愚人众·罗素\", \"愚人众·阿尔乔姆\", \"愚人众·伊戈尔\", \"愚人众·费奥多尔\", \"愚人众·弗拉基米尔\", \"愚人众·尼柯莱\", \"愚人众·马克西姆\", \"愚人众·尼古拉耶夫\", \"愚人众·约瑟夫\", \"愚人众·舍甫琴科\", \"愚人众·康斯坦丁\", \"愚人众·萨沙\", \"愚人众·亚历山大\", \"愚人众·格里戈尔\", \"愚人众·谢尔盖\", \"愚人众·米哈伊尔\", \"愚人众·帕夫洛维奇\", \"愚人众·伊斯迈洛维奇\", \"愚人众·安德烈\", \"愚人众·伊凡诺夫\", \"愚人众·基里连科\", \"愚人众·叶甫根尼\", \"愚人众·丹尼洛维奇\", \"愚人众·瓦西列夫\", \"愚人众·列奥\", \"愚人众·鲍里亚\", \"愚人众·谢苗\", \"愚人众·帕夫洛\", \"愚人众·彼得罗夫\", \"愚人众·阿列克谢\", \"愚人众·列夫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '操使着烈焰之铳的愚人众士兵。\r\n先遣队配置的武器在一定程度上能制御元素，战斗策略上则会利用元素反应。\r\n因为拥有这样的武装与知识，先遣队团队作战时能带来无法小觑的威胁。');
INSERT INTO `genshin_enemy` VALUES (23020101, 23020101, '愚人众·火之债务处理人', '[\"愚人众·狄康德\", \"愚人众·罗素\", \"愚人众·阿尔乔姆\", \"愚人众·伊戈尔\", \"愚人众·费奥多尔\", \"愚人众·弗拉基米尔\", \"愚人众·尼柯莱\", \"愚人众·马克西姆\", \"愚人众·尼古拉耶夫\", \"愚人众·约瑟夫\", \"愚人众·舍甫琴科\", \"愚人众·康斯坦丁\", \"愚人众·萨沙\", \"愚人众·亚历山大\", \"愚人众·格里戈尔\", \"愚人众·谢尔盖\", \"愚人众·米哈伊尔\", \"愚人众·帕夫洛维奇\", \"愚人众·伊斯迈洛维奇\", \"愚人众·安德烈\", \"愚人众·伊凡诺夫\", \"愚人众·基里连科\", \"愚人众·叶甫根尼\", \"愚人众·丹尼洛维奇\", \"愚人众·瓦西列夫\", \"愚人众·列奥\", \"愚人众·鲍里亚\", \"愚人众·谢苗\", \"愚人众·帕夫洛\", \"愚人众·彼得罗夫\", \"愚人众·阿列克谢\", \"愚人众·列夫\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_FATUI', '愚人众', '隶属愚人众的特务人员。\r\n债务处理人所处理的「债务」，并不局限于钱货往来的清算。\r\n「以眼还眼，以牙还牙」也是一种债。无论是谁，只要损害了愚人众的利益，那就要十倍奉还。');
INSERT INTO `genshin_enemy` VALUES (23030101, 23030101, '愚人众·雷萤术士', '[\"愚人众·安娜\", \"愚人众·奥尔嘉\", \"愚人众·娜塔莎\", \"愚人众·玛利亚\", \"愚人众·卡佳\", \"愚人众·达丽雅\", \"愚人众·索菲亚\", \"愚人众·尤莉亚\", \"愚人众·安托诺娃\", \"愚人众·朵洛宁娜\", \"愚人众·斯维捷洛娃\", \"愚人众·伊琳娜\", \"愚人众·拉赫玛诺娃\", \"愚人众·谢苗诺娃\", \"愚人众·塔尼娅\", \"愚人众·妮娜\", \"愚人众·莱莎\", \"愚人众·波利索娃\", \"愚人众·卢莎卡\", \"愚人众·玛莎\", \"愚人众·娜佳\", \"愚人众·斯涅日娜\", \"愚人众·瓦伦季娜\", \"愚人众·瓦莉娅\", \"愚人众·叶夫根尼娅\", \"愚人众·艾达\", \"愚人众·切尔诺夫娜\", \"愚人众·米菈\", \"愚人众·弗拉基米娅\", \"愚人众·索拉\", \"愚人众·米洛斯拉娃\", \"愚人众·布兰卡\", \"愚人众·薇罗什卡\", \"愚人众·爱尔佳\", \"愚人众·齐万卡\", \"愚人众·特列丝卡\", \"愚人众·丹妮卡\", \"愚人众·蕾娜\", \"愚人众·维丽涅\", \"愚人众·安妮雅\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_FATUI', '愚人众', '操控着雷萤进行战斗，由来与面具下的容貌都是谜的愚人众少女术士。\r\n会利用飞萤喜爱「雾虚草」的特性，操控它们为自己而战。正如雾虚草的气味会令雷萤迷醉，嗜虐的术士也贪恋着戏弄对手的快感。');
INSERT INTO `genshin_enemy` VALUES (23040101, 23040101, '愚人众·冰萤术士', '[\"愚人众·安娜\", \"愚人众·奥尔嘉\", \"愚人众·娜塔莎\", \"愚人众·玛利亚\", \"愚人众·卡佳\", \"愚人众·达丽雅\", \"愚人众·索菲亚\", \"愚人众·尤莉亚\", \"愚人众·安托诺娃\", \"愚人众·朵洛宁娜\", \"愚人众·斯维捷洛娃\", \"愚人众·伊琳娜\", \"愚人众·拉赫玛诺娃\", \"愚人众·谢苗诺娃\", \"愚人众·塔尼娅\", \"愚人众·妮娜\", \"愚人众·莱莎\", \"愚人众·波利索娃\", \"愚人众·卢莎卡\", \"愚人众·玛莎\", \"愚人众·娜佳\", \"愚人众·斯涅日娜\", \"愚人众·瓦伦季娜\", \"愚人众·瓦莉娅\", \"愚人众·叶夫根尼娅\", \"愚人众·艾达\", \"愚人众·切尔诺夫娜\", \"愚人众·米菈\", \"愚人众·弗拉基米娅\", \"愚人众·索拉\", \"愚人众·米洛斯拉娃\", \"愚人众·布兰卡\", \"愚人众·薇罗什卡\", \"愚人众·爱尔佳\", \"愚人众·齐万卡\", \"愚人众·特列丝卡\", \"愚人众·丹妮卡\", \"愚人众·蕾娜\", \"愚人众·维丽涅\", \"愚人众·安妮雅\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_FATUI', '愚人众', '操控着冰萤进行战斗，由来与面具下的容貌都是谜的愚人众少女术士。\r\n没有神之眼的人类，理应是无法像她们这样自如地操控元素的；但她们却在利用雾虚草操控冰萤之余，肆无忌惮地挥霍着寒冰的力量。看似漫无目的地四处游荡的她们，又领受着何种不为人知的使命呢…');
INSERT INTO `genshin_enemy` VALUES (23050101, 23050101, '愚人众·藏镜仕女', '[\"愚人众·安娜\", \"愚人众·奥尔嘉\", \"愚人众·娜塔莎\", \"愚人众·玛利亚\", \"愚人众·卡佳\", \"愚人众·达丽雅\", \"愚人众·索菲亚\", \"愚人众·尤莉亚\", \"愚人众·安托诺娃\", \"愚人众·朵洛宁娜\", \"愚人众·斯维捷洛娃\", \"愚人众·伊琳娜\", \"愚人众·拉赫玛诺娃\", \"愚人众·谢苗诺娃\", \"愚人众·塔尼娅\", \"愚人众·妮娜\", \"愚人众·莱莎\", \"愚人众·波利索娃\", \"愚人众·卢莎卡\", \"愚人众·玛莎\", \"愚人众·娜佳\", \"愚人众·斯涅日娜\", \"愚人众·瓦伦季娜\", \"愚人众·瓦莉娅\", \"愚人众·叶夫根尼娅\", \"愚人众·艾达\", \"愚人众·切尔诺夫娜\", \"愚人众·米菈\", \"愚人众·弗拉基米娅\", \"愚人众·索拉\", \"愚人众·米洛斯拉娃\", \"愚人众·布兰卡\", \"愚人众·薇罗什卡\", \"愚人众·爱尔佳\", \"愚人众·齐万卡\", \"愚人众·特列丝卡\", \"愚人众·丹妮卡\", \"愚人众·蕾娜\", \"愚人众·维丽涅\", \"愚人众·安妮雅\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_FATUI', '愚人众', '操纵着水镜进行战斗，有着仿如侍奉神明般的端庄姿态的愚人众仕女。\r\n优雅自如地操控着水镜的力量，让为之所炫的人，心甘情愿地坠入她的幻境。似乎一切都逃不过她的耳朵。被蒙住的双眼，不知见识过什么景象，也不知其中会倒映出怎样的执妄…');
INSERT INTO `genshin_enemy` VALUES (23060101, 23060101, '愚人众·霜役人', '[\"愚人众·安娜\", \"愚人众·奥尔嘉\", \"愚人众·娜塔莎\", \"愚人众·玛利亚\", \"愚人众·卡佳\", \"愚人众·达丽雅\", \"愚人众·索菲亚\", \"愚人众·尤莉亚\", \"愚人众·安托诺娃\", \"愚人众·朵洛宁娜\", \"愚人众·斯维捷洛娃\", \"愚人众·伊琳娜\", \"愚人众·拉赫玛诺娃\", \"愚人众·谢苗诺娃\", \"愚人众·塔尼娅\", \"愚人众·妮娜\", \"愚人众·莱莎\", \"愚人众·波利索娃\", \"愚人众·卢莎卡\", \"愚人众·玛莎\", \"愚人众·娜佳\", \"愚人众·斯涅日娜\", \"愚人众·瓦伦季娜\", \"愚人众·瓦莉娅\", \"愚人众·叶夫根尼娅\", \"愚人众·艾达\", \"愚人众·切尔诺夫娜\", \"愚人众·米菈\", \"愚人众·弗拉基米娅\", \"愚人众·索拉\", \"愚人众·米洛斯拉娃\", \"愚人众·布兰卡\", \"愚人众·薇罗什卡\", \"愚人众·爱尔佳\", \"愚人众·齐万卡\", \"愚人众·特列丝卡\", \"愚人众·丹妮卡\", \"愚人众·蕾娜\", \"愚人众·维丽涅\", \"愚人众·安妮雅\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_FATUI', '愚人众', '愚人众当中精锐的特务。\r\n自幼就被选中的人，经长久年月的教化与训练，在无数次的汰换后才能成为所谓的「役人」。是愚人众的阵列中最优秀的士兵，有着出色的身手与不渝的忠诚心。');
INSERT INTO `genshin_enemy` VALUES (23060201, 23060201, '愚人众·风役人', '[\"愚人众·安娜\", \"愚人众·奥尔嘉\", \"愚人众·娜塔莎\", \"愚人众·玛利亚\", \"愚人众·卡佳\", \"愚人众·达丽雅\", \"愚人众·索菲亚\", \"愚人众·尤莉亚\", \"愚人众·安托诺娃\", \"愚人众·朵洛宁娜\", \"愚人众·斯维捷洛娃\", \"愚人众·伊琳娜\", \"愚人众·拉赫玛诺娃\", \"愚人众·谢苗诺娃\", \"愚人众·塔尼娅\", \"愚人众·妮娜\", \"愚人众·莱莎\", \"愚人众·波利索娃\", \"愚人众·卢莎卡\", \"愚人众·玛莎\", \"愚人众·娜佳\", \"愚人众·斯涅日娜\", \"愚人众·瓦伦季娜\", \"愚人众·瓦莉娅\", \"愚人众·叶夫根尼娅\", \"愚人众·艾达\", \"愚人众·切尔诺夫娜\", \"愚人众·米菈\", \"愚人众·弗拉基米娅\", \"愚人众·索拉\", \"愚人众·米洛斯拉娃\", \"愚人众·布兰卡\", \"愚人众·薇罗什卡\", \"愚人众·爱尔佳\", \"愚人众·齐万卡\", \"愚人众·特列丝卡\", \"愚人众·丹妮卡\", \"愚人众·蕾娜\", \"愚人众·维丽涅\", \"愚人众·安妮雅\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_FATUI', '愚人众', '愚人众当中精锐的特务。\r\n役人在愚人众中并没有常规的军种编制。依据命令与任务的内容，她们既可以与士兵同进退，也能独自或者与埋在各地的「钉子」一同，进行谍报、反侦察、护卫、抹杀等工作。为了那些更为特殊的任务，役人往往也需要掌握多种多样的技能乃至才艺。');
INSERT INTO `genshin_enemy` VALUES (23070101, 23070101, '愚人众特辖队·线列军', '[\"线列军\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '隶属于愚人众特辖队的士兵，装备了铳刃，是维持阵线的中坚力量。\r\n在至冬的步兵典则中，线列军的首要职责唯有瞄准、射击与冲锋。尽管单兵作战能力并不出众，但集结成密集阵型的线列军总是至冬军势中最牢固的基石之一。');
INSERT INTO `genshin_enemy` VALUES (23072101, 23072101, '愚人众特辖队·支援兵', '[\"先锋士\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '隶属于愚人众特辖队的士兵，装备了重型盾牌，负责在交战的最前线为战友提供掩护。\r\n许多人都明白，在至冬与漆黑灾厄这场旷日持久的战争中，唯有「支撑」更坚韧，坚持更久的一方才能获胜。而特辖队的「支撑」正是支援兵的盾牌——只要盾牌不倒，胜利的希望就仍然存在。');
INSERT INTO `genshin_enemy` VALUES (23073101, 23073101, '愚人众特辖队·榴铳手', '[\"支援兵\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '隶属于愚人众特辖队的士兵，装备了单兵榴铳，可在近距离发起若狂风骤雨一般的轰击。\r\n愚人众特辖队虽拥有数量庞大、功能齐全的支援火力，但在士官们的坚持下，部队依然保留了大量榴铳手。毕竟，对于前线来说，纸面上再强大的火力，也不如一门随叫随到的单兵榴铳实在。');
INSERT INTO `genshin_enemy` VALUES (23074101, 23074101, '愚人众特辖队·先锋士', '[\"疗愈师\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '隶属于愚人众特辖队的士兵，装备了工兵器械，有着很强的白刃战能力。\r\n为满足作战任务的需求，愚人众特辖队设立了先锋士，以铲除行军的障碍。至于障碍究竟是什么，那并不重要，无论是天堑还是如天堑般难以跨过的强敌，凡是阻挡苍星的圣帜前进之物，他们都会不计代价地将其清除。');
INSERT INTO `genshin_enemy` VALUES (23076101, 23076101, '愚人众特辖队·疗愈师', '[\"榴铳手\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '隶属于愚人众特辖队的士兵，装备了杖形器械，负责为战友提供应急医疗支援。\r\n事实上，疗愈师大多只受过速成培训，医疗援助能力十分有限。因此，他们更多时候会选择更高效的支援方式——与其他兵种混编，一同发起冲锋。');
INSERT INTO `genshin_enemy` VALUES (23078101, 23078101, '愚人众特辖队·掷弹兵', '[\"掷弹兵\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '隶属于愚人众特辖队的士兵，装备了特殊悬浮背包与爆弹，负责执行突破任务。\r\n作为具有强大突破能力的兵种，掷弹兵常被前线指挥官派往最凶险的战场，因此成为立功升迁最快的兵种之一。据说，在特辖队内，出身掷弹兵的士官比例远高于其他兵种。');
INSERT INTO `genshin_enemy` VALUES (23079101, 23079101, '愚人众特辖队·火刃突击队', '[null]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '隶属于愚人众特辖队的精锐士官，擅长以巨剑与敌人近身相搏。\r\n无论是在抵御漆黑灾厄的战斗中，还是在与那些胆敢阻拦女皇理想的无知者们的战斗中，冲在最前线的突击队都是伤亡最高的编制之一，历经数战而依然生还者自然是精锐中的精锐。总是有人甘愿成为帝国的火与剑，正如总是有人不甘于命运的不义与旧世界的不公。');
INSERT INTO `genshin_enemy` VALUES (23079201, 23079201, '愚人众特辖队·冰雹重炮手', '[\"冰雹重炮手\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '隶属于愚人众特辖队的精锐士官，擅长以重炮撕裂敌阵，同时以厚重的大盾保护共同战斗的友伴。\r\n苦难将盾染成霜白，凝积的鲜血为它们镀上黑色的边缘。特辖队的士官知晓空洞的言语从来无法挽回那些不可避免的牺牲，唯有冰雹般的轰响，方能将这污秽的旧世界撼动。');
INSERT INTO `genshin_enemy` VALUES (23079301, 23079301, '愚人众特辖队·雷霰近卫军', '[\"雷霰近卫军\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '隶属于愚人众特辖队的精锐士官，擅长操持双铳进行战斗。\r\n与先遣队不同，特辖队的士官几乎皆由至冬皇家军事学院所出，无论是以贵族的身份，还是以平民的天赋。毕竟在女皇仁爱的理想中，两者原本便也不存在区别。正如传统中只能由妖精缙绅担任的「近卫军」，如今也已演变为特辖队士官的荣誉头衔，平等地授予那些构筑新世界的人们。');
INSERT INTO `genshin_enemy` VALUES (23080101, 23080102, '巡陆艇·近战攻坚型', '[\"近战攻坚型\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '将海军理念应用在地面战之上的自律机关，正所谓「巡弋于陆地的武装舰艇」。\r\n装有履带式行走机构的巡陆艇通常被用于攻坚作战，得益于优秀的底盘承载与越野能力，它们可以搭载更为厚重的装甲和武装，轻松通过泥泞与融雪的恶劣地形。平举旋刃的近战巡陆艇展开队形抵近目标防线时，大部分敌军都会将火力聚焦在它们身上，如此一来，其他单位便拥有了发挥火力的良好条件…');
INSERT INTO `genshin_enemy` VALUES (23080201, 23080201, '巡陆艇·近战斥候型', '[\"近战斥候型\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '将海军理念应用在地面战之上的自律机关，正所谓「巡弋于陆地的武装舰艇」。\r\n装有双足型行走机构的巡陆艇通常被作为「斥候」运用，它们能够快速翻越崎岖地形，抵达关键阵位，为部队占据主动权。近战标准的旋刃武装不仅能对轻装目标发起致命打击，还可以轻松粉碎树丛等障碍，开辟通路，使得部队即便置身茂密的雨林之中，也能畅行无阻。');
INSERT INTO `genshin_enemy` VALUES (23080301, 23080301, '巡陆艇·强侦攻坚型', '[\"强侦攻坚型\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '将海军理念应用在地面战之上的自律机关，正所谓「巡弋于陆地的武装舰艇」。\r\n装有履带式行走机构的巡陆艇通常被用于攻坚作战，得益于优秀的底盘承载与越野能力，它们可以搭载更为厚重的装甲和武装，轻松通过泥泞与融雪的恶劣地形。强侦型的武装包含了一门多管自动机铳，使得巡陆艇能够在接近作战与远程打击中自由选择战术。无论保持距离执行侦察任务，还是在烈度可观的交战中攻夺敌军情报，这型巡陆艇都能轻松胜任。');
INSERT INTO `genshin_enemy` VALUES (23080401, 23080401, '巡陆艇·强侦斥候型', '[\"强侦斥候型\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '将海军理念应用在地面战之上的自律机关，正所谓「巡弋于陆地的武装舰艇」。\r\n装有双足型行走机构的巡陆艇通常被作为「斥候」运用，它们能够快速翻越崎岖地形，抵达关键阵位，为部队占据主动权。搭载强侦型武装后，这型巡陆艇不仅能担任主力部队前方的眼哨，还拥有了抓住战机，主动打击敌军薄弱部分的能力，扮演着类似部分骑兵的角色…');
INSERT INTO `genshin_enemy` VALUES (23080501, 23080501, '巡陆艇·强侦地效型', '[\"强侦地效型\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_FATUI', '愚人众', '将海军理念应用在地面战之上的自律机关，正所谓「巡弋于陆地的武装舰艇」。\r\n「地效型」的动力机构通过向地面高速喷射流体的方式，在维持向上推力的同时获得一定压力差，从而使得巡陆艇能够在距离地面一定的高度「飞行」，以更经济的方式获得可观的战斗航速，并避开地雷等陷阱，实现高效突击。不过，碍于成本和续航时间的限制，大规模量产的地效巡陆艇的载荷有限，目前以搭载强侦型武装为主…');
INSERT INTO `genshin_enemy` VALUES (23085101, 23085101, '巡陆艇·尖端全能攻坚型', '[\"尖端全能攻坚型\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_FATUI', '愚人众', '均衡了尖端技术、生产成本与出动率，为战斗序列赋予强大穿透力的精锐巡陆艇，是阵线上的重要支点。\r\n全能攻坚型的武装综合了多管自动机铳与近战旋刃，使得该型巡陆艇能够从容应对所有交战距离上的敌军，双臂的重型榴铳则能破坏掩体，使得防守方失去工事的掩护。根据愚人众与皇家军事学院共同编写的作战条令，当尖端全能攻坚型巡陆艇进入发起进攻时，周围的所有单位都应与其配合，在敌军的防线上迅速打开缺口，以便进行后续的纵深进攻，彻底瓦解敌军的防线…');
INSERT INTO `genshin_enemy` VALUES (23085201, 23085201, '巡陆艇·尖端全能斥候型', '[\"尖端全能斥候型\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_FATUI', '愚人众', '均衡了尖端技术、生产成本与出动率，为战斗序列赋予强大穿透力的精锐巡陆艇，是阵线上的重要支点。\r\n全能斥候型的武装同样兼顾了远近作战，不止能担任斥候型巡陆艇的领队，还可以在高烈度战斗中，为全能攻坚型提供近距离支援，诸如越过专门的「反巡陆艇壕沟」，拔除对方难缠的火力点。该型巡陆艇也能及时跟随矛头向纵深突破，并向两翼发展，快速打击敌军后方的各式关键目标…');
INSERT INTO `genshin_enemy` VALUES (23085301, 23085301, '巡陆艇·尖端火力地效型', '[\"尖端火力地效型\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_FATUI', '愚人众', '均衡了尖端技术、生产成本与出动率，为战斗序列赋予强大穿透力的精锐巡陆艇，是阵线上的重要支点。\r\n换装了高功率喷流引擎后，此型地效型巡陆艇获得了复数火器运用能力，可将不错的火力及时投送至阵线任何一处。因此，在愚人众与皇家军事学院共同编写的作战条令中，它们在大规模作战中，应被单独编为一支「快速反应部队」，用于防范敌人的突破或反冲击，以及在战局占优时扩大战果。当然，所有的尖端巡陆艇都有着单独执行任务的能力，在长期执勤作战中，它们随时可以作为一支小队的核心，充分发挥各式愚人众兵种的战力…');
INSERT INTO `genshin_enemy` VALUES (23090101, 23090101, '超重型陆巡舰·机动战垒', '[\"全地形战争机关\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_FATUI', '愚人众', '军械宫与月矩力试验设计局合作研发的超重型机关，在内部文件中被称作德兹斯拉沃型。\r\n设计者最初的意图似乎是创造用于搬运货物的重型全地形民用运输装置，因此搭载了大量切割与挖掘设备，但后续的通用生产型号已经被改为了搭载复数重型武器的军用版本。\r\n毕竟在月下的尘世，即便是最为完美而神圣的规划也会偏离原初的意旨，更何况是凡人因渺小的善意而创造的、原本便不完美的机械呢。');
INSERT INTO `genshin_enemy` VALUES (24010101, 24010101, '遗迹守卫', '[\"Hu-04510\", \"Hu-11037\", \"Hu-41822\", \"Hu-24601\", \"Hu-25173\", \"Hu-13086\", \"Hu-77514\", \"Hu-36226\", \"Hu-11307\", \"Hu-11226\", \"Hu-39091\", \"Hu-41125\", \"Hu-2734\", \"Hu-51789\", \"Hu-23532\", \"Hu-21258\", \"Hu-96988\", \"Hu-95710\", \"Hu-57113\", \"Hu-58515\", \"Hu-95912\", \"Hu-71419\", \"Hu-82419\", \"Hu-41013\", \"Hu-63616\", \"Hu-93736\", \"Hu-63321\", \"Hu-61412\", \"Hu-93439\", \"Hu-89488\", \"Hu-93511\", \"Hu-68914\", \"Hu-91943\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '古老的人形战斗机械。\r\n传说是已经覆灭的国度留下的战争机械，会徘徊至世界各地的遗迹废都，并攻击冒失的旅人。研究表明遗迹守卫与这些废墟并非同源，表明两者的时代也相差至少数千年，为何遗迹守卫会驻留在其中，并以「爆炸性的火力」守护这些残垣断壁呢…');
INSERT INTO `genshin_enemy` VALUES (24010201, 24010201, '遗迹猎者', '[\"Fo-74931\", \"Fo-69320\", \"Fo-89128\", \"Fo-12062\", \"Fo-62012\", \"Fo-33007\", \"Fo-14258\", \"Fo-94553\", \"Fo-41125\", \"Fo-31124\", \"Fo-20118\", \"Fo-22019\", \"Fo-11711\", \"Fo-99411\", \"Fo-98435\", \"Fo-78469\", \"Fo-89211\", \"Fo-21226\", \"Fo-38518\", \"Fo-44232\", \"Fo-66931\", \"Fo-54221\", \"Fo-49101\", \"Fo-93777\", \"Fo-23232\", \"Fo-92681\", \"Fo-24742\", \"Fo-11226\", \"Fo-19101\", \"Fo-36108\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '巨大的异形战斗机械。\r\n传说是已经覆灭的国度留下的战争机械。似乎是为了提高战斗性能，设计上放弃了低效的拟人形态。无论是白刃战还是远程炮火的威力都相当恐怖。\r\n仅仅是废弃的古代兵器就有如此能力，曾经能生产这种兵器的文明又是如何呢…');
INSERT INTO `genshin_enemy` VALUES (24010301, 24010301, '遗迹重机', '[\"Ra-11235\", \"Ra-81321\", \"Ra-34558\", \"Ra-91142\", \"Ra-33377\", \"Ra-61098\", \"Ra-71597\", \"Ra-25844\", \"Ra-41816\", \"Ra-76510\", \"Ra-94617\", \"Ra-71128\", \"Ra-65746\", \"Ra-36875\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '古老的人形战斗机械。\r\n形态与遗迹守卫相似，但形态更为扭曲、力量更为强大。似乎是为了驱动过于沉重的躯体，在双脚上还额外装配了能量核心。');
INSERT INTO `genshin_enemy` VALUES (24010401, 24010401, '遗迹巨蛇', '[\"进路开掘·SI/Glp\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '古老的异形自律机关。\r\n传说是已经覆灭的国度留下的工程重机，「头部」的齿盘结构能够轻松挖开坚硬的岩盘。果真如此的话，借由这种能力，应该能开凿出足以让大军通行大陆各地的黯道吧。');
INSERT INTO `genshin_enemy` VALUES (24020101, 24020101, '遗迹巡弋者', '[\"Ald-32624\", \"Ald-82994\", \"Ald-96176\", \"Ald-64775\", \"Ald-82780\", \"Ald-95134\", \"Ald-13110\", \"Ald-52260\", \"Ald-25442\", \"Ald-48920\", \"Ald-90256\", \"Ald-27033\", \"Ald-85541\", \"Ald-70590\", \"Ald-31302\", \"Ald-46395\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '为了适应特殊的目标，有着定制化外形与机能的异形机械。\r\n传说是已经覆灭的国度留下的战争机械。相比更为广泛存在的「遗迹守卫」，在形态上有着更强的仿生学意义。分散化的设计和战斗模式似乎模仿了蜂群，能够变换成各种形态从不同方向发起攻击。');
INSERT INTO `genshin_enemy` VALUES (24020201, 24020201, '遗迹歼击者', '[\"Ald-32624\", \"Ald-82994\", \"Ald-96176\", \"Ald-64775\", \"Ald-82780\", \"Ald-95134\", \"Ald-13110\", \"Ald-52260\", \"Ald-25442\", \"Ald-48920\", \"Ald-90256\", \"Ald-27033\", \"Ald-85541\", \"Ald-70590\", \"Ald-31302\", \"Ald-46395\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '为了适应特殊的目标，有着定制化外形与机能的异形机械。\r\n传说是已经覆灭的国度留下的战争机械。相比更为广泛存在的「遗迹守卫」，在设计上有着更强的仿生学意义。由若干部件构成的巨大花冠像是某种可怕的植物，不知道经历过什么才能设计出这种可怕的机械。');
INSERT INTO `genshin_enemy` VALUES (24020301, 24020301, '遗迹防卫者', '[\"Ald-32624\", \"Ald-82994\", \"Ald-96176\", \"Ald-64775\", \"Ald-82780\", \"Ald-95134\", \"Ald-13110\", \"Ald-52260\", \"Ald-25442\", \"Ald-48920\", \"Ald-90256\", \"Ald-27033\", \"Ald-85541\", \"Ald-70590\", \"Ald-31302\", \"Ald-46395\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '为了适应特殊的目标，有着定制化外形与机能的异形机械。\r\n传说是已经覆灭的国度留下的战争机械。相比更为广泛存在的「遗迹守卫」，在设计上有着更强的仿生学意义。模仿昆虫的肢体相较于拟人机器更加方便移动，各部件结成的护盾能够抵御任何来自正面的攻击。');
INSERT INTO `genshin_enemy` VALUES (24020401, 24020401, '遗迹侦察者', '[\"Ald-32624\", \"Ald-82994\", \"Ald-96176\", \"Ald-64775\", \"Ald-82780\", \"Ald-95134\", \"Ald-13110\", \"Ald-52260\", \"Ald-25442\", \"Ald-48920\", \"Ald-90256\", \"Ald-27033\", \"Ald-85541\", \"Ald-70590\", \"Ald-31302\", \"Ald-46395\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '为了适应特殊的目标，有着定制化外形与机能的异形机械。\r\n传说是已经覆灭的国度留下的战争机械。相比更为广泛存在的「遗迹守卫」，在设计上有着更强的仿生学意义。不知道根据什么原理在形态和行动模式上都模仿了某种深海中的生物，总之无论如何也不想被它缠上。');
INSERT INTO `genshin_enemy` VALUES (24021101, 24021101, '恒常机关阵列', '[\"永续谐振·SI/Ald\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '诡谲的异形战斗机械。\r\n传说是已经覆灭的国度留下的战争机械。由若干部件构成，能够适应战斗的环境变换成不同形态，施展各种攻击手段。\r\n由立方体构成的形态在某个层面而言，与所谓的「无相元素」有着不少相似之处。');
INSERT INTO `genshin_enemy` VALUES (24030101, 24030101, '遗迹龙兽·空巡', '[\"Faf-96624\", \"Faf-83100\", \"Faf-11953\", \"Faf-34863\", \"Faf-82702\", \"Faf-84107\", \"Faf-11316\", \"Faf-38558\", \"Faf-85819\", \"Faf-11673\", \"Faf-30742\", \"Faf-50889\", \"Faf-44591\", \"Faf-92161\", \"Faf-54466\", \"Faf-46308\", \"Faf-40158\", \"Faf-56551\", \"Faf-61237\", \"Faf-10227\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '令人望而生畏的龙形战斗机械。\r\n传说是已经覆灭的国度留下的战争机械。形态上模仿了「龙蜥」这一物种，但为了性能进行了结构的优化。较之真正的龙蜥，具有更强的「吸收」，抑或是说「反制」元素的能力。\r\n能创造出这样可怕兵器的文明，又会因为什么而覆灭呢…');
INSERT INTO `genshin_enemy` VALUES (24030201, 24030201, '遗迹龙兽·地巡', '[\"Faf-96624\", \"Faf-83100\", \"Faf-11953\", \"Faf-34863\", \"Faf-82702\", \"Faf-84107\", \"Faf-11316\", \"Faf-38558\", \"Faf-85819\", \"Faf-11673\", \"Faf-30742\", \"Faf-50889\", \"Faf-44591\", \"Faf-92161\", \"Faf-54466\", \"Faf-46308\", \"Faf-40158\", \"Faf-56551\", \"Faf-61237\", \"Faf-10227\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '令人望而生畏的龙形战斗机械。\r\n传说是已经覆灭的国度留下的战争机械。形态上模仿了「龙蜥」这一物种，但为了性能进行了结构的优化。较之真正的龙蜥，具有更强的「吸收」，抑或是说「反制」元素的能力。\r\n从这种能力来看，创造出这样可怕兵器的文明曾经有过相当宏大的野心吧…');
INSERT INTO `genshin_enemy` VALUES (24030301, 24030301, '兆载永劫龙兽', '[\"永续永动·GL-Faf\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '如同古时曾制御大地的君王一般，令人望而生畏的龙形战斗机械。\r\n传说已经覆灭的国度曾渴求着禁忌的技术，试图拟造出可以匹敌，乃至超越亘古生命的永续机关。这架不知疲倦的神秘机械巨兽似乎证明，他们确已触及了人所不应抵达的领域。');
INSERT INTO `genshin_enemy` VALUES (24040101, 24040101, '元能构装体·力场发生器', '[\"砂原王都的建造者\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '失落在荒漠中的古老遗迹的守护者，其力量足以惩罚一切敢于惊扰君王清梦之人。\r\n这些机械最初的用途并非是把守宫殿与神庙，而是要在沙海之上重现痴愚之王梦想中乐园。\r\n如今「乐园」早已湮灭，只有蚀刻在这些机械上的咒文还记录着那些已被世人忘却的梦想与承诺。');
INSERT INTO `genshin_enemy` VALUES (24040201, 24040201, '元能构装体·重塑仪', '[\"砂原王都的建造者\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '失落在荒漠中的古老遗迹的守护者，其力量足以惩罚一切敢于惊扰君王清梦之人。\r\n统治沙海的烈日之王曾向他的子民许诺过彼岸的乐土，然而事实证明那不过是君王愚痴的妄念。\r\n如今「乐园」早已湮灭，只有蚀刻在这些机械上的咒文还记录着那些已被世人忘却的梦想与承诺。');
INSERT INTO `genshin_enemy` VALUES (24040301, 24040301, '元能构装体·勘探机', '[\"砂原王都的建造者\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '失落在荒漠中的古老遗迹的守护者，其力量足以惩罚一切敢于惊扰君王清梦之人。\r\n为了构筑梦想中的乐园，沙海的主人曾探究禁忌的知识，这些神秘的机械或许正是其造物。\r\n如今「乐园」早已湮灭，只有蚀刻在这些机械上的咒文还记录着那些已被世人忘却的梦想与承诺。');
INSERT INTO `genshin_enemy` VALUES (24050101, 24050101, '半永恒统辖矩阵', '[\"砂原王之梦的守墓者\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '统辖着散落在沙漠中的众多遗迹构装体的永恒机关，其中似乎仍残留着孤独君王的执着意念。\r\n或许是因为梦中的友人曾经的教诲，又或是因为觊觎着天上诸圣的权能，王创造出了本应不属于地上的神秘机关，并以此构建砂原上的国都。\r\n在千柱之城的废墟之上，古老的晶石中仍折射着黄金乐园的美景，即便王的梦想早已无人铭记。');
INSERT INTO `genshin_enemy` VALUES (24060401, 24060401, '机关·地质勘探型', '[\"Ser.472030\", \"Ser.301014\", \"Ser.735311\", \"Ser.652190\", \"Ser.158439\", \"Ser.359360\", \"Ser.174326\", \"Ser.361617\", \"Ser.208594\", \"Ser.295062\", \"Ser.775577\", \"Ser.391908\", \"Ser.918722\", \"Ser.208739\", \"Ser.422440\", \"Ser.574902\", \"Ser.665997\", \"Ser.358002\", \"Ser.776950\", \"Ser.438412\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '以探测地下资源及特定矿物为目的，设计制造的发条机关。\r\n因为能够设置搜寻的金属类型，所以也很受盗宝团与冒险家的欢迎。');
INSERT INTO `genshin_enemy` VALUES (24068101, 24060101, '机关·侦察记录型', '[\"Ser.472030\", \"Ser.301014\", \"Ser.735311\", \"Ser.652190\", \"Ser.158439\", \"Ser.359360\", \"Ser.174326\", \"Ser.361617\", \"Ser.208594\", \"Ser.295062\", \"Ser.775577\", \"Ser.391908\", \"Ser.918722\", \"Ser.208739\", \"Ser.422440\", \"Ser.574902\", \"Ser.665997\", \"Ser.358002\", \"Ser.776950\", \"Ser.438412\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '最早设计制造的新式发条机关机械之一。\r\n据说「奇械公」吉约丹在自然哲学学院的时期，曾经做出了能够真正模拟智慧思考的机械。\r\n尽管他从未正式承认过这种说法，这一传奇仍在日后激起了许多工程师的斗志。数十年前曾有人宣布创造了具有基础思考能力，并能够解读人类情感的发条机关，但最后相关的成果并未得到认同。');
INSERT INTO `genshin_enemy` VALUES (24068201, 24060201, '机关·算力增幅器', '[\"Ser.472030\", \"Ser.301014\", \"Ser.735311\", \"Ser.652190\", \"Ser.158439\", \"Ser.359360\", \"Ser.174326\", \"Ser.361617\", \"Ser.208594\", \"Ser.295062\", \"Ser.775577\", \"Ser.391908\", \"Ser.918722\", \"Ser.208739\", \"Ser.422440\", \"Ser.574902\", \"Ser.665997\", \"Ser.358002\", \"Ser.776950\", \"Ser.438412\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '以中继并增幅信号为目的，设计制造的发条机关。\r\n驱动发条机关的能源是通过荒性与芒性在动力核心内部进行可控湮灭反应而产生的。因此向其释放过度的能量会导致原本的平衡被打破。');
INSERT INTO `genshin_enemy` VALUES (24068301, 24060301, '机关·水下勘测型', '[\"Ser.472030\", \"Ser.301014\", \"Ser.735311\", \"Ser.652190\", \"Ser.158439\", \"Ser.359360\", \"Ser.174326\", \"Ser.361617\", \"Ser.208594\", \"Ser.295062\", \"Ser.775577\", \"Ser.391908\", \"Ser.918722\", \"Ser.208739\", \"Ser.422440\", \"Ser.574902\", \"Ser.665997\", \"Ser.358002\", \"Ser.776950\", \"Ser.438412\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '以水下探测为目的，设计制造的发条机关。\r\n在发条机关的设计上，在动力学无法得到突破的情况下，运动学是最重要的研究对象。在特定目的的机械设计上，仿生学有时能提供最便捷的解法。');
INSERT INTO `genshin_enemy` VALUES (24068501, 24060501, '机关·水下巡游型', '[\"Ser.472030\", \"Ser.301014\", \"Ser.735311\", \"Ser.652190\", \"Ser.158439\", \"Ser.359360\", \"Ser.174326\", \"Ser.361617\", \"Ser.208594\", \"Ser.295062\", \"Ser.775577\", \"Ser.391908\", \"Ser.918722\", \"Ser.208739\", \"Ser.422440\", \"Ser.574902\", \"Ser.665997\", \"Ser.358002\", \"Ser.776950\", \"Ser.438412\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '这种发条机关的设计目的为搜寻、驱逐、消灭对水下设施有不利影响的水生动物。\r\n自第一次涨水期以来，枫丹科学院便一直忧心于或许有一天终将发生的第二次涨水期。其中一部分人开始构想收复丧失在水中的遗迹并建设海底之城，另一部分人则望着永远浮在不可触及高度的空中岛屿，梦想天空的都会。\r\n「水下巡游型」来自前者，但从结果而言，近些年后者似乎取得了上风。');
INSERT INTO `genshin_enemy` VALUES (24068601, 24060601, '机关·深海攻击型', '[\"Ser.472030\", \"Ser.301014\", \"Ser.735311\", \"Ser.652190\", \"Ser.158439\", \"Ser.359360\", \"Ser.174326\", \"Ser.361617\", \"Ser.208594\", \"Ser.295062\", \"Ser.775577\", \"Ser.391908\", \"Ser.918722\", \"Ser.208739\", \"Ser.422440\", \"Ser.574902\", \"Ser.665997\", \"Ser.358002\", \"Ser.776950\", \"Ser.438412\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '设计目的是进行水下攻击的发条机关。与「水下巡游型」机关不同的是，预期中它的敌人会更大、更凶暴。当然性能与造价的代价是，面对小体型的敌人时便无法完全发挥威力。\r\n过去在枫丹曾经发生了巨大魔兽入侵的悲剧，在陆上大湖受到景仰的白色铁甲舰队为了护国全军覆没。设计者希望如有此类事件再次发生，至少能在水中以强大火力出击的发条机关能先于将官与士兵成为第一道防线。');
INSERT INTO `genshin_enemy` VALUES (24068701, 24060701, '机关·灵活采集型', '[\"Ser.472030\", \"Ser.301014\", \"Ser.735311\", \"Ser.652190\", \"Ser.158439\", \"Ser.359360\", \"Ser.174326\", \"Ser.361617\", \"Ser.208594\", \"Ser.295062\", \"Ser.775577\", \"Ser.391908\", \"Ser.918722\", \"Ser.208739\", \"Ser.422440\", \"Ser.574902\", \"Ser.665997\", \"Ser.358002\", \"Ser.776950\", \"Ser.438412\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '以发掘、输送砂土为目的设计制造的发条机关。\r\n基于荒性与芒性湮灭产生能量的发条机关在枫丹具有得天独厚的优势，因为枫丹的水脉与土质本身就有储存、传导荒性与芒性的特性。这也是冒险中有时会见到荒性与芒性能量块的原因。');
INSERT INTO `genshin_enemy` VALUES (24068801, 24060801, '攻坚特化型机关', '[\"谢尔比乌斯式机关\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '与「侦察记录型」一样，是最早设计制造的新式发条机关机械之一（数百年后的如今已经无人将其称为「新式」。这在当时是用以区分传统发条势能动力的机械机关用的说法）。\r\n名称是用来纪念发明者的友人而起的，最初设计的目的是帮助人。但后来的使用者普遍认为用它攻击人较之用人攻击人的相对优势更大。');
INSERT INTO `genshin_enemy` VALUES (24068901, 24060901, '压制特化型机关', '[\"布莱切利式机关\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '基于「谢尔比乌斯式」，进行了调整的发条机关。很遗憾，并不具备攻击以外的能力。\r\n基于湮灭能量的发条机关通常会利用特殊晶体构成的中继器从枫丹的环境中提炼荒性与芒性产生能量，但在枫丹以外的区域也能通过预先准备的能量块进行短程短时的行动。这两者的区别体现在机关上晶体部件的形状。');
INSERT INTO `genshin_enemy` VALUES (24069001, 24061001, '歼灭特化型机关', '[\"拜伦伯爵夫人式机关\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '尽管枫丹动能工程科学研究院是最为主要的发条机械研究与设计机构，坊间也有许多不隶属于科学院的工程师与独立工坊。\r\n这种机械起初是为一名独立工程师为纪念情人及赞助者而设计制造的。它最终被执律庭选中并采购作为城市安全或称公共暴力机构的武器之一。');
INSERT INTO `genshin_enemy` VALUES (24069101, 24061101, '机关·区域警戒型', '[\"Ser.472030\", \"Ser.301014\", \"Ser.735311\", \"Ser.652190\", \"Ser.158439\", \"Ser.359360\", \"Ser.174326\", \"Ser.361617\", \"Ser.208594\", \"Ser.295062\", \"Ser.775577\", \"Ser.391908\", \"Ser.918722\", \"Ser.208739\", \"Ser.422440\", \"Ser.574902\", \"Ser.665997\", \"Ser.358002\", \"Ser.776950\", \"Ser.438412\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '能够将湮灭产生的能量投射出去的机关。严格来说，是在枫丹科学院建立之前，自然哲学学院的相关研究中产生的试验装置。\r\n因此，尽管作为警戒与防御设备取得了相当的商业成功，大多数工程师并不将其视为严格意义的发条机关机械。');
INSERT INTO `genshin_enemy` VALUES (24069201, 24061201, '建造特化型机关', '[\"艾蒂安-路易式机关\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '在建筑施工、考古发掘上同样有不可估量价值的大型发条机关，其名来自修建克莱门汀线时卡雷斯雇佣的工程师。\r\n这名工程师在卡雷斯的资助下为打通白淞隧道建造了颇具传奇性的「黄金乐船」巨型工程机械，并在竣工后据此设计了这类结构相似，但尺寸缩小的发条机关。');
INSERT INTO `genshin_enemy` VALUES (24070301, 24070101, '冰风组曲', '[\"冰风组曲·阳面\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '由枫丹科学院研发的奇械舞者。\r\n在博絮埃最初的设想中，奇械舞者是超越机械复制时代的艺术品。但在博絮埃被迫离任后，该项目改由梅雅德接手。梅雅德对于奇械和舞者均有自己独到的见解，因此在迭代过程中，奇械舞者的各项功能在臻于完备的同时，也逐渐偏离了博絮埃的设计初衷。');
INSERT INTO `genshin_enemy` VALUES (24080101, 24080101, '实验性场力发生装置', '[\"布雷阁原型机器\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '艾德温·伊斯丁豪斯生前设计的大型装置。依照原本的设计意图，拥有「抵消」重力的效果；依照原本的设计意图，这将是将枫丹建设成天空之都的第一步，从此以后再也没有人需要为曾经荡涤大地的浪潮而忧心，即使七国尽没深海，瑰丽的枫丹廷也将如天空岛那样在空中漂游。就连宇宙的秘密也将变得不那么遥不可及。\r\n装置核心的始基矿拥有「分离」或是「沉淀」的特性，能够将物质，或是某些物质以外的事物分离；传说这样的性质也能被反转，但枫丹科学院只醉心于它所能产生的物理效用。');
INSERT INTO `genshin_enemy` VALUES (24090101, 24090101, '秘源机兵·寻捕械', '[\"深古遗迹采集机关\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '深古遗迹的采集用机械体。\r\n传说是远古遗迹特殊的工作用机械，本身主要是为了捕捉或采集样本这一实验目的而被设计使用，仅赋予了基础的战斗机能。\r\n传言并非是人类制造出来机械，而是更远古的文明的造物。如今，古老的文明已经失落，只留有这些古怪的机械四处巡游。');
INSERT INTO `genshin_enemy` VALUES (24090201, 24090201, '秘源机兵·构型械', '[\"深古遗迹建造机关\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '深古遗迹的制造用机械体。远古遗迹的主人们用这种会改变形态的机器进行各种制造的工作，只要学会如何利用这样的机械，即使是在类似火山内部的极端环境里，也能够构造超乎想象的庞然城市。\r\n除此之外，似乎也被作为兵器使用。古老的文明早已失落，但在金纹铭刻命令的驱动之下，形如巨爪的机械体仍能按预先设定的进程进行战斗。');
INSERT INTO `genshin_enemy` VALUES (24090501, 24090501, '秘源机兵·统御械', '[\"深古遗迹辖制机关\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '深古遗迹的统御机关。\r\n远古，伟大的种族为了维持巨大城市的运作，将一部分的权能给予了由燃素构造而出的智慧。这些智慧秉持使命，一度通过各种机关来统御无数陆上城市的运转。如今古老的文明毁于与新生种族的战火，曾经承载伟大智慧的统御机关之内，也仅留存了最为简单的指令。');
INSERT INTO `genshin_enemy` VALUES (24100101, 24100101, '重拳出击鸭', '[\"重拳出击鸭\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '由废弃的金属与机关轴承拼接而成的、造型奇特的月矩力机关，似乎是因为制造者的偏好而被部分赋予了「鸭子」的外观特征。\r\n即便是与愚人众最尖端的战争兵器相比，在出力与抗打击性能方面都毫不逊色，但依然只是一只会对敌人重拳出击的玩具鸭子。毕竟制造者的喜好总是会决定受造之物的形貌，泥土终究无权质问抟弄它的匠人要为它选择怎样的模具。月下的世界如今早已被塑造成人们常识中理所应得的模样，但在这个世界原本的住民眼中，那也不过是像鸭子一样的、制造者的古怪偏好吧。\r\n当然，上面这些话，那位蓝发的女仆是不会对蛋卷工坊的主人说出口的——况且与世界的模样相比，鸭子还是很可爱的。');
INSERT INTO `genshin_enemy` VALUES (24110101, 24110101, '辖域守护者', '[\"守护者\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '原初的大能者流溢而出的影之造物，守卫高天之柱殿的守护者。\r\n作为空之柱殿的守卫，虽被赋予了「眼」，却只能颂赞永恒实在的「理型」，无从得见现象世界的纷繁，因此不被视为天使的同类。这般自相乖离之事究竟是其造主理性的设计，又或是它们所侍奉的主人终究也不理解原初那一位的心意，恐怕已无从得知。');
INSERT INTO `genshin_enemy` VALUES (24111101, 24111101, '守望者·堕天', '[\"开眼者\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '原初的大能者流溢而出的影之造物，曾居于高天之上的守望者，终因开眼而堕入尘世。\r\n守望者只应沉默地于世界之柱殿守望，一切逾越规则的探求，皆是与谋求世界破灭等同的不赦之罪。\r\n身为世界望楼的统权，执掌其造主所赋予的纠正一切「革新进化之事」的权柄。在历经百千劫的无明后，终于选择开眼直面世界的谎言与真实，却也因此违背了造主的意志。\r\n守望者不知晓那位离去的主人因何离去，唯有永恒的惩罚依然驻留在凝滞的隙间…');
INSERT INTO `genshin_enemy` VALUES (25010201, 25010201, '盗宝团·斥候', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n在团队协作中，职责通常是踩点与盯梢。落草为寇通常因为贫困与缺乏教育，但从他们的装备来看，即使选择了盗贼之路，也没有因此变得富裕…');
INSERT INTO `genshin_enemy` VALUES (25010301, 25010301, '盗宝团·火之药剂师', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n利用化学的知识，铤而走险的人。会调配出易燃易爆的物质，与团伙中其他的同伴一同作案。');
INSERT INTO `genshin_enemy` VALUES (25010401, 25010401, '盗宝团·水之药剂师', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n据说部分盗宝团的药剂师，在加入盗宝团之前，曾经是在城镇间漫游，兜售自己调配的…「灵药」、「圣水」的江湖骗子。这些灵药、圣水显然在战斗中更能大放异彩。');
INSERT INTO `genshin_enemy` VALUES (25010501, 25010501, '盗宝团·雷之药剂师', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n「药剂师」是盗宝团成员当中，为这些具有调配危险化学物质知识的人物取的诨名。\r\n「嗯？这宝物上写了你们冒险家协会的名字么？」\r\n——某名盗宝团的「药剂师」与冒险家对峙时说的话');
INSERT INTO `genshin_enemy` VALUES (25010601, 25010601, '盗宝团·冰之药剂师', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n冰之药剂师在盗宝团当中相当受欢迎，因为他们调配的冰之灵药有快速降温的作用。即使是在没有冰雾花的野外，也可以制作冰镇酒类饮料。');
INSERT INTO `genshin_enemy` VALUES (25010701, 25010701, '盗宝团·杂工', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n在盗宝团当中从事着体力工作，地位比较低下的成员，因为自己的身材还经常被同伙取笑。但在团队遇袭时，会展现出人意料的身手与力量！');
INSERT INTO `genshin_enemy` VALUES (25020201, 25020201, '盗宝团·神射手', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n虽然被称作「神射手」，但其实那是带有讥笑性质的诨名。毕竟他们使用的是弩，而不是弓这样需要长期训练的武器。要知道，就连丘丘人也会用弩。只要把比较宽的那头对准敌人，然后扣下扳机就行了。');
INSERT INTO `genshin_enemy` VALUES (25030201, 25030201, '盗宝团·掘墓者', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n「站在巨人的肩膀上，意思就是把前人积累的财富挖出来，拿走，好让我们…让它们回归经济循环！这是多么高尚的事情！」\r\n——某名盗宝团的「掘墓者」在挖掘遗迹中的财宝时说的话');
INSERT INTO `genshin_enemy` VALUES (25030301, 25030301, '盗宝团·海上男儿', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n「我们的活动怎么能叫偷？怎么能叫盗？那叫重新发现，让宝藏回到赏识宝藏的鉴赏家怀抱中！大家都开心，多好的事儿！」\r\n——某名盗宝团的「海上男儿」对怀有疑问的新人说的话');
INSERT INTO `genshin_enemy` VALUES (25060101, 25060101, '盗宝团·拳术家', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n热衷于肌肉和战斗的人。对食物很挑剔，并且总是向周围的人宣扬肌肉的好处，所以其他盗宝团成员通常对这种人多有微辞。');
INSERT INTO `genshin_enemy` VALUES (25070101, 25070101, '盗宝团·粉碎者', '[\"雅号「摸金狂」\", \"雅号「麻子」\", \"雅号「马屁精」\", \"雅号「钻地虫」\", \"雅号「大鲶」\", \"雅号「黄金蟹」\", \"雅号「老手」\", \"雅号「新手」\", \"雅号「懒虫」\", \"雅号「大诗人」\", \"雅号「神偷」\", \"雅号「自封神偷」\", \"雅号「幻影」\", \"雅号「爱哭鬼」\", \"雅号「大厨」\", \"雅号「飓风」\", \"雅号「醉鬼」\", \"雅号「酿鸡大师」\", \"雅号「油头」\", \"雅号「机灵鬼」\", \"雅号「下巴哥」\", \"雅号「旺达鱼」\", \"雅号「阿狗」\", \"雅号「鼬小弟」\", \"雅号「船长」\", \"雅号「阿诺」\", \"雅号「铁皮」\", \"雅号「溜溜眼」\", \"雅号「泥鳅」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织中的一员。\r\n原本是在矿下工作的人。层岩巨渊封锁后，尽管领取着津贴，还是出于各种缘由加入了盗宝团。');
INSERT INTO `genshin_enemy` VALUES (25080101, 25080101, '野伏·阵刀番', '[\"「恶党左马介」\", \"「萤切之藤堂」\", \"「逐电的丑右卫门」\", \"「蛇坊主」\", \"「绯木之虎」\", \"「一往无前的阳司」\", \"「二村之曲轮」\", \"「不死的平兵卫」\", \"「一揆军监」\", \"「恶逆非道的鹰司」\", \"「一文字阿俊」\", \"「犬之左近」\", \"「花之宗兵卫」\", \"「归人次郎政一」\", \"「天邪鬼家严」\", \"「蟾蜍家贞」\", \"「背上长眼的才藏」\", \"「刃连岛晴正」\", \"「刃连岛秀满」\", \"「赤目的阿掘」\", \"「野良犬渡部」\", \"「螳螂介」\", \"「剑舞文之助」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '落草为寇的流浪武人，虽然常被称为「野伏」，但并不隶属于某个统一的团体。\r\n作为常年行走在武道上的人，有着精湛的剑术，如今却不将其用于正道。\r\n为了生计与财富，有时候甚至会与盗宝团、愚人众沆瀣一气。');
INSERT INTO `genshin_enemy` VALUES (25080201, 25080201, '野伏·火付番', '[\"「恶党左马介」\", \"「萤切之藤堂」\", \"「逐电的丑右卫门」\", \"「蛇坊主」\", \"「绯木之虎」\", \"「一往无前的阳司」\", \"「二村之曲轮」\", \"「不死的平兵卫」\", \"「一揆军监」\", \"「恶逆非道的鹰司」\", \"「一文字阿俊」\", \"「犬之左近」\", \"「花之宗兵卫」\", \"「归人次郎政一」\", \"「天邪鬼家严」\", \"「蟾蜍家贞」\", \"「背上长眼的才藏」\", \"「刃连岛晴正」\", \"「刃连岛秀满」\", \"「赤目的阿掘」\", \"「野良犬渡部」\", \"「螳螂介」\", \"「剑舞文之助」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '落草为寇的流浪武人，虽然常被称为「野伏」，但并不隶属于某个统一的团体。\r\n不仅掌握着精湛的剑术，还会使用具有元素的焰硝药粉攻击。从客观来说，或许这是背离武之道，转而寻求胜之途的体现吧。\r\n为了生计与财富，有时候甚至会与盗宝团、愚人众沆瀣一气。');
INSERT INTO `genshin_enemy` VALUES (25080301, 25080301, '野伏·机巧番', '[\"「恶党左马介」\", \"「萤切之藤堂」\", \"「逐电的丑右卫门」\", \"「蛇坊主」\", \"「绯木之虎」\", \"「一往无前的阳司」\", \"「二村之曲轮」\", \"「不死的平兵卫」\", \"「一揆军监」\", \"「恶逆非道的鹰司」\", \"「一文字阿俊」\", \"「犬之左近」\", \"「花之宗兵卫」\", \"「归人次郎政一」\", \"「天邪鬼家严」\", \"「蟾蜍家贞」\", \"「背上长眼的才藏」\", \"「刃连岛晴正」\", \"「刃连岛秀满」\", \"「赤目的阿掘」\", \"「野良犬渡部」\", \"「螳螂介」\", \"「剑舞文之助」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '落草为寇的流浪武人，虽然常被称为「野伏」，但并不隶属于某个统一的团体。\r\n除了作为武者必修的剑术之外，还会熟练地使用手弩偷袭对手，只要能够取胜便会不择手段。抛弃了武家之名的人，也常常会抛弃武家的自矜。\r\n为了生计与财富，有时候甚至会与盗宝团、愚人众沆瀣一气。');
INSERT INTO `genshin_enemy` VALUES (25090101, 25090101, '魔偶剑鬼', '[\"万般机巧·剑豪人形\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_AUTOMATRON', '自律机关', '自律的人形机关剑士。\r\n似乎没有说话的能力与意愿，只愿意用剑沟通。\r\n据说在试作时，集成了某个剑道流派初代宗主的记忆，却又因为不明的原因而失控，最终被废弃了。\r\n根据歌人的描述，剑鬼会徘徊在因缘断绝的地方，而守护它的凶恶之面似乎取自那个时代有名的鬼人。');
INSERT INTO `genshin_enemy` VALUES (25100101, 25100101, '海乱鬼·雷腾', '[\"「恶党左马介」\", \"「萤切之藤堂」\", \"「逐电的丑右卫门」\", \"「蛇坊主」\", \"「绯木之虎」\", \"「一往无前的阳司」\", \"「二村之曲轮」\", \"「不死的平兵卫」\", \"「一揆军监」\", \"「恶逆非道的鹰司」\", \"「一文字阿俊」\", \"「犬之左近」\", \"「花之宗兵卫」\", \"「归人次郎政一」\", \"「天邪鬼家严」\", \"「蟾蜍家贞」\", \"「背上长眼的才藏」\", \"「刃连岛晴正」\", \"「刃连岛秀满」\", \"「赤目的阿掘」\", \"「野良犬渡部」\", \"「螳螂介」\", \"「剑舞文之助」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '落草为寇的流浪武人。\r\n有着高强的武道修养，却因为种种原因而没有用武之地，走投无路中踏上了恶逆之道。会利用本应在数百年前失传的惟神技术制造的符纸，为刀剑附上雷霆的力量。');
INSERT INTO `genshin_enemy` VALUES (25100201, 25100202, '海乱鬼·炎威', '[\"「恶党左马介」\", \"「萤切之藤堂」\", \"「逐电的丑右卫门」\", \"「蛇坊主」\", \"「绯木之虎」\", \"「一往无前的阳司」\", \"「二村之曲轮」\", \"「不死的平兵卫」\", \"「一揆军监」\", \"「恶逆非道的鹰司」\", \"「一文字阿俊」\", \"「犬之左近」\", \"「花之宗兵卫」\", \"「归人次郎政一」\", \"「天邪鬼家严」\", \"「蟾蜍家贞」\", \"「背上长眼的才藏」\", \"「刃连岛晴正」\", \"「刃连岛秀满」\", \"「赤目的阿掘」\", \"「野良犬渡部」\", \"「螳螂介」\", \"「剑舞文之助」\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '落草为寇的流浪武人。\r\n自幼时便专注于武道从未懈怠，却因为种种原因失去了奉公的机会，背离了正道，走上恶逆之路。刀刃不似一般的钢铁那般冰冷，而是充满了忿恨的炽热怒火——似乎是利用了本应失传的惟神技术制造的符纸，为刀刃附上火焰。');
INSERT INTO `genshin_enemy` VALUES (25210101, 25210101, '镀金旅团·阵前斧手', '[\"以武谋生的沙之遗民\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自黄金一般的沙漠，是松散佣兵团体中的一员。为了报酬，愿意为任何人效力。\r\n使用手斧的女战士在厮杀时往往一往无前，以此打乱敌人的阵脚，为战友创造机会。\r\n在沙漠的故乡里，她们有时会坐在篝火边，弹起那些失落在沙海中的悠远歌谣。');
INSERT INTO `genshin_enemy` VALUES (25210201, 25210201, '镀金旅团·机弩兵', '[\"以武谋生的沙之遗民\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自黄金一般的沙漠，是松散佣兵团体中的一员。为了报酬，愿意为任何人效力。\r\n传统上，镀金旅团其实更习惯使用弓箭对付敌人。不过自从教令院允许他们在巴扎采购机弩之后，就只有最骄傲的射手才会再使用弓箭这种需要常年训练的武器了。');
INSERT INTO `genshin_enemy` VALUES (25210301, 25210301, '镀金旅团·鸦喙戟手', '[\"以武谋生的沙之遗民\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自黄金一般的沙漠，是松散佣兵团体中的一员。为了报酬，愿意为任何人效力。\r\n使用名为「鸦喙戟」的武器进行战斗。传说在古代，侍奉沙漠神祇的隐士会携带这种战戟作为身份的象征。这种武器的真名已经失落在了沙海中。');
INSERT INTO `genshin_enemy` VALUES (25210401, 25210401, '镀金旅团·破阵者', '[\"以武谋生的沙之遗民\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自黄金一般的沙漠，是松散佣兵团体中的一员。为了报酬，愿意为任何人效力。\r\n装备了独特拳刃的武道家，为了寻找更多更强的对手而加入了镀金旅团。战斗与其说是为了报酬，不如说是为了追求更高的武技。');
INSERT INTO `genshin_enemy` VALUES (25210501, 25210501, '镀金旅团·刀舞者', NULL, 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自黄金一般的沙漠，是松散佣兵团体中的一员。为了报酬，愿意为任何人效力。\r\n擅长使用大弯刀的沙漠武士。其所掌握的传承自失落文明的刀法不仅是一种战技，由其发展而来的刀舞更成为了在各国都广受欢迎的杂技表演。\r\n这种大弯刀据说在古时是用于骑乘战斗的。');
INSERT INTO `genshin_enemy` VALUES (25310101, 25310101, '镀金旅团·沙中净水', '[\"沙下泉流般跃动的刀舞者\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自黄金一般的沙漠，是松散佣兵团体中的一员。为了报酬，愿意为任何人效力。\r\n迷失在砂砾作歌的旧梦之中的少女，将厮杀的趣味视作执行委托时真正有价值的报偿。传说诞在这一族中的女子常受沙漠中的游魂青睐，因而往往早夭。或许只有血管中澎湃着战斗的旋律时，她才能摆脱魂灵的低语吧。\r\n使用的武器中封印着残破的厄灵，会在危急时苏醒。只有战败者的哀嚎才能平息其忿怒——不论败者是武器的主人，抑或是敌人。');
INSERT INTO `genshin_enemy` VALUES (25310201, 25310201, '镀金旅团·炽阳凝冰', '[\"深暮结霜般清冷的佣兵\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自黄金一般的沙漠，是松散佣兵团体中的一员。为了报酬，愿意为任何人效力。\r\n对职责与任务之外的一切事宜漠不关心的职业佣兵。将完成委托作为唯一的行动纲领，在佣兵市场上的要价也是最高的。\r\n使用的武器中封印着残破的厄灵，会在危急时苏醒。只有战败者的哀嚎才能平息其忿怒——不论败者是武器的主人，抑或是敌人。');
INSERT INTO `genshin_enemy` VALUES (25310301, 25310301, '镀金旅团·白日鸣雷', '[\"疾雷馀声般迅猛的战士\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自黄金一般的沙漠，是松散佣兵团体中的一员。为了报酬，愿意为任何人效力。\r\n以战斗为天职，真正的武士部族的后裔。与轻松挥舞巨斧的蛮人形象不同，这一族的战士实际上对沙中废都的古文与诗歌颇有研究。\r\n使用的武器中封印着残破的厄灵，会在危急时苏醒。只有战败者的哀嚎才能平息其忿怒——不论败者是武器的主人，抑或是敌人。');
INSERT INTO `genshin_enemy` VALUES (25410101, 25410101, '镀金旅团·魔岩役使', '[\"使役风之魔鸢的猎手\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '从沙漠中走出的松散佣兵团体中的一员，为了报酬愿意为任何人效力。\r\n在古代，这些重装的武士乃是烈日君王最为亲信的宿卫。或许正是由于这个缘故，他们身上至今仍流溢着太阳般的金色光辉。\r\n使用的武器中封印着残破的厄灵，会在危急时苏醒。只有战败者的哀嚎才能平息他们的愤怒。——不论败者是武器的主人，抑或是敌人。');
INSERT INTO `genshin_enemy` VALUES (25410201, 25410201, '镀金旅团·灵风猎手', '[\"使役岩之魔蜥的战士\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '从沙漠中走出的松散佣兵团体中的一员，为了报酬愿意为任何人效力。\r\n由于机弩的广泛使用，在如今的镀金部族中唯有最老练的战士才会使用长弓作战。她们无需依靠双目，仅凭风沙流动的声音便能分辨出敌人的所在。\r\n使用的武器中封印着残破的厄灵，会在危急时苏醒。只有战败者的哀嚎才能平息他们的愤怒。——不论败者是武器的主人，抑或是敌人。');
INSERT INTO `genshin_enemy` VALUES (25410301, 25410301, '镀金旅团·炽沙叙事人', '[\"编织烈焰与史诗的神谕\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '从沙漠中走出的松散佣兵团体中的一员。即使为了报酬愿意为任何人效力，也不会忘记沙海中的根源。\r\n在文明崩解之后，沙漠中的故事如同风中的火星、云中的雨一样，是经由口口相传的诗与秘史一代又一代继承下去的。在流传的过程中有许多故事变化了，又有许多故事失落了。\r\n「镀金旅团」是无知或是怀着蔑视的心不去区分沙海中诸多部族的外人对他们的统称。在被称为镀金旅团的人当中，有许多人已经忘记了沙漠的故事。如今仍然能记起许多故事的人，是不会背叛流淌在体内的沙漠血脉的。');
INSERT INTO `genshin_enemy` VALUES (25410401, 25410401, '镀金旅团·叶轮舞者', '[\"与灵蛇共舞的轮刃武者\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '从沙漠中走出的松散佣兵团体中的一员，为了报酬愿意为任何人效力。\r\n沙之民有音乐与舞蹈的传统，起初是对神的礼赞，后来则是讨取王者欢心的演艺与战斗的技术。大漠的传说中，便有曾将王者谋刺于床榻或高塔的舞姬。如今即使他们的神与王都尽数沉入流沙，舞蹈的记忆依然留存在民族的血脉中。\r\n使用的武器中封印着残破的厄灵，会在危急时苏醒。只有战败者的哀嚎才能平息他们的愤怒。——不论败者是武器的主人，抑或是敌人。');
INSERT INTO `genshin_enemy` VALUES (25500101, 25500101, '流刃勇士·游击人', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自流泉之源的勇士，在临水流域巡游的部族守卫者。\r\n手中空空，精通最原始搏击技巧的部族战士。看似平平无奇的拳脚中，蕴藏着海浪般的力量。');
INSERT INTO `genshin_enemy` VALUES (25500201, 25500201, '结羽勇士·腾空士', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自山崖之上的勇士，在陡峭山峰巡游的部族守卫者。\r\n比起武器更信任自己双手的部族战士。最为人称道的是其轻盈的身姿。');
INSERT INTO `genshin_enemy` VALUES (25501101, 25501101, '铸砂勇士·叩问人', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自峡谷之中的勇士，在琉晶山川巡游的部族守卫者。\r\n手持球首棒的部族战士，其敲击能让一切坚石化为齑粉。在不进行战斗的时候，她经常用武器敲碎山岩，以寻找宝石和燃素晶块的踪迹。');
INSERT INTO `genshin_enemy` VALUES (25501201, 25501201, '疾迅勇士·引索客', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自悬木之里的勇士，在林涧溪谷巡游的部族守卫者。\r\n与其他部族的战士相比，这些终日借助钩绳在山间摆荡的战士对于环境更为敏感，时刻在想着如何使用意料之外的攻击击败对手。');
INSERT INTO `genshin_enemy` VALUES (25501301, 25501301, '结羽勇士·削羽人', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自山崖之上的勇士，在陡峭山峰巡游的部族守卫者。\r\n挥剑犹如翼龙展开翅膀般大开大合的高傲剑士，被其剑刃劈开的伤口之中，鲜血将如飞羽般挥洒而出。');
INSERT INTO `genshin_enemy` VALUES (25501401, 25501401, '灵觉勇士·执意师', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自谜烟之内的勇士，在漫霾峡谷巡游的部族守卫者。\r\n能够借由身上油彩涂鸦的力量，一定程度地凭借意念操控手中的武器进行攻击。');
INSERT INTO `genshin_enemy` VALUES (25502101, 25502101, '疾迅勇士·荡风斥候', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自悬木之里的勇士，在林涧溪谷巡游的部族守卫者。\r\n据说使剑的部族人在训练自己的战斗技巧时，需要站在树下，劈开一天内落下的所有叶子。但就像落叶其实是没有声音的，讯使们的斩击往往也会悄然而至。');
INSERT INTO `genshin_enemy` VALUES (25502201, 25502201, '流刃勇士·锯脂者', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自流泉之源的勇士，在临水流域巡游的部族守卫者。\r\n总是冲在前方的战士，手中的剑犹如噬人的骨齿。习练剑术的部族人需要在水中抵抗阻力来锻炼力量与技巧，其中的佼佼者，甚至可以将水中的游鱼一分为二。');
INSERT INTO `genshin_enemy` VALUES (25502301, 25502301, '灵觉勇士·控念师', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自谜烟之内的勇士，在漫霾峡谷巡游的部族守卫者。\r\n据说身上的油彩涂鸦是燃素刻录演化到了如今的形式，需要经过漫长的修行才能真正掌握其中的力量。');
INSERT INTO `genshin_enemy` VALUES (25502401, 25502401, '横蛮勇士·冲撞手', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自平原之上的勇士，在金穗田间巡游的部族守卫者。\r\n精通如何利用刃角攻击敌人弱点的技巧，切忌被其发现自身的破绽。');
INSERT INTO `genshin_enemy` VALUES (25503101, 25503101, '疾迅勇士·重刃讯使', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自悬木之里的勇士，在林涧溪谷巡游的部族守卫者。\r\n常常有人怀疑，双手剑对于「悬木人」的讯使来说是否是种过重的武器，但或许正因为讯使承担的职责过于紧要，更具威慑力的武器才被视为一种必须。');
INSERT INTO `genshin_enemy` VALUES (25503201, 25503201, '灵觉勇士·冥思者', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自谜烟之内的勇士，在漫霾峡谷巡游的部族守卫者。\r\n只有力量经过考验的卫从才能在身上绘制具有特殊力量的油彩涂鸦，也意味着部族勇士关于意念的修行到达了下一个阶段。');
INSERT INTO `genshin_enemy` VALUES (25504101, 25504101, '铸砂勇士·碎盾者', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自峡谷之中的勇士，在琉晶山川巡游的部族守卫者。\r\n双手挥舞巨锤的部族战士，会率先攻破敌人防御的先锋。在喜好宝石和装饰品工艺的「回声之子」，锤子往往是战士们仍在孩童时期就经常接触的工具。');
INSERT INTO `genshin_enemy` VALUES (25504201, 25504201, '结羽勇士·驭空客', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自山崖之上的勇士，在陡峭山峰巡游的部族守卫者。\r\n从飞龙爪击的动作中体悟到运用力量真谛的战士，自高处使用的踢击不容小觑。');
INSERT INTO `genshin_enemy` VALUES (25504301, 25504301, '横蛮勇士·摔跤客', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自平原之上的勇士，在金穗田间巡游的部族守卫者。\r\n从立志成为战士之初便不断训练自身的力量的战士，手持双手武器下劈时，具有常人无法抵挡的威势。');
INSERT INTO `genshin_enemy` VALUES (25505101, 25505101, '铸砂勇士·投矛手', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自峡谷之中的勇士，在琉晶山川巡游的部族守卫者。\r\n在山脊破碎，部族需要被重新建立的时代，战士们用投矛作为标的，确认峡谷两侧的位置以开凿通路。这意味着，每一根投矛都要深深没入山石之中才行。');
INSERT INTO `genshin_enemy` VALUES (25505201, 25505201, '流刃勇士·掷叉猎手', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自流泉之源的勇士，在临水流域巡游的部族守卫者。\r\n手中常握着长叉的勇士，他们在渔猎中习得的本领不容小觑。据说，从前的部族人就是凭借这手技巧，在海面上追逐鳍鳞坚韧的巨兽。');
INSERT INTO `genshin_enemy` VALUES (25505301, 25505301, '横蛮勇士·抓扑人', '[\"部族忠诚的护卫\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自平原之上的勇士，在金穗田间巡游的部族守卫者。\r\n仅用肢体进行格斗在「沃陆之邦」被视为一种荣耀之行，为此踏上修行之路的战士，拥有将投矛投出万钧之势的臂力。');
INSERT INTO `genshin_enemy` VALUES (25510101, 25510101, '嵴锋龙武士·碎晶打者', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自峡谷之中，勇武受到认可，得以获授龙冠的强大武士。\r\n能够借助岩崩之力进行击打的武者。即使是在与山岩晶体亲近的「回声之子」中，龙冠武士也是领悟山岩之力更为透彻的高手。据说他们甚至能够透过原矿表面粗糙的风化皮，分析其内部的成色和纹理。');
INSERT INTO `genshin_enemy` VALUES (25510201, 25510201, '嵴锋龙武士·破岩锐刃', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自峡谷之中，勇武受到认可，得以获授龙冠的强大武士。\r\n能够借助岩崩之力进行击打的武者。在传说中，硫晶支脉原本是更完整和更漂亮的山脉。只是在黑潮来袭之时，「回声之子」的龙冠武士们为了引导黑潮的方向，将大地敲凿而开，才有了现在的样貌。');
INSERT INTO `genshin_enemy` VALUES (25510301, 25510301, '匿叶龙武士·旋锯飞叶', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自悬木之里，勇武受到认可，得以获授龙冠的强大武士。\r\n能够借助钩绳延展攻击范围的武者。钩绳是「悬木人」部族成员日常生活中不可缺少的组成部分。不过即使如此，只有最疯狂的战士才会将钩绳和锯刃相结合，变成难以操纵但杀伤力巨大的武器。');
INSERT INTO `genshin_enemy` VALUES (25510401, 25510401, '匿叶龙武士·流火鸣空', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自悬木之里，勇武受到认可，得以获授龙冠的强大武士。\r\n能够借助钩绳延展攻击范围的武者。经过精巧机关的组装后，其手中的手砲可以利用钩绳触动发射。对于「悬木人」部族的龙冠武士们来说，更重要的不是对精神和意志的锤炼，而是对技艺与思绪的精研。');
INSERT INTO `genshin_enemy` VALUES (25510501, 25510501, '鳍游龙武士·穿浪之梭', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自流泉之源，勇武受到认可，得以获授龙冠的强大武士。\r\n能短暂借助海浪之力来回穿梭的武者。传说中，部族的英杰甚至能够借由极高的速度，不凭借任何工具即可在水面上折返来回。如今的部族人认为，这是一种相当精巧的驱使海浪的技艺，其重点在于移动时的方法。');
INSERT INTO `genshin_enemy` VALUES (25510601, 25510601, '鳍游龙武士·裂礁之涛', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自流泉之源，勇武受到认可，得以获授龙冠的强大武士。\r\n能短暂借助海浪之力来回穿梭的武者。据说要熟练掌握这样的技巧需要三个阶段的修炼：首先适应，其次依从，最后驱使。掌握这样的运力之法只是成为「流泉之众」龙冠武士的入门要求，而龙冠武士中的高手甚至可以短暂借此施行陆上行舟的法门。');
INSERT INTO `genshin_enemy` VALUES (25510701, 25510701, '绒翼龙武士·膛星之锤', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自山崖之上，勇武受到认可，得以获授龙冠的强大武士。\r\n即便是在火之国纳塔，来自「花羽会」部族的成员对于火焰与燃烧的利用仍然别具一格。对于使用重锤的部族武士来说，火焰是冲撞与迸发，是激昂与热烈。对于他们来说，战斗往往在瞬息之间就将迎来结果，而他们总是获得胜利的一方。');
INSERT INTO `genshin_enemy` VALUES (25510801, 25510801, '绒翼龙武士·长空明焰', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自山崖之上，勇武受到认可，得以获授龙冠的强大武士。\r\n绒翼龙在诸多龙众之中也是相当骄傲的一族，能够得到它们承认的绒翼龙武士亦同享这一份骄矜。据说从前部族的勇士在看到绯色的翼龙将火石从高处投掷以取乐时，迸发出了连环爆炸的弹药的想法。这一逐渐完善的想法，据说就是「花羽会」诸多火器的雏形。');
INSERT INTO `genshin_enemy` VALUES (25510901, 25510901, '暝视龙武士·寒涌持者', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自谜烟之内，勇武受到认可，得以获授龙冠的强大武士。\r\n来自「烟谜主」的部族勇士通常不以真正意义上的力量见长。令他们能够自如操纵武器的是长久修行产生的意念。所以相较于战斗的天赋，「烟谜主」的勇士更看重「灵觉」的天赋。据说，「灵觉」最为出众的武士，甚至能够凭借特殊涂鸦和精神的力量抬起一人高的巨石。');
INSERT INTO `genshin_enemy` VALUES (25511001, 25511001, '暝视龙武士·冰晶炮手', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自谜烟之内，勇武受到认可，得以获授龙冠的强大武士。\r\n据说能够被暝视龙承认的部族武士无一不有着超然的敏锐感知和强大坚韧的精神力。她们甚至能够借由这份力量微微改变火炮射出的弹药的轨迹。');
INSERT INTO `genshin_enemy` VALUES (25511101, 25511101, '突角龙武士·破空轰动', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自沃陆之上，勇武受到认可，得以获授龙冠的强大武士。\r\n据说在「沃陆之邦」，与突角龙共同生活的战士们自龙伙伴的身上，学会了如何一边冲刺一边进行强力攻击的方法。使用重型武器的战士更是如此，据说，其中的秘诀其实是灵巧转动腰身的技术。');
INSERT INTO `genshin_enemy` VALUES (25511201, 25511201, '突角龙武士·追缉灵光', '[\"授获龙冠的勇武\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '来自沃陆之上，勇武受到认可，得以获授龙冠的强大武士。\r\n在「沃陆之邦」，即使是钻研如何使用远程武器的战士，也有出色的近战技巧。或许对她们来说，比起使用远程的炮火进行打击，直接抡起弹弓才是更适合自己的方式吧。');
INSERT INTO `genshin_enemy` VALUES (25520101, 25520101, '灵觉隐修的迷者', '[\"索居的祭司\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_HUMAN', '其他人类势力', '独自在外潜修的「烟谜主」的祭司。据说因为得到了「烟谜主」大灵的庇护而拥有比一般的祭司与萨满更强大的「灵觉」的能力。此等能力既是祝福也是一种诅咒，无法控制这份力量的祭司，当初只能独自在部族外进行修炼。即使在已经能够熟练掌握力量的今日，也保留着离群索居的习惯，因此也有她「不甚合群」的传言。据说只要有后来者想要向她寻求帮助，她也不吝赐教，只不过，是以她自己的方式…');
INSERT INTO `genshin_enemy` VALUES (26010101, 26010101, '冰霜骗骗花', '[\"伺机而动的拟态植物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '神出鬼没的拟态植物魔物，会利用冰元素战斗。\r\n有时会隐藏在地表下，捕猎浑然不觉的猎物。如果有足够的年月、养分与环境，或许能扎根某处，长成巨大的急冻树…');
INSERT INTO `genshin_enemy` VALUES (26010201, 26010201, '炽热骗骗花', '[\"伺机而动的拟态植物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '古灵精怪的拟态植物魔物，会用火元素攻击猎物。\r\n提瓦特的世界中，存在着元素凭附的植物。因此获得了智性的它们，对「养分」的需求也大大提升了…');
INSERT INTO `genshin_enemy` VALUES (26010301, 26010301, '电气骗骗花', '[\"伺机而动的拟态植物\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '元气满满的拟态植物魔物，会用雷元素攻击猎物。\r\n在元素能量充满的时候，可以从花冠中释放出强大的电流，因此也有学者试图将其用于一些其他方面的用途…');
INSERT INTO `genshin_enemy` VALUES (26020101, 26020101, '急冻树', '[\"极寒的冰之花\", \"吐息冰霜的巨藤\", \"静静绽放的霜花\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '地脉中的寒霜附着在藤蔓上，由此形成的魔物。\r\n有研究认为，植物就像世界的器官一样，调和着元素奔涌的地脉；而这种生态在地表上的结晶就是冰雾花、骗骗花等，充满了元素能量的产物。\r\n而生长在特定环境的特定植物，经年累月或许就会成为急冻树这样的，如同魔兽一般庞大而凶猛的生命体吧…');
INSERT INTO `genshin_enemy` VALUES (26020201, 26020201, '爆炎树', '[\"怒放的火之花\", \"恒常燃烧的巨藤\", \"摇曳的炽热火花\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '吸收了地脉中奔涌的古老烈焰的巨大藤蔓。\r\n如同充满怒火一般，永不止息的植物。\r\n诗人、歌手乃至一些学者认为「元素」中蕴含着情感和愿望。如果属实，又是什么情感与愿望驱使着爆炎树恒常燃烧，如同渴求着挣脱大地的束缚一般挣扎舞动呢…');
INSERT INTO `genshin_enemy` VALUES (26020301, 26020301, '掣电树', '[\"震霆的雷之花\", \"电荷喷薄的巨藤\", \"雷殛的天电之花\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '汲取了地脉中传导的高压电流的巨大藤蔓形成的魔物。\r\n从树冠中源源不断释放出电力，如同发泄着大地的愤怒。\r\n曾经有妙论派的学者提出，如果围绕掣电树建立起一套复杂的电路矩阵，便能够将其中的电能输送到城市里使用。这一计划遭到了素论派学者的激烈反对，为此他们不惜牺牲了十头蕈猪以证明使用电力的危险性。');
INSERT INTO `genshin_enemy` VALUES (26030101, 26030101, '幼岩龙蜥', '[\"梦想成为巨龙的幼兽\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '有着坚硬岩质甲壳的小型龙蜥。\r\n行动非常灵活，是不容小觑的对手。须弥教令院的研究认为，即使是这种幼兽，也有成为「龙」的潜质。假以时日，如果不受天灾与敌害，或许也有一天能成为撼动高山的巨大魔物吧。');
INSERT INTO `genshin_enemy` VALUES (26040101, 26040101, '岩龙蜥', '[\"坚若磐石的岩生猛兽\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '成熟的岩之龙蜥。\r\n据称，幼岩龙蜥历经漫长岁月的积累后，会蜕去原本保护自己的装甲，成为「岩龙蜥」。但这两者，以及更古老、更伟大的「古岩龙蜥」，在过去的许多年中都蛰伏在山下，直到近期才开始活动。因此这种说法没有第一手观测记录证明。');
INSERT INTO `genshin_enemy` VALUES (26050101, 26050101, '古岩龙蜥', '[\"曾与「龙王」摇撼山岳的岩龙\", \"自漫长蛰眠中苏醒的撼地之龙\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '经历了长久岁月，拥有伟大力量的巨大岩龙蜥，能够适应元素环境的异变。\r\n根据民话，导致天遒谷毁灭的「龙灾」发生后，岩龙蜥与古岩龙蜥的王者被禁锢在大地深处，而它们则在地壳之下休眠，等待着复起的时机…');
INSERT INTO `genshin_enemy` VALUES (26050601, 26050601, '深海龙蜥·原种', '[\"盘踞深海的水栖猛兽\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '生活在海渊之下的龙蜥。\r\n它们曾经是海渊之下的支配种族——其实在更加久远的过去，龙们就是这个世界的支配者。曾经的七王被高天之力打败，相继凋零了。');
INSERT INTO `genshin_enemy` VALUES (26050701, 26050701, '深海龙蜥·啮冰', '[\"盘踞深海的水栖猛兽\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '生活在海渊之下的龙蜥。因为社会分工，而出现了冰元素的形态。\r\n人类的到来引发了对抗，深海龙蜥开始了进化。正如蚂蚁会因性别和分工不同，而产生不同形态。这些龙蜥比起普通深海龙蜥更加强大。');
INSERT INTO `genshin_enemy` VALUES (26050801, 26050801, '深海龙蜥·吞雷', '[\"盘踞深海的水栖猛兽\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '生活在海渊之下的龙蜥。因为社会分工，而出现了雷元素的形态。\r\n古七王凋零之后，新一代的七王正在陆续诞生。只是深海龙蜥如此进化，失去了纯粹。水之龙已经不会在它们族群中诞生了。根据预言，新的水之龙一定会以人形降临…');
INSERT INTO `genshin_enemy` VALUES (26060101, 26060101, '雷萤', '[\"酥酥麻麻\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '能够稍微导引雷元素的小型生物。\r\n与其他的萤族生物通称「飞萤」。尽管力量十分弱小，但在某些环境下也能造成可观的伤害。');
INSERT INTO `genshin_enemy` VALUES (26060201, 26060201, '水萤', '[\"湿湿滑滑\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '能够稍微导引水元素的小型生物。\r\n与其他的萤族生物通称「飞萤」。飞萤对「雾虚草」这种罕见而奇妙的植物情有独钟，而愚人众的术士据此开发了利用飞萤进行战斗的方法。');
INSERT INTO `genshin_enemy` VALUES (26060301, 26060301, '冰萤', '[\"冰冰凉凉\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '能够稍微导引冰元素的小型生物。\r\n与其他的萤族生物通称「飞萤」。尽管力量非常弱小，但也因为力量弱小，所以进化出了奇特的移动方式，以避开掠食者的攻击。');
INSERT INTO `genshin_enemy` VALUES (26090101, 26090101, '浮游水蕈兽', '[\"孢子飘浮，所以蕈兽也飘浮？\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有一定智能的孢子生物。具有强大的环境适应能力。\r\n据说很难吃。但这种蕈兽因为含有丰富的水分，所以也能成为应急水源…');
INSERT INTO `genshin_enemy` VALUES (26090201, 26090201, '浮游草蕈兽', '[\"孢子飘浮，所以蕈兽也飘浮？\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有一定智能的孢子生物。具有强大的环境适应能力。\r\n曾经有学者撰文宣称它们是草飘浮灵的一种。在受到批驳后，他便改口说这是一种诗性的「修辞」。');
INSERT INTO `genshin_enemy` VALUES (26090301, 26090301, '浮游风蕈兽', '[\"孢子飘浮，所以蕈兽也飘浮？\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有一定智能的孢子生物。具有强大的环境适应能力。\r\n虽然有着不小的菌帽，但这些伞状组织的结构其实是中空的，因此难以作为食材使用。');
INSERT INTO `genshin_enemy` VALUES (26090401, 26090401, '旋转雷蕈兽', '[\"旋转，并以此通往胜利\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有一定智能的孢子生物。具有强大的环境适应能力。\r\n有研究表明，这类蕈兽内部电流的方向会随时间发生周期性的变化，如果加以开发说不定会有更广泛的用途…');
INSERT INTO `genshin_enemy` VALUES (26090501, 26090501, '旋转冰蕈兽', '[\"旋转，并以此通往胜利\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有一定智能的孢子生物。具有强大的环境适应能力。\r\n经过冰镇之后的蕈兽也不会变得更好吃，不过倒也因此有着消暑的功效。');
INSERT INTO `genshin_enemy` VALUES (26090601, 26090601, '旋转火蕈兽', '[\"旋转，并以此通往胜利\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有一定智能的孢子生物。具有强大的环境适应能力。\r\n因为含有富集的火元素，在干燥的季节容易引发林火，对森林来说是非常危险的入侵物种。');
INSERT INTO `genshin_enemy` VALUES (26090701, 26090701, '伸缩火蕈兽', '[\"格外具有弹性\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有一定智能的孢子生物。具有强大的环境适应能力。\r\n虽然看上去很火爆，但其实性格相当温和，只要不要靠得太近应该不会有什么危险…？');
INSERT INTO `genshin_enemy` VALUES (26090801, 26090801, '伸缩风蕈兽', '[\"格外具有弹性\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有一定智能的孢子生物。具有强大的环境适应能力。\r\n通过伸长的菌柱快速吸收养分的蕈兽，伞状的菌盖会随着风的流向转动。');
INSERT INTO `genshin_enemy` VALUES (26090901, 26090901, '伸缩岩蕈兽', '[\"格外具有弹性\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有一定智能的孢子生物。具有强大的环境适应能力。\r\n富集的岩元素在它们的菌盖上形成了坚硬的外壳。为了挥舞沉重的头部，想必其身体结构相比同类也更加紧密。');
INSERT INTO `genshin_enemy` VALUES (26091001, 26091001, '伸缩雷蕈兽', '[\"格外具有弹性\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有一定智能的孢子生物。具有强大的环境适应能力。\r\n不同于其他蕈兽，除了菌盖外还长有会发光的触角。遇到危险的话会释放出小电球来保护自己。');
INSERT INTO `genshin_enemy` VALUES (26100101, 26100101, '圣骸角鳄', '[\"啃噬伟大生命的水之兽\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '因为啃噬伟大的生命体，而扭曲异变的爬行动物。\r\n姿态威严的猛兽有时会受到人们的敬畏，被视为伟大力量的化身，并借由他们的形象彰显自己。而真的摄入「伟大力量」的野兽大多因此丧命，仅有少数进化出了新的形态。');
INSERT INTO `genshin_enemy` VALUES (26100201, 26100201, '圣骸牙兽', '[\"啃噬伟大生命的草之兽\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '因为啃噬伟大的生命体，而扭曲异变的掠食者。\r\n自然的规律是弱肉强食，宠物和圣骸兽则是例外。人类的饵食与不朽的遗骸，本质都是有意或无意的圈套。贪图至强者的馈赠，代价比被关进笼子要惨痛得多。');
INSERT INTO `genshin_enemy` VALUES (26100301, 26100301, '圣骸赤鹫', '[\"啃噬伟大生命的火之兽\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '因为啃噬伟大的生命体，而扭曲异变的食腐猛禽。\r\n圣骸兽所吞食的尸骸当中，常常夹杂着有永远无法陷入沉寂的意志。而这些意志与力量又会驱使它无穷尽地渴求厮杀与亡骸。');
INSERT INTO `genshin_enemy` VALUES (26100401, 26100401, '圣骸毒蝎', '[\"啃噬伟大生命的雷之兽\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '因为啃噬伟大的生命体，而扭曲异变的节肢动物。\r\n生物有其进化之法则，而圣骸兽的法则则是拥有足够的运气，能在同族之前发现在遥远过去就已亡殁的强大生灵遗骸。动物与人的共性往往比人所甘愿承认的更多。');
INSERT INTO `genshin_enemy` VALUES (26100501, 26100501, '圣骸飞蛇', '[\"啃噬伟大生命的风之兽\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '因为啃噬伟大的生命体，而扭曲异变的爬行动物。\r\n即使获得了操使元素的异能，圣骸兽自身无法将体内不朽的亡骸彻底消化。其中的力量与动物本身融合，长出的骨质甲壳据说在成分上与主要产自稻妻的冶炼材料有相近之处。');
INSERT INTO `genshin_enemy` VALUES (26110101, 26110101, '翠翎恐蕈', '[\"菌族拥趸的王者\", \"深居幽林的蕈王\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '经过漫长的岁月，演化出了独特形态的大型蕈兽。\r\n智能水平已经接近，甚至超越了真正的动物，会主动捕食猎物以获取养分。尾巴上长有漂亮的翠翎，与素论派尊崇的古代圣兽非常相似。以拟态演化的逻辑来看，想必它们曾经共同行走在大地之上吧。');
INSERT INTO `genshin_enemy` VALUES (26120101, 26120101, '有翼草本真蕈', '[\"菌族的守护者\", \"孢子的牧者\", \"蕈群的超越者\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '孢子构成的拟态生物，具有强大的环境适应能力。\r\n不仅看上去像，连生活习性也模仿了鸟类。可以依靠菌类组织的翅膀飞上天空，将孢子播撒到更远的地方。\r\n在蕈兽群落中占有主导地位，显示出其拥有着更高的智能。');
INSERT INTO `genshin_enemy` VALUES (26120201, 26120201, '有翼冰本真蕈', '[\"菌族的守护者\", \"孢子的牧者\", \"蕈群的超越者\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '孢子构成的拟态生物，具有强大的环境适应能力。\r\n不仅看上去像，连生活习性也模仿了鸟类。飞舞的时候会散落出轻盈的冰花，这些冰晶的晶核其实也是孢子。\r\n在蕈兽群落中占有主导地位，显示出其拥有着更高的智能。');
INSERT INTO `genshin_enemy` VALUES (26120301, 26120301, '陆行水本真蕈', '[\"菌族的守护者\", \"孢子的牧者\", \"蕈群的超越者\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '孢子构成的拟态生物，具有强大的环境适应能力。\r\n看上去像是鸟类，不过似乎并没有掌握飞行的能力。或许是因为水元素的影响，与同类相比其行动异常敏捷。也有研究推断这种蕈兽实际上是由无数细小的孢子集结构成的菌株，并不是纯粹单一的生命体。 \r\n在蕈兽群落中占有主导地位，显示出其拥有着更高的智能。');
INSERT INTO `genshin_enemy` VALUES (26120401, 26120401, '陆行岩本真蕈', '[\"菌族的守护者\", \"孢子的牧者\", \"蕈群的超越者\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '孢子构成的拟态生物，具有强大的环境适应能力。\r\n受到岩元素的影响，部分组织似乎已经完全角质化了。考虑到蕈类本就是从孢子进化而来，假以时日，或许可以以此为基础发展出另一种全新的生命形态。\r\n在蕈兽群落中占有主导地位，显示出其拥有着更高的智能。');
INSERT INTO `genshin_enemy` VALUES (26130101, 26130101, '风蚀沙虫', '[\"一万万砂砾最后的亲王\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '生活在沙海深处的无目掠食者，会依据声音与大地的震动寻找猎物的踪迹。\r\n传说在时间开始之前的过去，它们所统辖地上遍布芳草与巨木，而它们的主宰与其子嗣一同，在湿润的泥土中穿梭，如同鱼之游于水中。\r\n许多纪元之后，天降的恩赐让泥土化为砂砾。许多生命陨落了，许多物种消失了，而依托土地而生的这一族则成为了「沙虫」。\r\n或许是因为生物习性中的共同之处，似乎有沙漠的居民错误地认为，「沙虫」是流沙鳗鳗蛹化成熟之后的完整形态。');
INSERT INTO `genshin_enemy` VALUES (26140101, 26140101, '魔像督军', '[\"不朽军团督军\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '白石与黄铜塑造的半人马巨像，坚硬的石质躯壳下流淌着灵露的血液。以军团统帅般的姿态屹立着，随时准备将敢于冒犯其威严之人踏为齑粉。\r\n已沉没的古代文明认为，战争与音乐一样，是需要遵循节律的艺术。军团的统帅应当像乐团的指挥者一样，将手中的盾与剑视作琴的弦与弓，在无情的战场弹奏出烈火的旋律。\r\n「战争是通向普遍幸福的必要之恶。」统率魔像的军团，一度征服整片高海的调律师曾如是说。');
INSERT INTO `genshin_enemy` VALUES (26140201, 26140201, '魔像禁卫', '[\"黄金乐章的守卫者\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '战士姿态的活动雕像，会将剑刃指向任何胆敢侵入其所守护之地的人。驱使其战斗的不知是灵魂，抑或是魔法。\r\n传说魔像组成的军团曾征服高海上的列邦，它或许也是其中的一员。沉没海底的高塔与宫殿，见证了敢于阻挡命运轮轴之人的下场。');
INSERT INTO `genshin_enemy` VALUES (26151001, 26151001, '猎刀鳐', '[\"因原海而进化的生命\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '能够释放水刃的鳐鱼。\r\n在原海异种中，存在着诡谲的「异色」生物。据说这种异色体并不是生物，而是海洋中未曾经受肉身诞生，不曾吞下饵食的灵魂，会向原海所认同者或是驾驭原海者施以祝福。当然对自然哲学更有研究与心得的人是不会认同这种毫无依据的说法的。');
INSERT INTO `genshin_enemy` VALUES (26152101, 26152101, '重甲蟹', '[\"因原海而进化的生命\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '寄居在螺与壳之中的螃蟹。\r\n几乎不具备野生动物常有的攻击性，因为食欲之外的攻击性常常源自领域意识，而重甲蟹的领土就是其背在身后的小小家园。');
INSERT INTO `genshin_enemy` VALUES (26153101, 26153101, '膨膨兽', '[\"因原海而进化的生命\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '生活在枫丹水域的哺乳动物，能够发出悠扬的声音与同伴进行通讯。\r\n依据密度的原则，水作为声音传播的介质，效率远远高于空气。基于源自膨膨兽的灵感，科学院中有人发明了将图像转为数据并即时传输的技术，但由于实验的技术限制诸多所以并未在科学院外广泛使用。\r\n但事实上在更遥远的古代就有过基于液体与声音的数据传输技术了。世上没有新鲜事。');
INSERT INTO `genshin_enemy` VALUES (26154101, 26154101, '帽子水母', '[\"因原海而进化的生命\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '通过发射水弹进行狩猎的水生动物。\r\n虽然看起来像帽子，但进食的口器在「帽子」的底部，所以将其戴在头上实在是很不明智的行为。过去曾经有人证实过这一点：「事后回想起来，那确实是很不明智的行为。」');
INSERT INTO `genshin_enemy` VALUES (26155101, 26155101, '泡泡海马', '[\"因原海而进化的生命\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '通过发射水弹进行狩猎的水生动物。\r\n在（为数不多的）原海异种动物爱好者当中，泡泡海马有着相当多的拥趸。当然，原海异种爱好者和发条机关爱好者一样，当中的细分群体对其他群体有很强的攻击性。');
INSERT INTO `genshin_enemy` VALUES (26156101, 26156101, '球球章鱼', '[\"因原海而进化的生命\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '通过发射水弹进行狩猎的水生动物。\r\n当然了，发射水弹在原海异种当中并不是稀罕的能力，但对以游客为首的大意潜水者而言，这种高压水流能够造成不小的伤害。潜水护具的厚重是为了两个原因：抵抗水下的压力，以及抵御原海异种的攻击。');
INSERT INTO `genshin_enemy` VALUES (26157101, 26157101, '天使海兔', '[\"因原海而进化的生命\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '通过发射水弹进行狩猎的水生动物。\r\n从演化的角度而言，原海异种是因为枫丹特殊的环境而产生了变化的水生动物。也因此可以认为在过去的某个时点前，枫丹原始的水生动物与提瓦特其他地区的水生动物并没有多少区别。');
INSERT INTO `genshin_enemy` VALUES (26160101, 26160101, '坚盾重甲蟹', '[\"因原海而进化的生命\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '寄居在螺与壳之中的螃蟹。\r\n重甲蟹会在成长的阶段中不断寻找适合自己体格的外壳。曾经有畅销的童话书，描述了重甲蟹寻找属于自己的住所的坎坷历程。那是充满了童趣的故事，但事后的反响证明了它与不少别的童话一样，为成年人带来的感触更深。');
INSERT INTO `genshin_enemy` VALUES (26160201, 26160201, '大天使海兔', '[\"因原海而进化的生命\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '天使海兔成年后的形态，背上的「双翼」实际上是储存元素能量的脂肪块。\r\n这种水生动物究其一生都在进食、储存实际活动中并不需要的大量能量。或许在大海干涸后的末日，它能够继续存活很长的时间，或是成为其他生物的重要养分。');
INSERT INTO `genshin_enemy` VALUES (26160301, 26160301, '泡泡雄海马', '[\"因原海而进化的生命\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '雄性的泡泡海马成年后的形态，具有非常强的攻击性。\r\n曾经有人遇见过海马当中的王者，据说那是拥有修长四肢的高傲生灵。');
INSERT INTO `genshin_enemy` VALUES (26160302, 26170101, '铁甲熔火帝皇', '[\"山峦之下鼓动的热潮\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '矗立在原海异种顶端的两位霸主之一，曾经是海员之间的逸闻。\r\n不遇天敌，能够一直狩猎、进食的重甲蟹会随着成长，不断寻找适合的螺与贝壳，作为新的甲胄。但在最后它长得实在太大了。在第一次涨水期前，曾有巨大的重甲蟹袭击船只，并最终被尚未复职的海军司令贝瑟·埃尔顿击退的记录。\r\n设想这样的世界：将提瓦特所有的人都消除，无限成长下去的铁甲熔火帝皇终究会将沫芒宫穿在身上，作为最为华美的白石铠甲吧。当然在那样的世界自然不会有人半是敬畏，半是戏谑地将它称为「铁甲熔火帝皇」了。');
INSERT INTO `genshin_enemy` VALUES (26180101, 26180101, '千年珍珠骏麟', '[\"陆上大湖的无名之主\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '矗立在原海异种顶端的两位霸主之一。\r\n诗人与作者常因其独行而称之孤傲而高洁，但能成为这类描绘的对象归根到底是因为它身姿修长优美。也因此它为「骏麟」，而重甲蟹的王是「帝皇」。\r\n在枫丹的传奇逸话中，原海异种当中曾经爆发过无比酷烈的战争，只留下「千年珍珠骏麟」与「铁甲熔火帝皇」在大湖南北分庭抗礼。在《多尔库之歌》中，作者曾经描绘了战争的结局：被称为风暴王的巨大猎刀鳐在死前掀起了巨浪，导致了人们口中所谓的「第一次涨水期」…\r\n所有的这一切当然只不过是人不愿习惯于毫无幻想可言的现实生活而进行的浪漫想象。原海异种归根到底不过是水生动物罢了，既没有华丽或破败的王庭，也没有昂扬或恶毒的话语。');
INSERT INTO `genshin_enemy` VALUES (26190101, 26190101, '隐山猊兽', '[\"悠古的群山之主\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '优雅而高傲的灵兽，只栖息于仙力萦绕的深山中。\r\n自古以来，这种仙兽便被认为是福运的象征，其隐居山林、远离世俗纷扰的特质也为历代文人墨客所赞赏。在沉玉谷当地的古老传说中，猊兽的首领名为「山主」，其地位往往被认为与仙人等同。\r\n另有说法认为，如今伏行山林的玄文兽亦是这些仙兽的后嗣，只是因仙缘浅薄，难以继承如此高贵的血脉，从而退化为凶暴的野兽。这种说法与另一种关于玄文兽起源的说法相违背，但尽管如此，关于猊兽为数不多的记载中，其出现往往伴随着大量的玄文兽作为随从。\r\n如今，沉玉谷家喻户晓的「舞兽戏」，便是模仿传说中猊兽的动作与神态进行的表演。然而，真正见到过猊兽的人少之又少，绝大多数人只能通过想象来描述这种生灵的模样。数千年的流变与艺术加工后，「兽首」最终也固定成了现今的样式。');
INSERT INTO `genshin_enemy` VALUES (26190201, 26190201, '玄文兽', '[\"伏行的玄影\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '栖息在沉玉谷山林间的凶猛野兽，因其深色的纹理而得名「玄文」。\r\n沉玉谷本地的民话中，在遥远的过去，这些猛兽曾是某位仙人的眷属，降妖伏魔、庇护一方，在仙人故去后，方才退化为凶暴的野兽。传说早已无从查考，仙人的身份也众说纷纭，唯一可以确定的是，出于安全考虑，最好还是不要贸然靠近这些暴躁的生灵。\r\n千年间，伴随着人类不懈的开拓，原本属于这些野兽的生存空间变得越来越小。时至今日，只有在沉玉谷人迹罕至的崇山峻岭中，才能偶尔看到这些猛兽的身影…');
INSERT INTO `genshin_enemy` VALUES (26200101, 26200101, '幼嵴锋龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '年幼的嵴锋龙，拥有在山石与固态燃素中穿梭的能力。\r\n额前尚未形成钻角，而开掘的技术也不够熟练。甚至经常听闻练习挖掘的幼嵴锋龙被山石困住的事。不过终有一日，能够成长为在坚土中自由穿行的样貌吧。');
INSERT INTO `genshin_enemy` VALUES (26200201, 26200201, '嵴锋龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有钻角与坚爪，能够在山石与固态燃素中穿梭的龙。\r\n传说中，嵴锋龙的祖先是山一般巨大的龙兽，拥有相当漫长的寿命，沉睡时，群山在其背脊上成型，苏醒时，就会抖落身上的泥土与沉岩，唯留宝石与美玉在鳞角中熠熠生辉。「回声之子」部族中巨大的钻状物，据说是那时龙兽巨大钻角的遗留。');
INSERT INTO `genshin_enemy` VALUES (26210101, 26210101, '幼鳍游龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '年幼的鳍游龙，拥有在水域与液态燃素中游动的能力。\r\n皮肤与鳍肢尚且稚嫩，甚至还无法像成年的鳍游龙那样长时间待在高热的环境中。不过终有一日，能够成长为在水中自由遨游的样貌吧。');
INSERT INTO `genshin_enemy` VALUES (26210201, 26210201, '鳍游龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '具有粗壮的鳍肢与长尾，能够在水域与液态燃素中游动的龙。\r\n传说中，更为远古的龙拥有更加强的环境适应度，那时海中最为巨大的龙漂浮在水面上时，甚至会让人误以为是一座浮起的岛屿。据说现在的鳍游龙就是那种巨大海龙的后裔，从其宽阔的背部，似乎也能窥得远古海兽的庞然形态。');
INSERT INTO `genshin_enemy` VALUES (26220101, 26220101, '幼匿叶龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '年幼的匿叶龙，可以吐出藏在颊袋中的火榴果胶卷住远处的物体。\r\n卷住物体的力量并不强，自身的平衡感也远未达到可在空中自如穿梭的程度，有时即使是坐在尾巴上也会不由自主地向着一侧倾倒。不过终有一日，能够成长为在林间悠然摆荡的样貌吧。');
INSERT INTO `genshin_enemy` VALUES (26220201, 26220201, '匿叶龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有强壮的后肢与蓬松的尾部，能够吐出藏在颊袋中的火榴果胶卷住远处物体的龙。\r\n传说中，原本的匿叶龙并非现在的模样，而是更小，小到不易被观察到的程度。它们甚至可以随意游荡在风中，依附在其他巨龙的身体表面，或是如云一般群聚与游移。只是后来为了能够维持住能力退化后的形态，不得不选择现在的身姿。');
INSERT INTO `genshin_enemy` VALUES (26220301, 26220301, '贪食匿叶龙山王', '[\"巨硕山中之王\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '自古老的年代存活至今，经历了无数战场的强大匿叶龙。\r\n曾经与众英杰们携手面对漆黑潮水的「山王」，在「悬木人」部族的成员心中具备极重的分量。有部族人认为，它有着现在这样的体态，是与绒翼龙的「暴君」一般，拥有着特殊的体质…但也许只是因为它活得太长，而吃得也实在太多了的缘故。');
INSERT INTO `genshin_enemy` VALUES (26230101, 26230101, '幼绒翼龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '年幼的绒翼龙，拥有轻巧的身姿。\r\n脖颈与羽翼尚未完全生长开，对气态燃素的运用也十分生疏。也有年长的绒翼龙为促进幼龙的飞行而将它们推下山崖的逸话。虽然不知传言的真假，不过只要经历夜以继日的锻炼，稚嫩的翎羽总会有逐渐变得坚硬的一天。');
INSERT INTO `genshin_enemy` VALUES (26230201, 26230201, '绒翼龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有巨大且柔软的羽翅，能够在空中长时间滑行的龙。\r\n据说绒翼龙的先祖是最接近巨大翼龙形态的龙兽，能够如云一般在天际巡游。叙事人的故事里，远古翼龙里最伟大的那只，只要张开翅膀，就可以遮蔽一整片天空。如今的绒翼龙自然不再具有那样的形态，只有藏在绒羽之中的龙爪仍如从前一般锋利。');
INSERT INTO `genshin_enemy` VALUES (26230301, 26230301, '金焰绒翼龙暴君', '[\"告谕之翎\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '因承受了如今龙众的身躯无法驭使的伟力，而拥有超然形体的异种绒翼龙。\r\n在古老的传说里，如今常于山间迷雾盘桓的巨大翼龙，也曾在幼年时跟随故事里拯救纳塔的英杰们一同历险。据说众英雄的其中一位曾相约与它一同踏上前往火山的圣路，以挽回它因血脉中逐渐狂暴的力量而濒临失常的心智。只是以这位「暴君」现在获得的称呼来看，这段故事并未拥有完满的结局。');
INSERT INTO `genshin_enemy` VALUES (26240101, 26240101, '幼暝视龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '年幼的暝视龙，拥有细腻的感知力。\r\n尚未生长出覆羽，甚至看上去并不聪慧。据说暝视龙在现有的龙众中拥有最漫长的寿命，也拥有更长的幼年期。它们拥有与夜神之国或是大灵沟通的能力，只不过年幼的暝视龙要能够理解其中的一切或许还需经历许多岁月。');
INSERT INTO `genshin_enemy` VALUES (26240201, 26240201, '暝视龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '能够利用生长出的覆羽进行腾跃，亦是唯一一种掌握了进入「灵觉」状态技巧的龙。\r\n传说中，暝视龙的祖先不具备真正的实体，而能如游魂一般在魂灵和现实的世界穿梭，可以借由夜色显化自己的形体。也有传言，世上第一只暝视龙并非真正的龙，而是自夜神的国度走出的有别于正常龙众的种族。');
INSERT INTO `genshin_enemy` VALUES (26250101, 26250101, '幼突角龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '年幼的突角龙，因无法完全掌控身躯的力量而有些笨拙。\r\n第二对副角并未生长完全，背部与腹部的力量也没有到能够摧毁挡路岩石的程度。但只要能够茁壮成长，总有能够在沃土平原之上自由驰骋的时刻吧。');
INSERT INTO `genshin_enemy` VALUES (26250201, 26250201, '突角龙', '[\"肆游纳塔的诸龙众\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '拥有坚硬的冠骨和强大身躯力量，能够在火山四周的原野上飞速疾驰的龙。\r\n传说中，原本的突角龙具有堪称庞大的形体，甚至可以用角顶着山峰进行移动，只不过行动远不如当今这样灵敏。或许如今突角龙身躯里所具备的那种力量，也是一种血脉之中的遗留。');
INSERT INTO `genshin_enemy` VALUES (26260101, 26260101, '窟岩·大灵显化身', '[\"夜晚与游灵的代行\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '「回声之子」部族所信仰与崇拜的「大灵」，借由图腾与夜魂之力，于大地之上显化的形体。在纳塔部族民的认知之中，「大灵」生活在夜神的国度，并且不具备固有的形体，因为「大灵」可以依附于任何事物上，给迷茫的部族民以指引。而大灵显化身在其中尤为特殊，借助图腾的形态展露的身姿，往往有其重要的使命。\r\n「回声之子」的人相信他们的「大灵」拥有塑造山峰与低谷的力量，能够执掌山石摩擦的回响。');
INSERT INTO `genshin_enemy` VALUES (26260201, 26260201, '溯流·大灵显化身', '[\"夜晚与游灵的代行\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '「流泉之众」部族所信仰与崇拜的「大灵」，借由图腾与夜魂之力，于大地之上显化的形体。\r\n所谓的「大灵」，即是纳塔人与夜神的国度沟通之后，逐渐形成的以部族与曜石图腾为主体的信仰，是集体冥思的意识，也是先民灵魂的归处。\r\n「流泉之众」的人相信他们的「大灵」拥有控制潮汐与海浪的力量，能够执掌流水与腐水的变化。');
INSERT INTO `genshin_enemy` VALUES (26260301, 26260301, '疾叶·大灵显化身', '[\"夜晚与游灵的代行\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '「悬木人」部族所信仰与崇拜的「大灵」，借由图腾与夜魂之力，于大地之上显化的形体。\r\n在叙事人的故事中，大灵显化身经常作为试炼的使者，或者夜神之国的引路人的形象出场。也有龙冠武士曾言，自己在武术修行的恍惚中与大灵显化身交手，从而获得了更深层次的领悟。\r\n「悬木人」的人相信他们的「大灵」拥有控制果实与林叶生长的力量，能够执掌作物的根茎，画下叶脉的走势。');
INSERT INTO `genshin_enemy` VALUES (26260801, 26260801, '凛冽·大灵显化身', '[\"夜晚与游灵的代行\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '「烟谜主」部族所信仰与崇拜的「大灵」，借由图腾与夜魂之力，于大地之上显化的形体。\r\n「烟谜主」部族的成员曾尝试过许多与夜魂的国度沟通的媒介，最后众人发现，能与「大灵」建立最为稳定联系的中介物质是黑曜石。这或许是大灵显化身在长久的岁月中形成类似石像般造型的原因。「烟谜主」的人相信他们的「大灵」拥有控制冰晶与冻结的力量，能够执掌固型和流变的话语。');
INSERT INTO `genshin_enemy` VALUES (26260901, 26260901, '焚燃·大灵显化身', '[\"夜晚与游灵的代行\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '「花羽会」部族所信仰与崇拜的「大灵」，借由图腾与夜魂之力，于大地之上显化的形体。\r\n据说很久以前大灵显化身的造型与如今也有很大的差别，是更粗糙，更接近黑曜石像的姿态。可是随着织卷记录下了大灵显化身的轮廓后，就很少再有变化了。\r\n「花羽会」的人相信他们的「大灵」拥有控制火焰与燃烧的力量，能够执掌热量与焚风的流转。');
INSERT INTO `genshin_enemy` VALUES (26261101, 26261101, '雳震·大灵显化身', '[\"夜晚与游灵的代行\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '「沃陆之邦」部族所信仰与崇拜的「大灵」，借由图腾与夜魂之力，于大地之上显化的形体。\r\n在「沃陆之邦」的部族的传说里，「大灵」曾经幻化过种种样貌，在晦暗而看不清相互面目的黎明之前，与部族里有名的大力士角力，不过往往以两者相持不下为结尾告终。\r\n「沃陆之邦」的人相信他们的「大灵」拥有控制雷霆与速度的力量，能够为土地带来富饶的物产。');
INSERT INTO `genshin_enemy` VALUES (26270101, 26270101, '熔岩游像·流燃体', '[\"熊熊燃烧的石之心\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '需要持续不断吸收热量以维持活动状态的奇特魔物。\r\n曾经，更加古老而深邃的火以各种形态遍布纳塔的大地，那时一度伟大的原始住民们利用这些火来传递光热与智慧，他们认为生命与灵魂亦是从燧石相撞的火花中拥有最初的形廓。\r\n如果拥有常燃之芯，即使是顽石也能成就生命吧，被名为熔岩游像包裹在体内的余烬，似乎也是那伟大时代冷灰般的残余。');
INSERT INTO `genshin_enemy` VALUES (26270201, 26270201, '熔岩游像·蚀土者', '[\"熊熊燃烧的石之心\"]', 'MONSTER_ORDINARY', 'NORMAL', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '需要持续不断吸收热量以维持活动状态的奇特魔物。\r\n古老的文明利用镌光的金纹驱使燃素流动的诸多法式，令巨大的造物与恢弘的城市得以在金纹创生的智慧中运转。据说除了固定结构的机械以外，名为熔岩游像的魔物其实也是以此方法创造的残缺生命，只不过在圣山的火焰熄灭之后，它们大多失去了目的与方向。');
INSERT INTO `genshin_enemy` VALUES (26270301, 26270301, '熔岩辉龙像', '[\"石心流焰的终型\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '能够自身持续产生热量，以维持活动状态的魔物。\r\n据说，由熔岩作为核心的魔物，是有别于后来诞生的秘源机关的另一方向研究的副产物。其研究的主题即是，原初的火焰是否能够模仿人类创造新的种族…但研究毫无疑问失败了，在天上掠夺者的圣座到来之后，源火之中所能诞生的，最终也只有这样徒具备形态和生命力，却无知无觉的空壳魔物。');
INSERT INTO `genshin_enemy` VALUES (26290101, 26290101, '炉壳山鼬', '[\"远古圣山的巡猎者\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '因生活在与外界隔绝的特殊燃素环境之内，而拥有特殊形态的古代种山鼬。\r\n通过进食富含燃素的生物，不断向背壳之中积蓄力量的古代兽种。于圣山废墟的长久生活之中，似乎由于独特的亲近燃素的性质，逐渐被圣山废墟之中的秘源机关影响，形成了独有的与秘源机关互相依附的生存状态。');
INSERT INTO `genshin_enemy` VALUES (26300101, 26300101, '蕴光奇羊', '[\"奇羊\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '长久浸浴古老月之力而演化出独特生态的魔兽。\r\n在月光眷顾的土地上曾降下异雷，而原本凡弱的奇羊也因此而获得了驱使雷电的能力。据说也曾有人目睹奇羊立于雷暴汇聚的崖边，主动吸引雷电淬炼己身的奇异景象。');
INSERT INTO `genshin_enemy` VALUES (26300201, 26300201, '蕴光刃犀', '[\"刃犀\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '长久浸浴古老月之力而演化出独特生态的魔兽。\r\n据说从前，在边界之地曾被漆黑的阴影笼罩之时，唯有巨犀能通过族群的奔行将可令万物流转的力量重新带回此处…而这也是月光降下恩赐后，向它们索求的唯一的报答。');
INSERT INTO `genshin_enemy` VALUES (26300301, 26300301, '蕴光璇蛸', '[\"璇蛸\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '长久浸浴古老月之力而演化出独特生态的魔兽。\r\n传说在灾厄席卷大地的时代，在绝海之中生息的种群亦不能幸免，那些未能接纳月光的都如泡沫消散，无论是翻腾起滔天巨浪的大海蛇抑或是妄图吞噬一切的独眼怪兽。');
INSERT INTO `genshin_enemy` VALUES (26300401, 26300401, '蕴光凛狼', '[\"凛狼\"]', 'MONSTER_ORDINARY', 'ELITE', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '长久浸浴古老月之力而演化出独特生态的魔兽。\r\n传说在漆黑的灾祸抹去诸多生灵之际，边地的森林寂然无声。彼时，划破死寂的是向月而嗥的凛狼。群狼悲歌般的低吼挟着清冷的月光，在无数个夜里回荡于荒野之上。');
INSERT INTO `genshin_enemy` VALUES (26301101, 26301101, '蕴光月幻蝶', '[\"蕴光月幻蝶\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '古老的月之力浸润了幻惑的双翅，于月光下翩然起舞的蝶形魔物。\r\n按照演化的理论来说，在狂暴而原始的力量被天空的主人驯化之后，此种类型的魔物本应无法维持这样的体型，会变得更为微小和脆弱。然而月光的恩赐令其能以强盛时的姿态漫行于世，向众人展现古老月亮曾照映的旧世界的残余。');
INSERT INTO `genshin_enemy` VALUES (26302101, 26302101, '蕴光月守宫', '[\"蕴光月守宫\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BEAST', '异种魔兽', '眷恋月光的古老魔物，在岩层深处栖息的守宫。\r\n躯体因长久以来积蓄的月矩力而发生晶化，形成如同机关构件般精密的节段，能化作岩刺攻击敌人。\r\n有学者认为，这种奇异蜥类的祖先原本生活在地表，千年以来的沧海桑田令它们被迫遁入地底，从此之后便世代栖居于黑暗之中，逐渐忘却了真正的月光，不过本能依旧驱使着它们在满月之时啃食被月辉浸浴的岩土以维持血脉。');
INSERT INTO `genshin_enemy` VALUES (29010101, 29010104, '裂空的魔龙', '[\"风魔龙\", \"风魔龙·特瓦林\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '蒙德的「四风守护」之一，东风之龙特瓦林。\r\n在漫长的岁月与无边的黑暗中，清澈的宝石也会蒙尘而变得黯淡，高傲的龙也会被侵蚀而充满了忿恨。\r\n不过，要记住，尘埃能被轻易拭去，疑惧与毒也能被粉碎。\r\n\r\n「自由地在深空中翱翔吧。\r\n「就如当年你我相遇时，我行走在大地上，唱着风的歌曲；\r\n「你则在大气稀薄的高天上，俯瞰世界。\r\n「如今的天空中没有风雪，大地上充满了绿草，会很美丽吧。\r\n「如果你也在地面上行走过，听过牧歌和风铃在远方错落的歌，尝过蜜一样甜的酒，就会明白吧。\r\n「如果你曾是我，看见过你在蓝蓝的天上滑翔的孤高模样，见识过你的美丽身姿就好了。\r\n「如此，你就会明白，这样的天空与大地，是值得为之奋战的。」');
INSERT INTO `genshin_enemy` VALUES (29020101, 29020101, '北风的王狼，奔狼的领主', '[\"玻瑞亚斯\", \"安德留斯\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '守望着奔狼领的「卢皮卡」，无比崇高的伟大灵魂。\r\n当群狼受到威胁时，会以狼的姿态现世，展现自己的苍牙与利爪。\r\n\r\n奔狼领的狼对蒙德人而言，通常是诡谲的魅影：\r\n树木之间一闪而过的模糊形象、方位难辨的凄嚎，以及独行郊野林中时，时常能隐约感受到的视线。\r\n人与狼冰冷的双眸直视的机会很少，因为「王狼」为自己的族类订立了规矩。');
INSERT INTO `genshin_enemy` VALUES (29030101, 29030103, '「公子」', '[\"「公子」\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '愚人众执行官第十一席，「公子」达达利亚。\r\n自不祥的「邪眼」之中汲取力量，以至暗之地习得的武艺战斗。\r\n\r\n拥有无穷争斗欲望的纯粹战士。\r\n每次浴血的纷争、每场生死攸关的挑战，于他而言皆是快意试炼。\r\n人皆言年轻的「公子」战绩远近闻名。\r\n但他本人却对这种大话从来不以为然。\r\n\r\n毕竟…\r\n「你的命运将成为纷争的风暴之眼，\r\n「铁剑交错的声响是常伴你的奏乐。\r\n「踏入至暗之处的漆黑记忆，\r\n「终将成为你颠覆世界的力量吧。」');
INSERT INTO `genshin_enemy` VALUES (29040101, 29040101, '若陀龙王', '[\"若陀龙王\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '如同山岳一般长寿的古老巨龙。\r\n在难以追忆的年月里曾与岩港的帝君并肩，但最终反目，遭镇压于黑暗的地底。在无比漫长的岁月中，它的力量渐渐流失，形态也因各种折磨而扭曲。\r\n枷锁的隐隐震响与龙祖低沉的怒吼，同记忆一般在山峦间回荡。');
INSERT INTO `genshin_enemy` VALUES (29050101, 29050102, '「女士」', '[\"「女士」\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '愚人众执行官第八席的「女士」。\r\n与行使邪眼之权能的其他愚人众不同，邪眼是抑制啃噬一切的烈火的器物。比起厮杀用的兵器，说是刑拘道具才更为贴切。\r\n而这就是漫长的岁月中积郁的余烬，冲破邪眼霜封后为她涂抹的扭曲妆容。\r\n\r\n瞳仁中倒映着破晓的赤红，她最后展开烈焰之翼向黎明飞去。\r\n「但那并不是曙光，亲爱的罗莎琳。那是焚尽一切的火海。」\r\n在光芒中，一个声音这么对她说。\r\n\r\n但这也没什么所谓。因为她心中明白，自己早已被烈火吞没。');
INSERT INTO `genshin_enemy` VALUES (29060201, 29060202, '祸津御建鸣神命', '[\"雷电之稻妻殿\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '代行雷电将军权能的人偶，在对抗威胁「永恒」之敌时展现出的形态。\r\n作为雷电影践行「永恒」的协助者，她从未质疑，亦无畏惧，一直以来全力以赴，心无杂念。\r\n她曾听闻在真与影的时代，影承担着与她类似的责任，经历了诸多惨痛失去。\r\n当两个影子交叠为一时，她却只能看见在「她」本应永恒的意志上留下的无数细密的凿痕吧。既然命运注定是一场轮回，就如约定那样，向其宣战吧。\r\n\r\n「此身，象征无上威严，被授予统领一国之权，凝聚了『雷电将军』的一切。\r\n「自然也继承了影前行时不断失去的痛苦，以及，想要抵达永恒的决心。\r\n「决心、勇气、爱慕、仇恨…都会在时间长河中变质扭曲。\r\n「唯有『法则』永恒不变。」');
INSERT INTO `genshin_enemy` VALUES (29070101, 29070104, '「正机之神」', '[\"七叶寂照秘密主\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '汇聚须弥教令院六大学院力量制造出的人造正机神，拥有比肩真神的威能。\r\n世人若称之为伪神，则是不懂得「神」的真意。\r\n假如超人者为神，\r\n正机神已通晓万事背负无上力量，谓之超人。\r\n假如爱人者为神，\r\n正机神亦懂得赐予人平等的失败，谓之爱人。\r\n假如观人者为神，\r\n……\r\n…………\r\n正机神窥得无数爱憎别离怨嗔痴，谓之观人。\r\n\r\n「汝等已拥有太多的幸福，\r\n「因此变得愚昧自大，贪婪可怖。\r\n「终结这个时代！\r\n「新的神明，宣告旧神将败北。\r\n「可悲的人类…现在还来得及跪下。」');
INSERT INTO `genshin_enemy` VALUES (29080101, 29080102, '阿佩普的绿洲守望者', '[\"历经千年之「末日」的进化生命\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '阿佩普曾与诸多子嗣一同在芳草之海、百尺巨木与千里之藤蔓中，如游鱼穿行于水。直到最终草木枯萎化为尘埃，如同砂砾般渺小的诸多生灵在它原本的土地上建立起脆弱的城国。\r\n阿佩普曾与诸多子嗣一同令沙海如沸水般翻腾，将城楼如落叶般吹散。直到新的沙海之王与失去故土的王相互和解，从此日光之下的沙丘都属于人与神，而龙的绿洲留在龙的心中。\r\n阿佩普曾与诸多子嗣一同分享进化的知识，因为流水不腐，而朽木必定倾倒。直到最终它践行了与沙之王的约定得到了终极的智慧，从此它只能看见终末的风景，漫无边际的末日。\r\n阿佩普曾独自沉溺于末日的风景当中。所有的人、神、龙、走兽、飞鸟与游鱼，所有记忆、智慧、话语与仇恨将都磨为无色尘粉，最后一轮明月之光则化作白焰之雨落在荒土之上。\r\n……\r\n阿佩普曾视沙海之底为自己的墓场，而非失乡之王的行宫。「智慧」的毒很快就会让它从无数个月亮的仇恨与愤怒中解脱。它已经对终末缺乏颜色的景象感到厌倦了。直到最终年轻的神明与金色的旅人让它再度回想起，即便自己曾经主宰的青绿土地已经化作饰金的荒原，即便自己与子嗣为了在其中生存而变得扭曲丑陋，但它的心中始终珍藏着那一角绿洲的景象。');
INSERT INTO `genshin_enemy` VALUES (29090101, 29090101, '吞星之鲸', '[\"无光星海彼端的访客\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '神秘的异界巨兽。');
INSERT INTO `genshin_enemy` VALUES (29091001, 29100103, '「仆人」', '[\"愚人众执行官第四席\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '愚人众执行官第四席，「仆人」。');
INSERT INTO `genshin_enemy` VALUES (29091101, 29110101, '蚀灭的源焰之主', '[\"受塑的已死之龙\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '漆黑之力凝成的魔龙。');
INSERT INTO `genshin_enemy` VALUES (29122000, 29122000, '门扉前的弈局', '[null]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '集魔女会诸家技艺而制成的集团军。\r\n虽然全都是既有技术，并无触及宇宙根本的高深智慧。它们把守跨越门扉的最后一关，同时自身也是一种隐喻。\r\n这个世界上或许有规则，可一旦越过门扉，就再无约束了。');
INSERT INTO `genshin_enemy` VALUES (29130201, 29130201, '「博士」', '[\"多托雷\"]', 'MONSTER_BOSS', 'BOSS', 'CODEX_SUBTYPE_BOSS', '值得铭记的强敌', '以「异端」的恶名昭著于世，愚人众执行官第二席的「博士」，在攫取了三月的权柄后，如今已踏上通往「新世界」神座的阶梯。\r\n我们本应拥有一切。\r\n理，放逐了所有不可思之物，使世人再也无法抵达本性；\r\n生与死，制造了肉体凡胎的牢笼，禁锢一切灵魂的野心；\r\n时与空，限制了人类思想的边界，使人们变得短视顺从。\r\n从此，虚伪的神明统治了世界，每一个都以真理之名宣称自己唯一正确，却没有一个配得上这般名头。\r\n生命的流变并不具有秩序的结构，唯有抹除施加在这个世界上的层层枷锁，才能窥见一切事物的本质。\r\n那便是新世界的光芒。\r\n「你们难道愿意忍受这个迂腐陈旧的世界吗？」');
INSERT INTO `genshin_enemy_investigation` VALUES (1, 24030301, 46, '兆载永劫龙兽', 'Boss', '首领', '如同古时曾制御大地的君王一般，令人望而生畏的龙形战斗机械。\\n这架不知疲倦的神秘机械巨兽似乎证明，传说已经覆灭的国度确已触及了人所不应抵达的领域。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (2, 24050101, 47, '半永恒统辖矩阵', 'Boss', '首领', '属于古老文明的永恒机关。\\n统辖着散落在沙漠中的众多遗迹构装体，其中似乎仍残留着孤独君王的执着意念。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (3, 21040101, 52, '丘丘游侠', 'Elite', '精英', '不属于任何部族与聚落的丘丘人流浪者，常在荒野中四处漫游。\\n有时也会在因缘的指引下帮助其他的丘丘人。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (4, 20040201, 7, '无相之风', 'Boss', '首领', '代号为「贝特」的高级风元素生命。\\n「无相」指的是抛弃了其他元素生物的形态与生态，达到的纯粹境地。\\n针对无相元素的研究，主要由须弥教令院的学者主导进行。但由于其危险性，除了代号与命名以外，基本没有取得什么值得参考的研究成果…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (5, 21030301, 19, '丘丘萨满', 'Common', '普通', '丘丘人当中的萨满祭司。能在一定程度上求得元素的帮助。\\n「面具的造型设计有着恫吓敌人的意味，但反而让它们看起来有些亲切。」——雅各布·马斯克', '');
INSERT INTO `genshin_enemy_investigation` VALUES (6, 20010301, 20, '史莱姆', 'Common', '普通', '圆滚滚的元素生物。\\n据说，不同元素属性的史莱姆做成的甜品，会有各不相同的奇妙风味。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (7, 20060301, 34, '飘浮灵', 'Common', '普通', '高浓度的元素孕育而生的魔物，能够飘浮在空中。\\n总体而言，是性情相对温和，近似史莱姆的小小生灵，但在愤怒的状态下也会爆发。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (8, 26157101, 55, '原海异种', 'Common', '普通', '遍布枫丹的水生动物。\\n出于自然环境的缘故，似乎只能在枫丹生长。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (9, 24069001, 54, '发条机关', 'Common', '普通', '得益于工程技术的进步与枫丹独有的动力源，而存在的人造机械。\\n同时也是歹人盗匪的好帮手。', '');
