INSERT INTO `genshin_enemy_investigation` VALUES (15, 22080201, 40, '黑蛇众', 'Elite', '精英', '曾经似乎是具有相当身份的王国骑士。\\n如今似乎随着岁月与诅咒，失去了几乎全部的智性与记忆，只有「为了何事、何人、何物而战」的意志还残留在铠甲当中吧。\\n依据损耗的程度，分别被称为「黯色空壳」与「黑蛇骑士」。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (16, 22080101, 40, '黑蛇众', 'Elite', '精英', '曾经似乎是具有相当身份的王国骑士。\\n如今似乎随着岁月与诅咒，失去了几乎全部的智性与记忆，只有「为了何事、何人、何物而战」的意志还残留在铠甲当中吧。\\n依据损耗的程度，分别被称为「黯色空壳」与「黑蛇骑士」。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (17, 21020201, 4, '丘丘暴徒', 'Elite', '精英', '丘丘人的部落当中，百里挑一的强壮勇士。\\n对于丘丘人而言，最重要的事情就是吃肉和打架，让身体变得强壮。如果能成为丘丘暴徒这样又大又壮的战士，就能吃更多肉、打更多架了。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (18, 20080301, 82, '霜夜灵嗣', 'Elite', '精英', '体态瑰美优雅的元素生命。\\n它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。在漫长的岁月中沐染着高浓度的元素力，最终演化成了如今的形貌。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (19, 26153101, 55, '原海异种', 'Common', '普通', '遍布枫丹的水生动物。\\n出于自然环境的缘故，似乎只能在枫丹生长。', '');
