INSERT INTO `genshin_enemy_investigation` VALUES (23, 23080201, 85, '巡陆艇', 'Common', '普通', '将海军理念应用在地面战之上的自律机关。\\n作为「巡弋于陆地的武装舰艇」，巡陆艇是由至冬军械宫的工程师研发设计的新型战争兵器，如今已广泛应用于愚人众所发起战争的最前线。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (24, 23080101, 85, '巡陆艇', 'Common', '普通', '将海军理念应用在地面战之上的自律机关。\\n作为「巡弋于陆地的武装舰艇」，巡陆艇是由至冬军械宫的工程师研发设计的新型战争兵器，如今已广泛应用于愚人众所发起战争的最前线。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (25, 26100201, 51, '圣骸兽', 'Elite', '精英', '因为啃噬伟大的生命体，而扭曲异变的动物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (26, 26100501, 51, '圣骸兽', 'Elite', '精英', '因为啃噬伟大的生命体，而扭曲异变的动物。', '');
