INSERT INTO `genshin_enemy_investigation` VALUES (29, 26100401, 51, '圣骸兽', 'Elite', '精英', '因为啃噬伟大的生命体，而扭曲异变的动物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (30, 24069201, 54, '发条机关', 'Common', '普通', '得益于工程技术的进步与枫丹独有的动力源，而存在的人造机械。\\n同时也是歹人盗匪的好帮手。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (31, 21020701, 4, '丘丘暴徒', 'Elite', '精英', '丘丘人的部落当中，百里挑一的强壮勇士。\\n对于丘丘人而言，最重要的事情就是吃肉和打架，让身体变得强壮。如果能成为丘丘暴徒这样又大又壮的战士，就能吃更多肉、打更多架了。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (32, 22010201, 2, '深渊法师', 'Elite', '精英', '一定程度上能驾驭元素进行战斗的深渊魔物。\\n出于某种不为人知的缘由，深渊法师精通丘丘人的笨拙语言，能驾驭它们的心智。据说深渊法师略通如今几乎无人可解的失落古语，并利用这种语言的力量行使魔法…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (33, 21011301, 18, '丘丘人', 'Common', '普通', '遍布大陆，有着最基础文明形态的人形魔物。\\n如今，大部分人已经放弃了与丘丘人沟通的尝试，认为它们只是纯粹的、不通言语的魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (34, 21010901, 17, '丘丘射手', 'Common', '普通', '操作弩进行远程攻击的丘丘人。\\n丘丘人的智能水平连学会弩机的操控方式都有困难，遑论生产这种需要精密加工的设备了。由此，或许可以认为，看似漫无目的地散布在大陆各处的丘丘人背后，或许有着为它们提供装备与训练的组织……', '');
INSERT INTO `genshin_enemy_investigation` VALUES (35, 20040501, 25, '无相之冰', 'Boss', '首领', '代号为「塔勒特」的高级冰元素生命。\\n根据研究，无相元素与常规的元素生物在物质构成上有着细微的差别。而这些细微的成分差别，或许就是它们高度稳定的形态与机械般的行动方式的由来吧。', '远古时期降落在龙脊雪山的长钉，不断向地脉中灌注着能量。当长钉被拔起时，或许山中会出现其他的异象吧…');
INSERT INTO `genshin_enemy_investigation` VALUES (36, 26020101, 8, '急冻树', 'Boss', '首领', '地脉中的寒霜附着在藤蔓上，由此形成的魔物。\\n有研究认为，植物就像世界的器官一样，调和着元素奔涌的地脉；而这种生态在地表上的结晶就是冰雾花、骗骗花等，充满了元素能量的产物。\\n而生长在特定环境的特定植物，经年累月或许就会成为急冻树这样的，如同魔兽一般庞大而凶猛的生命体吧…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (37, 21030501, 19, '丘丘萨满', 'Common', '普通', '丘丘人当中的萨满祭司。能在一定程度上求得元素的帮助。\\n「面具的造型设计有着恫吓敌人的意味，但反而让它们看起来有些亲切。」——雅各布·马斯克', '');
INSERT INTO `genshin_enemy_investigation` VALUES (38, 20010801, 20, '史莱姆', 'Common', '普通', '圆滚滚的元素生物。\\n据说，不同元素属性的史莱姆做成的甜品，会有各不相同的奇妙风味。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (39, 20060401, 34, '飘浮灵', 'Common', '普通', '高浓度的元素孕育而生的魔物，能够飘浮在空中。\\n总体而言，是性情相对温和，近似史莱姆的小小生灵，但在愤怒的状态下也会爆发。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (40, 26010101, 12, '骗骗花', 'Common', '普通', '古灵精怪的拟态植物魔物，会用元素战斗。\\n有时会隐藏在地表下，捕猎浑然不觉的猎物。如果有足够的年月、养分与环境，或许能扎根某处，长成巨大的、摇曳着喷吐魔力的树…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (41, 23085201, 85, '巡陆艇', 'Common', '普通', '将海军理念应用在地面战之上的自律机关。\\n作为「巡弋于陆地的武装舰艇」，巡陆艇是由至冬军械宫的工程师研发设计的新型战争兵器，如今已广泛应用于愚人众所发起战争的最前线。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (42, 23085101, 85, '巡陆艇', 'Common', '普通', '将海军理念应用在地面战之上的自律机关。\\n作为「巡弋于陆地的武装舰艇」，巡陆艇是由至冬军械宫的工程师研发设计的新型战争兵器，如今已广泛应用于愚人众所发起战争的最前线。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (43, 23085301, 85, '巡陆艇', 'Common', '普通', '将海军理念应用在地面战之上的自律机关。\\n作为「巡弋于陆地的武装舰艇」，巡陆艇是由至冬军械宫的工程师研发设计的新型战争兵器，如今已广泛应用于愚人众所发起战争的最前线。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (44, 24068601, 54, '发条机关', 'Common', '普通', '得益于工程技术的进步与枫丹独有的动力源，而存在的人造机械。\\n同时也是歹人盗匪的好帮手。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (45, 20040701, 49, '无相之草', 'Boss', '首领', '代号为「扎因」的高级草元素生命。\\n与其他的无相元素在行为规律上有显著的差异。而导致这一现象的原因迄今未有可靠的结论。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (46, 21030201, 19, '丘丘萨满', 'Common', '普通', '丘丘人当中的萨满祭司。能在一定程度上求得元素的帮助。\\n「面具的造型设计有着恫吓敌人的意味，但反而让它们看起来有些亲切。」——雅各布·马斯克', '');
INSERT INTO `genshin_enemy_investigation` VALUES (47, 20010101, 20, '史莱姆', 'Common', '普通', '圆滚滚的元素生物。\\n据说，不同元素属性的史莱姆做成的甜品，会有各不相同的奇妙风味。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (48, 20060701, 34, '飘浮灵', 'Common', '普通', '高浓度的元素孕育而生的魔物，能够飘浮在空中。\\n总体而言，是性情相对温和，近似史莱姆的小小生灵，但在愤怒的状态下也会爆发。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (49, 24110101, 95, '辖域守护者', 'Elite', '精英', '原初的大能者流溢而出的影之造物，守卫高天之柱殿的守护者。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (50, 22010401, 2, '深渊法师', 'Elite', '精英', '一定程度上能驾驭元素进行战斗的深渊魔物。\\n出于某种不为人知的缘由，深渊法师精通丘丘人的笨拙语言，能驾驭它们的心智。据说深渊法师略通如今几乎无人可解的失落古语，并利用这种语言的力量行使魔法…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (51, 21011601, 18, '丘丘人', 'Common', '普通', '遍布大陆，有着最基础文明形态的人形魔物。\\n如今，大部分人已经放弃了与丘丘人沟通的尝试，认为它们只是纯粹的、不通言语的魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (52, 21011001, 17, '丘丘射手', 'Common', '普通', '操作弩进行远程攻击的丘丘人。\\n丘丘人的智能水平连学会弩机的操控方式都有困难，遑论生产这种需要精密加工的设备了。由此，或许可以认为，看似漫无目的地散布在大陆各处的丘丘人背后，或许有着为它们提供装备与训练的组织……', '');
INSERT INTO `genshin_enemy_investigation` VALUES (53, 20040101, 6, '无相之雷', 'Boss', '首领', '代号为「阿莱夫」的高级雷元素生命。\\n无相元素是顶尖的元素构造体，会在元素能量喷涌的位置，或元素地脉阻塞的地点形成。\\n不同的无相元素会基于其元素特性，进化出歼敌方式。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (54, 26020301, 41, '掣电树', 'Boss', '首领', '会肆意释放地脉当中储存的电荷的巨大植物。\\n雷电的力量能使植物活化、土地肥沃。假使这种藤蔓是为了调和地脉而生的，那让须弥的林木繁茂或许就是大地的愿望吧。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (55, 21030601, 19, '丘丘萨满', 'Common', '普通', '丘丘人当中的萨满祭司。能在一定程度上求得元素的帮助。\\n「面具的造型设计有着恫吓敌人的意味，但反而让它们看起来有些亲切。」——雅各布·马斯克', '');
INSERT INTO `genshin_enemy_investigation` VALUES (56, 20010501, 20, '史莱姆', 'Common', '普通', '圆滚滚的元素生物。\\n据说，不同元素属性的史莱姆做成的甜品，会有各不相同的奇妙风味。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (57, 20060501, 34, '飘浮灵', 'Common', '普通', '高浓度的元素孕育而生的魔物，能够飘浮在空中。\\n总体而言，是性情相对温和，近似史莱姆的小小生灵，但在愤怒的状态下也会爆发。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (58, 26010301, 12, '骗骗花', 'Common', '普通', '古灵精怪的拟态植物魔物，会用元素战斗。\\n有时会隐藏在地表下，捕猎浑然不觉的猎物。如果有足够的年月、养分与环境，或许能扎根某处，长成巨大的、摇曳着喷吐魔力的树…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (59, 26160302, 59, '铁甲熔火帝皇', 'Boss', '首领', '蛰居在岩窟之中的古老原海异种王者，据说曾经见证过第一次涨水期之前的枫丹之海。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (60, 25210101, 44, '镀金旅团', 'Common', '普通', '来自黄金一般的沙漠的松散佣兵团体。为了报酬，愿意为任何人效力。\\n「镀金旅团」是沙之民以外的人对他们的统称，其中有着诸如「法罗赫之子」这样的佣兵团体，也有「塔尼特」这样的部族。\\n作为没有神的民族，多数的「镀金旅团」成员只会为了生计与雇主施展沙漠遗民的武艺。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (61, 25210201, 44, '镀金旅团', 'Common', '普通', '来自黄金一般的沙漠的松散佣兵团体。为了报酬，愿意为任何人效力。\\n「镀金旅团」是沙之民以外的人对他们的统称，其中有着诸如「法罗赫之子」这样的佣兵团体，也有「塔尼特」这样的部族。\\n作为没有神的民族，多数的「镀金旅团」成员只会为了生计与雇主施展沙漠遗民的武艺。', '');
