INSERT INTO `genshin_enemy_investigation` VALUES (72, 26270201, 73, '熔岩游像', 'Elite', '精英', '需要持续不断吸收热量以维持活动状态的奇特魔物。\\n会根据形成时名为「游像眼」的核心拥有的热量与周围山石的材质，而拥有不同的性质。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (73, 24080101, 61, '实验性场力发生装置', 'Boss', '首领', '枫丹动能工程科学研究院的作品，因为事故而失控。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (74, 23040101, 1, '愚人众·萤术士', 'Elite', '精英', '操控着飞萤进行战斗的愚人众少女术士。\\n正如雾虚草的气味会令飞萤迷醉，嗜虐的术士也贪恋着戏弄对手的快感。\\n看似漫无目的地四处游荡的她们，又领受着何种不为人知的使命呢…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (75, 23030101, 1, '愚人众·萤术士', 'Elite', '精英', '操控着飞萤进行战斗的愚人众少女术士。\\n正如雾虚草的气味会令飞萤迷醉，嗜虐的术士也贪恋着戏弄对手的快感。\\n看似漫无目的地四处游荡的她们，又领受着何种不为人知的使命呢…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (76, 23020101, 10, '愚人众·债务处理人', 'Elite', '精英', '隶属愚人众的特务人员。\\n债务处理人所处理的「债务」，并不局限于钱货往来的清算。\\n「以眼还眼，以牙还牙」也是一种债。无论是谁，只要损害了愚人众的利益，那就要十倍奉还。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (77, 23010501, 5, '愚人众·先遣队', 'Common', '普通', '愚人众战争机器中的士兵。\\n「先遣队」之名意味着生死不问，深入祖国以外的土地完成前期任务，为未来的某些行动夯实基础。\\n不同于少数精锐的债务处理人与萤术士，先遣队的单兵实力与装备较为薄弱。\\n为了完成任务，为了减少人员与物资的损耗，先遣队的战术更讲究团队协作。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (78, 23010101, 5, '愚人众·先遣队', 'Common', '普通', '愚人众战争机器中的士兵。\\n「先遣队」之名意味着生死不问，深入祖国以外的土地完成前期任务，为未来的某些行动夯实基础。\\n不同于少数精锐的债务处理人与萤术士，先遣队的单兵实力与装备较为薄弱。\\n为了完成任务，为了减少人员与物资的损耗，先遣队的战术更讲究团队协作。', '');
