INSERT INTO `genshin_enemy_investigation` VALUES (82, 23010601, 5, '愚人众·先遣队', 'Common', '普通', '愚人众战争机器中的士兵。\\n「先遣队」之名意味着生死不问，深入祖国以外的土地完成前期任务，为未来的某些行动夯实基础。\\n不同于少数精锐的债务处理人与萤术士，先遣队的单兵实力与装备较为薄弱。\\n为了完成任务，为了减少人员与物资的损耗，先遣队的战术更讲究团队协作。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (83, 22140101, 91, '深黯钓客', 'Elite', '精英', '穿过深黯的裂隙，自异界侵入此世的深渊魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (84, 26090301, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (85, 26090201, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (86, 26090101, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (87, 25502201, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (88, 25505201, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (89, 25500101, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (90, 26260201, 72, '大灵显化身', 'Elite', '精英', '纳塔各个部族所信仰的「大灵」借由黑曜石图腾的形象如斯显化。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (91, 26270101, 73, '熔岩游像', 'Elite', '精英', '需要持续不断吸收热量以维持活动状态的奇特魔物。\\n会根据形成时名为「游像眼」的核心拥有的热量与周围山石的材质，而拥有不同的性质。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (92, 26260301, 72, '大灵显化身', 'Elite', '精英', '纳塔各个部族所信仰的「大灵」借由黑曜石图腾的形象如斯显化。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (93, 23080501, 85, '巡陆艇', 'Common', '普通', '将海军理念应用在地面战之上的自律机关。\\n作为「巡弋于陆地的武装舰艇」，巡陆艇是由至冬军械宫的工程师研发设计的新型战争兵器，如今已广泛应用于愚人众所发起战争的最前线。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (94, 23080401, 85, '巡陆艇', 'Common', '普通', '将海军理念应用在地面战之上的自律机关。\\n作为「巡弋于陆地的武装舰艇」，巡陆艇是由至冬军械宫的工程师研发设计的新型战争兵器，如今已广泛应用于愚人众所发起战争的最前线。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (95, 23080301, 85, '巡陆艇', 'Common', '普通', '将海军理念应用在地面战之上的自律机关。\\n作为「巡弋于陆地的武装舰艇」，巡陆艇是由至冬军械宫的工程师研发设计的新型战争兵器，如今已广泛应用于愚人众所发起战争的最前线。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (96, 25501101, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (97, 25505101, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (98, 25504101, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (99, 21020401, 22, '丘丘王', 'Elite', '精英', '体内积聚了大量的元素，发生了变异的丘丘暴徒。更大、更壮、更凶悍。\\n丘丘人的文明中没有神，也没有秩序。只要够强壮，打架够狠，就能成为它们的王者。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (100, 20081001, 89, '霜夜巡天灵主', 'Boss', '首领', '傲然巡行于霜夜的奇异生灵。\\n自如驱使着如今早已被高天之主驯化的古老力量，其染上绚烂色彩的羽翼至今仍残留着远古岁月的光辉。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (101, 23060101, 60, '愚人众·役人', 'Elite', '精英', '愚人众当中精锐的特务，有着不凡的身手与不渝的意志。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (102, 26290101, 80, '炉壳山鼬', 'Elite', '精英', '因生活在与外界隔绝的特殊燃素环境之内，而拥有特殊形态的古代种山鼬。有龙遗物研究协会的学者认为，虽然它看上去是和秘源机关互相依存，但说不定其实是秘源机关借由它浑身充斥的燃素持续控制着它。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (103, 20040301, 13, '无相之岩', 'Boss', '首领', '代号为「基末尔」的高级岩元素生命。\\n无相元素本身是超浓缩的构造体，拥有极高的质量。\\n浓缩成硬质固体的元素超质壳是惰性的，只有内部的核会活跃发生元素反应。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (104, 24060401, 54, '发条机关', 'Common', '普通', '得益于工程技术的进步与枫丹独有的动力源，而存在的人造机械。\\n同时也是歹人盗匪的好帮手。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (105, 21030401, 19, '丘丘萨满', 'Common', '普通', '丘丘人当中的萨满祭司。能在一定程度上求得元素的帮助。\\n「面具的造型设计有着恫吓敌人的意味，但反而让它们看起来有些亲切。」——雅各布·马斯克', '');
INSERT INTO `genshin_enemy_investigation` VALUES (106, 20011401, 20, '史莱姆', 'Common', '普通', '圆滚滚的元素生物。\\n据说，不同元素属性的史莱姆做成的甜品，会有各不相同的奇妙风味。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (107, 20060201, 34, '飘浮灵', 'Common', '普通', '高浓度的元素孕育而生的魔物，能够飘浮在空中。\\n总体而言，是性情相对温和，近似史莱姆的小小生灵，但在愤怒的状态下也会爆发。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (108, 26040101, 24, '岩龙蜥', 'Elite', '精英', '成熟的岩之龙蜥。\\n据称，幼岩龙蜥历经漫长岁月的积累后，会蜕去原本保护自己的装甲，成为「岩龙蜥」。但这两者，以及更古老、更伟大的「古岩龙蜥」，在过去的许多年中都蛰伏在山下，直到近期才开始活动。因此这种说法没有第一手观测记录证明。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (109, 26030101, 16, '幼岩龙蜥', 'Elite', '精英', '有着坚硬岩质甲壳的小型龙蜥。\\n行动非常灵活，是不容小觑的对手。须弥教令院的研究认为，即使是这种幼兽，也有成为「龙」的潜质。假以时日，如果不受天灾与敌害，或许也有一天能成为撼动高山的巨大魔物吧。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (110, 20080101, 82, '霜夜灵嗣', 'Elite', '精英', '体态瑰美优雅的元素生命。\\n它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。在漫长的岁月中沐染着高浓度的元素力，最终演化成了如今的形貌。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (111, 26220301, 68, '贪食匿叶龙山王', 'Boss', '首领', '自古老的年代存活至今，经历了无数战场的强大匿叶龙。因贪食而成就了现在相当庞硕的体态。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (112, 22060101, 36, '黄金王兽', 'Boss', '首领', '来自异界的扭曲魔兽。\\n统领兽境群狼的王者，拥有指挥狼群溶解空间的权威。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (113, 26230301, 69, '金焰绒翼龙暴君', 'Boss', '首领', '承受了特殊伟力的异种绒翼龙，在战斗中会展露出燃烧着金色火焰的昂然姿态。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (114, 26120401, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (115, 26120301, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (116, 26154101, 55, '原海异种', 'Common', '普通', '遍布枫丹的水生动物。\\n出于自然环境的缘故，似乎只能在枫丹生长。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (117, 21010101, 18, '丘丘人', 'Common', '普通', '遍布大陆，有着最基础文明形态的人形魔物。\\n如今，大部分人已经放弃了与丘丘人沟通的尝试，认为它们只是纯粹的、不通言语的魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (118, 21010701, 18, '丘丘人', 'Common', '普通', '遍布大陆，有着最基础文明形态的人形魔物。\\n如今，大部分人已经放弃了与丘丘人沟通的尝试，认为它们只是纯粹的、不通言语的魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (119, 21010201, 18, '丘丘人', 'Common', '普通', '遍布大陆，有着最基础文明形态的人形魔物。\\n如今，大部分人已经放弃了与丘丘人沟通的尝试，认为它们只是纯粹的、不通言语的魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (120, 21010601, 18, '丘丘人', 'Common', '普通', '遍布大陆，有着最基础文明形态的人形魔物。\\n如今，大部分人已经放弃了与丘丘人沟通的尝试，认为它们只是纯粹的、不通言语的魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (121, 21010401, 17, '丘丘射手', 'Common', '普通', '操作弩进行远程攻击的丘丘人。\\n丘丘人的智能水平连学会弩机的操控方式都有困难，遑论生产这种需要精密加工的设备了。由此，或许可以认为，看似漫无目的地散布在大陆各处的丘丘人背后，或许有着为它们提供装备与训练的组织……', '');
INSERT INTO `genshin_enemy_investigation` VALUES (122, 26151001, 55, '原海异种', 'Common', '普通', '遍布枫丹的水生动物。\\n出于自然环境的缘故，似乎只能在枫丹生长。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (123, 22010301, 2, '深渊法师', 'Elite', '精英', '一定程度上能驾驭元素进行战斗的深渊魔物。\\n出于某种不为人知的缘由，深渊法师精通丘丘人的笨拙语言，能驾驭它们的心智。据说深渊法师略通如今几乎无人可解的失落古语，并利用这种语言的力量行使魔法…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (124, 21040201, 52, '丘丘游侠', 'Elite', '精英', '不属于任何部族与聚落的丘丘人流浪者，常在荒野中四处漫游。\\n有时也会在因缘的指引下帮助其他的丘丘人。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (125, 20040401, 32, '无相之水', 'Boss', '首领', '代号为「希伊」的高级水元素生命。\\n无相元素有强大的排异本能，会无情地驱逐试探它的人。\\n而这种行为背后的逻辑至今仍是谜团。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (126, 21030101, 19, '丘丘萨满', 'Common', '普通', '丘丘人当中的萨满祭司。能在一定程度上求得元素的帮助。\\n「面具的造型设计有着恫吓敌人的意味，但反而让它们看起来有些亲切。」——雅各布·马斯克', '');
INSERT INTO `genshin_enemy_investigation` VALUES (127, 20011001, 20, '史莱姆', 'Common', '普通', '圆滚滚的元素生物。\\n据说，不同元素属性的史莱姆做成的甜品，会有各不相同的奇妙风味。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (128, 20060101, 34, '飘浮灵', 'Common', '普通', '高浓度的元素孕育而生的魔物，能够飘浮在空中。\\n总体而言，是性情相对温和，近似史莱姆的小小生灵，但在愤怒的状态下也会爆发。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (129, 20051201, 63, '水形幻人', 'Boss', '首领', '由无数的水滴凝聚成的，初具人形的魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (130, 21011401, 18, '丘丘人', 'Common', '普通', '遍布大陆，有着最基础文明形态的人形魔物。\\n如今，大部分人已经放弃了与丘丘人沟通的尝试，认为它们只是纯粹的、不通言语的魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (131, 21020601, 4, '丘丘暴徒', 'Elite', '精英', '丘丘人的部落当中，百里挑一的强壮勇士。\\n对于丘丘人而言，最重要的事情就是吃肉和打架，让身体变得强壮。如果能成为丘丘暴徒这样又大又壮的战士，就能吃更多肉、打更多架了。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (132, 24070301, 58, '「冰风组曲」', 'Boss', '首领', '来自枫丹科学院的献礼，分为「歌裴莉娅的葬送」与「科培琉司的劫罚」二曲。\\n\\n<color=#F39000FF>挑战前对话的选项将决定挑战与奖励的属性。</color>', '');
INSERT INTO `genshin_enemy_investigation` VALUES (133, 20080401, 82, '霜夜灵嗣', 'Elite', '精英', '体态瑰美优雅的元素生命。\\n它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。在漫长的岁月中沐染着高浓度的元素力，最终演化成了如今的形貌。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (134, 26240201, 70, '纳塔龙众', 'Common', '普通', '纳塔的龙。\\n传说中更为远古的龙拥有更强的环境适应度，于是在不同的环境幻化出了不同的姿态与形体。而今纳塔的龙众，据说是那时候龙丧失了力量后，为了生存，不得不更加依赖环境后，固定下来的形态。\\n但没人知道这个说法的真假。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (135, 26240101, 70, '纳塔龙众', 'Common', '普通', '纳塔的龙。\\n传说中更为远古的龙拥有更强的环境适应度，于是在不同的环境幻化出了不同的姿态与形体。而今纳塔的龙众，据说是那时候龙丧失了力量后，为了生存，不得不更加依赖环境后，固定下来的形态。\\n但没人知道这个说法的真假。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (136, 25511001, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (137, 25510901, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (138, 22100501, 53, '深罪浸礼者', 'Boss', '首领', '因为深渊的力量取得「进化」而获得了多余的肢体的深渊魔物。\\n能够驱役多种元素的力量。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (139, 26110101, 42, '翠翎恐蕈', 'Boss', '首领', '深居林间菌族拥簇之中的蕈兽之王。\\n只要有雨露与肥沃的土地，蕈兽就会生长。只要存在逆境，菌类就会适应。只要存在伸展的空间，孢子就会在天地间散布。假以时日，这种如同高傲鸟兽的蕈兽还能进化成更加伟大的形态吧。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (140, 25100101, 29, '野伏众', 'Common', '普通', '虽然常被称为「野伏众」，但这些贼匪并没有统一的团体。有时也会根据犯行的性质与其人的气质，被称为「无宿」、「浮浪」、「海乱鬼」、「无赖汉」、「一揆众」，或者更加直截了当的「流寇」。\\n他们通常是落草为寇的武人、逐电的士兵之流，其中有的人为了生计与财富，甚至会与盗宝团、愚人众沆瀣一气。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (141, 25100201, 29, '野伏众', 'Common', '普通', '虽然常被称为「野伏众」，但这些贼匪并没有统一的团体。有时也会根据犯行的性质与其人的气质，被称为「无宿」、「浮浪」、「海乱鬼」、「无赖汉」、「一揆众」，或者更加直截了当的「流寇」。\\n他们通常是落草为寇的武人、逐电的士兵之流，其中有的人为了生计与财富，甚至会与盗宝团、愚人众沆瀣一气。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (142, 24100101, 87, '重拳出击鸭', 'Boss', '首领', '造型奇特的月矩力机关。\\n由废弃的金属与机关轴承拼接而成，似乎是因为制造者的偏好而被部分赋予了「鸭子」的外观特征。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (143, 26210201, 70, '纳塔龙众', 'Common', '普通', '纳塔的龙。\\n传说中更为远古的龙拥有更强的环境适应度，于是在不同的环境幻化出了不同的姿态与形体。而今纳塔的龙众，据说是那时候龙丧失了力量后，为了生存，不得不更加依赖环境后，固定下来的形态。\\n但没人知道这个说法的真假。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (144, 25510601, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (145, 25510501, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
