INSERT INTO `genshin_enemy_investigation` VALUES (147, 20010401, 20, '史莱姆', 'Common', '普通', '圆滚滚的元素生物。\\n据说，不同元素属性的史莱姆做成的甜品，会有各不相同的奇妙风味。', '');
