INSERT INTO `genshin_enemy_investigation` VALUES (153, 22110301, 57, '隙境原体', 'Elite', '精英', '神秘的异形生命体。\\n与提瓦特的任何生物都没有共性。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (154, 20011301, 20, '史莱姆', 'Common', '普通', '圆滚滚的元素生物。\\n据说，不同元素属性的史莱姆做成的甜品，会有各不相同的奇妙风味。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (155, 22110101, 57, '隙境原体', 'Elite', '精英', '神秘的异形生命体。\\n与提瓦特的任何生物都没有共性。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (156, 26270301, 79, '熔岩辉龙像', 'Boss', '首领', '能够自身持续产生热量，以维持活动状态的魔物。\\n无法从纯粹的能量中诞生智慧，无知无觉，而徒具伟大种族形廓的失败品。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (157, 26140101, 66, '魔像督军', 'Boss', '首领', '白石与黄铜塑造的半人马巨像，坚硬的石质躯壳下流淌着灵露的血液。\\n手中的盾与剑能够弹奏出烈火的旋律。', '在水下城堡的陈列馆中，沉睡着曾寄托古人梦想的石像…');
INSERT INTO `genshin_enemy_investigation` VALUES (158, 22150101, 92, '深黯魇语之主', 'Boss', '首领', '伏行于深黯的裂隙，窥伺此世的深渊魔物。\\n据说那怪异、亵渎的无面形貌不过是投射于世界上的影像，其真实姿态乃是以纯粹深渊能量形式存在的无形之物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (159, 25090101, 26, '魔偶剑鬼', 'Boss', '首领', '自律的人形机关剑士。\\n据说在试作时，集成了某个以秘剑「天狗抄」闻名的剑道流派初代宗主的记忆，却又因为不明的原因而失控，最终被废弃了。\\n根据歌人的描述，剑鬼会徘徊在因缘断绝的地方。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (160, 26180101, 62, '千年珍珠骏麟', 'Boss', '首领', '蛰居在岩窟之中的古老原海异种王者。拥有幻兽般优美的身姿与雷霆般酷烈的脾性。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (161, 23050101, 30, '愚人众·冬国仕女', 'Elite', '精英', '来自极冬的国土，隶属于愚人众的特殊仪仗兵士。\\n与「仕女」之名所象征的端庄姿态相反，为了实现愚人众全体的宏大目标，无论什么事情都能做出来。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (162, 20010701, 20, '史莱姆', 'Common', '普通', '圆滚滚的元素生物。\\n据说，不同元素属性的史莱姆做成的甜品，会有各不相同的奇妙风味。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (163, 24068701, 54, '发条机关', 'Common', '普通', '得益于工程技术的进步与枫丹独有的动力源，而存在的人造机械。\\n同时也是歹人盗匪的好帮手。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (164, 25080201, 29, '野伏众', 'Common', '普通', '虽然常被称为「野伏众」，但这些贼匪并没有统一的团体。有时也会根据犯行的性质与其人的气质，被称为「无宿」、「浮浪」、「海乱鬼」、「无赖汉」、「一揆众」，或者更加直截了当的「流寇」。\\n他们通常是落草为寇的武人、逐电的士兵之流，其中有的人为了生计与财富，甚至会与盗宝团、愚人众沆瀣一气。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (165, 25080101, 29, '野伏众', 'Common', '普通', '虽然常被称为「野伏众」，但这些贼匪并没有统一的团体。有时也会根据犯行的性质与其人的气质，被称为「无宿」、「浮浪」、「海乱鬼」、「无赖汉」、「一揆众」，或者更加直截了当的「流寇」。\\n他们通常是落草为寇的武人、逐电的士兵之流，其中有的人为了生计与财富，甚至会与盗宝团、愚人众沆瀣一气。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (166, 25080301, 29, '野伏众', 'Common', '普通', '虽然常被称为「野伏众」，但这些贼匪并没有统一的团体。有时也会根据犯行的性质与其人的气质，被称为「无宿」、「浮浪」、「海乱鬼」、「无赖汉」、「一揆众」，或者更加直截了当的「流寇」。\\n他们通常是落草为寇的武人、逐电的士兵之流，其中有的人为了生计与财富，甚至会与盗宝团、愚人众沆瀣一气。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (167, 20050101, 14, '纯水精灵', 'Boss', '首领', '极纯的水元素凝结成的生命体。\\n常与水体相伴。据说，水体越纯净，其中的水元素越丰沛，纯水精灵的力量就越强。\\n又有传说认为，纯水精灵曾是来自异乡的水之亲眷。怀着已殁之神的碎片，流落到了世界各处，或许是为了让她们的神对世界的爱，循着水流广布大地…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (168, 23078101, 84, '愚人众特辖队', 'Common', '普通', '愚人众战争机器中的士兵。\\n不同于「先遣队」，「特辖队」是经过正式招募与长期训练的正规部队，他们往往会被部署在对于愚人众来说最为重要的据点，又或是被投入极凶险的正面战场。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (169, 23079101, 84, '愚人众特辖队', 'Common', '普通', '愚人众战争机器中的士兵。\\n不同于「先遣队」，「特辖队」是经过正式招募与长期训练的正规部队，他们往往会被部署在对于愚人众来说最为重要的据点，又或是被投入极凶险的正面战场。', '');
