INSERT INTO `genshin_enemy_investigation` VALUES (177, 22110401, 57, '隙境原体', 'Elite', '精英', '神秘的异形生命体。\\n与提瓦特的任何生物都没有共性。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (178, 24021101, 28, '恒常机关阵列', 'Boss', '首领', '诡谲的异形机械。\\n传说是已经覆灭的国度留下的战争机械。由若干部件构成，能够适应战斗的环境，施展各种攻击手段。\\n由立方体构成的形态在某个层面而言，与所谓的「无相元素」有着相似点。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (179, 26140201, 67, '魔像禁卫', 'Elite', '精英', '战士姿态的活动雕像，会将剑刃指向任何胆敢侵入其所守护之地的人。\\n坚硬躯壳之下的存在或许早已迷失于往日的追忆之中。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (180, 24040301, 48, '元能构装体', 'Elite', '精英', '失落在荒漠中的古老遗迹的守护者，其力量足以惩罚一切敢于惊扰君王清梦之人。\\n传说沙海的主人曾做过一个关于「永恒乐园」的梦。如今「乐园」早已湮灭，只有蚀刻在这些机械上的咒文还记录着那些已被世人忘却的梦想与承诺。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (181, 24040101, 48, '元能构装体', 'Elite', '精英', '失落在荒漠中的古老遗迹的守护者，其力量足以惩罚一切敢于惊扰君王清梦之人。\\n传说沙海的主人曾做过一个关于「永恒乐园」的梦。如今「乐园」早已湮灭，只有蚀刻在这些机械上的咒文还记录着那些已被世人忘却的梦想与承诺。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (182, 24040201, 48, '元能构装体', 'Elite', '精英', '失落在荒漠中的古老遗迹的守护者，其力量足以惩罚一切敢于惊扰君王清梦之人。\\n传说沙海的主人曾做过一个关于「永恒乐园」的梦。如今「乐园」早已湮灭，只有蚀刻在这些机械上的咒文还记录着那些已被世人忘却的梦想与承诺。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (183, 26050101, 23, '古岩龙蜥', 'Boss', '首领', '经历了长久岁月，拥有伟大力量的巨大岩龙蜥，能够适应元素环境的异变。\\n根据民话，导致天遒谷毁灭的「龙灾」发生后，岩龙蜥与古岩龙蜥们沉入大地之中，等待着复起的时机…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (184, 26050601, 38, '深海龙蜥', 'Elite', '精英', '在深海里居住的龙蜥族群。\\n它们讨厌光的主要原因并不是视觉系统过于脆弱。不如与之相反，正因为失去了地表，无私的日光被夺走了，它们才不愿意看到人造的光芒。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (185, 22010101, 2, '深渊法师', 'Elite', '精英', '一定程度上能驾驭元素进行战斗的深渊魔物。\\n出于某种不为人知的缘由，深渊法师精通丘丘人的笨拙语言，能驾驭它们的心智。据说深渊法师略通如今几乎无人可解的失落古语，并利用这种语言的力量行使魔法…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (186, 21010501, 17, '丘丘射手', 'Common', '普通', '操作弩进行远程攻击的丘丘人。\\n丘丘人的智能水平连学会弩机的操控方式都有困难，遑论生产这种需要精密加工的设备了。由此，或许可以认为，看似漫无目的地散布在大陆各处的丘丘人背后，或许有着为它们提供装备与训练的组织……', '');
INSERT INTO `genshin_enemy_investigation` VALUES (187, 20040601, 27, '无相之火', 'Boss', '首领', '代号为「亚因」的高级火元素生命。\\n无相元素被破坏之前，通常而言，会进入某种近似「紧急再启动」的状态，并通过这种方式恢复能量。这种急速再生的能力，是连以生存为究极目的的大部分生物都不具备的。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (188, 26020201, 15, '爆炎树', 'Boss', '首领', '吸收了地脉中奔涌的古老烈焰的巨大藤蔓。\\n如同充满怒火一般，永不止息的植物。\\n诗人、歌手乃至一些学者认为「元素」中蕴含着情感和愿望。如果属实，又是什么情感与愿望驱使着爆炎树恒常燃烧，如同渴求着挣脱大地的束缚一般挣扎舞动呢…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (189, 20011201, 20, '史莱姆', 'Common', '普通', '圆滚滚的元素生物。\\n据说，不同元素属性的史莱姆做成的甜品，会有各不相同的奇妙风味。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (190, 20060601, 34, '飘浮灵', 'Common', '普通', '高浓度的元素孕育而生的魔物，能够飘浮在空中。\\n总体而言，是性情相对温和，近似史莱姆的小小生灵，但在愤怒的状态下也会爆发。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (191, 26010201, 12, '骗骗花', 'Common', '普通', '古灵精怪的拟态植物魔物，会用元素战斗。\\n有时会隐藏在地表下，捕猎浑然不觉的猎物。如果有足够的年月、养分与环境，或许能扎根某处，长成巨大的、摇曳着喷吐魔力的树…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (192, 26230201, 70, '纳塔龙众', 'Common', '普通', '纳塔的龙。\\n传说中更为远古的龙拥有更强的环境适应度，于是在不同的环境幻化出了不同的姿态与形体。而今纳塔的龙众，据说是那时候龙丧失了力量后，为了生存，不得不更加依赖环境后，固定下来的形态。\\n但没人知道这个说法的真假。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (193, 26230101, 70, '纳塔龙众', 'Common', '普通', '纳塔的龙。\\n传说中更为远古的龙拥有更强的环境适应度，于是在不同的环境幻化出了不同的姿态与形体。而今纳塔的龙众，据说是那时候龙丧失了力量后，为了生存，不得不更加依赖环境后，固定下来的形态。\\n但没人知道这个说法的真假。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (194, 25510701, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (195, 26300101, 86, '蕴光异兽', 'Elite', '精英', '长久浸浴古老月之力而演化出独特生态的魔兽。\\n原本只是普通的生物，却因为月矩力的影响而获得了特殊的力量。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (196, 26300201, 86, '蕴光异兽', 'Elite', '精英', '长久浸浴古老月之力而演化出独特生态的魔兽。\\n原本只是普通的生物，却因为月矩力的影响而获得了特殊的力量。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (197, 26300301, 86, '蕴光异兽', 'Elite', '精英', '长久浸浴古老月之力而演化出独特生态的魔兽。\\n原本只是普通的生物，却因为月矩力的影响而获得了特殊的力量。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (198, 26301101, 88, '蕴光月幻蝶', 'Boss', '首领', '于月光下翩然起舞的蝶形魔物。\\n月光的恩赐令其能以强盛时的姿态漫行于世，向众人展现古老月亮曾照映的旧世界的残余。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (199, 26302101, 93, '蕴光月守宫', 'Boss', '首领', '眷恋月光的古老魔物，在岩层深处栖息的守宫。\\n即便已逐渐忘却了真正的月光，本能依旧驱使着它们在满月之时啃食被月辉浸浴的岩土以维持血脉。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (200, 24068101, 54, '发条机关', 'Common', '普通', '得益于工程技术的进步与枫丹独有的动力源，而存在的人造机械。\\n同时也是歹人盗匪的好帮手。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (201, 26050701, 37, '深海龙蜥之群', 'Boss', '首领', '强大的深海龙蜥之群。\\n它们的强大源自渊下宫之民的培育和筛选。自然，必定不会有龙蜥会认为这是恩情。\\n这一支族群里最强大者会操持着不同的元素，向着来者宣泄它们的愤怒。', '海渊的深处，它们在阴影中等待着捕猎之时…');
INSERT INTO `genshin_enemy_investigation` VALUES (202, 26260101, 72, '大灵显化身', 'Elite', '精英', '纳塔各个部族所信仰的「大灵」借由黑曜石图腾的形象如斯显化。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (203, 22050101, 35, '兽境之狼', 'Elite', '精英', '黯色的不祥异兽，会如狼群一般行动。\\n据说有溶解边界的力量。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (204, 22040101, 35, '兽境之狼', 'Elite', '精英', '黯色的不祥异兽，会如狼群一般行动。\\n据说有溶解边界的力量。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (205, 21011201, 18, '丘丘人', 'Common', '普通', '遍布大陆，有着最基础文明形态的人形魔物。\\n如今，大部分人已经放弃了与丘丘人沟通的尝试，认为它们只是纯粹的、不通言语的魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (206, 21020301, 4, '丘丘暴徒', 'Elite', '精英', '丘丘人的部落当中，百里挑一的强壮勇士。\\n对于丘丘人而言，最重要的事情就是吃肉和打架，让身体变得强壮。如果能成为丘丘暴徒这样又大又壮的战士，就能吃更多肉、打更多架了。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (207, 24020101, 31, '遗迹机兵', 'Elite', '精英', '各种为了适应不同的目标，有着定制化外形与机能的异形机械。\\n传说是已经覆灭的国度留下的战争机械。且不论坚硬的装甲与强大的性能，有人认为这种遗迹机关的设计相比更为广泛存在的「遗迹守卫」，在设计上有更强的仿生学意义。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (208, 24020301, 31, '遗迹机兵', 'Elite', '精英', '各种为了适应不同的目标，有着定制化外形与机能的异形机械。\\n传说是已经覆灭的国度留下的战争机械。且不论坚硬的装甲与强大的性能，有人认为这种遗迹机关的设计相比更为广泛存在的「遗迹守卫」，在设计上有更强的仿生学意义。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (209, 24020201, 31, '遗迹机兵', 'Elite', '精英', '各种为了适应不同的目标，有着定制化外形与机能的异形机械。\\n传说是已经覆灭的国度留下的战争机械。且不论坚硬的装甲与强大的性能，有人认为这种遗迹机关的设计相比更为广泛存在的「遗迹守卫」，在设计上有更强的仿生学意义。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (210, 24030201, 43, '遗迹龙兽', 'Elite', '精英', '传说是已经覆灭的国度留下的，依照古老的「龙蜥」制成的战争机械。\\n相比真正的生物，进行了结构与性能的优化。似乎是为了增幅龙蜥这种原始生命所具有的「吸收」，抑或是说「反制」元素的能力，而对其能源系统进行了特殊设计。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (211, 24030101, 43, '遗迹龙兽', 'Elite', '精英', '传说是已经覆灭的国度留下的，依照古老的「龙蜥」制成的战争机械。\\n相比真正的生物，进行了结构与性能的优化。似乎是为了增幅龙蜥这种原始生命所具有的「吸收」，抑或是说「反制」元素的能力，而对其能源系统进行了特殊设计。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (212, 24010301, 3, '遗迹守卫', 'Elite', '精英', '古老的人形战斗机械。\\n传说是已经覆灭的国度留下的战争机械，但也有人认为，这款机器开发的目的不是为了战斗，而是为了守护过去留下的遗迹。\\n虽然这无法解释，为何它们会在理应守护的遗迹中，使用爆炸性的火力攻击就是了…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (213, 24010101, 3, '遗迹守卫', 'Elite', '精英', '古老的人形战斗机械。\\n传说是已经覆灭的国度留下的战争机械，但也有人认为，这款机器开发的目的不是为了战斗，而是为了守护过去留下的遗迹。\\n虽然这无法解释，为何它们会在理应守护的遗迹中，使用爆炸性的火力攻击就是了…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (214, 24010201, 11, '遗迹猎者', 'Elite', '精英', '巨大的异形战斗机械。\\n传说是已经覆灭的国度留下的战争机械。似乎是为了提高战斗性能，设计上放弃了低效的拟人形态。无论是白刃战还是远程炮火的威力都相当恐怖。\\n仅仅是废弃的古代兵器就有如此能力，曾经能生产这种兵器的文明又是如何呢…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (215, 24020401, 31, '遗迹机兵', 'Elite', '精英', '各种为了适应不同的目标，有着定制化外形与机能的异形机械。\\n传说是已经覆灭的国度留下的战争机械。且不论坚硬的装甲与强大的性能，有人认为这种遗迹机关的设计相比更为广泛存在的「遗迹守卫」，在设计上有更强的仿生学意义。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (216, 24010401, 39, '遗迹巨蛇', 'Boss', '首领', '踞身层岩巨渊地下的异形机关。\\n拥有能够轻易挖开岩石的坚硬齿盘。似乎也是通过这种能力，从「何处」打通了前往层岩巨渊的黯道。', '从层岩巨渊的地下深处，似乎传来了阵阵细微的、机械的律动…');
INSERT INTO `genshin_enemy_investigation` VALUES (217, 24090201, 76, '秘源机兵·构型械', 'Boss', '首领', '古老的制造用机械体。\\n据说是已经失落的古代文明生产的工作用机械，既作为工具也作为武器使用，所以比起一般的秘源机兵来说，更具有威胁性。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (218, 24090101, 74, '秘源机兵·寻捕械', 'Elite', '精英', '古老的采集用机械体。\\n据说是已经失落的古代文明生产的工作用机械，也就是说，战斗原本并非它的职责。但即使如此，失控的采集机械也会造成极大的麻烦。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (219, 24090501, 81, '秘源机兵·统御械', 'Boss', '首领', '深古遗迹的统御用机关。\\n曾经，一度伟大的古老种族借由这种机关来统御城市的运转，即使在旧日文明崩毁的现在，也依然拥有着极高的权能。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (220, 26130101, 50, '风蚀沙虫', 'Boss', '首领', '生活在沙海深处的无目掠食者，会依据声音与大地的震动寻找猎物的踪迹。\\n有时会展现出与植物相近的形态，据说这是因为它们曾是草木主宰所诞下的子嗣，也有说法认为这是为了欺瞒在沙海中寻觅果与叶的猎物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (221, 22070301, 40, '黑蛇众', 'Elite', '精英', '曾经似乎是具有相当身份的王国骑士。\\n如今似乎随着岁月与诅咒，失去了几乎全部的智性与记忆，只有「为了何事、何人、何物而战」的意志还残留在铠甲当中吧。\\n依据损耗的程度，分别被称为「黯色空壳」与「黑蛇骑士」。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (222, 22070201, 40, '黑蛇众', 'Elite', '精英', '曾经似乎是具有相当身份的王国骑士。\\n如今似乎随着岁月与诅咒，失去了几乎全部的智性与记忆，只有「为了何事、何人、何物而战」的意志还残留在铠甲当中吧。\\n依据损耗的程度，分别被称为「黯色空壳」与「黑蛇骑士」。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (223, 22070101, 40, '黑蛇众', 'Elite', '精英', '曾经似乎是具有相当身份的王国骑士。\\n如今似乎随着岁月与诅咒，失去了几乎全部的智性与记忆，只有「为了何事、何人、何物而战」的意志还残留在铠甲当中吧。\\n依据损耗的程度，分别被称为「黯色空壳」与「黑蛇骑士」。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (224, 22110201, 57, '隙境原体', 'Elite', '精英', '神秘的异形生命体。\\n与提瓦特的任何生物都没有共性。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (225, 26190101, 64, '隐山猊兽', 'Boss', '首领', '时常被人们认为只存在于幻想的仙兽，优雅的身姿与孤傲的性情是其特征。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (226, 25503201, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (227, 25501401, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (228, 25502301, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (229, 26160101, 55, '原海异种', 'Common', '普通', '遍布枫丹的水生动物。\\n出于自然环境的缘故，似乎只能在枫丹生长。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (230, 21020501, 22, '丘丘王', 'Elite', '精英', '体内积聚了大量的元素，发生了变异的丘丘暴徒。更大、更壮、更凶悍。\\n丘丘人的文明中没有神，也没有秩序。只要够强壮，打架够狠，就能成为它们的王者。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (231, 26090801, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (232, 26091001, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (233, 26090901, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (234, 26090701, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (235, 23090101, 90, '超重型陆巡舰·机动战垒', 'Boss', '首领', '军械宫与月矩力试验设计局合作研发的超重型机关，在内部文件中被称作德兹斯拉沃型。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (236, 24068901, 54, '发条机关', 'Common', '普通', '得益于工程技术的进步与枫丹独有的动力源，而存在的人造机械。\\n同时也是歹人盗匪的好帮手。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (237, 25503101, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (238, 25501201, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (239, 25502101, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (240, 20051001, 56, '浊水幻灵', 'Elite', '精英', '取代形姿优美的纯水精灵，从枫丹的水上升起的元素生命体。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (241, 20051101, 56, '浊水幻灵', 'Elite', '精英', '取代形姿优美的纯水精灵，从枫丹的水上升起的元素生命体。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (242, 20080201, 82, '霜夜灵嗣', 'Elite', '精英', '体态瑰美优雅的元素生命。\\n它们是受霜月祝福而诞生的生命，象征着纯然的源质与肇始的辉光。在漫长的岁月中沐染着高浓度的元素力，最终演化成了如今的形貌。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (243, 22120101, 77, '深邃摹结株', 'Boss', '首领', '如植株般侵蚀生长的深渊魔物。\\n持续侵蚀此界的扭曲者，能够提取大地之中相对深层的记忆，亦能通过深渊的力量复现更为强大的记忆体。如果放任此物持续侵蚀提瓦特的话，或许连最为远古的记忆都能够以扭曲污秽的方式摹写而出吧。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (244, 26200201, 70, '纳塔龙众', 'Common', '普通', '纳塔的龙。\\n传说中更为远古的龙拥有更强的环境适应度，于是在不同的环境幻化出了不同的姿态与形体。而今纳塔的龙众，据说是那时候龙丧失了力量后，为了生存，不得不更加依赖环境后，固定下来的形态。\\n但没人知道这个说法的真假。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (245, 25510201, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (246, 25510101, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (247, 26200101, 70, '纳塔龙众', 'Common', '普通', '纳塔的龙。\\n传说中更为远古的龙拥有更强的环境适应度，于是在不同的环境幻化出了不同的姿态与形体。而今纳塔的龙众，据说是那时候龙丧失了力量后，为了生存，不得不更加依赖环境后，固定下来的形态。\\n但没人知道这个说法的真假。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (248, 22050201, 35, '兽境之狼', 'Elite', '精英', '黯色的不祥异兽，会如狼群一般行动。\\n据说有溶解边界的力量。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (249, 22040201, 35, '兽境之狼', 'Elite', '精英', '黯色的不祥异兽，会如狼群一般行动。\\n据说有溶解边界的力量。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (250, 21020801, 22, '丘丘王', 'Elite', '精英', '体内积聚了大量的元素，发生了变异的丘丘暴徒。更大、更壮、更凶悍。\\n丘丘人的文明中没有神，也没有秩序。只要够强壮，打架够狠，就能成为它们的王者。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (251, 20070101, 33, '雷音权现', 'Boss', '首领', '异常的雷元素生命，以电光与霆雷高唱驱使它行动的忿恨。\\n虽然形象上与「纯水精灵」有着某种程度上的相似之处，但似乎并不具备纯水精灵的智慧。\\n传说是由纯粹的悔恨驱使的元素魔物。', '天云峠的风暴中，传来了愤怒的雷鸣…');
INSERT INTO `genshin_enemy_investigation` VALUES (252, 25070101, 21, '盗宝团', 'Common', '普通', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织。\\n虽然主要的活动是收集宝藏，但也会出手撵走倒霉的目击者。\\n据说创始人雷德·米勒将盗宝团定义为「互助协调组织」…？', '');
INSERT INTO `genshin_enemy_investigation` VALUES (253, 25010601, 21, '盗宝团', 'Common', '普通', '足迹遍布大陆各处，甚至深入未知秘境的松散盗贼组织。\\n虽然主要的活动是收集宝藏，但也会出手撵走倒霉的目击者。\\n据说创始人雷德·米勒将盗宝团定义为「互助协调组织」…？', '');
