INSERT INTO `genshin_enemy_investigation` VALUES (263, 24068501, 54, '发条机关', 'Common', '普通', '得益于工程技术的进步与枫丹独有的动力源，而存在的人造机械。\\n同时也是歹人盗匪的好帮手。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (264, 24068301, 54, '发条机关', 'Common', '普通', '得益于工程技术的进步与枫丹独有的动力源，而存在的人造机械。\\n同时也是歹人盗匪的好帮手。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (265, 24111101, 94, '守望者·堕天', 'Boss', '首领', '原初的大能者流溢而出的影之造物，曾居于高天之上的守望者，终因开眼而堕入尘世。\\n守望者不知晓那位离去的主人因何离去，唯有永恒的惩罚依然驻留在凝滞的隙间…', '');
INSERT INTO `genshin_enemy_investigation` VALUES (266, 25520101, 78, '灵觉隐修的迷者', 'Boss', '首领', '离群索居的「烟谜主」祭司，拥有比寻常祭司或萨满更为强大的「灵觉」的力量。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (267, 26090501, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
