INSERT INTO `genshin_enemy_investigation` VALUES (270, 22130001, 83, '荒野狂猎', 'Elite', '精英', '徘徊在荒原冻土上的幽魂。\\n总是与漆黑的迷雾相伴随，据说他们的出现预兆着更为可怕的灾难。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (271, 22131001, 83, '荒野狂猎', 'Elite', '精英', '徘徊在荒原冻土上的幽魂。\\n总是与漆黑的迷雾相伴随，据说他们的出现预兆着更为可怕的灾难。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (272, 23060201, 60, '愚人众·役人', 'Elite', '精英', '愚人众当中精锐的特务，有着不凡的身手与不渝的意志。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (273, 26120201, 45, '蕈兽', 'Common', '普通', '一言以蔽之的话，就是过度成长、过度进化的孢子。\\n<color=#F39000FF>在遇到火元素或雷元素后，会转化成「枯焦」或「活化」状态，并且在这个状态下能产生特别的素材。</color>\\n据说蕈兽的广布来自实验事故。最初须弥的贤人期冀将孢子一些特性运用在救死扶伤上。若果真如此，此人显然低估了孢子的环境适应力与传播能力。', '');
