INSERT INTO `genshin_enemy_investigation` VALUES (275, 21010301, 18, '丘丘人', 'Common', '普通', '遍布大陆，有着最基础文明形态的人形魔物。\\n如今，大部分人已经放弃了与丘丘人沟通的尝试，认为它们只是纯粹的、不通言语的魔物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (276, 21020101, 4, '丘丘暴徒', 'Elite', '精英', '丘丘人的部落当中，百里挑一的强壮勇士。\\n对于丘丘人而言，最重要的事情就是吃肉和打架，让身体变得强壮。如果能成为丘丘暴徒这样又大又壮的战士，就能吃更多肉、打更多架了。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (277, 26190201, 65, '玄文兽', 'Elite', '精英', '伏行于山野间的猛兽，能驱使风元素力驰逐猎物。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (278, 26220201, 70, '纳塔龙众', 'Common', '普通', '纳塔的龙。\\n传说中更为远古的龙拥有更强的环境适应度，于是在不同的环境幻化出了不同的姿态与形体。而今纳塔的龙众，据说是那时候龙丧失了力量后，为了生存，不得不更加依赖环境后，固定下来的形态。\\n但没人知道这个说法的真假。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (279, 25510401, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (280, 25510301, 71, '部族龙形武士', 'Common', '普通', '纳塔六大部族的勇士，为了各自部族的荣耀与光辉而征战。\\n与龙同行的部族战士，在与龙一同生活和战斗的漫长岁月中，逐渐习得了龙的特性并将之应用在了战场之上。', '');
INSERT INTO `genshin_enemy_investigation` VALUES (281, 26220101, 70, '纳塔龙众', 'Common', '普通', '纳塔的龙。\\n传说中更为远古的龙拥有更强的环境适应度，于是在不同的环境幻化出了不同的姿态与形体。而今纳塔的龙众，据说是那时候龙丧失了力量后，为了生存，不得不更加依赖环境后，固定下来的形态。\\n但没人知道这个说法的真假。', '');
