INSERT INTO `geographies` VALUES (70100001, '守护神像的湖泽', 1103, '星落湖', '曾有诗歌说：星辰坠入此间大地，造就了湖泽。但也有其他的诗歌说，就连星辰也会为这如同风神的明眸般清澈的景象倾倒，落入湖中。', 1, '蒙德', 0, 2, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70100002, '风之城', 1102, '蒙德城', '风会将蒲公英的种子、诗歌与故事带到远方，也会将温柔的旅人带到自己的国度。欢迎来到蒙德。', 1, '蒙德', 0, 1, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70100003, '西风骑士团·图书馆', 1102, '蒙德城', '北大陆藏书数目最多的图书馆。除「禁书区」的书籍外，所有馆藏皆可供公众自由阅览。', 1, '蒙德', 0, 7, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70100004, '西风大教堂', 1102, '蒙德城', '由风神的虔诚信徒经营的宏伟圣堂。\r\n过去曾是贵族炫耀权威的大殿。', 1, '蒙德', 0, 6, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70100005, '风洗的原野', 1201, '风起地', '永不止歇的细风洗濯着这片原野。昔日的英雄留下的挺拔巨木在风中轻轻吟籁。', 1, '蒙德', 0, 3, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70100006, '未名的剑冢', 1203, '达达乌帕谷', '数百年过去了，天地已经归复平和。如林的剑冢静静铭记着，过去钢铁交错编织的诗篇，战士吟唱的歌谣，妖物如雷撼动大地的步伐，如同鲜烈的血一般赤红的天空。', 1, '蒙德', 0, 9, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70100007, '清泉静流之地', 1301, '清泉镇', '宁静祥和的城郊小镇。有着悠久的猎人传统、清澈甘甜的泉水，以及水源中寄寓着某种良善精灵的传说。', 1, '蒙德', 0, 4, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70100008, '曙光初照的庄园', 1302, '晨曦酒庄', '弥漫着葡萄的芬芳与醇厚的酒香，蒙德酒业望族的庄园宅邸。以难以望其项背的佳酿征服了蒙德的酒客，某种意义上是贪恋杯中物之人不得不巡礼的圣地。', 1, '蒙德', 0, 5, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70100009, '悠古的千风神殿', 1107, '千风神殿', '环形剧场的古遗迹。悠扬的千风曾经汇集此地，带来无数故事，也让无数故事乘风去往远方。', 1, '蒙德', 0, 8, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70100010, '风啸的古代废都', 1401, '风龙废墟', '独踞高塔者已经不再。盘旋废都的风低啸着无人可知的最古之事：它过去的主人、风中无名的精灵、以及撼动尖塔的群唱…', 1, '蒙德', 0, 10, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200001, '远眺高车之所', 2504, '望舒客栈', '端坐荻花洲南端的客栈，似乎也承担着客栈以外的使命。据说望舒客栈的楼阁是恋人共约赏月的胜地。坊间有传说道，纵然贵为仙人者，偶尔也会在此沐浴清冷的月光…', 2, '璃月', 0, 105, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200002, '轻策山间', 2507, '轻策庄', '高大的轻策山慈悲地怀抱着安乐无虞的村庄，静静守护着其中的老者、孩童与丰饶的田地。而山下镇压着古老妖异的传说早已同讲述者一齐老去，亦不复归。', 2, '璃月', 0, 108, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200003, '水泽荻原', 2503, '荻花洲', '此间是沙沙作响的荻草与蛙声和鸣之地，也是古代无数侠客最后的安息之所。', 2, '璃月', 0, 106, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200004, '千峰绝云之间', 2601, '绝云间', '传说仙家寄寓此间千百石峰与翻腾云霭之间。是凡骨之躯难以企及的地方。', 2, '璃月', 0, 109, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200005, '雾海中的石林', 2602, '华光林', '云中有如亭阁般耸立的石峰。纵使知晓此间绝非凡人应当涉足之地，这样的华光雾海也会有如漩涡一般，吸引着憧憬天空、憧憬仙居之人吧。', 2, '璃月', 0, 111, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200006, '沐浴月光之树', 2605, '南天门', '枝头流淌着清冷的月光的奇树。深入地心的根系末端，是否又连结着某种等待着再次沐浴月光的悠古之物呢…', 2, '璃月', 0, 110, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200007, '归离城墟', 2505, '归离原', '曾经盛开着某种花卉的繁华城集。但美梦最终醒转，乐土终究毁于乱世，归人复离。', 2, '璃月', 0, 107, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200008, '盈泪的故园', 2509, '渌华池', '传说是深情清澈的相思盈满了旧日的园圃，造就了渌华池如今的景象。', 2, '璃月', 0, 112, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200009, '靖世九柱', 2607, '翠玦坡', '浅眠在翠玦坡的山谷深处的，传说祓除妖异、靖却世间邪妄的九柱石锁。', 2, '璃月', 0, 117, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200010, '青墟孤楼', 2803, '青墟浦', '矗立在青潭之间的荒废城楼。如今依旧守护着早已化为土灰的高傲过往。', 2, '璃月', 0, 116, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200011, '遁玉古陵', 2801, '遁玉陵', '「美玉遁藏之地」。但昔日发生在此地的战争早已结束，因玉而辉的古陵早已毁灭。如今只有流水之声陌陌低语。', 2, '璃月', 0, 115, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200012, '层岩巨渊外', 2200, '层岩巨渊', '连接璃月港与名为层岩巨渊的巨大矿坑的中转站，近来因为层岩巨渊深处的某种变故而停止运作。', 2, '璃月', 0, 114, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200013, '千船万商云集之地', 2701, '璃月港', '千帆汇集的繁荣海港。在无数契约规约之下，百货迭出，宝飨七国。欢迎来到璃月，遍行四方的旅人。', 2, '璃月', 0, 101, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200014, '玉京台', 2701, '璃月港', '远离嚣闹的港口，依着天衡山高高升起。「七星」与诸商会的首脑，在此驱动着璃月驶向无止境的平稳与繁华。', 2, '璃月', 0, 104, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200015, '吃虎岩', 2701, '璃月港', '璃月港永远搏动的心脏，为之输送活力十足的血液。此处忙碌热闹的市井景象，正是璃月港无限生机之所在。', 2, '璃月', 0, 103, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200016, '绯云坡', 2701, '璃月港', '诸商行兴隆发达，居民富足无忧的繁华之所，灯火熙熙攘攘，长明不灭。', 2, '璃月', 0, 102, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200017, '瀚海孤云', 2703, '孤云阁', '传说是帝君镇压海中妖物留下的孤傲石峰。据说，心神敏感者偶然会在睡梦中听见，磐岩镇压的海床深处传来的某种律动。', 2, '璃月', 0, 113, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200018, '层岩巨渊地面景观', 2200, '层岩巨渊', '「初来此地时，望见如此奇迹般的可怖地貌曾一度惊愕失声…那时的震撼与敬畏感，至今没有忘记。」\r\n「但被总务司支使着跑上跑下久了，就算再巧夺天工的奇景也难免厌烦了…」\r\n「说到这里，不得不多谢前辈的相助，我才能继续自己的冒险…」', 2, '璃月', 1, 118, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200019, '矿坑巨口', 2202, '巨渊之口', '「层岩巨渊矿井的入口，被矿工们敬畏地称作『巨渊之口』。最近那场地震发生后，本就被七星封闭的坑口更显诡谲难测…」\r\n「在前辈的忙碌下，封印巨口的法印终于被解除了。希望『七星』不要怪罪下来才好…」', 2, '璃月', 1, 119, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200020, '伏鳌谷古战场', 2200, '层岩巨渊', '「此地曾是若陀龙王与岩王帝君死斗的战场。我只是一个经验浅薄的年轻冒险家，提笔弄墨本非所长…但目睹这样的奇观，仍然不觉感慨。」\r\n「与不舍昼夜的时空、震天撼地的巨神相比，我们身为凡人如何渺小…」', 2, '璃月', 0, 120, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200021, '地下矿区', 3900, '层岩巨渊·地下矿区', '「我曾在明蕴镇矿区长大，矿工们热闹嘈杂的劳动生息、矿工们的喜怒哀乐，占满了我的整个童年生活。」\r\n「如今面对更加宏大却寂静无人的地下矿道，心中有如昨日重现，只不过是更加寂寥忧郁的昨日…」', 2, '璃月', 0, 121, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200022, '被阻塞的矿道', 3901, '临时主矿道', '「当年撤离层岩巨渊的工人们将通往更深处的矿道封闭了，却保留下来了一尊『开山炮』。」\r\n「或许是当年大人物的特别指令吧…璃月蓬勃的商业，可不能离开琉璃晶砂的滋养太久。」', 2, '璃月', 0, 122, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200023, '地下水泽', 3903, '地下水泽', '「独自勘探的路上，发现了这处水泽。池水清凉洁净，在这里放松一下正好，将一路上的晦气洗濯一空。」\r\n「附近徘徊着一些温和的元素生物，慢悠悠的，罕见的与世无争之物…将它画在了地图上，如果前辈能顺着地图来到这里就好了。」', 2, '璃月', 0, 123, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200024, '晶石碎片', 3904, '崎岖石厅', '「曾经存在于此的晶石正是当年迫使层岩巨渊关闭的『元凶』，如今它的异动又令总务司惊悚不已。」\r\n「幸有前辈相助，它已经回归了地下更深处的渊薮，空留这座冷峻的『岩石行宫』。」', 2, '璃月', 1, 124, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200025, '颠倒古城', 3905, '无名遗迹', '「独自探索的路上，发现了这座宏大可怖的遗迹。或许是千百年前遭受惩罚而湮灭的古老文明，这座古城似乎在抗拒着外人的存在…或许与那些来历不明的紫黑色晶体与泥状物有关。」\r\n「驻足片刻，我只得远离这不祥的倒吊剪影。」', 2, '璃月', 1, 125, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200026, '大蘑菇之地', 3906, '荧光狭道', '「生长着奇怪巨大蘑菇的地下洞穴，似乎能听到诡异的呼唤声。也许是我的幻觉，出现幻觉则说明这里应该充满了有毒气体，应该尽快离开。」', 2, '璃月', 0, 126, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70200027, '巨柱岩宫', 3900, '层岩巨渊·地下矿区', '「尽管前辈警告再三，我还是跟随着{M#他}{F#她}的脚步来到了这片区域。」\r\n「天空般湛蓝的晶石巨柱，是我难以理解的景象…这是绝不属于大地的造物，只可能来自同它一般耀眼的天空。」\r\n「为了破解它的谜团，我决定通过隐秘的通道继续向深处探索…不知之后还能走多远，能否留下任何记录…」', 2, '璃月', 1, 127, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300001, '鸣神·离岛', 3102, '离岛', '传说数百年前，勘定奉行柊弘嗣曾从荒岛之上奇迹般地建起一座繁荣的商贸中心，令将军殿下刮目相看。「锁国令」实行的日子里，勘定奉行府上依旧灯火通明，来自远国的商户却已寂寥怆然，不复百年前熙攘之貌。或许这便是凡人之业的最好写照：成于一夕者，亦将败于一朝。', 3, '稻妻', 0, 201, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300002, '月光下的神林', 3106, '镇守之森', '传说在过去，这片神林曾是诸多妖怪栖身之处。如今，关于这片静谧的林地，仍有妖狸的「狸囃子」传说。', 3, '稻妻', 0, 204, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300003, '稻妻城·天领', 3101, '稻妻城', '诸多街巷坂道延伸交割，最终集于天守前。天守是稻妻无可置疑的权力中心，在大御所将军殿下永恒静谧的注视下，熙攘的万民终将摆脱执念的烦恼，走向不再需要追逐竞夺愿望的乐土——只不过，将军所见的那片净土，究竟是何风景呢？', 3, '稻妻', 0, 202, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300004, '稻妻城·城郊', 3101, '稻妻城', '沿古老的坂道逐步上行，稻妻城的城郊是一片颇有古风的闲适景象。似乎城内的繁华胜景并未感染此处的风光。将军的威势与恩惠同样在此弥布，带来了静谧而别样的生机。', 3, '稻妻', 0, 203, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300005, '影向山·鸣神大社', 3109, '鸣神大社', '鸣神大社坐落于影向山顶，守护着独一无二的神樱，是稻妻最大的神社。在并不太平的今日，为稻妻的民众提供可贵的慰藉与安宁。', 3, '稻妻', 0, 205, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300006, '远眺踏鞴之岛', 3200, '神无冢', '此处重峦叠嶂的环形岛屿是幕府的冶炼设施的最佳地形屏障。此处宏伟的巨型高炉曾源源不断地为稻妻生产高质量玉钢。但近来由于战事，驱动生产的「御影炉心」遭到了破坏。', 3, '稻妻', 0, 206, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300007, '神无冢·阵前', 3202, '九条阵屋', '传说在数百年前的灾事中，将军殿下倚重的凡人名将九条重赖短短一夜间便筑起阵城，与漆黑的军势对抗，高扬「雷之三重巴」的旗印。数百年后，九条家的后人亦传承了出色的军事工程技术。', 3, '稻妻', 0, 207, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300008, '高眺之蛇首', 3307, '蛇神之首', '传说中曾经深入深海的巨蛇，最终在八酝岛归于沉默。又有传说说海风穿过巨蛇的双眼、利齿时会发出阵阵如同哨子的声响，那是它为自己所作的镇魂诗。如今这首镇魂诗也同样为所有在战争中倒下、流离失所的人而吟。', 3, '稻妻', 0, 210, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300009, '战火中的滩涂', 3302, '名椎滩', '「名椎」在稻妻先民的古老语言中有「为神灵之手温柔爱抚」之含义。但讽刺的是，自千百年前至今，名椎滩便饱受战乱的摧残，落得居民寥寥，也成了拾荒者与海贼的天地。', 3, '稻妻', 0, 208, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300010, '八酝岛·裂谷', 3304, '无想刃狭间', '传说中，终结蛇神的一刀正是在此处斩下的。在这道横贯八酝岛的深邃峡谷中，雷光的残响至今不绝，仿佛属雷的精灵仍在喋喋不休地议论着数千年前，划开天空与大地的传奇光景…', 3, '稻妻', 0, 209, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300011, '珠光弥布的宫阙', 3501, '珊瑚宫', '海祇岛住民的政治中心与信仰集聚之地，礁岩与巨贝拱卫的宫阙隐居着蛇神的孑遗。', 3, '稻妻', 0, 215, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300012, '月浴之渊', 3501, '珊瑚宫', '「渊下宫」入口之所在，池水终年闪烁着比拟月华的磷光，因而得名「月浴」。', 3, '稻妻', 0, 217, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300013, '海渊民的村落', 3503, '望泷村', '海祇岛上的古老村庄，据说其居民祖辈自海渊而来。\r\n也是对向「眼狩令」揭旗抵抗之人重要的据点。', 3, '稻妻', 0, 216, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300014, '雷云旋聚之处', 3401, '天云峠', '海天变色的大战已成为渐被遗忘的过去，应唤而来的悠远雷暴依然在此驻留。', 3, '稻妻', 0, 214, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300015, '搁浅的旗舰', 3403, '「清籁丸」', '破落的安宅船也曾经历宏伟年代，星光垂泪的遗骸中，依稀可见在昔日巫女与乡老祝福下骄傲扬帆的光景。', 3, '稻妻', 0, 212, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300016, '寂静的渔村', 3404, '越石村', '旧日的笑语蝉鸣终湮于雷的威声。今人只记得，这是一座因无羁的雷电而废弃的村庄。', 3, '稻妻', 0, 211, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300017, '代宫司寝子大人的居所', 3402, '浅濑神社', '「『阿响』会回来的。」\r\n「多亏了汝等，神社打理得很好了。她很快就会回来了。」', 3, '稻妻', 1, 213, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70300018, '鹤观', 3600, '鹤观', '「啊啊，美丽的鸟，如神的鹫鸟啊。」\r\n「我们一同沉睡在蛛丝般的雾巢中。」', 3, '稻妻', 1, 218, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400001, '一切智慧具足之城', 4500, '道成林', '地上一切智慧的渊薮。在繁枝茂叶的圣树之下，学城的贤者们已遍计所有知识。欢迎来到须弥，寻找答案的旅人。', 4, '须弥', 0, 301, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400002, '林上的化城', 4501, '化城郭', '「智慧的华城属于我们，无明的密林亦然。那宝树上缀满的，是失梦之国的余物。」', 4, '须弥', 0, 302, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400003, '临河的村庄', 4202, '维摩庄', '维摩庄中除了宁静的生活外，别无他物。疲惫的旅人，请好好休息一下吧。', 4, '须弥', 1, 303, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400004, '双树控扼的港湾', 4200, '阿陀河谷', '「贤者的说教何其枯燥，不如斟满花酿的美酒，踏上征服七海的航程。」', 4, '须弥', 0, 304, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400005, '卡萨扎莱宫的回忆', 4100, '护世森', '在林中深处的宫殿前，有一片紫色的园林。繁花锦簇，莺鸟欢歌，正适合出演一场美丽的邂逅。', 4, '须弥', 0, 305, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400006, '沉思的花园', 4401, '禅那园', '花园中播种着无数的花卉，每一朵都要比晶蝶更加绚丽。这是善思之人所蒙许的乐园。', 4, '须弥', 0, 306, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400007, '高墙下的边驿', 4404, '喀万驿', '高大的坚壁抵御了热砂的风暴，也隔绝了知识的恩典。但神明的慧光不是本应普照所有人吗？', 4, '须弥', 0, 307, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400008, '遥望降魔的巨人', 4204, '降诸魔山', '「诸位，古国坎瑞亚数千年的历史在看着我们！」', 4, '须弥', 1, 308, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400009, '法留纳法宝', 4403, '水天丛林', '法留纳神机的力量的显现。带来生命的水，把巴螺迦变成桓那，让不毛的土地从此充满生机。', 4, '须弥', 1, 309, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400010, '雨的尽头', 4406, '', '「这里是没有雨的地方，又是雨诞生的地方。净化桓那的雨，从这里开始，也在这里结束。」', 4, '须弥', 1, 310, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400011, '无郁夷摩之地', 4101, '无郁稠林', '森林的记忆与梦汇集之处，似乎拥有着自己的意识。', 4, '须弥', 1, 311, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400012, '兰纳迦的小小园圃', 4101, '无郁稠林', '在这里，石榴歌唱，苹果鼓掌。', 4, '须弥', 1, 312, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400013, '兰那罗的世界', 4000, '桓那兰那', '「不管天空、大地有多么灰暗，只要你的心一直像太阳一样，发出金色的、温暖的光，那就一直都会有希望。」', 4, '须弥', 1, 313, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400014, '失梦的苗圃', 4602, '', '「挚友将再次同行于茂密的森林中。一切美好的事物终将归来，一切痛苦的记忆也会远去，就像溪水净化自己，枯树绽出新芽。」', 4, '须弥', 1, 314, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400015, '小小的梦', 4603, '沙中故里', '尽管拙劣，但他似乎为了迎接那菈朋友，做了许多准备。', 4, '须弥', 1, 315, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400016, '苗圃的新芽', 4604, '失梦的国土', '森林会记住一切。', 4, '须弥', 1, 316, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400017, '飞沙起舞的不毛地', 4700, '下风蚀地', '防沙壁以西，曾经也是一位神明的居所，也许在那时，沙漠也曾经是众生的乐园，智慧汇聚之所。而不是如同今日这般，举目所见，除却风暴以外，只有让人徒生感叹的陈迹。', 4, '须弥', 0, 317, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400018, '「背弃之塔」', 4700, '下风蚀地', '赤王逝去后矗立于此的宏大尖碑，沙漠住民称之为「背弃之塔」，将它们视作耻辱的标志，意味着沙漠诸王背弃了同赤王的誓约…\r\n它们的真实历史或许早于短寿的沙漠诸国，但早已被今人遗忘。', 4, '须弥', 0, 318, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400019, '遗民聚居之所', 4701, '阿如村', '「蓝宝石之城」图莱杜拉的巧舌诗人、萨勒赫城金瞳的赛莫德角斗士，阿伊·哈努姆的镇灵…赤王的伟大国度崩溃后产生和消亡的无数国度、英雄及其故事，在这座村庄化作了古老的童谣，轻响在幼童的枕边…\r\n长年以来，赤王的遗民早已混淆了历史与传说的界限，将之交融成浑然一体的回忆…', 4, '须弥', 0, 319, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400020, '赛莫德绿洲', 4700, '下风蚀地', '金瞳的赛莫德人同他们七重城墙的宏伟城邦崛起于古国的尸骸之上，旋又覆灭于诸国争斗的漩涡之中…\r\n短寿的国度沦亡已久，绿洲却仍如宝石一般点缀在沙海之上，以甘泉芳草招待往来的商队与流浪者。', 4, '须弥', 0, 320, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400021, '赤王陵', 4801, '赤王陵', '巨大的锥体像是支撑在高天与黄沙之间的柱石，从不知何时的过去就伫立于沙漠正中。站在它的面前，无论是平民、富有者亦或是饱识的学者，都不过是几粒沙尘。', 4, '须弥', 0, 321, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400022, '深埋地下的千间宫室', 4800, '列柱沙原', '在黄沙无法肆虐的幽暗处，无数间宫室与塑像久久沉睡，等待着自己的主人再度巡游至此的时日…', 4, '须弥', 0, 322, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400023, '圣显厅', 4702, '沙之眼', '「黄金的梦乡在召唤流浪的沙子，在这里不必将那苦涩的盐水掬饮，在这里不会再有明日的愁肠。」', 4, '须弥', 1, 323, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400024, '无底的大厅', 4805, '渡厄厅', '传说，在沙漠的深处，古老的神明试图将神话中的幽冥与天国一一再现，让那些有罪之人堕入幽冥，受他眷顾的子民居于乐土。', 4, '须弥', 0, 324, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400025, '阿如的倒影', 4801, '赤王陵', '在赤王陵顶端的顶端，并没有令人垂涎的宝藏，亦没有镶嵌宝石的殿宇，只有与沙漠别无二致的荒芜与衰颓，只有那宏大梦想破碎的痕迹。', 4, '须弥', 1, 325, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400026, '风蚀谷地中的巨人', 4901, '荼诃落谷', '巨人在山谷之间归于沉寂，过往黑渊的魔群仿佛是诗歌的夸张叙事。只有那足够摧山崩岩的力量，是学者所言非虚的最好证明。', 4, '须弥', 1, 326, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400027, '并无活力的活力之家', 4703, '活力之家', '以对患者的祈愿而命名的医院，如今不见了医者的身影与病愈者的欢歌，只剩下一片残迹。', 4, '须弥', 0, 327, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400028, '远眺葱茏之野', 4700, '下风蚀地', '从荒芜的沙漠远眺藏匿智慧的森林国度，深绿的遥远剪影阻隔在阻拦沙暴的高墙之后，冷眼睥睨着热风中飘摇的沙之国度…\r\n赤王之国覆灭后破碎诸国的时代，藩王们也曾以嫉恨的目光，在此遥望丰裕的国土吧…', 4, '须弥', 0, 328, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400029, '沙暴不息的达马山', 5001, '塔尼特露营地', '达马山的中央永远回旋着不散的沙暴。\r\n沙漠人口口相传，称在那沙暴的中央正隐藏着「永恒绿洲」之所在。', 4, '须弥', 0, 329, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400030, '「月蓝运河」', 5005, '啁哳之沙', '在沙漠人的古老民谣中，这里曾是三条运河交汇之处，孕育了肥沃的田野与富庶的庄园。\r\n但过去繁荣的景象，如今只留存于日渐褪色的睡梦之中了…', 4, '须弥', 0, 330, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400031, '塔尼特部族宿营地', 5001, '塔尼特露营地', '某座古老建筑的部分废墟，一度寄宿着旧日之人的幽灵…\r\n如今寄宿在这里的则是一支名为「塔尼特」的沙漠部族。', 4, '须弥', 0, 331, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400032, '被神遗弃的殿阁', 5002, '神弃殿阁', '居尔城的神殿废墟。在沙漠人的歌谣中曾是长寿的巨人所居之处。\r\n但一夜之间，巨人跌入大地的裂口，不知所踪…宏大的神殿也化作了裂谷中的废墟。', 4, '须弥', 0, 332, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400033, '威权尽葬之殿', 5015, '君王之殿', '居尔城的旧日之人曾在这些长廊与殿堂中祭祀沙漠神王，但遗忘令尊贵与卑贱失却了意义…', 4, '须弥', 0, 333, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400034, '沙虫隧道', 5014, '沙虫隧道', '人的殿堂早已陨落，沙虫占据了此处，将之改造成自己的宫廷与花园…', 4, '须弥', 0, 334, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400035, '失落的隐居行宫', 5021, '阿佩普的行宫花园', '传说赤王的眷友曾在沙丘下的庞大空洞中修筑行宫…\r\n沙虫曾是它的廷臣，飞蛇曾是它的友伴。但在今日，它们一并失去了高贵的神智与光彩。', 4, '须弥', 0, 335, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400036, '被遗忘的河谷', 5007, '「五绿洲」的孑遗', '曾经灌溉「五绿洲」的伟大河谷，居尔城贵胄曾在其中乘画舫巡游，放飞矫捷的猎鹰…\r\n但那骄傲猎鹰的后代，最终却蜕变成了狂野的沙漠赤鹫…', 4, '须弥', 0, 336, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400037, '藏匿遗迹的裂口', 5003, '巨人峡谷', '壮伟的居尔城及其间崛起的广厦，最终难逃沉入漆黑裂谷的下场。\r\n仿佛毁灭本身还不够屈辱一般，旧日的楼宇和庄园又被横行沙漠的匪类占据…', 4, '须弥', 0, 337, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400038, '醴泉干涸之殿', 5016, '酣乐之殿', '居尔城的旧日之人曾在这些长廊与殿堂中以美酒与歌舞纪念花园的曼妙岁月，但遗忘令一切酣乐零落成砂…', 4, '须弥', 1, 338, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400039, '生命枯焦之殿', 5017, '生命之殿', '居尔城的旧日之人曾在这些长廊与殿堂中培育多彩的植物与肥美的蕈类，但遗忘令一切生命重归贫瘠…', 4, '须弥', 1, 339, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400040, '巨人折胫之处', 5008, '折胫谷', '「折胫谷」之名古已有之，如今钢铁的巨人在这里失足陨落， 岂不是为这个名字更增添了分量？', 4, '须弥', 1, 340, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400041, '「神的棋盘」', 5002, '神弃殿阁', '被沙漠部族称为「神的棋盘」，如今已残缺失落的广场。\r\n学者们则认为这里曾是为古老机关实战训练准备的「演习场」。', 4, '须弥', 1, 341, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400042, '利露帕尔的监牢', 5013, '镇灵监牢', '如今化作绿洲的监牢，曾监禁着怎样的重犯？\r\n她的醒转，将为孤独的沙漠部族带来怎样的转机？', 4, '须弥', 1, 342, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400043, '旧日园圃的残迹', 5003, '巨人峡谷', '没入黑暗的裂谷之前，居尔宫城的大门曾是诗人与美人群聚之所。\r\n只有人中的精英才有资格在此地游览园圃，面见高贵的人王…', 4, '须弥', 1, 343, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400044, '愚人众远征队的临时总部', 5003, '巨人峡谷', '在呢喃低语的古老神龛之间，远北雪国的先遣部队在这里扎下了营地。', 4, '须弥', 1, 344, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400045, '永恒宁静的乐园', 5019, '「永恒绿洲」', '「…它的绿叶不会被秋风的手夺去，它的新春的快乐不会被时序的循环变为岁暮的残景…」', 4, '须弥', 1, 345, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400046, '岩穴吞没的秘殿', 41002, '阻勒隘', '地下的古国曾依托幽深岩穴中的古老遗迹修造隐秘的门厅，为所有不再敬拜神明的人类指引前行的道路。\r\n如今无神的国度已然覆灭，却依旧有徘徊在此的引路之人，宣讲着通往黑暗的扭曲福音…', 4, '须弥', 0, 346, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400047, '荒原顶上的古松', 41103, '跋松顶', '寄宿在高耸的跋尔松中的善灵曾庇护过诸多归乡的勇士，然而古老的盟约今已无人能识…', 4, '须弥', 1, 347, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400048, '废弃工坊的熔炉', 41004, '逾渊地墟', '在过去，曾有人类试图凭借自己的力量超越神明，这座巨大的熔炉似乎便是其象征。\r\n虽然古老的工坊早已无人维护，但熔炉中的火光却依旧生辉。', 4, '须弥', 0, 348, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400049, '永世叹息之门', 41004, '逾渊地墟', '恢弘崇高的巨扉不过是通往地下世界的边门。如今重门紧锁，门后一度繁荣的古国也已化为丘墟。', 4, '须弥', 0, 349, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400050, '不再受垢的渊谷', 41001, '荼泥黑渊', '「…渊底流溢的污泥终究退去，荼诃的遗胤也慑服于正法。千歌齐唱，霖雨暂息。」', 4, '须弥', 1, 350, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400051, '甘露滋养的归巢', 41101, '', '至纯的甘露滋养了花灵们的故园，那是唯有无垢的勇士才被允许踏入的禁囿。散落四方的灵光百种，最终亦将汇聚于此。', 4, '须弥', 1, 351, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400052, '万千子种的母树', 41101, '', '「赞美万千子种的母树，熄灭几欲焚天的劫火，降下涤荡污秽的甘霖。彼日灵光神耀，有如自灰暗山头初升的旭日。」', 4, '须弥', 1, 352, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400053, '源水之国', 41106, '遗忘之路', '正义将使真理昭示，恶者受罚，善者得偿。而你我不过是源水中的一滴，最初的愿望也终将随飞湍急流一道沉没，与被遗忘的乐符与暗语一同埋葬。', 4, '须弥', 0, 353, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400054, '厄里那斯深处的风景', 50203, '「特别温暖的地方」', '几近苏醒的心如今再度归于沉寂。', 5, '枫丹', 1, 354, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400055, '厄里那斯最深处的风景', 50203, '「特别温暖的地方」', '「很高兴见到你！」', 5, '枫丹', 1, 355, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400056, '「谕示裁定枢机」', 50306, '欧庇克莱歌剧院', '「尚未有律法之时，罪便已行于众水之上。但若是没有律法，罪又如何以罪之名得到宽赦？」', 5, '枫丹', 0, 356, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400057, '海沫之乡', 50205, '海沫村', '葱茂的苍晶山原下，是美露莘们温馨的家园。造型奇异的小房子分布在各处，令人印象深刻。不过，究竟是谁教给了她们这种独特的建筑方式呢？', 5, '枫丹', 1, 357, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400058, '旧日古螺的乐章', 50200, '苍晶区', '「从前伟大的雷穆利亚，如今却只余空响的乐章。曾经引导万民的旋律，也早已无人能识…」', 5, '枫丹', 1, 358, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400059, '暗潮回响之所', 50103, '白淞镇', '刺玫会的起源之地。如同有朝一日会成为雄鹰的雏鸟破壳而出，宏大而光明的野心曾经在狭小而阴暗的地方孕育。\r\n出身白淞镇的人与灰河的住民一样，从这些地方的历史中明白了，有些事情是值得、必须，或是只能用血去争取的。', 5, '枫丹', 0, 359, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400060, '水下的光荣', 50312, '', '昔日繁盛的街巷已经伴随着值得夸耀的一切没入深水。如今穿行于拱廊之间的只有鱼群，与孤寂的海潮之声。', 5, '枫丹', 0, 360, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400061, '白露与泉景之廷', 50320, '枫丹廷·瓦萨里回廊', '「众水之上，唯有此城。」', 5, '枫丹', 0, 361, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400062, '蚀影与浊流之地', 50314, '枫丹廷·灰河', '潜藏在枫丹澈光之下的浊影，也是属于放逐者们的栖身之所。\r\n「哪怕是律法筛落的残灰，最终也会重归同一条河。」', 5, '枫丹', 0, 362, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400063, '海噬之穴', 50309, '塞洛海原', '如同山岳一般宏伟的巨型颌骨，几乎能够将海潮吞吐。难以想象这般庞然大物竟曾阔步于世间。', 5, '枫丹', 0, 363, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400064, '「水仙十字王国」', 50305, '', '「在很久很久以后，在很远很远的地方，有一个美丽的『水仙十字王国』…」', 5, '枫丹', 1, 364, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400065, '伊黎耶的旋舞', 50301, '露景泉', '悠古的歌谣中，寻访纯水的骑士正是在此处与精灵相遇，一同踏上了救赎的旅途。千年的时岁如露景流转，无论是欢笑还是泪水，无论是欢悦还是苦难，最终都化作了如梦的旋舞，消散于喧闹的喝彩。', 5, '枫丹', 0, 365, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400066, '「芒索斯山麓的回忆」', 50300, '枫丹廷区', '萨莎曾在此处取景。\r\n柔风拂过芒索斯山麓鲜花盛开的草地，吹得风车也吱呀旋转。安宁闲适的氛围让人不由沉浸在美好的回忆之中。', 5, '枫丹', 1, 366, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400067, '「于秋分山远眺」', 50104, '秋分山西侧', '萨莎曾在此处取景。\r\n于秋分山远眺，可见厄里那斯山脊。在群山与湖泊之下，隐藏着美露莘的故乡。', 5, '枫丹', 1, 367, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400068, '「枫丹热泉」', 50200, '苍晶区', '萨莎曾在此处取景。\r\n透过热泉蒸腾的氤氲雾气，极目可见高耸入云的秋分山，以及贯穿而过的克莱门汀线。', 5, '枫丹', 1, 368, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400069, '「苍晶山地的晴朗清晨」', 50200, '苍晶区', '萨莎曾在此取景。\r\n苍晶山地的晴朗清晨，湿润晚风在叶片上留下的露水还未消失…', 5, '枫丹', 1, 369, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400070, '「边村风景」', 50200, '苍晶区', '萨莎曾在此取景。\r\n风景秀丽的滨海边村，不受打扰的平静生活令人心向往之。', 5, '枫丹', 1, 370, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70400071, '船之墓', 50200, '苍晶区', '追随着如同黑夜中的星宿一般散布着微小光芒的白色铁甲旗舰，众多战船在与巨兽的厮杀中沉入海沟深处。这里及上方的水域因此有幽灵作祟的传说，但这也让它成为了追求隐秘之人最合适的藏身处。', 5, '枫丹', 0, 371, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70500001, '璀璨才智的留遗', 50500, '枫丹动能工程科学研究院区', '在过剩的才智和热情的相互作用下，其以一种超乎所有人预期的方式实现了研究目的。但如今，已无人为之喝彩。', 5, '枫丹', 0, 401, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70500002, '破碎梦想的余迹', 50501, '中央实验室遗址', '在理想破灭后，保持沉默是它此刻最重要的责任。\r\n不过，似乎仍然有人相信，这些炽烈的能量有着别样用途…', 5, '枫丹', 1, 402, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70500003, '流逐之海', 50400, '黎翡区', '「无论何种罪愆，最终总会如砂砾般，隐落流逐于海潮之间。」', 5, '枫丹', 0, 403, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70500004, '铸铜的要塞', 50401, '管理区', '「黄铜与锻铁的要塞终有崩毁之日，律法与正义的坚城永无陨落之时。」', 5, '枫丹', 0, 404, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70500005, '零余的参照', 50500, '枫丹动能工程科学研究院区', '事故的余波未能将其完全摧毁，它以相悖于设计初衷的形式继续存在，或许这也称得上是一种精神的延续。', 5, '枫丹', 0, 405, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70500006, '伊黎耶的水色垂柳', 50721, '湖中垂柳', '在古时，湖中的垂柳是受到敬畏的。一切水脉在伊黎耶汇合，而垂柳随着水脉的甜与苦而繁茂或衰败。湖中之国也是如此，只是预兆总是先于灾难之月显现。', 5, '枫丹', 1, 406, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70500007, '载醉之舟', 50724, '「锈舵」', '曾经在日光下闪耀着洁白辉光的舰船已经彻底锈蚀。在这里易手的故事与钱币几乎一样多，而敢于步入其中的异乡人如月亮一般少。', 5, '枫丹', 0, 407, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70500008, '远港', 50725, '柔灯港', '往来其他国度的主要港口。据说曾经有修建第四条巡轨船航线，连通柔灯港与枫丹廷的计划。但这一计划随着最有力的执行者之死而无限期停摆了。', 5, '枫丹', 0, 408, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70500009, '格式塔', 50700, '莫尔泰区', '它曾经是许多事物、许多梦想。', 5, '枫丹', 1, 409, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70500010, '世界的胎水', 50706, '某微观宇宙的肇始', '它曾经将要再度成为众生的摇篮。', 5, '枫丹', 1, 410, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600001, '沉珑的瑶庭', 21006, '沉珑渊', '「碧潭沉玉镜光摇，云里深藏古洞霄。」', 2, '璃月', 1, 411, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600002, '碧水的玉玦歌', 21005, '宝玦口', '「…幽谷涟涟泉响圜，灵龛先出东北岸，幽峦岸峻藏西南；乾阳临坤自相隔，长流涡不转，美玉藏其间…」', 2, '璃月', 1, 412, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600003, '云瀑万寻遗珑埠', 21003, '遗珑埠', '沿着碧水河溯流而上，邻接瀚海的万丈悬瀑间，坐落着繁荣的商港。人稠物穰，无数商贾与海员的谈笑，伴随着街头巷尾的叫卖声，构成了璃月北境别具一格的风光。', 2, '璃月', 0, 413, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600004, '彩蝶翩绵之谷', 21103, '药蝶谷', '远离尘世喧嚣的仙家洞府。传说在遥远的过去，因战乱而流离失所的先民曾经蒙受名为「浮锦」的仙人庇佑，在此躲避外界的祸殃。文明的火种最终得以留存，而非消逝于滔天的山洪。', 2, '璃月', 0, 414, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600005, '洞天伏仙', 21110, '伏仙洞', '远离尘世喧嚣的仙家洞府。传说在遥远的过去，因战乱而流离失所的先民曾经蒙受名为「浮锦」的仙人庇佑，在此躲避外界的祸殃。文明的火种最终得以留存，而非消逝于滔天的山洪。', 2, '璃月', 1, 415, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600006, '药笼的枢庭', 21109, '灵枢庭', '昔日被奉为「药君」的仙人已经离去，如今留在此地的唯有无数空置的药笼。直到战争的最后，那扶危济困的悲愿都未曾动摇。', 2, '璃月', 1, 416, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600007, '泓浄的余音', 21203, '锦落庭', '「…宝玦沉，玉珑出…人间得失本相同，世事浮沉总难疏；万古兴亡俱是梦，一江流水自如初…」', 2, '璃月', 1, 417, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600008, '王山遗威', 21004, '灵濛山', '昔日，古华派势盛之时，各路豪杰曾聚义于此，觥筹交错，行歌之声不绝于耳。尽管如今门派业已式微，恢宏的厅堂依然伫立在此处，铭刻着被称作「侠义」的昨日。', 2, '璃月', 0, 418, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600009, '古华洗刃池', 21004, '灵濛山', '「愿君重洗剑，莫负匣中辉。」', 2, '璃月', 1, 419, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600010, '悬练垂晴', 21104, '悬练山', '「万斛凝岚结昼阴，千寻悬瀑垂晴练。」', 2, '璃月', 0, 420, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600011, '荒祠枕山麓', 21102, '赤璋城垣', '在老人们的传说中，沉玉谷的先民自遥远的南方迁居而来，他们在此地筑起了直通高天的祭台，留下了无数恢宏的殿宇。玉造的祭台早已无处可寻，唯有那些缄默的古老废墟依然伫立在浓雾缭绕的山岭中，看守着再也无人知晓的秘密。', 2, '璃月', 0, 421, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600012, '来歆的痕影', 21105, '来歆山', '「匪石斯沉，惟时来歆。」', 2, '璃月', 1, 422, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600013, '赤望高丘', 21202, '赤望台', '如今早已被遗忘的古老年岁里，沉玉的先民曾将此地称作「悬圃」。昔日辉煌的国度散作诸多部族，诸多部族又再度统一于繁荣的国度，而沉玉谷的灵脉只是一如当初，忠实地汇集于此处。', 2, '璃月', 1, 423, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600014, '昔古的宿诺', 21107, '古茶树坡', '「…等这棵树长大一些，我便把叶子摘了，在这里研茶给你们喝…」', 2, '璃月', 0, 424, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600015, '翘英日暖絮花轻', 21002, '翘英庄', '当春日温煦的柔风再度抚过沉玉的山野，那馥郁的茶香也会伴着轻舞的魂香花瓣，如昔时一般，再度飘遍安宁的街巷…', 2, '璃月', 0, 425, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600016, '碧水沉暮辉', 21001, '沉玉谷·上谷', '最后的玉珑在这里沉落千丈沧渊，最初的心愿在这里化作万寻江烟。', 2, '璃月', 0, 426, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600031, '佩特莉可的美丽传说', 50802, '佩特莉可镇', '佩特莉可有过许多美妙的梦想与动人的传说，但它们都未能改变小镇平静的生活。\r\n每当阵阵海风吹散晚钟的声音，镇上的人们便又度过了悠闲的一日。', 5, '枫丹', 1, 431, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600032, '黄金褪色的舞台', 50801, '褪色古堡', '在一切伟大与光荣结束之后，失去乐章的乐师曾在此哀歌不再归来的往日。', 5, '枫丹', 0, 432, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600033, '古老教团的奥秘之所', 50801, '褪色古堡', '他们曾发现许多秘密，但却从未找到答案。', 5, '枫丹', 0, 433, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600034, '沉睡的永恒之城', 560001, '雅努斯之门', '「海底之下，亦有王都。」', 5, '枫丹', 0, 434, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600035, '惟余钟声之处', 560003, '安提库旧港', '沉入海底的岩窟曾是繁荣的王城巨港。倘若旧日的钟声能够穿破海水的阻隔，迷途的灵魂或许便能找到返乡的道路。', 5, '枫丹', 0, 435, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600036, '通往卡皮托林之阶', 560006, '崇高大道', '耀眼的灵露曾沿着水道直抵北方的大湖，将正义与幸福传遍整个高海。那是雷穆利亚治下的和平，那是充满荣耀与希望的好时代。', 5, '枫丹', 1, 436, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600037, '安息的殿堂', 560009, '黄金的大宫', '「请赐予他们永恒的休息吧，并愿光明永久地撒在他们身上。」', 5, '枫丹', 1, 437, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600038, '谐律的投影', 560007, '谐律院', '「命运往往不过是叫人们看到幸福的一个影子，随后就把他们推上了毁灭的道路。」', 5, '枫丹', 0, 438, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70600039, '旧日梦想的终点', 560009, '黄金的大宫', '「我做了一个梦，在那个梦里，就连凡人也能拥有自由的意志与未定的命运…」', 5, '枫丹', 0, 439, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700001, '回声作响之地', 60100, '坚岩隘谷', '与嵴锋龙共同生活，名为「回声之子」的部族聚落处。峡谷之中，四处传来工匠的敲击，或寻猎宝石的人试探山岩的声响。', 6, '纳塔', 0, 501, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700002, '崖壁空悬的聚落', 60400, '踞石山', '与匿叶龙共同生活的部族聚落处。他们的先祖用绳索与钩爪将块块巨木悬挂于此，部族因此也有了「悬木人」这样的名字。', 6, '纳塔', 0, 502, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700003, '流水与温泉之乡', 60300, '涌流地', '与鳍游龙共同生活的部族，「流泉之众」因温泉和舒缓的音乐而闻名。在诸部族之中，唯有此处最受外来游客的欢迎。', 6, '纳塔', 0, 503, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700004, '追逐胜利与荣耀的战场', 60200, '万火之瓯', '在此处，为荣誉与胜利点燃纷争之火吧，然后，一切灵魂之炽热，都将化作圣火永明的薪柴。', 6, '纳塔', 0, 504, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700005, '金文萦绕的岩钉', 60107, '硫晶支脉', '名为「缝影针」的巨大固态燃素钉柱。传说从前「回声之子」的大灵借由部族勇士的血肉铸造而成，高悬于此，震慑地底幽暗的岁月…', 6, '纳塔', 0, 505, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700006, '晶柱迁动的石室', 60108, '众岩之里', '「斗争会在何处终结，恐惧会在何处失去效用？」\r\n「迷身的游魂，将自身从自身中解脱吧，因对面即是永恒荒凉的乐园。」', 6, '纳塔', 1, 506, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700007, '渺无人迹的净土', 60304, '浮土静界', '被藏起，门扉被合拢于半空的净土。曾经，怜悯一切的贤人向伟大之人传授秘法，而最后，又不知出于何等的心绪将之隐去。', 6, '纳塔', 1, 507, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700008, '远古先民的庙宇', 60404, '祖遗庙宇', '在大地拒绝种子的时代，鲜花枯萎，再无人可向土地祈求令口腹满足的食粮。那时，古老的先民于此，开始向夜晚的神明寻求启示。', 6, '纳塔', 0, 508, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700009, '硕果累累的母树', 60100, '坚岩隘谷', '在溪地生长着名为火榴果的果实，而据说所有的火榴果不过是这棵巨大母树的小小分株。', 6, '纳塔', 1, 509, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700010, '画境开辟之所', 60400, '踞石山', '那是因涂鸦的壁画而诞生的世界，还是被写意的笔迹掩藏起来的世界呢？', 6, '纳塔', 1, 510, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700011, '跋涉而至的秘屿', 60406, '窃火者密岛', '「追寻力量的渺小种族啊，你们将为渴求之物付出怎样的代价，又或愿意付出怎样的牺牲呢？」', 6, '纳塔', 0, 511, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700012, '立誓的壁画', 60102, '分道誓约之厅', '「于此立誓吧，希巴拉克…」\r\n「曾升浮土以庇佑众生者，曾授火种以光耀众生者…」\r\n「其族裔溯火而归时，不可有人阻拦！」', 6, '纳塔', 1, 512, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700013, '夜魂游荡的试炼场', 60201, '夜魂试炼之所', '安抚这些躁动不安的夜魂的方法，唯有炽烈的战斗一途！', 6, '纳塔', 0, 513, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700014, '在彩绘群山之中', 60100, '坚岩隘谷', '古时一位精通燃素刻录所有笔画与构造的智者，将其中的种种意义化作飘逸的线条，以燃素为染料，将巨崖作画布施以彩绘。据说，那就是如今纳塔涂鸦的由来。', 6, '纳塔', 0, 514, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700015, '谧光的洞窟', 60502, '荧草窟', '为了应对灰烬如谜烟笼罩山麓的危机，「烟谜主」的祭司曾在此研究如何让涂鸦在雾霭中亦能被分辨的秘法，据说那就是为何此处涂鸦具有别样力量的开端。', 6, '纳塔', 0, 515, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700016, '属血气者的统律中枢', 60603, '统律之心', '为了掩埋无可名状的过去，也为了开拓属血气者的未来，某人献上了自己的心，作为统律整座城市的容器。那一日后，连山中的灵魂都已焚尽，如今照看烬城的又是何人？', 6, '纳塔', 0, 516, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700017, '白色巨塔的倒塌', 60600, '奥奇卡纳塔', '理想、妄想、怨望、希望，因人们的愿望而建起的高塔，最终也随那愿望的破碎倒塌。', 6, '纳塔', 0, 517, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700018, '未完工的灰烬之城', 60602, '流灰之街', '在已被遗忘的种族所修筑的城墟之上，曾有人试图建起新的邦国。现在这里只剩下遭焚后的灰烬，一度为此而聚集起来的联盟也早已离散。', 6, '纳塔', 1, 518, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700019, '迷烟与谜语生长的山麓', 60503, '「烟谜主」', '与暝视龙共同生活，在六个部族之中也最为神秘的「烟谜主」部族坐落之处。据说在夜晚，部族内的成员和他们的龙，会借由如荧光的纹路，倾听寂静夜晚国度的回音。', 6, '纳塔', 0, 519, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700020, '灵谜的大涂鸦', 60503, '「烟谜主」', '维护这个规模的涂鸦需要代代相传的努力，据说曾有睡在巨大涂鸦画下的人于睡梦中梦见巨鸟张开翅膀的模样。', 6, '纳塔', 0, 520, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700021, '迷途夜色的祭祀所', 60503, '「烟谜主」', '经过考验，被视为拥有「灵觉」的「烟谜主」部族成员，自小都需要在此处进行修行，学习如何以正确的方式解读诸多夜魂的话语。', 6, '纳塔', 0, 521, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700022, '失落祭祀所', 60508, '浮羽之湾', '一度被迷雾笼罩的浮屿从前也是在陆上高耸的祭祀所，却在最后不得不沉入水中，以封绝蛊惑众人的恶念。', 6, '纳塔', 1, 522, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700023, '在镜璧之山前', 60500, '镜璧山', '「伟大的祭司将手中的镜子放在了地上，于是形成了此处的山壁，以抵挡漆黑的奔流。」', 6, '纳塔', 0, 523, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700024, '飘浮在云间的卫星', 60601, '？？？', '不知为何被云海掩没，也不知为何停驻于此的天船。在脱离了其创造者的控制后，仍默默守护着久远的秘密。', 6, '纳塔', 1, 524, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700025, '被记述的故事', 60502, '荧草窟', '记录以往英雄故事的涂鸦墙壁。被记载在此处的故事，究竟是曾经真实发生过的历史，还是别的故事的影子…', 6, '纳塔', 0, 525, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700026, '旧日的统律之心', 60608, '旧日的统律之心', '在如今被视为遗迹之城的深墟之中，远古的种族为了统律整座城市的机关曾用金文与指令铸造不具肉体的智慧，将之寄存于石制的造像。', 6, '纳塔', 0, 526, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700027, '翎羽如花相结之处', 60901, '「花羽会」', '与绒翼龙共同生活，名为「花羽会」的部族聚落处。每日，与绒翼龙一起飞行的部族成员，都会在空中巡视他们的领地。', 6, '纳塔', 0, 527, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700028, '永蕴常火的圣山', 60700, '安饶之野', '一切的火焰都曾来源于斯，一切的光亮都曾来源于斯。上古的英雄在流炎之中落下血与汗，才将一度点燃世界的热烈迎回今日的纳塔。', 6, '纳塔', 0, 528, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700029, '丰藏与耕种的沃野', 60701, '「沃陆之邦」', '与突角龙共同生活，名为「沃陆之邦」的部族聚落处。火山的余灰带给他们肥沃的土地，在这里，象征富饶的金穗在部族民的双手之中随风摆动。', 6, '纳塔', 0, 529, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700030, '天火浮岩之冠', 60704, '「天火之冠」', '在喷发时，因蕴含过量的气态燃素而得以浮动在天上的岩石群落。在经年的层积之后，形成了如是的样貌。有人曾说此处与「浮土静界」同为盗火贤者的手笔，但或许只是没有由来的无故猜测罢了。', 6, '纳塔', 0, 530, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700031, '曾受封绝的古城', 680000, '远古圣山', '一度被脆弱的誓言所封禁的古代城市，犹如已死去千年的骸骨受风吹动而展露一瞬栩栩之态，这座古老之城的最后挣扎又将迎来什么样的结局呢？', 6, '纳塔', 1, 531, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700032, '识海的流炎地', 680002, '分流识海', '据说古代的伟大种族通过浸泡流炎之池，即可从其中海量的燃素里获取自己需要的智识。据说曾有弱小的种族效仿这样的行为却最终失败，最后，一度仁慈的贤者才告诉那弱小的种族他们可以承受知识的方式。', 6, '纳塔', 0, 532, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700033, '聚缩的祭炼台', 680003, '聚火祭验所', '金色的秘文将光分化成种种形式，受伟力牵引的燃素在此化作层层的载体，从此，巨大的手掌之中，就浮动着被制造出来的星星。', 6, '纳塔', 1, 533, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700034, '众龙的审判所', 680004, '审议之庭', '此处原本是议事之厅，在繁荣之时，龙众在此处创造诸多秘法与机关。但在众龙的主人死去之后，此处变成了审判同族的场所。', 6, '纳塔', 0, 534, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700035, '心中的孔窍', 680009, '圣山之心', '那是圣山藏于深底的中心，也是伟大之龙的孔窍。受龙所选者归还瞳中的影子吧，以此，得以唤来涤荡一切的圣火！', 6, '纳塔', 1, 535, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700036, '惬意之街', 60801, '悠悠集市', '话事处的人们像喜欢倦意之屋般喜欢这条惬意的街道。', 6, '纳塔', 0, 536, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700037, '海崖上的绘卷', 60802, '彩彩崖', '纳塔最早的织卷，或许就是孩子们留在大地上的缤纷绘卷。', 6, '纳塔', 1, 537, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700038, '洋流拂过的夏湾', 60804, '浪浪湾', '若旅人正为前方的迷雾而疲惫，那么请让盛夏的温暖海水抚去那叹息。', 6, '纳塔', 1, 538, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700039, '狂舞之乐夜', 60806, '提提岛', '「亲爱的旅者，今天是音乐与舞蹈的夏夜，请将悲伤石沉大海，无需囿于离合聚散。」', 6, '纳塔', 1, 539, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700040, '蜜酎秘醅山馆', 60806, '提提岛', '依山而建的蜜酿之馆，灵与蜜的气息如瀑布般从山间倾泻而下。', 6, '纳塔', 0, 540, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700041, '地岩中的集镇', 60807, '刺梨镇', '海中巨岩下开发的安宁小镇，可爱的居民们已经准备好迎接来自世界各地的客人。', 6, '纳塔', 0, 541, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70700042, '岩石与刺梨的洞穴', 60807, '刺梨镇', '无时无刻不威胁着刺梨镇的安宁，被邪恶坏蛋盘踞的大本营。多年前其实是特诺奇兹托克地区的奇瑰之洞。', 6, '纳塔', 1, 542, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800001, '终北的遗响', 70300, '希汐岛', '「月啊，仁善的女主人，你要引我们行往何方？」', 7, '挪德卡莱', 1, 601, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800002, '觐月的旅路', 70302, '沐光之台', '凡世的众生常因苦痛而诞出心愿，又因心愿而诞出信仰。然而若是信仰并非总是献予虚幻之人，又何必要将冰冷无言的巨石雕琢成梦与歌谣中的形貌？', 7, '挪德卡莱', 0, 602, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800003, '月下的庭院', 70303, '', '而月色依然漫流如初。', 7, '挪德卡莱', 0, 603, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800004, '无信者的谎言', 70300, '希汐岛', '「我等皆是染罪之人，又如何得见无垢的月光？」', 7, '挪德卡莱', 0, 604, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800005, '寂静的浅滩', 70104, '绯沙盐沼', '钢铁的结构矗立在这片粉色的地质层，像一个错误的音符。没有大脑，也没有发声器官的神秘生命曾沉默地在此栖息，最终也沉默地逝去。', 7, '挪德卡莱', 1, 605, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800006, '叮铃哐啷的工坊', 70202, '叮铃哐啷蛋卷工坊', '叮铃哐啷、叮铃哐啷，大大小小的许多机械造物在这里诞生，当然，还有喷香可口的蛋卷！', 7, '挪德卡莱', 0, 606, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800007, '边地小镇', 70201, '那夏镇', '这镇子就像一艘在世界边缘搁浅的船，流民在此处汇聚，在过去的残骸与虚构的往昔中搜刮构筑乐园的碎片。', 7, '挪德卡莱', 0, 607, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800008, '钢铸的城塞', 70208, '空寂走廊', '这白铁与黑钢锻成的巨兽急迫地吞噬着目所能及的一切，无论是能源还是血泪。然而它所希求的却非剥夺，而是足以与近在眉睫的灾厄相抗衡的权柄。', 7, '挪德卡莱', 0, 608, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800009, '新世界的先声', 70101, '月矩力试验设计局', '正如边民在月下将祈愿纺成无数的诗章，北国的匠人将僭越的企图淬炼成如月光般冰冷的坚钢。\r\n月伴着长夜一同落下的时刻，撕裂旧世界之物便足以被称作新生的曙光。', 7, '挪德卡莱', 0, 609, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800010, '秘密的研究', 70100, '帕哈岛', '巨大的容器中盛放着被捕获的月光。', 7, '挪德卡莱', 0, 610, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800011, '新诞的舛讹', 70208, '空寂走廊', '他们以人的傲慢定义生命，却未能定义他们自己生命的终局。', 7, '挪德卡莱', 1, 611, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800012, '铁鲸之梦', 70206, '蓝珀湖', '由巨大齿轮构成的心脏早已停跳，钢铁的血管也已生锈，直到谁人将它从梦中唤醒，巨兽向着星空，呼出了一口长长的、彩缎似的气。', 7, '挪德卡莱', 1, 612, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800013, '矢誓的灯火', 70105, '终夜长茔', '许多人曾毅然走入黑暗，只为家园的光明得以保全。', 7, '挪德卡莱', 1, 613, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800014, '守望长夜的明灯', 70402, '皮拉米达城', '「如是我预见：\r\n海浪翻起白沫，死寂毁灭了星月夜。」\r\n「如是我宣告：\r\n谁掌中灯火不灭，就不必陷入如此黑暗。」', 7, '挪德卡莱', 0, 614, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800015, '乐园最后的宝藏', 70405, '雷德·米勒的「伟大财宝」', '「让死人埋葬死人吧，然后你们站起来，用高傲者的财富，筑起饥贫之人的乐园！」', 7, '挪德卡莱', 0, 615, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800016, '夜壑的黎明', 70604, '靡穷深壑', '「那不死的毒蛇必将两度复活，再被三次击倒…」\r\n「直到被月下世界的英雄们彻底埋葬…」', 7, '挪德卡莱', 1, 616, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800017, '零号避难所', 70501, '「末日后的乐园」', '或许一个不完美的世界，比「末日」更让人难以接受。', 7, '挪德卡莱', 1, 617, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800018, '遗世的仙庭', 70504, '仙灵的王廷', '这里只有古老的魔神留下的鬼魂残迹，与往日仙灵空空如也的宫廷。', 7, '挪德卡莱', 1, 618, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800019, '刺向苍穹的塔', 70506, '厄布拉神柱', '在过去，高塔是野心之人僭越的妄想，承载着虚无缥缈的魔天之梦。直到高塔随膨胀的野心一同破碎，「乐园」的种子方才破土而出。', 7, '挪德卡莱', 0, 619, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800020, '噩梦的预兆', 70602, '望崖营壁', '那是一只没有眼睑的巨眼，他的目光穿透云层与雾霭，大地与山峦，无所不知又无处不在。', 7, '挪德卡莱', 0, 620, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800021, '战歌回荡的厅堂', 70601, '英灵的享殿', '终北的猎手、反乱的英豪与执灯的勇士，一代又一代的英灵之声在此间回荡。战士之血虽已干涸，他们的功业也已为陈迹，但赞美之词永不消逝，高贵的名声永不消亡。', 7, '挪德卡莱', 1, 621, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800022, '兔子洞里的仙境', 70404, '魔女的花园', '装点花园的不过是普通的雕塑，绝非定格时光的魔法。魔女的秘密花园里没有秘密，就像自诩公义的命运从来不讲道理。', 7, '挪德卡莱', 1, 622, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800023, '墨染轻岚间', 10703, '麓阳书院', '研尽一寸墨，扫成千仞峰。', 105, '空之神殿', 1, 623, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800024, '千柱之殿', 10700, '空之神殿', '「让我们驶向世界的中心，那未给老者与年轻人、国王与愚人预留的国度。」', 105, '空之神殿', 0, 624, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800025, '炽沙与骄阳的高阁', 10704, '「沙上楼阁」', '「见证我的伟业，强悍者呵，并为之折服！」', 105, '空之神殿', 1, 625, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800026, '指动字成', 10702, '大方广', '唯有记忆与知识的建材，能塑造真正的通天之路。', 105, '空之神殿', 1, 626, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800027, '五百由旬一极微', 10705, '无想之间', '生生生生暗生始，死死死死冥死终。', 105, '空之神殿', 0, 627, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800028, '千风交汇之港', 10601, '荆夫港', '寄予远方与未来的渴慕，在这里散入轻柔的港风。', 1, '蒙德', 0, 628, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800029, '花景芳馥', 10602, '风车镇', '花纱蒙盖芳草，于是晴朗的天空同样将大地笼罩。', 1, '蒙德', 0, 629, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `geographies` VALUES (70800030, '北风的歌吟', 10600, '风息山', '「你可知道风息花盛开的地方？我心爱的人啊，我便要与你同往。」', 1, '蒙德', 0, 630, '2026-05-20 19:08:48', '2026-05-20 19:08:48');
INSERT INTO `materials` VALUES (102, '冒险阅历', NULL, 3, 13, '冒险阅历，用于提升冒险等阶', 'NONE', '系统开放', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (105, '好感经验', NULL, 3, 11, '好感经验，用于提升好感等级', 'NONE', '好感成长', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (201, '原石', NULL, 5, 30, '超出世界的原初晶石。黑暗的宇宙中，由无主的梦想与希望凝结而成的辉光。', 'ADSORBATE', '稀有货币', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (202, '摩拉', NULL, 3, 10, '通行大陆的钱。世界通用的共同语言，谁人都能理解的贵金属。', 'ADSORBATE', '通用货币', NULL, NULL, NULL, '[\"冒险与探索奖励\", \"洞天百宝兑换\", \"激活藏金之花奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (221, '无主的星辉', NULL, 5, 410001, '可以在商城兑换珍稀资源的货币。\n过剩的命运星之光辉。或许可以点亮宇宙其他角落。', 'CONSUME', '高级兑换券', NULL, NULL, NULL, '[\"祈愿\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (222, '无主的星尘', NULL, 4, 410002, '可以在商城兑换珍稀资源的货币。\n过剩的命运星之晶尘。累积起来，或许可以创造新的命运。', 'CONSUME', '普通兑换券', NULL, NULL, NULL, '[\"祈愿\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (223, '纠缠之缘', NULL, 5, 410003, '连结梦想的命运之种。\n缘石辉光能让本无交集的命运交错，让彼此的梦想相连，正如这种光辉将群星连成心之所向的图形。', 'CONSUME', '限定祈愿道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (224, '相遇之缘', NULL, 5, 410004, '点亮星空的希望之种。\n无论相隔多远，命定相遇的人都会受缘石辉光的指引，在星空下相会。', 'CONSUME', '祈愿道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (239, '纪游经验', NULL, 3, 1120100, '魔女封存于奇域中的万千收藏，皆是你们新奇的见闻，构成全新画卷的灵感。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (240, '诸界纪游', NULL, 5, 1000250, '使用后可以获得当期的诸界纪游使用资格。', 'CONSUME', '功能开启凭证', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (301, '火之印', NULL, 3, 430006, '受到纳塔的火焰认可，获授的印记。\n可以供奉在帕克斯神庙的煅石之轮前，以此得到圣火的庇佑。', 'CONSUME', '七国徽印', NULL, NULL, NULL, '[\"纳塔地区探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (302, '水之印', NULL, 3, 430005, '受到枫丹的流水认可，获授的印记。\n可以投入露景泉中，以此得到泉水的回馈。', 'CONSUME', '七国徽印', NULL, NULL, NULL, '[\"枫丹地区探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (303, '草之印', NULL, 3, 430004, '受到须弥的草木认可，获授的印记。\n可以贡献给森林深处的「梦之树」，以此获得森林的嘉许。', 'CONSUME', '七国徽印', NULL, NULL, NULL, '[\"须弥地区探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (304, '雷之印', NULL, 3, 430003, '受到稻妻群岛的鸣雷认可，获授的印记。\n可以缴纳给鸣神大社的神樱，提高「神樱眷顾」的等级。', 'CONSUME', '七国徽印', NULL, NULL, NULL, '[\"稻妻地区探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (305, '风之印', NULL, 3, 430001, '受到蒙德大地的千风认可，获授的印记。\n用来在蒙德城内特定的地方兑换特殊道具。', 'CONSUME', '七国徽印', NULL, NULL, NULL, '[\"蒙德地区探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (306, '冰之印', NULL, 3, 430007, '蒙德周围的特殊纪念货币，可在城市商店中兑换珍稀物品', 'CONSUME', '七国徽印', NULL, NULL, NULL, '[\"探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (307, '岩之印', NULL, 3, 430002, '受到璃月大地的岩石认可，获授的印记。\n用来在璃月港内特定的地方兑换特殊道具。', 'CONSUME', '七国徽印', NULL, NULL, NULL, '[\"璃月地区探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (308, '月之印', NULL, 3, 430008, '受到边地如水月华的认可，获授的印记。\n可以用于共建聚所，以此获得月光的赠礼。', 'CONSUME', '徽印', NULL, NULL, NULL, '[\"挪德卡莱地区探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (1201, '珍珠纪行·初稿', NULL, 5, 430011, '用纪行文体写成的游记，记载了在大陆上旅行的种种见闻。不知道为什么会有这个初稿，难道你之前来过？\n\n使用后可以获得当期的珍珠纪行使用资格。', 'CONSUME', '功能开启凭证', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (1202, '空月祝福·新月', NULL, 5, 430011, '于新月初升之时，向天空之月祈求财富与好运的仪式。你完全可以认为这是提瓦特的第一轮新月，至少是你见到的第一轮。\n\n使用后可以获得30天的空月祝福时间。', 'CONSUME', '功能开启凭证', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100001, '苹果', NULL, NULL, 90000, '爽脆可口的酸甜果实，无论生食或是酿酒都很是美味。', 'NOTICE_ADD_HP', '食物', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100002, '日落果', NULL, NULL, 90000, '遍布提瓦特大陆的自然恩惠，如夕阳般靓丽美好的饱满果实。有着奇异的香甜气味，能让人精神百倍。', 'NOTICE_ADD_HP', '食物', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100011, '蘑菇', NULL, NULL, 321, '生命力旺盛的常见菌类。只要拥有适宜的荫蔽与水分，在何处都能蓬勃生长。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100012, '甜甜花', NULL, NULL, 321, '香气浓郁的植株。即便在黑暗中，也能循着芬芳的气息找到的花朵。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100013, '胡萝卜', NULL, NULL, 321, '营养非常丰富的草本植物。易于种植与收获的作物，口感清甜爽脆。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100014, '白萝卜', NULL, NULL, 321, '纤维分明的草本植物。易于种植与收获的作物，富含纤维与营养。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100015, '金鱼草', NULL, NULL, 321, '烹饪后可食用的植株。作为香料能给食材带来奇妙的滋味。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"河岸湖泊采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100016, '薄荷', NULL, NULL, 321, '饱含清凉成分的植物叶子。清爽冰凉的滋味能将暑气荡涤一空。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100017, '小麦', NULL, NULL, 321, '金灿灿的穗子，让人充满希望。要经过磨砺与水火才能成为终极形态。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\", \"杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100018, '卷心菜', NULL, NULL, 321, '层层相裹的蔬菜。据说曾经是观赏植物，如今在锅里的模样也很棒。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\", \"杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100019, '天原银莲', NULL, NULL, 321, '珍贵的植物，生长在陡峭崖壁上的傲骨，在暗夜中发出高洁的光。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100020, '松果', NULL, NULL, 321, '富含油脂的肥美种子，并不会在松鼠的胃里长成参天大树。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100021, '钩钩果', NULL, NULL, 311, '带着勾刺的莓果，会挂在狼的毛皮上来迁徙。看见它时，仿佛能听见狼的凄嚎在林间回荡…', 'EXCHANGE', '蒙德区域特产', NULL, NULL, NULL, '[\"推荐：奔狼领采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100022, '落落莓', NULL, NULL, 311, '饱满透亮的莓果，在口中绽放出清甜的花香。在过去，守望风暴的人仅有的慰藉便是落落莓的甜蜜与对城市安宁的希望。', 'EXCHANGE', '蒙德区域特产', NULL, NULL, NULL, '[\"推荐：望风山地采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100023, '塞西莉亚花', NULL, NULL, 311, '名字与外形同等美丽的花朵，只生长在清冷而风急的高处，如同浪子一样真心难以触碰。', 'EXCHANGE', '蒙德区域特产', NULL, NULL, NULL, '[\"推荐：摘星崖采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100024, '风车菊', NULL, NULL, 311, '喜好风的植物。对于崇信风、本身也如风一般爽朗自在的蒙德人而言，风车菊便是「看得见的风」。', 'EXCHANGE', '蒙德区域特产', NULL, NULL, NULL, '[\"风起地七天神像附近采集\", \"推荐：风龙废墟采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100025, '慕风蘑菇', NULL, NULL, 311, '沐浴着和煦的风而生长的菌类，与风一样生生不息，滋养生命。', 'EXCHANGE', '蒙德区域特产', NULL, NULL, NULL, '[\"房檐下采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100026, '莲蓬', NULL, NULL, 321, '璃月水生的泽芝，花开两株。一株盛放芳香，一株莲蓬清苦。据说能入药。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"河岸湖泊采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100027, '绝云椒椒', NULL, NULL, 312, '璃月地方特产的辛辣植物。只要闻到它的味道，身体就会变得炽热，渴求水分。', 'EXCHANGE', '璃月区域特产', NULL, NULL, NULL, '[\"推荐：轻策庄采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100028, '夜泊石', NULL, NULL, 312, '稀有的特质矿石，在静谧的暗夜里会幽幽地发光。据称是天地间奔流的元素在异变中凝聚成的珍奇宝石。', 'EXCHANGE', '璃月区域特产', NULL, NULL, NULL, '[\"璃月山洞内采集\", \"推荐：明蕴镇采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100029, '霓裳花', NULL, NULL, 312, '在璃月如霓云般盛放的妖红之花，能制成如水般顺滑的织物。', 'EXCHANGE', '璃月区域特产', NULL, NULL, NULL, '[\"璃月港玉京台附近采集\", \"望舒客栈附近采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100030, '琉璃百合', NULL, NULL, 312, '极为古老的花卉。据说曾经遍布璃月大地，能将大地的记忆积攒成花期时的芬芳。', 'EXCHANGE', '璃月区域特产', NULL, NULL, NULL, '[\"推荐：璃月港玉京台采集\", \"推荐：轻策庄采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100031, '清心', NULL, NULL, 312, '只生长在孤高石峰的通透白花。不愿接受平原的温暖与湿润，宁可在清冷的尖峰眺望远方。', 'EXCHANGE', '璃月区域特产', NULL, NULL, NULL, '[\"推荐：绝云间采集\", \"推荐：孤云阁采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100032, '马尾', NULL, NULL, 320, '偶然随荻草生长的紫色植物。比周围的荻草更为挺拔、饱满，如同崇高的人。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"荻草丛中，湿地采集\", \"推荐：荻花洲采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100033, '星螺', NULL, NULL, 312, '随着海潮来到沙滩上的螺。将耳朵凑近空壳，能听见海充满思念的呼唤。', 'EXCHANGE', '璃月区域特产', NULL, NULL, NULL, '[\"璃月海滩采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100034, '琉璃袋', NULL, NULL, 312, '拥有旺盛生命力的小花，传说朝下盛开的花姿是为了守住它的香气。', 'EXCHANGE', '璃月区域特产', NULL, NULL, NULL, '[\"璃月山壁采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100051, '树莓', NULL, NULL, 321, '颜色鲜艳的果实。遍布野外的小小美好，能将路途疲惫一扫而空。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100052, '冰雾花花朵', NULL, NULL, 320, '封闭在坚冰当中的花芯。即使离开了植株也持续散发着寒气的冰凉植物。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：晨曦酒庄采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100053, '烈焰花花蕊', NULL, NULL, 320, '火辣辣的花芯。熊熊燃烧的炙热花朵，即使被水浇熄了也隐隐地放出热量。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：千风神殿采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100054, '电气水晶', NULL, NULL, 320, '富含电力的晶石，由逸散在大气与大地中的电气积聚而成。摸起来酥酥麻麻的。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"山壁下采集\", \"推荐：誓言岬采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100055, '小灯草', NULL, NULL, 311, '在夜间会隐隐散发辉光的野花。与其他食材一同烹饪能提升鲜味。', 'EXCHANGE', '蒙德区域特产', NULL, NULL, NULL, '[\"推荐：奔狼领采集\", \"推荐：低语森林采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100056, '嘟嘟莲', NULL, NULL, 311, '生长在水边的花。花瓣经过烹制口感爽脆，清甜微苦。', 'EXCHANGE', '蒙德区域特产', NULL, NULL, NULL, '[\"湖泊水边采集\", \"推荐：清泉镇采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100057, '蒲公英籽', NULL, NULL, 311, '随风而行的细小种子。即使拔去了旅行的羽絮，其中也寄宿着远方的希望吧。', 'EXCHANGE', '蒙德区域特产', NULL, NULL, NULL, '[\"推荐：蒙德城门采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100058, '石珀', NULL, NULL, 312, '极纯的岩元素凝成的珍稀晶石，常与其他矿物伴生。也被称为「岩之心」。', 'EXCHANGE', '璃月区域特产', NULL, NULL, NULL, '[\"璃月山壁下采集\", \"推荐：琥牢山采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100061, '兽肉', NULL, NULL, 321, '兽类的新鲜肉块。经过适当处理可以制成让人元气满满的美食。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"动物掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100062, '鸟蛋', NULL, NULL, 321, '拥有无限可能性的禽类的卵，能带来一整天所需的蛋白质。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100063, '松茸', NULL, NULL, 321, '与松树伴生的珍稀菌类，散发的淡雅鲜香暴露了它的位置。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100064, '禽肉', NULL, NULL, 321, '禽类的新鲜肉块。经过适当处理可以制成让人精神一振的佳肴。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"动物掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100072, '蝴蝶翅膀', NULL, NULL, 320, '色彩靓丽的翅膀。散落的鳞粉微微地发着光，或许是让蝴蝶能轻快飞翔的成分。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100073, '螃蟹', NULL, NULL, 321, '生活在近海区的甲壳类动物。细嫩鲜美的肉质，能够很容易地被加工成美味佳肴。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"河岸湖泊海滩采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100074, '蟹黄', NULL, NULL, 322, '母蟹体内独有的美味。稀少而又珍贵的蟹黄，聚集了螃蟹的精华。但并非所有人都擅于品尝这种美味。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100075, '盐', NULL, NULL, 321, '带有咸味的调味剂。只要在料理中准确把握「适量」的程度，就能让菜品产生质的提升。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100076, '洋葱', NULL, NULL, 321, '球状的草本植物。为了报复切碎它的人，不管人的心情好坏都会让他落泪。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100077, '胡椒', NULL, NULL, 321, '带有香辛味的调味剂。能够解腻并激发食材的香味，和肉搭配在一起最佳。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100078, '牛奶', NULL, NULL, 321, '奶牛的乳汁。香香甜甜，嘴角的那滴也不想放过。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100079, '番茄', NULL, NULL, 321, '外皮鲜红的草本植物。色泽艳丽，酸甜多汁。关于它到底属于水果还是蔬菜的争论自古有之。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100080, '土豆', NULL, NULL, 321, '块状的草本植物。来自大地的馈赠，是不管怎样加工都永远吃不腻的一味神奇食材。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100081, '青蛙', NULL, NULL, 320, '常见的蛙类，生活在潮湿的环境。总是富有活力。身上会分泌出让人充满活力的物质。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"淡水水域采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100082, '发光髓', NULL, NULL, 320, '萤火虫发出磷光的部位。对它而言是求偶的器官，对人则是能强健力量的良药。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100083, '蜥蜴尾巴', NULL, NULL, 320, '失去生命后微微卷曲的蜥蜴尾巴。含有强烈的药性，能让人皮肤变硬。味道很苦。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"捕捉蜥蜴采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100084, '鱼肉', NULL, NULL, 321, '鱼类的新鲜肉块。经过适当处理可以制成让人回味无穷的菜式。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"捕捉鱼类采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100085, '晶核', NULL, NULL, 320, '晶蝶的核心。是吸食着大气中逸散的细小元素的晶蝶长出的奇妙器官。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"捕捉晶蝶采集\", \"捕捉月萤虫采集\", \"晶蝶诱捕装置采集获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100088, '豆腐', NULL, NULL, 321, '鲜嫩的豆制品。口感如凝乳般细腻。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"璃月杂货店购买\", \"稻妻杂货店购买\", \"须弥杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100089, '杏仁', NULL, NULL, 321, '有着奇特香味的种子。能给食物带来全然不同的清新风味。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"璃月杂货店购买\", \"枫丹杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100090, '鳅鳅宝玉', NULL, NULL, 320, '鳅鳅吐出的闪亮珍珠，有神奇的药用效果。\n鳅鳅会将摄入的矿物质和元素凝结成带有微弱魔力的珠子，在紧急情况下，会将这些珠子吐出来迷惑狩猎者，以保全性命。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：荻花洲采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100091, '竹笋', NULL, NULL, 321, '新鲜生长出土的竹子嫩芽。有着奇妙的芳香，是只有竹子生长的地方才会出产的美味食材。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：轻策庄竹林采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100092, '稻米', NULL, NULL, 321, '提瓦特常见的禾本作物。无论是什么样的人，都能欣赏这种颗粒分明的饱满口感，正所谓「一样米养百样人」。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"璃月杂货店购买\", \"稻妻杂货店购买\", \"须弥杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100093, '虾仁', NULL, NULL, 321, '饱满的深海虾仁。拥有丰富的营养与压倒性的鲜美风味。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"璃月杂货店购买\", \"稻妻杂货店购买\", \"须弥杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100094, '「冷鲜肉」', NULL, NULL, 321, '稀有的鲜美肉类。\n据记载在数百年前已经灭绝的走豕品种，因为龙脊雪山的极端天候而被保存了下来。对于提瓦特的老饕们而言，是福音般神圣的极佳食材。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"动物掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100095, '鳗肉', NULL, NULL, 321, '陆鳗鳗的新鲜肉块。经过适当调理，可以做成极其鲜美的佳肴。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：海祇岛采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100096, '秃秃豆', NULL, NULL, 321, '提瓦特常见的豆类作物。带有淡淡的香气，因食用方法多样而被各地民众广泛接受。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"须弥餐馆购买\", \"枫丹杂货店购买\", \"纳塔杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100097, '神秘的肉', NULL, NULL, 321, '散发着神秘气息的新鲜肉块。不知道吃起来会是什么味道呢？', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"动物掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100098, '咖啡豆', NULL, NULL, 321, '提瓦特常见的植物果实。带有特殊的香气，碾碎后，可用于制作饮品。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"须弥咖啡厅购买\", \"枫丹咖啡厅购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100099, '发酵果实汁', NULL, NULL, 321, '经发酵而制成的果实汁。带有非同寻常的果实香气，常在烹饪肉类时用于调味。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"枫丹杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100100, '黑麦', NULL, NULL, 321, '灰褐色的穗子，是大地的馈赠。要经过研磨与烘烤，才能化为醇厚的滋味。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\", \"挪德卡莱杂货店购买\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100225, '狩猎陷阱', NULL, NULL, 430031, '用来捕捉一定体型的野兽。在野外留心搜集的话，还是能做出这样一个陷阱的。布置在地上，小心藏好。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100618, '奇异的「牙齿」', NULL, NULL, 200, '从雪山上拾得的「牙齿」。也许有人会知道关于它的一些信息…', 'EXCHANGE', '素材', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100619, '汲取了力量的龙牙', NULL, NULL, 200, '汲取了力量的龙牙。无论是光泽还是质感，相较原本都有所不同…', 'EXCHANGE', '素材', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100934, '键纹', '键纹 0', NULL, 430041, '海祇岛与渊下宫流传的键纹。用以解锁的图案，因此称之为「键纹」。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100935, '键纹', '键纹 1', NULL, 430041, '海祇岛与渊下宫流传的键纹。是由曾经的白夜国民之纹拆解而成的。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100936, '键纹', '键纹 2', NULL, 430041, '海祇岛与渊下宫流传的键纹。五种键纹样式各不相同。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100937, '键纹', '键纹 3', NULL, 430041, '海祇岛与渊下宫流传的键纹。人们离开海渊之后，将键纹拼合，形成了珊瑚宫家之纹。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (100938, '键纹', '键纹 4', NULL, 430041, '海祇岛与渊下宫流传的键纹。隐藏着一段秘密。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101001, '铁块', NULL, NULL, 301, '铁的矿石，在拥有相应技能的工匠手中能绽放光采吧。', 'EXCHANGE', '锻造用矿石', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101002, '白铁块', NULL, NULL, 301, '白铁的矿石，在拥有相应技能的工匠手中能大放异彩吧。', 'EXCHANGE', '锻造用矿石', NULL, NULL, NULL, '[\"野外采集\", \"推荐：望风山地采集\", \"推荐：奔狼领采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101003, '水晶块', NULL, NULL, 301, '未经削切的晶体。在专门处理后，才能真正展现价值吧。', 'EXCHANGE', '锻造用矿石', NULL, NULL, NULL, '[\"野外采集\", \"推荐：风龙废墟采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101004, '魔晶块', NULL, NULL, 301, '可以通过「委托锻造」，利用原粹树脂，提炼成武器经验材料。\n受地脉的能量侵蚀的水晶矿，寻常手段无法处理。', 'EXCHANGE', '锻造用矿石', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101006, '星银矿石', NULL, NULL, 301, '因为龙脊雪山的特殊地理环境与地脉，而产生的珍稀矿石。', 'EXCHANGE', '锻造用矿石', NULL, NULL, NULL, '[\"野外采集\", \"推荐：龙脊雪山采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101008, '紫晶块', NULL, NULL, 301, '未经削切的矿物晶体，仅在稻妻列岛上产生。经过专门处理后，能展现其真正的价值。', 'EXCHANGE', '锻造用矿石', NULL, NULL, NULL, '[\"野外采集\", \"推荐：鸣神岛采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101009, '萃凝晶', NULL, NULL, 301, '澄澈明净的晶石，矿芯具备良好的韧性与塑性。', 'EXCHANGE', '锻造用矿石', NULL, NULL, NULL, '[\"野外采集\", \"推荐：厄里那斯地面区域采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101010, '虹滴晶', NULL, NULL, 301, '映着虹色辉芒的晶石，有着优异的韧性与可塑性，自古以来便被至冬的工匠们视为绝佳的锻造材料。\n传说明月的高车破碎时，沾染神血的车軎殒入月下的尘世，化作虹色的宝玉。从那以后，大地上的人们不再为死去的神明奉上信仰，唯有那些知晓夜的君王们为何而死的幸存者们依然在徒劳地歌唱着那些早已被遗忘的名字。', 'EXCHANGE', '锻造用矿石', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101101, '北陆单手剑原胚', NULL, 4, 300, '生产武器的原材料。通过锻造，可以生产出4星的单手剑。\n哲学中认为大理石蕴藏着成为美丽雕塑的潜能。这些原胚也孕育了无限可能。真让人期待。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"蒙德、璃月、稻妻地区「征讨领域」或「奔狼的领主」挑战奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
