INSERT INTO `materials` VALUES (101201, '鬼兜虫', NULL, NULL, 313, '栖息在雷元素富集区域的奇异甲虫。与甲壳上宛如怒目而视的恶鬼之相相反，鬼兜虫其实非常温顺迟钝。', 'EXCHANGE', '稻妻区域特产', NULL, NULL, NULL, '[\"推荐：鸣神岛采集\", \"推荐：踏鞴砂采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101202, '绯樱绣球', NULL, NULL, 313, '从鸣神大社的神樱上飘落的花瓣，怀着稻妻大地的眷顾。', 'EXCHANGE', '稻妻区域特产', NULL, NULL, NULL, '[\"推荐：鸣神岛采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101203, '晶化骨髓', NULL, NULL, 313, '蕴含着「祟神」力量的晶体。冶炼时加入这种物质的话，能极大地提高钢铁制品的强度与韧性。', 'EXCHANGE', '稻妻区域特产', NULL, NULL, NULL, '[\"推荐：八酝岛采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101204, '血斛', NULL, NULL, 313, '在诗文中也被称为「赤蕊」的鲜艳植物，一度在稻妻列岛绝迹，如今在战场上再度重现。传说在血腥的战场上，它们开得格外妖艳。', 'EXCHANGE', '稻妻区域特产', NULL, NULL, NULL, '[\"推荐：名椎滩采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101205, '鸣草', NULL, NULL, 313, '即使在无风的日子里，亦会随雷鸣之声隐隐振动的植物。看起来像是花瓣的结构其实是叶片的延伸，保护着脆弱的花朵。', 'EXCHANGE', '稻妻区域特产', NULL, NULL, NULL, '[\"推荐：踏鞴砂采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101206, '海灵芝', NULL, NULL, 313, '在某些特殊的海域中、岛屿上才会生长的特殊物种。虽然外形看起来像菌类，但其实是由软体生物分泌增生而成的。', 'EXCHANGE', '稻妻区域特产', NULL, NULL, NULL, '[\"稻妻海域采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101207, '珊瑚真珠', NULL, NULL, 313, '与海祇的珊瑚相伴而生的宝珠，散发着月光般的丝丝凉意。', 'EXCHANGE', '稻妻区域特产', NULL, NULL, NULL, '[\"推荐：海祇岛采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101208, '天云草实', NULL, NULL, 313, '生长在清籁岛的天云草结成的果实，贴在耳畔能听见微弱的电流声。', 'EXCHANGE', '稻妻区域特产', NULL, NULL, NULL, '[\"推荐：清籁岛采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101209, '幽灯蕈', NULL, NULL, 313, '如同夜灯般微微发光的蘑菇，其中蕴含着不可思议的力量。', 'EXCHANGE', '稻妻区域特产', NULL, NULL, NULL, '[\"推荐：鹤观采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101210, '海草', NULL, NULL, 321, '生长在浅海中的植物，能为菜肴增添特殊的风味。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"稻妻海域采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101211, '堇瓜', NULL, NULL, 321, '有着色泽艳丽的外皮的果实，其中的果肉可以在烹饪后转化为口感独特的食物。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"稻妻野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101212, '星蕈', NULL, NULL, 90000, '伞盖形如五角星星一般的菌类，生命力十分顽强。成熟后，伞盖中央会裂开。', 'NOTICE_ADD_HP', '食物', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101213, '树王圣体菇', NULL, NULL, 314, '如云海般层层叠叠生长的菌类，大多寄生于雨林深处的乔木之上。', 'EXCHANGE', '须弥区域特产', NULL, NULL, NULL, '[\"推荐：善见地采集\", \"推荐：护世森采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101214, '帕蒂沙兰', NULL, NULL, 314, '圣洁而高贵的花卉，对生长环境的要求十分苛刻。花蕊经过加工后可以制成珍贵的香料。', 'EXCHANGE', '须弥区域特产', NULL, NULL, NULL, '[\"须弥城附近采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101215, '月莲', NULL, NULL, 314, '生长于林中湿地，散发着同月亮一般皎洁光芒的花卉。只有在夜晚才会绽放。', 'EXCHANGE', '须弥区域特产', NULL, NULL, NULL, '[\"须弥水域采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101216, '香辛果', NULL, NULL, 321, '生长在炎热潮湿的雨林当中，有着特殊辛香的果实。磨成粉末后可以制成香辛料，是须弥最重要的香料植物。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101217, '劫波莲', NULL, NULL, 314, '生长在山崖峭壁之上的攀援植物开出的花朵。被称为莲只是因为外形相似，本身和莲花并没有什么关系。', 'EXCHANGE', '须弥区域特产', NULL, NULL, NULL, '[\"须弥山崖采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101218, '墩墩桃', NULL, NULL, 321, '林中灌木结出的果实。肉质敦实，味道香甜可口。据说食用后还有宁心安神的功效。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101219, '须弥蔷薇', NULL, NULL, 321, '明艳而深沉的紫色花卉，散发出使行人驻足的馥郁芬芳。虽然被称作蔷薇但其实严格来说应该算作玫瑰。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101220, '赤念果', NULL, NULL, 314, '在恶劣的沙漠环境中也能存活的植物所结的果子，赤红的果实在黄沙映衬下显得格外动人。', 'EXCHANGE', '须弥区域特产', NULL, NULL, NULL, '[\"须弥沙漠采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101221, '枣椰', NULL, NULL, 321, '沙漠绿洲中的常绿乔木结出的果实。坚硬果皮下的果肉肉质绵厚，甘甜可口，对沙海子民而言是重要的食物来源。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"须弥沙漠绿洲采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101222, '沙脂蛹', NULL, NULL, 314, '在沙漠深处流沙鳗鳗的繁殖地才能找到的枯壳。其坚硬的表壳是为了保护流沙鳗鳗的幼体，直到它们得以适应炎热干燥的沙漠环境而存在的。', 'EXCHANGE', '须弥区域特产', NULL, NULL, NULL, '[\"须弥沙漠采集\", \"推荐：沙虫隧道采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101223, '悼灵花', NULL, NULL, 314, '绽放在古老战场上的鲜红之花，即便在荒漠中也能顽强生长。低垂的花朵似乎是在哀悼曾在此牺牲的英灵。', 'EXCHANGE', '须弥区域特产', NULL, NULL, NULL, '[\"须弥沙漠采集\", \"推荐：锋刃林泽采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101224, '万相石', NULL, NULL, 314, '分布在荒原群山的深处，散发着异彩的特殊辉石，似乎是由混化的元素能量凝结而成的。', 'EXCHANGE', '须弥区域特产', NULL, NULL, NULL, '[\"须弥沙漠采集\", \"推荐：铁穆山采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101225, '圣金虫', NULL, NULL, 314, '栖息在浩瀚沙海之中的顽强甲虫。甲壳上的金色纹路似乎暗示着它们与遍布沙漠的古老遗迹间存在某种渊源。', 'EXCHANGE', '须弥区域特产', NULL, NULL, NULL, '[\"须弥沙漠遗迹采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101226, '活化的星蕈', NULL, NULL, 90000, '伞盖形如五角星星一般的菌类，生命力十分顽强。看上去似乎充满了活力。', 'NOTICE_ADD_HP', '食物', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101227, '枯焦的星蕈', NULL, NULL, 90000, '伞盖形如五角星星一般的菌类，生命力十分顽强。看上去似乎被烤焦了。', 'NOTICE_ADD_HP', '食物', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101228, '毗波耶', NULL, NULL, 320, '没有种子的花卉。\n只要大地重新记起，毗波耶就会绽放。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：桓那兰那采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101229, '久雨莲', NULL, NULL, 320, '生长在水元素富集之处的植物。枫丹漫长的雨季后，随处可见其踪影，因此而得名。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"河岸湖泊采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101231, '茉洁草', NULL, NULL, 321, '华润而温莹的桃色花朵。拥有不同层次的芬芳，是用来调香的主要原料之一。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101232, '苍晶螺', NULL, NULL, 315, '散发着幽光的贝状结构。似乎是纯净的元素能量凝结而成的产物，而非某种生物的甲壳。', 'EXCHANGE', '枫丹区域特产', NULL, NULL, NULL, '[\"推荐：塞洛海原采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101233, '海露花', NULL, NULL, 315, '幽淡而高贵的蓝色花卉。柔软的花蕊具备良好的吸水性和弹性，是诸多日用品的原材料。', 'EXCHANGE', '枫丹区域特产', NULL, NULL, NULL, '[\"推荐：塞洛海原采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101234, '汐藻', NULL, NULL, 321, '随波逐流的藻类，依靠其他植物释放出的养分维持自身存在。虽然经常会被误解成浮游动物，但本质上其实是浮游植物。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"枫丹水下采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101235, '柔灯铃', NULL, NULL, 315, '静雅而清美的紫色花卉。其香清淡悠长、细腻柔和，因此常被用来制作名贵的香水。', 'EXCHANGE', '枫丹区域特产', NULL, NULL, NULL, '[\"枫丹廷北部采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101236, '虹彩蔷薇', NULL, NULL, 315, '纤婉而柔洁的粉色花卉。虽然被称作蔷薇，但本质上更接近百合。', 'EXCHANGE', '枫丹区域特产', NULL, NULL, NULL, '[\"推荐：苍晶区采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101237, '幽光星星', NULL, NULL, 315, '在水中会发出柔浅微光的软体动物。大多攀附在水边或水下的人造建筑表面。', 'EXCHANGE', '枫丹区域特产', NULL, NULL, NULL, '[\"推荐：黎翡区采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101238, '湖光铃兰', NULL, NULL, 315, '明澈而澄净的苍色花卉。生于水脉汇聚之处，其香清冷淡雅，辛凉柔婉。', 'EXCHANGE', '枫丹区域特产', NULL, NULL, NULL, '[\"推荐：伊黎耶林区采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101239, '子探测单元', NULL, NULL, 315, '枫丹科学院利用新型奇械构件生产的微型探测单元，原本用以监测各类环境数据。', 'EXCHANGE', '枫丹区域特产', NULL, NULL, NULL, '[\"推荐：枫丹动能工程科学研究院区采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101240, '初露之源', NULL, NULL, 315, '悬浮于莫尔泰区水体深处的清澈露滴，与常见的纯水造物不同，似乎凝聚着更为原始而纯粹的元素能量。', 'EXCHANGE', '枫丹区域特产', NULL, NULL, NULL, '[\"推荐：莫尔泰区水下采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101241, '清水玉', NULL, NULL, 312, '出产于沉玉谷的玉石。触感凉如清水，因此而得名。', 'EXCHANGE', '璃月区域特产', NULL, NULL, NULL, '[\"野外采集\", \"推荐：沉玉谷·南陵采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101242, '沉玉仙茗', NULL, NULL, 321, '生长在沉玉谷温暖湿润之处的茶叶。经过数千年的精心筛选培育，如今的茶叶香气浓馥绵长，纵然相隔数条街，依然能够嗅到那沁人心脾的芬芳。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：翘英庄采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101243, '颗粒果', NULL, NULL, 321, '因穗轴上长出巨大颗粒果实而得到此名的作物。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101245, '澄晶实', NULL, NULL, 321, '广泛生长于液态燃素环境之中的澄晶果树，在汲取燃素后结出的形如宝石的果实。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"液态燃素区域采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101246, '苦种', NULL, NULL, 320, '风味浓郁的作物。果肉本身会有独特的苦涩味，其种子在发酵及烘焙后，可以制成其他的美食。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101247, '浪沫羽鳃', NULL, NULL, 316, '生长在海边如羽状的特殊物种，看似是水草般的植物，实际上是形态特殊的水栖软体珊瑚。', 'EXCHANGE', '纳塔区域特产', NULL, NULL, NULL, '[\"推荐：涌流地采集\", \"推荐：「流泉之众」周边采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101248, '灼灼彩菊', NULL, NULL, 316, '形如飘然羽翼的花，花瓣的姿态在风中无比悠然。', 'EXCHANGE', '纳塔区域特产', NULL, NULL, NULL, '[\"推荐：柴薪之丘采集\", \"推荐：圣火竞技场周边采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101249, '青蜜莓', NULL, NULL, 316, '青蓝色的，汁液丰富的莓果。其果树大片生长在「悬木人」部族附近，是形态与火榴果相近的植物。', 'EXCHANGE', '纳塔区域特产', NULL, NULL, NULL, '[\"推荐：踞石山采集\", \"推荐：「悬木人」下方采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101250, '肉龙掌', NULL, NULL, 316, '形如巨大动物爪掌的多肉植物。', 'EXCHANGE', '纳塔区域特产', NULL, NULL, NULL, '[\"推荐：硫晶支脉采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101251, '烬芯花', NULL, NULL, 320, '散布在平原与高土的奇特花朵。成熟的花苞会在受到冲击后绽放开来。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101252, '微光角菌', NULL, NULL, 316, '在黑暗中微微发出光芒的菌类，因为形似暝视龙的角冠而被称为角菌。', 'EXCHANGE', '纳塔区域特产', NULL, NULL, NULL, '[\"推荐：镜璧山采集\", \"推荐：「烟谜主」周边采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101253, '枯叶紫英', NULL, NULL, 316, '叶片与花瓣呈现枯焦之态的花朵，常常能在流灰弥漫之处看到它。', 'EXCHANGE', '纳塔区域特产', NULL, NULL, NULL, '[\"推荐：奥奇卡纳塔采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101254, '云岩裂叶', NULL, NULL, 316, '花叶的外侧犹如石质的奇特植物，在绽放后，会露出晶石一般的芯。', 'EXCHANGE', '纳塔区域特产', NULL, NULL, NULL, '[\"推荐：安饶之野采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101255, '琉鳞石', NULL, NULL, 316, '沉积在富含燃素的区域，逐渐形成的红色鳞状晶石，蕴含极高的热量。', 'EXCHANGE', '纳塔区域特产', NULL, NULL, NULL, '[\"推荐：安饶之野采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101256, '红果果菇', NULL, NULL, 321, '看似形态普通，风味却相当特殊的蘑菇，只会生长于瓦雷莎家的果园附近。既然派蒙取下了很可爱的名字，说明味道深得她心。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"推荐：安饶之野果园采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101257, '便携轴承', NULL, NULL, 317, '愚人众进驻挪德卡莱后大量制造的便携轴承单元。损耗过度的单元也会像失去用途的单位一样被抛弃。\n其中偶尔还会残存一些微弱的月矩力。由于难以仿造，有时也会被那夏镇的商人当作等价交换的凭物。\n也正是因为如此，据说曾经有人试图伪造过这些单元。最终似乎是因为伪造的成本高于它们作为一般等价物的价格而破产了。', 'EXCHANGE', '挪德卡莱区域特产', NULL, NULL, NULL, '[\"蓝珀湖附近采集\", \"推荐：叮铃哐啷蛋卷工坊采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101259, '寒涌石', NULL, NULL, 320, '常见于挪德卡莱沿海地带的砾石，特征是其上自然形成的空洞，触碰时总能感到一股隐隐的寒意。\n在古老的传说中，寒涌石上的空洞曾是霜月指引妖灵们避难的居所，亦是通向幽域的门扉。而在另一个流行于那夏镇的故事里，大盗雷德·米勒被围困之时，正是靠着霜月的圣女送给他作为定情信物的符石隐去身形，逃脱了追捕。霜月之子的追随者们坚决否认这样的说法，将其斥为胡言乱语，毕竟现在的寒涌石也的确看不出有如此神奇的效果。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101261, '霜盏花', NULL, NULL, 317, '形如烛盏的花卉，多生长在水边，香气寒冽素净，有安神的功效。\n花蕊与花茎彼此相异的色彩被认为是两种不同的月矩力的象征，然而霜盏花却是极为罕有的、不会受到月矩力任何影响的植物，因此有时也会被霜月之子的追随者们视为无信者与叛离者的象征。\n据说五百年前的漆黑灾厄结束时，这种造型奇异的花朵才出现在大地上，但这种说法从未得到过严谨的考证。', 'EXCHANGE', '挪德卡莱区域特产', NULL, NULL, NULL, '[\"推荐：终夜长茔采集\", \"推荐：霜月之坊附近采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101262, '宿影花', NULL, NULL, 320, '双色缠络的花卉，有着极强的月矩力亲和性。由于香调淡雅、色泽显明，时常被认为是优质的天然染料。\n彼此相异的色彩被认为是两种不同的月矩力的象征，因此宿影花有时也会被霜月之子的追随者们视为月之少女的祝福。\n据说五百年前的漆黑灾厄结束后数十年，这种造型奇异的花朵才伴着咏月使的故去出现在大地上。霜月之子的诗歌大多采用这种说法，但这种说法从未得到过严谨的考证。', 'EXCHANGE', '素材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101263, '月落银', NULL, NULL, 317, '如月光一般明净无瑕的银白晶体，具有几乎完美的元素亲和力。\n在霜月之子的传承中，这种晶石于五百年前伴随月之少女一同诞生，被彼时的咏月使认为是从月上落下的馈赠，因此得名「月落银」。然而在至冬的编年者们记述的、更为古老的文献中，黄金国的遗胤自数千年前便在使用霜月纺就的秘银。两者之间的关联早已无从考证，唯一能确定的只有这种晶石如今依然被挪德卡莱的工匠们视为绝佳的元素力导体。', 'EXCHANGE', '挪德卡莱区域特产', NULL, NULL, NULL, '[\"希汐岛采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101264, '白灵果', NULL, NULL, 321, '如珍珠般澄澈的白色果实，口感清润甘甜。\n在霜月之子的传说中，与月灵一样，白灵果也是月之少女的恩赐，受新月祝福的神圣象征，因此分享并食用美味的白灵果也是对库塔尔的虔敬。\n话虽如此，即便没有与神明相关的故事，如此饱满甜蜜的果实本身便也足以唤起人们的食欲了。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101265, '夏槲果', NULL, NULL, 321, '生长在挪德卡莱温暖地带的果实，深受过冬的动物与嘴馋的孩子们喜爱。\n在霜月之子的传承中，夏槲果被视为「生命」与「丰盈」的象征，因为只有在春夏温暖的日子里，这种果实才会开花生长。\n亦有「冬凌王」与「夏槲王」永恒斗争的逸话。传说两位孪生的君王伴着年轮的转动，交替杀死彼此、又交替从冥府重生，统治属于他们的时节，如此循环往复，直至世界终结。至冬的学者们普遍认为这只是原始信仰中对季节交替的隐喻，至少他们这样说服了自己。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101268, '冬凌草', NULL, NULL, 317, '生命力极其顽强的花草，即便历经风吹霜打，依旧在苦寒的冬日里迎风摇曳。', 'EXCHANGE', '挪德卡莱区域特产', NULL, NULL, NULL, '[\"厄布拉神柱采集\", \"推荐：安瓦蒂尼尔湖附近采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101269, '松珀香', NULL, NULL, 317, '古时覆盖挪德卡莱的参天巨木，流淌下的树脂凝结而成的宝石，散发着璀璨的色彩。', 'EXCHANGE', '挪德卡莱区域特产', NULL, NULL, NULL, '[\"噩影泽地采集\", \"推荐：西风戍垒附近采集\", \"尘歌壶种植\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101271, '风息花', NULL, NULL, 321, '瑰秀却不失清润的花朵，主要生长在蒙德北方。\n花香明澈悠长，是用来调香的主要原料之一。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：风车镇采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101272, '空羽蛾', NULL, NULL, 311, '闪耀着神圣金色光辉的奇异生命，如飞蛾般游曳在同样奇异的隙间。', 'EXCHANGE', '蒙德区域特产', NULL, NULL, NULL, '[\"推荐：风息山、空之神殿采集\", \"推荐：风车镇、柱殿中央区采集\", \"前往采集\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101301, '桦木', NULL, 1, 330, '产自「桦树」的木材，易于加工，切面光滑，用这种木材制作的家具器物大多美观而耐用。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：苍风高地砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101302, '萃华木', NULL, 1, 330, '产自「萃华树」的木材，色泽秀美，木质独特，经过适当的加工，能胜任各种用途。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：坠星山谷砍伐\", \"推荐：碧水原砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101303, '松木', NULL, 1, 330, '产自「松树」的木材，色泽与木纹并不亮眼，但以朴实无华、低调素雅著称。且木质坚实，只需老练的木匠处理，就能耐受虫蛀和腐蚀。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：龙脊雪山砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101304, '却砂木', NULL, 1, 330, '产自「却砂树」的木材，据说有着风雨不侵，百年不朽的卓越木质。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：珉林砍伐\", \"推荐：璃沙郊砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101305, '竹节', NULL, 1, 330, '翠竹的竹段，轻巧而结实，远比谦逊的外表坚韧，散发着独特的清幽气息。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：碧水原砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101307, '垂香木', NULL, 1, 330, '产自「苍柏」的木材，因其富含油脂，香气别致，有着「垂香木」的别称。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：坠星山谷砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101308, '杉木', NULL, 1, 330, '「冷杉」出产的木材，有着不错的木质和纹理，被广泛使用于各种领域。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：坠星山谷砍伐\", \"推荐：风啸山坡砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101309, '梦见木', NULL, 1, 330, '产自「樱树」的木材，质感细腻，富含水分，据说能为人们带来暖春般的美梦。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：鸣神岛砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101310, '枫木', NULL, 1, 330, '产自「羽扇枫」的木材，硬度适中，品质优异，色泽与纹理上佳。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：鸣神岛砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101311, '孔雀木', NULL, 1, 330, '「柳杉」出产的木材，质地柔软，纹理平直，散发着浅淡的清香。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：鸣神岛砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101312, '御伽木', NULL, 1, 330, '「御伽树」出产的木材，水分和油脂的含量恰到好处，因此有着各种用途。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：八酝岛砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101313, '辉木', NULL, 1, 330, '产自「辉树」的木材，似乎有着与普通木材不同的构造，质地较软，但极为坚韧，易于染色，用途较为特别。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：须弥森林砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101314, '业果木', NULL, 1, 330, '「业果树」出产的木材，只需简单的处理就能得到光滑的切面，无需精细加工就极为美观。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：须弥森林砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101315, '证悟木', NULL, 1, 330, '产自「证悟树」的木材，几乎随处可见，看似平凡，实则有着轻便耐用的特点。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：须弥森林砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101316, '刺葵木', NULL, 1, 330, '「刺葵树」出产的木材，虽然没有优秀的质感和纹理，但锁水能力极强，便于维护。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：须弥沙漠砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101317, '柽木', NULL, 1, 330, '产自「柽树」的木材，质地特别，能够同时抵抗干旱和潮湿，极耐衰损。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：须弥沙漠砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101318, '悬铃木', NULL, 1, 330, '产自「悬铃树」的木材，芯材坚韧，适合用于搭建房屋的地基和框架。边材也易于加工，制作各类美观的家具时，所需的人力相对较少。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：枫丹野外砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101319, '椴木', NULL, 1, 330, '「心叶椴」出产的木材，质地细腻，色泽较浅，精细处理时的木屑较少，常被用于雕刻精巧的工艺品，或是制作尺寸紧凑的木制机关部件。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：枫丹野外砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101320, '白梣木', NULL, 1, 330, '产自「白梣树」的木材，强度极高，除了制作高强度的承力部件，还可以组合成坚韧的板材，用于加固墙体，或拼装成货运木箱等需要时常应对冲击的物件。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：枫丹野外砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101321, '香柏木', NULL, 1, 330, '「香柏树」出产的木材，有着边材较薄，芯材直径较大的优点。虽不如金属般坚实可靠，但需要制作较大面积的部件时，这种木材有着独特的优势。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：枫丹野外砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101322, '炬木', NULL, 1, 330, '产自「炬树」的木材，质地较软，易于切削，保持干燥的能力较强，与许多色泽亮丽的涂料相性极好，因此常被工匠们制作成各种精美的装饰品。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：枫丹野外砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101323, '白栗栎木', NULL, 1, 330, '产自「白栗栎树」的木材，硬度和韧性达成了较好的平衡，便于加工。虽说外观和其他木材并无太大差别，但经过纳塔各部族常用的方法处理后，木质颜色会变得较浅，接近白色，因此有了这一名字。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：纳塔野外砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101324, '灰灰楼林木', NULL, 1, 330, '产自「灰灰楼林树」的木材，有着较为轻便的优势，其余性能与大部分纳塔木材相差无几，成年的龙伙伴可以轻松搬运，传说也有部族战士将成捆的灰灰楼林木当成健身器材。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：纳塔野外砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101325, '燃爆木', NULL, 1, 330, '产自「燃爆树」的木材，与名字不同，这种木材经过「沃陆之邦」推荐的方法处理后，不易燃不易爆，相当可靠。\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：纳塔野外砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101326, '桃椰子木', NULL, 1, 330, '产自「桃椰子树」的木材，正如其名，树皮有着椰子壳般的质感，打磨后光滑而美观，硬度和防潮性能都极为出色…\n可用于制作摆设。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：纳塔野外砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101327, '银冷杉木', NULL, 1, 330, '「银冷杉树」出产的木材，被人类运用的历史悠久，可以胜任小到木桶，大到建筑板材的各种需求…', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：挪德卡莱砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101328, '榛木', NULL, 1, 330, '产自「榛树」的木材，虽然来源的树种形态多样，但木材表层大多具有独特的成分，防虫防腐能力可观，极为耐用。', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：挪德卡莱砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101329, '夏栎木', NULL, 1, 330, '产自「夏栎树」的木材，密度较低，韧性却相当不错，且有着不错的防水性能，因此常被用作水畔建筑…', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：挪德卡莱砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101330, '桤木', NULL, 1, 330, '「桤树」出产的木材，对于水汽和寒气有着可观的耐受性，亦是不错的家具和乐器原材…', 'WOOD', '素材', NULL, NULL, NULL, '[\"野外采集\", \"推荐：挪德卡莱砍伐\", \"洞天百宝·木材购买获取\", \"木材转化\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101401, '布匹', NULL, NULL, 331, '优质的布匹。制作摆设时应该能派上用场。', 'EXCHANGE', '素材', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101402, '红色染料', NULL, NULL, 331, '红色的染料。制作摆设时应该能派上用场。', 'EXCHANGE', '素材', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101403, '黄色染料', NULL, NULL, 331, '黄色的染料。制作摆设时应该能派上用场。', 'EXCHANGE', '素材', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101404, '蓝色染料', NULL, NULL, 331, '蓝色的染料。制作摆设时应该能派上用场。', 'EXCHANGE', '素材', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101644, '流明石原矿', NULL, 3, 420011, '流明石的璞矿，稍加雕琢的话似乎可以用来增强手中的流明石「触媒」，不如去找瑾武咨询看看…', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101692, '光界之印', NULL, 3, 430041, '受到渊下宫常世大神的认可，获授的印记。\n用来供奉给御使雕像，提升睦疏之匣的等级。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101693, '光界之核', NULL, 4, 430041, '在黑雾笼罩的渊下宫调查探索时，找到了奇特石头。\n为了对抗深渊，光界给人类提供了额外的帮助。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (101714, '香气四溢的调料', NULL, 1, 10, '根据娜扎法琳给的配方，制作出来的调料。带有扑鼻的香气，加入到料理中似乎能激发出更多风味。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104001, '流浪者的经验', NULL, 2, 100, '角色经验素材，含有1000点经验值。\n如果不在大陆七国生活，这些经验还是很必要的。', 'EXP_FRUIT', '角色经验素材', NULL, NULL, NULL, '[\"冒险与探索奖励\", \"洞天百宝兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104002, '冒险家的经验', NULL, 3, 100, '角色经验素材，含有5000点经验值。\n如果踏上了前人未至的秘境，这些经验还是很重要的。', 'EXP_FRUIT', '角色经验素材', NULL, NULL, NULL, '[\"冒险与探索奖励\", \"激活启示之花奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104003, '大英雄的经验', NULL, 4, 100, '角色经验素材，含有20000点经验值。\n如果向往着天空岛而在大陆开始巡礼，这些经验可称得上弥足珍贵。', 'EXP_FRUIT', '角色经验素材', NULL, NULL, NULL, '[\"解决事件报酬\", \"洞天百宝兑换\", \"激活启示之花奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104011, '精锻用杂矿', NULL, 1, 5, '武器经验素材，含有400点经验值。\n蕴含着无限可能性的精炼矿锭，可以用来强化武器。', 'WEAPON_EXP_STONE', '武器强化素材', NULL, NULL, NULL, '[\"锻造获得\", \"解决事件报酬\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104012, '精锻用良矿', NULL, 2, 5, '武器经验素材，含有2000点经验值。\n出于某种原理，武器可以吸收这种特殊的精矿，来变得更强大。', 'WEAPON_EXP_STONE', '武器强化素材', NULL, NULL, NULL, '[\"锻造获得\", \"解决事件报酬\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104013, '精锻用魔矿', NULL, 3, 5, '武器经验素材，含有10000点经验值。\n传说，精炼的矿锭中凝结了大地上战斗的记忆。而受益于这些记忆的兵器，自然也是有灵魂的了。', 'WEAPON_EXP_STONE', '武器强化素材', NULL, NULL, NULL, '[\"锻造获得\", \"解决事件报酬\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
