INSERT INTO `materials` VALUES (104111, '燃愿玛瑙碎屑', NULL, 2, 12102, '角色突破素材。', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"纪念品商店兑换\", \"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104112, '燃愿玛瑙断片', NULL, 3, 12102, '角色突破素材。\n「为了愿望而步上巡礼，为了最强之名而云聚争斗…」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104113, '燃愿玛瑙块', NULL, 4, 12102, '角色突破素材。\n「为了愿望而步上巡礼，为了最强之名而云聚争斗…\n「最后为了梦在劫火中燃尽。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104114, '燃愿玛瑙', NULL, 5, 12102, '角色突破素材。\n「为了愿望而步上巡礼，为了最强之名而云聚争斗…\n「最后为了梦在劫火中燃尽。\n「灰烬中如果留下了最初的心，那他就达成了██的真实。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
