INSERT INTO `materials` VALUES (104122, '涤净青金断片', NULL, 3, 12103, '角色突破素材。\n「我的理想之内并没有一丝污浊。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104123, '涤净青金块', NULL, 4, 12103, '角色突破素材。\n「我的理想之内并没有一丝污浊。\n「我要纠正你，在这里，人并不对神背负罪孽…」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104124, '涤净青金', NULL, 5, 12103, '角色突破素材。\n「我的理想之内并没有一丝污浊。\n「我要纠正你，在这里，人并不对神背负罪孽，能下达判决的只有法律与裁判庭。\n「他们甚至连我也可以裁判。赞美我的崇高与纯洁吧。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104131, '生长碧翡碎屑', NULL, 2, 12104, '角色突破素材。', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104132, '生长碧翡断片', NULL, 3, 12104, '角色突破素材。\n「我做了一个很长很长的梦…」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104133, '生长碧翡块', NULL, 4, 12104, '角色突破素材。\n「我做了一个很长很长的梦…\n「人们手握着手转圈。贤人与愚者，舞女与勇士，人偶与神像…」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104134, '生长碧翡', NULL, 5, 12104, '角色突破素材。\n「我做了一个很长很长的梦…\n「人们手握着手转圈。贤人与愚者，舞女与勇士，人偶与神像…\n「大家的欢舞里蕴藏着宇宙的一切。『生命』一直都是目的，『智慧』才是手段。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104141, '最胜紫晶碎屑', NULL, 2, 12105, '角色突破素材。', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"纪念品商店兑换\", \"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104142, '最胜紫晶断片', NULL, 3, 12105, '角色突破素材。\n「此身即是尘世最为殊胜尊贵之身。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104143, '最胜紫晶块', NULL, 4, 12105, '角色突破素材。\n「此身即是尘世最为殊胜尊贵之身。\n「应持天下之大权。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104144, '最胜紫晶', NULL, 5, 12105, '角色突破素材。\n「此身即是尘世最为殊胜尊贵之身。\n「应持天下之大权。\n「此身曾许诺予臣民一梦，即是千世万代不变不移的『永恒』。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104151, '自在松石碎屑', NULL, 2, 12106, '角色突破素材。', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"纪念品商店兑换\", \"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104152, '自在松石断片', NULL, 3, 12106, '角色突破素材。\n「但风向是会转变的。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104153, '自在松石块', NULL, 4, 12106, '角色突破素材。\n「但风向是会转变的。\n「终有一天，会吹向更有光亮的方向。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104154, '自在松石', NULL, 5, 12106, '角色突破素材。\n「但风向是会转变的。\n「终有一天，会吹向更有光亮的方向。\n「从今往后，带着我的祝福，活得更加从容一些吧。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104161, '哀叙冰玉碎屑', NULL, 2, 12107, '角色突破素材。', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"纪念品商店兑换\", \"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104162, '哀叙冰玉断片', NULL, 3, 12107, '角色突破素材。\n「…抱歉…」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104163, '哀叙冰玉块', NULL, 4, 12107, '角色突破素材。\n「…抱歉…\n「让你们一起和我背负了整个世界的哀思。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104164, '哀叙冰玉', NULL, 5, 12107, '角色突破素材。\n「…抱歉让你们一起和我背负了整个世界的哀思。\n「你们既然能忍受我的苦寒，那心中一定都有炽烈的欲望吧？\n「那么，替我燃烧旧世界吧。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104171, '坚牢黄玉碎屑', NULL, 2, 12108, '角色突破素材。', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"纪念品商店兑换\", \"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104172, '坚牢黄玉断片', NULL, 3, 12108, '角色突破素材。\n「大陆所流通的一切银钱皆是我的血肉。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104173, '坚牢黄玉块', NULL, 4, 12108, '角色突破素材。\n「大陆所流通的一切银钱皆是我的血肉。\n「我在以这样的方式，为人类一切的汗水、智慧和未来做担保。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104174, '坚牢黄玉', NULL, 5, 12108, '角色突破素材。\n「大陆所流通的一切银钱皆是我的血肉。\n「我在以这样的方式，为人类一切的汗水、智慧和未来做担保。\n「这是我对众生的信任，辜负了它就是玷污了我的血。」', 'AVATAR_MATERIAL', '角色突破素材', NULL, NULL, NULL, '[\"冒险之证讨伐页签查看\", \"合成台-转化页签：转化获取\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104201, '嬗变之尘', NULL, 2, 410011, '能够使元素突破材料发生变质，转变其元素属性的道具。\n刨除实用目的的话，炼金术实际上是研讨物质本质与其变化规律的学科，最终通向的是世界运转、地脉流通的规律。\n不知何者出于何种目的，在地上的文明当中散布的这种炼金术的极高成就产物，具有扭转完全惰性化结晶后的元素物质的能力。虽然相当便利实用，但也隐藏着打破平衡的巨大危险性…', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104301, '「自由」的教导', NULL, 2, 13101, '天赋培养素材。\n风之国土的精神是自由。\n自由其一，是生存的自由，即是能健全、健康地生活，而不必担心朝不保夕的自由。', 'AVATAR_MATERIAL', '角色天赋素材', 4210, '精通秘境：霜凝祭坛', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104302, '「自由」的指引', NULL, 3, 13101, '天赋培养素材。\n风之国土的精神是自由。\n自由其二，是漫游的自由，即是能在苍翠的土地上自由地通行，而不受阻挠的自由。', 'AVATAR_MATERIAL', '角色天赋素材', 4211, '精通秘境：霜凝祭坛', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104303, '「自由」的哲学', NULL, 4, 13101, '天赋培养素材。\n风之国土的精神是自由。\n自由其三，是歌唱的自由，即是能在风之神塑造的美好土地上歌唱，让自己的心与歌一同随风而去的自由。', 'AVATAR_MATERIAL', '角色天赋素材', 4213, '精通秘境：霜凝祭坛', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104304, '「抗争」的教导', NULL, 2, 13102, '天赋培养素材。\n风之国土的脊梁是抗争。\n蒙德的历史即是抗争的历史。抗争是为了蒙德过去的一切抗争不被遗忘，如同草木突破土壤，如同恒风洞穿石墙。', 'AVATAR_MATERIAL', '角色天赋素材', 4220, '精通秘境：冰封废渊', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104305, '「抗争」的指引', NULL, 3, 13102, '天赋培养素材。\n风之国土的脊梁是抗争。\n蒙德的历史即是抗争的历史。抗争是为了蒙德现在的人们能够拥有自由，正如风之神吹散冰雪，正如温妮莎奋起抗争。', 'AVATAR_MATERIAL', '角色天赋素材', 4221, '精通秘境：冰封废渊', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104306, '「抗争」的哲学', NULL, 4, 13102, '天赋培养素材。\n风之国土的脊梁是抗争。\n蒙德的历史即是抗争的历史。抗争是为了蒙德未来的诗文，也能自由地随着眷顾的风，传到远方。', 'AVATAR_MATERIAL', '角色天赋素材', 4223, '精通秘境：冰封废渊', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104307, '「诗文」的教导', NULL, 2, 13103, '天赋培养素材。\n风之国土的灵魂是诗文。\n诗文是美好的心意。在美好的日子里，吹拂原野的风中飘扬着田园诗、情诗，如和风拨动草叶般拨动人们的心。', 'AVATAR_MATERIAL', '角色天赋素材', 4230, '精通秘境：沉睡之国', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104308, '「诗文」的指引', NULL, 3, 13103, '天赋培养素材。\n风之国土的灵魂是诗文。\n诗文是激励的心意。在黯淡的日子里，穿过巷道的风中低语着愤怒的诗文，如同战鼓，如同风暴前的低鸣。', 'AVATAR_MATERIAL', '角色天赋素材', 4231, '精通秘境：沉睡之国', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104309, '「诗文」的哲学', NULL, 4, 13103, '天赋培养素材。\n风之国土的灵魂是诗文。\n诗文是传颂的心意。即使一切都将逝去，即使一切都将不再，随风而行的诗歌，仍会将此世间一切美好传遍天空、大地与海洋的一切角落。', 'AVATAR_MATERIAL', '角色天赋素材', 4233, '精通秘境：沉睡之国', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104310, '「繁荣」的教导', NULL, 2, 13104, '天赋培养素材。\n岩之国土的追求是繁荣。\n繁荣是璃月的恩惠，是璃月的神与人共同建立的伟大城市，是璃月的大地安全和平的源泉。', 'AVATAR_MATERIAL', '角色天赋素材', 5254, '精通秘境：炽炎祭场', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104311, '「繁荣」的指引', NULL, 3, 13104, '天赋培养素材。\n岩之国土的追求是繁荣。\n繁荣是璃月对它的子女的许诺：以繁荣回报勤劳者，以黄金照亮这片土地。', 'AVATAR_MATERIAL', '角色天赋素材', 5255, '精通秘境：炽炎祭场', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104312, '「繁荣」的哲学', NULL, 4, 13104, '天赋培养素材。\n岩之国土的追求是繁荣。\n繁荣是璃月的过去、现在与未来。在此世间一切国度都无法企及的繁荣，均归于璃月，以及璃月的子女。', 'AVATAR_MATERIAL', '角色天赋素材', 5257, '精通秘境：炽炎祭场', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104313, '「勤劳」的教导', NULL, 2, 13105, '天赋培养素材。\n岩之国土的根基是勤劳。\n勤劳即为通过人的努力，克服高山与大海，追求繁荣与黄金的勇气与力量。', 'AVATAR_MATERIAL', '角色天赋素材', 5258, '精通秘境：深炎之底', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104314, '「勤劳」的指引', NULL, 3, 13105, '天赋培养素材。\n岩之国土的根基是勤劳。\n勤劳是流传在璃月人血脉中的催化剂，能将岩石化为黄金，是伟大商港之所以为伟大商港的原因。', 'AVATAR_MATERIAL', '角色天赋素材', 5259, '精通秘境：深炎之底', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104315, '「勤劳」的哲学', NULL, 4, 13105, '天赋培养素材。\n岩之国土的根基是勤劳。\n勤劳即为相信自己，即为相信通过汗水、智慧与力量，在诸神的土地上，人人都可以拥有自己的一席之地。', 'AVATAR_MATERIAL', '角色天赋素材', 5261, '精通秘境：深炎之底', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104316, '「黄金」的教导', NULL, 2, 13106, '天赋培养素材。\n岩之国土的象征是黄金。\n黄金是流淌在璃月土地深处的血液，是鼓动璃月的心脏有力搏动的肌肉，是让璃月傲然挺立的筋骨。', 'AVATAR_MATERIAL', '角色天赋素材', 5262, '精通秘境：焚尽之环', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104317, '「黄金」的指引', NULL, 3, 13106, '天赋培养素材。\n岩之国土的象征是黄金。\n黄金意味着转换，这是璃月的岩山、大地、港城与人们的默契。在璃月，勤劳被转换为黄金，而黄金被转换为繁荣。', 'AVATAR_MATERIAL', '角色天赋素材', 5263, '精通秘境：焚尽之环', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104318, '「黄金」的哲学', NULL, 4, 13106, '天赋培养素材。\n岩之国土的象征是黄金。\n黄金是璃月的财富。但璃月真正的财富，是璃月的人们那如黄金般闪耀的心灵。', 'AVATAR_MATERIAL', '角色天赋素材', 5265, '精通秘境：焚尽之环', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104319, '智识之冕', NULL, 5, 14101, '提升天赋所需的珍贵素材。\n远古时期，承载与传授智识所用的仪式器具。尽管如今，智慧居于言语及典籍中，但「智识之冕」中残存的力量与智慧仍能给如今的人们带来伟大的突破吧。', 'AVATAR_MATERIAL', '角色天赋素材', NULL, NULL, NULL, '[\"限时活动奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104320, '「浮世」的教导', NULL, 2, 13107, '天赋培养素材。\n雷之国土的梦想是浮世。\n浮世之荣华乃是人之美的最高体现。人之在世岂不与疾电相类？如美梦或花火般浮华一瞬，在永恒的夜幕中留下绚烂的印记。', 'AVATAR_MATERIAL', '角色天赋素材', 4400, '精通秘境：菫染之国', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104321, '「浮世」的指引', NULL, 3, 13107, '天赋培养素材。\n雷之国土的梦想是浮世。\n浮世之难求乃是人之美的价值所在。人之在世岂不与雷影相似？意欲追逐掇取则遥踞云端，灯火阑珊的静谧之时却不期而来。', 'AVATAR_MATERIAL', '角色天赋素材', 4401, '精通秘境：菫染之国', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104322, '「浮世」的哲学', NULL, 4, 13107, '天赋培养素材。\n雷之国土的梦想是浮世。\n浮世之短暂乃是人之美的本性所在。人之在世岂不与稻光相近？神威显现的刹那恍若隽永，而永恒的威鸣又有谁人能够承受？', 'AVATAR_MATERIAL', '角色天赋素材', 4403, '精通秘境：菫染之国', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104323, '「风雅」的教导', NULL, 2, 13108, '天赋培养素材。\n雷之国土的姿容是风雅。\n风雅是不谄媚。风雅之人永远是高贵的。正似只愿高飞与雷暴争鸣的海鹰；迎合鄙俗则恰如将花冠倒插泥淖，仅让尊严染上了污渍。', 'AVATAR_MATERIAL', '角色天赋素材', 4410, '精通秘境：初雷幽谷', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104324, '「风雅」的指引', NULL, 3, 13108, '天赋培养素材。\n雷之国土的姿容是风雅。\n风雅是不倨傲。风雅之人永远是谦虚的。只有消除虚荣与怠慢，才能明亮双眼，从哪怕最不堪入目的表象之下寻求美与雅致的真境。', 'AVATAR_MATERIAL', '角色天赋素材', 4411, '精通秘境：初雷幽谷', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104325, '「风雅」的哲学', NULL, 4, 13108, '天赋培养素材。\n雷之国土的姿容是风雅。\n风雅是不庸俗。风雅之人永远是独行的。不屈于平庸之恶，不感动于平庸之爱，不逃避于平庸的无知，才可能明辨何为雅致与鄙陋。', 'AVATAR_MATERIAL', '角色天赋素材', 4413, '精通秘境：初雷幽谷', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104326, '「天光」的教导', NULL, 2, 13109, '天赋培养素材。\n雷之国土的愿望是天光。\n自认通透一切的大君，永远企图将高天之光彩尽收囊中。然而无从分享的愿景，却反令须臾之人更加炽烈地追求，犹如飞蛾扑火。', 'AVATAR_MATERIAL', '角色天赋素材', 4420, '精通秘境：真葛废都', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104327, '「天光」的指引', NULL, 3, 13109, '天赋培养素材。\n雷之国土的愿望是天光。\n即使晖光被重重雷云所掩盖，鸣神的国土之上，依旧有志士如云雀般突破雷光与天之怒海，追寻天光之迹，哪怕迎来冷酷的殛灭。', 'AVATAR_MATERIAL', '角色天赋素材', 4421, '精通秘境：真葛废都', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104328, '「天光」的哲学', NULL, 4, 13109, '天赋培养素材。\n雷之国土的愿望是天光。\n即使永远生活在地下，人也会不屈地祈求天光。人总是追逐超越，无可止步。静止封闭的永恒亦固然壮丽，但其本质终究是死亡。', 'AVATAR_MATERIAL', '角色天赋素材', 4423, '精通秘境：真葛废都', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104329, '「诤言」的教导', NULL, 2, 13110, '天赋培养素材。\n「诤言」是智慧之国的枝干。\n诤言出于纯净的心智。唯有清醒纯善的言语，方能表达深秘的智慧，令睿智之种突破傲慢的壅阻，生根繁茂。', 'AVATAR_MATERIAL', '角色天赋素材', 4430, '精通秘境：圆镜', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104330, '「诤言」的指引', NULL, 3, 13110, '天赋培养素材。\n「诤言」是智慧之国的枝干。\n诤言相伴巧妙的思虑。多思多虑方能出言谦逊明晰，令智者折服，使愚者醒悟，让智慧如川流一般畅通不息。', 'AVATAR_MATERIAL', '角色天赋素材', 4431, '精通秘境：圆镜', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104331, '「诤言」的哲学', NULL, 4, 13110, '天赋培养素材。\n「诤言」是智慧之国的枝干。\n诤言终于至善的操行。行为赋予言语真实含义，言、思、行的协同一致，是令智慧之树结出善果的丰厚养分。', 'AVATAR_MATERIAL', '角色天赋素材', 4433, '精通秘境：圆镜', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104332, '「巧思」的教导', NULL, 2, 13111, '天赋培养素材。\n「巧思」是智慧之国的叶脉。\n巧思生自良善的意旨。所谓「毒树不结善果」，良善坚定的意念才能孕育巧妙周到的思谋，方不玷污智慧之名。', 'AVATAR_MATERIAL', '角色天赋素材', 4440, '精通秘境：妙语', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104333, '「巧思」的指引', NULL, 3, 13111, '天赋培养素材。\n「巧思」是智慧之国的叶脉。\n巧思引导正直的言语。巧妙而周密的向善思索，令出口之言不偏离福祉之正道；怠慢与歹意则令言行卑劣不堪。', 'AVATAR_MATERIAL', '角色天赋素材', 4441, '精通秘境：妙语', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104334, '「巧思」的哲学', NULL, 4, 13111, '天赋培养素材。\n「巧思」是智慧之国的叶脉。\n巧思成于谐和的品行。行为赋予思想完美形态，思、言、行的彼此印证，是令智慧之树绽放出花朵的忠实基干。', 'AVATAR_MATERIAL', '角色天赋素材', 4443, '精通秘境：妙语', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104335, '「笃行」的教导', NULL, 2, 13112, '天赋培养素材。\n「笃行」是智慧之国的根系。\n笃行源于明晰的真性。不懈求索的实践，正是一切智慧最终显现的必经之途。不拘善行，明思与雅言亦无土壤。', 'AVATAR_MATERIAL', '角色天赋素材', 4450, '精通秘境：律藏', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104336, '「笃行」的指引', NULL, 3, 13112, '天赋培养素材。\n「笃行」是智慧之国的根系。\n笃行印证直率的言说。所思所行皆是为善，仍不可称之为智慧。智慧孕育于行动之中，为正直的言语篆下封印。', 'AVATAR_MATERIAL', '角色天赋素材', 4451, '精通秘境：律藏', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104337, '「笃行」的哲学', NULL, 4, 13112, '天赋培养素材。\n「笃行」是智慧之国的根系。\n笃行促生智慧的果实。行为实证行为本身的意义，行、言、思的联结一体，是令贤智之人得见完美的唯一通途。', 'AVATAR_MATERIAL', '角色天赋素材', 4453, '精通秘境：律藏', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104338, '「公平」的教导', NULL, 2, 13113, '天赋培养素材。\n水之国土的堤岸是公平。\n公平限制了权利的边界。若无公平，律法赋予的权利亦会被滥用，成为损害善良风俗的工具。', 'AVATAR_MATERIAL', '角色天赋素材', 4460, '精通秘境：旋韵', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104339, '「公平」的指引', NULL, 3, 13113, '天赋培养素材。\n水之国土的堤岸是公平。\n公平是枫丹立国的基础。公平形成了律法的准绳。假若律法失去公平的本质，必沦为敛利的棋盘。', 'AVATAR_MATERIAL', '角色天赋素材', 4461, '精通秘境：旋韵', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104340, '「公平」的哲学', NULL, 4, 13113, '天赋培养素材。\n水之国土的堤岸是公平。\n公平是枫丹立国的基础。公平总是需要稳固的道德与律法加以支撑，道德与律法亦基于不变的公平准则而流变不息。', 'AVATAR_MATERIAL', '角色天赋素材', 4463, '精通秘境：旋韵', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104341, '「正义」的教导', NULL, 2, 13114, '天赋培养素材。\n水之国土的利剑是正义。\n枫丹的律法秉正义之剑而行。若无正义的准则，一切律法将沦为无力的空文，任人篡改宰割。', 'AVATAR_MATERIAL', '角色天赋素材', 4490, '精通秘境：箴铭', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104342, '「正义」的指引', NULL, 3, 13114, '天赋培养素材。\n水之国土的利剑是正义。\n枫丹的律法秉正义之剑而行。正义必定是盲目的，以正义为利剑者，不论利益或私情都无法蛊惑。', 'AVATAR_MATERIAL', '角色天赋素材', 4491, '精通秘境：箴铭', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104343, '「正义」的哲学', NULL, 4, 13114, '天赋培养素材。\n水之国土的利剑是正义。\n枫丹的律法秉正义之剑而行。正义意味着裁决与调和，以裁决的剑锋遏止恶行，以调和的手段维护秩序。', 'AVATAR_MATERIAL', '角色天赋素材', 4493, '精通秘境：箴铭', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104344, '「秩序」的教导', NULL, 2, 13115, '天赋培养素材。\n水之国土的坚盾是秩序。\n枫丹的一切律法终究服务于稳固的秩序。若无秩序的存在，混沌的乱流中自然亦无公平可言。', 'AVATAR_MATERIAL', '角色天赋素材', 4494, '精通秘境：琅诵', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104345, '「秩序」的指引', NULL, 3, 13115, '天赋培养素材。\n水之国土的坚盾是秩序。\n枫丹的一切律法终究服务于稳固的秩序。若无秩序的保证，正义也将沦为无止境的暴力，成为一切人反对一切人的武器。', 'AVATAR_MATERIAL', '角色天赋素材', 4495, '精通秘境：琅诵', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104346, '「秩序」的哲学', NULL, 4, 13115, '天赋培养素材。\n水之国土的坚盾是秩序。\n枫丹的一切律法终究服务于稳固的秩序。公平与正义源于秩序，亦服务于秩序。正如枫丹恒无风浪的绵延水面那般，秩序构成了枫丹存在的基石。', 'AVATAR_MATERIAL', '角色天赋素材', 4497, '精通秘境：琅诵', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104347, '「角逐」的教导', NULL, 2, 13116, '天赋培养素材。\n火之国土的原则是角逐。\n何为强大者，何为弱小者？唯有胜败彰示着一切，角逐的结果，比任何话语更有说服力。', 'AVATAR_MATERIAL', '角色天赋素材', 4434, '精通秘境：转竟', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104348, '「角逐」的指引', NULL, 3, 13116, '天赋培养素材。\n火之国土的原则是角逐。\n人无法与有翼的兽比较飞行的速度，无法与史莱姆比较身躯的柔软，但人自有卓然之处。有时，为何要进行角逐，如何进行角逐，正是认清自己的关键。', 'AVATAR_MATERIAL', '角色天赋素材', 4435, '精通秘境：转竟', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104349, '「角逐」的哲学', NULL, 4, 13116, '天赋培养素材。\n火之国土的原则是角逐。\n角逐是为了让自身更加强大，在一场角逐的胜负落定之后，胜利者从中获得确立自己方向的自信，失败者获得如何变得强大的启示。在胜负之外，这是角逐真正的意义。', 'AVATAR_MATERIAL', '角色天赋素材', 4437, '精通秘境：转竟', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104350, '「焚燔」的教导', NULL, 2, 13117, '天赋培养素材。\n火之国土的成规是焚燔。\n有所取，即要有所予。想要得到，首先要付出相应的代价，正如应在焚燔中献上的祭品。', 'AVATAR_MATERIAL', '角色天赋素材', 4444, '精通秘境：空华', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104351, '「焚燔」的指引', NULL, 3, 13117, '天赋培养素材。\n火之国土的成规是焚燔。\n想要取得多少的东西，就要付出相应量级的代价。有时为了得到而付出太多，有时却付出的不足而无法得到。能够认识如何正确的付出与得到，也是焚燔的意义之一。', 'AVATAR_MATERIAL', '角色天赋素材', 4445, '精通秘境：空华', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104352, '「焚燔」的哲学', NULL, 4, 13117, '天赋培养素材。\n火之国土的成规是焚燔。\n所谓的焚燔，是在得到之前，先献出代价，但往往并非一定会有回应与回报。不求回报地付出代价，才是焚燔的真意，因为取得成果的日子终究会到来。', 'AVATAR_MATERIAL', '角色天赋素材', 4447, '精通秘境：空华', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104353, '「纷争」的教导', NULL, 2, 13118, '天赋培养素材。\n火之国土的事理是纷争。\n不去避让矛盾，而是直面冲突，在纷争的结果彰显后，根据此结果决定将行的道路。', 'AVATAR_MATERIAL', '角色天赋素材', 4454, '精通秘境：旋复', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104354, '「纷争」的指引', NULL, 3, 13118, '天赋培养素材。\n火之国土的事理是纷争。\n纷争永远能够被更高层面的力量介入并解决，而非不可收拾，这让一切都得以进入可控的境地。纷争亦是一种局限，禁止不计成本地推诿下去，而是要求参与方更干净利落地得出结果。', 'AVATAR_MATERIAL', '角色天赋素材', 4455, '精通秘境：旋复', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104355, '「纷争」的哲学', NULL, 4, 13118, '天赋培养素材。\n火之国土的事理是纷争。\n纷争的前提是，参与争端的人都会真诚地面对自己的欲望，面对欲望，然后在争辩或战斗之中，才不会忘记自己想要取得的东西，也不会偏离原本的目的。', 'AVATAR_MATERIAL', '角色天赋素材', 4457, '精通秘境：旋复', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104356, '「月光」的教导', NULL, 2, 13119, '天赋培养素材。\n「月光」是月下之地的祝福。\n物有大小不一，人有贤愚不齐。但在月光之下，一切都是平等的。', 'AVATAR_MATERIAL', '角色天赋素材', 4651, '精通秘境：墟都', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104357, '「月光」的指引', NULL, 3, 13119, '天赋培养素材。\n「月光」是月下之地的祝福。\n云中之月的光芒，相对于幽暗无垠的荒野是如此微弱，然而在漫漫长夜中，引导人们前行的却总是那一缕微光。', 'AVATAR_MATERIAL', '角色天赋素材', 4652, '精通秘境：墟都', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104358, '「月光」的哲学', NULL, 4, 13119, '天赋培养素材。\n「月光」是月下之地的祝福。\n于新月初升之时向天空之月祈求启示与祝福，是从初民的时代流传至今的仪式。今夜的月光似乎与过去的每一夜并无不同，但人们曾仰望的那轮新月又在何方？', 'AVATAR_MATERIAL', '角色天赋素材', 4654, '精通秘境：墟都', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104359, '「乐园」的教导', NULL, 2, 13120, '天赋培养素材。\n「乐园」是月下之地的狂想。\n有人不择手段地想进来，也有人拼了命地想出去。或许乐园就是你永远无法抵达的地方。', 'AVATAR_MATERIAL', '角色天赋素材', 4655, '精通秘境：遗荫', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104360, '「乐园」的指引', NULL, 3, 13120, '天赋培养素材。\n「乐园」是月下之地的狂想。\n在满溢着苦涩与悲泣的大地上，创造出没有界限亦没有差别的乐园。虽说这不过是孩子气的妄想，但那同样也是创造未来的基石。', 'AVATAR_MATERIAL', '角色天赋素材', 4656, '精通秘境：遗荫', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104361, '「乐园」的哲学', NULL, 4, 13120, '天赋培养素材。\n「乐园」是月下之地的狂想。\n乐园的定义因人而异。对那些从不安于现状的人而言，再也没有比挪德卡莱更适合称作乐园的地方了。但对剩下的人来说，情况则恰恰相反。', 'AVATAR_MATERIAL', '角色天赋素材', 4658, '精通秘境：遗荫', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104362, '「浪迹」的教导', NULL, 2, 13121, '天赋培养素材。\n「浪迹」是月下之地的生活。\n安享短暂的休整，于黑夜到来前启程。黎明并非终点，而是另一次旅途的开幕。', 'AVATAR_MATERIAL', '角色天赋素材', 4659, '精通秘境：覆巢', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104363, '「浪迹」的指引', NULL, 3, 13121, '天赋培养素材。\n「浪迹」是月下之地的生活。\n生命与流浪本身并无差别，无人在世间永远驻留，不过是暂作停歇。值得纪念的不是抵达终点的时刻，而是沿途留下的足迹。', 'AVATAR_MATERIAL', '角色天赋素材', 4660, '精通秘境：覆巢', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (104364, '「浪迹」的哲学', NULL, 4, 13121, '天赋培养素材。\n「浪迹」是月下之地的生活。\n穿越雷霆与风暴，跨过山峦和雪原，即便遍体鳞伤，也绝不就此驻足。浪迹之人之所以还没有停下脚步，是因为他们还没有找到可以称之为「家」的地方。', 'AVATAR_MATERIAL', '角色天赋素材', 4662, '精通秘境：覆巢', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (105005, '祝圣之霜', NULL, 5, 410006, '通过圣言自明机，进行圣遗物定义时所消耗的素材。\n圣遗物本质上是意志与记忆的具现结晶。此即是炼金术伟业的一种应用：将意志保存于物质世界的精华之中，并使之结晶。只有这样才方便将其按需塑造。', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"「圣言自明机」萃取获取\", \"「幻想真境剧诗」星章奖励\", \"「砺行修远」获取\", \"纳塔「煅石之轮」供奉获取\", \"纳塔「部族秘藏之所」获取\", \"挪德卡莱「聚所共建」获取\", \"「珍珠纪行」获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (105006, '启圣之尘', NULL, 5, 410006, '圣遗物力量的本源来自于故事，因此神圣或渎圣的书写可以尝试重塑圣遗物。\n然而故事本身并无善恶，歌谣与字句既有拯救之力，亦有毁灭之能，正如昔日传谕至圣的启示、统领地上的万国与万国的荣华，却又从高天坠落的使者所相信的那般。时至今日，这些至洁或不洁的翎羽依然能写下虚假的启示，改写注定的故事，然而与世界相抗的结果唯有散落成尘。', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"「幽境危战」危战嘉奖\", \"「幽境危战」挑战奖励\", \"「砺行修远」获取\", \"挪德卡莱「月灵盈藏之地」获取\", \"「珍珠纪行」和「珍珠之歌」获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107001, '散失的风神瞳', NULL, NULL, 420001, '浓烈的风元素能量积聚成的物质。献给风的神像，能弥补它在漫长岁月中散失的力量。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107002, '元素晶尘', NULL, NULL, 406, '神瞳结晶破碎后的碎片，揭示附近隐藏宝箱', 'CONSUME', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107003, '散失的岩神瞳', NULL, NULL, 420001, '浓烈的岩元素能量积聚成的物质。献给岩的神像，能弥补它在漫长岁月中散失的力量。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107010, '绯红玉髓', NULL, NULL, 420021, '某种浓郁的生命力与龙脊雪山的特殊能量结合产生的结晶。对于渴求生长的忍冬之树，是绝好的「养分」。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107011, '绯红玉髓（纯表现）', NULL, NULL, 420021, '某种浓郁的生命力与龙脊雪山的特殊能量结合产生的结晶。对于渴求生长的忍冬之树，是绝好的「养分」。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107013, '仙速瓶', NULL, 4, 410012, '封存着一股仙力的小瓶。使用后能立即完成一件摆设的制作。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107014, '散失的雷神瞳', NULL, NULL, 420001, '浓烈的雷元素能量积聚成的物质。献给雷的神像，能弥补它在漫长岁月中散失的力量。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107015, '逐月符', NULL, NULL, 420021, '由冒险家协会布设在各地的玉符，以「浮生石片」雕琢而成，光泽温润，晶莹剔透。据说这种玉符凝聚着皓月的精华，寄托着人们对往日佳节的追思，意义非凡。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107016, '流明晶石', NULL, NULL, 420021, '湛蓝如天幕的晶石，表面光芒明灭，似乎在呼应着地层深处不可见的高远天空…\n侧耳细听，仿佛能听到其中传来细微的叹息。\n说来奇怪，这块晶石有一种温暖的触感。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107017, '散失的草神瞳', NULL, NULL, 420001, '浓烈的草元素能量积聚成的物质。献给草的神像，能弥补它在漫长岁月中散失的力量。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107020, '对局邀请函', NULL, 3, 410021, '可以阅览猫尾酒馆对局邀请板，选择牌手名录中的一位，即可使用这封对局邀请函，委托猫尾酒馆发出对局邀请。受邀请的牌手将会到猫尾酒馆等待进行对局。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107021, '幸运牌币', NULL, 3, 410021, '牌手协会内部认证和使用的货币，可以用于购买「七圣召唤」相关的各式各样的道具。据说当初取名为幸运牌币，是希望拥有它的人能够变得幸运，不过，或许是足够幸运的人才能拥有它们也说不定…', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107022, '净光翎', NULL, NULL, 420021, '灵光百种所遗留下来的，凝结着过去记忆的断片。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107023, '散失的水神瞳', NULL, NULL, 420001, '浓烈的水元素能量积聚成的物质。献给水的神像，能弥补它在漫长岁月中散失的力量。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107024, '礼券秘盒', NULL, NULL, 420001, '存放着「欢兴礼券」的礼盒，有着花朵般的奇特外形，是「琉形蜃境」中独树一帜的景观，也是游客们赢取奖品所需的重要收集物。使用「流悦晶石」与「酣悦晶石」，似乎能更便捷地确定它们的位置…', 'CONSUME', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107026, '苍灵鲤', NULL, NULL, 420021, '由逸散的仙力凝集而成，畅游于山野河谷之间的灵鲤。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107028, '散失的火神瞳', NULL, NULL, 420001, '浓烈的火元素能量积聚成的物质。献给火的神像，能弥补它在漫长岁月中散失的力量。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107029, '欢声飞羽', NULL, NULL, 420001, '如同快乐笑声凝结而成的神奇晶体，呈现出两片书页拼接的姿态，或是自由飞旋的羽毛。触碰之后，便能从中获得「悠乐片段」…\n使用「轻愉信笺」与「欢跃信笺」，似乎能更便捷地确定它们的位置…', 'CONSUME', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107030, '散失的月神瞳', NULL, NULL, 420001, '浓烈的月矩力积聚成的物质。献给新月的神像，能弥补它在漫长岁月中散失的力量。', 'ELEM_CRYSTAL', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107033, '技艺团块', NULL, NULL, 420001, 'test 空之神殿神瞳', 'CONSUME', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (107034, '摹忆因子', NULL, 3, 420001, '构筑「文明」的最小单位。\n任何来自「文明」的造物，从人类的集体记忆中消逝后，皆会裂解为摹忆因子。将其供奉于空之神殿内的摹忆中枢，或许会得到来自隙间记忆的赐福…', 'CONSUME', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110001, '面粉', NULL, NULL, 322, '由小麦磨成的粉末。无论做成怎样的主食，都能给食客的胃带来片刻充实。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110002, '奶油', NULL, NULL, 322, '将牛奶快速搅拌后提制的奶制品。是制作美味糕点时必备的材料之一。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110003, '熏禽肉', NULL, NULL, 322, '经过熏制的禽肉。紧实的肉质带来别样的味觉体验。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110004, '黄油', NULL, NULL, 322, '从牛奶中分离提制的乳脂肪。适当添加，能让哪怕平凡的原料，也散发出甜蜜浓厚的香气。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110005, '火腿', NULL, NULL, 322, '经过熏制的腿部兽肉。薄薄的一片就能带来满嘴的芳香。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110006, '糖', NULL, NULL, 322, '提炼自甜甜花的调味剂。它的甜味仿佛有着与人共鸣的力量，能够驱散内心的阴霾。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110008, '果酱', NULL, NULL, 322, '由水果和糖熬制而成的凝胶物质。只要少许就能轻易唤醒疲惫的味蕾。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110009, '奶酪', NULL, NULL, 322, '由牛奶浓缩发酵制成的奶制品。提供热量的同时，赋予了烹饪无限可能性。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110010, '培根', NULL, NULL, 322, '经过熏制的肋条兽肉。层次丰富、肥而不腻正是它广受欢迎的原因。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110011, '香肠', NULL, NULL, 322, '灌入肠衣后制成的条状兽肉。便于储存的特性，极大地满足了肉食爱好者的日常需要。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110012, '熏鱼', NULL, NULL, 322, '', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110013, '鱼干', NULL, NULL, 322, '', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110014, '香辛料', NULL, NULL, 322, '复合口味的调味剂。由干燥的香辛果加工而成。能为料理赋予多层次的风味，因而坊间有着「万物皆可香辛料」的说法。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110015, '酸奶油', NULL, NULL, 322, '经分离发酵等复杂工艺后得到的奶制品。具有柔滑的质地与清爽的酸味，是许多菜肴中的点睛之笔。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (110016, '黑麦粉', NULL, NULL, 322, '碾碎黑麦后得到的粗糙、深色粉末。用其制作出的食物拥有独特的口感与酸味。', 'EXCHANGE', '食材', NULL, NULL, NULL, '[\"烹饪加工获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111020, '漂亮的小结晶', NULL, NULL, 430051, '合成额外产物', 'CONSUME', '合成产物', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111021, '漂亮的中结晶', NULL, NULL, 430051, '合成额外产物', 'CONSUME', '合成产物', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111022, '漂亮的大结晶', NULL, NULL, 430051, '合成额外产物', 'CONSUME', '合成产物', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111023, '果酿饵', NULL, 2, 340, '十分常见的鱼饵，由日落果与小麦捣碎发酵揉制而成，入水后能够快速雾化，对小型鱼类有着强烈的吸引力。由于其制作简单、价格低廉、效用优秀，因此又被戏称为「钓鱼佬宝珠」。\n\n适用鱼种：鳉鱼类。', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111024, '赤糜饵', NULL, 2, 340, '由血斛和捣碎的肉类混合制成的鱼饵，独特的腥甜味在水中扩散极快，能够吸引个性凶悍的掠食鱼类。但用量需要谨慎，以免引来一些麻烦的坏家伙。\n\n适用鱼种：棘鱼类。', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111025, '蠕虫假饵', NULL, 2, 340, '以凝液为主料制成的蠕虫仿生饵，会随着水中的暗流扭动身姿，对好奇心旺盛的鱼儿有致命的吸引力。行家还会用融入水果的方法来丰富它的香气，简直无鱼能挡了。\n\n适用鱼种：蝶鱼类。', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111026, '飞蝇假饵', NULL, 2, 340, '用颜色鲜艳的材料制成的飞蝇仿生饵，没有气味，是针对视觉灵敏的大型鱼类的特殊鱼饵，通常会配合更高难度的钓鱼手法。某些地区的钓鱼协会，会把活用飞蝇假饵作为干部晋升标准之一。\n\n适用鱼种：假龙类、炮鲀类、鳐类。', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111027, '荧草饵', NULL, 2, 340, '由魔晶矿和海草制成的特殊饵料，会在无光处闪耀，对于那些向往光明的家伙，或许有非凡的吸引力。\n若耗尽可在鲸井椛处重复领取。\n\n适用鱼种：所有鱼类', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"完成鲸井椛任务获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111028, '甘露饵', NULL, 2, 340, '以蔷薇花露为基底的鱼饵，混入了晒干后的香辛果粉，入口辛辣，回味却交织甜蜜。如此滋味，一如钓鱼佬的生活。所谓雨打风吹日暴晒，潮涌波汹浪翻天，经受考验后的收获，才格外令人欣喜吧。\n\n适用鱼种：角鲀类、斧枪鱼类。', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111030, '酸桔饵', NULL, 2, 340, '以小麦粉为基底的鱼饵，混入了泡泡桔的果肉和桔籽，投入水中后，酸甜的香味会迅速弥漫开来，有效吸引诸如心羽鲈之类的鱼儿。据说，曾有钓鱼佬在野外长期驻守时，耗尽了口粮，食用这类鱼饵应急，并不幸中毒…为防这类事故再次发生，此后制作的这类鱼饵大幅提升了酸度，以至于普通人将鱼饵凑近鼻子边，都会被刺激得头晕流泪，根本不可能将它放入口中…\n\n适用鱼种：心羽鲈类。', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111031, '维护机关频闪诱饵', NULL, 2, 340, '极为特殊的「诱捕装置」，传说运用了枫丹科学院某开发组外流的技术。装置外部装有金属制作的保护笼和咬钩筋条，内部则是含有茉洁草提取物的灯具。\n投入水中后，装置内部的灯具会以特定频率闪烁，吸引附近的「维护机关」，也就是人们俗称的「水域维护鱼」或「铁鱼」。「维护机关」们的咬力强大，但也只能咬到外部的特质筋条，并牢牢固定在上边。本质上，这也算得上是一种特别的「鱼饵」，专用于钓获价值不菲的「铁鱼」。\n\n适用鱼种：维护机关类。', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111033, '澄晶果粒饵', NULL, 2, 340, '奇妙的纳塔鱼饵，以澄晶实和颗粒果制成，入水后能长期维持形态，并保证风味物质化开弥漫的速度，持久而高效地吸引鱼类。\n\n适用鱼种：普通急流鱼类、翻车鲀类、普通独角鱼类', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111034, '温火饵', NULL, 2, 340, '奇妙的纳塔鱼饵，以烬芯花和小麦辅以专门的手法制成，据说能在液面下维持特定的温度，从而吸引对此敏感的特殊鱼类。\n\n适用鱼种：燃素鱼类', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111035, '槲梭饵', NULL, 2, 340, '常见的挪德卡莱鱼饵，以夏槲果和面粉制成，对于普通的鱼类有着不错的吸引力…\n\n适用鱼种：巨斧鱼类。', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (111036, '清白饵', NULL, 2, 340, '以白灵果和薄荷制成的鱼饵，暗藏玄机，对于部分鱼类有着视觉和气味的双重诱惑，在鱼师群体中获得了大量好评…\n\n适用鱼种：凶凶鲨类、明眼鱼类。', 'FISH_BAIT', '鱼饵', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112002, '史莱姆凝液', NULL, 1, 10601, '覆于史莱姆体表的浓稠流体，各地元素工坊中最常见的原料。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"史莱姆掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112003, '史莱姆清', NULL, 2, 10601, '略加提纯的史莱姆分泌物，对皮肤有害，请务必避免不加防护措施的接触。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上史莱姆掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112004, '史莱姆原浆', NULL, 3, 10601, '浓缩的史莱姆原浆，静置时会自主进行不规则运动。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上史莱姆掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112005, '破损的面具', NULL, 1, 10602, '破碎的骨质面具，曾经属于某个丘丘人。\n破损的部分比完整的部分更多，已经失去了假面应有的功能。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"丘丘人掉落\", \"丘丘射手少量掉落\", \"丘丘萨满少量掉落\", \"丘丘暴徒少量掉落\", \"丘丘王少量掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112006, '污秽的面具', NULL, 2, 10602, '沾满了难以辨认的污渍，散发着微妙气味的骨质面具。\n即使这样也要戴在脸上，这就是丘丘人的执着。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上丘丘人掉落\", \"40级以上丘丘射手少量掉落\", \"40级以上丘丘萨满少量掉落\", \"40级以上丘丘暴徒少量掉落\", \"40级以上丘丘王少量掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112007, '不祥的面具', NULL, 3, 10602, '光亮的骨质面具，上面涂绘着意在恐吓敌人的油彩。\n丘丘人对面具的执着缘起为何，至今无人能解。一说认为是不愿看见自己在水中的倒影。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上丘丘人掉落\", \"60级以上丘丘射手少量掉落\", \"60级以上丘丘萨满少量掉落\", \"60级以上丘丘暴徒少量掉落\", \"60级以上丘丘王少量掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112008, '导能绘卷', NULL, 1, 10603, '大抵是某种关于魔法的绘卷残篇。隐隐地散发着某种异样的、不祥的温暖。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"丘丘萨满掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112009, '封魔绘卷', NULL, 2, 10603, '模糊地绘制了难解形象的古书断章。通过模仿其中的人物形象，一些魔物能小小地再现魔法的奇迹。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上丘丘萨满掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112010, '禁咒绘卷', NULL, 3, 10603, '绘制着古代形象的古书抄本。鲜有人能解读它的含义；据说最终理解了其中真意的学者都陷入了癫狂。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上丘丘萨满掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112011, '牢固的箭簇', NULL, 1, 10604, '做工粗糙的箭簇。即使如此，也不容小觑：弩是危险的武器，即使贵为骑士，也可能被从后方来的弩矢击倒。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"丘丘射手掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112012, '锐利的箭簇', NULL, 2, 10604, '做工精良的箭簇。锐利的尖端或许能像投石入水一样轻易穿透敌人的甲胄，没入猎物的体内。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上丘丘射手掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112013, '历战的箭簇', NULL, 3, 10604, '老旧的、沾染了干涸血迹的箭簇。箭头在反复的使用中已经失去了应有的锐利，根本不能作为武器使用。\n但它也代表着猎手的骄傲，是它们的护身符与奖章。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上丘丘射手掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112014, '沉重号角', NULL, 2, 10105, '粗砺的号角，是丘丘人用来警告同伴的道具。现在散布在号角上的战损使其失去了发声的功能。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"丘丘暴徒掉落\", \"丘丘王掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112015, '黑铜号角', NULL, 3, 10105, '金属制的魔物号角。通常只能从格外强壮的丘丘人身上获得，因为鸣响号角是需要气力的事情。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上丘丘暴徒掉落\", \"40级以上丘丘王掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112016, '黑晶号角', NULL, 4, 10105, '隐隐反射着不祥光芒的金属号角，饰有材质不明的黑晶。几乎没有使用过，推测是丘丘人重要的仪式器具。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上丘丘暴徒掉落\", \"60级以上丘丘王掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112017, '晦暗刻像', NULL, 2, 10120, '刻画着某人形象的小塑像。\n即使经过了长久的岁月，也没有受到任何损伤。似乎被原本的主人如同圣象一般呵护着。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"黑蛇众掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112018, '夤夜刻像', NULL, 3, 10120, '刻画着某人形象的独目偶像。\n握在手中时似乎能感受到其中散发的丝丝暖意，就像挚友的臂膀那般。或许能给予明白雕像背后个中含义的人持续前进的勇气吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上黑蛇众掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112019, '幽邃刻像', NULL, 4, 10120, '微微散发着不祥的能量的独目刻像，是以何种材质制成则完全不可知。\n凝视着这尊偶像时，似乎能听见令人心情宁静的奇妙低语…\n「看吧，我的孩子。天之座下的万物终将在动荡中消亡。永远宁静的漆黑深空会包容一切。」', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上黑蛇众掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112020, '地脉的旧枝', NULL, 2, 10107, '来自深邃地底的脆弱枯枝。即使饱经岁月，也能从斑驳的树皮下，看出尚未散尽的力量。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"深渊法师掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112021, '地脉的枯叶', NULL, 3, 10107, '来自深邃地底的植物枝条。即使远离它的原主，其中也残留着低沉脉动的力量。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上深渊法师掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112022, '地脉的新芽', NULL, 4, 10107, '据说有一株巨木曾经贯彻了世界的各处；据说这枝是它的一部分。仿佛从未被人折下带到遥远的地表，仍然充满了勃发的生机，长出了新叶。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上深渊法师掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112023, '混沌装置', NULL, 2, 10108, '来自不再活动的古代遗迹构装体。曾经是维系它身躯的某个部位，有着精妙的工学美感。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"遗迹守卫掉落\", \"遗迹猎者掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112024, '混沌回路', NULL, 3, 10108, '来自不再活动的古代遗迹构装体。曾经是驱使它行动的逻辑回路。其中蕴含的伟大技术，如今已经无人可解。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上遗迹守卫掉落\", \"40级以上遗迹猎者掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112025, '混沌炉心', NULL, 4, 10108, '来自不再活动的古代遗迹构装体。曾经是驱动它活动的能源之心。若能理解、重构这样的神秘技术，或许能改变这个世界也说不定。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上遗迹守卫掉落\", \"60级以上遗迹猎者掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112026, '雾虚花粉', NULL, 2, 10109, '雾虚草在密闭空间中会产生的奇妙孢子，是飞萤喜好的食物。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"愚人众·萤术士掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112027, '雾虚草囊', NULL, 3, 10109, '保存完好的雾虚草。有的人会利用飞萤对雾虚草的喜好，来控制它们。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上愚人众·萤术士掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112028, '雾虚灯芯', NULL, 4, 10109, '将本就罕见的雾虚草集结成的束，会散发出幽晦的冥光；提着这种灯的人，则会召来飞萤与不幸。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上愚人众·萤术士掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112029, '猎兵祭刀', NULL, 2, 10110, '某种锋利的合金武具。即便失去了原本的主人，仍反射着令人不安的寒光。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"愚人众·债务处理人掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112030, '特工祭刀', NULL, 3, 10110, '利用至冬国优越的技术制造的异形兵器，曾经属于某位资深特工。一般人不经训练，根本无法使用这种奇怪的武具。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上愚人众·债务处理人掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112031, '督察长祭刀', NULL, 4, 10110, '在故主手中，曾处理过许多「债务」的凶恶武具。世上无人背后长眼，而这种兵器与相关的武艺则是针对这种弱点设计的。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上愚人众·债务处理人掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112032, '新兵的徽记', NULL, 1, 10611, '标识着新兵身份的徽记。不知曾经带着它的人，是怀着何种心情加入愚人众的战争机器的呢。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"愚人众·先遣队掉落\", \"愚人众·债务处理人少量掉落\", \"愚人众·萤术士少量掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112033, '士官的徽记', NULL, 2, 10611, '标识着士官身份的徽记，有着区分一般士兵的奇异造型。其中或许蕴含着复杂的情绪吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上愚人众·先遣队掉落\", \"40级以上愚人众·债务处理人少量掉落\", \"40级以上愚人众·萤术士少量掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112034, '尉官的徽记', NULL, 3, 10611, '标识着尉官身份的徽记。愚人众拥有庞大的军队，能在其中担任尉官者，想必是有过人之处吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上愚人众·先遣队掉落\", \"60级以上愚人众·债务处理人少量掉落\", \"60级以上愚人众·萤术士少量掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112035, '寻宝鸦印', NULL, 1, 10612, '骄傲地标识着盗宝团身份的印记，描绘着他们对宝藏永无止境的追求。话虽如此，盗贼的身份真的需要骄傲地展示吗…？', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"盗宝团掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112036, '藏银鸦印', NULL, 2, 10612, '盗宝团的成员用于相互辨识的乌鸦纹章。盗宝团不问出身，无论何者，只要怀着贪求宝藏的心，有铤而走险的胆识，都可以成为「优秀」的成员。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上盗宝团掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112037, '攫金鸦印', NULL, 3, 10612, '象征着盗宝团唯一的原则与傲骨的徽印。只要广袤的大地上、幽邃的深渊里、未知的海洋中仍有待发掘的秘宝，那么手段不论地征服宝藏的盗宝之魂，就永远不会熄灭。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上盗宝团掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112038, '骗骗花蜜', NULL, 1, 10613, '从花蕊中提取出的花蜜，其中含有少量元素。\n尝起来和甜甜花的味道有些微妙地相似。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"骗骗花掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112039, '微光花蜜', NULL, 2, 10613, '元素纯度较高的花蜜。\n学界一般认为骗骗花是元素植物的高级生命形态，但始终无法解明它的掠食习性。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上骗骗花掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112040, '原素花蜜', NULL, 3, 10613, '饱含能量的黏稠蜜汁。\n骗骗花欺瞒猎物是为了狩猎，而狩猎进食或许是为了进化成某种更强大、更纯粹的姿态吧…', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上骗骗花掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112041, '脆弱的骨片', NULL, 2, 10114, '从龙蜥身上找到的某种骨片。\n尽管十分脆弱，其中似乎蕴含着某种难以言喻的力量。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"幼岩龙蜥掉落\", \"岩龙蜥掉落\", \"深海龙蜥掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112042, '结实的骨片', NULL, 3, 10114, '出于某种理由，龙蜥十分珍惜的某种生物骨片。\n看上去有一定的年头。即使是这种不通人言的龙兽，似乎对这种遗骸也拥有某种特殊的憧憬。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上幼岩龙蜥掉落\", \"40级以上岩龙蜥掉落\", \"40级以上深海龙蜥掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112043, '石化的骨片', NULL, 4, 10114, '击败龙蜥后有时能找到的石化骨片。\n龙蜥都梦想着成长为真正的龙。会把古老的化石认作是龙之骨而加以珍惜，或许是因为希冀着龙的永恒与强大吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上幼岩龙蜥掉落\", \"60级以上岩龙蜥掉落\", \"60级以上深海龙蜥掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112044, '破旧的刀镡', NULL, 1, 10615, '装配在稻妻刀剑上的护具，见证过许多战斗。\n对剑术纯熟者而言，镡可以在实战中阻挡对手的刀刃；而对于新手剑士，镡是保护自己右手的关键。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"野伏众掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112045, '影打刀镡', NULL, 2, 10615, '装配在优秀刀剑上的护具。\n稻妻有悠久的刀剑锻冶传统。匠人锻造一把刀时，常常会制造数柄样品，从中甄选。其中最为优秀的作品是为「真打」，而其余的则被称为「影打」。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上野伏众掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112046, '名刀镡', NULL, 3, 10615, '装配在名刀上的华美护具。\n有人坚信刀剑有灵魂、有生命，这也是为什么人们会为刀起名。爱护刀的人，也会得到刀的赏识。但与刀剑成为挚友、甚至爱人的人，须知这份情义是由杀伐浇灌的。常常浴血、与刀共舞之人，他们的热血最终总会被薄情的钢铁冷却。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上野伏众掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112047, '混沌机关', NULL, 2, 10116, '来自不再活动的古代遗迹机关。\n似乎是拟生机关的动力来源。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"遗迹机兵掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112048, '混沌枢纽', NULL, 3, 10116, '来自不再活动的古代遗迹机关。\n在无法维持机关构装体的结构性之后，其中蕴含的伟大技术与未知力量也失去意义了吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上遗迹机兵掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112049, '混沌真眼', NULL, 4, 10116, '来自不再活动的古代遗迹机关。\n这类机关的「遗迹」之名源自它们热衷的活动区域。但遗迹机关本身与它们所寄居的残垣断壁之间却没有多少共同之处。\n在遥远的过去，遗迹曾经属于伟大的、几乎可以触碰天空穹顶的文明，而「遗迹」则在大地的深处蓄势待发，等待着踏平一切国度的指令下达。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上遗迹机兵掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112050, '黯淡棱镜', NULL, 2, 10117, '原本是能偏转光线的棱镜，在流水般的年岁中渐渐变得黯淡。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"愚人众·冬国仕女掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112051, '水晶棱镜', NULL, 3, 10117, '能够偏转光线的棱镜。\n利用这种棱镜，可以制造虚幻的影像。从某种意义而言，也因此有着操纵人心的力量。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上愚人众·冬国仕女掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112052, '偏光棱镜', NULL, 4, 10117, '能够偏转光线的棱镜。\n在黑暗中，棱镜可以将细微的光明散布到更大的范围里。或许也是因为这样的特性，这种棱镜对于内心常常被黑暗笼罩的人，有着令他们稍稍安心的力量。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上愚人众·冬国仕女掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112053, '浮游干核', NULL, 1, 10618, '能让飘浮灵浮游的能量核，其中含有些微的元素。\n大部分的能量似乎已经逸散了。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"飘浮灵掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112054, '浮游幽核', NULL, 2, 10618, '能让飘浮灵浮游的能量核。\n这种元素生物似乎有奇异的习性，会周期性大量涌现、消失。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上飘浮灵掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112055, '浮游晶化核', NULL, 3, 10618, '击败飘浮灵后有时能发现的完整的能量核。\n在热衷于给任何事物都分个高下的人当中，经常发生这样的争论：飘浮灵和风史莱姆的浮力，究竟孰高孰低。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上飘浮灵掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112056, '隐兽指爪', NULL, 2, 10119, '兽境群狼的残留身体组织。\n按照常理来说，这种与此世不容的事物不应在这种异常造物被驱逐后，残留于世才对。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"兽境之狼掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112057, '隐兽利爪', NULL, 3, 10119, '兽境群狼的身体组织。\n虽然奇妙，但是和大杰作「腐殖层」杜林相比，「淋溶层」猎犬不值一提。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上兽境之狼掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112058, '隐兽鬼爪', NULL, 4, 10119, '兽境群狼的利爪。\n世之奇珍，但是和最高杰作「白垩层」相比，只是寻常之物罢了。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上兽境之狼掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112059, '蕈兽孢子', NULL, 1, 10621, '蕈兽留下的零星孢子粉末，闪烁着点点微光。仿佛只需一个喷嚏，便会被吹散得无影无踪。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"蕈兽掉落\", \"活化状态下蕈兽少量掉落\", \"枯焦状态下蕈兽少量掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112060, '荧光孢粉', NULL, 2, 10621, '小小一包散发着荧光的蕈兽孢子粉末，在雨林之国是一剂常见的药材，往往被商人用纸包封装起来贩售。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上蕈兽掉落\", \"40级以上活化状态下蕈兽少量掉落\", \"40级以上枯焦状态下蕈兽少量掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112061, '孢囊晶尘', NULL, 3, 10621, '从完整的孢子囊中精心收集的大团孢子粉末，想必在合适的环境条件下，将会孕育出一个颇有规模的蕈兽群落吧…', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上蕈兽掉落\", \"60级以上活化状态下蕈兽少量掉落\", \"60级以上枯焦状态下蕈兽少量掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112062, '失活菌核', NULL, 2, 10122, '蕈兽的部分身体组织，在外界元素的剧烈刺激下才会形成。\n手感很好，适合用来解压，但容易造成蕈兽大量孳生，所以不宜商用。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"活化状态下蕈兽掉落\", \"枯焦状态下蕈兽掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112063, '休眠菌核', NULL, 3, 10122, '蕈兽的部分身体组织，在外界元素的剧烈刺激下才会形成。\n生论派的学者们曾对蕈兽究竟属于植物还是动物展开过旷日持久的论战。最后两派达成和解，将蕈兽单列在动植物之外，并不再讨论。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上活化状态下蕈兽掉落\", \"40级以上枯焦状态下蕈兽掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112064, '茁壮菌核', NULL, 4, 10122, '蕈兽的部分身体组织，在外界元素的剧烈刺激下才会形成。\n一般认为，蕈兽之所以演化出移动能力，是为了将孢子散布在更为广泛的天地中。\n曾有诗人称，在蕈兽共同的梦中，孢子覆盖了山岳与海洋，世界无比宁静。蕈兽演化成游鱼、走兽、飞禽、人与神，仰赖雨水、土地与回归土地的同伴而生。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上活化状态下蕈兽掉落\", \"60级以上枯焦状态下蕈兽掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112065, '褪色红绸', NULL, 1, 10623, '用以遮盖眼睛的红色绸缎，略有残破。\n镀金旅团当中常有人以织物遮蔽双眼，而这种举动的肇始早已失落在时之沙海中。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"镀金旅团掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112066, '镶边红绸', NULL, 2, 10623, '镶有简单装饰的红色绸缎。\n老练的战士能够从对手眼神中的破绽，找到先机。镀金旅团早已失去了可效忠的主，能够相信的只有自己。据说，他们坚信万物皆会背叛，连自己的双眼也不例外。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上镀金旅团掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112067, '织金红绸', NULL, 3, 10623, '以金丝织成纹路的红色绸缎。\n在日光之下如同镀金的沙漠当中出生的遗民，偶尔会唱起含义已被遗忘的歌谣，赞美平等照耀大地的烈日，痛惜黄昏之末的余晖。在歌谣的终章反复出现的陌生词汇，据说是古老神明的名讳。据说，沙漠之王尚在时，子民们不敢直视太阳般的光辉，因而遮住了自己的双目。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上镀金旅团掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112068, '混沌容器', NULL, 2, 10124, '来自不再活动的古代遗迹龙兽。\n遗迹龙兽可以吸收外界的元素能量，并储存在「颈部」的构件中。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"遗迹龙兽掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112069, '混沌模块', NULL, 3, 10124, '来自不再活动的古代遗迹龙兽。\n「龙」是最为原始、古老的顶级元素受肉之形态，直到它们被击溃、被征服，抑或是被同化。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上遗迹龙兽掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112070, '混沌锚栓', NULL, 4, 10124, '来自不再活动的古代遗迹龙兽。\n已经失落的古国之中，曾有一派人醉心于拟生之原理。无论是无相的纯粹秩序元素，或是龙的亘古原始力量，都应当加以拟造、改良，最终达成超越。\n如此便能以更为优越的无垢之身，取代终将朽败、终将破碎的秩序。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上遗迹龙兽掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112071, '破缺棱晶', NULL, 2, 10125, '打倒元能构装体后获得的破碎零件。\n这些造型特异的机械是沙漠遗迹永恒的守护者，具有足以凿穿岩山，重塑巨石的力量。驱动这些机械运作的原理与地上、地下许多神秘的机关相似。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"元能构装体掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112072, '混浊棱晶', NULL, 3, 10125, '打倒元能构装体后获得的老旧零件。\n据说这些机械与同样来自沙海深处的「遗迹机关」不同，并不是作为歼灭与征服的使者被制造出来的。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上元能构装体掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112073, '辉光棱晶', NULL, 4, 10125, '打倒元能构装体后获得的精巧零件。\n荒漠的王曾经做过一个梦，也做出过许多许诺。\n在荒漠的传说中，这些机械的造物原本是践行诺言的道具，如今也只有它们的机械记忆体中刻写着无人记得的梦与承诺吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上元能构装体掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112074, '残毁的横脊', NULL, 2, 10126, '圣骸兽脊背上残毁的骨壳。\n昔日遍布四方之土的灾厄之证，如今唯有在人迹罕至之处方能寻得踪影。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"圣骸兽掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112075, '密固的横脊', NULL, 3, 10126, '圣骸兽脊背上坚实的骨壳。\n噬啮殒落的伟大生灵之躯骸，并藉此升衍的灾兽之骨。纵然窃得昔日权能的片影，兽群终究无法逃过与诸神相同的终局。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上圣骸兽掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112076, '锲纹的横脊', NULL, 4, 10126, '圣骸兽脊背上铭镌着古老徽记的骨壳。\n琅霜般净固的骨壳上，依稀萦绕着遥世的遗恨。终有一日，兽骨会在时之风中散作白灰，而那旧日倾殒的高贵者，最终也会迎来安眠之日吧…', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上圣骸兽掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112077, '来自何处的待放之花', NULL, 2, 10127, '丘丘游侠曾珍视的野花。在开放前就被摘下了。\n它在荒野的巡礼中并不携带任何多余的物品，除了这朵未开之花。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"丘丘游侠掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112078, '何人所珍藏之花', NULL, 3, 10127, '丘丘游侠曾珍视的野花，并不具有什么特别之处。\n花朵在许多文明当中都是表达心意的赠礼或谢礼。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上丘丘游侠掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112079, '漫游者的盛放之花', NULL, 4, 10127, '丘丘游侠曾珍视的盛放野花，并不具有什么特别之处。\n永恒的异乡人从不索要酬劳，所行所为最终都将开花结果…', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上丘丘游侠掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112080, '异海凝珠', NULL, 1, 10628, '击败原海异种后，从其体内取得的细小晶体。\n原海异种依托枫丹的「海」而生，推测是因为水中奇异的能量而形成独特形态的生命体。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"原海异种掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112081, '异海之块', NULL, 2, 10628, '击败原海异种后，从其体内取得的结晶体。\n散发着些微神秘的能量。\n尽管传说在航道与人迹所不及的远海中存在着伟大的生命，但寻常的海洋不过乏善可陈，生命力远远不及枫丹的「海」。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上原海异种掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112082, '异色结晶石', NULL, 3, 10628, '击败原海异种后，从其体内取得的大颗结晶。\n其中蕴含着神秘的能量。\n尽管是万水之源，但枫丹之水流向异国之后却失去了其独特的性质。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上原海异种掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112083, '啮合齿轮', NULL, 1, 10629, '发条机关的齿轮。\n是传动所需的重要零件。一旦缺失，对应模块的功能便无法运作。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"发条机关掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112084, '机关正齿轮', NULL, 2, 10629, '发条机关的齿轮。\n尽管发条机关在运动学上经历了许多突破，但动力学上迄今未能突破四百多年前阿兰·吉约丹所立下的根基与框架。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上发条机关掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112085, '奇械机芯齿轮', NULL, 3, 10629, '发条机关的齿轮。\n加工精度与材料学的进步是枫丹发条机关进步的关键。在先进设备的支持下，任何工程师都有制造出超越「奇械公」吉约丹时代机械的可能。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上发条机关掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112086, '浊水的一滴', NULL, 2, 10130, '击败浊水幻灵后，取得的一小滴水。\n其中的生命力似乎尚未完全消散。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"浊水幻灵掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112087, '浊水的一掬', NULL, 3, 10130, '击败浊水幻灵后，取得的水。\n其中的生命力似乎尚未完全消散。\n过去的纯水精灵如今在枫丹已经绝迹，从水中升起的只有这些不具备优美形态的奇异元素生命体。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上浊水幻灵掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112088, '初生的浊水幻灵', NULL, 4, 10130, '击散浊水幻灵后，即将再度升起的新生命体，被装在了禁锢的瓶中。\n水中所蕴含着的生命是无形的，而无形的生命也寄于水中，借由水之形诞生。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上浊水幻灵掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112089, '隙间之核', NULL, 2, 10131, '隙境原体留下的碎屑。\n与地上任何生命形式都不具备相似之处。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"隙境原体掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112090, '外世突触', NULL, 3, 10131, '隙境原体留下的碎屑。\n这种异形生命体的根源是厄里那斯，活动范围也以厄里那斯为主。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上隙境原体掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112091, '异界生命核', NULL, 4, 10131, '隙境原体留下的核心。\n这种生命体并没有彻底消灭的手段，即使只剩下核心也会在翌日，或是数十年后再度复生。所幸似乎没有很强的攻击性与智性，所以枫丹人对其大多采取的是敬而远之的态度。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上隙境原体掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112092, '老旧的役人怀表', NULL, 2, 10132, '配发给愚人众役人的制式怀表。\n猎壳上徽记的磨损与氧化褪色忠实地记录着身为执行者，所度过的时日。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"愚人众·役人掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112093, '役人的制式怀表', NULL, 3, 10132, '配发给愚人众役人的制式怀表。\n怀表把头的位置设计并不合理，外壳过多的棱角也容易将衣物磨破，所以总有人会将其中的机芯装配在更加朴实、缺乏特征性的壳套中使用。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上愚人众·役人掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112094, '役人的时时刻刻', NULL, 4, 10132, '装载着「邪眼」的饰物，是愚人众役人元素力量的来源。\n但即使将之取下，役者仍然有着远超常人的身体素质，这些都来自漫长岁月的训练与实战经验；而她们往往清楚，自己的过去、现在与未来已经奉献给了愚人众的理想国，驱使邪眼的力量所带来的折损因此也不值一提。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上愚人众·役人掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112095, '羽状鳍翅', NULL, 2, 10133, '击败玄文兽后，从其背上取得的鳍翅残片。\n尽管不具备长距离飞行的能力，这些如同鸟羽一般的鳍翅依然能让玄文兽在驰逐猎物时更为迅疾。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"玄文兽掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112096, '月色鳍翅', NULL, 3, 10133, '击败玄文兽后，从其背上取得的鳍翅。\n其上隐隐折射着如月色般温润的幽光，不知为何给人一种宁谧感。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上玄文兽掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112097, '渊光鳍翅', NULL, 4, 10133, '击败玄文兽后，从其背上取得的华美鳍翅。\n其上折射着幽邃的微光，能隐隐感受到仙力的痕迹。更深夜静之时，即便是凶暴的野兽亦会短暂沉入宁谧的安眠，追忆「梦」尚不独属于人的年岁。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上玄文兽掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112098, '残毁的剑柄', NULL, 2, 10134, '自古老雕像上取得的的石质剑柄。\n在海水的冲刷下已彻底残毁，失去了曾经的光泽。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"魔像禁卫掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112099, '裂断的剑柄', NULL, 3, 10134, '自古老雕像上取得的的石质剑柄。\n剑柄上的断口与刻痕似乎记录了其主人曾经历过的残酷战斗。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上魔像禁卫掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112100, '未熄的剑柄', NULL, 4, 10134, '自古老雕像上取得的的石质剑柄。\n或许是因为刚刚离开其主人的缘故，剑柄中的火光还尚未熄灭。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上魔像禁卫掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112101, '稚嫩的尖齿', NULL, 1, 10635, '纳塔龙众脱落的牙。\n尚显稚嫩的牙齿，如果有从牙齿判断主人年龄的方式的话，或许就能看出这枚牙齿的主人并未在世上经历太久的岁月。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"纳塔龙众掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112102, '老练的坚齿', NULL, 2, 10635, '纳塔龙众脱落的坚牙。\n其上的磨损见证了其主人曾经历的生活与战斗，拥有这等牙齿的龙，想必在纳塔的诸多龙众中，也能被称为了不起的战士吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上纳塔龙众掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112103, '横行霸者的利齿', NULL, 3, 10635, '纳塔的强龙脱落的尖锐利齿。\n旁生的锯状结构与其狰狞的形态，可窥见其主人在战斗中的蛮勇。拥有这等牙齿的龙，想必在纳塔诸多龙众中，可称得上是横行无忌的霸者了吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上纳塔龙众掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112104, '卫从的木哨', NULL, 1, 10636, '纳塔部族卫从的象征。\n战士并非一开始就是战士，得先跟从真正的战士们学习战斗的技巧，这就是部族中「卫从」这一见习职位的由来。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"部族龙形武士掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112105, '战士的铁哨', NULL, 2, 10636, '纳塔部族战士的象征。\n正式成为部族战士后能够拥有的铁哨。在部族周围巡游，一旦出现危险就用哨声互相通知呼应。这就是部族中「战士」需要履行的职责。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上部族龙形武士掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112106, '龙冠武士的金哨', NULL, 3, 10636, '纳塔部族中，获授龙冠的强大武士的象征。\n只有为部族争取到了足够的荣誉，其勇武得到承认之后，才会得到的金哨。但此时其装饰的意义已经高过实际使用的意义，因为头戴龙冠的武士可以独自解决大部分的危机。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上部族龙形武士掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112107, '意志破碎的残片', NULL, 2, 10137, '大灵显化身寄宿的残片。\n破碎的石偶断片，其承载的「大灵」意志与力量也十分有限。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"大灵显化身掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112108, '意志明晰的寄偶', NULL, 3, 10137, '大灵显化身寄宿的玉偶。\n能够隐约看到形制的玉偶雕像，能够承载更多「大灵」的意志与力量。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上大灵显化身掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112109, '意志巡游的符像', NULL, 4, 10137, '大灵显化身寄宿的黑曜石符像。\n环绕黑曜石的玉偶雕像，据说从前的人经常用这样的雕像，尝试与夜神国度中的「大灵」进行沟通，或许这也是「大灵」能够凭依在其上，并显化出形体的缘由吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上大灵显化身掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112110, '聚燃的石块', NULL, 2, 10138, '击败熔岩游像之后，从其体内取得的碎块。\n即使已经破碎到了这个程度，其中的燃烧也并没有停止，或许是因为燃素所具备的超常活力所致。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"熔岩游像掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112111, '聚燃的命种', NULL, 3, 10138, '击败熔岩游像之后，从其体内取得的聚燃堆。\n散发着些微的热量。\n到了这种规模的石堆，已经很难阻止其不断燃烧下去了。据说，这就是某种生命初始的形态。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上熔岩游像掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112112, '聚燃的游像眼', NULL, 4, 10138, '击败熔岩游像之后，从其体内取得的核心。\n散发着相当的热量。\n据说只要形成这样的核心，放置不管就会形成新的熔岩游像。古老的文明一度认为生命的所有形式来源于火的燃烧，认为灵魂与智慧的起源即是聚燃的火种。熔岩游像这一生命体或许印证了这样的说法，又或者，是那样的理论使它诞生在了纳塔的大地上…', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上熔岩游像掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112113, '秘源轴', NULL, 2, 10139, '来自不再活动的秘源机兵。\n看上去只是两个机关之间的承接结构。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"秘源机兵·寻捕械掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112114, '秘源机鞘', NULL, 3, 10139, '来自不再活动的秘源机兵。\n看上去是承载秘源机械体运作的机关，但其核心之处空空如也。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上秘源机兵·寻捕械掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112115, '秘源真芯', NULL, 4, 10139, '来自不再活动的秘源机兵。\n看上去是完整的驱动秘源机械体运作的核心，似乎是作为通用的组件而被制造出来的奇特装置。传说古老文明的伟大住民会用金纹创生的智慧勾勒奇异机械体运作的蓝图，或许这核心也是其中之一吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上秘源机兵·寻捕械掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112116, '折光的胚芽', NULL, 2, 10140, '名为深邃拟覆叶的魔物在被击败后所掉落的芽叶。\n据说这种魔物自黑潮之中诞生时，最先生长而出的，就是这样能使元素的力量偏转的嫩芽。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"深邃拟覆叶掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112117, '惑光的阔叶', NULL, 3, 10140, '名为深邃拟覆叶的魔物在被击败后所掉落的箭形叶片。\n在侵蚀地脉并抽取其中的记忆后，魔物所生长出的承载自身解析出信息的载体。魔物能够拟态复现何种形态，或许与这些具有复杂纹路的枝叶息息相关。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上深邃拟覆叶掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112118, '迷光的蜷叶之心', NULL, 4, 10140, '名为深邃拟覆叶的魔物在被击败后所残余，由蜷缩在一起的叶片构成的核心。\n即使已如生机尽失般黯淡下去，但是仍能感受到其中隐约鼓动的不祥之力。\n时常有人感到困惑，当此种魔物被消灭时，它从大地之中汲取的那些记忆都去往了何处？或许这枚核心提供了这一问题的答案。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上深邃拟覆叶掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112119, '冷裂壳块', NULL, 2, 10141, '击败炉壳山鼬后，从其背上取得的背壳的残片。\n一度燃烧，但此时已经冷却的背壳的裂块，已经失去其中原本蕴藏的如火的光彩。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"炉壳山鼬掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112120, '蕴热的背壳', NULL, 3, 10141, '击败炉壳山鼬后，从其背上取得的背壳的部分结构。\n炉壳山鼬会在背壳之后蕴积进食所得的燃素，以备不时之需，燃火的鼬兽在圣山中腾跃时的一抹焰色，或许是长久以来都未曾被人窥得的风景吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上炉壳山鼬掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112121, '明燃的棱状壳', NULL, 4, 10141, '击败炉壳山鼬后，从其背上取得的完整的背壳碎块。\n据说在一个种群之中，地位越高的炉壳山鼬，其背后蕴藏的燃素会更多，而地位越低越弱的个体，背后蕴藏的燃素越少。形成这个现象的原因也许很好解释：地位越高的炉壳山鼬，需要运用到背后积蓄的燃素的机会或许永远没有地位低的个体那样多吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上炉壳山鼬掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112122, '毁损机轴', NULL, 1, 10637, '在战斗中损毁的巡陆艇机轴。\n即便是精密的工艺也难以胜过高强度的磨耗，正如无论何等宏伟的理想也难以挽回因他人理想而枉死之人的性命。况且量产的机关称不上精密，量产的理想也难称是理想。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"巡陆艇掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112123, '加固机轴', NULL, 2, 10637, '经过加固处理的巡陆艇机轴。\n无数的损毁报告才换来这微不足道的改良。从某种意义上来说，帝国军械宫的行政体制也许比它所制造的机械本身还要复杂数十倍，毕竟即便是最先进的巡陆艇，也不需要消耗数月甚至数年的时间来制造。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上巡陆艇掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112124, '精制机轴', NULL, 3, 10637, '由设计局精制的巡陆艇机轴。\n在北国的工程师规划的图纸上，这不起眼的小东西曾经是象征着荣耀与技术进步的完美杰作，无数世代智慧的成果凝结在这小小的金属元件之中。于是它就这样散落在冰冷的泥土中，等待下一次的回收。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上巡陆艇掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112125, '磨损的执凭', NULL, 1, 10638, '配发给愚人众特辖队的执凭。\n不知持有它的人，怀抱了怎样的决意加入这支队伍。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"愚人众特辖队掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112126, '精致的执凭', NULL, 2, 10638, '配发给愚人众特辖队的执凭。\n精致造型的背后，或许也有执凭的主人为了晋升所付出的代价吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上愚人众特辖队掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112127, '霜镌的执凭', NULL, 3, 10638, '配发给愚人众特辖队的执凭。\n镶嵌着霜色晶石的执凭是荣耀的象征，想必执有凭证者已在过去的行动中证明了自己的忠诚与价值。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上愚人众特辖队掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112128, '霜夜的残照', NULL, 2, 10142, '击败霜夜灵嗣后，从其角冠上取得的残片。\n传说在遥远的过去，这些高贵的生灵亦是黄金之城的侍仆，辉映于其瞳中的乃是至圣至耀的天光。如今那缕残光早已熄灭，而失却了旧主的灵嗣依然漫行于月下的霜夜，守望无人铭记的誓言。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"霜夜灵嗣掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112129, '霜夜的柔辉', NULL, 3, 10142, '击败霜夜灵嗣后，从其角冠上取得的碎块。\n在霜月之子最古老的口头传承祷歌中，这些高贵生灵的辉光曾被终北的哲人称作神使无垢的垂怜。尽管垂怜最终未能阻止黄金城的覆灭，也未能让她的后裔免于流离于荒野的命运，但那柔辉依然流淌在角冠上，等待着也许不会再度降临的梦。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上霜夜灵嗣掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112130, '霜夜的煌荣', NULL, 4, 10142, '击败霜夜灵嗣后，从其角冠上取得的骨甲。\n其上萦缠着如月光般柔润的温存，即便是在寒夜最深之时亦不会消退。从某种意义上来说，与霜月之子一样，这是这些高贵的生灵最后的坚守。它们侍奉的旧主已经殒入尘埃，它们的梦中却依然辉耀着金色的煌荣。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上霜夜灵嗣掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112131, '失光块骨', NULL, 2, 10143, '自蕴光的魔兽体表，取下的黯淡骨块。\n浸润古老月之力的魔兽生长出来的外骨的碎块，已经失去其中蕴藏的隐秘与一度显曜的光亮。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"蕴光异兽掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112132, '稀光遗骼', NULL, 3, 10143, '自蕴光的魔兽体表，取下的散发微光的骨块。\n仍然残留一部分古老月之力的外骨遗骸，在其中能看到因月之力浸润已久，即使已脱离了本体许久仍无法褪去的深邃颜色。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上蕴光异兽掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112133, '繁光躯外骸', NULL, 4, 10143, '自蕴光的魔兽体表，取下的散发着清凉光芒的巨大骨块。\n曾受古老月之力恩赐的魔兽，能够通过这种在漫长岁月中浸入深髓中的光亮，操纵生长而出的外骨，对它们来说，即使并未完全在生理结构上连接，但浮于体表的外骨仍然是可随心念驱使的身躯的一部分吧。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上蕴光异兽掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112134, '幽雾化形', NULL, 2, 10144, '在狂猎的迷雾中寻得的碎块。\n如同雪花一般，是由来自异界的漆黑力量显化凝结而成的。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"荒野狂猎掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112135, '幽雾片甲', NULL, 3, 10144, '在狂猎的迷雾中寻得的甲片。\n曾是狂猎魔物所着盔甲的一部分，不知为何没有随着迷雾一同消失。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上荒野狂猎掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112136, '幽雾兜盔', NULL, 4, 10144, '在狂猎的迷雾中寻得的兜鍪。\n或许是因为来自异界的不洁存在汲取了地脉中古老的记忆，造型与失落古国的遗物颇为相似。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上荒野狂猎掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112137, '深黯的裂眼', NULL, 2, 10145, '自异界侵入的钓客，在形体消散后留下的残屑。\n表壳碎裂后，寄宿在其中的恶意也随之消泯。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"深黯钓客掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112138, '深黯的怪核', NULL, 3, 10145, '自异界侵入的钓客，在形体消散后留下的残屑。\n机能已然停止的核心，与地上任何生物的器官组织都没有相似之处。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上深黯钓客掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112139, '深黯的钩喙', NULL, 4, 10145, '自异界侵入的钓客，在形体消散后留下的残屑。\n形如禽类的钩喙，乃是天外的捕食者们用于储存所攫获生物质的容器。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上深黯钓客掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112140, '失色的焰剑', NULL, 2, 10146, '辖域守护者所持的焰剑熄灭后遗留下的剑柄。\n发火焰的宝剑是守护的象征，依仗「空」之权柄，封锁了永恒与须臾的边界。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"辖域守护者掉落\", \"星尘兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112141, '残失的焰剑', NULL, 3, 10146, '辖域守护者所持的焰剑熄灭后遗留下的剑柄。\n发火焰的宝剑是审判的象征，依仗「空」之权柄，封堵了逾越与亵渎的道路。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"40级以上辖域守护者掉落\", \"星尘兑换\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (112142, '宝饰的焰剑', NULL, 4, 10146, '辖域守护者所持的焰剑熄灭后遗留下的剑柄。\n发火焰的宝剑是戒谕的象征，依仗「空」之权柄，宣告了绝对且无谬的神意。', 'AVATAR_MATERIAL', '角色与武器培养素材', NULL, NULL, NULL, '[\"60级以上辖域守护者掉落\", \"星尘兑换：兑换后合成\", \"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113001, '飓风之种', NULL, 4, 11101, '无相之风被击败后，所坍缩成的形态。其中蕴含着至纯的风之力。\n传说在纤细脆弱的蝴蝶体内，也藏有引发飓风的力量。这由纯粹的风构成的蝴蝶，无疑在等待着再次召来暴风的那一天吧。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上无相之风掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113002, '雷光棱镜', NULL, 4, 11101, '无相之雷用于汇聚元素，修复损伤的元素物质。其中蕴含着至纯的雷之力。\n棱镜能将构成光的色彩区分，而雷光棱镜将奔流的能量编织成纯粹的雷光。即使无相之雷已经被击败，雷元素也持续在这只棱镜中汇聚。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上无相之雷掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113003, '东风之翎', NULL, 5, 11101, '从蒙德的东风之主身上，取下的一枚翎羽。\n那是经历了千年之风的龙之羽。追求自由的本心使它几乎唤起轻风，好逃离现今的桎梏；但它的旧主对你的赏识，使它留在了你的掌心里。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上风魔龙挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113004, '东风之爪', NULL, 5, 11101, '从蒙德的东风之主身上，取下的一丝锋锐。\n因为过去撕裂了伟大魔龙「杜林」的血肉的缘故，过去蕴含着骇人的猛毒。但经过你的净化与治愈，其中躁动的毒性终于平息。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上风魔龙挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113005, '东风的吐息', NULL, 5, 11101, '从蒙德的东风之主唤起的狂风中，采来的些许力量。\n它的身躯是优美而通透的，信风与龙卷都愿为它效力。只要乘风而行，风就是它的同伴、它的歌声与它的自由。\n而它的敌人，就是一千种名字各异的风的敌人。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上风魔龙挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113006, '北风之尾', NULL, 5, 11101, '从北风的伟大王狼身上，取来的些许尾鳞。\n失去了生命与形体的北风王狼仍有超越凡俗的伟大力量。为了迎接挑战而用冰与风复现的形体也无法容下它的全部，少数灵魂附在了在战斗中脱落的冰鳞上。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上北风狼挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113007, '北风之环', NULL, 5, 11101, '从北风的伟大王狼身上，取来的些许凝冰。\n这片大地曾经北风呼啸，呼气凝霜。如砂砾的冰与雪在寒风中嚣叫，飞舞着将肌肤撕裂，让血液凝结。如今的北风王狼力量虽然不如往昔，却仍有能将大地冰封的力量。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上北风狼挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113008, '北风的魂匣', NULL, 5, 11101, '从北风的伟大王狼之灵处，取来的些许力量。\n这片大地上曾经北风呼啸，呼气凝霜。但它在最终终于明白，酷烈的北风只能熄灭生命，不能滋养生命。在生命的末尾，它让自己的力量流入这片大地，永远守护大地与大地的住民。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上北风狼挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113009, '玄岩之塔', NULL, 4, 11101, '无相之岩的外壳构成的石柱。由纯粹的岩元素高度浓缩而成。\n岩元素是最为沉重的元素。无相之岩将外壳筑成高耸的岩柱，将自己抬升至高处，或许不仅是为了应敌。或许也是为了更加接近与它无缘的天空吧。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上无相之岩掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113010, '极寒之核', NULL, 4, 11101, '急冻树被击败后，裸露出的原核。其中蕴含着纯净的冰元素。\n在大地深处中奔涌的能量与思念终归会喷发。就连哀思般沉寂的寒霜，也会附着在地面上的生命形态当中；即使原本不该狩猎生灵的藤蔓植物，也会变得庞大而凶悍吧。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上急冻树掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113011, '常燃火种', NULL, 4, 11101, '驱动爆炎树持续燃烧的种子。仿佛要点燃世间的一切草木般放射着火元素的热量。\n大地深处湍流不息的能量中运载着无穷的愿望。挟着烈火凭依在植物上，使它恒常地燃烧，并且渴望用爆裂的火炎洗净一切的，又是什么样的愿望呢。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上爆炎树掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113012, '净水之心', NULL, 4, 11101, '纯水精灵留下的永远透彻的一掬水。\n即使溶在了湖泊中，它的纯净也不会被稀释吧。但高洁如此的纯水精灵，又是为何渴望着地上生灵的模样，以净水模拟成生物的姿态呢，即使不需要呼吸、也不需要进食…', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上纯水精灵掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113013, '吞天之鲸·只角', NULL, 5, 11101, '战胜解放了邪眼之力的「公子」后，取来的水鲸之角。\n传说中，命之座的图形反映着人的气质。而巡弋漆黑夜空的星辰之鲸，恐怕映照出的是粉碎一切、吞噬一切的狂傲理念吧…\n而接受了这一面的他，欣然唤出灭世的水之鲸，投身与你的战斗。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上公子挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113014, '魔王之刃·残片', NULL, 5, 11101, '战胜解放了邪眼之力的「公子」后，得到的武器破片。\n因为曾经抵达无穷的至暗之地，以少年的双眼目睹了那个国度的漆黑，因此不可逆地染上了不应属于这个世界的深邃色彩。\n纵使「邪眼」的力量与其无关，但物似主人形…', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上公子挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113015, '武炼之魂·孤影', NULL, 5, 11101, '战胜解放了邪眼之力的「公子」后，取来的些许力量。\n经过无尽历练的气势与战意在全力的厮杀中喷涌而出，物质化的产物。\n倘若人类拥有命运，那恐怕他的命运也为之歪曲了吧。否则，他又为何总是身处斗争的漩涡中心呢。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上公子挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113016, '未熟之玉', NULL, 4, 11101, '从古岩龙蜥处取来的结晶物质，蕴含着成为龙的可能性。\n沉眠在山岳中的龙蜥体内，会析出这种黯淡的晶石。璃月有坊间传说认为，力量随着年月积聚，而这种晶石最终会取代原本的心脏，而龙蜥也会成为真正的龙，撼动山岳、撕裂大地。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上古岩龙蜥掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113017, '龙王之冕', NULL, 5, 11101, '千年刚玉凝成的结晶之角，乃是「龙王」的天生冠冕。\n注之以精魄，塑之以顽岩。它自山涧而生，在群岩的国土彰示天地的威权，而黄金般的长角则是它在过去与某位君王分庭抗礼的标志。\n曾一度裂折失色，如今却在你的手中闪烁着冰冷的黄金光泽。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上若陀龙王挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113018, '血玉之枝', NULL, 5, 11101, '闪烁着特异色泽的骨质枝条，以「龙王」的力量滋养而生。\n憎恨淌过天成的泉道，交汇冰冷的月光，令晶化的枝桠舒展而生…\n即使在战斗中已被斩落，龙血滋养的枝叶仍在簌簌作响，永无宁时。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上若陀龙王挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113019, '鎏金之鳞', NULL, 5, 11101, '玄岩之中自然而生的鳞甲，坚韧而沉默，蕴含着「龙王」的威能。\n在无数代蝼蚁归于腐土的岁月中，黄金与黑曜嵌入磐石造就的血肉，蔓延盘生而成甲胄。\n炽热的痛感，无声的呼号，或许皆会在恩怨终结的一刻消散吧。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上若陀龙王挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113020, '晶凝之华', NULL, 4, 11101, '无相之冰绽开的极寒瞬间，凝结而出的至纯冰晶。\n冰霜的结晶永远依凭着冰冷的定则生长、盛放，最终开出冻结一切的凛冬之花。或许滞顿的时间，无法解冻的幽怀，才应当是永存不灭之花的真谛。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上无相之冰掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113021, '异梦溶媒', NULL, 4, 410011, '能够使追忆与试炼中取得的角色培养素材发生变质，使其变为所需要的形态。\n曾经人们相信灵魂和记忆也是有其质料的。如果曾经有人梦到过天堂，醒来后取出了一朵花，那它应该就是由此构成的。异梦溶媒可以溶解回忆中取得的东西，并且将其变成另一种梦。\n与强者交手的回忆，的确成为了更强之路的砖石。', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"【征讨领域和北风的王狼】挑战奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113022, '魔偶机心', NULL, 4, 11101, '能够驱动无机质的机关魔偶剑鬼，使它如同生者一般挥舞刀剑的核心。\n无论是如何精湛的武艺、多么美丽的记忆，也会随着肉体的衰败而凋零。\n恐怕只有将自己的四肢、躯体都换成牢固的机关，最终将心脏换成精密的「机心」，才能比凡骨肉胎更加接近永恒吧…', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上魔偶剑鬼掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113023, '恒常机关之心', NULL, 4, 11101, '驱使恒常机关阵列自律行动的核心。\n有人推测这种核心上的纹样当中以肉眼不可见的语言写上了智能与逻辑，也有人进一步认为这种特殊的遗迹机关因为格外庞大的核心与复杂的纹样，自发选择抛弃了生物的姿态，转而追求性能的强大。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上恒常机关阵列掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113024, '阴燃之珠', NULL, 4, 11101, '无相之火坍缩成的结晶，不断散发着热量。\n炽热的火焰终有一天会冷却，而熄灭的柴薪也会随着意志而再度熊熊燃烧。无相之火不断的冷却与复燃、消散与凝聚也是这个世界意志的一部分吧，就如同宇宙万物的生生不息。直到漆黑的命运终有一日降临，将森罗万象归于空无为止。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上无相之火掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113025, '熔毁之刻', NULL, 5, 11101, '战胜解放了原本力量的「女士」后，得到的某种蕴含着强大力量的畸形碎片。\n「我做了一个很长的梦。\n「我梦见我与你，在我们缔造的纯白世界中再会。\n「但我终于醒来了。我早已经被烈火吞没。你早已与毒血一同回归大地。\n「不过都无所谓了。要不断往前走，就要烧毁身后的一切，就要相信他所说的永远纯白无瑕的国度，在地平线的尽头，『陛下』的梦中，在他让我看见的『妄念』里。」', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上女士挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113026, '狱火之蝶', NULL, 5, 11101, '战胜解放了原本力量的「女士」后，得到的某种蕴含着温暖的力量的畸形碎片。\n应激的冰之封印被打破，过往的意志冲破苍白的囚牢，她再度想起自己原本的名字时，不死蝶会随着血肉焚毁一同逸散飞舞。而她也想起了漫游大地，散布烈焰，烧尽一切罪恶的过去，以及自己未能再见的那个人的面貌。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上女士挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113027, '灰烬之心', NULL, 5, 11101, '战胜解放了原本力量的「女士」后，得到的某种蕴含着强大思念的畸形碎片。\n即使是泪水也无法使火焰熄灭。铁水般炽热的哀伤与愤怒在她的血管中奔涌，从泪腺中迸发。\n在她的心脏被永恒之火烧尽前，最初的愚者找到了她。他明白，只有更加深刻的仇恨与妄执，才能熄灭吞噬她的火焰，让她成为自己的同伴…', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上女士挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113028, '排异之露', NULL, 4, 11101, '无相之水坍缩后，留下的奇异水珠。\n具有强烈的排异本能，也是无相之水的攻击手段之一。据说水中蕴含着记忆与意志，也能随水体的融合获得成长。然而无相之水唤出的浪潮，与地上地下一切湍流之物皆不相容。哪怕落入佩特莉可那无比纯粹的水中，这滴水也会像水银一般抗拒着周遭的融合吧。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上无相之水掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113029, '雷霆数珠', NULL, 4, 11101, '雷音权现留下的，蕴含电气的雷之珠。\n传说雷音权现只会随着雷霆降生在遗留着强大忿恨的土地上。驱使它永远地徘徊在破碎的土地上，释放贯天之雷的，在歌人的故事中往往是生命无法承受的失望与痛苦。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上雷音权现掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113030, '兽境王器', NULL, 4, 11101, '战胜王兽后，得到的折断犄角。在它遭到驱逐后，不应残留在此世才对。\n即使在兽境群狼中贵为王兽，在魔兽的系谱中也不及其兄长们的万分之一吧。\n「黄金」将无数兽境的群狼如同将弃置的画纸一般压缩后而意外产生的畸形魔兽，而寄寓在其犄角中的是足以号令黑色的狼群为它溶解空间的权威。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上黄金王兽掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113031, '龙嗣伪鳍', NULL, 4, 11101, '击败深海龙蜥之后，可以拾取到的一截生物组织。\n虽然看起来像是鲨鳍，但其实并不发挥什么作用。\n曾经的白夜国之民对深海龙蜥有深入的研究。它们最为不同的一点就是可以靠意志决定自身特征的去留与遗传。因为厌恶人造光源，龙蜥成年就会失去视觉上的大部分细节；同时为了战斗，它们进化出了其他元素的行为多型性。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上深海龙蜥之群掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113032, '凶将之手眼', NULL, 5, 11101, '从净土中取回来的人偶关节，这一部分乃是象征着「所见即所为」的手眼造型。\n已经化做祸神的「她」，同样可以驾驭此等手眼神通。目光所见之瞬间，便已斩出一刀。\n然而万劫太过久远，凶将之骸亦得春生。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上永恒的守护者挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113033, '祸神之禊泪', NULL, 5, 11101, '从净土中取回的人偶关节，这一部分乃是「恶曜之眼」的造型。\n仅仅依靠凝视就可以降下灾祸与诅咒，因此把人生之不顺归咎于「祸神」似乎理所当然。但是好好想想吧，倘若意志足够强大，信念足够坚定…\n万劫太过久远，凶星恶曜亦能以泪涤净自身。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上永恒的守护者挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113034, '万劫之真意', NULL, 5, 11101, '在一切尘埃落定之后，从净土带回的小小头饰。\n一念则万劫尽，总有思念可以超越时间。\n百千万劫，「真」实之意，不知道是否传达到了。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上永恒的守护者挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113035, '符纹之齿', NULL, 4, 11101, '神秘的蛇状古代机械用于掘削山壁的「齿」，其上篆刻着无解的不祥符文。\n相传在大地的深黑裂缝中潜藏着庞大的虺类，它们永远怀着对地上世界的憎恨与恶意，抱着不可知的险恶目的，发掘着宏大的隧道…', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上遗迹巨蛇掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113036, '蕈王钩喙', NULL, 4, 11101, '击败翠翎恐蕈后，获得的角质结构。\n学者至今都觉得柔软的蕈兽演化出坚如磐石的钩喙是一个奇迹。在演化的终点线上，堪称华美的众蕈之王悠然踱步，时而长鸣，在向雨林中的万物昭告：哪怕再弱小再胆怯的生灵，也有可能成为未来的山林主人。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上翠翎恐蕈掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113037, '藏雷野实', NULL, 4, 11101, '被锋锐树叶包裹着的掣电树核心，肆意向周身散发雷元素。\n大地深处咆哮的能量急切地想要倾泻暴怒，于是不幸的藤蔓也沾染了狂躁的气息，挥舞着扭曲的枝条哀号，不知是想要让他人品尝雷火穿身的苦痛，还是挣扎着期待必至的末日。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上掣电树掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113038, '永续机芯', NULL, 4, 11101, '从神秘的遗迹机械上取来的动力机关。\n即使它所驱动的机体已经被摧毁，仍在持续运转着。\n地上理应不存在无限持续的能源，关于「永动」的研究成果发表也大多被证伪。然而从这枚机芯可以看出，如今已经覆灭的文明曾经一度触及人所不能抵达的领域。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上兆载永劫龙兽掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113039, '导光四面体', NULL, 4, 11101, '击败神秘的机关组合后，获得的核心部件。\n即使到今日，古老的机械也从未遗忘主人的梦与自己的职责：构筑一千座宫殿、统辖三千台机械、种下一万朵如今已经不再开放的花，为地上一切有灵者重现埋没在沙海中的「乐园」。\n即使荒漠的王者已经不再，梦想也因为深罪的低语而腐败；即使所有魔柱都完全折断、倒塌，原本受王青睐的巨兽隐入热砂的风暴中。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上半永恒统辖矩阵掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113040, '灭诤草蔓', NULL, 4, 11101, '无相之草最终凝聚成的形姿，坚硬的藤蔓包围之下的纯净元素方晶。\n最与常理相悖、又最适宜生命的草元素，与距离一切生命的形态最遥远的无相元素原本不应当相结合出现在大地上吧。一说认为无相元素有「学习」的智性，所以了解到了森林中的多彩与梦。在超越千年的晕染中，也变成了如此的形态。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上无相之草掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113041, '傀儡的悬丝', NULL, 5, 11101, '插入机心人偶背部的导管。流淌其中的色彩时而晦暗时而明艳，矛盾到令人恐惧。\n为机心人偶提供能量，同时也如悬挂木偶的丝线一般控制束缚着人偶。\n失去导管支撑，人偶将羸弱得堪比新生幼儿，寸步难行。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上「正机之神」挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113042, '无心的渊镜', NULL, 5, 11101, '正机之主胸前用于隔断外界的镜面。特意绘上了三重巴纹以宣告其身份与威严。\n此纹样并非向雷之主人宣告臣服，\n而是刺往世间既有之威能的利刃；\n此镜面并非隔绝世人批判之目光，\n而是断却俗世一切之污脏的宫墙。\n于此大殿中施舍惩戒，洗净蒙昧，\n颠倒梦想、剜去心因，重书定业。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上「正机之神」挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113043, '空行的虚铃', NULL, 5, 11101, '状似铃铛，用来连接机体臂部的球形关节部件。看起来精致小巧，却能负荷远超想象的能量。\n链接手臂，自己的双臂就会失去知觉；\n链接腿部，自己的双腿几乎无法使力；\n而链接这颗机械之颅…\n憎恨与痛苦，疯狂与自傲，都不会被洗去。\n万幸。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上「正机之神」挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113044, '苍砾蕊羽', NULL, 4, 11101, '沙虫隐于尾中的苍色鞘翼，仿若绽露的花蕊般纤薄。\n传说在时间开始之前的过去，它们曾在草甸与巨木之下的湿润土地中穿行，如空中飞鸟、水中游鱼。一般认为，花的拟态是为了引诱沙暴中迷途的猎物，但也有说法认为，那盛绽的浮花之形，仿拓的是归于黄沙的，在无数纪元之前的，芳草遍布、繁花依旧盛开的时代。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上风蚀沙虫掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113045, '常暗圆环', NULL, 4, 11101, '击败呢喃着至暗福音的四臂使者后，得到的环形法器。\n圆环即是通道的造型。是故能产生各种神秘效力的法阵常常以圆环构成。这种环形法器或许便是导引宇宙的门路。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上深罪浸礼者掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113046, '生长天地之蕨草', NULL, 5, 11101, '从阿佩普体内的绿洲中取来的一支蕨草。\n在时间开始之前，世界曾经由龙管辖。而在阿佩普的宫阙灵囿里、草木生长之天地中，首先抽芽的便是蕨草。\n在随后的漫长年月当中，蕨草将变为树木、藤蔓、根茎与草叶，遍布大地。但阿佩普还记得最初的一支蕨草由蜷曲的姿态，向无拘无束的天空伸展开时，发出的细不可闻的声响。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上阿佩普的绿洲守望者挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113047, '原初绿洲之初绽', NULL, 5, 11101, '从阿佩普体内的绿洲中取来的保有古老原始形态的花朵。\n在随后的漫长年月当中，花取得了无穷多的色彩与芬芳，也获得了如夜空中繁星的数量一般多的名字。\n但这朵最初绽放的花始终没有名字。对古老的龙而言，即便玫瑰失去了它的名字，也不会失去它的芳香。定义不过是狭隘短寿的物种用于认识世界的工具；生命是不会为字词所限，永远变化着的。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上阿佩普的绿洲守望者挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113048, '亘古树海之一瞬', NULL, 5, 11101, '从阿佩普体内的绿洲中取来的一枚琥珀。其中禁锢着细小的，如今已经绝迹的飞虫。\n包裹着细小生命的琥珀对于树木而言是偶然，对其中的存在而言则是命运。\n随着从天而降的灾厄，树木、藤蔓、根茎与花草纷纷枯干，化作尘埃，许多的生命也消失了。\n但静止在琥珀当中，又被珍藏于这一不存在于地上的绿洲里的无名飞虫，也因此得以前往同族无缘抵达的未来。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上阿佩普的绿洲守望者挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113049, '奇械发条备件·歌裴莉娅', NULL, 4, 11101, '属于歌裴莉娅的奇械发条备件，能够为奇械舞者提供能源。\n在制造者的构想中，有着纤细关节的奇械舞者的故事停留在欢快的一瞬。歌裴莉娅将会以超凡的战斗能力为任何试图搅扰此刻的不速之客送去厄运的篇章。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上「冰风组曲」掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113050, '奇械发条备件·科培琉司', NULL, 4, 11101, '属于科培琉司的奇械发条备件，能够为奇械舞者提供能源。\n奇械舞者踏着白金的音节，不知昼夜地为观众献上冰风的轮舞。科培琉司不会停下舞步，直至丧钟敲响。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上「冰风组曲」掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113051, '帝皇的决断', NULL, 4, 11101, '铁甲熔火帝皇的战锤。\n无论是其他的原海异种，还是发条机关或是一时兴起的讨伐者，它用这只巨钳粉碎了无数觐见者。\n与人不同：在原海异种当中，不存在贵族，也不存在富人之子，谁也无法生来就高于别的同类。能够克服一切逆境、战胜一切天敌的原海异种在漫长的岁月中能够随着捕猎与进食，无限地积累力量成长，最终被充满畏惧地称为霸王。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上铁甲熔火帝皇掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113052, '「图比昂装置」', NULL, 4, 11101, '实验性场力发生装置的核心部件。\n能够在肉眼几乎无法捕获的高速旋转中，抵消重力影响的精密加工机械件。\n在长久的历史中，枫丹动能工程科学研究院一直在以曾经洗去无数生命，又总有一天会再度遮天蔽日的洪水为敌，寻找着生存的途径。\n而蕴含着庞大能量，能够粉碎大地桎梏的始基矿则一度被认为是开启救赎大门的钥匙。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上实验性场力发生装置掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113053, '原海麟角', NULL, 4, 11101, '千年珍珠骏麟的放电器官，也是象征它的伟大超越的王器。已经在与挑战者的战斗中折断了。\n作为自泡泡海马成长而来的顶尖掠食者，千年珍珠骏麟的进化之旅与别的原海异种截然不同：并不是基于原本的物种结构而进化得更大、更强壮，而是生出了泡泡海马所不具备的肢体、犄角，甚至连同骨骼、肌肉都发生了变化。比起原本应有的形态，它的身姿更像古老传说中的幻兽。在诗人与剧作家的幻想中，即使是海马也会有骐骥在大地上驰骋、跃动的姿态。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上千年珍珠骏麟掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113054, '无光丝线', NULL, 5, 11101, '与吞星之鲸战斗时，不知不觉缠绕在武器上的细丝。\n在古代的枫丹，曾有人认为主宰万物现象的「法图纳」是由无比细微的「纤维」编制而成，就如同组成竖琴的弦丝。与宏伟的乐声共振的丝线将会带来普世的幸福，正如不谐音会破坏宇宙的肌理。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上吞星之鲸挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113055, '无光涡眼', NULL, 5, 11101, '从吞星之鲸的战斗中取得的奇异「物质」，实际质量远比从尺寸看上去的重。\n一切都聚集在命定沉重的事物旁，正如黄金比之黑铁、大地比之轻风。正如光线无法从黑暗的涡眼当中逃脱，因缘也会汇聚在沉重的命运上，或许这也是不可逆转的规则吧。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上吞星之鲸挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113056, '无光质块', NULL, 5, 11101, '在与吞星之鲸的激烈战斗中，产生的碎屑。\n宇宙是黑暗而冰冷的地方。\n但仔细看吧。其中总有无比细微的亮光，如同半掩沙中的珍珠、撒在沥青上的碎钻、雾夜中视界尽头的灯光，以及点燃枯草原的火星。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上吞星之鲸挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113057, '未能达成超越之水', NULL, 4, 11101, '水形幻人崩溃逸散后留下的唯一痕迹。\n与原海异种体内取出的晶体有非常相近的性质，但当中蕴含了许多细碎的浊物，就如同凝固在拙劣工匠的玻璃制品中的微小气泡。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上水形幻人掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113058, '凝云鳞甲', NULL, 4, 11101, '隐山猊兽的甲鳞，质地冰冷而坚硬。纵然剥离脱落，其上依然萦绕着纯净的仙力，普通的武器难以损之分毫。\n普通的野兽有时也会被逸散的仙力影响，变得比往常更为强大，但猊兽的不同之处在于，萦绕其身的仙力并非源于环境，而是源于它们自身——这也是其首领的地位往往被认为与仙人等同的原因。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上隐山猊兽掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113059, '金色旋律的断章', NULL, 4, 11101, '半人马魔像胸前掉落的金色别章。与之连缀的碎石上所镌刻着的曲调，似乎是某部宏大乐剧的断章。\n曾有人认为，永恒幸福的谐和音律将会响彻寰宇，直至一切命运的尽头，但谐律亦会变奏。最终，当叛逆的神王跌落王座，不朽的王都化为丘墟，失去了军团的统帅手中的琴又要为谁人奏响呢。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上魔像督军掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113060, '残火灯烛', NULL, 5, 11101, '完成与「仆人」的决斗后，在废墟中拾起的灯烛。\n相传当烛火摇曳于罪人的手中，光亮即可化作阴影，掩盖脚步声与杀意。\n不知用何种材料制成，燃烧后没有蜡泪，只有黑色的灰烬散入风中，飘向未知的远方。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上「仆人」挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113061, '丝织之羽', NULL, 5, 11101, '完成与「仆人」的决斗后，在废墟中拾起的晶片。\n已经冷却的血与火依旧维持着羽毛的形状，周围缭绕着凝固的黑色细线。\n心智尚未成熟之时，稚童们总是依赖父母的精心照料，如同雏鸟需要羽翼的庇护。\n为了满足这份愿望，「父亲」将危险的蛛丝织成羽毛，模仿成鸟的翅膀，为家中带去些许温暖。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上「仆人」挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113062, '否定裁断', NULL, 5, 11101, '完成与「仆人」的决斗后，在废墟中拾起的耳钉。\n红色的符号如同她眼中的图案，既是申敕也是否决。\n失怙失恃的孩子们自幼就蒙受诸般苦难，这些她都记在心底。\n命运审视人间，亦将有人审视命运。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上「仆人」挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113063, '星与火的基石', NULL, 5, 11101, '「英雄点燃圣火，照亮世界，又终将沉眠，枕星安息。」\n「他们留下了一块石头，一张织物。我们以此为基石，搭起了永不断绝的文明。」', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"完成纳塔地区任务获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113064, '受祝所缚之印', NULL, 4, 11101, '击败金焰绒翼龙暴君后，获得的角的残片。\n其上能够看到蔓延于角上的奇怪印记，这印记被称为「焰主之祝」，拥有此印的龙众将获得远古的伟力。不过，远古的伟力自然不是现在龙众的身躯所能承担，也是诸多祸事的来由。许多的悲剧，其源头正是不可自控的力量。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上金焰绒翼龙暴君掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113065, '过熟的火榴果', NULL, 4, 11101, '击败贪食匿叶龙山王后，获得的奇特火榴果。\n一般来说，成熟的火榴果如果再继续生长，就会跌入泥中腐烂。但是从山王的鬃毛之中落下的果子，或由于其奇特体温保护着的缘故，呈现出非常难得的「过熟」状态。这种状态下的火榴果稳定，富含燃素，果色厚重，别具一番风味。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上贪食匿叶龙山王掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113066, '秘刻金纹的源核', NULL, 4, 11101, '在击败秘源机兵·构型械后，从其失去动力而解离的躯体中寻找到的核心构件。\n据说驱使所有现在被称为秘源机兵的造物的核心都是同一种，只是不同核心携带的信息并不一样，其上金色纹路图案的差别或许也可以说明这一点。起初只是为了让工具能够自如运转而在回路之中加入了诸多命令，或许正是这种命令的重重叠加，最后造就了人造智慧的雏形吧。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上秘源机兵·构型械掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113067, '深邃纠缠的凝视', NULL, 4, 11101, '击败名为深邃摹结株的魔物后，获得的犹如果实却并非果实的事物。\n那聚集一处的能量所形成的「眼」，其后似乎有仿佛来自遥远而黑暗的彼端的视线。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上深邃摹结株掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113068, '蚀灭的灵犀', NULL, 5, 11101, '在与蚀灭的源焰之主战斗后，斩下的魔龙的焰角。\n传说最初的源火是一切光明与智慧诞生之处，而火龙之角犹如光炬一般照亮蛮荒凄凉的世界。\n在焰角底座已受腐蚀的情况下，一度点亮世界的光辉也并未染上丝毫的污浊。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上蚀灭的源焰之主挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113069, '蚀灭的阳焰', NULL, 5, 11101, '在与蚀灭的源焰之主战斗后，仍在不息燃烧的环状火焰。\n最初，在最深邃的夜晚里，执掌火焰的主人仿照太阳，以此取代星空的光芒。\n一半的火焰已受侵蚀的焰芒之辉，似乎还能看出映照旧日世界的光采。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上蚀灭的源焰之主挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113070, '蚀灭的鳞羽', NULL, 5, 11101, '在与蚀灭的源焰之主战斗后，落于地面的漆黑鳞片。\n古老的龙众曾经用自身脱落的鳞片以传递秘密的信息与谕令。\n完全被漆黑之力腐蚀的鳞片，原本镌刻其上的光芒被噬尽后，唯留有扭曲与黑暗的残余。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上蚀灭的源焰之主挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113071, '谜土的护符', NULL, 4, 11101, '通过灵觉隐修的迷者的考验后，不知何时出现在背包中的护符。\n在「烟谜主」部族中的一些记载中，「灵觉」强大的祭司甚至能够通过冥想，令意识穿越黑曜石反射的光影，进入唯有亡者才能进入的地下谜土。只是这一举动相当危险，能够做到此举的祭司往往需要佩戴类似的护符，避免灵魂迷失在谜土之中。不过，这护符的象征意义远大于实际意义，隐修的祭司将之留给通过考验的勇士，也许只是为了留下简单的祝福。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上灵觉隐修的迷者掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113072, '龙像的无智核', NULL, 4, 11101, '击败熔岩辉龙像之后，从其持续燃烧的身躯中取得的核心。\n据说名为熔岩辉龙像的个体是无限堆垒燃素以后形成的特殊存在，在原本的构想之中，纯粹的能量之中会诞生具有人智的生命。只不过这一尝试最终以失败告终，事实证明，纯粹的能量已无法像更远古的时代那般，自发形成能够成长和受到操控的复杂智慧。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上熔岩辉龙像掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113073, '升扬样本·骑士', NULL, 5, 11101, '这是物质经过炼金术的活性化反应后，所留下的珍稀样本。\n秘典的记述中，青铜骑士并不知道自己的使命是征服还是守护。它只是经历了炼金术的擢升，开始寻找自己的意义罢了。青铜时代是英雄的时代。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上门扉前的弈局挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113074, '升扬样本·战车', NULL, 5, 11101, '这是物质经过炼金术的活性化反应后，所留下的珍稀样本。\n棋子的「车」词源乃是古代须弥语言的「战车」。在占卜牌中，「战车」的画面必须驾驭黑白双色的神驹，这也是炼金术里驾驭性质相反之物的平衡之道。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上门扉前的弈局挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113075, '升扬样本·王族', NULL, 5, 11101, '这是物质经过炼金术的活性化反应后，所留下的珍稀样本。\n「王后」棋子曾经的名字是「宰相」。但是随着游戏规则的发展，它变成了象征外戚势力的最强重子，实至名归的黄金王族。\n普通士兵的升变和炼金术的物质嬗变或许有些相似之处吧。但是就算成为了黄金，也只能用倒置的城堡来表示。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上门扉前的弈局挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113076, '秘源积气喉', NULL, 4, 11101, '自不再活动、看似龙首的秘源机兵上取下的特殊结构。\n据说，这个结构原本是为了使各种物体能够挣脱星体的束缚而设计的，首先被运用在了各种秘源机关之上。或许，如果一切顺利的话，这项技术本来将被应用在其他更重要的地方吧…', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上秘源机兵·统御械掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113077, '精密型月矩力冲鸭模具', NULL, 4, 11101, '击败重拳出击鸭之后，从其破损的结构中取得的冲压模具，也可以认为是爱诺赠送的纪念品。\n曾有须弥的哲人在论证中认为，自我繁衍是生命独一无二的特征，任何受造于人的物件都无法实现同等的伟业，因而繁衍的权能正是将神性与人性区分的关键。\n然而，若是给定模具，让机关按照其形状复制连同模具在内的自身，是否也能被视为永生的繁衍呢？陪伴在爱诺身边的那位沉默寡言的蓝发女仆，她过去侍奉的旧主也思考过同样的问题，最终却因为担忧无限自我增殖的机器会耗尽星球地表的一切而作罢。\n不过，这些事情与爱诺向来是没有关系的，这台机器暂时也不会用尽地表的一切来复制自身——毕竟鸭子只是鸭子而已。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上重拳出击鸭掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113078, '承光的鳞羽', NULL, 4, 11101, '击败蕴光月幻蝶之后，其身后蜕下的布满细琐鳞片的虫翅。\n据说在此地流传的诸多民俗故事中，常有踏入禁忌之地的人被幻惑的鳞翅迷惑，从此消失于林泽之中的记载。有人说这是因为蝶形魔兽的幻惑之法来自于易让人发疯失常的月亮，但也有人说这是古老力量变化多样而又危险至极的警示…', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上蕴光月幻蝶掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113079, '漫光的辉角', NULL, 4, 11101, '击败霜夜巡天灵主之后，自其角冠上脱落的碎片，质地轻盈而锋锐，即便是在未经打磨的情况下，也能毫不费力地削开普通的金属护甲。\n古老的民话中，这些高傲而优美的生灵受造于最初的神使。乐园殒落之时，它们曾与霜月的女主人立约，誓要以得赐于霜月的源光，涤净尘世的污秽，直至旧日的恩主再度归来。传说的来由与真实性如今早已无从考证，但过去与光同行的生灵依然在影中庇卫着这片大地——无论是凛冽的长夜还是漆黑的枯潮，都未能使它们的身姿从世间隐匿。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上霜夜巡天灵主掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113080, '循环式军用月矩核心', NULL, 4, 11101, '击败超重型陆巡舰·机动战垒之后，自其能源核心中取得的月矩力装置。\n枫丹动能工程科学研究院曾定义过数类元素工质发动机的理想循环模式，无论是哪一种，最为完美的循环数目皆为四。尽管军械宫与帕哈岛试验设计局的工程师们大多倾向于将月矩力视为一种不同于元素力的工质，四循环以外的设计构型依然被证明是低效而不实用的。从某种意义上来说，「四」的循环也许是世界古怪的偏好吧——当然，世界也许并无偏好，对世界而言，自作聪明的凡人擅自猜度的习惯才是最古怪的偏好也说不定。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上超重型陆巡舰·机动战垒掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113081, '贤医的假面', NULL, 5, 11101, '战胜僭月的伪神后，自异端的试验场内拾得的面具。\n所谓医疗的目的在于消除躯体上的病症，然而俗世的医者却对真正致死的疾病视而不见。苦弱的血肉之躯，经由贤医之手不再囿于生老病死，展现出超越常理的力量。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上「博士」挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113082, '狂人的约束', NULL, 5, 11101, '战胜僭月的伪神后，自异端的试验场内拾得的束带。\n人们通过排除疯狂定义了文明，然而自以为能将一切存在与非存在皆纳入理性的筹划，或许也不过是另一形式的癫狂。狂人看穿了理性的狡计，在他的世界中一切皆允。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上「博士」挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113083, '异端的瓶剂', NULL, 5, 11101, '战胜僭月的伪神后，自异端的试验场内拾得的瓶剂。\n千百年来，自称学者的众愚匍匐在六宗禁制的脚下，他们自欺欺人的研究不过是循环论证的文字游戏。对真理的探求绝不应受到任何限制，如此说来被世人视作异端的恶徒，才是真正的求知者。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"70级以上「博士」挑战奖励\", \"合成台-转化页签：转化获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113084, '魇翼枯骸', NULL, 4, 11101, '击败自异界侵入此世的魇语之主，从其留下的残秽中取得的深黯骨骸。\n翱翔于漆黑星海间的无形之兽，本不应需要被这个世界称作「羽翼」的器官。那怪诞而亵渎的翅膀，或许是为了适应月下的法则而生；又或许它不过是凡夫眼中所见的，其真身投下的扭曲一角罢了。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上深黯魇语之主掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113085, '棱光的断尾', NULL, 4, 11101, '击败蕴光月守宫之后，其试图逃脱时遗留下的晶化尾椎。\n以常理而言，演化至如此强大的蜥类本不应再受到天敌的威胁，然而它却依旧保留了断尾求生的本能。或许是因为在月光遍照大地的时代，此地曾存在着更加可怕的掠食者吧。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上蕴光月守宫掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (113086, '堕天的落羽', NULL, 4, 11101, '击败堕天的守望者后，于尘世一隅拾得的落羽。\n与真正的天之御使相比，拥有羽毛的守望者在形象上似乎与通常意义的天使更为肖似。这或许是因为它们侍奉的造主也并不理解天上有翼者的神圣规划，只能拙劣地摹仿其理念投射出的影子。', 'AVATAR_MATERIAL', '角色培养素材', NULL, NULL, NULL, '[\"30级以上守望者·堕天掉落\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114001, '高塔孤王的破瓦', NULL, 2, 15101, '赋予武器突破之力的材料。\n最近被称为风龙废墟的地方，曾经是烈风的魔神「迭卡拉庇安」建造的王都。因这繁华之梦全是魔神之力所造，因此梦碎瞬间的破瓦断片也有强大的力量。', 'AVATAR_MATERIAL', '武器突破素材', 4310, '炼武秘境：水光之城', '[\"周一\", \"周四\", \"周日\"]', '[\"蒙德纪念品商店兑换\", \"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114002, '高塔孤王的残垣', NULL, 3, 15101, '赋予武器突破之力的材料。\n烈风的魔神「迭卡拉庇安」对自己所造的王城十分满意，他在高塔上接受所有追随者的跪拜。但他却不知道，众人对他俯身并非出于敬仰爱戴。', 'AVATAR_MATERIAL', '武器突破素材', 4311, '炼武秘境：水光之城', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114003, '高塔孤王的断片', NULL, 4, 15101, '赋予武器突破之力的材料。\n「安德留斯」曾经对高塔的孤王宣战，却也无法损伤王都分毫。若不是「自由」高歌的瞬间让这座城市土崩瓦解，这一切都会继续永远之梦。', 'AVATAR_MATERIAL', '武器突破素材', 4312, '炼武秘境：水光之城', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114004, '高塔孤王的碎梦', NULL, 5, 15101, '赋予武器突破之力的材料。\n众人对高塔上的孤王俯身并非出于敬仰爱戴，而是被它的烈风吹得无法起身。这是巴巴托斯崛起之前，风神之一柱的野心与碎梦。\n它是如此用力地做梦，因此梦的碎片也带着强大的力量。', 'AVATAR_MATERIAL', '武器突破素材', 4313, '炼武秘境：水光之城', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114005, '凛风奔狼的始龀', NULL, 2, 15102, '赋予武器突破之力的材料。\n群狼是受它祝福的近卫军，就算是小狼的乳牙也有相当的潜力。\n曾经的众神皆背负爱人的责任。因此引导群狼，却只收养弃婴、接纳流浪者的「安德留斯」十分异类。', 'AVATAR_MATERIAL', '武器突破素材', 4320, '炼武秘境：深没之谷', '[\"周二\", \"周五\", \"周日\"]', '[\"蒙德纪念品商店兑换\", \"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114006, '凛风奔狼的裂齿', NULL, 3, 15102, '赋予武器突破之力的材料。\n狼的生活经常伴有厮杀，断骨裂齿的死斗也不罕见。\n「安德留斯」认为人类只会带来失望，但是纯真的婴儿是无辜的。狼群选择了孩子，孩子如果也选择了狼，那么他们就结成了「卢皮卡」——命运的家族。', 'AVATAR_MATERIAL', '武器突破素材', 4321, '炼武秘境：深没之谷', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114007, '凛风奔狼的断牙', NULL, 4, 15102, '赋予武器突破之力的材料。\n狼群也充分理解，人如果没有同类会感到孤独。光荣的断牙是狼们离别的赠礼，据说真的有保护平安的魔力。\n在遥远世界的传说里，有一只母狼领养了伟大的双子。狼与人所同住的「家」则被称为「狼之洞」，也就是「卢佩卡」，与这个世界的「卢皮卡」同义。', 'AVATAR_MATERIAL', '武器突破素材', 4322, '炼武秘境：深没之谷', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114008, '凛风奔狼的怀乡', NULL, 5, 15102, '赋予武器突破之力的材料。\n认为自己讨厌人类的奔狼之王，自觉无法去描绘人类的幸福生活，因此没有资格成为尘世的风之王。于是它选择了消失。但是事实不是这样的，它看着被抛弃之人的眼神是如此温柔。', 'AVATAR_MATERIAL', '武器突破素材', 4323, '炼武秘境：深没之谷', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114009, '狮牙斗士的枷锁', NULL, 2, 15103, '赋予武器突破之力的材料。\n人们总是会对英雄的故事过分夸大啦。甚至是曾经束缚英雄的枷锁，都被升华到了自由之敌的高度。\n因此这些锁链也拥有了非凡的力量。', 'AVATAR_MATERIAL', '武器突破素材', 4330, '炼武秘境：渴水的废都', '[\"周三\", \"周六\", \"周日\"]', '[\"蒙德纪念品商店兑换\", \"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114010, '狮牙斗士的铁链', NULL, 3, 15103, '赋予武器突破之力的材料。\n曾经施在大英雄温妮莎身上的枷锁——或者这么说吧，那个时代里，所有剑斗士都会背负镣铐。狮牙的斗士也只是其中一员。', 'AVATAR_MATERIAL', '武器突破素材', 4331, '炼武秘境：渴水的废都', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114011, '狮牙斗士的镣铐', NULL, 4, 15103, '赋予武器突破之力的材料。\n温妮莎并不是被镣铐或者锁链困住的，她想要挣脱枷锁和镣铐的话，随时都能击碎蒙德融造的普通金属。毕竟这里既没有优秀的矿石，也没有故乡的神火。\n锁住她的，是守护族人的责任。', 'AVATAR_MATERIAL', '武器突破素材', 4332, '炼武秘境：渴水的废都', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114012, '狮牙斗士的理想', NULL, 5, 15103, '赋予武器突破之力的材料。\n温妮莎从奴役之中得到了自由。结果锁住她的东西越来越大了：从族人变成了整个蒙德，甚至变成了「自由」，乃至这个世界。\n她是发自真心这么希望着的：愿这个世界变得更加坚强一些。', 'AVATAR_MATERIAL', '武器突破素材', 4333, '炼武秘境：渴水的废都', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114013, '孤云寒林的光砂', NULL, 2, 15104, '赋予武器突破之力的材料。\n孤云阁耸立的岩柱，曾经都是摩拉克斯为了镇伏敌手降下的岩枪。久而久之，魔神之体渗入了岩柱，使之拥有了圣性。岩柱偶尔会剥落一些散发着怨恨和不祥的碎屑。', 'AVATAR_MATERIAL', '武器突破素材', 5214, '炼武秘境：雷云祭坛', '[\"周一\", \"周四\", \"周日\"]', '[\"璃月纪念品商店兑换\", \"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114014, '孤云寒林的辉岩', NULL, 3, 15104, '赋予武器突破之力的材料。\n所以对于知情人士来说，孤云阁并不是什么愉快的海上奇观，而是曾经璃月众神的墓园。这里的确会周期性地涌起不祥和污秽，不过那都被另一个降妖伏魔的少年平息了。', 'AVATAR_MATERIAL', '武器突破素材', 5215, '炼武秘境：雷云祭坛', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114015, '孤云寒林的圣骸', NULL, 4, 15104, '赋予武器突破之力的材料。\n岩枪的核心是发着暗淡光辉的核心，那是战败魔神的力量深入岩石形成的。他们的怨恨并不针对摩拉克斯，因为他们早就已经没有自我了，不可能还残留私怨。', 'AVATAR_MATERIAL', '武器突破素材', 5216, '炼武秘境：雷云祭坛', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114016, '孤云寒林的神体', NULL, 5, 15104, '赋予武器突破之力的材料。\n于此躁动、作祟的，正是嗟叹连绵的众神圣骸之体。它们是未能实现的理想，对人类另一种幸福生活的描绘。它们以深海、层岩收纳，却不愿意就此入梦。', 'AVATAR_MATERIAL', '武器突破素材', 5217, '炼武秘境：雷云祭坛', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114017, '雾海云间的铅丹', NULL, 2, 15105, '赋予武器突破之力的材料。\n绝云间乃是仙家府地。而相传仙家除了三眼五显神通，可以操纵尘世的元素之力外，另有三项不传秘：丹鼎、符箓与外景。', 'AVATAR_MATERIAL', '武器突破素材', 5218, '炼武秘境：鸣雷城墟', '[\"周二\", \"周五\", \"周日\"]', '[\"璃月纪念品商店兑换\", \"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114018, '雾海云间的汞丹', NULL, 3, 15105, '赋予武器突破之力的材料。\n符箓可以让仙人力量借符号残留，外景可以用心像造出宇宙洞天。丹鼎之术，则一直笼罩在秘密之中。毕竟尝试吞下这些金丹的话，结果必定十死无生。', 'AVATAR_MATERIAL', '武器突破素材', 5219, '炼武秘境：鸣雷城墟', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114019, '雾海云间的金丹', NULL, 4, 15105, '赋予武器突破之力的材料。\n其实所谓金丹，真的是字面意思的金属之丹。这些都是仙人们制造的合金，融合了神通之力，可以给与武器超越的力量。武人似乎都觉得武道优于仙道，不怎么访神问仙。所以金丹并没什么机会给出去。', 'AVATAR_MATERIAL', '武器突破素材', 5220, '炼武秘境：鸣雷城墟', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114020, '雾海云间的转还', NULL, 5, 15105, '赋予武器突破之力的材料。\n这是金丹的最高品质，它模拟了混沌初开、清浊不分、天地一体的状态。据说这个是天地创世的缩影。当然，那位是知道的，世界的重现不是这样的。', 'AVATAR_MATERIAL', '武器突破素材', 5221, '炼武秘境：鸣雷城墟', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114021, '漆黑陨铁的一粒', NULL, 2, 15106, '赋予武器突破之力的材料。\n曾经在璃月云来海之外落下过一个漆黑陨铁，据说也是为了降伏魔兽妖物。但是因为沾染了强大的污秽之血，这块材料的特性已经不再是纯粹的岩王帝君之力了。', 'AVATAR_MATERIAL', '武器突破素材', 5222, '炼武秘境：古雷试炼场', '[\"周三\", \"周六\", \"周日\"]', '[\"璃月纪念品商店兑换\", \"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114022, '漆黑陨铁的一片', NULL, 3, 15106, '赋予武器突破之力的材料。\n璃月之地向来都有海怪的传说，毕竟彼方是超越提瓦特的未知区域了。没有了尘世七神的守护，外面不知道是怎样的一团混沌。能把岩王帝君的力量都染黑的，正是提瓦特秩序之外的力量。', 'AVATAR_MATERIAL', '武器突破素材', 5223, '炼武秘境：古雷试炼场', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114023, '漆黑陨铁的一角', NULL, 4, 15106, '赋予武器突破之力的材料。\n提瓦特沿海的诸国把超越七神庇护的外部称之为「暗之外海」，据说许多战败的魔神不愿意活在新的七神秩序之下，于是逃到了远岛，化作了邪神。不过它们的力量和岩王帝君的力量本就同源，和这个吞噬一切的漆黑并不一样。', 'AVATAR_MATERIAL', '武器突破素材', 5224, '炼武秘境：古雷试炼场', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114024, '漆黑陨铁的一块', NULL, 5, 15106, '赋予武器突破之力的材料。\n坎瑞亚覆灭的时代，某位大罪人制造了无数的魔兽。它们流淌着与此世不容的黑血，在大陆上践踏众生、破坏一切。它们的生命是变质的，由世界外的力量赐予的。硬要说的话，袭击蒙德的「杜林」也是此类。', 'AVATAR_MATERIAL', '武器突破素材', 5225, '炼武秘境：古雷试炼场', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114025, '远海夷地的瑚枝', NULL, 2, 15107, '赋予武器突破之力的材料。\n稻妻列岛中距离鸣神岛最遥远的「海祇」，在海祇岛的古语中的意思是「统管诸海的大神」。传说大蛇在常夜的渊下国土中初次现身时，身上覆满了四色的珊瑚枝，散发着煌煌的荧光。', 'AVATAR_MATERIAL', '武器突破素材', 4340, '炼武秘境：沉沙之渊', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114026, '远海夷地的玉枝', NULL, 3, 15107, '赋予武器突破之力的材料。\n这种珊瑚在提瓦特的大地上是见不到的，是大蛇闯入「暗之外海」时，获得的礼赠。因此对于深海的大蛇而言，身负珊瑚枝象征着力量；而失去珊瑚枝时，力量会相应地折损。换言之，折断的珊瑚枝中也蕴含着超常的力量。', 'AVATAR_MATERIAL', '武器突破素材', 4341, '炼武秘境：沉沙之渊', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114027, '远海夷地的琼枝', NULL, 4, 15107, '赋予武器突破之力的材料。\n失去了一切、逃向暗之外海的魔神在海渊中，见到了什么都没有的弃民。于是它决定留下来，成为他们的「远吕羽氏尊」、「海祇大御神」。\n传说大蛇神曾经折下身上所有的珊瑚枝，让蜷缩在黑暗中的孩子们拥有照亮周遭的光明。又有一说它用折下的珊瑚枝架起了登高的阶梯，让它的孩子们再次回到了地面上，见到阳光。', 'AVATAR_MATERIAL', '武器突破素材', 4342, '炼武秘境：沉沙之渊', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114028, '远海夷地的金枝', NULL, 5, 15107, '赋予武器突破之力的材料。\n「海祇」之名所背负的含义，归根到底只是曾栖身在深海中的弃民，对引领他们的蛇神一厢情愿的期许罢了。\n也正是因为有了仰望自己的子民，所以蛇神不得不留在本应逃离的世界里，折下身上的珊瑚枝，向自己不应涉足的土地入侵，与自己无法抗衡的敌手战斗，直到神体与山丘一同被斩断；直到鲜血化为电浆；直到思念与力量沦为永远无法消散的「祟神」。', 'AVATAR_MATERIAL', '武器突破素材', 4343, '炼武秘境：沉沙之渊', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114029, '鸣神御灵的明惠', NULL, 2, 15108, '赋予武器突破之力的材料。\n在过去，先民会攀登如今被称为影向山的高峰，将雷电灼烧过的树木雕琢成曲勾形，为照亮高天的闪电、震撼大地的鸣雷赋予造型。这个形象在漫长岁月的积累中，最终演化成了「雷之三重巴」的纹样，象征着雷的眷顾、智慧与威能，以及代行此等眷顾、智慧与威能的人们。', 'AVATAR_MATERIAL', '武器突破素材', 4350, '炼武秘境：砂之祭场', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114030, '鸣神御灵的欢喜', NULL, 3, 15108, '赋予武器突破之力的材料。\n在鸣神的幕府中设有奉行之名，乃是诸类事务的管理与执行者。在妖物悠长久远的故事中，在过去，深受将军殿下亲近信赖者会佩戴这种曲勾造型的护符；而奉行之名也取自欢喜奉行之意，得到她青睐的人，也会回报以爱与忠义。而从某一时点开始，一切都不再是原本的模样了。', 'AVATAR_MATERIAL', '武器突破素材', 4351, '炼武秘境：砂之祭场', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114031, '鸣神御灵的亲爱', NULL, 4, 15108, '赋予武器突破之力的材料。\n漫游在荒野中，或是与人一同生活的妖物都会被「雷之三重巴」所代表的御建鸣神主尊所吸引。纵使他们的寿命远远久于万物灵长，也有终结的一日。要在有限的寿命中求得永恒与无限，就只能骥望于「永恒」能记住他们了。而她也回应了他们的愿望，将所有的敌手与友人铭记于心。据说，无论是栖息在迷雾当中、撕裂天空的魔性之枭，胆敢擅闯御苑的怪化狸，还是那位武艺高强容貌如月、最终却对自己露出尖牙的鬼族少女；无论是曾经展开黑翼自在空行的天狗，抑或是与她同行，最终又永远消失的「狐斋宫大人」…\n无数的故事静静地沉睡在她的心中，终有一日会在她所梦想的永恒净土中灼灼发光吧。', 'AVATAR_MATERIAL', '武器突破素材', 4352, '炼武秘境：砂之祭场', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114032, '鸣神御灵的勇武', NULL, 5, 15108, '赋予武器突破之力的材料。\n雷电之尊的重宝在于威严，威严由勇武与震怒体现，震怒源于心中的爱执，勇武则是震怒的权现。最终，无论何者，只要敢于挡住望向永恒的目光，只要敢于伤害稻妻的子民，就会成为她的敌人。\n据说御灵有四魂，仙狐有三匹，名刀有二本；而御建鸣神主尊大御所大人的威严之相，只会呈现为流星光底的无想一线。', 'AVATAR_MATERIAL', '武器突破素材', 4353, '炼武秘境：砂之祭场', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114033, '今昔剧画之恶尉', NULL, 2, 15109, '赋予武器突破之力的材料。\n民话传说中，过去有名鬼人「虎千代」。武艺高强，曾有在刀剑一千柄当中狂舞，被割破的十二单如同菫花般零落，身体却未受一丝伤害的说法。后来却对将军大人露出獠牙，拔刀反叛，被斩下一臂一角后遁逃，最终郁愤发狂，自裁而殁。\n狂言称怀抱执妄之鬼往往内心惊悸而忧患。妄想永恒却恐惧须臾，总会为恐惧与怨怒吞没，是为自业自得。这种面具刻画的就是露出尖牙的虎千代。', 'AVATAR_MATERIAL', '武器突破素材', 4360, '炼武秘境：流沙之葬', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114034, '今昔剧画之虎啮', NULL, 3, 15109, '赋予武器突破之力的材料。\n《菫染山月虎啮鉴》中描绘的鬼人「虎千代」，曾以利齿咬碎将军的薙刀，取得过一时的上风。因此以他为原型制造的面具上往往有精心雕琢的尖牙。\n在其结局中，负伤之兽般遁入林野，连清凉的月光也避之唯恐不及。穿过窄巷与峡谷的风声像是受伤的鬼在低声哀嚎，因此也有「虎千代风」这一季语。', 'AVATAR_MATERIAL', '武器突破素材', 4361, '炼武秘境：流沙之葬', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114035, '今昔剧画之一角', NULL, 4, 15109, '赋予武器突破之力的材料。\n在鬼族失落的子守奉公子守歌中，鬼人「虎千代」是一位翩翩少年，拥有优雅勇健的身姿与华丽的容貌。他原本是将军麾下的爱将，曾忠心追随她深入漆黑的渊薮，击退邪秽之物，为血脉日渐稀薄的鬼族争取功绩。\n纵使如今这样的歌谣已经无人传唱了，以另一种形象流传下来的有角鬼面形象仍然有着非凡的力量。', 'AVATAR_MATERIAL', '武器突破素材', 4362, '炼武秘境：流沙之葬', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114036, '今昔剧画之鬼人', NULL, 5, 15109, '赋予武器突破之力的材料。\n背上「雷之三重巴」的纹样时名为「千代」的鬼族女武者，面对漆黑的军势时，曾被虎躯蛇尾的世外之兽吞下。最后她撕开魔兽的胸腔，得以幸存。\n这是「虎啮的千代」之名的来由。在此后的岁月中，这一名号渐渐简化为「虎千代」。\n但在深邃之兽的腹中，她染上了深罪的黯色，也透过猩红的利齿看见同行者被撕碎。沉湎于漆黑景色的她最终向御建鸣神主尊拔剑；后来，她持刀之臂与尖角被斩落，如同负伤的野兽般从城中逃向林野；再后来似乎是被天狗，或是终末番，或是山中修行的岩藏之胤当成不认得的怪物，收拾掉了罢，因为她俊美的容貌已经因为漆黑的仇恨与负伤痛苦变得狰狞扭曲。抑或是遇见了大蛇遗骸附近的鬼面执剑人形，故此结束了命运的旅途。\n昔日曾与渊薮战斗者难免梦见漆黑的剧画。曾与魔兽厮杀又沦为当中一员者亦不在少数。世界的边缘正在变得稀薄而脆弱，这种侵蚀或许并非是单向的。', 'AVATAR_MATERIAL', '武器突破素材', 4363, '炼武秘境：流沙之葬', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114037, '谧林涓露的铜符', NULL, 2, 15110, '赋予武器突破之力的材料。\n在最初的贤者指导下，雨林的先民曾将枯木雕成神符，以供奉纪念绿草与高木的主人。\n神符仿照林间清露的形状雕成，象征着智慧的涓滴在凡人的心智中渗流。', 'AVATAR_MATERIAL', '武器突破素材', 4370, '炼武秘境：云垢', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114038, '谧林涓露的铁符', NULL, 3, 15110, '赋予武器突破之力的材料。\n后来，草木的主人教会了人们锻造黑铁的奥秘。就这样，天真的凡人学会了使用火与利刃的知识。\n草木的主人为之欢欣，纵使火与金属会伤害她，但亦会使凡人强大。', 'AVATAR_MATERIAL', '武器突破素材', 4371, '炼武秘境：云垢', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114039, '谧林涓露的银符', NULL, 4, 15110, '赋予武器突破之力的材料。\n在森林的诸多故事中，身披烈火般条纹斗篷的王是迷宫的大君，是映月之水的主人。\n当他俯首与草木的主人缔结友谊，信物便是闪烁着似水光泽的宝石与月光似的白银。\n作为友谊的珍贵交换，草木的主人承诺为迷宫之王保守秘密，保护雨林绮丽的梦想。\n尽管后来，一切秘密与梦构成的华美宫阙都在遗忘的深黑烈焰之下烟消云散，又融入厚重土壤，化作了新生雨林的养料。', 'AVATAR_MATERIAL', '武器突破素材', 4372, '炼武秘境：云垢', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114040, '谧林涓露的金符', NULL, 5, 15110, '赋予武器突破之力的材料。\n「为人只有三物值得相顾：怀抱月光的泉水、生命的绿色，与不老的容颜…」\n「智慧」的本质并不在于掌控一切思维，谋取一切利益，而在于其能够令平凡的生命最终也获得超越桎梏的自由。\n尽管密林中不再回荡着摄人心魄的虎啸，坚强的卫士也退隐孩童的梦中…在秘密的黄金封印都被揭开，所有的梦想在月光下如琥珀闪闪发亮的那一夜，或许她与她所深爱的凡人们将会赢得真正的自由。', 'AVATAR_MATERIAL', '武器突破素材', 4373, '炼武秘境：云垢', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114041, '绿洲花园的追忆', NULL, 2, 15111, '赋予武器突破之力的材料。\n人们曾说，花的王者是欢乐与幸福之主。清泉从她的袖口涌流而出，沙漠中便有了百花盛开的绿洲；鲜花与香草紧随着她的脚步，银白的月光为她开道。\n在高天转过脸去的艰苦时代里，花的女主人为凡人遍洒恩惠，人们开始重新认识到快乐与自我，于是再度拾起了闲暇与奢侈。', 'AVATAR_MATERIAL', '武器突破素材', 4374, '炼武秘境：思惑', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114042, '绿洲花园的恩惠', NULL, 3, 15111, '赋予武器突破之力的材料。\n在被黄沙掩埋的古老文献中，花的王者是梦的女主人。\n她曾为被放逐之人、癫狂之人与痴愚之人展现梦想，在梦想中为他们奉上甘美的欢乐，即使人们的手中只有黑铁的碗砵，依旧为花之女王的魅力所折服，深醉于她美丽的形象与无微不至的关怀之中。', 'AVATAR_MATERIAL', '武器突破素材', 4375, '炼武秘境：思惑', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114043, '绿洲花园的哀思', NULL, 4, 15111, '赋予武器突破之力的材料。\n花的王者曾与镇灵为善。\n鲜花与绿洲的女主人曾与沙漠的王共同为镇灵建起了「圆形剧场之城」阿伊·哈努姆，在古老镇灵的语言中乃是「月女城」之意。\n但后来，据说花的女王死于烈日与黄沙的恶意，绿洲也不复有紫红的帕蒂沙兰盛开。\n在她陨落之后，沙暴哀鸣、镇灵恸哭，月光般白银的宝石圆盘亦失却了原本的享乐用途，散发出哀伤的光芒。', 'AVATAR_MATERIAL', '武器突破素材', 4376, '炼武秘境：思惑', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114044, '绿洲花园的真谛', NULL, 5, 15111, '赋予武器突破之力的材料。\n「何人会敬奉已死的神祇？」\n花的王者曾与彼时的两位神王结成同盟，在智慧与威权之外，她为蒙昧的子民带来了慈悲与欢乐。\n正如大地不能只有烈日和雨水那般，理性与强力之下，欢乐与爱、歌声与乐曲、酒与奢侈同样重要。\n人们说，鲜花盛开的目的即是灿烂的死亡，而死亡正是花之主人从最开始便尽力追寻的终焉——因为死亡为失去的欢乐增添苦涩的风味，让它愈发浓烈地在无穷回忆之中显现。\n黄沙的无知之王从未明晓她的道理，仅仅迷醉于她无穷的魅力与柔情——执着的追忆尽管妄入歧途，却也在花之女王的计算之中。', 'AVATAR_MATERIAL', '武器突破素材', 4377, '炼武秘境：思惑', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114045, '烈日威权的残响', NULL, 2, 15112, '赋予武器突破之力的材料。\n很久很久以前，黄沙的居民以顽强的甲虫为原型雕成王印，用以纪念朝暮轮回的红日与无始无终的时光。\n尽管那位王者的名讳如今已不再被人挂在嘴边，但这些小巧的王印却保留下来，隐约透露着旧日的威名。\n它们随镀金的子孙流散四方，依然沉默地倾诉着旧主的往事。', 'AVATAR_MATERIAL', '武器突破素材', 4378, '炼武秘境：引业', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114046, '烈日威权的余光', NULL, 3, 15112, '赋予武器突破之力的材料。\n编织万千思绪，统制万千灵魂，此所谓威权之道。\n然而威权之道并非冷酷的暴政，其目的恰恰最为深郁——创造不再有人苦恼，不再需要迫害与奴役的真实乐土。\n正如沉默的王从晶石的秘密中望见的一切，正如已然消逝的伴侣曾经的教诲那般。\n玄色的虫印与铁色的裁决，就这样成为了王国法度的基石。', 'AVATAR_MATERIAL', '武器突破素材', 4379, '炼武秘境：引业', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114047, '烈日威权的梦想', NULL, 4, 15112, '赋予武器突破之力的材料。\n白银的月光与碧蓝的清泉，曾装点了绿洲乐园的美景。但随着花的主人谢落在蔽日的沙暴中，无忧的黄金乐园也被死亡所淹没。\n在镀金部族的诗歌中，银白的月光照在猩红的袍裾上，令哀恸之王阿赫玛尔发狂。\n忧伤的沙漠歌谣唱道，出于对旧日回忆的执着，孤独的君王在沙漠中央塑造了无法老去的梦乡。在那里凝聚着不被扰动的纯洁泉水，与永远停留在日暮时分的露光。', 'AVATAR_MATERIAL', '武器突破素材', 4380, '炼武秘境：引业', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114048, '烈日威权的旧日', NULL, 5, 15112, '赋予武器突破之力的材料。\n愚痴的黄沙之王统治的年代里，烈日般黄金的权力遍洒大地。\n古旧的石碑记录，王的威权化作七道烈光或七座柱梁；王的慈悲平均地赐予每一个人手中，没有人受到忽视，亦没有人心怀不满。\n那是一个被遗忘的黄金时代，彼时花的女王已谢落尘沙，草木的主人也决定离去。但只有黄沙的子嗣选择与他们的神祇同在，即使灾祸的阴影渐行渐近，他们所信赖的威权依旧如琥珀与黄金那般闪耀着不灭的光芒。\n但灾祸终究还是降临了，黄金的虫印也被葬在了神殿与宫阙深处、曾雕着鹫兽与牛头的破碎柱基之下。', 'AVATAR_MATERIAL', '武器突破素材', 4381, '炼武秘境：引业', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114049, '悠古弦音的残章', NULL, 2, 15113, '赋予武器突破之力的材料。\n琴键已然腐朽的竖琴，其音腔被阻塞，已经无法奏出声响。\n据说，遗忘乐章的后人为复活古老王朝的华丽残迹，曾在木制的机械竖琴上涂刷金漆，徒劳地将之与无言的魔像相配…\n很久很久以后，腐朽走调的竖琴仍旧留在那些沉默的巨像手中，任海浪抚摩，奏出忧伤的余音。', 'AVATAR_MATERIAL', '武器突破素材', 4470, '炼武秘境：机思', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114050, '悠古弦音的断章', NULL, 3, 15113, '赋予武器突破之力的材料。\n传说古老王朝的遗民曾以黑铁铸成竖琴，用于纪念与哀悼。\n黑铁所铸成的竖琴，是奏不出声音的。为了哀悼那个以金色乐曲为傲的古老王朝，遗民们打造了这些沉重而沉默的乐器。\n但无论如何，正如那沉默的时代一般，黑铁是奏不出音调的。', 'AVATAR_MATERIAL', '武器突破素材', 4471, '炼武秘境：机思', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114051, '悠古弦音的乐章', NULL, 4, 15113, '赋予武器突破之力的材料。\n在黄金宫殿与王座同沉的灾难中，乐章破碎，音符沉默…\n但帝国的遗民从未放弃拯救与超越命运的执望。\n为了拯救没落的文明与超越的旧梦，「金色剧团」奏响美妙的乐曲，指引孩童向沉睡的魔像献出高贵灵魂。', 'AVATAR_MATERIAL', '武器突破素材', 4472, '炼武秘境：机思', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114052, '悠古弦音的回响', NULL, 5, 15113, '赋予武器突破之力的材料。\n神王的宏大乐章由无数曲调连缀而成，但其主调深潜于水国的共同命运之下。\n无虑之年的协和奏鸣曲曾是文明与秩序的最高代表，但当盛世帝国沦为暴君的乐园，横暴者以华丽的黄金大氅为遮掩撕裂着与源泉的联系，不和谐的噪音终于在帝国各处蜂起扰攘之时——\n那最初的命运之曲仍不受骚乱的影响，在黄金日渐褪色的乐谱上持续奏响着…直至一切皆被溶解，一切重回混沌。', 'AVATAR_MATERIAL', '武器突破素材', 4473, '炼武秘境：机思', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114053, '纯圣露滴的滤渣', NULL, 2, 15114, '赋予武器突破之力的材料。\n传说在诸生命诞生之前，曾有一片浓稠的原始之海。它曾是万物纯净的起源，也终将吞没一切生命…而那些本不属于原始之海的物质则将被滤除，成为漂荡的浮渣。\n「浮渣亦有它们存在的意义——究竟何种物质会被吞噬一切生命的原始根源之海所排斥？」年轻的调律师曾追随伟大的僭主，思索着这个难题。', 'AVATAR_MATERIAL', '武器突破素材', 4500, '炼武秘境：匠理', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114054, '纯圣露滴的凝华', NULL, 3, 15114, '赋予武器突破之力的材料。\n「源自原始之海的活物，必将回归同一的命运。」调律师波爱修斯曾如是说，「但人的超越有着无限可能，即使原始的胎海也无法将之消融净尽…」\n傲慢的僭主曾试图调配不溶于纯水的灵露，以之容纳灵智与记忆，令臣民得以抛却肉身，获得永恒独立的生命。\n但灵肉转换的痛苦并非任何凡俗生命能够承受，僭主的律令撕扯着破碎的灵魂…\n灵露被众多魂灵的哭嚎染成黑色，从此其中失却调谐的神智，只余混乱与疯狂。', 'AVATAR_MATERIAL', '武器突破素材', 4501, '炼武秘境：匠理', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114055, '纯圣露滴的醴泉', NULL, 4, 15114, '赋予武器突破之力的材料。\n这是「纯水骑士」尚在时的遗物——骑士们说，在无人问津的山野泉流之中仍然有忠诚的精灵，正守护着不被污染的至纯醴泉…\n然而，人造灵露之主却无法容忍任何不同于伟大乐章的杂音。传说调律师波爱修斯所到之处，自然甘露皆被填埋，树立起帝国的渡槽，纯水的精灵亦销声匿迹…', 'AVATAR_MATERIAL', '武器突破素材', 4502, '炼武秘境：匠理', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114056, '纯圣露滴的真粹', NULL, 5, 15114, '赋予武器突破之力的材料。\n浓稠纯净的精粹溶液，由原始无垠之海的水滴中精炼而出。古代的神王曾相信它能带来永恒生命与无穷智慧，然而侧耳细听——它正隐隐预言着溶合为一的终局。\n这曾是神王未完成的宏伟乐章——无根无源的黄金灵露将替代原始莽荒之水，永生智者的辉煌秩序将为所有无知的角落带来甘露般的启蒙。\n但神王的妄想终究沉入深黑的海渊，黄金的灵露也随着无情时光被原始之汤侵蚀…\n调律师却对噩兆视之不见，支撑着残破的身躯，仍旧企图以最后的灵露赋同胞以生命，让旧日的秩序重临…\n如今，在枫丹诸多疯诗人与年轻画家的噩梦中，波爱修斯亲历的末日幻景仍旧时而重现，向他们提醒着难以逃避的轮回。', 'AVATAR_MATERIAL', '武器突破素材', 4503, '炼武秘境：匠理', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114057, '无垢之海的苦盏', NULL, 2, 15115, '赋予武器突破之力的材料。\n传说在最初的僭主来到原始之海时，水国的先主曾赠予他一杯水。\n后来，他成为了不可质疑的神王，以这杯水提炼神奇的露珠，从而建立了辉煌强盛的帝国。\n那是久远的故事了，其主角如今正沉睡在深海鱼群的磷光之中。', 'AVATAR_MATERIAL', '武器突破素材', 4504, '炼武秘境：奇械', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114058, '无垢之海的酒盏', NULL, 3, 15115, '赋予武器突破之力的材料。\n什么样的帝国能够延续千年？从龙的国度归来后，僭主曾思考过如是问题。\n不朽的石材与自原始之水提取的灵露结合，雕成如黑铁般坚韧的种族——以魔石为肤，灵露为血，从此之后再也无惧回归莽荒的诅咒…\n沉默的魔像仍做着帝国美梦——不知不觉间，帝国湮没已千年有余。', 'AVATAR_MATERIAL', '武器突破素材', 4505, '炼武秘境：奇械', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114059, '无垢之海的银杯', NULL, 4, 15115, '赋予武器突破之力的材料。\n在黄金之衾覆盖国土的岁月里，纯真的泉水不得不藏匿于隐秘山涧，「纯水骑士」便是在这些避难所中诞生的。\n骑士们以白银的甲胄为誓，守护着来自纯水的精灵，守卫着同样信赖唯一源泉的乡亲，抵抗遮天蔽日的黄金之权。\n那是很久以前的传说了…在帝国崩毁沉没之后不久，抵抗僭主的骑士们也卸下甲胄，其故事隐入了庞杂的故事歌谣之中。', 'AVATAR_MATERIAL', '武器突破素材', 4506, '炼武秘境：奇械', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114060, '无垢之海的金杯', NULL, 5, 15115, '赋予武器突破之力的材料。\n沉没之城的僭主弹奏黄金乐章的最后一曲时，深受宠渥的乐师窃走了满盛灵露的金杯。\n为神王的背叛愚行所震惊，乐师召集了最后的禁卫，用不溶的灵露将魔龙封印于高塔之下，同王城一起沉沦海渊。\n后来，这高贵窃贼的身影从历史上默默消湮，只有「金色剧团」仍忠诚地记得他的预言。', 'AVATAR_MATERIAL', '武器突破素材', 4507, '炼武秘境：奇械', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114061, '贡祭炽心的惶恐', NULL, 2, 15116, '赋予武器突破之力的材料。\n在部族古老的传统之中，有这样的观点：你所取的都是来自于这个世界，于是你所得的也将献于这个世界。', 'AVATAR_MATERIAL', '武器突破素材', 4382, '炼武秘境：冥见', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114062, '贡祭炽心的踌躇', NULL, 3, 15116, '赋予武器突破之力的材料。\n在原有的文明如破碎的玉石般失落，自天上来，引导地上文明的使者被醒来的巨龙吞噬殆尽之后，步入荒蛮的人失去了重新认识世界的能力。\n于是他们将一切所得都归于最为原始的信仰，认为承载一切的大地自有其神秘，于是，所获的猎物被作为祭品上贡的时代开始了。', 'AVATAR_MATERIAL', '武器突破素材', 4383, '炼武秘境：冥见', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114063, '贡祭炽心的决绝', NULL, 4, 15116, '赋予武器突破之力的材料。\n据说盗取火种的贤者，在他将掌握各种形态火焰的秘术交给部族的民众之后，曾希望他们得以踏上文明的阶梯，摆脱古老的陋习。\n但传承的迂腐总是难以撼动，而掌握力量的稚童仅仅为了更多的献祭之物就能开启同族之间的战端，这或许也是贤者最后心灰意冷，而从历史中隐去身形的原因。\n值得一说的事是，将生命献祭的仪式遭到全面禁止，却恰恰是禁城的圣主掌权之时。后者为了执掌权威而废弃了种种民俗，却也可视为一类文明的开端。', 'AVATAR_MATERIAL', '武器突破素材', 4384, '炼武秘境：冥见', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114064, '贡祭炽心的荣膺', NULL, 5, 15116, '赋予武器突破之力的材料。\n「如果你想要拥有世上的一切，那就先将自己的一切献给世界吧。」\n在禁城的圣主不再允许众人向夜晚的国度祈求之后，一度建立的精神的纽带业已荒毁。\n受指引的赤瞳的少年经历种种考验，其最后一项就是要效仿最初的人神那样，用黄金的匕首献上自己的心脏。\n自我的献祭是一种胜者的荣膺，他没有丝毫的犹豫，用烁光的利刃劈开自己的胸膛。而他再次出现的时候，已是从水如流光的国度归来，即将重造伟业的时刻了。', 'AVATAR_MATERIAL', '武器突破素材', 4385, '炼武秘境：冥见', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114065, '谵妄圣主的朽败', NULL, 2, 15117, '赋予武器突破之力的材料。\n据说后来被称为禁城圣主的备受争议的谋主曾一度受到拘禁，而最初的人神，但当时并未具备神体的那位，向他展露了宽阔的胸怀。\n于是原本属于他的族群接纳了他，自他从一度伟大的种族巨大翅膀的阴影中走出之后。\n那以后，他将文有金纹的真容藏在面具之下，决定为那个掌握了他誓言的主人献出一切。', 'AVATAR_MATERIAL', '武器突破素材', 4386, '炼武秘境：究观', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114066, '谵妄圣主的余哀', NULL, 3, 15117, '赋予武器突破之力的材料。\n在与巨龙进行战争之时，众部族的谋主，那位以面具掩藏起面目者，为部族的战士们解读非人遗迹上金色纹路的信息，那是在现今早已失落的技巧。\n这语言与思想由自己的敌人所授予，或许对谋主来说，站在相对的立场驱使它们是相当快意的复仇之事吧。\n只是他那份毫不掩饰的恨意，偶尔也会换来同行英杰们的深深担忧。', 'AVATAR_MATERIAL', '武器突破素材', 4387, '炼武秘境：究观', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114067, '谵妄圣主的容光', NULL, 4, 15117, '赋予武器突破之力的材料。\n那是端居在王座的，最初的人神走入了圣火，而凡俗的世界等待着王厅继任者的时代。\n也是谋主代执一切权柄的时代。\n可惜自称圣主的，这位认为他所爱的、他愿意为之垂下金泪的神应该永远只有那一位的僭越者，将私心凌驾于敬爱之神留下的诫言，建立了地天隔绝的城邑。', 'AVATAR_MATERIAL', '武器突破素材', 4388, '炼武秘境：究观', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114068, '谵妄圣主的神面', NULL, 5, 15117, '赋予武器突破之力的材料。\n禁城的圣主经常在梦中呓语中叙说非人的语言，并在镜中，面具唯一能露出的眼睛中看到逐渐竖立的瞳孔，而这也是他愈加厌恶龙众的原因。\n传说在赤瞳的少年用火焚烧那被幽影淹没的城上之城时，曾看到王厅前，陷入疯狂的半人如揭下脸皮一般撕下无法脱去的神面，露出犹如巨龙一般的狰狞窍孔。\n癫狂之人口中喷吐的金焰熔化了自己，失形的魂魄自高处沉入了漆黑的泥沼之中，而据说，这就是这位众叛亲离的谵妄者可悲的结局。', 'AVATAR_MATERIAL', '武器突破素材', 4389, '炼武秘境：究观', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114069, '神合秘烟的思绪', NULL, 2, 15118, '赋予武器突破之力的材料。\n古时的萨满、祭司或称秘术师的那些，在「大灵」自孤冷英雄与夜魂的呼应之中逐渐形成以来，持续不断地寻找与寂静地下国度沟通的方法。\n入迷，出魂与降神曾是三种主要的途径，而每种途径都将借助打磨的祭具完成。', 'AVATAR_MATERIAL', '武器突破素材', 4390, '炼武秘境：测度', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114070, '神合秘烟的预感', NULL, 3, 15118, '赋予武器突破之力的材料。\n尚古的通灵者认为，没有形象而只有意识的「大灵」是去除了外在，更接近精神本质的存在。\n将粗糙的石料打磨，直至去除所有纹理，成为反射光亮的镜子的过程，也是一种除去世界原有表征的仪式。或许光滑的镜面亦是通灵者自身精神的投射也说不定。', 'AVATAR_MATERIAL', '武器突破素材', 4391, '炼武秘境：测度', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114071, '神合秘烟的征兆', NULL, 4, 15118, '赋予武器突破之力的材料。\n没有固型的灵性依附于物件之上，结合转化为种种不同的面目，这一过程被称为神合，此后，神合后的灵性会在人的恍惚中，向其传达如梦般的图景。\n经常与灵进行这般对话的人需要理解那些图景之中的意义，如解梦般将大地之下的征兆化作部族民众所能理解的语言，或将警示转化为故事。据说这就是部族内被称为「叙事人」的职位的由来，也是大多数杰出的「叙事人」都来自谜烟之内的原因。', 'AVATAR_MATERIAL', '武器突破素材', 4392, '炼武秘境：测度', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114072, '神合秘烟的启示', NULL, 5, 15118, '赋予武器突破之力的材料。\n正如物质的表征不管如何打磨，其存在本身仍然是物质的，无法超脱于实体。人类的纯粹精神，依托之物既非意向之树，也不是需要勤加拂拭的曜石之镜。在夜晚的国度与夜魂的力量逐渐强大之后，神合之物的范畴也变得逐渐宽泛。后来，无需打磨石镜的仪式，「大灵」借由种种思绪就能向它的崇敬者传达夜神国度的启示，也使得此种祭具最终失去了作用。', 'AVATAR_MATERIAL', '武器突破素材', 4393, '炼武秘境：测度', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114073, '奇巧秘器的残件', NULL, 2, 15119, '赋予武器突破之力的材料。\n在过去也被称作「大盗的七道具」的精妙装置，据传其发明人正是闻名诸国的大盗雷德·米勒。\n如同最初的盗宝团中汇聚了形形色色的人们，将诸多原本用于不同意图的小道具整合在一处，便能破除人为设下的界限，无论是锁链还是疆域。\n其中收纳的工具数量并非只有七类，只是人们习惯于用七之数来称呼种类繁多之物。世界的秩序被认为只有七类，或许也是出于同样的原因吧。', 'AVATAR_MATERIAL', '武器突破素材', 4671, '炼武秘境：明辉', '[\"周一\", \"周四\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114074, '奇巧秘器的模本', NULL, 3, 15119, '赋予武器突破之力的材料。\n正如其工具曾被无数人仿制，大盗的名讳也曾被无数人仿用。\n从某种意义上来说，并非是渴求得到什么的人们窃走了雷德·米勒的名字，而是大盗雷德·米勒窃走了原本只属于他们自己的「身份」。这两件事之间，原本便没有什么区别。', 'AVATAR_MATERIAL', '武器突破素材', 4672, '炼武秘境：明辉', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114075, '奇巧秘器的继业', NULL, 4, 15119, '赋予武器突破之力的材料。\n在街头巷尾荒诞不经的传说中，大盗雷德·米勒曾数度被处以极刑，却总能在生死关头，依靠朋友的帮助与奇巧的道具逃出刑场。\n某些版本的故事里，曾有数名追随者为了他们崇敬的乐园之王而甘愿替死。只是那些故事并不受欢迎，因为酒后的笑谈应当是浪漫与圆满——既然世上从未有过能困住大盗的枷锁，自然也就不存在能困住他的结局。', 'AVATAR_MATERIAL', '武器突破素材', 4673, '炼武秘境：明辉', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114076, '奇巧秘器的真愿', NULL, 5, 15119, '赋予武器突破之力的材料。\n「贫困之人，饥寒之人，饱受欺辱之人，饱饮凌轹之人，流离至此的兄弟姐妹呀」\n「若是你也曾经因不公的命运而尝尽屈枉，若是你也在黑夜里为邻人的苦厄而垂泪」\n「若是你也渴望得到不再恐惧的容身之所，若是你也梦想见证无人饮泣的『世界』」\n「那你也一同，与你的兄弟姐妹们一同，挣脱奴役的锁链，加入到我们的行列中吧」\n「让死人埋葬死人吧，然后你们站起来，用高傲者们的财宝，筑起没有界限的乐园」', 'AVATAR_MATERIAL', '武器突破素材', 4674, '炼武秘境：明辉', '[\"周一\", \"周四\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114077, '长夜燧火的余烬', NULL, 2, 15120, '赋予武器突破之力的材料。\n在尘世的诗歌中，灯火常为希望的譬喻。燃薪在寂静中焚尽，只为让人们在黎明前的黑夜中望见前行的旅路。\n话虽如此，无论是最初的铸灯者，还是年幼时与他共同描绘乐园的挚友，直至灯火熄灭的时刻，也未曾知晓那被照亮的道路究竟通往何方。', 'AVATAR_MATERIAL', '武器突破素材', 4675, '炼武秘境：祷颂', '[\"周二\", \"周五\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114078, '长夜燧火的残照', NULL, 3, 15120, '赋予武器突破之力的材料。\n正如点亮灯盏便能驱散黑暗，边地的人们深信，只要执灯人的燧火长明，卑污的邪祟便不会沾染生者的家园。\n誓言守望长夜的战士亦曾如此相信。正因如此，如灯蛾赴火那般，男人以铁胄中脆弱的血肉迎向如山的灾厄。\n直至漆黑的荒潮噬尽他的血肉，亦或他的血肉将污浊的黑潮吞噬，二者再也无从界别。', 'AVATAR_MATERIAL', '武器突破素材', 4676, '炼武秘境：祷颂', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114079, '长夜燧火的明焰', NULL, 4, 15120, '赋予武器突破之力的材料。\n口衔燃芯的夜莺即是执灯人的徽记。\n据说在过去，夜莺的纹章曾属于北国某个声名烜赫的贵族家系。曾几何时，在灯火不抵的阴影中，后来以大盗闻名诸国的少年亦是仿照夜莺的形貌，与挚友共同刻下了最初的鸦印。\n但那也已经是许多年前的事了。时至今日，鸦印已经遍及大地四方，而黑鸦曾仰望的夜莺依然留驻在高塔上，向光明低唱着冬都的哀歌。', 'AVATAR_MATERIAL', '武器突破素材', 4677, '炼武秘境：祷颂', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114080, '长夜燧火的烈辉', NULL, 5, 15120, '赋予武器突破之力的材料。\n在长夜笼罩边地的年岁里，最初的铸灯者点燃驱散黑暗的明焰，以守望黑潮的重誓换来了特许的御敕，「执灯人」便是这样诞生的。\n与高海的逐影猎人们不同，巡夜的执灯士们既没有失落帝国传承的古老技艺，也没有显荣的封号与头衔，能倚靠的只有银胄下羸弱的血肉之躯、手中的刀剑与灯盏，以及世代背负的古老誓约。\n无论多少魂灵伴着微茫的灯火一同消逝，漆黑的灾厄也无法覆尽凡人的决意。因为长夜能夺去的唯有生命，却夺不去终将到来的黎明。', 'AVATAR_MATERIAL', '武器突破素材', 4678, '炼武秘境：祷颂', '[\"周二\", \"周五\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114081, '终北遗嗣的哀荣', NULL, 2, 15121, '赋予武器突破之力的材料。\n传说在黄金与白石之国尚未沉沦的年岁，崇月的先民曾在拂晓之星的引导下，筑起直抵天穹的高塔。\n后来，那最为僭越的狂想——即便是统领地上万国的君王也未能成就的、令生命与世界同构的狂想，在高天的震怒中与城邑一同倾覆。\n失乡的幸存者循着霜月的残光逃向南方，在泪中吟咏昔日的哀荣，那已是数千年前的故事了。', 'AVATAR_MATERIAL', '武器突破素材', 4679, '炼武秘境：祭月', '[\"周三\", \"周六\", \"周日\"]', '[\"礼包商城兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114082, '终北遗嗣的迷顽', NULL, 3, 15121, '赋予武器突破之力的材料。\n黄金与白石的大城早已不复，循着月光苍冷的指引，流亡的遗民踏上了阴恶荒寒的异土。\n往日的荣光与神妙的技艺如晨露般枯涸，然而最初的妄执却依然流淌在顽傲者的肌肤下，未曾与衰朽的坟墓一同失却。\n侍奉月光的主祭者们像农人修剪地里的作物那般，世代相继地拣选着最接近原初的纯净血脉，无论要何人为此付出何种代偿…', 'AVATAR_MATERIAL', '武器突破素材', 4680, '炼武秘境：祭月', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114083, '终北遗嗣的祷献', NULL, 4, 15121, '赋予武器突破之力的材料。\n银白如清辉的锋刃是恩主的慈恻。\n以仁慈之名，众生皆得以向明日献上希望。即便是未能「完成」的残次品，肤下流淌的亦是月光无垢的祝福。即便是微不足道的祝福，铢积寸累，亦能让浸入其中的圣嗣更接近终将到来的「乐园」。\n一切罪愆与凶慝最终都会被无瑕的月光洗净，因此一切泪水与苦厄皆为必要的牺牲——至少崇月的人们曾如此坚信不疑。', 'AVATAR_MATERIAL', '武器突破素材', 4681, '炼武秘境：祭月', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (114084, '终北遗嗣的煌熠', NULL, 5, 15121, '赋予武器突破之力的材料。\n伴随着预言之子不受祝福的降生，千年的规划迎来了黯然的暮色。\n用尽心机的谋算因背叛的愚行轰然破碎，理应为王的少年带走本该服膺他的侍女，窃取本该属于他的秘宝，却只是将命运为他留存的冠冕悉数否决。\n后来，注定统治乐园的王以罪无可赦的大盗之名沦入历史，而真正的新月照临大地之时，终北之国辉煌如黄金的悲愿，也已经被从未信仰过任何神明的祭司，葬入了她的王空无一物的坟茔。', 'AVATAR_MATERIAL', '武器突破素材', 4682, '炼武秘境：祭月', '[\"周三\", \"周六\", \"周日\"]', '[\"占位-可合成数量:{0}\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (116001, '纪行经验', NULL, 3, 430061, '纪行即是将长旅中所经历的一切都记录下来。这些就是将被谱写成诗的素材。', 'CONSUME', '纪行经验', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (118002, '给旅行者的小蛋糕', '给旅行者的小蛋糕 0', 4, 260101, '某个意义重大的日子留下的纪念品。\n\n献给星海之中熠熠生辉的你。\n祈愿你在这片大地上的旅程美好幸福。\n\n「这是第一次为你庆祝这个日子吧。每隔七天，推荐菜就会轮换一次。每隔三十天，月亮就会播撒新的祝福。下次为你庆祝，居然还要接近九千小时！」', 'CONSUME', '贵重物品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (118004, '给旅行者的小蛋糕', '给旅行者的小蛋糕 1', 4, 260101, '某个意义重大的日子留下的纪念品。\n\n献给大陆上奔忙着的你。\n祈愿你在这片大地上的旅程美好幸福。\n\n「每隔七天，推荐菜就会轮换一次。每隔三十天，月亮就会播撒新的祝福。下次为你庆祝，居然还要接近九千小时！这上面文字的意思，大概是派蒙陪着旅行者哦。」', 'CONSUME', '贵重物品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (118006, '给旅行者的小蛋糕', '给旅行者的小蛋糕 2', 4, 260101, '某个意义重大的日子留下的纪念品。\n\n献给越过海浪与山峦的你。\n祈愿你在这片大地上的旅程美好幸福。\n\n「每隔七天，推荐菜就会轮换一次。每隔三十天，月亮就会播撒新的祝福。下次为你庆祝，居然还要接近九千小时！往后的日子无论是晴还是阴雨，派蒙都要和旅行者一起度过，嘿嘿。」', 'CONSUME', '贵重物品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (118008, '给旅行者的小蛋糕', '给旅行者的小蛋糕 3', 4, 260101, '某个意义重大的日子获得的礼品。\n\n献给于林中奏曲并探听婆娑回音的你。\n祈愿你在甜美的梦境中得享幸福与安宁。\n\n「每隔七天，推荐菜就会轮换一次。每隔三十天，月亮就会播撒新的祝福。下次为你庆祝，居然还要接近九千小时！嘿嘿，现在派蒙我就按照蛋糕上的乐谱，弹奏给你听吧，先说好，不许笑，我练习了好久呢！」', 'CONSUME', '贵重物品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (118010, '给旅行者的小蛋糕', '给旅行者的小蛋糕 4', 4, 260101, '某个意义重大的日子获得的礼品。\n\n献给静心聆听海潮歌声的你。\n祈愿你在这片大地上的旅程美好幸福。\n\n「每隔七天，推荐菜就会轮换一次。每隔三十天，月亮就会播撒新的祝福。下次为你庆祝，居然还要接近九千小时！就像贝壳总是会陪伴着悠悠海獭一样，派蒙也会一直陪着旅行者喔！」', 'CONSUME', '贵重物品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (118012, '给旅行者的小蛋糕', '给旅行者的小蛋糕 5', 4, 260101, '某个意义重大的日子获得的礼品。\n\n献给凝望着营火摇曳的你。\n祈愿你在旅途中找到属于自己的温暖与幸福。\n\n「每隔七天，推荐菜就会轮换一次。每隔三十天，月亮就会播撒新的祝福。下次为你庆祝，居然还要接近九千小时！我们一起度过的时光就像巧克力一样，软软甜甜，还不舍得一口气吃完…嗯！派蒙最喜欢和你一起旅行了！」', 'CONSUME', '贵重物品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120815, '培育区域扩展·其一', NULL, NULL, 0, '增加一块可用于培育药材的区域。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120816, '培育区域扩展·其二', NULL, NULL, 0, '增加一块可用于培育药材的区域。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120817, '培育区域扩展·其三', NULL, NULL, 0, '增加一块可用于培育药材的区域。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120818, '培育区域扩展·其四', NULL, NULL, 0, '增加一块可用于培育药材的区域。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120819, '培育区域扩展·其五', NULL, NULL, 0, '增加一块可用于培育药材的区域。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120820, '培育区域扩展·其六', NULL, NULL, 0, '增加一块可用于培育药材的区域。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120821, '改进炼金釜·其一', NULL, NULL, 0, '改进炼金釜的性能，扩展炼制药剂时放置药材的区域大小。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120822, '改进炼金釜·其二', NULL, NULL, 0, '改进炼金釜的性能，扩展炼制药剂时放置药材的区域大小。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120823, '改进炼金釜·其三', NULL, NULL, 0, '改进炼金釜的性能，扩展炼制药剂时放置药材的区域大小。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120824, '改进炼金釜·其四', NULL, NULL, 0, '改进炼金釜的性能，扩展炼制药剂时放置药材的区域大小。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120825, '棱角水滴瓶', NULL, NULL, 0, '棱角分明的药剂瓶体，如同方方正正的水滴，对于宝贵的炼金药剂而言，确实每一滴都不能浪费…\n可以略微提升药剂的品质，所有特殊瓶体提供的增益效果相同。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120826, '妙妙心心瓶', NULL, NULL, 0, '高脚设计的药剂瓶体，采用了心形的设计，据说无论装着什么颜色的药剂，都能给顾客带来愉快的观感…\n可以略微提升药剂的品质，所有特殊瓶体提供的增益效果相同。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120827, '宁静水湾瓶', NULL, NULL, 0, '设计巧妙的药剂瓶体，采用了长瓶颈的独特设计，据说这种瓶型被设计师比作「宁静的水湾」…\n可以略微提升药剂的品质，所有特殊瓶体提供的增益效果相同。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120828, '华丽宝石瓶', NULL, NULL, 0, '窄口宽体的药剂瓶体，大量直线交织的外观如同一颗大型宝石，可以给顾客格外华丽的观感…\n可以略微提升药剂的品质，所有特殊瓶体提供的增益效果相同。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120829, '胖胖猫猫瓶', NULL, NULL, 0, '弧线圆润的药剂瓶体，如同胖胖的猫猫头，喜欢可爱事物的顾客很容易被这种瓶体吸引注意力…\n可以略微提升药剂的品质，所有特殊瓶体提供的增益效果相同。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120830, '风车菊的气息', NULL, NULL, 0, '风车菊与翠绿树叶相结合的瓶体配饰，似乎能让药剂被和煦之风环绕…', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120831, '如晶蝶般璀璨', NULL, NULL, 0, '晶蝶造型的瓶体配饰，尤为亮眼，有时能瞬间吸引顾客的目光…', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120832, '完美赠礼织带', NULL, NULL, 0, '蝴蝶结缎带造型的瓶体配饰，似乎能让药剂充满礼物盒包装般的惊喜感…', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120833, '莓红飞花一羽', NULL, NULL, 0, '有着莓红点缀物的羽毛造型瓶体配饰，据说能让顾客和使用者联想到飞鸟的意象…', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120834, '鎏金与青宝石', NULL, NULL, 0, '金色框体与青色宝石外形的瓶体配饰，「宝石」由玻璃制成，兼顾了美观与成本…', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120835, '店铺饰物-「士气花花」', NULL, NULL, 0, '骑士团的炼金店铺专用的特别装潢，美观的双层花坛，据说是由某位调查小队的队员捐赠的「士气提升品」。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120836, '店铺饰物-「氛围花花」', NULL, NULL, 0, '骑士团的炼金店铺专用的特别装潢，栽有蓝色与米色的花卉，据说是某位后勤小队队员打造的「氛围营造品」。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120837, '店铺饰物-「高效药剂」', NULL, NULL, 0, '骑士团的炼金店铺专用的特别装潢，可被悬挂在店铺的棚体上，画面上的药剂采用了大众印象中的经典造型…', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120838, '店铺饰物-「奇妙药剂」', NULL, NULL, 0, '骑士团的炼金店铺专用的特别装潢，也是在蒙德城各处宣传炼金店铺所用的广告牌，画面上的药剂采用了大众印象中的经典造型…', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120839, '店铺饰物-「多色效应」', NULL, NULL, 0, '骑士团的炼金店铺专用的特别装潢，悬挂着多种颜色的小彩旗，据说「多彩」也象征着奇妙炼金药剂的多种功效…', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120840, '经销拓展合同', NULL, NULL, 0, '额外聘用一位经销商。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120858, '明黄曜石断片', NULL, 4, 410007, '在探索时偶然得到的，刻画有「回声之子」风格纹饰的黑曜石断片。看上去只要有如是三个就能够组成一个完整的环，但不知道有什么作用。', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"坚岩隘谷、万火之瓯探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120859, '明黄曜石环', NULL, 5, 410007, '刻画有「回声之子」风格纹饰的黑曜石环，是部族与深沉夜晚建立联系所用的古老媒介，或许可以凭借它的力量跨越某处的边界…', 'CONSUME', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120875, '培育区域扩展·其七', NULL, NULL, 0, '增加一块可用于培育药材的区域。', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120876, '药材研析仪', NULL, NULL, 0, '骑士团特制的药材研析装置，可以将炼金店铺中用到的药材置入其中，分析其特性，提升相应的「药材等级」，进而从多方面改善使用药材时的效能…', 'CONSUME', NULL, NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120912, '翠青曜石断片', NULL, 4, 410007, '在探索时偶然得到的，刻画有「悬木人」风格纹饰的黑曜石断片。看上去只要有如是三个就能够组成一个完整的环，但不知道有什么作用。', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"踞石山、万火之瓯探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120913, '翠青曜石环', NULL, 5, 410007, '刻画有「悬木人」风格纹饰的黑曜石环，是部族与深沉夜晚建立联系所用的古老媒介，或许可以凭借它的力量跨越某处的边界…', 'CONSUME', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (120914, '湛蓝曜石断片', NULL, 4, 410007, '在探索时偶然得到的，刻画有「流泉之众」风格纹饰的黑曜石断片。看上去只要有如是三个就能够组成一个完整的环，但不知道有什么作用。', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"涌流地探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
