INSERT INTO `materials` VALUES (120961, '采集用-燃素能量球', NULL, NULL, 10, '燃素能量球', 'CONSUME', '获取燃素', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121103, '幽紫曜石断片', NULL, 4, 410007, '在探索时偶然得到的，刻画有「烟谜主」风格纹饰的黑曜石断片。看上去只要有如是三个就能够组成一个完整的环，但不知道有什么作用。', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"镜璧山探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121104, '幽紫曜石环', NULL, 5, 410007, '刻画有「烟谜主」风格纹饰的黑曜石环，是部族与深沉夜晚建立联系所用的古老媒介，或许可以凭借它的力量跨越某处的边界…', 'CONSUME', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121105, '灼赤曜石断片', NULL, 4, 410007, '在探索时偶然得到的，刻画有「花羽会」风格纹饰的黑曜石断片。看上去只要有如是三个就能够组成一个完整的环，但不知道有什么作用。', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"翘枝崖、奥奇卡纳塔探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121106, '灼赤曜石环', NULL, 5, 410007, '刻画有「花羽会」风格纹饰的黑曜石环，是部族与深沉夜晚建立联系所用的古老媒介，或许可以凭借它的力量跨越某处的边界…', 'CONSUME', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121107, '青绛曜石断片', NULL, 4, 410007, '在探索时偶然得到的，刻画有「沃陆之邦」风格纹饰的黑曜石断片。看上去只要有如是三个就能够组成一个完整的环，但不知道有什么作用。', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"安饶之野探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121108, '青绛曜石环', NULL, 5, 410007, '刻画有「沃陆之邦」风格纹饰的黑曜石环，是部族与深沉夜晚建立联系所用的古老媒介，或许可以凭借它的力量跨越某处的边界…', 'CONSUME', '冒险道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121251, '爱诺的工具箱（空）', NULL, 4, 260102, '存放爱诺小饰品的工具箱，如今饰品已被取走。', 'CONSUME', '贵重物品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121253, '伊涅芙的工具箱（空）', NULL, 4, 260102, '存放伊涅芙小饰品的工具箱，如今饰品已被取走。', 'CONSUME', '贵重物品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121279, '蛋卷螺栓', NULL, 3, 410200, '刻着蛋卷工坊标识的螺栓，似乎可以在那里派上用场。', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121283, '恒月印磐', '恒月印磐 0', 4, 410007, '集齐3个印磐后，可开启希汐岛宝库。\n\n在探索时偶然得到的圆形符印，如能找到纹样相同的3个，似乎就能拼凑出曾经照亮世界的皓月的影迹。', 'CONSUME', '冒险道具', NULL, NULL, NULL, '[\"希汐岛探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121284, '恒月印磐', '恒月印磐 1', 4, 410007, '集齐3个印磐后，可开启帕哈岛宝库。\n\n在探索时偶然得到的圆形符印，如能找到纹样相同的3个，似乎就能拼凑出曾经照亮世界的皓月的影迹。', 'CONSUME', '冒险道具', NULL, NULL, NULL, '[\"帕哈岛探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121285, '恒月印磐', '恒月印磐 2', 4, 410007, '集齐3个印磐后，可开启伦波岛宝库。\n\n在探索时偶然得到的圆形符印，如能找到纹样相同的3个，似乎就能拼凑出曾经照亮世界的皓月的影迹。', 'CONSUME', '冒险道具', NULL, NULL, NULL, '[\"伦波岛探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121330, '已记载的情报', NULL, 2, 410300, '由「秘闻馆」中的人士所调查且记载下的情报。或许冒险家协会对此会有兴趣…', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121450, '虹月印磐', '虹月印磐 0', 4, 410007, '集齐3个印磐后，可开启虚海望宝库。\n\n在探索时偶然得到的圆形符印，如能找到纹样相同的3个，似乎就能拼凑出曾经照亮世界的皓月的影迹。', 'CONSUME', '冒险道具', NULL, NULL, NULL, '[\"虚海望探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121451, '虹月印磐', '虹月印磐 1', 4, 410007, '集齐3个印磐后，可开启逐浪野宝库。\n\n在探索时偶然得到的圆形符印，如能找到纹样相同的3个，似乎就能拼凑出曾经照亮世界的皓月的影迹。', 'CONSUME', '冒险道具', NULL, NULL, NULL, '[\"逐浪野探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121452, '虹月印磐', '虹月印磐 2', 4, 410007, '集齐3个印磐后，可开启烟硌山峰宝库。\n\n在探索时偶然得到的圆形符印，如能找到纹样相同的3个，似乎就能拼凑出曾经照亮世界的皓月的影迹。', 'CONSUME', '冒险道具', NULL, NULL, NULL, '[\"烟硌山峰探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121601, '古蒙德宗室之印', NULL, 4, 410007, '集齐2个宗室之印后，可开启宗室密藏之地。\n\n在探索时偶然得到的古代符印，如能找到纹样相同的2个，似乎就能打开旧日蒙德宗室留下的藏宝库。', 'CONSUME', '冒险道具', NULL, NULL, NULL, '[\"风息山探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (121602, '切片辖域管控模块·零质点', NULL, 4, 410007, '集齐3个辖域管控模块后，可开启诸界秘展之厅。\n\n在探索时偶然得到的奇怪模块，如能找到纹样相同的3个，似乎就能打开空之神殿中封锁的秘藏展厅。', 'CONSUME', '冒险道具', NULL, NULL, NULL, '[\"空之神殿探索奖励\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131000, '花鳉', NULL, 3, 341, '活泼好动的小型鳉鱼，以优美的花瓣型鱼尾闻名。\n大多时候都以观赏鱼的身份幸福生活着。但在人们发现了它肉质醇香、少刺多脂的特点后，被精心料理、呈上餐盘的情况也便不罕见了。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131001, '琉璃花鳉', NULL, 3, 341, '活泼好动的小型鳉鱼，以优美的花瓣型鱼尾闻名。\n有着难以捉摸的行为方式，常能见到它们毫无征兆地挣扎起来，似乎正忍受着某种看不见的痛苦，但在其落单的情况下，便不会发生这种事情。有学者猜测，这可能与它们天生的表演欲有关。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131002, '甜甜花鳉', NULL, 3, 341, '活泼好动的小型鳉鱼，以优美的花瓣型鱼尾闻名。\n可能是最爱甜食的一种鳉鱼，身体的每个部分都是一种甜味搜索器，循着甜蜜主义的指引，它们巡游到了提瓦特每条溪流，恪守绝对公正的教旨，对所有甜食一视同仁，绝不因为某些甜味饵料裹挟着鱼钩就将其拒之门外。你肯下饵，它们就肯上钩。\n钓鱼新手友好。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131003, '蓝染花鳉', NULL, 3, 341, '活泼好动的小型鳉鱼，以优美的花瓣型鱼尾闻名。\n早先有种趣闻——将普通花鳉投入蓝色染缸，就能得到更贵的蓝染花鳉。这类说法大约是从孩童的天真玩笑里流传开的，但却意外点拨了不少无良鱼贩。于是每隔段时间，坊间就会出现「你买的花鳉怎么还掉色？」之类的对话。对此，总务司市坊署特地张贴过告示——「市场纷乱繁杂，警惕蓝鱼充数。」', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131004, '擒霞客', NULL, 3, 341, '体表浮现着斑斓霞光的珍稀鳉鱼，看似普通花鳉的变种，但无论是习性还是外观都有不小区别。\n在民间传闻中，这种鱼儿还有预测天气的神异能力。每个晨光刺破天际的时刻，若能见到它们跃出水面、将小小身躯撞入第一缕朝霞，那意味着接下来，人们将会享受到一整日的好晴天。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131005, '水晶宴', NULL, 3, 341, '如水晶般闪耀的珍稀鳉鱼，花纹繁复，堪称鳉鱼中的美术家。\n有商贩宣称，这种鳉鱼在极端条件中会产下一种水晶珍珠，十分名贵，是上流的象征。这让它们受到各路人士的追捧，市面上的价格也一路水涨船高。但这在了解内情的渔师眼里却颇为滑稽：那珍珠明明只是被误食的鳅鳅宝玉而已，打腌臜鱼肠滚进去，再从有心商贩嘴里吐出来，怎就摇身一变、价值连城了？', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131006, '肺棘鱼', NULL, 3, 341, '长满刺状鳍的迅猛鱼类，全速游动时矛般尖吻甚至能劈开水流。因此又得名「劈水刺」、「箭难追」等。\n与诸多同类相异，肺棘鱼可以在干涸的泥塘中存活很久，除了鳃部，它们还能用退化了鳞片的皮肤来呼吸，这更符合两栖类的性状，因此除了不请自来的渔师，它们还面临着被棘鱼学科除名的存在性危机。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131007, '斗棘鱼', NULL, 3, 341, '长满刺状鳍的迅猛鱼类，全速游动时矛般尖吻甚至能劈开水流。因此又得名「劈水刺」、「箭难追」等。\n有着棘鱼中数一数二的自尊心。尤其在求偶期间，任何一点风吹水皱都有可能激怒它们。曾有爱好者观察到一条斗棘鱼正向着摇曳的水草发起冲锋，显然它认为如此放荡形骸的舞姿是对棘鱼王者的严重挑衅。\n「若在水下相遇，请勿与它们对视。」——《野钓手册·斗棘鱼篇》', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131008, '鸩棘鱼', NULL, 3, 341, '长满刺状鳍的迅猛鱼类，迅捷灵敏，全速游动时矛般尖吻甚至能劈开水流。因此又得名「劈水刺」、「箭难追」等。\n鸩棘鱼最为人熟知的是其带毒的棘刺，这种神经毒素对小型猎物足够致命，但对大型生物则显得力不从心，多数情况下只有致惑、致幻等不良症状。\n「满上！岩王老弟！给哥哥满上！」——某位不慎被刺伤的璃月渔师。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131009, '赤魔王', NULL, 3, 341, '外表凶恶、表里如一的凶猛棘鱼，为了争抢食物它们不忌讳攻击任何水下生物，是令人生畏的赤色悍匪。与生俱来的火红表皮似乎与火元素有着千丝万缕的联系，虽然没能让它们直接变成烈焰发生器，却仍然赋予了掌控高温的能力。它们能够转化食物中的能量，并将其集中在危险的尖吻上，这让它们成为不折不扣的水底混蛋。\n「钻木取火好帮手。」——《野钓手册·赤魔王篇》', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131010, '雪中君', NULL, 3, 341, '祖祖辈辈都生活在雪山地区的珍稀棘鱼，或许正因如此。其性格意外的冷静，远不如同类那样凶狠暴躁。这种棘鱼对寒冷有着非同寻常的依恋，像父母之于孩子。虽然它们的确能在温暖水域存活，但远离寒冷似乎会让它们遭受某种心理上的重创，进而郁郁寡欢，停止繁衍。\n「不建议捕捉它们。」——《野钓手册·雪中君篇》', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131011, '金赤假龙', NULL, 3, 341, '被传为龙之后裔的大型鱼类。\n额上长角，体表无鳞，有金赤战袍加身，有水中王者风姿。实际就血统与习性而论，它们与龙之间的距离差之千里——既无呼风唤雨之能，又无雄踞一方之技，甚至由于性格过于软弱，还常被其他掠食性鱼类抢夺食物，实在愧对这一副威风凛凛的好相貌。因此只能摘下「龙裔」之称，屈居「假龙」之号。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131012, '锖假龙', NULL, 3, 341, '被传为龙之后裔的大型鱼类。\n是假龙族群的旁支，也可以说是假龙族群中的觉醒者。跟它不成器的表亲相比， 锖假龙褪下了原先银样蜡枪头般的金赤战袍，取而代之的是其貌不扬却硬如精铁的锖色铠甲，意志坚定，为了食物和领地敢于向任何进犯者发起反击。就战斗力而言，它们已经能够与小型海兽一较高下，堪称振兴族群的骨干力量，又有「铁骨海龙」的尊称。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131013, '流纹褐蝶鱼', NULL, 3, 342, '性情温和，姿态优雅的蝶鱼，拥有流线型的美丽背鳍，又有「水中王后」的美誉。\n体表环绕着大地色的纹路，脾气也如同岩石般沉稳，缺点是沉稳过头了，有时会像岩石一样沉在水底不动，以致常让买家怀疑买到了已经无力回天的老头鱼。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131014, '流纹京紫蝶鱼', NULL, 3, 342, '性情温和，姿态优雅的蝶鱼，拥有流线型的美丽背鳍，又有「水中王后」的美誉。\n体表环绕着京紫色纹路，喜好群居，以此来抵抗环境和天敌的危险。但这种习性被老道的渔师摸透后，便成了反过来捕捉它们的良方——只要想办法将头鱼引进陷阱，剩下的家伙就坐看它们自投罗网就好。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131015, '流纹茶蝶鱼', NULL, 3, 342, '性情温和，姿态优雅的蝶鱼，拥有流线型的美丽背鳍，又有「水中王后」的美誉。\n体表环绕着茶色的纹路，好奇心旺盛，对一切活动物体都抱有强烈的兴趣，而它们表达兴趣的方式就是用嘴试试能不能吃，虽然不是什么带有恶意的攻击，但却因此常常招来灭顶之灾。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131016, '长生仙', NULL, 3, 342, '生活在璃月的珍稀蝶鱼，如今只在仙家之所附近的水域中出没，体表的妃白色纹路轻逸出尘，相较于其他同类而言，寿命也更为悠长，因此又被认为是受仙人恩赐的祥瑞之鱼。\n出于敬仙的朴素观念，多数璃月人拒绝食用这种蝶鱼，但也有不信邪的少数派坚信吃了它们可以延年益寿。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131017, '雷鸣仙', NULL, 3, 342, '生活在稻妻的珍稀蝶鱼，喜好雷元素聚集的水域，似乎能从电流中攫取欢愉。\n相传原本与生活在璃月的「长生仙」源出一脉，直到被旅行商人引入稻妻后，生态上发生了意想不到的变化。就目前而言，已经有学者利用它们与雷史莱姆进行通电研究了。\n「麻...麻...舌陀...麻噜...」——某位贪食了「雷鸣仙」料理的老饕。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131019, '炮鲀', NULL, 3, 342, '圆润短小的腹鳍、肥硕敦厚的身躯和老实巴交的脑袋构成了人们对炮鲀的第一印象。这准确地反应了它的大部分个性——呆板、迟钝、缓慢。但少有人知的是，这样的傻瓜外表下却隐藏了一项绝杀秘技——将水流快速吸入身体，然后像炮弹一样从嘴里射出去，精准，强力，即使是渔夫挨上这么一下也免不了七晕八素，是一等一的水中杀手。\n「前有炮鲀出没，小心躲避口水。」——《野钓手册·炮鲀篇》', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131020, '苦炮鲀', NULL, 3, 342, '稀有的炮鲀品种，鱼如其名，是在水底世界传播苦涩的家伙。与普通炮鲀相较，它们射出的水炮速度更慢、体积更小，但却因为附着了极具刺激性的苦味信息素而让威力不退反进。在求偶期间，还经常能够见到雄性和雌性之间互相喷射苦味水炮的奇景，或许向彼此传递生命中的苦涩，也是一种爱意的体现吧。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131021, '迪芙妲鳐', NULL, 3, 342, '曾经一度被认为是幻想生物的奇异鳐鱼，只被记录在一些海祇岛的古老画卷中。如今随着尘封的海渊被打开，它们的真实样貌才展现在人们眼前。\n据传这种奇异生物的体色会随着时间的变化而变化，幼年时通常呈现出皦日一般的浅金色。在古画卷的记录中，这个时期的它们被冠以「迪芙妲」之名，其意为「纯真之尾」。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131022, '佛玛洛鳐', NULL, 3, 342, '曾经一度被认为是幻想生物的奇异鳐鱼，只被记录在一些海祇岛的古老画卷中。如今随着尘封的海渊被打开，它们的真实样貌才展现在人们眼前。\n据传这种奇异生物的体色会随着时间的变化而变化，幼年时通常呈现出如同皦日一般的浅金色，成年后体色会变深，双翼也被如同夜幕一般的暗紫色覆盖。在古画卷的记录中，这个时期的它们被冠以「佛玛洛」之名，其意为「贪婪之口」。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131023, '真果角鲀', NULL, 3, 342, '体型圆润的中型鱼类，生有犄角般的软骨结构，据说它们会用这一结构开凿水下洞穴，建造栖身之所，或是驱赶试图伤害自己的生物。\n体表呈现出青绿色彩的角鲀是这一谱系中最常见的品种，状如枝头尚未成熟的果实，因而得名「真果」。\n虽说这种角鲀鱼刺极少，肉质肥美，但要是处理的方式不当，或是摘除胆囊的时间较晚，鱼肉就会像未熟果实般的酸涩。因此，「能否制作鲜美的角鲀料理」也成了衡量须弥厨师技艺的标准之一。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131024, '沉波蜜桃', NULL, 3, 342, '体型圆润的中型鱼类，生有犄角般的软骨结构，据说它们会用这一结构开凿水下洞穴，建造栖身之所，或是驱赶试图伤害自己的生物。\n通体粉红，尾鳍嫩绿的角鲀，常让人联想到墩墩桃。鱼如其名，它们的口感确实相当甜美，以至于被鱼师们认定「用来做甜品都不为过」。\n当然，在种种因素的影响下，鱼师们期待的鱼肉甜品并未获得成功。加上这种角鲀较为少见，价格高昂，难以作为食材，人们通常将它作为观赏鱼养殖。\n由于不想花费大笔钱财购买这种角鲀，但又喜爱其明艳色彩的客户基数较大，甚至有商人反其道而行之，当真用墩墩桃制作了这种角鲀的模型，销量还相当不错。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131025, '吹沙角鲀', NULL, 3, 342, '体型圆润的中型鱼类，生有犄角般的软骨结构，据说它们会用这一结构开凿水下洞穴，建造栖身之所，或是驱赶试图伤害自己的生物。\n这种角鲀有着黄沙般的色泽，其貌不扬，却是相当重要的品种。学者们根据这种角鲀的生理结构，推断出了整个角鲀谱系的生态特点——这种角鲀有着同族中最强的力量和最坚硬的犄角，扮演着「水下工人」的角色。由于长期在河床与湖底活动，与弥漫的河沙与湖沙为伴，它们也进化出了相应的保护色。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131026, '暮云角鲀', NULL, 3, 342, '体型圆润的中型鱼类，生有犄角般的软骨结构，据说它们会用这一结构开凿水下洞穴，建造栖身之所，或是驱赶试图伤害自己的生物。\n作为角鲀中最为长寿的品种，它们有着淡暮云灰的体色，易于辨识。这种体色来源于它们独特的生存之道——它们的皮质中含有和胆汁相似的成分，酸涩程度远超其他角鲀，许多水下生物对其敬而远之。\n不过用特殊的手法烹饪后，这种酸味反倒能为鱼肉的鲜美增色，导致这种角鲀的销路极佳。在须弥的鱼市经常能看见「请勿将暮云角鲀与其他食用鱼类饲养在同一水池中」的告示牌。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131027, '青金斧枪鱼', NULL, 3, 342, '形貌独特的鱼类，是蝶鱼的须弥远亲。这种鱼类的骨架宽大，身形曲线独具一格。相传最早钓上这种鱼的鱼师将钓竿斜放在尾鳍末端，发现两者结合后形如某种长柄武器，为其取名「斧枪鱼」。相比它的学名「锚钩蝶」，这个名字更为形象，因而在民间广为流传。\n虽说名字来源于武器，体内蕴含的力量在鱼类之中也位居前列，但斧枪鱼大多有着温厚的性格，体表生有着青金色纹路的斧枪鱼尤其如此。得益于坚硬的鳞片和力量的优势，斧枪鱼能从容应对其他水生生物的攻击，等到对方精疲力竭后悠然离去。\n它们的力气对于鱼师而言也是一种挑战，唯有做好对抗大型猛兽的准备，在它们咬钩时就全力以赴，才能有效消耗它们的体能，将它们钓获。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131028, '翡玉斧枪鱼', NULL, 3, 342, '形貌独特的鱼类，是蝶鱼的须弥远亲。这种鱼类的骨架宽大，身形曲线独具一格。相传最早钓上这种鱼的鱼师将钓竿斜放在尾鳍末端，发现两者结合后形如某种长柄武器，为其取名「斧枪鱼」。相比它的学名「锚钩蝶」，这个名字更为形象，因而在民间广为流传。\n色泽如翡玉的斧枪鱼喜欢在水生植物茂盛的区域活动，身形极易与背景相融，若隐若现。穿行在水草间的小鱼常常撞上它们屏障般的身体，晕头转向，不过翡玉斧枪鱼也不会被激怒，反而会适时为这些邻居提供庇护。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131029, '海涛斧枪鱼', NULL, 3, 342, '形貌独特的鱼类，是蝶鱼的枫丹远亲。这种鱼类的骨架宽大，身形曲线独具一格。相传最早钓上这种鱼的鱼师将钓竿斜放在尾鳍末端，发现两者结合后形如某种长柄武器，为其取名「斧枪鱼」。相比它的学名「锚钩蝶」，这个名字更为形象，因而在民间广为流传。\n传说，有着「海涛蓝」色泽的斧枪鱼是从须弥水域迁徙至枫丹的特例。相比性格温和的须弥亲属，海涛斧枪鱼的确有着更为坚忍的性格，能在恶劣的环境下长期生存，或是长途跋涉，航程媲美一些商船。因此，也有船员将其视为勇气和耐心的象征。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131030, '波波心羽鲈', NULL, 3, 342, '侧面样貌呈心形的奇特鱼类，据说与鲈鱼有着一定的亲缘关系，又因羽毛般细长软骨构成的背鳍和腹鳍，被学者们形象地命名为「心羽鲈」。\n作为心羽鲈中重要的品种之一，波波心羽鲈有着与外貌不符的航渡能力，甚至可以穿行于怒涛之间。据说这种鱼类露出水面，迎着激流游动时，独特的鱼鳍会发出「波波」的声响。单单从蓝色的水体中辨别出具有保护色的这种鱼类，就已经是一大难题了，大部分鱼师尚未亲耳听见这种独特的音色。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131031, '烘烘心羽鲈', NULL, 3, 342, '侧面样貌呈心形的奇特鱼类，据说与鲈鱼有着一定的亲缘关系，又因羽毛般细长软骨构成的背鳍和腹鳍，被学者们形象地命名为「心羽鲈」。\n得名「烘烘心羽鲈」的这种鱼类有着阳光般独特的色彩，在水中尤为醒目。相传这是一种另辟蹊径的自我保护方法，部分依赖视觉的鱼类会将它们看成「水中燃烧的不明物体」，避而远之。不过，与火热的外表恰恰相反的是，这类心羽鲈的体温较低，摄入的食物又相当之少，有时还会刻意待在浅水区域，晒晒太阳。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131032, '维护机关·初始能力型', NULL, 3, 343, '为了辅助水下活动的发条机关，提升机队总出勤率而开发的紧凑型辅助机关。最初的设计目的是清除水下的垃圾、植物残渣等杂物，避免它们吸附在发条机关关键部位，从而尽可能降低发条机关的故障率。从另一种角度看，它们无疑也扮演着「水下清洁工」的角色，对枫丹的生态环境有益。\n这种机关搭载了灵敏的传感器，能有效用「嗅觉」寻获目标物，或是发现水下垃圾的光学特征。因此，有时它们也会被一些鱼饵吸引。钓上了这种机关的鱼师则将它们称为「水域维护鱼」或「铁鱼」。\n采用轻型木材和低成本金属的这一型号是维护机关稳定量产后的第一批次型号，具备达成设计目的的「初始行动能力」。但使用寿命本身也不太理想。因此，这一型号的投放量相当之大，采取了「分组开机轮替」的模式，即一部分机关活动时限结束或故障瘫痪后，另一部分预先隐藏在水下的机关开机活动，接替岗位。因此，在普通人看来，这些「铁鱼」就像是会自行繁殖一样，源源不断地涌现出来。偶尔钓上来几条，也不需要有什么负罪感。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131033, '维护机关·水域清理者', NULL, 3, 343, '为了辅助水下活动的发条机关，提升机队总出勤率而开发的紧凑型辅助机关。最初的设计目的是清除水下的垃圾、植物残渣等杂物，避免它们吸附在发条机关关键部位，从而尽可能降低发条机关的故障率。从另一种角度看，它们无疑也扮演着「水下清洁工」的角色，对枫丹的生态环境有益。\n这种机关搭载了灵敏的传感器，能有效用「嗅觉」寻获目标物，或是发现水下垃圾的光学特征。因此，有时它们也会被一些鱼饵吸引。钓上了这种机关的鱼师则将它们称为「水域维护鱼」或「铁鱼」。\n相比于大量铺货的「初始能力型」，这一更为成熟的量产型号「水域清理者」的表面刷有耐腐蚀能力极强的涂层，而且，该项目的研究员，不再采用一次性投放，投放后不理的运行方案，而是为其引入了周期性回收维护的设计——研究员们会用特定频率的闪光向维护机关的传感器发送归航信号，将它们回收，适当修理与检查，再放回水中继续工作。这种特定频率的闪光后来则演变成一种专门针对维护机关族群的鱼饵，通过不明渠道，在普通鱼师的群体中流传了开来。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131034, '维护机关·态势控制者', NULL, 3, 343, '为了辅助水下活动的发条机关，提升机队总出勤率而开发的紧凑型辅助机关。最初的设计目的是清除水下的垃圾、植物残渣等杂物，避免它们吸附在发条机关关键部位，从而尽可能降低发条机关的故障率。从另一种角度看，它们无疑也扮演着「水下清洁工」的角色，对枫丹的生态环境有益。\n这种机关搭载了灵敏的传感器，能有效用「嗅觉」寻获目标物，或是发现水下垃圾的光学特征。因此，有时它们也会被一些鱼饵吸引。钓上了这种机关的鱼师则将它们称为「水域维护鱼」或「铁鱼」。\n某些特定情境下，维护机关会将一些水下生物的食物当成垃圾清理，并与水下生物发生冲突，功率较低的小型机关自然占不到上风。久而久之，如此折损的维护机关总量愈发悲观。\n为了保护前两种型号的维护机关，让它们安全地清理水域，研究员们沿用了已有的框架，尽可能提高核心机构的功率密度，开发出了具备一定战斗能力的第三种型号，试图让它们用撞击的方式驱离水下生物，从而为其他维护机关维持一个正常工作的态势，并以原有的生产链快速大量投产。\n然而，研究员们后续加强「态势控制者」的开发计划被枫丹科学院紧急叫停了，毕竟「如果这种小东西都能打跑凶猛的水下生物，那还要原来那些水下机关有什么用！」。事实也证明，这些「态势控制者」根本无法驱赶不利的水下生物，反倒只能「清理」一些普通鱼类，对环境造成严重破坏。因此，研究员们还专门关停了一部分「态势控制者」，并对其攻击行为进行了限制。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131035, '维护机关·白金典藏型', NULL, 3, 343, '为了辅助水下活动的发条机关，提升机队总出勤率而开发的紧凑型辅助机关。最初的设计目的是清除水下的垃圾、植物残渣等杂物，避免它们吸附在发条机关关键部位，从而尽可能降低发条机关的故障率。\n相较于其他量产型号，这一特别的「白金典藏型」维护机关采用了光洁亮丽的壳体，是该开发组专门生产的纪念型号。该组在游说一些财力雄厚的商人，为维护机关项目招商引资时，会将这种纪念品赠送给商人，作为鱼缸中的精致观赏物，的确相当难得。可惜的是，该组所有吸引投资的尝试都以失败告终，转而计划将这种维护机关作为玩具出售，补贴日渐亏空的项目经费池。\n最终，随着那场人尽皆知的事故，整个维护机关开发组彻底停摆，维护机关的后续项目也被取消。目前，枫丹水域内该谱系的维护机关全都无人管理。预先生产的一批「白金典藏型」也全部沉入水中，不知去向，成为了枫丹水域最富特色，也是最昂贵的「鱼类」。随着科学院的一些项目公开，《蒸汽鸟报》的记者们对比资料，深入调查，发现「维护机关投放前后，枫丹水域的污染状况其实并没有显著变化，该项目的效能值得怀疑」。此后，尚能活动的「白金典藏型」维护机关依旧在枫丹的水域中游弋着，鱼师们也开始以钓到「白金典藏型」为荣，毕竟「白金典藏型」的稀有程度和其他国家最珍贵的观赏鱼旗鼓相当。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131036, '维护机关·澄金领队型', NULL, 3, 343, '为了辅助水下活动的发条机关，提升机队总出勤率而开发的紧凑型辅助机关。最初的设计目的是清除水下的垃圾、植物残渣等杂物，避免它们吸附在发条机关关键部位，从而尽可能降低发条机关的故障率。从另一种角度看，它们无疑也扮演着「水下清洁工」的角色，对枫丹的生态环境有益。\n相较于其他量产型号，这一特别的「澄金领队型」维护机关采用了澄澈金色的壳体，以及特别的控制设备。在开发组的设想中，在较为复杂的水下地形活动时，这种维护机关能作为一种高效能的「中继指挥站」，接收并向周围的维护机关分发控制者所下达的各类指令，可以说是宛如「领队」一般的重要机关。\n然而，随着维护机关项目的整体停转，这些「领队机关」们失去了存在的意义，唯有它们富有辨识度的，澄澈金色的外表，使得它们在一些鱼师的眼中具有极高的收藏价值。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131037, '玉玉心羽鲈', NULL, 3, 342, '侧面样貌呈心形的奇特鱼类，据说与鲈鱼有着一定的亲缘关系，又因羽毛般细长软骨构成的背鳍和腹鳍，被学者们形象地命名为「心羽鲈」。\n「玉玉心羽鲈」的色泽尤为特别，如同水中的翡玉，因而获得了这一美称。它们有着与安静外貌完全不符的强韧生命力，能在多种特性截然不同的水域存活，而沉玉谷清冽的水质对于它们而言更是无可挑剔，在美玉之名广为流传的沉玉谷，它们生活得无忧无虑，健康安逸。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131038, '繁花斗士急流鱼', NULL, 3, 344, '名中带鱼却不属鱼的中型两栖生物，外形独特，有着拳刃般别致的扁平头部，似乎随时能与天敌激烈战斗。实际上，它们天性温和，并不好斗，这种头部构造只是为了减少在河中游动时的水流阻力。得益于这种头部构造，它们能够破开湍急的逆流，在各个水域自如地穿梭，因而获称「斗士急流鱼」。\n明艳粉红的斗士急流鱼被人们冠以「繁花」的前缀，部分游客还误以为它们和「花羽会」或「绒翼龙」有关。据说在有着红褐岩石的浅滩上，这种伪装色对于它们的天敌异常有效。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131039, '深潜斗士急流鱼', NULL, 3, 344, '名中带鱼却不属鱼的中型两栖生物，外形独特，有着拳刃般别致的扁平头部，似乎随时能与天敌激烈战斗。实际上，它们天性温和，并不好斗，这种头部构造只是为了减少在河中游动时的水流阻力。得益于这种头部构造，它们能够破开湍急的逆流，在各个水域自如地穿梭，因而获称「斗士急流鱼」。\n色调偏蓝的斗士急流鱼有着潜入较深水域的能力，不过，由于喜爱阳光直射的温暖感，以及和幼鳍游龙们玩耍的轻松时光，它们不会长时间在水底停留…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131040, '炽岩斗士急流鱼', NULL, 3, 344, '名中带鱼却不属鱼的中型两栖生物，外形独特，有着拳刃般别致的扁平头部，似乎随时能与天敌激烈战斗。实际上，它们天性温和，并不好斗，这种头部构造只是为了减少在河中游动时的水流阻力。得益于这种头部构造，它们能够破开湍急的逆流，在各个水域自如地穿梭，因而获称「斗士急流鱼」。\n生活在液态燃素中的斗士急流鱼亚种有着格外坚韧的表皮，耐受高温的能力尤为出色，被誉为「无法做成烤鱼的鱼」。当然，大部分钓鱼爱好者钓获了炽岩斗士急流鱼后，都会将它们当成珍贵的观赏鱼用心饲养，而不是送进厨房…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131041, '青浪翻车鲀', NULL, 3, 344, '体型扁平的中型鱼类，性格温吞，被认为是纳塔各水域中最不易怒的生物。什么都能往肚里塞的饮食习惯使得它们成为了天然的水域清理者，在民间广受好评。\n据传，许久以前，青浪翻车鲀曾在营养物质过度富集，以至于水体表面漂浮着厚重藻类的水域出没，抑制了藻类的过度繁衍。如今「流泉之众」一带的明彻湛蓝的水质，或许也有它们的几分功劳。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131042, '晚霞翻车鲀', NULL, 3, 344, '体型扁平的中型鱼类，性格温吞，被认为是纳塔各水域中最不易怒的生物。什么都能往肚里塞的饮食习惯使得它们成为了天然的水域清理者，在民间广受好评。\n在一些民间故事中，这种翻车鲀明红与浅蓝交织的色彩，缘于它们「饮下了晚霞的余晖」，而阳光与焰光是纳塔人所爱所敬之物，这个故事在璃月和枫丹的作家们看来，属于「纳塔特有的浪漫」。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131043, '拟似燃素独角鱼', NULL, 3, 344, '生有独角的奇特鱼类，体型圆润敦实，鱼肚富有弹力，堪比气球。\n其头顶的晶体角状物与固态燃素有着相仿之处，不过据研究，在这种鱼类刚孵化时，其角状物晶莹剔透，如同玻璃，在液态燃素中长期生活，着色物质累积后，才呈现出现有的色泽，获得了「拟似燃素」的戏称。\n每隔几年，独角鱼头顶的「拟似燃素」晶体就会在生长作用下少量崩落，崩落后的碎片是非常珍贵的染色原料，被涂鸦爱好者们视为「火焰的色彩」。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131044, '伪装鲨鲨独角鱼', NULL, 3, 344, '生有独角的奇特鱼类，体型圆润敦实，鱼肚富有弹力，堪比气球…其实真的内置了类似气球的浮力舱。\n「拟似燃素独角鱼」能为涂鸦爱好者们带来珍贵的颜料，却又仅能在液态燃素环境中生存，「涂鸦联盟」开始探索在普通水域饲养这种鱼类的可行性。为此，「涂鸦联盟」的上上上任盟主联合纳塔钓鱼协会，斥巨资从枫丹引入了发条鱼类，即「维护机关」的技术，开发了内置数据收集系统的生态模仿机关，进行了一番观察和研究。结果令人遗憾，离开了液态燃素环境后，独角鱼的晶体角状物再也不会焕发出火焰般的光彩，这一计划以失败告终。\n好在，这种机关独角鱼游动时，远看水面以上的部分，就如鲨鱼的背鳍，「流泉之众」向「涂鸦联盟」和纳塔钓鱼协会适量购买了这种「伪装鲨鲨」，用于为冲浪的游客提供刺激而安全的体验，以及在部分水域震慑不法分子。', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131045, '秘源机关·巡戒使', NULL, 3, 344, '行动灵巧，构型如同游鱼的小型机关，似乎与深古遗迹中的机械体有着的同源技术，能够在各种液体环境下运转，包括高热的液态燃素——抑或是其本身就有着侦测热源的设计意图，会自动趋近高热信号。\n正是因为其「寻热」的特性，技艺娴熟的鱼师能用散发热量的鱼饵将其诱捕。拆解后，还能获得古老文明的奇特装置。因此，这种「机关鱼类」可谓价值连城…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131046, '无奇巨斧鱼', NULL, 3, 345, '形貌独特的鱼类，与斧枪鱼有着一定的亲缘关系。曾有生物学家调侃，斧枪鱼选择了「斧状下腹」，而巨斧鱼选择了「斧状头壳」。\n不过，除去醒目的轮廓，巨斧鱼中数量最多的亚种并无任何特别之处，说是挪德卡莱水域「平平无奇」的代表也不为过…\n那夏镇酒馆的传说中，有的鱼师反而盯上了「无奇巨斧鱼」普普通通的特性，会特意训练其中一些聪颖的个体，用背脊去切断竞争对手的鱼线…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131047, '冷冽巨斧鱼', NULL, 3, 345, '形貌独特的鱼类，与斧枪鱼有着一定的亲缘关系。曾有生物学家调侃，斧枪鱼选择了「斧状下腹」，而巨斧鱼选择了「斧状头壳」。\n有着蓝紫背脊的巨斧鱼曾被普通鱼师误认为「来自海冰漂浮的北方水域」，较为珍贵，并将之置于接近冰点的水中饲养。其实，它们独特的色彩来源于不同「无奇巨斧鱼」的进食习惯。若是要研究水域中各种养分的「传导链」，这种鱼类无疑是个很好的样本节点…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131048, '炽铁巨斧鱼', NULL, 3, 345, '形貌独特的鱼类，与斧枪鱼有着一定的亲缘关系。曾有生物学家调侃，斧枪鱼选择了「斧状下腹」，而巨斧鱼选择了「斧状头壳」。\n背脊如同烙铁般炽红的特殊个体，在挪德卡莱区域极为少见。相传，激怒自然之人乘船漂浮于水波之上时，这种巨斧鱼会悄然出现，用滚烫的背脊划破船体，让恶人沉底溺亡，因此，走运的渔师也会对上钩的「炽铁巨斧鱼」充满敬意，要么将其放生，要么用华丽的鱼缸将其认真供养…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131049, '素素凶凶鲨', NULL, 3, 345, '游弋在挪德卡莱水域的猎手，无比凶悍的肉食鱼！曾经什么都敢往嘴里塞，大口将之嚼碎，但在不少个体误食「月矩力试验设计局」投下的未爆物后，已老实。\n更惨的是，渔师们会用各种武器问候这些鲨鱼，以防它们吞食潜在的鱼获。因此，这类鲨鱼已逐渐演化出杂食的习性，有什么吃什么，甚至有些个体吃素数年都未曾开荤，也未见营养不良…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131050, '虹光凶凶鲨', NULL, 3, 345, '游弋在挪德卡莱水域的猎手，无比凶悍的肉食鱼！曾经什么都敢往嘴里塞，大口将之嚼碎，但在不少个体误食「月矩力试验设计局」投下的未爆物后，已老实。\n见识到普通凶凶鲨的遭遇后，一些智慧的个体开始学习伪装自身，并通过吞食相对无害的有色食物，演化出如同彩灯招牌般的花纹，如此一来，它们埋伏水下不动时，挪德卡莱的渔师们就会以为它们是水下的垃圾…吗？\n遗憾的是，并不会。彩灯招牌很贵重，一般商家不会轻易将其丢弃…但这些特殊的凶凶鲨反倒因为外表特别，歪打正着，被一些渔师有意保护，总算有了开荤的机会…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131051, '蓝昼明眼鱼', NULL, 3, 345, '外形亮眼的鱼类，有着水晶般晶莹剔透的头腔，常出没于挪德卡莱水域。具有蓝色外表的个体常使人联想到无云的天空，因此有了「蓝昼」的美称。\n据研究，这种鱼类的头部充满保护性的液体，主要的双眼位于其中，可以看向各个方位，观察能力卓越。但时常有动物误认为，其鱼嘴两侧的结构是闭上的双眼，它们一直在睡觉…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131052, '夜色明眼鱼', NULL, 3, 345, '外形亮眼的鱼类，有着水晶般晶莹剔透的头腔，常出没于挪德卡莱水域。具有深色外表的个体常使人联想到无星的夜空，因此有了「夜色」的美称。\n据研究，这种鱼类的头部充满保护性的液体，主要的双眼位于其中，可以看向各个方位，观察能力卓越。得益于这种身体结构带来的卓越光通量，「夜色明眼鱼」在深水或夜间活动时，相比其他动物，有着更为清晰的视野，能帮助它们及时应对多种威胁…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (131053, '綦假龙', NULL, 3, 341, '被传为龙之后裔的大型鱼类。\n是假龙群族的旁支，主体呈深沉的青黑色，腹部则是醒目的淡金。与众多表亲相比，性格极为温和，从不主动与其他水生生物冲突。当然，这不意味着它们好欺负，受到攻击时，它们能如金枪直刺般暴起一击，将体型数倍于自己的进犯者利落打退，震慑整片水域…', 'EXCHANGE', '鱼', NULL, NULL, NULL, '[\"钓鱼获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200001, '灯纸纤维', NULL, 3, 100, '海灯节期间，用以制作「霄灯」的材料。\n随处可见的纤维素。特殊处理后，可以制成霄灯的灯皮，让它承载着良善的愿望飘向远方。', 'EXCHANGE', '海灯节材料', NULL, NULL, NULL, '[\"植物类采集物中获取\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200002, '灯芯绒材', NULL, 3, 100, '海灯节期间，用以制作「霄灯」的材料。\n随处可见的绒材。特殊处理后，可以制成霄灯的灯芯，让它承载着良善的愿望飘向远方。', 'EXCHANGE', '海灯节材料', NULL, NULL, NULL, '[\"丘丘人系列魔物产出\", \"愚人众精英产出\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200003, '浮生石片', NULL, 3, 100, '海灯节期间，用以制作「霄灯」的材料。\n能自行悬浮的神秘元素石片，是霄灯飞往遥远天际线的秘密，传说也是「群玉阁」漂浮的动力来源。', 'EXCHANGE', '海灯节材料', NULL, NULL, NULL, '[\"矿物类采集物中获取\", \"幼岩龙蜥、岩龙蜥产出\", \"丘丘岩盔王产出\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200101, '霜噬碎屑', NULL, 3, 430061, '从龙脊雪山的魔物处提取出来的小块结晶。\n仅仅会在特殊的时期产生。', 'CONSUME', '雪山材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200102, '霜噬结晶', NULL, 3, 430061, '从龙脊雪山的魔物处提取出来的结晶块。\n仅仅会在特殊的时期产生。', 'CONSUME', '雪山材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200103, '腐殖龙髓', NULL, 4, 90, '「腐殖之剑」专用的精炼道具。\n将散布在龙脊雪山的地脉当中的，「杜林」的腐毒提纯后得到的物质。用在亲和这种物质的「渴血之剑」上的话，可以提升这把剑的力量。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200104, '「看得见的风」', NULL, 4, 90, '「风花之颂」专用的精炼道具。\n象征着风车与风之花的精致饰物，也是「风花之颂」的弓臂上的装饰品。「风」本身看不见、摸不着，而恒常转动着的风车、绿地上摇摆的花朵则是「看得见的风」，向人们昭示着，轻柔的风无时无刻不眷顾蒙德的大地与众生。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200105, '「童真的断篇」', NULL, 4, 90, '「嘟嘟可故事集」专用的精炼道具。\n随风散落的断篇，每一页上都写满童趣之事，而尺寸恰好与《嘟嘟可故事集》完美相合。其间满溢的童心与纯真的爱永不褪色，就像书中永无完结的大冒险一样，热忱的童话永远随着其作者的脚步飞扬。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200106, '海皇香脂', NULL, 4, 90, '「衔珠海皇」专用的精炼道具。\n香气浓郁的膏体，似乎凝结着水中生命的灵气。涂抹在「衔珠海皇」上之后，能将这柄形貌独特的大剑淬炼得更为坚韧。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200107, '赤穗酒枡', NULL, 4, 90, '「渔获」专用的精炼道具。\n过去称霸清籁地方的赤穗百目鬼一众爱用的酒具。被海水带到了渔师的钓钩上。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200108, '「溶媒」', NULL, 4, 90, '「辰砂之纺锤」专用的精炼道具。\n隐隐泛着世外之光的白银液体，对地上之物或许有着蚀骨的猛毒吧。但也具有使物质升华的力量。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200109, '明目之油膏', NULL, 4, 90, '「证誓之明瞳」专用的精炼道具。\n由特殊的深海鳗鳗精炼出的鱼油，曾经被拿来保养渊下宫的神器，使其灼目长明。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200110, '霞色宝珠', NULL, 4, 90, '「落霞」专用的精炼道具。\n以层岩巨渊先民的古老工艺精致打磨而成的石珀宝珠。能够微微散发出如同黎明或夕暮的辉光。对于在不见天日的岩窟中，与漆黑之敌战斗的人而言，或许能带来小小的慰藉吧。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200111, '原海鱼油', NULL, 4, 90, '「竭泽」专用的精炼道具。\n从北方大湖的渔获中提炼出的油膏，能短暂地让成为良弓的鱼恢复生机。\n据说那个大湖中生活着大陆别处绝对无法见到的水生物种。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200112, '迁风的苍翎', NULL, 4, 90, '「风信之锋」专用的精炼道具。\n由松石雕而成的古旧羽翮，在过去似乎曾被用作饰品或信物。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200113, '若狭的藁末', NULL, 4, 90, '「东花坊时雨」专用的精炼道具。\n用以粘接竹簳与伞面的粉剂。\n纵然时节流转、昔日之雨散落成烟，总会有回忆重接思念，宛若置伞、伴梦同眠。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200114, '「不凋的绢华」', NULL, 4, 90, '「饰铁之花」专用的精炼道具。\n「装饰」能够为任何事物附上一份超出其自身价值与功能的小小心意。即便是战斗的工具，在这样的时日，这种不再枯萎的花朵也能为它赋予些许浪漫的内涵。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200115, '凝恒的脂蜡', NULL, 4, 90, '「鹮穿之喙」专用的精炼道具。\n据说后来成为「召唤王」的少年曾在大赤沙海之中受鹮之王的后裔所托，花费数日收集脂蛹熬制护弦之蜡。只是传说中的宝弓随鹮之王消失不复归来，唯有脂蜡的做法代代相传，也许，是为了能够再度使用的某日而作出的准备。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200116, '马腾斯万能护养剂', NULL, 4, 90, '「灰河渡手」专用的精炼道具。\n不但能够在特定材质的表面形成隔离层来避免金属氧化和腐蚀，还有润滑、清洁、抛光作用，曾经在枫丹风靡一时。在当时的广告中，灰河的传奇人物就用它来维护那根著名的弯头铜管。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200117, '蒲公英书签', NULL, 4, 90, '「无垠蔚蓝之歌」专用的精炼道具。\n在许多诗与故事中，蒲公英都是不受拘束、自在、旅行远方的象征。将蒲公英图案的书签夹在书中从某种意义上而言并不是一种禁锢，反而使它能在比现实更广阔、更光明的世界中遨游。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200118, '涌现的圣杯', NULL, 4, 90, '「水仙十字之剑」专用的精炼道具。\n古代枫丹文明喜欢用螺贝制作仪式道具，这个被选做圣杯的螺壳内终于涌现出圣油。从象征意义来说，圣杯是太初的言语，圣油是锤炼的意志，圣剑则是破开一切的理性。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200119, '「超级无敌闪亮亮魔晶」', NULL, 4, 90, '「究极霸王超级魔剑」专用的精炼道具。\n能够将许多心愿（以及帅气的硬纸板）牢牢地拼合在一起，从而诞生出究极无敌的神奇力量。\n虽说造型差不多（或者说完全一样）的小道具在达莫维百货也买得到，但两者之间其实说不定有着本质上的区别，所以千万不要搞混。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200120, '「大地之王」', NULL, 4, 90, '「沙中伟贤的对答」专用的精炼道具。\n在炼金术的基础教程中，水银被叫做「大地之王」，因为它甚至可以贪婪地吞吃黄金。因此炼金术也以它代表金属。\n干涸化为粉尘后依然拥有转变的性质。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200121, '衡仪机枢', NULL, 4, 90, '「筑云」专用的精炼道具。\n由玉衡星委托黑岩厂锻造的新型机件，据工匠所说有着「不逊仙家机关」的传动载荷。安装在对应的实验式兵器上，便可以进一步提升其威力。\n人治之世亦如良弓之弦，唯有定度衡仪，方能使其不至绷断。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200122, '「凝静的海色」', NULL, 4, 90, '「苍纹角杯」专用的精炼道具。\n细密温润的彩砂，质地如傍晚的海风般轻柔。\n在梅兹特利的古老传说中，海是群星的归宿，沉落的星芒终将化作苍色的海砂。静静聆听，瓶中摇晃的，正是星光与海潮的絮语。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200123, '纺灵之梭', NULL, 4, 90, '「厄水之祸」专用的精炼道具。\n如棱镜般折射着奇异光泽的玉石坠饰，即便置于焚火上灼烤，那份萦绕的阴冷依然挥之不去。\n古老的巫术传承中，「梭」本身便象征着穿刺不同界域的媒介。据说在众人尚不知晓怎样数算自己日子、怎样将故事纺成织物的蛮荒年岁，那些流徙于灵火之原的巨龙早已被忘却的语言中，亦将在漆黑死寂的群星间巡行的造物称作「空梭」，哪怕是将一个世界笼罩在内的厚重面纱，也会被流火的梭镖刺破。\n当然，这些说法全部来自狡狯的欺诈师桑哈杰，与他曾经编织出的无数戏言一样，说不定只是用来骗吃骗喝的故事——时至今日，烟谜主一些德高望重的祭司依然抱持着这样的观点。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200124, '灼幽的磷焰', NULL, 4, 90, '「且住亭御咄」专用的精炼道具。\n昔时以火焰为身奔行稻妻的妖怪，散落于四野的残留磷火。就像每一盏油灯都曾记忆围炉夜谈之人的话语，散落的焰火之中，或许也有对某人而言相当重要的回忆。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200125, '强弓校调工具组', NULL, 4, 90, '「冷寂迸音」专属的精炼道具。\n古老的故事中，劫富济贫的逐影猎人、人称「幻戏师」与「行刑人」的沃尔特总是善于利用精密机关的力学效应辅助拉弓射击。据说这种射击方式极度节省体能，从而让沃尔特能够应对可能追至的大量恶人与邪魔。\n这一特性在幻想映影中得到强调，以至于发展出「机关技术强化战士」的夸张形象。\n而探索极限远射与安静射击性能极限的「复合结构猎弓」同样需要多次校准和调试，才能发挥出最为理想的性能。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200126, '漫行者的晶髓', NULL, 4, 90, '「拾慧铸熔」专用的精炼道具。\n看上去只是普通的矿石，在纳塔各地都有出土。但正因为产地的不同，即使是同样的矿石，其石髓亦有细看才能看出的差别——这也是曾经漫行纳塔的旅人收集矿石的原因，有些东西要真切地触碰或握于手中，才可仔细品会其中的不同。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200127, '金色弦丝', NULL, 4, 90, '「天光的纺琴」专用的精炼道具。\n在早已失落的古代文明中，曾有人认为主宰世界的命运就像舞台上的唱段，是由高天之上一架巨大的竖琴编制而成。或许是因为他们曾亲眼见过天使从天光中抽出金色的琴弦，在宏伟的乐声中宣告命运的无情。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200128, '练心', NULL, 4, 90, '「虹蛇的雨弦」专用的精炼道具。\n被弓手长期佩戴的护指，色彩鲜艳，制作精良。\n箭矢的准头有赖于弓手的经验，其人凝息拨弦的次数越多，弓与箭越能随心而动。搭弦挽弓便是练心，护指有多破损，心就有多锐利。', 'AVATAR_MATERIAL', '精炼材料', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200900, '林野钓竿', NULL, 4, 62000, '其貌不扬的木质钓竿，除了比较坚韧，可以当作野外防身武器外，再没有什么值得称道的了。但老话说的好——新手一根竿，老手摆地摊。就算是钓鱼之王，最初也是从这根普通的家伙开始的吧。', 'FISH_ROD', '鱼竿', NULL, NULL, NULL, '[\"任务获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200901, '风缠', NULL, 4, 62001, '钓鱼过程中，若能使张力处于最佳张力区，使用此竿可稳定缩短鱼儿挣扎时间，提高钓鱼成功率。仅蒙德地区生效。\n\n由一位蒙德诗人创造的长竿，碧荧通透。为了借来风的力量帮助提竿，诗人别出心裁地设计了由风车叶组成的渔轮，也使其蕴含了一丝「与风缠绵」的浪漫意味。但不知是制作工艺还是设计本身的问题，最终的完成品并不能如预想中自由转动，或许这就是所谓的隔行如隔山吧？', 'FISH_ROD', '鱼竿', NULL, NULL, NULL, '[\"蒙德钓鱼协会兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200902, '愿者', NULL, 4, 62002, '钓鱼过程中，若能使张力处于最佳张力区，使用此竿可稳定缩短鱼儿挣扎时间，提高钓鱼成功率。仅璃月地区生效。\n\n如竹般高雅挺拔的长竿，据说是一位隐居璃月的高人执藏之竿，最初被发现于一面刻有「负愿者，执竿去」的石碑之上，如传说中的神剑，等待被勇者拔出。当然，如此显赫的来历，尽是从商家口中流出的，所以说不定只是些抬高身价的说辞...但话说回来，凡是知晓这些仍入手者，也都是心甘情愿、自负契约之人吧。', 'FISH_ROD', '鱼竿', NULL, NULL, NULL, '[\"璃月钓鱼协会兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200903, '鸣川鹈饲', NULL, 4, 62003, '钓鱼过程中，若能使张力处于最佳张力区，使用此竿可稳定缩短鱼儿挣扎时间，提高钓鱼成功率。仅稻妻地区生效。\n\n为纪念古老的鹈饲捕鱼法而制的长竿，竿尖的红宝石象征着鹈匠的火绒，竿身的鸟饰象征着鹈匠的鸬鹚，它们曾指引辛勤的稻妻先辈度过艰难的灾变年代。如今这种生产力低下的捕鱼法基本已被弃用，但那种顽强的开拓精神却伴随此竿一同传承下来。', 'FISH_ROD', '鱼竿', NULL, NULL, NULL, '[\"稻妻钓鱼协会兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200904, '长绳系月', NULL, 4, 62004, '钓鱼过程中，若能使张力保持在最佳张力区，使用此竿可加速缩短鱼儿挣扎时间，若离开最佳张力区，加速过程会被重置。\n\n因「海中月」而生的特制长竿。为了应对传说中的大鱼，制作者特别在竿身、鱼线中掺入了罕见的功能材料，使其不仅拥有不俗的延展性，更能承千斤而不崩。如此宝具，用来对付普通鱼儿自然也不在话下，但总是这样牛鼎烹鸡的话，它也会感到负尘蒙羞吧？', 'FISH_ROD', '鱼竿', NULL, NULL, NULL, '[\"活动获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200905, '盘缘', NULL, 4, 62005, '钓鱼过程中，若能使张力处于最佳张力区，使用此竿可稳定缩短鱼儿挣扎时间，提高钓鱼成功率。仅须弥地区生效。\n\n形制古朴的须弥鱼竿，竿体如白玉雕琢，黯金色的纹饰盘绕其上，并以苍青的宝石作为点缀。纯美的形貌之下，似是有着与「生命」相关的寓意——据说须弥最古老的鱼竿就是缠绕着藤蔓的树枝，许多钓鱼宗师用这样的鱼竿完成了他们的「奇迹一钓」。如今的鱼师们也相信，这种历史悠久的鱼竿将为他们带来收获的好运。', 'FISH_ROD', '鱼竿', NULL, NULL, NULL, '[\"须弥钓鱼协会兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200906, '穿浪斗枪', NULL, 4, 62006, '钓鱼过程中，若能使张力处于最佳张力区，使用此竿可稳定缩短鱼儿挣扎时间，提高钓鱼成功率。仅枫丹地区生效。\n\n有着优美金属光泽的修长鱼竿，应用了枫丹科学院的新式金属材料，轻便而坚韧，在多段结构的连接处，还安装了高强度的金属加强导线环，足以吊起重量惊人的鱼类，类似武器护手状的卷线器轮座则可以保护鱼师，防止他们的手被凶猛而「坚硬」的鱼类伤到。\n在一些经验丰富的鱼师口中，这种鱼竿正是与枫丹特色之「铁鱼」进行决斗的理想武器，就如一柄趁手的长枪。', 'FISH_ROD', '鱼竿', NULL, NULL, NULL, '[\"枫丹钓鱼协会兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200907, '长犀圆鸟和扁鱼', NULL, 4, 62007, '钓鱼过程中，若能使张力处于最佳张力区，使用此竿可稳定缩短鱼儿挣扎时间，提高钓鱼成功率。仅纳塔地区生效。\n\n纳塔钓鱼协会特有的鱼竿，以精雕细琢的长颈角犀和浮流鸟装扮点缀竿体，材质则选用了武器级金属，兼顾趣味与耐用性。\n钓鱼佬们时常猜想，有着修长脖子的长颈角犀或许能成为自然界最优秀的鱼师，而看似笨拙的浮流鸟需要捕鱼为生，两者堪称绝妙的搭档，同时出现在鱼竿上，必定能为鱼师带来绝佳的钓鱼运！', 'FISH_ROD', '鱼竿', NULL, NULL, NULL, '[\"纳塔钓鱼协会兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (200908, '谧晖白枝', NULL, 4, 62008, '钓鱼过程中，若能使张力处于最佳张力区，使用此竿可稳定缩短鱼儿挣扎时间，提高钓鱼成功率。仅挪德卡莱地区生效。\n\n如同凝结的月光般，散发着明净白晖的鱼竿，是挪德卡莱鱼师群体之中，有着至高技法的宗师才有资格持有的杰作。相传，上一位善用这型鱼竿的鱼师仅将钓鱼视作和鱼儿们的「对谈」，会将钓获的鱼儿们就地放生，或是「请回」家中的鱼缸做客几天，就恭送至原本栖息的水域…这等温柔的做法，也在如今的鱼师群体中形成了一个特别的流派…', 'FISH_ROD', '鱼竿', NULL, NULL, NULL, '[\"挪德卡莱钓鱼协会兑换\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (220007, '浓缩树脂', NULL, 4, 300101, '同时最多持有5个。\n能在激活石化古树与地脉之花时替代原粹树脂，以获得更丰厚的宝藏的树脂浓缩产物。\n蕴含着充沛能量的晶体。\n银白的古树与花连接着地脉，而树脂蕴含的能量能疏通地脉的管道，提炼淤滞其中的物质。', 'CONSUME', '消耗品', NULL, NULL, NULL, '[\"合成获得\"]', '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (220060, '试验型超燃灯', NULL, 4, 410011, '能够通过消耗矿物，提高食材加工效率的小装置。\n教令院的年轻学者有着利用实验器材进行烹饪的习惯。为了提高效率，节约时间，有人发明了「超燃灯」这种能将矿物中的能量提取出来，增加功率的装置。\n手中的是这种超燃灯的民用试验型，限制了出力功率，消除了明火，以降低火灾风险。不过，就算如此，还是能够熬制果酱、烘干香肠，十分方便。', 'CONSUME', '小道具', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (221018, '附有记忆的面具', NULL, 4, 300201, '巫女「花散里」曾经戴着的面具，内侧有着深色的污渍。\n其中承载着一部分记忆。通过这份记忆，可以学会法器「白辰之环」的锻造方法。\n如今面具与花散里分别了，派蒙也不会叫她「面具巫女」了吧。', 'CONSUME', '锻造图纸', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (222001, '「绘绮之枕印」', NULL, 4, 410011, '饰有彩画的绘马，由品质上佳的梦见木精雕细刻而成，描绘着明丽的稻妻风光。\n借由「外景之能」，方可将彩画上的风雅景致呈现在「尘歌壶」之中…', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (222002, '「烟林之真果」', NULL, 4, 410011, '蕴含着奇妙香气的果实，是周游壶灵阿嘟从须弥带回的纪念品。\n轻嗅这种果实的香气，脑海中似乎就有某种意象浮现而出。借由「外景之能」，方可在壶中洞天构筑奇妙的须弥景致…', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (222003, '「旋流之瓶景」', NULL, 4, 410011, '内部景观优美的生态瓶，是周游壶灵阿嘟从枫丹带回的纪念品。\n凝望瓶内的景致，脑海中似乎就有某种意象浮现而出。借由「外景之能」，方可在壶中洞天构筑奇妙的枫丹景致…', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (222004, '「炽空的绘卷」', NULL, 4, 410011, '绘有独特风光，隐含着独特力量的纳塔织卷，是周游壶灵阿嘟从纳塔带回的纪念品。\n注视绘卷上的图案，脑海中似乎就有某种意象浮现而出。借由「外景之能」，方可将绘卷上的纳塔景致呈现在「尘歌壶」之中…', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
INSERT INTO `materials` VALUES (222005, '「掠影之球机」', NULL, 4, 410011, '具有播放音乐与制造炫丽光效功能的挪德卡莱月矩力机关球，是周游壶灵阿嘟从挪德卡莱带回的纪念品。\n注视机关球上放出的光影，脑海中似乎就有某种意象浮现而出。借由「外景之能」，方可在壶中洞天构筑奇妙的挪德卡莱景致…', 'CONSUME', '消耗品', NULL, NULL, NULL, NULL, '2026-05-20 19:11:55', '2026-05-20 19:11:55');
