INSERT INTO `tcg_cards` VALUES (520101, '自行·热诚之火', NULL, 'GCG_CARD_ASSIST', '支援牌', '我方融化和蒸发效果改为：本次伤害翻倍。\n超载效果改为：本伤害+6，目标强制切换到上一个角色。', '我方{SPRITE_PRESET#2101}{SPRITE_PRESET#2103}<color=#FFFFFFFF>融化</color>和{SPRITE_PRESET#2103}{SPRITE_PRESET#2102}<color=#FFFFFFFF>蒸发</color>效果改为：本次伤害翻倍。\\n{SPRITE_PRESET#2103}{SPRITE_PRESET#2104}<color=#FFFFFFFF>超载</color>效果改为：本伤害+6，目标强制切换到上一个角色。', '我方{SPRITE_PRESET#2101}{SPRITE_PRESET#2103}<color=#FFFFFFFF>融化</color>和{SPRITE_PRESET#2103}{SPRITE_PRESET#2102}<color=#FFFFFFFF>蒸发</color>效果改为：本次伤害翻倍。\\n{SPRITE_PRESET#2103}{SPRITE_PRESET#2104}<color=#FFFFFFFF>超载</color>效果改为：本伤害+6，目标强制切换到上一个角色。', NULL, NULL, NULL, '2026-05-20 19:19:43', '2026-05-20 19:19:43');
INSERT INTO `tcg_cards` VALUES (520102, '自行·强能之雷', NULL, 'GCG_CARD_ASSIST', '支援牌', '我方原激化生成的激化领域效果改为：我方造成的雷元素伤害和草元素伤害+1。（可叠加，没有上限）', '我方{SPRITE_PRESET#2107}{SPRITE_PRESET#2104}<color=#FFFFFFFF>原激化</color>生成的<color=#FFFFFFFF>激化领域</color>效果改为：我方造成的$[K104]和$[K107]+1。（可叠加，没有上限）', '我方{SPRITE_PRESET#2107}{SPRITE_PRESET#2104}<color=#FFFFFFFF>原激化</color>生成的<color=#FFFFFFFF>激化领域</color>效果改为：我方造成的{SPRITE_PRESET#2104}<color=#FFACFFFF>雷元素伤害</color>和{SPRITE_PRESET#2107}<color=#7EC236FF>草元素伤害</color>+1。（可叠加，没有上限）', NULL, NULL, NULL, '2026-05-20 19:19:43', '2026-05-20 19:19:43');
INSERT INTO `tcg_cards` VALUES (520103, '自行·疲劳之冰', NULL, 'GCG_CARD_ASSIST', '支援牌', '我方超导和冻结额外使目标攻击力-6，直到下次行动后。（可叠加）', '我方{SPRITE_PRESET#2101}{SPRITE_PRESET#2104}<color=#FFFFFFFF>超导</color>和{SPRITE_PRESET#2101}{SPRITE_PRESET#2102}<color=#FFFFFFFF>冻结</color>额外使目标攻击力-6，直到下次行动后。（可叠加）', '我方{SPRITE_PRESET#2101}{SPRITE_PRESET#2104}<color=#FFFFFFFF>超导</color>和{SPRITE_PRESET#2101}{SPRITE_PRESET#2102}<color=#FFFFFFFF>冻结</color>额外使目标攻击力-6，直到下次行动后。（可叠加）', NULL, NULL, NULL, '2026-05-20 19:19:43', '2026-05-20 19:19:43');
INSERT INTO `tcg_cards` VALUES (520104, '自行·蔓生之草', NULL, 'GCG_CARD_ASSIST', '支援牌', '敌方受到绽放伤害后：敌方全体受到2点穿透伤害。\n敌方受到燃烧伤害后：附属2层持续燃烧。', '敌方受到{SPRITE_PRESET#2107}{SPRITE_PRESET#2102}<color=#FFFFFFFF>绽放</color>伤害后：敌方全体受到2点穿透伤害。\\n敌方受到{SPRITE_PRESET#2107}{SPRITE_PRESET#2103}<color=#FFFFFFFF>燃烧</color>伤害后：附属2层$[C133]。', '敌方受到{SPRITE_PRESET#2107}{SPRITE_PRESET#2102}<color=#FFFFFFFF>绽放</color>伤害后：敌方全体受到2点穿透伤害。\\n敌方受到{SPRITE_PRESET#2107}{SPRITE_PRESET#2103}<color=#FFFFFFFF>燃烧</color>伤害后：附属2层持续燃烧。', NULL, NULL, NULL, '2026-05-20 19:19:43', '2026-05-20 19:19:43');
INSERT INTO `tcg_cards` VALUES (520105, '自行·坚定之岩', NULL, 'GCG_CARD_ASSIST', '支援牌', '我方护盾没有上限，我方结晶反应每次生成7层护盾。', '我方$[C135]没有上限，我方结晶反应每次生成7层$[C135]。', '我方护盾没有上限，我方结晶反应每次生成7层护盾。', NULL, NULL, NULL, '2026-05-20 19:19:43', '2026-05-20 19:19:43');
INSERT INTO `tcg_cards` VALUES (520106, '自行·翠绿之风', NULL, 'GCG_CARD_ASSIST', '支援牌', '我方扩散反应造成伤害+1。\n我方触发扩散反应后：本回合我方角色和召唤物该元素造成的伤害+1。', '我方扩散反应造成伤害+1。\\n<color=#FFFFFFFF>我方触发扩散反应后：</color>本回合我方角色和召唤物该元素造成的伤害+1。', '我方扩散反应造成伤害+1。\\n<color=#FFFFFFFF>我方触发扩散反应后：</color>本回合我方角色和召唤物该元素造成的伤害+1。', NULL, NULL, NULL, '2026-05-20 19:19:43', '2026-05-20 19:19:43');
INSERT INTO `tcg_cards` VALUES (520107, '自行·迟滞之水', NULL, 'GCG_CARD_ASSIST', '支援牌', '敌方受到感电伤害后：附属4层持续电击。（行动后受到层数的穿透伤害)', '敌方受到{SPRITE_PRESET#2102}{SPRITE_PRESET#2104}<color=#FFFFFFFF>感电</color>伤害后：附属4层<color=#FFFFFFFF>$[C144]</color>。（行动后受到层数的$[K5])', '敌方受到{SPRITE_PRESET#2102}{SPRITE_PRESET#2104}<color=#FFFFFFFF>感电</color>伤害后：附属4层<color=#FFFFFFFF>持续电击</color>。（行动后受到层数的<color=#FFFFFFFF>穿透伤害</color>)', NULL, NULL, NULL, '2026-05-20 19:19:43', '2026-05-20 19:19:43');
