INSERT INTO `tcg_character_skills` VALUES (25, 2204, 22042, '迸落星雨', '造成$[D__KEY__DAMAGE_2]点$[D__KEY__ELEMENT]，此角色每有3点<color=#FFFFFFFF>$[S22044]</color>提供的额外最大生命，此伤害+1（最多+3）。然后$[K56]1张原本元素骰费用最高的手牌。', '造成1点水元素伤害，此角色每有3点无尽食欲提供的额外最大生命，此伤害+1（最多+3）。然后舍弃1张原本元素骰费用最高的手牌。', '造成1点{SPRITE_PRESET#2102}<color=#80C0FFFF>水元素伤害</color>，此角色每有3点<color=#FFFFFFFF>无尽食欲</color>提供的额外最大生命，此伤害+1（最多+3）。然后<color=#FFFFFFFF>舍弃</color>1张原本元素骰费用最高的手牌。', NULL, 'GCG_ELEMENT_HYDRO', 'GCG_SKILL_TAG_E', '元素战技', '[{\"count\": 3, \"costtype\": \"GCG_COST_DICE_HYDRO\"}]', '2026-05-20 19:24:33');
