INSERT INTO `tcg_character_skills` VALUES (148, 2304, 23042, '烈焰燃绽', '造成$[D__KEY__DAMAGE]点$[D__KEY__ELEMENT]；如果本角色附属有至少7层<color=#FFFFFFFF>$[C123041]</color>，则此伤害+1。\\n然后，本角色附属2层<color=#FFFFFFFF>$[C123041]</color>。', '造成1点火元素伤害；如果本角色附属有至少7层重甲蟹壳，则此伤害+1。\n然后，本角色附属2层重甲蟹壳。', '造成1点{SPRITE_PRESET#2103}<color=#FF9999FF>火元素伤害</color>；如果本角色附属有至少7层<color=#FFFFFFFF>重甲蟹壳</color>，则此伤害+1。\\n然后，本角色附属2层<color=#FFFFFFFF>重甲蟹壳</color>。', 1, 'GCG_ELEMENT_PYRO', 'GCG_SKILL_TAG_E', '元素战技', '[{\"count\": 3, \"costtype\": \"GCG_COST_DICE_PYRO\"}]', '2026-05-20 19:24:33');
INSERT INTO `tcg_character_skills` VALUES (149, 2304, 23043, '战阵爆轰', '本角色$[K53]：<color=#FFFFFFFF>$[S23046]</color>。', '本角色准备技能：炽烈轰破。', '本角色<color=#FFFFFFFF>准备技能</color>：<color=#FFFFFFFF>炽烈轰破</color>。', NULL, NULL, 'GCG_SKILL_TAG_Q', '元素爆发', '[{\"count\": 3, \"costtype\": \"GCG_COST_DICE_PYRO\"}, {\"count\": 2, \"costtype\": \"GCG_COST_ENERGY\"}]', '2026-05-20 19:24:33');
INSERT INTO `tcg_character_skills` VALUES (150, 2304, 23044, '帝王甲胄', '【被动】<color=#FFFFFFFF>战斗开始时：</color>初始附属5层<color=#FFFFFFFF>$[C123041]</color>。\\n<color=#FFFFFFFF>我方执行任意行动后：</color>如果我方场上存在$[C123041]以外的$[K6]状态或$[K6]出战状态，则将其全部移除；每移除1个，就使角色附属2层<color=#FFFFFFFF>$[C123041]</color>。', '【被动】战斗开始时：初始附属5层重甲蟹壳。\n我方执行任意行动后：如果我方场上存在重甲蟹壳以外的护盾状态或护盾出战状态，则将其全部移除；每移除1个，就使角色附属2层重甲蟹壳。', '【被动】<color=#FFFFFFFF>战斗开始时：</color>初始附属5层<color=#FFFFFFFF>重甲蟹壳</color>。\\n<color=#FFFFFFFF>我方执行任意行动后：</color>如果我方场上存在重甲蟹壳以外的{SPRITE_PRESET#4007}<color=#FFFFFFFF>护盾</color>状态或{SPRITE_PRESET#4007}<color=#FFFFFFFF>护盾</color>出战状态，则将其全部移除；每移除1个，就使角色附属2层<color=#FFFFFFFF>重甲蟹壳</color>。', NULL, NULL, 'GCG_SKILL_TAG_PASSIVE', '被动技能', NULL, '2026-05-20 19:24:33');
INSERT INTO `tcg_character_skills` VALUES (151, 2304, 23046, '炽烈轰破', '（需准备1个行动轮）\\n造成$[D__KEY__DAMAGE]点$[D__KEY__ELEMENT]，对敌方所有后台角色造成2点$[K5]。本角色每附属有2层<color=#FFFFFFFF>$[C123041]</color>，就使此技能造成的$[K103]+1。', '（需准备1个行动轮）\n造成1点火元素伤害，对敌方所有后台角色造成2点穿透伤害。本角色每附属有2层重甲蟹壳，就使此技能造成的火元素伤害+1。', '（需准备1个行动轮）\\n造成1点{SPRITE_PRESET#2103}<color=#FF9999FF>火元素伤害</color>，对敌方所有后台角色造成2点<color=#FFFFFFFF>穿透伤害</color>。本角色每附属有2层<color=#FFFFFFFF>重甲蟹壳</color>，就使此技能造成的{SPRITE_PRESET#2103}<color=#FF9999FF>火元素伤害</color>+1。', 1, 'GCG_ELEMENT_PYRO', 'GCG_SKILL_TAG_Q', '元素爆发', NULL, '2026-05-20 19:24:33');
