INSERT INTO `tcg_character_skills` VALUES (301, 1214, 12142, '踏鲨破浪', '自身附属<color=#FFFFFFFF>$[C112142]</color>，然后进入<color=#FFFFFFFF>$[C112141]</color>，并获得2点<color=#FFFFFFFF>「夜魂值」</color>。（角色进入<color=#FFFFFFFF>$[C112141]</color>后不可使用此技能）\\n（附属<color=#FFFFFFFF>$[C112142]</color>的角色可以使用特技：<color=#FFFFFFFF>$[S1121422]</color>）', '自身附属咬咬鲨鱼，然后进入夜魂加持，并获得2点「夜魂值」。（角色进入夜魂加持后不可使用此技能）\n（附属咬咬鲨鱼的角色可以使用特技：鲨鲨冲浪板）', '自身附属<color=#FFFFFFFF>咬咬鲨鱼</color>，然后进入<color=#FFFFFFFF>夜魂加持</color>，并获得2点<color=#FFFFFFFF>「夜魂值」</color>。（角色进入<color=#FFFFFFFF>夜魂加持</color>后不可使用此技能）\\n（附属<color=#FFFFFFFF>咬咬鲨鱼</color>的角色可以使用特技：<color=#FFFFFFFF>鲨鲨冲浪板</color>）', NULL, NULL, 'GCG_SKILL_TAG_E', '元素战技', '[{\"count\": 2, \"costtype\": \"GCG_COST_DICE_HYDRO\"}]', '2026-05-20 19:24:33');
