INSERT INTO `tcg_character_skills` VALUES (310, 1608, 16084, '互助关系网', '【被动】<color=#FFFFFFFF>敌方角色受到结晶反应伤害后：</color>生成3张<color=#FFFFFFFF>$[C116081]</color>，随机置入我方牌库中。', '【被动】敌方角色受到结晶反应伤害后：生成3张裂晶弹片，随机置入我方牌库中。', '【被动】<color=#FFFFFFFF>敌方角色受到结晶反应伤害后：</color>生成3张<color=#FFFFFFFF>裂晶弹片</color>，随机置入我方牌库中。', NULL, NULL, 'GCG_SKILL_TAG_PASSIVE', '被动技能', NULL, '2026-05-20 19:24:33');
