INSERT INTO `tcg_character_skills` VALUES (348, 1507, 15074, '风风轮舞踢', '（需准备1个行动轮）\\n造成$[D__KEY__DAMAGE]点$[D__KEY__ELEMENT]（或被扩散元素的伤害）。', '（需准备1个行动轮）\n造成2点风元素伤害（或被扩散元素的伤害）。', '（需准备1个行动轮）\\n造成2点{SPRITE_PRESET#2105}<color=#80FFD7FF>风元素伤害</color>（或被扩散元素的伤害）。', 2, 'GCG_ELEMENT_ANEMO', 'GCG_SKILL_TAG_E', '元素战技', NULL, '2026-05-20 19:24:33');
