INSERT INTO `tcg_character_skills` VALUES (367, 1204, 12042, '魔王武装·狂澜', '切换为<color=#FFFFFFFF>$[C112042]</color>，然后造成$[D__KEY__DAMAGE]点$[D__KEY__ELEMENT]，并使目标角色附属<color=#FFFFFFFF>$[C112043]</color>。', '切换为近战状态，然后造成2点水元素伤害，并使目标角色附属断流。', '切换为<color=#FFFFFFFF>近战状态</color>，然后造成2点{SPRITE_PRESET#2102}<color=#80C0FFFF>水元素伤害</color>，并使目标角色附属<color=#FFFFFFFF>断流</color>。', 2, 'GCG_ELEMENT_HYDRO', 'GCG_SKILL_TAG_E', '元素战技', '[{\"count\": 3, \"costtype\": \"GCG_COST_DICE_HYDRO\"}]', '2026-05-20 19:24:33');
INSERT INTO `tcg_character_skills` VALUES (368, 1204, 12043, '极恶技·尽灭闪', '依据<color=#FFFFFFFF>$[A1204]</color>当前所处的状态，进行不同的攻击：\\n<color=#FFFFFFFF>远程状态·魔弹一闪：</color>造成$[D__KEY__DAMAGE_5]点$[D__KEY__ELEMENT]，返还2点$[K310]，目标角色附属<color=#FFFFFFFF>$[C112043]</color>。\\n<color=#FFFFFFFF>近战状态·尽灭水光：</color>造成$[D__KEY__DAMAGE]点$[D__KEY__ELEMENT]。', '依据达达利亚当前所处的状态，进行不同的攻击：\n远程状态·魔弹一闪：造成5点水元素伤害，返还2点充能，目标角色附属断流。\n近战状态·尽灭水光：造成7点水元素伤害。', '依据<color=#FFFFFFFF>达达利亚</color>当前所处的状态，进行不同的攻击：\\n<color=#FFFFFFFF>远程状态·魔弹一闪：</color>造成5点{SPRITE_PRESET#2102}<color=#80C0FFFF>水元素伤害</color>，返还2点<color=#FFFFFFFF>{SPRITE_PRESET#1110}充能</color>，目标角色附属<color=#FFFFFFFF>断流</color>。\\n<color=#FFFFFFFF>近战状态·尽灭水光：</color>造成7点{SPRITE_PRESET#2102}<color=#80C0FFFF>水元素伤害</color>。', 7, 'GCG_ELEMENT_HYDRO', 'GCG_SKILL_TAG_Q', '元素爆发', '[{\"count\": 3, \"costtype\": \"GCG_COST_DICE_HYDRO\"}, {\"count\": 3, \"costtype\": \"GCG_COST_ENERGY\"}]', '2026-05-20 19:24:33');
INSERT INTO `tcg_character_skills` VALUES (369, 1204, 12044, '遏浪', '【被动】战斗开始时，初始附属<color=#FFFFFFFF>$[C112041]</color>。\\n角色所附属的<color=#FFFFFFFF>$[C112042]</color>效果结束时，重新附属<color=#FFFFFFFF>$[C112041]</color>。', '【被动】战斗开始时，初始附属远程状态。\n角色所附属的近战状态效果结束时，重新附属远程状态。', '【被动】战斗开始时，初始附属<color=#FFFFFFFF>远程状态</color>。\\n角色所附属的<color=#FFFFFFFF>近战状态</color>效果结束时，重新附属<color=#FFFFFFFF>远程状态</color>。', NULL, NULL, 'GCG_SKILL_TAG_PASSIVE', '被动技能', NULL, '2026-05-20 19:24:33');
