INSERT INTO `tcg_character_skills` VALUES (407, 1312, 13122, '热情拂扫', '造成$[D__KEY__DAMAGE]点$[D__KEY__ELEMENT]，随机$[K56]1张原本元素骰费用最高的手牌，生成<color=#FFFFFFFF>$[C113121]</color>。', '造成2点火元素伤害，随机舍弃1张原本元素骰费用最高的手牌，生成热情护盾。', '造成2点{SPRITE_PRESET#2103}<color=#FF9999FF>火元素伤害</color>，随机<color=#FFFFFFFF>舍弃</color>1张原本元素骰费用最高的手牌，生成<color=#FFFFFFFF>热情护盾</color>。', 2, 'GCG_ELEMENT_PYRO', 'GCG_SKILL_TAG_E', '元素战技', '[{\"count\": 3, \"costtype\": \"GCG_COST_DICE_PYRO\"}]', '2026-05-20 19:24:33');
INSERT INTO `tcg_character_skills` VALUES (408, 1312, 13123, '叛逆刮弦', '造成$[D__KEY__DAMAGE]点$[D__KEY__ELEMENT]，对所有敌方后台角色造成2点<color=#FFFFFFFF>$[K5]</color>；$[K56]我方所有手牌，生成<color=#FFFFFFFF>$[C113123]</color>。', '造成3点物理伤害，对所有敌方后台角色造成2点穿透伤害；舍弃我方所有手牌，生成氛围烈焰。', '造成3点{SPRITE_PRESET#2100}<color=#FFFFFFFF>物理伤害</color>，对所有敌方后台角色造成2点<color=#FFFFFFFF><color=#FFFFFFFF>穿透伤害</color></color>；<color=#FFFFFFFF>舍弃</color>我方所有手牌，生成<color=#FFFFFFFF>氛围烈焰</color>。', 3, 'GCG_ELEMENT_NONE', 'GCG_SKILL_TAG_Q', '元素爆发', '[{\"count\": 3, \"costtype\": \"GCG_COST_DICE_PYRO\"}, {\"count\": 2, \"costtype\": \"GCG_COST_ENERGY\"}]', '2026-05-20 19:24:33');
