INSERT INTO `tcg_character_skills` VALUES (410, 1408, 14082, '野干役咒·杀生樱', '召唤<color=#FFFFFFFF>$[C114081]</color>。如果场上原本已存在<color=#FFFFFFFF>$[C114081]</color>，则额外使其造成的伤害+1。（最多+1）', '召唤杀生樱。如果场上原本已存在杀生樱，则额外使其造成的伤害+1。（最多+1）', '召唤<color=#FFFFFFFF>杀生樱</color>。如果场上原本已存在<color=#FFFFFFFF>杀生樱</color>，则额外使其造成的伤害+1。（最多+1）', NULL, NULL, 'GCG_SKILL_TAG_E', '元素战技', '[{\"count\": 3, \"costtype\": \"GCG_COST_DICE_ELECTRO\"}]', '2026-05-20 19:24:33');
