INSERT INTO `tcg_characters` VALUES (1101, '甘雨', 1, 10, 3, 0, '循循守月·甘雨', '「既然是明早前要，那这份通稿，只要熬夜写完就好。」', '在猫尾酒馆中邀请甘雨进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1102, '迪奥娜', 2, 10, 3, 0, '猫尾特调·迪奥娜', '用1%的力气调酒，99%的力气…拒绝失败。', '在猫尾酒馆中邀请迪奥娜进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1103, '凯亚', 3, 10, 2, 0, '寒风剑士·凯亚', '他很擅长在他人身上发掘出「骑士般的美德」。', '初始牌组中获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1104, '重云', 4, 10, 3, 0, '雪融有踪·重云', '「夏天啊，你还是悄悄过去吧…」', '在猫尾酒馆中邀请重云进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1105, '神里绫华', 5, 10, 3, 0, '白鹭霜华·神里绫华', '如霜凝华，如鹭在庭。', '在猫尾酒馆中邀请神里绫华进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1106, '优菈', 6, 10, 2, 0, '浪沫的旋舞·优菈', '这只是一场游戏，无论是取胜或落败，你都不会因此被添上罪状。', '在猫尾酒馆中邀请优菈进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1107, '申鹤', 7, 10, 2, 0, '孤辰茕怀·申鹤', '红尘渺渺，因果烟消。', '在猫尾酒馆中邀请申鹤进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1108, '七七', 8, 10, 3, 0, '冻冻回魂夜·七七', '流转不息，生生不绝。', '在猫尾酒馆中邀请七七进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1109, '莱依拉', 279, 10, 2, 0, '绮思晚星·莱依拉', '夜沉星移，月笼梦行。', '在猫尾酒馆中邀请莱依拉进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1110, '夏洛蒂', 334, 10, 2, 0, '朗镜索真·夏洛蒂', '「真实至上，故事超群！」', '在猫尾酒馆中邀请夏洛蒂进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1111, '莱欧斯利', 363, 10, 3, 0, '寂罪的密使·莱欧斯利', '罪囚于斯，深水无漪。', '在猫尾酒馆中邀请莱欧斯利进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1112, '菲米尼', 407, 10, 2, 0, '潜怀遐梦·菲米尼', '繁星丽天，孤怀寒芒。', '在猫尾酒馆中邀请菲米尼进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1113, '罗莎莉亚', 432, 10, 2, 0, '棘冠恩典·罗莎莉亚', '「黑影源于光明，光明却不统御黑影。」', '在猫尾酒馆中邀请罗莎莉亚进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1201, '芭芭拉', 9, 10, 3, 0, '闪耀偶像·芭芭拉', '无论何时都能治愈人心。', '在猫尾酒馆中邀请芭芭拉进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1202, '行秋', 10, 10, 2, 0, '古华飞云·行秋', '「怎么最近小说里的主角，都是些私塾里的学生…」', '在猫尾酒馆中邀请行秋进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1203, '莫娜', 11, 10, 3, 0, '星天水镜·莫娜', '无论胜负平弃，都是命当如此。', '在猫尾酒馆中邀请莫娜进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1204, '达达利亚', 12, 10, 3, 0, '「公子」·达达利亚', '牌局亦为战场，能者方可争先。', '在猫尾酒馆中邀请达达利亚进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1205, '珊瑚宫心海', 13, 10, 2, 0, '真珠之智·珊瑚宫心海', '未雨绸缪，临危莫乱。', '在猫尾酒馆中邀请珊瑚宫心海进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1206, '神里绫人', 14, 10, 2, 0, '磐祭叶守·神里绫人', '神守之柏，已焕新材。', '在猫尾酒馆中邀请神里绫人进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1207, '坎蒂丝', 15, 10, 2, 0, '浮金的誓愿·坎蒂丝', '赤沙浮金，恪誓戍御。', '在猫尾酒馆中邀请坎蒂丝进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
