INSERT INTO `tcg_characters` VALUES (1703, '纳西妲', 49, 10, 2, 0, '白草净华·纳西妲', '白草净华，幽宫启蛰。', '在猫尾酒馆中邀请纳西妲进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1704, '瑶瑶', 50, 10, 2, 0, '仙蕊玲珑·瑶瑶', '玲珑玉质，身含仙骨。', '在猫尾酒馆中邀请瑶瑶进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1705, '白术', 51, 10, 2, 0, '遵生合和·白术', '生老三千疾，何处可问医。', '在猫尾酒馆中邀请白术进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1706, '艾尔海森', 284, 10, 2, 0, '诲韬诤言·艾尔海森', '学识、思考及处事之道。', '在猫尾酒馆中邀请艾尔海森进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1707, '绮良良', 336, 10, 2, 0, '檐宇猫游·绮良良', '歧尾骏足，通达万户。', '在猫尾酒馆中邀请绮良良进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1708, '卡维', 367, 10, 2, 0, '天穹之镜·卡维', '体悟、仁爱与识美之知。', '在猫尾酒馆中邀请卡维进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (1709, '基尼奇', 455, 10, 2, 0, '回火之狩·基尼奇', '悬木游火，受任皆偿。', '在猫尾酒馆中邀请基尼奇进行对局，在友好对局难度中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2101, '愚人众·冰萤术士', 52, 10, 3, 0, '雾虚召萤·冰萤术士', '至少在雾虚草耗尽之前，冰萤不会离她而去。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度愚人众·冰萤术士中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2102, '「女士」', 277, 10, 2, 0, '第八执行官·「女士」', '瞳仁中倒映着破晓的赤红，她最后展开烈焰之翼向黎明飞去。\n「但那并不是曙光，亲爱的罗莎琳。那是焚尽一切的火海。」\n但这也没什么所谓。因为她心中明白，自己早已被烈火吞没。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度「女士」中获得胜利后获取', '[6301]', '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2103, '无相之冰', 321, 8, 2, 0, '无相之冰', '代号为「塔勒特」的高级冰元素生命。\n似乎很不擅长球类运动…', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度无相之冰中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2104, '愚人众·霜役人', 397, 10, 2, 0, '汰换之果·霜役人', '自幼就被选中的人，经长久年月的教化与训练，在无数次的汰换后才能成为所谓的「役人」。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度愚人众·霜役人中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2201, '纯水精灵·洛蒂娅', 53, 10, 3, 0, '净水之主·洛蒂娅', '「但，只要百川奔流，雨露不休，水就不会消失…」', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度纯水精灵·洛蒂娅中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2202, '愚人众·藏镜仕女', 54, 10, 2, 0, '冬国仕女·水镜使者', '一切隐秘，都将深藏于潋光的水镜之中吧…', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度愚人众·藏镜仕女中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2203, '深渊使徒·激流', 350, 6, 2, 0, '深渊使徒·激流', '断绝诸世，万物湮灭。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度深渊使徒·激流中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2204, '吞星之鲸', 368, 5, 2, 0, '深秘异兽·吞星之鲸', '在最魔幻的故事里或是最疯癫的诳语中，宇宙深处真正的星辰或许也如提瓦特一般充满了生机，而宇宙本身就如同海洋。\n或许宇宙渗入提瓦特的过程从未停止；也许更高的意志为它划定了边界是为了保护这个世界。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度吞星之鲸中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2205, '丘丘水行游侠', 409, 10, 2, 0, '锐波漫游·丘丘水行游侠', '不属于任何部族的丘丘人流浪者，如同自我流放一般在荒野中四处漫游。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度丘丘水行游侠中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2301, '愚人众·火之债务处理人', 55, 9, 2, 0, '清算之刃·债务处理人', '「死债不可免，活债更难逃…」', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度愚人众·火之债务处理人中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2302, '深渊咏者·渊火', 56, 6, 2, 0, '深渊咏者·渊火', '章典示现，劝听箴言。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度深渊咏者·渊火中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2303, '镀金旅团·炽沙叙事人', 285, 10, 2, 0, '诗与秘史·炽沙叙事人', '如今仍然能记起许多故事的人，是不会背叛流淌在体内的沙漠血脉的。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度镀金旅团·炽沙叙事人中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2304, '铁甲熔火帝皇', 351, 5, 2, 0, '铁甲熔火帝皇', '矗立在原海异种顶端的两位霸主之一，不遇天敌，不倦狩猎并成长之蟹。有着半是敬畏，半是戏谑的「帝皇」之称。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度铁甲熔火帝皇中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2401, '无相之雷', 57, 8, 2, 0, '无相之雷', '代号为「阿莱夫」的高级雷元素生命。\n就算猜拳获胜，它一般也不会认输。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度无相之雷中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2402, '雷音权现', 286, 10, 2, 0, '弥留之恨·雷音权现', '只要土地中的怨恨不消，那雷鸣也不会断绝吧。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度雷音权现中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2403, '千年珍珠骏麟', 322, 8, 2, 0, '千年珍珠骏麟', '矗立在原海异种顶端的两位霸主之一，因身姿修长优美，被诗人与作者视为孤傲而高洁的生灵，获称「骏麟」。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度千年珍珠骏麟中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2404, '愚人众·雷萤术士', 337, 10, 2, 0, '雾虚霆闪·雷萤术士', '…正如雾虚草的气味会令雷萤迷醉，嗜虐的术士也贪恋着戏弄对手的快感…', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度愚人众·雷萤术士中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2405, '圣骸毒蝎', 369, 10, 2, 0, '亡骸遗毒·圣骸毒蝎', '因为啃噬伟大的生命体，而扭曲异变的毒蝎，操纵着险恶的轰雷。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度圣骸毒蝎中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2406, '深渊咏者·紫电', 421, 6, 2, 0, '深渊咏者·紫电', '高颂渊薮，侵蚀之智。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度深渊咏者·紫电中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2501, '魔偶剑鬼', 58, 10, 3, 0, '万般机巧·魔偶剑鬼', '今日，其仍徘徊在因缘断绝之地。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度魔偶剑鬼中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2502, '特瓦林', 287, 10, 2, 0, '东风之龙·特瓦林', '「如果你曾是我，看见过你在蓝蓝的天上滑翔的孤高模样，见识过你的美丽身姿就好了。」\n「如此，你就会明白，这样的天空与大地，是值得为之奋战的。」', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度特瓦林中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2503, '圣骸飞蛇', 370, 10, 2, 0, '亡骸恶风·圣骸飞蛇', '因为啃噬伟大的生命体，而扭曲异变的飞蛇，驾驭着凌厉的狂风。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度圣骸飞蛇中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2601, '丘丘岩盔王', 59, 8, 2, 0, '千嶂漫行·丘丘岩盔王', '绕道而行吧，因为前方是属于「王」的领域。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度丘丘岩盔王中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2602, '若陀龙王', 278, 10, 2, 0, '古岩龙祖·若陀龙王', '枷锁的隐隐震响与龙祖低沉的怒吼，同记忆一般在山峦间回荡。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度若陀龙王中获得胜利后获取', '[6601, 6602, 6603, 6604]', '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2603, '黄金王兽', 434, 10, 2, 0, '狼群魔主·黄金王兽', '来自异界的扭曲魔兽，统领兽境群狼的王者，拥有指挥狼群溶解空间的权威。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度黄金王兽中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2701, '翠翎恐蕈', 60, 10, 2, 0, '幽蕈之王·翠翎恐蕈', '悄声静听，可以听到幽林之中，蕈类王者巡视领土的脚步…', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度翠翎恐蕈中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2702, '阿佩普的绿洲守望者', 371, 10, 2, 0, '智慧终景·阿佩普的绿洲守望者', '阿佩普曾独自沉溺于末日的风景当中。所有的人、神、龙、走兽、飞鸟与游鱼，所有记忆、智慧、话语与仇恨将都磨为无色尘粉，最后一轮明月之光则化作白焰之雨落在荒土之上。\n……\n阿佩普曾视沙海之底为自己的墓场，而非失乡之王的行宫。「智慧」的毒很快就会让它从无数个月亮的仇恨与愤怒中解脱。它已经对终末缺乏颜色的景象感到厌倦了。直到最终年轻的神明与金色的旅人让它再度回想起，即便自己曾经主宰的青绿土地已经化作饰金的荒原，即便自己与子嗣为了在其中生存而变得扭曲丑陋，但它的心中始终珍藏着那一角绿洲的景象。', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度阿佩普的绿洲守望者中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (2703, '镀金旅团·叶轮舞者', 422, 10, 2, 0, '旋舞之忆·叶轮舞者', '「沙之民有音乐与舞蹈的传统，起初是对神的礼赞，后来则是讨取王者欢心的演艺与战斗的技术。」', '在猫尾酒馆中小王子处进行酒馆挑战，在友好对局难度镀金旅团·叶轮舞者中获得胜利后获取', NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (6301, '焚尽的炽炎魔女', NULL, 10, 2, 1, NULL, NULL, NULL, NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
INSERT INTO `tcg_characters` VALUES (6601, '若陀龙王', NULL, 10, 2, 1, NULL, NULL, NULL, NULL, '2026-05-20 19:24:33', '2026-05-20 19:24:33');
