INSERT INTO `voiceovers` VALUES (10000002, 'Kamisato Ayaka', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_draw_appear\", \"description\": \"稻妻神里流太刀术皆传——神里绫华，参上！\\n请多指教哦。\", \"voicelineId\": 3100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·安定\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_character_idle_01\", \"description\": \"像这样悠闲安稳的时光，如果再多一点就好了…我真贪心啊。\", \"voicelineId\": 3101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·剑\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_character_idle_02\", \"description\": \"剑，就和茶一样，细细品味才能理解其中风雅。\", \"voicelineId\": 3102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·出神\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_character_idle_03\", \"description\": \"这就是旅行者平日里的生活么，呵，感觉又多了解了你一些。\", \"voicelineId\": 3103, \"voicelineType\": \"1103\"}, {\"title\": \"闲聊·名刀\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_character_idle_04\", \"description\": \"刀剑抱业，名工怀宝。\", \"voicelineId\": 3104, \"voicelineType\": \"1104\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_weather_heavyRain_01\", \"description\": \"请随我一同避雨吧。\", \"voicelineId\": 3105, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_weather_thunder_01\", \"description\": \"大御所大人…是在诉说什么吗？\", \"voicelineId\": 3106, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_weather_snowy_01\", \"description\": \"「雪霁银妆素，桔高映琼枝。」嗯…美景当前，只差一壶茶与之相衬呢。\", \"voicelineId\": 3107, \"voicelineType\": \"1205\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_weather_sunny_01\", \"description\": \"风和日丽，要去哪边走走么？\", \"voicelineId\": 3108, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_weather_breezy_01\", \"description\": \"闭上眼睛，向着风吹来的方向…怎么样，很舒服吧？\", \"voicelineId\": 3109, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_greetingMorning\", \"description\": \"早安，旅行者。能像这样在清晨见你一面，我会忍不住觉得…接下来将是顺利的一天。\", \"voicelineId\": 3110, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_greetingNoon\", \"description\": \"午安。茶饭之后，难免略有困倦。是否有兴致下盘棋提神呢？\", \"voicelineId\": 3111, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_greetingNight\", \"description\": \"晚上好。夜风舒畅，会是一个良宵呢。\", \"voicelineId\": 3112, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_greetingNight2\", \"description\": \"「若知是梦何须醒，不比真如一相会。」\", \"voicelineId\": 3113, \"voicelineType\": \"1004\"}, {\"title\": \"关于绫华自己·社奉行\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_idle_01\", \"description\": \"「稻妻幕府社奉行神里家」，位于稻妻名门中的笔头之格位。作为三奉行之一，掌管祭祀活动与人文艺术。自从双亲过世之后，族内的大小事务，便由兄长和我承担了。\", \"voicelineId\": 3114, \"voicelineType\": \"2001\"}, {\"title\": \"关于绫华自己·地位\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_idle_02\", \"description\": \"很多人因为我是「白鹭公主」，是社奉行神里家的大小姐而敬重我。他们所敬重的，只是我所身处的地位，与绫华我是怎样的人并无关系…\\n所以我想，能真正走近我的，或许只有…\", \"voicelineId\": 3115, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绫华自己·愿望\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_idle_03\", \"description\": \"如今的我，依旧想成为值得大家信任的人。不过，鼓舞我的原因，已不再是肩上的责任或他人的期待。而是因为，你也是这样的人啊。\", \"voicelineId\": 3116, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·茶室\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_close1\", \"description\": \"如你有空，我们移步木漏茶室如何？在这样恬静的日子，略加交流茶艺心得，想来是颇具雅趣的。\", \"voicelineId\": 3117, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·节日\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_close2\", \"description\": \"如果有机会的话，我想试着和你共度异国的节日。需要遵循的当地风俗、礼仪规范，还有伴手礼的推荐，可以麻烦你…一一指导我吗？\", \"voicelineId\": 3118, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1200804], \"unlockText\": \"完成「鹤与白兔的诉说」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_pendant\", \"description\": \"「神之眼」，即是胸怀大志之人所获的印绶。如果问我有什么志向的话…这个还是保密吧，只是一个微不足道的梦想罢了。\", \"voicelineId\": 3119, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_share\", \"description\": \"试问，常说「禅茶一味」，又说「剑禅一如」，那么剑和茶，又是什么关系呢？\", \"voicelineId\": 3120, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_pref_gift\", \"description\": \"你在城中，见过枯萎的樱花树么？这种「枯」之美，让我想到春天盛开之景。不过别人似乎并不这么想，不再开花的樱树会被移走…就算一次也好，真想看到它再次开放。\", \"voicelineId\": 3121, \"voicelineType\": \"3003\"}, {\"title\": \"关于托马…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_teammate_thoma_01\", \"description\": \"托马是我很重要的朋友，他的开朗和阳光总是感染着我。某种意义上来说，他就像是我的另一个兄长一样，已经成为了「神里家」的一员。\", \"voicelineId\": 3122, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_teammate_kujouSara_01\", \"description\": \"为「天领奉行」工作的九条裟罗…她总是一脸严肃。我和她曾经起过几次争端，不过她本质是忠义之士，这点无可否认。\", \"voicelineId\": 3123, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鹿野院平藏…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_teammate_shikanoinHeizou_01\", \"description\": \"鹿野院先生？他和九条小姐一样，是「天领奉行」的人。他…也是一个很有原则的人。对于这些「原则」的坚持，甚至比九条小姐更执着。只不过，什么事应该被算在这些「原则」之内，我想，或许只有鹿野院先生自己知道吧。\", \"voicelineId\": 3124, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于早柚…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_teammate_sayu_01\", \"description\": \"早柚这孩子，最近有没有给你添什么麻烦呢？如果看见她偷懒，可以直接告诉我。\", \"voicelineId\": 3125, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军·猜测\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_teammate_raidenShogun_01\", \"description\": \"对大御所大人的看法吗？这并不该由我等下属随意议论。但…将军大人她，在追求「永恒」之路上，可能也很孤独吧。\", \"voicelineId\": 3126, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军·立场\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_teammate_raidenShogun_02\", \"description\": \"见证了「无想的一刀」并且活了下来，该说是堪称伟业的经历了吧。虽然对我来说，她是真正的神明，一念之间可以更改稻妻的命运，但如果是和你起了冲突的话…我一定会站在你这一边的。\", \"voicelineId\": 3127, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_teammate_yaeMiko_01\", \"description\": \"我和八重宫司大人的合作向来很愉快。你看，操办节庆庆典非常劳神费力，营收多半也不好看。但是八重宫司大人操办的产业，真的既风雅又有收成。\", \"voicelineId\": 3128, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫人…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_teammate_ayato_01\", \"description\": \"作为神里家的家主，兄长平日需要出面诸多场合。我虽尽力分担兄长肩上所负担的责任，却也无法缓和他常年积压在身的疲倦。唉，就当是为了妹妹着想，希望你能劝言，让兄长多多注意身体啊。\", \"voicelineId\": 3129, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_teammate_yoimiya_01\", \"description\": \"操办节庆庆典是社奉行和巫女众的责任，那位烟火专家也的确能让气氛热烈起来，彼此合作多了，因而渐渐熟络。\\n嗯？治安和消防问题吗？我们也会一并纳入预先规划的。因为这些原因而看不到烟花，才会让人们心中留下缺憾吧。\", \"voicelineId\": 3130, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解绫华·其一\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_friendship_01\", \"description\": \"你的请求，对我来说很特别呢。既然把你当做朋友，我也应坦诚以待。不过，事关神里家的秘密，还希望你能守口如瓶。\", \"voicelineId\": 3131, \"voicelineType\": \"5001\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解绫华·其二\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_friendship_02\", \"description\": \"曾经，神里家因为没能保护好国宝级别的刀工，遭受了不小的冲击。受愚人众阴谋算计，我们折损了诸多臣下，受到许多责罚。父亲甚至因之早衰，神里家在幕府中的地位也一落千丈…好在兄长继任后力挽狂澜。不过，家门虽已复兴，社奉行一系也上下齐心，但大事要事方面，仍靠兄长定夺。\", \"voicelineId\": 3132, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解绫华·其三\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_friendship_03\", \"description\": \"将军所传的锻刀之术，也因星象、用途、矿质、炉火环境、人之性格、元素变化的不同，而有所区分。即是刀工之间所说的「雷电五传」。能锻造名刀的刀工，也被算作是本领通神的神事相关人员，归属统筹文化、艺术、祭祀的社奉行一派管理。因此，出现了刀工背叛的事情，自然就是神里家的督办不力了。\", \"voicelineId\": 3133, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解绫华·其四\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_friendship_04\", \"description\": \"对我来说，母亲是意义非凡的存在。端庄、优雅，无论遇到怎样的局面都会露出沉静的笑容，以从容不迫的态度，操持着神里家大大小小的事务，说母亲是完美的化身也不为过。但自从她离世的那一刻起，我就深切地意识到，我已经不是那个可以躲在母亲身后的小绫华了。\", \"voicelineId\": 3134, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解绫华·其五\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_friendship_05\", \"description\": \"接下来要说的话，可能不太符合「稻妻幕府社奉行神里家」的身份。不过，就我的判断，你应该能容许我小小的任性吧？\\n…稍微有点累了…可以让我靠一下你的肩膀吗？一下就好。\", \"voicelineId\": 3135, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"绫华的爱好…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_pref_hobby\", \"description\": \"风雅之物我都很喜欢：雅乐诗词、棋艺与舞蹈。你也感兴趣吗？\", \"voicelineId\": 3136, \"voicelineType\": \"6001\"}, {\"title\": \"绫华的烦恼·忧虑\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_annoyed_01\", \"description\": \"烦恼吗？啊，是啊。只要生活在这个世界上，就难免遇到种种不如意的事情。但如果是因为自己的事情，就让周遭的人担心的话…果然，我还是不能说…\", \"voicelineId\": 3137, \"voicelineType\": \"6002\"}, {\"title\": \"绫华的烦恼·心意\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_dialog_annoyed_02\", \"description\": \"「坦率」，真的是一件很难的事情。我必须不断告诫自己是神里家的大小姐，在无数双眼睛，无数人的期盼之下摆出完美无缺的姿态。这样的我，是否也该追求自己的愿望呢，是否也该…让你理解我的心意呢…\", \"voicelineId\": 3138, \"voicelineType\": \"6006\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_pref_foodLike\", \"description\": \"我对异国料理很有兴趣，虽然很少有尝试的机会。嗯…如果是要局限在稻妻料理内的话…应该是「茶泡饭」吧。不过，不能给一般客人看见，我也是偷偷告诉你的。\", \"voicelineId\": 3139, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_pref_foodDislike\", \"description\": \"虽然不是不能吃，但我对动物脂肪或内脏大概会有点…\", \"voicelineId\": 3140, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_spice_pref_01\", \"description\": \"嗯…我真是太幸福了…\", \"voicelineId\": 3168, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_spice_normal_01\", \"description\": \"谢谢你让我有机会尝试这道菜，我会把它的味道记在心里的。\", \"voicelineId\": 3169, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_spice_dislike_01\", \"description\": \"啊…稍微有点油腻了呢。\", \"voicelineId\": 3170, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_pref_birthday\", \"description\": \"请随我来！只要走一小段路，不会耽搁你太长时间的哦。\\n打听到你的生日之后，我就提前了一段时间开始筹备。比起名贵的礼物，我妄自猜测…或许这样的礼物会更合我们的情谊。此次，就请让我以扇舞为礼吧。\\n那么，失礼了。\", \"voicelineId\": 3141, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_starUp_01\", \"description\": \"非常感谢。与你切磋使我受益良多，相信在剑术上也能更进一步。\", \"voicelineId\": 3142, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_starUp_02\", \"description\": \"多亏你的点拨。有你相助，我对自己的能力也理解得更透彻了。\", \"voicelineId\": 3143, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_starUp_03\", \"description\": \"感觉更加游刃有余了。处理社奉行事务之余，甚至有空尝试一些新的事情。要来试试最近学做的点心吗？\", \"voicelineId\": 3144, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_ayaka/vo_ayaka_starUp_04\", \"description\": \"「尝有所思，斯世如磐；孰料浮世事，留驻难。」\\n…抱歉，明明是值得高兴的时候，我却想起了那么悲伤的诗歌。和你相处的时间过于畅怀，竟然让我害怕再次失去。真是…失态了呀。\", \"voicelineId\": 3145, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_battle_skill1_01\", \"description\": \"起舞吧。\", \"voicelineId\": 3146, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_battle_skill1_02\", \"description\": \"失礼了。\", \"voicelineId\": 3147, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_battle_skill1_03\", \"description\": \"雪纷飞。\", \"voicelineId\": 3148, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_battle_skill3_01\", \"description\": \"…拿下了！\", \"voicelineId\": 3149, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_battle_skill3_02\", \"description\": \"樱吹雪。\", \"voicelineId\": 3150, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_battle_skill3_03\", \"description\": \"神里流…霜灭！\", \"voicelineId\": 3151, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_chest_open_01\", \"description\": \"寻珍觅奇…也算得一种雅趣。\", \"voicelineId\": 3152, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_chest_open_02\", \"description\": \"呵呵…今日运势不错。\", \"voicelineId\": 3153, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_chest_open_03\", \"description\": \"我会珍惜这一份幸运。\", \"voicelineId\": 3154, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_life_less30_01\", \"description\": \"不容小觑呢。\", \"voicelineId\": 3155, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_life_less30_02\", \"description\": \"久违的对手…\", \"voicelineId\": 3156, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_life_less30_03\", \"description\": \"该决断了…\", \"voicelineId\": 3157, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_life_less30_teammate_01\", \"description\": \"不可大意。\", \"voicelineId\": 3158, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_life_less30_teammate_02\", \"description\": \"阁下务必小心。\", \"voicelineId\": 3159, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_life_die_01\", \"description\": \"失态了…\", \"voicelineId\": 3160, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_life_die_02\", \"description\": \"我还有…未竟之事…\", \"voicelineId\": 3161, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_life_die_03\", \"description\": \"让家族…蒙羞了…\", \"voicelineId\": 3162, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_battle_hit_H_01\", \"description\": \"无礼的家伙…\", \"voicelineId\": 3163, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_ayaka/vo_ayaka_battle_hit_H_02\", \"description\": \"怎么会…\", \"voicelineId\": 3164, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_ayaka_teamJoin_01\", \"description\": \"神里绫华，参上。\", \"voicelineId\": 3165, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_ayaka_teamJoin_02\", \"description\": \"烦请赐教。\", \"voicelineId\": 3166, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_ayaka_teamJoin_03\", \"description\": \"呵呵，请多关照。\", \"voicelineId\": 3167, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000003, 'Jean', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_draw_appear\", \"description\": \"「蒲公英骑士」，琴，申请入队。从今往后，我的荣誉与忠诚将与你同在！\", \"voicelineId\": 4100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·行动\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_explore_idle_01\", \"description\": \"行动起来吧，我们不该在这里停留。\", \"voicelineId\": 4101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·骑士团\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_explore_idle_02\", \"description\": \"骑士团的大家…有没有认真工作呢？\", \"voicelineId\": 4102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·目标\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_explore_idle_03\", \"description\": \"走吧，前往下一个目标！\", \"voicelineId\": 4103, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_weather_heavyRain_01\", \"description\": \"下雨也无法阻挡我的脚步。\", \"voicelineId\": 4104, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_weather_afterRain_01\", \"description\": \"这样的天气，正适合行动。\", \"voicelineId\": 4105, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_weather_snowy_01\", \"description\": \"下雪了，要注意战靴的保养啊。\", \"voicelineId\": 4106, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_weather_breezy_01\", \"description\": \"舒适的天气。\", \"voicelineId\": 4107, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_weather_gale_01\", \"description\": \"传说，那天也刮着罕见的大风…\", \"voicelineId\": 4108, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_greetingMorning\", \"description\": \"「一日之计在于晨」，今天也请加油。\", \"voicelineId\": 4109, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_greetingNoon\", \"description\": \"好，现在开始处理任务吧。\", \"voicelineId\": 4110, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_greetingNight\", \"description\": \"看样子，差不多已经对咖啡免疫了。如果有什么替代品的话…问问丽莎好了。\", \"voicelineId\": 4111, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_greetingNight2\", \"description\": \"今日的修炼就到此为止，做得很棒，辛苦你了。\", \"voicelineId\": 4112, \"voicelineType\": \"1004\"}, {\"title\": \"关于琴自己…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_idle\", \"description\": \"今天为了保护民众，把五座遗迹守卫斩成了碎片。唉，我还需要继续磨练自己…这么珍贵的文化遗产，下次应该尝试空手制服…\", \"voicelineId\": 4113, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·信条\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_close1\", \"description\": \"我会全力帮助你，当然，如果你的方向偏离了正义，我也会毫不犹豫地指出。\", \"voicelineId\": 4114, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·誓言\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_close2\", \"description\": \"我以此剑起誓，必将胜利献给你。\", \"voicelineId\": 4115, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·任务\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_close3\", \"description\": \"任务可是不会自动完成的，但适当放松一下也好。今天就破例午休几分钟吧。\", \"voicelineId\": 4116, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_pendant\", \"description\": \"「永护蒙德」是古恩希尔德家族的家训。每当驱动「神之眼」，我都会想起母亲、还有蒙德民众的期盼。为蒙德而战，为自由而战——我，在所不辞。\", \"voicelineId\": 4117, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_share\", \"description\": \"我谨代表西风骑士团，向你为蒙德所做的一切致以谢意。还请你劳逸结合，量力而…怎么了，你突然笑了起来，我说了什么奇怪的话吗？\", \"voicelineId\": 4118, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_pref_gift\", \"description\": \"「蒲公英，蒲公英，跟风一起，到远方去吧。」…它乘上风，说不定连天空岛都能飞到呢。\", \"voicelineId\": 4119, \"voicelineType\": \"3003\"}, {\"title\": \"关于芭芭拉…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_barbara_01\", \"description\": \"芭芭拉非常努力，只不过有时过于勉强自己…嗯？问我为什么了解得这么清楚？因为西风教会也归属骑士团管辖。\", \"voicelineId\": 4120, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_lisa_01\", \"description\": \"丽莎，有她在的话，我会安心很多。\", \"voicelineId\": 4121, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_ambor_01\", \"description\": \"安柏这段时间确实有所成长。希望有朝一日，她的事迹也会被吟游诗人传颂。\", \"voicelineId\": 4122, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_kaeya_01\", \"description\": \"是吗…凯亚也向你提出建言了啊。他是一名优秀的西风骑士，这点毋庸置疑。\", \"voicelineId\": 4123, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_klee_01\", \"description\": \"虽说玩乐是孩子的天性，但可莉中意的玩具却都是些危险品。让人难以放心。\", \"voicelineId\": 4124, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_albedo_01\", \"description\": \"「天才」这种名词，或许正是为了阿贝多这样的人准备的吧。\", \"voicelineId\": 4125, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_varka_01\", \"description\": \"法尔伽大团长，他是西风骑士团的当代传奇。等到他凯旋归来的那一天，就请你亲自和他交谈吧。相信你也能从中受益。\", \"voicelineId\": 4126, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于诺艾尔…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_noel_01\", \"description\": \"诺艾尔，嗯…那个努力想要成为西风骑士的少女。她的内心仍有软弱之处，现在这个阶段，也许还不适合让她接触外界的凶险。\", \"voicelineId\": 4127, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于罗莎莉亚…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_rosaria_01\", \"description\": \"罗莎莉亚修女总是把「麻烦」挂在嘴边，实际却十分称职。上次我和她说「如果觉得麻烦也可以找我帮忙」，她却回答「这样更麻烦」。嗯…我果然还有很多欠缺啊。\", \"voicelineId\": 4128, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克·愧欠\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_diluc_01\", \"description\": \"迪卢克前辈对骑士团的指摘事出有因，即使心中愧疚也无法改变既定的结果…我只想通过我的努力，让他对骑士团有所改观…嗯，这是我的责任。\", \"voicelineId\": 4129, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克·敬重\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_diluc_02\", \"description\": \"迪卢克…是一位非常可敬的前辈。虽然我们选择的道路不同，但这份共通的守护蒙德的心意，我能感受得到。\", \"voicelineId\": 4130, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于砂糖…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_sucrose_01\", \"description\": \"作为炼金术士，砂糖也算天赋异禀。况且她的身边还有阿贝多指点，未来应该不用担心。只是…不，没什么，沉浸在自己的世界里，也不算坏事吧。\", \"voicelineId\": 4131, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于优菈…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_eula_01\", \"description\": \"优菈？咳…请不要对她的身世耿耿于怀，西风骑士会公正地评价每个人。优菈明辨是非，才华出众，偶尔发表危险言论，也只是她的性格使然。哪怕她总是说要挑战我，我也不介意。\", \"voicelineId\": 4132, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于米卡…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_teammate_mika_01\", \"description\": \"大团长选中米卡作为远征队的前侦骨干，不仅是出于任务需要，更是看中了他踏实勤恳的品质。从我个人角度而言，我也很荣幸能与这样的同伴共事。\", \"voicelineId\": 4171, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解琴·其一\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_friendship_01\", \"description\": \"我肩负着西风骑士团的信任，还有蒙德民众的期待。为此，我不能松懈。\", \"voicelineId\": 4133, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解琴·其二\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_friendship_02\", \"description\": \"温妮莎的「蒲公英骑士」之名传承至今，曾经有无数伟大的骑士获授这一荣誉。我不能辱没这个名字。因此，决不能松懈。要成为守护众人的坚盾与利剑。\", \"voicelineId\": 4134, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解琴·其三\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_friendship_03\", \"description\": \"无论是传奇故事还是史书，都只记载了伟大骑士的功绩。难道，他们一次也不曾迷失过吗…？\\n风啊，请指引我前进的道路。\", \"voicelineId\": 4135, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解琴·其四\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_friendship_04\", \"description\": \"全身心投入工作的时候，烦恼和时间会一并被忘却。「你是最适合做这种事情的人选。」…那个时候，大团长法尔伽就是这样对我说的。\", \"voicelineId\": 4136, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解琴·其五\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_friendship_05\", \"description\": \"与你同行时，前进的道路变得无比清晰。就好像，终于有人能依靠，这究竟是…\\n不，一定是我还不够努力。绝对不能松懈，不能辜负西风骑士团和蒙德…但是，谢谢你。\", \"voicelineId\": 4137, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"琴的爱好…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_pref_hobby\", \"description\": \"或许可以和你聊聊书上那些英雄传记。嗯，你听说过「坎瑞亚英雄王」的故事吗？\", \"voicelineId\": 4138, \"voicelineType\": \"6001\"}, {\"title\": \"琴的烦恼…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_dialog_annoyed\", \"description\": \"假如有什么神奇的药剂，喝了就不需要睡觉…嗯，要不明天问问丽莎吧？\", \"voicelineId\": 4139, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_pref_foodLike\", \"description\": \"猫尾酒馆的披萨…很久没吃过了。如果能外送到办公室就好了呢。\", \"voicelineId\": 4140, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_pref_foodDislike\", \"description\": \"优秀的骑士不能挑食。\", \"voicelineId\": 4141, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_spice_pref_01\", \"description\": \"不仅味道好，还兼顾了健康。让你费心了。\", \"voicelineId\": 4168, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_spice_normal_01\", \"description\": \"嗯，精神振奋不少。谢谢你。\", \"voicelineId\": 4169, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_spice_dislike_01\", \"description\": \"呼…总之，辛苦你了。\", \"voicelineId\": 4170, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_pref_birthday\", \"description\": \"今天是值得庆祝的日子。要说为何的话，因为这是受风护佑的你，诞生的日子啊。既然是生日，那就好好休息一下吧。\\n咳咳…祝你生日快乐…\\n啊，请原谅我的冒昧。不知这份礼物，是否能令你满意呢？\", \"voicelineId\": 4142, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_starUp_01\", \"description\": \"好，一鼓作气前往下一个目标。\", \"voicelineId\": 4143, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_starUp_02\", \"description\": \"只要风不停歇，我就不会停下脚步。\", \"voicelineId\": 4144, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_starUp_03\", \"description\": \"就算暂时获得了平静，也不能掉以轻心。身为代理团长，我必须未雨绸缪。\", \"voicelineId\": 4145, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_qin/vo_qin_starUp_04\", \"description\": \"我做得还不够好。自从与你相遇，一直承蒙你的关照。这份感激…\\n风啊，请容许我的私心。并非作为代理团长，只是作为「琴」，在此起誓——我的剑将与你同在。\", \"voicelineId\": 4146, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_battle_skill1_01\", \"description\": \"一决胜负！\", \"voicelineId\": 4147, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_battle_skill1_02\", \"description\": \"…哈！\", \"voicelineId\": 4148, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_battle_skill1_03\", \"description\": \"…散！\", \"voicelineId\": 4149, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_battle_skill3_01\", \"description\": \"风，回应我吧。\", \"voicelineId\": 4150, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_battle_skill3_02\", \"description\": \"以剑为誓！\", \"voicelineId\": 4151, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_battle_skill3_03\", \"description\": \"风之神，请指引我们。\", \"voicelineId\": 4152, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_chest_open_01\", \"description\": \"惊喜的收获。\", \"voicelineId\": 4153, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_chest_open_02\", \"description\": \"嗯，真是幸运的一天。\", \"voicelineId\": 4154, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_chest_open_03\", \"description\": \"希望大家都能获得宝藏。\", \"voicelineId\": 4155, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_life_less30_01\", \"description\": \"我，没事…！\", \"voicelineId\": 4156, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_life_less30_02\", \"description\": \"还有同伴…需要保护…\", \"voicelineId\": 4157, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_life_less30_03\", \"description\": \"还不能放弃…\", \"voicelineId\": 4158, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_life_less30_teammate_01\", \"description\": \"你受伤了…请暂时退后吧！\", \"voicelineId\": 4159, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_life_less30_teammate_02\", \"description\": \"让我来吧。\", \"voicelineId\": 4160, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_life_die_01\", \"description\": \"蒙德…\", \"voicelineId\": 4161, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_life_die_02\", \"description\": \"个人的力量是有极限的…\", \"voicelineId\": 4162, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_life_die_03\", \"description\": \"我…还不够称职…\", \"voicelineId\": 4163, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_qin/vo_qin_battle_hit_H_01\", \"description\": \"这点伤而已！\", \"voicelineId\": 4164, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_qin_teamJoin_01\", \"description\": \"随时可以出发。\", \"voicelineId\": 4165, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_qin_teamJoin_02\", \"description\": \"已做好万全准备。\", \"voicelineId\": 4166, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_qin_teamJoin_03\", \"description\": \"听凭风引。\", \"voicelineId\": 4167, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000005, 'Aether', '[{\"title\": \"关于风车…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_windmill_hero\", \"description\": \"派蒙：蒙德有很多风车呢。\\n{NICKNAME}：因为蒙德城建在水平面的上方，所以是靠风车把水抽上来的吧。\\n派蒙：回答正确！蒙德四季风吹不断，所以水源的供应也很稳定。\\n派蒙：而且，风车就是所谓「看得见的风」吧——然后，风铃就是「听得见的风」。\\n派蒙：也算是一种祈求风神护佑的吉祥物啦。\\n{NICKNAME}：原来如此，和派蒙一样是吉祥物啊。\\n派蒙：不一样！风车是用木头做的，不能当应急食品，只能用来磨牙啊！\\n{NICKNAME}：嗯…\\n{NICKNAME}：…我该接话吗？\", \"voicelineId\": 1002, \"voicelineType\": \"24001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于酒馆老板…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_pubHolder_hero\", \"description\": \"{NICKNAME}：我听说，收了可观的小费以后，酒馆老板会小声说出一些情报。\\n派蒙：是「天使的馈赠」吗？但那位迪卢克老爷，好像是非常有钱的人。\\n派蒙：究竟要多少小费，才能让老板觉得「可观」呢？\\n{NICKNAME}：唔…那也许是我记错了吧。\\n{NICKNAME}：也许这个传言，是在别的世界听到的…\\n派蒙：你去过的世界真的很多呢。\", \"voicelineId\": 1003, \"voicelineType\": \"25001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于果酒湖…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_ciderLake_hero\", \"description\": \"派蒙：果酒湖是不冻湖，一整年里都不会结冰。\\n派蒙：蒙德最好的苹果酒，只能用这座湖里的甜水来酿。\\n派蒙：湖水真的很好喝！我一秒就能喝掉两大瓶。\\n{NICKNAME}：真是惊人。\\n派蒙：哼哼。\\n{NICKNAME}：派蒙这样的体型，喝这么多水…\\n{NICKNAME}：居然不会像风史莱姆那样，炸到漏气满天飞…\\n派蒙：哼哼，装好喝的饮料的是另一个胃。\\n{NICKNAME}：嗯…世界真是广大，需要花时间去思考的见闻，还有很多…\", \"voicelineId\": 1004, \"voicelineType\": \"26001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于禁书区的书…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_restrictedSection_hero\", \"description\": \"{NICKNAME}：丽莎提到过的，那些「禁书区」的书…\\n{NICKNAME}：你有没有好奇过？什么样的书会被放在禁书区里呢？\\n{NICKNAME}：莫非…\\n{NICKNAME}：会有那种不适合小孩子看的书…？\\n派蒙：什么？明明《野猪公主》都不在禁书区的！\\n派蒙：还有比那本更不适合小孩子看的书吗？派蒙开始好奇了！\", \"voicelineId\": 1005, \"voicelineType\": \"37001\", \"unlockConditions\": [{\"paramList\": [1010115], \"unlockText\": \"完成「麻烦的工作」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于努力与回报…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_effortsVSreturn_hero\", \"description\": \"派蒙：我发现，在蒙德努力工作不一定会有回报呢。\\n{NICKNAME}：为什么这么说？\\n派蒙：你看西风骑士的霍夫曼先生，每天尽职尽责…\\n派蒙：可那位总是很轻松悠闲的凯亚先生，却是他的上司。\\n{NICKNAME}：嗯…可是最辛苦的琴，当上了代理团长呀？\\n派蒙：那、那论地位来讲的话…\\n派蒙：最懒散的温迪，还是整个蒙德城的神明呢！\", \"voicelineId\": 1006, \"voicelineType\": \"31001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于歌德大酒店…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_gothHotel_hero\", \"description\": \"{NICKNAME}：想住一次歌德大酒店…\\n派蒙：我也是！\\n派蒙：里面的房间一定又干净又大吧。\\n{NICKNAME}：不过听歌德老伯说，愚人众搬进去以后，出现了各种奇怪的问题。\\n{NICKNAME}：雷萤术士提进去的雷萤，因为静电吸了好多灰，死了不少。\\n{NICKNAME}：然后，因为雾虚花粉和胡椒弄错了…\\n{NICKNAME}：「债务处理人」互相指责对方欠过自己酒钱，引发了斗殴。\\n派蒙：…加油啊，歌德大酒店。\", \"voicelineId\": 1007, \"voicelineType\": \"56001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于风的流向…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_windDirection_hero\", \"description\": \"{NICKNAME}：人们都说，蒙德是风的国度。\\n{NICKNAME}：可是，我还不知道这个季节盛行的风向，是哪个方位呢。\\n派蒙：不如我们去问问温迪吧。\\n{NICKNAME}：他对这种问题，只会「欸嘿」一声敷衍过去吧…\\n派蒙：说得也是。风神只是一个卖唱的而已，懂什么风…\", \"voicelineId\": 1008, \"voicelineType\": \"64001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于炼金术…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_alchemy_hero\", \"description\": \"{NICKNAME}：原来蒙德的炼金工作台是在街头开放的。\\n派蒙：是呀，很奇怪吗？\\n{NICKNAME}：我曾经去过的许多世界里，炼金术都是作为秘术存在的。\\n{NICKNAME}：看到炼金术成为日常的一部分，就像看到「三胃人」的世界一样奇怪…\\n派蒙：喂！人只有一个胃才会奇怪吧！\\n{NICKNAME}：嗯…\\n{NICKNAME}：你是认真的吗？\\n派蒙：嘿嘿，你猜！\", \"voicelineId\": 1009, \"voicelineType\": \"66001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提瓦特…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_teyvat_hero\", \"description\": \"{NICKNAME}：提瓦特大陆的昼夜，好像都特别短暂。\\n{NICKNAME}：这里的夜空也布满了星星。不过，跟故乡看到的不同。\\n{NICKNAME}：提瓦特人的命运，会不会也与他们的星座有关呢？\\n派蒙：哦？你也懂「观星」吗？真好啊，须弥国以外很少有人会这种技巧呢。\\n派蒙：我的好奇心被点燃了！快，给我占卜一下！\\n{NICKNAME}：嗯…\\n{NICKNAME}：派蒙围巾上的夜空…流转着群星与深海之光…\\n{NICKNAME}：星的纹路，告诉我说，在未来…七天之内…\\n派蒙：七天之内…？\\n{NICKNAME}：可能有好事…或者坏事…或者不好不坏的事发生…\\n派蒙：嗯…你这个回答平稳得像岩史莱姆一样啊！\", \"voicelineId\": 1010, \"voicelineType\": \"11001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「自由」之神…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_godOfFreedom_hero\", \"description\": \"{NICKNAME}：我们救回特瓦林之后，在回蒙德的路上…\\n{NICKNAME}：第一次见到了「尘世七执政」的面目呢。原来是这样的神…\\n派蒙：嗯？我们认识温迪，不是已经很久了吗？\\n{NICKNAME}：我是指…他作为风神巴巴托斯的那一面。\\n{NICKNAME}：在吟游诗人的躯壳之下，藏着真实的神灵。\\n{NICKNAME}：「被自由之神命令的自由，还能称之为自由吗？」\\n{NICKNAME}：他问特瓦林的这个问题，我也还在思考答案…\", \"voicelineId\": 1011, \"voicelineType\": \"67001\", \"unlockConditions\": [{\"paramList\": [39604], \"unlockText\": \"完成「巨龙与自由之歌」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于蒙德的地形…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_monstadtTerrain_hero\", \"description\": \"派蒙：蒙德这边的地形，平原和丘陵是很多的。\\n派蒙：据说是巴巴托斯改造天地时，用暴风削平了陡峭的山崖和峡湾…\\n{NICKNAME}：不过，没修整完的地方也还是有的。\\n派蒙：比如摘星崖？\\n{NICKNAME}：没错。\\n{NICKNAME}：这就好像是…做模型时懒得磨平的水口一样吧。\\n派蒙：水口？那是什么？\", \"voicelineId\": 1012, \"voicelineType\": \"69001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于对联…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_couplet_hero\", \"description\": \"派蒙：听说对联是璃月的传统文化，有人写完上联以后，会为下联悬赏千金！\\n派蒙：但因为对联很难，钱也不是那么好赚的。\\n派蒙：不仅要求字数相等，还要考虑词性相对…\\n{NICKNAME}：嗯，举一个例子呢？\\n派蒙：嗯...「风起地风不起」。\\n{NICKNAME}：…唔，「云来海云再来」。\\n派蒙：唔！\\n派蒙：别坐着了，快点起来，快点起来！我们该赚钱去了！\", \"voicelineId\": 1013, \"voicelineType\": \"47001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「不要玩吃的，也不要玩钱」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_moneyAdmonishment_hero\", \"description\": \"派蒙：璃月港流传着一条岩王帝君的训诫，大概的意思是「不要玩钱」。\\n派蒙：因为最初的「摩拉」是他信任人类，才用黄金之体舍肉铸造的。\\n{NICKNAME}：凯亚好像一直在玩钱…\\n派蒙：所以千万不要学他。\\n{NICKNAME}：我记得还有谁告诫过，不要玩食物。\\n派蒙：是的是的。要对做好的食物抱有敬畏之心。\\n派蒙：…你，你看着我干什么？\", \"voicelineId\": 1014, \"voicelineType\": \"59001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于《碎梦奇珍》…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_heartsDesire_hero\", \"description\": \"派蒙：顺时针走七圈，逆时针走七圈，再睁开眼睛…\\n{NICKNAME}：你在梦游吗？\\n派蒙：才没有呢！我只是想看看《碎梦奇珍》里的那家古董店，是不是真的存在！\\n{NICKNAME}：假如故事里的古董店真的存在，派蒙想要买什么宝物呢？\\n派蒙：史莱姆生成器！\\n{NICKNAME}：真的会存在那种东西吗…\", \"voicelineId\": 1015, \"voicelineType\": \"62001\", \"unlockConditions\": [{\"paramList\": [3, 128], \"unlockText\": \"解锁「璃月 璃月港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于古华派…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_guhuaClan_hero\", \"description\": \"{NICKNAME}：最近，听古华派的弟子讲了这样一个故事。\\n派蒙：古华派吗，应该是很侠义的故事吧。\\n{NICKNAME}：几位师兄弟想要通过比武，定下师妹的亲事，师妹也很赞成这么做。\\n派蒙：在璃月叫「比武招亲」吧？我听说过！\\n{NICKNAME}：可比武前一晚，师妹将大师兄最顺手的那柄剑偷走了。\\n派蒙：那师兄可真惨…是师妹有意想要他输的呀…\\n{NICKNAME}：是啊，后来大师兄用了十分不顺手的剑，惨遭落败。\\n{NICKNAME}：他难以接受这样的结局，跪在地上痛哭流涕。\\n派蒙：可怜的人…他一定很喜欢那个师妹吧？\\n{NICKNAME}：最终，他不得不在众人的见证下…迎娶了师妹。\\n派蒙：原来是输的人娶吗？！\", \"voicelineId\": 1016, \"voicelineType\": \"32001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荻花洲…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_dihuaMarsh_hero\", \"description\": \"派蒙：你知道吗？荻花洲的荻叶，是常见的造纸材料。\\n派蒙：用荻杆实心的一端做笔、空心的一端做笛，在璃月也是一件很风雅的事。\\n派蒙：千百年来，有许多侠客与剑士，都会选在这个风雅的地方对决。\\n派蒙：荻花越多就越风雅，但它们长势最茂盛的地方，有时水会很深…\\n派蒙：所以，决斗声势浩大、最终却双双失足溺死的倒霉侠客…其实还挺多的。\\n{NICKNAME}：从这个故事里我们能学到什么呢？\\n派蒙：不要打架！\", \"voicelineId\": 1017, \"voicelineType\": \"29001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「君子鸟」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_crane_hero\", \"description\": \"派蒙：据说在璃月，人们把鹤叫做「君子鸟」。\\n{NICKNAME}：这是为什么呢？\\n派蒙：唔…这个，我也不太清楚…\\n{NICKNAME}：那么，我来给你讲一个「仙鹤报恩」的故事吧。\\n{NICKNAME}：很久很久以前，有一个善良的书生，解救了一只落入陷阱的仙鹤。\\n{NICKNAME}：后来，在一个非常寒冷的夜晚，有一位美丽的姑娘前来借宿。\\n{NICKNAME}：姑娘背着一把重剑，把剑法传授给了书生，督促他日夜练习。\\n派蒙：咦？\\n{NICKNAME}：书生剑术大成以后，就与姑娘一起投身江湖，行侠仗义。\\n{NICKNAME}：十年以后，仙鹤所化的君子终于前来报恩，但那对侠侣却已经退隐江湖…\\n{NICKNAME}：这就是「君子报恩，十年太晚」的故事。\\n派蒙：嗯？\", \"voicelineId\": 1018, \"voicelineType\": \"28001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绝云间…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_jueyunKarst_hero\", \"description\": \"{NICKNAME}：据说绝云间是仙人的居住地。\\n派蒙：哇——仙人的居住地！\\n{NICKNAME}：说不定在高耸入云的山顶，能遇到仙人呢。\\n派蒙：哇——遇到仙人！\\n{NICKNAME}：但是，仙人平时该怎么交流呢？\\n派蒙：哇——怎么交流呢！\\n{NICKNAME}：嗯？这个应急食品快要坏掉了吗？该抓紧吃掉了…\\n派蒙：咳、咳咳。嗯…在山头呼喊的话，就能交流了吧。\\n{NICKNAME}：比起仙人，这更像是丘丘人的行为吧…\", \"voicelineId\": 1019, \"voicelineType\": \"43001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「契约」之神…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_godOfContract_hero\", \"description\": \"{NICKNAME}：没想到，岩神居然与冰神签订了「契约」。\\n{NICKNAME}：契约的内容，究竟会是什么呢…\\n派蒙：派蒙觉得，不管是谁，要和「冰之女皇」做交易，都很不安全！\\n{NICKNAME}：确实是这样…\\n{NICKNAME}：但既然摩拉克斯是所有神灵里，最理解「契约」本质的那一位…\\n{NICKNAME}：他应该不会没有考虑过这件事。\\n派蒙：嗯，摩拉克斯本人好像很有自信，叫它「终结一切契约的契约」…\\n{NICKNAME}：我们最终会见证真相…和结局的。\", \"voicelineId\": 1020, \"voicelineType\": \"68001\", \"unlockConditions\": [{\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于璃月的神谕…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_divinePrediction_hero\", \"description\": \"派蒙：说起来，岩王爷虽然喜欢微服私访，但正式降临却只有一年一次。\\n派蒙：其他神好像都不是这样的，岩王爷是有什么深意吗？\\n{NICKNAME}：我大概能猜到一点原因…\\n{NICKNAME}：你看，现在每年降下的那些神谕，已经牵动了太多璃月人的心。\\n{NICKNAME}：他们围着神谕打转，试图从字缝里分析出无限的「潜台词」…\\n{NICKNAME}：如果那样的神谕每天都有，璃月又会变成什么样呢？\\n派蒙：啊！\\n派蒙：我明白了。如果是我的话，一定会收集岩王爷在民间夸赞过的小吃，天天供奉给他！\\n派蒙：如果能直接从摩拉克斯那里得到摩拉的话，谁还会去做正经生意啊！\\n{NICKNAME}：虽然例子的逻辑有点跳跃，但…道理大致就是这样。\", \"voicelineId\": 1021, \"voicelineType\": \"70001\", \"unlockConditions\": [{\"paramList\": [101801], \"unlockText\": \"完成「浮世浮生千岩间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于班尼冒险团…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_bennysAdventureTeam_hero\", \"description\": \"派蒙：如果要和「班尼冒险团」合作探索秘境，就一定要做好准备。\\n派蒙：秘境是很危险的，出发前要多检查几遍物资和工具，不能大意。\\n派蒙：我听说在这些秘境里，光是冒险家协会统计过的死法，就有四百六十三种…\\n派蒙：如果班尼特不小心害死了你，我和他的良心都会很不安的！\\n{NICKNAME}：…为什么死的只有我？\\n派蒙：嗯，根据统计，因为我会飞，所以可以至少免疫其中的三百二十二种死法！\\n{NICKNAME}：我忽然不太想去秘境探险了…\", \"voicelineId\": 1022, \"voicelineType\": \"27001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于班尼特…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_bennett_hero\", \"description\": \"{NICKNAME}：我听说，艾伯特先生作为芭芭拉粉丝团的团长…\\n{NICKNAME}：经常故意弄出些磕磕碰碰的伤，就为了去教堂见芭芭拉一面。\\n派蒙：我觉得西风骑士团需要重点关注这种家伙。\\n{NICKNAME}：可是一个月下来，艾伯特发现…跟芭芭拉见面的次数，被班尼特远远超越了。\\n{NICKNAME}：毕竟在受伤方面，班尼特有天然的优势…\\n派蒙：这是什么「给芭芭拉小姐添麻烦」的比赛吗！\", \"voicelineId\": 1023, \"voicelineType\": \"34001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于偶像…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_idol_hero\", \"description\": \"派蒙：芭芭拉很受大家欢迎呢。\\n{NICKNAME}：毕竟是蒙德的大众偶像嘛。\\n派蒙：说起来我一直没太懂…「偶像」是什么呀？\\n{NICKNAME}：是一种职业，只需要负责可爱，就可以受大家喜欢，赚好多摩拉呢。\\n派蒙：和吉祥物差不多嘛。\\n{NICKNAME}：呃，也可以这么说吧…\", \"voicelineId\": 1024, \"voicelineType\": \"61001\", \"unlockConditions\": [{\"paramList\": [39604], \"unlockText\": \"完成「巨龙与自由之歌」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于姐妹关系…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_sisters_hero\", \"description\": \"{NICKNAME}：丽莎和安柏的关系，有点像姐妹。\\n派蒙：咦，为什么？\\n{NICKNAME}：安柏经常帮丽莎跑腿。姐姐为了偷懒，要求妹妹帮忙跑腿，是很常见的事…\\n{NICKNAME}：不过我和妹妹因为同年，所以就只能猜拳决定了。\\n派蒙：呜哇，这么说来，那你就是我的弟弟了！\\n{NICKNAME}：为什么？\\n派蒙：我会「飞」啊，实际上「跑腿」的只有你一个人哦！\\n{NICKNAME}：啊？\", \"voicelineId\": 1025, \"voicelineType\": \"40001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚的眼罩…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_kaeyasPatch_hero\", \"description\": \"{NICKNAME}：派蒙，你见过凯亚眼罩下面的样子吗？\\n派蒙：没见过呢。\\n{NICKNAME}：这么说来，凯亚似乎一年四季都不会摘下眼罩…\\n派蒙：哼哼，机智的派蒙已经猜到为什么了！\\n{NICKNAME}：嗯？\\n派蒙：肯定是要隐藏什么大秘密！\\n{NICKNAME}：大秘密？\\n派蒙：你看，凯亚外出的工作比较多。\\n派蒙：所以凯亚眼罩下的皮肤，肯定比周围的白一大圈。\\n{NICKNAME}：那如果摘下眼罩…\\n派蒙：肯定会被大家笑话的吧！然后被取奇怪的绰号！\\n派蒙：比如说——「花脸猫」！\\n{NICKNAME}：唔，他还没摘下眼罩，就已经被取了奇怪的绰号呢…\", \"voicelineId\": 1026, \"voicelineType\": \"41001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克与凯亚…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_dilucAndKaeya_hero\", \"description\": \"派蒙：奇怪…\\n{NICKNAME}：怎么了？\\n派蒙：为什么迪卢克和凯亚明明是很相似的两个人，关系却不太好呢？\\n{NICKNAME}：他们哪里相似了？\\n派蒙：凯亚像是那种…会光明正大地耍阴招的人。\\n派蒙：迪卢克像是那种…在暗地里做光明正大的事的人。\\n派蒙：是不是很相似？\\n{NICKNAME}：我还是不知道相似在哪里。\", \"voicelineId\": 1027, \"voicelineType\": \"60001\", \"unlockConditions\": [{\"paramList\": [46618], \"unlockText\": \"完成「暗夜英雄的不在场证明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于战斗力单位…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_combatEffectiveness_hero\", \"description\": \"{NICKNAME}：如果说一个丘丘人，能打三头野猪的话…\\n{NICKNAME}：琴团长和迪卢克老爷，分别有几丘丘战斗力呢？\\n派蒙：如果在蒙德城里体会过大家的统一口径，就应该知道，最厉害的是琴团长。\\n{NICKNAME}：我觉得迪卢克先出手的话，琴团长应该没办法化解。\\n派蒙：琴团长一定有办法的。\\n{NICKNAME}：肯定无解。\\n派蒙：琴团长的元素爆发是很强的。\\n{NICKNAME}：但那个「领域」，反过来会增强迪卢克。\\n派蒙：琴团长对付迪卢克老爷都不用「神之眼」。\\n{NICKNAME}：迪卢克只用「新手大剑」就…\\n派蒙：唉…\\n{NICKNAME}：唔…\\n{NICKNAME}：我们好无聊啊。\\n{NICKNAME}：他们都是为了蒙德而战的，不可能会打起来的。\\n派蒙：所以我觉得需要用丘丘人当战斗力单位啊。\\n派蒙：顺带一提，派蒙大概五分之一野猪哦。\", \"voicelineId\": 1028, \"voicelineType\": \"58001\", \"unlockConditions\": [{\"paramList\": [1020204], \"unlockText\": \"完成「真正的宝物」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷泽…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_razor_hero\", \"description\": \"派蒙：{NICKNAME}，你知道毛笔吗？\\n{NICKNAME}：用动物的毛做成的笔，可以拿来写字？\\n派蒙：嗯，答对了！据说好的毛笔能在璃月商人那边卖出高价呢！\\n{NICKNAME}：所以派蒙也想做毛笔？\\n派蒙：嗯！但是野外的狼都太凶了，所以我们去薅雷泽的毛做毛笔吧！\\n派蒙：雷泽毛茸茸的，肯定能做出上好的狼毫笔！然后我们就能大赚一笔！\\n{NICKNAME}：这样做出来的笔肯定带电，没办法用吧。\\n{NICKNAME}：而且雷泽不是狼，狼毫笔也不是狼毛做的…\\n派蒙：欸——那为什么要叫做狼毫笔！\\n{NICKNAME}：你看果酒湖里不也没有果酒吗。\\n派蒙：喔——很有道理呢！\", \"voicelineId\": 1029, \"voicelineType\": \"33001\", \"unlockConditions\": [{\"paramList\": [45406], \"unlockText\": \"完成「卢皮卡的意义」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_klee_hero\", \"description\": \"派蒙：可莉也是个很有意思的孩子呢。\\n派蒙：骑士团的大家都很喜欢她，说是团宠也不为过吧。\\n{NICKNAME}：派蒙和可莉…究竟哪一边比较强呢？\\n{NICKNAME}：啊，对了，派蒙不是吉祥物，派蒙是…\\n派蒙：哼，看到你张嘴就知道你准备说什么。这个笑话说太多次就不好笑了。\", \"voicelineId\": 1030, \"voicelineType\": \"57001\", \"unlockConditions\": [{\"paramList\": [1020204], \"unlockText\": \"完成「真正的宝物」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于传说中的万能女仆…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_noelle_hero\", \"description\": \"派蒙：分享生活小智慧时间到！\\n{NICKNAME}：生活小智慧？\\n派蒙：在蒙德，如果有东西怎么修都修不好，或者怎么洗都洗不干净…\\n派蒙：遇到这种事，自己又处理不了的话，就可以对着天空大喊一声：\\n派蒙：「诺——艾——尔——！」\\n派蒙：所有的烦心事，就都会被马上解决啦。\\n{NICKNAME}：这就是蒙德人的生活小智慧吗？太棒了，学到许多…\", \"voicelineId\": 1031, \"voicelineType\": \"30001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲谢尔…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fischl_hero\", \"description\": \"派蒙：菲谢尔给人的感觉很不一样呢。\\n{NICKNAME}：比如说？\\n派蒙：比如说，和一只会说话的乌鸦一起行动。\\n{NICKNAME}：唔，那我和派蒙一起旅行，也差不多吧。\\n{NICKNAME}：不过，奥兹还能当菲谢尔的翻译。但派蒙的话…嗯…\\n派蒙：什么？！我可比乌鸦厉害多了！\\n{NICKNAME}：比如说？\\n派蒙：唔…嗯…呃…比如说我不用翅膀也能飞！\", \"voicelineId\": 1032, \"voicelineType\": \"35001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宠物…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_pet_hero\", \"description\": \"{NICKNAME}：说起菲谢尔，她也自称是「异世界的来客」…\\n{NICKNAME}：这一点和我一样呢，而且都带着一只宠物。\\n派蒙：宠物？不对不对…\\n{NICKNAME}：只不过她的乌鸦「奥兹」…外型又帅气，讲话又彬彬有礼。\\n{NICKNAME}：更重要的是又能侦察又能打架，帮助很大。\\n{NICKNAME}：和菲谢尔商量一下，偶尔交换一下也还挺有趣的吧？一周两周之类的。\\n派蒙：你不先问我的意见吗？！\", \"voicelineId\": 1033, \"voicelineType\": \"36001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_beidou_hero\", \"description\": \"派蒙：要怎么样才能成为北斗大姐头那种，又有号召力，又帅气的人物呢！\\n{NICKNAME}：要有足够的见识…\\n派蒙：陪你旅行到现在，派蒙已经见过很多东西了！\\n{NICKNAME}：要经历挫折和苦难…\\n派蒙：派蒙差点在水里咕嘟咕嘟咕嘟下去了…\\n{NICKNAME}：要始终怀有鼓舞他人的气概…\\n派蒙：嗯！派蒙一直支持着你哦。\\n{NICKNAME}：看待问题要成熟…\\n派蒙：喂！你就是想说派蒙我没可能了是吧？\", \"voicelineId\": 1034, \"voicelineType\": \"52001\", \"unlockConditions\": [{\"paramList\": [3, 128], \"unlockText\": \"解锁「璃月 璃月港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_ningguang_hero\", \"description\": \"派蒙：要怎么样才能成为凝光大人那种，很有钱，又很有钱的人物呢！\\n{NICKNAME}：凝光给你的印象就只剩下钱了吗…\\n派蒙：还有大大的「群玉阁」！不过那也是用摩拉堆出来的吧。\\n{NICKNAME}：那么，要有精明的头脑…\\n派蒙：派蒙擅长给人取绰号！\\n{NICKNAME}：要熟悉市场运作的规则…\\n派蒙：一份渔人吐司卖1025摩拉，下雨天也不会打折。\\n{NICKNAME}：要有高人一等的办事手腕…\\n派蒙：…怎样才能跟一个有钱人成为朋友呢？\\n{NICKNAME}：这就已经放弃了吗？！\", \"voicelineId\": 1035, \"voicelineType\": \"53001\", \"unlockConditions\": [{\"paramList\": [101609], \"unlockText\": \"完成「辞行久远之躯」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于七七是僵尸这件事…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_qiqi_hero\", \"description\": \"派蒙：七七…会不会需要吸血呢？\\n{NICKNAME}：那不是僵尸，是吸血鬼吧。\\n派蒙：那她的胳膊会不会突然掉下来？\\n{NICKNAME}：那不是僵尸，是丧尸吧。\\n派蒙：真不愧是旅行者，见识非常广呢！\\n派蒙：这样说来，僵尸会做什么特别的事呢？\\n{NICKNAME}：体操？\\n派蒙：你说得很有道理！所以会做体操就是僵尸！\", \"voicelineId\": 1036, \"voicelineType\": \"38001\", \"unlockConditions\": [{\"paramList\": [101609], \"unlockText\": \"完成「辞行久远之躯」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于飞行…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fly_hero\", \"description\": \"派蒙：{NICKNAME}，来跟派蒙学飞行吧！\\n派蒙：三、二、一！\\n{NICKNAME}：啊，不见了。\\n{NICKNAME}：算了，已经很累了，还是先在这坐一会…\\n{NICKNAME}：我的心是和你一起飞翔的…嗯…\", \"voicelineId\": 1037, \"voicelineType\": \"10001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于史莱姆…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_slime_hero\", \"description\": \"派蒙：{NICKNAME}，你最喜欢哪种史莱姆呀？\\n{NICKNAME}：火史莱姆吧。凑近就能感到热浪，冬天会很需要。\\n派蒙：实用性的角度呢，不愧是旅行者。\\n{NICKNAME}：那派蒙呢？\\n派蒙：我都喜欢！都很好吃！\\n{NICKNAME}：好吃…\\n派蒙：把史莱姆叽里咕噜、咕嘟哇噜地做成特色饮品，就是「派蒙特调」喔！\\n{NICKNAME}：好，好吧…\\n{NICKNAME}：那么，就把小派蒙在应急食品的顺位，下调一位吧。\\n派蒙：我希望这个顺位里不要有我才好！\", \"voicelineId\": 1038, \"voicelineType\": \"12001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丘丘人…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_hilichurls_hero\", \"description\": \"{NICKNAME}：对丘丘人，我们是不是做得有点太过分了？\\n派蒙：确实…有的时候，我们就像见到蜂窝一定要捅一下的小孩子一样。\\n{NICKNAME}：嗯…只是「捅一下」的程度吗？\", \"voicelineId\": 1039, \"voicelineType\": \"13001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「好睡族」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_sleeper_hero\", \"description\": \"{NICKNAME}：「好睡族」…丘丘人的部族名真是奇妙。\\n派蒙：好睡族的丘丘人，会抓住一切可以利用的时机睡觉。\\n派蒙：据说他们的兽皮床铺非常松软，你想试试看吗？\\n{NICKNAME}：派蒙自己不试试吗？\\n派蒙：我可以飘浮着睡！空气永远是最松软的床。嘿嘿嘿，羡慕吗？\\n{NICKNAME}：…有一点点。\", \"voicelineId\": 1040, \"voicelineType\": \"14001\", \"unlockConditions\": [{\"paramList\": [3, 14], \"unlockText\": \"解锁「蒙德 达达乌帕谷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「好肉族」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_meaty_hero\", \"description\": \"{NICKNAME}：「好肉族」…丘丘人的部族名真是奇妙。\\n派蒙：「好肉族」的丘丘人，会定期祭祀。他们的祭坛建得很壮观喔。\\n{NICKNAME}：祭祀的内容是？\\n派蒙：「每天都有肉吃」！是很棒的愿望吧？\\n{NICKNAME}：…可以想见的答案，我不意外。\", \"voicelineId\": 1041, \"voicelineType\": \"15001\", \"unlockConditions\": [{\"paramList\": [3, 14], \"unlockText\": \"解锁「蒙德 达达乌帕谷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「黑日族」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_blacksun_hero\", \"description\": \"{NICKNAME}：「黑日族」…丘丘人也有这种听起来比较正常的部族名呢。\\n派蒙：「黑日族」的丘丘人，很神秘呀。\\n派蒙：那个部族的丘丘人，都会画一种叫做「黑日标志」的图案。\\n派蒙：但据说只有黑日族的大萨满，才知道那个标志背后的含义…\\n{NICKNAME}：黑色的…太阳…\\n派蒙：嗯？{NICKNAME}，你刚才说什么？\\n{NICKNAME}：啊，我在问你今天晚上要煮什么肉的汤。\\n派蒙：怎么突然转到这种话题，你是「好肉族」的丘丘人吗——我要野猪肉的！谢谢！\", \"voicelineId\": 1042, \"voicelineType\": \"16001\", \"unlockConditions\": [{\"paramList\": [3, 14], \"unlockText\": \"解锁「蒙德 达达乌帕谷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于财宝…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_treasure_hero\", \"description\": \"派蒙：派蒙…身体，有点不太舒服…\\n{NICKNAME}：你怎么了？\\n派蒙：已经很久没有亲手打开过宝箱了，这样下去…这样下去的话…\\n{NICKNAME}：这样下去的话，总有一天你会被放着一摩拉的捕兽夹抓住吧。\\n派蒙：喂——派蒙会飞啦，才不会上那种当的。\", \"voicelineId\": 1043, \"voicelineType\": \"17001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于发胖…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fat_hero\", \"description\": \"派蒙：呜哇，最近在旅行途中，吃了很多好吃的呢。\\n派蒙：只要吃到好吃的，旅行的疲惫就能一扫而空！\\n{NICKNAME}：嗯…如果发胖了，小派蒙会飞不起来吗？\\n派蒙：哼哼，才不会！我是吃不胖的类型！\\n{NICKNAME}：嗯…\\n派蒙：所以我还要吃更多好吃的！\\n{NICKNAME}：光吃不长肉。从应急食品的角度来看，不合格了吧？\\n派蒙：喂——难道你在外面还有其他合格的应急食品吗？\", \"voicelineId\": 1044, \"voicelineType\": \"19001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于猫派和狗派…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_catORdog_hero\", \"description\": \"派蒙：猫咪和狗狗，你更喜欢哪一个？\\n{NICKNAME}：我更喜欢小派蒙哦！\\n派蒙：呜哇，这犯规了吧…\\n派蒙：咦，不对。派蒙不是宠物！\", \"voicelineId\": 1045, \"voicelineType\": \"20001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于大海的声音…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_oceanVoice_hero\", \"description\": \"派蒙：据说把耳朵凑近星螺，就能听到大海的悄悄话哦！\\n{NICKNAME}：派蒙想要试一试吗？\\n派蒙：不用啦！我刚刚听过了！\\n{NICKNAME}：哦？那大海悄悄说了些什么？\\n派蒙：大海说，现在到用餐时间啦——快走吧，我想吃「渔人吐司」！\", \"voicelineId\": 1046, \"voicelineType\": \"44001\", \"unlockConditions\": [{\"paramList\": [3, 114], \"unlockText\": \"解锁「璃月 瑶光滩」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于猜拳…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fingerGuessing_hero\", \"description\": \"派蒙：想马上就能吃到好吃的！但，又不想跑腿…\\n{NICKNAME}：要用猜拳来决定谁去买吗？\\n派蒙：好呀好呀！\\n{NICKNAME}：那么，石头剪刀布——\\n派蒙：「超级派蒙旋风」！\\n{NICKNAME}：…欸？\", \"voicelineId\": 1047, \"voicelineType\": \"45001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于放松方式…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_relax_hero\", \"description\": \"派蒙：最近好累啊，有什么推荐的放松方式吗？\\n{NICKNAME}：睡觉？\\n派蒙：睡觉好无聊，换一个。\\n{NICKNAME}：看书？\\n派蒙：脑袋会晕晕的，换一个。\\n{NICKNAME}：跟好朋友聊天？\\n派蒙：…唔。\\n派蒙：但我们却在讨论需要思考的话题呢。\\n派蒙：不思考的话，反而会变得更放松。\\n{NICKNAME}：未来提瓦特哲学史上著名的「派蒙悖论」，在这个时刻被提出了。\", \"voicelineId\": 1048, \"voicelineType\": \"46001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于饮食差异…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_foodCulture_hero\", \"description\": \"{NICKNAME}：璃月的菜肴跟蒙德的差异很大呢。\\n{NICKNAME}：比如辣味的炒菜，在蒙德就几乎见不到。\\n派蒙：这就是人们常说的，「一方水土养一方人」吧！\\n派蒙：呃…但是为什么全提瓦特的史莱姆都是一个味道的？\\n{NICKNAME}：那是因为你只会同一种烹饪方式吧…\", \"voicelineId\": 1049, \"voicelineType\": \"48001\", \"unlockConditions\": [{\"paramList\": [3, 128], \"unlockText\": \"解锁「璃月 璃月港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于藏钱…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_weaselThief_hero\", \"description\": \"派蒙：「盗宝鼬」的背包里，真的藏着好多摩拉啊！\\n{NICKNAME}：嗯，鼬鼠这种小动物，天生就喜欢收集亮晶晶的东西吧。\\n派蒙：听说最初的「盗宝鼬」的来历，和「盗宝团」有关…\\n派蒙：对了，说到收集亮晶晶的东西，乌鸦也是这种动物。\\n派蒙：不知道奥兹会不会背着菲谢尔，藏了一箱摩拉呢。\\n{NICKNAME}：这么说的话，派蒙也…\\n{NICKNAME}：不知道派蒙…\\n派蒙：哇，你不要过来。我绝对没有在鞋底里面藏钱！\", \"voicelineId\": 1050, \"voicelineType\": \"49001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于冒险故事…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_adventureStory_hero\", \"description\": \"{NICKNAME}：派蒙，你看过《少女薇拉的忧郁》吗？\\n派蒙：听起来很耳熟呢！\\n{NICKNAME}：那本书还挺受欢迎的，据说作者靠它大赚了一笔…\\n派蒙：欸，我也想赚好多好多摩拉。\\n派蒙：嗯...决定了！我也要去写冒险故事！\\n{NICKNAME}：小派蒙的冒险故事？\\n派蒙：对！英勇的旅行者打败了魔龙，拯救了世界…\\n派蒙：然后和他可靠的同伴一起吃了十份蜜酱胡萝卜煎肉的故事！\\n{NICKNAME}：十份？\\n派蒙：嗯！结局要十全十美，大家才会来看嘛！\\n派蒙：就这么愉快地决定了！书名就叫做《少女派蒙的快乐》。\\n{NICKNAME}：呃？\", \"voicelineId\": 1051, \"voicelineType\": \"39001\", \"unlockConditions\": [{\"paramList\": [39604], \"unlockText\": \"完成「巨龙与自由之歌」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于噩梦…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nightmare_hero\", \"description\": \"派蒙：{NICKNAME}，你做过什么超恐怖级别的噩梦吗？\\n{NICKNAME}：唔，我梦见过自己在无边的黑暗中坠落…\\n{NICKNAME}：没带风之翼。\\n派蒙：哇…\\n{NICKNAME}：还梦见过妹妹头也不回地往前走，我怎么追赶都抓不住她。\\n{NICKNAME}：…她说我「来得太晚了」。\\n派蒙：唔…\\n派蒙：跟我的情况不太一样呢。\\n派蒙：我梦见过最恐怖的事情，是被超巨大的史莱姆吞进肚子里。\", \"voicelineId\": 1052, \"voicelineType\": \"50001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「仙灵」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_seelie_hero\", \"description\": \"{NICKNAME}：那些追逐着宝藏的「仙灵」，是从哪里来的呢？\\n派蒙：说不定是从地里长出来的吧，或者是从树上掉下来的？\\n派蒙：虽然不明白来源，但有「仙灵」就有好东西！\\n{NICKNAME}：可是…为什么它们自己，在接触到宝藏的时候，却有一种悲伤的气氛呢？\\n派蒙：嗯？\\n{NICKNAME}：没什么，可能是我的错觉吧。\\n派蒙：唔…你要是不想要宝箱的话，就都拿来给派蒙保管吧！不收保管费！\", \"voicelineId\": 1053, \"voicelineType\": \"51001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于印象最深刻的人…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_impressivePerson_hero\", \"description\": \"派蒙：在最近的旅行里，你有没有什么留下深刻印象的人呢？\\n派蒙：我的话，应该是莎拉吧。\\n{NICKNAME}：提米。\\n派蒙：欸！为什么？\\n{NICKNAME}：最近每次吃甜甜花酿鸡，都会想到他的脸…肉也变得难吃了。\", \"voicelineId\": 1054, \"voicelineType\": \"54001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于语言…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_language_hero\", \"description\": \"派蒙：你学新东西真的很快啊。\\n派蒙：居然在这么短的时间里，就掌握了提瓦特的语言。\\n{NICKNAME}：是派蒙教得好。\\n派蒙：欸嘿嘿…\\n{NICKNAME}：以后，起难听绰号的水平…说不定也会上升吧。\", \"voicelineId\": 1055, \"voicelineType\": \"21001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于派蒙的物种…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_species_hero\", \"description\": \"{NICKNAME}：你感觉什么样的怪物让你印象深刻呢？\\n派蒙：怪物吗…嗯…遗迹守卫？\\n{NICKNAME}：遗迹守卫算是怪物吗？应该属于「机关」之类的吧…\\n派蒙：我觉得那种会给人造成麻烦、需要被打败的都算是「怪物」哦？\\n派蒙：就像打猎可以打到的都算是「猎物」。\\n{NICKNAME}：原来如此…这么讲的话，我终于可以界定派蒙的物种类型了。\\n派蒙：欸？是什么呢？\\n{NICKNAME}：派蒙属于可以钓上来的…所以是「鱼类」。\\n派蒙：嗯？\\n\", \"voicelineId\": 1056, \"voicelineType\": \"18001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于收起武器的方法…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_weapon_hero\", \"description\": \"派蒙：喂，你能再表演一下那个吗？就是那个！\\n{NICKNAME}：哪个？\\n派蒙：就是…「唰」地一下把武器变没，然后又忽然出现在背后！\\n{NICKNAME}：那个呀…你应该见过很多次了吧？\\n派蒙：但我还是没弄明白原理，你能解释一下吗？\\n{NICKNAME}：那不如你先解释一下，你刚才是怎么突然出现在我面前，有时又突然消失的呢？\\n派蒙：唔…这…好像派蒙天生就会了，不知道该怎么解释…\\n{NICKNAME}：嗯，收起武器的技巧其实也是一个道理吧。\\n{NICKNAME}：这就是友情的证明吧。\", \"voicelineId\": 1057, \"voicelineType\": \"22001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宝箱…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_chest_hero\", \"description\": \"派蒙：{NICKNAME}，你对「宝箱」这种东西怎么看？\\n{NICKNAME}：我会相信…那些都是曾经的伟大旅行者留下的痕迹。\\n{NICKNAME}：每次我打开箱子，看到里面的一切，都能与前人感同身受…\\n派蒙：冒险经验增加了！\", \"voicelineId\": 1058, \"voicelineType\": \"23001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于眼睛…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_eyes_hero\", \"description\": \"派蒙：看我的眼睛！\\n{NICKNAME}：怎么了？\\n派蒙：听凯亚说，人的眼睛会出卖自己。\\n派蒙：他只看眼睛就知道，那人说的是不是真话。\\n{NICKNAME}：嗯…\\n派蒙：我喜欢渔人吐司！\\n{NICKNAME}：应该是真话。因为你只要是吃的，好像什么都喜欢。\\n派蒙：嘿嘿。\\n{NICKNAME}：说起来，上一个见过的，眼神充满热情的是——\\n派蒙：是？\\n{NICKNAME}：遗迹守卫。让人很想戳下去…\", \"voicelineId\": 1059, \"voicelineType\": \"55001\", \"unlockConditions\": [{\"paramList\": [46308], \"unlockText\": \"完成「海盗秘宝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于模仿其他人…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_imitate_hero\", \"description\": \"派蒙：唔…好无聊…整个人都没有精神了…\\n{NICKNAME}：反正闲着也是闲着，我们来模仿骑士团的其他人吧？\\n派蒙：欸…？会不会很没礼貌？\\n{NICKNAME}：哈哈，果真不错。连骑士「谦卑有礼」的品德都掌握了呢。\\n派蒙：喂——这就已经开始了吗！\", \"voicelineId\": 1060, \"voicelineType\": \"65001\", \"unlockConditions\": [{\"paramList\": [46308], \"unlockText\": \"完成「海盗秘宝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于幸运抽奖…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_lottery_hero\", \"description\": \"派蒙：咕咕咕…\\n{NICKNAME}：嗯？有鸽子吗？\\n派蒙：不对啦，是我饿了。\\n派蒙：嗯…现在我要抽一位旅行者，来为我做一份蜜酱胡萝卜煎肉。\\n派蒙：到底是哪位旅行者这么幸运呢？\", \"voicelineId\": 1061, \"voicelineType\": \"42001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于眼狩令…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_visionHuntDecree_hero\", \"description\": \"派蒙：说到稻妻最近发生的大事，果然还是眼狩令吧。\\n派蒙：不过你没有神之眼，所以不用担心会被收走。\\n派蒙：但反过来，如果被天领奉行抓住，{NICKNAME}，你也没办法交出神之眼来保命…\\n{NICKNAME}：我可以跟他们说，派蒙就是我的神之眼哦。\\n派蒙：派蒙还真是方便的道具…才不对吧！\\n{NICKNAME}：放心吧，不会交出派蒙的。\\n派蒙：这样还差不多。\\n{NICKNAME}：然后我和派蒙大概会一起坐牢，一起被下令处死…\\n派蒙：唔…如、如果真的这样的话，还是把我交出去吧…\\n派蒙：…等等，从一开始不要被抓住不就好了吗！\", \"voicelineId\": 1090, \"voicelineType\": \"71001\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于反抗军…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_rebels_hero\", \"description\": \"派蒙：只有拥有反抗的意志，才能加入反抗军！\\n派蒙：这么说来，我也是合格的反抗军士兵呢！\\n{NICKNAME}：派蒙也有反抗的意志吗？\\n派蒙：我可是一直在全心全力地反抗被压迫的命运哦！\\n{NICKNAME}：那派蒙应该不能加入反抗军。\\n派蒙：为什么？是因为我们反抗的不是同一件事吗？\\n{NICKNAME}：是因为派蒙的反抗一直没什么用…\\n派蒙：呜呜，好过分！\", \"voicelineId\": 1091, \"voicelineType\": \"71002\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神居岛崩炮…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_tatarasaWeapon_hero\", \"description\": \"派蒙：神居岛崩报、神居岛懵炮、神居鸟崩炮、神居岛喵喵…呸呸呸，好拗口的名字。\\n{NICKNAME}：派蒙在读什么？\\n派蒙：就是这个啦。幕府军为了保护踏鞴砂，在附近修建的超厉害兵器。\\n派蒙：神居岛、崩、炮！\\n{NICKNAME}：看上去很强的样子…不过我们来踏鞴砂的时候，好像并没有见到它运转起来。\\n派蒙：听说因为连反抗军都知道很强，所以正式开战前就通过奇袭的方式把这里打下来了。\\n派蒙：但这个神居…神居大炮需要用特殊炮弹或者雷元素来驱动，反抗军那边也用不了。\\n派蒙：花费这么大力气修建的兵器到底有多厉害呢？真想见识一下…\\n{NICKNAME}：雷元素我倒是也会一点。\\n派蒙：对哦！但是这附近好像也没有合适的炮弹…\\n派蒙：嗯？你看我干什么？喂——\", \"voicelineId\": 1092, \"voicelineType\": \"71003\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于太郎丸…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_taroumaru_hero\", \"description\": \"派蒙：说起来，我们刚到木漏茶室的时候，是真的以为太郎丸会说话呢…\\n{NICKNAME}：派蒙听起来有些失落呀？\\n派蒙：是啊，如果太郎丸会说话的话，总觉得会说出不得了的事情呢！\\n{NICKNAME}：比如？\\n派蒙：比如…「托马，你躲在这里挡到我了汪！」\\n{NICKNAME}：嗯，合情合理。\\n派蒙：再比如…「梢，在我们的契约终结之前，你一生一世不得解脱，汪汪！」\\n{NICKNAME}：梢说自己被神秘契约困在店里打工的事情，派蒙不会真的相信了吧…\\n派蒙：哦哦！还有还有，我想到了，这个不错——\\n派蒙：「看这位名为派蒙的客人机灵可爱，今天的餐费全部免除汪！」\\n{NICKNAME}：这已经是你自己在说话了吧。\\n派蒙：嘿嘿…\", \"voicelineId\": 1093, \"voicelineType\": \"71004\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于五郎…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_gorou_hero\", \"description\": \"派蒙：嗯…\\n{NICKNAME}：派蒙在烦恼什么呢？\\n派蒙：{NICKNAME}，你还记得五郎那毛茸茸的耳朵吗？\\n派蒙：我也好想要那个…或者像甘雨一样，有可爱的角也不错。\\n派蒙：{NICKNAME}，你有什么好办法吗？\\n{NICKNAME}：让我找找…啊，有了。\\n派蒙：真的吗？{NICKNAME}，我就知道你是最可靠的！\\n{NICKNAME}：锵锵~「吞天之鲸·只角」！\\n派蒙：不是要这个啦！\\n派蒙：唉…不过仔细想想，五郎不仅有毛茸茸的耳朵，还有尾巴呢…\\n{NICKNAME}：锵锵~「北风之尾」！\\n派蒙：都说了不需要啦！而且这两个组合起来绝对会很奇怪吧！\", \"voicelineId\": 1094, \"voicelineType\": \"71005\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于小说出版…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_novelPublish_hero\", \"description\": \"派蒙：稻妻有八重堂这种专门出版小说的地方呢！\\n派蒙：甚至还有比赛，真厉害！\\n{NICKNAME}：那么，之前派蒙说要写的《少女派蒙的快乐》刚好可以拿去投稿了。\\n派蒙：呃，那个，手稿在我们来稻妻的时候不小心弄丢了…\\n{NICKNAME}：…真的吗？（盯——）\\n派蒙：好啦，我承认，我还没开始动笔。\\n派蒙：可是这不能怪我嘛！其实我一直想要动笔的，但是大前天我笔断了，前天我手抽筋了，昨天我脚扭了，今天我…唔…今天我肚子饿了！\\n{NICKNAME}：说不定《派蒙的十万个拖稿理由》会比《少女派蒙的快乐》更快完成。\", \"voicelineId\": 1096, \"voicelineType\": \"71007\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_kazuha_hero\", \"description\": \"派蒙：万叶是一个很洒脱的人呢。\\n{NICKNAME}：是的，似乎经常看到他独来独往。\\n派蒙：一个人行走在世间，倾听自然万物的声音，似乎也不错…\\n派蒙：{NICKNAME}，你该不会也想背着我偷偷出去冒险吧？\\n{NICKNAME}：怎么会，我一直都会和小派蒙在一起的哦。\\n派蒙：太好啦。那…嘿嘿，这个给你…\\n{NICKNAME}：「当月饮食开销」…共欠三十万摩拉？！\\n派蒙：喂喂，{NICKNAME}，你要去哪？\\n{NICKNAME}：我突然觉得一个人行走在世间，似乎也不错。\\n派蒙：不要啊！等等我呀——\", \"voicelineId\": 1097, \"voicelineType\": \"71008\", \"unlockConditions\": [{\"paramList\": [200212], \"unlockText\": \"完成「振袖秋风问红叶」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_ayaka_hero\", \"description\": \"派蒙：嗯…嗯…\\n{NICKNAME}：派蒙，今天看起来好严肃啊。\\n派蒙：因为我正在思考很严肃的事情。\\n派蒙：我以前很羡慕大户人家的生活，可以有用不完的摩拉和吃不完的美食…\\n{NICKNAME}：嗯，确实都是你喜欢的东西。\\n派蒙：但是认识了绫华之后，我发现大小姐的生活也很辛苦呢。\\n派蒙：需要背负家族的使命与责任，尽力完成工作，才能在难得的闲暇享受自己的生活。\\n派蒙：绫华平常这么辛苦，应该也要多放松下才好呀…\\n派蒙：对了对了！下次再有祭典活动的话，我们也邀请绫华一起去吧？\\n派蒙：我们去邀请的话，绫华应该不会拒绝的吧，嘿嘿。\\n{NICKNAME}：嗯，我也很想再和她去一次祭典。\\n派蒙：而且，只要绫华在的话，那我们游玩的全部费用就都…\\n{NICKNAME}：…这才是你真正的目的吧…\", \"voicelineId\": 1098, \"voicelineType\": \"71009\", \"unlockConditions\": [{\"paramList\": [1200804], \"unlockText\": \"完成「鹤与白兔的诉说」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于模仿绫华…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_imitateAyaka_hero\", \"description\": \"派蒙：绫华小姐举手投足都散发着高贵的气息呢。\\n{NICKNAME}：突然想看派蒙模仿绫华。\\n派蒙：欸，我试试。\\n派蒙：「哦，原来你这么用心的采蘑菇，是为了给我做野菇鸡肉串啊。」\\n派蒙：「真是可爱呢。」\\n{NICKNAME}：完全不是绫华啊。不过，总感觉…\\n{NICKNAME}：这种明明不是派蒙却又觉得似乎理应如此的感觉是…\", \"voicelineId\": 1099, \"voicelineType\": \"71010\", \"unlockConditions\": [{\"paramList\": [1200804], \"unlockText\": \"完成「鹤与白兔的诉说」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于祭典的传统…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fiestaTradition_hero\", \"description\": \"派蒙：说起来，在稻妻的祭典上，大家都有佩戴面具的传统呢。\\n派蒙：可是找遍所有的摊位，都没有适合我戴的尺寸…\\n{NICKNAME}：派蒙很想要自己的面具吗？\\n派蒙：当然啦！总觉得在祭典的氛围里，如果没戴面具，就好像在风花节上没收到花束一样…\\n{NICKNAME}：那我来给你做一个吧。\\n派蒙：哇——{NICKNAME}，你是最好的人！\\n{NICKNAME}：嗯，面具的样式就定为…派蒙最喜欢的史莱姆吧。\\n派蒙：好耶，史莱姆派蒙！\", \"voicelineId\": 1100, \"voicelineType\": \"71011\", \"unlockConditions\": [{\"paramList\": [1200804], \"unlockText\": \"完成「鹤与白兔的诉说」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_yoimiya_hero\", \"description\": \"派蒙：你说，宵宫老爹的听力不好，是不是跟烟花有关啊？\\n派蒙：由于常年制作、试放烟花，每日被火药炸响的声音包围，导致听力变弱…\\n派蒙：呜哇！那宵宫继承家业，最后会不会也变得像她老爹那样，听不清人讲话…\\n派蒙：不可以不可以，为了避免这种事情发生，要赶快想想办法！\\n{NICKNAME}：派蒙有什么建议吗？\\n派蒙：唔…嗯…\\n派蒙：如果我飞在宵宫后边，一直用手捂住她的耳朵…\\n{NICKNAME}：那派蒙就不能跟着我了。\\n派蒙：…没有我的话，你就没有向导了。要我离开你是不可能的！\\n派蒙：可是宵宫…该怎么办才好…\\n{NICKNAME}：其实，在制作烟火的时候带上耳塞就可以了。\\n派蒙：对哦，还有这种方法！你真聪明！\\n{NICKNAME}：嘿…看派蒙这么困扰，我反而有些开心呢。\\n派蒙：欸？其实你早就想好了办法，却不告诉派蒙吗！\\n派蒙：怎么这样，你这坏家伙！\", \"voicelineId\": 1101, \"voicelineType\": \"71012\", \"unlockConditions\": [{\"paramList\": [1201309], \"unlockText\": \"完成「如梦如电的隽永」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于早柚的烦恼…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_sayuAnnoy_hero\", \"description\": \"派蒙：小早柚似乎有很多烦恼呢。\\n派蒙：真是难以理解。\\n{NICKNAME}：这大概就是成长的烦恼吧。\\n派蒙：唔，你这句话也很难理解。\\n派蒙：毕竟派蒙是没什么烦恼的。\\n{NICKNAME}：嗯…\\n{NICKNAME}：糟了，背包里没几个摩拉了，接下来我们要过穷日子了…\\n派蒙：欸？不要啊——\\n{NICKNAME}：现在你有烦恼了。\\n派蒙：怎么会这样…\", \"voicelineId\": 1102, \"voicelineType\": \"71013\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鬼兜虫…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_oniHornedBeetle_hero\", \"description\": \"派蒙：呀，这些鬼兜虫看起来好厉害，背纹好可怕！\\n{NICKNAME}：你说那些恶鬼样式的背纹吗？因为它们不喜欢争斗，所以才进化出了这种鬼怪的图形，用来恫吓敌人。\\n派蒙：真是智慧呀，我们是不是也可以学习学习！\\n派蒙：不如把魈的面具借过来怎么样？这样丘丘人看见你会被吓呆吧？\\n{NICKNAME}：呃…魈恐怕不会同意吧…\\n派蒙：也是哦…那要不我们——拜托早柚去偷？！\\n派蒙：她不是会倏的一下就消失的忍术吗！一定能偷到！真好啊！\\n派蒙：唔…如果怕魈事后算账的话，不如去偷「公子」的吧！反正你也打得过他。\\n{NICKNAME}：偷东西不太好吧，而且万一早柚不同意呢？\\n派蒙：那、那我们就先去找…先去找阿贝多！\\n派蒙：要是阿贝多能研究出让早柚长高高的药剂，早柚一定愿意帮忙！\\n{NICKNAME}：那么就该想想怎么让阿贝多帮忙了？\\n派蒙：呜哇！头开始痛了，我们还是去祭典上买一个吧。\", \"voicelineId\": 1103, \"voicelineType\": \"71014\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鸣草…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_peelGrass_hero\", \"description\": \"派蒙：你知道吗？鸣草上长得像花的结构，其实是叶片呢。\\n派蒙：不起眼的叶片也在努力成长，保护着脆弱的花…\\n派蒙：嘿嘿，就像我也在保护着旅行者一样呢。\\n{NICKNAME}：但我记得鸣草的叶片是不能吃的。\\n派蒙：是啊是啊…等等？你在暗示什么？\", \"voicelineId\": 1104, \"voicelineType\": \"71015\", \"unlockConditions\": [{\"paramList\": [3, 235], \"unlockText\": \"解锁「稻妻 踏鞴砂」七天神像-雷\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鸣草与雷电…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_peelGrassAndThunder_hero\", \"description\": \"派蒙：你知道吗？鸣草的振动，经常被稻妻的居民用来预报雷雨。\\n派蒙：因为鸣草通常在雷元素富集的区域生长，天生对雷电有着极强的感应能力。\\n{NICKNAME}：这么说来，鸣草和派蒙很像呢。\\n派蒙：欸？哪里像啦？\\n{NICKNAME}：因为派蒙通常在美食密集的区域出没，天生对好吃的食物有着极强的感应能力！\\n派蒙：嘿嘿，这倒是事实！\\n{NICKNAME}：那么，派蒙搜索雷达，启动…\\n派蒙：嘟嘟，嘀嘀嘀，为了好吃的，冲呀！\", \"voicelineId\": 1105, \"voicelineType\": \"71016\", \"unlockConditions\": [{\"paramList\": [3, 235], \"unlockText\": \"解锁「稻妻 踏鞴砂」七天神像-雷\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绯樱绣球…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_sakuraTemari_hero\", \"description\": \"派蒙：从神樱树上飘下来的绯樱绣球，真好看呀。\\n派蒙：听说花瓣因为雷元素的力量，可以长时间悬浮在空中。\\n{NICKNAME}：派蒙可以飞在空中，也是利用这种原理吗？\\n派蒙：哎…这个…是因为…\\n{NICKNAME}：难道派蒙也不知道自己为什么会飞吗？\\n派蒙：派蒙会飞，当然是…是因为神秘的力量啦！\\n{NICKNAME}：明白了，你什么都不知道。\\n{NICKNAME}：既然如此，应该拿给神奇的阿贝多去研究一下…\\n派蒙：不要哇！\", \"voicelineId\": 1106, \"voicelineType\": \"71017\", \"unlockConditions\": [{\"paramList\": [3, 244], \"unlockText\": \"解锁「稻妻 鸣神大社」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于堇瓜…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_sumireLemon_hero\", \"description\": \"派蒙：堇瓜用处很多呢！\\n派蒙：果肉可以吃，果皮还可以加工成染料。\\n{NICKNAME}：派蒙用处也很多呢！\\n{NICKNAME}：能当我的向导，还会给别人起难听的绰号。\\n派蒙：嗯！谢谢你对我的肯定！\\n派蒙：等等，你该不会是准备抖出最后的包袱了吧？\\n派蒙：那我要捂住你的嘴，不让你说了！\", \"voicelineId\": 1107, \"voicelineType\": \"71018\", \"unlockConditions\": [{\"paramList\": [3, 296], \"unlockText\": \"解锁「稻妻 绀田村」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于佩刀…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_sabre_hero\", \"description\": \"派蒙：{NICKNAME}，你注意到了吗？\\n派蒙：在稻妻，只有少数人的腰间有佩刀，大部分的士兵还是用长枪呢。\\n派蒙：说不定刀其实是一种身份的象征…我要不要也带一把呢？\\n派蒙：不过这里的刀对我来说都太大了…果然还是去找名家定制一把比较好！\\n{NICKNAME}：但是定制刀的话，要花不少钱吧。\\n派蒙：难道摩拉，比可爱同伴的愿望还要重要吗？\\n{NICKNAME}：…其实我早就给派蒙准备好了。\\n派蒙：真的吗真的吗，快给我看看！\\n派蒙：喂，这不是我们用来切水果的刀吗！\\n{NICKNAME}：至少大小上很适合派蒙啦…\\n{NICKNAME}：咳，「重要的不是刀的价值，而是追求武道的心」。\\n派蒙：不要试图用听着很帅的台词糊弄过去！\", \"voicelineId\": 1108, \"voicelineType\": \"71019\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温泉…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_hotSpring_hero\", \"description\": \"派蒙：稻妻城里居然有温泉！\\n{NICKNAME}：但是稻妻没有火山呢。\\n派蒙：嗯，据说是用一个很大的炉子供热的！\\n派蒙：有机会的话，我也想去泡温泉，可惜似乎只有大人物才有资格。\\n{NICKNAME}：嗯…\\n{NICKNAME}：走了，我们回蒙德的达达乌帕谷吧！\\n派蒙：欸？为什么这么突然！\\n{NICKNAME}：达达乌帕谷那边，丘丘人的那口大锅是用烈焰花供热的，四舍五入和温泉也差不多吧。派蒙可以去那里泡…呃…泡汤？\\n派蒙：？？？\", \"voicelineId\": 1109, \"voicelineType\": \"71020\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「寿限无」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_jugemu_hero\", \"description\": \"派蒙：在稻妻传统里，家长常会给小孩子取一个吉祥的名字。\\n{NICKNAME}：这名字自然是饱含了大家的期待，既希望财运亨通，又希望无病无灾。\\n派蒙：所以这孩子的家长，就给孩子取了一个很长很长的名字。里面那可真的是什么好处都有。\\n{NICKNAME}：结果有一天，孩子回家路上掉进了河里，她的同伴立刻就赶回家喊她的父母。「不好啦，不好啦。」\\n派蒙：「怎么啦？」\\n{NICKNAME}：「她掉在水里了！巴波·修立干·古立泰·彭彭克皮·彭彭科纳·菲谢尔·冯·露弗施洛斯·那菲多特·阿斯托洛吉斯·莫娜·梅姬斯图斯掉水里了！！」\\n派蒙：…莫娜掉水里的话，应该不用担心吧。\\n{NICKNAME}：正是如此。等她的小伙伴把话说完，名字长长、游泳快快的莫娜已经站在家门口了。\", \"voicelineId\": 1110, \"voicelineType\": \"71021\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于稻妻的岛屿…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_inazumaIsland_hero\", \"description\": \"派蒙：稻妻的风景，和之前见过的大不相同呢。\\n{NICKNAME}：嗯，是有很多岛屿的海上国度。\\n派蒙：你说，在船被发明出来之前，不同岛屿上的人们是如何交流的呢？\\n{NICKNAME}：按照宵宫老爹的说法，应该是用升上空中的烟火来传递讯息的吧。\\n{NICKNAME}：或者，还可以…\\n派蒙：还可以…？\\n{NICKNAME}：还可以委托能够冻结水面的人，在各个岛屿之间往来传信。\\n派蒙：呜哇，那幸亏凯亚不在稻妻，不然会成为比琴团长还劳累的大忙人吧！\", \"voicelineId\": 1111, \"voicelineType\": \"71022\", \"unlockConditions\": [{\"paramList\": [3, 331], \"unlockText\": \"解锁「稻妻 离岛」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于狸猫…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_bakeDanuki_hero\", \"description\": \"派蒙：狸猫真是神奇的生物啊。\\n{NICKNAME}：狸猫真是可爱啊。\\n派蒙：可惜会说人话。\\n{NICKNAME}：如果派蒙不会说人话的话，会不会看起来神秘又高贵呢？\\n派蒙：你这句话，是在损我吗？\\n{NICKNAME}：嗯哼。哼~哼~哼哼哼~，哼哼哼哼哼哼哼~\", \"voicelineId\": 1112, \"voicelineType\": \"71023\", \"unlockConditions\": [{\"paramList\": [3, 298], \"unlockText\": \"解锁「稻妻 镇守之森」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于狸猫与幻术…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_bakeDanukiAndIllusion_hero\", \"description\": \"派蒙：你知不知道稻妻有一种妖怪叫做狸猫，能够变成任何人的模样！\\n{NICKNAME}：确实听过类似的传闻，真是神奇的变幻之术。\\n派蒙：要是它哪天变成我的模样来骗你怎么办？呜哇…好担心！ \\n{NICKNAME}：别担心，我还是有自信能分辨的——哦！我明白了，你在担心我的财产吧？\\n派蒙：就是啊…啊啊——才、才、才没有！我当然是担心{NICKNAME}你的安危！\\n派蒙：哼，不要那样看我啦——快先想想办法！要是有两个派蒙，要怎么找出真的那个嘛。\\n{NICKNAME}：…欸嘿。\\n派蒙：欸嘿是什么啦！\\n{NICKNAME}：看吧，会这样吐槽的就是派蒙。\\n派蒙：啊！不自觉就…\", \"voicelineId\": 1113, \"voicelineType\": \"71024\", \"unlockConditions\": [{\"paramList\": [3, 298], \"unlockText\": \"解锁「稻妻 镇守之森」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于其他神龛…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_otherShrine_hero\", \"description\": \"派蒙：最近看见了好多小小的神龛，感觉不像是用来供奉雷神的呢。\\n{NICKNAME}：大概是民间的一些神灵吧？稻妻的人们相信万物有灵，会在各种意外的时刻帮助人们。\\n派蒙：哦——所以就会为它们修建神龛，奉上贡品。\\n{NICKNAME}：嗯，也算是一种祈祷和感谢。\\n派蒙：我明白了！那我去找绫华小姐，请她为我们修建一座神龛吧！\\n派蒙：然后就可以收获许多免费的贡品了！\\n派蒙：真高兴！\\n{NICKNAME}：欸？这、这样也可以吗？\\n派蒙：怎么了？我们不是也在一直帮助大家吗？做的说不定比神灵还要好呢！\\n{NICKNAME}：说得也是…\\n{NICKNAME}：但一想到人们带着花和果子放在我的神龛前面，就觉得有什么地方不太对劲…\", \"voicelineId\": 1114, \"voicelineType\": \"71025\", \"unlockConditions\": [{\"paramList\": [3, 245], \"unlockText\": \"解锁「稻妻 荒海」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八酝岛的雨…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_yashioriIslandsRain_hero\", \"description\": \"{NICKNAME}：八酝岛的大雨下个不停，据说是「祟神」的气息导致的。\\n派蒙：「祟神」？那是什么？听起来很厉害。\\n{NICKNAME}：就是魔神残渣，也就是魔神的遗骸，因为力量没有完全消散，还会导致各种坏事，所以又被叫做「祟神」。\\n派蒙：原来是这样，可是下雨也算不上什么坏事吧。\\n派蒙：反而感觉它更像是被欺负了，在伤心地哭个不停呢。\\n{NICKNAME}：哭吗？神不会哭的吧，你看温迪、钟离他们就从来不哭。\\n派蒙：也有例外！你快捏我一下，就可以看到哭泣的神了。\\n{NICKNAME}：嗯？原来你也是神吗？\\n派蒙：我是，我是的！\\n{NICKNAME}：好嘛，让我猜猜，你是飞行笨蛋之神？史莱姆之神？还是水中上钩之神？\\n派蒙：什么乱七八糟的神呀，哼！\\n派蒙：我是守护神哦！是{NICKNAME}的守护神。\", \"voicelineId\": 1115, \"voicelineType\": \"71026\", \"unlockConditions\": [{\"paramList\": [3, 258], \"unlockText\": \"解锁「稻妻 名椎滩」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于万端珊瑚侦探社…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_bantanNoSangoDetectiveAgency_hero\", \"description\": \"{NICKNAME}：说起来，在花见坂有一家「万端珊瑚侦探社」呢。\\n派蒙：我有印象，是珊瑚和龙二经营的那家吧？大家对他们的评价很不错哦。\\n{NICKNAME}：唔，不过我听说他们经常会碰上奇怪的事件，有些地方都禁止他们入内了…\\n派蒙：我觉得这样做不太好吧，毕竟珊瑚和龙二帮了大家很多忙呢…\\n{NICKNAME}：那派蒙吃饭会请他们来吗？\\n{NICKNAME}：然后吃到一半，突然发现邻桌的客人惨叫一声、倒在了地上…\\n派蒙：那、那还是别了吧，突然感觉和他们一起行动好危险啊…\\n{NICKNAME}：所以说这就是名侦探的不便之处吧。\", \"voicelineId\": 1116, \"voicelineType\": \"71027\", \"unlockConditions\": [{\"paramList\": [3, 242], \"unlockText\": \"解锁「稻妻 町街」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于求签…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_kauChim_hero\", \"description\": \"派蒙：对了，{NICKNAME}，你有去过神社求签吗？\\n派蒙：做事之前先去求个签，说不定能得到一些启示哦。\\n{NICKNAME}：唔，但有可能会抽到「凶」或者「大凶」一类的吧？感觉会影响心情…\\n派蒙：没关系的，听神社的巫女说，要是抽到了不好的签，挂到神社的御签挂上就可以啦…\\n派蒙：所以只要一直抽一直抽，直到抽中「大吉」为止就好啦！其他的全挂到御签挂上！\\n{NICKNAME}：如果大家都像你这样做，御签挂会挂不下吧…\", \"voicelineId\": 1117, \"voicelineType\": \"71028\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「无想的一刀」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_musouNoHitotachi_hero\", \"description\": \"派蒙：「无想的一刀」好厉害！\\n派蒙：不管遇到什么敌人只要来一刀就行了吧！\\n{NICKNAME}：嗯…但是「公子」的话，可能要三刀…\\n派蒙：对、对哦！\\n派蒙：总之，如果你学会了的话，接下来的旅途我就再也不用担心你了！\\n{NICKNAME}：那么，要去哪里才能学到呢？\\n派蒙：那么，要去哪里才能学到呢？\\n{NICKNAME}：嗯？\\n派蒙：不要这么看着我嘛！好、好嘛，接下来的旅途我也会多多关照你的…\", \"voicelineId\": 1118, \"voicelineType\": \"71029\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珊瑚宫心海…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_kokomi_hero\", \"description\": \"派蒙：{NICKNAME}，你知道吗？那位珊瑚宫心海，可是海祇岛的「现人神巫女」呢。\\n派蒙：也就是海祇岛的最高领袖！整个海祇岛都归她管哦。\\n派蒙：啊，派蒙也想成为那样的大人物…\\n{NICKNAME}：成为大人物之后呢？\\n派蒙：之后就可以伸张正义了呀。比如说…咳咳。\\n派蒙：嫌犯{NICKNAME}中午吃三彩团子的时候，自己吃掉了两个，只分给了受害人派蒙一个，严重违反了「派蒙法令」第三十七条——「公平公正」！\\n{NICKNAME}：那请问派蒙大人打算如何处理此事？\\n派蒙：当然是罚你给派蒙做好多三彩团子啦，嘿嘿！\", \"voicelineId\": 1119, \"voicelineType\": \"71030\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「无常」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_anitya_hero\", \"description\": \"派蒙：不知道前代将军是个什么样的人呢。\\n{NICKNAME}：似乎是一个能理解花不常开的人呢，并且她也能坦然接受自己终有一日会离开的命运。\\n派蒙：知道眼前之物的宝贵，才能更加珍惜啊。\\n{NICKNAME}：这个可能也影响了稻妻的美学吧。浮世之景里，众生流淌而过。度过的热闹时光、一起结伴而行的人、一起品尝过的美味，这些是真实不虚的，是真正重要的事物。\\n派蒙：虽然…虽然宴席肯定会结束，但快乐的时间能更长一点就好了。\\n{NICKNAME}：「白露与清梦，胧幻与此生，若比君侧时，皆算久长事。」\\n派蒙：你在说什么！\\n{NICKNAME}：这是说，和小派蒙的旅行很开心。如果能一直这样下去就好了。\\n派蒙：你不会骗我吧。嘿嘿。\", \"voicelineId\": 1120, \"voicelineType\": \"71031\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于巫女…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_miko_hero\", \"description\": \"派蒙：巫女们的衣服很有特色呀。\\n{NICKNAME}：据说八重神子在思考锁国结束之后，把试穿巫女服作为一项旅游业务在各地布设开来。配合枫丹的新型留影机技术，感觉能大赚一笔。\\n派蒙：哦！\\n{NICKNAME}：{M#大社的巫女上次还问我认不认识好看的女孩子愿意当宣传模特，只用穿着巫女服对留影机笑一笑就好。或者我自己来也行，化一下妆就好。},{F#大社的巫女上次还问我有没有兴趣当宣传模特，只用穿着巫女服对留影机笑一笑就好。或者认不认识其他好看的女孩子。}\\n派蒙：喂！\\n{NICKNAME}：我转手就把这个想法告诉了罗莎莉亚。觉得她们的西风教会修女服也可以这么来一出。\\n派蒙：你等等！\\n{NICKNAME}：唉，罗莎莉亚只是觉得好麻烦。\\n派蒙：还好只是罗莎莉亚…\", \"voicelineId\": 1121, \"voicelineType\": \"71032\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于画家歌麿…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_utamoro_hero\", \"description\": \"派蒙：最近葵送了我一幅画，虽然不能吃，但还是十分高兴！\\n{NICKNAME}：是那个杂货店主吗？我看看。\\n派蒙：喏，小心点，这是名画师歌麿的作品哦，值钱货！\\n{NICKNAME}：歌麿？唔…总觉得在哪见过…\\n派蒙：那当然，毕竟是歌麿大师，名作早就遍布稻妻了吧！\\n派蒙：你是在绫华小姐家看到的吧？我这幅可一点也不差哟。\\n{NICKNAME}：不对，我想起来了！上次宵宫用来做火折子的就是这个吧？\\n派蒙：欸？做火折子？\\n{NICKNAME}：托马好像也拿来垫桌脚过…\\n派蒙：什么？垫桌脚？\\n{NICKNAME}：没记错的话，早柚午睡的时候还找了好几张当做垫子。\\n派蒙：早柚那家伙都有好几张？绝对不可能吧…\\n{NICKNAME}：歌麿这家伙根本不是什么大师吧，真正的名作怎么会到处都是啦。\\n派蒙：欸——\", \"voicelineId\": 1122, \"voicelineType\": \"71033\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于茶室与老板…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_teaHouseBoss_hero\", \"description\": \"派蒙：「木漏茶室」的生意还不错呢，每天都有不少客人来光顾。\\n派蒙：{NICKNAME}，有机会的话我们也开一间茶室吧，感觉会很赚钱！\\n{NICKNAME}：嗯…如果以后我开茶室的话，一定会让派蒙来当店长的。\\n派蒙：欸？好呀！\\n派蒙：没想到你这么信任我的经营能力…我一定会当一个负责的店长，把我们的店做成全提瓦特第一的！\\n{NICKNAME}：经营就不麻烦你了…派蒙，你还记得太郎丸吗？\\n派蒙：记得记得，是茶室的老板嘛，听说有些客人不是来喝茶，而是来找它玩的。\\n{NICKNAME}：所以我在想，如果让派蒙来当店长的话，一定会比太郎丸更受欢迎吧。\\n派蒙：嘿嘿，那当然了…喂，原来你不是信任我的经营能力，只是想让我当吉祥物吗！\", \"voicelineId\": 1123, \"voicelineType\": \"71034\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于锁国…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_sakoku_hero\", \"description\": \"{NICKNAME}：眼狩令结束了，锁国也将不日解除了吧。\\n派蒙：希望一切都能好起来吧。\\n{NICKNAME}：希望就在眼前，要鼓励大家坚持下去啊。\\n派蒙：嗯嗯。\\n{NICKNAME}：找个机会去和竺子说一下吧。「竺子，故乡的樱花开了。」\\n派蒙：嗯…总觉得哪里不对！\", \"voicelineId\": 1124, \"voicelineType\": \"71006\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于着物…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_kimono_hero\", \"description\": \"派蒙：唉，听小仓澪说，高档着物的存货太少，就算有摩拉也很难买到。\\n派蒙：好可惜，派蒙也想穿上那些漂亮衣服。\\n{NICKNAME}：不过，现在锁国令已经解除，「小仓屋」应该能从璃月进口绸缎了。\\n派蒙：太好了，新衣服有希望了！\\n派蒙：想象一下，穿上「小仓屋」私人定制着物的我，一定会大有不同！\\n派蒙：摆脱掉传奇故事中的主角小跟班印象，升格为英雄宿命中的友人。\\n派蒙：哇，感觉好棒。\\n派蒙：{NICKNAME}，你一定也这么觉得吧？所以…\\n{NICKNAME}：说到底就是想要我付账嘛。\\n派蒙：这么快就领悟了，不愧是「宿命中的友人」！\\n派蒙：我想要七件不同的，每天都可以换着穿！花纹的话…我想想…\\n{NICKNAME}：…突然感觉不想买了！\", \"voicelineId\": 1125, \"voicelineType\": \"71035\", \"unlockConditions\": [{\"paramList\": [1204209], \"unlockText\": \"完成「须臾百梦」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于罐装知识…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_cannedKnowledge_hero\", \"description\": \"派蒙：不用读书就能知道好多东西，罐装知识真是太方便了！\\n派蒙：不知道须弥，有没有关于七国风土人情的罐装知识…\\n派蒙：要是有的话，每到一个新的地方，我就替你打开一个新罐头，就不用再多费口舌了！\\n{NICKNAME}：那也不用去新的地方，在须弥就能全都打开了吧。\\n派蒙：这、这是为了保持旅程的期待感嘛！\\n{NICKNAME}：而且这么一来，也不用派蒙来当向导了…\\n派蒙：不行不行，我们还是把买罐头的摩拉省下来吧！\\n派蒙：省下来…当我的小费！嘿嘿，合情合理。\", \"voicelineId\": 1132, \"voicelineType\": \"71036\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于镀金旅团…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_gildedBrigade_hero\", \"description\": \"派蒙：镀金旅团内部还真是鱼龙混杂呢…\\n{NICKNAME}：这就是所谓的多样性吧。\\n派蒙：喔——我能理解你在说什么呢！因为派蒙自己也有很多样子。\\n派蒙：有犀利评论的样子，有博学可靠的样子，还有乐于助人的样子…\\n{NICKNAME}：明明是完全没有理解的样子…\", \"voicelineId\": 1133, \"voicelineType\": \"71037\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于信仰…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_faith_hero\", \"description\": \"派蒙：你发现了吗？须弥人看上去不是很相信小草神的样子。\\n派蒙：之前不管是在璃月还是稻妻，大家明明都很相信岩王帝君和将军大人的。\\n派蒙：那些奇奇怪怪的学者先不提，就算是住在下面的居民，每天也只是把「树王大人」挂在嘴边。\\n{NICKNAME}：嗯，就连好吃的蘑菇也说是树王的恩惠呢。\\n派蒙：这样说来，我们在璃月的时候，也有很多美食，据说得到过岩王帝君的认可和指点呢！\\n派蒙：我知道了！只要能带来好吃的东西，人们就会喜欢那样的神明。\\n{NICKNAME}：应该只有派蒙才会这样吧。\\n派蒙：欸？那{NICKNAME}会相信什么呢？\\n{NICKNAME}：我的话，当然是相信派蒙咯。\\n派蒙：嘿嘿，这个你不用说我也知道啦！\", \"voicelineId\": 1134, \"voicelineType\": \"71038\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于防沙壁…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_sandPreventWall_hero\", \"description\": \"派蒙：防沙壁，第一次看到的时候真是吓了一大跳，根本看不到尽头…\\n{NICKNAME}：毕竟在当时是为了保护整片雨林而建立的。\\n派蒙：而且，真的很高很高。\\n派蒙：真不知道{NICKNAME}能不能爬上去呢。\\n{NICKNAME}：应该不行吧，为什么我非要爬那个不可？\\n派蒙：欸，可是因为防沙壁就在那里。\\n{NICKNAME}：不，就算你这么说…\\n派蒙：防沙壁就在那里呢！\\n{NICKNAME}：好了好了，但再怎么说防沙壁也太…\\n派蒙：可是防沙壁…\\n{NICKNAME}：知道了！我现在就去！\", \"voicelineId\": 1135, \"voicelineType\": \"71039\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于虚空终端…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_voidTerminal_hero\", \"description\": \"派蒙：须弥的学者们好像都会戴着虚空终端，从虚空中获得知识。\\n派蒙：感觉像是随身带着一本活着的百科全书一样，有点羡慕。\\n{NICKNAME}：一点也不羡慕，我也随身带着一本更高级的百科全书，不仅会自动跟随，还会说话。\\n派蒙：欸？是在夸我吗？哎呀，有点不好意思。其实我也没有知道很多啦，最多就是九十九科全书。\\n{NICKNAME}：如果这本九十九科全书不吃东西就更好了。\\n派蒙：喂——\", \"voicelineId\": 1136, \"voicelineType\": \"71040\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于兰那罗用的称呼…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_aranaraName_hero\", \"description\": \"派蒙：兰罗摩，兰拉娜，兰拉迦，兰加惟…唔，兰那罗的名字还真是难记…\\n派蒙：唯一能确定的就是名字最开始一定是个兰字！\\n{NICKNAME}：如果派蒙是兰那罗的话，派蒙的名字就会变成兰派蒙呢。\\n派蒙：是呢，如果是{NICKNAME}…\\n派蒙：这么说来，如果是称呼你的话，他们都会叫那菈{NICKNAME}呢…\\n{NICKNAME}：那菈就是他们对我们的称呼吧…\\n派蒙：那如果有个名字是那菈的家伙，被他们称呼的话会变成什么样？\\n{NICKNAME}：那菈那菈…吧，感觉有点可爱。\\n派蒙：嘿嘿，确实呢。\", \"voicelineId\": 1137, \"voicelineType\": \"71041\", \"unlockConditions\": [{\"paramList\": [7303208], \"unlockText\": \"完成「？？？」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于兰那罗的料理…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_aranaraFood_hero\", \"description\": \"派蒙：不知道为什么，兰那罗的料理味道都…该怎么说好呢，都过于纯粹了。\\n派蒙：感觉和平时吃到的很不一样呢。\\n{NICKNAME}：嗯，但是食材都是相当好的食材…\\n派蒙：是啊是啊，蘑菇也好，水果也好，吃着吃着都感觉要在嘴里重新生长了一样！\\n{NICKNAME}：虽然有点夸张了，不过确实，好的食材或许也不用复杂的烹饪方式。\\n派蒙：说的也是，如果食材本身足够好，简单的烹饪方式也能获得极致的美味！\\n{NICKNAME}：就像派蒙，只要…\\n派蒙：喂！我们的冒险旅途都已经到须弥了，你怎么还在开这样过时的玩笑啦！\", \"voicelineId\": 1138, \"voicelineType\": \"71042\", \"unlockConditions\": [{\"paramList\": [7303208], \"unlockText\": \"完成「？？？」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于多莉的镇灵…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_dorisGenie_hero\", \"description\": \"派蒙：这么大的精灵，是怎么进到灯里的呢？\\n{NICKNAME}：派蒙也可以进去试试。\\n派蒙：——进不去，怎么想都进不去吧！\\n{NICKNAME}：那用尘歌壶试试？\\n派蒙：哦哦，原来还有这种方法，快让我试试！\\n{NICKNAME}：派蒙很有兴致嘛…\\n派蒙：我早就想试试这种展开了——嘿！是你召唤了我吗？异乡的旅行者哟。\\n派蒙：快来实现我的三个愿望吧！第一个是…带我去吃好吃的！\\n{NICKNAME}：为什么是你来许愿啊！\", \"voicelineId\": 1139, \"voicelineType\": \"71043\", \"unlockConditions\": [{\"paramList\": [1100811], \"unlockText\": \"完成「翠石砌玉壶·其一」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于健康之家…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_homeOfHealth_hero\", \"description\": \"派蒙：哇，须弥居然…还能免费看病吗！\\n{NICKNAME}：派蒙有哪里不舒服吗？\\n派蒙：现在还没有，谢谢你的关心。\\n派蒙：不过我从很久以前开始就一直想试试，一边吃冰棍一边吃火锅了！\\n{NICKNAME}：肯定会吃坏肚子吧！\\n派蒙：反正看病是免费的嘛，不看病不会觉得哪里亏了吗？\\n{NICKNAME}：嗯…但是换个角度的话，在治病的时候，饮食会被限制哦。\\n派蒙：欸！不能再吃好吃的了吗？\\n{NICKNAME}：还会给派蒙开很苦的药。\\n派蒙：好、好吧！那我再想想…\", \"voicelineId\": 1140, \"voicelineType\": \"71044\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于学者…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_scholar_hero\", \"description\": \"派蒙：须弥城里真的有好多人希望成为学者呢。\\n派蒙：在这种愿望的推动下，他们都学习得好努力…\\n派蒙：不过，我觉得第一位学者的愿望肯定不是「成为学者」吧？\\n派蒙：唔…那第一位学者的愿望，到底会是什么呢…\\n{NICKNAME}：我想，大概就是「快点写完这篇论文」吧。\\n派蒙：欸？一般来说不都是，追求究极的，最最厉害的知识吗？\\n派蒙：在这种求知欲的驱使下，渐渐成为第一位真正意义上的学者…\\n{NICKNAME}：求知的具体方法就是论文啦。\\n派蒙：可是，那个究极的，最最厉害的知识…\\n{NICKNAME}：要证明这件事，也需要论文啦。\\n{NICKNAME}：然后，为了证明你的论文，又要开始写另外一篇论文…\\n派蒙：好、好了啦！我知道了，不要露出这么难过的表情！你又不用写论文！\\n派蒙：你、你没写过吧…\", \"voicelineId\": 1141, \"voicelineType\": \"71045\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于生论派…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_zoologySchools_hero\", \"description\": \"派蒙：我想去拜访生论派的学者们！\\n{NICKNAME}：派蒙怎么突然勤学好问了起来？\\n派蒙：因为我听说生论派的学者们主要研究的内容是自然和生态。\\n派蒙：那么一定有研究各种动物能不能吃、好不好吃的学者吧！\\n派蒙：我觉得帮助这样的学者进行研究，一定会非常有意思。\\n{NICKNAME}：你只是想吃咖喱了吧？\\n派蒙：不，我真的觉得这是一件很有意义的事情。\\n{NICKNAME}：那…这样的学者，一定会先对派蒙是什么物种，有什么行为习惯产生好奇吧。\\n派蒙：我，我突然想起来我们好像有更要紧的事情！\", \"voicelineId\": 1142, \"voicelineType\": \"71046\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于驮兽…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_sumpterBeast_hero\", \"description\": \"派蒙：那些驮兽真可爱，养驮兽的人还会根据特性，给它们专门起名字呢。\\n{NICKNAME}：说不定它们也在给我们取名字，并且用来回应我们呢。\\n派蒙：咦？他们会给我们起什么名字啊？\\n{NICKNAME}：哞——\\n派蒙：谁听得懂啦！\\n{NICKNAME}：大意就是…\\n{NICKNAME}：「白白矮矮香香吵吵事情多多双足兽」。\\n{NICKNAME}：当然啦，这是学名的全称。\\n派蒙：哦，所以呢，那简略的称呼要怎么说？\\n{NICKNAME}：「吵吵双足兽」。\\n派蒙：喂！怎么只留下不好的特点了啊！\", \"voicelineId\": 1143, \"voicelineType\": \"71047\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于第七学派…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_sevenSchools_hero\", \"description\": \"派蒙：须弥有六大学派呢。\\n派蒙：感觉很有趣，派蒙也想要拥有自己的学派！\\n派蒙：有了…就叫做派蒙派吧！\\n{NICKNAME}：那派蒙派代表的智慧是什么？\\n派蒙：唔…是实用生活智慧！\\n{NICKNAME}：所以特色学科是史莱姆的一百种吃法、绝不放过映入眼帘的任何一摩拉、如何给人起难听的绰号…之类的？\\n派蒙：哇，你真了解我！还可以加上「如何成为提瓦特最棒的向导」！\\n派蒙：我觉得非常厉害，我们快去教令院提交学派申请吧！今后{NICKNAME}就是派蒙派大贤者了！\\n{NICKNAME}：我可以拒绝吗…\", \"voicelineId\": 1144, \"voicelineType\": \"71048\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于蕈猪…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_fungiPig_hero\", \"description\": \"派蒙：你知道吗，须弥有各种各样奇特的蕈类。\\n{NICKNAME}：嗯，有意思的是，据说有些林猪离不开蕈类，逐渐就形成了共生关系，于是便被称为蕈猪。\\n派蒙：哇，那和我们很像呢！我也离不开{NICKNAME}。\\n{NICKNAME}：派蒙离不开我，所以我是蕈，派蒙就是…\\n派蒙：猪！ \\n派蒙：欸？喂——\", \"voicelineId\": 1145, \"voicelineType\": \"71049\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于大巴扎…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_grandBazaar_hero\", \"description\": \"派蒙：大巴扎居民们真是多才多艺啊！\\n派蒙：不仅会卖自己做的编织品、好看的瓶瓶罐罐，闻到味道肚子就会饿的香料…\\n派蒙：还个个能歌善舞，好让人羡慕！\\n{NICKNAME}：只要有心，派蒙也可以学哦。\\n派蒙：欸？真的吗？\\n{NICKNAME}：就拿跳舞举例吧，派蒙是有先天优势的。\\n{NICKNAME}：既不会自己绊倒自己，也不会踩到舞伴的脚…\\n派蒙：对哦！我都忘记会飞是那么方便的事了！\\n派蒙：走吧，快点去大巴扎那晃悠晃悠，让大家都来羡慕我！\\n{NICKNAME}：原来你是想去攀比吗？\", \"voicelineId\": 1146, \"voicelineType\": \"71050\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于占卜…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_divination_hero\", \"description\": \"派蒙：说起来，须弥的人似乎很热衷于算命占卜。\\n派蒙：除了学者们才会的占星术之外，普通须弥人用咖啡就能进行占卜！\\n{NICKNAME}：毕竟是智慧的国度，大家的好奇心都很强吧。\\n派蒙：我听他们说，只要根据咖啡喝完之后杯底上的形状，就能知道一个人的命运…\\n派蒙：和爬到塔上面看一晚上星星比起来，要方便多了呢！\\n{NICKNAME}：派蒙也想知道自己的命运吗？\\n派蒙：嗯…不过比起命运，我还是更想知道咖啡好不好喝。\", \"voicelineId\": 1147, \"voicelineType\": \"71051\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「普尔比鲁尼」与「普尔希娜」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_purbiruniAndPursina_hero\", \"description\": \"派蒙：唔…先前听海迪夫和阿妮萨他们提到过，什么「普尔比鲁尼」一门、「普尔希娜」一门的…\\n派蒙：那些…普尔这、普尔那的，都是什么呀？\\n{NICKNAME}：「普尔」是「后嗣」的意思，也是「学徒」的意思…所以这个就是说，他们都是古代大贤者的徒子徒孙。\\n派蒙：原来是这样呀…看他们炫耀来炫耀去的，我还以为是什么值得骄傲的称呼呢。\\n{NICKNAME}：欸…？\\n派蒙：拿我来说吧，有人说我是谁的爸爸或者妈妈，我才会开心！但随便认别人是我的爸爸妈妈…不会很尴尬吗？\\n{NICKNAME}：唔…从没想过这种问题…\", \"voicelineId\": 1148, \"voicelineType\": \"71052\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于留学…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_abroad_hero\", \"description\": \"派蒙：在教令院里不仅能见到须弥当地人，也还能见到来自其他国度的留学生。\\n派蒙：为了学习知识，离开家乡，前往陌生的土地，真是了不起！\\n{NICKNAME}：我们也经常前往陌生的土地。\\n派蒙：对哦，那…我们也真是了不起！\\n{NICKNAME}：可我们并不是为了学习知识才来的。\\n派蒙：唔…总感觉输给那些留学生了。\\n派蒙：不过，我们知道了须弥哪里有好吃的、哪里有可靠的人。这些也算是知识吧？\\n{NICKNAME}：唔，算。并且对于很多人来说是很宝贵的知识。\\n派蒙：所以我们确实很了不起！\", \"voicelineId\": 1149, \"voicelineType\": \"71053\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于圣树…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_sacredTree_hero\", \"description\": \"派蒙：整个须弥城都建在大树上面，感觉很不可思议呢！\\n派蒙：我们之前也见过很多很厉害的树吧。风起地的「老地方」，雪山的「忍冬之树」，还有稻妻的「神樱树」！\\n派蒙：不过说起这棵树，大家好像只是叫它圣树什么的…\\n{NICKNAME}：有时候越重要的东西名字越简单呢。\\n派蒙：是这样吗？不过也对，名字太长的话每天念起来也很麻烦吧。\\n派蒙：反正只要城里的人说起「树底」，都知道是指这棵树的下面，不会走错地方就好啦。\\n派蒙：那句话怎么说的来着，「名字只是代号」？\\n{NICKNAME}：这么说派蒙也是代号咯？\\n派蒙：唔，好像也没错…才不是吧，派蒙就是派蒙！\", \"voicelineId\": 1150, \"voicelineType\": \"71054\", \"unlockConditions\": [{\"paramList\": [3, 4], \"unlockText\": \"解锁「蒙德 风起地」七天神像-风\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [3, 204], \"unlockText\": \"解锁「蒙德 雪葬之都·旧宫」七天神像-风\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于学派关系…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_schoolsRelation_hero\", \"description\": \"派蒙：你说，须弥有那么多不同学派的学者，他们在讨论的时候会不会吵起来？ \\n派蒙：就像是璃月的璃菜月菜之争一样。\\n{NICKNAME}：会吧，学派之间有矛盾再正常不过了。就像是璃月的武侠小说里说的那样：「有人的地方，就有争斗」。\\n派蒙：唔啊，好沉重的台词。不过他们应该不至于像侠客一样决斗吧。\\n{NICKNAME}：也许他们会来一局「七圣召唤」。\\n派蒙：喔，对哦！用智慧决斗。\\n派蒙：我来想象一下：在不能说服对方的情况下，拿出卡牌，坐下来冷静思考，取得胜利。\\n{NICKNAME}：确实很有须弥的风格。\\n派蒙：赢家在胜利后还会说出一句「打得不错！」表达对对手的尊敬，最后双方重归于好。\\n{NICKNAME}：不…这句话只会让矛盾升级。\\n派蒙：欸…为什么？\", \"voicelineId\": 1151, \"voicelineType\": \"71055\", \"unlockConditions\": [{\"paramList\": [3, 128], \"unlockText\": \"解锁「璃月 璃月港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于奥摩斯港…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_portOrmos_hero\", \"description\": \"派蒙：唔，奥摩斯港的氛围与须弥城里完全不一样呢…\\n派蒙：热热闹闹的，还有好多外国人，大家都不用埋头读书忙学业，真好呀。\\n{NICKNAME}：就是因为他们不好好读书，所以才会被那些港务官管教，派蒙可别学他们哦！\\n派蒙：哦…\\n派蒙：不对！你这是什么口气啦！\", \"voicelineId\": 1152, \"voicelineType\": \"71056\", \"unlockConditions\": [{\"paramList\": [3, 501], \"unlockText\": \"解锁「须弥 奥摩斯港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「二十九海洋代伊联盟」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_29thOceanAlliance_hero\", \"description\": \"派蒙：听说奥摩斯港原本是在一个叫「二十九」…唔…什么什么联盟留下的堡垒遗迹。\\n派蒙：哇啊，名字好长！记不得了！总之，须弥的书呆子们都是这么说的呢。\\n{NICKNAME}：是「二十九海洋代伊联盟」。\\n{NICKNAME}：那个呀…据说是由一群桀骜不驯，互不从属的海盗头子组成的海盗团。他们从一开始就彼此争斗劫掠不休，搅得须弥沿海不得安宁…\\n{NICKNAME}：后来终于有一天，他们决定各自公平划分权力，组成一个和平的「联盟」，「联盟」的「盟主」们，就叫做「代伊」…\\n派蒙：哦…所以他们就…不再互相打架，不再互相抢东西了，大家和平共处，有钱一起赚！对吧！\\n{NICKNAME}：……\\n派蒙：对吧…？\\n{NICKNAME}：嗯…至少他们也想这样吧…\\n派蒙：欸…？\\n{NICKNAME}：后来他们拉帮结派，掀起了一场更大的内战，把奥摩斯港的要塞打成了一堆废墟，所有「代伊」全都完蛋啦！\\n派蒙：欸——！\\n{NICKNAME}：就这样，奥摩斯港在前所未有的和平中重新发展了起来，成了现在的样子…\\n派蒙：什么嘛…原来只是一群单纯的坏东西而已…\", \"voicelineId\": 1153, \"voicelineType\": \"71057\", \"unlockConditions\": [{\"paramList\": [3, 501], \"unlockText\": \"解锁「须弥 奥摩斯港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺与七圣召唤…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_cynoAndCard_hero\", \"description\": \"派蒙：话说，赛诺是不是特别喜欢玩那种叫做「七圣召唤」的牌类游戏来着？\\n派蒙：明明是「大风纪官」，却喜欢玩牌，真奇怪啊…\\n{NICKNAME}：看到他的发型之后我就一点也不奇怪了。\\n派蒙：欸？玩牌和发型有什么关系？\\n{NICKNAME}：在打牌的时候，越是夸张的发型就越能吸引住敌人的注意力。\\n{NICKNAME}：「这家伙搞什么啊，这么夸张的发型到底是怎么梳出来的？」\\n{NICKNAME}：让对手的脑子里都被这种想法填满之后，就可以在牌桌对决上占得先机了。\\n派蒙：是这样吗？那我们以后还是别轻易和赛诺打牌了吧…\\n{NICKNAME}：我倒是觉得，我和赛诺打牌会占得优势喔。\\n派蒙：可是你的发型很普通啊，也没有穿奇怪的衣服…\\n{NICKNAME}：但是我有派蒙啊。\\n{NICKNAME}：「这家伙搞什么啊，后面飘着的那个小东西到底是干什么的？」\\n{NICKNAME}：只要派蒙飘在我旁边，赛诺的脑子会被这种想法填满。\\n{NICKNAME}：但我却不会对他的发型惊讶，这样子我就可以轻松抢得先机了。\\n派蒙：你还不如去弄一个特别的发型啦！\", \"voicelineId\": 1154, \"voicelineType\": \"71058\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于须弥的儿歌…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_sumeruNurseryRhyme_hero\", \"description\": \"派蒙：「咖喱~咖喱的香味~就是孩子们回家的信号~♪」\\n{NICKNAME}：「咖喱的香味~♪」\\n派蒙：哇！接得真棒，原来你也一直记得这段旋律呢！\\n{NICKNAME}：派蒙不也唱得很好嘛？\\n派蒙：嘿嘿，那是因为我有一个伟大的计划！\\n派蒙：你听过那个故事吗？从前有一只丘丘狗，当丘丘萨满跳起舞的时候，它就能分到肉吃。后来，它只要一听到舞步声，就会流口水。\\n派蒙：听到咖喱歌的时候，就能吃到咖喱。那我只要把它记熟，哪天想吃一顿美美的咖喱，提前哼一哼就行了。\\n派蒙：喂，你怎么不说话？\\n派蒙：「咖喱~咖喱的香味~就是孩子们回家的信号~♪」\", \"voicelineId\": 1155, \"voicelineType\": \"71059\", \"unlockConditions\": [{\"paramList\": [7303208], \"unlockText\": \"完成「？？？」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于兰那罗绕口令…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_xm_aranaraTongueTwister_hero\", \"description\": \"{NICKNAME}：派蒙有没有觉得「兰那罗」这个名字，还挺难念的？\\n派蒙：嗯？难念吗？是不是你平时说话太少了呀。\\n派蒙：像我天天说话，嘴皮子特别利索，从来不会咬到舌头。\\n{NICKNAME}：那你读一下这个。\\n派蒙：什么嘛，我看看。\\n派蒙：打南边来了个兰拉娜，兰拉娜练着兰迦拉梨。\\n派蒙：打北边来了个那菈拉娜，那菈拉娜捧着帕蒂沙兰。\\n派蒙：捧着帕蒂沙兰的那菈拉娜想带练着兰迦拉梨的兰拉娜去酒馆找兰巴德，练着兰迦拉梨的兰拉娜想带捧着帕蒂沙兰的那菈拉娜去桓那兰那。\\n派蒙：那菈拉娜拗不过兰拉娜，和兰拉娜去桓那兰那见到了叫兰罗摩的兰那罗…\\n派蒙：这，这一定是做梦吧。\\n派蒙：我的眼前…出现了星星…\", \"voicelineId\": 1156, \"voicelineType\": \"71060\", \"unlockConditions\": [{\"paramList\": [7303208], \"unlockText\": \"完成「？？？」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「预言危机」的应对…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_predictCrisis_hero\", \"description\": \"派蒙：我突然想到了一个好办法，来应对枫丹的「预言危机」！\\n{NICKNAME}：派蒙有什么高见？\\n派蒙：枫丹不是有用来挖掘隧道的大型工程发条机关吗，为什么不把那个丢到水下最深的地方挖洞呢？挖一个会漏水的洞出来，上面涨再多也不怕了。\\n{NICKNAME}：听起来好像挺有道理的，但是下面漏掉的水去哪儿了呢？\\n派蒙：哎呀，这个就不用考虑了嘛！你想呀，要是你的钱包破了个洞，就算再仔细认真地考虑摩拉去了哪里，它也绝对不可能鼓起来的。\\n{NICKNAME}：原来你对我存不住钱的原因这么了解哦。\\n派蒙：干嘛…干嘛看着我说这句话呀…你钱包的洞，跟我、跟我又…没关系…是这样吧？\", \"voicelineId\": 1163, \"voicelineType\": \"71061\", \"unlockConditions\": [{\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魔术…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_magic_hero\", \"description\": \"派蒙：林尼的魔术表演真精彩，在解答之前，完全想不到他是怎么做到的！\\n{NICKNAME}：啊，我突然想到了一个魔术。\\n派蒙：欸？你也会魔术？\\n{NICKNAME}：嗯，我会把大大的魔术帽悬浮在空中，还能让它听我的指示飘来飘去。\\n派蒙：哇！真的吗？怎么办到的呀？\\n{NICKNAME}：嘿嘿，因为派蒙在帽子里呀。\\n派蒙：欸？为什么我在…哦！是我让它飘起来的呀！\\n派蒙：嘿嘿，那我也想到了一个魔术！\\n{NICKNAME}：哦？说来听听。\\n派蒙：你往这个帽子里塞好多好吃的，会发现它怎么装都装不满！\\n{NICKNAME}：呃…那盘子怎么办？\\n派蒙：哦对！这帽子还会自己把盘子吐出来，很神奇吧！\", \"voicelineId\": 1164, \"voicelineType\": \"71062\", \"unlockConditions\": [{\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于飞行专利…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_flyingPatent_hero\", \"description\": \"派蒙：枫丹的「巡轨船」好方便！要是没有轨道也能用就好了，去哪儿都不用自己费力气。\\n{NICKNAME}：派蒙不是一直在飞吗？也会觉得累吗？\\n派蒙：飞…飞…对哦！要是能让「巡轨船」飞起来的话，不就不用轨道了吗！嘿嘿，就叫它「飞空船」好了！\\n派蒙：快，我们去申请哪个什么…「专利」！这么天才的点子，可不能让别人抢了先！\\n{NICKNAME}：只想出一个名字可申请不了专利啊，还得有能让船飞起来的方案。\\n派蒙：方案吗？唔…比如说…比如说…在船顶安一个巨大的螺旋桨！ \\n{NICKNAME}：那怎么保证船不会跟着螺旋桨一起转？又怎么控制飞行的方向？\\n派蒙：这个…那个…唉，飞行原来是这么麻烦的事吗？我平时都没注意到…\\n{NICKNAME}：嗯…不过不考虑方向和速度的话，还有一个简单的方案。\\n派蒙：欸？真的吗！\\n{NICKNAME}：找一个足够高的出发点，然后向下加速飞。\\n派蒙：喂！那不就是坠落吗！\", \"voicelineId\": 1165, \"voicelineType\": \"71063\", \"unlockConditions\": [{\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于出版行业的黑暗…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_publishingIndustry_hero\", \"description\": \"派蒙：《蒸汽鸟报》连载的《大侦探赫尔洛克》，最后的合本也会在稻妻八重堂出版吧。\\n{NICKNAME}：似乎是这样没错。\\n派蒙：明明拥有这么厉害的印刷和配送能力，为什么不自己出版呢？\\n{NICKNAME}：哼哼，这就是出版行业的黑暗了。\\n派蒙：一副看穿了一切的嘴脸！那你说说，为什么能联络全大陆的《蒸汽鸟报》不能自己出版小说吧。\\n{NICKNAME}：小说最重要的是——\\n派蒙：最重要的是…？\\n{NICKNAME}：插画！\\n派蒙：给全大陆辛苦写作、想点子的小说家和编辑们道歉啊！\\n{NICKNAME}：八重堂手上可是握有很多优秀插画师的，想轻易挖角这些人恐怕不容易哦。比如白垩老师这样的，除了八重堂根本就没有手段联系上。\\n派蒙：哦哦，这点确实呢。\\n{NICKNAME}：还有就是…\\n派蒙：就是？\\n{NICKNAME}：只有被八重堂出版了，才有可能和《七圣召唤》联动！\\n派蒙：原、原来是这样吗！\\n{NICKNAME}：出版行业最大的黑暗就是——故事不重要，发掘商业价值的能力更重要！\\n派蒙：太黑暗了！\", \"voicelineId\": 1166, \"voicelineType\": \"71064\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于足不出户的侦探…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_detectiveIndoor_hero\", \"description\": \"派蒙：听说枫丹廷有足不出户就能解明真相的侦探。\\n派蒙：这就是所谓的居家办公吧？听起来很轻松呢！\\n派蒙：不过话说回来，不亲自去现场调查，究竟是靠什么推理出真相的呢…啊，我知道了！一定是用占卜吧？\\n{NICKNAME}：那应该叫占卜师而不是侦探吧。\\n派蒙：对、对哦…\\n{NICKNAME}：案件的线索可不会自己长脚还专程到侦探府上拜访。\\n派蒙：也就是说，一定有人帮侦探收集线索…\\n{NICKNAME}：说不定我们在冒险家协会接到的委托里有一部分就是…\\n派蒙：欸？那原本应该给我们的报酬岂不是会被侦探拿走一部分？那可不行！我们现在就去找侦探抗议！\", \"voicelineId\": 1167, \"voicelineType\": \"71065\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫丹科学院的神秘宝藏…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_mysteriousTreasure_hero\", \"description\": \"派蒙：枫丹科学院是研究发条机关和各种能量的学术机构对吧？为什么会有神秘宝藏的传闻…\\n派蒙：如果是什么怪盗的宝藏、海贼的宝藏，倒是比较容易理解啦。\\n派蒙：研究员的宝藏、高阶技官的宝藏…总觉得听起来缺少冲击力…\\n{NICKNAME}：如果有人白天是研究员，晚上是怪盗…这种神秘人物留下的神秘宝藏呢？\\n派蒙：唔…听起来好辛苦的样子…白天也要工作，晚上也要工作，那什么时候才能休息啊？\\n{NICKNAME}：也许这位神秘人物的真实身份是发条机关，这样就不用休息了。\\n派蒙：白天是研究员，晚上是怪盗的神秘发条机关留下的神秘宝藏…听起来真的很神秘呢！\", \"voicelineId\": 1168, \"voicelineType\": \"71066\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于侦探小说的大忌…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_detectiveNovel_hero\", \"description\": \"派蒙：《大侦探赫尔洛克》、《奥西兹小姐事件簿》…枫丹很流行这种侦探、推理小说呢。\\n{NICKNAME}：派蒙能看懂吗？\\n派蒙：你也太看不起我了吧！如果让我来看的话，一定看到一半就猜出来凶手了。\\n{NICKNAME}：千万记得不要剧透别人哦。\\n派蒙：不会干这种事的啦。\\n{NICKNAME}：不过也有一些人，喜欢拿着「不要剧透」的名义打压别人的讨论。其实他们只是自己不想看到讨厌的作品有人气罢了。\\n派蒙：我不怎么看书，倒是不太了解这种情况呢。\\n{NICKNAME}：比如说两个爱好者正在讨论《鬼武道》，这种家伙就会突然插进去说「我第一卷第二章还没有看，不要继续剧透我啦！」\\n派蒙：那不就是根本没怎么看吗！\\n{NICKNAME}：我和你说一个秘密哦，派蒙。\\n派蒙：嗯，怎么突然…\\n{NICKNAME}：其实…\\n派蒙：其实…\\n{NICKNAME}：其实，钟离就是岩王帝君。\\n派蒙：震惊！你居然剧透我——才怪，这不是早就知道了吗！\", \"voicelineId\": 1169, \"voicelineType\": \"71067\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于正当防卫与互殴…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_defenseAndFight_hero\", \"description\": \"{NICKNAME}：在枫丹如果被打了，没有目击者可千万不要随意还手。\\n派蒙：欸，为什么？\\n{NICKNAME}：如果没有证据，很可能最后不会被判正当防卫，而是互殴。\\n派蒙：那会怎么样呢？\\n{NICKNAME}：那样的话，很大概率会最后走入决斗审判的环节。\\n{NICKNAME}：到这一步，就只能亲自下场和对方继续互殴了，或者请决斗代理人进行互殴。\\n派蒙：…还好你很能打。\", \"voicelineId\": 1170, \"voicelineType\": \"71068\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于《蒸汽鸟报》编辑部…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_steambirdEditorial_hero\", \"description\": \"派蒙：啊，昨天发生的事，立刻就出现在了今天的《蒸汽鸟报》上…\\n派蒙：还有昨日深夜发生在城外的事故，这些报道到底是什么时候写的。\\n{NICKNAME}：而且还能在一大早刊印出来。\\n派蒙：哼哼，我知道了，说不定《蒸汽鸟报》内部有一个魔法打印机，各地的记者只要带来报道，它就会把文章「吭哧吭哧」吃进去，然后到了要发印的节点，全部吐出来！\\n派蒙：说不定已经快到打印时间了，还有记者闯进门来，说「等等，我还有一篇报道没有被吃进去」呢。\\n{NICKNAME}：这种画面倒是很容易想象到，不过据我所知可没有这样的打印机。每天能够有报纸正常发刊，都是《蒸汽鸟报》员工的功劳。「哼哧哼哧」地检查错别字，「哗啦哗啦」地把文字内容拼成一个个大方块，「实在不行了，求求了再等五分钟吧」地联系其他人，这就是名为编辑部的魔法。\\n派蒙：真厉害啊，《蒸汽鸟报》的编辑部，用一天时间就能做出这样的一份报纸，他们不会都不用睡觉吧…\", \"voicelineId\": 1171, \"voicelineType\": \"71069\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫丹的小说…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_fontaineNovel_hero\", \"description\": \"派蒙：唔，《发条机关会梦见齿轮正骨师吗？》枫丹也有些标题很长很奇怪的小说呢。\\n派蒙：不过和稻妻的轻小说相比，写法和题材好像都有些不一样。\\n{NICKNAME}：我看看简介，故事讲述因为长期弓身导致背脊疼痛的发条机关，终于不堪重负放弃了绘制报纸插画的工作，四处寻找能够拯救它机械背脊的按摩师…\\n派蒙：听上去还蛮有意思的嘛。\\n{NICKNAME}：可是也太奇怪了，这个发条机关为什么要找按摩师，为什么不直接找那些工程师帮它处理，比如…嗯，枫丹科学院的工程师？\\n派蒙：呃，不过，枫丹科学院的工程师感觉都有些…\\n{NICKNAME}：那倒也是。哎，虽然这个故事是以发条机关为主角，不过一看就知道还是人写的啦。如果真的让发条机关执笔的话，会写出什么样的故事呢？\\n派蒙：我想想…《一觉醒来，变成肉做的人！》\\n{NICKNAME}：噢，派蒙很有想象力嘛。\", \"voicelineId\": 1172, \"voicelineType\": \"71070\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于审判与表演…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_trialAndPerform_hero\", \"description\": \"派蒙：枫丹人经常在欧庇克莱歌剧院进行审判，但是也会在里面进行表演，可是…\\n{NICKNAME}：怎么了，派蒙有什么疑问吗？\\n派蒙：如果有人在欧庇克莱歌剧院表演审判的话会怎么样呢，大家会以为那个审判是真的还是表演的呢？\\n{NICKNAME}：这倒是个好问题，说不定也有扮演被审判者的演员第二天走在街上被人认出来。「这家伙，不是昨天被审判的人吗！」\\n派蒙：对啊对啊，这难道不会造成很大的困扰吗？\\n{NICKNAME}：这个时候就要大声说，「别把演出的内容当真了！」\\n派蒙：但是表演审判的人其实就是想要别人弄混真的审判和表演的审判，真是太过分了。\\n{NICKNAME}：真是太过分了，派蒙，你居然想出了这么糟糕的主意！\\n派蒙：咦，欸，是我吗？\", \"voicelineId\": 1173, \"voicelineType\": \"71071\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫达…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_fonta_hero\", \"description\": \"派蒙：枫达喝起来真的很痛快，你不觉得吗？\\n{NICKNAME}：嗯，一饮而下的话，就会特别神清气爽。\\n派蒙：能给我买一杯吗？我很久以前就想试试那个了！\\n{NICKNAME}：哪个？\\n派蒙：哎呀，等下我表演给你看。\\n派蒙：咕嘟咕嘟咕嘟咕嘟——\\n派蒙：哈啊——\\n派蒙：那些酒鬼干杯的时候总是这个样子，我也想试一次！\\n{NICKNAME}：别像个老头子一样啊…\", \"voicelineId\": 1174, \"voicelineType\": \"71072\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于警卫机关…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_guardMechanism_hero\", \"description\": \"派蒙：警卫机关会执行设定好的任务，也就是说，只要提前输入命令，它们什么都能做。\\n{NICKNAME}：你又有新的想法了？\\n派蒙：是的，我需要「委托处理警卫机关」，「素材采集警卫机关」，「秘境探索警卫机关」…\\n派蒙：再加上「做饭香香警卫机关」，我们就可以迈入全自动冒险时代！\\n{NICKNAME}：可是警卫机关的持有和使用成本很高，再加上后续的维修与养护的费用…\\n{NICKNAME}：我算算，嗯，就连采集每个薄荷的平均成本都会达到六千三百摩拉…\\n派蒙：欸，好贵？！\\n派蒙：…突然感觉我们冒险生活的价值很高呢！\", \"voicelineId\": 1175, \"voicelineType\": \"71073\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于潜水…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_diving_hero\", \"description\": \"派蒙：枫丹的水下世界好漂亮啊，有好多没见过的鱼呢！\\n{NICKNAME}：要是在其他地方也能潜水就好了。\\n派蒙：对哦，我也觉得挺可惜的…\\n派蒙：但如果可以的话，你想潜到哪里去看看呀？\\n{NICKNAME}：唔…璃月港或者孤云阁附近？\\n派蒙：哦！我懂！这些地方要是有沉船的话，一定会发现好多好多宝藏吧！\\n{NICKNAME}：还有稻妻的珊瑚宫，水下一定很漂亮。派蒙呢？\\n派蒙：我想想…你去了璃月和稻妻，那我就去蒙德的果酒湖吧！\\n{NICKNAME}：那也不错。但正当你游着游着的时候…\\n派蒙：怎…怎么啦？\\n{NICKNAME}：突然发现有什么东西慢慢沉到了你面前…\\n派蒙：欸？！\\n{NICKNAME}：那东西圆滚滚、胖嘟嘟的，身上花纹红白相间。你意识到了，这就是…\\n派蒙：蹦蹦炸弹！！\\n{NICKNAME}：嘣——！\\n派蒙：呜啊啊啊！被炸飞啦——！\", \"voicelineId\": 1176, \"voicelineType\": \"71074\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艺术…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_art_hero\", \"description\": \"派蒙：枫丹廷里到处都是奇奇怪怪的艺术家，听说歌剧院里也经常会有艺术家登台表演。\\n派蒙：看来枫丹人真的很重视艺术呢，不愧是艺术之都。\\n派蒙：不像在须弥，就连演出都要偷偷摸摸的…\\n{NICKNAME}：看来派蒙对艺术很感兴趣呢。\\n派蒙：那当然，我对艺术可是很有研究的！\\n{NICKNAME}：那么派蒙觉得什么样的才算是艺术呢？\\n派蒙：这个嘛…艺术就是那种和一般常见的都不一样，会像星星一样闪闪发光的东西吧！\\n{NICKNAME}：嗯…这样的东西，眼前好像正好有一个呢。\\n派蒙：欸…？\\n派蒙：等等，你该不会是在说我吧。\\n{NICKNAME}：嗯嗯，仔细想想，如果把派蒙带去歌剧院里表演的话，说不定也能大受欢迎呢！\\n派蒙：才不要吧！\", \"voicelineId\": 1177, \"voicelineType\": \"71075\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于修理故障…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_troubleshooting_hero\", \"description\": \"派蒙：奇怪…明明发条机关的结构都精密得不得了，为什么有时候出了故障，只要拍一拍就能好？\\n{NICKNAME}：大概是机关里面有哪个齿轮或者传动杆松动了吧，拍一拍晃一晃，让它们扣上了就行。\\n派蒙：欸？还是不太懂…\\n{NICKNAME}：嗯…简单来说，就是这些机关本身就没有多大故障，拍一拍就能让零件回到正常的位置。\\n{NICKNAME}：反过来说，如果是零件本身受损，就算拍散架了也修不好。\\n派蒙：哦哦…是不是说，就像有的人只是偶尔迷糊，拍拍脑门就能清醒过来。有些人本来就迷糊，就算再怎么拍也还是一样迷糊！\\n派蒙：…等等，你为什么盯着我的脑门看？\\n{NICKNAME}：放心吧，我不会拍的，反正拍了也没用。\\n派蒙：这还差不多…等等——喂！\", \"voicelineId\": 1178, \"voicelineType\": \"71076\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于梅洛彼得堡…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_fortressOfMeropide_hero\", \"description\": \"派蒙：听说枫丹有个地方叫作梅洛彼得堡，是不是为了纪念一个叫做梅洛彼得的人修建的？\\n{NICKNAME}：我倒没听说过欸，感觉挺有可能的。\\n派蒙：真羡慕啊，拥有一座跟自己名字一样的堡垒。等你有空了，帮我在尘歌壶里弄一个好不好？我也想要一个派蒙堡。\\n{NICKNAME}：那都用不着尘歌壶，跟我去一趟枫丹廷就好了。\\n派蒙：难道要在枫丹廷买地建房子吗？那要花好多摩拉吧？\\n{NICKNAME}：花不了多少。\\n派蒙：呜哇，你现在都对我这么大方啦？\\n{NICKNAME}：因为只需要买些面包，再买些菜叶，再买些沙拉酱汁…然后…\\n派蒙：喂！不是那种可以吃的派蒙堡！这个桥段你真的要玩遍七国嘛！\", \"voicelineId\": 1179, \"voicelineType\": \"71077\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [1100811], \"unlockText\": \"完成「翠石砌玉壶·其一」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于超级机关…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_mechanism_hero\", \"description\": \"派蒙：听说，最早的发条部件，其实有着很简单的运作原理！\\n派蒙：把一个很有韧性的，长条形的物体掰弯，然后借助它恢复成原样的力量，就能驱动齿轮之类的东西，带动机器了！\\n{NICKNAME}：很有韧性的，长条形的物体…总觉得有些耳熟？\\n{NICKNAME}：急冻树和爆炎树不也是吗！\\n派蒙：噫！为什么会想到那两个大家伙啦！\\n派蒙：不过你这么一说，它们两个确实特别能转圈呢…\\n{NICKNAME}：而且力气特别大哦，突然蓄满全力一下子抡过来的话…\\n{NICKNAME}：就算是强大的我，也会摔倒在地上！\\n派蒙：所以急冻树和爆炎树…也能被做成发条？\\n{NICKNAME}：根据冰元素生物讨厌火元素，火元素生物讨厌冰元素的原理，把急冻树和爆炎树斜着放在一起…\\n{NICKNAME}：它们就会因为讨厌彼此而不停转圈！\\n{NICKNAME}：这不就是一个超级发条机关吗！捕捉这股力量的话，大半个枫丹廷的机器都不愁没能源了！\\n派蒙：喔喔喔！好有道理！\\n派蒙：真是天才的方案！枫丹科学院的院长也想不到吧！\\n派蒙：接下来只要想办法把急冻树和爆炎树带到枫丹来，放在一起…\\n派蒙：等等，要怎么样把这两个大家伙送到枫丹来？\\n{NICKNAME}：至于成本和实现方法的问题嘛…\\n{NICKNAME}：前面的细节，以后再来讨论吧！\", \"voicelineId\": 1180, \"voicelineType\": \"71078\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于水下咖啡馆…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_underwaterCafe_hero\", \"description\": \"派蒙：之前，我们在须弥见到了很漂亮的咖啡馆，结果枫丹人也很喜欢喝咖啡呢，和须弥人不相上下！\\n{NICKNAME}：是呀，就连报纸上的文章都在强调，咖啡的提神效果很好，还能帮助正在工作的人迅速恢复精力，保持最高效率一直上班。\\n派蒙：需要喝咖啡来恢复精力的工作，一听就很累…\\n派蒙：比如说…铁匠吗？厨师和到处跑的冒险家应该也会经常喝咖啡？还有…潜水员？\\n{NICKNAME}：咦，潜水员？派蒙好像提到了不得了的职业！\\n{NICKNAME}：潜水员在水下干活的时候，要怎么喝咖啡呢？\\n派蒙：对哦，这个问题好关键！\\n派蒙：在水里不能摘下头盔，难道要用一个更大的玻璃罩子把自己关起来，然后抽干里面的水，再安安心心地喝瓶子里的咖啡…\\n派蒙：不对，这样一说，把咖啡装在瓶子里，装上一根长长的管子，管子的另一头直接安装在头盔里边，歪歪头就能喝到了！\\n{NICKNAME}：那样咖啡就凉掉了！\\n{NICKNAME}：不热也不冰的咖啡，一点也不香！\\n派蒙：没关系，大不了就再带一个炉子去潜水。\\n派蒙：你看，枫丹人经常用来做饭的炉子只有最上边一个开口，只要把它牢牢封住，放进水里，炉火应该也不会熄灭…\\n派蒙：等等…这么巧吗？会不会…枫丹的炉子本来就有这种用法？\\n{NICKNAME}：噔噔！居然被派蒙发现了！枫丹烹饪炉的真正设计意图！\\n派蒙：不愧是我！\\n派蒙：这么说来，在水下开一间咖啡馆也不是不可能嘛！肯定会有很多潜水员来喝咖啡的，这都是商机，商机呀！\\n派蒙：只要我们开了第一家水下咖啡馆，摩拉就会滚滚掉进我们的口袋，说不定还有机会发展成水下的商业街…\\n派蒙：嘿嘿！靠商业头脑赚来的摩拉，更有满足感！\\n{NICKNAME}：要提醒派蒙的是…千万不要用我的名字向银行贷款哦！\", \"voicelineId\": 1181, \"voicelineType\": \"71079\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于蒸汽鸟报…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_steambird_hero\", \"description\": \"派蒙：那个「蒸汽鸟报社」就在枫丹廷里呢，不知道平时这些报纸上会写什么。\\n派蒙：你说，会不会报道我们之前和特瓦林的故事呀？还有雷电将军…对了，还有教令院的事！\\n{NICKNAME}：蒸汽鸟报上应该会有很多版面吧，每一个版面都会报道不同的事。\\n派蒙：喔！那头版一定是我们经历的那些冒险啦，又精彩又引人注意！\\n{NICKNAME}：唔…我觉得不一定喔。或许会有那么一两次，但大部分时间，头版可能都是歌剧或者歌剧演员的新闻。\\n{NICKNAME}：像是某某演员突然出现在路边喝咖啡，某某演员宣布自己开始恋爱，某某演员不再演出之类的。\\n派蒙：这种没价值的新闻为什么要放在最显眼的地方？\\n{NICKNAME}：可不能说没价值，这反倒是大家最津津乐道的内容，一个激动就会愿意买下来细细品读了。\\n派蒙：唉…好吧。那…内页里的版面？买下报纸之后，内页肯定要有一些精彩内容，吸引大家继续看呀？\\n{NICKNAME}：那就是和枫丹廷有关的好消息了。比如食物、材料降价啦，水道又往外重建了多少啦…\\n{NICKNAME}：这种新闻放在一打开报纸就能看见的地方，负责的是「打发时间」。\\n{NICKNAME}：教令院的事虽然是重大新闻，但和枫丹人的生活却没有直接关系。\\n派蒙：呜…那我们的冒险会放在哪里？\\n{NICKNAME}：我想，大概会放在整份报纸彻底翻开后的版面吧。\\n派蒙：为什么要放在这么后面啦！\\n{NICKNAME}：这就是俗称的「压阵」新闻啦。\\n{NICKNAME}：他们多半还会把我们的冒险添油加醋写得很长，再把这一整篇文章拆开来，连载个三五天才算完。\\n派蒙：那这个版面负责什么？\\n{NICKNAME}：负责让这张报纸多少带上一些「存在价值」。\", \"voicelineId\": 1182, \"voicelineType\": \"71080\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}, {\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于发条机关…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_clockwork_hero\", \"description\": \"派蒙：没想到还有会跳舞的发条机关…虽然靠近会很危险，但只是在观众席上欣赏的话感觉还挺不错的。\\n派蒙：如果还有演奏发条机关、唱歌发条机关…一定会很热闹！\\n{NICKNAME}：再加上观众发条机关，那就是——发条机关演出，发条机关欣赏，发条机关为了发条机关。\\n派蒙：不知道为什么听起来有点可怕…\\n派蒙：还是让发条机关干点别的吧！对了！如果有画画发条机关，画出来的画会不会就像留影机拍出来的一样。\\n{NICKNAME}：那直接用留影机不就好了？\\n派蒙：说的也是…唔…\\n派蒙：不行了…我的脑袋转不动了。你呢？如果现在能让你变出任意一种发条机关，你希望它承担怎样的工作？\\n{NICKNAME}：嗯，比如说向导的工作…\\n{NICKNAME}：嘎嘎，我是向导发条机关，前方的道路请保持直行，嘎嘎。\\n派蒙：这、这么说来，发条机关的维护不仅需要专业知识，成本也很高呢！而且也不知道离开枫丹之后还能不能正常运作…\\n派蒙：提瓦特大陆最好的向导是不会失业的！应该…应该不会吧？\", \"voicelineId\": 1183, \"voicelineType\": \"71081\", \"unlockConditions\": [{\"paramList\": [3, 874], \"unlockText\": \"解锁「枫丹 伊黎耶岛」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于观景喷泉…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_fountain_hero\", \"description\": \"派蒙：说起来，每天都能看到有人往伊黎耶岛的喷泉里丢摩拉呢。\\n{NICKNAME}：嗯，据说住在泉水里的精灵能够聆听大家的愿望，所以才有这样的习俗吧。\\n派蒙：喔！所以泉水精灵也需要摩拉吗？\\n派蒙：真好啊，只要住在泉水里，每天什么都不用做，就可以从大家那里收到摩拉…\\n{NICKNAME}：我觉得应该不是那样的…\\n派蒙：「年轻的旅人啊，我已经听到了你的愿望，你掉的是这把无锋剑呢，还是这把银剑呢？」\\n{NICKNAME}：两边好像都不是什么值钱的东西呢。\\n派蒙：快选啦。\\n{NICKNAME}：「泉中的少女啊，我掉的既不是这把无锋剑，也不是这把银剑，而是与我同行的伙伴。」\\n派蒙：欸？真、真是拿你没办法…那就把泉水精灵本人送给你，作为最棒的搭档吧！\", \"voicelineId\": 1184, \"voicelineType\": \"71082\", \"unlockConditions\": [{\"paramList\": [3, 875], \"unlockText\": \"解锁「枫丹 欧庇克莱歌剧院」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于歌剧…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_opera_hero\", \"description\": \"派蒙：枫丹的歌剧题材好多呀，除了历史故事和传说，居然还有童话和现代浪漫戏…\\n{NICKNAME}：好像还有很多冒险的故事呢。\\n派蒙：是呀，比如刚才看过的「堂克勒德与夏蕾克莱娅」，呜啊，要是男主角在那个时候认出了女主角的话…\\n{NICKNAME}：据说是真实历史改编的喔。\\n派蒙：唔，既然这样的话，那有朝一日，我们的冒险会不会也被改编成歌剧呢？\\n派蒙：毕竟，我们也经历过那么多冒险，说不定也会有感兴趣的剧作家把我们的故事搬上舞台！\\n派蒙：这样一来，他们也不必处心积虑构思悲剧啦，大家都想看点开心的故事，对吧？\\n{NICKNAME}：那样的话，我们提前考虑一下声部的划分吧？ \\n派蒙：唔，你的话，应该是青年男中音吧？而派蒙就应该是——\\n{NICKNAME}：花腔女高音？\\n派蒙：为什么啦！\", \"voicelineId\": 1185, \"voicelineType\": \"71083\", \"unlockConditions\": [{\"paramList\": [3, 875], \"unlockText\": \"解锁「枫丹 欧庇克莱歌剧院」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于美露莘…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_melusine_hero\", \"description\": \"派蒙：听说每位美露莘在诞生时都会有一个与生俱来的信物，她们会把这个信物当作自己精神的象征。\\n{NICKNAME}：假如派蒙是美露莘的话，这个信物会是什么呢？\\n派蒙：肯定是叉子！代表吃遍全世界的好吃的！\\n{NICKNAME}：不是摩拉吗？\\n派蒙：对哦，假如是摩拉的话，不就说明我会成为大富翁。以后想买什么就买什么了吗？\\n派蒙：唔——好纠结，我都好想要！\\n{NICKNAME}：那就摩拉做的叉子吧，这样就都能有了。\\n派蒙：那真是好主意呢！\\n派蒙：如果是这样的话，你的信物一定是一口锅，负责给我做好吃的！\\n{NICKNAME}：不不不，我的信物是派蒙哦。\\n派蒙：嘿嘿，真的吗？\\n{NICKNAME}：这样派蒙的东西就都是我的啦。\\n派蒙：唔——那好吧，好朋友之间东西是要互相分享的。\\n{NICKNAME}：我的东西还是我的。\\n派蒙：喂！\", \"voicelineId\": 1186, \"voicelineType\": \"71084\", \"unlockConditions\": [{\"paramList\": [3, 877], \"unlockText\": \"解锁「枫丹 海沫村」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于沫芒宫…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_fd_palaisMermonia_hero\", \"description\": \"派蒙：说起来，我们在城里总听人说，在沫芒宫里工作的人都很忙。\\n派蒙：但上次去沫芒宫的时候，里面压根没多少人呀？\\n派蒙：剩下的人也一副优哉游哉的样子…真不知道忙在哪里…\\n{NICKNAME}：也许，他们都在忙一些「十万火急又无足轻重」的事呢。\\n派蒙：怎么可能有这样的事情啦，都十万火急了，怎么可能无足轻重呢？\\n{NICKNAME}：有喔，比如说…派蒙有一天也许会突然飞不动，从半空摔下来…\\n派蒙：会这样吗？我飞得还挺轻松的…\\n{NICKNAME}：所以我们应该采购一些带软垫的小车，一直放在派蒙的下方。\\n{NICKNAME}：这辆小车要足够可靠，能在任何路况下跟着派蒙移动，车上的垫子也要足够软…\\n{NICKNAME}：还有牵引绳的质量，小车的材质，也许还要准备一些医疗用品和零食…\\n{NICKNAME}：毕竟，为了不让派蒙受伤，这件事当然十万火急。\\n派蒙：是这样吗？嘿嘿…也不用想得这么周到啦。\\n派蒙：但我都飞这么久了，肯定不会突然就不能飞了，不用杞人忧天啦。\\n{NICKNAME}：喏，你看，这不就是「无足轻重」吗？\\n{NICKNAME}：如果这件事真的发生了，就会产生很严重的后果，所以「十万火急」。\\n{NICKNAME}：但从各种角度来说，这件事都不太可能立即发生，所以「无足轻重」。\\n{NICKNAME}：如果一个人被分配去处理这种事，那无论是想要偷懒还是想要忙碌，都由他自己定啦。\\n派蒙：但，但是！如果我真的突然飞不动了，摔下来怎么办？！\\n{NICKNAME}：那我一定会接住派蒙的，派蒙是我重要的伙伴，可不是「十万火急又无足轻重」的事。\", \"voicelineId\": 1187, \"voicelineType\": \"71085\", \"unlockConditions\": [{\"paramList\": [3, 772], \"unlockText\": \"解锁「枫丹 沫芒宫」七天神像-水\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于回声之子的宝石…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_nanatzcayanDiamond_hero\", \"description\": \"派蒙：说起来，这边的山谷有好多亮闪闪的宝石呢！\\n派蒙：机会难得，我们也在附近挖挖看吧。要是运气好的话，说不定就能挖到超级厉害的宝石，再也不用担心摩拉不够用啦！\\n{NICKNAME}：咦？派蒙能分辨宝石的种类吗？\\n派蒙：呃，这个…只要是亮闪闪的东西，就一定是好东西！嗯，应该是这样没错！\\n{NICKNAME}：听上去简直就像是童话故事里收集财宝的恶龙一样呢。\\n派蒙：哼哼，既然到了纳塔，就不应该叫「恶龙」，而是应该叫「贤龙」啦！\\n派蒙：「勇敢而机智的{NICKNAME}呀，就让本贤龙指引你找到超级厉害的宝石吧——」\\n{NICKNAME}：明明连宝石的种类都没办法分辨？\", \"voicelineId\": 1188, \"voicelineType\": \"71086\", \"unlockConditions\": [{\"paramList\": [3, 1252], \"unlockText\": \"解锁「纳塔 回声之子」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于悬木人…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_huitztlan_hero\", \"description\": \"派蒙：悬木人似乎很喜欢那些看起来就非常危险的户外运动呢。\\n派蒙：什么无护具徒手攀岩，高空滑板，火山跑酷，悬崖蹦极…光是想想就让人心跳加速了！\\n{NICKNAME}：有吗？其实我们的冒险也挺危险的吧。冷风飕飕的雪山，酥酥麻麻的雷暴，黄沙乱舞的沙漠，寸草不生的死域…\\n派蒙：呃，这么说，我们这一路还真是水深火热…\\n{NICKNAME}：但我们够强，所以在普通人眼里是冒险的事情，对我们来说是家常便饭。悬木人说不定也是这样的吧。\\n派蒙：等，等一下！我可没有你那么英勇，你别把我算上。\\n派蒙：你们强者之间互相理解就好了。真要有危险的事情发生，我…我还是会躲在你身后的。\", \"voicelineId\": 1189, \"voicelineType\": \"71087\", \"unlockConditions\": [{\"paramList\": [3, 1253], \"unlockText\": \"解锁「纳塔 悬木人」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于纳塔的温泉…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_natlanSpa_hero\", \"description\": \"派蒙：「流泉之众」的氛围真是悠闲呀，大家不是在泡温泉，就是在泡温泉的路上…\\n{NICKNAME}：听说有些温泉爱好者还会特意雇佣音乐家，在泡温泉的时候演奏舒适的音乐，这样能让身心彻底地放松哦。\\n派蒙：哇，说得我也想试试了…\\n{NICKNAME}：下次派蒙泡温泉的时候，我来为你演奏兰那罗的音乐吧。\\n派蒙：欸，但是我还没学会弹乐器，轮到你泡的时候怎么办…\\n{NICKNAME}：那派蒙就唱歌吧。嗯…选一首枫丹的歌剧如何？\\n派蒙：那也太难了！听了之后说不定没法放松心情，反而会头疼脑热的！\\n派蒙：不如来点纳塔特色的说唱吧，我刚学会的，咳咳——\\n派蒙：「hey站在你面前的就是大名鼎鼎派蒙，经历了这么多的冒险我已变得从容…」\\n派蒙：「yo见识过万水之源的海兽它叫膨膨，还有传闻之中古华派的枪剑双绝武功…」\\n{NICKNAME}：真的很有律动呢！\\n{NICKNAME}：让人有种想要一边泡温泉一边拍打水面，用溅起的水花来伴奏的冲动。\\n派蒙：像举行音乐派对一样！要是有来晚了的人，还可以一个滑铲直接滑到温泉里，加入大家的节奏！\\n{NICKNAME}：嗯？等等，我们好像完全忘记泡温泉是用来放松的了…\", \"voicelineId\": 1190, \"voicelineType\": \"71088\", \"unlockConditions\": [{\"paramList\": [3, 1254], \"unlockText\": \"解锁「纳塔 流泉之众」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于沃陆之邦…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_teteocan_hero\", \"description\": \"派蒙：你不觉得，蒙面战士的设定非常帅气吗？\\n{NICKNAME}：确实，会有一种谜一样的帅气感。\\n派蒙：对吧对吧，你说我是不是也可以戴上面具，然后在沃陆之邦摔跤，打响全新的名号？\\n派蒙：台词我都想好了，就叫：「龙战士永远不会揭下她的面具！」\\n派蒙：白天是著名的冒险家，夜晚是强大的龙战士摔跤手。怎么样，很帅吧！\\n{NICKNAME}：帅是很帅啦，但有一个问题。\\n派蒙：嗯？什么问题啊？\\n{NICKNAME}：你这种体型，一眼就会被人认出来了吧…\", \"voicelineId\": 1191, \"voicelineType\": \"71089\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于织物…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_woven_hero\", \"description\": \"派蒙：纳塔的传说和故事大多是编织在织物上面的，跟其他国家的书读起来体验很不一样呢。\\n{NICKNAME}：嗯，据说最早是起源于「烟谜主」，萨满会用织物来记录部族的历史和传说。后来织物被用于编写各种各样的故事，题材也越来越丰富了。\\n派蒙：嘿嘿，我也把我们一路的故事写下来吧，要是你有一天组建了名为「旅行者」的部族，就有现成的历史读物了！\\n派蒙：而且，平时能围在身上当披风，露营的时候还能躺在上面睡觉…\\n{NICKNAME}：真是「饱经风霜」的冒险传记呢。\", \"voicelineId\": 1192, \"voicelineType\": \"71090\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于沃陆之邦与花羽会…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_teteocanAndTlalocan_hero\", \"description\": \"派蒙：听说沃陆之邦的人们都很健壮。\\n{NICKNAME}：那假如把派蒙放在那里，会不会变成肌肉派蒙呢？\\n派蒙：我才不要变成那个样子啦！\\n{NICKNAME}：那放在花羽会怎么样，他们很擅长飞行，说不定可以帮忙提升派蒙的飞行技巧呢。\\n派蒙：欸，飞行不就是咻——的一下就好了，还需要什么技巧吗？\\n{NICKNAME}：我只要求派蒙能带着我飞起来就好。\\n派蒙：差太多了吧！怎么想都不可能吧！\\n{NICKNAME}：那你先变成肌肉派蒙不就好了。\\n派蒙：喂！说到底你就是想看肌肉吧！\", \"voicelineId\": 1193, \"voicelineType\": \"71091\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于使龙开心的办法…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_wayOfDragonHappy_hero\", \"description\": \"派蒙：欸嘿嘿，纳塔有好多好多可爱的龙，我要跟它们都搞好关系！\\n{NICKNAME}：哦？派蒙很自信嘛。\\n派蒙：那当然，我还特意为此准备了秘诀！\\n{NICKNAME}：秘诀？是什么秘诀啊？\\n派蒙：很简单！首先，你要先夸奖它，这样它就会感受到你的好意并放下防备。接着，再轻轻地摸摸它的头，你们就熟悉起来啦！\\n派蒙：最后，也是最重要的！好吃的！只要你跟龙分享好吃的，你们就是好朋友啦！怎么样，我厉害吧！\\n{NICKNAME}：——唔，总感觉…这些招数用来对付派蒙也很好用呢…\\n派蒙：喂！不许用那刚才的招数对付我！\\n{NICKNAME}：欸？我的意思明明是，派蒙就跟纳塔的龙宝宝一样可爱呢！\\n派蒙：哼，你就是想说点好听的来敷衍我，我才不上当呢！\\n{NICKNAME}：可我是在真心夸奖派蒙啊，没想到惹你不高兴了。作为道歉，我请你吃甜甜花酿鸡好不好？\\n派蒙：真的？好哎，是甜甜花酿鸡！我现在就要吃！\\n派蒙：不过话说回来，你怎么笑得这么开心啊？难道我错过了什么吗？\", \"voicelineId\": 1194, \"voicelineType\": \"71092\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于考古…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_archaeology_hero\", \"description\": \"派蒙：听说，在回声之子考古是一个非常考验速度的工作，这是为什么啊？\\n{NICKNAME}：或许是因为这里的古物太多了吧…\\n派蒙：欸？那不是好事吗！\\n{NICKNAME}：古物越多竞争者就越多啊！就比如你前一天看到了一块很棒的石板，打算第二天过来搬走。结果等第二天发现，已经早就被人捷足先登了！\\n派蒙：——唔，我还是没懂…\\n{NICKNAME}：打个比方的话，就像你昨晚准备偷偷独吞剩下的零食，结果突然发现少了一块…\\n派蒙：啊！那确实好可怕！\\n派蒙：——等等，你怎么知道昨天我的零食少了一块的？\", \"voicelineId\": 1195, \"voicelineType\": \"71093\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于解决争端的办法…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_solveConflict_hero\", \"description\": \"派蒙：据说在纳塔，有着可以不靠肌肉就解决争端的办法。\\n{NICKNAME}：在战争的国度，竟然还有这种方法吗？\\n派蒙：没错，我听说在回声之子，某一部分人就有用舞蹈对决来解决争端的传统！\\n{NICKNAME}：舞蹈对决？你是说，大家约好时间地点…\\n派蒙：嗯嗯。\\n{NICKNAME}：然后开始比拼花式动作…\\n派蒙：对对。\\n{NICKNAME}：直至一方力竭，最终倒地不起为止？\\n派蒙：没错！\\n派蒙：——欸，不对，那不还是靠肌肉吗！\", \"voicelineId\": 1196, \"voicelineType\": \"71094\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于发财的机会…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_opportunityOfRich_hero\", \"description\": \"派蒙：嘿嘿，你听我说哦。我发现了一个不得了的发财机会！\\n{NICKNAME}：嗯，什么机会？\\n派蒙：你看圣火竞技场有这么多人经过。我们要是能在这里做点生意，一定可以发大财！\\n{NICKNAME}：哦？那派蒙准备卖点什么呢？\\n派蒙：蒙德的炼金药剂怎么样？\\n{NICKNAME}：貌似已经有人在卖类似的东西了…\\n派蒙：那璃月的各种矿石呢？这个一定很赚钱！\\n{NICKNAME}：回声之子不就是干这个的…\\n派蒙：哦对…啊！我想到了，须弥的挂毯，这个一定会很吃香！\\n{NICKNAME}：可惜，还有烟谜主呢。\\n派蒙：那，那我们把圣火竞技场四面用围栏拦起来！从今往后不管是参赛的和观战的，都要先付钱才能出入场地。\\n{NICKNAME}：你的围栏还没建成，人就会先被谁给抓起来…\\n派蒙：怎么这样——发财可真难啊。\", \"voicelineId\": 1197, \"voicelineType\": \"71095\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于龙的发型师…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_dragonHairStylist_hero\", \"description\": \"派蒙：我们刚到纳塔遇见的三种龙伙伴都很特别呢。\\n派蒙：小嵴锋龙的脑袋弹弹的，小鳍游龙的背滑滑的，小匿叶龙的耳朵和脑袋毛茸茸。\\n{NICKNAME}：毛茸茸的小匿叶龙，抱着睡觉一定很香…\\n派蒙：不过，我记得很多动物的毛发会长得很长，也不知道会不会影响它们的行动？\\n派蒙：就比如说，如果匿叶龙耳朵和头上的绒毛太长，说不定会挡住眼睛，看不清前面的路，还有一点危险…\\n{NICKNAME}：既然派蒙想到了这一点，就由你来帮匿叶龙修理发型吧！\\n派蒙：欸，我吗？\\n{NICKNAME}：等你成为了纳塔有名的龙之发型师，还能赚大钱！\\n派蒙：说得对喔，没想到还能用这种方式发财！\\n派蒙：整个纳塔的匿叶龙都由我来理发，嘿嘿，摩拉…\\n派蒙：不对不对，摩拉是次要的，能和一整个纳塔的匿叶龙做朋友，肯定超开心！\\n{NICKNAME}：但是匿叶龙那么——那么大，用普通的小剪刀，不知道要修剪多久，也许每天只能给一只龙做发型。\\n{NICKNAME}：要想成为厉害的龙之发型师，派蒙就得好好锻炼锻炼了，至少要拿得起…无锋剑这么大的剪刀！\\n派蒙：无锋剑…那不是你的武器吗？\\n{NICKNAME}：我们可是好伙伴。走吧走吧，现在就去野外为你上第一堂课。\\n派蒙：不要以训练的名义把魔物推给我处理啊！\", \"voicelineId\": 1198, \"voicelineType\": \"71096\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「古名」…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_name_hero\", \"description\": \"派蒙：据说被大灵认可并且选中的纳塔战士会获得「古名」呢，真羡慕…要是我也能有自己的「古名」就好了！\\n{NICKNAME}：欸？可是派蒙不是已经有很多称号了吗？\\n派蒙：咦？是哦！\\n派蒙：我可是你「最好的伙伴」和「非常可靠的向导」，同时还是「荣誉高级研究员助理」、「时髦飞行家」和「白银伴星」…这样想想，真是不得了的大英雄！\\n派蒙：如果纳塔人要记录我和{NICKNAME}在这里的冒险，我要把这些称号都用上！\\n{NICKNAME}：欸？这样不会太长了吗？\\n{NICKNAME}：想一想，如果纳塔人也把他们的称号都用上，织物就会变成这样…\\n{NICKNAME}：「这一天，『回声之子』纳茨卡延的『乌沙博蒂』的卡齐娜，和她热情的朋友，『流泉之众』梅兹特利的『沃摩延』的玛拉妮，在去往『烟谜主』米克特兰的路上，遇见了『悬木人』维茨特兰的『马力卜』的基尼奇，和他狡诈的伙伴，『库胡勒阿乔』…」\\n派蒙：停停停！说了这么多，都够从这里一直铺到圣火竞技场，再铺回来了…可是根本还没讲到关键信息啊！\\n派蒙：唔，如果只能选一个称号的话…果然还是只要「最好的伙伴」好了！\", \"voicelineId\": 1199, \"voicelineType\": \"71097\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于圣火竞技场…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_arena_hero\", \"description\": \"派蒙：偷偷告诉你，我一直对圣火竞技场有个好奇的地方。\\n派蒙：比赛的形式不是积分制吗？大家组成小队，小队成员分别一对一进行固定轮次的比赛，再按照最后的积分来确定名次…\\n派蒙：为什么要采用这种规则呢？\\n{NICKNAME}：是为了把悬念留到最后一轮吧，也许观众的口味都喜欢看逆风翻盘。\\n派蒙：有道理，但会不会还有一种可能，是为了避免发生那种情况：只有两人参赛，双方又战力相当，怎么也分不出胜负…\\n{NICKNAME}：唔...似乎只能中途休战了。\\n派蒙：对呀！想象一下，一只突角龙和一只匿叶龙在场上比赛，突角龙擅长猛攻，匿叶龙擅长躲避，已经比赛了一天一夜…\\n派蒙：观战的大家早都看饿了，于是说，暂停暂停，下次再来。\\n派蒙：下次还是没能决出胜负，甚至匿叶龙违规使出偷袭，突角龙受伤了，又被发下了休止牌。\\n派蒙：这就变成了《突角龙大战匿叶龙》、《突角龙大战匿叶龙：续篇》、《突角龙大战匿叶龙：神龙归来》、《突角龙大战匿叶龙：纵横火山》…连续的剧场。\\n派蒙：欸？找人拍成系列映影也可以啊！还可以大赚一笔。\\n{NICKNAME}：虽然想法不错，但是…悬木人不会高兴你把他们的龙拉过来当反派吧！\\n派蒙：我只是一时间没找到什么更好的素材啦！\", \"voicelineId\": 1208, \"voicelineType\": \"71098\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于纳塔的冒险家…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_adventurerInNatlan_hero\", \"description\": \"派蒙：纳塔人一般是不会离开纳塔的，对吧？\\n{NICKNAME}：嗯，有一些原因呢。\\n派蒙：唔，这样说来，他们要是想当冒险家的话，岂不是会很不方便？\\n派蒙：你想想，没办法去其它国家，就有一大堆委托没办法接…不能去未知的遗迹探险，也赚不到很多的摩拉，好可怜哦。\\n{NICKNAME}：听起来很有道理的样子，不过实际情况好像不是这样呢。\\n派蒙：欸？\\n{NICKNAME}：我听说在「流泉之众」有一群自称「旅行家」的人，因为他们对纳塔的地理啦，遗迹啦，都十分了解，所以其它国家的冒险家来到纳塔都会雇佣他们作为向导。\\n{NICKNAME}：这样不管这些冒险家最后有没有找到宝藏，都要付给他们报酬。时间长了，他们可能比冒险家赚得都要多呢。\\n派蒙：原来是这样…等等，如果他们真的对遗迹什么的这么了解的话，为什么不自己去找宝藏啦？\\n{NICKNAME}：假如说，从一开始就没有什么宝藏呢？\\n派蒙：哇，总感觉知道了什么不得了的事情…\", \"voicelineId\": 1209, \"voicelineType\": \"71099\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于涂鸦…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_scrawl_hero\", \"description\": \"派蒙：纳塔的人很喜欢在各种地方涂涂画画呢，我记得他们是叫作燃素…\\n{NICKNAME}：是「燃素刻录」啦。不过只有刻在特殊的石碑上的才是真正的「燃素刻录」，这些就只是单纯的涂鸦而已。\\n{NICKNAME}：比如这幅就像是在说，「喂，这里是我们的地盘，『回声之子』天下第一！」\\n派蒙：感觉很有意思呢！既然这样，{NICKNAME}，我们也来留下自己的涂鸦吧。\\n{NICKNAME}：听起来不错，不过我们的话要画些什么呢？\\n派蒙：那当然是要留下提瓦特大陆最棒向导的画像啦！嘿嘿，不如就在那边的岩壁上…\\n{NICKNAME}：这样啊，那画师自然就是我了。让我想想，派蒙的话，首先应该是气鼓鼓的脸…\\n派蒙：嗯嗯…才不对吧！算了算了，还是等下次有机会的时候，让纳塔专业的画师来帮我们画好了。\", \"voicelineId\": 1210, \"voicelineType\": \"71100\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于纳塔的龙伙伴…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_dragonFriends_hero\", \"description\": \"{NICKNAME}：纳塔的人们，真的把龙当作伙伴了呢…\\n派蒙：是呀，简直就像是{NICKNAME}和我一样，不管走到哪里都形影不离！\\n{NICKNAME}：既然派蒙是我的伙伴，龙是纳塔人的伙伴，要是让派蒙和龙比赛的话，谁会赢呢？\\n派蒙：为什么会突然出现这么奇怪的想法啦！\\n{NICKNAME}：仔细想想的话，派蒙既不会像嵴锋龙一样钻地，也没有绒翼龙飞得那么快…\\n派蒙：应、应该换一种角度考虑嘛！比方说，派蒙比嵴锋龙飞得更快，比绒翼龙…呃，比绒翼龙更擅长分辨野菇鸡肉串的美味程度！\\n{NICKNAME}：更重要的是，比所有龙陪在我身边的时间都要长呢。\\n派蒙：没错没错！哼哼，毕竟我可是提瓦特大陆最棒的向导——\\n{NICKNAME}：那我的好伙伴，我们也该开始今天的冒险了吧？\\n派蒙：哎呀，总觉得分辨美食的技巧都有点生疏了，先来一份野菇鸡肉串再出发吧！\", \"voicelineId\": 1211, \"voicelineType\": \"71101\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿乔…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_ajaw_hero\", \"description\": \"派蒙：其实我想问你很久了…难道你就不好奇吗？阿乔的样子…\\n{NICKNAME}：有什么问题吗？\\n派蒙：问题很大吧！他跟别的龙都不一样！阿乔会讲话，话还不少！他不在地上走，总是绕在基尼奇周围飞，而且而且啊，哪有龙会戴那种奇怪的墨镜啊！\\n{NICKNAME}：嗯…\\n派蒙：突、突然盯着我看做什么…\\n{NICKNAME}：这么说来，派蒙话也不少，也会飞，而且在枫丹不也弄了副搞怪的眼镜吗？\\n派蒙：哎呀…不对啦！\\n派蒙：先不讨论这些。我其实最想问的是…阿乔像硬纸板一样…扁扁的…难道整个纳塔都没有人在意过这个问题吗？\\n{NICKNAME}：有道理，不过也许是因为大家已经习以为常了吧。\\n{NICKNAME}：这种关乎来历与隐私的事情，也许要问问阿乔本人才知道了。\\n派蒙：可是，你觉得阿乔会说实话吗？总觉得他会胡编乱造一些话来忽悠我们呢…\\n派蒙：又或者…故意引诱我们，让我们也变成扁扁的硬纸板…\\n{NICKNAME}：嗯…扁扁的派蒙…其实我也有点好奇…\\n派蒙：又、又盯着我看做什么！我才不要变成扁派蒙——呜！\", \"voicelineId\": 1212, \"voicelineType\": \"71102\", \"unlockConditions\": [{\"paramList\": [15004], \"unlockText\": \"完成「尤潘基的回火」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于纳塔人的彩绘…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_bodyPainting_hero\", \"description\": \"派蒙：说起来，我发现纳塔人身上都有些不同纹样的…呃…油彩？涂鸦？虽然看不懂，但看上去好酷！\\n{NICKNAME}：我也发现了！听说是用涂料画上去的哦，这种涂料用燃素为原料制成，跟普通涂料不太一样呢。\\n派蒙：欸？居然是这样吗？\\n{NICKNAME}：但如果派蒙也感兴趣的话，我记得有专为游客提供的涂鸦体验服务哦，会用普通涂料来替代。\\n派蒙：真的吗真的吗？正所谓「来都来了」…不如…\\n{NICKNAME}：好啦好啦，可是不同的部族喜欢用的色彩和纹样风格都不一样，那派蒙选一个喜欢的吧。\\n派蒙：那我选…呃，选…哎呀！各有各的特色，根本选不出来嘛！\\n派蒙：哼。小孩子才做选择，派蒙我全都要！\\n{NICKNAME}：哇哦…想不到派蒙现在的审美风格是「极繁主义」…虽然不清楚别人会不会觉得奇怪，但我一定会支持你！\\n派蒙：我又没说要同时画在身上，我的意思是一天换一个，六天不重样啦！\\n{NICKNAME}：哦。好可惜…看来花臂派蒙只能靠想象了…\\n派蒙：不许可惜！还有快停止这种奇怪的想象！\", \"voicelineId\": 1213, \"voicelineType\": \"71103\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于与龙共生…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_liveWithDragon_hero\", \"description\": \"派蒙：纳塔人和龙之间的关系真好啊，可以一起生活，一起战斗，一起飞行…\\n{NICKNAME}：有点像我和派蒙哦。可惜派蒙不会长大，也没法背着我在天上飞…明明吃了那么多的野菇鸡肉串呢。\\n派蒙：哼，但是龙又不能给你当向导，也不能和你聊天。\\n{NICKNAME}：其实很早之前，有过人和龙互相争夺的时代，变成如今这样和平共处的样子，一定很不容易吧。\\n派蒙：如果我是龙的话，只要给我足够的食物，我就完全不想打架了。\\n{NICKNAME}：可是如果派蒙一天要吃一百个鸡肉串，人类却没有那么多食物该怎么办？\\n派蒙：那我可以只吃五十个…\\n{NICKNAME}：或者人类也可以和派蒙约定好一起打猎，拿到更多的食材，这样两边都能吃饱了。\\n派蒙：哦！和平的关键是更多的肉！\", \"voicelineId\": 1214, \"voicelineType\": \"71104\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于火山…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_volcano_hero\", \"description\": \"派蒙：纳塔到处都能看到那个大火山呢，你说底下那些咕噜噜往外冒的岩浆是从哪里来的呀？\\n{NICKNAME}：有这么一种说法哦，据说在纳塔的地底最深处，有一只古老的巨大的沉睡的火龙，它的体内是这个世界里最初的火。火在它的体内不断燃烧，它的后背产生了许许多多冒火的孔，会周期性地往外喷出火焰，喷到地上就变成了火山里的岩浆。\\n派蒙：真的假的，那如果火龙醒了，纳塔岂不是会发生可怕的事？\\n{NICKNAME}：是啊，所以火神要聚集各部族的力量，定期安抚火龙，让它继续沉睡在梦中。\\n派蒙：不对，火神要对抗的明明是深渊的侵蚀呀！\\n{NICKNAME}：这其实是我在地摊上买到的一卷织物里记录的故事啦。\\n派蒙：我就说呢…\", \"voicelineId\": 1215, \"voicelineType\": \"71105\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夜的诅咒…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_curseOfNight_hero\", \"description\": \"派蒙：曾经有一个伟大的骑士被诅咒了，白天只能以邋遢的酒鬼大叔形象出现。\\n派蒙：只有夜深人静的时候，他会展示出自己专业、成熟、勇敢的骑士本来面目…\\n{NICKNAME}：有没有什么办法解除诅咒呢？\\n派蒙：只有发自真心的尊敬可以解除酒鬼大叔身上的诅咒。\\n{NICKNAME}：那我就去当这个解除诅咒的人吧。\\n派蒙：噔噔！诅咒解除了，现在法尔伽大团长可以选择成为酒鬼大叔或者可靠的骑士。\\n派蒙：然后法尔伽说，我本来就是邋遢的酒鬼大叔，真是对不起哦。于是白天黑夜全都是酒鬼大叔了。\\n{NICKNAME}：太糟糕了！\\n派蒙：纳塔流传的故事则是，有一个被诅咒的女孩子，白天是为老不尊、目中无人的老婆婆，晚上则会变成单纯的少女。\\n派蒙：只有…呃，只有和她聊喜欢的东西才能解除诅咒。\\n{NICKNAME}：我都能猜到结局了。珐露珊前辈的话，一定会「呵呵呵，年纪大怎么了，新生娃子你们有什么意见吗？」\\n派蒙：没错，而茜特菈莉就会——\\n{NICKNAME}：茜特菈莉应该就会又委屈又着急地说：「我本来就是普通女孩子啊！？」\\n派蒙：好像也没有诅咒？\", \"voicelineId\": 1216, \"voicelineType\": \"71106\", \"unlockConditions\": [{\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于游隙灵道…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_spiritway_hero\", \"description\": \"派蒙：五百摩拉…一千摩拉…一千二百摩拉…\\n{NICKNAME}：在做什么？\\n派蒙：呜哇！吓我一跳！\\n派蒙：嘿嘿，你知道吗，我最近攒了不少钱，过几天我也要去「流泉之众」买个冲浪板！\\n派蒙：然后我就可以像玛拉妮一样，唰地一下滑过「游隙灵道」啦。\\n{NICKNAME}：小派蒙…冲浪…\\n派蒙：等等，为什么你的眼神中带着几分怀疑？\\n{NICKNAME}：我会想你的。和你一起旅行的日子，我一直都很开心…\\n派蒙：等下！不要说得像是我回不来啦！\\n派蒙：我已经提前做好准备了！就算摔下来也没有关系，毕竟我会飞嘛。\\n派蒙：不过这么一想，游隙灵道那么高、那么陡，玛拉妮是怎么玩转的呢？\\n{NICKNAME}：对玛拉妮来说，在「游隙灵道」上滑行应该不算什么难事吧。你看她表演高难度动作时候脸上的笑容就知道了。\\n派蒙：那岂不是就是在说我没用吗？！\", \"voicelineId\": 1217, \"voicelineType\": \"71107\", \"unlockConditions\": [{\"paramList\": [3, 1254], \"unlockText\": \"解锁「纳塔 流泉之众」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于火神…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_mavuika_hero\", \"description\": \"派蒙：没想到火神居然是从「归火圣夜巡礼」中选出来的！\\n派蒙：如果我打赢比赛的话，是不是也有机会成为新的火神呢？\\n{NICKNAME}：哦？派蒙很有自信嘛。\\n派蒙：哼哼，不要小看我哦，其实我已经领教过许多神明的「招式」了。\\n{NICKNAME}：什么？\\n派蒙：比如传说中的真·风神杂烩菜、文火慢炖腌笃鲜、哈瓦玛玛兹、「普茹斯蒂司」…\\n{NICKNAME}：原来是烹饪招式啊！\\n派蒙：没错，我提议等纳塔迎来和平后，在归火圣夜巡礼中也加入烹饪对决！\\n派蒙：我已经迫不及待想领教火神的「火力」啦。\", \"voicelineId\": 1218, \"voicelineType\": \"71108\", \"unlockConditions\": [{\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于休息…\", \"voicefile\": \"VO_friendship/VO_hero/vo_fetter_nt_rest_hero\", \"description\": \"派蒙：说起来，有一段时间没见过希诺宁了，上次见到她的时候，她还趴在一棵树上睡觉。\\n{NICKNAME}：上上次，应该是躺在屋顶，戴着墨镜晒太阳。\\n派蒙：上上上次，好像是坐在自己做的摇摇椅上喝果汁…\\n派蒙：呜哇，为什么我们对希诺宁的印象，都是她在休息啊！\\n{NICKNAME}：平时工作很勤奋的人，一旦停下来休息，就会给人留下很深的印象。\\n派蒙：真的？这么一想，我工作的时候也很努力啊。\\n派蒙：上次追那只小嵴锋龙的时候，我为了给你指路，飞得很高很高。\\n派蒙：还有那次帮「悬木人」的讯使找邮包，帮人去采苦种，哇…说起来都好累好累。\\n派蒙：哼，以后我们去做委托的时候，我要多多偷懒，而且不让你发现！\\n{NICKNAME}：我尽量不发现，派蒙就好好偷懒吧。\\n派蒙：你那么好呀？那你偷懒的时候，我也尽量不发现…\\n派蒙：哎呀，这么一想，我们干脆一起去偷懒吧。\\n派蒙：好，决定了！现在就是我们互相不发现的偷懒时间，快快快，一起躺下晒太阳吧。\", \"voicelineId\": 1219, \"voicelineType\": \"71109\", \"unlockConditions\": [{\"paramList\": [15016], \"unlockText\": \"完成「祈祝福愿，倾告嵴锋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_01\", \"description\": \"…喝！\", \"voicelineId\": 1062, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_02\", \"description\": \"…哈！\", \"voicelineId\": 1063, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_03\", \"description\": \"风刃！\", \"voicelineId\": 1064, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_rock_01\", \"description\": \"喝！\", \"voicelineId\": 1065, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_rock_02\", \"description\": \"落！\", \"voicelineId\": 1066, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_rock_03\", \"description\": \"荒星！\", \"voicelineId\": 1067, \"voicelineType\": \"100006\"}, {\"title\": \"元素战技·其七\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_thunder_01\", \"description\": \"哈！\", \"voicelineId\": 1068, \"voicelineType\": \"100007\"}, {\"title\": \"元素战技·其八\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_thunder_02\", \"description\": \"接招！\", \"voicelineId\": 1069, \"voicelineType\": \"100008\"}, {\"title\": \"元素战技·其九\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_thunder_03\", \"description\": \"紫影！\", \"voicelineId\": 1070, \"voicelineType\": \"100009\"}, {\"title\": \"元素战技·其十\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_dendro_01\", \"description\": \"哈！\", \"voicelineId\": 1126, \"voicelineType\": \"100010\"}, {\"title\": \"元素战技·其十一\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_dendro_02\", \"description\": \"散！\", \"voicelineId\": 1127, \"voicelineType\": \"100011\"}, {\"title\": \"元素战技·其十二\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_dendro_03\", \"description\": \"蔓延！\", \"voicelineId\": 1128, \"voicelineType\": \"100012\"}, {\"title\": \"元素战技·其十三\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_hydro_01\", \"description\": \"哈！\", \"voicelineId\": 1157, \"voicelineType\": \"100013\"}, {\"title\": \"元素战技·其十四\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_hydro_02\", \"description\": \"逐！\", \"voicelineId\": 1158, \"voicelineType\": \"100014\"}, {\"title\": \"元素战技·其十五\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_hydro_03\", \"description\": \"漩击！\", \"voicelineId\": 1159, \"voicelineType\": \"100015\"}, {\"title\": \"元素战技·其十六\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_pyro_01\", \"description\": \"哈！\", \"voicelineId\": 1220, \"voicelineType\": \"100016\"}, {\"title\": \"元素战技·其十七\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_pyro_02\", \"description\": \"纵燃！\", \"voicelineId\": 1221, \"voicelineType\": \"100017\"}, {\"title\": \"元素战技·其十八\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_pyro_03\", \"description\": \"闪灼！\", \"voicelineId\": 1222, \"voicelineType\": \"100018\"}, {\"title\": \"元素战技·其十九\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_pyro_04\", \"description\": \"哈——！\", \"voicelineId\": 1223, \"voicelineType\": \"100019\"}, {\"title\": \"元素战技·其二十\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_pyro_05\", \"description\": \"束火！\", \"voicelineId\": 1224, \"voicelineType\": \"100020\"}, {\"title\": \"元素战技·其二十一\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill1_pyro_06\", \"description\": \"铸光！\", \"voicelineId\": 1225, \"voicelineType\": \"100021\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_01\", \"description\": \"嘿——\", \"voicelineId\": 1071, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_02\", \"description\": \"消失吧。\", \"voicelineId\": 1072, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_03\", \"description\": \"随风而去吧。\", \"voicelineId\": 1073, \"voicelineType\": \"200003\"}, {\"title\": \"元素爆发·其四\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_rock_01\", \"description\": \"哈——！\", \"voicelineId\": 1074, \"voicelineType\": \"200004\"}, {\"title\": \"元素爆发·其五\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_rock_02\", \"description\": \"震颤吧！\", \"voicelineId\": 1075, \"voicelineType\": \"200005\"}, {\"title\": \"元素爆发·其六\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_rock_03\", \"description\": \"化为尘埃吧。\", \"voicelineId\": 1076, \"voicelineType\": \"200006\"}, {\"title\": \"元素爆发·其七\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_thunder_01\", \"description\": \"喝——！\", \"voicelineId\": 1077, \"voicelineType\": \"200007\"}, {\"title\": \"元素爆发·其八\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_thunder_02\", \"description\": \"轰鸣吧！\", \"voicelineId\": 1078, \"voicelineType\": \"200008\"}, {\"title\": \"元素爆发·其九\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_thunder_03\", \"description\": \"天雷鼓音！\", \"voicelineId\": 1079, \"voicelineType\": \"200009\"}, {\"title\": \"元素爆发·其十\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_dendro_01\", \"description\": \"哈！\", \"voicelineId\": 1129, \"voicelineType\": \"200010\"}, {\"title\": \"元素爆发·其十一\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_dendro_02\", \"description\": \"萌发吧！\", \"voicelineId\": 1130, \"voicelineType\": \"200011\"}, {\"title\": \"元素爆发·其十二\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_dendro_03\", \"description\": \"新蕾破土！\", \"voicelineId\": 1131, \"voicelineType\": \"200012\"}, {\"title\": \"元素爆发·其十三\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_hydro_01\", \"description\": \"哈！\", \"voicelineId\": 1160, \"voicelineType\": \"200013\"}, {\"title\": \"元素爆发·其十四\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_hydro_02\", \"description\": \"涤荡吧！\", \"voicelineId\": 1161, \"voicelineType\": \"200014\"}, {\"title\": \"元素爆发·其十五\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_hydro_03\", \"description\": \"奔流飞去！\", \"voicelineId\": 1162, \"voicelineType\": \"200015\"}, {\"title\": \"元素爆发·其十六\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_pyro_01\", \"description\": \"哈！\", \"voicelineId\": 1226, \"voicelineType\": \"200016\"}, {\"title\": \"元素爆发·其十七\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_pyro_02\", \"description\": \"启明吧！\", \"voicelineId\": 1227, \"voicelineType\": \"200017\"}, {\"title\": \"元素爆发·其十八\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_battle_skill3_pyro_03\", \"description\": \"逐示曜焰！\", \"voicelineId\": 1228, \"voicelineType\": \"200018\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_chest_open_01\", \"description\": \"这个世界，也在回应我吗？\", \"voicelineId\": 1080, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_chest_open_02\", \"description\": \"旅途中的收获。\", \"voicelineId\": 1081, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_chest_open_03\", \"description\": \"我会好好保存。\", \"voicelineId\": 1082, \"voicelineType\": \"300003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_life_less30_teammate_01\", \"description\": \"等等…让我来吧！\", \"voicelineId\": 1083, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_life_less30_teammate_02\", \"description\": \"当心！\", \"voicelineId\": 1084, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_life_die_01\", \"description\": \"这…不是终点…\", \"voicelineId\": 1085, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_hero/vo_hero_life_die_02\", \"description\": \"世界…拒绝了我？\", \"voicelineId\": 1086, \"voicelineType\": \"500002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_hero_teamJoin_01\", \"description\": \"这次又会遇见什么？\", \"voicelineId\": 1087, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_hero_teamJoin_02\", \"description\": \"世界，充满未解之谜…\", \"voicelineId\": 1088, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_hero_teamJoin_03\", \"description\": \"要做的事，还有很多。\", \"voicelineId\": 1089, \"voicelineType\": \"600003\", \"voicefile_male\": \"VO_teamJoin/vo_hero_teamJoin_03\", \"hasGenderedVoicefile\": true}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000006, 'Lisa', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_draw_appear\", \"description\": \"嗨，小可爱，你是新来的助理吗？啊？魔导师大人？那是很久以前的事啦，现在的我不过是一介图书管理员而已。放心吧，姐姐会照顾好你的。那么…\", \"voicelineId\": 5100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·下午茶\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_explore_idle_01\", \"description\": \"明明是该喝下午茶的时间。\", \"voicelineId\": 5101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·任务\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_explore_idle_02\", \"description\": \"任务是做不完的，还不如陪姐姐…聊会儿天。\", \"voicelineId\": 5102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·不宜出门\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_explore_idle_03\", \"description\": \"今天不宜出门…欸，我昨天也是这么说的？\", \"voicelineId\": 5103, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_weather_heavyRain_01\", \"description\": \"这种天气，泡一杯茶，坐着看雨多好。\", \"voicelineId\": 5104, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_weather_thunder_01\", \"description\": \"在雷雨天训练事半功倍哦~呵呵，骗你的。\", \"voicelineId\": 5105, \"voicelineType\": \"1202\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_weather_breezy_01\", \"description\": \"天气真好，能躺下来补个觉就更好了。\", \"voicelineId\": 5106, \"voicelineType\": \"1203\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_greetingMorning\", \"description\": \"啊…早安，琴。嗯？不好意思，我看错了。\", \"voicelineId\": 5107, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_greetingNoon\", \"description\": \"午休时间到了…\", \"voicelineId\": 5108, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_greetingNight\", \"description\": \"你还不睡吗？我已经困了呢…\", \"voicelineId\": 5109, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_greetingNight2\", \"description\": \"你努力的样子，姐姐全都见到了哦。嗯…让我想想，给你什么奖励吧…\", \"voicelineId\": 5110, \"voicelineType\": \"1004\"}, {\"title\": \"关于丽莎自己…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_idle\", \"description\": \"这可不是偷懒呀。谁不想用最省力的方法达到目的呢？\", \"voicelineId\": 5111, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·关系\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_close1\", \"description\": \"你想把我当作你的老师、前辈，还是朋友？都可以哦。\", \"voicelineId\": 5112, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·本领\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_close2\", \"description\": \"哎呀，再不拿出点真本事出来，就对不起你的努力了吧。嗯哼…也好也好。\", \"voicelineId\": 5113, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·仪式\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_close3\", \"description\": \"再等一下，「将悔罪的记号吻在弟子的前额」…好了，那么仪式就完成了~今后你就是我丽莎的首席弟子了哟。\", \"voicelineId\": 5114, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_pendant\", \"description\": \"「神之眼」啊…那可是导引元素力所必要的装置呢。唯独在你身上却是例外。唔…究竟是什么原理呢，啊，有了，你…有空陪姐姐做个实验么？\", \"voicelineId\": 5115, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_share\", \"description\": \"图书馆楼上的炼金工坊，可以随意使用哦？不过进去之前记得敲门，如果撞见什么不该见到的东西那就麻烦了。\", \"voicelineId\": 5116, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_pref_gift\", \"description\": \"嘟嘟莲是有着解毒功效的药草。有了它，就不用再担心魔药的副作用了…哼哼。\", \"voicelineId\": 5117, \"voicelineType\": \"3003\"}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_qin_01\", \"description\": \"琴是个称职的好团长。看到她认真工作的样子，就连我也忍不住想要多帮她一把。\", \"voicelineId\": 5118, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_ambor_01\", \"description\": \"小安柏刚进骑士团的样子我还记得呢，一转眼都那么能干了。啊，再过几年，又会变成什么样呢？\", \"voicelineId\": 5119, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芭芭拉…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_barbara_01\", \"description\": \"芭芭拉的歌，你听过么？哼哼，听说她的旋律里有种治愈的魔力在流动喔。和我的魔药相比，不知道哪边更合你的胃口呢？\", \"voicelineId\": 5120, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_diluc_01\", \"description\": \"哦，想听迪卢克的故事？哈哈，那我知道一个更好的聊天对象。\", \"voicelineId\": 5121, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷泽…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_razor_01\", \"description\": \"小狼狼，来来，过来这边。今天就临时来一场实战练习吧，对手我已经给你找好了哟。欸？怎么跑了，真是的…\", \"voicelineId\": 5122, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_klee_01\", \"description\": \"上次小可莉想借用我的工坊做实验，被我拒绝了，她可是生了我一天的气呢。嗯？你问第二天？第二天，她当然又高高兴兴地出门去玩了。\", \"voicelineId\": 5123, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莫娜…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_mona_01\", \"description\": \"莫娜？似乎是一位很优秀的魔导师小姐呢。但我并不是她们「魔女会」的成员哦。古树考察，组织茶会，一听就是麻烦的事情吧。\", \"voicelineId\": 5124, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_albedo_01\", \"description\": \"姐姐我觉得，阿贝多是很优秀的炼金术士。跟他只需要用三言两语，就能得到不错的结论。而且脸也长得好看。和小可爱你很像喔，嗯。\", \"voicelineId\": 5125, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲谢尔…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_fischl_01\", \"description\": \"菲谢尔…哦，那个总是来图书馆借幻想小说的女孩子。每次还书都会提前三天，对书籍也十分爱护，是个好孩子呢。\", \"voicelineId\": 5126, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于诺艾尔…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_noel_01\", \"description\": \"拜托诺艾尔清扫书架的时候，总感觉这孩子，越是疲惫就越开心，嗯…到底是怎么回事呢？\", \"voicelineId\": 5127, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于砂糖…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_sucrose_01\", \"description\": \"没事就不要去打扰小砂糖哦，会吓到她的。呵呵，她擅长和各种各样的生物打交道，却唯独，不怎么善于和人类相处呢。\", \"voicelineId\": 5128, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_cyno_01\", \"description\": \"离开须弥之后，除了和恩师保持礼节性的通信，我和教令院已经没有什么往来了。幸好，不是每位被寄予了重望的弟子，都像我一样怠惰…听说那位师弟赛诺就相当活跃呢。\", \"voicelineId\": 5171, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于柯莱…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_collei_01\", \"description\": \"小柯莱每次写信都会使用新词，尝试与之前不同的表述方式。呵呵，也难怪她进步得那么快。除了自己的努力之外，她那位善良而又热忱的师父，一定也给予了很多帮助吧。\", \"voicelineId\": 5172, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于米卡…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_teammate_mika_01\", \"description\": \"真羡慕霍夫曼先生有这样一位擅长照顾人的弟弟。不仅帮着打点生活起居，连喝醉后的护理也无微不至。啊，我也好想什么都不用操心，懒洋洋地度过每一天啊…嗯？你说我现在也差不多？哼，小可爱…胆子变大了嘛。\", \"voicelineId\": 5173, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解丽莎·其一\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_friendship_01\", \"description\": \"那么，今天想学习哪种元素力的知识呢？\", \"voicelineId\": 5129, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解丽莎·其二\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_friendship_02\", \"description\": \"我的过去？嗯？想要更多地了解我一些吗？…可今天我恰巧有点累了。不过这份心意，姐姐我还是很高兴的。\", \"voicelineId\": 5130, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解丽莎·其三\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_friendship_03\", \"description\": \"我教雷泽掌握元素力量的时候，完全没想到那个孩子的悟性有那么好。仔细想想的话，你也相当能干啊，小可爱。\", \"voicelineId\": 5131, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解丽莎·其四\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_friendship_04\", \"description\": \"什么？想学习须弥教令院的魔法？可对现在的你来说，负担会有些重…啊？至少想学会入门的知识？那先看完这本《绪论》吧，也就800多页而已。\", \"voicelineId\": 5132, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解丽莎·其五\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_friendship_05\", \"description\": \"总有一天，这「眼」中的力量会毁灭一切的吧…到了那时，如果有你在的话…啊，没什么。\", \"voicelineId\": 5133, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"丽莎的爱好…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_pref_hobby\", \"description\": \"小可爱，你想要来挑一瓶神奇的药水么？喝下去之前完全不知道会有什么效果，呼呼。\", \"voicelineId\": 5134, \"voicelineType\": \"6001\"}, {\"title\": \"丽莎的烦恼…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_dialog_annoyed\", \"description\": \"二楼的审讯大厅已经闲置两年了，明明给我用作元素工坊的话，就不至于那么荒废…赫塔小姐真是死脑筋。\", \"voicelineId\": 5135, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_pref_foodLike\", \"description\": \"我喜欢蔬菜汤哦。只要把所有的蔬菜全都丢进一口大锅子里，再用长柄的勺子搅一搅…欸，问我好不好吃？哼哼，来，啊——\", \"voicelineId\": 5136, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_pref_foodDislike\", \"description\": \"我有南瓜恐惧症，每年的秋收节对我来说都太煎熬了。啊，要不要干脆把南瓜这个物种，彻底抹除呢？\", \"voicelineId\": 5137, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_spice_pref_01\", \"description\": \"真贴心呢，小可爱。姐姐我很满意哦。\", \"voicelineId\": 5168, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_spice_normal_01\", \"description\": \"呵呵，你很擅长做这些呢。\", \"voicelineId\": 5169, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_spice_dislike_01\", \"description\": \"哎呀…这可真是…\", \"voicelineId\": 5170, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_pref_birthday\", \"description\": \"来，拿着，护身符，就作为生日礼物送给你了。虽然制作起来花了我不少时间…不许弄丢哦。\", \"voicelineId\": 5138, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_starUp_01\", \"description\": \"该不会想让我加班吧…那可不好哦。\", \"voicelineId\": 5139, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_starUp_02\", \"description\": \"锻炼的机会，应该多留给新人，不是吗？\", \"voicelineId\": 5140, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_starUp_03\", \"description\": \"…要是我恢复全盛状态的话，说不定会发生什么不得了的大事哟。\", \"voicelineId\": 5141, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_lisa/vo_lisa_starUp_04\", \"description\": \"明明已经用各种方法劝过你了…真有你的，小可爱。到这份上还装作无动于衷的话，恐怕连丘丘人都看得出来我在撒谎了。那就让你见识一下，「蔷薇魔女」的真实吧。\", \"voicelineId\": 5142, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_skill1_01\", \"description\": \"哼哼。\", \"voicelineId\": 5143, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_skill1_02\", \"description\": \"该电一电了。\", \"voicelineId\": 5144, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_skill1_03\", \"description\": \"别逃哟。\", \"voicelineId\": 5145, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_skill1_04\", \"description\": \"…Blitz！\", \"voicelineId\": 5146, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_skill1_05\", \"description\": \"这是…惩罚哦！\", \"voicelineId\": 5147, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_skill1_06\", \"description\": \"…呵呵~\", \"voicelineId\": 5148, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_skill3_01\", \"description\": \"酥酥麻麻的哟。\", \"voicelineId\": 5149, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_skill3_02\", \"description\": \"快点投降吧。\", \"voicelineId\": 5150, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_skill3_03\", \"description\": \"可别上瘾喔。\", \"voicelineId\": 5151, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_chest_open_01\", \"description\": \"努力，获得回报了哟。\", \"voicelineId\": 5152, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_chest_open_02\", \"description\": \"我也来兴致了…\", \"voicelineId\": 5153, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_chest_open_03\", \"description\": \"小可爱会喜欢吗？\", \"voicelineId\": 5154, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_life_less30_01\", \"description\": \"有你的嘛。\", \"voicelineId\": 5155, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_life_less30_02\", \"description\": \"有点生疏了呀…\", \"voicelineId\": 5156, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_life_less30_03\", \"description\": \"哎呀，手套要破了呢。\", \"voicelineId\": 5157, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_life_less30_teammate_01\", \"description\": \"逞强可不好。\", \"voicelineId\": 5158, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_life_less30_teammate_02\", \"description\": \"要姐姐帮忙吗？\", \"voicelineId\": 5159, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_life_die_01\", \"description\": \"出门好累…\", \"voicelineId\": 5160, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_life_die_02\", \"description\": \"看来我大意了呢…\", \"voicelineId\": 5161, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_life_die_03\", \"description\": \"果然不该出门的…\", \"voicelineId\": 5162, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_hit_L_01\", \"description\": \"疼…\", \"voicelineId\": 5163, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_lisa/vo_lisa_battle_hit_H_01\", \"description\": \"不要那么粗暴。\", \"voicelineId\": 5164, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_lisa_teamJoin_01a\", \"description\": \"让姐姐帮帮你吧。\", \"voicelineId\": 5165, \"voicelineType\": \"600001\", \"voicefile_male\": \"VO_teamJoin/vo_lisa_teamJoin_01b\", \"hasGenderedVoicefile\": true}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_lisa_teamJoin_02\", \"description\": \"我会看着你的。\", \"voicelineId\": 5166, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_lisa_teamJoin_03\", \"description\": \"要出门了吗？\", \"voicelineId\": 5167, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000007, 'Lumine', '[{\"title\": \"关于风车…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_windmill_heroine\", \"description\": \"派蒙：蒙德有很多风车呢。\\n{NICKNAME}：因为蒙德城建在水平面的上方，所以是靠风车把水抽上来的吧。\\n派蒙：回答正确！蒙德四季风吹不断，所以水源的供应也很稳定。\\n派蒙：而且，风车就是所谓「看得见的风」吧——然后，风铃就是「听得见的风」。\\n派蒙：也算是一种祈求风神护佑的吉祥物啦。\\n{NICKNAME}：原来如此，和派蒙一样是吉祥物啊。\\n派蒙：不一样！风车是用木头做的，不能当应急食品，只能用来磨牙啊！\\n{NICKNAME}：嗯…\\n{NICKNAME}：…我该接话吗？\", \"voicelineId\": 2001, \"voicelineType\": \"24001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于酒馆老板…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_pubHolder_heroine\", \"description\": \"{NICKNAME}：我听说，收了可观的小费以后，酒馆老板会小声说出一些情报。\\n派蒙：是「天使的馈赠」吗？但那位迪卢克老爷，好像是非常有钱的人。\\n派蒙：究竟要多少小费，才能让老板觉得「可观」呢？\\n{NICKNAME}：唔…那也许是我记错了吧。\\n{NICKNAME}：也许这个传言，是在别的世界听到的…\\n派蒙：你去过的世界真的很多呢。\", \"voicelineId\": 2002, \"voicelineType\": \"25001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于果酒湖…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_ciderLake_heroine\", \"description\": \"派蒙：果酒湖是不冻湖，一整年里都不会结冰。\\n派蒙：蒙德最好的苹果酒，只能用这座湖里的甜水来酿。\\n派蒙：湖水真的很好喝！我一秒就能喝掉两大瓶。\\n{NICKNAME}：真是惊人。\\n派蒙：哼哼。\\n{NICKNAME}：派蒙这样的体型，喝这么多水…\\n{NICKNAME}：居然不会像风史莱姆那样，炸到漏气满天飞…\\n派蒙：哼哼，装好喝的饮料的是另一个胃。\\n{NICKNAME}：嗯…世界真是广大，需要花时间去思考的见闻，还有很多…\", \"voicelineId\": 2003, \"voicelineType\": \"26001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于禁书区的书…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_restrictedSection_heroine\", \"description\": \"{NICKNAME}：丽莎提到过的，那些「禁书区」的书…\\n{NICKNAME}：你有没有好奇过？什么样的书会被放在禁书区里呢？\\n{NICKNAME}：莫非…\\n{NICKNAME}：会有那种不适合小孩子看的书…？\\n派蒙：什么？明明《野猪公主》都不在禁书区的！\\n派蒙：还有比那本更不适合小孩子看的书吗？派蒙开始好奇了！\", \"voicelineId\": 2004, \"voicelineType\": \"37001\", \"unlockConditions\": [{\"paramList\": [1010115], \"unlockText\": \"完成「麻烦的工作」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于努力与回报…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_effortsVSreturn_heroine\", \"description\": \"派蒙：我发现，在蒙德努力工作不一定会有回报呢。\\n{NICKNAME}：为什么这么说？\\n派蒙：你看西风骑士的霍夫曼先生，每天尽职尽责…\\n派蒙：可那位总是很轻松悠闲的凯亚先生，却是他的上司。\\n{NICKNAME}：嗯…可是最辛苦的琴，当上了代理团长呀？\\n派蒙：那、那论地位来讲的话…\\n派蒙：最懒散的温迪，还是整个蒙德城的神明呢！\", \"voicelineId\": 2005, \"voicelineType\": \"31001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于歌德大酒店…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_gothHotel_heroine\", \"description\": \"{NICKNAME}：想住一次歌德大酒店…\\n派蒙：我也是！\\n派蒙：里面的房间一定又干净又大吧。\\n{NICKNAME}：不过听歌德老伯说，愚人众搬进去以后，出现了各种奇怪的问题。\\n{NICKNAME}：雷萤术士提进去的雷萤，因为静电吸了好多灰，死了不少。\\n{NICKNAME}：然后，因为雾虚花粉和胡椒弄错了…\\n{NICKNAME}：「债务处理人」互相指责对方欠过自己酒钱，引发了斗殴。\\n派蒙：…加油啊，歌德大酒店。\", \"voicelineId\": 2006, \"voicelineType\": \"56001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于风的流向…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_windDirection_heroine\", \"description\": \"{NICKNAME}：人们都说，蒙德是风的国度。\\n{NICKNAME}：可是，我还不知道这个季节盛行的风向，是哪个方位呢。\\n派蒙：不如我们去问问温迪吧。\\n{NICKNAME}：他对这种问题，只会「欸嘿」一声敷衍过去吧…\\n派蒙：说得也是。风神只是一个卖唱的而已，懂什么风…\", \"voicelineId\": 2007, \"voicelineType\": \"64001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于炼金术…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_alchemy_heroine\", \"description\": \"{NICKNAME}：原来蒙德的炼金工作台是在街头开放的。\\n派蒙：是呀，很奇怪吗？\\n{NICKNAME}：我曾经去过的许多世界里，炼金术都是作为秘术存在的。\\n{NICKNAME}：看到炼金术成为日常的一部分，就像看到「三胃人」的世界一样奇怪…\\n派蒙：喂！人只有一个胃才会奇怪吧！\\n{NICKNAME}：嗯…\\n{NICKNAME}：你是认真的吗？\\n派蒙：嘿嘿，你猜！\", \"voicelineId\": 2008, \"voicelineType\": \"66001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提瓦特…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_teyvat_heroine\", \"description\": \"{NICKNAME}：提瓦特大陆的昼夜，好像都特别短暂。\\n{NICKNAME}：这里的夜空也布满了星星。不过，跟故乡看到的不同。\\n{NICKNAME}：提瓦特人的命运，会不会也与他们的星座有关呢？\\n派蒙：哦？你也懂「观星」吗？真好啊，须弥国以外很少有人会这种技巧呢。\\n派蒙：我的好奇心被点燃了！快，给我占卜一下！\\n{NICKNAME}：嗯…\\n{NICKNAME}：派蒙围巾上的夜空…流转着群星与深海之光…\\n{NICKNAME}：星的纹路，告诉我说，在未来…七天之内…\\n派蒙：七天之内…？\\n{NICKNAME}：可能有好事…或者坏事…或者不好不坏的事发生…\\n派蒙：嗯…你这个回答平稳得像岩史莱姆一样啊！\", \"voicelineId\": 2009, \"voicelineType\": \"11001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「自由」之神…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_godOfFreedom_heroine\", \"description\": \"{NICKNAME}：我们救回特瓦林之后，在回蒙德的路上…\\n{NICKNAME}：第一次见到了「尘世七执政」的面目呢。原来是这样的神…\\n派蒙：嗯？我们认识温迪，不是已经很久了吗？\\n{NICKNAME}：我是指…他作为风神巴巴托斯的那一面。\\n{NICKNAME}：在吟游诗人的躯壳之下，藏着真实的神灵。\\n{NICKNAME}：「被自由之神命令的自由，还能称之为自由吗？」\\n{NICKNAME}：他问特瓦林的这个问题，我也还在思考答案…\", \"voicelineId\": 2010, \"voicelineType\": \"67001\", \"unlockConditions\": [{\"paramList\": [39604], \"unlockText\": \"完成「巨龙与自由之歌」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于蒙德的地形…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_monstadtTerrain_heroine\", \"description\": \"派蒙：蒙德这边的地形，平原和丘陵是很多的。\\n派蒙：据说是巴巴托斯改造天地时，用暴风削平了陡峭的山崖和峡湾…\\n{NICKNAME}：不过，没修整完的地方也还是有的。\\n派蒙：比如摘星崖？\\n{NICKNAME}：没错。\\n{NICKNAME}：这就好像是…做模型时懒得磨平的水口一样吧。\\n派蒙：水口？那是什么？\", \"voicelineId\": 2011, \"voicelineType\": \"69001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于对联…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_couplet_heroine\", \"description\": \"派蒙：听说对联是璃月的传统文化，有人写完上联以后，会为下联悬赏千金！\\n派蒙：但因为对联很难，钱也不是那么好赚的。\\n派蒙：不仅要求字数相等，还要考虑词性相对…\\n{NICKNAME}：嗯，举一个例子呢？\\n派蒙：嗯...「风起地风不起」。\\n{NICKNAME}：…唔，「云来海云再来」。\\n派蒙：唔！\\n派蒙：别坐着了，快点起来，快点起来！我们该赚钱去了！\", \"voicelineId\": 2012, \"voicelineType\": \"47001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「不要玩吃的，也不要玩钱」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_moneyAdmonishment_heroine\", \"description\": \"派蒙：璃月港流传着一条岩王帝君的训诫，大概的意思是「不要玩钱」。\\n派蒙：因为最初的「摩拉」是他信任人类，才用黄金之体舍肉铸造的。\\n{NICKNAME}：凯亚好像一直在玩钱…\\n派蒙：所以千万不要学他。\\n{NICKNAME}：我记得还有谁告诫过，不要玩食物。\\n派蒙：是的是的。要对做好的食物抱有敬畏之心。\\n派蒙：…你，你看着我干什么？\", \"voicelineId\": 2013, \"voicelineType\": \"59001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于《碎梦奇珍》…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_heartsDesire_heroine\", \"description\": \"派蒙：顺时针走七圈，逆时针走七圈，再睁开眼睛…\\n{NICKNAME}：你在梦游吗？\\n派蒙：才没有呢！我只是想看看《碎梦奇珍》里的那家古董店，是不是真的存在！\\n{NICKNAME}：假如故事里的古董店真的存在，派蒙想要买什么宝物呢？\\n派蒙：史莱姆生成器！\\n{NICKNAME}：真的会存在那种东西吗…\", \"voicelineId\": 2014, \"voicelineType\": \"62001\", \"unlockConditions\": [{\"paramList\": [3, 128], \"unlockText\": \"解锁「璃月 璃月港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于古华派…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_guhuaClan_heroine\", \"description\": \"{NICKNAME}：最近，听古华派的弟子讲了这样一个故事。\\n派蒙：古华派吗，应该是很侠义的故事吧。\\n{NICKNAME}：几位师兄弟想要通过比武，定下师妹的亲事，师妹也很赞成这么做。\\n派蒙：在璃月叫「比武招亲」吧？我听说过！\\n{NICKNAME}：可比武前一晚，师妹将大师兄最顺手的那柄剑偷走了。\\n派蒙：那师兄可真惨…是师妹有意想要他输的呀…\\n{NICKNAME}：是啊，后来大师兄用了十分不顺手的剑，惨遭落败。\\n{NICKNAME}：他难以接受这样的结局，跪在地上痛哭流涕。\\n派蒙：可怜的人…他一定很喜欢那个师妹吧？\\n{NICKNAME}：最终，他不得不在众人的见证下…迎娶了师妹。\\n派蒙：原来是输的人娶吗？！\", \"voicelineId\": 2015, \"voicelineType\": \"32001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荻花洲…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_dihuaMarsh_heroine\", \"description\": \"派蒙：你知道吗？荻花洲的荻叶，是常见的造纸材料。\\n派蒙：用荻杆实心的一端做笔、空心的一端做笛，在璃月也是一件很风雅的事。\\n派蒙：千百年来，有许多侠客与剑士，都会选在这个风雅的地方对决。\\n派蒙：荻花越多就越风雅，但它们长势最茂盛的地方，有时水会很深…\\n派蒙：所以，决斗声势浩大、最终却双双失足溺死的倒霉侠客…其实还挺多的。\\n{NICKNAME}：从这个故事里我们能学到什么呢？\\n派蒙：不要打架！\", \"voicelineId\": 2016, \"voicelineType\": \"29001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「君子鸟」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_crane_heroine\", \"description\": \"派蒙：据说在璃月，人们把鹤叫做「君子鸟」。\\n{NICKNAME}：这是为什么呢？\\n派蒙：唔…这个，我也不太清楚…\\n{NICKNAME}：那么，我来给你讲一个「仙鹤报恩」的故事吧。\\n{NICKNAME}：很久很久以前，有一个善良的书生，解救了一只落入陷阱的仙鹤。\\n{NICKNAME}：后来，在一个非常寒冷的夜晚，有一位美丽的姑娘前来借宿。\\n{NICKNAME}：姑娘背着一把重剑，把剑法传授给了书生，督促他日夜练习。\\n派蒙：咦？\\n{NICKNAME}：书生剑术大成以后，就与姑娘一起投身江湖，行侠仗义。\\n{NICKNAME}：十年以后，仙鹤所化的君子终于前来报恩，但那对侠侣却已经退隐江湖…\\n{NICKNAME}：这就是「君子报恩，十年太晚」的故事。\\n派蒙：嗯？\", \"voicelineId\": 2017, \"voicelineType\": \"28001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绝云间…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_jueyunKarst_heroine\", \"description\": \"{NICKNAME}：据说绝云间是仙人的居住地。\\n派蒙：哇——仙人的居住地！\\n{NICKNAME}：说不定在高耸入云的山顶，能遇到仙人呢。\\n派蒙：哇——遇到仙人！\\n{NICKNAME}：但是，仙人平时该怎么交流呢？\\n派蒙：哇——怎么交流呢！\\n{NICKNAME}：嗯？这个应急食品快要坏掉了吗？该抓紧吃掉了…\\n派蒙：咳、咳咳。嗯…在山头呼喊的话，就能交流了吧。\\n{NICKNAME}：比起仙人，这更像是丘丘人的行为吧…\", \"voicelineId\": 2018, \"voicelineType\": \"43001\", \"unlockConditions\": [{\"paramList\": [3, 72], \"unlockText\": \"解锁「璃月 荻花洲」七天神像-岩\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「契约」之神…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_godOfContract_heroine\", \"description\": \"{NICKNAME}：没想到，岩神居然与冰神签订了「契约」。\\n{NICKNAME}：契约的内容，究竟会是什么呢…\\n派蒙：派蒙觉得，不管是谁，要和「冰之女皇」做交易，都很不安全！\\n{NICKNAME}：确实是这样…\\n{NICKNAME}：但既然摩拉克斯是所有神灵里，最理解「契约」本质的那一位…\\n{NICKNAME}：他应该不会没有考虑过这件事。\\n派蒙：嗯，摩拉克斯本人好像很有自信，叫它「终结一切契约的契约」…\\n{NICKNAME}：我们最终会见证真相…和结局的。\", \"voicelineId\": 2019, \"voicelineType\": \"68001\", \"unlockConditions\": [{\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于璃月的神谕…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_divinePrediction_heroine\", \"description\": \"派蒙：说起来，岩王爷虽然喜欢微服私访，但正式降临却只有一年一次。\\n派蒙：其他神好像都不是这样的，岩王爷是有什么深意吗？\\n{NICKNAME}：我大概能猜到一点原因…\\n{NICKNAME}：你看，现在每年降下的那些神谕，已经牵动了太多璃月人的心。\\n{NICKNAME}：他们围着神谕打转，试图从字缝里分析出无限的「潜台词」…\\n{NICKNAME}：如果那样的神谕每天都有，璃月又会变成什么样呢？\\n派蒙：啊！\\n派蒙：我明白了。如果是我的话，一定会收集岩王爷在民间夸赞过的小吃，天天供奉给他！\\n派蒙：如果能直接从摩拉克斯那里得到摩拉的话，谁还会去做正经生意啊！\\n{NICKNAME}：虽然例子的逻辑有点跳跃，但…道理大致就是这样。\", \"voicelineId\": 2020, \"voicelineType\": \"70001\", \"unlockConditions\": [{\"paramList\": [101801], \"unlockText\": \"完成「浮世浮生千岩间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于班尼冒险团…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_bennysAdventureTeam_heroine\", \"description\": \"派蒙：如果要和「班尼冒险团」合作探索秘境，就一定要做好准备。\\n派蒙：秘境是很危险的，出发前要多检查几遍物资和工具，不能大意。\\n派蒙：我听说在这些秘境里，光是冒险家协会统计过的死法，就有四百六十三种…\\n派蒙：如果班尼特不小心害死了你，我和他的良心都会很不安的！\\n{NICKNAME}：…为什么死的只有我？\\n派蒙：嗯，根据统计，因为我会飞，所以可以至少免疫其中的三百二十二种死法！\\n{NICKNAME}：我忽然不太想去秘境探险了…\", \"voicelineId\": 2021, \"voicelineType\": \"27001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于班尼特…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_bennett_heroine\", \"description\": \"{NICKNAME}：我听说，艾伯特先生作为芭芭拉粉丝团的团长…\\n{NICKNAME}：经常故意弄出些磕磕碰碰的伤，就为了去教堂见芭芭拉一面。\\n派蒙：我觉得西风骑士团需要重点关注这种家伙。\\n{NICKNAME}：可是一个月下来，艾伯特发现…跟芭芭拉见面的次数，被班尼特远远超越了。\\n{NICKNAME}：毕竟在受伤方面，班尼特有天然的优势…\\n派蒙：这是什么「给芭芭拉小姐添麻烦」的比赛吗！\", \"voicelineId\": 2022, \"voicelineType\": \"34001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于偶像…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_idol_heroine\", \"description\": \"派蒙：芭芭拉很受大家欢迎呢。\\n{NICKNAME}：毕竟是蒙德的大众偶像嘛。\\n派蒙：说起来我一直没太懂…「偶像」是什么呀？\\n{NICKNAME}：是一种职业，只需要负责可爱，就可以受大家喜欢，赚好多摩拉呢。\\n派蒙：和吉祥物差不多嘛。\\n{NICKNAME}：呃，也可以这么说吧…\", \"voicelineId\": 2023, \"voicelineType\": \"61001\", \"unlockConditions\": [{\"paramList\": [39604], \"unlockText\": \"完成「巨龙与自由之歌」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于姐妹关系…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_sisters_heroine\", \"description\": \"{NICKNAME}：丽莎和安柏的关系，有点像姐妹。\\n派蒙：咦，为什么？\\n{NICKNAME}：安柏经常帮丽莎跑腿。姐姐为了偷懒，要求妹妹帮忙跑腿，是很常见的事…\\n{NICKNAME}：不过我和哥哥因为同年，所以就只能猜拳决定了。\\n派蒙：呜哇，这么说来，那你就是我的妹妹了！\\n{NICKNAME}：为什么？\\n派蒙：我会「飞」啊，实际上「跑腿」的只有你一个人哦！\\n{NICKNAME}：啊？\", \"voicelineId\": 2024, \"voicelineType\": \"40001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚的眼罩…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_kaeyasPatch_heroine\", \"description\": \"{NICKNAME}：派蒙，你见过凯亚眼罩下面的样子吗？\\n派蒙：没见过呢。\\n{NICKNAME}：这么说来，凯亚似乎一年四季都不会摘下眼罩…\\n派蒙：哼哼，机智的派蒙已经猜到为什么了！\\n{NICKNAME}：嗯？\\n派蒙：肯定是要隐藏什么大秘密！\\n{NICKNAME}：大秘密？\\n派蒙：你看，凯亚外出的工作比较多。\\n派蒙：所以凯亚眼罩下的皮肤，肯定比周围的白一大圈。\\n{NICKNAME}：那如果摘下眼罩…\\n派蒙：肯定会被大家笑话的吧！然后被取奇怪的绰号！\\n派蒙：比如说——「花脸猫」！\\n{NICKNAME}：唔，他还没摘下眼罩，就已经被取了奇怪的绰号呢…\", \"voicelineId\": 2025, \"voicelineType\": \"41001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克与凯亚…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_dilucAndKaeya_heroine\", \"description\": \"派蒙：奇怪…\\n{NICKNAME}：怎么了？\\n派蒙：为什么迪卢克和凯亚明明是很相似的两个人，关系却不太好呢？\\n{NICKNAME}：他们哪里相似了？\\n派蒙：凯亚像是那种…会光明正大地耍阴招的人。\\n派蒙：迪卢克像是那种…在暗地里做光明正大的事的人。\\n派蒙：是不是很相似？\\n{NICKNAME}：我还是不知道相似在哪里。\", \"voicelineId\": 2026, \"voicelineType\": \"60001\", \"unlockConditions\": [{\"paramList\": [46618], \"unlockText\": \"完成「暗夜英雄的不在场证明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于战斗力单位…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_combatEffectiveness_heroine\", \"description\": \"{NICKNAME}：如果说一个丘丘人，能打三头野猪的话…\\n{NICKNAME}：琴团长和迪卢克老爷，分别有几丘丘战斗力呢？\\n派蒙：如果在蒙德城里体会过大家的统一口径，就应该知道，最厉害的是琴团长。\\n{NICKNAME}：我觉得迪卢克先出手的话，琴团长应该没办法化解。\\n派蒙：琴团长一定有办法的。\\n{NICKNAME}：肯定无解。\\n派蒙：琴团长的元素爆发是很强的。\\n{NICKNAME}：但那个「领域」，反过来会增强迪卢克。\\n派蒙：琴团长对付迪卢克老爷都不用「神之眼」。\\n{NICKNAME}：迪卢克只用「新手大剑」就…\\n派蒙：唉…\\n{NICKNAME}：唔…\\n{NICKNAME}：我们好无聊啊。\\n{NICKNAME}：他们都是为了蒙德而战的，不可能会打起来的。\\n派蒙：所以我觉得需要用丘丘人当战斗力单位啊。\\n派蒙：顺带一提，派蒙大概五分之一野猪哦。\", \"voicelineId\": 2027, \"voicelineType\": \"58001\", \"unlockConditions\": [{\"paramList\": [1020204], \"unlockText\": \"完成「真正的宝物」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷泽…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_razor_heroine\", \"description\": \"派蒙：{NICKNAME}，你知道毛笔吗？\\n{NICKNAME}：用动物的毛做成的笔，可以拿来写字？\\n派蒙：嗯，答对了！据说好的毛笔能在璃月商人那边卖出高价呢！\\n{NICKNAME}：所以派蒙也想做毛笔？\\n派蒙：嗯！但是野外的狼都太凶了，所以我们去薅雷泽的毛做毛笔吧！\\n派蒙：雷泽毛茸茸的，肯定能做出上好的狼毫笔！然后我们就能大赚一笔！\\n{NICKNAME}：这样做出来的笔肯定带电，没办法用吧。\\n{NICKNAME}：而且雷泽不是狼，狼毫笔也不是狼毛做的…\\n派蒙：欸——那为什么要叫做狼毫笔！\\n{NICKNAME}：你看果酒湖里不也没有果酒吗。\\n派蒙：喔——很有道理呢！\", \"voicelineId\": 2028, \"voicelineType\": \"33001\", \"unlockConditions\": [{\"paramList\": [45406], \"unlockText\": \"完成「卢皮卡的意义」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_klee_heroine\", \"description\": \"派蒙：可莉也是个很有意思的孩子呢。\\n派蒙：骑士团的大家都很喜欢她，说是团宠也不为过吧。\\n{NICKNAME}：派蒙和可莉…究竟哪一边比较强呢？\\n{NICKNAME}：啊，对了，派蒙不是吉祥物，派蒙是…\\n派蒙：哼，看到你张嘴就知道你准备说什么。这个笑话说太多次就不好笑了。\", \"voicelineId\": 2029, \"voicelineType\": \"57001\", \"unlockConditions\": [{\"paramList\": [1020204], \"unlockText\": \"完成「真正的宝物」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于传说中的万能女仆…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_noelle_heroine\", \"description\": \"派蒙：分享生活小智慧时间到！\\n{NICKNAME}：生活小智慧？\\n派蒙：在蒙德，如果有东西怎么修都修不好，或者怎么洗都洗不干净…\\n派蒙：遇到这种事，自己又处理不了的话，就可以对着天空大喊一声：\\n派蒙：「诺——艾——尔——！」\\n派蒙：所有的烦心事，就都会被马上解决啦。\\n{NICKNAME}：这就是蒙德人的生活小智慧吗？太棒了，学到许多…\", \"voicelineId\": 2030, \"voicelineType\": \"30001\", \"unlockConditions\": [{\"paramList\": [3, 10], \"unlockText\": \"解锁「蒙德 蒙德城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲谢尔…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fischl_heroine\", \"description\": \"派蒙：菲谢尔给人的感觉很不一样呢。\\n{NICKNAME}：比如说？\\n派蒙：比如说，和一只会说话的乌鸦一起行动。\\n{NICKNAME}：唔，那我和派蒙一起旅行，也差不多吧。\\n{NICKNAME}：不过，奥兹还能当菲谢尔的翻译。但派蒙的话…嗯…\\n派蒙：什么？！我可比乌鸦厉害多了！\\n{NICKNAME}：比如说？\\n派蒙：唔…嗯…呃…比如说我不用翅膀也能飞！\", \"voicelineId\": 2031, \"voicelineType\": \"35001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宠物…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_pet_heroine\", \"description\": \"{NICKNAME}：说起菲谢尔，她也自称是「异世界的来客」…\\n{NICKNAME}：这一点和我一样呢，而且都带着一只宠物。\\n派蒙：宠物？不对不对…\\n{NICKNAME}：只不过她的乌鸦「奥兹」…外型又帅气，讲话又彬彬有礼。\\n{NICKNAME}：更重要的是又能侦察又能打架，帮助很大。\\n{NICKNAME}：和菲谢尔商量一下，偶尔交换一下也还挺有趣的吧？一周两周之类的。\\n派蒙：你不先问我的意见吗？！\", \"voicelineId\": 2032, \"voicelineType\": \"36001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_beidou_heroine\", \"description\": \"派蒙：要怎么样才能成为北斗大姐头那种，又有号召力，又帅气的人物呢！\\n{NICKNAME}：要有足够的见识…\\n派蒙：陪你旅行到现在，派蒙已经见过很多东西了！\\n{NICKNAME}：要经历挫折和苦难…\\n派蒙：派蒙差点在水里咕嘟咕嘟咕嘟下去了…\\n{NICKNAME}：要始终怀有鼓舞他人的气概…\\n派蒙：嗯！派蒙一直支持着你哦。\\n{NICKNAME}：看待问题要成熟…\\n派蒙：喂！你就是想说派蒙我没可能了是吧？\", \"voicelineId\": 2033, \"voicelineType\": \"52001\", \"unlockConditions\": [{\"paramList\": [3, 128], \"unlockText\": \"解锁「璃月 璃月港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_ningguang_heroine\", \"description\": \"派蒙：要怎么样才能成为凝光大人那种，很有钱，又很有钱的人物呢！\\n{NICKNAME}：凝光给你的印象就只剩下钱了吗…\\n派蒙：还有大大的「群玉阁」！不过那也是用摩拉堆出来的吧。\\n{NICKNAME}：那么，要有精明的头脑…\\n派蒙：派蒙擅长给人取绰号！\\n{NICKNAME}：要熟悉市场运作的规则…\\n派蒙：一份渔人吐司卖1025摩拉，下雨天也不会打折。\\n{NICKNAME}：要有高人一等的办事手腕…\\n派蒙：…怎样才能跟一个有钱人成为朋友呢？\\n{NICKNAME}：这就已经放弃了吗？！\", \"voicelineId\": 2034, \"voicelineType\": \"53001\", \"unlockConditions\": [{\"paramList\": [101609], \"unlockText\": \"完成「辞行久远之躯」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于七七是僵尸这件事…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_qiqi_heroine\", \"description\": \"派蒙：七七…会不会需要吸血呢？\\n{NICKNAME}：那不是僵尸，是吸血鬼吧。\\n派蒙：那她的胳膊会不会突然掉下来？\\n{NICKNAME}：那不是僵尸，是丧尸吧。\\n派蒙：真不愧是旅行者，见识非常广呢！\\n派蒙：这样说来，僵尸会做什么特别的事呢？\\n{NICKNAME}：体操？\\n派蒙：你说得很有道理！所以会做体操就是僵尸！\", \"voicelineId\": 2035, \"voicelineType\": \"38001\", \"unlockConditions\": [{\"paramList\": [101609], \"unlockText\": \"完成「辞行久远之躯」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于飞行…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fly_heroine\", \"description\": \"派蒙：{NICKNAME}，来跟派蒙学飞行吧！\\n派蒙：三、二、一！\\n{NICKNAME}：啊，不见了。\\n{NICKNAME}：算了，已经很累了，还是先在这坐一会…\\n{NICKNAME}：我的心是和你一起飞翔的…嗯…\", \"voicelineId\": 2036, \"voicelineType\": \"10001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于史莱姆…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_slime_heroine\", \"description\": \"派蒙：{NICKNAME}，你最喜欢哪种史莱姆呀？\\n{NICKNAME}：冰史莱姆吧。凑近就能感到寒气，夏天会很需要。\\n派蒙：实用性的角度呢，不愧是旅行者。\\n{NICKNAME}：那派蒙呢？\\n派蒙：我都喜欢！都很好吃！\\n{NICKNAME}：好吃…\\n派蒙：把史莱姆叽里咕噜、咕嘟哇噜地做成特色饮品，就是「派蒙特调」喔！\\n{NICKNAME}：好，好吧…\\n{NICKNAME}：那么，就把小派蒙在应急食品的顺位，下调一位吧。\\n派蒙：我希望这个顺位里不要有我才好！\", \"voicelineId\": 2037, \"voicelineType\": \"12001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丘丘人…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_hilichurls_heroine\", \"description\": \"{NICKNAME}：对丘丘人，我们是不是做得有点太过分了？\\n派蒙：确实…有的时候，我们就像见到蜂窝一定要捅一下的小孩子一样。\\n{NICKNAME}：嗯…只是「捅一下」的程度吗？\", \"voicelineId\": 2038, \"voicelineType\": \"13001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「好睡族」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_sleeper_heroine\", \"description\": \"{NICKNAME}：「好睡族」…丘丘人的部族名真是奇妙。\\n派蒙：好睡族的丘丘人，会抓住一切可以利用的时机睡觉。\\n派蒙：据说他们的兽皮床铺非常松软，你想试试看吗？\\n{NICKNAME}：派蒙自己不试试吗？\\n派蒙：我可以飘浮着睡！空气永远是最松软的床。嘿嘿嘿，羡慕吗？\\n{NICKNAME}：…有一点点。\", \"voicelineId\": 2039, \"voicelineType\": \"14001\", \"unlockConditions\": [{\"paramList\": [3, 14], \"unlockText\": \"解锁「蒙德 达达乌帕谷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「好肉族」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_meaty_heroine\", \"description\": \"{NICKNAME}：「好肉族」…丘丘人的部族名真是奇妙。\\n派蒙：「好肉族」的丘丘人，会定期祭祀。他们的祭坛建得很壮观喔。\\n{NICKNAME}：祭祀的内容是？\\n派蒙：「每天都有肉吃」！是很棒的愿望吧？\\n{NICKNAME}：…可以想见的答案，我不意外。\", \"voicelineId\": 2040, \"voicelineType\": \"15001\", \"unlockConditions\": [{\"paramList\": [3, 14], \"unlockText\": \"解锁「蒙德 达达乌帕谷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「黑日族」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_blacksun_heroine\", \"description\": \"{NICKNAME}：「黑日族」…丘丘人也有这种听起来比较正常的部族名呢。\\n派蒙：「黑日族」的丘丘人，很神秘呀。\\n派蒙：那个部族的丘丘人，都会画一种叫做「黑日标志」的图案。\\n派蒙：但据说只有黑日族的大萨满，才知道那个标志背后的含义…\\n{NICKNAME}：黑色的…太阳…\\n派蒙：嗯？{NICKNAME}，你刚才说什么？\\n{NICKNAME}：啊，我在问你今天晚上要煮什么肉的汤。\\n派蒙：怎么突然转到这种话题，你是「好肉族」的丘丘人吗——我要野猪肉的！谢谢！\", \"voicelineId\": 2041, \"voicelineType\": \"16001\", \"unlockConditions\": [{\"paramList\": [3, 14], \"unlockText\": \"解锁「蒙德 达达乌帕谷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于财宝…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_treasure_heroine\", \"description\": \"派蒙：派蒙…身体，有点不太舒服…\\n{NICKNAME}：你怎么了？\\n派蒙：已经很久没有亲手打开过宝箱了，这样下去…这样下去的话…\\n{NICKNAME}：这样下去的话，总有一天你会被放着一摩拉的捕兽夹抓住吧。\\n派蒙：喂——派蒙会飞啦，才不会上那种当的。\", \"voicelineId\": 2042, \"voicelineType\": \"17001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于发胖…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fat_heroine\", \"description\": \"派蒙：呜哇，最近在旅行途中，吃了很多好吃的呢。\\n派蒙：只要吃到好吃的，旅行的疲惫就能一扫而空！\\n{NICKNAME}：嗯…如果发胖了，小派蒙会飞不起来吗？\\n派蒙：哼哼，才不会！我是吃不胖的类型！\\n{NICKNAME}：嗯…\\n派蒙：所以我还要吃更多好吃的！\\n{NICKNAME}：光吃不长肉。从应急食品的角度来看，不合格了吧？\\n派蒙：喂——难道你在外面还有其他合格的应急食品吗？\", \"voicelineId\": 2043, \"voicelineType\": \"19001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于猫派和狗派…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_catORdog_heroine\", \"description\": \"派蒙：猫咪和狗狗，你更喜欢哪一个？\\n{NICKNAME}：我更喜欢小派蒙哦！\\n派蒙：呜哇，这犯规了吧…\\n派蒙：咦，不对。派蒙不是宠物！\", \"voicelineId\": 2044, \"voicelineType\": \"20001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于大海的声音…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_oceanVoice_heroine\", \"description\": \"派蒙：据说把耳朵凑近星螺，就能听到大海的悄悄话哦！\\n{NICKNAME}：派蒙想要试一试吗？\\n派蒙：不用啦！我刚刚听过了！\\n{NICKNAME}：哦？那大海悄悄说了些什么？\\n派蒙：大海说，现在到用餐时间啦——快走吧，我想吃「渔人吐司」！\", \"voicelineId\": 2045, \"voicelineType\": \"44001\", \"unlockConditions\": [{\"paramList\": [3, 114], \"unlockText\": \"解锁「璃月 瑶光滩」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于猜拳…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fingerGuessing_heroine\", \"description\": \"派蒙：想马上就能吃到好吃的！但，又不想跑腿…\\n{NICKNAME}：要用猜拳来决定谁去买吗？\\n派蒙：好呀好呀！\\n{NICKNAME}：那么，石头剪刀布——\\n派蒙：「超级派蒙旋风」！\\n{NICKNAME}：…欸？\", \"voicelineId\": 2046, \"voicelineType\": \"45001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于放松方式…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_relax_heroine\", \"description\": \"派蒙：最近好累啊，有什么推荐的放松方式吗？\\n{NICKNAME}：睡觉？\\n派蒙：睡觉好无聊，换一个。\\n{NICKNAME}：看书？\\n派蒙：脑袋会晕晕的，换一个。\\n{NICKNAME}：跟好朋友聊天？\\n派蒙：…唔。\\n派蒙：但我们却在讨论需要思考的话题呢。\\n派蒙：不思考的话，反而会变得更放松。\\n{NICKNAME}：未来提瓦特哲学史上著名的「派蒙悖论」，在这个时刻被提出了。\", \"voicelineId\": 2047, \"voicelineType\": \"46001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于饮食差异…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_foodCulture_heroine\", \"description\": \"{NICKNAME}：璃月的菜肴跟蒙德的差异很大呢。\\n{NICKNAME}：比如辣味的炒菜，在蒙德就几乎见不到。\\n派蒙：这就是人们常说的，「一方水土养一方人」吧！\\n派蒙：呃…但是为什么全提瓦特的史莱姆都是一个味道的？\\n{NICKNAME}：那是因为你只会同一种烹饪方式吧…\", \"voicelineId\": 2048, \"voicelineType\": \"48001\", \"unlockConditions\": [{\"paramList\": [3, 128], \"unlockText\": \"解锁「璃月 璃月港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于藏钱…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_weaselThief_heroine\", \"description\": \"派蒙：「盗宝鼬」的背包里，真的藏着好多摩拉啊！\\n{NICKNAME}：嗯，鼬鼠这种小动物，天生就喜欢收集亮晶晶的东西吧。\\n派蒙：听说最初的「盗宝鼬」的来历，和「盗宝团」有关…\\n派蒙：对了，说到收集亮晶晶的东西，乌鸦也是这种动物。\\n派蒙：不知道奥兹会不会背着菲谢尔，藏了一箱摩拉呢。\\n{NICKNAME}：这么说的话，派蒙也…\\n{NICKNAME}：不知道派蒙…\\n派蒙：哇，你不要过来。我绝对没有在鞋底里面藏钱！\", \"voicelineId\": 2049, \"voicelineType\": \"49001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于冒险故事…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_adventureStory_heroine\", \"description\": \"{NICKNAME}：派蒙，你看过《少女薇拉的忧郁》吗？\\n派蒙：听起来很耳熟呢！\\n{NICKNAME}：那本书还挺受欢迎的，据说作者靠它大赚了一笔…\\n派蒙：欸，我也想赚好多好多摩拉。\\n派蒙：嗯...决定了！我也要去写冒险故事！\\n{NICKNAME}：小派蒙的冒险故事？\\n派蒙：对！英勇的旅行者打败了魔龙，拯救了世界…\\n派蒙：然后和她可靠的同伴一起吃了十份蜜酱胡萝卜煎肉的故事！\\n{NICKNAME}：十份？\\n派蒙：嗯！结局要十全十美，大家才会来看嘛！\\n派蒙：就这么愉快地决定了！书名就叫做《少女派蒙的快乐》。\\n{NICKNAME}：呃？\", \"voicelineId\": 2050, \"voicelineType\": \"39001\", \"unlockConditions\": [{\"paramList\": [39604], \"unlockText\": \"完成「巨龙与自由之歌」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于噩梦…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nightmare_heroine\", \"description\": \"派蒙：{NICKNAME}，你做过什么超恐怖级别的噩梦吗？\\n{NICKNAME}：唔，我梦见过自己在无边的黑暗中坠落…\\n{NICKNAME}：没带风之翼。\\n派蒙：哇…\\n{NICKNAME}：还梦见过哥哥头也不回地往前走，我怎么追赶都抓不住他。\\n{NICKNAME}：…他说我「来得太晚了」。\\n派蒙：唔…\\n派蒙：跟我的情况不太一样呢。\\n派蒙：我梦见过最恐怖的事情，是被超巨大的史莱姆吞进肚子里。\", \"voicelineId\": 2051, \"voicelineType\": \"50001\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「仙灵」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_seelie_heroine\", \"description\": \"{NICKNAME}：那些追逐着宝藏的「仙灵」，是从哪里来的呢？\\n派蒙：说不定是从地里长出来的吧，或者是从树上掉下来的？\\n派蒙：虽然不明白来源，但有「仙灵」就有好东西！\\n{NICKNAME}：可是…为什么它们自己，在接触到宝藏的时候，却有一种悲伤的气氛呢？\\n派蒙：嗯？\\n{NICKNAME}：没什么，可能是我的错觉吧。\\n派蒙：唔…你要是不想要宝箱的话，就都拿来给派蒙保管吧！不收保管费！\", \"voicelineId\": 2052, \"voicelineType\": \"51001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于印象最深刻的人…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_impressivePerson_heroine\", \"description\": \"派蒙：在最近的旅行里，你有没有什么留下深刻印象的人呢？\\n派蒙：我的话，应该是莎拉吧。\\n{NICKNAME}：提米。\\n派蒙：欸！为什么？\\n{NICKNAME}：最近每次吃甜甜花酿鸡，都会想到他的脸…肉也变得难吃了。\", \"voicelineId\": 2053, \"voicelineType\": \"54001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于语言…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_language_heroine\", \"description\": \"派蒙：你学新东西真的很快啊。\\n派蒙：居然在这么短的时间里，就掌握了提瓦特的语言。\\n{NICKNAME}：是派蒙教得好。\\n派蒙：欸嘿嘿…\\n{NICKNAME}：以后，起难听绰号的水平…说不定也会上升吧。\", \"voicelineId\": 2054, \"voicelineType\": \"21001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于派蒙的物种…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_species_heroine\", \"description\": \"{NICKNAME}：你感觉什么样的怪物让你印象深刻呢？\\n派蒙：怪物吗…嗯…遗迹守卫？\\n{NICKNAME}：遗迹守卫算是怪物吗？应该属于「机关」之类的吧…\\n派蒙：我觉得那种会给人造成麻烦、需要被打败的都算是「怪物」哦？\\n派蒙：就像打猎可以打到的都算是「猎物」。\\n{NICKNAME}：原来如此…这么讲的话，我终于可以界定派蒙的物种类型了。\\n派蒙：欸？是什么呢？\\n{NICKNAME}：派蒙属于可以钓上来的…所以是「鱼类」。\\n派蒙：嗯？\\n\", \"voicelineId\": 2055, \"voicelineType\": \"18001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于收起武器的方法…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_weapon_heroine\", \"description\": \"派蒙：喂，你能再表演一下那个吗？就是那个！\\n{NICKNAME}：哪个？\\n派蒙：就是…「唰」地一下把武器变没，然后又忽然出现在背后！\\n{NICKNAME}：那个呀…你应该见过很多次了吧？\\n派蒙：但我还是没弄明白原理，你能解释一下吗？\\n{NICKNAME}：那不如你先解释一下，你刚才是怎么突然出现在我面前，有时又突然消失的呢？\\n派蒙：唔…这…好像派蒙天生就会了，不知道该怎么解释…\\n{NICKNAME}：嗯，收起武器的技巧其实也是一个道理吧。\\n{NICKNAME}：这就是友情的证明吧。\", \"voicelineId\": 2056, \"voicelineType\": \"22001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宝箱…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_chest_heroine\", \"description\": \"派蒙：{NICKNAME}，你对「宝箱」这种东西怎么看？\\n{NICKNAME}：我会相信…那些都是曾经的伟大旅行者留下的痕迹。\\n{NICKNAME}：每次我打开箱子，看到里面的一切，都能与前人感同身受…\\n派蒙：冒险经验增加了！\", \"voicelineId\": 2057, \"voicelineType\": \"23001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于眼睛…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_eyes_heroine\", \"description\": \"派蒙：看我的眼睛！\\n{NICKNAME}：怎么了？\\n派蒙：听凯亚说，人的眼睛会出卖自己。\\n派蒙：他只看眼睛就知道，那人说的是不是真话。\\n{NICKNAME}：嗯…\\n派蒙：我喜欢渔人吐司！\\n{NICKNAME}：应该是真话。因为你只要是吃的，好像什么都喜欢。\\n派蒙：嘿嘿。\\n{NICKNAME}：说起来，上一个见过的，眼神充满热情的是——\\n派蒙：是？\\n{NICKNAME}：遗迹守卫。让人很想戳下去…\", \"voicelineId\": 2058, \"voicelineType\": \"55001\", \"unlockConditions\": [{\"paramList\": [46308], \"unlockText\": \"完成「海盗秘宝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于模仿其他人…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_imitate_heroine\", \"description\": \"派蒙：唔…好无聊…整个人都没有精神了…\\n{NICKNAME}：反正闲着也是闲着，我们来模仿骑士团的其他人吧？\\n派蒙：欸…？会不会很没礼貌？\\n{NICKNAME}：哈哈，果真不错。连骑士「谦卑有礼」的品德都掌握了呢。\\n派蒙：喂——这就已经开始了吗！\", \"voicelineId\": 2059, \"voicelineType\": \"65001\", \"unlockConditions\": [{\"paramList\": [46308], \"unlockText\": \"完成「海盗秘宝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于幸运抽奖…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_lottery_heroine\", \"description\": \"派蒙：咕咕咕…\\n{NICKNAME}：嗯？有鸽子吗？\\n派蒙：不对啦，是我饿了。\\n派蒙：嗯…现在我要抽一位旅行者，来为我做一份蜜酱胡萝卜煎肉。\\n派蒙：到底是哪位旅行者这么幸运呢？\", \"voicelineId\": 2060, \"voicelineType\": \"42001\", \"unlockConditions\": [{\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于眼狩令…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_visionHuntDecree_heroine\", \"description\": \"派蒙：说到稻妻最近发生的大事，果然还是眼狩令吧。\\n派蒙：不过你没有神之眼，所以不用担心会被收走。\\n派蒙：但反过来，如果被天领奉行抓住，{NICKNAME}，你也没办法交出神之眼来保命…\\n{NICKNAME}：我可以跟他们说，派蒙就是我的神之眼哦。\\n派蒙：派蒙还真是方便的道具…才不对吧！\\n{NICKNAME}：放心吧，不会交出派蒙的。\\n派蒙：这样还差不多。\\n{NICKNAME}：然后我和派蒙大概会一起坐牢，一起被下令处死…\\n派蒙：唔…如、如果真的这样的话，还是把我交出去吧…\\n派蒙：…等等，从一开始不要被抓住不就好了吗！\", \"voicelineId\": 2089, \"voicelineType\": \"71001\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于反抗军…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_rebels_heroine\", \"description\": \"派蒙：只有拥有反抗的意志，才能加入反抗军！\\n派蒙：这么说来，我也是合格的反抗军士兵呢！\\n{NICKNAME}：派蒙也有反抗的意志吗？\\n派蒙：我可是一直在全心全力地反抗被压迫的命运哦！\\n{NICKNAME}：那派蒙应该不能加入反抗军。\\n派蒙：为什么？是因为我们反抗的不是同一件事吗？\\n{NICKNAME}：是因为派蒙的反抗一直没什么用…\\n派蒙：呜呜，好过分！\", \"voicelineId\": 2090, \"voicelineType\": \"71002\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神居岛崩炮\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_tatarasaWeapon_heroine\", \"description\": \"派蒙：神居岛崩报、神居岛懵炮、神居鸟崩炮、神居岛喵喵…呸呸呸，好拗口的名字。\\n{NICKNAME}：派蒙在读什么？\\n派蒙：就是这个啦。幕府军为了保护踏鞴砂，在附近修建的超厉害兵器。\\n派蒙：神居岛、崩、炮！\\n{NICKNAME}：看上去很强的样子…不过我们来踏鞴砂的时候，好像并没有见到它运转起来。\\n派蒙：听说因为连反抗军都知道很强，所以正式开战前就通过奇袭的方式把这里打下来了。\\n派蒙：但这个神居…神居大炮需要用特殊炮弹或者雷元素来驱动，反抗军那边也用不了。\\n派蒙：花费这么大力气修建的兵器到底有多厉害呢？真想见识一下…\\n{NICKNAME}：雷元素我倒是也会一点。\\n派蒙：对哦！但是这附近好像也没有合适的炮弹…\\n派蒙：嗯？你看我干什么？喂——\", \"voicelineId\": 2091, \"voicelineType\": \"71003\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于太郎丸…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_taroumaru_heroine\", \"description\": \"派蒙：说起来，我们刚到木漏茶室的时候，是真的以为太郎丸会说话呢…\\n{NICKNAME}：派蒙听起来有些失落呀？\\n派蒙：是啊，如果太郎丸会说话的话，总觉得会说出不得了的事情呢！\\n{NICKNAME}：比如？\\n派蒙：比如…「托马，你躲在这里挡到我了汪！」\\n{NICKNAME}：嗯，合情合理。\\n派蒙：再比如…「梢，在我们的契约终结之前，你一生一世不得解脱，汪汪！」\\n{NICKNAME}：梢说自己被神秘契约困在店里打工的事情，派蒙不会真的相信了吧…\\n派蒙：哦哦！还有还有，我想到了，这个不错——\\n派蒙：「看这位名为派蒙的客人机灵可爱，今天的餐费全部免除汪！」\\n{NICKNAME}：这已经是你自己在说话了吧。\\n派蒙：嘿嘿…\", \"voicelineId\": 2092, \"voicelineType\": \"71004\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于五郎…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_gorou_heroine\", \"description\": \"派蒙：嗯…\\n{NICKNAME}：派蒙在烦恼什么呢？\\n派蒙：{NICKNAME}，你还记得五郎那毛茸茸的耳朵吗？\\n派蒙：我也好想要那个…或者像甘雨一样，有可爱的角也不错。\\n派蒙：{NICKNAME}，你有什么好办法吗？\\n{NICKNAME}：让我找找…啊，有了。\\n派蒙：真的吗？{NICKNAME}，我就知道你是最可靠的！\\n{NICKNAME}：锵锵~「吞天之鲸·只角」！\\n派蒙：不是要这个啦！\\n派蒙：唉…不过仔细想想，五郎不仅有毛茸茸的耳朵，还有尾巴呢…\\n{NICKNAME}：锵锵~「北风之尾」！\\n派蒙：都说了不需要啦！而且这两个组合起来绝对会很奇怪吧！\", \"voicelineId\": 2093, \"voicelineType\": \"71005\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于小说出版…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_novelPublish_heroine\", \"description\": \"派蒙：稻妻有八重堂这种专门出版小说的地方呢！\\n派蒙：甚至还有比赛，真厉害！\\n{NICKNAME}：那么，之前派蒙说要写的《少女派蒙的快乐》刚好可以拿去投稿了。\\n派蒙：呃，那个，手稿在我们来稻妻的时候不小心弄丢了…\\n{NICKNAME}：…真的吗？（盯——）\\n派蒙：好啦，我承认，我还没开始动笔。\\n派蒙：可是这不能怪我嘛！其实我一直想要动笔的，但是大前天我笔断了，前天我手抽筋了，昨天我脚扭了，今天我…唔…今天我肚子饿了！\\n{NICKNAME}：说不定《派蒙的十万个拖稿理由》会比《少女派蒙的快乐》更快完成。\", \"voicelineId\": 2095, \"voicelineType\": \"71007\", \"unlockConditions\": [{\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_kazuha_heroine\", \"description\": \"派蒙：万叶是一个很洒脱的人呢。\\n{NICKNAME}：是的，似乎经常看到他独来独往。\\n派蒙：一个人行走在世间，倾听自然万物的声音，似乎也不错…\\n派蒙：{NICKNAME}，你该不会也想背着我偷偷出去冒险吧？\\n{NICKNAME}：怎么会，我一直都会和小派蒙在一起的哦。\\n派蒙：太好啦。那…嘿嘿，这个给你…\\n{NICKNAME}：「当月饮食开销」…共欠三十万摩拉？！\\n派蒙：喂喂，{NICKNAME}，你要去哪？\\n{NICKNAME}：我突然觉得一个人行走在世间，似乎也不错。\\n派蒙：不要啊！等等我呀——\", \"voicelineId\": 2096, \"voicelineType\": \"71008\", \"unlockConditions\": [{\"paramList\": [200212], \"unlockText\": \"完成「振袖秋风问红叶」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_ayaka_heroine\", \"description\": \"派蒙：嗯…嗯…\\n{NICKNAME}：派蒙，今天看起来好严肃啊。\\n派蒙：因为我正在思考很严肃的事情。\\n派蒙：我以前很羡慕大户人家的生活，可以有用不完的摩拉和吃不完的美食…\\n{NICKNAME}：嗯，确实都是你喜欢的东西。\\n派蒙：但是认识了绫华之后，我发现大小姐的生活也很辛苦呢。\\n派蒙：需要背负家族的使命与责任，尽力完成工作，才能在难得的闲暇享受自己的生活。\\n派蒙：绫华平常这么辛苦，应该也要多放松下才好呀…\\n派蒙：对了对了！下次再有祭典活动的话，我们也邀请绫华一起去吧？\\n派蒙：我们去邀请的话，绫华应该不会拒绝的吧，嘿嘿。\\n{NICKNAME}：嗯，我也很想再和她去一次祭典。\\n派蒙：而且，只要绫华在的话，那我们游玩的全部费用就都…\\n{NICKNAME}：…这才是你真正的目的吧…\", \"voicelineId\": 2097, \"voicelineType\": \"71009\", \"unlockConditions\": [{\"paramList\": [1200804], \"unlockText\": \"完成「鹤与白兔的诉说」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于模仿绫华…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_imitateAyaka_heroine\", \"description\": \"派蒙：绫华小姐举手投足都散发着高贵的气息呢。\\n{NICKNAME}：突然想看派蒙模仿绫华。\\n派蒙：欸，我试试。\\n派蒙：「哦，原来你这么用心的采蘑菇，是为了给我做野菇鸡肉串啊。」\\n派蒙：「真是可爱呢。」\\n{NICKNAME}：完全不是绫华啊。不过，总感觉…\\n{NICKNAME}：这种明明不是派蒙却又觉得似乎理应如此的感觉是…\", \"voicelineId\": 2098, \"voicelineType\": \"71010\", \"unlockConditions\": [{\"paramList\": [1200804], \"unlockText\": \"完成「鹤与白兔的诉说」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于祭典的传统…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fiestaTradition_heroine\", \"description\": \"派蒙：说起来，在稻妻的祭典上，大家都有佩戴面具的传统呢。\\n派蒙：可是找遍所有的摊位，都没有适合我戴的尺寸…\\n{NICKNAME}：派蒙很想要自己的面具吗？\\n派蒙：当然啦！总觉得在祭典的氛围里，如果没戴面具，就好像在风花节上没收到花束一样…\\n{NICKNAME}：那我来给你做一个吧。\\n派蒙：哇——{NICKNAME}，你是最好的人！\\n{NICKNAME}：嗯，面具的样式就定为…派蒙最喜欢的史莱姆吧。\\n派蒙：好耶，史莱姆派蒙！\", \"voicelineId\": 2099, \"voicelineType\": \"71011\", \"unlockConditions\": [{\"paramList\": [1200804], \"unlockText\": \"完成「鹤与白兔的诉说」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_yoimiya_heroine\", \"description\": \"派蒙：你说，宵宫老爹的听力不好，是不是跟烟花有关啊？\\n派蒙：由于常年制作、试放烟花，每日被火药炸响的声音包围，导致听力变弱…\\n派蒙：呜哇！那宵宫继承家业，最后会不会也变得像她老爹那样，听不清人讲话…\\n派蒙：不可以不可以，为了避免这种事情发生，要赶快想想办法！\\n{NICKNAME}：派蒙有什么建议吗？\\n派蒙：唔…嗯…\\n派蒙：如果我飞在宵宫后边，一直用手捂住她的耳朵…\\n{NICKNAME}：那派蒙就不能跟着我了。\\n派蒙：…没有我的话，你就没有向导了。要我离开你是不可能的！\\n派蒙：可是宵宫…该怎么办才好…\\n{NICKNAME}：其实，在制作烟火的时候带上耳塞就可以了。\\n派蒙：对哦，还有这种方法！你真聪明！\\n{NICKNAME}：嘿…看派蒙这么困扰，我反而有些开心呢。\\n派蒙：欸？其实你早就想好了办法，却不告诉派蒙吗！\\n派蒙：怎么这样，你这坏家伙！\", \"voicelineId\": 2100, \"voicelineType\": \"71012\", \"unlockConditions\": [{\"paramList\": [1201309], \"unlockText\": \"完成「如梦如电的隽永」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于早柚的烦恼…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_sayuAnnoy_heroine\", \"description\": \"派蒙：小早柚似乎有很多烦恼呢。\\n派蒙：真是难以理解。\\n{NICKNAME}：这大概就是成长的烦恼吧。\\n派蒙：唔，你这句话也很难理解。\\n派蒙：毕竟派蒙是没什么烦恼的。\\n{NICKNAME}：嗯…\\n{NICKNAME}：糟了，背包里没几个摩拉了，接下来我们要过穷日子了…\\n派蒙：欸？不要啊——\\n{NICKNAME}：现在你有烦恼了。\\n派蒙：怎么会这样…\", \"voicelineId\": 2101, \"voicelineType\": \"71013\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鬼兜虫…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_oniHornedBeetle_heroine\", \"description\": \"派蒙：呀，这些鬼兜虫看起来好厉害，背纹好可怕！\\n{NICKNAME}：你说那些恶鬼样式的背纹吗？因为它们不喜欢争斗，所以才进化出了这种鬼怪的图形，用来恫吓敌人。\\n派蒙：真是智慧呀，我们是不是也可以学习学习！\\n派蒙：不如把魈的面具借过来怎么样？这样丘丘人看见你会被吓呆吧？\\n{NICKNAME}：呃…魈恐怕不会同意吧…\\n派蒙：也是哦…那要不我们——拜托早柚去偷？！\\n派蒙：她不是会倏的一下就消失的忍术吗！一定能偷到！真好啊！\\n派蒙：唔…如果怕魈事后算账的话，不如去偷「公子」的吧！反正你也打得过他。\\n{NICKNAME}：偷东西不太好吧，而且万一早柚不同意呢？\\n派蒙：那、那我们就先去找…先去找阿贝多！\\n派蒙：要是阿贝多能研究出让早柚长高高的药剂，早柚一定愿意帮忙！\\n{NICKNAME}：那么就该想想怎么让阿贝多帮忙了？\\n派蒙：呜哇！头开始痛了，我们还是去祭典上买一个吧。\", \"voicelineId\": 2102, \"voicelineType\": \"71014\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鸣草…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_peelGrass_heroine\", \"description\": \"派蒙：你知道吗？鸣草上长得像花的结构，其实是叶片呢。\\n派蒙：不起眼的叶片也在努力成长，保护着脆弱的花…\\n派蒙：嘿嘿，就像我也在保护着旅行者一样呢。\\n{NICKNAME}：但我记得鸣草的叶片是不能吃的。\\n派蒙：是啊是啊…等等？你在暗示什么？\", \"voicelineId\": 2103, \"voicelineType\": \"71015\", \"unlockConditions\": [{\"paramList\": [3, 235], \"unlockText\": \"解锁「稻妻 踏鞴砂」七天神像-雷\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鸣草与雷电…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_peelGrassAndThunder_heroine\", \"description\": \"派蒙：你知道吗？鸣草的振动，经常被稻妻的居民用来预报雷雨。\\n派蒙：因为鸣草通常在雷元素富集的区域生长，天生对雷电有着极强的感应能力。\\n{NICKNAME}：这么说来，鸣草和派蒙很像呢。\\n派蒙：欸？哪里像啦？\\n{NICKNAME}：因为派蒙通常在美食密集的区域出没，天生对好吃的食物有着极强的感应能力！\\n派蒙：嘿嘿，这倒是事实！\\n{NICKNAME}：那么，派蒙搜索雷达，启动…\\n派蒙：嘟嘟，嘀嘀嘀，为了好吃的，冲呀！\", \"voicelineId\": 2104, \"voicelineType\": \"71016\", \"unlockConditions\": [{\"paramList\": [3, 235], \"unlockText\": \"解锁「稻妻 踏鞴砂」七天神像-雷\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绯樱绣球…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_sakuraTemari_heroine\", \"description\": \"派蒙：从神樱树上飘下来的绯樱绣球，真好看呀。\\n派蒙：听说花瓣因为雷元素的力量，可以长时间悬浮在空中。\\n{NICKNAME}：派蒙可以飞在空中，也是利用这种原理吗？\\n派蒙：哎…这个…是因为…\\n{NICKNAME}：难道派蒙也不知道自己为什么会飞吗？\\n派蒙：派蒙会飞，当然是…是因为神秘的力量啦！\\n{NICKNAME}：明白了，你什么都不知道。\\n{NICKNAME}：既然如此，应该拿给神奇的阿贝多去研究一下…\\n派蒙：不要哇！\", \"voicelineId\": 2105, \"voicelineType\": \"71017\", \"unlockConditions\": [{\"paramList\": [3, 244], \"unlockText\": \"解锁「稻妻 鸣神大社」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于堇瓜…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_sumireLemon_heroine\", \"description\": \"派蒙：堇瓜用处很多呢！\\n派蒙：果肉可以吃，果皮还可以加工成染料。\\n{NICKNAME}：派蒙的用处也很多呢！\\n{NICKNAME}：能当我的向导，还会给别人起难听的绰号。\\n派蒙：嗯！谢谢你对我的肯定！\\n派蒙：等等，你该不会是准备抖出最后的包袱了吧？\\n派蒙：那我要捂住你的嘴，不让你说了！\", \"voicelineId\": 2106, \"voicelineType\": \"71018\", \"unlockConditions\": [{\"paramList\": [3, 296], \"unlockText\": \"解锁「稻妻 绀田村」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于佩刀…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_sabre_heroine\", \"description\": \"派蒙：{NICKNAME}，你注意到了吗？\\n派蒙：在稻妻，只有少数人的腰间有佩刀，大部分的士兵还是用长枪呢。\\n派蒙：说不定刀其实是一种身份的象征…我要不要也带一把呢？\\n派蒙：不过这里的刀对我来说都太大了…果然还是去找名家定制一把比较好！\\n{NICKNAME}：但是定制刀的话，要花不少钱吧。\\n派蒙：难道摩拉，比可爱同伴的愿望还要重要吗？\\n{NICKNAME}：…其实我早就给派蒙准备好了。\\n派蒙：真的吗真的吗，快给我看看！\\n派蒙：喂，这不是我们用来切水果的刀吗！\\n{NICKNAME}：至少大小上很适合派蒙啦…\\n{NICKNAME}：咳，「重要的不是刀的价值，而是追求武道的心」。\\n派蒙：不要试图用听着很帅的台词糊弄过去！\", \"voicelineId\": 2107, \"voicelineType\": \"71019\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温泉…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_hotSpring_heroine\", \"description\": \"派蒙：稻妻城里居然有温泉！\\n{NICKNAME}：但是稻妻没有火山呢。\\n派蒙：嗯，据说是用一个很大的炉子供热的！\\n派蒙：有机会的话，我也想去泡温泉，可惜似乎只有大人物才有资格。\\n{NICKNAME}：嗯…\\n{NICKNAME}：走了，我们回蒙德的达达乌帕谷吧！\\n派蒙：欸？为什么这么突然！\\n{NICKNAME}：达达乌帕谷那边，丘丘人的那口大锅是用烈焰花供热的，四舍五入和温泉也差不多吧。派蒙可以去那里泡…呃…泡汤？\\n派蒙：？？？\", \"voicelineId\": 2108, \"voicelineType\": \"71020\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「寿限无」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_jugemu_heroine\", \"description\": \"派蒙：在稻妻传统里，家长常会给小孩子取一个吉祥的名字。\\n{NICKNAME}：这名字自然是饱含了大家的期待，既希望财运亨通，又希望无病无灾。\\n派蒙：所以这孩子的家长，就给孩子取了一个很长很长的名字。里面那可真的是什么好处都有。\\n{NICKNAME}：结果有一天，孩子回家路上掉进了河里，她的同伴立刻就赶回家喊她的父母。「不好啦，不好啦。」\\n派蒙：「怎么啦？」\\n{NICKNAME}：「她掉在水里了！巴波·修立干·古立泰·彭彭克皮·彭彭科纳·菲谢尔·冯·露弗施洛斯·那菲多特·阿斯托洛吉斯·莫娜·梅姬斯图斯掉水里了！！」\\n派蒙：…莫娜掉水里的话，应该不用担心吧。\\n{NICKNAME}：正是如此。等她的小伙伴把话说完，名字长长、游泳快快的莫娜已经站在家门口了。\", \"voicelineId\": 2109, \"voicelineType\": \"71021\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于稻妻的岛屿…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_inazumaIsland_heroine\", \"description\": \"派蒙：稻妻的风景，和之前见过的大不相同呢。\\n{NICKNAME}：嗯，是有很多岛屿的海上国度。\\n派蒙：你说，在船被发明出来之前，不同岛屿上的人们是如何交流的呢？\\n{NICKNAME}：按照宵宫老爹的说法，应该是用升上空中的烟火来传递讯息的吧。\\n{NICKNAME}：或者，还可以…\\n派蒙：还可以…？\\n{NICKNAME}：还可以委托能够冻结水面的人，在各个岛屿之间往来传信。\\n派蒙：呜哇，那幸亏凯亚不在稻妻，不然会成为比琴团长还劳累的大忙人吧！\", \"voicelineId\": 2110, \"voicelineType\": \"71022\", \"unlockConditions\": [{\"paramList\": [3, 331], \"unlockText\": \"解锁「稻妻 离岛」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于狸猫…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_bakeDanuki_heroine\", \"description\": \"派蒙：狸猫真是神奇的生物啊。\\n{NICKNAME}：狸猫真是可爱啊。\\n派蒙：可惜会说人话。\\n{NICKNAME}：如果派蒙不会说人话的话，会不会看起来神秘又高贵呢？\\n派蒙：你这句话，是在损我吗？\\n{NICKNAME}：嗯哼。哼~哼~哼哼哼~，哼哼哼哼哼哼哼~\", \"voicelineId\": 2111, \"voicelineType\": \"71023\", \"unlockConditions\": [{\"paramList\": [3, 298], \"unlockText\": \"解锁「稻妻 镇守之森」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于狸猫与幻术…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_bakeDanukiAndIllusion_heroine\", \"description\": \"派蒙：你知不知道稻妻有一种妖怪叫做狸猫，能够变成任何人的模样！\\n{NICKNAME}：确实听过类似的传闻，真是神奇的变幻之术。\\n派蒙：要是它哪天变成我的模样来骗你怎么办？呜哇…好担心！ \\n{NICKNAME}：别担心，我还是有自信能分辨的——哦！我明白了，你在担心我的财产吧？\\n派蒙：就是啊…啊啊——才、才、才没有！我当然是担心{NICKNAME}你的安危！\\n派蒙：哼，不要那样看我啦——快先想想办法！要是有两个派蒙，要怎么找出真的那个嘛。\\n{NICKNAME}：…欸嘿。\\n派蒙：欸嘿是什么啦！\\n{NICKNAME}：看吧，会这样吐槽的就是派蒙。\\n派蒙：啊！不自觉就…\", \"voicelineId\": 2112, \"voicelineType\": \"71024\", \"unlockConditions\": [{\"paramList\": [3, 298], \"unlockText\": \"解锁「稻妻 镇守之森」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于其他神龛…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_otherShrine_heroine\", \"description\": \"派蒙：最近看见了好多小小的神龛，感觉不像是用来供奉雷神的呢。\\n{NICKNAME}：大概是民间的一些神灵吧？稻妻的人们相信万物有灵，会在各种意外的时刻帮助人们。\\n派蒙：哦——所以就会为它们修建神龛，奉上贡品。\\n{NICKNAME}：嗯，也算是一种祈祷和感谢。\\n派蒙：我明白了！那我去找绫华小姐，请她为我们修建一座神龛吧！\\n派蒙：然后就可以收获许多免费的贡品了！\\n派蒙：真高兴！\\n{NICKNAME}：欸？这、这样也可以吗？\\n派蒙：怎么了？我们不是也在一直帮助大家吗？做的说不定比神灵还要好呢！\\n{NICKNAME}：说得也是…\\n{NICKNAME}：但一想到人们带着花和果子放在我的神龛前面，就觉得有什么地方不太对劲…\", \"voicelineId\": 2113, \"voicelineType\": \"71025\", \"unlockConditions\": [{\"paramList\": [3, 245], \"unlockText\": \"解锁「稻妻 荒海」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八酝岛的雨…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_yashioriIslandsRain_heroine\", \"description\": \"{NICKNAME}：八酝岛的大雨下个不停，据说是「祟神」的气息导致的。\\n派蒙：「祟神」？那是什么？听起来很厉害。\\n{NICKNAME}：就是魔神残渣，也就是魔神的遗骸，因为力量没有完全消散，还会导致各种坏事，所以又被叫做「祟神」。\\n派蒙：原来是这样，可是下雨也算不上什么坏事吧。\\n派蒙：反而感觉它更像是被欺负了，在伤心地哭个不停呢。\\n{NICKNAME}：哭吗？神不会哭的吧，你看温迪、钟离他们就从来不哭。\\n派蒙：也有例外！你快捏我一下，就可以看到哭泣的神了。\\n{NICKNAME}：嗯？原来你也是神吗？\\n派蒙：我是，我是的！\\n{NICKNAME}：好嘛，让我猜猜，你是飞行笨蛋之神？史莱姆之神？还是水中上钩之神？\\n派蒙：什么乱七八糟的神呀，哼！\\n派蒙：我是守护神哦！是{NICKNAME}的守护神。\", \"voicelineId\": 2114, \"voicelineType\": \"71026\", \"unlockConditions\": [{\"paramList\": [3, 258], \"unlockText\": \"解锁「稻妻 名椎滩」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于万端珊瑚侦探社…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_bantanNoSangoDetectiveAgency_heroine\", \"description\": \"{NICKNAME}：说起来，在花见坂有一家「万端珊瑚侦探社」呢。\\n派蒙：我有印象，是珊瑚和龙二经营的那家吧？大家对他们的评价很不错哦。\\n{NICKNAME}：唔，不过我听说他们经常会碰上奇怪的事件，有些地方都禁止他们入内了…\\n派蒙：我觉得这样做不太好吧，毕竟珊瑚和龙二帮了大家很多忙呢…\\n{NICKNAME}：那派蒙吃饭会请他们来吗？\\n{NICKNAME}：然后吃到一半，突然发现邻桌的客人惨叫一声、倒在了地上…\\n派蒙：那、那还是别了吧，突然感觉和他们一起行动好危险啊…\\n{NICKNAME}：所以说这就是名侦探的不便之处吧。\", \"voicelineId\": 2115, \"voicelineType\": \"71027\", \"unlockConditions\": [{\"paramList\": [3, 242], \"unlockText\": \"解锁「稻妻 町街」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于求签…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_kauChim_heroine\", \"description\": \"派蒙：对了，{NICKNAME}，你有去过神社求签吗？\\n派蒙：做事之前先去求个签，说不定能得到一些启示哦。\\n{NICKNAME}：唔，但有可能会抽到「凶」或者「大凶」一类的吧？感觉会影响心情…\\n派蒙：没关系的，听神社的巫女说，要是抽到了不好的签，挂到神社的御签挂上就可以啦…\\n派蒙：所以只要一直抽一直抽，直到抽中「大吉」为止就好啦！其他的全挂到御签挂上！\\n{NICKNAME}：如果大家都像你这样做，御签挂会挂不下吧…\", \"voicelineId\": 2116, \"voicelineType\": \"71028\", \"unlockConditions\": [{\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「无想的一刀」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_musouNoHitotachi_heroine\", \"description\": \"派蒙：「无想的一刀」好厉害！\\n派蒙：不管遇到什么敌人只要来一刀就行了吧！\\n{NICKNAME}：嗯…但是「公子」的话，可能要三刀…\\n派蒙：对、对哦！\\n派蒙：总之，如果你学会了的话，接下来的旅途我就再也不用担心你了！\\n{NICKNAME}：那么，要去哪里才能学到呢？\\n派蒙：那么，要去哪里才能学到呢？\\n{NICKNAME}：嗯？\\n派蒙：不要这么看着我嘛！好、好嘛，接下来的旅途我也会多多关照你的…\", \"voicelineId\": 2117, \"voicelineType\": \"71029\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珊瑚宫心海…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_kokomi_heroine\", \"description\": \"派蒙：{NICKNAME}，你知道吗？那位珊瑚宫心海，可是海祇岛的「现人神巫女」呢。\\n派蒙：也就是海祇岛的最高领袖！整个海祇岛都归她管哦。\\n派蒙：啊，派蒙也想成为那样的大人物…\\n{NICKNAME}：成为大人物之后呢？\\n派蒙：之后就可以伸张正义了呀。比如说…咳咳。\\n派蒙：嫌犯{NICKNAME}中午吃三彩团子的时候，自己吃掉了两个，只分给了受害人派蒙一个，严重违反了「派蒙法令」第三十七条——「公平公正」！\\n{NICKNAME}：那请问派蒙大人打算如何处理此事？\\n派蒙：当然是罚你给派蒙做好多三彩团子啦，嘿嘿！\", \"voicelineId\": 2118, \"voicelineType\": \"71030\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「无常」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_anitya_heroine\", \"description\": \"派蒙：不知道前代将军是个什么样的人呢。\\n{NICKNAME}：似乎是一个能理解花不常开的人呢，并且她也能坦然接受自己终有一日会离开的命运。\\n派蒙：知道眼前之物的宝贵，才能更加珍惜啊。\\n{NICKNAME}：这个可能也影响了稻妻的美学吧。浮世之景里，众生流淌而过。度过的热闹时光、一起结伴而行的人、一起品尝过的美味，这些是真实不虚的，是真正重要的事物。\\n派蒙：虽然…虽然宴席肯定会结束，但快乐的时间能更长一点就好了。\\n{NICKNAME}：「白露与清梦，胧幻与此生，若比君侧时，皆算久长事。」\\n派蒙：你在说什么！\\n{NICKNAME}：这是说，和小派蒙的旅行很开心。如果能一直这样下去就好了。\\n派蒙：你不会骗我吧。嘿嘿。\", \"voicelineId\": 2119, \"voicelineType\": \"71031\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于巫女…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_miko_heroine\", \"description\": \"派蒙：巫女们的衣服很有特色呀。\\n{NICKNAME}：据说八重神子在思考锁国结束之后，把试穿巫女服作为一项旅游业务在各地布设开来。配合枫丹的新型留影机技术，感觉能大赚一笔。\\n派蒙：哦！\\n{NICKNAME}：{M#大社的巫女上次还问我认不认识好看的女孩子愿意当宣传模特，只用穿着巫女服对留影机笑一笑就好。或者我自己来也行，化一下妆就好。},{F#大社的巫女上次还问我有没有兴趣当宣传模特，只用穿着巫女服对留影机笑一笑就好。或者认不认识其他好看的女孩子。}\\n派蒙：喂！\\n{NICKNAME}：我转手就把这个想法告诉了罗莎莉亚。觉得她们的西风教会修女服也可以这么来一出。\\n派蒙：你等等！\\n{NICKNAME}：唉，罗莎莉亚只是觉得好麻烦。\\n派蒙：还好只是罗莎莉亚…\", \"voicelineId\": 2120, \"voicelineType\": \"71032\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于画家歌麿…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_utamoro_heroine\", \"description\": \"派蒙：最近葵送了我一幅画，虽然不能吃，但还是十分高兴！\\n{NICKNAME}：是那个杂货店主吗？我看看。\\n派蒙：喏，小心点，这是名画师歌麿的作品哦，值钱货！\\n{NICKNAME}：歌麿？唔…总觉得在哪见过…\\n派蒙：那当然，毕竟是歌麿大师，名作早就遍布稻妻了吧！\\n派蒙：你是在绫华小姐家看到的吧？我这幅可一点也不差哟。\\n{NICKNAME}：不对，我想起来了！上次宵宫用来做火折子的就是这个吧？\\n派蒙：欸？做火折子？\\n{NICKNAME}：托马好像也拿来垫桌脚过…\\n派蒙：什么？垫桌脚？\\n{NICKNAME}：没记错的话，早柚午睡的时候还找了好几张当做垫子。\\n派蒙：早柚那家伙都有好几张？绝对不可能吧…\\n{NICKNAME}：歌麿这家伙根本不是什么大师吧，真正的名作怎么会到处都是啦。\\n派蒙：欸——\", \"voicelineId\": 2121, \"voicelineType\": \"71033\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于茶室与老板…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_teaHouseBoss_heroine\", \"description\": \"派蒙：「木漏茶室」的生意还不错呢，每天都有不少客人来光顾。\\n派蒙：{NICKNAME}，有机会的话我们也开一间茶室吧，感觉会很赚钱！\\n{NICKNAME}：嗯…如果以后我开茶室的话，一定会让派蒙来当店长的。\\n派蒙：欸？好呀！\\n派蒙：没想到你这么信任我的经营能力…我一定会当一个负责的店长，把我们的店做成全提瓦特第一的！\\n{NICKNAME}：经营就不麻烦你了…派蒙，你还记得太郎丸吗？\\n派蒙：记得记得，是茶室的老板嘛，听说有些客人不是来喝茶，而是来找它玩的。\\n{NICKNAME}：所以我在想，如果让派蒙来当店长的话，一定会比太郎丸更受欢迎吧。\\n派蒙：嘿嘿，那当然了…喂，原来你不是信任我的经营能力，只是想让我当吉祥物吗！\", \"voicelineId\": 2122, \"voicelineType\": \"71034\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于锁国…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_sakoku_heroine\", \"description\": \"{NICKNAME}：眼狩令结束了，锁国也将不日解除了吧。\\n派蒙：希望一切都能好起来吧。\\n{NICKNAME}：希望就在眼前，要鼓励大家坚持下去啊。\\n派蒙：嗯嗯。\\n{NICKNAME}：找个机会去和竺子说一下吧。「竺子，故乡的樱花开了。」\\n派蒙：嗯…总觉得哪里不对！\", \"voicelineId\": 2123, \"voicelineType\": \"71006\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于着物…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_kimono_heroine\", \"description\": \"派蒙：唉，听小仓澪说，高档着物的存货太少，就算有摩拉也很难买到。\\n派蒙：好可惜，派蒙也想穿上那些漂亮衣服。\\n{NICKNAME}：不过，现在锁国令已经解除，「小仓屋」应该能从璃月进口绸缎了。\\n派蒙：太好了，新衣服有希望了！\\n派蒙：想象一下，穿上「小仓屋」私人定制着物的我，一定会大有不同！\\n派蒙：摆脱掉传奇故事中的主角小跟班印象，升格为英雄宿命中的友人。\\n派蒙：哇，感觉好棒。\\n派蒙：{NICKNAME}，你一定也这么觉得吧？所以…\\n{NICKNAME}：说到底就是想要我付账嘛。\\n派蒙：这么快就领悟了，不愧是「宿命中的友人」！\\n派蒙：我想要七件不同的，每天都可以换着穿！花纹的话…我想想…\\n{NICKNAME}：…突然感觉不想买了！\", \"voicelineId\": 2124, \"voicelineType\": \"71035\", \"unlockConditions\": [{\"paramList\": [1204209], \"unlockText\": \"完成「须臾百梦」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于罐装知识…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_cannedKnowledge_heroine\", \"description\": \"派蒙：不用读书就能知道好多东西，罐装知识真是太方便了！\\n派蒙：不知道须弥，有没有关于七国风土人情的罐装知识…\\n派蒙：要是有的话，每到一个新的地方，我就替你打开一个新罐头，就不用再多费口舌了！\\n{NICKNAME}：那也不用去新的地方，在须弥就能全都打开了吧。\\n派蒙：这、这是为了保持旅程的期待感嘛！\\n{NICKNAME}：而且这么一来，也不用派蒙来当向导了…\\n派蒙：不行不行，我们还是把买罐头的摩拉省下来吧！\\n派蒙：省下来…当我的小费！嘿嘿，合情合理。\", \"voicelineId\": 2131, \"voicelineType\": \"71036\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于镀金旅团…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_gildedBrigade_heroine\", \"description\": \"派蒙：镀金旅团内部还真是鱼龙混杂呢…\\n{NICKNAME}：这就是所谓的多样性吧。\\n派蒙：喔——我能理解你在说什么呢！因为派蒙自己也有很多样子。\\n派蒙：有犀利评论的样子，有博学可靠的样子，还有乐于助人的样子…\\n{NICKNAME}：明明是完全没有理解的样子…\", \"voicelineId\": 2132, \"voicelineType\": \"71037\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于信仰…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_faith_heroine\", \"description\": \"派蒙：你发现了吗？须弥人看上去不是很相信小草神的样子。\\n派蒙：之前不管是在璃月还是稻妻，大家明明都很相信岩王帝君和将军大人的。\\n派蒙：那些奇奇怪怪的学者先不提，就算是住在下面的居民，每天也只是把「树王大人」挂在嘴边。\\n{NICKNAME}：嗯，就连好吃的蘑菇也说是树王的恩惠呢。\\n派蒙：这样说来，我们在璃月的时候，也有很多美食，据说得到过岩王帝君的认可和指点呢！\\n派蒙：我知道了！只要能带来好吃的东西，人们就会喜欢那样的神明。\\n{NICKNAME}：应该只有派蒙才会这样吧。\\n派蒙：欸？那{NICKNAME}会相信什么呢？\\n{NICKNAME}：我的话，当然是相信派蒙咯。\\n派蒙：嘿嘿，这个你不用说我也知道啦！\", \"voicelineId\": 2133, \"voicelineType\": \"71038\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于防沙壁…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_sandPreventWall_heroine\", \"description\": \"派蒙：防沙壁，第一次看到的时候真是吓了一大跳，根本看不到尽头…\\n{NICKNAME}：毕竟在当时是为了保护整片雨林而建立的。\\n派蒙：而且，真的很高很高。\\n派蒙：真不知道{NICKNAME}能不能爬上去呢。\\n{NICKNAME}：应该不行吧，为什么我非要爬那个不可？\\n派蒙：欸，可是因为防沙壁就在那里。\\n{NICKNAME}：不，就算你这么说…\\n派蒙：防沙壁就在那里呢！\\n{NICKNAME}：好了好了，但再怎么说防沙壁也太…\\n派蒙：可是防沙壁…\\n{NICKNAME}：知道了！我现在就去！\", \"voicelineId\": 2134, \"voicelineType\": \"71039\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于虚空终端…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_voidTerminal_heroine\", \"description\": \"派蒙：须弥的学者们好像都会戴着虚空终端，从虚空中获得知识。\\n派蒙：感觉像是随身带着一本活着的百科全书一样，有点羡慕。\\n{NICKNAME}：一点也不羡慕，我也随身带着一本更高级的百科全书，不仅会自动跟随，还会说话。\\n派蒙：欸？是在夸我吗？哎呀，有点不好意思。其实我也没有知道很多啦，最多就是九十九科全书。\\n{NICKNAME}：如果这本九十九科全书不吃东西就更好了。\\n派蒙：喂——\", \"voicelineId\": 2135, \"voicelineType\": \"71040\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于兰那罗用的称呼…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_aranaraName_heroine\", \"description\": \"派蒙：兰罗摩，兰拉娜，兰拉迦，兰加惟…唔，兰那罗的名字还真是难记…\\n派蒙：唯一能确定的就是名字最开始一定是个兰字！\\n{NICKNAME}：如果派蒙是兰那罗的话，派蒙的名字就会变成兰派蒙呢。\\n派蒙：是呢，如果是{NICKNAME}…\\n派蒙：这么说来，如果是称呼你的话，他们都会叫那菈{NICKNAME}呢…\\n{NICKNAME}：那菈就是他们对我们的称呼吧…\\n派蒙：那如果有个名字是那菈的家伙，被他们称呼的话会变成什么样？\\n{NICKNAME}：那菈那菈…吧，感觉有点可爱。\\n派蒙：嘿嘿，确实呢。\", \"voicelineId\": 2136, \"voicelineType\": \"71041\", \"unlockConditions\": [{\"paramList\": [7303208], \"unlockText\": \"完成「？？？」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于兰那罗的料理…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_aranaraFood_heroine\", \"description\": \"派蒙：不知道为什么，兰那罗的料理味道都…该怎么说好呢，都过于纯粹了。\\n派蒙：感觉和平时吃到的很不一样呢。\\n{NICKNAME}：嗯，但是食材都是相当好的食材…\\n派蒙：是啊是啊，蘑菇也好，水果也好，吃着吃着都感觉要在嘴里重新生长了一样！\\n{NICKNAME}：虽然有点夸张了，不过确实，好的食材或许也不用复杂的烹饪方式。\\n派蒙：说的也是，如果食材本身足够好，简单的烹饪方式也能获得极致的美味！\\n{NICKNAME}：就像派蒙，只要…\\n派蒙：喂！我们的冒险旅途都已经到须弥了，你怎么还在开这样过时的玩笑啦！\", \"voicelineId\": 2137, \"voicelineType\": \"71042\", \"unlockConditions\": [{\"paramList\": [7303208], \"unlockText\": \"完成「？？？」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于多莉的镇灵…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_dorisGenie_heroine\", \"description\": \"派蒙：这么大的精灵，是怎么进到灯里的呢？\\n{NICKNAME}：派蒙也可以进去试试。\\n派蒙：——进不去，怎么想都进不去吧！\\n{NICKNAME}：那用尘歌壶试试？\\n派蒙：哦哦，原来还有这种方法，快让我试试！\\n{NICKNAME}：派蒙很有兴致嘛…\\n派蒙：我早就想试试这种展开了——嘿！是你召唤了我吗？异乡的旅行者哟。\\n派蒙：快来实现我的三个愿望吧！第一个是…带我去吃好吃的！\\n{NICKNAME}：为什么是你来许愿啊！\", \"voicelineId\": 2138, \"voicelineType\": \"71043\", \"unlockConditions\": [{\"paramList\": [1100811], \"unlockText\": \"完成「翠石砌玉壶·其一」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于健康之家…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_homeOfHealth_heroine\", \"description\": \"派蒙：哇，须弥居然…还能免费看病吗！\\n{NICKNAME}：派蒙有哪里不舒服吗？\\n派蒙：现在还没有，谢谢你的关心。\\n派蒙：不过我从很久以前开始就一直想试试，一边吃冰棍一边吃火锅了！\\n{NICKNAME}：肯定会吃坏肚子吧！\\n派蒙：反正看病是免费的嘛，不看病不会觉得哪里亏了吗？\\n{NICKNAME}：嗯…但是换个角度的话，在治病的时候，饮食会被限制哦。\\n派蒙：欸！不能再吃好吃的了吗？\\n{NICKNAME}：还会给派蒙开很苦的药。\\n派蒙：好、好吧！那我再想想…\", \"voicelineId\": 2139, \"voicelineType\": \"71044\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于学者…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_scholar_heroine\", \"description\": \"派蒙：须弥城里真的有好多人希望成为学者呢。\\n派蒙：在这种愿望的推动下，他们都学习得好努力…\\n派蒙：不过，我觉得第一位学者的愿望肯定不是「成为学者」吧？\\n派蒙：唔…那第一位学者的愿望，到底会是什么呢…\\n{NICKNAME}：我想，大概就是「快点写完这篇论文」吧。\\n派蒙：欸？一般来说不都是，追求究极的，最最厉害的知识吗？\\n派蒙：在这种求知欲的驱使下，渐渐成为第一位真正意义上的学者…\\n{NICKNAME}：求知的具体方法就是论文啦。\\n派蒙：可是，那个究极的，最最厉害的知识…\\n{NICKNAME}：要证明这件事，也需要论文啦。\\n{NICKNAME}：然后，为了证明你的论文，又要开始写另外一篇论文…\\n派蒙：好、好了啦！我知道了，不要露出这么难过的表情！你又不用写论文！\\n派蒙：你、你没写过吧…\", \"voicelineId\": 2140, \"voicelineType\": \"71045\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于生论派…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_zoologySchools_heroine\", \"description\": \"派蒙：我想去拜访生论派的学者们！\\n{NICKNAME}：派蒙怎么突然勤学好问了起来？\\n派蒙：因为我听说生论派的学者们主要研究的内容是自然和生态。\\n派蒙：那么一定有研究各种动物能不能吃、好不好吃的学者吧！\\n派蒙：我觉得帮助这样的学者进行研究，一定会非常有意思。\\n{NICKNAME}：你只是想吃咖喱了吧？\\n派蒙：不，我真的觉得这是一件很有意义的事情。\\n{NICKNAME}：那…这样的学者，一定会先对派蒙是什么物种，有什么行为习惯产生好奇吧。\\n派蒙：我，我突然想起来我们好像有更要紧的事情！\", \"voicelineId\": 2141, \"voicelineType\": \"71046\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于驮兽…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_sumpterBeast_heroine\", \"description\": \"派蒙：那些驮兽真可爱，养驮兽的人还会根据特性，给它们专门起名字呢。\\n{NICKNAME}：说不定它们也在给我们取名字，并且用来回应我们呢。\\n派蒙：咦？他们会给我们起什么名字啊？\\n{NICKNAME}：哞——\\n派蒙：谁听得懂啦！\\n{NICKNAME}：大意就是…\\n{NICKNAME}：「白白矮矮香香吵吵事情多多双足兽」。\\n{NICKNAME}：当然啦，这是学名的全称。\\n派蒙：哦，所以呢，那简略的称呼要怎么说？\\n{NICKNAME}：「吵吵双足兽」。\\n派蒙：喂！怎么只留下不好的特点了啊！\", \"voicelineId\": 2142, \"voicelineType\": \"71047\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于第七学派…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_sevenSchools_heroine\", \"description\": \"派蒙：须弥有六大学派呢。\\n派蒙：感觉很有趣，派蒙也想要拥有自己的学派！\\n派蒙：有了…就叫做派蒙派吧！\\n{NICKNAME}：那派蒙派代表的智慧是什么？\\n派蒙：唔…是实用生活智慧！\\n{NICKNAME}：所以特色学科是史莱姆的一百种吃法、绝不放过映入眼帘的任何一摩拉、如何给人起难听的绰号…之类的？\\n派蒙：哇，你真了解我！还可以加上「如何成为提瓦特最棒的向导」！\\n派蒙：我觉得非常厉害，我们快去教令院提交学派申请吧！今后{NICKNAME}就是派蒙派大贤者了！\\n{NICKNAME}：我可以拒绝吗…\", \"voicelineId\": 2143, \"voicelineType\": \"71048\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于蕈猪…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_fungiPig_heroine\", \"description\": \"派蒙：你知道吗，须弥有各种各样奇特的蕈类。\\n{NICKNAME}：嗯，有意思的是，据说有些林猪离不开蕈类，逐渐就形成了共生关系，于是便被称为蕈猪。\\n派蒙：哇，那和我们很像呢！我也离不开{NICKNAME}。\\n{NICKNAME}：派蒙离不开我，所以我是蕈，派蒙就是…\\n派蒙：猪！ \\n派蒙：欸？喂——\", \"voicelineId\": 2144, \"voicelineType\": \"71049\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于大巴扎…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_grandBazaar_heroine\", \"description\": \"派蒙：大巴扎居民们真是多才多艺啊！\\n派蒙：不仅会卖自己做的编织品、好看的瓶瓶罐罐，闻到味道肚子就会饿的香料…\\n派蒙：还个个能歌善舞，好让人羡慕！\\n{NICKNAME}：只要有心，派蒙也可以学哦。\\n派蒙：欸？真的吗？\\n{NICKNAME}：就拿跳舞举例吧，派蒙是有先天优势的。\\n{NICKNAME}：既不会绊倒自己，也不会踩到舞伴的脚…\\n派蒙：对哦！我都忘记会飞是那么方便的事了！\\n派蒙：走吧，快点去大巴扎那晃悠晃悠，让大家都来羡慕我！\\n{NICKNAME}：原来你是想去攀比吗？\", \"voicelineId\": 2145, \"voicelineType\": \"71050\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于占卜…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_divination_heroine\", \"description\": \"派蒙：说起来，须弥的人似乎很热衷于算命占卜。\\n派蒙：除了学者们才会的占星术之外，普通须弥人用咖啡就能进行占卜！\\n{NICKNAME}：毕竟是智慧的国度，大家的好奇心都很强吧。\\n派蒙：我听他们说，只要根据咖啡喝完之后杯底上的形状，就能知道一个人的命运…\\n派蒙：和爬到塔上面看一晚上星星比起来，要方便多了呢！\\n{NICKNAME}：派蒙也想知道自己的命运吗？\\n派蒙：嗯…不过比起命运，我还是更想知道咖啡好不好喝。\", \"voicelineId\": 2146, \"voicelineType\": \"71051\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「普尔比鲁尼」与「普尔希娜」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_purbiruniAndPursina_heroine\", \"description\": \"派蒙：唔…先前听海迪夫和阿妮萨他们提到过，什么「普尔比鲁尼」一门、「普尔希娜」一门的…\\n派蒙：那些…普尔这、普尔那的，都是什么呀？\\n{NICKNAME}：「普尔」是「后嗣」的意思，也是「学徒」的意思…所以这个就是说，他们都是古代大贤者的徒子徒孙。\\n派蒙：原来是这样呀…看他们炫耀来炫耀去的，我还以为是什么值得骄傲的称呼呢。\\n{NICKNAME}：欸…？\\n派蒙：拿我来说吧，有人说我是谁的爸爸或者妈妈，我才会开心！但随便认别人是我的爸爸妈妈…不会很尴尬吗？\\n{NICKNAME}：唔…从没想过这种问题…\", \"voicelineId\": 2147, \"voicelineType\": \"71052\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于留学…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_abroad_heroine\", \"description\": \"派蒙：在教令院里不仅能见到须弥当地人，也还能见到来自其他国度的留学生。\\n派蒙：为了学习知识，离开家乡，前往陌生的土地，真是了不起！\\n{NICKNAME}：我们也经常前往陌生的土地。\\n派蒙：对哦，那…我们也真是了不起！\\n{NICKNAME}：可我们并不是为了学习知识才来的。\\n派蒙：唔…总感觉输给那些留学生了。\\n派蒙：不过，我们知道了须弥哪里有好吃的、哪里有可靠的人。这些也算是知识吧？\\n{NICKNAME}：唔，算。并且对于很多人来说是很宝贵的知识。\\n派蒙：所以我们确实很了不起！\", \"voicelineId\": 2148, \"voicelineType\": \"71053\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于圣树…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_sacredTree_heroine\", \"description\": \"派蒙：整个须弥城都建在大树上面，感觉很不可思议呢！\\n派蒙：我们之前也见过很多很厉害的树吧。风起地的「老地方」，雪山的「忍冬之树」，还有稻妻的「神樱树」！\\n派蒙：不过说起这棵树，大家好像只是叫它圣树什么的…\\n{NICKNAME}：有时候越重要的东西名字越简单呢。\\n派蒙：是这样吗？不过也对，名字太长的话每天念起来也很麻烦吧。\\n派蒙：反正只要城里的人说起「树底」，都知道是指这棵树的下面，不会走错地方就好啦。\\n派蒙：那句话怎么说的来着，「名字只是代号」？\\n{NICKNAME}：这么说派蒙也是代号咯？\\n派蒙：唔，好像也没错…才不是吧，派蒙就是派蒙！\", \"voicelineId\": 2149, \"voicelineType\": \"71054\", \"unlockConditions\": [{\"paramList\": [3, 4], \"unlockText\": \"解锁「蒙德 风起地」七天神像-风\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [3, 204], \"unlockText\": \"解锁「蒙德 雪葬之都·旧宫」七天神像-风\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [3, 306], \"unlockText\": \"解锁「稻妻 稻妻城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于学派关系…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_schoolsRelation_heroine\", \"description\": \"派蒙：你说，须弥有那么多不同学派的学者，他们在讨论的时候会不会吵起来？ \\n派蒙：就像是璃月的璃菜月菜之争一样。\\n{NICKNAME}：会吧，学派之间有矛盾再正常不过了。就像是璃月的武侠小说里说的那样：「有人的地方，就有争斗」。\\n派蒙：唔啊，好沉重的台词。不过他们应该不至于像侠客一样决斗吧。\\n{NICKNAME}：也许他们会来一局「七圣召唤」。\\n派蒙：喔，对哦！用智慧决斗。\\n派蒙：我来想象一下：在不能说服对方的情况下，拿出卡牌，坐下来冷静思考，取得胜利。\\n{NICKNAME}：确实很有须弥的风格。\\n派蒙：赢家在胜利后还会说出一句「打得不错！」表达对对手的尊敬，最后双方重归于好。\\n{NICKNAME}：不…这句话只会让矛盾升级。\\n派蒙：欸…为什么？\", \"voicelineId\": 2150, \"voicelineType\": \"71055\", \"unlockConditions\": [{\"paramList\": [3, 128], \"unlockText\": \"解锁「璃月 璃月港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于奥摩斯港…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_portOrmos_heroine\", \"description\": \"派蒙：唔，奥摩斯港的氛围与须弥城里完全不一样呢…\\n派蒙：热热闹闹的，还有好多外国人，大家都不用埋头读书忙学业，真好呀。\\n{NICKNAME}：就是因为他们不好好读书，所以才会被那些港务官管教，派蒙可别学他们哦！\\n派蒙：哦…\\n派蒙：不对！你这是什么口气啦！\", \"voicelineId\": 2151, \"voicelineType\": \"71056\", \"unlockConditions\": [{\"paramList\": [3, 501], \"unlockText\": \"解锁「须弥 奥摩斯港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「二十九海洋代伊联盟」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_29thOceanAlliance_heroine\", \"description\": \"派蒙：听说奥摩斯港原本是在一个叫「二十九」…唔…什么什么联盟留下的堡垒遗迹。\\n派蒙：哇啊，名字好长！记不得了！总之，须弥的书呆子们都是这么说的呢。\\n{NICKNAME}：是「二十九海洋代伊联盟」。\\n{NICKNAME}：那个呀…据说是由一群桀骜不驯，互不从属的海盗头子组成的海盗团。他们从一开始就彼此争斗劫掠不休，搅得须弥沿海不得安宁…\\n{NICKNAME}：后来终于有一天，他们决定各自公平划分权力，组成一个和平的「联盟」，「联盟」的「盟主」们，就叫做「代伊」…\\n派蒙：哦…所以他们就…不再互相打架，不再互相抢东西了，大家和平共处，有钱一起赚！对吧！\\n{NICKNAME}：……\\n派蒙：对吧…？\\n{NICKNAME}：嗯…至少他们也想这样吧…\\n派蒙：欸…？\\n{NICKNAME}：后来他们拉帮结派，掀起了一场更大的内战，把奥摩斯港的要塞打成了一堆废墟，所有「代伊」全都完蛋啦！\\n派蒙：欸——！\\n{NICKNAME}：就这样，奥摩斯港在前所未有的和平中重新发展了起来，成了现在的样子…\\n派蒙：什么嘛…原来只是一群单纯的坏东西而已…\", \"voicelineId\": 2152, \"voicelineType\": \"71057\", \"unlockConditions\": [{\"paramList\": [3, 501], \"unlockText\": \"解锁「须弥 奥摩斯港」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺与七圣召唤…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_cynoAndCard_heroine\", \"description\": \"派蒙：话说，赛诺是不是特别喜欢玩那种叫做「七圣召唤」的牌类游戏来着？\\n派蒙：明明是「大风纪官」，却喜欢玩牌，真奇怪啊…\\n{NICKNAME}：看到他的发型之后我就一点也不奇怪了。\\n派蒙：欸？玩牌和发型有什么关系？\\n{NICKNAME}：在打牌的时候，越是夸张的发型就越能吸引住敌人的注意力。\\n{NICKNAME}：「这家伙搞什么啊，这么夸张的发型到底是怎么梳出来的？」\\n{NICKNAME}：让对手的脑子里都被这种想法填满之后，就可以在牌桌对决上占得先机了。\\n派蒙：是这样吗？那我们以后还是别轻易和赛诺打牌了吧…\\n{NICKNAME}：我倒是觉得，我和赛诺打牌会占得优势喔。\\n派蒙：可是你的发型很普通啊，也没有穿奇怪的衣服…\\n{NICKNAME}：但是我有派蒙啊。\\n{NICKNAME}：「这家伙搞什么啊，后面飘着的那个小东西到底是干什么的？」\\n{NICKNAME}：只要派蒙飘在我旁边，赛诺的脑子会被这种想法填满。\\n{NICKNAME}：但我却不会对他的发型惊讶，这样子我就可以轻松抢得先机了。\\n派蒙：你还不如去弄一个特别的发型啦！\", \"voicelineId\": 2153, \"voicelineType\": \"71058\", \"unlockConditions\": [{\"paramList\": [3, 598], \"unlockText\": \"解锁「须弥 须弥城」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于须弥的儿歌…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_sumeruNurseryRhyme_heroine\", \"description\": \"派蒙：「咖喱~咖喱的香味~就是孩子们回家的信号~♪」\\n{NICKNAME}：「咖喱的香味~♪」\\n派蒙：哇！接得真棒，原来你也一直记得这段旋律呢！\\n{NICKNAME}：派蒙不也唱得很好嘛？\\n派蒙：嘿嘿，那是因为我有一个伟大的计划！\\n派蒙：你听过那个故事吗？从前有一只丘丘狗，当丘丘萨满跳起舞的时候，它就能分到肉吃。后来，它只要一听到舞步声，就会流口水。\\n派蒙：听到咖喱歌的时候，就能吃到咖喱。那我只要把它记熟，哪天想吃一顿美美的咖喱，提前哼一哼就行了。\\n派蒙：喂，你怎么不说话？\\n派蒙：「咖喱~咖喱的香味~就是孩子们回家的信号~♪」\", \"voicelineId\": 2154, \"voicelineType\": \"71059\", \"unlockConditions\": [{\"paramList\": [7303208], \"unlockText\": \"完成「？？？」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于兰那罗绕口令…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_xm_aranaraTongueTwister_heroine\", \"description\": \"{NICKNAME}：派蒙有没有觉得「兰那罗」这个名字，还挺难念的？\\n派蒙：嗯？难念吗？是不是你平时说话太少了呀。\\n派蒙：像我天天说话，嘴皮子特别利索，从来不会咬到舌头。\\n{NICKNAME}：那你读一下这个。\\n派蒙：什么嘛，我看看。\\n派蒙：打南边来了个兰拉娜，兰拉娜练着兰迦拉梨。\\n派蒙：打北边来了个那菈拉娜，那菈拉娜捧着帕蒂沙兰。\\n派蒙：捧着帕蒂沙兰的那菈拉娜想带练着兰迦拉梨的兰拉娜去酒馆找兰巴德，练着兰迦拉梨的兰拉娜想带捧着帕蒂沙兰的那菈拉娜去桓那兰那。\\n派蒙：那菈拉娜拗不过兰拉娜，和兰拉娜去桓那兰那见到了叫兰罗摩的兰那罗…\\n派蒙：这，这一定是做梦吧。\\n派蒙：我的眼前…出现了星星…\", \"voicelineId\": 2155, \"voicelineType\": \"71060\", \"unlockConditions\": [{\"paramList\": [7303208], \"unlockText\": \"完成「？？？」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「预言危机」的应对…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_predictCrisis_heroine\", \"description\": \"派蒙：我突然想到了一个好办法，来应对枫丹的「预言危机」！\\n{NICKNAME}：派蒙有什么高见？\\n派蒙：枫丹不是有用来挖掘隧道的大型工程发条机关吗，为什么不把那个丢到水下最深的地方挖洞呢？挖一个会漏水的洞出来，上面涨再多也不怕了。\\n{NICKNAME}：听起来好像挺有道理的，但是下面漏掉的水去哪儿了呢？\\n派蒙：哎呀，这个就不用考虑了嘛！你想呀，要是你的钱包破了个洞，就算再仔细认真地考虑摩拉去了哪里，它也绝对不可能鼓起来的。\\n{NICKNAME}：原来你对我存不住钱的原因这么了解哦。\\n派蒙：干嘛…干嘛看着我说这句话呀…你钱包的洞，跟我、跟我又…没关系…是这样吧？\", \"voicelineId\": 2162, \"voicelineType\": \"71061\", \"unlockConditions\": [{\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魔术…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_magic_heroine\", \"description\": \"派蒙：林尼的魔术表演真精彩，在解答之前，完全想不到他是怎么做到的！\\n{NICKNAME}：啊，我突然想到了一个魔术。\\n派蒙：欸？你也会魔术？\\n{NICKNAME}：嗯，我会把大大的魔术帽悬浮在空中，还能让它听我的指示飘来飘去。\\n派蒙：哇！真的吗？怎么办到的呀？\\n{NICKNAME}：嘿嘿，因为派蒙在帽子里呀。\\n派蒙：欸？为什么我在…哦！是我让它飘起来的呀！\\n派蒙：嘿嘿，那我也想到了一个魔术！\\n{NICKNAME}：哦？说来听听。\\n派蒙：你往这个帽子里塞好多好吃的，会发现它怎么装都装不满！\\n{NICKNAME}：呃…那盘子怎么办？\\n派蒙：哦对！这帽子还会自己把盘子吐出来，很神奇吧！\", \"voicelineId\": 2163, \"voicelineType\": \"71062\", \"unlockConditions\": [{\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于飞行专利…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_flyingPatent_heroine\", \"description\": \"派蒙：枫丹的「巡轨船」好方便！要是没有轨道也能用就好了，去哪儿都不用自己费力气。\\n{NICKNAME}：派蒙不是一直在飞吗？也会觉得累吗？\\n派蒙：飞…飞…对哦！要是能让「巡轨船」飞起来的话，不就不用轨道了吗！嘿嘿，就叫它「飞空船」好了！\\n派蒙：快，我们去申请哪个什么…「专利」！这么天才的点子，可不能让别人抢了先！\\n{NICKNAME}：只想出一个名字可申请不了专利啊，还得有能让船飞起来的方案。\\n派蒙：方案吗？唔…比如说…比如说…在船顶安一个巨大的螺旋桨！ \\n{NICKNAME}：那怎么保证船不会跟着螺旋桨一起转？又怎么控制飞行的方向？\\n派蒙：这个…那个…唉，飞行原来是这么麻烦的事吗？我平时都没注意到…\\n{NICKNAME}：嗯…不过不考虑方向和速度的话，还有一个简单的方案。\\n派蒙：欸？真的吗！\\n{NICKNAME}：找一个足够高的出发点，然后向下加速飞。\\n派蒙：喂！那不就是坠落吗！\", \"voicelineId\": 2164, \"voicelineType\": \"71063\", \"unlockConditions\": [{\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于出版行业的黑暗…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_publishingIndustry_heroine\", \"description\": \"派蒙：《蒸汽鸟报》连载的《大侦探赫尔洛克》，最后的合本也会在稻妻八重堂出版吧。\\n{NICKNAME}：似乎是这样没错。\\n派蒙：明明拥有这么厉害的印刷和配送能力，为什么不自己出版呢？\\n{NICKNAME}：哼哼，这就是出版行业的黑暗了。\\n派蒙：一副看穿了一切的嘴脸！那你说说，为什么能联络全大陆的《蒸汽鸟报》不能自己出版小说吧。\\n{NICKNAME}：小说最重要的是——\\n派蒙：最重要的是…？\\n{NICKNAME}：插画！\\n派蒙：给全大陆辛苦写作、想点子的小说家和编辑们道歉啊！\\n{NICKNAME}：八重堂手上可是握有很多优秀插画师的，想轻易挖角这些人恐怕不容易哦。比如白垩老师这样的，除了八重堂根本就没有手段联系上。\\n派蒙：哦哦，这点确实呢。\\n{NICKNAME}：还有就是…\\n派蒙：就是？\\n{NICKNAME}：只有被八重堂出版了，才有可能和《七圣召唤》联动！\\n派蒙：原、原来是这样吗！\\n{NICKNAME}：出版行业最大的黑暗就是——故事不重要，发掘商业价值的能力更重要！\\n派蒙：太黑暗了！\", \"voicelineId\": 2165, \"voicelineType\": \"71064\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于足不出户的侦探…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_detectiveIndoor_heroine\", \"description\": \"派蒙：听说枫丹廷有足不出户就能解明真相的侦探。\\n派蒙：这就是所谓的居家办公吧？听起来很轻松呢！\\n派蒙：不过话说回来，不亲自去现场调查，究竟是靠什么推理出真相的呢…啊，我知道了！一定是用占卜吧？\\n{NICKNAME}：那应该叫占卜师而不是侦探吧。\\n派蒙：对、对哦…\\n{NICKNAME}：案件的线索可不会自己长脚还专程到侦探府上拜访。\\n派蒙：也就是说，一定有人帮侦探收集线索…\\n{NICKNAME}：说不定我们在冒险家协会接到的委托里有一部分就是…\\n派蒙：欸？那原本应该给我们的报酬岂不是会被侦探拿走一部分？那可不行！我们现在就去找侦探抗议！\", \"voicelineId\": 2166, \"voicelineType\": \"71065\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫丹科学院的神秘宝藏…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_mysteriousTreasure_heroine\", \"description\": \"派蒙：枫丹科学院是研究发条机关和各种能量的学术机构对吧？为什么会有神秘宝藏的传闻…\\n派蒙：如果是什么怪盗的宝藏、海贼的宝藏，倒是比较容易理解啦。\\n派蒙：研究员的宝藏、高阶技官的宝藏…总觉得听起来缺少冲击力…\\n{NICKNAME}：如果有人白天是研究员，晚上是怪盗…这种神秘人物留下的神秘宝藏呢？\\n派蒙：唔…听起来好辛苦的样子…白天也要工作，晚上也要工作，那什么时候才能休息啊？\\n{NICKNAME}：也许这位神秘人物的真实身份是发条机关，这样就不用休息了。\\n派蒙：白天是研究员，晚上是怪盗的神秘发条机关留下的神秘宝藏…听起来真的很神秘呢！\", \"voicelineId\": 2167, \"voicelineType\": \"71066\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于侦探小说的大忌…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_detectiveNovel_heroine\", \"description\": \"派蒙：《大侦探赫尔洛克》、《奥西兹小姐事件簿》…枫丹很流行这种侦探、推理小说呢。\\n{NICKNAME}：派蒙能看懂吗？\\n派蒙：你也太看不起我了吧！如果让我来看的话，一定看到一半就猜出来凶手了。\\n{NICKNAME}：千万记得不要剧透别人哦。\\n派蒙：不会干这种事的啦。\\n{NICKNAME}：不过也有一些人，喜欢拿着「不要剧透」的名义打压别人的讨论。其实他们只是自己不想看到讨厌的作品有人气罢了。\\n派蒙：我不怎么看书，倒是不太了解这种情况呢。\\n{NICKNAME}：比如说两个爱好者正在讨论《鬼武道》，这种家伙就会突然插进去说「我第一卷第二章还没有看，不要继续剧透我啦！」\\n派蒙：那不就是根本没怎么看吗！\\n{NICKNAME}：我和你说一个秘密哦，派蒙。\\n派蒙：嗯，怎么突然…\\n{NICKNAME}：其实…\\n派蒙：其实…\\n{NICKNAME}：其实，钟离就是岩王帝君。\\n派蒙：震惊！你居然剧透我——才怪，这不是早就知道了吗！\", \"voicelineId\": 2168, \"voicelineType\": \"71067\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于正当防卫与互殴…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_defenseAndFight_heroine\", \"description\": \"{NICKNAME}：在枫丹如果被打了，没有目击者可千万不要随意还手。\\n派蒙：欸，为什么？\\n{NICKNAME}：如果没有证据，很可能最后不会被判正当防卫，而是互殴。\\n派蒙：那会怎么样呢？\\n{NICKNAME}：那样的话，很大概率会最后走入决斗审判的环节。\\n{NICKNAME}：到这一步，就只能亲自下场和对方继续互殴了，或者请决斗代理人进行互殴。\\n派蒙：…还好你很能打。\", \"voicelineId\": 2169, \"voicelineType\": \"71068\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于《蒸汽鸟报》编辑部…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_steambirdEditorial_heroine\", \"description\": \"派蒙：啊，昨天发生的事，立刻就出现在了今天的《蒸汽鸟报》上…\\n派蒙：还有昨日深夜发生在城外的事故，这些报道到底是什么时候写的。\\n{NICKNAME}：而且还能在一大早刊印出来。\\n派蒙：哼哼，我知道了，说不定《蒸汽鸟报》内部有一个魔法打印机，各地的记者只要带来报道，它就会把文章「吭哧吭哧」吃进去，然后到了要发印的节点，全部吐出来！\\n派蒙：说不定已经快到打印时间了，还有记者闯进门来，说「等等，我还有一篇报道没有被吃进去」呢。\\n{NICKNAME}：这种画面倒是很容易想象到，不过据我所知可没有这样的打印机。每天能够有报纸正常发刊，都是《蒸汽鸟报》员工的功劳。「哼哧哼哧」地检查错别字，「哗啦哗啦」地把文字内容拼成一个个大方块，「实在不行了，求求了再等五分钟吧」地联系其他人，这就是名为编辑部的魔法。\\n派蒙：真厉害啊，《蒸汽鸟报》的编辑部，用一天时间就能做出这样的一份报纸，他们不会都不用睡觉吧…\", \"voicelineId\": 2170, \"voicelineType\": \"71069\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫丹的小说…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_fontaineNovel_heroine\", \"description\": \"派蒙：唔，《发条机关会梦见齿轮正骨师吗？》枫丹也有些标题很长很奇怪的小说呢。\\n派蒙：不过和稻妻的轻小说相比，写法和题材好像都有些不一样。\\n{NICKNAME}：我看看简介，故事讲述因为长期弓身导致背脊疼痛的发条机关，终于不堪重负放弃了绘制报纸插画的工作，四处寻找能够拯救它机械背脊的按摩师…\\n派蒙：听上去还蛮有意思的嘛。\\n{NICKNAME}：可是也太奇怪了，这个发条机关为什么要找按摩师，为什么不直接找那些工程师帮它处理，比如…嗯，枫丹科学院的工程师？\\n派蒙：呃，不过，枫丹科学院的工程师感觉都有些…\\n{NICKNAME}：那倒也是。哎，虽然这个故事是以发条机关为主角，不过一看就知道还是人写的啦。如果真的让发条机关执笔的话，会写出什么样的故事呢？\\n派蒙：我想想…《一觉醒来，变成肉做的人！》\\n{NICKNAME}：噢，派蒙很有想象力嘛。\", \"voicelineId\": 2171, \"voicelineType\": \"71070\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于审判与表演…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_trialAndPerform_heroine\", \"description\": \"派蒙：枫丹人经常在欧庇克莱歌剧院进行审判，但是也会在里面进行表演，可是…\\n{NICKNAME}：怎么了，派蒙有什么疑问吗？\\n派蒙：如果有人在欧庇克莱歌剧院表演审判的话会怎么样呢，大家会以为那个审判是真的还是表演的呢？\\n{NICKNAME}：这倒是个好问题，说不定也有扮演被审判者的演员第二天走在街上被人认出来。「这家伙，不是昨天被审判的人吗！」\\n派蒙：对啊对啊，这难道不会造成很大的困扰吗？\\n{NICKNAME}：这个时候就要大声说，「别把演出的内容当真了！」\\n派蒙：但是表演审判的人其实就是想要别人弄混真的审判和表演的审判，真是太过分了。\\n{NICKNAME}：真是太过分了，派蒙，你居然想出了这么糟糕的主意！\\n派蒙：咦，欸，是我吗？\", \"voicelineId\": 2172, \"voicelineType\": \"71071\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫达…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_fonta_heroine\", \"description\": \"派蒙：枫达喝起来真的很痛快，你不觉得吗？\\n{NICKNAME}：嗯，一饮而下的话，就会特别神清气爽。\\n派蒙：能给我买一杯吗？我很久以前就想试试那个了！\\n{NICKNAME}：哪个？\\n派蒙：哎呀，等下我表演给你看。\\n派蒙：咕嘟咕嘟咕嘟咕嘟——\\n派蒙：哈啊——\\n派蒙：那些酒鬼干杯的时候总是这个样子，我也想试一次！\\n{NICKNAME}：别像个老头子一样啊…\", \"voicelineId\": 2173, \"voicelineType\": \"71072\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于警卫机关…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_guardMechanism_heroine\", \"description\": \"派蒙：警卫机关会执行设定好的任务，也就是说，只要提前输入命令，它们什么都能做。\\n{NICKNAME}：你又有新的想法了？\\n派蒙：是的，我需要「委托处理警卫机关」，「素材采集警卫机关」，「秘境探索警卫机关」…\\n派蒙：再加上「做饭香香警卫机关」，我们就可以迈入全自动冒险时代！\\n{NICKNAME}：可是警卫机关的持有和使用成本很高，再加上后续的维修与养护的费用…\\n{NICKNAME}：我算算，嗯，就连采集每个薄荷的平均成本都会达到六千三百摩拉…\\n派蒙：欸，好贵？！\\n派蒙：…突然感觉我们冒险生活的价值很高呢！\", \"voicelineId\": 2174, \"voicelineType\": \"71073\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于潜水…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_diving_heroine\", \"description\": \"派蒙：枫丹的水下世界好漂亮啊，有好多没见过的鱼呢！\\n{NICKNAME}：要是在其他地方也能潜水就好了。\\n派蒙：对哦，我也觉得挺可惜的…\\n派蒙：但如果可以的话，你想潜到哪里去看看呀？\\n{NICKNAME}：唔…璃月港或者孤云阁附近？\\n派蒙：哦！我懂！这些地方要是有沉船的话，一定会发现好多好多宝藏吧！\\n{NICKNAME}：还有稻妻的珊瑚宫，水下一定很漂亮。派蒙呢？\\n派蒙：我想想…你去了璃月和稻妻，那我就去蒙德的果酒湖吧！\\n{NICKNAME}：那也不错。但正当你游着游着的时候…\\n派蒙：怎…怎么啦？\\n{NICKNAME}：突然发现有什么东西慢慢沉到了你面前…\\n派蒙：欸？！\\n{NICKNAME}：那东西圆滚滚、胖嘟嘟的，身上花纹红白相间。你意识到了，这就是…\\n派蒙：蹦蹦炸弹！！\\n{NICKNAME}：嘣——！\\n派蒙：呜啊啊啊！被炸飞啦——！\", \"voicelineId\": 2175, \"voicelineType\": \"71074\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艺术…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_art_heroine\", \"description\": \"派蒙：枫丹廷里到处都是奇奇怪怪的艺术家，听说歌剧院里也经常会有艺术家登台表演。\\n派蒙：看来枫丹人真的很重视艺术呢，不愧是艺术之都。\\n派蒙：不像在须弥，就连演出都要偷偷摸摸的…\\n{NICKNAME}：看来派蒙对艺术很感兴趣呢。\\n派蒙：那当然，我对艺术可是很有研究的！\\n{NICKNAME}：那么派蒙觉得什么样的才算是艺术呢？\\n派蒙：这个嘛…艺术就是那种和一般常见的都不一样，会像星星一样闪闪发光的东西吧！\\n{NICKNAME}：嗯…这样的东西，眼前好像正好有一个呢。\\n派蒙：欸…？\\n派蒙：等等，你该不会是在说我吧。\\n{NICKNAME}：嗯嗯，仔细想想，如果把派蒙带去歌剧院里表演的话，说不定也能大受欢迎呢！\\n派蒙：才不要吧！\", \"voicelineId\": 2176, \"voicelineType\": \"71075\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于修理故障…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_troubleshooting_heroine\", \"description\": \"派蒙：奇怪…明明发条机关的结构都精密得不得了，为什么有时候出了故障，只要拍一拍就能好？\\n{NICKNAME}：大概是机关里面有哪个齿轮或者传动杆松动了吧，拍一拍晃一晃，让它们扣上了就行。\\n派蒙：欸？还是不太懂…\\n{NICKNAME}：嗯…简单来说，就是这些机关本身就没有多大故障，拍一拍就能让零件回到正常的位置。\\n{NICKNAME}：反过来说，如果是零件本身受损，就算拍散架了也修不好。\\n派蒙：哦哦…是不是说，就像有的人只是偶尔迷糊，拍拍脑门就能清醒过来。有些人本来就迷糊，就算再怎么拍也还是一样迷糊！\\n派蒙：…等等，你为什么盯着我的脑门看？\\n{NICKNAME}：放心吧，我不会拍的，反正拍了也没用。\\n派蒙：这还差不多…等等——喂！\", \"voicelineId\": 2177, \"voicelineType\": \"71076\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于梅洛彼得堡…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_fortressOfMeropide_heroine\", \"description\": \"派蒙：听说枫丹有个地方叫作梅洛彼得堡，是不是为了纪念一个叫做梅洛彼得的人修建的？\\n{NICKNAME}：我倒没听说过欸，感觉挺有可能的。\\n派蒙：真羡慕啊，拥有一座跟自己名字一样的堡垒。等你有空了，帮我在尘歌壶里弄一个好不好？我也想要一个派蒙堡。\\n{NICKNAME}：那都用不着尘歌壶，跟我去一趟枫丹廷就好了。\\n派蒙：难道要在枫丹廷买地建房子吗？那要花好多摩拉吧？\\n{NICKNAME}：花不了多少。\\n派蒙：呜哇，你现在都对我这么大方啦？\\n{NICKNAME}：因为只需要买些面包，再买些菜叶，再买些沙拉酱汁…然后…\\n派蒙：喂！不是那种可以吃的派蒙堡！这个桥段你真的要玩遍七国嘛！\", \"voicelineId\": 2178, \"voicelineType\": \"71077\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [1100811], \"unlockText\": \"完成「翠石砌玉壶·其一」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于超级机关…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_mechanism_heroine\", \"description\": \"派蒙：听说，最早的发条部件，其实有着很简单的运作原理！\\n派蒙：把一个很有韧性的，长条形的物体掰弯，然后借助它恢复成原样的力量，就能驱动齿轮之类的东西，带动机器了！\\n{NICKNAME}：很有韧性的，长条形的物体…总觉得有些耳熟？\\n{NICKNAME}：急冻树和爆炎树不也是吗！\\n派蒙：噫！为什么会想到那两个大家伙啦！\\n派蒙：不过你这么一说，它们两个确实特别能转圈呢…\\n{NICKNAME}：而且力气特别大哦，突然蓄满全力一下子抡过来的话…\\n{NICKNAME}：就算是强大的我，也会摔倒在地上！\\n派蒙：所以急冻树和爆炎树…也能被做成发条？\\n{NICKNAME}：根据冰元素生物讨厌火元素，火元素生物讨厌冰元素的原理，把急冻树和爆炎树斜着放在一起…\\n{NICKNAME}：它们就会因为讨厌彼此而不停转圈！\\n{NICKNAME}：这不就是一个超级发条机关吗！捕捉这股力量的话，大半个枫丹廷的机器都不愁没能源了！\\n派蒙：喔喔喔！好有道理！\\n派蒙：真是天才的方案！枫丹科学院的院长也想不到吧！\\n派蒙：接下来只要想办法把急冻树和爆炎树带到枫丹来，放在一起…\\n派蒙：等等，要怎么样把这两个大家伙送到枫丹来？\\n{NICKNAME}：至于成本和实现方法的问题嘛…\\n{NICKNAME}：前面的细节，以后再来讨论吧！\", \"voicelineId\": 2179, \"voicelineType\": \"71078\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于水下咖啡馆…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_underwaterCafe_heroine\", \"description\": \"派蒙：之前，我们在须弥见到了很漂亮的咖啡馆，结果枫丹人也很喜欢喝咖啡呢，和须弥人不相上下！\\n{NICKNAME}：是呀，就连报纸上的文章都在强调，咖啡的提神效果很好，还能帮助正在工作的人迅速恢复精力，保持最高效率一直上班。\\n派蒙：需要喝咖啡来恢复精力的工作，一听就很累…\\n派蒙：比如说…铁匠吗？厨师和到处跑的冒险家应该也会经常喝咖啡？还有…潜水员？\\n{NICKNAME}：咦，潜水员？派蒙好像提到了不得了的职业！\\n{NICKNAME}：潜水员在水下干活的时候，要怎么喝咖啡呢？\\n派蒙：对哦，这个问题好关键！\\n派蒙：在水里不能摘下头盔，难道要用一个更大的玻璃罩子把自己关起来，然后抽干里面的水，再安安心心地喝瓶子里的咖啡…\\n派蒙：不对，这样一说，把咖啡装在瓶子里，装上一根长长的管子，管子的另一头直接安装在头盔里边，歪歪头就能喝到了！\\n{NICKNAME}：那样咖啡就凉掉了！\\n{NICKNAME}：不热也不冰的咖啡，一点也不香！\\n派蒙：没关系，大不了就再带一个炉子去潜水。\\n派蒙：你看，枫丹人经常用来做饭的炉子只有最上边一个开口，只要把它牢牢封住，放进水里，炉火应该也不会熄灭…\\n派蒙：等等…这么巧吗？会不会…枫丹的炉子本来就有这种用法？\\n{NICKNAME}：噔噔！居然被派蒙发现了！枫丹烹饪炉的真正设计意图！\\n派蒙：不愧是我！\\n派蒙：这么说来，在水下开一间咖啡馆也不是不可能嘛！肯定会有很多潜水员来喝咖啡的，这都是商机，商机呀！\\n派蒙：只要我们开了第一家水下咖啡馆，摩拉就会滚滚掉进我们的口袋，说不定还有机会发展成水下的商业街…\\n派蒙：嘿嘿！靠商业头脑赚来的摩拉，更有满足感！\\n{NICKNAME}：要提醒派蒙的是…千万不要用我的名字向银行贷款哦！\", \"voicelineId\": 2180, \"voicelineType\": \"71079\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于蒸汽鸟报…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_steambird_heroine\", \"description\": \"派蒙：那个「蒸汽鸟报社」就在枫丹廷里呢，不知道平时这些报纸上会写什么。\\n派蒙：你说，会不会报道我们之前和特瓦林的故事呀？还有雷电将军…对了，还有教令院的事！\\n{NICKNAME}：蒸汽鸟报上应该会有很多版面吧，每一个版面都会报道不同的事。\\n派蒙：喔！那头版一定是我们经历的那些冒险啦，又精彩又引人注意！\\n{NICKNAME}：唔…我觉得不一定喔。或许会有那么一两次，但大部分时间，头版可能都是歌剧或者歌剧演员的新闻。\\n{NICKNAME}：像是某某演员突然出现在路边喝咖啡，某某演员宣布自己开始恋爱，某某演员不再演出之类的。\\n派蒙：这种没价值的新闻为什么要放在最显眼的地方？\\n{NICKNAME}：可不能说没价值，这反倒是大家最津津乐道的内容，一个激动就会愿意买下来细细品读了。\\n派蒙：唉…好吧。那…内页里的版面？买下报纸之后，内页肯定要有一些精彩内容，吸引大家继续看呀？\\n{NICKNAME}：那就是和枫丹廷有关的好消息了。比如食物、材料降价啦，水道又往外重建了多少啦…\\n{NICKNAME}：这种新闻放在一打开报纸就能看见的地方，负责的是「打发时间」。\\n{NICKNAME}：教令院的事虽然是重大新闻，但和枫丹人的生活却没有直接关系。\\n派蒙：呜…那我们的冒险会放在哪里？\\n{NICKNAME}：我想，大概会放在整份报纸彻底翻开后的版面吧。\\n派蒙：为什么要放在这么后面啦！\\n{NICKNAME}：这就是俗称的「压阵」新闻啦。\\n{NICKNAME}：他们多半还会把我们的冒险添油加醋写得很长，再把这一整篇文章拆开来，连载个三五天才算完。\\n派蒙：那这个版面负责什么？\\n{NICKNAME}：负责让这张报纸多少带上一些「存在价值」。\", \"voicelineId\": 2181, \"voicelineType\": \"71080\", \"unlockConditions\": [{\"paramList\": [3, 905], \"unlockText\": \"解锁「枫丹 枫丹廷」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}, {\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于发条机关…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_clockwork_heroine\", \"description\": \"派蒙：没想到还有会跳舞的发条机关…虽然靠近会很危险，但只是在观众席上欣赏的话感觉还挺不错的。\\n派蒙：如果还有演奏发条机关、唱歌发条机关…一定会很热闹！\\n{NICKNAME}：再加上观众发条机关，那就是——发条机关演出，发条机关欣赏，发条机关为了发条机关。\\n派蒙：不知道为什么听起来有点可怕…\\n派蒙：还是让发条机关干点别的吧！对了！如果有画画发条机关，画出来的画会不会就像留影机拍出来的一样。\\n{NICKNAME}：那直接用留影机不就好了？\\n派蒙：说的也是…唔…\\n派蒙：不行了…我的脑袋转不动了。你呢？如果现在能让你变出任意一种发条机关，你希望它承担怎样的工作？\\n{NICKNAME}：嗯，比如说向导的工作…\\n{NICKNAME}：嘎嘎，我是向导发条机关，前方的道路请保持直行，嘎嘎。\\n派蒙：这、这么说来，发条机关的维护不仅需要专业知识，成本也很高呢！而且也不知道离开枫丹之后还能不能正常运作…\\n派蒙：提瓦特大陆最好的向导是不会失业的！应该…应该不会吧？\", \"voicelineId\": 2182, \"voicelineType\": \"71081\", \"unlockConditions\": [{\"paramList\": [3, 874], \"unlockText\": \"解锁「枫丹 伊黎耶岛」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于观景喷泉…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_fountain_heroine\", \"description\": \"派蒙：说起来，每天都能看到有人往伊黎耶岛的喷泉里丢摩拉呢。\\n{NICKNAME}：嗯，据说住在泉水里的精灵能够聆听大家的愿望，所以才有这样的习俗吧。\\n派蒙：喔！所以泉水精灵也需要摩拉吗？\\n派蒙：真好啊，只要住在泉水里，每天什么都不用做，就可以从大家那里收到摩拉…\\n{NICKNAME}：我觉得应该不是那样的…\\n派蒙：「年轻的旅人啊，我已经听到了你的愿望，你掉的是这把无锋剑呢，还是这把银剑呢？」\\n{NICKNAME}：两边好像都不是什么值钱的东西呢。\\n派蒙：快选啦。\\n{NICKNAME}：「泉中的少女啊，我掉的既不是这把无锋剑，也不是这把银剑，而是与我同行的伙伴。」\\n派蒙：欸？真、真是拿你没办法…那就把泉水精灵本人送给你，作为最棒的搭档吧！\", \"voicelineId\": 2183, \"voicelineType\": \"71082\", \"unlockConditions\": [{\"paramList\": [3, 875], \"unlockText\": \"解锁「枫丹 欧庇克莱歌剧院」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于歌剧…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_opera_heroine\", \"description\": \"派蒙：枫丹的歌剧题材好多呀，除了历史故事和传说，居然还有童话和现代浪漫戏…\\n{NICKNAME}：好像还有很多冒险的故事呢。\\n派蒙：是呀，比如刚才看过的「堂克勒德与夏蕾克莱娅」，呜啊，要是男主角在那个时候认出了女主角的话…\\n{NICKNAME}：据说是真实历史改编的喔。\\n派蒙：唔，既然这样的话，那有朝一日，我们的冒险会不会也被改编成歌剧呢？\\n派蒙：毕竟，我们也经历过那么多冒险，说不定也会有感兴趣的剧作家把我们的故事搬上舞台！\\n派蒙：这样一来，他们也不必处心积虑构思悲剧啦，大家都想看点开心的故事，对吧？\\n{NICKNAME}：那样的话，我们提前考虑一下声部的划分吧？ \\n派蒙：唔，你的话，应该是青年女中音吧？而派蒙就应该是——\\n{NICKNAME}：花腔女高音？\\n派蒙：为什么啦！\", \"voicelineId\": 2184, \"voicelineType\": \"71083\", \"unlockConditions\": [{\"paramList\": [3, 875], \"unlockText\": \"解锁「枫丹 欧庇克莱歌剧院」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于美露莘…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_melusine_heroine\", \"description\": \"派蒙：听说每位美露莘在诞生时都会有一个与生俱来的信物，她们会把这个信物当作自己精神的象征。\\n{NICKNAME}：假如派蒙是美露莘的话，这个信物会是什么呢？\\n派蒙：肯定是叉子！代表吃遍全世界的好吃的！\\n{NICKNAME}：不是摩拉吗？\\n派蒙：对哦，假如是摩拉的话，不就说明我会成为大富翁。以后想买什么就买什么了吗？\\n派蒙：唔——好纠结，我都好想要！\\n{NICKNAME}：那就摩拉做的叉子吧，这样就都能有了。\\n派蒙：那真是好主意呢！\\n派蒙：如果是这样的话，你的信物一定是一口锅，负责给我做好吃的！\\n{NICKNAME}：不不不，我的信物是派蒙哦。\\n派蒙：嘿嘿，真的吗？\\n{NICKNAME}：这样派蒙的东西就都是我的啦。\\n派蒙：唔——那好吧，好朋友之间东西是要互相分享的。\\n{NICKNAME}：我的东西还是我的。\\n派蒙：喂！\", \"voicelineId\": 2185, \"voicelineType\": \"71084\", \"unlockConditions\": [{\"paramList\": [3, 877], \"unlockText\": \"解锁「枫丹 海沫村」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于沫芒宫…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_fd_palaisMermonia_heroine\", \"description\": \"派蒙：说起来，我们在城里总听人说，在沫芒宫里工作的人都很忙。\\n派蒙：但上次去沫芒宫的时候，里面压根没多少人呀？\\n派蒙：剩下的人也一副优哉游哉的样子…真不知道忙在哪里…\\n{NICKNAME}：也许，他们都在忙一些「十万火急又无足轻重」的事呢。\\n派蒙：怎么可能有这样的事情啦，都十万火急了，怎么可能无足轻重呢？\\n{NICKNAME}：有喔，比如说…派蒙有一天也许会突然飞不动，从半空摔下来…\\n派蒙：会这样吗？我飞得还挺轻松的…\\n{NICKNAME}：所以我们应该采购一些带软垫的小车，一直放在派蒙的下方。\\n{NICKNAME}：这辆小车要足够可靠，能在任何路况下跟着派蒙移动，车上的垫子也要足够软…\\n{NICKNAME}：还有牵引绳的质量，小车的材质，也许还要准备一些医疗用品和零食…\\n{NICKNAME}：毕竟，为了不让派蒙受伤，这件事当然十万火急。\\n派蒙：是这样吗？嘿嘿…也不用想得这么周到啦。\\n派蒙：但我都飞这么久了，肯定不会突然就不能飞了，不用杞人忧天啦。\\n{NICKNAME}：喏，你看，这不就是「无足轻重」吗？\\n{NICKNAME}：如果这件事真的发生了，就会产生很严重的后果，所以「十万火急」。\\n{NICKNAME}：但从各种角度来说，这件事都不太可能立即发生，所以「无足轻重」。\\n{NICKNAME}：如果一个人被分配去处理这种事，那无论是想要偷懒还是想要忙碌，都由他自己定啦。\\n派蒙：但，但是！如果我真的突然飞不动了，摔下来怎么办？！\\n{NICKNAME}：那我一定会接住派蒙的，派蒙是我重要的伙伴，可不是「十万火急又无足轻重」的事。\", \"voicelineId\": 2186, \"voicelineType\": \"71085\", \"unlockConditions\": [{\"paramList\": [3, 772], \"unlockText\": \"解锁「枫丹 沫芒宫」七天神像-水\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于回声之子的宝石…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_nanatzcayanDiamond_heroine\", \"description\": \"派蒙：说起来，这边的山谷有好多亮闪闪的宝石呢！\\n派蒙：机会难得，我们也在附近挖挖看吧。要是运气好的话，说不定就能挖到超级厉害的宝石，再也不用担心摩拉不够用啦！\\n{NICKNAME}：咦？派蒙能分辨宝石的种类吗？\\n派蒙：呃，这个…只要是亮闪闪的东西，就一定是好东西！嗯，应该是这样没错！\\n{NICKNAME}：听上去简直就像是童话故事里收集财宝的恶龙一样呢。\\n派蒙：哼哼，既然到了纳塔，就不应该叫「恶龙」，而是应该叫「贤龙」啦！\\n派蒙：「勇敢而机智的{NICKNAME}呀，就让本贤龙指引你找到超级厉害的宝石吧——」\\n{NICKNAME}：明明连宝石的种类都没办法分辨？\", \"voicelineId\": 2187, \"voicelineType\": \"71086\", \"unlockConditions\": [{\"paramList\": [3, 1252], \"unlockText\": \"解锁「纳塔 回声之子」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于悬木人…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_huitztlan_heroine\", \"description\": \"派蒙：悬木人似乎很喜欢那些看起来就非常危险的户外运动呢。\\n派蒙：什么无护具徒手攀岩，高空滑板，火山跑酷，悬崖蹦极…光是想想就让人心跳加速了！\\n{NICKNAME}：有吗？其实我们的冒险也挺危险的吧。冷风飕飕的雪山，酥酥麻麻的雷暴，黄沙乱舞的沙漠，寸草不生的死域…\\n派蒙：呃，这么说，我们这一路还真是水深火热…\\n{NICKNAME}：但我们够强，所以在普通人眼里是冒险的事情，对我们来说是家常便饭。悬木人说不定也是这样的吧。\\n派蒙：等，等一下！我可没有你那么英勇，你别把我算上。\\n派蒙：你们强者之间互相理解就好了。真要有危险的事情发生，我…我还是会躲在你身后的。\", \"voicelineId\": 2188, \"voicelineType\": \"71087\", \"unlockConditions\": [{\"paramList\": [3, 1253], \"unlockText\": \"解锁「纳塔 悬木人」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于纳塔的温泉…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_natlanSpa_heroine\", \"description\": \"派蒙：「流泉之众」的氛围真是悠闲呀，大家不是在泡温泉，就是在泡温泉的路上…\\n{NICKNAME}：听说有些温泉爱好者还会特意雇佣音乐家，在泡温泉的时候演奏舒适的音乐，这样能让身心彻底地放松哦。\\n派蒙：哇，说得我也想试试了…\\n{NICKNAME}：下次派蒙泡温泉的时候，我来为你演奏兰那罗的音乐吧。\\n派蒙：欸，但是我还没学会弹乐器，轮到你泡的时候怎么办…\\n{NICKNAME}：那派蒙就唱歌吧。嗯…选一首枫丹的歌剧如何？\\n派蒙：那也太难了！听了之后说不定没法放松心情，反而会头疼脑热的！\\n派蒙：不如来点纳塔特色的说唱吧，我刚学会的，咳咳——\\n派蒙：「hey站在你面前的就是大名鼎鼎派蒙，经历了这么多的冒险我已变得从容…」\\n派蒙：「yo见识过万水之源的海兽它叫膨膨，还有传闻之中古华派的枪剑双绝武功…」\\n{NICKNAME}：真的很有律动呢！\\n{NICKNAME}：让人有种想要一边泡温泉一边拍打水面，用溅起的水花来伴奏的冲动。\\n派蒙：像举行音乐派对一样！要是有来晚了的人，还可以一个滑铲直接滑到温泉里，加入大家的节奏！\\n{NICKNAME}：嗯？等等，我们好像完全忘记泡温泉是用来放松的了…\", \"voicelineId\": 2189, \"voicelineType\": \"71088\", \"unlockConditions\": [{\"paramList\": [3, 1254], \"unlockText\": \"解锁「纳塔 流泉之众」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于沃陆之邦…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_teteocan_heroine\", \"description\": \"派蒙：你不觉得，蒙面战士的设定非常帅气吗？\\n{NICKNAME}：确实，会有一种谜一样的帅气感。\\n派蒙：对吧对吧，你说我是不是也可以戴上面具，然后在沃陆之邦摔跤，打响全新的名号？\\n派蒙：台词我都想好了，就叫：「龙战士永远不会揭下她的面具！」\\n派蒙：白天是著名的冒险家，夜晚是强大的龙战士摔跤手。怎么样，很帅吧！\\n{NICKNAME}：帅是很帅啦，但有一个问题。\\n派蒙：嗯？什么问题啊？\\n{NICKNAME}：你这种体型，一眼就会被人认出来了吧…\", \"voicelineId\": 2190, \"voicelineType\": \"71089\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于织物…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_woven_heroine\", \"description\": \"派蒙：纳塔的传说和故事大多是编织在织物上面的，跟其他国家的书读起来体验很不一样呢。\\n{NICKNAME}：嗯，据说最早是起源于「烟谜主」，萨满会用织物来记录部族的历史和传说。后来织物被用于编写各种各样的故事，题材也越来越丰富了。\\n派蒙：嘿嘿，我也把我们一路的故事写下来吧，要是你有一天组建了名为「旅行者」的部族，就有现成的历史读物了！\\n派蒙：而且，平时能围在身上当披风，露营的时候还能躺在上面睡觉…\\n{NICKNAME}：真是「饱经风霜」的冒险传记呢。\", \"voicelineId\": 2191, \"voicelineType\": \"71090\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于沃陆之邦与花羽会…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_teteocanAndTlalocan_heroine\", \"description\": \"派蒙：听说沃陆之邦的人们都很健壮。\\n{NICKNAME}：那假如把派蒙放在那里，会不会变成肌肉派蒙呢？\\n派蒙：我才不要变成那个样子啦！\\n{NICKNAME}：那放在花羽会怎么样，他们很擅长飞行，说不定可以帮忙提升派蒙的飞行技巧呢。\\n派蒙：欸，飞行不就是咻——的一下就好了，还需要什么技巧吗？\\n{NICKNAME}：我只要求派蒙能带着我飞起来就好。\\n派蒙：差太多了吧！怎么想都不可能吧！\\n{NICKNAME}：那你先变成肌肉派蒙不就好了。\\n派蒙：喂！说到底你就是想看肌肉吧！\", \"voicelineId\": 2192, \"voicelineType\": \"71091\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于使龙开心的办法…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_wayOfDragonHappy_heroine\", \"description\": \"派蒙：欸嘿嘿，纳塔有好多好多可爱的龙，我要跟它们都搞好关系！\\n{NICKNAME}：哦？派蒙很自信嘛。\\n派蒙：那当然，我还特意为此准备了秘诀！\\n{NICKNAME}：秘诀？是什么秘诀啊？\\n派蒙：很简单！首先，你要先夸奖它，这样它就会感受到你的好意并放下防备。接着，再轻轻地摸摸它的头，你们就熟悉起来啦！\\n派蒙：最后，也是最重要的！好吃的！只要你跟龙分享好吃的，你们就是好朋友啦！怎么样，我厉害吧！\\n{NICKNAME}：——唔，总感觉…这些招数用来对付派蒙也很好用呢…\\n派蒙：喂！不许用那刚才的招数对付我！\\n{NICKNAME}：欸？我的意思明明是，派蒙就跟纳塔的龙宝宝一样可爱呢！\\n派蒙：哼，你就是想说点好听的来敷衍我，我才不上当呢！\\n{NICKNAME}：可我是在真心夸奖派蒙啊，没想到惹你不高兴了。作为道歉，我请你吃甜甜花酿鸡好不好？\\n派蒙：真的？好哎，是甜甜花酿鸡！我现在就要吃！\\n派蒙：不过话说回来，你怎么笑得这么开心啊？难道我错过了什么吗？\", \"voicelineId\": 2193, \"voicelineType\": \"71092\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于考古…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_archaeology_heroine\", \"description\": \"派蒙：听说，在回声之子考古是一个非常考验速度的工作，这是为什么啊？\\n{NICKNAME}：或许是因为这里的古物太多了吧…\\n派蒙：欸？那不是好事吗！\\n{NICKNAME}：古物越多竞争者就越多啊！就比如你前一天看到了一块很棒的石板，打算第二天过来搬走。结果等第二天发现，已经早就被人捷足先登了！\\n派蒙：——唔，我还是没懂…\\n{NICKNAME}：打个比方的话，就像你昨晚准备偷偷独吞剩下的零食，结果突然发现少了一块…\\n派蒙：啊！那确实好可怕！\\n派蒙：——等等，你怎么知道昨天我的零食少了一块的？\", \"voicelineId\": 2194, \"voicelineType\": \"71093\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于解决争端的办法…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_solveConflict_heroine\", \"description\": \"派蒙：据说在纳塔，有着可以不靠肌肉就解决争端的办法。\\n{NICKNAME}：在战争的国度，竟然还有这种方法吗？\\n派蒙：没错，我听说在回声之子，某一部分人就有用舞蹈对决来解决争端的传统！\\n{NICKNAME}：舞蹈对决？你是说，大家约好时间地点…\\n派蒙：嗯嗯。\\n{NICKNAME}：然后开始比拼花式动作…\\n派蒙：对对。\\n{NICKNAME}：直至一方力竭，最终倒地不起为止？\\n派蒙：没错！\\n派蒙：——欸，不对，那不还是靠肌肉吗！\", \"voicelineId\": 2195, \"voicelineType\": \"71094\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于发财的机会…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_opportunityOfRich_heroine\", \"description\": \"派蒙：嘿嘿，你听我说哦。我发现了一个不得了的发财机会！\\n{NICKNAME}：嗯，什么机会？\\n派蒙：你看圣火竞技场有这么多人经过。我们要是能在这里做点生意，一定可以发大财！\\n{NICKNAME}：哦？那派蒙准备卖点什么呢？\\n派蒙：蒙德的炼金药剂怎么样？\\n{NICKNAME}：貌似已经有人在卖类似的东西了…\\n派蒙：那璃月的各种矿石呢？这个一定很赚钱！\\n{NICKNAME}：回声之子不就是干这个的…\\n派蒙：哦对…啊！我想到了，须弥的挂毯，这个一定会很吃香！\\n{NICKNAME}：可惜，还有烟谜主呢。\\n派蒙：那，那我们把圣火竞技场四面用围栏拦起来！从今往后不管是参赛的和观战的，都要先付钱才能出入场地。\\n{NICKNAME}：你的围栏还没建成，人就会先被谁给抓起来…\\n派蒙：怎么这样——发财可真难啊。\", \"voicelineId\": 2196, \"voicelineType\": \"71095\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于龙的发型师…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_dragonHairStylist_heroine\", \"description\": \"派蒙：我们刚到纳塔遇见的三种龙伙伴都很特别呢。\\n派蒙：小嵴锋龙的脑袋弹弹的，小鳍游龙的背滑滑的，小匿叶龙的耳朵和脑袋毛茸茸。\\n{NICKNAME}：毛茸茸的小匿叶龙，抱着睡觉一定很香…\\n派蒙：不过，我记得很多动物的毛发会长得很长，也不知道会不会影响它们的行动？\\n派蒙：就比如说，如果匿叶龙耳朵和头上的绒毛太长，说不定会挡住眼睛，看不清前面的路，还有一点危险…\\n{NICKNAME}：既然派蒙想到了这一点，就由你来帮匿叶龙修理发型吧！\\n派蒙：欸，我吗？\\n{NICKNAME}：等你成为了纳塔有名的龙之发型师，还能赚大钱！\\n派蒙：说得对喔，没想到还能用这种方式发财！\\n派蒙：整个纳塔的匿叶龙都由我来理发，嘿嘿，摩拉…\\n派蒙：不对不对，摩拉是次要的，能和一整个纳塔的匿叶龙做朋友，肯定超开心！\\n{NICKNAME}：但是匿叶龙那么——那么大，用普通的小剪刀，不知道要修剪多久，也许每天只能给一只龙做发型。\\n{NICKNAME}：要想成为厉害的龙之发型师，派蒙就得好好锻炼锻炼了，至少要拿得起…无锋剑这么大的剪刀！\\n派蒙：无锋剑…那不是你的武器吗？\\n{NICKNAME}：我们可是好伙伴。走吧走吧，现在就去野外为你上第一堂课。\\n派蒙：不要以训练的名义把魔物推给我处理啊！\", \"voicelineId\": 2197, \"voicelineType\": \"71096\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「古名」…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_name_heroine\", \"description\": \"派蒙：据说被大灵认可并且选中的纳塔战士会获得「古名」呢，真羡慕…要是我也能有自己的「古名」就好了！\\n{NICKNAME}：欸？可是派蒙不是已经有很多称号了吗？\\n派蒙：咦？是哦！\\n派蒙：我可是你「最好的伙伴」和「非常可靠的向导」，同时还是「荣誉高级研究员助理」、「时髦飞行家」和「白银伴星」…这样想想，真是不得了的大英雄！\\n派蒙：如果纳塔人要记录我和{NICKNAME}在这里的冒险，我要把这些称号都用上！\\n{NICKNAME}：欸？这样不会太长了吗？\\n{NICKNAME}：想一想，如果纳塔人也把他们的称号都用上，织物就会变成这样…\\n{NICKNAME}：「这一天，『回声之子』纳茨卡延的『乌沙博蒂』的卡齐娜，和她热情的朋友，『流泉之众』梅兹特利的『沃摩延』的玛拉妮，在去往『烟谜主』米克特兰的路上，遇见了『悬木人』维茨特兰的『马力卜』的基尼奇，和他狡诈的伙伴，『库胡勒阿乔』…」\\n派蒙：停停停！说了这么多，都够从这里一直铺到圣火竞技场，再铺回来了…可是根本还没讲到关键信息啊！\\n派蒙：唔，如果只能选一个称号的话…果然还是只要「最好的伙伴」好了！\", \"voicelineId\": 2198, \"voicelineType\": \"71097\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于圣火竞技场…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_arena_heroine\", \"description\": \"派蒙：偷偷告诉你，我一直对圣火竞技场有个好奇的地方。\\n派蒙：比赛的形式不是积分制吗？大家组成小队，小队成员分别一对一进行固定轮次的比赛，再按照最后的积分来确定名次…\\n派蒙：为什么要采用这种规则呢？\\n{NICKNAME}：是为了把悬念留到最后一轮吧，也许观众的口味都喜欢看逆风翻盘。\\n派蒙：有道理，但会不会还有一种可能，是为了避免发生那种情况：只有两人参赛，双方又战力相当，怎么也分不出胜负…\\n{NICKNAME}：唔...似乎只能中途休战了。\\n派蒙：对呀！想象一下，一只突角龙和一只匿叶龙在场上比赛，突角龙擅长猛攻，匿叶龙擅长躲避，已经比赛了一天一夜…\\n派蒙：观战的大家早都看饿了，于是说，暂停暂停，下次再来。\\n派蒙：下次还是没能决出胜负，甚至匿叶龙违规使出偷袭，突角龙受伤了，又被发下了休止牌。\\n派蒙：这就变成了《突角龙大战匿叶龙》、《突角龙大战匿叶龙：续篇》、《突角龙大战匿叶龙：神龙归来》、《突角龙大战匿叶龙：纵横火山》…连续的剧场。\\n派蒙：欸？找人拍成系列映影也可以啊！还可以大赚一笔。\\n{NICKNAME}：虽然想法不错，但是…悬木人不会高兴你把他们的龙拉过来当反派吧！\\n派蒙：我只是一时间没找到什么更好的素材啦！\", \"voicelineId\": 2199, \"voicelineType\": \"71098\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于纳塔的冒险家…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_adventurerInNatlan_heroine\", \"description\": \"派蒙：纳塔人一般是不会离开纳塔的，对吧？\\n{NICKNAME}：嗯，有一些原因呢。\\n派蒙：唔，这样说来，他们要是想当冒险家的话，岂不是会很不方便？\\n派蒙：你想想，没办法去其它国家，就有一大堆委托没办法接…不能去未知的遗迹探险，也赚不到很多的摩拉，好可怜哦。\\n{NICKNAME}：听起来很有道理的样子，不过实际情况好像不是这样呢。\\n派蒙：欸？\\n{NICKNAME}：我听说在「流泉之众」有一群自称「旅行家」的人，因为他们对纳塔的地理啦，遗迹啦，都十分了解，所以其它国家的冒险家来到纳塔都会雇佣他们作为向导。\\n{NICKNAME}：这样不管这些冒险家最后有没有找到宝藏，都要付给他们报酬。时间长了，他们可能比冒险家赚得都要多呢。\\n派蒙：原来是这样…等等，如果他们真的对遗迹什么的这么了解的话，为什么不自己去找宝藏啦？\\n{NICKNAME}：假如说，从一开始就没有什么宝藏呢？\\n派蒙：哇，总感觉知道了什么不得了的事情…\", \"voicelineId\": 2208, \"voicelineType\": \"71099\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于涂鸦…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_scrawl_heroine\", \"description\": \"派蒙：纳塔的人很喜欢在各种地方涂涂画画呢，我记得他们是叫作燃素…\\n{NICKNAME}：是「燃素刻录」啦。不过只有刻在特殊的石碑上的才是真正的「燃素刻录」，这些就只是单纯的涂鸦而已。\\n{NICKNAME}：比如这幅就像是在说，「喂，这里是我们的地盘，『回声之子』天下第一！」\\n派蒙：感觉很有意思呢！既然这样，{NICKNAME}，我们也来留下自己的涂鸦吧。\\n{NICKNAME}：听起来不错，不过我们的话要画些什么呢？\\n派蒙：那当然是要留下提瓦特大陆最棒向导的画像啦！嘿嘿，不如就在那边的岩壁上…\\n{NICKNAME}：这样啊，那画师自然就是我了。让我想想，派蒙的话，首先应该是气鼓鼓的脸…\\n派蒙：嗯嗯…才不对吧！算了算了，还是等下次有机会的时候，让纳塔专业的画师来帮我们画好了。\", \"voicelineId\": 2209, \"voicelineType\": \"71100\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于纳塔的龙伙伴…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_dragonFriends_heroine\", \"description\": \"{NICKNAME}：纳塔的人们，真的把龙当作伙伴了呢…\\n派蒙：是呀，简直就像是{NICKNAME}和我一样，不管走到哪里都形影不离！\\n{NICKNAME}：既然派蒙是我的伙伴，龙是纳塔人的伙伴，要是让派蒙和龙比赛的话，谁会赢呢？\\n派蒙：为什么会突然出现这么奇怪的想法啦！\\n{NICKNAME}：仔细想想的话，派蒙既不会像嵴锋龙一样钻地，也没有绒翼龙飞得那么快…\\n派蒙：应、应该换一种角度考虑嘛！比方说，派蒙比嵴锋龙飞得更快，比绒翼龙…呃，比绒翼龙更擅长分辨野菇鸡肉串的美味程度！\\n{NICKNAME}：更重要的是，比所有龙陪在我身边的时间都要长呢。\\n派蒙：没错没错！哼哼，毕竟我可是提瓦特大陆最棒的向导——\\n{NICKNAME}：那我的好伙伴，我们也该开始今天的冒险了吧？\\n派蒙：哎呀，总觉得分辨美食的技巧都有点生疏了，先来一份野菇鸡肉串再出发吧！\", \"voicelineId\": 2210, \"voicelineType\": \"71101\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿乔…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_ajaw_heroine\", \"description\": \"派蒙：其实我想问你很久了…难道你就不好奇吗？阿乔的样子…\\n{NICKNAME}：有什么问题吗？\\n派蒙：问题很大吧！他跟别的龙都不一样！阿乔会讲话，话还不少！他不在地上走，总是绕在基尼奇周围飞，而且而且啊，哪有龙会戴那种奇怪的墨镜啊！\\n{NICKNAME}：嗯…\\n派蒙：突、突然盯着我看做什么…\\n{NICKNAME}：这么说来，派蒙话也不少，也会飞，而且在枫丹不也弄了副搞怪的眼镜吗？\\n派蒙：哎呀…不对啦！\\n派蒙：先不讨论这些。我其实最想问的是…阿乔像硬纸板一样…扁扁的…难道整个纳塔都没有人在意过这个问题吗？\\n{NICKNAME}：有道理，不过也许是因为大家已经习以为常了吧。\\n{NICKNAME}：这种关乎来历与隐私的事情，也许要问问阿乔本人才知道了。\\n派蒙：可是，你觉得阿乔会说实话吗？总觉得他会胡编乱造一些话来忽悠我们呢…\\n派蒙：又或者…故意引诱我们，让我们也变成扁扁的硬纸板…\\n{NICKNAME}：嗯…扁扁的派蒙…其实我也有点好奇…\\n派蒙：又、又盯着我看做什么！我才不要变成扁派蒙——呜！\", \"voicelineId\": 2211, \"voicelineType\": \"71102\", \"unlockConditions\": [{\"paramList\": [15004], \"unlockText\": \"完成「尤潘基的回火」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于纳塔人的彩绘…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_bodyPainting_heroine\", \"description\": \"派蒙：说起来，我发现纳塔人身上都有些不同纹样的…呃…油彩？涂鸦？虽然看不懂，但看上去好酷！\\n{NICKNAME}：我也发现了！听说是用涂料画上去的哦，这种涂料用燃素为原料制成，跟普通涂料不太一样呢。\\n派蒙：欸？居然是这样吗？\\n{NICKNAME}：但如果派蒙也感兴趣的话，我记得有专为游客提供的涂鸦体验服务哦，会用普通涂料来替代。\\n派蒙：真的吗真的吗？正所谓「来都来了」…不如…\\n{NICKNAME}：好啦好啦，可是不同的部族喜欢用的色彩和纹样风格都不一样，那派蒙选一个喜欢的吧。\\n派蒙：那我选…呃，选…哎呀！各有各的特色，根本选不出来嘛！\\n派蒙：哼。小孩子才做选择，派蒙我全都要！\\n{NICKNAME}：哇哦…想不到派蒙现在的审美风格是「极繁主义」…虽然不清楚别人会不会觉得奇怪，但我一定会支持你！\\n派蒙：我又没说要同时画在身上，我的意思是一天换一个，六天不重样啦！\\n{NICKNAME}：哦。好可惜…看来花臂派蒙只能靠想象了…\\n派蒙：不许可惜！还有快停止这种奇怪的想象！\", \"voicelineId\": 2212, \"voicelineType\": \"71103\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于与龙共生…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_liveWithDragon_heroine\", \"description\": \"派蒙：纳塔人和龙之间的关系真好啊，可以一起生活，一起战斗，一起飞行…\\n{NICKNAME}：有点像我和派蒙哦。可惜派蒙不会长大，也没法背着我在天上飞…明明吃了那么多的野菇鸡肉串呢。\\n派蒙：哼，但是龙又不能给你当向导，也不能和你聊天。\\n{NICKNAME}：其实很早之前，有过人和龙互相争夺的时代，变成如今这样和平共处的样子，一定很不容易吧。\\n派蒙：如果我是龙的话，只要给我足够的食物，我就完全不想打架了。\\n{NICKNAME}：可是如果派蒙一天要吃一百个鸡肉串，人类却没有那么多食物该怎么办？\\n派蒙：那我可以只吃五十个…\\n{NICKNAME}：或者人类也可以和派蒙约定好一起打猎，拿到更多的食材，这样两边都能吃饱了。\\n派蒙：哦！和平的关键是更多的肉！\", \"voicelineId\": 2213, \"voicelineType\": \"71104\", \"unlockConditions\": [{\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于火山…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_volcano_heroine\", \"description\": \"派蒙：纳塔到处都能看到那个大火山呢，你说底下那些咕噜噜往外冒的岩浆是从哪里来的呀？\\n{NICKNAME}：有这么一种说法哦，据说在纳塔的地底最深处，有一只古老的巨大的沉睡的火龙，它的体内是这个世界里最初的火。火在它的体内不断燃烧，它的后背产生了许许多多冒火的孔，会周期性地往外喷出火焰，喷到地上就变成了火山里的岩浆。\\n派蒙：真的假的，那如果火龙醒了，纳塔岂不是会发生可怕的事？\\n{NICKNAME}：是啊，所以火神要聚集各部族的力量，定期安抚火龙，让它继续沉睡在梦中。\\n派蒙：不对，火神要对抗的明明是深渊的侵蚀呀！\\n{NICKNAME}：这其实是我在地摊上买到的一卷织物里记录的故事啦。\\n派蒙：我就说呢…\", \"voicelineId\": 2214, \"voicelineType\": \"71105\", \"unlockConditions\": [{\"paramList\": [3, 1166], \"unlockText\": \"解锁「纳塔 坚岩隘谷」七天神像-火\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夜的诅咒…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_curseOfNight_heroine\", \"description\": \"派蒙：曾经有一个伟大的骑士被诅咒了，白天只能以邋遢的酒鬼大叔形象出现。\\n派蒙：只有夜深人静的时候，他会展示出自己专业、成熟、勇敢的骑士本来面目…\\n{NICKNAME}：有没有什么办法解除诅咒呢？\\n派蒙：只有发自真心的尊敬可以解除酒鬼大叔身上的诅咒。\\n{NICKNAME}：那我就去当这个解除诅咒的人吧。\\n派蒙：噔噔！诅咒解除了，现在法尔伽大团长可以选择成为酒鬼大叔或者可靠的骑士。\\n派蒙：然后法尔伽说，我本来就是邋遢的酒鬼大叔，真是对不起哦。于是白天黑夜全都是酒鬼大叔了。\\n{NICKNAME}：太糟糕了！\\n派蒙：纳塔流传的故事则是，有一个被诅咒的女孩子，白天是为老不尊、目中无人的老婆婆，晚上则会变成单纯的少女。\\n派蒙：只有…呃，只有和她聊喜欢的东西才能解除诅咒。\\n{NICKNAME}：我都能猜到结局了。珐露珊前辈的话，一定会「呵呵呵，年纪大怎么了，新生娃子你们有什么意见吗？」\\n派蒙：没错，而茜特菈莉就会——\\n{NICKNAME}：茜特菈莉应该就会又委屈又着急地说：「我本来就是普通女孩子啊！？」\\n派蒙：好像也没有诅咒？\", \"voicelineId\": 2215, \"voicelineType\": \"71106\", \"unlockConditions\": [{\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于游隙灵道…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_spiritway_heroine\", \"description\": \"派蒙：五百摩拉…一千摩拉…一千二百摩拉…\\n{NICKNAME}：在做什么？\\n派蒙：呜哇！吓我一跳！\\n派蒙：嘿嘿，你知道吗，我最近攒了不少钱，过几天我也要去「流泉之众」买个冲浪板！\\n派蒙：然后我就可以像玛拉妮一样，唰地一下滑过「游隙灵道」啦。\\n{NICKNAME}：小派蒙…冲浪…\\n派蒙：等等，为什么你的眼神中带着几分怀疑？\\n{NICKNAME}：我会想你的。和你一起旅行的日子，我一直都很开心…\\n派蒙：等下！不要说得像是我回不来啦！\\n派蒙：我已经提前做好准备了！就算摔下来也没有关系，毕竟我会飞嘛。\\n派蒙：不过这么一想，游隙灵道那么高、那么陡，玛拉妮是怎么玩转的呢？\\n{NICKNAME}：对玛拉妮来说，在「游隙灵道」上滑行应该不算什么难事吧。你看她表演高难度动作时候脸上的笑容就知道了。\\n派蒙：那岂不是就是在说我没用吗？！\", \"voicelineId\": 2216, \"voicelineType\": \"71107\", \"unlockConditions\": [{\"paramList\": [3, 1254], \"unlockText\": \"解锁「纳塔 泉流之众」传送锚点\", \"conditionType\": \"FETTER_COND_UNLOCK_TRANS_POINT\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于火神…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_mavuika_heroine\", \"description\": \"派蒙：没想到火神居然是从「归火圣夜巡礼」中选出来的！\\n派蒙：如果我打赢比赛的话，是不是也有机会成为新的火神呢？\\n{NICKNAME}：哦？派蒙很有自信嘛。\\n派蒙：哼哼，不要小看我哦，其实我已经领教过许多神明的「招式」了。\\n{NICKNAME}：什么？\\n派蒙：比如传说中的真·风神杂烩菜、文火慢炖腌笃鲜、哈瓦玛玛兹、「普茹斯蒂司」…\\n{NICKNAME}：原来是烹饪招式啊！\\n派蒙：没错，我提议等纳塔迎来和平后，在归火圣夜巡礼中也加入烹饪对决！\\n派蒙：我已经迫不及待想领教火神的「火力」啦。\", \"voicelineId\": 2217, \"voicelineType\": \"71108\", \"unlockConditions\": [{\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于休息…\", \"voicefile\": \"VO_friendship/VO_heroine/vo_fetter_nt_rest_heroine\", \"description\": \"派蒙：说起来，有一段时间没见过希诺宁了，上次见到她的时候，她还趴在一棵树上睡觉。\\n{NICKNAME}：上上次，应该是躺在屋顶，戴着墨镜晒太阳。\\n派蒙：上上上次，好像是坐在自己做的摇摇椅上喝果汁…\\n派蒙：呜哇，为什么我们对希诺宁的印象，都是她在休息啊！\\n{NICKNAME}：平时工作很勤奋的人，一旦停下来休息，就会给人留下很深的印象。\\n派蒙：真的？这么一想，我工作的时候也很努力啊。\\n派蒙：上次追那只小嵴锋龙的时候，我为了给你指路，飞得很高很高。\\n派蒙：还有那次帮「悬木人」的讯使找邮包，帮人去采苦种，哇…说起来都好累好累。\\n派蒙：哼，以后我们去做委托的时候，我要多多偷懒，而且不让你发现！\\n{NICKNAME}：我尽量不发现，派蒙就好好偷懒吧。\\n派蒙：你那么好呀？那你偷懒的时候，我也尽量不发现…\\n派蒙：哎呀，这么一想，我们干脆一起去偷懒吧。\\n派蒙：好，决定了！现在就是我们互相不发现的偷懒时间，快快快，一起躺下晒太阳吧。\", \"voicelineId\": 2218, \"voicelineType\": \"71109\", \"unlockConditions\": [{\"paramList\": [15016], \"unlockText\": \"完成「祈祝福愿，倾告嵴锋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_01\", \"description\": \"…喝！\", \"voicelineId\": 2061, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_02\", \"description\": \"…哈！\", \"voicelineId\": 2062, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_03\", \"description\": \"风刃！\", \"voicelineId\": 2063, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_rock_01\", \"description\": \"喝！\", \"voicelineId\": 2064, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_rock_02\", \"description\": \"落！\", \"voicelineId\": 2065, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_rock_03\", \"description\": \"荒星！\", \"voicelineId\": 2066, \"voicelineType\": \"100006\"}, {\"title\": \"元素战技·其七\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_thunder_01\", \"description\": \"哈！\", \"voicelineId\": 2067, \"voicelineType\": \"100007\"}, {\"title\": \"元素战技·其八\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_thunder_02\", \"description\": \"接招！\", \"voicelineId\": 2068, \"voicelineType\": \"100008\"}, {\"title\": \"元素战技·其九\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_thunder_03\", \"description\": \"紫影！\", \"voicelineId\": 2069, \"voicelineType\": \"100009\"}, {\"title\": \"元素战技·其十\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_dendro_01\", \"description\": \"哈！\", \"voicelineId\": 2125, \"voicelineType\": \"100010\"}, {\"title\": \"元素战技·其十一\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_dendro_02\", \"description\": \"散！\", \"voicelineId\": 2126, \"voicelineType\": \"100011\"}, {\"title\": \"元素战技·其十二\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_dendro_03\", \"description\": \"蔓延！\", \"voicelineId\": 2127, \"voicelineType\": \"100012\"}, {\"title\": \"元素战技·其十三\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_hydro_01\", \"description\": \"哈！\", \"voicelineId\": 2156, \"voicelineType\": \"100013\"}, {\"title\": \"元素战技·其十四\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_hydro_02\", \"description\": \"逐！\", \"voicelineId\": 2157, \"voicelineType\": \"100014\"}, {\"title\": \"元素战技·其十五\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_hydro_03\", \"description\": \"漩击！\", \"voicelineId\": 2158, \"voicelineType\": \"100015\"}, {\"title\": \"元素战技·其十六\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_pyro_01\", \"description\": \"哈！\", \"voicelineId\": 2219, \"voicelineType\": \"100016\"}, {\"title\": \"元素战技·其十七\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_pyro_02\", \"description\": \"纵燃！\", \"voicelineId\": 2220, \"voicelineType\": \"100017\"}, {\"title\": \"元素战技·其十八\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_pyro_03\", \"description\": \"闪灼！\", \"voicelineId\": 2221, \"voicelineType\": \"100018\"}, {\"title\": \"元素战技·其十九\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_pyro_04\", \"description\": \"哈——！\", \"voicelineId\": 2222, \"voicelineType\": \"100019\"}, {\"title\": \"元素战技·其二十\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_pyro_05\", \"description\": \"束火！\", \"voicelineId\": 2223, \"voicelineType\": \"100020\"}, {\"title\": \"元素战技·其二十一\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill1_pyro_06\", \"description\": \"铸光！\", \"voicelineId\": 2224, \"voicelineType\": \"100021\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_01\", \"description\": \"嘿——\", \"voicelineId\": 2070, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_02\", \"description\": \"消失吧。\", \"voicelineId\": 2071, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_03\", \"description\": \"随风而去吧。\", \"voicelineId\": 2072, \"voicelineType\": \"200003\"}, {\"title\": \"元素爆发·其四\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_rock_01\", \"description\": \"哈——！\", \"voicelineId\": 2073, \"voicelineType\": \"200004\"}, {\"title\": \"元素爆发·其五\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_rock_02\", \"description\": \"震颤吧！\", \"voicelineId\": 2074, \"voicelineType\": \"200005\"}, {\"title\": \"元素爆发·其六\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_rock_03\", \"description\": \"化为尘埃吧。\", \"voicelineId\": 2075, \"voicelineType\": \"200006\"}, {\"title\": \"元素爆发·其七\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_thunder_01\", \"description\": \"喝——！\", \"voicelineId\": 2076, \"voicelineType\": \"200007\"}, {\"title\": \"元素爆发·其八\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_thunder_02\", \"description\": \"轰鸣吧！\", \"voicelineId\": 2077, \"voicelineType\": \"200008\"}, {\"title\": \"元素爆发·其九\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_thunder_03\", \"description\": \"天雷鼓音！\", \"voicelineId\": 2078, \"voicelineType\": \"200009\"}, {\"title\": \"元素爆发·其十\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_dendro_01\", \"description\": \"哈！\", \"voicelineId\": 2128, \"voicelineType\": \"200010\"}, {\"title\": \"元素爆发·其十一\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_dendro_02\", \"description\": \"萌发吧！\", \"voicelineId\": 2129, \"voicelineType\": \"200011\"}, {\"title\": \"元素爆发·其十二\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_dendro_03\", \"description\": \"新蕾破土！\", \"voicelineId\": 2130, \"voicelineType\": \"200012\"}, {\"title\": \"元素爆发·其十三\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_hydro_01\", \"description\": \"哈！\", \"voicelineId\": 2159, \"voicelineType\": \"200013\"}, {\"title\": \"元素爆发·其十四\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_hydro_02\", \"description\": \"涤荡吧！\", \"voicelineId\": 2160, \"voicelineType\": \"200014\"}, {\"title\": \"元素爆发·其十五\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_hydro_03\", \"description\": \"奔流飞去！\", \"voicelineId\": 2161, \"voicelineType\": \"200015\"}, {\"title\": \"元素爆发·其十六\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_pyro_01\", \"description\": \"哈！\", \"voicelineId\": 2225, \"voicelineType\": \"200016\"}, {\"title\": \"元素爆发·其十七\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_pyro_02\", \"description\": \"启明吧！\", \"voicelineId\": 2226, \"voicelineType\": \"200017\"}, {\"title\": \"元素爆发·其十八\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_battle_skill3_pyro_03\", \"description\": \"逐示曜焰！\", \"voicelineId\": 2227, \"voicelineType\": \"200018\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_chest_open_01\", \"description\": \"这个世界，也在回应我吗？\", \"voicelineId\": 2079, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_chest_open_02\", \"description\": \"旅途中的收获。\", \"voicelineId\": 2080, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_chest_open_03\", \"description\": \"我会好好保存。\", \"voicelineId\": 2081, \"voicelineType\": \"300003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_life_less30_teammate_01\", \"description\": \"等等…让我来吧！\", \"voicelineId\": 2082, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_life_less30_teammate_02\", \"description\": \"当心！\", \"voicelineId\": 2083, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_life_die_01\", \"description\": \"这…不是终点…\", \"voicelineId\": 2084, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_heroine/vo_heroine_life_die_02\", \"description\": \"世界…拒绝了我？\", \"voicelineId\": 2085, \"voicelineType\": \"500002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_heroine_teamJoin_01\", \"description\": \"这次又会遇见什么？\", \"voicelineId\": 2086, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_heroine_teamJoin_02\", \"description\": \"世界，充满未解之谜…\", \"voicelineId\": 2087, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_heroine_teamJoin_03\", \"description\": \"要做的事，还有很多。\", \"voicelineId\": 2088, \"voicelineType\": \"600003\", \"voicefile_male\": \"VO_teamJoin/vo_heroine_teamJoin_03\", \"hasGenderedVoicefile\": true}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000014, 'Barbara', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_draw_appear\", \"description\": \"芭芭拉，闪耀登场~治疗就交给我吧，不会让你失望的！\", \"voicelineId\": 6100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·犯困\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_explore_idle_01\", \"description\": \"再这样站下去，会…想睡觉的…\", \"voicelineId\": 6101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·激励\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_explore_idle_02\", \"description\": \"大家应该都在努力着，那我们也不能偷懒，对吧？\", \"voicelineId\": 6102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·提神秘诀\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_explore_idle_03\", \"description\": \"欸，是没精神了吗？尝一尝我做的辣味饮料吧，很提神的喔！\", \"voicelineId\": 6103, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_weather_heavyRain_01\", \"description\": \"这样淋着不要紧吗？会感冒的吧？\", \"voicelineId\": 6104, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_weather_thunder_01\", \"description\": \"呜哇！\", \"voicelineId\": 6105, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_weather_snowy_01\", \"description\": \"欸！是雪花欸！冰冰凉凉的~！\", \"voicelineId\": 6106, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_weather_sunny_01\", \"description\": \"这样的好天气，嗯~适合比较明快的曲风呢！\", \"voicelineId\": 6107, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_weather_gale_01\", \"description\": \"放心，我不会被吹走的！\", \"voicelineId\": 6108, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_dialog_greetingMorning\", \"description\": \"早安~今天也要加油呀。\", \"voicelineId\": 6109, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_dialog_greetingNoon\", \"description\": \"欸，想听我唱歌…？对不起，还…还没有到演出时间呢。\", \"voicelineId\": 6110, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_dialog_greetingNight\", \"description\": \"想吃猎鹿人餐馆的香辣鲈鱼…可是最近的肚子，呜…\", \"voicelineId\": 6111, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_dialog_greetingNight2\", \"description\": \"辛苦了！请好好休息吧。\", \"voicelineId\": 6112, \"voicelineType\": \"1004\"}, {\"title\": \"关于芭芭拉自己…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_dialog_idle\", \"description\": \"「指引我前进的风啊。在我困顿时给我继续前行的力量，在我迷惑时给我辨明善恶的智慧，在我遭受不义时给我抗争的勇气…」…哎呀，抱歉，刚才在专心祈祷。有什么事吗？\", \"voicelineId\": 6113, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·愿望\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_dialog_close1\", \"description\": \"我的愿望，是给身边的大家带来笑容！只要能帮上你的忙，我就很开心了。\", \"voicelineId\": 6114, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·梦想\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_dialog_close2\", \"description\": \"谢谢你陪我走到现在，离我的梦想已经越来越近了呢。未来的日子，也请多多关照啦~！\", \"voicelineId\": 6115, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_dialog_pendant\", \"description\": \"每个人都会有自己的愿望。汇聚大家的愿望，让大家感到幸福，这一定，就是神给予我的使命吧。\", \"voicelineId\": 6116, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_dialog_share\", \"description\": \"蒙德城外青青的原野，真的百看不厌。但我听说，世界上还有蓝色的树林呢！就在海对岸的稻妻城那边。嗯！我还得多攒一点…欸？问我在攒什么？嘿嘿，是秘密哦~！\", \"voicelineId\": 6117, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_pref_gift\", \"description\": \"向日葵一直对着阳光的样子，很耀眼呢。其实，妈妈送过我一条向日葵风格的礼裙…但我什么时候才能穿上它去演出呢？\", \"voicelineId\": 6118, \"voicelineType\": \"3003\"}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_teammate_qin_01\", \"description\": \"代理团长大人…骑士团的领袖，大家都很喜欢她哦。欸？问我吗？我…我当然也非常尊敬她！\", \"voicelineId\": 6119, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_teammate_lisa_01\", \"description\": \"我一直承蒙丽莎姐姐照顾呢。要是她也成为偶像的话，我绝对会全力应援，喊到嗓子哑掉…啊，这样会吓到别人的吧…\", \"voicelineId\": 6120, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_teammate_ambor_01\", \"description\": \"以前就经常看到安柏风风火火地往城外跑，侦察骑士还真是辛苦呀。\", \"voicelineId\": 6121, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_teammate_diluc_01\", \"description\": \"迪卢克老爷吗？上次在「天使的馈赠」演出，他一直皱着眉头…是不是我唱的歌他不喜欢呢？\", \"voicelineId\": 6122, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温迪…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_teammate_venti_01\", \"description\": \"温迪的声音很好听！不过，他唱的歌跟我擅长的风格差异很大。我试着偷偷学过…那旋律还真是复杂呀。\", \"voicelineId\": 6123, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于班尼特…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_teammate_bennett_01\", \"description\": \"班尼特经常带着一身伤痕来教堂…他却一直毫不在意、大大咧咧地笑着。唔…还是应该更爱惜自己才好啊。\", \"voicelineId\": 6124, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_teammate_varka_01\", \"description\": \"父亲跟着法尔伽大团长一起出远门了，也不知道路途中会不会遇到什么…啊，没关系，大团长可是「北风骑士」，一定没问题的！我…也会为他们祈祷的。\", \"voicelineId\": 6125, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于罗莎莉亚…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_teammate_rosaria_01\", \"description\": \"罗莎莉亚修女虽然难以接近，也从不参加祈祷，但我觉得…唔，她一定是相信着风神的！不过，不过我并没有勇气和她交流就是了…\", \"voicelineId\": 6126, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于诺艾尔…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_teammate_noel_01\", \"description\": \"诺艾尔实在是太可爱了！人又温柔，还很有耐心，跟她在一起的时候，完全不会有什么压力…哦，对了，她做的茶点也很特别。又香，又甜，而且很健康，嘿嘿。\", \"voicelineId\": 6127, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解芭芭拉·其一\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_friendship_01\", \"description\": \"骑士们挥剑作战的样子好帅啊！你是不是也有这种感觉？我自己也试过用剑…欸嘿嘿，可惜我在剑术上，完全没有天赋呢。\", \"voicelineId\": 6128, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解芭芭拉·其二\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_friendship_02\", \"description\": \"想要治愈大家。就是这么简单的心情，让我成为了牧师。要是能帮上大家就好了。\", \"voicelineId\": 6129, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解芭芭拉·其三\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_friendship_03\", \"description\": \"偶像，唔...是从艾莉丝那边了解到的…「优秀的偶像能够治愈人们的心灵。」嗯，嗯，总之就是这样啦。\", \"voicelineId\": 6130, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解芭芭拉·其四\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_friendship_04\", \"description\": \"我每天都在努力，这份努力…如果能配得上蒙德城大家的信任…\", \"voicelineId\": 6131, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解芭芭拉·其五\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_friendship_05\", \"description\": \"每次演出的时候我都会想…我真的能够治愈蒙德城里的每个人么？但是看着你，我总觉得只要一步步向前，总有一天…欸？至少已经把你治愈了…？这时候不是应该说！我已经治愈很多人了吗？！不过这样也不错…\", \"voicelineId\": 6132, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"芭芭拉的爱好…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_pref_hobby\", \"description\": \"是大家脸上的笑容，一直在支持我。\", \"voicelineId\": 6133, \"voicelineType\": \"6001\"}, {\"title\": \"芭芭拉的烦恼…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_dialog_annoyed\", \"description\": \"同伴们一直在受伤…我，没有替大家分担痛苦的力量。但我可以尽最大的努力治疗！一定，要让大家恢复健康。\", \"voicelineId\": 6134, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_pref_foodLike\", \"description\": \"你喜欢麻辣小鱼干吗？我这还有两条…喏，给你一条！\", \"voicelineId\": 6135, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_pref_foodDislike\", \"description\": \"我不太喜欢苦的东西，特别是…苦瓜。\", \"voicelineId\": 6136, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_spice_pref_01\", \"description\": \"很少吃到那么合我口味的菜肴。今天是幸运日呢！\", \"voicelineId\": 6167, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_spice_normal_01\", \"description\": \"谢谢你特意做的这些，这次，是被你治愈了。\", \"voicelineId\": 6168, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_spice_dislike_01\", \"description\": \"不，不好…\", \"voicelineId\": 6169, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_pref_birthday\", \"description\": \"请收下！这个是给你的生日礼物，专属签名绘哟~欸嘿，等下一首新歌，我会第一时间唱给你听的！生日快乐呀！\", \"voicelineId\": 6137, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_starUp_01\", \"description\": \"芭芭拉的舞步…治愈力UP！\", \"voicelineId\": 6138, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_starUp_02\", \"description\": \"谢谢你的支持~啊，不好，好像有点太激动了…心脏怦怦跳个不停。\", \"voicelineId\": 6139, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_starUp_03\", \"description\": \"请告诉我继续变强的秘诀~欸？放心交给你就行？…这怎么行，我也要一起努力！\", \"voicelineId\": 6140, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_barbara/vo_barbara_starUp_04\", \"description\": \"和你一起旅行，我才意识到舞台是没有边界的。谢谢你！嘿嘿…好！一起喊出那句咒语吧！三、二、一，——芭芭拉冲呀！\", \"voicelineId\": 6141, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_battle_skill1_01\", \"description\": \"我会保护大家！\", \"voicelineId\": 6142, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_battle_skill1_02\", \"description\": \"打起精神来哟！\", \"voicelineId\": 6143, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_battle_skill1_03\", \"description\": \"演唱，开始！\", \"voicelineId\": 6144, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_battle_skill3_01\", \"description\": \"♪哼哼哼~哼哼~\", \"voicelineId\": 6145, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_battle_skill3_02\", \"description\": \"准备好了吗~\", \"voicelineId\": 6146, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_battle_skill3_03\", \"description\": \"大家加油喔！\", \"voicelineId\": 6147, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_explore_sprint_start_01\", \"description\": \"芭芭拉，冲呀！\", \"voicelineId\": 6148, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺结束·其一\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_explore_sprint_end_01\", \"description\": \"呼…呼…没问题！\", \"voicelineId\": 6149, \"voicelineType\": \"710001\"}, {\"title\": \"冲刺结束·其二\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_explore_sprint_end_02\", \"description\": \"能跟得上！\", \"voicelineId\": 6150, \"voicelineType\": \"710002\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_chest_open_01\", \"description\": \"想用歌声，带给人们同样的惊喜。\", \"voicelineId\": 6151, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_chest_open_02\", \"description\": \"光彩熠熠！\", \"voicelineId\": 6152, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_chest_open_03\", \"description\": \"嗯哼♪真是幸运的一天~\", \"voicelineId\": 6153, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_life_less30_01\", \"description\": \"我没关系的！\", \"voicelineId\": 6154, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_life_less30_02\", \"description\": \"为了大家，我还不能…\", \"voicelineId\": 6155, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_life_less30_03\", \"description\": \"我再坚持一下…\", \"voicelineId\": 6156, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_life_less30_teammate_01\", \"description\": \"我…不想看你受伤。\", \"voicelineId\": 6157, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_life_less30_teammate_02\", \"description\": \"让我为你治疗，拜托了！\", \"voicelineId\": 6158, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_life_die_01\", \"description\": \"有点，没力气了…\", \"voicelineId\": 6159, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_life_die_02\", \"description\": \"大家的声音，听不到呢…\", \"voicelineId\": 6160, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_life_die_03\", \"description\": \"姐姐…\", \"voicelineId\": 6161, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_battle_hit_L_02\", \"description\": \"疼…\", \"voicelineId\": 6162, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_barbara/vo_barbara_battle_hit_H_02\", \"description\": \"讨厌…\", \"voicelineId\": 6163, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_barbara_teamJoin_01\", \"description\": \"放心交给我就好。\", \"voicelineId\": 6164, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_barbara_teamJoin_02\", \"description\": \"我会加油的！\", \"voicelineId\": 6165, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_barbara_teamJoin_03\", \"description\": \"一起努力吧！\", \"voicelineId\": 6166, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000015, 'Kaeya', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_draw_appear\", \"description\": \"西风骑士团，凯亚。请让我与你同行吧。比起团里的差事，还是做你的护卫要有趣得多。\", \"voicelineId\": 7100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·无所事事\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_explore_idle_01\", \"description\": \"没想到你也知道忙里偷闲。\", \"voicelineId\": 7101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·骑士团\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_explore_idle_02\", \"description\": \"骑士团的战友们已经忙得不可开交了吧，哼哼。\", \"voicelineId\": 7102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·懒散\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_explore_idle_03\", \"description\": \"逗留够久了吧，再不活动活动筋骨，要长出蘑菇来了。\", \"voicelineId\": 7103, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_weather_heavyRain_01\", \"description\": \"这雨天里，冰冻的力量会更强吧，有趣。\", \"voicelineId\": 7104, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候·逸闻\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_weather_snowy_01\", \"description\": \"呼…趁着这雪天，跟你讲一个鬼故事吧。\", \"voicelineId\": 7105, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候·寒冷\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_weather_snowy_02\", \"description\": \"怎么，你怕冷？\", \"voicelineId\": 7106, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_weather_breezy_01\", \"description\": \"真是和平啊，可又能持续多久呢？\", \"voicelineId\": 7107, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_dialog_greetingMorning\", \"description\": \"享受这一天吧。\", \"voicelineId\": 7108, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_dialog_greetingNoon\", \"description\": \"哟，要不要一起去酒馆坐坐。\", \"voicelineId\": 7109, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_dialog_greetingNight\", \"description\": \"你该不会怕黑吧？哦？那我…可找到新素材了。\", \"voicelineId\": 7110, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_dialog_greetingNight2\", \"description\": \"这就要走了吗。那就下回见了，别让我等太久啊。\", \"voicelineId\": 7111, \"voicelineType\": \"1004\"}, {\"title\": \"关于凯亚自己…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_dialog_idle\", \"description\": \"你最近有没有被深渊教团找麻烦？有什么心烦的可以跟我聊聊。\", \"voicelineId\": 7112, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·雇佣关系\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_dialog_close1\", \"description\": \"需要我的时候就派我上场吧，别谈那些雇佣关系了。\", \"voicelineId\": 7113, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·实力\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_dialog_close2\", \"description\": \"哦？既然这么在意我们之间的雇佣关系，就多使唤我一点吧，老大？哼哼，可别被我的真正实力吓到哦。\", \"voicelineId\": 7114, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_dialog_pendant\", \"description\": \"不明白「神之眼」的原理？嗯…我想想，给你打个比方吧。引导视线的器官是眼睛，而引导元素力的器官是「神之眼」。这样就很简单了吧。\", \"voicelineId\": 7115, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_dialog_share\", \"description\": \"你喜欢酒吗？蒲公英酒的口感就很特别。什么？还没到喝酒的年纪？呵呵，那试一试蒙德的苹果酿吧，我知道一家还算不错的店。\", \"voicelineId\": 7116, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_pref_gift\", \"description\": \"你见过龙脊雪山的猫头鹰么？和它对视的时候，它好像看穿了你，而你却完全参不透它…很迷人的家伙，不是吗？\", \"voicelineId\": 7117, \"voicelineType\": \"3003\"}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_qin_01\", \"description\": \"哦？代理团长大人，你可要多多支持她。\", \"voicelineId\": 7118, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_lisa_01\", \"description\": \"丽莎啊…你千万记得要准时还书哦？上次因为这事儿惹她生了气，直到现在我左手的尺骨还是麻麻的。\", \"voicelineId\": 7119, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_ambor_01\", \"description\": \"侦察骑士是个机灵又正义的好骑士。可千万别在她面前做坏事喔。\", \"voicelineId\": 7120, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_diluc_01\", \"description\": \"迪卢克？小时候的他挺可爱的。可如今却活在自己的世界里…总之是个无趣的家伙。\", \"voicelineId\": 7121, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_klee_01\", \"description\": \"可莉，看来还是没有掌握躲避代理团长检查的技巧啊，明明我已经点拨过她…哈哈，我说着玩玩的，你可别去揭发我哦。\", \"voicelineId\": 7122, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_albedo_01\", \"description\": \"阿贝多啊，沉稳优雅的小帅哥，而且才华横溢，是很讨人喜欢的类型。怎么，你也心动了？\", \"voicelineId\": 7123, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪奥娜…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_diona_01\", \"description\": \"你也尝过了迪奥娜调的酒？还没到喝酒的年纪呐。哈哈，哎呀，可惜，真是可惜，这种快乐无法跟你共享。呵呵，只能期待你早点长大喽。\", \"voicelineId\": 7124, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_varka_01\", \"description\": \"说来可惜，现在的西风骑士团里，根本没人继承大团长的行事作风。唉…我个人倒还挺欣赏那种的。\", \"voicelineId\": 7125, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲谢尔…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_fischl_01\", \"description\": \"什么？你说菲谢尔遮起一只眼睛的神秘样子，的确很符合「断罪皇女」的形象？哈哈哈，按照这个规律，我至少也得是个末代皇族后裔，对吧？\", \"voicelineId\": 7126, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于诺艾尔…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_noel_01\", \"description\": \"我受代理团长大人所托，暗中照顾这位后辈。不过她很懂事，不需要我操太多心。真是令人欣慰。\", \"voicelineId\": 7127, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于罗莎莉亚…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_rosaria_01\", \"description\": \"啊哈哈，你想知道罗莎莉亚修女的秘密吗？这个不能说。不过我对她印象还不错，比某人好多了。她能够诚实地面对自己。烂事就是烂事，提不起干劲就是提不起干劲。\", \"voicelineId\": 7128, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于砂糖…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_sucrose_01\", \"description\": \"别看砂糖文静又内向，据说，她在实验室里，收藏了很多特别的东西哦，很刺激，又很…露骨的那种。嗯？你问我？…我像是会偷看女孩子房间的人吗？\", \"voicelineId\": 7129, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于柯莱…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_collei_01\", \"description\": \"嗯，柯莱？真是个怀念的名字，你可找对人了！我来告诉你过去发生的事情吧，干脆从头说起——保证原汁原味！\", \"voicelineId\": 7173, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于米卡…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_teammate_mika_01\", \"description\": \"刚开始接触那会儿，我看米卡容易紧张，就跟他开了一点无关痛痒的小玩笑。哪知他更紧张了，连笑都笑得很僵硬…最后还特意写信道歉。欸，这种单纯老实的品质，难道是施密特家族的遗传？\", \"voicelineId\": 7174, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解凯亚·其一\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_friendship_01\", \"description\": \"骑兵队长的头衔可没什么了不起的。说起来，蒙德城的骑兵都被大团长带走了。呵呵。\", \"voicelineId\": 7130, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解凯亚·其二\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_friendship_02\", \"description\": \"其实西风骑士团一共有十位队长。但不是所有人都有队长级的实力。\", \"voicelineId\": 7131, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解凯亚·其三\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_friendship_03\", \"description\": \"我的眼睛？我的眼睛没事。想把身体的某些部分遮起来是很平常的事儿吧？衣服和裤子也是一个道理。\", \"voicelineId\": 7132, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解凯亚·其四\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_friendship_04\", \"description\": \"坎瑞亚？哦，你知道的真多。坎瑞亚的荣耀早已不在，剩下的如今都已沦为罪人，又何必再提起他们。\", \"voicelineId\": 7133, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解凯亚·其五\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_friendship_05\", \"description\": \"原来我们已经相遇这么久了。跟你一起旅行，大概是我这辈子遇上的最有趣的事儿了，今后可别让我失望哦。\", \"voicelineId\": 7134, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"凯亚的爱好…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_pref_hobby\", \"description\": \"品酒也是一种艺术，蒙德的酒是风神的恩赐，懂得好好品味才不会浪费了这份幸运。\", \"voicelineId\": 7135, \"voicelineType\": \"6001\"}, {\"title\": \"凯亚的烦恼…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_dialog_annoyed\", \"description\": \"孤独？怎么会，现在不就有人在我身边唠叨么。\", \"voicelineId\": 7136, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_pref_foodLike\", \"description\": \"蒙德特酿的起泡白葡萄酒，兑上三份蒲公英酒，苦味会被完美中和，这种酒名叫「午后之死」。美味。\", \"voicelineId\": 7137, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_pref_foodDislike\", \"description\": \"居然有人直接把葡萄汁拿来喝，明明只需少许时日就能变成佳酿的…啧，真是不懂浪漫。\", \"voicelineId\": 7138, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_spice_pref_01\", \"description\": \"哦！这味道好棒，看不出来，你真有两下子啊。\", \"voicelineId\": 7170, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_spice_normal_01\", \"description\": \"配上美酒，会变得更美味吧。\", \"voicelineId\": 7171, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_spice_dislike_01\", \"description\": \"放心，我只是吃得慢了一点，我会好好吃完的。\", \"voicelineId\": 7172, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_pref_birthday\", \"description\": \"值得庆贺的日子，祝你今天能得到真正的快乐。\", \"voicelineId\": 7139, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_starUp_01\", \"description\": \"嚯，你也有两下子嘛。\", \"voicelineId\": 7140, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_starUp_02\", \"description\": \"你好像一直都很照顾我嘛。谢啦。\", \"voicelineId\": 7141, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_starUp_03\", \"description\": \"力量又增强了啊…我说，你那是什么眼神，怎么感觉比我还兴奋。\", \"voicelineId\": 7142, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_kaeya/vo_kaeya_starUp_04\", \"description\": \"本来只是同行，没想到你居然为我做到这一步…看来我也必须好好回应你才行呢。继续我们的旅程吧，挚友，是时候认真起来了。\", \"voicelineId\": 7143, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_battle_skill1_01\", \"description\": \"老实点！\", \"voicelineId\": 7144, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_battle_skill1_02\", \"description\": \"冻结吧！\", \"voicelineId\": 7145, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_battle_skill1_03\", \"description\": \"这个如何？\", \"voicelineId\": 7146, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_battle_skill3_01\", \"description\": \"小心着凉。\", \"voicelineId\": 7147, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_battle_skill3_02\", \"description\": \"抱歉哦。\", \"voicelineId\": 7148, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_battle_skill3_03\", \"description\": \"…这刹那，将是你的永恒。\", \"voicelineId\": 7149, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_explore_sprint_start_01\", \"description\": \"真是急性子啊你。\", \"voicelineId\": 7150, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺结束·其一\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_explore_sprint_end_01\", \"description\": \"呼，哈哈。\", \"voicelineId\": 7151, \"voicelineType\": \"710001\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_explore_fly_start_01\", \"description\": \"起风了。\", \"voicelineId\": 7152, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_chest_open_01\", \"description\": \"运气还不错！\", \"voicelineId\": 7154, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_chest_open_02\", \"description\": \"挺有趣的。\", \"voicelineId\": 7155, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_chest_open_03\", \"description\": \"哈哈，真有乐子。\", \"voicelineId\": 7156, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_life_less30_01\", \"description\": \"看来该认真了。\", \"voicelineId\": 7157, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_life_less30_02\", \"description\": \"似乎变得无聊了…\", \"voicelineId\": 7158, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_life_less30_03\", \"description\": \"麻烦的家伙…\", \"voicelineId\": 7159, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_life_less30_teammate_01\", \"description\": \"让我帮你吧，记得欠我一个人情。\", \"voicelineId\": 7160, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_life_less30_teammate_02\", \"description\": \"喂，命丢了可就不好玩了。\", \"voicelineId\": 7161, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_life_die_01\", \"description\": \"还没尽…兴…\", \"voicelineId\": 7162, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_life_die_02\", \"description\": \"哼，意料之外…\", \"voicelineId\": 7163, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_life_die_03\", \"description\": \"太难看了。\", \"voicelineId\": 7164, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_battle_hit_H_01\", \"description\": \"可恶…\", \"voicelineId\": 7165, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_kaeya/vo_kaeya_battle_hit_H_02\", \"description\": \"适可而止。\", \"voicelineId\": 7166, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_kaeya_teamJoin_01\", \"description\": \"真期待啊。\", \"voicelineId\": 7167, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_kaeya_teamJoin_02\", \"description\": \"去找点乐子吧。\", \"voicelineId\": 7168, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_kaeya_teamJoin_03\", \"description\": \"早就准备好喽。\", \"voicelineId\": 7169, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000016, 'Diluc', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_draw_appear\", \"description\": \"蒙德城的迪卢克，应约而来。闲聊恕不奉陪，如果你是想做一番大事，我倒有点兴致。\", \"voicelineId\": 8100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·放松\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_explore_idle_01\", \"description\": \"偶尔悠闲一下，也不错。\", \"voicelineId\": 8101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·骑士团\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_explore_idle_02\", \"description\": \"应该换骑士团的那些家伙来陪你。\", \"voicelineId\": 8102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·行会\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_explore_idle_03\", \"description\": \"行会里还有很多事，你要么在这休息，我回去看看。\", \"voicelineId\": 8103, \"voicelineType\": \"1103\"}, {\"title\": \"闲聊·准备\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_suit_aristocrat_idle_01\", \"description\": \"提前做好准备，先于对方进攻吧。\", \"voicelineId\": 8161, \"voicelineType\": \"1106\"}, {\"title\": \"闲聊·计划\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_suit_aristocrat_idle_02\", \"description\": \"休息时，也可以思考接下来的计划。\", \"voicelineId\": 8162, \"voicelineType\": \"1107\"}, {\"title\": \"闲聊·提醒\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_suit_aristocrat_idle_03\", \"description\": \"任何行动难免都有风险，你要多加小心。\", \"voicelineId\": 8163, \"voicelineType\": \"1108\"}, {\"title\": \"下雨的时候·伞\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_weather_heavyRain_01\", \"description\": \"我不用伞，你随意。\", \"voicelineId\": 8104, \"voicelineType\": \"1201\"}, {\"title\": \"下雨的时候·清洗\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_weather_heavyRain_02\", \"description\": \"雨吗，可惜洗刷不了那些污秽的心。\", \"voicelineId\": 8105, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_weather_sunny_01\", \"description\": \"只要坚信自己的道路，就无所谓天气是晴是雨。\", \"voicelineId\": 8106, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_weather_gale_01\", \"description\": \"呼啸的风声，会被用来遮掩犯罪的痕迹。\", \"voicelineId\": 8107, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_dialog_greetingMorning\", \"description\": \"寒暄就免了。昨夜一切平安就好。\", \"voicelineId\": 8108, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_dialog_greetingNoon\", \"description\": \"想试试隐藏菜单吗？\", \"voicelineId\": 8109, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_dialog_greetingNight\", \"description\": \"夜晚到了。\", \"voicelineId\": 8110, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_dialog_greetingNight2\", \"description\": \"嗯，下次见。我会目送你安全离开的。\", \"voicelineId\": 8111, \"voicelineType\": \"1004\"}, {\"title\": \"关于迪卢克自己…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_dialog_idle\", \"description\": \"「暗夜英雄」的传说吗？有趣的传言。\", \"voicelineId\": 8112, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·需要\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_dialog_close1\", \"description\": \"需要什么就直说。报销问题找埃泽。\", \"voicelineId\": 8113, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·证明\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_dialog_close2\", \"description\": \"你已经证明了你的决心。那么，也让你见证一下我的意志吧。\", \"voicelineId\": 8114, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_dialog_pendant\", \"description\": \"对于无法看清眼前道路的人来说，「神之眼」或许是神的一盏明灯。但对于有信念的人来说，只是一个可有可无的奖章罢了。\", \"voicelineId\": 8115, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_dialog_share\", \"description\": \"我偶尔会去「天使的馈赠」亲自调酒，因为酒馆是情报集中流通的地方。\", \"voicelineId\": 8116, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_pref_gift\", \"description\": \"…是夜枭。在黑暗中守望、观察的猛禽，只在最合适的时机出手，没有任何破绽。\", \"voicelineId\": 8117, \"voicelineType\": \"3003\"}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_teammate_kaeya_01\", \"description\": \"凯亚吗…那个男人说的话，只能信一半。\", \"voicelineId\": 8118, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_teammate_lisa_01\", \"description\": \"丽莎，能成为骑士团内最值得仰赖的人之一。如果她愿意的话。\", \"voicelineId\": 8119, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴·敌人\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_teammate_qin_01\", \"description\": \"无意义的琐事，是琴最大的敌人。\", \"voicelineId\": 8120, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴·职责\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_teammate_qin_02\", \"description\": \"琴那无人能及的责任心，终究让她没能看清自己真正的职责啊。\", \"voicelineId\": 8121, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莫娜…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_teammate_mona_01\", \"description\": \"蒙德的土地浸润着风神的恩泽，就不需要赞助占星术士来预测收成了吧。\", \"voicelineId\": 8122, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪奥娜…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_teammate_diona_01\", \"description\": \"迪奥娜对我的态度很是生硬，我也一直没找到合适的机会交流。如果是涉及到家族恩怨的话…嗯？不是？只是单纯地讨厌酒？没想到在这蒙德，也会有讨厌酒的酒保啊。\", \"voicelineId\": 8123, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_teammate_varka_01\", \"description\": \"大团长法尔伽，我能理解他的立场，却无法认同他的做派。呵…是我多言了。我早已不是西风骑士，忘了我说的话吧。\", \"voicelineId\": 8124, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于优菈…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_teammate_eula_01\", \"description\": \"我听说过她，她有自己的理念。努力挣脱家族束缚的气势也值得称道。但她…却加入了西风骑士团。\", \"voicelineId\": 8125, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪卢克·其一\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_friendship_01\", \"description\": \"有何贵干？\", \"voicelineId\": 8126, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解迪卢克·其二\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_friendship_02\", \"description\": \"嗯，你问骑士团？哼…没什么可多谈的，道路不同罢了。\", \"voicelineId\": 8127, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪卢克·其三\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_friendship_03\", \"description\": \"很久不和管家之外的人对弈了。难得有这份闲暇，跟我下局棋吧。\", \"voicelineId\": 8128, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪卢克·其四\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_friendship_04\", \"description\": \"将军。哼，但能把我逼到这个地步，还真是不简单啊。\", \"voicelineId\": 8129, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪卢克·其五\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_friendship_05\", \"description\": \"你还不赖。无论是对弈还是战斗，都不乏让人眼前一亮的表现。不…这样的合作，对我来说也算新奇…那么，今后也同行吧，「吾友」。\", \"voicelineId\": 8130, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"迪卢克的爱好…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_pref_hobby\", \"description\": \"庄园里的那些艺术品？那不是我的。是先父有收集的爱好。\", \"voicelineId\": 8131, \"voicelineType\": \"6001\"}, {\"title\": \"迪卢克的烦恼…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_dialog_annoyed\", \"description\": \"真正应当消灭的敌人，孕育罪恶的「黑暗」本身，需要用刀剑以外的方法去斩断…\", \"voicelineId\": 8132, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_pref_foodLike\", \"description\": \"你问我杯子里的是什么酒？葡萄汁而已，我一般喝这个。\", \"voicelineId\": 8133, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_pref_foodDislike\", \"description\": \"我不喜欢酒。没什么…我不喜欢酒的口感。\", \"voicelineId\": 8134, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_spice_pref_01\", \"description\": \"很精致。风味令人难忘。\", \"voicelineId\": 8170, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_spice_normal_01\", \"description\": \"能品尝出厨师的专注。不错的菜肴。\", \"voicelineId\": 8171, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_spice_dislike_01\", \"description\": \"…谢谢。\", \"voicelineId\": 8172, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_pref_birthday\", \"description\": \"生日快乐，这是属于你的重要日子。说吧，你的心愿。如果在我能力范围之内，我会考虑的。\", \"voicelineId\": 8135, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_starUp_01\", \"description\": \"为了达成目标，力量是必须的。\", \"voicelineId\": 8136, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_starUp_02\", \"description\": \"前方会有什么？我很少会思考这种问题。\\n我必须前进，不论有谁阻挡在我面前。\", \"voicelineId\": 8137, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_starUp_03\", \"description\": \"力量增强了…虽然还不够，但终归是在向前方探索。\\n在「黎明」到来之前，必须有人稍微照亮「黑暗」…\", \"voicelineId\": 8138, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_diluc/vo_diluc_starUp_04\", \"description\": \"我原以为——要扫荡罪恶的话，我必须独自行走在长夜之中。\\n但你的坚持让我意识到，我又一次错了。「同伴」，我向你致以感谢。\", \"voicelineId\": 8139, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_battle_skill1_01\", \"description\": \"呵。\", \"voicelineId\": 8140, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_battle_skill1_02\", \"description\": \"哈。\", \"voicelineId\": 8141, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_battle_skill1_03\", \"description\": \"哈！——\", \"voicelineId\": 8142, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_suit_aristocrat_skill1_01\", \"description\": \"呵。\", \"voicelineId\": 8164, \"voicelineType\": \"100010\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_suit_aristocrat_skill1_02\", \"description\": \"哈。\", \"voicelineId\": 8165, \"voicelineType\": \"100011\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_suit_aristocrat_skill1_03\", \"description\": \"哈！——\", \"voicelineId\": 8166, \"voicelineType\": \"100012\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_battle_skill3_01\", \"description\": \"在此——宣判！\", \"voicelineId\": 8143, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_battle_skill3_02\", \"description\": \"火焰——烧尽。\", \"voicelineId\": 8144, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_battle_skill3_03\", \"description\": \"审判——喝啊！\", \"voicelineId\": 8145, \"voicelineType\": \"200003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_suit_aristocrat_skill3_01\", \"description\": \"在此——清算！\", \"voicelineId\": 8167, \"voicelineType\": \"200010\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_suit_aristocrat_skill3_02\", \"description\": \"烈焰——燃毁！\", \"voicelineId\": 8168, \"voicelineType\": \"200011\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_suit_aristocrat_skill3_03\", \"description\": \"破晓——将至！\", \"voicelineId\": 8169, \"voicelineType\": \"200012\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_chest_open_01\", \"description\": \"哼，就当是聚沙成塔。\", \"voicelineId\": 8146, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_chest_open_02\", \"description\": \"还不赖。\", \"voicelineId\": 8147, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_chest_open_03\", \"description\": \"一点一滴地积累吧。\", \"voicelineId\": 8148, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_life_less30_01\", \"description\": \"这点程度…\", \"voicelineId\": 8149, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_life_less30_02\", \"description\": \"可恶…\", \"voicelineId\": 8150, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_life_less30_03\", \"description\": \"你会付出代价。\", \"voicelineId\": 8151, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_life_less30_teammate_01\", \"description\": \"…当心点。\", \"voicelineId\": 8152, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_life_less30_teammate_02\", \"description\": \"状态不好就去休息。\", \"voicelineId\": 8153, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_life_die_01\", \"description\": \"计划…出错了吗…\", \"voicelineId\": 8154, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_life_die_02\", \"description\": \"败者…没有借口…\", \"voicelineId\": 8155, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_life_die_03\", \"description\": \"要熄灭了吗…\", \"voicelineId\": 8156, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_diluc/vo_diluc_battle_hit_H_01\", \"description\": \"可恶。\", \"voicelineId\": 8157, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_diluc_teamJoin_01\", \"description\": \"走吧。\", \"voicelineId\": 8158, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_diluc_teamJoin_02\", \"description\": \"任务的目标是…\", \"voicelineId\": 8159, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_diluc_teamJoin_03\", \"description\": \"利落地解决吧。\", \"voicelineId\": 8160, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000020, 'Razor', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_draw_appear\", \"description\": \"你的气味…好闻。一起狩猎吧！\", \"voicelineId\": 9100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·气味\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_explore_idle_01\", \"description\": \"唔，兔子的味道…\", \"voicelineId\": 9101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·饿\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_explore_idle_02\", \"description\": \"走吗，肚子饿了。\", \"voicelineId\": 9102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·望风\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_explore_idle_03\", \"description\": \"我去望风，走了叫我。\", \"voicelineId\": 9103, \"voicelineType\": \"1103\"}, {\"title\": \"打雷的时候·提醒\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_weather_thunder_01\", \"description\": \"怕就快点躲起来。\", \"voicelineId\": 9104, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候·带路\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_weather_thunder_02\", \"description\": \"避开树，跟我来！\", \"voicelineId\": 9105, \"voicelineType\": \"1204\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_weather_breezy_01\", \"description\": \"风…唔…舒服。\", \"voicelineId\": 9106, \"voicelineType\": \"1202\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_weather_gale_01\", \"description\": \"风…嗯…扎扎的，有点疼。\", \"voicelineId\": 9107, \"voicelineType\": \"1203\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_dialog_greetingMorning\", \"description\": \"太阳出来了。狩猎一起去？\", \"voicelineId\": 9108, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_dialog_greetingNoon\", \"description\": \"大块吃肉，开心！\", \"voicelineId\": 9109, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_dialog_greetingNight\", \"description\": \"你去睡觉吧，我看月亮。\", \"voicelineId\": 9110, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_dialog_greetingNight2\", \"description\": \"你睡觉，我看守。明天一起狩猎。\", \"voicelineId\": 9111, \"voicelineType\": \"1004\"}, {\"title\": \"关于雷泽自己…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_dialog_idle\", \"description\": \"我是狼。人的爸爸、妈妈，没有。\", \"voicelineId\": 9112, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·朋友\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_dialog_close1\", \"description\": \"你是朋友。我和你一起狩猎。\", \"voicelineId\": 9113, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·武器\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_dialog_close2\", \"description\": \"我有铁的爪子和雷的牙。我保护你。\", \"voicelineId\": 9114, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_dialog_pendant\", \"description\": \"「神之眼」，师父帮忙。雷的牙打架，保护「卢皮卡」。\", \"voicelineId\": 9115, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_dialog_share\", \"description\": \"晚上，星星很好看。天空，湖里，都有很多很多星星。\\n晚上，城市里，也有很多星星。\", \"voicelineId\": 9116, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_pref_gift\", \"description\": \"我的「卢皮卡」的狼。它们是家人。\", \"voicelineId\": 9117, \"voicelineType\": \"3003\"}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_teammate_lisa_01\", \"description\": \"师父的雷，天空会变黑。很可怕，很强。\", \"voicelineId\": 9118, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [45406], \"unlockText\": \"完成「卢皮卡的意义」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芭芭拉…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_teammate_barbara_01\", \"description\": \"芭芭拉，亮晶晶的女孩子。很善良。\", \"voicelineId\": 9119, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_teammate_diluc_01\", \"description\": \"迪卢克，红红的、黑黑的。又冷又热。\", \"voicelineId\": 9120, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温迪…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_teammate_venti_01\", \"description\": \"诗歌…唔，不明白。虽然不明白，「卢皮卡」喜欢。\", \"voicelineId\": 9121, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于班尼特…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_teammate_bennett_01\", \"description\": \"班尼特，话很多，和他一起，吃不饱。\", \"voicelineId\": 9122, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_teammate_klee_01\", \"description\": \"可莉，朋友！朋友，但是，头疼。\", \"voicelineId\": 9123, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [45406], \"unlockText\": \"完成「卢皮卡的意义」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽·陌生\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_teammate_varka_01\", \"description\": \"法尔伽？不认识…\", \"voicelineId\": 9124, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽·回忆\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_teammate_varka_02\", \"description\": \"哦…法尔伽，是名字。那个男人，高大。雷泽名字，铁的爪子，他给的。唔…想见他。\", \"voicelineId\": 9125, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解雷泽·其一\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_friendship_01\", \"description\": \"你的气味，善良的味道。喜欢吃肉？\", \"voicelineId\": 9126, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解雷泽·其二\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_friendship_02\", \"description\": \"你很强。和狼一样强。喜欢和你狩猎。收获很多。\", \"voicelineId\": 9127, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解雷泽·其三\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_friendship_03\", \"description\": \"卢皮卡是「狼的家」。不对，是「狼的家人」。我的卢皮卡在树林里。它们保护我，说我是卢皮卡。\", \"voicelineId\": 9128, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解雷泽·其四\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_friendship_04\", \"description\": \"我只有卢皮卡。\\n但是，就算是卢皮卡，我没有四只脚，不是真的狼。有时候心里难过。\", \"voicelineId\": 9129, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解雷泽·其五\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_friendship_05\", \"description\": \"和你一起奔跑开心，和你一起狩猎开心。和你一起，我是狼，我是人，都没关系。\\n你是朋友，你是我的「卢皮卡」。我想要你也开心。\", \"voicelineId\": 9130, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"雷泽的爱好…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_pref_hobby\", \"description\": \"喜欢卢皮卡。喜欢树林。喜欢朋友。喜欢奔跑。\", \"voicelineId\": 9131, \"voicelineType\": \"6001\"}, {\"title\": \"雷泽的烦恼…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_dialog_annoyed\", \"description\": \"说话很累，很难。但是，不说话不行。\", \"voicelineId\": 9132, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_pref_foodLike\", \"description\": \"喜欢肉。喜欢土豆。\", \"voicelineId\": 9133, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_pref_foodDislike\", \"description\": \"蔬菜不好。我吃的肉才吃菜。\", \"voicelineId\": 9134, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_spice_pref_01\", \"description\": \"气味很香，味道一样好。喜欢。\", \"voicelineId\": 9163, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_spice_normal_01\", \"description\": \"吃了有力气，很开心。\", \"voicelineId\": 9164, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_spice_dislike_01\", \"description\": \"吃，不好。不吃，不好。有些难过。\", \"voicelineId\": 9165, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_pref_birthday\", \"description\": \"今天是你的…你是在很多很多个月以前的，今天出生的。想和你一起开心。今天一起吃肉。\", \"voicelineId\": 9135, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_starUp_01\", \"description\": \"手臂，更粗了…？\", \"voicelineId\": 9136, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_starUp_02\", \"description\": \"磨爪子，磨牙，要更强！\", \"voicelineId\": 9137, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_starUp_03\", \"description\": \"跑，狩猎。不够，不行！我要…更强。\", \"voicelineId\": 9138, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_razor/vo_razor_starUp_04\", \"description\": \"牙齿，爪子，腿。更强，更有力气…保护你！\", \"voicelineId\": 9139, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_battle_skill1_01\", \"description\": \"走开！\", \"voicelineId\": 9140, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_battle_skill1_02\", \"description\": \"啊！\", \"voicelineId\": 9141, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_battle_skill1_03\", \"description\": \"嗷！\", \"voicelineId\": 9142, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_battle_skill1_06\", \"description\": \"别过来！\", \"voicelineId\": 9143, \"voicelineType\": \"100004\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_battle_skill3_01\", \"description\": \"嗷——\", \"voicelineId\": 9144, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_battle_skill3_02\", \"description\": \"Blitz！\", \"voicelineId\": 9145, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_battle_skill3_03\", \"description\": \"嚎——\", \"voicelineId\": 9146, \"voicelineType\": \"200003\"}, {\"title\": \"元素爆发·其四\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_battle_skill1_02\", \"description\": \"啊——\", \"voicelineId\": 9147, \"voicelineType\": \"200004\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_chest_open_01\", \"description\": \"这些东西，可能有用？\", \"voicelineId\": 9148, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_chest_open_02\", \"description\": \"箱子，用完可以，装东西。\", \"voicelineId\": 9149, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_chest_open_03\", \"description\": \"宝藏的气味。奇怪。\", \"voicelineId\": 9150, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_life_less30_01\", \"description\": \"疼。\", \"voicelineId\": 9151, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_life_less30_02\", \"description\": \"嗷——\", \"voicelineId\": 9152, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_life_less30_03\", \"description\": \"杀了你！…\", \"voicelineId\": 9153, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_life_less30_teammate_01\", \"description\": \"不行。\", \"voicelineId\": 9154, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_life_less30_teammate_02\", \"description\": \"活下来！\", \"voicelineId\": 9155, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_life_die_01\", \"description\": \"唔，好难呼吸…\", \"voicelineId\": 9156, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_life_die_02\", \"description\": \"想回去…\", \"voicelineId\": 9157, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_life_die_03\", \"description\": \"我的…卢皮卡…\", \"voicelineId\": 9158, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_razor/vo_razor_battle_hit_H_02\", \"description\": \"嘴里，咸的…\", \"voicelineId\": 9159, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_razor_teamJoin_01\", \"description\": \"我打头阵。\", \"voicelineId\": 9160, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_razor_teamJoin_02\", \"description\": \"要去哪里？\", \"voicelineId\": 9161, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_razor_teamJoin_03\", \"description\": \"背后，交给我。\", \"voicelineId\": 9162, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000021, 'Amber', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_draw_appear\", \"description\": \"侦察骑士安柏，前来报到！今后有什么需要帮忙的，尽管说好啦！\", \"voicelineId\": 10100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·兴趣\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_explore_idle_01\", \"description\": \"好想跑一会儿步呀。\", \"voicelineId\": 10101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·挂念\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_explore_idle_02\", \"description\": \"要是被琴发现我们在偷懒，她会不高兴的。\", \"voicelineId\": 10102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·新发现\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_explore_idle_03\", \"description\": \"那边好像有什么奇怪的东西耶…不去看吗、不去看看吗？\", \"voicelineId\": 10103, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候·担忧\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_weather_heavyRain_01\", \"description\": \"下雨了…蝴蝶结会淋湿的…\", \"voicelineId\": 10104, \"voicelineType\": \"1201\"}, {\"title\": \"下雨的时候·提醒\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_weather_heavyRain_02\", \"description\": \"下雨了啊…视野会有影响，要小心哦。\", \"voicelineId\": 10105, \"voicelineType\": \"1202\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_weather_afterRain_01\", \"description\": \"唔哇~天气真好。\", \"voicelineId\": 10106, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_weather_sunny_01\", \"description\": \"嗯…要是风大点就好了。\", \"voicelineId\": 10107, \"voicelineType\": \"1204\"}, {\"title\": \"起风的时候·惬意\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_weather_breezy_01\", \"description\": \"真舒服呀…\", \"voicelineId\": 10108, \"voicelineType\": \"1205\"}, {\"title\": \"起风的时候·放松\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_weather_breezy_02\", \"description\": \"我喜欢这种天气，嗯…真轻松！\", \"voicelineId\": 10109, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_dialog_greetingMorning\", \"description\": \"早上好哟！要不要一起晨跑？\", \"voicelineId\": 10110, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_dialog_greetingNoon\", \"description\": \"可以跟你一起吃午饭吗？\", \"voicelineId\": 10111, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_dialog_greetingNight\", \"description\": \"天黑了，要我点个火把吗？\", \"voicelineId\": 10112, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_dialog_greetingNight2\", \"description\": \"没错，休息也很重要！那就说好了哦，明天见！\", \"voicelineId\": 10113, \"voicelineType\": \"1004\"}, {\"title\": \"关于安柏自己…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_dialog_idle\", \"description\": \"蒙德城的飞行冠军，就是我啦！\", \"voicelineId\": 10114, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·比赛\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_dialog_close1\", \"description\": \"就算是你，比赛我也不会放水！\", \"voicelineId\": 10115, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·飞行\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_dialog_close2\", \"description\": \"教你飞…与你一起飞行的时候，我自己好像也能飞得更快…欸，你在笑什么啊？来比赛吧！现在就比！\", \"voicelineId\": 10116, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_dialog_pendant\", \"description\": \"「神之眼」，是神对我的认可吧。嗯，我要成为最优秀的侦察骑士才行！\", \"voicelineId\": 10117, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_dialog_share\", \"description\": \"走嘛~去大教堂的钟楼上看看，风景超棒的！\", \"voicelineId\": 10118, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_pref_gift\", \"description\": \"看，那里有鸽子！嗯…想跟它们一起飞呢。\", \"voicelineId\": 10119, \"voicelineType\": \"3003\"}, {\"title\": \"关于琴·帮忙\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_qin_01\", \"description\": \"大团长出征之后，大大小小的事务都压在了琴的身上。如果我也能多帮到她一点就好了…\", \"voicelineId\": 10120, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴·关怀\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_qin_02\", \"description\": \"琴可能还在工作？…走，一起请她喝杯咖啡吧。\", \"voicelineId\": 10121, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎·听故事\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_lisa_01\", \"description\": \"等你有空，我们一起去找丽莎吧！她上次和我讲了一个龙脊雪山宝藏的故事，只讲到一半。唔，我还想知道后续！\", \"voicelineId\": 10122, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎·钦佩\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_lisa_02\", \"description\": \"丽莎好像除了睡觉的时间都在看书！真厉害啊，我就坐不住那么长时间。\", \"voicelineId\": 10123, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚·忧虑\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_kaeya_01\", \"description\": \"…有种不安的感觉！刚才是凯亚陪着你吧？他没给你添麻烦吧？\", \"voicelineId\": 10124, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚·祸首\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_kaeya_02\", \"description\": \"花圃里的蒲公英看上去蔫蔫的，哼…一定又是凯亚捣的鬼！\", \"voicelineId\": 10125, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于班尼特…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_bennett_01\", \"description\": \"嗯？班尼特…好像在哪里听过…哦！你说的是冒险家协会那个热血的男孩子啊！嗯，我有时会在秘境附近见到他，好像对寻宝很有热情呢。\", \"voicelineId\": 10126, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_klee_01\", \"description\": \"可莉呀，偶尔会有点调皮，但骑士团的大家都很喜欢她！唔…为了不让她又被琴抓去关禁闭，还是看紧她一点吧。\", \"voicelineId\": 10127, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_albedo_01\", \"description\": \"阿贝多，大多数时候都呆在自己的工坊里，捣鼓一些很厉害的东西。但是，见到他的时候，会有种猜不透他在想些什么的感觉。嗯，猜不透呢…\", \"voicelineId\": 10128, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于诺艾尔…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_noel_01\", \"description\": \"你问诺艾尔吗？她的韧性可是很强的。作为前辈，你也要多照顾她一点哦。\", \"voicelineId\": 10129, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于优菈…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_eula_01\", \"description\": \"优菈是我的好伙伴！只要习惯了优菈开的玩笑，你就会发现，其实她是很好相处的。只不过，优菈因为自己的姓氏，经常被很多人误解，怎么样才能让大家理解她呢…\", \"voicelineId\": 10130, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于柯莱…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_collei_01\", \"description\": \"柯莱和我写信说，她的「魔鳞病」已经彻底康复…我太为她高兴了！真想下一秒就飞到她身边，紧紧地抱住她。她还说很想念蒙德的大家，想等哪一天独当一面之后，亲口来汇报自己的成长…啊，要是能赶上下一次羽球节就好了，我都快等不及了！\", \"voicelineId\": 10179, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于米卡…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_teammate_mika_01\", \"description\": \"哦，米卡是优菈那儿的老队员了，最初可能是看我和优菈关系比较好吧，总是长官长官地叫我。在我跟他分享自己的侦察心得之后，他又改叫我前辈了…弄得我挺不好意思的。明明我们的职责不一样，他在绘制地图上的专业性，是我怎么都比不上的。\", \"voicelineId\": 10180, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解安柏·其一\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_friendship_01\", \"description\": \"狩猎我也很擅长哦！怎么样，想不想看看我的身手？还是…要来个狩猎比赛？\", \"voicelineId\": 10131, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解安柏·其二\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_friendship_02\", \"description\": \"和你分享我的飞行冠军经验吧！最重要的，就是要有勇气！\", \"voicelineId\": 10132, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解安柏·其三\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_friendship_03\", \"description\": \"其实我不擅长解谜，羽球节里看到猜谜的摊位都要绕着走…你呢？\", \"voicelineId\": 10133, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解安柏·其四\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_friendship_04\", \"description\": \"我因为爷爷才加入骑士团，因为琴留在了团里。现在，是你陪我见到了蒙德以外的天空。我真的很开心。\", \"voicelineId\": 10134, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解安柏·其五\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_friendship_05\", \"description\": \"我还想去更远的世界。我想去看天空的尽头！你也会继续陪着我的，对吧、对吧？\", \"voicelineId\": 10135, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"安柏的爱好…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_pref_hobby\", \"description\": \"兔兔伯爵，今天也是干干净净的一天！\", \"voicelineId\": 10136, \"voicelineType\": \"6001\"}, {\"title\": \"安柏的烦恼…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_dialog_annoyed\", \"description\": \"唔…你知道，怎样才能做出好吃的月亮派吗？\", \"voicelineId\": 10137, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_pref_foodLike\", \"description\": \"琴泡的咖啡真的好香！有机会你要尝尝哦。\", \"voicelineId\": 10138, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_pref_foodDislike\", \"description\": \"只要不是冰钩钩果汁…唔…我都应付得来！\", \"voicelineId\": 10139, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_spice_pref_01\", \"description\": \"哇，这个太好吃了。你真厉害！\", \"voicelineId\": 10176, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_spice_normal_01\", \"description\": \"要是我也有这样的手艺就好了…\", \"voicelineId\": 10177, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_spice_dislike_01\", \"description\": \"我不太习惯这种味道，抱歉啦！不是你的问题！\", \"voicelineId\": 10178, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_pref_birthday\", \"description\": \"嘿嘿嘿，生日快乐！来，这个给你，是我亲手缝的「兔兔伯爵·特别定制版」…放心放心，是特别定制版哦，不会爆炸的！\", \"voicelineId\": 10140, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_starUp_01\", \"description\": \"哇！像乘着风一样轻快~\", \"voicelineId\": 10141, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_starUp_02\", \"description\": \"现在的速度，没有人能追得上了吧！\", \"voicelineId\": 10142, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_starUp_03\", \"description\": \"蒙德的天空好像变小了…还是因为我的视野变大了？\", \"voicelineId\": 10143, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_ambor/vo_ambor_starUp_04\", \"description\": \"我现在…比起最初跟你认识的时候，又进步了不少吧。嘿嘿，非常感谢！让我请你吃蜜酱胡萝卜煎肉吧，跟我来跟我来！\", \"voicelineId\": 10144, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_battle_skill1_01\", \"description\": \"靠你咯。\", \"voicelineId\": 10145, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_battle_skill1_02\", \"description\": \"兔兔伯爵，出击！\", \"voicelineId\": 10146, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_battle_skill1_03\", \"description\": \"♪哼哼~哼哼哼~\", \"voicelineId\": 10147, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_battle_skill3_01\", \"description\": \"百发百中！\", \"voicelineId\": 10148, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_battle_skill3_02\", \"description\": \"箭如…雨下！\", \"voicelineId\": 10149, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_battle_skill3_03\", \"description\": \"你没有退路了！\", \"voicelineId\": 10150, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_explore_sprint_start_01\", \"description\": \"来比赛吧！\", \"voicelineId\": 10151, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺开始·其二\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_explore_sprint_start_02\", \"description\": \"跟得上我吗？\", \"voicelineId\": 10152, \"voicelineType\": \"700002\"}, {\"title\": \"冲刺结束·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_explore_sprint_end_01\", \"description\": \"说了你们跑不过我。\", \"voicelineId\": 10153, \"voicelineType\": \"710001\"}, {\"title\": \"冲刺结束·其二\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_explore_sprint_end_02\", \"description\": \"就是这种感觉！\", \"voicelineId\": 10154, \"voicelineType\": \"710002\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_explore_fly_start_01\", \"description\": \"我可是蒙德城的飞行冠军！\", \"voicelineId\": 10155, \"voicelineType\": \"800001\"}, {\"title\": \"打开风之翼·其二\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_explore_fly_start_02\", \"description\": \"尽管交给我吧！\", \"voicelineId\": 10156, \"voicelineType\": \"800002\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_chest_open_01\", \"description\": \"打开宝箱的一瞬间，最兴奋了！\", \"voicelineId\": 10159, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_chest_open_02\", \"description\": \"侦察骑士，发现目标！\", \"voicelineId\": 10160, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_chest_open_03\", \"description\": \"哇，都是好东西！\", \"voicelineId\": 10161, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_life_less30_01\", \"description\": \"…我可不会认输！\", \"voicelineId\": 10162, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_life_less30_02\", \"description\": \"好痛…这家伙…\", \"voicelineId\": 10163, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_life_less30_03\", \"description\": \"别小瞧我！\", \"voicelineId\": 10164, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_life_less30_teammate_01\", \"description\": \"小心啊！\", \"voicelineId\": 10165, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_life_less30_teammate_02\", \"description\": \"你…要不要紧？我来帮帮你吧？\", \"voicelineId\": 10166, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_life_die_01\", \"description\": \"跑累了…\", \"voicelineId\": 10167, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_life_die_02\", \"description\": \"训练…还不够…\", \"voicelineId\": 10168, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_life_die_03\", \"description\": \"这次我…输了啊…\", \"voicelineId\": 10169, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_battle_hit_L_02\", \"description\": \"真难缠！\", \"voicelineId\": 10170, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_battle_hit_H_01\", \"description\": \"好痛！\", \"voicelineId\": 10171, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_ambor/vo_ambor_battle_hit_H_02\", \"description\": \"犯规啦！\", \"voicelineId\": 10172, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_ambor_teamJoin_01\", \"description\": \"交给我吧！\", \"voicelineId\": 10173, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_ambor_teamJoin_02\", \"description\": \"准备就绪！\", \"voicelineId\": 10174, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_ambor_teamJoin_03\", \"description\": \"侦察骑士登场！\", \"voicelineId\": 10175, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000022, 'Venti', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_draw_appear\", \"description\": \"哈…睡得好香呀。欸，你好呀，旅行者，我们又见面了。嗯？不记得我了？嘿嘿，那就让我再次加入你的旅程吧。你的诗篇，值得被我这个世上最好的吟游诗人传唱！\", \"voicelineId\": 11100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·弹琴\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_explore_idle_01\", \"description\": \"嗯…想接着听下去的话，送我一个苹果吧。\", \"voicelineId\": 11101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·苹果酒\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_explore_idle_02\", \"description\": \"嗯…好想坐在大树上，手边有喝不完的苹果酒。哎。\", \"voicelineId\": 11102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·诗篇\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_explore_idle_03\", \"description\": \"动身吧，旅行者。佚失的诗篇，还在等着我们呢。\", \"voicelineId\": 11103, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_weather_heavyRain_01\", \"description\": \"来踩小水坑吧！看看谁溅出来的水花更大！\", \"voicelineId\": 11104, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_weather_afterRain_01\", \"description\": \"欸~这就天晴了？我还想多玩一会儿呢。\", \"voicelineId\": 11105, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_weather_snowy_01\", \"description\": \"等雪积起来…我们来打雪仗吧！\", \"voicelineId\": 11106, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_weather_gale_01\", \"description\": \"难得呀，要不要去飞一飞？\", \"voicelineId\": 11107, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_greetingMorning\", \"description\": \"早，准备开始新的冒险了么？\", \"voicelineId\": 11108, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_greetingNoon\", \"description\": \"咕…肚子饿了，又不敢再去晨曦酒庄蹭饭…啊，是你呀！欸嘿，要出门么？带我一个呗。\", \"voicelineId\": 11109, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_greetingNight\", \"description\": \"我还不困哦。要我陪你走走么？\", \"voicelineId\": 11110, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_greetingNight2\", \"description\": \"欸？要休息了吗？嘿嘿，晚安。\", \"voicelineId\": 11111, \"voicelineType\": \"1004\"}, {\"title\": \"关于温迪自己…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_idle\", \"description\": \"练习？哼哼，我当然不需要啦，在这提瓦特就没有我不会唱的歌。\", \"voicelineId\": 11112, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·新歌\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_close1\", \"description\": \"我想把你写进新歌里！欸，怎么露出这种表情呀，担心付不起稿费吗？哈哈，摩拉就不要了，不如…跟我再讲讲你的故事吧！\", \"voicelineId\": 11113, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·勇者\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_close2_heroine\", \"description\": \"唔…嗯！嘿嘿，等到勇者救出了{MATEAVATAR#SEXPRO[INFO_MALE_PRONOUN_BOYD|INFO_FEMALE_PRONOUN_GIRLD]}，我会第一时间让全大陆传唱这首歌谣。\", \"voicelineId\": 11114, \"voicelineType\": \"2003\", \"voicefile_male\": \"VO_friendship/VO_venti/vo_venti_dialog_close2_hero\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true, \"hasGenderedVoicefile\": true}, {\"title\": \"关于我们·使徒\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_close3\", \"description\": \"夜风凉爽，是适合成为神的使徒的天气！那么事不宜迟，快来向我献上供奉吧？\", \"voicelineId\": 11115, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [39604], \"unlockText\": \"完成「巨龙与自由之歌」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·请求\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_close4\", \"description\": \"欸，要风神我更加努力一点？那你是不是也要展示点诚意呢。比如虔诚、热爱，或者说…\", \"voicelineId\": 11116, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [39604], \"unlockText\": \"完成「巨龙与自由之歌」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_pendant\", \"description\": \"欸？好奇我的「神之眼」？喔…喏，给你。喜欢的话…要我给你做一个一样的么？嘿嘿嘿。\", \"voicelineId\": 11117, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_share\", \"description\": \"Olah！嘿嘿，这是丘丘人打招呼用的话哦。问我学这个干嘛？哎呀，为了创作，知识面当然越广越好啊。唔，好像，我还没尝试过用丘丘语写歌呢…\", \"voicelineId\": 11118, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_pref_gift\", \"description\": \"旅行者，你见过塞西莉亚花么？那是一种只在安静的山崖顶上默默绽放的白色野花。在我心里，它就是全提瓦特最美的花。\", \"voicelineId\": 11119, \"voicelineType\": \"3003\"}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_qin_01\", \"description\": \"骑士团代理团长大人…你觉得她是个怎样的人？嘿嘿，跟我想得一样。认真，勇敢，也不乏温柔。和我一个朋友有点像呢…\", \"voicelineId\": 11120, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_diluc_01\", \"description\": \"去跟迪卢克老爷处好关系吧？你想，他家可是有好~多~珍藏的酒啊！嘿嘿嘿，嘿嘿嘿嘿…咦，无论如何不准喝酒么？那…就去闻一闻吧，闻一闻！只是闻的话，你也可以喔。\", \"voicelineId\": 11121, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芭芭拉…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_barbara_01\", \"description\": \"唱歌很好听的牧师女孩儿，你认识么、你认识么？…唔，偶像？…啊，握手会？…嗯，专场live？…这样啊，音乐还真是深奥呐。\", \"voicelineId\": 11122, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷泽…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_razor_01\", \"description\": \"那个奔狼领的白发少年，哦哦，是吗，是被狼养大的啊…怪不得呢，他身上的气息，令人怀念…\", \"voicelineId\": 11123, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莫娜…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_mona_01\", \"description\": \"啊，那位占星术士吗？这么说吧，占卜和我的诗歌一样，都是让人穷到酒钱都凑不齐的没用技术呢！欸？你说占星至少是一项文化传统，所以不是没用的？呜，真失礼啊，那诗歌也一样有用啊！\", \"voicelineId\": 11124, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪奥娜…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_diona_01\", \"description\": \"远近闻名的猫尾酒馆特调酒。可是…呜，会，打，打喷嚏。要不，你帮我讨一杯酒来吧。我肯定会好好感激你的，一言为定。\", \"voicelineId\": 11125, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_albedo_01\", \"description\": \"黑土与白垩、宇宙与地层，无垢之土创生原初之人…特征实在太明显了，难以忽视呀。这么危险的古老技术，万一在城里失控——嗨，算了，就让蒙德人自己解决蒙德的问题吧。\", \"voicelineId\": 11126, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于摩拉克斯…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_morax_01\", \"description\": \"你见过那位老爷子了？他近来还好吗？欸，变成名叫「钟离」的普通人了？对他那个死脑筋而言，这应该是不小的改变啊。啊，陪我去见见他吧，带上这瓶埋在风起地的陈年好酒当作慰问品。啊对了，他现在还强不强，实力还剩几成啊？我这样过去，应该不会被打飞吧？\", \"voicelineId\": 11127, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于优菈…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_eula_01\", \"description\": \"优菈对酒的品位可是很不错的。无论夏天、冬天都要喝冰的这一点，在现在的蒙德人里也算难得啦。感觉能和她成为不错的酒友。嗯？你说我编排的劳伦斯家的歌…早已经传到了她的耳朵里？哈，那有什么关系嘛？说不定，我们还能一起唱呢。\", \"voicelineId\": 11128, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于巴尔…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_baal_01\", \"description\": \"听说，你把那位不可一世的雷电将军也击败了？啊…想当年她作为影武者的时候，就在追求极致的武技了。如今，也一定会借用各种各样的理由叫你做陪练吧。嗯嗯，偷偷告诉你她的弱点吧，耳朵凑过来——是「甜点心」哦！\", \"voicelineId\": 11167, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于布耶尔…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_nahida_01\", \"description\": \"你说草神啊，说到草神，就会先想到她那关于「梦境」的权能吧？与我所作的那些诗歌一样，她所创造的梦境也一样充满了浪漫与想象，我们可是很合得来呢。\", \"voicelineId\": 11171, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_teammate_furina_01\", \"description\": \"吟游诗人所擅长的，多是弹奏与演唱，可一位戏剧表演者所需要具备的能力，还远远不止这些…下次风花节把芙宁娜请过来一起表演怎么样？嗯？你想让我聊聊她拯救枫丹的事？有这样艺术才华的人就算拯救了整个世界，也毫不奇怪吧？\", \"voicelineId\": 11172, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解温迪·其一\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_friendship_01\", \"description\": \"来得正好，旅行者。我想听听，你的愿望是什么？\", \"voicelineId\": 11129, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解温迪·其二\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_friendship_02\", \"description\": \"跟你一起旅行真是件有趣的事，要说美中不足就是你身边的那只小不点了吧。那么能吃，你们的伙食费很了不得吧？哈哈。\", \"voicelineId\": 11130, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解温迪·其三\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_friendship_03\", \"description\": \"火之神是个横行霸道的战斗狂，岩之神是个不懂人心的死脑筋。问我怎么会知道这些？欸嘿，叙事诗里都写得一清二楚嘛，他们的故事。那个年代的故事。\", \"voicelineId\": 11131, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解温迪·其四\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_friendship_04\", \"description\": \"天空岛啊。连我也不一定飞得到那里呢。而且在那里，没有甜的水，也长不出什么好吃的果子。就更不会有好酒咯？嘿嘿，所以请我去我都不想去哦。\", \"voicelineId\": 11132, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解温迪·其五\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_friendship_05\", \"description\": \"我的愿望？嗯。以前，我想着要游历整个世界。现在也一样，不过嘛，加上了一份限定条件，那就是跟你一起。有你在，才是完整的。记叙者果然要和冒险者在一起才行嘛，嘿嘿！\", \"voicelineId\": 11133, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"温迪的爱好…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_pref_hobby\", \"description\": \"我喜欢酒！还有风！唔，如果能有用风酿的酒就好了。\", \"voicelineId\": 11134, \"voicelineType\": \"6001\"}, {\"title\": \"温迪的烦恼…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_dialog_annoyed\", \"description\": \"其实，只要有猫在附近，我就忍不住会打喷嚏…啊-啊-阿嚏！唔…哎呀…就连想一想也不行么…欸，你知不知道该怎么治好这个毛病呀？\", \"voicelineId\": 11135, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_pref_foodLike\", \"description\": \"你也来一个苹果吗，刚摘的。啊呜，啊…又脆又甜，苹果才是神的馈赠吧！\", \"voicelineId\": 11136, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_pref_foodDislike\", \"description\": \"哎，你在做什么好吃的吗？欸？热奶酪饼！这个…这个不行，热热的黏糊糊的，唔…对我来说，太腻了…\", \"voicelineId\": 11137, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_spice_pref_01\", \"description\": \"啊，好满足！明天也会有吧？后天也会有吧？\", \"voicelineId\": 11168, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_spice_normal_01\", \"description\": \"呼，好饱，连餐后水果都要吃不下了…\", \"voicelineId\": 11169, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_spice_dislike_01\", \"description\": \"竟然是连我都应付不来的食物。唔…这下可难办了。\", \"voicelineId\": 11170, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_pref_birthday\", \"description\": \"我以前听朋友说生日是要吃蛋糕的…喏，苹果蛋糕，给，勺子。烤出来的时候有点塌了，所以看上去像是苹果派。欸嘿，甜点还真是复杂呀。\", \"voicelineId\": 11138, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_starUp_01\", \"description\": \"欸！刚刚发生了什么！\", \"voicelineId\": 11139, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_starUp_02\", \"description\": \"辛苦啦。想要来点音乐放松一下吗？随想曲，还是小夜曲？\", \"voicelineId\": 11140, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_starUp_03\", \"description\": \"来，坐这边。我写了一首新诗哦，就叫它「旅行者之风」吧。\", \"voicelineId\": 11141, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_venti/vo_venti_starUp_04\", \"description\": \"唔…明明这些风景早就看过很多遍了，有你在身边，却像是呈现出了不同的样子。你该不会…还藏着一大堆奇奇怪怪的能力吧？…唔，那倒也不错。说明，我看人的眼光很准呀，欸嘿。\", \"voicelineId\": 11142, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_battle_skill1_01\", \"description\": \"哟呼——\", \"voicelineId\": 11143, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_battle_skill1_02\", \"description\": \"在这哟。\", \"voicelineId\": 11144, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_battle_skill1_03\", \"description\": \"留意脚下。\", \"voicelineId\": 11145, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_battle_skill1_04\", \"description\": \"一起来玩吧。\", \"voicelineId\": 11146, \"voicelineType\": \"100004\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_battle_skill3_01\", \"description\": \"别想逃开喔？\", \"voicelineId\": 11147, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_battle_skill3_02\", \"description\": \"起风咯~\", \"voicelineId\": 11148, \"voicelineType\": \"200002\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_explore_sprint_start_01\", \"description\": \"飞，比跑快吧？\", \"voicelineId\": 11149, \"voicelineType\": \"700001\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_explore_fly_start_01\", \"description\": \"呀嘿~\", \"voicelineId\": 11150, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_chest_open_01\", \"description\": \"咳咳，请听一首，「宝箱之歌」！\", \"voicelineId\": 11151, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_chest_open_02\", \"description\": \"嘿嘿，要不要感谢「风神的眷顾」呀？\", \"voicelineId\": 11152, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_chest_open_03\", \"description\": \"收获不少，可以拿去换几瓶好酒啦。\", \"voicelineId\": 11153, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_life_less30_01\", \"description\": \"等等，这可不好玩！\", \"voicelineId\": 11154, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_life_less30_02\", \"description\": \"哎呀，别盯着我打呀。\", \"voicelineId\": 11155, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_life_less30_03\", \"description\": \"好过分呐。\", \"voicelineId\": 11156, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_life_less30_teammate_01\", \"description\": \"交给我吧。\", \"voicelineId\": 11157, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_life_less30_teammate_02\", \"description\": \"还不能放弃哦。\", \"voicelineId\": 11158, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_life_die_01\", \"description\": \"稍微睡一下吧…\", \"voicelineId\": 11159, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_life_die_02\", \"description\": \"啊呀，弦断了…\", \"voicelineId\": 11160, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_life_die_03\", \"description\": \"扑通。\", \"voicelineId\": 11161, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_battle_hit_L_02\", \"description\": \"哎呀…\", \"voicelineId\": 11162, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_venti/vo_venti_battle_hit_H_02\", \"description\": \"好粗鲁哦。\", \"voicelineId\": 11163, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_venti_teamJoin_01\", \"description\": \"调音完成。\", \"voicelineId\": 11164, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_venti_teamJoin_02\", \"description\": \"让你久等了哦？\", \"voicelineId\": 11165, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_venti_teamJoin_03\", \"description\": \"是要做热身运动吗。\", \"voicelineId\": 11166, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000023, 'Xiangling', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_draw_appear\", \"description\": \"我是来自璃月的厨师香菱，最擅长的是做各种捞…捞，料理…哎呀，练了那么多次，还是会紧张，嘿。\", \"voicelineId\": 12100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·点心\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_explore_idle_01\", \"description\": \"要吃点点心休息一下吗？我准备了一箩！\", \"voicelineId\": 12101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·火史莱姆\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_explore_idle_02\", \"description\": \"火史莱姆，是椒盐…还是做成蒜香的好呢？\", \"voicelineId\": 12102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·觅食\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_explore_idle_03\", \"description\": \"嗯，闲着也是闲着，还不如一起找找食材去！\", \"voicelineId\": 12103, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候·态度\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_weather_heavyRain_01\", \"description\": \"嗯…我不太喜欢雨天。\", \"voicelineId\": 12104, \"voicelineType\": \"1201\"}, {\"title\": \"下雨的时候·疏忽\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_weather_heavyRain_02\", \"description\": \"我想想…今天有没有晒衣服出去…\", \"voicelineId\": 12105, \"voicelineType\": \"1202\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_weather_afterRain_01\", \"description\": \"走走走，我带你去找松茸！\", \"voicelineId\": 12106, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_weather_breezy_01\", \"description\": \"风史莱姆最喜欢在这种天气活动，快趁机多收集点儿！我给你做史莱姆沙冰！\", \"voicelineId\": 12107, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_dialog_greetingMorning\", \"description\": \"来得正好！一起去补充点食材吧？\", \"voicelineId\": 12108, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_dialog_greetingNoon\", \"description\": \"午饭已经做好了，快过来吃哦！啊呜…来晚了可就没了。\", \"voicelineId\": 12109, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_dialog_greetingNight\", \"description\": \"要吃夜宵吗？我这正好做了串炭烤岩蜥蜴。哎呀，别盯着了，快尝尝吧！\", \"voicelineId\": 12110, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_dialog_greetingNight2\", \"description\": \"喂…你不会是想背着我偷偷吃什么好东西吧？哦，只是休息啊…嘿嘿，那晚安喔。\", \"voicelineId\": 12111, \"voicelineType\": \"1004\"}, {\"title\": \"关于香菱自己…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_dialog_idle\", \"description\": \"你见过蒙德城的龙？有多大？哇，不是吧。那要是做成龙肉排——嗯，该有多棒啊！\", \"voicelineId\": 12112, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·长处\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_dialog_close1\", \"description\": \"虽然比起认路我更擅长做饭，但…不管啦，出门喊我准没错！\", \"voicelineId\": 12113, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·新知识\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_dialog_close2\", \"description\": \"自从认识你，我好像学会了不少料理以外的知识。欸？呃…你问我都有些什么？嗯…嗯…你突然这样问，我又有点想不起来了。算了算了，我原本就不擅长这些，还是给你做两道新菜尝尝吧！\", \"voicelineId\": 12114, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_dialog_pendant\", \"description\": \"无论什么时候，我都要做出所有人都爱吃的料理。神一定也认为这是正确的事情，才授予了我这个连大师父也没有的「神之眼」…唔，怎么说来着…哦，以资鼓励！\", \"voicelineId\": 12115, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_dialog_share\", \"description\": \"如果拉肚子了，喝一杯霓裳花泡的茶就会好的！欸？我懂一点食疗方法也不用奇怪吧！\", \"voicelineId\": 12116, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_pref_gift\", \"description\": \"我喜欢洋葱！…我试过十几种切洋葱不会流泪的方法，没一个对我有用。但这也阻止不了我喜欢洋葱！\", \"voicelineId\": 12117, \"voicelineType\": \"3003\"}, {\"title\": \"关于白术…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_baizhu_01\", \"description\": \"嗯？我闻到了雾虚花的香气！是白先生，白先生来帮你看病了吗？你是哪里不舒服，头晕还是胃疼？还是嗓子痒？还是没力气？哦…没生病啊。那还好。不然白先生会给你超——苦的药哦。\", \"voicelineId\": 12118, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_ningguang_01\", \"description\": \"哦！刚才那个，是「天权」大人啊…嗯，你凑过来点。再，再过来点。我跟你说哦，她可是一个特别厉害的人，港内的事情她什么都知道。所以，你也要小心一点，不要被她盯上了…\", \"voicelineId\": 12119, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_hutao_01\", \"description\": \"唔，你是不是也被胡桃欺负过？她老是趁我不注意躲到我后面，这样突然拍我的后背，得逞了还嘿嘿地笑，哼。但我大人大量，看在她每次都会给我带酿梅花做线花糕的份上，才没跟她斤斤计较。\", \"voicelineId\": 12120, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪奥娜…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_diona_01\", \"description\": \"清泉镇的迪奥娜！啊啊，听说她能调出特别好喝的酒，我专门拜访过她！想着如果能把调酒的秘方借鉴到料理上，说不定也能做出美味。但是，她给我的秘方，比如啤酒里泡蜥蜴尾巴，蒲公英酒里放小块熏鱼…做出来都不是很好吃。呜，果然还是要靠自己吗？\", \"voicelineId\": 12121, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_beidou_01\", \"description\": \"北斗姐姐人特别好！跟着她出去航海的话，每次都能捕获到好多新鲜的食材！章鱼脚拿来煲汤最好，海天青就要用辣椒好好炝一炝。不光北斗姐姐，「南十字」的船员们都很喜欢我做的菜呢。\", \"voicelineId\": 12122, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_zhongli_01\", \"description\": \"我遇到过不少挑剔的食客，但像钟离先生那种嘴巴上讲究，还能一针见血的，真的就只有他一个！那天我给他上的第一道菜是「椒盐豆腐」，他只尝了一口，就问我用的是什么盐，然后又说什么「不妨试试孤云阁浅海处提炼的海盐吧，它的层次感能够为豆腐赋予更多鲜味」。我试过之后味道真的大有不同。你说，他是不是好厉害！\", \"voicelineId\": 12123, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于重云…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_chongyun_01\", \"description\": \"重云啊，他总是跟着行秋一起来「万民堂」吃饭…呃，或者应该说，是被行秋拖来的？但是重云不吃热食。每次热菜上桌，行秋就会客客气气地说一声「失敬」，然后动起筷子逐一评点起每道菜的美味之处，他那夸得呀，我都想冲过去尝一口！你是没见到重云那种眼神，哈哈哈。还挺有趣的呢，他俩。\", \"voicelineId\": 12124, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_ganyu_01\", \"description\": \"甘雨？嗯…啊啊有印象有印象，是那位只吃素食的客人吧！她来「万民堂」的次数不算多，每次都是一个人躲在小角落里不吭声地吃着饭。我嘛，看她孤孤单单有些可怜，就总帮她多舀两大勺菜。没想到，她每次都能全部吃完！真是不可貌相。\", \"voicelineId\": 12125, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于瑶瑶…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_yaoyao_01\", \"description\": \"嘿嘿，她啊，是我引以为豪的小师妹喔！不过呀，她很久没来「万民堂」玩儿了。是大师父放心不下吧…哼，明明生的云来大章鱼那么好吃，瑶瑶上次不光不让我吃，还叫上大师父一起训斥我，呜…有时候真不知道，到底谁才是师姐了。\", \"voicelineId\": 12126, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于辛焱…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_xinyan_01\", \"description\": \"辛焱经常来「万民堂」吃夜宵喔！像行秋、重云他们不敢试吃的新品，辛焱就会毫不犹豫地下筷…而且有八成以上的概率喜欢！哎，真是很不错的人呐。\", \"voicelineId\": 12127, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夜兰…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_yelan_01\", \"description\": \"夜兰姐？我当然记得她啦。第一次见面时，我还猜她会喜欢那种清淡的菜式，没想到她是我见过最能吃辣的客人！菜肴里的辣味她觉得不够，居然把绝云椒椒直接嚼来吃！真了不起。\", \"voicelineId\": 12128, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于嘉明…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_gaming_01\", \"description\": \"哎呀，知道嘉明要来，我就会早早备上一大壶茶水，方便他涮辣菜。我提议说给他做一份不辣的，但他却摆着手说就喜欢原汁原味的配方…不会错的，那不是客套话，我能分辨出真正食客的眼神！嘿嘿，那我当然也不能让他失望啦！\", \"voicelineId\": 12171, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于蓝砚…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_teammate_lanyan_01\", \"description\": \"锅巴很喜欢她！第一天见面就不停地跟她握手，不知道的还以为他们认识了很久呢哈哈！我已经跟蓝师傅约好啦，让她带我去抓昆虫，采野蕈…嘻嘻，等我的新菜创作出来之后，你们都要来吃哦！\", \"voicelineId\": 12172, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解香菱·其一\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_friendship_01\", \"description\": \"烤鸽子肉，来两串？哎呀~尝尝嘛。加了我的独门秘方，绝对跟其他家的不一样！\", \"voicelineId\": 12129, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解香菱·其二\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_friendship_02\", \"description\": \"大师父教我的枪法，很厉害吧？你想学的话我也可以教给你哦！不过说到这个…要是你愿意跟我学厨就好了！我的这些技巧和配方，要流传得远远的才好呢。\", \"voicelineId\": 12130, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解香菱·其三\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_friendship_03\", \"description\": \"问我的愿望吗？那当然是要创造全新的新菜系！璃菜和月菜都是有极限的。哦，关键一定在于辣味吧！事不宜迟，让我爆炒个锅巴辣椒给你尝尝！\", \"voicelineId\": 12131, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解香菱·其四\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_friendship_04\", \"description\": \"嗯！我看你已经快被我的厨艺征服了嘛~是时候给你品尝我苦心研制的新菜品了——七彩琉璃大煎饼。喏喏，这薄薄一层蛋皮里面包着红色的松鼠火腿，橙色的胡萝卜，黄色的太阳蛙肉，绿色的嘟嘟莲，蓝色的蝴蝶翅膀…呃？真的不想吃吗？\", \"voicelineId\": 12132, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解香菱·其五\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_friendship_05\", \"description\": \"我…有点想不明白，明明以前睡一觉就好了的，这可不是我的风格。啊呀，不行！还是让你来想吧！嗯…我很想让你一直试吃我的新菜，但不知道从什么时候起，如果你吃坏了肚子，我也会特别难受。我，我到底该怎么办呢？\", \"voicelineId\": 12133, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"香菱的爱好…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_pref_hobby\", \"description\": \"看着点哦！像这样烧热一锅油，然后，把去掉翅膀的晶蝶这样放下去炸…哎呀你别走啊，超香的啦！\", \"voicelineId\": 12134, \"voicelineType\": \"6001\"}, {\"title\": \"香菱的烦恼…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_dialog_annoyed\", \"description\": \"呜，史莱姆滑蘑菇一份也没卖出去。就因为卖相不好吗？口感明明很棒的呀…\", \"voicelineId\": 12135, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_pref_foodLike\", \"description\": \"喜欢的食物呀，嘿，那当然是尚且不知道味道的新菜啦！欸，我这样回答很狡猾？呜，明明说的是实话嘛。\", \"voicelineId\": 12136, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_pref_foodDislike\", \"description\": \"我是不会对食物有什么偏见的！只有不合适的做法，没有不合格的食物！\", \"voicelineId\": 12137, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_spice_pref_01\", \"description\": \"哇，这就是…「噼咔」的味道！\", \"voicelineId\": 12168, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_spice_normal_01\", \"description\": \"嗯，你做菜真有一套。下次就换我来露两手吧。\", \"voicelineId\": 12169, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_spice_dislike_01\", \"description\": \"难道是做法的问题吗？总觉得哪里怪怪的…\", \"voicelineId\": 12170, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_pref_birthday\", \"description\": \"啊，找到你了！快来，我给你做了一整桌的菜喔！嘿嘿，不用急着夸我，先等你尝过味道再慢慢说吧！\", \"voicelineId\": 12138, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_starUp_01\", \"description\": \"呼哇~！好爽！全身上下都充满了力量！\", \"voicelineId\": 12139, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_starUp_02\", \"description\": \"嘿、哈！好！一拳就能把野物打晕…保证食材新鲜！\", \"voicelineId\": 12140, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_starUp_03\", \"description\": \"有这种力量的话…终于可以…不好，口水要流下来了！\", \"voicelineId\": 12141, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_xiangling/vo_xiangling_starUp_04\", \"description\": \"父亲曾经说过：「想做出十分的菜肴，就要投入十二分的热情。」我懂的、我懂的！能走到今天这个地步，一定是因为有你付出了十二分的热情陪我练习。嗯，那我也要再加倍…用再加倍的热情来回应你！\", \"voicelineId\": 12142, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_battle_skill1_01\", \"description\": \"锅巴，喷火！\", \"voicelineId\": 12143, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_battle_skill1_02\", \"description\": \"热和热和嘛。\", \"voicelineId\": 12144, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_battle_skill1_03\", \"description\": \"开锅了开锅了！\", \"voicelineId\": 12145, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_battle_skill3_01\", \"description\": \"嘿…哈！\", \"voicelineId\": 12146, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_battle_skill3_02\", \"description\": \"讲不通，就打扁咯！\", \"voicelineId\": 12147, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_battle_skill3_03\", \"description\": \"见识下师父的枪法！\", \"voicelineId\": 12148, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_explore_sprint_start_01\", \"description\": \"跑起来跑起来！\", \"voicelineId\": 12149, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺结束·其一\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_explore_sprint_end_01\", \"description\": \"肚子岔气了…\", \"voicelineId\": 12150, \"voicelineType\": \"710001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_chest_open_01\", \"description\": \"是新的食材！\", \"voicelineId\": 12151, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_chest_open_02\", \"description\": \"大丰收大丰收！\", \"voicelineId\": 12152, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_chest_open_03\", \"description\": \"我会物尽其用！\", \"voicelineId\": 12153, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_life_less30_01\", \"description\": \"呜，今天的食材好凶啊。\", \"voicelineId\": 12154, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_life_less30_02\", \"description\": \"哎呀，疼疼疼…\", \"voicelineId\": 12155, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_life_less30_03\", \"description\": \"我是不是惹了个不得了的家伙！\", \"voicelineId\": 12156, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_life_less30_teammate_01\", \"description\": \"别着急，歇会儿再打吧？\", \"voicelineId\": 12157, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_life_less30_teammate_02\", \"description\": \"快回来！\", \"voicelineId\": 12158, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_life_die_01\", \"description\": \"搞砸了呢…\", \"voicelineId\": 12159, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_life_die_02\", \"description\": \"突然…好渴啊…\", \"voicelineId\": 12160, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_life_die_03\", \"description\": \"是不是…连累你了…\", \"voicelineId\": 12161, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_battle_hit_L_02\", \"description\": \"不要打我…\", \"voicelineId\": 12162, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_battle_hit_H_01\", \"description\": \"救命啊，食材打人啦！\", \"voicelineId\": 12163, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_xiangling/vo_xiangling_battle_hit_H_02\", \"description\": \"还挺疼的唔…\", \"voicelineId\": 12164, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_xiangling_teamJoin_01\", \"description\": \"佐料带全了！\", \"voicelineId\": 12165, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_xiangling_teamJoin_02\", \"description\": \"长枪磨亮了！\", \"voicelineId\": 12166, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_xiangling_teamJoin_03\", \"description\": \"一刻都不想多等！\", \"voicelineId\": 12167, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000024, 'Beidou', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_draw_appear\", \"description\": \"我是北斗，听过我的「南十字」船队吗？如果你也喜欢冒险，那就跟着我吧。我罩你。\", \"voicelineId\": 14100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·切磋\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_explore_idle_01\", \"description\": \"想切磋的话，我随时奉陪。\", \"voicelineId\": 14101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·畅饮\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_explore_idle_02\", \"description\": \"啊——干完活，喝口酒。真畅快。\", \"voicelineId\": 14102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·陆地\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_explore_idle_03\", \"description\": \"难得在陆地上逗留那么久，居然有点不习惯了。\", \"voicelineId\": 14103, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_weather_heavyRain_01\", \"description\": \"被困荒岛的时候，雨水就是宝贵的淡水来源。嗯…虽然现在是用不上啦。\", \"voicelineId\": 14104, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_weather_thunder_01\", \"description\": \"喂，打雷而已。在海上不用怕，在陆地上，就更不用怕了。\", \"voicelineId\": 14105, \"voicelineType\": \"1202\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_weather_breezy_01\", \"description\": \"这天气，很适合出航啊。\", \"voicelineId\": 14106, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_weather_gale_01\", \"description\": \"注意扬起来的风沙，别揉眼睛。\", \"voicelineId\": 14107, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_greetingMorning\", \"description\": \"哟，早。我准备出发了，一起来？\", \"voicelineId\": 14108, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_greetingNoon\", \"description\": \"去香菱那吃午饭吧。你别说，这大锅热油炒出来的，还真和海上的烤鱼腌肉不一样。\", \"voicelineId\": 14109, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_greetingNight\", \"description\": \"好，出发喝酒去喽！嗯？哈哈哈，平时没人卖酒给你是吧？那不如——\", \"voicelineId\": 14110, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_greetingNight2\", \"description\": \"这时间过得可真快。去吧，一帆风顺。\", \"voicelineId\": 14111, \"voicelineType\": \"1004\"}, {\"title\": \"关于北斗自己…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_idle\", \"description\": \"航海准备，兄弟们，各就各位，全新的冒险要开始了！\", \"voicelineId\": 14112, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·称呼\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_close1\", \"description\": \"我是老大，你是我兄弟，没问题吧？哈？这些叫法太老土？行。那就按你喜欢的方式叫吧。\", \"voicelineId\": 14113, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·识人\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_close2\", \"description\": \"我认人很准。当你见过大海，那么普通人脸上的小水花，可就太好读懂了。哈哈，所以，我第一眼就认准了你这个家伙。\", \"voicelineId\": 14114, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·选择\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_close3\", \"description\": \"你是我选择的船员，是我选择的兄弟。就说这一点，都够我自豪很久。\", \"voicelineId\": 14115, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_pendant\", \"description\": \"在那些没有「神之眼」的家伙心中，拥有「神之眼」，获得了神的认可的人，应该是旗帜吧。那么，旗帜就该有旗帜的样子。我是这样鞭策自己的。\", \"voicelineId\": 14116, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_share\", \"description\": \"遇到难题了吗？不知道如何向前的话，总之先迈出第一步，后面的道路就会自然而然地展开了。\", \"voicelineId\": 14117, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_pref_gift\", \"description\": \"每次远航回来看见石鸢的时候，就说明差不多快到家了。海上的景色看多了难免单调，相比之下，虽说是猛禽，但那副自在翱翔的模样，总觉得亲切可爱。\", \"voicelineId\": 14118, \"voicelineType\": \"3003\"}, {\"title\": \"关于凝光·璃月七星\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_teammate_ningguang_01\", \"description\": \"凝光啊，从「璃月七星」的角度上来说已经做得很好了吧。只是，我要负责的对象从来就是我的船和兄弟们，不是什么「璃月七星」啊。\", \"voicelineId\": 14119, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光·态度\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_teammate_ningguang_02\", \"description\": \"凝光一向不怎么坦率，但她曾经很直接地表露过对我的不满。哈哈，不过啊，喜欢和讨厌都是她自己的事情，我是不可能动摇的。\", \"voicelineId\": 14120, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱·好厨艺\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_teammate_xiangling_01\", \"description\": \"香菱的一手好菜，可是我们一众人在远航时的念想。没力气的时候，要是想想干煸绝云椒椒那满嘴留香的滋味，都能精神几分。\", \"voicelineId\": 14121, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱·试吃\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_teammate_xiangling_02\", \"description\": \"香菱啊，她偶尔也会用一些说不上好滋味的食材，做出一些很是了不得的味道。不过嘛，没有尝试就不会有进步，我倒是挺乐意帮她试吃的。\", \"voicelineId\": 14122, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_teammate_zhongli_01\", \"description\": \"你说「往生堂」的那位先生吗？兄弟们有时会聊起他的传言，听上去是个很有意思的人啊。嗯，有机会去结交一下吧。\", \"voicelineId\": 14123, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_teammate_xiao_01\", \"description\": \"有一年海灯节前夕，船队在归航时遭遇了风暴，紧赶慢赶才在入夜时分回到了璃月港。那时候海灯早就散了。我却在孤云阁的方向，看到了空中悬着一个少年模样的仙人。想必就如传闻一样，在人们看不见的地方，也有人在守护这个璃月港吧。\", \"voicelineId\": 14124, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_teammate_ganyu_01\", \"description\": \"我和甘雨那丫头私交不错！但你也知道，她是「璃月七星」的秘书，「七星」不待见我那可不是一天两天了。哈，我倒是无所谓，要连累了那丫头可不行。嗯，对外还是保密得好。\", \"voicelineId\": 14125, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于辛焱…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_teammate_xinyan_01\", \"description\": \"哈，很有意思的丫头！船上的兄弟们也有喜欢听她「摇滚」的。嗯…我本人？怎么说呢，虽然在某些方面跟辛焱有共同话题，但我的音乐品味却是另一方面的…\", \"voicelineId\": 14126, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于瑶瑶…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_teammate_yaoyao_01\", \"description\": \"瑶瑶这个小家伙啊，总是爱到船上来玩。但她那副扑闪着眼睛，见什么都新奇的样子，让谁都狠不下心来赶她走。唉，差点要打乱出航的计划。\", \"voicelineId\": 14127, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_teammate_kazuha_01\", \"description\": \"听说万叶那小子在天守阁外挡了雷电将军的一刀，不简单嘛！嗯…战争结束后，他回了我们南十字船队，说是继续和我们同行一段时间。我当然是非常欢迎了，如果哪天他决定要独自踏上下一段旅程，我再打一壶好酒为他送行，哈哈。\", \"voicelineId\": 14128, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解北斗·其一\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_friendship_01\", \"description\": \"想要踏上我的「死兆星」号，得先回答我一个问题。大海之中充满凶险，告诉我——你为什么想上我的船？\", \"voicelineId\": 14130, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解北斗·其二\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_friendship_02\", \"description\": \"那些关于我的传奇故事？哈哈哈，那是兄弟们看重，才在夸我的时候添油加醋。不过，你要问我怕不怕在出海的时候遇到什么魔物，那自然是不怕的。\", \"voicelineId\": 14131, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解北斗·其三\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_friendship_03\", \"description\": \"问我帮助平民的用意？哈，哪有什么用意不用意的。谁的人生还没有个低谷。我的帮助是小事，但对他们而言，迈不迈得过去那道坎，可能就是两条路啊。\", \"voicelineId\": 14132, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解北斗·其四\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_friendship_04\", \"description\": \"我经历过痛苦的时光。小时候没摩拉买吃的，只好偷人家树上的果子，讨了几年生活。等到有了自己的船队，还是被趾高气昂的商人们排挤在外。但是，这些事当作茶余饭后的笑谈讲给你听，就足够了，我绝不会让你再经历一遍。\", \"voicelineId\": 14133, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解北斗·其五\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_friendship_05\", \"description\": \"追随我的兄弟有很多，我问过，我也记得他们每一个人上船的理由。你是很特别的。我知道你还有需要完成的事情，我不会授予你职务和头衔。但无论你的旅途去往何方，「死兆星」号上，永远都有你的位置。\", \"voicelineId\": 14134, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"北斗的爱好…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_pref_hobby\", \"description\": \"爱好啊…我想想。冒险算一个，掌舵算一个，交朋友算一个，喝酒算一个，吃好吃的算一个…啧，一个手都数不过来啊。\", \"voicelineId\": 14135, \"voicelineType\": \"6001\"}, {\"title\": \"北斗的烦恼…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_dialog_annoyed\", \"description\": \"搞得定的事不必烦恼，搞不定的事烦恼也没有意义。我就这样过得快快活活的。哦，要是你遇到什么想不通的事情，你可以来找我。我帮你一起解决。\", \"voicelineId\": 14136, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_pref_foodLike\", \"description\": \"我喜欢味道重的菜！什么炝炒肉片啊，麻婆豆腐啊我就很喜欢。能填饱肚子，大家围坐一圈一起吃的时候，气氛也会变得火热火热的。哈，说得我都想去吃一顿了。\", \"voicelineId\": 14137, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_pref_foodDislike\", \"description\": \"我不太喜欢吃凉菜冷盘。有这慢悠悠开胃的功夫，鱼都能烤熟几条了。\", \"voicelineId\": 14138, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_spice_pref_01\", \"description\": \"好味道，我喜欢！有米饭吗，帮忙添两碗？\", \"voicelineId\": 14169, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_spice_normal_01\", \"description\": \"你的手艺真不错，让人心情也变得不一样了。\", \"voicelineId\": 14170, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_spice_dislike_01\", \"description\": \"菜是好菜，这就够了。\", \"voicelineId\": 14171, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_pref_birthday\", \"description\": \"来，上船。我早就跟兄弟们约好把时间腾出来了，吃的喝的也都准备好了。今天你生日，让你做一天老大。哈！嗯，想去哪？\", \"voicelineId\": 14139, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_starUp_01\", \"description\": \"痛快！又变强了不少。\", \"voicelineId\": 14140, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_starUp_02\", \"description\": \"这满载而归的滋味，开瓶美酒来庆祝吧！\", \"voicelineId\": 14141, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_starUp_03\", \"description\": \"好样的，有你这种得力的兄弟，是我北斗的荣光！我也不能让你小瞧了啊。\", \"voicelineId\": 14142, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_beidou/vo_beidou_starUp_04\", \"description\": \"这几番操练下来，算是达到了我武艺的巅峰状态了吧。谢谢你…对了，不如再陪我过两招吧。\", \"voicelineId\": 14143, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_skill1_04\", \"description\": \"闪开！\", \"voicelineId\": 14144, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_skill1_05\", \"description\": \"哈！\", \"voicelineId\": 14145, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_skill1_06\", \"description\": \"悉数奉还！\", \"voicelineId\": 14146, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_skill1_07\", \"description\": \"接下吧！\", \"voicelineId\": 14147, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_skill1_08\", \"description\": \"——喝啊！\", \"voicelineId\": 14148, \"voicelineType\": \"100005\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_skill3_01\", \"description\": \"这是斩灭「海山」的力量！\", \"voicelineId\": 14149, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_skill3_02\", \"description\": \"给我瞧好了！\", \"voicelineId\": 14150, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_skill3_03\", \"description\": \"化作焦炭吧！\", \"voicelineId\": 14151, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_chest_open_01\", \"description\": \"哟，真让人开心。\", \"voicelineId\": 14152, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_chest_open_02\", \"description\": \"不错嘛，又有收获了！\", \"voicelineId\": 14153, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_chest_open_03\", \"description\": \"找到了财宝，就来喝酒助兴吧！\", \"voicelineId\": 14154, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_life_less30_01\", \"description\": \"还没完呢！\", \"voicelineId\": 14155, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_life_less30_02\", \"description\": \"哼，我来精神了。\", \"voicelineId\": 14156, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_life_less30_03\", \"description\": \"我绝不屈服。\", \"voicelineId\": 14157, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_life_less30_teammate_01\", \"description\": \"到我身后！\", \"voicelineId\": 14158, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_life_less30_teammate_02\", \"description\": \"退下！别逞英雄。\", \"voicelineId\": 14159, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_life_die_01\", \"description\": \"糟透了。\", \"voicelineId\": 14160, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_life_die_02\", \"description\": \"兄弟们…先…撤…\", \"voicelineId\": 14161, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_life_die_03\", \"description\": \"全员…归航…\", \"voicelineId\": 14162, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_hit_L_02\", \"description\": \"区区小伤。\", \"voicelineId\": 14163, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_hit_H_01\", \"description\": \"输赢还说不定呢。\", \"voicelineId\": 14164, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_beidou/vo_beidou_battle_hit_H_02\", \"description\": \"有两下子。\", \"voicelineId\": 14165, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_beidou_teamJoin_01\", \"description\": \"好，出发吧！\", \"voicelineId\": 14166, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_beidou_teamJoin_02\", \"description\": \"跟我来吧。\", \"voicelineId\": 14167, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_beidou_teamJoin_03\", \"description\": \"我相信你。\", \"voicelineId\": 14168, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000025, 'Xingqiu', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_draw_appear\", \"description\": \"在下行秋，不过书海一蠹。某虽不才，仍愿为君略尽绵薄。难得有机会说这种风格的台词，感觉还不错。\", \"voicelineId\": 13009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·无人夜\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_explore_idle_01\", \"description\": \"「有时明月无人夜，独向昭潭制恶龙。」\", \"voicelineId\": 13010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·文章\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_explore_idle_02\", \"description\": \"「衣裓贮文章，自言学雕虫。」\", \"voicelineId\": 13011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·偷闲\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_explore_idle_03\", \"description\": \"正所谓「偷得浮生半日闲」，哈哈。\", \"voicelineId\": 13012, \"voicelineType\": \"1103\"}, {\"title\": \"闲聊·阅卷\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_explore_idle_04\", \"description\": \"如此如此，这般这般…欸？欲知后事如何，且听下回分解？唔…\", \"voicelineId\": 13013, \"voicelineType\": \"1104\"}, {\"title\": \"闲聊·新书\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_explore_idle_05\", \"description\": \"盘算着也该到「万文集舍」新进小说的日子了，不妨…我们顺道去看看？\", \"voicelineId\": 13014, \"voicelineType\": \"1105\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_weather_heavyRain_01\", \"description\": \"这么说来，我们家出品的锦缎伞，好像既不能遮阳也不能挡雨。唯一的用处就是挂在墙上。\", \"voicelineId\": 13015, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_weather_afterRain_01\", \"description\": \"晴了就好，不然藏书会生霉的。\", \"voicelineId\": 13016, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_weather_snowy_01\", \"description\": \"只有这种天气的时候，我才会觉得家里比书店好。家里炭火很足，而书堆里就不准用火。\", \"voicelineId\": 13017, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_weather_sunny_01\", \"description\": \"练功的好…啊不，是看书的好时节啊。好啦，我脸上又没有写字，别一直盯着我看了。\", \"voicelineId\": 13018, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_greetingMorning\", \"description\": \"早啊。早上的时间这么难得，能做做自己喜欢的事情就好了。\", \"voicelineId\": 13019, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_greetingNoon\", \"description\": \"午饭有点不想吃米饭，想吃糕点。待在书斋吃，父亲和兄长就不知道了…嗯？想一起来吗？嗯…只要你不把碎屑沾到书上就行。\", \"voicelineId\": 13020, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_greetingNight\", \"description\": \"去偷点萤火虫来看书，怎么样？唔，我的玩笑话你可别当真，对眼睛不好的。\", \"voicelineId\": 13021, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_greetingNight2\", \"description\": \"明天我也在老地方。只要你不中途迷了路，就准能找得到我。\", \"voicelineId\": 13022, \"voicelineType\": \"1004\"}, {\"title\": \"关于行秋自己…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_idle\", \"description\": \"在人前彬彬有礼，是因为大家见我是飞云商会的二少爷；在你面前能这么轻松，大概因为你看我的方式并不一样吧。\", \"voicelineId\": 13023, \"voicelineType\": \"2001\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·书友\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_close\", \"description\": \"你算是我的书友吧。什么？打架？古华派？战友？…唔！你都在说些什么呢。不是说好这是我们两人间的秘密吗！\", \"voicelineId\": 13024, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·结拜\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_close1\", \"description\": \"我要和你结拜，就去绝云间的祭坛那边。不行，不能拒绝。你知道了我的底细，也就知道了一直被我掩饰着的真实的自己…我不能放你走。除非…你答应我不会撒手不干！\", \"voicelineId\": 13025, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·古书\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_pendant\", \"description\": \"「神之眼」的事情，虽然一般少有记载，但在我所收集的古书中却有一段特别的描述，待我找给你。\", \"voicelineId\": 13026, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·领悟\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_pendant_02\", \"description\": \"受书中启发，我领会到，枪术与剑术的本质，正是瞳术。唔，解释起来可能有点费力…如果你真想知道，就跟我去「王山厅」走一趟吧。事先声明，到时候你可不准笑。\", \"voicelineId\": 13027, \"voicelineType\": \"3004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_share\", \"description\": \"璃月非去不可的地方？这个问题很难回答，不过，如果消失了会让我很难过的地方…「万文集舍」稳排第一，「古华堂」能进前十吧。\", \"voicelineId\": 13028, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_pref_gift\", \"description\": \"以前是兔子，后来是鹿。对我来说，「请从绝处，读我侠义」是舍弃一切的觉悟，鹿却是绝处逢得新生的希望。真想再见它一次啊。\", \"voicelineId\": 13029, \"voicelineType\": \"3003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_beidou_01\", \"description\": \"北斗阁下是我非常敬重的人。不过希望她不要喊我「小子」，也不要一见面就揉我头发。\", \"voicelineId\": 13030, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_ningguang_01\", \"description\": \"「天权」大人是我不得不敬重的人。不然会给家父以及家兄添麻烦。嗯？对她本人，我想想。嗯…还是算了，不说人坏话了。\", \"voicelineId\": 13031, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于重云…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_chongyun_01\", \"description\": \"唉，重云这家伙，虽然也知道我的底细，但真要和他搭档去完成任务还得审慎。他现在还是执着「武」技，却不理解「侠」心的境界。需要多练练。尤其…是吃辣的方面，哈哈。\", \"voicelineId\": 13032, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于云堇…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_yunjin_01\", \"description\": \"云堇啊，她只要能喝到满意的饮品，就会有动力去创作新戏。我呢，就一直在床底下囤着一小罐茶叶，就是为了等哪天她兴致索然的时候给她送去。这样，我就有听不完的异侠传奇了！\", \"voicelineId\": 13033, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_hutao_01\", \"description\": \"那个小姑娘，正是「往生堂」的当代堂主。嗯？问我怎样看待她的为人？…行事作风嘛，坊间传闻是作不了数的。真想了解一个人，还得看她真正想要的是什么。\", \"voicelineId\": 13034, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于七七…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_qiqi_01\", \"description\": \"总感觉七七的身上藏着谜团。但只要白术先生在场，就跟她说不上几句话。除非，我们能找个白术先生外出看诊的机会，专门…\", \"voicelineId\": 13035, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_xiangling_01\", \"description\": \"见到香菱的时候，你可得多观察一下她的表情。尤其是刚刚添置完食材回来的香菱，笑得越开心，就越危险。要是被她缠上、逼你试吃新品…这种情况，我一般会靠重云来处理。\", \"voicelineId\": 13036, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于辛焱…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_xinyan_01\", \"description\": \"辛焱到底是在哪里演出的？从吃虎岩到玉京台，哪里都躲不过那种鸡飞狗跳的穿透力…唉，能够安静看书的时日是多么宝贵啊。\", \"voicelineId\": 13037, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_albedo_01\", \"description\": \"下一卷、下下卷、下下下卷的重要场景，我都已经想好要配怎样的插画了！啊，必须赶快把灵感记下来，修书一封，寄给白垩老师…\", \"voicelineId\": 13038, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_zhongli_01\", \"description\": \"我看见过家父和家兄接待这位先生，就从他们行礼时候的恭敬态度来看…对方应该是很有地位的人物吧。我还听说他是给仙人办丧事的人，感觉很有底蕴。要不要一起去挖掘他身上的秘密呢？\", \"voicelineId\": 13039, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [101609], \"unlockText\": \"完成「辞行久远之躯」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于申鹤…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_shenhe_01\", \"description\": \"总觉得申鹤小姐看我的眼神里略显凶恶，让我不敢随便跟她搭话。奇怪，难道我无意中得罪过她吗？或者…得罪过她身边的人？\", \"voicelineId\": 13040, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夜兰…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_yelan_01\", \"description\": \"你听说过「一人千面」这个词语吗？夜兰小姐就给我这种感觉。上门来访的时候，家父和家兄以礼相待，她也还之以礼，就像是个亲切稳重的大姐姐。可在别的地方见到她时，又完全是不同的印象。\", \"voicelineId\": 13041, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于嘉明…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_teammate_gaming_01\", \"description\": \"嘉明的工作颇有侠之风范。试想，功夫盖世的黑衣少年携手威武镇煞的瑞兽，在月黑风高夜，将盗贼与恶徒打得落花流水，狼狈而逃…等他得空，真想听他多分享一些走镖路途中的见闻。你也一起来吧？\", \"voicelineId\": 13085, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解行秋·其一\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_friendship_01\", \"description\": \"阁下近来可好？如果闲来无事，可以来「万文集舍」转转。\", \"voicelineId\": 13042, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解行秋·其二\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_friendship_02\", \"description\": \"问我为什么总是一个人看书？好学…并不是什么坏习惯吧。没有什么特别的地方，嗯，真的没有。\", \"voicelineId\": 13043, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解行秋·其三\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_friendship_03\", \"description\": \"今天的时间已经空出来了吗？好，我也随时可以出发。书？没关系，书可以回来接着看，那些需要我们帮助的人可不能等啊。\", \"voicelineId\": 13044, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解行秋·其四\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_friendship_04\", \"description\": \"你说你有个好点子？用我们之前做的事情当原型，写一本探案集加武侠题材的小说，《万文集事件簿》？嗯，啊哈哈哈…是个好点子，但是不采纳。嗯，不会采纳的。\", \"voicelineId\": 13045, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解行秋·其五\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_friendship_05\", \"description\": \"「洋洋万言，织诗成锦。」唉，我也想有这样的评价啊。这件事我只和你一个人说。其实，我也在写小说。现、现在当然不能给你看，以后…以后你会在书店里看到的。\", \"voicelineId\": 13046, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"行秋的爱好…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_pref_hobby\", \"description\": \"我的爱好自然是看书。什么书都会看。嗯？你一脸坏笑看着我干什么。唔，那事我们两个知道就行了，还是不适合明面上讲。说出来就没意思了。\", \"voicelineId\": 13047, \"voicelineType\": \"6001\"}, {\"title\": \"行秋的烦恼…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_dialog_annoyed\", \"description\": \"烦恼啊，嗯…未来有朝一日兄长继承了家业，我会怎么样呢？这样无忧无虑的生活恐怕…啊，我不是在说身份之类的，我不在乎那些。我是觉得大哥太呆了，没我帮忙不太行啊。\", \"voicelineId\": 13048, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_pref_foodLike\", \"description\": \"我比较喜欢吃糕点和月菜海鲜。主要是因为，我们家一直就吃得很清淡吧。\", \"voicelineId\": 13049, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_pref_foodDislike\", \"description\": \"我很讨厌胡萝卜，小时候家母经常捣碎胡萝卜做成…还是不要让我讲下去了。即使是在回忆里，那种味道也…\", \"voicelineId\": 13050, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_spice_pref_01\", \"description\": \"此等美食，吃过一次就再难忘怀了啊。\", \"voicelineId\": 13082, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_spice_normal_01\", \"description\": \"既然你有这份手艺，不如我们开个路边餐馆，如何？\", \"voicelineId\": 13083, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_spice_dislike_01\", \"description\": \"你吃你吃，不必客气。\", \"voicelineId\": 13084, \"voicelineType\": \"6009\"}, {\"title\": \"生日·祝福\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_pref_birthday_01\", \"description\": \"咳，咳咳。恭祝你福寿与天齐，庆贺你生辰快乐。\", \"voicelineId\": 13051, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"生日·习俗\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_pref_birthday_02\", \"description\": \"据记载，天成石桥是上古战争时候，岩之神摩拉克斯投出的石枪倒塌后形成的。要是生日当天在桥上走一趟，往两边海里投点摩拉，就能保佑一年安康…生日一年只有一次，想去的话就快点去吧…没骗你，是真的。真的，快去吧。\", \"voicelineId\": 13052, \"voicelineType\": \"7002\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_starUp_01\", \"description\": \"如果没有能力，那我心中的那个字，可能也就停在纸面上了吧。\", \"voicelineId\": 13053, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_starUp_02\", \"description\": \"如果心中没有善恶的标尺，努力就会错了方向。舍本逐末，变成追逐暴力的俗人。\", \"voicelineId\": 13054, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_starUp_03\", \"description\": \"我所追求的那个字，在璃月这方土地上并非处处通行。不过行道至此，我对这一点早就有了足够的认识。\", \"voicelineId\": 13055, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_xingqiu/vo_xingqiu_starUp_04\", \"description\": \"多亏了你的陪伴。我对自己也很满意了——无论是武学，还是对那个字的理解。唉，算啦。我也不用对「侠」字讳莫如深了。我的「侠」，父亲和兄长应该也不会质疑了。只不过嘛，低调行事这点还是得保留的。\", \"voicelineId\": 13056, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_battle_skill1_01\", \"description\": \"雨线难画。\", \"voicelineId\": 13057, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_battle_skill1_02\", \"description\": \"裁——！\", \"voicelineId\": 13058, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_battle_skill1_03\", \"description\": \"断！\", \"voicelineId\": 13059, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_battle_skill3_01\", \"description\": \"古华深秘。\", \"voicelineId\": 13060, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_battle_skill3_02\", \"description\": \"织诗成锦。\", \"voicelineId\": 13061, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_battle_skill3_03\", \"description\": \"裁雨留虹。\", \"voicelineId\": 13062, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_explore_sprint_start_01\", \"description\": \"形随神至。\", \"voicelineId\": 13063, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺开始·其二\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_explore_sprint_start_02\", \"description\": \"该行动了。\", \"voicelineId\": 13064, \"voicelineType\": \"700002\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_chest_open_01\", \"description\": \"甚好甚好。\", \"voicelineId\": 13065, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_chest_open_02\", \"description\": \"寻得珍宝，真是充满侠意的经历。\", \"voicelineId\": 13066, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_chest_open_03\", \"description\": \"倘若还有几卷失传的古书，就完满了。\", \"voicelineId\": 13067, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_life_less30_01\", \"description\": \"计划有变…\", \"voicelineId\": 13068, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_life_less30_02\", \"description\": \"接下来就不再是「点到为止」了。\", \"voicelineId\": 13069, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_life_less30_03\", \"description\": \"「请从绝处，读我侠义。」\", \"voicelineId\": 13070, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_life_less30_teammate_01\", \"description\": \"过来这边，我有一计。\", \"voicelineId\": 13071, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_life_less30_teammate_02\", \"description\": \"小心行事为好。\", \"voicelineId\": 13072, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_life_die_01\", \"description\": \"承蒙…赐教…\", \"voicelineId\": 13073, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_life_die_02\", \"description\": \"灯华易散…我是知道的。\", \"voicelineId\": 13074, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_life_die_03\", \"description\": \"失手了…\", \"voicelineId\": 13075, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_battle_hit_L_02\", \"description\": \"不妨事。\", \"voicelineId\": 13076, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_battle_hit_H_01\", \"description\": \"大意了。\", \"voicelineId\": 13077, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_xingqiu/vo_xingqiu_battle_hit_H_02\", \"description\": \"不好…\", \"voicelineId\": 13078, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_xingqiu_teamJoin_01\", \"description\": \"厚积而薄发。\", \"voicelineId\": 13079, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_xingqiu_teamJoin_02\", \"description\": \"不惭世上英。\", \"voicelineId\": 13080, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_xingqiu_teamJoin_03\", \"description\": \"扶善惩恶，当仁不让。\", \"voicelineId\": 13081, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000026, 'Xiao', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_draw_appear\", \"description\": \"如遇失道旷野之难，路遭贼人之难，水火刀兵之难，鬼神药毒之难，恶兽毒虫之难，冤家恶人之难，便呼我名。\\n「三眼五显仙人」——「魈」，听召前来守护。\", \"voicelineId\": 16100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·闲散\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_explore_idle_01\", \"description\": \"我居然沦落到如此闲散的地步，可笑。\", \"voicelineId\": 16101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·荒魂\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_explore_idle_02\", \"description\": \"荒野上的孤魂，休想伤我分毫。\", \"voicelineId\": 16102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·侵蚀\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_explore_idle_03\", \"description\": \"…呃啊…哼，想起了一些不愉快的事。\", \"voicelineId\": 16103, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_weather_heavyRain_01\", \"description\": \"魔物不会因为下雨就休息。我们走。\", \"voicelineId\": 16104, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_weather_afterRain_01\", \"description\": \"天晴了？哼，我不关心天气。\", \"voicelineId\": 16105, \"voicelineType\": \"1202\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_weather_thunder_01\", \"description\": \"不少凡人害怕打雷。无法理解，这分明很寻常。\", \"voicelineId\": 16106, \"voicelineType\": \"1203\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_weather_snowy_01\", \"description\": \"雪积起来之后，就可以挖着吃了。\", \"voicelineId\": 16107, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_greetingMorning\", \"description\": \"时候不早了。出发吧。\", \"voicelineId\": 16108, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_greetingNoon\", \"description\": \"午餐…回望舒客栈吧。\", \"voicelineId\": 16109, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_greetingNight\", \"description\": \"夜晚，不祥之物最易骚动。你最好别出门。\", \"voicelineId\": 16110, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_greetingNight2\", \"description\": \"你去吧，我会在这里等你。\", \"voicelineId\": 16111, \"voicelineType\": \"1004\"}, {\"title\": \"关于魈自己·非人\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_idle_01\", \"description\": \"我并非人类，不太能够理解人类的感情。\", \"voicelineId\": 16112, \"voicelineType\": \"2001\"}, {\"title\": \"关于魈自己·璃月\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_idle_02\", \"description\": \"近来璃月变化得过于迅速了…呵，罢了，我也没打算适应。\", \"voicelineId\": 16113, \"voicelineType\": \"2006\"}, {\"title\": \"关于我们·警示\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_close1\", \"description\": \"如果有一天，连你也陷入了黑暗。就由我来——\", \"voicelineId\": 16114, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·信任\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_close2\", \"description\": \"别被污染，我不会留情的。\\n…我是说，既然是「你」，「你」应该能够保持坚定。\", \"voicelineId\": 16115, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·犯困\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_close3\", \"description\": \"…谁！？…你觉得我是站着睡着了？哼，不敬仙师！\", \"voicelineId\": 16116, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·海灯节\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_close4\", \"description\": \"海灯节？哼，原来又到了凡人用发光垃圾塞满璃月港的时候了，唉，为何如此幼稚。\\n不过你若无聊，我便陪你去。\", \"voicelineId\": 16117, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·欲望\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_pendant_01\", \"description\": \"「神之眼」、欲望？呵…不要用凡人的标准来揣测仙人，我没有欲望。\", \"voicelineId\": 16118, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·理由\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_pendant_02\", \"description\": \"并不是有意隐瞒。我的欲望，不应对外人讲。\\n人间不是有着愿望说出口就会失效的规矩…呃，不是一回事？\", \"voicelineId\": 16119, \"voicelineType\": \"3004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_share\", \"description\": \"杀戮是我的强项。如果你下不去手，就叫我来。\", \"voicelineId\": 16120, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_pref_gift\", \"description\": \"荻花洲，曾经一度荒芜。\\n虽然，是过去好多年…不，好几百年的事了。\", \"voicelineId\": 16121, \"voicelineType\": \"3003\"}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_teammate_zhongli_01\", \"description\": \"嗯…打听一下。请问钟离大人平日里都在…呃，遛鸟？赏花？品鉴古玩？\\n…钟离大人做这些，是有什么深意…\", \"voicelineId\": 16122, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_teammate_beidou_01\", \"description\": \"北斗吗？我与她没有什么交情。不过，冥海巨兽确有其事。能够将「海山」击败，作为人类，她的实力值得肯定。\", \"voicelineId\": 16123, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于白术…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_teammate_baizhu_01\", \"description\": \"你想…托付白术研制缓解我痛苦的药物？呵…你的好意我心领了。凡人的药物，对仙人是无法起效的。\", \"voicelineId\": 16124, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_teammate_hutao_01\", \"description\": \"胡桃？那孩子，活泼到令人头疼。所幸她还算风趣，不必担心会成长为无趣的人类。\", \"voicelineId\": 16125, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温迪…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_teammate_venti_01\", \"description\": \"温迪…？原来如此，名字叫作温迪啊。他演奏的曲调…不，没什么。\", \"voicelineId\": 16126, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_teammate_ganyu_01\", \"description\": \"甘雨既非仙兽，又非凡人，游走于仙人两界，靠着职责支撑自我，困惑是免不了的。...你说，我？呵，要让只懂杀戮与生存之道的夜叉，去开导瑞兽？天方夜谭。\", \"voicelineId\": 16127, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于申鹤…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_teammate_shenhe_01\", \"description\": \"申鹤似乎对你颇为信赖。…也是。毕竟，世间难得几人能有你这般的善心与热忱。\", \"voicelineId\": 16128, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1101505], \"unlockText\": \"完成「风起鹤归」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夜兰…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_teammate_yelan_01\", \"description\": \"我听说她曾调查千岩军在层岩巨渊的相关痕迹。孤身追查秘密，想来也是有点本事的人。\", \"voicelineId\": 16129, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解魈·其一\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_friendship_01\", \"description\": \"我会为你护法。\\n但是…别靠近我，别妨碍我。否则，你会后悔的。\", \"voicelineId\": 16130, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解魈·其二\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_friendship_02\", \"description\": \"在这千年以来，我猎杀过数以万计的怨魂。不想惹上麻烦，就离我远点。把我当作「工具」就好。\", \"voicelineId\": 16131, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解魈·其三\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_friendship_03\", \"description\": \"「它们」的声音…常常在我的耳边出现。咆哮、号哭…嘶喊着杀戮…\\n这是我自己的选择和自己的报应。与你无关。\", \"voicelineId\": 16132, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解魈·其四\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_friendship_04\", \"description\": \"摩拉克斯？关于这个名字，你究竟知道多少？\\n他是赐予我「魈」之名之人，将我从漫长的痛苦中解放。\\n胆敢对他不敬的话。即使是你，我也不会原谅。\", \"voicelineId\": 16133, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解魈·其五\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_friendship_05\", \"description\": \"已经迟了。我们之间的关联已经太多了。即使你想要放弃，也来不及了吧。嗯？没有这样想过？\\n…「靖妖傩舞」，我的战斗是不会停下的。\\n但是，关于你的事情，我想了解更多。\", \"voicelineId\": 16134, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"魈的爱好…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_pref_hobby\", \"description\": \"你还真是胆量不小，有勇气询问我的爱好。\\n那便来战吧。以你的身躯，扛得住我几招呢？\", \"voicelineId\": 16135, \"voicelineType\": \"6001\"}, {\"title\": \"魈的烦恼…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_dialog_annoyed\", \"description\": \"烦恼？呵…这个问题对仙人毫无意义，没有什么烦恼能够存在千年。\", \"voicelineId\": 16136, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物·杏仁豆腐\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_pref_foodLike_01\", \"description\": \"我对人间的食物并无兴致。烹饪繁琐，等待漫长。唯独杏仁豆腐，勉强可以入口。\", \"voicelineId\": 16137, \"voicelineType\": \"6003\"}, {\"title\": \"喜欢的食物·回忆\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_pref_foodLike_02\", \"description\": \"杏仁豆腐的味道，和「美梦」非常相似呢。\", \"voicelineId\": 16138, \"voicelineType\": \"6004\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_pref_foodDislike\", \"description\": \"要我亲手在薄饼中包入肉片？啊…然后…一起吃下去？呵…麻烦。如今的人间，真是越来越缺乏常识了。\", \"voicelineId\": 16139, \"voicelineType\": \"6005\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_spice_pref_01\", \"description\": \"嗯，不错…为什么要盯着我看。\", \"voicelineId\": 16169, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_spice_normal_01\", \"description\": \"不用麻烦。\", \"voicelineId\": 16170, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_spice_dislike_01\", \"description\": \"下次做点别的吧。\", \"voicelineId\": 16171, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_pref_birthday\", \"description\": \"诞生的时日…人类的这些纪念，真是冗余。嗯…等着。我给你折一只梧桐树叶蝴蝶。\\n好了，拿去吧。这是仙法，可以辟邪。\", \"voicelineId\": 16140, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_starUp_01\", \"description\": \"只是这种程度而已。没什么值得大惊小怪的。\", \"voicelineId\": 16141, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_starUp_02\", \"description\": \"新的力量？这力量，也只会被用于斩杀。\", \"voicelineId\": 16142, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_starUp_03\", \"description\": \"力量的尽头，是自我毁灭。回答我，为何如此执着呢？\", \"voicelineId\": 16143, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_xiao/vo_xiao_starUp_04\", \"description\": \"我的枪缨，早就屠戮了无尽的怨魂。连我本人，不免也被黑暗吞噬。——你却敢于驱使这样的我，将我当作…「同伴」。\\n…你是想要救赎我吗？…你，真是难以理解的生物。\", \"voicelineId\": 16144, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_battle_skill1_01\", \"description\": \"哼。\", \"voicelineId\": 16145, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_battle_skill1_02\", \"description\": \"无聊。\", \"voicelineId\": 16146, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_battle_skill1_03\", \"description\": \"无用。\", \"voicelineId\": 16147, \"voicelineType\": \"100003\"}, {\"title\": \"下落攻击·其一\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_battle_skill2_01\", \"description\": \"这里！\", \"voicelineId\": 16148, \"voicelineType\": \"110001\"}, {\"title\": \"下落攻击·其二\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_battle_skill2_02\", \"description\": \"无能。\", \"voicelineId\": 16149, \"voicelineType\": \"110002\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_battle_skill3_01\", \"description\": \"就此消失。\", \"voicelineId\": 16150, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_battle_skill3_02\", \"description\": \"靖妖傩舞。\", \"voicelineId\": 16151, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_battle_skill3_03\", \"description\": \"悲鸣吧。\", \"voicelineId\": 16152, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_chest_open_01\", \"description\": \"对你有用便好。\", \"voicelineId\": 16153, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_chest_open_02\", \"description\": \"这些物品的用途…算了，我不关心。\", \"voicelineId\": 16154, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_chest_open_03\", \"description\": \"嗯…品质尚可。\", \"voicelineId\": 16155, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_life_less30_01\", \"description\": \"住口。\", \"voicelineId\": 16156, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_life_less30_03\", \"description\": \"愚蠢。\", \"voicelineId\": 16157, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_life_less30_04\", \"description\": \"很好。\", \"voicelineId\": 16158, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_life_less30_teammate_01\", \"description\": \"…弱小。\", \"voicelineId\": 16159, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_life_less30_teammate_02\", \"description\": \"想活命，就退后。\", \"voicelineId\": 16160, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_life_die_01\", \"description\": \"这是…报应吗。\", \"voicelineId\": 16161, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_life_die_02\", \"description\": \"这一天…到来了呀。\", \"voicelineId\": 16162, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_life_die_03\", \"description\": \"不可能…\", \"voicelineId\": 16163, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_battle_hit_L_02\", \"description\": \"就凭你？\", \"voicelineId\": 16164, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_xiao/vo_xiao_battle_hit_H_02\", \"description\": \"别妨碍我。\", \"voicelineId\": 16165, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_xiao_teamJoin_01\", \"description\": \"听召而来。\", \"voicelineId\": 16166, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_xiao_teamJoin_02\", \"description\": \"诸邪退散。\", \"voicelineId\": 16167, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_xiao_teamJoin_03\", \"description\": \"降魔乃分内之事。\", \"voicelineId\": 16168, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000027, 'Ningguang', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_draw_appear\", \"description\": \"我是七星之「天权」，凝光。要做个交易吗？你来做我的贴身侍卫，而我，会教导你在璃月出人头地的技巧。\", \"voicelineId\": 15100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·古玩\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_explore_idle_01\", \"description\": \"就算古玩价值连城，给人的快乐也只有刚拥有的一瞬。\", \"voicelineId\": 15101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·商战\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_explore_idle_02\", \"description\": \"在商战中，完美的猎手不会留下任何痕迹。\", \"voicelineId\": 15102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·投资\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_explore_idle_03\", \"description\": \"找笔新的投资吧。无论如何，摩拉都不会嫌多。\", \"voicelineId\": 15103, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_weather_heavyRain_01\", \"description\": \"哦？下雨了啊。替我打伞吧。\", \"voicelineId\": 15104, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_weather_snowy_01\", \"description\": \"不过是寻常雪景。我带你见见，真正的「碎雪」。\", \"voicelineId\": 15105, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_weather_sunny_01\", \"description\": \"风平浪静？呵，不要相信你的眼睛，眼睛会说谎。\", \"voicelineId\": 15106, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_weather_gale_01\", \"description\": \"这样的大风天，会成为捕鱼人的灾难。也会成为…呵，没什么。\", \"voicelineId\": 15107, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_greetingMorning\", \"description\": \"早，按事情的轻重缓急向我禀报吧。\", \"voicelineId\": 15108, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_greetingNoon\", \"description\": \"「琉璃亭」和「新月轩」，你更常去哪一家？\", \"voicelineId\": 15109, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_greetingNight\", \"description\": \"茶馆已经客满了？那就来「群玉阁」坐坐吧。只要…你付得起价钱。\", \"voicelineId\": 15110, \"voicelineType\": \"1003\", \"unlockConditions\": [{\"paramList\": [101609], \"unlockText\": \"完成「辞行久远之躯」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_greetingNight2\", \"description\": \"嗯，去休息吧。要是发生了重要的事情，我会派人通知你的。\", \"voicelineId\": 15111, \"voicelineType\": \"1004\"}, {\"title\": \"关于凝光自己·观点\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_idle\", \"description\": \"无论是价格谈判还是商战博弈，声势和筹码都是次要的。想要取得胜利，就需要先去了解对手的底牌。\", \"voicelineId\": 15112, \"voicelineType\": \"2001\"}, {\"title\": \"关于凝光自己·印象\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_idle_02\", \"description\": \"觉得我给你的印象变了？呵…那时我需要借助你的力量，当然要让你觉得我亲切热情。但现在我已将你当作重要的「契约」伙伴，伙伴之间，就不用这些虚情假意了。\", \"voicelineId\": 15113, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·传言\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_close1\", \"description\": \"关于我的传言，最近听了不少吧。我究竟是怎样的人？用你自己的双眼分辨吧…当然，你的看法，也会成为传言的一部分。\", \"voicelineId\": 15114, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·观察\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_close2\", \"description\": \"跟了我那么久，你学会「观察」了吗。那么，试着来「观察」我吧，直到成为我的心腹为止。\", \"voicelineId\": 15115, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·群玉阁\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_close3\", \"description\": \"上前来，和我并肩站着。看到「群玉阁」了吗。它起初只有房间大小，如今却能遮蔽璃月上空。等到它的规模有朝一日笼罩七国，那时候，也这样和我并肩而立吧。\", \"voicelineId\": 15116, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [101609], \"unlockText\": \"完成「辞行久远之躯」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_pendant\", \"description\": \"能用摩拉解决的事情，就无需使用「神之眼」。至于用摩拉也解决不了的事情…至今我只遇到过一件。\", \"voicelineId\": 15117, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·庄家\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_share\", \"description\": \"赌徒永远会把希望寄托在下一颗骰子上…但最后赚钱的，当然是从来不碰骰子的庄家。\", \"voicelineId\": 15118, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·目标\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_share_02\", \"description\": \"帝君的离去，无论对璃月还是七星来说，都是不小的考验。我也很久没有像最近这样辗转反侧了。\\n不过，我不会放弃我的目标。总有一日，我会让群玉阁投下的影子笼罩七国——\", \"voicelineId\": 15119, \"voicelineType\": \"3004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_pref_gift\", \"description\": \"璃月古代辞赋中不乏对于「琉璃百合」的溢美，但它现今却近乎灭绝，只在「玉京台」还有保留。名声在外却又不可多得，因此更加价格不菲。\", \"voicelineId\": 15120, \"voicelineType\": \"3003\"}, {\"title\": \"关于北斗·罚金\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_beidou_01\", \"description\": \"那位…船长。明明也受到不少人推崇，却总是带头漠视规则。她缴纳的罚金，都够买一艘崭新的远洋船了吧。\", \"voicelineId\": 15121, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗·态度\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_beidou_02\", \"description\": \"或许你没有遇到过这种糟糕的交流体验。将好话坏话说尽了，对方却依然自行其是。罢了，尽可能不要让我见到那位北斗船长。\", \"voicelineId\": 15122, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_zhongli_01\", \"description\": \"钟离…「往生堂」口中的这位先生，精通许多旁人不知的事物。但在掌握他的弱点之前，再优秀的棋子，也还不能为我所用。\", \"voicelineId\": 15123, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_xingqiu_01\", \"description\": \"飞云商会的二公子，那种性格的人看不惯我，是很自然的，而我也不会去为难他。「道不同不相为谋」，说的就是这个道理。\", \"voicelineId\": 15124, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_xiangling_01\", \"description\": \"「万民堂」的小丫头…总是把对我的猜疑写在脸上。呵，要是让她知道了，这些年来我对「万民堂」的资助…她会露出怎样的表情来呢？\", \"voicelineId\": 15125, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_ganyu_01\", \"description\": \"即使是甘雨，也不可过度依赖。璃月俗语说「百密终有一疏」。重要事情当前，只有自己亲手处理，亲眼查证，才可放心。\", \"voicelineId\": 15126, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于瑶瑶…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_yaoyao_01\", \"description\": \"是在谈论甘雨正帮忙照看着的小姑娘么。呵，不用紧张，此事我并无声张的打算。就当那个船长，总能做一两件聪明事吧。对了，这瑶瑶，近来光顾着吃海产了，你得想办法劝劝甘雨，叫她为瑶瑶多补充些瓜果蔬菜才对。\", \"voicelineId\": 15127, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_keqing_01\", \"description\": \"「玉衡星」…她最近的变化可真不小。璃月究竟更需要曾经的她，还是更需要现在的她呢？可能要多花一些时间，才能判断吧。\", \"voicelineId\": 15128, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_qin_01\", \"description\": \"蒙德城的代理团长，想必是一位严谨而又细腻的女性吧。且不说她恰如其分的用词，连每张信纸的边缘都折叠得一丝不苟。越是这些容易被人忽视的细节，越能透过它窥见一个人真正的品质。\", \"voicelineId\": 15129, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于烟绯…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_yanfei_01\", \"description\": \"烟绯？呵，某种意义上，她是个贴心的对手呢。若不是她「灵巧」地解释律法，为咨询者们提供各种「奇妙」的建议，要让我独自找到律法的缺口，逐步完善法典，怕是要多花数月的时间。\", \"voicelineId\": 15130, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于申鹤…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_shenhe_01\", \"description\": \"申鹤小姐近来可好？有劳你多多关照她了。你们帮忙重建群玉阁的事，我一直记在心里，也很是感激。啊，客套话就不多说了，我备了好茶，闲时多来坐坐吧。\", \"voicelineId\": 15131, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1101505], \"unlockText\": \"完成「风起鹤归」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于云堇…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_yunjin_01\", \"description\": \"云堇啊…怎么样，你听得惯她的戏吗？起初可能是有些难懂，试着耐下性子多品味一下吧。我投资她的戏班不为别的，只是觉得，这般典雅的艺术，值得被一直传承下去。\", \"voicelineId\": 15132, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夜兰…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_yelan_01\", \"description\": \"她是个很有意思的人，对我而言，也是绝对可信之人。八面玲珑，才能无可挑剔。呵呵，既然同为聪明人，希望你们能相处愉快。\", \"voicelineId\": 15133, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于闲云…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_teammate_xianyun_01\", \"description\": \"再过些时日，我打算约闲云女士去茶室小坐。我恰巧收集了一些机巧玩物，想听听她的高见，也想趁此机会，听她讲讲仙人在璃月港生活的趣事。至于为我递这份邀请函的人选…你可有意？\", \"voicelineId\": 15174, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11035], \"unlockText\": \"完成「千里月明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解凝光·其一\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_friendship_01\", \"description\": \"既然是你，就不用恪守那些繁文缛节了，可以随意一些。不过，希望你能珍惜我的时间，言简意赅地进行说明。\", \"voicelineId\": 15134, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解凝光·其二\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_friendship_02\", \"description\": \"我向来以为，孩子们最为天真纯粹，他们提供的情报也最有价值。那么，你又如何呢？你向我提供的东西，会是些什么呢。\", \"voicelineId\": 15135, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解凝光·其三\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_friendship_03\", \"description\": \"最近我在思考一个问题。如果能把你留在璃月，假以时日…或许能撬动这座城市的…呵，只是设想而已。这笔投资值不值，我还得再考虑考虑。\", \"voicelineId\": 15136, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解凝光·其四\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_friendship_04\", \"description\": \"你可以学我的做法，靠摩拉来为自己获取一些便利。但你要记住，摩拉维持的关系只能依仗一时。呵，这也是我从不用摩拉来试探你的理由。\", \"voicelineId\": 15137, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解凝光·其五\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_friendship_05\", \"description\": \"真是一笔不错的投资。虽然没有收益多少摩拉，但与你度过的这些时光，已是很不错的回报。呵，看来我又赢了——我，赌对了人。\", \"voicelineId\": 15138, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"凝光的爱好…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_pref_hobby\", \"description\": \"想来试试棋戏「璃月千年」么？正好也让我看看，你作为一名棋手的素质，究竟如何呢。\", \"voicelineId\": 15139, \"voicelineType\": \"6001\"}, {\"title\": \"凝光的烦恼…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_dialog_annoyed\", \"description\": \"烦恼…哦？「璃月七星」的烦恼告诉了你…你的肩膀，能够承受得住吗？而且，如果你一不小心说出去了的话…\", \"voicelineId\": 15140, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_pref_foodLike\", \"description\": \"用老鸡和猪骨小火久煮熬制高汤，淋在只取菜心的鲜嫩白菜上。我对饮食追求不深。平日里吃点这样的东西，也就够了。\", \"voicelineId\": 15141, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_pref_foodDislike\", \"description\": \"我见过有人每次宴会必点「黄金蟹」这种看上去显得大富大贵的食物，但我对此始终不敢恭维。如果你想用这样的料理宴请我，还不如直接给我摩拉。\", \"voicelineId\": 15142, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_spice_pref_01\", \"description\": \"不错。你总能出乎我的意料。\", \"voicelineId\": 15171, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_spice_normal_01\", \"description\": \"有时，没有把握关键要素，就等于徒劳无功…能明白么？\", \"voicelineId\": 15172, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_spice_dislike_01\", \"description\": \"心意我领了。\", \"voicelineId\": 15173, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_pref_birthday_b\", \"description\": \"{M#这是选用上等的霓裳花织出的锦缎。这份是留给你的，这一份…等你找到自己的妹妹之后，拿去做件她喜欢的衣服吧。祝你们，生日快乐。},{F#这是选用上等的霓裳花织出的锦缎。拿去做件自己喜欢的衣服，过个开心点的生日吧。}\", \"voicelineId\": 15143, \"voicelineType\": \"7001\", \"voicefile_male\": \"VO_friendship/VO_ningguang/vo_ningguang_pref_birthday_a\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true, \"hasGenderedVoicefile\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_starUp_01\", \"description\": \"「武斗」缺乏风度，只能作为下策中的下策。\", \"voicelineId\": 15144, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_starUp_02\", \"description\": \"将时间和摩拉作为筹码，等价交换到「力量」吗…有趣。我认可它的价值。\", \"voicelineId\": 15145, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_starUp_03\", \"description\": \"你是怀着怎样的心情坚持的呢？嘘…不要说出来。让我多花一点时间来看透你。\", \"voicelineId\": 15146, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_ningguang/vo_ningguang_starUp_04\", \"description\": \"我并不轻易肯定别人，但现在看来，我这赞扬是留不住了。呵…你做得很出色。要是我的手下能多一点像你这样的人…不，或许，有你一个就够了。\", \"voicelineId\": 15147, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_battle_skill1_01\", \"description\": \"雕虫小技。\", \"voicelineId\": 15148, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_battle_skill1_02\", \"description\": \"别白费功夫。\", \"voicelineId\": 15149, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_battle_skill1_03\", \"description\": \"哼，劝你放弃。\", \"voicelineId\": 15150, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_battle_skill3_01\", \"description\": \"你的性命，我收下了。\", \"voicelineId\": 15151, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_battle_skill3_02\", \"description\": \"向我臣服吧。\", \"voicelineId\": 15152, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_battle_skill3_03\", \"description\": \"永别了。\", \"voicelineId\": 15153, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_chest_open_01\", \"description\": \"好一双慧眼。\", \"voicelineId\": 15154, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_chest_open_02\", \"description\": \"颗粒归仓。\", \"voicelineId\": 15155, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_chest_open_03\", \"description\": \"财富，多多益善。\", \"voicelineId\": 15156, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_life_less30_01\", \"description\": \"竟然敢伤我。\", \"voicelineId\": 15157, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_life_less30_02\", \"description\": \"我记下了。\", \"voicelineId\": 15158, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_life_less30_03\", \"description\": \"哼。\", \"voicelineId\": 15159, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_life_less30_teammate_01\", \"description\": \"如今的局面，你没有几成胜算。\", \"voicelineId\": 15160, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_life_less30_teammate_02\", \"description\": \"既然如此，就帮你一把。\", \"voicelineId\": 15161, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_life_die_01\", \"description\": \"这世上之人，皆为棋子…\", \"voicelineId\": 15162, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_life_die_02\", \"description\": \"胜负已分…真是无可奈何。\", \"voicelineId\": 15163, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_life_die_03\", \"description\": \"这就是，「天权」的终焉？…\", \"voicelineId\": 15164, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_battle_hit_L_02\", \"description\": \"无礼。\", \"voicelineId\": 15165, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_battle_hit_H_01\", \"description\": \"等着吧。\", \"voicelineId\": 15166, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_ningguang/vo_ningguang_battle_hit_H_02\", \"description\": \"血债血还。\", \"voicelineId\": 15167, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_ningguang_teamJoin_01\", \"description\": \"知道了。\", \"voicelineId\": 15168, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_ningguang_teamJoin_02\", \"description\": \"抓紧时间吧。\", \"voicelineId\": 15169, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_ningguang_teamJoin_03\", \"description\": \"不要让我失望。\", \"voicelineId\": 15170, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000029, 'Klee', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_draw_appear\", \"description\": \"西风骑士团，「火花骑士」，可莉，前来报到！…呃——后面该说什么词来着？可莉背不下来啦…\", \"voicelineId\": 18009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·收获\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_explore_idle_01\", \"description\": \"可莉今天又勇敢地抓到了花纹奇怪的蜥蜴！从没见过这种图案，你要看看吗？\", \"voicelineId\": 18010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·冒险\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_explore_idle_02\", \"description\": \"要和可莉一起去炸鱼吗？虽然被抓住就是一整天的禁闭，但鱼很好吃，所以值得！\", \"voicelineId\": 18011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·守则\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_explore_idle_03\", \"description\": \"「城里放炮禁闭室报到」、「炸弹伤人琴找上门」、「放火烧山可莉完蛋」——这就是可莉在骑士团的生存守则。\", \"voicelineId\": 18012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_weather_heavyRain_01\", \"description\": \"哼哼哼，这次的炸弹可是防水的。\", \"voicelineId\": 18013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_weather_thunder_01\", \"description\": \"啊！什么东西爆炸了？！…哦，是打雷啊。\", \"voicelineId\": 18014, \"voicelineType\": \"1202\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_weather_gale_01\", \"description\": \"风神保佑，把可莉的炸弹往合适的地方吹吧。\", \"voicelineId\": 18015, \"voicelineType\": \"1203\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_greetingMorning\", \"description\": \"早安！带可莉出去玩吧！我们一起来冒险！\", \"voicelineId\": 18016, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_greetingNoon\", \"description\": \"午饭时间到了！啊…吃什么呢？我来看看《提瓦特游览指南》…\", \"voicelineId\": 18017, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_greetingNight\", \"description\": \"晚上好！拜托你也帮我跟霍夫曼先生说说吧，可莉不是小孩子了，可莉晚上也可以出去玩——带我出去玩——\", \"voicelineId\": 18018, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_greetingNight2\", \"description\": \"虽然出来玩的时候说不想回家，但天黑以后的旷野，不认识路…拜、拜托你回去的时候，把我也送回家好不好…\", \"voicelineId\": 18019, \"voicelineType\": \"1004\"}, {\"title\": \"关于可莉自己·肇事\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_idle\", \"description\": \"呜…这次居然炸歪了大风车的叶片…真对不起！\", \"voicelineId\": 18020, \"voicelineType\": \"2001\"}, {\"title\": \"关于可莉自己·赔偿\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_idle2\", \"description\": \"我，我还挺会做手工的，请让我帮你们重新做一个…什么？禁止雇佣童工？呜…\", \"voicelineId\": 18021, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·骑士\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_close\", \"description\": \"呼呼…荣誉骑士，可莉作为「火花骑士」，可以说是你在西风骑士团的前辈喔？所以！所以…这次我闯的祸，能不能帮我隐瞒一下…\", \"voicelineId\": 18022, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·玩伴\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_close1_b\", \"description\": \"不行！才九点，可莉今晚一定要撑到看完马戏团的午夜专场！你是可莉的玩伴吧！那就别想现在就把我送回家，略略略略…\", \"voicelineId\": 18023, \"voicelineType\": \"2004\", \"voicefile_male\": \"VO_friendship/VO_klee/vo_klee_dialog_close1_a\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true, \"hasGenderedVoicefile\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_pendant\", \"description\": \"这个小小的玻璃球，就代表了巴巴托斯大人对可莉的肯定吗…唔…究竟是认可了我的哪一部分呢？是自由吗？那以后要不要更自由地出去炸鱼，来回应巴巴托斯大人的期待呢…？\", \"voicelineId\": 18024, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_share\", \"description\": \"可莉知道，骑士团的墙是不能炸的。虽然打通了能从禁闭室出去很方便，但凯亚哥哥说，这样做了以后，琴团长恐怕会让我再也见不到第二天的太阳…\", \"voicelineId\": 18025, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_pref_gift\", \"description\": \"每一只蜥蜴的花纹都是不同的，有些蜥蜴的尾巴干燥以后磨成粉，可以当做炸药的材料哦。这是阿贝多哥哥告诉我的事。\", \"voicelineId\": 18026, \"voicelineType\": \"3003\"}, {\"title\": \"关于雷泽…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_razor_01\", \"description\": \"我们是朋友！雷泽努力对抗危机、保护可莉的样子，让人安心！…唔…虽然基本上都是我把危机带到他身边的…\", \"voicelineId\": 18027, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于父母…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_parent_01\", \"description\": \"爸爸和妈妈都是全大陆有名的旅行家！妈妈写的《提瓦特游览指南》，有好多餐馆和旅店都很在意它的权威评价呢。\", \"voicelineId\": 18028, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_kaeya_01\", \"description\": \"凯亚哥哥是好人！《骑士团生存守则》就是凯亚哥哥帮可莉写的。可莉闯祸的时候，他也经常帮忙遮掩呢。\", \"voicelineId\": 18029, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_ambor_01\", \"description\": \"安柏姐姐是好人！兔兔伯爵摸起来也是毛茸茸的，而且还会爆炸，太棒了！\", \"voicelineId\": 18030, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_qin_01\", \"description\": \"琴团长是好人！虽然…有点可怕…\", \"voicelineId\": 18031, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_diluc_01\", \"description\": \"奇怪的大人，一直都是不太开心的样子。唔…为什么不喜欢笑呢？\", \"voicelineId\": 18032, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_lisa_01\", \"description\": \"丽莎阿…丽莎姐姐是好人！每次可莉靠近她的工坊，她就会给可莉好吃的茶点…欸？说起来我想进她的工坊，好像一开始是想做新的炸药来着…？\", \"voicelineId\": 18033, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于班尼特…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_bennett_01\", \"description\": \"班尼特哥哥是好人！和他一起冒险，可莉总能有更多收获！…虽然班尼特哥哥自己总是什么宝物都找不到，嗯…这是为什么呢？\", \"voicelineId\": 18034, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪奥娜…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_diona_01\", \"description\": \"迪奥娜姐姐是好人！「靠一己之力摧毁蒙德酒业」的想法好有趣，可莉也要用炸弹来帮忙！——呃，虽然不太懂什么叫做「蒙德酒业」，是怪物吗？\", \"voicelineId\": 18035, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_albedo_01\", \"description\": \"阿贝多哥哥跟可莉有个秘密的约定！要是可莉看到工坊门前挂着「实验进行中」的牌子，就要晚点再去找他。阿贝多哥哥不工作的时候，会很耐心地陪着可莉，所以可莉也会很耐心地等着的！\", \"voicelineId\": 18036, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莫娜…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_mona_01\", \"description\": \"莫娜姐姐是好人！她每次找阿贝多哥哥和可莉玩的时候，都会说好多听不明白，但是很有趣的东西！可莉喜欢她来玩！\", \"voicelineId\": 18037, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于砂糖…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_teammate_sucrose_01\", \"description\": \"砂糖姐姐是好人！她问我，想不想要一个会跑会跳的蹦蹦！嘿嘿嘿，当然想要了，我还想要好几百个，让蒙德的街道上，台阶上，广场上，全是蹦蹦！\", \"voicelineId\": 18038, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解可莉·其一\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_friendship_01\", \"description\": \"你好！你是来找可莉玩的吗？\", \"voicelineId\": 18039, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解可莉·其二\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_friendship_02\", \"description\": \"是啊，这个炸弹是可莉最新改良的作品！你看我做得好不好？…呃——如果是在什么纵火现场发现的话，那就不是我做的，绝对不是。\", \"voicelineId\": 18040, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解可莉·其三\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_friendship_03\", \"description\": \"哎，虽然新炸药的配方，很多都是在被关禁闭的时候想出来的…但如果不被关禁闭的话就更好了…\", \"voicelineId\": 18041, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解可莉·其四\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_friendship_04\", \"description\": \"这是嘟嘟可，是可莉很久以前就交到的好朋友。要记得它的名字哦，以后别叫它「挂在你包上的玩偶」啦。\", \"voicelineId\": 18042, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解可莉·其五\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_friendship_05\", \"description\": \"谢谢你总是帮可莉解决麻烦！就用这串「可莉烤鱼」来报答你吧！——呃，其实鱼是直接在湖里就被炸弹烤熟了，不过这件事就和平时一样，假装不知道好了。\", \"voicelineId\": 18043, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"可莉的爱好…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_pref_hobby\", \"description\": \"可莉喜欢毛茸茸的东西。比如嘟嘟可、蒲公英，还有雷泽的头发。\", \"voicelineId\": 18044, \"voicelineType\": \"6001\"}, {\"title\": \"可莉的烦恼…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_dialog_annoyed\", \"description\": \"唉，你是好人，我是坏孩子…等我这次的禁闭结束、好好反省过以后，再来找你带我出去玩…\", \"voicelineId\": 18045, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_pref_foodLike\", \"description\": \"蒙德的鲈鱼是很好吃的，从果酒湖里抓到的尤其好吃！这可不是瞎说的，连妈妈也认同可莉的想法喔。\", \"voicelineId\": 18046, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_pref_foodDislike\", \"description\": \"讨厌蒙德蟹——什么蟹都讨厌——可莉要出去玩——不要坐在餐桌前慢慢剥壳——\", \"voicelineId\": 18047, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_spice_pref_01\", \"description\": \"好香好香！可莉已经吃到吃不下啦…\", \"voicelineId\": 18077, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_spice_normal_01\", \"description\": \"今天也吃到了好吃的东西，可莉好开心！谢谢你！\", \"voicelineId\": 18078, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_spice_dislike_01\", \"description\": \"看上去很好吃，但吃起来不太方便…嘿嘿，你来帮帮可莉好不好！\", \"voicelineId\": 18079, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_pref_birthday\", \"description\": \"生日快乐！过生日很开心，你比可莉大，那过生日的次数一定比可莉多吧？可莉很羡慕！\", \"voicelineId\": 18048, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_starUp_01\", \"description\": \"嗯，新型炸弹研究完毕！趁琴团长发现之前，开溜！\", \"voicelineId\": 18049, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_starUp_02\", \"description\": \"又进步了一点！不过琴团长总是说：「进步是分内之事。」\", \"voicelineId\": 18050, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_starUp_03\", \"description\": \"谢谢你总是陪我一起收集研究用的材料！如果你想学习炸弹的制作方法，我也可以来教你哦。\", \"voicelineId\": 18051, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_klee/vo_klee_starUp_04\", \"description\": \"很久以前，第一次听到爆炸声的时候，我没有害怕…后来我才知道，大部分人不是这样的…不过，你也不害怕我的炸弹呢！嘿嘿，太好了，可莉果然交到了很好的朋友！\", \"voicelineId\": 18052, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_battle_skill1_01\", \"description\": \"蹦蹦炸弹！\", \"voicelineId\": 18053, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_battle_skill1_02\", \"description\": \"弹起来吧！\", \"voicelineId\": 18054, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_battle_skill1_03\", \"description\": \"嘿咻！\", \"voicelineId\": 18055, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_battle_skill3_01\", \"description\": \"轰轰火花！\", \"voicelineId\": 18056, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_battle_skill3_02\", \"description\": \"火力全开！\", \"voicelineId\": 18057, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_battle_skill3_03\", \"description\": \"全——都可以炸完！\", \"voicelineId\": 18058, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_explore_sprint_start_01\", \"description\": \"啦啦啦~\", \"voicelineId\": 18059, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺开始·其二\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_explore_sprint_start_02\", \"description\": \"哒哒哒~\", \"voicelineId\": 18060, \"voicelineType\": \"700002\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_chest_open_01\", \"description\": \"可莉又找到新的宝物了！\", \"voicelineId\": 18061, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_chest_open_02\", \"description\": \"亮闪闪的，好开心！\", \"voicelineId\": 18062, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_chest_open_03\", \"description\": \"地下会不会埋着更多宝箱呢…\", \"voicelineId\": 18063, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_life_less30_01\", \"description\": \"哇…怎么会这样…\", \"voicelineId\": 18064, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_life_less30_02\", \"description\": \"琴团长…它欺负我…\", \"voicelineId\": 18065, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_life_less30_03\", \"description\": \"玩累了，有点晕…\", \"voicelineId\": 18066, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_life_less30_teammate_01\", \"description\": \"火花骑士，爆破支援！\", \"voicelineId\": 18067, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_life_less30_teammate_02\", \"description\": \"你不要紧吧？\", \"voicelineId\": 18068, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_life_die_01\", \"description\": \"看我成功开溜…！啊，失败了。\", \"voicelineId\": 18069, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_life_die_02\", \"description\": \"可莉…想回家了…\", \"voicelineId\": 18070, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_life_die_03\", \"description\": \"又闯祸了…\", \"voicelineId\": 18071, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_battle_hit_L_02\", \"description\": \"过分…\", \"voicelineId\": 18072, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_klee/vo_klee_battle_hit_H_02\", \"description\": \"好疼啊！\", \"voicelineId\": 18073, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_klee_teamJoin_01\", \"description\": \"可莉来帮忙！\", \"voicelineId\": 18074, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_klee_teamJoin_02\", \"description\": \"锵锵——可莉登场。\", \"voicelineId\": 18075, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_klee_teamJoin_03\", \"description\": \"好耶！是大冒险。\", \"voicelineId\": 18076, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000030, 'Zhongli', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_draw_appear\", \"description\": \"一份新的「契约」？好吧…虽然我还在度假，但也可以陪你走一趟。契约书上，该签什么名字呢？我有许多名字，度假期间的话…我会自称「钟离」。你呢，旅行者？你会签下什么名字？\", \"voicelineId\": 17100, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·旅程\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_explore_idle_01\", \"description\": \"旅程总有一天会迎来终点，不必匆忙。\", \"voicelineId\": 17101, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·游览\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_explore_idle_02\", \"description\": \"接下来想去哪里？如果想游历璃月名胜的话，我有一些不错的参考方案。\", \"voicelineId\": 17102, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·璃月\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_explore_idle_03\", \"description\": \"为「流通」而造的船，遇到港口也会停泊，所以璃月是一切财富「沉淀」的地方。\", \"voicelineId\": 17103, \"voicelineType\": \"1103\"}, {\"title\": \"闲聊·怀旧\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_explore_idle_04\", \"description\": \"欲买桂花同载酒…只可惜故人，何日再见呢？\", \"voicelineId\": 17104, \"voicelineType\": \"1104\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_weather_afterRain_01\", \"description\": \"「琉璃袋」这种植物，它偏爱潮湿的环境，最适合雨后采摘。如果发现的话，适当储备些吧。\", \"voicelineId\": 17105, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_weather_snowy_01\", \"description\": \"找个地方避避雪吧。我不会有事，但你可能着凉。\", \"voicelineId\": 17106, \"voicelineType\": \"1202\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_weather_gale_01\", \"description\": \"嗯…不适合度假的天气。去听听戏吧。\", \"voicelineId\": 17107, \"voicelineType\": \"1203\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_greetingMorning\", \"description\": \"希望今日也有好景气。\", \"voicelineId\": 17108, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_greetingNoon\", \"description\": \"想要吃点提神的？嗯，吃虎岩倒是有爿不错的店…\", \"voicelineId\": 17109, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_greetingNight\", \"description\": \"虽然这种时候已经错过了云先生的戏，但夜晚的璃月仍有许多好去处。\", \"voicelineId\": 17110, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_greetingNight2\", \"description\": \"集市已收，喧闹的码头也已沉睡。去休息吧。\", \"voicelineId\": 17111, \"voicelineType\": \"1004\"}, {\"title\": \"关于钟离自己…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_idle\", \"description\": \"不以规矩，不能成方圆。不管是常人还是仙人，惟有各司其职，方能保璃月长久太平。\", \"voicelineId\": 17112, \"voicelineType\": \"2001\", \"unlockConditions\": [{\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·黄金\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_close1\", \"description\": \"黄金是璃月的财富，是令璃月的心脏搏动的血液。你是否拥有黄金般闪耀的心，就让我拭目以待吧。\", \"voicelineId\": 17113, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·契约\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_close2\", \"description\": \"你我既有「契约」之交——那么凡在契约范围内的事，都可同我商量。\", \"voicelineId\": 17114, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·公平\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_close3\", \"description\": \"「契约」之外的事也可与我相谈。毕竟我在这片土地上活了这么久，凡事都略通一二。哦，虽说如此，我也有希望你能为我做的事情。毕竟，这样才符合「公平」嘛。\", \"voicelineId\": 17115, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·困惑\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_close4\", \"description\": \"「契约」无法界定「友谊」、无法丈量「情谊」，那到底用什么才能称量你我之间情感的重量呢？「朋友」，你知道答案吗？\", \"voicelineId\": 17116, \"voicelineType\": \"2006\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_pendant\", \"description\": \"「神之眼」…也是一种「契约」。须知一切力量皆有其代价，一千种权力伴随着一千种责任。\", \"voicelineId\": 17117, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_share\", \"description\": \"「交易」的规矩是「契约」，准则是「公平」。这是订立、遵循「契约」者绝不可忘却之事：倘若失了公平，那契约便成了欺瞒的凭据。\", \"voicelineId\": 17118, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_pref_gift\", \"description\": \"你若去往「绝云间」，便替我采来一束「清心」吧。一束就好。此行的旅费…啊，差些忘了，「契约」生效期间，旅费由你代为垫付。那就有劳了。\", \"voicelineId\": 17119, \"voicelineType\": \"3003\"}, {\"title\": \"关于魈…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_xiao_01\", \"description\": \"你说，归离原的少年仙人…啊…直至今日，他仍在履行他的职责…哦，这副「连理镇心散」，请替我带给他。对了，可千万不能让小派蒙偷吃了去，这里的药力…绝非常人所能承受。\", \"voicelineId\": 17120, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温迪…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_venti_01\", \"description\": \"嘶...好浓的酒气。那个诗人刚刚来过吧，那个和风雅二字搭不上一点关系的酒鬼诗人！你这里…唔，被他诱骗着灌了酒，话也说不清了么…你等一下，我去沏一壶「醒神茶」，只需三个时辰便好。你等一下…\", \"voicelineId\": 17121, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_ningguang_01\", \"description\": \"即便每日经手的事务千条万缕，她仍不失进取之心，实属难得。让我想起，彼时的她赤着脚从瑶光滩走到南码头，一路叫卖货品的样子。时间对于常人，真是残酷…\", \"voicelineId\": 17122, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_hutao_01\", \"description\": \"当代堂主？嗯…那孩子，我应付不来。\", \"voicelineId\": 17123, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于达达利亚·沉着\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_tartaglia_01\", \"description\": \"那位来自至冬的武人，还没离开璃月吗？没关系，要是他找你麻烦，你可以唤我去应付他。\", \"voicelineId\": 17124, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于达达利亚·酒桌\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_tartaglia_02\", \"description\": \"听说「公子」最近在愚人众的风评又变糟了不少。但像他这样的人，一定会用积极的行动去扫清那些对他的怨言吧。嗯…这样想来，下回酒桌上又有不少趣事可以听了。旅者，你也一起来吗？\", \"voicelineId\": 17125, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_ganyu_01\", \"description\": \"璃月这个国度的繁荣，靠得绝不仅是「岩王帝君」的神谕，而是无数响应「契约」的岩神子民。在这之中，甘雨已是就职时间最长的一位了。关于她的往事…我怕她怪罪，让她自己和你说吧。\", \"voicelineId\": 17126, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_keqing_01\", \"description\": \"她是当代七星中最「不敬神」的，但我还挺欣赏这样的人。「觉得自己是正确的，就大声地说出来、坚决地去行动」——就是因为璃月有这样的人，我才会考虑退休一事。\", \"voicelineId\": 17127, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于烟绯…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_yanfei_01\", \"description\": \"她未曾与我签订「契约」，却在以自己的方式维护璃月各界的规矩，并将有失偏颇的观念纠正。倘若某天，她的父亲远游归来，想来会比我更欣慰吧。\", \"voicelineId\": 17128, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于巴尔…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_raidenShogun_01\", \"description\": \"时间会淬炼一切意志。而她，恰好是会为信念付出所有的人。或许正因如此，她才能走到这一步。如有机会，我也想见识一下她为之倾尽一切的「永恒」。\", \"voicelineId\": 17168, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于布耶尔…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_nahida_01\", \"description\": \"智慧之神布耶尔，不仅统管整个须弥，还肩负着守护世界树的职责。若非有大智慧，的确难以司掌这些。拯救世界树一事，整个提瓦特的生灵都理应向她致谢。\", \"voicelineId\": 17172, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_furina_01\", \"description\": \"与「自我」签订下拯救国家的契约，并严守五百年，最终骗过了天理…我尊敬一切需要自我践行的「正义」。即便神性的部分已经消散，神座不复存在，但对于整个枫丹的历史来说，芙宁娜依旧是值得被认可的正义之神。\", \"voicelineId\": 17173, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于闲云…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_teammate_xianyun_01\", \"description\": \"我听不少商人聊起过「闲云」的逸闻。说是这位女子看似倨傲，不喜言谈，交谈一番却发现她性格耿直，作风正派，是位值得结交的良友。我为她高兴。但「出手阔绰」这条评价，嗯，也有不少人对我说过…\", \"voicelineId\": 17174, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11035], \"unlockText\": \"完成「千里月明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解钟离·其一\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_friendship_01\", \"description\": \"怎么，难得闲暇，不好好休息却反来找我。是想听我讲故事吗？\", \"voicelineId\": 17129, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解钟离·其二\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_friendship_02\", \"description\": \"「黑岩厂」的起源，听说过吗？\\n在过去，人们一边将天衡山中的矿脉挖空，一边在里面修建工场设施，渐渐建成了东大陆最大的工厂。山中黯道四通八达，一些甚至能通往大地深处的古遗迹。能掌握其中一切通路的人，如今大概没有了吧。\", \"voicelineId\": 17130, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解钟离·其三\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_friendship_03\", \"description\": \"「海灯节」的起源，听说过吗？\\n在很久以前的战争中，璃月人会在夜里放飞明亮的灯，让厮杀的战士不迷失回家的方向，不迷失自己的心。这种事情，如今大概已经没有人记得了。\", \"voicelineId\": 17131, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解钟离·其四\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_friendship_04\", \"description\": \"「契约之神」的事情，听说过吗？\\n他的记性很好。每位对手的名字，璃港船局建成以来制造的每一艘船起航的日子，都不曾忘却。毕竟，有这样的记忆力，才能铭记一切「契约」。\\n然而，记性很好有时是令人不快的事。\", \"voicelineId\": 17132, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解钟离·其五\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_friendship_05\", \"description\": \"活得太久的人，只能在记忆中寻访往昔的战友、过去的景色。\\n即使如此我也不后悔与你相识，「朋友」。假使有一日不得不同你相别，你在我的记忆中也会如黄金般闪耀。\", \"voicelineId\": 17133, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"钟离的爱好…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_pref_hobby\", \"description\": \"得闲时在城内散步，就能让我心安不少。嗯…这种心情，是从何时开始…？\", \"voicelineId\": 17134, \"voicelineType\": \"6001\"}, {\"title\": \"钟离的烦恼…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_dialog_annoyed\", \"description\": \"让人们遵循「契约」，依照契约的规矩行事，其实是希望人们能遵循「公平」。只是这一点，总有人意识不到。\", \"voicelineId\": 17135, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_pref_foodLike\", \"description\": \"很久以前，与朋友共饮的酒。是因为气候变了吗？唉，过去的滋味，或许再也不能重现了吧。\", \"voicelineId\": 17136, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_pref_foodDislike\", \"description\": \"我不喜欢海鲜。仅仅是看到海鲜，就会想到那种…该怎么说呢，滑溜溜的触感，洗不净的腥味。哦，原因的话…\\n唉，说来话长，就当是因为我记性太好了吧。\", \"voicelineId\": 17137, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_spice_pref_01\", \"description\": \"用料讲究，做法地道。属实不易。\", \"voicelineId\": 17169, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_spice_normal_01\", \"description\": \"烹饪是一件饶有趣味的事，想来对你而言也是如此。\", \"voicelineId\": 17170, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_spice_dislike_01\", \"description\": \"既有闲暇，不如找一处庭院，和你说一段故事吧。\", \"voicelineId\": 17171, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_pref_birthday\", \"description\": \"生日快乐。这是曾在你出生的那天盛开的，「琉璃百合」的干花。\\n很久以前的璃月人会说，这种花承载着大地中的美好记忆与祈愿而盛开。我愿意相信，你的诞生也是同样的道理。\", \"voicelineId\": 17138, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_starUp_01\", \"description\": \"力量似乎渐渐回来了。不多，但有用。\", \"voicelineId\": 17139, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_starUp_02\", \"description\": \"力量增长了，身体的负担随之剧增…哦，我没事，我的构造不同常人，请不用担心。\", \"voicelineId\": 17140, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_starUp_03\", \"description\": \"原来如此，驱动「神之眼」驾驭元素力，对于常人而言不啻伟业。哦，原来如此…那时的他们，是抱着这样的觉悟站在我身旁啊…\", \"voicelineId\": 17141, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_zhongli/vo_zhongli_starUp_04\", \"description\": \"不曾料想，放下「神之心」后，还能看到这种景色——感谢你，「朋友」...对了，我这里有一份新的「契约」，不一起来看看么？\", \"voicelineId\": 17142, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_skill1_01\", \"description\": \"壁立千仞。\", \"voicelineId\": 17143, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_skill1_02\", \"description\": \"震天撼地。\", \"voicelineId\": 17144, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_skill1_03\", \"description\": \"靡坚不摧。\", \"voicelineId\": 17145, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_skill1_04\", \"description\": \"俱收并蓄。\", \"voicelineId\": 17146, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_skill1_05\", \"description\": \"安如磐石。\", \"voicelineId\": 17147, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_skill1_06\", \"description\": \"固若金汤。\", \"voicelineId\": 17148, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_skill3_01\", \"description\": \"天理长驱。\", \"voicelineId\": 17149, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_skill3_02\", \"description\": \"此乃天道。\", \"voicelineId\": 17150, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_skill3_03\", \"description\": \"天动万象。\", \"voicelineId\": 17151, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_chest_open_01\", \"description\": \"遗珠弃璧，吉光片裘…\", \"voicelineId\": 17152, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_chest_open_02\", \"description\": \"偶遇之物，亦有风雅。\", \"voicelineId\": 17153, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_chest_open_03\", \"description\": \"不虚此行。\", \"voicelineId\": 17154, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_life_less30_01\", \"description\": \"你的实力我姑且认可。\", \"voicelineId\": 17155, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_life_less30_02\", \"description\": \"哈，有点意思。\", \"voicelineId\": 17156, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_life_less30_03\", \"description\": \"不太擅长危机应对啊。\", \"voicelineId\": 17157, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_life_less30_teammate_01\", \"description\": \"不可贸然进攻。\", \"voicelineId\": 17158, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_life_less30_teammate_02\", \"description\": \"下去休息。这里交给我。\", \"voicelineId\": 17159, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_life_die_01\", \"description\": \"啊，略感疲惫…\", \"voicelineId\": 17160, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_life_die_02\", \"description\": \"让你看到，难堪的一面了啊。\", \"voicelineId\": 17161, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_life_die_03\", \"description\": \"磐石…也会归于尘土…\", \"voicelineId\": 17162, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_hit_H_01\", \"description\": \"大意了吗。\", \"voicelineId\": 17163, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_zhongli/vo_zhongli_battle_hit_H_02\", \"description\": \"不足为惧。\", \"voicelineId\": 17164, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_zhongli_teamJoin_01\", \"description\": \"也好。\", \"voicelineId\": 17165, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_zhongli_teamJoin_02\", \"description\": \"就当是散心了。\", \"voicelineId\": 17166, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_zhongli_teamJoin_03\", \"description\": \"做些什么好呢…\", \"voicelineId\": 17167, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000031, 'Fischl', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_draw_appear\", \"description\": \"菲谢尔：我即断罪之皇女，真名为菲谢尔。应命运的召唤降临在此间——哎？你也是，异世界的旅人吗…？那好吧，本皇女恩许你同行。\\n奥兹：她的意思是「你好，很高兴认识你」。\", \"voicelineId\": 19009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·真命低语\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_character_idle_01\", \"description\": \"我听见命运的嚅嗫，低声呼唤我之尊名…\", \"voicelineId\": 19010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·天地创造\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_character_idle_02\", \"description\": \"哼哼，就让皇女的光采荣耀此间天地吧。\", \"voicelineId\": 19011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·彼方之人\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_character_idle_03\", \"description\": \"菲谢尔：不知在遥远彼方的扈从…\\n奥兹：毋须担心冒险家协会的大家。\", \"voicelineId\": 19012, \"voicelineType\": \"1103\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_weather_afterRain_01\", \"description\": \"天晴了吗，真舒…咳，此间须臾的霁月光风，就如命运的转折点一般呢！愉快！\", \"voicelineId\": 19013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_weather_thunder_01\", \"description\": \"菲谢尔：啊啊，看那昭告命运的圣裁之雷…\\n奥兹：这么说来，是不是还有衣服没收？\\n菲谢尔：欸？！\", \"voicelineId\": 19014, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_weather_snowy_01\", \"description\": \"菲谢尔：哼哼，这可是好光景。就像在「那个世界」，罪人的血与泪在断罪的皇女面前凝结的模样呢——啊、啊——阿嚏！阿嚏！\\n奥兹：面对小姐，罪人的鼻涕恐怕都要凝结了。\\n菲谢尔：奥兹——啊、阿嚏！\", \"voicelineId\": 19015, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_weather_sunny_01\", \"description\": \"菲谢尔：奥兹，我之眷属啊…\\n奥兹：喔？怎么突然——\\n菲谢尔：以皇女之名，以你的祝圣之翼，遮蔽日月星空，带来永恒的幽夜吧。\\n奥兹：不要强人所难！\", \"voicelineId\": 19016, \"voicelineType\": \"1204\"}, {\"title\": \"早上好·问候菲谢尔\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_greetingMorning\", \"description\": \"昼夜时空皆为虚像，命运的纽带却再次将你带到了我的永恒长夜中。\", \"voicelineId\": 19017, \"voicelineType\": \"1001\"}, {\"title\": \"早上好·问候奥兹\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_greetingMorning2\", \"description\": \"奥兹：早上好！听说你要来，小姐在准备早点…\\n菲谢尔：奥兹！…咳，有何贵干？\", \"voicelineId\": 19018, \"voicelineType\": \"1002\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_greetingNoon\", \"description\": \"哈…即使贵为皇女，在这样的时辰也不免困乏…\", \"voicelineId\": 19019, \"voicelineType\": \"1003\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_greetingNight\", \"description\": \"菲谢尔：天穹上的星光，都是奥兹在无尽的夜幕上啄出来的洞。\\n奥兹：是才怪啦！\", \"voicelineId\": 19020, \"voicelineType\": \"1004\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_greetingNight2\", \"description\": \"菲谢尔：你的深眠将平安无梦。毕竟，岂有梦魇，敢染指幽夜净土所祝圣之人…\\n奥兹：她说「晚安」。\", \"voicelineId\": 19021, \"voicelineType\": \"1005\"}, {\"title\": \"关于菲谢尔自己·断罪之皇女\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_idle\", \"description\": \"菲谢尔：我吗？哼哼。记好了，我乃幽夜净土的主人，断罪之皇女菲谢尔，裁断此世一切罪责，透彻此间一切真知。\\n奥兹：就是冒险家协会的调查员。\\n菲谢尔：…那只是肤浅的表象！\", \"voicelineId\": 19022, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·降临此间之人\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_close\", \"description\": \"我与你同为异世界的旅人，在此相遇。错不了，想必是命运的意志吧。\", \"voicelineId\": 19023, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·射落世界之兽\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_close1\", \"description\": \"看你有什么烦恼的样子…？旅人啊，不必困惑。因为，我以我的左眼，这只透彻因果之丝的「断罪之眼」，守望着你的命运；以奥兹那见证过一千世界寂灭的鸦眼，观察着你的进路。假若名为「世界」的夜巡凶兽觊觎你的梦想，那我便以断罪的圣裁魔矢将其射落！\", \"voicelineId\": 19024, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·重要之人\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_close2\", \"description\": \"菲谢尔：奥兹，我之忠友啊…能遇到「那个人」，与本皇女同样不属于这个世界的旅人…连残酷的命运，也会对我罪孽深重的血脉，展露微笑呢。就算是我的命运，我无法逃离的「现实」…\\n奥兹：啊啊，我明白。那个旅行者的话，不管发生了什么，都不会抛弃小姐的吧。\", \"voicelineId\": 19025, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·守望\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_close3b\", \"description\": \"菲谢尔：奥兹华尔多·赫芙那梵茵斯。为我，为幽夜净土的主宰，断罪的皇女，做好献出生命的觉悟，守望{PLAYERAVATAR#SEXPRO[INFO_MALE_PRONOUN_HE|INFO_FEMALE_PRONOUN_SHE]}注定多舛的命运吧。\\n奥兹：不要随便让我送命啊！\", \"voicelineId\": 19026, \"voicelineType\": \"2005\", \"voicefile_male\": \"VO_friendship/VO_fischl/vo_fischl_dialog_close3a\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true, \"hasGenderedVoicefile\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_pendant\", \"description\": \"嗯？这个「渊色的幽邃秘珠」吗。那是我族的王器，向一切无礼者昭告断罪皇女之仪。即使流落到了这个荒芜的世界，王器仍然追随着皇族之血与崇高之魂，找到了我，这就是无法斩断的因果吧…\", \"voicelineId\": 19027, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_share\", \"description\": \"菲谢尔：这么说来，按照这个世界的历法，我有三千多岁了。当然，日月流转的虚像对看破三千宇宙因果的我而言没有意义。\\n奥兹：小姐，这招是骗不过酒保的，没到喝酒的年纪就是没到喝酒的年纪。\", \"voicelineId\": 19028, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_pref_gift\", \"description\": \"奥兹的全名，是奥兹华尔多·赫芙那梵茵斯，在「那个世界」主宰着三个宇宙的星海与夜空，以影之翼荫蔽所有战死的勇者之魂。顺带一提，叫错他的名字会被处以拔舌之刑。但我是皇女，而你是我认可的人，所以我们可以随意叫他奥兹。\", \"voicelineId\": 19029, \"voicelineType\": \"3003\"}, {\"title\": \"关于班尼特…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_teammate_bennett_01\", \"description\": \"菲谢尔：那位厄运的少年吗…错不了的，我这只「断罪之眼」见证过，他那被世界唾弃的悲哀——\\n奥兹：那个倒霉蛋，置之不理可不行。\", \"voicelineId\": 19030, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_teammate_lisa_01\", \"description\": \"菲谢尔：那司书的魔女，坐拥着宇宙知识的宝库…如果能赢取她的信任，或许就能获得伟大智慧…\\n奥兹：她说「图书馆的规矩就是有借有还，再借不难」。\", \"voicelineId\": 19031, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_teammate_kaeya_01\", \"description\": \"菲谢尔：无法看透的真实，无法断明的因果，虚实交织的狂言…那个人，或许也与我一样，背负了「魔眼」的命运…\\n奥兹：也可能暗地里是个海盗…？\", \"voicelineId\": 19032, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莫娜…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_teammate_mona_01\", \"description\": \"菲谢尔：啊啊，那位「伟大的占星术士莫娜」…哼，此人曾经妄图窥探本皇女的命运，结果却浑身颤抖呢。\\n奥兹：当时占星术士似乎在努力憋笑，非常不容易。\", \"voicelineId\": 19033, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于罗莎莉亚…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_teammate_rosaria_01\", \"description\": \"菲谢尔：她吗？似乎是虔信风神的忠实修女呢。\\n奥兹：「虔信」？「忠实」？\\n菲谢尔：没错。有天晚上看到过，她对什么人说「以风神巴托巴斯的名义，去死吧」这样的话，想必是在领祷吧。\", \"voicelineId\": 19034, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解菲谢尔·其一\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_friendship_01\", \"description\": \"哼哼，为应受罪罚之徒断罪，为命运青睐之人祝圣，以无尽的幽夜净土收容世间一切不被容赦的梦想，这就是断罪皇女血脉背负的沉重使命，谁人也不许质疑。\", \"voicelineId\": 19035, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解菲谢尔·其二\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_friendship_02\", \"description\": \"我的左眼？我的左眼是透彻世间一切真相的「断罪之眼」。至于为何要遮起来…那么，窥见此间与彼方一切真实的负担与痛，你愿意承受吗？再说了，通晓此世与常世一切妄念与谎言，又是何等无趣的事，哼哼。\", \"voicelineId\": 19036, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解菲谢尔·其三\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_friendship_03\", \"description\": \"菲谢尔：风魔龙？那种本皇女寝宫花园里拴着的宠物级别的东西，没想到在这个世界也能形成灾祸呢。哼，一群没用的家伙…\\n奥兹：虽然小姐这么说，当时不也为大家担心得不得了吗。\\n菲谢尔：那、那还不是因为身为皇女，有守护尘世众生一切灵魂的崇高职责…\", \"voicelineId\": 19037, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解菲谢尔·其四\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_friendship_04\", \"description\": \"奥兹：有的人会用其他的名字呼唤小姐。但对我来说，将生命与力量分给我的人，只有「菲谢尔」这个名字。这才是符合她命运的名字，千万不要弄错…\\n菲谢尔：你们，商谈之事为何？\\n奥兹：关、关于至夜幻现！还有断罪之名！\", \"voicelineId\": 19038, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解菲谢尔·其五\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_friendship_05\", \"description\": \"皇女应断之罪为何，那当然是「违逆命运」了…毕竟，正是命运，让你…是命运，令你我降临此世，将因果交织相连。我、我会守护你，只、只因这是命运的默示录中昭告之事！\", \"voicelineId\": 19039, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"菲谢尔的爱好·询问菲谢尔\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_pref_hobby_01\", \"description\": \"本皇女驰骋星间，行遍诸多世界，领略过一万种宇宙的命运，通读一切灵魂的默示录。\", \"voicelineId\": 19040, \"voicelineType\": \"6001\"}, {\"title\": \"菲谢尔的爱好·询问奥兹\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_pref_hobby_02\", \"description\": \"奥兹：小姐喜欢看小说。唉…「奥兹」这个名字，也是她从喜欢的小说里挑的。\", \"voicelineId\": 19041, \"voicelineType\": \"6002\"}, {\"title\": \"菲谢尔的烦恼…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_dialog_annoyed\", \"description\": \"嗯？这世间能困扰皇女的事情…硬要说的话，那就是，总有人无法接受我的真实身份。但无妨，毕竟高贵者注定孤独嘛。只要我不失却这颗崇高之心…\", \"voicelineId\": 19042, \"voicelineType\": \"6003\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_pref_foodLike\", \"description\": \"菲谢尔：哼，食物只是凡骨肉胎所受的桎梏。但硬要说的话，能配得上断罪皇女的，那莫过于罪人之泪与谎言之舌…\\n奥兹：并不是小姐常做的「常夜夏宫蜜吐司」吗？\\n菲谢尔：——只，只是为了补充这具躯壳所需的能量！\", \"voicelineId\": 19043, \"voicelineType\": \"6004\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_pref_foodDislike\", \"description\": \"奥兹：小姐讨厌的，应该是那个吧…\\n菲谢尔：那个吗。被违抗自然的锁链束缚的肢体…\\n奥兹：再也不能如我这般飞翔…\\n菲谢尔：失去了那生来便仰慕皇族王者的卑下头颅，简直是「那个世界」的地狱略影。其名为…\\n奥兹：好像是叫什么酿鸡来着？\", \"voicelineId\": 19044, \"voicelineType\": \"6005\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_spice_pref_01\", \"description\": \"菲谢尔：此等珍馐，可纳于忘忧之御膳园中。\\n奥兹：小姐说，这就是她理想的美味。\", \"voicelineId\": 19075, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_spice_normal_01\", \"description\": \"菲谢尔：为射落世界之兽，必须突破尘俗欲望，编织通向命运之间的道路。\\n奥兹：但刚才，小姐不是吃得很香吗？\", \"voicelineId\": 19076, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_spice_dislike_01\", \"description\": \"菲谢尔：为何要将残破与毁灭，呈于本皇女面前？\\n奥兹：小姐不太喜欢这道菜肴，请你见谅。\", \"voicelineId\": 19077, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_pref_birthday\", \"description\": \"菲谢尔：哼哼，既然今日是你的命定之日，那我不可能坐视不管。来，说吧！在这腐朽而幽邃的世界里，在你渺小而短暂的人生中，有什么想要实现的愿望，尽管说来，让本皇女听听！嗯…即使是…\\n奥兹：她说「生日快乐，如果你想要，她」…\\n菲谢尔：奥兹！多嘴！\", \"voicelineId\": 19045, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_starUp_01\", \"description\": \"菲谢尔：至夜的魔箭…它在高声呼唤着我的祝圣之名，祈求着罪罚的苍紫雷光，射落命运之敌！\\n奥兹：伟哉！考虑到晚饭，如果能射落鸽子就更好了。\", \"voicelineId\": 19046, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_starUp_02\", \"description\": \"菲谢尔：有了这个，就能更好地行使断罪皇女的威仪，击败名为「现实」的命运之敌了。\\n奥兹：嗯，就能更好地完成协会的工作了。\", \"voicelineId\": 19047, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_starUp_03\", \"description\": \"狂喜吧！战栗吧！要问为何的话，须知幽夜净土的断罪皇女，已经用这只左眼，看清了编织宇宙的命运之丝！\", \"voicelineId\": 19048, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_fischl/vo_fischl_starUp_04\", \"description\": \"来到这个世界而失去的力量，似乎已经恢复了大半。哼哼哼，定罪之时即将…啊啊，不必担心。即使到了终末之刻，我在此世降下罪罚之雷时，也不会伤及你。因为，你可是我的祝圣之人啊。\", \"voicelineId\": 19049, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_battle_skill1_01\", \"description\": \"以断罪之名！\", \"voicelineId\": 19050, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_battle_skill1_02\", \"description\": \"现身吧，奥兹！\", \"voicelineId\": 19051, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_battle_skill1_03\", \"description\": \"回应我吧！\", \"voicelineId\": 19052, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_battle_skill1_04\", \"description\": \"奥兹：又来了…\", \"voicelineId\": 19053, \"voicelineType\": \"100004\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_battle_skill3_01\", \"description\": \"黑之翼，屏断昼夜——\", \"voicelineId\": 19054, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_battle_skill3_02\", \"description\": \"至夜幻现！\", \"voicelineId\": 19055, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_battle_skill3_03\", \"description\": \"影之鸦，渴求幽夜——\", \"voicelineId\": 19056, \"voicelineType\": \"200003\"}, {\"title\": \"元素爆发·其四\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_battle_skill3_04\", \"description\": \"奥兹：一如小姐所愿！\", \"voicelineId\": 19057, \"voicelineType\": \"200004\"}, {\"title\": \"元素爆发·其五\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_battle_skill3_05\", \"description\": \"奥兹：至夜幻现！\", \"voicelineId\": 19058, \"voicelineType\": \"200005\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_chest_open_01\", \"description\": \"命运，指引我来此！\", \"voicelineId\": 19059, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_chest_open_02\", \"description\": \"荒芜的世界，竟藏有这等瑰宝！\", \"voicelineId\": 19060, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_chest_open_03\", \"description\": \"哈哈哈，高呼我的祝圣之名吧！\", \"voicelineId\": 19061, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_life_less30_01\", \"description\": \"只好稍微认真一点了，哼。\", \"voicelineId\": 19062, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_life_less30_02\", \"description\": \"奥兹：小姐，如果你倒下了，我——！\", \"voicelineId\": 19063, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_life_less30_03\", \"description\": \"皇女的命运，不应在此完结…！\", \"voicelineId\": 19064, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_life_less30_teammate_01\", \"description\": \"哼，就让我来吧！\", \"voicelineId\": 19065, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_life_less30_teammate_02\", \"description\": \"奥兹：小姐，那边有些不妙…\", \"voicelineId\": 19066, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_life_die_01\", \"description\": \"这个世界，也容不得本皇女吗…\", \"voicelineId\": 19067, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_life_die_02\", \"description\": \"我将再度降临…呜…\", \"voicelineId\": 19068, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_life_die_03\", \"description\": \"奥兹：小姐！…\", \"voicelineId\": 19069, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_fischl/vo_fischl_battle_hit_H_01\", \"description\": \"不敬之徒。\", \"voicelineId\": 19070, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_fischl_teamJoin_01\", \"description\": \"以皇女之名！\", \"voicelineId\": 19072, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_fischl_teamJoin_02\", \"description\": \"菲谢尔：赞颂我的降临吧。奥兹：伟哉！\", \"voicelineId\": 19073, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_fischl_teamJoin_03\", \"description\": \"你的命运，已成为我掌间之丝！\", \"voicelineId\": 19074, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000032, 'Bennett', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_draw_appear\", \"description\": \"这就是你的冒险团吗？真好啊…又热闹，又有人情味。啊，我是「班尼冒险团」的团长班尼特！能把我列入你们的合作伙伴吗？拜托了！\", \"voicelineId\": 20009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·宝藏\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_explore_idle_01\", \"description\": \"不如在周围找找看吧，说不定有宝藏呢！\", \"voicelineId\": 20010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·冒险\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_explore_idle_02\", \"description\": \"好久没有和别人一起冒险了！我们走吧！\", \"voicelineId\": 20011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·调侃\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_explore_idle_03\", \"description\": \"俗话说「等在原地是不会有好事发生的」，当然以我的运气来说，往哪里走都一样啦…\", \"voicelineId\": 20012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_weather_heavyRain_01\", \"description\": \"我冒险的时候，大多都是这种天气。\", \"voicelineId\": 20013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_weather_thunder_01\", \"description\": \"啊！别和我站得太近，这样雷就不会劈到你了。\", \"voicelineId\": 20014, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_weather_sunny_01\", \"description\": \"今天的天气真不错…啊，糟了，说完这种话多半就要下雨了。\", \"voicelineId\": 20015, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_weather_gale_01\", \"description\": \"小心点，别被吹过来的石头砸到脑袋了！\", \"voicelineId\": 20016, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_greetingMorning\", \"description\": \"早上好！我们今天去哪儿冒险啊？\", \"voicelineId\": 20017, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_greetingNoon\", \"description\": \"我带了三明治，要吃吗？分你一半…唔唔！咳，咳…不好意思，噎到了。\", \"voicelineId\": 20018, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_greetingNight\", \"description\": \"要不要陪我去和老爹们聊聊天啊？老冒险家的故事可有意思了！\", \"voicelineId\": 20019, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_greetingNight2\", \"description\": \"要走了吗？能和你一起冒险太开心了，下次记得再叫上我啊！\", \"voicelineId\": 20020, \"voicelineType\": \"1004\"}, {\"title\": \"关于班尼特自己·冒险团\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_idle\", \"description\": \"我就是「班尼冒险团」的团长，振兴蒙德冒险家协会的希望之星…没见过其他团员？那个…最近他们都请假了，哈哈。\", \"voicelineId\": 20021, \"voicelineType\": \"2001\"}, {\"title\": \"关于班尼特自己·坏运气\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_idle2\", \"description\": \"没有传说中那么夸张啦，不过就是走路经常会掉进猎人打猎用的坑里，或者被突然倒下的树干砸到脑袋，都很平常嘛，对吧？\", \"voicelineId\": 20022, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·搭档\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_close\", \"description\": \"哈哈，不行的，「班尼冒险团」早就满员了…合适的人选有那么多，没必要找我这个倒霉蛋吧？\", \"voicelineId\": 20023, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·分工\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_close1\", \"description\": \"以后我负责引走怪物和激活陷阱，你就负责带走宝藏。啊，这样不行吗？哎呀，没事没事！不用担心我会受伤啦，这是我最擅长的！而且为了你的话，我愿意！\", \"voicelineId\": 20024, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·险境\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_close2\", \"description\": \"我终于明白你为什么找我搭档了，你和我很像，一定也很喜欢置身于险境的那种快感吧！冒险就是因为有危险才让人欲罢不能啊。\", \"voicelineId\": 20025, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_pendant\", \"description\": \"没想到我这么倒霉的人也可以获得神的认可，既然神都没有放弃我，我又怎么能放弃我自己呢？\", \"voicelineId\": 20026, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_share\", \"description\": \"有机会要和我一起去俯瞰蒙德的夜景吗？蒙德城灯火通明，果酒湖反射着月光，特别漂亮…你问我在哪里看到的？哈哈，有一次不小心被龙卷风卷到了特别高的地方…什么？不想去啊，哦，好吧…\", \"voicelineId\": 20027, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_pref_gift\", \"description\": \"其实我很喜欢卷心菜，看上去很普通，却是一般人家必不可少的食物。它能生长在很多地方，也能和很多食材搭配，还从不抢味道。其实普通一点，也挺好的嘛。\", \"voicelineId\": 20028, \"voicelineType\": \"3003\"}, {\"title\": \"关于芭芭拉…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_teammate_barbara_01\", \"description\": \"她很擅长唱歌跳舞！我冒险不顺的时候就会去看她的演出，跟着观众一起喊喊口号加加油，心情就变好了，真的很神奇！这就是她为什么这么受欢迎的原因吧…啊，我这个当团长的，要是也这么受欢迎就好了。\", \"voicelineId\": 20029, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_teammate_klee_01\", \"description\": \"那个孩子啊…很可爱，但我必须和她保持距离。只要我陪她玩，她的那些炸弹就会突然爆炸…我倒霉一点无所谓，但要是炸伤了可莉就麻烦了，估计整个骑士团都会跟我没完吧。\", \"voicelineId\": 20030, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲谢尔…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_teammate_fischl_01\", \"description\": \"她是异世界来的「断罪皇女」，可厉害了！我不止一次和她说想要去她的家乡冒险，但每次说到这里她就吞吞吐吐的…嗯，一定是担心我的安危吧，看来她的家乡真的是很凶险的地方。\", \"voicelineId\": 20031, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_teammate_qin_01\", \"description\": \"我本来想向琴团长要一些对蒙德的冒险家协会的支援，但其实我不太知道要怎么和她说…冒险家协会没有骑士团那么多规矩，我和老爹们成天也嘻嘻哈哈的，但用这种态度和琴团长说话，肯定不行吧…我是不是要学一下骑士团敬礼的方式？\", \"voicelineId\": 20032, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_teammate_varka_01\", \"description\": \"他是我非常崇拜的人，名副其实的大团长！能领导整个西风骑士团，那该有多厉害啊。不过后来我想了想，冒险团规模太大好像也不行，团里太忙了的话，老爹们就没人照顾了。哈哈，还是现在好啊。\", \"voicelineId\": 20033, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷泽…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_teammate_razor_01\", \"description\": \"你说奔狼领的那个小哥哥啊，他虽然看上去凶巴巴的，也不愿意说话…但是是个有趣的人哦！他和我都特别喜欢吃肉，我给他做肉吃，他教我狼怎么说话，哈哈，你下次要不要一起来？\", \"voicelineId\": 20034, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_teammate_ambor_01\", \"description\": \"哦哦，想起来了，那个女孩子，总横冲直撞的…她和我一样，经常去野外冒险！只不过…只要路边架着锅，就总会飘来浓浓的黑烟，还有什么东西烧糊了的味道…唔，难道她的运气也很差？\", \"voicelineId\": 20035, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于诺艾尔…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_teammate_noel_01\", \"description\": \"你说她啊，其实我注意她很久了。她很有天分，又特别努力，但在骑士团只能当女仆，一直没成为正式的骑士，你不觉得太可惜了吗？唉，要是她肯来冒险家协会，估计早就是个了不起的冒险家了。\", \"voicelineId\": 20036, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解班尼特·其一\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_friendship_01\", \"description\": \"什么，想要了解我？哈哈，我只是个普普通通的倒霉冒险家，和你的各种传奇经历相比，简直不值一提啊。\", \"voicelineId\": 20037, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解班尼特·其二\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_friendship_02\", \"description\": \"「老爹们」…这是我对蒙德的老冒险家们的叫法，听说我是他们在非常险恶的绝境中捡到的孤儿。很奇妙对吧？明明我的运气这么差，居然能被人捡到还活到了现在，简直是奇迹啊。\", \"voicelineId\": 20038, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解班尼特·其三\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_friendship_03\", \"description\": \"你看出来了啊…呵呵，没错，「班尼冒险团」很久之前就只有我一个人了。因为我很倒霉，无论是多么简单安全的冒险都会变得险象环生，没人愿意跟着这样的团长…你也会这么想吗？\", \"voicelineId\": 20039, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解班尼特·其四\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_friendship_04\", \"description\": \"我的坏运气是与生俱来的，长这么大也差不多习惯了。其实换种想法，「倒霉」其实也是件好事，因为说不定哪天我的坏运气就会害死我，我才会想趁着还活着的时候，去更多的地方冒险，认识更多的人——不然，可能我就没机会认识你了，哈哈！\", \"voicelineId\": 20040, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解班尼特·其五\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_friendship_05\", \"description\": \"不知不觉，我们已经搭档很长时间了。其实我有一个梦想，等到蒙德城的冒险家协会发展成七国里最壮大的协会，我就要去周游提瓦特大陆！「班尼冒险团」会变成最伟大的冒险团，而我们，就是最伟大的两位冒险家！…你问你什么时候加入的？哎呀，这种细节不用在意嘛。\", \"voicelineId\": 20041, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"班尼特的爱好…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_pref_hobby\", \"description\": \"我什么都喜欢，但最喜欢的还是冒险！总有一天我会找到这世界上最珍贵的宝藏，到时候老爹们就都能过上好日子，蒙德的冒险家协会也会热闹起来吧！\", \"voicelineId\": 20042, \"voicelineType\": \"6001\"}, {\"title\": \"班尼特的烦恼…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_dialog_annoyed\", \"description\": \"硬要说的话…特别倒霉的日子心情会不太好，比如冒险又什么都没找到，或者老爹的身体犯老毛病了之类的，但这些都算不上烦恼，睡一觉就全忘光了。新的一天当然要有新的开始！\", \"voicelineId\": 20043, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_pref_foodLike\", \"description\": \"肉！肉是最能让人精力充沛的食物！野菇鸡肉串，烤肉排，还有甜甜花酿鸡都是我的拿手菜。和我一起冒险，是不会让你饿肚子的。\", \"voicelineId\": 20044, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_pref_foodDislike\", \"description\": \"虽然说冒险家不能挑食，但其实我不是很能吃辣，比如绝云椒椒什么的…吃了之后就喘不上气，感觉呼吸都是辣的，而且之后肯定会拉肚子…这种恶魔一样的果子究竟是怎么长出来的。\", \"voicelineId\": 20045, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_spice_pref_01\", \"description\": \"太幸福了！哈哈…哎呀！会不会把这阵子的好运全部用完了…\", \"voicelineId\": 20079, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_spice_normal_01\", \"description\": \"无论做什么都很好吃，真不愧是你啊！\", \"voicelineId\": 20080, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_spice_dislike_01\", \"description\": \"完了…肚子已经开始疼了…\", \"voicelineId\": 20081, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_pref_birthday\", \"description\": \"生日快乐！祝你新的一年也能有最好的运气！放心吧放心吧，倒霉是不会传染的，因为只要有我在，它们就不会找上你了。\", \"voicelineId\": 20046, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_starUp_01\", \"description\": \"所有力量都提升了！除了运气，哈哈。\", \"voicelineId\": 20047, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_starUp_02\", \"description\": \"这样距离你就又近了一步，我会继续努力的！\", \"voicelineId\": 20048, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_starUp_03\", \"description\": \"得到了这么强的力量，我要怎么报答你呢？对了，我知道一个藏着无价宝藏的秘境，一起去冒险吧？\", \"voicelineId\": 20049, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_bennett/vo_bennett_starUp_04\", \"description\": \"托你的福，现在的我应该有能力保护其他人了，这下子大家都会对我慢慢改观吧——那个倒霉得要命，总是遍体鳞伤的班尼特，终于变成一个可靠的冒险家了！…嘿嘿，但愿吧。\", \"voicelineId\": 20050, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_skill1_01\", \"description\": \"哈——\", \"voicelineId\": 20051, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_skill1_step1_03\", \"description\": \"烧起来吧！\", \"voicelineId\": 20052, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_skill1_step2_01\", \"description\": \"上天去吧！\", \"voicelineId\": 20053, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_skill1_step2_02\", \"description\": \"喝啊！\", \"voicelineId\": 20054, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_skill1_step3_01\", \"description\": \"炸飞你们！\", \"voicelineId\": 20055, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_skill1_step3_02\", \"description\": \"都闪开！\", \"voicelineId\": 20056, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_skill3_01\", \"description\": \"我来保护大家！\", \"voicelineId\": 20057, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_skill3_02\", \"description\": \"该总攻击了！\", \"voicelineId\": 20058, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_skill3_03\", \"description\": \"有大家在身边，伤口就不会痛！\", \"voicelineId\": 20059, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_explore_sprint_start_01\", \"description\": \"冒险、冒险！\", \"voicelineId\": 20060, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺开始·其二\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_explore_sprint_start_03\", \"description\": \"好，出发！\", \"voicelineId\": 20061, \"voicelineType\": \"700002\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_chest_open_01\", \"description\": \"是货真价实的宝藏！\", \"voicelineId\": 20062, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_chest_open_02\", \"description\": \"我居然也有这么好运的一天！\", \"voicelineId\": 20063, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_chest_open_03\", \"description\": \"简直是奇迹！\", \"voicelineId\": 20064, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_life_less30_01\", \"description\": \"糟糕…最近绷带在涨价啊！\", \"voicelineId\": 20065, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_life_less30_02\", \"description\": \"别担心…我坚持得住。\", \"voicelineId\": 20066, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_life_less30_03\", \"description\": \"绝地反击？这个我熟，让我来吧。\", \"voicelineId\": 20067, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_life_less30_teammate_01\", \"description\": \"别逞强，交给我！\", \"voicelineId\": 20068, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_life_less30_teammate_02\", \"description\": \"有本事冲我来！\", \"voicelineId\": 20069, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_life_die_01\", \"description\": \"我真是个不称职的团长…\", \"voicelineId\": 20070, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_life_die_02\", \"description\": \"不出意料的…坏运气…\", \"voicelineId\": 20071, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_life_die_03\", \"description\": \"没能突破…厄运的封锁…\", \"voicelineId\": 20072, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_hit_L_02\", \"description\": \"只是意外。\", \"voicelineId\": 20073, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_hit_H_01\", \"description\": \"痛死了。\", \"voicelineId\": 20074, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_bennett/vo_bennett_battle_hit_H_02\", \"description\": \"又没躲开…\", \"voicelineId\": 20075, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_bennett_teamJoin_01\", \"description\": \"真、真的在叫我吗？\", \"voicelineId\": 20076, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_bennett_teamJoin_02\", \"description\": \"决不拖后腿！…尽量。\", \"voicelineId\": 20077, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_bennett_teamJoin_03\", \"description\": \"太棒了！\", \"voicelineId\": 20078, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000033, 'Tartaglia', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_draw_appear\", \"description\": \"我是愚人众执行官第十一席，「公子」达达利亚。而你——哈，也是能招致纷争之人，实在愉快。我们应该会很合得来吧？\", \"voicelineId\": 23009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·闲散\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_explore_idle_01\", \"description\": \"在这干站着，也不会有对手找上门的。\", \"voicelineId\": 23010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·比试\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_explore_idle_02\", \"description\": \"嗯——附近就没有什么值得一战的强敌吗？\", \"voicelineId\": 23011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·愚人众\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_explore_idle_03\", \"description\": \"不知道其他执行官在忙些什么呢？嗯，算了，无非又是那些莫名其妙的「宏大计划」吧。\", \"voicelineId\": 23012, \"voicelineType\": \"1103\"}, {\"title\": \"闲聊·雪国故土\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_explore_idle_04\", \"description\": \"在我老家的雪原里这么闲站着的话，早该被冻僵了。哈哈哈。\", \"voicelineId\": 23013, \"voicelineType\": \"1104\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_weather_afterRain_01\", \"description\": \"雨点打在水面上的声音，会把鱼儿吓跑。相比之下，雨后是钓鱼的好时机。\", \"voicelineId\": 23014, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候·异国\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_weather_snowy_01\", \"description\": \"哈哈哈，不知老家那边，是否也在下雪？\", \"voicelineId\": 23015, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候·至冬国\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_weather_snowy_02\", \"description\": \"多好的雪！天地都和月光一样干净，在这样的舞台上泼洒的鲜血才格外炙烈。\", \"voicelineId\": 23016, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_weather_breezy_01\", \"description\": \"啊！风中传来了纷争的气息。\", \"voicelineId\": 23017, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了·异国\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_weather_gale_01\", \"description\": \"真是畅快的风！\", \"voicelineId\": 23018, \"voicelineType\": \"1205\"}, {\"title\": \"刮大风了·至冬国\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_weather_gale_02\", \"description\": \"感觉身体和头脑，都被穿过身体的风洗净了。真舒畅。\", \"voicelineId\": 23019, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_greetingMorning\", \"description\": \"哟，伙伴！今天精神不错啊。\", \"voicelineId\": 23020, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_greetingNoon\", \"description\": \"你看起来状态还不错嘛，要不陪我切磋一下？\", \"voicelineId\": 23021, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_greetingNight\", \"description\": \"哈——吃得真爽。活动活动，消化一下好了。\", \"voicelineId\": 23022, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_greetingNight2\", \"description\": \"真是愉快的一天。明天再见，伙伴！\", \"voicelineId\": 23023, \"voicelineType\": \"1004\"}, {\"title\": \"关于达达利亚自己…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_idle\", \"description\": \"身为战士，要时刻把挑战之心系于刀尖之上。但无论胜败，都是无可替代的珍贵经历。\", \"voicelineId\": 23024, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·同僚\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_close\", \"description\": \"与你同行的事情，在别的执行官当中，已经传开了吧。哼，真想看看那帮人脸上的表情，哈哈哈。\", \"voicelineId\": 23025, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·兵器\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_close1\", \"description\": \"弓，其实是我最不擅长的武器。正因如此，我才要征服它。\", \"voicelineId\": 23026, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·生存\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_close2\", \"description\": \"连神之眼也没有的你，竟有这样的力量，真是令人期待啊…在你抵达自己的极限之前，与我放下一切、决一死战之前，绝对不要倒下啊，伙伴！我绝不允许你倒下。\", \"voicelineId\": 23027, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·邀请\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_close3\", \"description\": \"伙伴，要不要加入愚人众？嗯，当我没说。以你现在的身份，和你在一起，连光明正大和其他执行官厮杀的理由也有了。这样的机会，实在无法放弃啊，哈。\", \"voicelineId\": 23028, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_pendant\", \"description\": \"只要能让我变强，「神之眼」也好，「邪眼」也好，师承深渊的罪人也好，都无所谓…\", \"voicelineId\": 23029, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_share\", \"description\": \"在无尽的雪原里，生命随时都会被碎骨一般的纯白天地吞噬，连足迹也无法留下。为此，我们每日都在与看不见的敌人战斗。\", \"voicelineId\": 23030, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_pref_gift\", \"description\": \"我曾经在世界的深渊与无名的巨大魔兽对视。总有一天，我会堂堂正正地，将那强大得令我骨髓冻结的怪物斩杀。届时，就拜托你当我的见证者了，伙伴！\", \"voicelineId\": 23031, \"voicelineType\": \"3003\"}, {\"title\": \"关于丝柯克…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_skirk_01\", \"description\": \"有多少年没见到师父了呢。哼，下次和她比试的时候，希望至少能逼她用上双手来对付我。\", \"voicelineId\": 23032, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离·掂量\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_zhongli_01\", \"description\": \"那家伙城府很深，不知真正的实力又如何呢…哼，真令人期待。\", \"voicelineId\": 23033, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离·挑战\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_zhongli_02\", \"description\": \"钟离先生，最近可好啊？嗯…还不错？看来他倒是挺适应作为「凡人」的生活嘛。可恶…竟然把我骗得团团转，只有痛痛快快地交战一场才能平息这份不甘！\\n你说…我打不过他？哈哈哈…\", \"voicelineId\": 23034, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「女皇」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_barnabas_01\", \"description\": \"女皇大人其实很温柔。但正是因为太温柔了，所以才不得不变得冷酷。正是因为梦想和平，才要向整个世界宣战。也正是因为她与世界为敌，我才有机会与你相识。\", \"voicelineId\": 23035, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_varka_01\", \"description\": \"法尔伽吗？哼，光是想到，有朝一日能和西风骑士团的顶点、传说中的「北风骑士」交手，就兴奋得颤抖。活在这个世界上，真是美妙。\", \"voicelineId\": 23036, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「丑角」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_pierro_01\", \"description\": \"他是愚人众最初的执行官，也是今日执行官们的领袖，只会在大场面出现。至于他的功绩…坦白说，我不关心。我效忠的对象是女皇大人。\", \"voicelineId\": 23078, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「队长」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_capitano_01\", \"description\": \"我曾见过他在战场上的模样，实在是过于强悍了。或许我的席位太靠后了吧，让他没有留意到我。但就算今天被他忽视，明天，我也会让他看到我的实力。\", \"voicelineId\": 23079, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「博士」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_dottore_01\", \"description\": \"听说他把不同年龄段的自己切片做成了义体，负责不同的任务。没办法，我的同僚都是些不太正常的人。反过来想想，要是某一天，我遇见了自己的义体…哈，肯定得和对方决出真正能活下去的那一个。\", \"voicelineId\": 23080, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「少女」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_columbina_01\", \"description\": \"愚人众执行官的席位是按照实力划分的，我不明白那个女孩为什么是「第三席」。有机会的话，我是想和排在我之前的执行官都比试一遍啦，但总有种不太想和她交手的感觉…不管怎么说，你也小心一点。\", \"voicelineId\": 23081, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「仆人」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_arlecchino_01\", \"description\": \"我不讨厌有自己打算的人。毕竟我加入愚人众，也是为了获得更多争斗的机会。但这个人，我不喜欢。如果背叛能够获得收益，她会毫不留情地向女皇大人挥剑。她的眼里只有疯狂。\", \"voicelineId\": 23082, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「公鸡」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_pulcinella_01\", \"description\": \"我不懂什么人情世故。但我知道，他是真心想要帮助我的。他看我的眼神，就像看待家人一样。哦，说到这个，冬妮娅和托克给我回信的时候，时常提到他送去家里的馅饼和礼物。在我暂别冬都期间，他确实按照约定，照顾好了我的家人们。\", \"voicelineId\": 23083, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「木偶」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_sandrone_01\", \"description\": \"好像是个埋头研究的人？我想想，那些机械是不是都跟她有关啊。总之，仅有几次的见面中，她一副想杀了我的眼神。可我完全不记得做过什么惹她生气的事。\", \"voicelineId\": 23084, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「富人」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_pantalone_01\", \"description\": \"哦，那个满脑子「宏大计划」的野心家。他的那些理论，我半句都听不进去啊。总之，只要后备资金管够就好啦。\", \"voicelineId\": 23085, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「女士」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_signora_01\", \"description\": \"我和她合不来，你是知道的。如今也不必评价她本人了吧。对于执行官而言，死期并不掌握在自己手上…不过，放心，我是无论如何，都会拼尽全力活下去的。\", \"voicelineId\": 23086, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「散兵」…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_teammate_scaramouche_01\", \"description\": \"他带着「神之心」与我们失去了联络，后面才有了追回那颗心的行动。我倒是不介意去四处走走，说不定还能在哪儿和你偶遇？\", \"voicelineId\": 23087, \"voicelineType\": \"4015\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解达达利亚·其一\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_friendship_01\", \"description\": \"记住了，伙伴，我是终有一天要征服世界的人！\", \"voicelineId\": 23037, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解达达利亚·其二\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_friendship_02\", \"description\": \"无论决斗的对手是神，还是深渊的魔兽，只要有形，就有得胜的可能。但执行官当中，有的人热衷于权术、阴谋那些…「看不见的手段」。我跟那些无聊的家伙合不来。\", \"voicelineId\": 23038, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解达达利亚·其三\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_friendship_03\", \"description\": \"这里的天空和故乡的天空是连成一片的。抬头看见雪一样的月光，就能想到，老家的人们也能看见同一个月亮。不知道弟弟妹妹…哈，他们有没有变成出色的战士呢？\", \"voicelineId\": 23039, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解达达利亚·其四\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_friendship_04\", \"description\": \"伙伴，不要忘记：厮杀的时候，绝不能用什么「燃烧起来了」之类的蠢话来驱策自己。毕竟，燃尽之后，除了灰烬，什么也不会剩下。无论如何，都要活下去。\", \"voicelineId\": 23040, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解达达利亚·其五\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_friendship_05\", \"description\": \"时间过得真快。总有一天，我要让你亲眼看见我征服世界的样子、我把神的王座踩在脚下的样子。哈哈，在那之前，你可绝对不要倒下啊，伙伴！\", \"voicelineId\": 23041, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"达达利亚的爱好…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_pref_hobby\", \"description\": \"冰钓和决斗的道理是相通的，关键是耐心与决断。这么说来，同样的道理好像也能应用在人生中的所有事情上？\", \"voicelineId\": 23042, \"voicelineType\": \"6001\"}, {\"title\": \"达达利亚的烦恼…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_dialog_annoyed\", \"description\": \"嗯？烦恼的事情…哼，与你同行，总是有值得挑战的强敌，根本没空思考这种琐碎无趣的小事。\", \"voicelineId\": 23043, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_pref_foodLike\", \"description\": \"这个世界上，充满了美妙的料理和酣畅淋漓的战斗。活着真是美妙！\", \"voicelineId\": 23044, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_pref_foodDislike\", \"description\": \"食物和武器是一样的。真正的战士不会挑剔兵器，也不会挑剔食物。你也不要挑食啊。\", \"voicelineId\": 23045, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_spice_pref_01\", \"description\": \"只要吃到好吃的，心情就会十分舒畅。我该如何回报你呢？\", \"voicelineId\": 23088, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_spice_normal_01\", \"description\": \"你的厨艺似乎长进了不少。难道你也在不断变强吗？\", \"voicelineId\": 23089, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_spice_dislike_01\", \"description\": \"真是出乎意料的口感，好…我就再试一次吧。\", \"voicelineId\": 23090, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_pref_birthday\", \"description\": \"哟，伙伴，生日快乐！有什么想痛打一顿的人吗？有的话，就尽管说出来吧！\", \"voicelineId\": 23046, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_starUp_01\", \"description\": \"喔！好像变强了一些。找谁试试好了…\", \"voicelineId\": 23047, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_starUp_02\", \"description\": \"「战士的力量就像一个圆。圆越大，能挑战的人就越多。」欸，这句话是谁说的来着…\", \"voicelineId\": 23048, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_starUp_03\", \"description\": \"真不错！伙伴，多亏了你，我离「征服世界」的目标又近了一步。就连女皇大人，也不曾料想过我这样的成长吧。\", \"voicelineId\": 23049, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_tartaglia/vo_tartaglia_starUp_04\", \"description\": \"伙伴，你也要好好锻炼自己才行！不然的话，等我到达了世界的顶点，又有谁能与我殊死厮杀呢？哈哈哈。\", \"voicelineId\": 23050, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_skill1_01\", \"description\": \"要上了！\", \"voicelineId\": 23051, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_skill1_02\", \"description\": \"哈！\", \"voicelineId\": 23052, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_skill1_03\", \"description\": \"势如狂澜！\", \"voicelineId\": 23053, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_skill1_04\", \"description\": \"来吧！\", \"voicelineId\": 23054, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_skill1_05\", \"description\": \"接下来——\", \"voicelineId\": 23055, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_skill1_06\", \"description\": \"呼——\", \"voicelineId\": 23056, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_skill3_01\", \"description\": \"一箭止水！\", \"voicelineId\": 23057, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_skill3_02\", \"description\": \"逃得掉吗！\", \"voicelineId\": 23058, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_skill3_03\", \"description\": \"破绽，稍纵即逝！\", \"voicelineId\": 23059, \"voicelineType\": \"200003\"}, {\"title\": \"元素爆发·其四\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_skill3_04\", \"description\": \"忍着点，这可是很痛的。\", \"voicelineId\": 23060, \"voicelineType\": \"200004\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_explore_sprint_start_03\", \"description\": \"兵贵神速。\", \"voicelineId\": 23061, \"voicelineType\": \"700001\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_explore_fly_start_02\", \"description\": \"呵，感觉不错。\", \"voicelineId\": 23062, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_chest_open_01\", \"description\": \"好！再去寻找更多的宝藏吧！\", \"voicelineId\": 23063, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_chest_open_02\", \"description\": \"相当不错！\", \"voicelineId\": 23064, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_chest_open_03\", \"description\": \"真让人摩拳擦掌！\", \"voicelineId\": 23065, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_life_less30_01\", \"description\": \"哈！有点意思。\", \"voicelineId\": 23066, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_life_less30_02\", \"description\": \"不赖嘛！\", \"voicelineId\": 23067, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_life_less30_03\", \"description\": \"生死边缘而已，我很擅长处理。\", \"voicelineId\": 23068, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_life_less30_teammate_01\", \"description\": \"你们，最近是不是缺乏锻炼啊？\", \"voicelineId\": 23069, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_life_less30_teammate_02\", \"description\": \"闪开！这里让我来！\", \"voicelineId\": 23070, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_life_die_01\", \"description\": \"怎能这样…得而复失…\", \"voicelineId\": 23071, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_life_die_02\", \"description\": \"失手了…\", \"voicelineId\": 23072, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_life_die_03\", \"description\": \"还挺…有两下子…\", \"voicelineId\": 23073, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_tartaglia/vo_tartaglia_battle_hit_H_01\", \"description\": \"嘁！大意了。\", \"voicelineId\": 23074, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_tartaglia_teamJoin_01\", \"description\": \"哈，强敌何在？\", \"voicelineId\": 23075, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_tartaglia_teamJoin_02\", \"description\": \"睁大眼睛看着吧！\", \"voicelineId\": 23076, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_tartaglia_teamJoin_03\", \"description\": \"真让我好等！\", \"voicelineId\": 23077, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000034, 'Noelle', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_draw_appear\", \"description\": \"我是诺艾尔，西风骑士团的女仆，从今天起会陪你一起去冒险。如果遇到任何困扰或者麻烦，不用担心，我都会尽全力帮你解决的。嗯，现在就可以哦。\", \"voicelineId\": 21009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·帮忙\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_explore_idle_01\", \"description\": \"交给我吧！什么都可以交给我！——对了，你要拜托我做什么来着？我还没来得及听…\", \"voicelineId\": 21010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·休息\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_explore_idle_02\", \"description\": \"有点累了吗？那就在这里休息吧，我去为你沏茶，要全糖、半糖，还是无糖？\", \"voicelineId\": 21011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·可靠\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_explore_idle_03\", \"description\": \"只要你需要我，我随时都会出现在你的身边。\", \"voicelineId\": 21012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_weather_heavyRain_01\", \"description\": \"糟了，大家的衣服还晾在外面！我能不能现在回去收拾一下？\", \"voicelineId\": 21013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_weather_thunder_01\", \"description\": \"遇到打雷还是待在屋子里比较好哦，如果有非出门不可的事，就交给我吧。\", \"voicelineId\": 21014, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_weather_sunny_01\", \"description\": \"天气晴朗，不如做一些和「阳光」有关的事吧。欸？具体一点…只要能让你的心情也变得晴朗的事，都可以。\", \"voicelineId\": 21015, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_weather_breezy_01\", \"description\": \"听见了吗？是风神的声音。每到我心烦意乱的时候，听见风声就能平静下来。\", \"voicelineId\": 21016, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_greetingMorning\", \"description\": \"早上好，早餐已经做好了哦。我就待在你身边，如果哪里不合口味，请随时告诉我。\", \"voicelineId\": 21017, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_greetingNoon\", \"description\": \"想要坐下来喝杯茶吗？我去为你准备。对了，我还顺手准备了厚云朵松饼，是我的拿手菜哦，请一定要尝一尝。\", \"voicelineId\": 21018, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_greetingNight\", \"description\": \"晚上是大家的休息时间，也是我最忙的时候…安柏洗好的发带放在哪了？凯亚新买的眼罩有几套？我会全部记住的，这是女仆的责任。\", \"voicelineId\": 21019, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_greetingNight2\", \"description\": \"今天的冒险辛苦你了，请去休息吧。我还要回骑士团一趟…欸？要我守候你入睡吗？…唔…倒是没什么问题，不过…不是在捉弄我吧？\", \"voicelineId\": 21020, \"voicelineType\": \"1004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于诺艾尔自己·自律\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_idle\", \"description\": \"我只是每天都做同样的事，和真正的骑士比起来还差远了…但这是通往骑士之路的修行，修行可不能只是嘴上说说而已啊。\", \"voicelineId\": 21021, \"voicelineType\": \"2001\"}, {\"title\": \"关于诺艾尔自己·分歧\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_idle2\", \"description\": \"我有点不太擅长和别人争辩，很多时候说不清道理，还会惹别人生气，所以我就会先按我的想法去做，结果又被人说是「固执」了…我只是想用结果说服他而已，这也是「固执」吗？\", \"voicelineId\": 21022, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·身份\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_close\", \"description\": \"我的奉献是出于自由的奉献，「女仆」在我看来就是最自由的身份。厨师、园丁、战士、向导…你需要我是什么，我就是什么！\", \"voicelineId\": 21023, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·叮嘱\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_close1\", \"description\": \"就算再怎么仓促，一日三餐也不能应付，不可以吃来历不明的东西，也不能光吃肉不吃蔬菜。对了，尽量不要喝冷水，对胃不好…唔，你不会在想「因为太麻烦所以还是交给诺艾尔」吧？唔唔…如果你真的这么想…好吧，还是交给我来吧！\", \"voicelineId\": 21024, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·欢迎会\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_close2\", \"description\": \"我听说了，你成为了西风骑士团的荣誉骑士，真是羡慕啊…那今后你就是我的前辈了。对了，应该为你举办一场热闹的欢迎会！我现在就去准备！\", \"voicelineId\": 21025, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [38406], \"unlockText\": \"完成「为了没有眼泪的明天」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_pendant\", \"description\": \"说实话，有些失望…虽然这「神之眼」象征神明对我的肯定，但为什么不是「风」，而是与风的性质相差最远的「岩」呢？我觉得最适合西风骑士团的元素，毕竟还是…\", \"voicelineId\": 21026, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_share\", \"description\": \"其实我很喜欢闻酒的味道，可是现在的我还没到喝酒的年纪…虽然不止一次有偷偷尝的机会，但我都忍住了，还是把这份神秘感保留到我成年的那一天吧。\", \"voicelineId\": 21027, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_pref_gift\", \"description\": \"女仆要严守秘密，所以我很喜欢玫瑰，玫瑰在蒙德就代表「守口如瓶」，它总是能提醒我…欸？在你的家乡，玫瑰代表「爱情」吗？…居、居然还有这么火热的含义啊…\", \"voicelineId\": 21028, \"voicelineType\": \"3003\"}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_teammate_ambor_01\", \"description\": \"她是我非常尊敬的前辈，实力很强不说，对人也很亲切。她还教我怎么做「兔兔伯爵」，你看，我会把它当成护身符带在身边，做得不错吧？\", \"voicelineId\": 21029, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_teammate_klee_01\", \"description\": \"我一直很想知道，她还这么小，是怎么正式成为骑士的。有一次向她请教经验，她还没听完我的话，就拉着我去骑士团外面玩炸弹…我以为这是什么修行，结果最后我和她都被琴团长关了禁闭…\", \"voicelineId\": 21030, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_teammate_qin_01\", \"description\": \"琴团长一直都是我的榜样，我的实力和认真程度完全比不上她。她对别人就像对自己一样严格，所以如果有一天我能得到她的认可，那也是对我一直以来努力的最大肯定了。在那之前，我都是不会松懈的！\", \"voicelineId\": 21031, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_teammate_varka_01\", \"description\": \"本来我想跟着他的队伍一起去冒险，履行女仆的责任，但大团长说我留在蒙德他才不会有后顾之忧…大团长这么器重我，我特别开心！虽然后来我知道大团长不只对我一个人说了这句话，不过…器重就是器重嘛。\", \"voicelineId\": 21032, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_teammate_kaeya_01\", \"description\": \"他很神秘，来如影，去如风，每天都有很重要的任务要去处理。他还经常会给我安排一些小任务，就好像我已经是他的小队成员了一样…嗯？只是跑腿？不不不，虽然确实是跑腿，可是我很珍惜的！\", \"voicelineId\": 21033, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于班尼特…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_teammate_bennett_01\", \"description\": \"他不止一次来邀请我，说什么比起骑士团，还是冒险家协会更适合我…虽然我是会像一个普通的冒险家一样，帮他照顾他的老爹们，但…骑士团对我来说有特别的意义，而且我也不想认输…嗯，果然还是没法答应。\", \"voicelineId\": 21034, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲谢尔·茶点\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_teammate_fischl_02\", \"description\": \"她好像是从别的世界来的，其他的我也不清楚…不过她好像很喜欢骑士团的图书馆，总是在那里看书。我打扫的时候会送去一些热乎乎的茶点，她每次都会感谢我，还会说很多听不明白，但都很夸张的话…\", \"voicelineId\": 21035, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲谢尔·身世\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_teammate_fischl_01\", \"description\": \"以前我打扫图书馆的时候，记得有本书叫《菲谢尔皇女夜谭》，我还以为只是幻想小说…但没想到，里面的主人公居然真的存在！能有一本自己的传记，她一定很厉害吧。\", \"voicelineId\": 21036, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芭芭拉…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_teammate_barbara_01\", \"description\": \"我们经常在一起喝茶，有时候她会轻轻哼出很好听的调子，告诉我灵感来了。虽然我对音乐给不出什么实用的建议…但能跟芭芭拉享受这样的时光，我真的非常高兴！\", \"voicelineId\": 21037, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解诺艾尔·其一\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_friendship_01\", \"description\": \"是需要我帮忙吗？哦…只是想和我聊聊天，好吧，如果这就算帮上了你的忙，那想聊多久都可以。\", \"voicelineId\": 21038, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解诺艾尔·其二\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_friendship_02\", \"description\": \"没关系，什么样的事都可以交给我，不用照顾我的感受的…欸？那不是「女仆」而是「工具」？唔…工具做了很多事也不一定会开心吧，但我为你做的每件事，我都很有成就感哦。\", \"voicelineId\": 21039, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解诺艾尔·其三\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_friendship_03\", \"description\": \"这、这些点心是送给我的吗？不不不，这怎么好意思呢？那…那我也要做很多点心作为回报！我现在就去，马上就去！半个小时…呜，最多一个小时就做好了。你可以先去做别的事，茶点很快就会热乎乎地端到你的面前！\", \"voicelineId\": 21040, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解诺艾尔·其四\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_friendship_04\", \"description\": \"我每天做的都是一些琐碎的小事，但只要这些小事能帮到你的冒险、你的生活，我就会很开心…因为你的道谢，会让我觉得这些小事，也都有小小的意义。\", \"voicelineId\": 21041, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解诺艾尔·其五\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_friendship_05\", \"description\": \"我是为骑士团服务的女仆，也一直想要帮到更多人的忙。但不知不觉，用在你身上的时间已经变得越来越多了…唉，像我这样自私的做法，是不是…不太好？\", \"voicelineId\": 21042, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"诺艾尔的爱好…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_pref_hobby\", \"description\": \"爱好吗？我最喜欢洗各种各样的东西，洗衣服，洗地板，洗窗户，看到脏东西变干净我就会特别有成就感…欸？是指「休息时的爱好」？我想想…嗯，果然还是洗东西！\", \"voicelineId\": 21043, \"voicelineType\": \"6001\"}, {\"title\": \"诺艾尔的烦恼…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_dialog_annoyed\", \"description\": \"该怎么用最少的预算、采购到最多最好的物资呢…我试过一个人跑去璃月比对所有商铺的价格、再一个人把东西全都搬回来…但那次花的时间太长，琴团长差点以为我在路上被风魔龙吃掉了…\", \"voicelineId\": 21044, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_pref_foodLike\", \"description\": \"当然是「满足沙拉」，蒙德的自然水土汇于一盘，营养均衡，热量也不会超标…你问吃不腻吗？当然不会，很好吃的！我已经吃了十年了。\", \"voicelineId\": 21045, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_pref_foodDislike\", \"description\": \"我不挑食！但有一种情况会让我比较头疼…宴会上的一大桌菜，作为女仆，每一道菜都必须自己先尝一尝。但这样一口接一口…唉，太罪恶了。\", \"voicelineId\": 21046, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_spice_pref_01\", \"description\": \"能把普通的菜肴做得那么好吃…我对你的钦佩，又多了一些！\", \"voicelineId\": 21075, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_spice_normal_01\", \"description\": \"味道真好。我也要向你学习！再怎么说，这也是女仆的职责…\", \"voicelineId\": 21076, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_spice_dislike_01\", \"description\": \"热量…会不会已经超过一整天的份额了…\", \"voicelineId\": 21077, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_pref_birthday\", \"description\": \"每天都忙于冒险，是不是积压了很多琐事来不及处理？今天我就是你的专属女仆，全都交给我吧！还有…在这最棒的一天，祝你生日快乐！\", \"voicelineId\": 21047, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_starUp_01\", \"description\": \"这就是…新的力量？谢谢你，这样我就能帮到更多人了。\", \"voicelineId\": 21048, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_starUp_02\", \"description\": \"还不能满足，在成为正式的西风骑士之前，我都要加倍努力。\", \"voicelineId\": 21049, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_starUp_03\", \"description\": \"多亏了能和你一起冒险，我才获得了这么多的成长。明明女仆的职责是为你排忧解难，结果反倒是让你为我花了这么多心思…\", \"voicelineId\": 21050, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_noel/vo_noel_starUp_04\", \"description\": \"蒙德城的大家都说我变得比以前更可靠了，还说我马上就能成为真正的西风骑士了，但其实我…什么？你也这么觉得？呃…谢谢你能这么说，这是对我最好的夸奖！\", \"voicelineId\": 21051, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_battle_skill1_01\", \"description\": \"岩石的重量，令人安心。\", \"voicelineId\": 21052, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_battle_skill1_02\", \"description\": \"一定要干净利落。\", \"voicelineId\": 21053, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_battle_skill1_03\", \"description\": \"交给我吧。\", \"voicelineId\": 21054, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_battle_skill3_01\", \"description\": \"该打扫战场了。\", \"voicelineId\": 21055, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_battle_skill3_02\", \"description\": \"我会注意骑士的风度。\", \"voicelineId\": 21056, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_battle_skill3_03\", \"description\": \"我会注意女仆的礼仪。\", \"voicelineId\": 21057, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_explore_sprint_start_01\", \"description\": \"应该赶得上。\", \"voicelineId\": 21058, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺开始·其二\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_explore_sprint_start_02\", \"description\": \"还有人需要帮忙。\", \"voicelineId\": 21059, \"voicelineType\": \"700002\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_chest_open_01\", \"description\": \"心满意足。\", \"voicelineId\": 21060, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_chest_open_02\", \"description\": \"真高兴…\", \"voicelineId\": 21061, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_chest_open_03\", \"description\": \"这些宝藏积灰了，先清洗一下！\", \"voicelineId\": 21062, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_life_less30_01\", \"description\": \"没关系，轻伤而已。\", \"voicelineId\": 21063, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_life_less30_02\", \"description\": \"唔，衣服都弄脏了…\", \"voicelineId\": 21064, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_life_less30_03\", \"description\": \"我不会退缩的。\", \"voicelineId\": 21065, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_life_less30_teammate_01\", \"description\": \"别动，小心伤口，我来治疗！\", \"voicelineId\": 21066, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_life_less30_teammate_02\", \"description\": \"交给我吧！换我来！\", \"voicelineId\": 21067, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_life_die_01\", \"description\": \"让骑士团…蒙羞了…\", \"voicelineId\": 21068, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_life_die_02\", \"description\": \"我还想…保护大家…\", \"voicelineId\": 21069, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_life_die_03\", \"description\": \"再见了…主人…\", \"voicelineId\": 21070, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_noel/vo_noel_battle_hit_H_02\", \"description\": \"唔…失态了。\", \"voicelineId\": 21071, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_noel_teamJoin_01\", \"description\": \"真高兴…啊、嗯。\", \"voicelineId\": 21072, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_noel_teamJoin_02\", \"description\": \"一定会保护你。\", \"voicelineId\": 21073, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_noel_teamJoin_03\", \"description\": \"嗯，如你所愿。\", \"voicelineId\": 21074, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000035, 'Qiqi', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_draw_appear\", \"description\": \"我是七七，是个僵尸…啊，还要说什么来着。\", \"voicelineId\": 24009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·自言自语\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_explore_idle_01\", \"description\": \"咦，刚刚…我想说什么来着…\", \"voicelineId\": 24010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·怕热\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_explore_idle_02\", \"description\": \"想去凉快点的地方。\", \"voicelineId\": 24011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·锻炼\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_explore_idle_03\", \"description\": \"七二三四，七二三四…五六七七，五六七七…\", \"voicelineId\": 24012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_weather_heavyRain_01\", \"description\": \"又忘记带伞了。\", \"voicelineId\": 24013, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_weather_snowy_01\", \"description\": \"想堆雪人…可以陪我吗？\", \"voicelineId\": 24014, \"voicelineType\": \"1202\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_weather_sunny_01\", \"description\": \"今天不该出门的。\", \"voicelineId\": 24015, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_weather_breezy_01\", \"description\": \"凉凉的，很舒服。\", \"voicelineId\": 24016, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_weather_gale_01\", \"description\": \"拉手…拉手！要、要被吹跑了！…\", \"voicelineId\": 24017, \"voicelineType\": \"1205\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_dialog_greetingMorning\", \"description\": \"早上了吗？今天要做的是…我看看笔记。\", \"voicelineId\": 24018, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_dialog_greetingNoon\", \"description\": \"…忘记帮白先生分拣药材了。\", \"voicelineId\": 24019, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_dialog_greetingNight\", \"description\": \"晚上好。今天…我做了什么来着…\", \"voicelineId\": 24020, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_dialog_greetingNight2\", \"description\": \"你先休息吧，我该去做柔软体操了…不要偷看。\", \"voicelineId\": 24021, \"voicelineType\": \"1004\"}, {\"title\": \"关于七七自己…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_dialog_idle\", \"description\": \"你问我吗…？对不起，我不记得了…\", \"voicelineId\": 24022, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·记忆力\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_dialog_close\", \"description\": \"很多事情我都记不起来了，但是…也没什么不好。\", \"voicelineId\": 24023, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·记忆力锻炼\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_dialog_close1\", \"description\": \"最近我努力做了很多记忆力锻炼，所以不用担心我会忘记你了。\", \"voicelineId\": 24024, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_dialog_pendant\", \"description\": \"「神之眼」，虽然无法停住时间，但是给了我守护重要之人的力量。\", \"voicelineId\": 24025, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_dialog_share\", \"description\": \"其实我的身体状况比白先生好很多…\", \"voicelineId\": 24026, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_pref_gift\", \"description\": \"药庐附近有时候会有小团雀出没，小小的一团。\", \"voicelineId\": 24027, \"voicelineType\": \"3003\"}, {\"title\": \"关于白术…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_teammate_baizhu_01\", \"description\": \"我记不起来白先生的脸了，但是也没什么关系…\", \"voicelineId\": 24028, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_teammate_hutao_01\", \"description\": \"高温、假笑和死亡…讨厌。\", \"voicelineId\": 24029, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈·名字\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_teammate_xiao_01\", \"description\": \"唔，听起来像老古董…\", \"voicelineId\": 24030, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈·记忆\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_teammate_xiao_02\", \"description\": \"我见过他吗…？\", \"voicelineId\": 24031, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于辛焱…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_teammate_xinyan_01\", \"description\": \"…是谁？\", \"voicelineId\": 24032, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于瑶瑶…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_teammate_yaoyao_01\", \"description\": \"可爱…像小团雀。\", \"voicelineId\": 24033, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于小冥…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_teammate_duskyMing_01\", \"description\": \"晚上…偶尔会感觉到有人和我一起做体操…是错觉吗？\", \"voicelineId\": 24034, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解七七·其一\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_friendship_01\", \"description\": \"有什么事吗？\", \"voicelineId\": 24035, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解七七·其二\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_friendship_02\", \"description\": \"柔软体操，让我能够保持和人类一样的身体状态。但是如果放松下来的话，就会变回去…\", \"voicelineId\": 24036, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解七七·其三\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_friendship_03\", \"description\": \"有的人想要利用我，有的人很害怕我。但是你…和他们都不一样。\", \"voicelineId\": 24037, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解七七·其四\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_friendship_04\", \"description\": \"从第一次见面开始，你就给我一种很温暖的感觉。和让人不舒服的热不一样，是我的心，感觉到了温暖。谢谢你…我很高兴。可惜我只认识现在的你，如果以后我忘记了…我们就…不，我会「命令」自己记住你。\", \"voicelineId\": 24038, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解七七·其五\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_friendship_05\", \"description\": \"以前我只想要活下去，虽然不知道为了什么活下去…但现在我好像知道了，以后想要和你一起活下去。我、我们可以…永远一直在一起吗？啊…真的可以吗？嗯！我会保护好你的！\", \"voicelineId\": 24039, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"七七的爱好…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_pref_hobby\", \"description\": \"想要一只小宠物…小团雀那样子的。\", \"voicelineId\": 24040, \"voicelineType\": \"6001\"}, {\"title\": \"七七的烦恼…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_dialog_annoyed\", \"description\": \"我不明白，但是，温度高会让身体很难受…\", \"voicelineId\": 24041, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_pref_foodLike\", \"description\": \"喜欢椰奶。但是…尝不出味道。\", \"voicelineId\": 24042, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_pref_foodDislike\", \"description\": \"对不起，我不知道…\", \"voicelineId\": 24043, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_spice_pref_01\", \"description\": \"凉凉的，很喜欢。虽然没有味道…\", \"voicelineId\": 24076, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_spice_normal_01\", \"description\": \"唔…\", \"voicelineId\": 24077, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_spice_dislike_01\", \"description\": \"有点烫…\", \"voicelineId\": 24078, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_pref_birthday\", \"description\": \"生辰快乐。给，草药香囊。很惊讶吗？上次你告诉我的时候，我就记在纸上了。每天都看一遍的话，今后也不会忘记的…\", \"voicelineId\": 24044, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_starUp_01\", \"description\": \"啊，变强了吗…变强，是什么呢？\", \"voicelineId\": 24045, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_starUp_02\", \"description\": \"啊，理解了。变强之后，控制力量需要更多的精力了。\", \"voicelineId\": 24046, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_starUp_03\", \"description\": \"以前我对更加强大并没有概念，但是现在…我希望能够再强一点。\", \"voicelineId\": 24047, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_qiqi/vo_qiqi_starUp_04\", \"description\": \"这一切都是因为你在，谢谢你…可以答应我一个愿望吗？今后…就让我来保护你吧，好不好？\", \"voicelineId\": 24048, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_battle_skill1_01\", \"description\": \"流转不息。\", \"voicelineId\": 24049, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_battle_skill1_02\", \"description\": \"生生不绝。\", \"voicelineId\": 24050, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_battle_skill1_03\", \"description\": \"去。\", \"voicelineId\": 24051, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_battle_skill1_04\", \"description\": \"起。\", \"voicelineId\": 24052, \"voicelineType\": \"100004\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_battle_skill3_01\", \"description\": \"听诏，宣此诰命。\", \"voicelineId\": 24053, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_battle_skill3_02\", \"description\": \"真名，度厄真君。\", \"voicelineId\": 24054, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_battle_skill3_03\", \"description\": \"玉签，仙法开匣。\", \"voicelineId\": 24055, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_explore_sprint_start_01\", \"description\": \"要更快一点吗？\", \"voicelineId\": 24056, \"voicelineType\": \"700001\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_explore_fly_start_01\", \"description\": \"欸？\", \"voicelineId\": 24057, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_chest_open_01\", \"description\": \"好看。\", \"voicelineId\": 24059, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_chest_open_02\", \"description\": \"宝箱…有用吗？\", \"voicelineId\": 24060, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_chest_open_03\", \"description\": \"里面，是什么？不记得…\", \"voicelineId\": 24061, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_life_less30_01\", \"description\": \"痛。\", \"voicelineId\": 24062, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_life_less30_02\", \"description\": \"啊——\", \"voicelineId\": 24063, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_life_less30_03\", \"description\": \"要活下去…\", \"voicelineId\": 24064, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_life_less30_teammate_01\", \"description\": \"危险。\", \"voicelineId\": 24065, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_life_less30_teammate_02\", \"description\": \"我来吧。\", \"voicelineId\": 24066, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_life_die_01\", \"description\": \"还会...被封印吗…\", \"voicelineId\": 24067, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_life_die_02\", \"description\": \"好冷…\", \"voicelineId\": 24068, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_life_die_03\", \"description\": \"不要…\", \"voicelineId\": 24069, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_battle_hit_L_02\", \"description\": \"没感觉…\", \"voicelineId\": 24070, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_battle_hit_H_01\", \"description\": \"居然…\", \"voicelineId\": 24071, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_qiqi/vo_qiqi_battle_hit_H_02\", \"description\": \"糟了…\", \"voicelineId\": 24072, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_qiqi_teamJoin_01\", \"description\": \"…我来了。\", \"voicelineId\": 24073, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_qiqi_teamJoin_02\", \"description\": \"有什么事吗？\", \"voicelineId\": 24074, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_qiqi_teamJoin_03\", \"description\": \"我带着…笔记。\", \"voicelineId\": 24075, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000036, 'Chongyun', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_draw_appear\", \"description\": \"我名重云，家族久居璃月，世代以驱邪除魔为业。今日萍水相逢，看来我与阁下有些缘分。唔…不收钱的，不收钱！\", \"voicelineId\": 22009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·驱邪之法\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_explore_idle_01\", \"description\": \"方士驱邪一靠咒术，二赖武艺。另辟蹊径亦可，但终非正道。\", \"voicelineId\": 22010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·饮食\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_explore_idle_02\", \"description\": \"寒食饮冰利于平神静气…清心泡水辅以冰块饮下，对身体最好。\", \"voicelineId\": 22011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·口诀\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_explore_idle_03\", \"description\": \"驱邪缚魅，内外澄清，啊，呃…糟了，后半句口诀忘了。\", \"voicelineId\": 22012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_weather_heavyRain_01\", \"description\": \"雨是无根水，是最澄净的水，对驱邪除魔大有帮助。\", \"voicelineId\": 22013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_weather_thunder_01\", \"description\": \"这落雷好大阵仗，妖邪也会惧怕的吧。\", \"voicelineId\": 22014, \"voicelineType\": \"1203\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_weather_snowy_01\", \"description\": \"啊…好天气，真是舒服。\", \"voicelineId\": 22015, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_greetingMorning\", \"description\": \"早晨的好时光可不能辜负，抓紧练功。\", \"voicelineId\": 22016, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_greetingNoon\", \"description\": \"正午灵气极盛，可得抓紧练功。\", \"voicelineId\": 22017, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_greetingNight\", \"description\": \"晚间最适静息凝神，更要抓紧练功。\", \"voicelineId\": 22018, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_greetingNight2\", \"description\": \"呼，累了一整天，你也休息去吧。明天再去传闻中鬼怪出没的老宅看看，说好了。\", \"voicelineId\": 22019, \"voicelineType\": \"1004\"}, {\"title\": \"关于重云自己·方士\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_idle\", \"description\": \"我们方士一派自古守护璃月，传承久远，剿杀邪魔自然是手到擒来。\", \"voicelineId\": 22020, \"voicelineType\": \"2001\"}, {\"title\": \"关于重云自己·委托\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_idle2\", \"description\": \"明明什么都没做，只是进了凶宅的门就解决了问题。这个委托的报酬，你觉得是拿还是不拿呢？\", \"voicelineId\": 22021, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·旅伴\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_close\", \"description\": \"你的本事不错，对丘丘…咳…邪魔从不手软，我们结伴而行如何。\", \"voicelineId\": 22022, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·怪谈\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_close1\", \"description\": \"璃月的奇闻异事你已经见了不少吧，你说的那些方外的鬼怪，我…我也想看看。\", \"voicelineId\": 22023, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_pendant\", \"description\": \"「神之眼」虽然厉害，却不可盲目依赖。我还是更加信任方术和武技。本事要精进，还是得勤学苦练。\", \"voicelineId\": 22024, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_share\", \"description\": \"璃月的土地上妖邪传闻虽然众多，但真假掺杂，有些奇奇怪怪的委托…其实跟鬼怪一点关系也没有。\", \"voicelineId\": 22025, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_pref_gift\", \"description\": \"听说琥牢山的琥珀中封存了不少稀奇古怪的东西，会不会也有一些历史传说中的妖邪呢？真想见识见识。\", \"voicelineId\": 22026, \"voicelineType\": \"3003\", \"unlockConditions\": [{\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_teammate_zhongli_01\", \"description\": \"「往生堂」的钟离先生啊，隐约觉得是个厉害角色，凡夫恶党杀人，我们方士除妖，他居然能葬仙人。\", \"voicelineId\": 22027, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [101609], \"unlockText\": \"完成「辞行久远之躯」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_teammate_xingqiu_01\", \"description\": \"我虽然敬佩行秋的武艺和侠心。但是我一定要事先提醒你，他坏心思也不少。如果真的发生了什么事情，记得回来和我结成受害者同盟啊。\", \"voicelineId\": 22028, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_teammate_xiao_01\", \"description\": \"降魔大圣和我们方士一派，一暗一明，共守璃月，历史已久，我非常尊敬魈上仙。但是，那位大人居然说…居然说什么驱邪方士量小力微不值一提，我，我绝对不能苟同！\", \"voicelineId\": 22029, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_teammate_hutao_01\", \"description\": \"「往生堂」的手段还是信得过的。但是那副「不用你们方士操心」的嘻嘻笑脸却看着让人火大…呼，冷静冷静。\", \"voicelineId\": 22030, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于七七…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_teammate_qiqi_01\", \"description\": \"看起来是个僵尸小姑娘，但作为方士我能察觉到…她可不一般。嗯…名字也不见宝诰之中，究竟是哪尊呢…\", \"voicelineId\": 22031, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于辛焱…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_teammate_xinyan_01\", \"description\": \"我会尽可能避开辛焱演出的区域。那般热烈的气氛，即使无意融入，也难免受其影响…我是说，会让人不自在。\", \"voicelineId\": 22032, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_teammate_xiangling_01\", \"description\": \"香菱做菜的手艺有口皆碑，但是她那些辛辣烫口的菜品我是绝对不会碰的…没有，没有什么…你看，史莱姆滑蘑菇？这能吃吗？\", \"voicelineId\": 22033, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于申鹤…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_teammate_shenhe_01\", \"description\": \"我曾听家中长辈聊起过她。她家的遭遇…很让人同情。原以为这次能够让分家的远亲重回家中，长辈们听说她还活着也都高兴坏了，说是要备上礼物，择个吉日好好聚聚。却没想到，平日根本见不到她的人影…等等，按辈分来算的话，我、我该不会…要叫她「小姨」吧…\", \"voicelineId\": 22034, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1101505], \"unlockText\": \"完成「风起鹤归」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夜兰…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_teammate_yelan_01\", \"description\": \"我初任方士那会儿，受邀到委托人家中驱邪，离开时，曾撞见过这位女性。她把我的名字记在某个小册子里，或许是想确认我有没有做值得怀疑的事吧。不过就那一次，后来再没遇见过她。\\n现在想想，大概是因为我平日打坐总是一动不动，谁看着都会觉得无趣吧。\", \"voicelineId\": 22035, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解重云·其一\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_friendship_01\", \"description\": \"本事很重要，不然空有热血，只会坏事。对于这点，我深有体会。啊，倒不是我自己的体会，呃…是近年行走璃月，观看人间百态的感悟。\", \"voicelineId\": 22036, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解重云·其二\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_friendship_02\", \"description\": \"我天生是「纯阳之体」，据说千年难遇，所有鬼怪对我退避三舍。唉…这其实一点都不好，哪有见不着鬼怪的驱邪方士。\", \"voicelineId\": 22037, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解重云·其三\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_friendship_03\", \"description\": \"「纯阳之体」常常导致热血太盛，没少害我出糗。我不食辛辣高温、出门撑伞、回避激荡的音律，就是为了克制它。唉…什么时候这体质才能不妨碍我呢？\", \"voicelineId\": 22038, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解重云·其四\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_friendship_04\", \"description\": \"坐等妖邪现身是没用的，得主动寻访。我为璃月人镇邪，于人能免去烦愁，于我也能广开视野。如果你遇到邪祟搅扰，我一定也会立刻来帮你。\", \"voicelineId\": 22039, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解重云·其五\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_friendship_05\", \"description\": \"剿灭天下妖邪是我身为方士的最终目标，将来这个宏愿实现之后，不管是温泉、绝云椒椒还是别的什么…热血刺激的东西，我其实…都可以考虑。唔…不行。这样想想就会有些激动…不好不好。\", \"voicelineId\": 22040, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"重云的爱好…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_pref_hobby\", \"description\": \"我？嗯…我最喜欢的还是听说书。茶博士总是能把各种奇闻怪谈讲得惊心动魄。有空不妨一道去听听。\", \"voicelineId\": 22041, \"voicelineType\": \"6001\"}, {\"title\": \"重云的烦恼…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_dialog_annoyed\", \"description\": \"经我多方打听，费了好大功夫，才找到一处破庙有妖邪出没！于是，我守了四天，却完全不见妖邪的影子。唉…这种事经常发生。\", \"voicelineId\": 22042, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_pref_foodLike\", \"description\": \"每日修行完毕后，要是能吃上稻妻运来的生鲜还有冷餐就好了，那种冰凉清爽的口感能缓解所有疲劳。\", \"voicelineId\": 22043, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_pref_foodDislike\", \"description\": \"所有又烫又辣的食物我都不能入口。如果是有绝云椒椒的菜，啊，想想就吓人。\", \"voicelineId\": 22044, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_spice_pref_01\", \"description\": \"口感凉爽，正合我意！我要多留一些，等到修行完毕后再来享用。\", \"voicelineId\": 22073, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_spice_normal_01\", \"description\": \"不好意思啊。明明是你的一片心意，我却只能放凉再吃…\", \"voicelineId\": 22074, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_spice_dislike_01\", \"description\": \"糟糕！这味道是…绝云椒椒？\", \"voicelineId\": 22075, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_pref_birthday\", \"description\": \"今天是你的生辰，这朵冰晶结成的小花送你，是我自己雕的。如果遇到妖邪，掷出冰花，我封入的咒术自会生效，助你脱险。啊…还有，生日快乐。\", \"voicelineId\": 22045, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_starUp_01\", \"description\": \"驱邪的术法也常常用到这些材料，没想到还能用于提升自己的灵气。\", \"voicelineId\": 22046, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_starUp_02\", \"description\": \"习武与术法一样，都有境界。受你指导，我又有进益了。\", \"voicelineId\": 22047, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_starUp_03\", \"description\": \"原来习武之道还有这样一种境界，手眼相通，人与剑合…嗯，我悟到了！\", \"voicelineId\": 22048, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_chongyun/vo_chongyun_starUp_04\", \"description\": \"领悟了这些武技，「剿灭天下妖邪」的愿望或许就能达成了。你一路相助，我当然铭感在心，今后赴汤蹈火在所不辞。\", \"voicelineId\": 22049, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_battle_skill1_01\", \"description\": \"剑印染冰！\", \"voicelineId\": 22050, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_battle_skill1_02\", \"description\": \"剑，出！\", \"voicelineId\": 22051, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_battle_skill1_03\", \"description\": \"急如敕令。\", \"voicelineId\": 22052, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_battle_skill1_04\", \"description\": \"听我法旨。\", \"voicelineId\": 22053, \"voicelineType\": \"100004\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_battle_skill3_01\", \"description\": \"邪魔退去！\", \"voicelineId\": 22054, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_battle_skill3_02\", \"description\": \"宝印幻剑！\", \"voicelineId\": 22055, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_battle_skill3_03\", \"description\": \"束手伏诛吧。\", \"voicelineId\": 22056, \"voicelineType\": \"200003\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_explore_fly_start_01\", \"description\": \"且看踏风纵云的本领。\", \"voicelineId\": 22057, \"voicelineType\": \"700001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_chest_open_01\", \"description\": \"这等器物，有助于驱邪除魔。\", \"voicelineId\": 22058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_chest_open_02\", \"description\": \"不枉你我一番劳苦！\", \"voicelineId\": 22059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_chest_open_03\", \"description\": \"意外之喜。\", \"voicelineId\": 22060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_life_less30_01\", \"description\": \"小伤不足挂齿。\", \"voicelineId\": 22061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_life_less30_02\", \"description\": \"不能再轻敌了。\", \"voicelineId\": 22062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_life_less30_03\", \"description\": \"你莫猖狂！\", \"voicelineId\": 22063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_life_less30_teammate_01\", \"description\": \"我来助你。\", \"voicelineId\": 22064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_life_less30_teammate_02\", \"description\": \"务必撑住！\", \"voicelineId\": 22065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_life_die_01\", \"description\": \"还是技不如人吗…\", \"voicelineId\": 22066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_life_die_02\", \"description\": \"妖邪…未除…\", \"voicelineId\": 22067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_life_die_03\", \"description\": \"辱没了…方士一门…\", \"voicelineId\": 22068, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_chongyun/vo_chongyun_battle_hit_H_01\", \"description\": \"居然！\", \"voicelineId\": 22069, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_chongyun_teamJoin_01\", \"description\": \"得令。\", \"voicelineId\": 22070, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_chongyun_teamJoin_02\", \"description\": \"我有咒毒杀鬼方。\", \"voicelineId\": 22071, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_chongyun_teamJoin_03\", \"description\": \"是去练功么？\", \"voicelineId\": 22072, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000037, 'Ganyu', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_draw_appear\", \"description\": \"我明白了，外派工作的「契约」已经拟好了，请过目，即日起就可以为你…欸！名字没有签吗？请让我看一下。唔…名字是甘，甘雨…呼，补上了。话，话说回来，工作具体是指哪些呢？\", \"voicelineId\": 25009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·松弛\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_explore_idle_01\", \"description\": \"安逸的氛围…喜欢。\", \"voicelineId\": 25010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·聆听\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_explore_idle_02\", \"description\": \"趴在草地上，能听见大地的心跳。\", \"voicelineId\": 25011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·焦虑\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_explore_idle_03\", \"description\": \"工作…工作还没有做完…真的可以提前休息吗？\", \"voicelineId\": 25012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候·担忧\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_weather_heavyRain_01\", \"description\": \"飞云商会种植的霓裳花需要充足的雨露，唔...和记交通的伙计们却不喜欢雨后泥泞的山路…\", \"voicelineId\": 25013, \"voicelineType\": \"1201\"}, {\"title\": \"下雨的时候·听雨\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_weather_heavyRain_02\", \"description\": \"在庭院里听雨的感觉很好，但是，太奢侈了。\", \"voicelineId\": 25014, \"voicelineType\": \"1202\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_weather_afterRain_01\", \"description\": \"嗯？天晴了吗？是什么时候…\", \"voicelineId\": 25015, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_weather_sunny_01\", \"description\": \"嗯，空气很适宜。\", \"voicelineId\": 25016, \"voicelineType\": \"1204\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_weather_breezy_01\", \"description\": \"啊，琉璃百合的味道，真好啊…\", \"voicelineId\": 25017, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_greetingMorning\", \"description\": \"早上好…唔？是哪里没有梳理好吗，请不要盯着我的…盯着我的头饰看。\", \"voicelineId\": 25018, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_greetingNoon\", \"description\": \"啊…需要午觉。如果没有什么特别的事情…我就先行告退了。\", \"voicelineId\": 25019, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_greetingNight\", \"description\": \"万家灯火就在眼前，人们的生活究竟是什么样的呢…欸？你想邀我去夜市？啊…不，不好意思，我就不去了吧。\", \"voicelineId\": 25020, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_greetingNight2\", \"description\": \"愿帝君保佑你，愿你的每个梦都踏实而香甜。\", \"voicelineId\": 25021, \"voicelineType\": \"1004\"}, {\"title\": \"关于甘雨自己…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_idle\", \"description\": \"我的工作，就是遵循与帝君的「契约」，为璃月的多数生命，谋求最大的福祉。\", \"voicelineId\": 25022, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·工作\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_close\", \"description\": \"今天的工作已经提前完成了。加…加班？我理解了，我会好好完成的。\", \"voicelineId\": 25023, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·请求\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_close1\", \"description\": \"我想了解更多有关人类的故事…尤其，想知道你对他们的看法和评价。因为，那个，你跟提瓦特大陆上的普通人不太一样吧。而我也…请务必，和我交流。\", \"voicelineId\": 25024, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·评价\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_close2\", \"description\": \"嗯…我，我一直想知道你对我工作的评价。是…普通宝箱的等级还是华丽宝箱的等级。没，没关系的。我的心理…能承受得住。\", \"voicelineId\": 25025, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_pendant\", \"description\": \"「一千种权力伴随着一千种责任。」那位拥有着博览古今的视野，却被迫放弃了自己生活的帝君，才是整个璃月最辛苦的人吧。相比起来，只拥有着普通「神之眼」，只需要去行使普通责任的我，已经轻松得多了。\", \"voicelineId\": 25026, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_share\", \"description\": \"「万商云来、千船继至、百货迭出、诸海历览。」人们用这样的话来称赞璃月。但成就这样的壮景，依靠的也是细小到每一个人的努力。我是怀着要对得起这份繁荣的心情工作的。\", \"voicelineId\": 25027, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻·名字\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_pref_gift_01\", \"description\": \"生活在璃月的每一只小狗，我都给它们取了名字。不过，有的狗狗如果用别的名字叫它也会有反应。真是了不起呢。如果有谁突然叫我「苦雪」什么的，我一定回应不上来。\", \"voicelineId\": 25028, \"voicelineType\": \"3003\"}, {\"title\": \"感兴趣的见闻·清心\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_pref_gift_02\", \"description\": \"清心的花瓣，很好吃…应该说特别好吃。就是因为太好吃了，所以我才不敢在玉京台种它。生怕哪天一个不小心就会忍不住…嗯？你说…特别苦？可是…这不就是它的味道吗？\", \"voicelineId\": 25029, \"voicelineType\": \"3004\"}, {\"title\": \"关于摩拉克斯·信任\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_morax_01\", \"description\": \"我对帝君有着绝对的信任。当年，正是有帝君率领，我们才能击退魔物、降伏海兽，保住了这一方平安。帝君守护众人的身姿，千年以来的情谊，我不会忘记。\", \"voicelineId\": 25030, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于摩拉克斯·追随\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_morax_02\", \"description\": \"帝君的决断，总是能够为璃月的多数生命带来福祉。我很敬佩这一点，也很想像他一样…但有时，越想着要去追赶帝君的脚步，就越容易紧张得出错…\", \"voicelineId\": 25031, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_ningguang_01\", \"description\": \"历任「天权」都会对璃月的古老律法进行释义和补充。在这之中，当代「天权」凝光的处理效率是无人能及的。只不过，她那追求效率和效益的作风常常遭人指摘。挑刺，总是比包容简单得多吧。\", \"voicelineId\": 25032, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴·隔阂\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_keqing_01\", \"description\": \"我无法认同她对帝君的态度。但是…但是…「甘雨，这才是璃月现今需要的人。」帝君反而这样说。我还是太愚钝了，要理解帝君话语中的意思，还得更努力地接触更多事务才行吧。\", \"voicelineId\": 25033, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴·改观\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_keqing_02\", \"description\": \"最近她主动与我讨论起了修复碧水商路的方案，还问我，是帝君的话会怎么做。我们商量出来的举措固然不比帝君，不过…看到她反复推演着沙盘的样子，隐约能够理解她的心情了。\", \"voicelineId\": 25034, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_xingqiu_01\", \"description\": \"飞云商会那位青衣少年，并不像他的父亲和兄长那般操心织物的经营。是因为对他来说，有更重要的事情值得去做吧。当然…这也只是我的猜测…\", \"voicelineId\": 25035, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_xiangling_01\", \"description\": \"香菱很有名！但...我不太敢去「万民堂」那一带…不敢就是…不敢啦。好，好吧，也不是秘密。那边的饭菜香味飘得满街都是。一旦被勾住了，点上了菜，就算是素菜也...很难控制住食欲吧。这样的话，这样的话…\", \"voicelineId\": 25036, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_beidou_01\", \"description\": \"近来，玉京台之上对南十字船队的怨言不断。可是在我看来，北斗船长对璃月所做的贡献，远非沉溺于伪造流言之徒所能想象…啊，抱歉，失言了…\", \"voicelineId\": 25037, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于瑶瑶…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_yaoyao_01\", \"description\": \"瑶瑶啊…我是受总务司那边的熟人托付，在城内好生照顾她，别让她再往船上跑…你问我总务司的业务范围？唔…不，不知道呢。\", \"voicelineId\": 25038, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_xiao_01\", \"description\": \"他一直与人间保持距离，应该说是性格使然吧…我能够理解他，但是我无法「接近」他。毕竟…与他履行同一份「契约」的同伴，都已经不在了啊…\", \"voicelineId\": 25039, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于烟绯…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_yanfei_01\", \"description\": \"烟绯呀…她还是个懵懂的小女孩时，就和我说过，要遵守契约，过上快乐的生活。如今她亭亭玉立，成了璃月的名人。\\n律法咨询师的工作很繁杂，但她总是一副无忧无虑的模样，这让我十分安心。\", \"voicelineId\": 25040, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于申鹤…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_shenhe_01\", \"description\": \"我和她并不能算是熟悉。只是听留云真君提过几句，听说她性子较凶，要是压抑不住心性，容易对周围造成严重破坏。嗯…会不会是因为平日里太闲了呢？我…我该给她推荐些工作吗？\", \"voicelineId\": 25041, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夜兰…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_yelan_01\", \"description\": \"虽说夜兰小姐每年有将近七成时间缺勤，但凝光会给她这样的特权，想必事出有因。当然，这不该是由我打听的事项，具体内容就不清楚了。不过，有天我回月海亭的路上，看到她和许多人有说有笑地吃着早点、喝着茶。我的内心深处…竟然有些羡慕。\", \"voicelineId\": 25042, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于闲云…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_teammate_xianyun_01\", \"description\": \"留云真君…啊，我是说，闲云小姐，她不久前约我一同逛街，却在每个摊位前都停下脚步，一定要把每件商品细细看过一遍才离开。等我们记起要吃饭时，已经夕阳西下了。这让我想起了从前在山中修行的日子，光阴也如同现在一样，转瞬即逝…\", \"voicelineId\": 25086, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11035], \"unlockText\": \"完成「千里月明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解甘雨·其一\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_friendship_01\", \"description\": \"临时的工作吗？啊，不用和我具体说。将你的要求写下来，放在这边就好。\", \"voicelineId\": 25043, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解甘雨·其二\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_friendship_02\", \"description\": \"「想要了解更多甘雨的事情」…这，这是什么工作要求啊。我，我还从来没有处理过这样的…去年年底述职报告的背诵可以吗？啊，不行啊。\", \"voicelineId\": 25044, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解甘雨·其三\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_friendship_03\", \"description\": \"我思考过了…既然是「工作」，处理「工作」就没有害羞的必要。如果你想要了解我的话，这个头上的…发饰。其实是我的角。我的身上，有着仙兽「麒麟」的血脉。唔…理解了的话，请签下这份保密协议，不要对别人讲…\", \"voicelineId\": 25045, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解甘雨·其四\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_friendship_04\", \"description\": \"虽然身为仙兽的混血后裔，但同时也有着人类的血脉。这么多年来，我也不知道自己算不算融入了璃月港的人类生活…可能，我只是像钻进地里的草史莱姆一样，把自己埋在数据和报表中间来逃避吧。\", \"voicelineId\": 25046, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解甘雨·其五\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_friendship_05\", \"description\": \"谢谢你一直陪我说话。遇见你之后，好像说了十几年都没有说过的那么多话…如果保持这样的锻炼，有朝一日也能从事秘书以外的职业了吧。用上几百年时间来熟练，应该就不会犯什么要紧的错了吧。\", \"voicelineId\": 25047, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"甘雨的爱好…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_pref_hobby\", \"description\": \"爱好吗，爱好的话…工作吧。嗯？工作不能算？但是，为什么呢？难道爱好不是指自己想要去做，做了就会感到开心的事情吗。那么爱好是工作，又有什么问题呢？\", \"voicelineId\": 25048, \"voicelineType\": \"6001\"}, {\"title\": \"甘雨的烦恼…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_dialog_annoyed\", \"description\": \"为何人们总是拼命证明…自己的存在比其他人更有价值呢？存在本身，就是足够美好的事情了吧？\", \"voicelineId\": 25049, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_pref_foodLike\", \"description\": \"「饮必甘露，食必嘉禾。」这是我的守则。所以，请把那盘「仙跳墙」，从我的视线范围里拿开…\", \"voicelineId\": 25050, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_pref_foodDislike\", \"description\": \"我们一族是严格的素食主义者，肉类料理就请允许我谢绝了。嗯，没错，即使是荤油混在蔬菜丸子里也不行…不可以。不可以哟。我能够闻出来的。\", \"voicelineId\": 25051, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_spice_pref_01\", \"description\": \"地道的美味佳肴…啊！我是不是已经吃多了？\", \"voicelineId\": 25083, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_spice_normal_01\", \"description\": \"我在饮食方面还挺挑剔的，让你费心了…\", \"voicelineId\": 25084, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_spice_dislike_01\", \"description\": \"我明白你的好意，但油荤…还是算了。\", \"voicelineId\": 25085, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_pref_birthday\", \"description\": \"生日快乐。这么久以来受你的关照，但却没有准备礼物，这点实在…藏在手后面的？欸，你看到了啊…是，失败了的清心花凉糕…抱着必须做完美的决心结果…欸，好，好吃的？真…真的吗。\", \"voicelineId\": 25052, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_starUp_01\", \"description\": \"力量？…真是久违了。\", \"voicelineId\": 25053, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_starUp_02\", \"description\": \"如果…可以用和平的方式解决。不，没什么…\", \"voicelineId\": 25054, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_starUp_03\", \"description\": \"这就是新的生活之道吧…我明白了，我不会抱怨的。\", \"voicelineId\": 25055, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_ganyu/vo_ganyu_starUp_04\", \"description\": \"我曾经看到古书上说，「麟斗则日无光」。其实没有那么夸张。但是，如果需要战斗，如果需要为你而战，我会献出自己的全部力量。\", \"voicelineId\": 25056, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_battle_skill1_01\", \"description\": \"禁止接触。\", \"voicelineId\": 25057, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_battle_skill1_02\", \"description\": \"闲人勿扰。\", \"voicelineId\": 25058, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_battle_skill1_03\", \"description\": \"霜寒化生。\", \"voicelineId\": 25059, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_battle_skill3_01\", \"description\": \"风雪的缩影。\", \"voicelineId\": 25060, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_battle_skill3_02\", \"description\": \"如琉璃般飘落。\", \"voicelineId\": 25061, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_battle_skill3_03\", \"description\": \"这项工作，该划掉了。\", \"voicelineId\": 25062, \"voicelineType\": \"200003\"}, {\"title\": \"元素爆发·其四\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_battle_skill3_04\", \"description\": \"为了岩王帝君！\", \"voicelineId\": 25063, \"voicelineType\": \"200004\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_explore_sprint_start_01\", \"description\": \"下一项工作是…\", \"voicelineId\": 25064, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺开始·其二\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_explore_sprint_start_02\", \"description\": \"我会跟上的…\", \"voicelineId\": 25065, \"voicelineType\": \"700002\"}, {\"title\": \"冲刺结束·其一\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_explore_sprint_end_01\", \"description\": \"运动，是必要的…\", \"voicelineId\": 25066, \"voicelineType\": \"710001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_chest_open_01\", \"description\": \"有所收获，就是一件好事。\", \"voicelineId\": 25067, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_chest_open_02\", \"description\": \"瑰丽的珍宝，令人欣喜。\", \"voicelineId\": 25068, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_chest_open_03\", \"description\": \"留下宝箱的人，也遵循着某种「契约」吗？\", \"voicelineId\": 25069, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_life_less30_01\", \"description\": \"…是我久疏战场。\", \"voicelineId\": 25070, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_life_less30_02\", \"description\": \"欸？好像弄砸了？\", \"voicelineId\": 25071, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_life_less30_03\", \"description\": \"需要…补充能量。\", \"voicelineId\": 25072, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_life_less30_teammate_01\", \"description\": \"请您退后！\", \"voicelineId\": 25073, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_life_less30_teammate_02\", \"description\": \"呃…「不可贸然进攻」！\", \"voicelineId\": 25074, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_life_die_01\", \"description\": \"帝君…对不起…\", \"voicelineId\": 25075, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_life_die_02\", \"description\": \"「契约」…尚未完成…\", \"voicelineId\": 25076, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_life_die_03\", \"description\": \"我得…再撑一会…\", \"voicelineId\": 25077, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_battle_hit_L_02\", \"description\": \"疏忽了…\", \"voicelineId\": 25078, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_ganyu/vo_ganyu_battle_hit_H_02\", \"description\": \"没有关系…\", \"voicelineId\": 25079, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_ganyu_teamJoin_01\", \"description\": \"工作时间到了么？\", \"voicelineId\": 25080, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_ganyu_teamJoin_02\", \"description\": \"请向我下达指令。\", \"voicelineId\": 25081, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_ganyu_teamJoin_03\", \"description\": \"谨遵你我「契约」。\", \"voicelineId\": 25082, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000038, 'Albedo', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_draw_appear\", \"description\": \"我是阿贝多，西风骑士团首席炼金术士。我对你身上星海的气息很感兴趣，想要就近观察研究。相信以后我们会有很多独处的机会。\", \"voicelineId\": 35009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·写生\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_explore_idle_01\", \"description\": \"风景不错，趁着休息，就把这一幕画下来吧。\", \"voicelineId\": 35010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·探究\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_explore_idle_02\", \"description\": \"「世界的真相」…究竟是什么呢？\", \"voicelineId\": 35011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·怀旧\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_explore_idle_03\", \"description\": \"用自己的双脚丈量土地，将「未知」变为知识。…这种感觉，真怀念啊。\", \"voicelineId\": 35012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_weather_heavyRain_01\", \"description\": \"土壤湿润，适合采集爆爆瓜的根。没事，我来动手就可以。\", \"voicelineId\": 35013, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_weather_snowy_01\", \"description\": \"师父…\", \"voicelineId\": 35014, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_weather_sunny_01\", \"description\": \"光线充足，生物行为活跃，嗯，很适合写生。\", \"voicelineId\": 35015, \"voicelineType\": \"1203\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_greetingMorning\", \"description\": \"早安，是准备出门寻找古代遗物吗？\", \"voicelineId\": 35016, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_greetingNoon\", \"description\": \"午安，我听到了你的脚步声。工坊之外真是热闹啊。\", \"voicelineId\": 35017, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_greetingNight\", \"description\": \"外面安静下来了，呼。\", \"voicelineId\": 35018, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_greetingNight2\", \"description\": \"晚安，你先去休息吧，我打算把最后一个实验做完。既然你那么感兴趣…明日再会时，我再与你一起探讨实验结果吧。\", \"voicelineId\": 35019, \"voicelineType\": \"1004\"}, {\"title\": \"关于阿贝多自己·天才\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_idle\", \"description\": \"天才？…不少人这么称呼我。其实，我不这样认为。\", \"voicelineId\": 35020, \"voicelineType\": \"2001\"}, {\"title\": \"关于阿贝多自己·人际\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_idle2\", \"description\": \"与人交往…很麻烦。一旦开始就要不断维持，如果联系中断了，想再重新恢复，就得消耗更多的时间。\", \"voicelineId\": 35021, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·实验\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_close\", \"description\": \"你…这是准备陪我做实验吗？呼，真荣幸。\\n啊，不用紧张。我的实验虽然危险，通常不会伤及无辜。\", \"voicelineId\": 35022, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·助手\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_close1\", \"description\": \"能麻烦你当我的助手吗？鉴于你旁观了那么多次，想必早就熟练了吧。放心，我在你旁边。就算是第一次实际操作，也不会有问题的。我相信我的指导能力，更相信你的天赋。\", \"voicelineId\": 35023, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_pendant\", \"description\": \"「神之眼」？不过就是个实验用的工具罢了，和烧杯、坩埚没什么不同。唯一让我感兴趣的，就是它的原理…我总有一天会研究明白的，这只是时间问题。\", \"voicelineId\": 35024, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_share_01\", \"description\": \"一直有些难以开口，因为假设被你拒绝的话，我可能会失落吧…\\n嗯…我对你身边那个飞着的小家伙很感兴趣，方便让我拿去研究一下吗？\", \"voicelineId\": 35025, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_pref_gift\", \"description\": \"想知道更多石化古树的事情？唔…你在附近秘境里观测到的那些，其实不算古老。稍微成熟一些的树，一般能长到两三公里高；在树的根部，常常聚集着一种大蜘蛛。那种蜘蛛啊，用地栀子和香茅草捆紧，抹上白豆蔻，熏烤上几个小时，那香味，是真的很…令我难忘。\", \"voicelineId\": 35026, \"voicelineType\": \"3003\"}, {\"title\": \"关于亲人…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_teammate_relatives_01\", \"description\": \"亲人吗？虽然艾莉丝总希望我喊她妈妈…唔，但在我心里，谈起亲人第一时间想到的还是师父吧。我从记事起就和她在一起探险了，她教会了我炼金术和无数世间的知识。或许…「亲人」或者「师父」，这些词汇都不足以描绘出她对我来说的意义吧。\", \"voicelineId\": 35027, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于砂糖·方向\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_teammate_sucrose_01\", \"description\": \"砂糖吗？我大概能理解她一心专攻「生物炼金」的理由…不管怎样，看到她的研究越来越顺利，我也为她感到高兴。\", \"voicelineId\": 35028, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于砂糖·坚持\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_teammate_sucrose_02\", \"description\": \"虽然在学术方面的合作非常愉快，但课题以外的部分，砂糖也有很多她自己的坚持。比如我告诉她我们是平辈，叫我阿贝多就好，她却坚持要用尊称。…只好随她去了。\", \"voicelineId\": 35029, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_teammate_lisa_01\", \"description\": \"丽莎吗？和她讨论总会得到很有价值的观点。如此有才华却满足于图书管理员一职，想必背后藏着与那才华等重的因缘吧。\", \"voicelineId\": 35030, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_teammate_klee_01\", \"description\": \"我的确把可莉当作亲妹妹一样看，所以每次当这位妹妹惹出麻烦的时候，我都只能安慰自己，至少她现在的破坏力，还不及艾莉丝女士的零头。\", \"voicelineId\": 35031, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_teammate_qin_01\", \"description\": \"琴吗？她是一位正直的代理团长，甚至可以说比那位团长大人更为可靠。可能大家心中都在期待着她成为正式团长的那一天吧。\", \"voicelineId\": 35032, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_teammate_xingqiu_01\", \"description\": \"行秋吗？他写的小说挺有趣的。稻妻那边的「八重堂」一直在旁敲侧击希望让我和别的作者合作，说这样版税收入也会更好。哼，我缺这点钱吗？\", \"voicelineId\": 35033, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芭芭拉…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_teammate_barbara_01\", \"description\": \"芭芭拉吗？她是一位认真的牧师，说来以前碰巧有机会给她画过速写…你问画哪儿去了？嗯…我拒绝了艾伯特的开价，直接把画送给了代理团长。人际交往…真是耗费精力啊。\", \"voicelineId\": 35034, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解阿贝多·其一\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_friendship_01\", \"description\": \"有问题想问我？请说吧。啊，冒昧地问一句，应该不会花费太长时间吧？手头的研究马上要进入最后一个阶段了。\", \"voicelineId\": 35035, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解阿贝多·其二\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_friendship_02\", \"description\": \"啊，只是随口一提。不人为介入的话，黄金需要杀死一个八倍大的太阳才能自然生成。\", \"voicelineId\": 35036, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解阿贝多·其三\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_friendship_03\", \"description\": \"人物画的耗时主要和心情有关。有时候霍夫曼我也能画半天，有时候凯亚都只需要三笔——这个圆是脸，这个是眼罩的带子…这个是眼罩。\", \"voicelineId\": 35037, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解阿贝多·其四\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_friendship_04\", \"description\": \"除了画画和研究之外的生活…我偶尔会去看稻妻和璃月的小说吧，能看到很多很有趣的想法，有时也会为创作提供意想不到的灵感。\", \"voicelineId\": 35038, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解阿贝多·其五\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_friendship_05\", \"description\": \"即便到了现在，师父传授给我的「黑土之术」仍是充满了谜团，师父到底想要用这个技术创造出什么呢？…研究之期还远未到尽头，得麻烦你和我一起继续探索了。\", \"voicelineId\": 35039, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"阿贝多的爱好…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_pref_hobby\", \"description\": \"嗯…研究之外我最愿意花时间去做的应该是画画吧。一开始只是为了理解物体与材料的构成，便于研究开展，不过到了后来就变成了爱好。嗯，也是一种很好的放松方式。\", \"voicelineId\": 35040, \"voicelineType\": \"6001\"}, {\"title\": \"阿贝多的烦恼…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_dialog_annoyed\", \"description\": \"时间真是不够用啊，即使把大部分麻烦的事情都推掉还是会觉得时间不够。\", \"voicelineId\": 35041, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_pref_foodLike\", \"description\": \"我挺喜欢甜点的。怎么说呢…在体力和精力同时消耗殆尽的时候，高能量的物质会提供原始而高效的支持吧。\", \"voicelineId\": 35042, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_pref_foodDislike\", \"description\": \"讨厌的食物？餐馆里分量比较大的肉吧。我的胃口吃不了多少，只会面临「浪费」或者「失去风味」的结局。后来我就干脆不去餐馆了，虽然这也意味着要花更多时间在做菜上…\", \"voicelineId\": 35043, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_spice_pref_01\", \"description\": \"味觉仿佛折射出了色彩…我想它是金色的。\", \"voicelineId\": 35071, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_spice_normal_01\", \"description\": \"你似乎很愿意花时间在做菜上，所以才能做出这样的味道。\", \"voicelineId\": 35072, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_spice_dislike_01\", \"description\": \"量有点大…要一起分享吗？\", \"voicelineId\": 35073, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_pref_birthday\", \"description\": \"生日快乐。你看起来很高兴，可以将你的样子画下来吗？大脑的容量是有限的，人总会不断忘记。如果画在纸上，那么这些画就成了记忆的延伸，在未来重新看到这些画面时，一定能回想起当时的感觉吧。\", \"voicelineId\": 35044, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_starUp_01\", \"description\": \"「黑土」，是炼金术的词源，也是最初的状态。活在这个世界上，我等俗类必须寻找意义。\", \"voicelineId\": 35045, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_starUp_02\", \"description\": \"「白垩」，即是变化的开始。抽离了杂质，准备好接受一切知识。要和我一起去探索世界吗？\", \"voicelineId\": 35046, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_starUp_03\", \"description\": \"「赤成」，炼金术中的意思是，情感的炼化。我的赤色好像来自于你。\", \"voicelineId\": 35047, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_albedo/vo_albedo_starUp_04\", \"description\": \"「黄金」，炼金术最后的阶段。无价值的事物终于找到了自己的意义，变化成了黄金。我，也找到了意义。\", \"voicelineId\": 35048, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_battle_skill1_01\", \"description\": \"绽放吧。\", \"voicelineId\": 35049, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_battle_skill1_02\", \"description\": \"拟造阳华。\", \"voicelineId\": 35050, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_battle_skill1_03\", \"description\": \"创生之法。\", \"voicelineId\": 35051, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_battle_skill3_01\", \"description\": \"此即，诞生之刻。\", \"voicelineId\": 35052, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_battle_skill3_02\", \"description\": \"冥古，于此显生。\", \"voicelineId\": 35053, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_battle_skill3_03\", \"description\": \"见证伟业吧。\", \"voicelineId\": 35054, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_chest_open_01\", \"description\": \"大地的秘宝。\", \"voicelineId\": 35055, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_chest_open_02\", \"description\": \"无言的叙事。\", \"voicelineId\": 35056, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_chest_open_03\", \"description\": \"虽无法比拟「黄金」，但终有价值。\", \"voicelineId\": 35057, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_life_less30_01\", \"description\": \"计算失误…\", \"voicelineId\": 35058, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_life_less30_02\", \"description\": \"需要重新评估…\", \"voicelineId\": 35059, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_life_less30_03\", \"description\": \"必须改变策略。\", \"voicelineId\": 35060, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_life_less30_teammate_01\", \"description\": \"交给我吧。\", \"voicelineId\": 35061, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_life_less30_teammate_02\", \"description\": \"换人，对你来说太危险了。\", \"voicelineId\": 35062, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_life_die_01\", \"description\": \"尘归尘，土归土…\", \"voicelineId\": 35063, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_life_die_02\", \"description\": \"实验失败了吗？\", \"voicelineId\": 35064, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_life_die_03\", \"description\": \"我的研究，结束了…\", \"voicelineId\": 35065, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_battle_hit_L_02\", \"description\": \"阈值以内…\", \"voicelineId\": 35066, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_albedo/vo_albedo_battle_hit_H_02\", \"description\": \"失算了…\", \"voicelineId\": 35067, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_albedo_teamJoin_01\", \"description\": \"了解。\", \"voicelineId\": 35068, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_albedo_teamJoin_02\", \"description\": \"是拓展课题吗？\", \"voicelineId\": 35069, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_albedo_teamJoin_03\", \"description\": \"一起探索吧。\", \"voicelineId\": 35070, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000039, 'Diona', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_draw_appear\", \"description\": \"「猫尾酒馆」的招牌调酒师，迪奥娜，我的出场费可是很贵的。唔？你居然…不是为了酒才来的？哼，那你的邀请…我就勉为其难地接受了。\", \"voicelineId\": 34009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·放松\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_explore_idle_01\", \"description\": \"哈~~好舒服，身体都变得更柔软了。\", \"voicelineId\": 34010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·思考\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_explore_idle_02\", \"description\": \"蜥蜴尾巴、胡椒、星螺…还差点什么才能调出「难喝到头脑炸裂的酒」呢？呜…\", \"voicelineId\": 34011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·等待\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_explore_idle_03\", \"description\": \"才，才没有在等你。我只是，正好在休息而已！\", \"voicelineId\": 34012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_weather_heavyRain_01\", \"description\": \"呜呜…讨厌下雨…去屋子里吧。唔，只是因为弄干衣服很麻烦！才不是什么怕水呢！\", \"voicelineId\": 34013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_weather_thunder_01\", \"description\": \"欸？！…我没有在发抖！没有！…呜…\", \"voicelineId\": 34014, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候·玩雪\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_weather_snowy_01\", \"description\": \"这个凉飕飕的触感，哇…好棒，好有趣。\", \"voicelineId\": 34015, \"voicelineType\": \"1203\"}, {\"title\": \"下雪的时候·观雪\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_weather_snowy_02\", \"description\": \"白茫茫的雪在风里跳舞，真好看呢。嗯…我旁边的座位还空着，没人坐哦。\", \"voicelineId\": 34016, \"voicelineType\": \"1204\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_weather_sunny_01\", \"description\": \"走喽，晒太阳…你不去我可就自己去了哦…唔，最后一次机会！走不走！\", \"voicelineId\": 34017, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_greetingMorning\", \"description\": \"早，把橱柜里那罐腌泥鳅递给我一下——好咧，我要开始摧毁蒙德酒业啦。\", \"voicelineId\": 34018, \"voicelineType\": \"1001\"}, {\"title\": \"中午好·异响\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_greetingNoon2\", \"description\": \"咕噜噜…嗯？没有！你什么都没有听到！\", \"voicelineId\": 34019, \"voicelineType\": \"1002\"}, {\"title\": \"中午好·罐头\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_greetingNoon\", \"description\": \"这个鱼肉罐头是我好不容易省下来的，别，别看啦！最多…最多只能给你尝一口。\", \"voicelineId\": 34020, \"voicelineType\": \"1005\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_greetingNight\", \"description\": \"失败了…又失败了…大家都喝得好开心，呜…别安慰我，我才不需要安慰…\", \"voicelineId\": 34021, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_greetingNight2\", \"description\": \"你没有猫的夜视能力，走夜路不要紧吧？要我护送你的话…欸，有灯啊？…谁，谁要护送你啦，快点走快点走。\", \"voicelineId\": 34022, \"voicelineType\": \"1004\"}, {\"title\": \"关于迪奥娜自己…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_idle\", \"description\": \"耳朵和尾巴才不是什么装饰，是「凯茨莱茵家族」血统的象征，真是少见多怪。呃…你、你把手伸过来干什么？这个…唔…好吧，耳朵的话可以让你摸一下…但是尾巴、尾巴绝对不可以！\", \"voicelineId\": 34023, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·饮料\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_close\", \"description\": \"想喝无酒精饮料？难倒是不难，但是没有意义！无论成功还是失败，都和摧毁蒙德酒业的目标没有关联。我才不会做呢。\", \"voicelineId\": 34024, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·贵宾渠道\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_close1\", \"description\": \"喏，这个是「了不起的夏日梦幻忧郁珊瑚气泡茶」，只是因为最近无聊才做的。热门产品？排队抢购？你在说什么呢，我可没听见。\", \"voicelineId\": 34025, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·聊天需要\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_close2\", \"description\": \"唔…要是，要是你感觉孤单了，我可以随便陪你聊聊天。我还是知道很多事情的哦！也是很好的…那个叫什么，说话对象哦。没错没错！来跟我，多说说话吧…\", \"voicelineId\": 34026, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·好奇心\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_close3\", \"description\": \"是什么是什么？你拿着的是什么？快给我看看！说不定丢到酒里能做出相当难喝的…啊，什么嘛，原来只是长得奇怪了点的蘑菇而已呀，真无趣。\", \"voicelineId\": 34027, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·遗传\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_pendant_01\", \"description\": \"问我的「神之眼」是怎么来的？哼，是、呃…是凯茨莱茵的家族遗传！唔？杜拉夫先生根本没有神之眼？欸——露馅了。\", \"voicelineId\": 34028, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·来历\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_pendant_02\", \"description\": \"为什么非得告诉你啦，哼！算了，看在你一直追问的份上，看在…看在我们是朋友的份上。那次我爸爸外出打猎，差点出大事，在大雨中，我脑袋里想的全部事情就是要找到他，救出他…好了啦，满意了吧！\", \"voicelineId\": 34029, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_share\", \"description\": \"龙脊雪山上，会不会长着奇珍异草呢。「拥有致命的苦味」或者「沾到一点就嘴巴发麻」这样？要拔好多下来！然后…嘿嘿嘿…嚯嚯。\", \"voicelineId\": 34030, \"voicelineType\": \"3003\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_pref_gift\", \"description\": \"我扑…捕捉蝴蝶的技巧可是一流的。喂，不是啦！抓蝴蝶是为了加进酒里做出难吃的味道，不要把我当成猫啦！喵！\", \"voicelineId\": 34031, \"voicelineType\": \"3004\"}, {\"title\": \"关于迪卢克…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_teammate_diluc_01\", \"description\": \"那个…迪卢克，是我最讨厌的人！没有迪卢克就不会有蒙德酒业，没有蒙德酒业爸爸就不会喝酒，爸爸不喝酒就…就会陪我了，哼。\", \"voicelineId\": 34032, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_teammate_kaeya_01\", \"description\": \"为什么连我的「护卫队长」也是个令人讨厌的酒鬼啦！就是那个，说起话来总是笑盈盈的家伙！喝起酒来一杯接一杯的，没完没了。呼！\", \"voicelineId\": 34033, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温迪…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_teammate_venti_01\", \"description\": \"温迪？不太熟的样子。但说到吟游诗人，就是那伙会给酒鬼们唱歌助兴的人吧。那就不喜欢！不喜欢不喜欢。\", \"voicelineId\": 34034, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芭芭拉…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_teammate_barbara_01\", \"description\": \"芭芭拉小姐的粉丝们，都是大哥哥大姐姐…好羡慕，为什么我的粉丝都是一群大叔呢。呜…可恶，哼，不想了。\", \"voicelineId\": 34035, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_teammate_qin_01\", \"description\": \"琴啊，骑士团的代理团长，嗯…难得一个不喝酒的成熟大人…但总感觉认真过了头，骑士团的大家对我有些过度保护了吧？\", \"voicelineId\": 34036, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_teammate_albedo_01\", \"description\": \"首席炼金术士大人？唔…我这种一直调出好酒的体质，他会知道破解的方法么？\", \"voicelineId\": 34037, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_teammate_lisa_01\", \"description\": \"丽莎姐姐，很和善对吧，很温柔对吧？但是，这样的姐姐也经常喝酒！呜呜呜…这是为什么啦…蒙德城已经没救了吧…\", \"voicelineId\": 34038, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_teammate_xiangling_01\", \"description\": \"我向香菱讨过一份「口感搭配特别糟糕的食物组合」，据说是她亲自实践下来的，绝对难吃什么的…没用，完全没用。「续杯」两个字已经听到猫耳朵都生茧了！呜…\", \"voicelineId\": 34039, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_teammate_klee_01\", \"description\": \"可莉每次来找我玩的时候，我都只好把她带去离酒馆远一点的地方。酒和炸弹…实在是太危险了！就算我想摧毁蒙德酒业，也得用堂堂正正的方式。\", \"voicelineId\": 34040, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于父亲…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_teammate_father_01\", \"description\": \"爸爸是我最尊敬的人！爸爸是最厉害的人！但是…喝了酒的爸爸，唔——果然还是要早点终结蒙德的酒业！没时间闲聊啦！\", \"voicelineId\": 34041, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪奥娜·其一\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_friendship_01\", \"description\": \"「调酒师」可是很忙的！即使不在酒馆工作，也要抽出时间来收集配方。所以，所以没有要紧事情的话，就不要来打搅我。\", \"voicelineId\": 34042, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解迪奥娜·其二\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_friendship_02\", \"description\": \"你不会…也像那些讨厌的酒鬼一样要我学猫咪叫吧？不会的，绝对不会的！我才不是什么抖抖耳朵伸伸懒腰的宠物！我可是…可是…「酒业杀手」！\", \"voicelineId\": 34043, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪奥娜·其三\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_friendship_03\", \"description\": \"你问我…为什么「酒业杀手」变成了「猫尾酒馆」的招牌…？你，你是故意这样问的吧！就是想看我的笑话。呜，坏人！再也不给你调喝的了，水也不给！\", \"voicelineId\": 34044, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪奥娜·其四\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_friendship_04\", \"description\": \"别再惹我了啊，我宽容大度，但也不好欺负！我警告你，我生起气来可是会咬人的！喵！虽然不一定舍得咬你…\", \"voicelineId\": 34045, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪奥娜·其五\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_friendship_05\", \"description\": \"我和你…已经成为好朋友了，对吧。我隐约记得…我以前也有过这样一个朋友，但我不确定那是不是梦…\\n把你的手给我。啊呜，唔…暖和的。这样就好，不要变成梦走了…\", \"voicelineId\": 34046, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"迪奥娜的爱好…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_pref_hobby\", \"description\": \"我喜欢打猎，追捕猎物可是我的强项！但爸爸说野外情况瞬息万变，只有跟着可靠的大人一起，才能深入森林。你…算是可靠的大人吧？\", \"voicelineId\": 34047, \"voicelineType\": \"6001\"}, {\"title\": \"迪奥娜的烦恼…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_dialog_annoyed\", \"description\": \"嗯…到底怎样才能调出难喝的酒呢…连我给予厚望的噩梦搭配——「酱油牛奶绝云椒椒配蒲公英籽特调」都被说成是「小迪奥娜又有进步了」，呜…我不会认输的…\", \"voicelineId\": 34048, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_pref_foodLike\", \"description\": \"我喜欢吃鱼！作为主食的鱼…爸爸做的鱼！但是…不要作为下酒菜，那是对鱼的亵渎！\", \"voicelineId\": 34049, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_pref_foodDislike\", \"description\": \"胡萝卜、土豆、洋葱、番茄…这些味道都不太喜欢。我，我可不是吃素的啊！\", \"voicelineId\": 34050, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_spice_pref_01\", \"description\": \"好吃…我，我就随便问一下哦，下次还有吗？\", \"voicelineId\": 34086, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_spice_normal_01\", \"description\": \"你可别指望我尝了点甜头，就会来蹭你…\", \"voicelineId\": 34087, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_spice_dislike_01\", \"description\": \"喂…你是把我当成路边的野猫了吗！\", \"voicelineId\": 34088, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_pref_birthday\", \"description\": \"炸鱼，配上这个我特别调制的酱料，给你。\\n…没有加奇怪的东西！我认真调味的手艺才不会差呢，先尝过才可以说话。\\n哼…这才对嘛…唔，那个，生日快乐。\", \"voicelineId\": 34051, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_starUp_01\", \"description\": \"猫的眼睛，看得见黑暗中的一切猎物！\", \"voicelineId\": 34052, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_starUp_02\", \"description\": \"猫的耳朵，听得见地上最细微的脚步声。\", \"voicelineId\": 34053, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_starUp_03\", \"description\": \"猫的四肢，爬得上全提瓦特最高的树。\", \"voicelineId\": 34054, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_diona/vo_diona_starUp_04\", \"description\": \"猫的鼻子，闻得出熟悉的、喜欢的人的…唔？！是你听错了！我怎么可能说出那种话…呜…\", \"voicelineId\": 34055, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_skill1_01\", \"description\": \"嘿…呀！\", \"voicelineId\": 34056, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_skill1_02\", \"description\": \"咻咻——\", \"voicelineId\": 34057, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_skill1_03\", \"description\": \"目标确认。\", \"voicelineId\": 34058, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_skill1_04\", \"description\": \"攻守兼备。\", \"voicelineId\": 34059, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_skill1_05\", \"description\": \"抓到你了！\", \"voicelineId\": 34060, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_skill1_06\", \"description\": \"我可不好欺负！\", \"voicelineId\": 34061, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_skill3_01\", \"description\": \"迪奥娜特调！\", \"voicelineId\": 34062, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_skill3_02\", \"description\": \"贪杯的下场…哼！\", \"voicelineId\": 34063, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_skill3_03\", \"description\": \"反省吧，酒鬼！\", \"voicelineId\": 34064, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_explore_sprint_start_01\", \"description\": \"唔，来了。\", \"voicelineId\": 34065, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺开始·其二\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_explore_sprint_start_02\", \"description\": \"出发，出发！\", \"voicelineId\": 34066, \"voicelineType\": \"700002\"}, {\"title\": \"冲刺结束·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_explore_sprint_end_01\", \"description\": \"呼。\", \"voicelineId\": 34067, \"voicelineType\": \"710001\"}, {\"title\": \"冲刺结束·其二\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_explore_sprint_end_02\", \"description\": \"哈唔…\", \"voicelineId\": 34068, \"voicelineType\": \"710002\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_explore_fly_start_01\", \"description\": \"飞起来喽。\", \"voicelineId\": 34069, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_chest_open_01\", \"description\": \"让酒变难喝的材料啊，出现吧！\", \"voicelineId\": 34070, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_chest_open_02\", \"description\": \"亮晶晶的…想要…扑过去！\", \"voicelineId\": 34071, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_chest_open_03\", \"description\": \"宝箱里有些什么，我很好奇！\", \"voicelineId\": 34072, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_life_less30_01\", \"description\": \"我不会认输…！\", \"voicelineId\": 34073, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_life_less30_02\", \"description\": \"喵…喵…！\", \"voicelineId\": 34074, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_life_less30_03\", \"description\": \"胜负还没分呢！\", \"voicelineId\": 34075, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_life_less30_teammate_01\", \"description\": \"太乱来啦！\", \"voicelineId\": 34076, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_life_less30_teammate_02\", \"description\": \"去休息去休息！\", \"voicelineId\": 34077, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_life_die_01\", \"description\": \"酒的味道…好臭…\", \"voicelineId\": 34078, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_life_die_02\", \"description\": \"泉水精灵…不要走…\", \"voicelineId\": 34079, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_life_die_03\", \"description\": \"眼睛…睁不开了…\", \"voicelineId\": 34080, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_hit_L_02\", \"description\": \"没躲开…\", \"voicelineId\": 34081, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_diona/vo_diona_battle_hit_H_02\", \"description\": \"从哪里来的？\", \"voicelineId\": 34082, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_diona_teamJoin_01\", \"description\": \"狩猎开始！\", \"voicelineId\": 34083, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_diona_teamJoin_02\", \"description\": \"果然需要我出手嘛！\", \"voicelineId\": 34084, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_diona_teamJoin_03\", \"description\": \"哼，就包在我身上。\", \"voicelineId\": 34085, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000041, 'Mona', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_draw_appear\", \"description\": \"我的名字是阿斯托洛吉斯·莫娜·梅姬斯图斯，意为「伟大的占星术士莫娜」。如果想找我占卜，记住我的名字是最基本的尊重…而且要一次性全念对！\", \"voicelineId\": 30009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·占卜\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_explore_idle_01\", \"description\": \"占卜就是把既定的命运准确地展示出来。过度的修饰，只会让人们产生误解。\", \"voicelineId\": 30010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·生活\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_explore_idle_02\", \"description\": \"限制物欲是占星术士修行的一部分，只有简朴地生活，才能窥探到世界的真实。\", \"voicelineId\": 30011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·命运\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_explore_idle_03\", \"description\": \"正是因为无法更改，无可违逆，只能接受，命运才会被称之为命运。\", \"voicelineId\": 30012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_weather_heavyRain_01\", \"description\": \"这么大的雨…不仅看不见星光，连水占盘都模糊了。\", \"voicelineId\": 30013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_weather_thunder_01\", \"description\": \"这些落雷…究竟是从哪个星空降下的呢？\", \"voicelineId\": 30014, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_weather_snowy_01\", \"description\": \"纯净的融雪之水，很适合用在水占盘里。\", \"voicelineId\": 30015, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_weather_sunny_01\", \"description\": \"嗯，是个无须占卜也能感觉到的好天气。\", \"voicelineId\": 30016, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_greetingMorning\", \"description\": \"你来得不巧，清晨的启明星刚刚消失了…早餐？我，我已经吃过了。\", \"voicelineId\": 30017, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_greetingNoon\", \"description\": \"已经正午了，去吃点东西吧，嗯？我…我吃份沙拉就行了，呃…简朴的生活是…是占星术士修行的一环！\", \"voicelineId\": 30018, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_greetingNight\", \"description\": \"入夜了，过会就可以开始占卜…呃，昨天的稿子我写了没…\", \"voicelineId\": 30019, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_greetingNight2\", \"description\": \"已经这么晚了，明天截稿的稿子一点没动…什么？你要去休息了？呜…我也想去睡觉…\", \"voicelineId\": 30020, \"voicelineType\": \"1004\"}, {\"title\": \"关于莫娜自己…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_idle\", \"description\": \"占星术士的工作，是向人们明确地展示他们即将面对的命运，我也是这么做的…不过，总有些人不愿意接受。\", \"voicelineId\": 30021, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·工作\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_idle2\", \"description\": \"为什么要写稿，不用占卜来赚钱？…我才不会为摩拉而使用「水占术」…我也不是因为这个而学习「水占术」的。\", \"voicelineId\": 30022, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·我的命运\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_close\", \"description\": \"我不知道。除非万不得已，占星术士不会占卜自己的命运。老太婆以前说过，这种行为可能会导致命运的自相矛盾，很危险。\", \"voicelineId\": 30023, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·你的命运\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_close1\", \"description\": \"你不是这个世界的人，所以我无法准确地为你预言。我只能告诉你，你要走的路还远未到尽头。\", \"voicelineId\": 30024, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·嫌弃\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_pendant_01\", \"description\": \"我刚刚拿到「神之眼」的时候，那个老太婆还假模假样地说什么「愿你求真之心永在」。结果这东西在「水占术」上一点用场都派不上，只会糊我一身水…\", \"voicelineId\": 30025, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·价值\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_pendant_02\", \"description\": \"哎…不过，「神之眼」当成个小饰品，装在身上倒是无所谓。毕竟，这也算那个抠门老太婆破天荒送我的「教具」。\", \"voicelineId\": 30026, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_share\", \"description\": \"你听说过「命之座」吗？占星术士认为，「命之座」是「神之眼」持有者的命运在星空上的映射，过去，现在和未来，所有的一切都在其中昭示。\", \"voicelineId\": 30027, \"voicelineType\": \"3003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_pref_gift\", \"description\": \"欸——你身边带着的这个小家伙，到底来自哪里？无论我用什么方法，都没法找到一丝关于她命运的踪迹。\\n…哈？你也不知道？\", \"voicelineId\": 30028, \"voicelineType\": \"3004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_teammate_qin_01\", \"description\": \"那位西风骑士团代理团长？她的「命之座」是「幼狮座」，象征着力量，还有过早担负的责任。「雄狮」早早离群，但她会继续成长，直到能完全继承狮群的荣耀。\", \"voicelineId\": 30029, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_teammate_albedo_01\", \"description\": \"阿贝多？啊…我真羡慕他，只用专注于研究就好，不用管其他的杂事，真是美好的生活啊。如果那个老太婆脑筋正常一点，我应该也过着这种生活吧…\", \"voicelineId\": 30030, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_teammate_klee_01\", \"description\": \"你是说，艾莉丝的女儿啊。她住在西风骑士团，还有阿贝多照顾…怎么说呢，哎…她的「命之座」不愧是象征着幸运的「四叶草」啊，真羡慕…\\n啊不过，要是我也有这么好的运气，首先就不会遇见那个老太婆了。\", \"voicelineId\": 30031, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_teammate_diluc_01\", \"description\": \"迪卢克·莱艮芬德。「夜枭」是他的「命之座」，象征着黑夜中的警觉，和孤独的守望。在他所认可的白昼来临之前，他都将孤独前行。\\n等等，「夜枭」象不象征财富来着？\", \"voicelineId\": 30032, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_teammate_kaeya_01\", \"description\": \"凯亚·亚尔伯里奇吗？他的「孔雀羽座」象征着高贵，但同时也象征着「华丽的掩饰」。他以为已经和过去一刀两断。但到了命中注定的那天，他依然必须做出自己的选择。\", \"voicelineId\": 30033, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_teammate_lisa_01\", \"description\": \"她的「命之座」以「沙漏」为名，象征着知识、时间与等价交换。一粒沙子落下，时间…或者说生命，就消逝一刹。如果想要止住沙粒奔流，只能平放沙漏，让它永不流动。嗨…简单来说，就是变着法偷懒啦。\", \"voicelineId\": 30034, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温迪…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_teammate_venti_01\", \"description\": \"温迪？那个成天无所事事的吟游诗人？咦，他有什么有趣的吗？我占卜看看…\\n咦，水占盘怎么…什么也看不清，怎，怎么起风了，眼睛都睁不开了！我的帽子！衣服，衣服要被吹跑了！停下来！我不干了！我不干了！\", \"voicelineId\": 30035, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莫娜·其一\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_friendship_01\", \"description\": \"你的意思是…想要闲聊？唔，我很少做这种浪费时间的事，而且稿子还有很多没写…嗯，不过，对象是你的话，也不是不行。呵呵，就当是换个心情吧。\", \"voicelineId\": 30036, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解莫娜·其二\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_friendship_02\", \"description\": \"占卜的收入…？不要用钱财这种…「东西」来衡量占星术！你听好了，我的「水占术」可是这片提瓦特大陆上，唯一能窥探到真实命运的占卜术！无论是摩拉还是宝石，都无法用来称量「命运」！所以，不要再问这种蠢问题了！\", \"voicelineId\": 30037, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莫娜·其三\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_friendship_03\", \"description\": \"我的占卜术？说了你也不明白，哼，不过…给你解释一下也不是不行。\\n我使用的是「水占术」。是基由星空映射在水面上的幻象进行推演的占卜术，以水中幻相倒映虚假之天，以此来窥探着世界的真实。这是那个老太婆唯一一个正经的研究成果。\", \"voicelineId\": 30038, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莫娜·其四\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_friendship_04\", \"description\": \"阿斯托洛吉斯·莫娜·梅姬斯图斯。这是那个老太婆之前和我一起定的名字，她说这名字的拼写里有一些她很喜欢的要素。哼，不过她有时会叫我「梅姬」，和常用的「莫娜」不一样，更像是小名…喂！你不能这么叫！很害羞的！早知道…早知道就不告诉你了！\", \"voicelineId\": 30039, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莫娜·其五\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_friendship_05\", \"description\": \"占卜师有一个禁忌：在占卜时只陈述预言，绝不提出任何建议。以免自己也陷入别人的「命运」之中。但如果占卜对象是你，那这个「禁忌」就无所谓了。\\n因为，我们的「命运」早就交织在一起了。\", \"voicelineId\": 30040, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"莫娜的爱好…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_pref_hobby\", \"description\": \"我的爱好？仰望星空。在这个真实得太过分的世界里，每个人都需要仰望星空，更何况，我还是个占星术士。\", \"voicelineId\": 30041, \"voicelineType\": \"6001\"}, {\"title\": \"莫娜的烦恼…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_dialog_annoyed\", \"description\": \"仪器修缮费，预订的星象仪要补款了，学术杂志的订购钱也没交，还有下个月的房租…到底先交哪个比较好。果然还是…先把星象仪的尾款补了，不然被抢购光了就糟糕了…\", \"voicelineId\": 30042, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_pref_foodLike\", \"description\": \"沙拉，沙拉是天底下最棒的食物。原料便宜，容易做，饱肚子。而且吃起来很方便，在写稿或者修理仪器的时候，可以很快吃掉。\", \"voicelineId\": 30043, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_pref_foodDislike\", \"description\": \"各种…价格很昂贵，吃起来又很麻烦的食物。因为，呃…用摩拉去满足不必要的食欲，是低俗又危险的。\", \"voicelineId\": 30044, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_spice_pref_01\", \"description\": \"啊，好满足——没想到，认识你还是挺不错的嘛。\", \"voicelineId\": 30074, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_spice_normal_01\", \"description\": \"我再确认一下。真的是…你请客吗？\", \"voicelineId\": 30075, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_spice_dislike_01\", \"description\": \"我没有什么想挑剔的。就是…唔…没怎么吃饱。\", \"voicelineId\": 30076, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_pref_birthday\", \"description\": \"生日快乐。这个袋子给你，里面有一个帮你渡过难关的「建议」。别着急打开，在往后的一年之内，这个袋子会有自己打开的机会。\", \"voicelineId\": 30045, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_starUp_01\", \"description\": \"命中当如此，我早已预知到了。\", \"voicelineId\": 30046, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_starUp_02\", \"description\": \"…再进一步，就能找到世界的真实了吗？\", \"voicelineId\": 30047, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_starUp_03\", \"description\": \"虚假之天，星空下的命运早已注定。\", \"voicelineId\": 30048, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_mona/vo_mona_starUp_04\", \"description\": \"水中之影，涟漪中窥见启明星升起。\", \"voicelineId\": 30049, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_battle_skill1_01\", \"description\": \"水中幻愿。\", \"voicelineId\": 30050, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_battle_skill1_02\", \"description\": \"…命运的虚影。\", \"voicelineId\": 30051, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_battle_skill1_03\", \"description\": \"命运，倒映水中。\", \"voicelineId\": 30052, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_battle_skill3_01\", \"description\": \"命运，在此显现。\", \"voicelineId\": 30053, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_battle_skill3_02\", \"description\": \"命定于此。\", \"voicelineId\": 30054, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_battle_skill3_03\", \"description\": \"天命既定！\", \"voicelineId\": 30055, \"voicelineType\": \"200003\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_explore_fly_start_01\", \"description\": \"这样更能看清星空了…\", \"voicelineId\": 30056, \"voicelineType\": \"700001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_chest_open_01\", \"description\": \"希望这种好事能多来几次…\", \"voicelineId\": 30058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_chest_open_02\", \"description\": \"房租和伙食费，都有着落了！\", \"voicelineId\": 30059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_chest_open_03\", \"description\": \"呜…找到宝物的感觉真棒啊…\", \"voicelineId\": 30060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_life_less30_01\", \"description\": \"无法判断…\", \"voicelineId\": 30061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_life_less30_02\", \"description\": \"讨厌的命运…\", \"voicelineId\": 30062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_life_less30_03\", \"description\": \"还没…推算到这！\", \"voicelineId\": 30063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_life_less30_teammate_01\", \"description\": \"再硬撑，你就会倒下咯。\", \"voicelineId\": 30064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_life_less30_teammate_02\", \"description\": \"你还没到命运的终点。\", \"voicelineId\": 30065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_life_die_01\", \"description\": \"星空…黯淡…\", \"voicelineId\": 30066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_life_die_02\", \"description\": \"无法违抗的…命运…\", \"voicelineId\": 30067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_life_die_03\", \"description\": \"推算结束了…\", \"voicelineId\": 30068, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_battle_hit_L_02\", \"description\": \"烦人。\", \"voicelineId\": 30069, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_mona/vo_mona_battle_hit_H_02\", \"description\": \"离我…远点！\", \"voicelineId\": 30070, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_mona_teamJoin_01\", \"description\": \"此乃，命运。\", \"voicelineId\": 30071, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_mona_teamJoin_02\", \"description\": \"真没办法。\", \"voicelineId\": 30072, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_mona_teamJoin_03\", \"description\": \"繁星，尽在掌握。\", \"voicelineId\": 30073, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000042, 'Keqing', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_draw_appear\", \"description\": \"我是刻晴，璃月七星中的「玉衡」。变革的时机已经到来，维持了千年的秩序即将被改写。这历史性的时刻，你愿意和我一起见证吗？\", \"voicelineId\": 32009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·耽误\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_explore_idle_01\", \"description\": \"耽误太多时间，事情可就做不完了。\", \"voicelineId\": 32010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·放松\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_explore_idle_02\", \"description\": \"劳逸结合是不错，但也别放松过头。\", \"voicelineId\": 32011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·机会\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_explore_idle_03\", \"description\": \"无论是冒险还是做生意，机会都稍纵即逝。\", \"voicelineId\": 32012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_weather_heavyRain_01\", \"description\": \"好大的雨…真耽误事。所以说他们的工作，明明昨天就能做完，为什么要拖到今天？\", \"voicelineId\": 32013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_weather_thunder_01\", \"description\": \"电闪雷鸣虽然有点吓人，但璃月港的防雷防火工事是一流的，不用担心。\", \"voicelineId\": 32014, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_weather_snowy_01\", \"description\": \"没关系，继续前进吧。这种程度的雪，算不了什么。\", \"voicelineId\": 32015, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_weather_sunny_01\", \"description\": \"啊…天气这么好，工作又正好告一段落，要不要…去逛逛街呢？\", \"voicelineId\": 32016, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_greetingMorning\", \"description\": \"早安，早上的状态会为一天奠定基调，就算仍有困意，也要强迫自己打起精神来！\", \"voicelineId\": 32017, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_greetingNoon\", \"description\": \"我没有午休的习惯，不过如果你累了，就去休息吧，三分钟之后我会叫醒你的。\", \"voicelineId\": 32018, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_greetingNight\", \"description\": \"夜幕降临，灯火初上。嗯——又是安宁祥和的一天呢。\", \"voicelineId\": 32019, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_greetingNight2\", \"description\": \"祝你好梦。我吗？…嗯，还有十来件事要处理，做完就能休息了。\", \"voicelineId\": 32020, \"voicelineType\": \"1004\"}, {\"title\": \"关于刻晴自己·理念\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_idle\", \"description\": \"觉得自己是正确的，就要大声地说出来，坚决地去行动——这是我一直以来都贯彻的人生理念。\", \"voicelineId\": 32021, \"voicelineType\": \"2001\"}, {\"title\": \"关于刻晴自己·本职\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_idle2\", \"description\": \"我的本职工作，是管理土地与建设。璃月幅员辽阔，物产丰饶，但若是缺乏合理规划，只重视眼前利益，就没办法抵抗风险。\", \"voicelineId\": 32022, \"voicelineType\": \"2002\"}, {\"title\": \"关于刻晴自己·质疑\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_idle3\", \"description\": \"在你看来，支撑璃月走过千年，最重要的东西是什么？\\n…帝君？…我不这么觉得，因为必须依靠努力才能生存下去的，终究是我们人类啊。高高在上的他却要介入一切。哼，说句不好听的，他真的什么都懂吗？\", \"voicelineId\": 32023, \"voicelineType\": \"2003\"}, {\"title\": \"关于刻晴自己·反思\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_idle4\", \"description\": \"真的接手璃月的各种事务之后，才深感帝君千年来的辛劳。最近我遇上的棘手问题数不胜数，我总会不自觉地去想：「若是帝君，这时候会怎么做呢？」说不定，他真的什么都懂，是我太不成熟了…\", \"voicelineId\": 32024, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·追寻\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_close\", \"description\": \"我很欣赏你，面对神明，不笃信，不盲从，随时保持独立思考，有问题就大胆问出来，没有答案就会一直追寻下去。别不好意思，这才是正确的态度，毕竟，谁又能保证，神就不会犯错呢？\", \"voicelineId\": 32025, \"voicelineType\": \"2005\"}, {\"title\": \"关于我们·尝试\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_close1\", \"description\": \"这没什么难的，你试试就知道了。如果试过以后还不行的话…？不，你从没让我失望过，所以我相信你不是那样的人。\", \"voicelineId\": 32026, \"voicelineType\": \"2006\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·鼓励\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_close2\", \"description\": \"过去的我太天真了。想要和帝君相提并论，我…真的有这个资格吗？…欸？嗯…你说得对，明明在其他事情上都很有自信，为什么我会为这件事烦恼。与其在这里垂头丧气，不如多做多学，努力追上他！\", \"voicelineId\": 32027, \"voicelineType\": \"2007\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·质疑\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_pendant_01\", \"description\": \"都说「神之眼」是神的认可，我才不需要这种东西。不如说我还有点生气呢！就像我一直以来的工作成果，都是多亏了神的力量一样。明明是我自己的功劳，和神才没什么关系。\", \"voicelineId\": 32028, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·反思\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_pendant_02\", \"description\": \"原来…帝君是想让我用超乎常人的力量，去带领大家。哼，就算没有这份认可，我也可以把工作做得很好！等…等着看吧！我不会让他失望的！\", \"voicelineId\": 32029, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·倡议\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_share_01\", \"description\": \"除开「璃月七星」的工作，我也会做很多公益方面的事，大多数的反响都还不错。但类似「每天多工作一个时辰」这样的倡议，就遇到了不小的阻力…唉，看来想法还是太超前了，要不然，下次改成半个时辰试试吧。\", \"voicelineId\": 32030, \"voicelineType\": \"3003\"}, {\"title\": \"有什么想要分享·纪念品\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_share_02\", \"description\": \"帝君的纪念品？你该不会觉得，我的房间里都是这种东西吧？我早就不是小女孩了！虽然…呃，确实是新买了几个帝君的土偶，但、但这些都是用来自我提醒的！和崇拜，仰慕什么的，通通没关系！\", \"voicelineId\": 32031, \"voicelineType\": \"3004\", \"unlockConditions\": [{\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_pref_gift\", \"description\": \"我听过一则流传在蒙德的故事：勇气让小鸟学会了飞翔。不过，应该是先有对浩瀚天空无与伦比的向往，才会有振翅的冲动与勇气吧。对我来说，璃月，就是那片天空。\", \"voicelineId\": 32032, \"voicelineType\": \"3005\"}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_zhongli_01\", \"description\": \"那位「往生堂」的先生，确实博学多才，令人敬佩，但他的思维方式，终究还是太像帝君的那一套了…如果他更有主见的话，将他招揽到我的身边做事，一定会大有帮助。\", \"voicelineId\": 32033, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_beidou_01\", \"description\": \"这位船长总是漠视规则，性格令人头疼，可她的「南十字」船队，对璃月港来说又是必不可少的。如何平衡规则和利益，也是一门艺术。哎呀，只不过那位负责律法的「天权」，可有的忙了。\", \"voicelineId\": 32034, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光·矛盾\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_ningguang_01\", \"description\": \"我和她虽然是同事，但性子真的合不来。在她的眼里，璃月港不过是她的生意场，只要是能赚钱的事，她什么都做。这岂不是太没原则了？唔…还是说，这就是她的原则？\", \"voicelineId\": 32035, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光·合作\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_ningguang_02\", \"description\": \"帝君离开之后，我们难得地达成了很多共识。过去我对她的评价，确实有点偏颇。尽管根本的观念不同，但在现在的时局下，也只能把她视为战友了。\", \"voicelineId\": 32036, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光·琐事\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_ningguang_03\", \"description\": \"话虽这么说！明星斋的「琉璃新月」，我提前三个月就预定了！结果去取货的时候才知道，凝光她用两倍的价钱，把这几个月里所有的「琉璃新月」都买走了！果然我还是受不了她！\", \"voicelineId\": 32037, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于辛焱…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_xinyan_01\", \"description\": \"其实我也对她的「摇滚」很感兴趣。从传统文化的视角看，确实有点喧闹，但我不在乎。好听就是好听，好听的东西就应该发扬光大。\", \"voicelineId\": 32038, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于白术…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_baizhu_01\", \"description\": \"白术先生的医术备受居民的信赖，如果有什么疑难杂症，去找他肯定不会有错。你说…那些奇怪的传闻？我只知道有一件事是真的，他开的药，确实特别苦，不止是小孩子觉得…给我都留下了很深刻的印象。\", \"voicelineId\": 32039, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_xiangling_01\", \"description\": \"「万民堂」的这位年轻掌勺，我知道她很有才华，但发挥还是太不稳定了。以前本来想找她定制几桌宴席的，可是尝过她蜥蜴还有史莱姆的试菜之后…我就打消了这个念头。\", \"voicelineId\": 32040, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_xingqiu_01\", \"description\": \"我听说过他的故事，明明出身名门望族，却不爱家族事业，喜欢去外面行侠仗义。我很欣赏他，毕竟，把家里的条条框框丢到一边，执意去做心中认为正确的事，这种魄力，可不是谁都有的。\", \"voicelineId\": 32041, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_xiao_01\", \"description\": \"传闻中的少年仙人，现如今在这人治之世，也应该放下身上的重担了吧。人类已经不需要这样的守护了，就算遇上什么棘手的难题，我们也有自行解决的能力。\", \"voicelineId\": 32042, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨·质疑\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_ganyu_01\", \"description\": \"我也不知道帝君当年做了什么，才会让甘雨对他这么忠心耿耿。不过，没主见也有没主见的好处——至少，就算是心中颇有微词，她也会按我说的去做，很有职业素养。\", \"voicelineId\": 32043, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨·反思\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_ganyu_02\", \"description\": \"因为最近有很多事都拿不定主意，我经常去向她询问意见，毕竟，她可能是璃月最熟悉帝君的人了。唉，想起以前，在她面前说了很多得罪帝君的话，还是有点不好意思，不过，她似乎没那么介意，这让我松了口气…\", \"voicelineId\": 32044, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于云堇…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_yunjin_01\", \"description\": \"路过和裕茶馆的时候，如果发现被围得水泄不通，那一定就是云堇正在台上唱戏。许多商人都觉得，只是为了云堇，就值得把整个茶馆都买下来。\", \"voicelineId\": 32045, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于风之神…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_venti_01\", \"description\": \"帝君离去之后，我一直都在思考，璃月港的未来该怎么走。除了参考帝君以前的行动，我还去研究了其他神明的治世手段。可是，邻国蒙德就让我很是困惑…像风之神这种做法，真的能让蒙德长久吗？\", \"voicelineId\": 32046, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于烟绯…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_yanfei_01\", \"description\": \"在我看来，律法是对过去「正确事物」的总结，但也具有时效性，需要不断完善和改进。璃月即将迎来剧变，熟知律法的人才不可多得，要是烟绯小姐愿意担任我的助手，许多麻烦就迎刃而解了。\", \"voicelineId\": 32047, \"voicelineType\": \"4015\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夜兰…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_yelan_01\", \"description\": \"夜兰小姐的祖辈曾为七星效力，我的祖父也曾与她的家族有过学术合作。总体来说，她办事可靠，干净利落，时常为总务司提供重要的情报。虽然我也不清楚，夜兰小姐究竟是从哪听说这些消息的。\", \"voicelineId\": 32048, \"voicelineType\": \"4016\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于蓝砚…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_teammate_lanyan_01\", \"description\": \"蓝师傅为人谦和，手艺精湛，往后总务司或有更多推广民间工艺的筹划，还要仰赖像她这样的手工大师支持。欸…抛开工作不谈？那自然也很欢迎她多来璃月港玩，我们应该挺聊得来的。\", \"voicelineId\": 32092, \"voicelineType\": \"4017\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解刻晴·其一\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_friendship_01\", \"description\": \"想要了解我？好啊，那我先把「玉衡」的工作原则讲给你听，等你熟记了这一百多条关键条目，就一定对我的理想了如指掌了！\", \"voicelineId\": 32049, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解刻晴·其二\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_friendship_02\", \"description\": \"万事万物都不可脱离联系独立存在，倘若一件事拖了后腿，与它联系的诸多事项也都会遭殃。所以，「今日事今日毕」。不是我性子急，而是事情本来就不能拖延。\", \"voicelineId\": 32050, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解刻晴·其三\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_friendship_03\", \"description\": \"不用和我太客气，「玉衡」说到底只是虚名，我不希望你因为我的身份，而把想说的话藏在心里——因为有话直说，这才是你独一无二的地方，也是我最欣赏的地方。\", \"voicelineId\": 32051, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解刻晴·其四\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_friendship_04\", \"description\": \"和你一起冒险，已经很长时间了。我越来越觉得，你就是我理想中的那个人——欸？这么吃惊干什么？为了建成我理想中的璃月，你的确是不可或缺的啊？\", \"voicelineId\": 32052, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解刻晴·其五\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_friendship_05\", \"description\": \"「想要在帝君的土地上，留下属于人类的印记。」这果然很不容易啊。但我想和你定下一个约定——等到新时代的璃月港落成之时，来看看吧，我来领路。只有让你亲眼见证这里的脱胎换骨，才不会辜负你对我的陪伴和支持。\", \"voicelineId\": 32053, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"刻晴的爱好…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_pref_hobby\", \"description\": \"这么多式样、这么多质地、这么多选择…啊，这就是「消费」呀，真是令人难以抵御的魅力。\", \"voicelineId\": 32054, \"voicelineType\": \"6001\"}, {\"title\": \"刻晴的烦恼…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_dialog_annoyed\", \"description\": \"璃月人的生活越来越好，这确实没错，但不思进取，好吃懒做的人也越来越多了。唉，「璃月七星」很努力地改善社会福利，可不是为了养活这帮闲人啊。\", \"voicelineId\": 32055, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_pref_foodLike\", \"description\": \"从道理上说，不应该对食物有什么贪欲，但唯独那一道美味的金丝虾球…总是让我忘不了。哪怕就吃一个，也能满足味蕾，扫清身上积累的所有压力。\", \"voicelineId\": 32056, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_pref_foodDislike\", \"description\": \"每种菜肴都有最理想的味道，我不能接受除此以外的做法，尝试都不行。比如，咸味的杏仁豆腐，甜味的莲子禽蛋羹什么的…都是在暴殄天物！\", \"voicelineId\": 32057, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_spice_pref_01\", \"description\": \"没错，正是我喜欢的。\", \"voicelineId\": 32089, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_spice_normal_01\", \"description\": \"味道中规中矩，但你的努力值得肯定。\", \"voicelineId\": 32090, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_spice_dislike_01\", \"description\": \"和理想中的味道有些差距…\", \"voicelineId\": 32091, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_pref_birthday\", \"description\": \"生日快乐！我为你准备了一份特别的礼物。别看这只是一盏普普通通的灯，只要有一点点雷元素力，就可以点亮很长时间。在你需要光的时候，就用它吧。\", \"voicelineId\": 32058, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_starUp_01\", \"description\": \"心有所向，日复一日，必有精进。\", \"voicelineId\": 32059, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_starUp_02\", \"description\": \"很好，在需要随机应变的时候，又多了一种选择。\", \"voicelineId\": 32060, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_starUp_03\", \"description\": \"「昨天的经历都将成为明天的力量。」而这一切，都是与你同行的收获。\", \"voicelineId\": 32061, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_keqing/vo_keqing_starUp_04\", \"description\": \"能和你一路结伴而行，我感觉受益匪浅。如果真的有一天，我抵达了理想中的终点…我的身边，还会有你陪伴吗？\", \"voicelineId\": 32062, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_skill1_01\", \"description\": \"去吧！\", \"voicelineId\": 32063, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_skill1_02\", \"description\": \"迅影如剑！\", \"voicelineId\": 32064, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_skill1_03\", \"description\": \"可别眨眼。\", \"voicelineId\": 32065, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_skill1_04\", \"description\": \"喝啊——！\", \"voicelineId\": 32066, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_skill1_05\", \"description\": \"嘿！\", \"voicelineId\": 32067, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_skill1_06\", \"description\": \"哈！\", \"voicelineId\": 32068, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_skill3_01\", \"description\": \"无处可逃！\", \"voicelineId\": 32069, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_skill3_02\", \"description\": \"剑出，影随——\", \"voicelineId\": 32070, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_skill3_03\", \"description\": \"剑光如我，斩尽芜杂！\", \"voicelineId\": 32071, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_chest_open_01\", \"description\": \"一份付出，一份收获。\", \"voicelineId\": 32072, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_chest_open_02\", \"description\": \"不错的珍宝。\", \"voicelineId\": 32073, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_chest_open_03\", \"description\": \"收纳完毕，就重新出发吧。\", \"voicelineId\": 32074, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_life_less30_01\", \"description\": \"以退为进…\", \"voicelineId\": 32075, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_life_less30_02\", \"description\": \"有点轻敌了。\", \"voicelineId\": 32076, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_life_less30_03\", \"description\": \"调整战略吧。\", \"voicelineId\": 32077, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_life_less30_teammate_01\", \"description\": \"先避避风头，让我来！\", \"voicelineId\": 32078, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_life_less30_teammate_02\", \"description\": \"别太冒失了！\", \"voicelineId\": 32079, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_life_die_01\", \"description\": \"时机…不对。\", \"voicelineId\": 32080, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_life_die_02\", \"description\": \"太不甘心了…\", \"voicelineId\": 32081, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_life_die_03\", \"description\": \"辜负了…期待。\", \"voicelineId\": 32082, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_hit_L_01\", \"description\": \"唔…可恶。\", \"voicelineId\": 32083, \"voicelineType\": \"900001\"}, {\"title\": \"普通受击·其二\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_hit_L_02\", \"description\": \"小伤而已。\", \"voicelineId\": 32084, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_keqing/vo_keqing_battle_hit_H_02\", \"description\": \"只是巧合…\", \"voicelineId\": 32085, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_keqing_teamJoin_01\", \"description\": \"走吧，时间紧迫。\", \"voicelineId\": 32086, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_keqing_teamJoin_02\", \"description\": \"是突发事件吗？\", \"voicelineId\": 32087, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_keqing_teamJoin_03\", \"description\": \"速战速决。\", \"voicelineId\": 32088, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000043, 'Sucrose', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_draw_appear\", \"description\": \"我是砂糖，炼金术的…研究员。听说你去过很多地方，一定也…不，没什么，第一次见面，不该这么麻烦你。但…如果你愿意，和我讲讲路上有意思的事，那个…我，会很开心的。\", \"voicelineId\": 31009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·好奇\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_explore_idle_01\", \"description\": \"那是什么？啊…不见了，我可以去看看吗！\", \"voicelineId\": 31010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·整理\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_explore_idle_02\", \"description\": \"趁现在，赶快整理一下研究笔记…\", \"voicelineId\": 31011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·深呼吸\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_explore_idle_03\", \"description\": \"嗯——！好久没出来透气了。\", \"voicelineId\": 31012, \"voicelineType\": \"1103\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_weather_gale_01\", \"description\": \"今天城里的风车，转得好快。欸，你说，如果在小动物背上，也装一个像风车一样的东西，会让它们跑得更快呢，还是会飞起来呢？\", \"voicelineId\": 31013, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_weather_snowy_01\", \"description\": \"这么大的雪，一年都没有几次，错过了，想研究就要等明年了，所以就别拦我啦。啊…阿嚏！呃…我知道了，我多穿一点…\", \"voicelineId\": 31014, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_weather_sunny_01\", \"description\": \"天…天已经亮了？！那、那再做最后一次实验吧，做完就休息！嗯，最后一次…\", \"voicelineId\": 31015, \"voicelineType\": \"1204\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_weather_heavyRain_01\", \"description\": \"湿度上升，嗯…要不要再加一组实验呢？\", \"voicelineId\": 31016, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_greetingMorning\", \"description\": \"早上好，昨晚睡得还好吗？研究表明，只有睡眠充足，第二天的精神才会好，而且，脑袋的运转也会更高效哦。欸…什么？我总是熬夜？那个…唔，没办法嘛。\", \"voicelineId\": 31017, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_greetingNoon\", \"description\": \"呜哇！别、别过来！啊…不是，我的意思是，不要靠得太近，我在做实验，这个…可能会爆炸的。\", \"voicelineId\": 31018, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_greetingNight\", \"description\": \"晚上好，啊…请稍等一下！「实验体玖零伍式」的光照分泌物其实有两种，为了明确区分，就叫「壹零叁叁式」和「壹零叁伍式」…嗯，好了，请问有什么事情要找我吗？\", \"voicelineId\": 31019, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_greetingNight2\", \"description\": \"不用等我，先去休息吧。唔…有这么不放心吗？实验已经在收尾了，不会熬夜的，真的…\", \"voicelineId\": 31020, \"voicelineType\": \"1004\"}, {\"title\": \"关于砂糖自己·「生物炼金」\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_idle\", \"description\": \"「生物炼金」，比起「创造」，更注重「改造」，找到生物隐藏起来的优点，然后放大，结合，结果往往都让人大吃一惊。嗯…生命真的是太神奇了，究竟还有多少我们不知道的东西呢？\", \"voicelineId\": 31021, \"voicelineType\": \"2002\"}, {\"title\": \"关于砂糖自己·怕生\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_idle2\", \"description\": \"我…其实我不知道怎么和陌生人说话。每个人性格都不一样，在意的东西也不一样，一不小心就会不够礼貌，或者哪里冒犯了，唉…说话真的好难啊，比炼金术什么的难多了。\", \"voicelineId\": 31022, \"voicelineType\": \"2003\"}, {\"title\": \"关于砂糖自己·耳朵\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_idle3\", \"description\": \"你…你注意到了啊。我的耳朵是家里遗传下来的，和其他人很不一样，所以平时我都会用头发尽量把它们藏起来…\", \"voicelineId\": 31023, \"voicelineType\": \"2004\"}, {\"title\": \"关于我们·观察\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_close\", \"description\": \"我对你的经历，特别好奇，所以…我可以「观察」你一段时间吗？我会很安静的，不会打扰你，这样…你会介意吗？\", \"voicelineId\": 31024, \"voicelineType\": \"2005\"}, {\"title\": \"关于我们·收获\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_close1\", \"description\": \"老实说，一开始我看你不怎么说话，有点害怕…还以为是在哪里冒犯了你，后来时间长了才慢慢发现，原来，你还是挺好相处的。嘿嘿，这也算…「观察」的意外收获吧。\", \"voicelineId\": 31025, \"voicelineType\": \"2006\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·请求\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_close2\", \"description\": \"听说，是你赶走了风魔龙？战斗一定特别危险吧，幸好你没事。那个…有件小事，风魔龙它在战斗的时候，有没有，掉下来什么东西呢？鳞也好，皮也好，一点点就可以，我想，研究一下…\", \"voicelineId\": 31026, \"voicelineType\": \"2007\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [30904], \"unlockText\": \"完成「捕风的异乡人」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_pendant_01\", \"description\": \"「神之眼」，是我最重要的实验器材。欸？就、就是实验器材啊，没有了「神之眼」，很多跟元素相关的实验，就没办法进行了。你说战斗？啊…偶尔吧，去野外找材料的时候，偶尔会用到。\", \"voicelineId\": 31027, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_share\", \"description\": \"这个房间里，都是我收藏的骨头。放在左边柜子里的，有蜥蜴，青蛙，还有草鱼，挂在前面的是野猪，右边角落里的那个，是丘丘人…啊，别紧张，不用害怕，其实都是很可爱的东西，习惯了就好了。\", \"voicelineId\": 31028, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_pref_gift\", \"description\": \"你看，种在这里的冰雾花，其实每一朵都不一样。这一朵冰元素含量更高，这一朵花期更长…嗯？你问那一朵，哦，那一朵叫「叁式冰雾花改十七号放大版」，特点，嗯…就是更大一点。\", \"voicelineId\": 31029, \"voicelineType\": \"3003\"}, {\"title\": \"关于诺艾尔…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_teammate_noel_01\", \"description\": \"她…经常会主动帮我的忙，但有时候太热情了，反而…让我有点苦恼。有一次，她看到我实验室门前堆了三箱器材，就很麻利地帮我搬了进来，但其实…那些都是我刚刚搬出去的。\", \"voicelineId\": 31030, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_teammate_klee_01\", \"description\": \"她已经被琴团长关过好多次禁闭了，但只要被放出来，不久就又会闯祸，唉，不知道有没有真的反省过。啊…我答应她，要帮她做一个会蹦会跳，又很安全的蹦蹦，只不过现在，设计上还有不少问题…\", \"voicelineId\": 31031, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_teammate_qin_01\", \"description\": \"我有点不敢和琴团长说话，因为她太严肃了…我知道她是个很好的人，但、但知道归知道，害怕…还是会害怕。我一般都不会去打扰她，实在有不得不找她的事，我…我也会拜托阿贝多先生。\", \"voicelineId\": 31032, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_teammate_lisa_01\", \"description\": \"我觉得她，好像懂的特别多。她明明没有看过我的研究，但有好几次，都给了我最关键的建议。她到底是怎么知道的呢？是…观察？还是推理呢？\", \"voicelineId\": 31033, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_teammate_kaeya_01\", \"description\": \"唔…我知道他喜欢开玩笑，也没有存心捉弄我的意思。可是，我实在是…分不清他的哪句话是真话，哪句话又是玩笑，所以最后要不然就变得很尴尬，要不然，就是我出洋相…\", \"voicelineId\": 31034, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多·艺术\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_teammate_albedo_01\", \"description\": \"当他的助手，每天都能学到很多。重点不是知识，而是「天才」的思考方法，无论是多么复杂的问题，他总能抽丝剥茧，再一一解决。在我看来，那就是艺术…\", \"voicelineId\": 31035, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多·天赋\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_teammate_albedo_02\", \"description\": \"你说天赋？嗯…假如和他做同样的研究，可能确实一辈子都没法超过他。但，我研究「生物炼金」并没有故意要躲开他的意思，只是…嗯，我和他恰好有不同的爱好，还有梦想，仅此而已吧。\", \"voicelineId\": 31036, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_teammate_ambor_01\", \"description\": \"我很好奇，为什么她做的布偶，名字叫「兔兔伯爵」呢？和兔子没什么关系吧。唔…你说，头上的发带，很像兔耳朵？…有道理，但其实这是刻板印象，也有很多兔子耳朵是垂下来的。\", \"voicelineId\": 31037, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲谢尔…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_teammate_fischl_01\", \"description\": \"你是说《菲谢尔皇女夜谭》？我知道，作者创造出的世界很有意思，要是能亲眼去看一看就好了…欸？你在说那个「菲谢尔」啊？她啊…嗯，她…应该是没办法带我去的。\", \"voicelineId\": 31038, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于优菈…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_teammate_eula_01\", \"description\": \"游击骑士的工作很危险，优菈小姐的行动又格外大胆，所以我给她制作了一个侦察装置，这样她就不用潜入敌人的营地了。但优菈小姐的气势太吓人，我有点怕她，告诉她使用方法的时候，不小心漏掉了几条注意事项，结果真的发生了意外…\\n怎么办？我会不会被她记仇了…\", \"voicelineId\": 31039, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解砂糖·其一\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_friendship_01\", \"description\": \"了解我？你…是对「生物炼金」感兴趣吗？你有疑问的话，我会尽量给你准确答案的。嗯？不是炼金，而是「我」？唔，这个，我也不知道该说什么…\", \"voicelineId\": 31040, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解砂糖·其二\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_friendship_02\", \"description\": \"研究的本质，是寻找答案的过程。这个过程有时候很繁琐，也很累，但每次只要看看积累起来的成果，就会觉得…嗯，我是真的很喜欢做这样的事。\", \"voicelineId\": 31041, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解砂糖·其三\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_friendship_03\", \"description\": \"小时候，我有两个好朋友，我们无话不说。本来我以为，我对她们了解得一清二楚，但后来发生了一些事，我突然就…看不透她们了。她们现在在哪儿，在做什么，还记不记得我，这些…我都不知道。就算再好的朋友，也会变成这样呢。\", \"voicelineId\": 31042, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解砂糖·其四\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_friendship_04\", \"description\": \"告诉你一个小秘密，我对谁都没有讲过。「生物炼金」的最终目标，是创造出「仙境」…对，就是童话里的那个，能找到永远的快乐与幸福的「仙境」。嘿嘿，有点幼稚对吧？但，我现在都还相信那个故事。\", \"voicelineId\": 31043, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解砂糖·其五\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_friendship_05\", \"description\": \"嗯…如果你忙的话，就去忙吧，我不想给你添麻烦。不忙？真的不忙吗？没事的，就算忙也没关系，一个人做实验我早就习惯了。啊…真、真的不忙？那…那可不可以，帮帮我的忙？或者…只是陪我说说话，什么的…\", \"voicelineId\": 31044, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"砂糖的爱好…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_pref_hobby\", \"description\": \"我喜欢看起来很规则的东西，你看，书架上每一本实验记录，厚度都是一样的，实验台上的几百瓶药水，都是按功效与颜色分别排好…欸？…欸欸？！为什么这瓶紫色的药水会出现在这里！我、我要全部整理一遍！\", \"voicelineId\": 31045, \"voicelineType\": \"6001\"}, {\"title\": \"砂糖的烦恼…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_dialog_annoyed\", \"description\": \"我想知道，你平时休息的时候，会干些什么呢？每到休息日，我就找不到事情做，只能发呆…明明做实验的时候时间过得很快，休息的时候，怎么就有种度日如年的感觉…\", \"voicelineId\": 31046, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_pref_foodLike\", \"description\": \"我会提炼出甜甜花的花蜜，做成糖块。脑袋转不动的时候吃一块，就又可以集中精神了。做研究，糖分的补充是很重要的。\", \"voicelineId\": 31047, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_pref_foodDislike\", \"description\": \"知道了很多「生物炼金」的知识之后，我就不怎么吃蘑菇了…你应该知道吧？蘑菇，是长在死掉的生物上的，联想到同类的其他东西，我、我的胃口就…呃…\", \"voicelineId\": 31048, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_spice_pref_01\", \"description\": \"好吃！啊…趁着现在状态最好，赶紧把研究做完…\", \"voicelineId\": 31076, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_spice_normal_01\", \"description\": \"比我做的营养餐好吃了不少。嗯，我也算改善伙食了。\", \"voicelineId\": 31077, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_spice_dislike_01\", \"description\": \"对不起。我对这道菜，还是有点…\", \"voicelineId\": 31078, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_pref_birthday\", \"description\": \"生日快乐！我做了好几个月的实验，终于，可以把这个药水送给你了。它能唤醒你这一年来最美好的回忆，名字叫做「生物秘药叁玖壹陆号」…唔，不是「叁壹玖陆号」，是「叁玖壹陆号」啦！\", \"voicelineId\": 31049, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_starUp_01\", \"description\": \"「生物炼金」的研究，终于有突破了。\", \"voicelineId\": 31050, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_starUp_02\", \"description\": \"这次旅行，我又收集到了很多研究材料，谢谢你，我会好好利用的。\", \"voicelineId\": 31051, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_starUp_03\", \"description\": \"最近我在做实验的时候，经常会莫名地期待起来，什么时候又可以和你一起去冒险。唔…好奇怪，这是为什么呢？我要研究看看。\", \"voicelineId\": 31052, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_sucrose/vo_sucrose_starUp_04\", \"description\": \"我收集到的研究材料，已经很足够了！花更多时间在我的身上，会…会很浪费的！至少…也让我用「生物炼金」，做点什么回礼给你！\", \"voicelineId\": 31053, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_battle_skill1_01\", \"description\": \"吸附力测试。\", \"voicelineId\": 31054, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_battle_skill1_02\", \"description\": \"陆叁零捌式风单元！\", \"voicelineId\": 31055, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_battle_skill1_03\", \"description\": \"确认…安全距离！\", \"voicelineId\": 31056, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_battle_skill3_01\", \"description\": \"超扩散态！\", \"voicelineId\": 31057, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_battle_skill3_02\", \"description\": \"柒伍式超级风模块！\", \"voicelineId\": 31058, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_battle_skill3_03\", \"description\": \"无相之风…拟造！\", \"voicelineId\": 31059, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_chest_open_01\", \"description\": \"宝箱的出现成因…也值得研究。\", \"voicelineId\": 31060, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_chest_open_02\", \"description\": \"真希望实验材料也能成箱出现啊。\", \"voicelineId\": 31061, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_chest_open_03\", \"description\": \"太好了，有这么多素材！\", \"voicelineId\": 31062, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_life_less30_01\", \"description\": \"这种误差，还能接受…\", \"voicelineId\": 31063, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_life_less30_02\", \"description\": \"有点，超出预想…\", \"voicelineId\": 31064, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_life_less30_03\", \"description\": \"不痛不痛，不痛的…\", \"voicelineId\": 31065, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_life_less30_teammate_01\", \"description\": \"快回来，我这里有药水！\", \"voicelineId\": 31066, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_life_less30_teammate_02\", \"description\": \"小心点，看准了再上！\", \"voicelineId\": 31067, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_life_die_01\", \"description\": \"研究…又失败了。\", \"voicelineId\": 31068, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_life_die_02\", \"description\": \"还需要…调整。\", \"voicelineId\": 31069, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_life_die_03\", \"description\": \"该…睡一会儿了。\", \"voicelineId\": 31070, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_battle_hit_L_02\", \"description\": \"不应该啊…\", \"voicelineId\": 31071, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_sucrose/vo_sucrose_battle_hit_H_02\", \"description\": \"眼镜会碎掉的！\", \"voicelineId\": 31072, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_sucrose_teamJoin_01\", \"description\": \"希望能帮上忙…\", \"voicelineId\": 31073, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_sucrose_teamJoin_02\", \"description\": \"我、我会努力的！\", \"voicelineId\": 31074, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_sucrose_teamJoin_03\", \"description\": \"实验…一定要成功。\", \"voicelineId\": 31075, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000044, 'Xinyan', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_draw_appear\", \"description\": \"我是辛焱，璃月港唯一的摇滚乐手，最近在想要不要去其他地方巡回演出，目的地的话…啊，听说你是走遍了很多地方的旅行者，对吧？让我加入你们吧！去哪里都行。\", \"voicelineId\": 33009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·气势\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_explore_idle_01\", \"description\": \"摇滚不可缺少的，就是激情——喂，别发呆了，快动起来！\", \"voicelineId\": 33010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·新曲\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_explore_idle_02\", \"description\": \"要不我来弹首曲子给你听，我新写的哦？\", \"voicelineId\": 33011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·注目\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_explore_idle_03\", \"description\": \"快看那边！好像有很摇滚的东西！\", \"voicelineId\": 33012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_weather_heavyRain_01\", \"description\": \"这么大的雨…可不能让琴被淋到了啊。\", \"voicelineId\": 33013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_weather_thunder_01\", \"description\": \"看样子这雨一时半会儿不会停…嗯，但演出不会推迟！\", \"voicelineId\": 33014, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_weather_snowy_01\", \"description\": \"唔…这种天气要怎么吸引观众呢？对了！来一场「暴风雪极限耐力摇滚挑战」怎么样！\", \"voicelineId\": 33015, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_weather_gale_01\", \"description\": \"呜哇，快找个地方躲躲，不然发型要塌了！\", \"voicelineId\": 33016, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_greetingMorning\", \"description\": \"早啊，我刚刚在开嗓，今天嗓子的状态也好得很呢。\", \"voicelineId\": 33017, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_greetingNoon\", \"description\": \"啊，收工了收工了，哈…没什么事的话，我去打个盹儿。\", \"voicelineId\": 33018, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_greetingNight\", \"description\": \"马上就要演出了，你也一起来嗨吗？\", \"voicelineId\": 33019, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_greetingNight2\", \"description\": \"哦，好的，你先去睡吧。我吗？我还要保养我的琴，还想改改曲子，嘿嘿，刚从舞台下来，睡也睡不着的。\", \"voicelineId\": 33020, \"voicelineType\": \"1004\"}, {\"title\": \"关于辛焱自己·凶恶\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_idle\", \"description\": \"你居然不怕我？唉，有人说，我眼神跟刀子一样，衣服不好好穿，讲话也不守规矩。他们一看到我就躲得远远的，哎，真是…只是风格不一样而已，我又不是什么怪物…\", \"voicelineId\": 33021, \"voicelineType\": \"2001\"}, {\"title\": \"关于辛焱自己·摇滚\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_idle2\", \"description\": \"摇滚是从枫丹传过来的，算是新东西吧。不过啊，在璃月挺不受欢迎的，一般人都觉得吵吵嚷嚷，不喜欢听。所以我啊，很感激每一个能来听我唱歌的人，哈哈。\", \"voicelineId\": 33022, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·观演\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_close\", \"description\": \"来看我演出？哈，到前面来吧！前面的感觉更好。咳咳，那么，璃月港独一份的摇滚现场，现在开始！\", \"voicelineId\": 33023, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·投缘\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_close1\", \"description\": \"我还在想为什么和你这么聊得来，原来你不是这个世界的人，那也就用不着关心这个世界的条条框框了——人生就该是这样！繁文缛节什么的统统闪一边去，无拘无束，自由自在。\", \"voicelineId\": 33024, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·邀请\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_close2\", \"description\": \"我想让我摇滚的音乐元素更丰富一点。其实，你的节奏感很好嘛，要不要试试帮我打鼓？没打过？唉呀，不要怯场，关键是气势。来试试看嘛，你绝对很有天赋的。\", \"voicelineId\": 33025, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_pendant\", \"description\": \"会把「神之眼」的火用来给摇滚伴奏的，估计全提瓦特也就我一个。有人批评我，应该好好敬重这种力量…不过，既然神都把「神之眼」给了我，就说明他对我的用法，也是认可的吧。\", \"voicelineId\": 33026, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·命名\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_share_01\", \"description\": \"这把琴，是我亲手做的哦。本来是按照枫丹的摇滚乐器来做的，但做着做着就不再是一个东西了。我一直想给它取一个好听又好记的名字，比如「焱琴」「碎玉」「定山」什么的，但还是差点味道…你有什么好主意吗？\", \"voicelineId\": 33027, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·宴乐\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_share_02\", \"description\": \"欸，你知道「宴乐」吗？就是有钱人在宴会上听的曲子。一会儿唱这个多有本事，一会儿又唱那个多了不起…把音乐用成这个样子，哎呀，一点儿都不摇滚。\", \"voicelineId\": 33028, \"voicelineType\": \"3003\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_pref_gift\", \"description\": \"我最喜欢的一套演出服，是我亲手用「霓裳花」织的。你肯定也见过那种花吧，红得够激情。而且，和我的摇滚也很搭呢。\", \"voicelineId\": 33029, \"voicelineType\": \"3004\"}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_teammate_xiangling_01\", \"description\": \"我经常去「万民堂」吃夜宵，香菱如果手头不忙，还经常跟我聊天，一直聊到很晚很晚。啊？你问我都点的啥？嗯…其实是香菱做啥我吃啥，哈哈。每次都不一样，味道也千变万化，她可以说是料理界的「摇滚明星」了！\", \"voicelineId\": 33030, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_teammate_zhongli_01\", \"description\": \"以前没什么人听我的摇滚，有一天他突然来邀请我，说可以去他那里试试，合适的话可以去当驻唱歌手，我心里激动啊，终于有人理解我的音乐了！就直接答应了下来。结果去了场地才知道，他居然是那个「往生堂」的客卿…这明显不合适啊，真是个怪人。\", \"voicelineId\": 33031, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_teammate_ningguang_01\", \"description\": \"你知道千岩军吧？他们以前总是妨碍我，说什么这里也不准搭舞台，那里也不准，麻烦死了。咳咳，不过在我找总务司申诉之后，听说那个「天权星」专门修订了璃月的什么…呃…反正是某个规则，划定了演出专属场地，还要申请什么许可。哎…其实还是很麻烦，不过，好歹不用像之前一样，被赶得到处乱跑了嘛。\", \"voicelineId\": 33032, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于白术…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_teammate_baizhu_01\", \"description\": \"白术先生开的药方保养嗓子效果一流，为了答谢他，我在他面前来了一段即兴摇滚，结果…他养的那条蛇就晕了过去。从那以后，那条蛇看到我就一个劲儿地往白术先生的衣领里面钻，哈哈哈。我从那以后才知道，蛇原来对震动很敏感。\", \"voicelineId\": 33033, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_teammate_beidou_01\", \"description\": \"她啊，说话直爽，气量也大，聊起来特别投缘。「死兆星」号乘风破浪的故事，实在是太帅了，给了我很多摇滚的灵感。嘿嘿，我还专门写了一首歌给他们。现在，只要我唱第一句，好多船员都能跟我唱下去，都快变成船歌啦。\", \"voicelineId\": 33034, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于重云…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_teammate_chongyun_01\", \"description\": \"他超有意思！看上去文静内向，但有一次演出，他好像是被朋友叫过来，要跟我说什么话。舞台上声音太大，我还没听清呢，他已经一个箭步跳上台来和我一起唱了，还唱得特别摇滚。这就叫「人不可貌相」吧。\", \"voicelineId\": 33035, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_teammate_hutao_01\", \"description\": \"她明明是往生堂的堂主，却每天一副开开心心的样子，完全不知道在想什么。街上碰到的话，还会大大方方地和我打招呼，说什么「喜欢玩火的人，是生意兴隆的保障呢。」…呃，有、有点诡异。\", \"voicelineId\": 33036, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于云堇…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_teammate_yunjin_01\", \"description\": \"告诉你个小秘密，别到处乱讲哦。那个人可喜欢摇滚了，不管多忙，一周都来听我三场，只多不少。按理说，「和裕茶馆」的戏班头牌，该喜欢什么琴棋书画，花鸟虫鱼才对吧？肯定是平时被憋坏了，哈哈哈。\", \"voicelineId\": 33037, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于嘉明…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_teammate_gaming_01\", \"description\": \"他第一次说我是「摇滚发烧友」的时候，我还仔细摸了摸额头，回答他说「没有啊」，结果他来了句「你绝对是」，我们争论了小半天，最后才发现是误会，他跟我说「发烧友」就是「爱好者」的意思。哈哈哈，他可真好玩，我要把这个词写进歌里！\", \"voicelineId\": 33077, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解辛焱·其一\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_friendship_01\", \"description\": \"想要了解我？哈，一般人看到我就躲得远远的了，你还真是奇怪。那好吧，那就…从了解我的摇滚开始？\", \"voicelineId\": 33038, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解辛焱·其二\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_friendship_02\", \"description\": \"小时候，大人都让我要像个女孩子，让我学这个，学那个，但我天赋不行，总是挨骂。摇滚就不一样，没人教我，我也能做得很好，但却被大人说「没个女孩儿样」，唉，这就叫成见。\", \"voicelineId\": 33039, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解辛焱·其三\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_friendship_03\", \"description\": \"你有注意到我今天有什么区别吗？其实为了见你，我出门之前做了面部的按摩，放松了眼睛和嘴，还对着镜子练习了半小时的微笑。怎么样？是不是看上去没那么凶了？比原来更凶了？唉…\", \"voicelineId\": 33040, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解辛焱·其四\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_friendship_04\", \"description\": \"陪我练琴辛苦了！欸？差不多到中午了，来吃午饭吧，你的份我也准备了！喏，里面有西红柿，香肠，煎蛋…什么？我不像是做这种事的人？别、别小看我啊！做个吃的，摆个可爱的造型，也、也没什么不行的吧。\", \"voicelineId\": 33041, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解辛焱·其五\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_friendship_05\", \"description\": \"我很信奉摇滚的反抗精神，但我觉得这不代表我就一定要去张扬个性，我也可以有很正常的生活，可以做缝纫，可以养花养鱼，可以做造型可爱的菜肴，可以喜欢任何事，还有…任何人，对吧。\", \"voicelineId\": 33042, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"辛焱的爱好…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_pref_hobby\", \"description\": \"爱好那当然是摇滚！你有没有全情投入过某件事呢？当你与你最爱的东西合二为一，时间空间什么的都不再重要，只需要尽情享受，尽情宣泄——对对！这样沉醉进去的感觉，上百次上千次都不够！\", \"voicelineId\": 33043, \"voicelineType\": \"6001\"}, {\"title\": \"辛焱的烦恼…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_dialog_annoyed\", \"description\": \"我每次不小心和路边的小孩子对上眼，都会把他们吓哭。唉，到底有没有办法，能让我看起来不那么凶啊？能想到的办法我全试过了，都没什么用…\", \"voicelineId\": 33044, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_pref_foodLike\", \"description\": \"璃港船局的午饭真的超好吃！油水很多，肉也管够，虽然菜就那么几样，但我怎么吃都吃不腻！要我说，光是为了尝尝他们的午饭，就值得去船局干一天活！\", \"voicelineId\": 33045, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_pref_foodDislike\", \"description\": \"我几乎不挑食，但我讨厌清汤寡水的菜。咸就是咸，辣就是辣，有滋有味吃着才过瘾！哪怕食材只够做一道「珍珠翡翠白玉汤」，我也会事先备好干碟蘸水。\", \"voicelineId\": 33046, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_spice_pref_01\", \"description\": \"身体情不自禁想要跟着律动起来。太酷了！\", \"voicelineId\": 33074, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_spice_normal_01\", \"description\": \"味道不错，稍微欠点「火花」…需要我帮你摆个盘吗？\", \"voicelineId\": 33075, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_spice_dislike_01\", \"description\": \"你不介意我调点佐料，配着吃吧？\", \"voicelineId\": 33076, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_pref_birthday\", \"description\": \"生日快乐！你看，这是我特地做的刺绣，我参考枫丹的洋娃娃的样子，把我们两个纹在了上面，特别可爱对吧？欸…为什么这样看着我呀，我、我会刺绣是很奇怪的事吗？\", \"voicelineId\": 33047, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_starUp_01\", \"description\": \"嗯！就是这样的节奏！\", \"voicelineId\": 33048, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_starUp_02\", \"description\": \"状态火热，期待我的下一次演出吧！\", \"voicelineId\": 33049, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_starUp_03\", \"description\": \"掌握了这么强的力量，说不定也能创作出前所未有的摇滚！谢谢你，我的新作不会让你失望的！\", \"voicelineId\": 33050, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_xinyan/vo_xinyan_starUp_04\", \"description\": \"酷！我感受到你饱满的「激情」了！那么，就让我写一首专属于你的摇滚，只为你而奏响吧！\", \"voicelineId\": 33051, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_battle_skill1_01\", \"description\": \"能跟上节拍吗？\", \"voicelineId\": 33052, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_battle_skill1_02\", \"description\": \"热情还不够！\", \"voicelineId\": 33053, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_battle_skill1_03\", \"description\": \"来点火花吧！\", \"voicelineId\": 33054, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_battle_skill3_01\", \"description\": \"摇滚时间到！\", \"voicelineId\": 33055, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_battle_skill3_02\", \"description\": \"为反抗高歌！\", \"voicelineId\": 33056, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_battle_skill3_03\", \"description\": \"听我的最强音！\", \"voicelineId\": 33057, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_chest_open_01\", \"description\": \"为了庆祝，演奏一曲吧！\", \"voicelineId\": 33058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_chest_open_02\", \"description\": \"很「摇滚」嘛！\", \"voicelineId\": 33059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_chest_open_03\", \"description\": \"气氛嗨起来了！\", \"voicelineId\": 33060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_life_less30_01\", \"description\": \"都还只是前奏…\", \"voicelineId\": 33061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_life_less30_02\", \"description\": \"乐感不太好啊。\", \"voicelineId\": 33062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_life_less30_03\", \"description\": \"这种程度，早习惯了。\", \"voicelineId\": 33063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_life_less30_teammate_01\", \"description\": \"我的摇滚会支援你的。\", \"voicelineId\": 33064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_life_less30_teammate_02\", \"description\": \"这可不摇滚！\", \"voicelineId\": 33065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_life_die_01\", \"description\": \"节拍…乱了。\", \"voicelineId\": 33066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_life_die_02\", \"description\": \"还不够…激昂…\", \"voicelineId\": 33067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_life_die_03\", \"description\": \"不该…跑调的。\", \"voicelineId\": 33068, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_battle_hit_L_02\", \"description\": \"这可不摇滚。\", \"voicelineId\": 33069, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_xinyan/vo_xinyan_battle_hit_H_02\", \"description\": \"啊，我的琴！\", \"voicelineId\": 33070, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_xinyan_teamJoin_01\", \"description\": \"轮到我登场了！\", \"voicelineId\": 33071, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_xinyan_teamJoin_02\", \"description\": \"非常摇滚的选择！\", \"voicelineId\": 33072, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_xinyan_teamJoin_03\", \"description\": \"一起演奏吧！\", \"voicelineId\": 33073, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000045, 'Rosaria', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_draw_appear\", \"description\": \"这位信徒，如果遇到难以解决的麻烦，可以来找我，如果只想祈祷，还请找其他修女。\\n…嗯？你不是信徒吗？\", \"voicelineId\": 37009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·无聊\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_explore_idle_01\", \"description\": \"还不走吗？\", \"voicelineId\": 37010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·加班\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_explore_idle_02\", \"description\": \"什么都可以商量，除了加班。\", \"voicelineId\": 37011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·蒙德生活\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_explore_idle_03\", \"description\": \"好好完成工作，好好度过每一天。蒙德的生活不就是如此吗？\", \"voicelineId\": 37012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_weather_heavyRain_01\", \"description\": \"唉，影响效率。\", \"voicelineId\": 37013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_weather_thunder_01\", \"description\": \"嘁，麻烦。\", \"voicelineId\": 37014, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_weather_snowy_01\", \"description\": \"雪天赶路，最好小心一些。\", \"voicelineId\": 37015, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_weather_gale_01\", \"description\": \"是风神巴斯巴托的庇佑吗？等等，好像是巴托巴斯…\", \"voicelineId\": 37016, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_greetingMorning\", \"description\": \"早安，哈…晨祷已经开始了吗？也太早了。\", \"voicelineId\": 37017, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_greetingNoon\", \"description\": \"午后的阳光对睡眠有好处。你也试试吧。\", \"voicelineId\": 37018, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_greetingNight\", \"description\": \"晚上好。晚间祷告的话，我不参加。嗯？不为什么。\", \"voicelineId\": 37019, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_greetingNight2\", \"description\": \"去休息吧，不用操心，剩下的事我会处理。\", \"voicelineId\": 37020, \"voicelineType\": \"1004\"}, {\"title\": \"关于罗莎莉亚自己·修女\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_idle\", \"description\": \"我？只是个无趣的人而已。如你所见，不爱教会也不爱工作。\", \"voicelineId\": 37021, \"voicelineType\": \"2001\"}, {\"title\": \"关于罗莎莉亚自己·麻烦\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_idle2\", \"description\": \"那些值班修女一个比一个麻烦，不是抓人去祷告，就是叫人去唱诗班。你可别告诉她们我在这里。\", \"voicelineId\": 37022, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·信仰\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_close\", \"description\": \"神或许能庇护所有人，可他不会这样做。否则，人的苦难就成了笑话。\", \"voicelineId\": 37023, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·祷告\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_close1\", \"description\": \"祈祷吧。不是为了神或其他任何人，而是为了自己。\", \"voicelineId\": 37024, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·战斗\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_close2\", \"description\": \"不要勉强，有困难可以叫我。\", \"voicelineId\": 37025, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_pendant\", \"description\": \"「神之眼」可以是实力的证明，也可以是幸存的勋章…谁知道呢？真正的好东西总是具有两面性。我不会定义「神之眼」。我和它只是互相见证的关系罢了。\", \"voicelineId\": 37026, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_share_01\", \"description\": \"要说什么是值得高兴的好事…呵，只是假设而已。如果有一天你遇到无法解决的难题，也别认为那就是人生的终点。说不定，会有人替你解决困境呢。\", \"voicelineId\": 37027, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_pref_gift\", \"description\": \"花草不属于我感兴趣的范畴。不过，蒲公英是个例外，它能酿出相当美味的蒲公英酒。休息时间来一杯，比睡懒觉还舒服。\", \"voicelineId\": 37028, \"voicelineType\": \"3003\"}, {\"title\": \"关于迪卢克…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_teammate_diluc_01\", \"description\": \"一看就知道了吧？那位富豪老爷可不是个简单的人物。低调、自信…还有一点危险的气息。\", \"voicelineId\": 37029, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_teammate_kaeya_01\", \"description\": \"人往往要到醉酒以后才会露出真面目。油嘴滑舌算是凯亚的保护色吧，呵，一目了然的伪装。你该看看他喝醉的样子。\", \"voicelineId\": 37030, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温迪…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_teammate_venti_01\", \"description\": \"这个吟游诗人身上有种非常特殊的气息…我还不能确定真相，但他与别的市民似乎很不一样。\", \"voicelineId\": 37031, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芭芭拉…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_teammate_barbara_01\", \"description\": \"芭芭拉总是缠着我，叫我参加礼拜和唱诗班。难道维多利亚给她下了监督我工作的命令？\", \"voicelineId\": 37032, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_teammate_qin_01\", \"description\": \"不仅完成本职工作，还会替他人收尾。值得钦佩的女人。\", \"voicelineId\": 37033, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_teammate_albedo_01\", \"description\": \"他就像一副挂在古旧房屋里的油画…厚重、神秘，无法被一眼看透。我不讨厌有故事的人。\", \"voicelineId\": 37034, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_teammate_lisa_01\", \"description\": \"我不喜欢上班偷懒的人，不过也很能理解她准点下班的心情。\", \"voicelineId\": 37035, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_teammate_klee_01\", \"description\": \"唉，除了麻烦就是麻烦，虽然是可爱的麻烦。\", \"voicelineId\": 37036, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_teammate_varka_01\", \"description\": \"虽说是出于好意，但法尔伽啰嗦起来像个老头一样，相当在意身边的人呢。唉，那家伙。\", \"voicelineId\": 37037, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于父亲…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_teammate_father_01\", \"description\": \"父亲？好遥远的词汇啊。对我而言可以说没有，也可以说有不止一个。怎么？很惊讶吗？\", \"voicelineId\": 37038, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解罗莎莉亚·其一\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_friendship_01\", \"description\": \"跳过寒暄吧。我来这里是为了完成工作，你解决不了的问题可以移交给我。\", \"voicelineId\": 37039, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解罗莎莉亚·其二\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_friendship_02\", \"description\": \"不信神的修女并不稀奇，就像世上也有不喜欢吃猪肉的猎人、讨厌鱼肉的渔民。做某一件事不代表爱它，不爱一件事也不意味着必须远离。工作就是这样的东西。\", \"voicelineId\": 37040, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解罗莎莉亚·其三\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_friendship_03\", \"description\": \"来一杯吗？这是今年的蒲公英酒，味道很不错。\", \"voicelineId\": 37041, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解罗莎莉亚·其四\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_friendship_04\", \"description\": \"蒙德是一头既古老又年轻的白色野兽，古老到需要人去保护，也年轻到无法独立生存。只有这样的地方才会需要我这样的人。我像其他修女照顾市民那样照顾着蒙德，让它在自由的道路上平稳前进。你问我为什么它是白色的？…因为像我这样的人，是黑色的。\", \"voicelineId\": 37042, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解罗莎莉亚·其五\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_friendship_05\", \"description\": \"我偶尔能感觉到过去每一年的自己都存在着、围绕着我…对我有所寄托。你一定也有相同的感觉，所以，哪怕如今你已走上截然不同的道路，也不要否认从前的自己。从前的每一个你，都是你脚下的基石。不要害怕过去，不要畏惧与它抗衡。\", \"voicelineId\": 37043, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"罗莎莉亚的爱好…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_pref_hobby\", \"description\": \"小酌怡情，有些烦心事只能靠酒精解决。话虽如此，我是不会醉的。\", \"voicelineId\": 37044, \"voicelineType\": \"6001\"}, {\"title\": \"罗莎莉亚的烦恼…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_dialog_annoyed\", \"description\": \"唉…真不想参加下个月的合唱活动，可维多利亚亲自点名了…\", \"voicelineId\": 37045, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_pref_foodLike\", \"description\": \"试过红酒炖兽肉吗？酒精和大块的动物肉出现在一个盘子里，相当有品味。\", \"voicelineId\": 37046, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_pref_foodDislike\", \"description\": \"这个…这个土豆饼的蘸料居然是果酱？完全不合理！\", \"voicelineId\": 37047, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_spice_pref_01\", \"description\": \"看来这方面，我们品味相投。\", \"voicelineId\": 37075, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_spice_normal_01\", \"description\": \"至少能填饱肚子。\", \"voicelineId\": 37076, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_spice_dislike_01\", \"description\": \"你对这种食物很感兴趣吗？\", \"voicelineId\": 37077, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_pref_birthday\", \"description\": \"今天是你生日，有什么想处理的人或事吗？我可以帮个小忙，别告诉其他人就行。\", \"voicelineId\": 37048, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_starUp_01\", \"description\": \"嗯，感觉不错。\", \"voicelineId\": 37049, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_starUp_02\", \"description\": \"需要帮忙吗？我现在有空。\", \"voicelineId\": 37050, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_starUp_03\", \"description\": \"也好。能力越强，效率越高。\", \"voicelineId\": 37051, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_rosaria/vo_rosaria_starUp_04\", \"description\": \"哪怕是擅长战斗与杀戮的我，也从未拥有过如此强大的力量，谢谢你的祝福。\", \"voicelineId\": 37052, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_battle_skill1_01\", \"description\": \"嘿呀！\", \"voicelineId\": 37053, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_battle_skill1_02\", \"description\": \"审判！\", \"voicelineId\": 37054, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_battle_skill1_03\", \"description\": \"别想跑！\", \"voicelineId\": 37055, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_battle_skill3_01\", \"description\": \"制裁！\", \"voicelineId\": 37056, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_battle_skill3_02\", \"description\": \"战栗吧！\", \"voicelineId\": 37057, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_battle_skill3_03\", \"description\": \"晚安了…\", \"voicelineId\": 37058, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_chest_open_01\", \"description\": \"…倒也有不错的玩意。\", \"voicelineId\": 37059, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_chest_open_02\", \"description\": \"还行，不算很麻烦。\", \"voicelineId\": 37060, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_chest_open_03\", \"description\": \"心情不错。\", \"voicelineId\": 37061, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_life_less30_01\", \"description\": \"没想到…哼。\", \"voicelineId\": 37062, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_life_less30_02\", \"description\": \"得加个班了。\", \"voicelineId\": 37063, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_life_less30_03\", \"description\": \"有两下子！\", \"voicelineId\": 37064, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_life_less30_teammate_01\", \"description\": \"退后！\", \"voicelineId\": 37065, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_life_less30_teammate_02\", \"description\": \"不要恋战！\", \"voicelineId\": 37066, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_life_die_01\", \"description\": \"这样也好…\", \"voicelineId\": 37067, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_life_die_02\", \"description\": \"或许是…命中注定…\", \"voicelineId\": 37068, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_life_die_03\", \"description\": \"唔…到此为止了吗…\", \"voicelineId\": 37069, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_battle_hit_L_02\", \"description\": \"不过如此。\", \"voicelineId\": 37070, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_rosaria/vo_rosaria_battle_hit_H_02\", \"description\": \"啧，真麻烦！\", \"voicelineId\": 37071, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_rosaria_teamJoin_01\", \"description\": \"又有新工作了？\", \"voicelineId\": 37072, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_rosaria_teamJoin_02\", \"description\": \"但愿配合顺利。\", \"voicelineId\": 37073, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_rosaria_teamJoin_03\", \"description\": \"呼…速战速决。\", \"voicelineId\": 37074, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000046, 'Hu Tao', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_draw_appear\", \"description\": \"唷，找本堂主有何贵干呀？嗯？你不知道吗，往生堂第七十七代堂主就是胡桃我啦！嘶，不过瞧你的模样，容光焕发，身体健康，嗯…想必是为了工作以外的事来找我，对吧？\", \"voicelineId\": 36009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·往生堂\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_explore_idle_01\", \"description\": \"不如去我那儿喝杯茶？嘿~\", \"voicelineId\": 36010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·客户\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_explore_idle_02\", \"description\": \"一个客户，两个客户，三个客户…\", \"voicelineId\": 36011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·偷懒\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_explore_idle_03\", \"description\": \"咳咳…太阳出来我晒太阳，月亮出来我晒月亮咯~\", \"voicelineId\": 36012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_weather_heavyRain_01\", \"description\": \"哎呀…麻烦喽。\", \"voicelineId\": 36013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_weather_thunder_01\", \"description\": \"打雷啦，起身啦。\", \"voicelineId\": 36014, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_weather_snowy_01\", \"description\": \"哇，是雪！\", \"voicelineId\": 36015, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_weather_breeze_01\", \"description\": \"嗯，真舒服。\", \"voicelineId\": 36016, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_weather_gale_01\", \"description\": \"欸？…唉，帽子都要吹飞了。\", \"voicelineId\": 36017, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_greetingMorning\", \"description\": \"嗯~早起身体好，晚睡人会飘。\", \"voicelineId\": 36018, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_greetingNoon\", \"description\": \"哟！中午好呀，吃了吗？\", \"voicelineId\": 36019, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_greetingNight\", \"description\": \"嘻嘻，月亮出来喽~咱也出门吧。\", \"voicelineId\": 36020, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_greetingNight2\", \"description\": \"哦，困了吗？那你好好休息，我一个人四处转转。\", \"voicelineId\": 36021, \"voicelineType\": \"1004\"}, {\"title\": \"关于胡桃自己·名字\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_idle\", \"description\": \"胡桃的胡是胡吃海喝的胡，胡桃的桃却不是淘气的淘！嘿嘿…不、不好笑吗？\", \"voicelineId\": 36022, \"voicelineType\": \"2001\"}, {\"title\": \"关于胡桃自己·拿手好戏\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_idle2\", \"description\": \"变个戏法给你看，瞧好了哦…火！然后…嚯！火蝴蝶！呼，飞啦——哈哈。\", \"voicelineId\": 36023, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·好奇心\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_close\", \"description\": \"你到处旅行，一定见多识广。有空也给我讲讲你自己的故事吧。\", \"voicelineId\": 36024, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·夜晚\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_close1\", \"description\": \"白天你尽管到处跑，晚上可得小心点。我不在的时候，务必谨慎行动。\", \"voicelineId\": 36025, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·帮手\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_close2\", \"description\": \"需要帮手吗？需要帮手吗？我来啦！若你需要帮助，胡桃我定当全力以赴，绝不推辞。\", \"voicelineId\": 36026, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·战斗\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_close3\", \"description\": \"战斗是件麻烦事，对我来说，它不是目的而是手段。用手段来达到目的，用战斗来维护不愿让步的东西。就这方面而言，我和你是一样的。\", \"voicelineId\": 36027, \"voicelineType\": \"2006\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_pendant\", \"description\": \"「神之眼」…「神之眼」？唔，这东西，随缘就好。\", \"voicelineId\": 36028, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_share_01\", \"description\": \"受人之托，忠人之事。我们往生堂性质特殊，肩负着双倍责任，所以，一定要让两个世界的人都满意才行。\", \"voicelineId\": 36029, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_pref_gift\", \"description\": \"有些花草只长在阴气重月光多的地方，你见过吗？没有？那下次带你见识见识。\", \"voicelineId\": 36030, \"voicelineType\": \"3003\"}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_zhongli_01\", \"description\": \"钟离长得那么年轻，性格倒像是个老古董，什么都懂，却什么都不关心，他该不会…？嘻嘻…\\n唉，算了，随他去吧。\", \"voicelineId\": 36031, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于七七…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_qiqi_01\", \"description\": \"看到七七了吗？快告诉我她在哪，我要把她藏起来，嘿！\", \"voicelineId\": 36032, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于白术…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_baizhu_01\", \"description\": \"白术？哼，麻烦的家伙。\", \"voicelineId\": 36033, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_ningguang_01\", \"description\": \"天权凝光，富甲一方；明眸善睐，桃羞杏让；目达耳通，百了千当！\", \"voicelineId\": 36034, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_beidou_01\", \"description\": \"北斗姐可是璃月名人，她不认识我没关系，我认识她就行。啊~真想和她交个朋友啊。\", \"voicelineId\": 36035, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_xingqiu_01\", \"description\": \"听说行秋少爷在写书？话本还是怪谈呢？好想把平日遇见的杂事说给他听，写成书一定很好看吧。\", \"voicelineId\": 36036, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于重云…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_chongyun_01\", \"description\": \"纯阳正气，阴阳合一？啧啧，嘶…没想到世上真有这种体质的人。\", \"voicelineId\": 36037, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_xiao_01\", \"description\": \"仙家的事，我怎么知道？哎呀呀，天机不可泄露。你就别问我啦。\", \"voicelineId\": 36038, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_keqing_01\", \"description\": \"「玉衡」刻晴啊，嘶…是个很难打交道的人呢。嘿嘿，瞧那一本正经的样子，真想逗逗她。哎呦，她应该不会用剑敲我头吧？不会的吧？\", \"voicelineId\": 36039, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_xiangling_01\", \"description\": \"香菱可好玩了，一碰就跳，特别容易被唬住。做我们这行，最喜欢这种人喽。不过也得注意分寸，毕竟，锅巴会替香菱出头呢。\", \"voicelineId\": 36040, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于云堇…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_yunjin_01\", \"description\": \"云堇她在正式场合很优雅，私底下却非常容易亲近哦！上次我跟她打了个赌，输的人要用自己习惯的唱法唱对方填的词。哎呀呀，戏腔版的丘丘谣，你真该听一次！\", \"voicelineId\": 36041, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于申鹤…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_shenhe_01\", \"description\": \"她可真是个有意思的人呐，跟别人都不一样。你说，要是我从现在开始天天吃仙草、喝山露，会不会也变成她那么不染红尘的样子？嘿嘿…\", \"voicelineId\": 36042, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于蓝砚…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_teammate_lanyan_01\", \"description\": \"蓝姑娘啊…她实力不俗，可不仅仅是「皮毛」这么简单。奇门秘术可真了不得，病气死气都被搬走啦。哎呀，可谓是——世风日上，身强力壮，往生堂的生意越来越难做喽。\", \"voicelineId\": 36085, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解胡桃·其一\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_friendship_01\", \"description\": \"大丘丘病了，二丘丘瞧；三丘丘采药，四丘丘熬；五丘丘死了，六丘丘抬~\\n欸…呼。\", \"voicelineId\": 36043, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解胡桃·其二\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_friendship_02\", \"description\": \"小巷派暗黑打油诗人，正是本人！\", \"voicelineId\": 36044, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解胡桃·其三\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_friendship_03\", \"description\": \"若要我说，往生堂的工作既不困难也不可怕，只是麻烦而已。可惜旁人理解不了，见到咱们夜里出工，总是有些惧怕。唉，是他们不懂啊。\", \"voicelineId\": 36045, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解胡桃·其四\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_friendship_04\", \"description\": \"我是「往生堂」第七十七代堂主，我爷爷是第七十五代。我经手的第一份工作，就是替爷爷办葬礼。是不是很意外啊？哎呀，不知不觉就在这行做了好些年，时间过得可真快。\", \"voicelineId\": 36046, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解胡桃·其五\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_friendship_05\", \"description\": \"阴阳有序，命运无常。死亡难以预测，却也有它的规矩。记住了，无论何时何地，无论有何原因，人都不该轻易挑衅「死」之一事。唯有认识它、尊重它，才能明白活着的价值。\", \"voicelineId\": 36047, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"胡桃的爱好…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_pref_hobby\", \"description\": \"天清海阔，皓月凌空，此情此景，正适合作诗一首。\", \"voicelineId\": 36048, \"voicelineType\": \"6001\"}, {\"title\": \"胡桃的烦恼…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_dialog_annoyed\", \"description\": \"唉…真想找些新乐子，无所事事比死亡可怕多了。\", \"voicelineId\": 36049, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_pref_foodLike\", \"description\": \"♪啦啦啦啦~吃水煮鱼配虾饺啦~\", \"voicelineId\": 36050, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_pref_foodDislike\", \"description\": \"清心炒史莱姆凝液…呕…这是香菱对我的复仇吗？\", \"voicelineId\": 36051, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_spice_pref_01\", \"description\": \"甚好甚好。本堂主现在就来为这道菜肴题诗一首——\", \"voicelineId\": 36082, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_spice_normal_01\", \"description\": \"真不用我来帮忙吗？做一道送一道哦！\", \"voicelineId\": 36083, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_spice_dislike_01\", \"description\": \"噫…这是什么东西呀？\", \"voicelineId\": 36084, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_pref_birthday\", \"description\": \"今夜天星璀璨，月相壮丽，想必是个好日子。嘶，待我一算…嗯~我知道我知道，是你的生辰！哎呀，真是个好日子。\", \"voicelineId\": 36052, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_starUp_01\", \"description\": \"哦呀？哦呀呀？\", \"voicelineId\": 36053, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_starUp_02\", \"description\": \"嗯~真不错，谢啦。\", \"voicelineId\": 36054, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_starUp_03\", \"description\": \"没想到没想到，胡桃我现在力如泉涌，心似雄鹰，非常有自信哦。\", \"voicelineId\": 36055, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_hutao/vo_hutao_starUp_04\", \"description\": \"力量若达到极限，接着考验的便是人心。多亏了你，我才能来到这片未曾踏足的领域。在这里，心和灵魂就像一片云彩…生老病死，天地万象，尽在吾辈。\", \"voicelineId\": 36056, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_battle_skill1_01\", \"description\": \"喝！\", \"voicelineId\": 36057, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_battle_skill1_02\", \"description\": \"起！\", \"voicelineId\": 36058, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_battle_skill1_03\", \"description\": \"散！\", \"voicelineId\": 36059, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_battle_skill3_01\", \"description\": \"吃饱喝饱，一路走好！\", \"voicelineId\": 36060, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_battle_skill3_02\", \"description\": \"再会啦！\", \"voicelineId\": 36061, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_battle_skill3_03\", \"description\": \"蝶火燎原！\", \"voicelineId\": 36062, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_explore_sprint_start_01\", \"description\": \"嚯——！\", \"voicelineId\": 36063, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺开始·其二\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_explore_sprint_start_02\", \"description\": \"走~\", \"voicelineId\": 36064, \"voicelineType\": \"700002\"}, {\"title\": \"冲刺开始·其三\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_explore_sprint_start_03\", \"description\": \"咻~\", \"voicelineId\": 36065, \"voicelineType\": \"700003\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_explore_fly_start_01\", \"description\": \"顺风顺水~\", \"voicelineId\": 36066, \"voicelineType\": \"710001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_chest_open_01\", \"description\": \"撞大运咯！\", \"voicelineId\": 36067, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_chest_open_02\", \"description\": \"让我看看，都有什么好东西。\", \"voicelineId\": 36068, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_chest_open_03\", \"description\": \"快埋进土里，等它长出好多宝箱！\", \"voicelineId\": 36069, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_life_less30_01\", \"description\": \"哎哟哎哟！\", \"voicelineId\": 36070, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_life_less30_02\", \"description\": \"噫——！\", \"voicelineId\": 36071, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_life_less30_03\", \"description\": \"糟糕！\", \"voicelineId\": 36072, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_life_less30_teammate_01\", \"description\": \"悠着点！\", \"voicelineId\": 36073, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_life_less30_teammate_02\", \"description\": \"放着我来！\", \"voicelineId\": 36074, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_life_die_01\", \"description\": \"到我了吗…\", \"voicelineId\": 36075, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_life_die_02\", \"description\": \"我记…仇…\", \"voicelineId\": 36076, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_life_die_03\", \"description\": \"呃啊——\", \"voicelineId\": 36077, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_hutao/vo_hutao_battle_hit_H_02\", \"description\": \"干嘛呀！\", \"voicelineId\": 36078, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_hutao_teamJoin_01\", \"description\": \"哦？该我出马了？\", \"voicelineId\": 36079, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_hutao_teamJoin_02\", \"description\": \"你很有眼光嘛！\", \"voicelineId\": 36080, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_hutao_teamJoin_03\", \"description\": \"一波送走，全送走。\", \"voicelineId\": 36081, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000047, 'Kaedehara Kazuha', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_draw_appear\", \"description\": \"「飘摇风雨中，带刀归来赤脚行」…我的名字是枫原万叶，游历四方的浪人。既然你我都在旅行的路上，这段路不妨结伴同行。\", \"voicelineId\": 40009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·自然\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_character_idle_01\", \"description\": \"见到了这么美丽的景色，自然会产生云游四海的想法吧？\", \"voicelineId\": 40010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·吹奏\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_character_idle_02\", \"description\": \"既然手边有树叶，我可以为你吹奏一曲。\", \"voicelineId\": 40011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·剑技\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_character_idle_03\", \"description\": \"飘摇风雨中，睹物思故乡，这把刀…是我与故乡唯一的联系了。\", \"voicelineId\": 40012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_weather_heavyRain_01\", \"description\": \"在大雨中漫步，让人神志清醒。不过等雨停之后，还是尽快把衣服烤干比较好。\", \"voicelineId\": 40013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_weather_thunder_01\", \"description\": \"比起在海上航行时遇到的雷暴，这倒也算不上什么。\", \"voicelineId\": 40014, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_weather_snowy_01\", \"description\": \"我喜欢下雪，雪后的世界很安静，无人来扰我清梦。\", \"voicelineId\": 40015, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_weather_sunny_01\", \"description\": \"晴空万里，真让人心情愉快。\", \"voicelineId\": 40016, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_greetingMorning\", \"description\": \"清晨的鸟鸣，是大自然的馈赠。启程吧，属于我们的旅途也要开始了。\", \"voicelineId\": 40017, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_greetingNoon\", \"description\": \"正午的阳光，让人想要小睡片刻。找个地方休息一下如何？\", \"voicelineId\": 40018, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_greetingNight\", \"description\": \"抬头见月，侧耳听风，壶中有酒，我心太平…\\n晚上好。\", \"voicelineId\": 40019, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_greetingNight2\", \"description\": \"风停了…\\n安静的世界，适合好好休息。明天见。\", \"voicelineId\": 40020, \"voicelineType\": \"1004\"}, {\"title\": \"关于枫原万叶自己·航行\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_idle\", \"description\": \"其实，大海并非每晚都充满风浪。天气清朗的时候，月光倒映在摇晃的海面上，鱼群在船舶的周围随行。我坐在船头眺望远方，会觉得这段旅程非常值得…唯一的遗憾是水手们的歌声太吵了，他们不用睡觉的吗？\", \"voicelineId\": 40021, \"voicelineType\": \"2001\"}, {\"title\": \"关于枫原万叶自己·贵族武士\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_idle2\", \"description\": \"枫原家曾经也是有名的武士门第，可惜传承到我这里时，除了贵族的名号外已经别无长物。不过对我来说倒也足够了，武士不需要富足的生活，我们需要的是诗歌、美酒与手中的刀。\", \"voicelineId\": 40022, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·出海\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_close\", \"description\": \"找个好天气，出海看看如何？\", \"voicelineId\": 40023, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·畅谈\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_close1\", \"description\": \"我喜欢性格爽朗的人，这样相处时可以畅所欲言。有什么想说的不必藏在心里，我能够听到自然万物的声音，其中也包括你的声音。\", \"voicelineId\": 40024, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_pendant\", \"description\": \"在我看来，神之眼是力量的「证明」，而不是力量的「来源」。神之眼象征的是凡人继续向前的愿望，而我们武士的底气，一直都是手里的刀。\", \"voicelineId\": 40025, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·竹刀\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_share_01\", \"description\": \"想学剑道的话…我想想，拿着这个吧，这是我刚刚做好的竹刀。用这个切磋的话，我们就都不会受伤了。\", \"voicelineId\": 40026, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·枫叶\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_share_02\", \"description\": \"「深山踏红叶，耳畔闻鹿鸣」…我很喜欢枫叶，可惜枫叶红时总多离别。\", \"voicelineId\": 40027, \"voicelineType\": \"3003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_pref_gift\", \"description\": \"海鸥别叫啦，从今天起，我也是漂泊者呀。\", \"voicelineId\": 40028, \"voicelineType\": \"3004\"}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_teammate_beidou_01\", \"description\": \"北斗大姐头是我的恩人。大姐头她收留了从稻妻逃出来的我，并在我最困难的那段时期里，给了我重返稻妻的勇气。她是我和所有船员可以托付后背的战友。\", \"voicelineId\": 40029, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于五郎…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_teammate_goro_01\", \"description\": \"我在被通缉的那段时间里，反抗军给了我许多帮助。那时候我与五郎只有短暂的接触，但我对他的印象很深刻。他是那种有话就说的直性子，与部下同甘共苦，为朋友两肋插刀，与我很合得来。\", \"voicelineId\": 40030, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗·态度…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_teammate_kujoSara_01\", \"description\": \"能在御前决斗中战胜我的朋友，我确实认可她的实力。但她却用这样的力量为虎作伥，带领九条军不断回收「神之眼」，我无法原谅。\", \"voicelineId\": 40031, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗·改观…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_teammate_kujoSara_02\", \"description\": \"原来如此。看来她也有自己坚持的信念。只是不知道风波平息后，「九条」家还能否延续曾经的昌盛。\", \"voicelineId\": 40032, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_teammate_raidenShogun_01\", \"description\": \"离开稻妻后，我许多次扪心自问，我对雷电将军的不满是否源于那一次御前决斗，是否源于她对友人落下的那一刀？\\n我想了很久，觉得不是的。我的友人是堂堂正正地死在了决斗场上，雷电将军的那一刀也并无不妥。我对她的不满，来源于「眼狩令」。没有任何人有资格剥夺他人的愿望，即便是「神」也不行。\", \"voicelineId\": 40033, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200212], \"unlockText\": \"完成「振袖秋风问红叶」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_teammate_ayaka_01\", \"description\": \"生活在稻妻的人，应该都听过「白鹭公主」这个名字吧。神里家的大小姐，近乎完美的一个人，不过我跟她没什么交集，不知道她对如今的稻妻抱有怎样的看法。\", \"voicelineId\": 40034, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_teammate_yoimiya_01\", \"description\": \"上次她托大姐头把烟火运到璃月，还是我亲自去卸的货。好沉！除了她以外，应该没人能造出这么大的烟火了吧。\", \"voicelineId\": 40035, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珊瑚宫心海…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_teammate_kokomi_01\", \"description\": \"我在反抗军的时候，周围的同伴无不对珊瑚宫大人充满敬仰。她爱惜兵力，很少会做出不计死伤的打法，总是能够用最小的代价取得胜利。听说她还要统管海祇岛的政务和外交，真的忙得过来吗…\", \"voicelineId\": 40077, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鹿野院平藏…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_teammate_heizou_01\", \"description\": \"别看我这位侦探朋友平日里潇洒随性，一旦他办起案子来，那些原本围绕在他身旁活泼灵动的风，就聚成了凌厉锐气。确实让人钦佩。\", \"voicelineId\": 40078, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解枫原万叶·其一\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_friendship_01\", \"description\": \"想要了解我的事？如你所见，我只是个随处可见的流浪武士。\", \"voicelineId\": 40036, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解枫原万叶·其二\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_friendship_02\", \"description\": \"我的耳朵很敏锐，能够听到各种各样的声音。比如风吹过山岗的声音，云散开的声音，林间的小狐狸啃咬苹果的声音，螃蟹吐泡泡的声音…这是自然万物对我的眷顾，让我总能提前发现危险的到来。\", \"voicelineId\": 40037, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解枫原万叶·其三\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_friendship_03\", \"description\": \"小时候我很喜欢下雨，那种沙沙的声响容易给人一个安稳的梦。但长大了以后，对雨的感情就变得复杂了许多…虽然依旧喜欢听雨，但每次看到乌云的时候，却又忍不住感叹「今天能不能找到好心人让我借宿呢」。穿着湿漉漉的衣服听雨，往往会被喷嚏声打断了情调。\", \"voicelineId\": 40038, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解枫原万叶·其四\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_friendship_04\", \"description\": \"我不会在一个地方驻足太久。因为太久的停留会让我跟「自然」产生隔阂，也会让我手里的刀变钝。趁我还能远航，我希望自己能去各种各样的地方，见到不同的人们。\", \"voicelineId\": 40039, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解枫原万叶·其五\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_friendship_05\", \"description\": \"不必担心，就算有一天我们去往不同的地方，也一定会在世界的某处再次相遇。人与人的「缘」不是那么容易就断掉的东西。\", \"voicelineId\": 40040, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"枫原万叶的爱好…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_pref_hobby\", \"description\": \"躺在被正午的阳光晒暖的岩石上休息，醒来后继续漫无目的地前行。只要与刀相伴，我可以去任何地方。\", \"voicelineId\": 40041, \"voicelineType\": \"6001\"}, {\"title\": \"枫原万叶的烦恼…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_dialog_annoyed\", \"description\": \"每逢风暴降临的时候，「自然」的声音就会变得嘈杂，我的耳朵也会嗡嗡作响。如果是在晚上的话，往往会辗转许久都无法入眠，让人有些头痛。\", \"voicelineId\": 40042, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_pref_foodLike\", \"description\": \"在大海上航行时，最容易获取到的食材便是鱼肉。怎么样把鱼做得好吃，是每个在海上冒险的人都要思考的问题。有机会的话，也想让你尝尝看我的手艺。\", \"voicelineId\": 40043, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_pref_foodDislike\", \"description\": \"我呢，不是特别喜欢那些粗制的食物。在我看来，就算是一条普普通通的鱼也要烧得好吃才行，吃东西本应是让人身心愉快的事情，怎么能将就呢？\", \"voicelineId\": 40044, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_spice_pref_01\", \"description\": \"能将鱼肉烹调出如此滋味，你的手艺当真了得。\", \"voicelineId\": 40079, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_spice_normal_01\", \"description\": \"你做的饭菜不仅能够饱腹，对我而言也是慰藉。\", \"voicelineId\": 40080, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_spice_dislike_01\", \"description\": \"要休息一下吗？内心疲惫的话，做出来的菜也会失去风味。\", \"voicelineId\": 40081, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_pref_birthday\", \"description\": \"哈…得知今天的生日，我特地写了新的诗歌。只可惜诗才不佳，几个晚上只想到前两句，就先送给你吧。\\n「流光换日月，鹤归云起庆生时」…欸等等，先别说话，我有灵感了。最后一句…「异乡有故知」，如何？\\n生日快乐，今天一起去…吃点甜品吧。\", \"voicelineId\": 40045, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_starUp_01\", \"description\": \"这把刀，更加锋利了。\", \"voicelineId\": 40046, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_starUp_02\", \"description\": \"雪落在地上的声音，细不可闻…但现在的我，应该可以听到了。\", \"voicelineId\": 40047, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_starUp_03\", \"description\": \"海上的风浪很大，我也要变得更强。\", \"voicelineId\": 40048, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_kazuha/vo_kazuha_starUp_04\", \"description\": \"行走世间，自然会有各种烦恼相伴，但既得与你相遇，不管是武艺还是内心都有了新的成长。想必今后的人生也会更加自在吧。\", \"voicelineId\": 40049, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_skill1_01\", \"description\": \"起！\", \"voicelineId\": 40050, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_skill1_02\", \"description\": \"嘿！\", \"voicelineId\": 40051, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_skill1_03\", \"description\": \"踏风！\", \"voicelineId\": 40052, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_skill1_04\", \"description\": \"御风而行。\", \"voicelineId\": 40053, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_skill1_05\", \"description\": \"朔风解意。\", \"voicelineId\": 40054, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_skill1_06\", \"description\": \"往返自然！\", \"voicelineId\": 40055, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_skill3_01\", \"description\": \"云隐…雁鸣！\", \"voicelineId\": 40056, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_skill3_02\", \"description\": \"风共云行。\", \"voicelineId\": 40057, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_skill3_03\", \"description\": \"可叹，落叶飘零。\", \"voicelineId\": 40058, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_explore_sprint_start_01\", \"description\": \"该出发了。\", \"voicelineId\": 40059, \"voicelineType\": \"700001\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_explore_fly_start_01\", \"description\": \"顺着风的方向。\", \"voicelineId\": 40060, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_chest_open_01\", \"description\": \"令人快慰。\", \"voicelineId\": 40061, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_chest_open_02\", \"description\": \"天地的馈赠。\", \"voicelineId\": 40062, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_chest_open_03\", \"description\": \"偶遇珍宝，是云游四方的妙趣之一。\", \"voicelineId\": 40063, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_life_less30_01\", \"description\": \"呼、有一套嘛…\", \"voicelineId\": 40064, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_life_less30_02\", \"description\": \"静心凝神。\", \"voicelineId\": 40065, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_life_less30_03\", \"description\": \"保持专注！\", \"voicelineId\": 40066, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_life_less30_teammate_01\", \"description\": \"换我来保护你了！\", \"voicelineId\": 40067, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_life_less30_teammate_02\", \"description\": \"你可以把后背交给我。\", \"voicelineId\": 40068, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_life_die_01\", \"description\": \"深感遗憾…\", \"voicelineId\": 40069, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_life_die_02\", \"description\": \"下次…绝不会再…\", \"voicelineId\": 40070, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_life_die_03\", \"description\": \"结束了吗…\", \"voicelineId\": 40071, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_hit_H_01\", \"description\": \"不要…紧。\", \"voicelineId\": 40072, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_kazuha/vo_kazuha_battle_hit_H_02\", \"description\": \"好痛！\", \"voicelineId\": 40073, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_kazuha_teamJoin_01\", \"description\": \"要带上我吗？\", \"voicelineId\": 40074, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_kazuha_teamJoin_02\", \"description\": \"出发出发。\", \"voicelineId\": 40075, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_kazuha_teamJoin_03\", \"description\": \"就这么做吧。\", \"voicelineId\": 40076, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000048, 'Yanfei', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_draw_appear\", \"description\": \"我叫烟绯，是璃月港最顶尖的律法专家，没有之一！商业纠纷、民事调解、刑事诉讼，样样精通，一出手就搞得定！我的联系方式…要给你记在哪里好呢？唔…记在纸上容易丢，记在手上容易糊掉…哦！有了，就写在你旁边这个小家伙的衣服上吧。\", \"voicelineId\": 38009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·律法\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_character_idle_01\", \"description\": \"律法既是约束，也是工具，请你千万记住哦！记不住的话，我就多给你念叨两遍。\", \"voicelineId\": 38010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·工作\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_character_idle_02\", \"description\": \"法理与人情有时冲突，有时兼容。权衡二者，真是种学问呢。\", \"voicelineId\": 38011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·阅读\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_character_idle_03\", \"description\": \"唔唔，居然还有这种案件…天下之大，无奇不有啊。\", \"voicelineId\": 38012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_weather_heavyRain_01\", \"description\": \"又下雨了！岩王爷行行好赶快出晴吧，一大墙法典可不能受潮。\", \"voicelineId\": 38013, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_weather_snowy_01\", \"description\": \"这…这是什么倒霉天气，有、有点冷哦…阿嚏…\", \"voicelineId\": 38014, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_weather_sunny_01\", \"description\": \"趁着天好，背背律条。嗯？《璃月商典》第二十七章第六条第三款是什么来着…我怎么会忘记？不应当不应当…\", \"voicelineId\": 38015, \"voicelineType\": \"1203\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_greetingMorning\", \"description\": \"早上有个债务纠纷的案件要出外勤，中午前要给上周来咨询的客户答复…好！干活干活！\", \"voicelineId\": 38016, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_greetingNoon\", \"description\": \"哈…有点困呢…不如来场辩论，帮我提神醒脑！辩题的话，「北国银行的开设对璃月经济利大于弊还是弊大于利」。嗯，就这个，你先来挑立场吧。\", \"voicelineId\": 38017, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_greetingNight\", \"description\": \"夜市？唔…本想留在家里整理笔记，不过你想逛的话，我们就一起去吧。哦，我跟你说，有的店家因为要保证每天商品都是新鲜的，又不想白白折损今天卖剩下的货物，经常会在晚上搞促销。\\n讨价还价的事就交给我来吧，零头…就当作我的服务费啦。\", \"voicelineId\": 38018, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_greetingNight2\", \"description\": \"想要快速入睡？那我来给你讲解璃月律法的演变史吧，我的那些朋友就没有能撑过二十分钟的。唔，还想要更快的话，那就背法典吧，背法典！明天记得告诉我你听到了第几条。咳咳…我开始了哦？\", \"voicelineId\": 38019, \"voicelineType\": \"1004\"}, {\"title\": \"关于烟绯自己·气场\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_idle\", \"description\": \"读卷宗时我的气场很强？唔…原来你会这样想。但那也只是我的工作状态吧。就是说，在我的身上有一个隐形的按钮，噗地拨过来，是平常模式，咻地拨过去，是工作模式。你身上难道就没有这种开关吗？\", \"voicelineId\": 38020, \"voicelineType\": \"2001\"}, {\"title\": \"关于烟绯自己·弱项\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_idle2\", \"description\": \"我最怕遇到的就是民事纠纷啦，什么婚姻破裂、抚养权诉讼…这类纠纷很难用理性或者逻辑去拆解。虽然说对当事人的态度要温和有耐心，但有的当事人自己都已经没法交流了…唉。虽然我标榜自己「样样精通」，但如果可以由我做主的话，我还是希望大家都能够和和气气生活，少出现些这种案子啦。\", \"voicelineId\": 38021, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·定价\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_close\", \"description\": \"想请我做你的顾问？可以啊，解读律法每条六千摩拉，随行咨询每个时辰十八万摩拉，商业案件单件七十一万摩拉起，后续具体报价和抽成视情况而定。怎么样，很实惠吧？\", \"voicelineId\": 38022, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·关系\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_close1\", \"description\": \"你四处游历，要是怕遇到麻烦处理起来棘手，最好的办法就是跟知法懂法之人同行。而我烟绯擅长的，也不止璃月本国的律法。呃，虽然，枫丹那边的还挺复杂…但靠我这个聪明的脑袋，要熟记也不是什么难事！总…总之！我是绝对值得依靠的！\", \"voicelineId\": 38023, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_pendant\", \"description\": \"「神之眼」应强烈的愿望而生。作为一个有理想的人，我当然能得到它了。因为——我希望所有人都能老老实实，遵纪守法！但如果敢有乱来的家伙，哼哼，那就统统给我接受律法的制裁去！\", \"voicelineId\": 38024, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·秤\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_share_01\", \"description\": \"这杆秤是老爹交给我的宝贝，能衡量出事物的「价值」。通常我会用摩拉当砝码，不过，它只能称量事物最初的价格。举例来说，千年前，璃月遍地都是琉璃百合，这种花在当时并不值钱。后来它数量骤减，售价也水涨船高，这杆秤显示的「价值」却没有更新，还是和之前一样的「便宜」。\\n所以，在大部分情况下，这杆秤也不能作为我工作的帮助啦…怎么？你有什么想要称量的东西吗？比如…称量一下你身边的那个小家伙，怎么样？\", \"voicelineId\": 38025, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·法治\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_share_02\", \"description\": \"我自创的招式「食炎之罚」改编自古籍《璃月会典例律总辑要》中记载的「食岩之罚」。岩王爷是契约之神，契约也可视作约束，说明什么呢？哼哼，说明璃月港自古就是契约之城。\", \"voicelineId\": 38026, \"voicelineType\": \"3003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_pref_gift\", \"description\": \"《璃月风物志》写到某种水生马尾，称它「独坐荻花洲岸，色如霞，可入药。」将其研磨成粉掺入墨汁之中，能使字迹不怕水浸。嗯…可惜啊，我去过荻花洲不下百次，常见的紫色马尾一摘就是几箩筐，却始终找不到书里记载的那种。\", \"voicelineId\": 38027, \"voicelineType\": \"3004\"}, {\"title\": \"关于七七…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_teammate_qiqi_01\", \"description\": \"听说那个采药姑娘给自己编写了一整套行为准则。瞧她身材娇小，办事却有条有理，实乃成大事之风范。\\n后生可畏，后生可畏呀。就连我也要说一声佩服。\", \"voicelineId\": 38028, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_teammate_ganyu_01\", \"description\": \"甘雨前辈温柔又贴心，可惜是个大忙人，大好的时光除了午睡，都在案卷堆里埋头苦干。我虽然也有工作时间，但也是快快乐乐的。我选择的工作，那可比她轻松多了。\", \"voicelineId\": 38029, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_teammate_xingqiu_01\", \"description\": \"飞云商会是我的老主顾了。他家行事一向慎重周全，与我的商谈通常由大当家亲自出面。不过，上一次却碰巧见到了他家小少爷行秋。这位少爷年纪轻轻，没想到居然跟得上我思考的速度。伶牙俐齿还分寸得当，嗯，真不简单。\", \"voicelineId\": 38030, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_teammate_hutao_01\", \"description\": \"常听人说「往生堂」堂主行事奇特，怕是沾了丧葬业的怪毛病。这算什么话？「往生堂」从事的可是正经行业，是构成商业的基本单位。而且工作就是工作，岂有高低贵贱，吉凶险恶之分？\\n不过，那位堂主倒是没怎么来光顾过我的生意，唔…\", \"voicelineId\": 38031, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_teammate_zhongli_01\", \"description\": \"钟离先生学识渊博，堪称行走的书库。你知道吗？我一眼就看出他深藏不露。这样的人大多不怕麻烦，就算遇上什么事也不会请我帮忙，依我看，他绝不是潜在客户。\\n可不知为何，他身上总有些不可思议的熟悉感，我说不上来。问过老爹，他也支支吾吾说什么他也不明白，真是奇怪…总感觉，老爹有什么事不想告诉我。哼，没关系，大不了我自己找机会弄明白…\", \"voicelineId\": 38032, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_teammate_ningguang_01\", \"description\": \"你知道「天权星」凝光小姐吧？她主管律法，也经常修正法典，每次增补删改的内容都多得要命。就在上次，全新的法典里又增加了三条律法，修改了一百二十一条律法注释，还新附了一堆典型判例，这次我又不知道要背到什么时候了…\\n哼，不过她终归是商界出身，论律法，我可不会输给她，等我背完了这些，我一定要更加「努力」地工作…\", \"voicelineId\": 38033, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_teammate_keqing_01\", \"description\": \"好在「玉衡星」不涉足专业律法领域。否则，依刻晴小姐的态度和效率，我怕是要失去不少工作。哦…不，好像也不至于。毕竟刻晴小姐为人刚正，容易得罪人，由我来当助手辅佐的话…哦不不，也不对，为什么我堂堂律法专家要当人助手？有事的话，应该是她来找我咨询才对。\", \"voicelineId\": 38034, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于优菈…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_teammate_eula_01\", \"description\": \"优菈曾经救过我一次，我们也从此有了书信往来。她牢记骑士团的各项条文，却从不墨守成规。还总能找到巧妙的逻辑，灵活处理问题。大概因为我也是这样的人，所以和她相处会特别轻松吧。不过，她那种洒脱劲，我可就学不会啦。毕竟，我和她的职业可是完全不同呢。\", \"voicelineId\": 38035, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夜兰…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_teammate_yelan_01\", \"description\": \"夜兰是总务司的雇员，帮我搞定过做假账的硬茬，我还请她吃了饭呢。不过…和她交谈的时候，总觉得自己的心思会被轻易看穿…嗯，以后千万不要站在她的对立面就好。\", \"voicelineId\": 38036, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于久岐忍…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_teammate_shinobu_01\", \"description\": \"阿忍？我记得她，那个来璃月留学专修律法的稻妻人嘛。为了完成课业实习，她专门约我讨论过案件，每次结束后又是鞠躬又是谢谢的，搞得我都有点不好意思了…当时就觉得，她将来一定会成为出色的律法专家。算起来，稻妻锁国的时间正好是她毕业前后，不知道她回去后一切还顺利吗…\", \"voicelineId\": 38037, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解烟绯·其一\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_friendship_01\", \"description\": \"是客人吗？幸会幸会，这是我的名牌，今天我可能不方便出外勤，有纠纷的话麻烦把双方都带过来，还有咨询费的收费标准我给你看一下，稍等一会儿…\\n欸？只是随便聊聊天？嗯…那就不收钱了。居然会找关系一般的律法专家「随便聊聊天」，真是个特别的人。\", \"voicelineId\": 38038, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解烟绯·其二\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_friendship_02\", \"description\": \"头上的鹿角？噢，这个啊，因为我的老爹是仙人，我有半仙之血嘛。不过，我是在璃月安定后出生的，没跟帝君签订契约，自然不用履行任何仙家职责，可以尽情过自己想要的生活。我还挺满意的，嘿嘿。\", \"voicelineId\": 38039, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解烟绯·其三\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_friendship_03\", \"description\": \"那种维系一生的严肃契约…我只和老爹订过。唔…就是那种「要快乐生活」什么的，他就是那种人啦。不过嘛，我还是挺为老爹的这份通透自豪的。要是他想跟我定那种「要吃苦中苦，要做人上人」之类的契约，我肯定逃都要逃走了。\", \"voicelineId\": 38040, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解烟绯·其四\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_friendship_04\", \"description\": \"有的时候，我处理的商业纠纷会以不太好看的形式收场。对方常常拿出数倍额度的赔偿，或者付出更多的代价…但这都是这些人违背「契约」后应得的苦果。有人会传流言说我很可怕，有人对我避之不及。虽然我没有解释给谁听，但我最初的目的是为了璃月港的大环境着想！\\n你看，纠纷的起点是违背契约，但看到乱来的后果，他们还敢背信弃义吗？让大家意识到「契约」的重要性，也是我工作中的重要一环呢。\", \"voicelineId\": 38041, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解烟绯·其五\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_friendship_05\", \"description\": \"我常常觉得自己活得够潇洒轻松了。你看，我事业有成，衣食自由。走南闯北不成问题，论嘴上功夫也没几个人说得过我。但「快乐生活」这种东西嘛，也没有哪条律法、哪条规范能够定义。\\n就我个人来说，遇见有趣的人、有趣的事，心里清楚该往何处迈出下一步，这样就已经获得快乐了。所以，你也是我的快乐源泉。\\n但话又说回来了！无论怎么生活，最重要的还是要守法懂法。毕竟离开了律法，这个世界肯定马上就会毁灭掉了。\", \"voicelineId\": 38042, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"烟绯的爱好…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_pref_hobby\", \"description\": \"我的爱好是读书和估价。读书能长知识，估价则长眼力。所以什么书都读，什么价都估。你要是不信，随便找件东西给我，只要是市面有售的商品，我都能估个八九不离十哦。就说这块石头好了，错不了，六百摩拉。\", \"voicelineId\": 38043, \"voicelineType\": \"6001\"}, {\"title\": \"烟绯的烦恼…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_dialog_annoyed\", \"description\": \"和记厅的朋友们常约我一起钓鱼，说是切磋钓技，但其实大家心里多少都有些炫耀的成分。我有一百种方法赢过所有人，但他们长期关照我的生意，屡战屡胜未免太不给面子。所以，我每次都靠着精妙的演技假装垫底…等等，你那是什么表情，在怀疑我吗？！\", \"voicelineId\": 38044, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_pref_foodLike\", \"description\": \"哦！说到这种话题，我就要好好向你推荐我的心头挚爱了，豆腐，绝对是豆腐！豆腐本是清淡的食材，口感鲜嫩，温润滋补，搭配各色汤头都能完美融入。最重要的是一年四季均有供应，随时可以吃到！不求至尊，只求完美，豆腐菜就是我要的那种滋味。\", \"voicelineId\": 38045, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_pref_foodDislike\", \"description\": \"我不喜欢冷菜，可能是因为我很少吃冷菜吧。以前如果很晚回到家，老爹也会为我留个灯，听见我的动静，还会问我肚子饿不饿。用他的话说，「菜嘛，总是热的好。」\", \"voicelineId\": 38046, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_spice_pref_01\", \"description\": \"滋味不错，看来你也挺懂「豆腐律法」的嘛。\", \"voicelineId\": 38073, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_spice_normal_01\", \"description\": \"璃月俗话说「民以食为天」，还真是没说错啊。\", \"voicelineId\": 38074, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_spice_dislike_01\", \"description\": \"…有了！我把它热一热再吃吧。\", \"voicelineId\": 38075, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_pref_birthday\", \"description\": \"生日快乐，这个匣子送你。里面是我为你准备的各国律法资料，你不是要去四处旅行了嘛，提前了解一下别国的律法肯定有用。\\n不过也别学得太好哦，不然…我就没法帮你的忙了。\", \"voicelineId\": 38047, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_starUp_01\", \"description\": \"「不期修古，不法常可」，这句话是我必须牢记的教诲。\", \"voicelineId\": 38048, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_starUp_02\", \"description\": \"唯有遵循应守之「律」，人才能获得解开一切问题的「法」。\", \"voicelineId\": 38049, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_starUp_03\", \"description\": \"学习律法是为了跟别人有理有据地谈话，习武防身则是为了应付无理无据的场合。欸，等等…我这能算习武吗…\", \"voicelineId\": 38050, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_yanfei/vo_yanfei_starUp_04\", \"description\": \"我现在应该算「文武双全」了吧！多亏有你一路陪我走到修行之路的终点。报酬嘛…全天候专属私人顾问？还不错吧。喂…不准和我讨价还价！\", \"voicelineId\": 38051, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_battle_skill1_01\", \"description\": \"嘣嘣——\", \"voicelineId\": 38052, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_battle_skill1_02\", \"description\": \"焚烧吧！\", \"voicelineId\": 38053, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_battle_skill1_03\", \"description\": \"速速退下！\", \"voicelineId\": 38054, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_battle_skill3_01\", \"description\": \"律火，引！\", \"voicelineId\": 38055, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_battle_skill3_02\", \"description\": \"食炎之罚！\", \"voicelineId\": 38056, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_battle_skill3_03\", \"description\": \"丹书铁契！\", \"voicelineId\": 38057, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_chest_open_01\", \"description\": \"这算是，「偶然所得」吗？\", \"voicelineId\": 38058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_chest_open_02\", \"description\": \"品相卓越！\", \"voicelineId\": 38059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_chest_open_03\", \"description\": \"嗯，让我来估个价。\", \"voicelineId\": 38060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_life_less30_01\", \"description\": \"得修正错误！\", \"voicelineId\": 38061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_life_less30_02\", \"description\": \"你犯规…\", \"voicelineId\": 38062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_life_less30_03\", \"description\": \"什么，有纰漏？\", \"voicelineId\": 38063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_life_less30_teammate_01\", \"description\": \"喂——还是交给我吧！\", \"voicelineId\": 38064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_life_less30_teammate_02\", \"description\": \"判断是…「紧急避险」！\", \"voicelineId\": 38065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_life_die_01\", \"description\": \"判断…失误了吗…\", \"voicelineId\": 38066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_life_die_02\", \"description\": \"律法…还有漏洞…\", \"voicelineId\": 38067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_life_die_03\", \"description\": \"我不能…接受…\", \"voicelineId\": 38068, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_yanfei/vo_yanfei_battle_hit_H_02\", \"description\": \"麻烦了…\", \"voicelineId\": 38069, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_yanfei_teamJoin_01\", \"description\": \"这次就算你预约过了。\", \"voicelineId\": 38070, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_yanfei_teamJoin_02\", \"description\": \"出外勤要另外收费。\", \"voicelineId\": 38071, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_yanfei_teamJoin_03\", \"description\": \"放马过来。\", \"voicelineId\": 38072, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000049, 'Yoimiya', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_draw_appear\", \"description\": \"欢迎光临「长野原」！我叫宵宫，有什么需要的都可以告诉我！\\n呃…「什锦炸串」和「鸟蛋烧」…不不不，我们家不是饭店啦，是做烟花的！嗯，就是这个，闪闪亮亮，啪啦啪啦的，小烟花~\", \"voicelineId\": 49032, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·烟花\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_character_idle_01\", \"description\": \"烟花易逝，人情长存。\", \"voicelineId\": 49033, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·讲故事\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_character_idle_02\", \"description\": \"没事做的话，我来给你讲故事吧！\", \"voicelineId\": 49034, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·金鱼\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_character_idle_03\", \"description\": \"你养过金鱼吗？很乖巧很可爱哦。\", \"voicelineId\": 49035, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_weather_heavyRain_01\", \"description\": \"呜哇，烟花要湿透了！得找地方躲躲，啊，要来不及了！\", \"voicelineId\": 49036, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_weather_snowy_01\", \"description\": \"哈哈，看我搓个雪球，咻——\", \"voicelineId\": 49037, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_weather_sunny_01\", \"description\": \"全身上下都暖暖的，好舒服啊。嗯，感觉要飘起来了。\", \"voicelineId\": 49038, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_weather_gale_01\", \"description\": \"风好大啊——声音都被吹回来啦——！\", \"voicelineId\": 49039, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_greetingMorning\", \"description\": \"啊——早上好啊，早上的空气最新鲜啦，多吸两口就会变聪明哦。\", \"voicelineId\": 49040, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_greetingNoon\", \"description\": \"嗯，该吃午饭啦，欸…今天的鸡蛋，是双黄蛋呢。嘿嘿，运气真好。\", \"voicelineId\": 49041, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_greetingNight\", \"description\": \"现在是最适合测试烟花效果的时间，无论是在天上还是地上炸开都会很好看。嘿嘿，开玩笑的，我会注意安全啦。\", \"voicelineId\": 49042, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_greetingNight2\", \"description\": \"提问时间——！请问，当看完一整天的烟花之后，接下来要做什么？嘿嘿，答案揭晓：当然是去梦里看烟花啦！晚安，明天见。\", \"voicelineId\": 49043, \"voicelineType\": \"1004\"}, {\"title\": \"关于宵宫自己·家事\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_idle\", \"description\": \"我的老爹耳朵不太好，小时候我无论对他说什么，他都是一副笑呵呵的样子，我就以为我说的都是对的，所以就一直说，一直说，他就一直笑。后来我才知道他笑是因为他听不清楚，但…只要他真的很开心，那我还是会一直说给他听。\", \"voicelineId\": 49044, \"voicelineType\": \"2001\"}, {\"title\": \"关于宵宫自己·说话\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_idle2\", \"description\": \"我不担心什么「祸从口出」，因为蕴含在语言中的情感是不会骗人的。就算说错话被误会，用更多的话去化解就好，但如果什么都不说，对方就没办法了解你的心意，也就没有和你拉近关系的契机了。\", \"voicelineId\": 49045, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·猜拳\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_close\", \"description\": \"我们来玩石头剪刀布吧！听我口令：石头，剪刀，布！好欸，我赢了！我赢了！嗯？我没变啊，才不会变呢。\", \"voicelineId\": 49046, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·陪伴\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_close1\", \"description\": \"其实我不在意我要做什么事，我更在意的是和我一起做事的人。比如和你在一起，就算只是看看风景，踢踢罐子，我都很开心。因为，跟你说话怎么都说不腻嘛。\", \"voicelineId\": 49047, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_pendant\", \"description\": \"悄悄告诉你一件事哦，我刚刚拿到「神之眼」的时候，我是把它当打火石来用的。我用它点过烟花烧过水，回家就把它往库房一扔不管了。结果，还是我老爹发现，告诉我这是个特别珍贵的东西，要好好保管。哈哈…幸好没有被神明大人收回去。\", \"voicelineId\": 49048, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·海灯节\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_share_01\", \"description\": \"你知道吗？璃月的海灯节，有很多烟花都是从我们家订购的。我按照要求做好，再找北斗阿姊用船送去璃月。虽然按锁国令的规矩，我不该把这些东西往外送，但…有节日的地方，烟花一定不能缺席。\", \"voicelineId\": 49049, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·循环\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_share_02\", \"description\": \"「烟花在天空中留下的光点消失之后，会变成雨，会变成雪，重新落到地上。它们滋润了大地，抚育了人类，为的是再一次被送上天空，重现华丽的瞬间。」在老爹讲的很多很多故事里，这是我很喜欢的一个。\", \"voicelineId\": 49050, \"voicelineType\": \"3003\"}, {\"title\": \"有什么想要分享·光斑\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_share_03\", \"description\": \"你小时候踩过地上的光斑吗？就是阳光很好的时候，光线穿过树叶在地上留下的那种光斑。本来以为踩了就会消失，结果它总是会跳到脚背上，我就一直踩，一直踩，试了好久也没成功。那时候挺不甘心的，坐在小石头上叹气，「唉，这个世界上居然有踩不到的东西啊…」\", \"voicelineId\": 49051, \"voicelineType\": \"3004\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_pref_gift\", \"description\": \"有一次夏日祭，我蹲在孩子们旁边看他们捞金鱼的时候，我突然想，有没有可能做出一种能在水上放的烟花呢？然后，「金鱼烟花」就诞生了！能在水面上游来游去，能发出七彩的光，还能吐泡泡呢，很不可思议吧！…我也没想到我真的能成功，但这个世界上就是有很多很多不可思议的事呢。\", \"voicelineId\": 49052, \"voicelineType\": \"3005\"}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_beidou_01\", \"description\": \"稻妻锁国之后，都是北斗阿姊帮我运烟花出去，为了给她一个惊喜，我准备了一个巨大的船型烟花。在「南十字船队」准备离开的时候，这烟花就在他们眼前冲了出去，直飞天空。船员们都以为是船队的船飞出去了，吓了一大跳，但北斗阿姊特别喜欢这个创意。她告诉我，惊喜惊喜，就是要又惊又喜，哈哈。\", \"voicelineId\": 49053, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_raidenShogun_01\", \"description\": \"烟花是和将军追求的「永恒」距离最远的东西，她可能觉得须臾的华光对于稻妻来说没有实际意义。唉，这就是执掌「永恒」的人难以理解的东西吧，正是因为我们都是「须臾之人」，才更需要纪念须臾的美好。\", \"voicelineId\": 49054, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华·认真\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_ayaka_01\", \"description\": \"因为工作关系，她和我家有很多合作。和其他两个奉行的人不同，她每次都会听我把话说完，还会很认真地回答我，完全不会有不耐烦的样子。嗯，「大家闺秀」这个词，就是为她而生的吧。\", \"voicelineId\": 49055, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华·泡澡\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_ayaka_02\", \"description\": \"有一次谈夏日祭的事谈到很晚，我们都很累了，我就邀请她去泡澡解乏。但她听说「泡澡」是很多人泡在同一个池子里的时候，脸一下子就红了，那时候我才意识到，大小姐是不能使用公共浴场的。\", \"voicelineId\": 49056, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于托马…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_thoma_01\", \"description\": \"他是个很擅长说话的人，话从他的嘴里说出来，就一定会有他的想法。虽然看似没什么联系，但绕着绕着，最后都巧妙地指向了同一个目的。嗯…总之就是和我的风格完全不一样啦，遇到我搞不定的事，我就会请他出马。\", \"voicelineId\": 49057, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_yaeMiko_01\", \"description\": \"有次神社祭典，绫华问我能不能为宫司大人准备玩乐用的烟花。可是…宫司大人不是要出席祭典，全程坐在神社里吗？然后我祭典的时候就一直看着她，想知道她要怎么放烟花。我等啊等，等啊等，结果等来了绫华，说宫司大人特别满意…欸？她已经放过了？难道，坐在里面的不是她？\", \"voicelineId\": 49058, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗·对决\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_itto_01\", \"description\": \"哦，他呀。别看他长得那么凶，他很受小孩子欢迎的。不过他的胜负心很强，每次我们一起陪孩子们玩，最后都会变成我和他一决胜负，比如一口气喝完拉面汤，面无表情吃酸梅什么的，孩子们会猜我们谁会赢，还会在旁边加油助威，哎呀，那我可不能输了，对吧？\", \"voicelineId\": 49059, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗·帮派\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_itto_02\", \"description\": \"「荒泷派」？欸？！原来他不是无所事事的人呐？\", \"voicelineId\": 49060, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_kazuha_01\", \"description\": \"像我这样没有心事的人，就喜欢有话直说。而有心事的人，往往都喜欢说古代的诗歌或者沿途的风景，比如花与鸟，风与月，唯独不提眼前的现实。他也是有故事的人吧。嗯，我懂的，我懂的。\", \"voicelineId\": 49061, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_kujoSara_01\", \"description\": \"因为治安和消防问题，我经常被抓去天领奉行的属地接受教育。在那帮人里，九条裟罗应该是最讲道理的一个了，至少她不会在了解情况之前就预设我的对错。如果我是正确的，她也会认同我的观点，如果我错了…嘿嘿，那就去拜托托马帮我赔礼道歉。\", \"voicelineId\": 49062, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于早柚…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_sayu_01\", \"description\": \"如果你见到她，记得告诉我哦？我很想带她去参加祭典，给她介绍很多很多新朋友。因为我看她平时精神不是太好，如果认识一些能玩在一起的人，她应该就会慢慢活泼起来吧。\", \"voicelineId\": 49063, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_klee_01\", \"description\": \"嗯？你说在蒙德有个擅长制作炸弹的小孩子？唔，炸弹和烟花其实相差不大，也就是说，她是这方面的天才？真想见上一面呐。欸，但是…让小孩子玩炸弹很危险吧？蒙德人不会担心吗？\", \"voicelineId\": 49064, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绮良良…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_teammate_kirara_01\", \"description\": \"你说「狛荷屋」的那位快递员呀，她手脚可麻利啦。做烟花的时候，时常有一两种决定颜色的材料消耗得比别的都快，这种时候，她总能很快补来新货，帮了大忙。有次我送了她一个烟花，想要表达感谢。她却怎么也不敢放，说是之前被烟花的动静吓到过。哈哈，那就只好让她跑到远远的地方，我来放给她看喽。\", \"voicelineId\": 49083, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解宵宫·其一\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_friendship_01\", \"description\": \"要听我讲故事啊？好呀好呀，这边坐，我给你讲讲最让我自豪的、「长野原」家的故事吧！是难得的正经话题哟。\", \"voicelineId\": 49065, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解宵宫·其二\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_friendship_02\", \"description\": \"我们家有项悠久的传统，那就是我们会给每一位来定做烟花的客人附赠一张纸条，这张纸条只有我们家的人能看懂，上面记录了烟花的具体配方。不管是过去了十年还是一百年，只要客人能把这张纸条带回来，我们家就能做出和当年完全相同的烟花。\", \"voicelineId\": 49066, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解宵宫·其三\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_friendship_03\", \"description\": \"最美的烟花配最棒的瞬间。那些易逝的小心情就这么被封装在烟花里，以另一种形式传承下去。纸条就像一把钥匙，等待想要纪念过去的人来开门。那么，「长野原」烟花匠人的工作，就是帮大家把门看好。\", \"voicelineId\": 49067, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解宵宫·其四\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_friendship_04\", \"description\": \"夏日祭上每时每刻都在诞生动人的故事，在烟花下相识相知的人们慢慢成长，成熟，最终老去。当他们放起如初的烟花，天空中倒映出的依然是他们如初的模样…烟花不是永恒的，但藏在烟花背后的美妙情感，我觉得应该和稻妻一起走向永恒。\", \"voicelineId\": 49068, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解宵宫·其五\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_friendship_05\", \"description\": \"最后的故事，就不由我来讲了吧，我很想和你静静看一场烟花，把今夜的美景，还有你想说的话全部记录下来。啊，不要误会，不是到此为止的意思，而是关于我们的「故事」，从此才要开始。\", \"voicelineId\": 49069, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"宵宫的爱好·玩耍\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_pref_hobby_01\", \"description\": \"烟花！啊，这个不算吗？那我想想，唔…这个问题好难啊，我喜欢和邻居聊家常，也喜欢和小孩子一起逛夏日祭、游泳、摘野果，好像没办法挑一个特殊的出来…哦，我懂了！我喜欢的，应该就是和大家一起玩吧！\", \"voicelineId\": 49070, \"voicelineType\": \"6001\"}, {\"title\": \"宵宫的爱好·模仿\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_pref_hobby_02\", \"description\": \"咕噜咕噜咕噜，嘿！哈哈，我在学派蒙消失的动作。\", \"voicelineId\": 49071, \"voicelineType\": \"6006\"}, {\"title\": \"宵宫的烦恼…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_dialog_annoyed\", \"description\": \"嗯，我追读了好长时间的小说，终于迎来了大结局，结果女主角失忆了，说好的婚礼也没办成…好难过，怎么这样！\", \"voicelineId\": 49072, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_pref_foodLike\", \"description\": \"比起主食，我更喜欢吃点心，每次祭典的时候我都会一家一家吃过去，直到吃不下为止。对了，你擅长做点心吗？我拿我做的团子和你换，这几个大的都给你。\", \"voicelineId\": 49073, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_pref_foodDislike\", \"description\": \"牛奶。喝了牛奶的话肚子里面就像开烟花会一样，噼里啪啦的。但加了牛奶的菜或者点心我可以吃，我也不知道为什么。可能是肚子里的小仙灵比较挑食？\", \"voicelineId\": 49074, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_spice_pref_01\", \"description\": \"哇，你做点心的手艺很不一般啊！去祭典上摆摊的话，肯定会成为最热门的那一个吧！\", \"voicelineId\": 49080, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_spice_normal_01\", \"description\": \"吃到了好吃的东西，人就会变得很有精神。一有精神，就想开始讲故事。嗯，我来挑个故事吧！\", \"voicelineId\": 49081, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_spice_dislike_01\", \"description\": \"哎呀，肚子里面好像有飘浮灵在上下闹腾…这不应该呀…\", \"voicelineId\": 49082, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_pref_birthday\", \"description\": \"生日从来都不是你一个人的节日哦，愿意为你送蛋糕，点蜡烛，鼓掌欢呼的人，都发自真心地感谢你能够降生在这个世界上。所以，一定要热热闹闹的才好，让所有人都有感谢你的机会！那么，生日快乐！准备好了吗？我要放烟花了！\", \"voicelineId\": 49075, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_starUp_01\", \"description\": \"飞得更高，炸得更响！\", \"voicelineId\": 49076, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_starUp_02\", \"description\": \"哈哈，我来试试看，直接用弓箭把烟花送上天空吧！\", \"voicelineId\": 49077, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_starUp_03\", \"description\": \"难得从你这里学到了这么多战斗技巧，干脆除了烟花工匠之外，我再去兼职当冒险家好了，或者…「英雄」也不错？\", \"voicelineId\": 49078, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_yoimiya/vo_yoimiya_starUp_04\", \"description\": \"「『英雄形态』的宵宫姐姐登场！邪恶退散！正义必胜！」\\n就这么和小孩子们介绍你教给我的新力量，没问题吧？应该很帅吧。嘿嘿，如果有人欺负你也要告诉我哦，宵宫姐姐帮你出头！\", \"voicelineId\": 49079, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_battle_skill1_01\", \"description\": \"想看烟花吗？\", \"voicelineId\": 49009, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_battle_skill1_02\", \"description\": \"点燃引信！\", \"voicelineId\": 49010, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_battle_skill1_03\", \"description\": \"小心火烛~\", \"voicelineId\": 49011, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_battle_skill3_01\", \"description\": \"祭典重现！\", \"voicelineId\": 49012, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_battle_skill3_02\", \"description\": \"金鱼来啦！\", \"voicelineId\": 49013, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_battle_skill3_03\", \"description\": \"烟花来喽！\", \"voicelineId\": 49014, \"voicelineType\": \"200003\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_explore_fly_start_01\", \"description\": \"飞高高啦——\", \"voicelineId\": 49015, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_chest_open_01\", \"description\": \"会有烟花材料吗？\", \"voicelineId\": 49016, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_chest_open_02\", \"description\": \"里面有什么呢？\", \"voicelineId\": 49017, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_chest_open_03\", \"description\": \"我来开我来开！\", \"voicelineId\": 49018, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_life_less30_01\", \"description\": \"不妙不妙！\", \"voicelineId\": 49019, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_life_less30_02\", \"description\": \"出丑了啊…\", \"voicelineId\": 49020, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_life_less30_03\", \"description\": \"得小心起来了啊。\", \"voicelineId\": 49021, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_life_less30_teammate_01\", \"description\": \"换我来支援你！\", \"voicelineId\": 49022, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_life_less30_teammate_02\", \"description\": \"别担心，有我在。\", \"voicelineId\": 49023, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_life_die_01\", \"description\": \"一不小心就…\", \"voicelineId\": 49024, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_life_die_02\", \"description\": \"玩过头了…\", \"voicelineId\": 49025, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_life_die_03\", \"description\": \"祭典…结束了。\", \"voicelineId\": 49026, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_battle_hit_L_02\", \"description\": \"轻点啊。\", \"voicelineId\": 49027, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_yoimiya/vo_yoimiya_battle_hit_H_02\", \"description\": \"这下不算！\", \"voicelineId\": 49028, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_yoimiya_teamJoin_01\", \"description\": \"你想办祭典吗？\", \"voicelineId\": 49029, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_yoimiya_teamJoin_02\", \"description\": \"一起去玩吧！\", \"voicelineId\": 49030, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_yoimiya_teamJoin_03\", \"description\": \"同行的伙伴增加了！\", \"voicelineId\": 49031, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000050, 'Thoma', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_draw_appear\", \"description\": \"初次见面，异乡的旅人，你的名字我可是早就听说了。只要你不嫌弃，我托马，从今天起就是你的朋友了。\", \"voicelineId\": 50008, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·请客\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_character_idle_01\", \"description\": \"嗯…找个时间一起吃顿好的怎么样，我请客。\", \"voicelineId\": 50009, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·担忧\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_character_idle_02\", \"description\": \"总觉得有什么事忘记做了…庭院打理过，茶也煎了，嗯…应该是错觉吧。\", \"voicelineId\": 50010, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·摩拉\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_character_idle_03\", \"description\": \"这几天花得太多，身上只剩十摩拉了，不过幸好还有十摩拉！\", \"voicelineId\": 50011, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_weather_heavyRain_01\", \"description\": \"怎么突然下雨了？你没事吧？要不要用我的外套挡挡？\", \"voicelineId\": 50012, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_weather_thunder_01\", \"description\": \"这种天气就别在野外晃悠了，会被劈的。\", \"voicelineId\": 50013, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_weather_snowy_01\", \"description\": \"别在雪地上跑哦，摔了我可不扶你。\", \"voicelineId\": 50014, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_weather_sunny_01\", \"description\": \"天气真不错啊，一起散步吧。\", \"voicelineId\": 50015, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_greetingMorning\", \"description\": \"早啊。要是你不忙，要不要跟我一起去集市上逛逛？早上的蔬菜可是最水灵的哦。\", \"voicelineId\": 50016, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_greetingNoon\", \"description\": \"今天午饭除了绯樱天妇罗还有三彩团子！来，你和派蒙都有份，还有神里小姐和家主大人的…欸等下，我好像忘了准备自己的份。\", \"voicelineId\": 50017, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_greetingNight\", \"description\": \"快走快走，这个点去市场买鱼能便宜不少。要是心血来潮想买什么小玩意儿，我帮你砍价。\", \"voicelineId\": 50018, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_greetingNight2\", \"description\": \"嗯，晚安。你这一天也辛苦了吧。早点休息去吧，别熬夜。\", \"voicelineId\": 50019, \"voicelineType\": \"1004\"}, {\"title\": \"关于托马自己·家政官\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_idle\", \"description\": \"不论是神里小姐还是家主大人，最初都没打算让我担任家政官，还是我自告奋勇的。我很喜欢这些活，将一切打理得井井有条，特别有成就感。看大家的反应…嗯，我应该干得不错。\", \"voicelineId\": 50020, \"voicelineType\": \"2001\"}, {\"title\": \"关于托马自己·意义\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_idle2\", \"description\": \"把居住的地方打扫干净，布置整齐，让所有生活在这里的人露出笑容，这就是家政的意义。至于现在…我会连带着为了你的份一起，好好努力的。\", \"voicelineId\": 50021, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·一人食\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_close\", \"description\": \"怎么一个人在这儿安安静静吃饭？…嗯，你介不介意跟我一起？还是说你比较想一个人吃？\", \"voicelineId\": 50022, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·立誓\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_close1\", \"description\": \"要不是你在「狩眼仪式」上站出来，单枪匹马与将军对抗，我应该已经失去神之眼，失去愿望了。我想了很久，恐怕只有这样才配得上你挺身而出的觉悟——\\n我，托马，愿献上我的武艺与忠诚。不惜一切，为你而战。\", \"voicelineId\": 50023, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_pendant\", \"description\": \"既然得到了神之眼，就得好好珍惜，我可不想把它弄丢了。\", \"voicelineId\": 50024, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_share_01\", \"description\": \"以我长期和大家打交道的经验来看，比起蒙德人，稻妻人更加在意礼节。要是能始终保持礼貌的态度，事情会变得好办不少。\", \"voicelineId\": 50025, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻·狸猫\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_pref_gift_01\", \"description\": \"我一直想见识狸猫的变化手段。传闻中，狸猫能够变化成各种各样的形态，跟路人开玩笑，是一种很有幽默感的生灵哦。\", \"voicelineId\": 50026, \"voicelineType\": \"3003\"}, {\"title\": \"感兴趣的见闻·动物\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_pref_gift_02\", \"description\": \"你喜欢小动物吗？要是你也喜欢的话，下次我带你去城郊附近走走。到时候我一声口哨，好多可爱的小猫小狗就会钻出来，黏在你的脚边向你撒娇。哈哈，光是想象就觉得很开心了。\", \"voicelineId\": 50027, \"voicelineType\": \"3004\"}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_yaeMiko_01\", \"description\": \"神子大人？为、为什么突然提她？唉，每次小姐派我出去送口信，我最不想去的就是鸣神大社了。啊，倒不是神子大人的气场让人发慌，而是，呃…是敬畏…敬畏！啊哈哈…\", \"voicelineId\": 50028, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军·比较\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_raidenShogun_01\", \"description\": \"在我的故乡蒙德，绝大多数人都尊敬着风神巴巴托斯大人。但稻妻人对待将军大人的态度就不同了。怎么说呢…除了爱戴与感激，好像还有些畏惧的成分。\", \"voicelineId\": 50029, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军·未知\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_raidenShogun_02\", \"description\": \"说实话，我对将军本人没什么怨恨。虽说她差点夺走我的神之眼，但那是因为她的立场特殊吧。立场不同是很正常的事情。\\n我想不明白的，是她的目的。她所设想的永恒国度到底是什么样？为什么非得牺牲民众的愿望换取。我无法理解，也无法认同。\", \"voicelineId\": 50030, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_beidou_01\", \"description\": \"「南十字」船队的大姐头可真是个飒爽的人呐。她曾经允诺带我去遥远的外海，看看封锁一切的雷暴是个什么样子。只是可惜，我一直没这个机会出去看看…\", \"voicelineId\": 50031, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫人…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_ayato_01\", \"description\": \"家主大人也够不容易的了。时局动荡，人心不安，同僚里又有不少贪官败类，想想都头疼。我所能做的，也就是在生活方面给予些照顾了。\", \"voicelineId\": 50032, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_ayaka_01\", \"description\": \"神里小姐知书达理，心地善良又温柔端庄，就是不够坦率。欸对了，下次说话的时候，要是小姐又露出那副欲言又止的模样，你一定要主动些，多问问她的想法。\", \"voicelineId\": 50033, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_yoimiya_01\", \"description\": \"「长野原烟花店」的那位店长？她很容易相处的，算是心直口快的类型。哦对了，她家的烟花也是厉害得很，有机会一定要多看几次。喏，优惠券给你。\", \"voicelineId\": 50034, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于早柚…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_sayu_01\", \"description\": \"唉，早柚太倔强了。不管我找她多少次，都不肯传授我忍术。甚至最近都刻意躲着我了…明明只是想求师而已，是我做得太过头了吗？\", \"voicelineId\": 50035, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_kujoSara_01\", \"description\": \"这位天领奉行麾下的将领，嗯…跟她交涉得拿出十二分的谨慎。她手握实权，又有点固执，嬉皮笑脸是绝对行不通的。\", \"voicelineId\": 50036, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_itto_01\", \"description\": \"那是市井传闻中的怪人，据说还拥有妖怪的血脉，你见过他了吗？要是你们熟络的话，帮我引荐引荐呗。广交朋友总是好事…妖怪朋友也算！\", \"voicelineId\": 50037, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鹿野院平藏…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_heizou_01\", \"description\": \"嚯，他可是天领奉行那边的「侦探」。他给人一种我行我素的感觉，不太容易打交道。另外，需要侦探出现的场合，一般也不会有什么好事。我还是和风暴中心保持距离吧。\", \"voicelineId\": 50038, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_qin_01\", \"description\": \"古恩希尔德家的琴小姐做了西风骑士团的团长吗？的确合适，她的优秀正直是出了名的…哦，目前还只是代理团长吗？哈哈，那种名头根本无所谓啦。\", \"voicelineId\": 50039, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于优菈…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_teammate_eula_01\", \"description\": \"你还遇见过优菈·劳伦斯吗？我只知道，他们家的人脾气烂透了，最好不要有什么来往。啊，跟你聊这些，又想起了很多蒙德的往事…真好。\", \"voicelineId\": 50040, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解托马·其一\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_friendship_01\", \"description\": \"有什么需要我帮忙的吗？家中杂务，人际交往，一句话的事。欸？聊天吗…这样这样。那倒是需要更用心一些了。\", \"voicelineId\": 50041, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解托马·其二\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_friendship_02\", \"description\": \"我应该跟你提过吧？我不是土生土长的稻妻人。我是从蒙德一路坐船来的，因为喜欢这里的风土，又遇到了家主大人和神里小姐这样亲切的人，干脆就留了下来。\", \"voicelineId\": 50042, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解托马·其三\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_friendship_03\", \"description\": \"其实我也会有想老家的时候，所以，我特别能理解离岛上那些外国商人，也想尽量多关照关照。不同的是，他们只把自己当作一个过客，并不想融入稻妻，因此也就只是过客了。大多数稻妻人不会把他们当自己人。\", \"voicelineId\": 50043, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解托马·其四\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_friendship_04\", \"description\": \"对一些保守的稻妻人来说，一个外国人要做奉行家的家臣，是几乎不能想象的事。因此，我有过一段不受人待见的经历。要不是他俩力保，恐怕我早被赶走了。为了不辜负神里家的恩情，那之后我诚心努力了很久，最终才被大家接纳。\", \"voicelineId\": 50044, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解托马·其五\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_friendship_05\", \"description\": \"这话跟你说…应该没关系吧。有一阵子，我很想回老家去。毕竟蒙德才是我的故乡，但稻妻…我同样难以割舍。你看，我受过许多稻妻人的恩惠——神里家始终有留给我的房间，还有不是亲人胜似亲人的人。就算吃过苦头，但也是帮助我的人多。想来想去，觉得自己还是留在稻妻好。实在想念蒙德的时候…就找你聊聊好了。你不会嫌弃我唠叨吧？\", \"voicelineId\": 50045, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"托马的爱好…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_pref_hobby\", \"description\": \"最近的话，我比较喜欢怪谈故事，那些千变万化的妖怪实在是神奇。之前的话，对忍术也有不小的兴趣。嗯？三分钟热度？…不，不是这样的！\", \"voicelineId\": 50046, \"voicelineType\": \"6001\"}, {\"title\": \"托马的烦恼…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_dialog_annoyed\", \"description\": \"我现在真的很烦恼。晚上大人要在家设宴招待朋友，说好了由我来露一手，做黄油蟹蟹撑场面的。结果这两天根本买不到螃蟹！难道我只能下水抓螃蟹了吗？\", \"voicelineId\": 50047, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_pref_foodLike\", \"description\": \"要说我最喜欢的食物，那绝对是市井杂煮了。煮好香喷喷的一大锅，然后大家一起分着吃，又热闹又开心。\", \"voicelineId\": 50048, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_pref_foodDislike\", \"description\": \"食物的范围里没什么，但如果饮料也算的话…我不怎么能喝酒。别笑我，我也怀疑过自己是不是蒙德人了。不过…过量饮酒对身体有害，不喝酒，也是好事吧。\", \"voicelineId\": 50049, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_spice_pref_01\", \"description\": \"好香！我还想再添一碗米饭！\", \"voicelineId\": 50077, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_spice_normal_01\", \"description\": \"你还有时间吗？和我一起分享厨艺心得吧！\", \"voicelineId\": 50078, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_spice_dislike_01\", \"description\": \"没怎么尝试过的味道…虽然也不坏吧。\", \"voicelineId\": 50079, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_pref_birthday_01\", \"description\": \"快跟我来，现在就来！你的生日我当然不会忘记，这不，准备好了一场大聚会。有吃有喝，还有一大帮你的朋友。嘿，这是纪念你诞生的好日子，我可不会让你一个人孤零零地过！\", \"voicelineId\": 50050, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_starUp_01\", \"description\": \"这样就能变强吗？不是在开玩笑吧，我还有衣服没洗完呢。\", \"voicelineId\": 50051, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_starUp_02\", \"description\": \"似乎…有一股火焰在我心中燃烧。\", \"voicelineId\": 50052, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_starUp_03\", \"description\": \"拥有了强大的力量，要用来做什么呢？嗯…得好好考虑考虑了啊。\", \"voicelineId\": 50053, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_thoma/vo_thoma_starUp_04\", \"description\": \"谢谢你对我的信赖。你给予我的恩惠，比火焰更温暖。放心吧，我找到自己想做的事了。这份力量将化作坚盾，一直守护你。\", \"voicelineId\": 50054, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_battle_skill1_01\", \"description\": \"火之盾！\", \"voicelineId\": 50055, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_battle_skill1_02\", \"description\": \"看看这个。\", \"voicelineId\": 50056, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_battle_skill1_03\", \"description\": \"小心着火。\", \"voicelineId\": 50057, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_battle_skill3_01\", \"description\": \"后援登场。\", \"voicelineId\": 50058, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_battle_skill3_02\", \"description\": \"护持之火！\", \"voicelineId\": 50059, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_battle_skill3_03\", \"description\": \"我来守护你。\", \"voicelineId\": 50060, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_chest_open_01\", \"description\": \"里面有什么好东西呢？\", \"voicelineId\": 50061, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_chest_open_02\", \"description\": \"哟，果然今天运势大吉。\", \"voicelineId\": 50062, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_chest_open_03\", \"description\": \"嘿嘿，见者有份。\", \"voicelineId\": 50063, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_life_less30_01\", \"description\": \"喂！有必要吗？\", \"voicelineId\": 50064, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_life_less30_02\", \"description\": \"惨了惨了…\", \"voicelineId\": 50065, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_life_less30_03\", \"description\": \"嘶，有那么点疼…\", \"voicelineId\": 50066, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_life_less30_teammate_01\", \"description\": \"别怕，我会保护你的。\", \"voicelineId\": 50067, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_life_less30_teammate_02\", \"description\": \"真是乱来，快去歇着。\", \"voicelineId\": 50068, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_life_die_01\", \"description\": \"要回老家了啊…\", \"voicelineId\": 50069, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_life_die_02\", \"description\": \"各位…保重。\", \"voicelineId\": 50070, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_life_die_03\", \"description\": \"没能尽到…守护的职责…\", \"voicelineId\": 50071, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_battle_hit_H_01\", \"description\": \"疼疼疼。\", \"voicelineId\": 50072, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_thoma/vo_thoma_battle_hit_H_02\", \"description\": \"住手！\", \"voicelineId\": 50073, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_thoma_teamJoin_01\", \"description\": \"好吧，家务待会再说。\", \"voicelineId\": 50074, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_thoma_teamJoin_02\", \"description\": \"出门找点新朋友。\", \"voicelineId\": 50075, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_thoma_teamJoin_03\", \"description\": \"这次去哪儿转转？\", \"voicelineId\": 50076, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000051, 'Eula', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_draw_appear\", \"description\": \"西风骑士团，游击小队队长，「浪花骑士」优菈·劳伦斯，向你致以问候…嗯，劳伦斯，没错。如你所见，我是罪人的后裔，是骑士团的内鬼，正在向他们复仇。\", \"voicelineId\": 39009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·礼仪\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_character_idle_01\", \"description\": \"骑士和贵族的礼仪一脉相承，只是前者脚踏实地，简化了繁文缛节。\", \"voicelineId\": 39010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·剑技\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_character_idle_02\", \"description\": \"西风剑术？想和我学两手吗？等你学成再找你报仇，想必能增添不少乐趣。\", \"voicelineId\": 39011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·规矩\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_character_idle_03\", \"description\": \"贵族们的陈腐规矩啊…听听就好，哪怕像我一样，被迫背诵了几百条，也不必当真。\", \"voicelineId\": 39012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_weather_heavyRain_01\", \"description\": \"快到伞下来，别被淋湿了。要是你得了病，身体早早就垮掉，那我找谁报仇去？\", \"voicelineId\": 39013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_weather_thunder_01\", \"description\": \"麻烦的天气，雷声会干扰听觉，影响我对周边的感知。\", \"voicelineId\": 39014, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_weather_sunny_01\", \"description\": \"视野不错！登上高地，就能将周围的敌情尽收眼底。\", \"voicelineId\": 39015, \"voicelineType\": \"1203\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_greetingMorning\", \"description\": \"该起床了，日出前两个小时，值岗一夜的哨兵最为疲惫，是我们活动的绝佳时间！\", \"voicelineId\": 39016, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_greetingNoon\", \"description\": \"午饭要少吃谷物，多吃肉类，防止午后困倦，被人趁机暗算。\", \"voicelineId\": 39017, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_greetingNight\", \"description\": \"「愿柔风伴你，度过安详的一夜。」…旧贵族的问候语里，难得有这么中听的一句。\", \"voicelineId\": 39018, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_greetingNight2\", \"description\": \"想听骨哨的催眠曲吗？会让你长睡不醒…但这样的报仇方法，实在太无聊了。\", \"voicelineId\": 39019, \"voicelineType\": \"1004\"}, {\"title\": \"关于优菈自己·骑士\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_idle\", \"description\": \"打入敌人内部，不就能更方便地复仇了吗？所以我才加入骑士团啊。\", \"voicelineId\": 39020, \"voicelineType\": \"2001\"}, {\"title\": \"关于优菈自己·态度\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_idle2\", \"description\": \"既然成为了西风骑士，基本工作还是要尽职的，不然就连混日子的庸人们都不如了。哪怕是罪人，也不能这么丢脸。\", \"voicelineId\": 39021, \"voicelineType\": \"2002\"}, {\"title\": \"关于优菈自己·游击\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_idle3\", \"description\": \"游击骑士的职责是自由狩猎敌军，或者在侧面战场牵制敌人，没有太多规矩，更符合我的作风。\", \"voicelineId\": 39022, \"voicelineType\": \"2003\"}, {\"title\": \"关于优菈自己·舞蹈\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_idle4\", \"description\": \"劳伦斯家的传统倒也不全是糟粕，至少「祭礼之舞」纯净而高洁，让我心境平和，给过我不少慰藉。这么多年来，我一直没有放下它，每个舞步都刻进了我的身体…所以，言归正传，想要学到只属于我的「西风剑术」，还得先过舞蹈这关。\", \"voicelineId\": 39023, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·共性\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_close\", \"description\": \"其实我们俩有点像，对于蒙德，我们都是「外人」。只不过，你这个外人受到欢迎，而我一直被提防，被人敌视。\", \"voicelineId\": 39024, \"voicelineType\": \"2005\"}, {\"title\": \"关于我们·复仇\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_close1\", \"description\": \"你还会和我结下更多仇的，不如就等到哪天一并清算吧，这样能省掉不少麻烦。也许是十年后，二十年后…放心，我不会忘的。在那之前，你可要生龙活虎，平安无事啊。\", \"voicelineId\": 39025, \"voicelineType\": \"2006\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_pendant\", \"description\": \"「罪人的后裔」，这个名号不太中听，我只有不断用我的方式复仇，才能彻底摆脱它。想要复仇就需要力量，得到「神之眼」，也是情理之中的事吧。\", \"voicelineId\": 39026, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·骨哨\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_share_01\", \"description\": \"我的骨哨能吹出各种音色，迷惑敌人，相当实用。我经常用它吹奏海浪的声音，「浪花骑士」的称号就是这样来的。但没人在乎，这骨哨的技艺起源于璃月。毕竟他们也不会去深究…一个被蒙德排斥的罪人，找了个被人遗忘的璃月人当老师嘛。\", \"voicelineId\": 39027, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·品酒\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_share_02\", \"description\": \"按理说，陈酿蒲公英酒要搭配银杯，醒酒十二分钟后加入冰块，酒面没过冰块六成为宜。但这样实在太麻烦了，我可不乐意。\", \"voicelineId\": 39028, \"voicelineType\": \"3003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_pref_gift\", \"description\": \"冰雾花呀，怎么就这么罕见呢？它制作的粉末有奇效，能让骨哨的音色变得更通透。\", \"voicelineId\": 39029, \"voicelineType\": \"3004\"}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_ambor_01\", \"description\": \"安柏总是自作主张，我刚加入骑士团那天，她替我打扫宿舍，带我四处参观，之后也主动帮我搞定各种麻烦事。在别人看来，我就像是个被妹妹照顾的姐姐，这怎么像话！这些仇，我都记下了！\", \"voicelineId\": 39030, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_qin_01\", \"description\": \"代理团长啊，她和我的家族是宿敌。但她公私分明，认可我的实力，邀请我加入骑士团，给了我不少机会。所以我考虑在复仇时，赏她一个不算难看的败北。\", \"voicelineId\": 39031, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_lisa_01\", \"description\": \"啊，麻烦的女人，她的脑袋里装着几千本书，也许是几万本。她能随口数落劳伦斯家的黑历史，每件事的日期都很准确。按理来说，她能帮我追查某个人的下落，可我又拉不下脸去找她。\", \"voicelineId\": 39032, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芭芭拉…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_barbara_01\", \"description\": \"她到底有什么秘诀，这么讨人喜欢？要是能和她学两招…哦不，还是算了吧，「偶像」和「罪人的后裔」，怎么想都不合拍。\", \"voicelineId\": 39033, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_varka_01\", \"description\": \"大团长啊，他的性格很直爽，不在乎琐事和传闻，算是个老好人吧。我和他切磋过一次，打成了平手，但他那轻松的表情，散漫的态度，绝对是在放水！是对我最大的轻视！这个仇，我绝不会忘的！\", \"voicelineId\": 39034, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温迪…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_venti_01\", \"description\": \"那个吟游诗人唱过几首歌，把劳伦斯家放进轻快的故事，用从没听过的口吻调侃，连我都憋不住笑…这个仇，我不会忘的。\", \"voicelineId\": 39035, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷泽…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_razor_01\", \"description\": \"不用拘泥于礼仪，不必在乎他人的目光，也没有所谓的家族责任…他的生活方式，还蛮轻松的。\", \"voicelineId\": 39036, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于砂糖…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_sucrose_01\", \"description\": \"那个炼金术士？她给过我一种装置，说是能用来潜入深渊教团的营地，结果却发出巨响爆炸了，害我当场暴露，被十三个丘丘暴徒围攻。事后我本来想找她算账，可看她慌张又内疚的样子，还有墙上贴着的失败记录，我也不好说什么。反正我没受伤，只是灰头土脸，有点丢人。\", \"voicelineId\": 39037, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪卢克…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_diluc_01\", \"description\": \"我和骑士团的某些人不对付，他也看骑士团不顺眼，理论上，我俩是一边的。但他总是对人不理不睬的样子，感觉比代理团长还麻烦。唉，我可不想和他打交道。\", \"voicelineId\": 39038, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪奥娜…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_diona_01\", \"description\": \"她呀，是个奇妙的调酒师呢，居然和我聊得来。她为了毁灭蒙德酒业在酒馆工作，而我为了向骑士团复仇加入了骑士团，天下还有这么巧的事。\", \"voicelineId\": 39039, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于烟绯·相识…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_yanfei_01\", \"description\": \"说来话长…有次我们追踪深渊教团的一批危险品，碰巧救下了她。当时，教团的危险品被伪装成普通货物，要从荆夫港转运到璃月港，她是跟随商船的顾问，发现货物有鬼，就擅自进行了调查，结果引火上身。要是我们再晚几分钟到，她就要倒大霉了。\", \"voicelineId\": 39040, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于烟绯·看法…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_yanfei_02\", \"description\": \"之后我们一直保持着联络，我还蛮喜欢她那股机灵劲儿的。她牢记规矩，但懂得变通，如果骑士团里的某些人能学学她就好了。而且，凭她的本事，应该能帮我找到那个人。就当是她还上欠我的人情了。\", \"voicelineId\": 39041, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于米卡·沟通\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_mika_01\", \"description\": \"米卡被分来游击小队的时候，我以为他会像之前某些人一样，没干几天就想走了。没想到他不声不响，任务却完成得相当出色，还主动承担了所有跑腿的任务，替我和其他人沟通。哼，一个两个都想着照顾我，也不知道是谁教出来的。\", \"voicelineId\": 39086, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于米卡·回归\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_teammate_mika_02\", \"description\": \"这次米卡从远征队回来，性格没什么变化，实力倒是强劲了不少。看来大团长没有怠慢对大家的训练。嗯？你说他自己都没发现？那是他迟钝吧…或者说，谦虚。毕竟是我小队的成员，这种事，看一眼就知道了。\", \"voicelineId\": 39087, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解优菈·其一\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_friendship_01\", \"description\": \"罪人的经历，有什么好了解的？反正不管说什么做什么，都会被敌视，被当成潜在的危险分子吧。现在还算好了，没加入骑士团的时候，猎鹿人和蒙德百货都不愿意卖东西给我，吃饭都得去野外打猎生火自己做。\", \"voicelineId\": 39042, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解优菈·其二\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_friendship_02\", \"description\": \"有人劝过我低声下气，谨言慎行，说这样也许能获得谅解，但他们会这么想，只是因为他们没当过真正的「罪人」。…「罪人」是不会轻易被原谅的，那还不如洒脱一点，上门复仇，堂堂正正地去较量。要是赢了我，我听凭处置，可要是输了，就得满足我的要求。比如…唉，至少也要好好地把东西卖给我吧。\", \"voicelineId\": 39043, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解优菈·其三\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_friendship_03\", \"description\": \"西风骑士团倒还挺像样的，至少他们更看重一个人的「才能」而非「身份」。当年我和他们的精锐切磋过几次，用实力折服了他们，所以收到了入团邀请。在骑士团内部工作，复仇更方便了，生活中的麻烦也减少了，何乐而不为呢？\", \"voicelineId\": 39044, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解优菈·其四\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_friendship_04\", \"description\": \"劳伦斯家族是在堕落后才背负恶名的，在此之前，这个姓氏也曾满载荣耀，可惜所有人都像是忘掉了那段历史。大团长说我作为骑士，干得还算不错，不说找回劳伦斯最初的荣光，至少是对片面观点的迎头痛击。这个说法倒是挺合我意的。\", \"voicelineId\": 39045, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解优菈·其五\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_friendship_05\", \"description\": \"如果家族里的那些人一直执迷不悟，甚至继续荼毒蒙德，那他们和劳伦斯这个姓氏，就该被我亲手抹杀…这大概是我唯一想要履行的「家族责任」吧。在那之后，我就随意改个姓氏，由你来起都没问题！\", \"voicelineId\": 39046, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"优菈的爱好…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_pref_hobby\", \"description\": \"凉爽的事，我都很中意。比如，痛饮冰镇后的酒和饮料，坐在峡谷山口享受狂风，或者跳进龙脊雪山山脚的湖里泡澡。哈，没准哪天你在湖边晃荡，会被我拖进冰水里哦。\", \"voicelineId\": 39047, \"voicelineType\": \"6001\"}, {\"title\": \"优菈的烦恼…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_dialog_annoyed\", \"description\": \"有的时候酒馆生意太火爆，我被要求和人拼桌。听说我是劳伦斯家的人，摆谱的、挑衅的、明着暗着使绊子的，就从各种地方冒出来了，唉，还让不让人好好喝酒了？\", \"voicelineId\": 39048, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_pref_foodLike\", \"description\": \"我喜欢亲手做点心，点心不一定都是甜品，比如冰镇后的番茄肉冻蛋卷，就很适合搭配冰树莓薄荷酒。重要的是，有些人吃到我做的点心，就会笑得很开心。\", \"voicelineId\": 39049, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_pref_foodDislike\", \"description\": \"浓郁的汤品，我实在不能接受。口感太厚重，饱腹感很强，影响运动和战斗，还不方便携带，简直是我的天敌。\", \"voicelineId\": 39050, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_spice_pref_01\", \"description\": \"哦？这是对我的挑战吗。我接受了。\", \"voicelineId\": 39083, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_spice_normal_01\", \"description\": \"马马虎虎嘛…你自己也尝尝？\", \"voicelineId\": 39084, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_spice_dislike_01\", \"description\": \"你这家伙，是在报复我吗？\", \"voicelineId\": 39085, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_pref_birthday\", \"description\": \"今天是个值得纪念的日子，但你的成长不能只限于年龄。送你一个特制骨哨，跟我学学吹奏的方法吧。等到我向你报仇的那天，你可以试试，用这枚骨哨干扰我，拖延时间，挣扎得更有趣一些吧。\", \"voicelineId\": 39051, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_starUp_01\", \"description\": \"战技提升了不少，但还不值得沾沾自喜。骑士团里也有不少家伙格外勤奋，要想战胜他们完成复仇，必须远远将他们甩在身后。\", \"voicelineId\": 39052, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_starUp_02\", \"description\": \"不错，以我现在的实力，哪怕和代理团长一较高下，也十拿九稳了！\", \"voicelineId\": 39053, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_starUp_03\", \"description\": \"奇怪…和你同行时，力量增长得格外迅猛呢。看来和你结仇是件走运的事，我得紧紧咬住你不放了。\", \"voicelineId\": 39054, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_eula/vo_eula_starUp_04\", \"description\": \"很好！这股坚冰的力量已被我牢牢掌控。别说代理团长，大团长都没法再阻挡我了！事不宜迟，我可以制定计划，发起总攻了。挫败西风骑士团之后，下个目标就是你，你也别想逃，乖乖待在我身边，见证这一切吧。\", \"voicelineId\": 39055, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_skill1_01\", \"description\": \"求饶吧。\", \"voicelineId\": 39056, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_skill1_02\", \"description\": \"结霜！\", \"voicelineId\": 39057, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_skill1_03\", \"description\": \"粉化！\", \"voicelineId\": 39058, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_skill1_04\", \"description\": \"判决！\", \"voicelineId\": 39059, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_skill1_05\", \"description\": \"破碎！\", \"voicelineId\": 39060, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_skill1_06\", \"description\": \"以眼还眼！\", \"voicelineId\": 39061, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_skill3_01\", \"description\": \"冰浪怒涛！\", \"voicelineId\": 39062, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_skill3_02\", \"description\": \"以霜还怨！\", \"voicelineId\": 39063, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_skill3_03\", \"description\": \"坚冰，断绝深仇！\", \"voicelineId\": 39064, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_explore_sprint_start_01\", \"description\": \"加快脚步。\", \"voicelineId\": 39065, \"voicelineType\": \"700001\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_explore_fly_start_01\", \"description\": \"空中行动，视野更棒。\", \"voicelineId\": 39066, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_chest_open_01\", \"description\": \"有所发现。\", \"voicelineId\": 39067, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_chest_open_02\", \"description\": \"嗯，大多能派上用场。\", \"voicelineId\": 39068, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_chest_open_03\", \"description\": \"罪人也有这么走运的时候啊…\", \"voicelineId\": 39069, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_life_less30_01\", \"description\": \"开战不利…\", \"voicelineId\": 39070, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_life_less30_02\", \"description\": \"要正式接敌了…\", \"voicelineId\": 39071, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_life_less30_03\", \"description\": \"不赖嘛！\", \"voicelineId\": 39072, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_life_less30_teammate_01\", \"description\": \"退回去，都交给我！\", \"voicelineId\": 39073, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_life_less30_teammate_02\", \"description\": \"听我指挥，拉开间距！\", \"voicelineId\": 39074, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_life_die_01\", \"description\": \"狼狈的收场…\", \"voicelineId\": 39075, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_life_die_02\", \"description\": \"我还能…撑住…\", \"voicelineId\": 39076, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_life_die_03\", \"description\": \"罪人的结局吗…\", \"voicelineId\": 39077, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_hit_H_01\", \"description\": \"还不错！\", \"voicelineId\": 39078, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_eula/vo_eula_battle_hit_H_02\", \"description\": \"难得啊！\", \"voicelineId\": 39079, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_eula_teamJoin_01\", \"description\": \"游击骑士，率先行动。\", \"voicelineId\": 39080, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_eula_teamJoin_02\", \"description\": \"由我打前锋。\", \"voicelineId\": 39081, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_eula_teamJoin_03\", \"description\": \"行动计划敲定了吗？\", \"voicelineId\": 39082, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000052, 'Raiden Shogun', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_draw_appear\", \"description\": \"无须行礼，此身虽然尊贵殊胜，不过此般前来，是想要做些微服游历民间的事。我看上了你的身手，现在你就是我的御侧保镖了。不用担心，遇到危险，我会出手的。\", \"voicelineId\": 52009, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·徒然\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_character_idle_01\", \"description\": \"徒然无事，对砚枯坐。哼。\", \"voicelineId\": 52010, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·浮世\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_character_idle_02\", \"description\": \"浮世景色百千年依旧，人之在世却如白露与泡影。虚无。\", \"voicelineId\": 52011, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·花鸟余情\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_character_idle_03\", \"description\": \"无人相陪，此般花鸟余情，也不过衬托我身不移不变的背景罢了。\", \"voicelineId\": 52012, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_weather_heavyRain_01\", \"description\": \"只是雨滴有什么麻烦的。这还没有打雷呢。\", \"voicelineId\": 52013, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_weather_thunder_01\", \"description\": \"哎呀，你不会怕了吧。明明此世最为殊胜最为恐怖的雷霆化身就站在你身边。\", \"voicelineId\": 52014, \"voicelineType\": \"1202\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_weather_snowy_01\", \"description\": \"冬将军也来了。\", \"voicelineId\": 52015, \"voicelineType\": \"1203\"}, {\"title\": \"晴天的时候…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_weather_sunny_01\", \"description\": \"天晴也并不能掩盖雷霆的威光。不下雨也可以降下神雷，看到那棵树了吗？你说你懂了，叫我停手。好吧。\", \"voicelineId\": 52016, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_dialog_greetingMorning\", \"description\": \"道完早安就打呵欠，太懈怠了。我这次就赦免你的无礼了。早安。\", \"voicelineId\": 52017, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_dialog_greetingNoon\", \"description\": \"啊，想吃甜点心。嗯，为什么不行？什么叫「哪有这个时间吃甜品的」。之前是因为他们看我是将军所以惯着我的？这样啊。\", \"voicelineId\": 52018, \"voicelineType\": \"1002\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_dialog_greetingNight\", \"description\": \"你想知道夜晚流星的真相吗？哈哈，真相就是缥缈须臾的一瞬天光罢了。嗯，你说其实是你？你也是天狗吗？\", \"voicelineId\": 52019, \"voicelineType\": \"1003\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_dialog_greetingNight2\", \"description\": \"我命十方世界雷鸣平息，愿你今晚得享安睡。\", \"voicelineId\": 52020, \"voicelineType\": \"1004\"}, {\"title\": \"关于雷电将军自己·须臾\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_dialog_idle\", \"description\": \"雷鸣闪电，一瞬即逝。正因如此，才会想要撷取「永恒」。不，才必须掌握「永恒」。\", \"voicelineId\": 52021, \"voicelineType\": \"2001\"}, {\"title\": \"关于雷电将军自己·永恒\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_dialog_idle2\", \"description\": \"「磨损」是一件很可怕的事情。此身诞生的意义，就是承受磨损。这样，或许「内在」就可以触及永恒了吧。\", \"voicelineId\": 52022, \"voicelineType\": \"2005\"}, {\"title\": \"关于我们·奥诘众\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_dialog_close\", \"description\": \"现在你是我的侧用人，换言之，依我判断，你是对幕府有用，对我忠诚的人。\", \"voicelineId\": 52023, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·用心棒\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_dialog_close1\", \"description\": \"虽然是微服出访的保镖，但是我遇到危险不用替我挡刀了。将军她构造还挺结实的，坏了还能替换呢。所以遇到危险把将军她推到前面就好了。\", \"voicelineId\": 52024, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·直传\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_dialog_close2\", \"description\": \"稻妻的薙刀术和剑术以及锻刀技法，基本都是由我直接传下的，随后因人资质不同而分枝开花、各自结果。\\n如何，再接我一刀？还能无事的话，许可你在稻妻开宗立派哦。啊，武艺的精进真是叫人欲罢不能。\", \"voicelineId\": 52025, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_dialog_pendant\", \"description\": \"外面的世界居然已经这么久没有出现过雷元素的神之眼了吗？虽然我因为一些制约无法说明…赐予神之眼这件事，和我的意志无关。重要的，还是人的「渴望」，以及…\", \"voicelineId\": 52026, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_dialog_share_01\", \"description\": \"有什么想要分享的？没有。倒是你，为什么没有神之眼却能使用元素之力。和我说说。\", \"voicelineId\": 52027, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_pref_gift\", \"description\": \"虽然身消梦陨，但是她化作了神樱。这，也是「永恒」。\", \"voicelineId\": 52028, \"voicelineType\": \"3003\"}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_teammate_yaeMiko_01\", \"description\": \"那家伙啊，最初她就是个会被油豆腐引诱的家伙。现在居然这么工于谋略了，让人欣慰。不过被她算计了，还是有些不愉快。虽说是为了我好，下次见到她恐怕会被她嘲笑的…那就先发制人，斩她一刀好了。反正她也能躲掉。\", \"voicelineId\": 52029, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫人…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_teammate_ayato_01\", \"description\": \"神里一门，无愧于稻妻名门笔头之格。绫人虽然此前在三奉行事务中，耍了不少手段，但是本身忠心可鉴。既往不咎了。\", \"voicelineId\": 52030, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_teammate_ayaka_01\", \"description\": \"神里一门，无愧于稻妻名门笔头之格。欸，你说我和将军的评价一模一样。那，绫华她，她剑术也很好。\", \"voicelineId\": 52031, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_teammate_kujoSara_01\", \"description\": \"忠义之士，武艺精湛，可担「豪杰」二字。有此麟儿，九条家应该还能兴盛下去吧。\", \"voicelineId\": 52032, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_teammate_yoimiya_01\", \"description\": \"是谁来着？啊，做烟火的。制造须臾幻象的人，沉醉于夏日幻觉的人，虽说如此，亦为我之臣民。\\n嗯，在天领奉行属地里炸烟花？谁啊，她吗？\", \"voicelineId\": 52033, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于托马…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_teammate_thoma_01\", \"description\": \"虽然差点夺走他神之眼这件事，我也不能说是完全没有责任。但要说道歉的话，还是应该让将军她去比较好吧…好吧，我也会好好反省的。\", \"voicelineId\": 52034, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珊瑚宫心海…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_teammate_kokomi_01\", \"description\": \"奥罗巴斯确为此身所斩。但是我也许可了珊瑚宫之民，以海祇大御神之名继续祭祀，让它得享牲醴。现在珊瑚宫捣毁鸣神分社，反叛幕府。她作为海祇大御神的现人神巫女，必须要承担责任。\", \"voicelineId\": 52035, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于国崩…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_teammate_kunikuzushi_01\", \"description\": \"那小子是制造将军的副产物。对他不加以管束，应该是因为我内心还是觉得对他有所亏欠吧。\", \"voicelineId\": 52036, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_teammate_itto_01\", \"description\": \"谁？\", \"voicelineId\": 52037, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于摩拉克斯…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_teammate_zhongli_01\", \"description\": \"曾经与他共饮之时，我还只是一介影武者，敬陪众神末席。他做出了这样的选择是吗？不过，我想他在下一个时代，仍然会继续和更多的人相遇吧。\", \"voicelineId\": 52038, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温迪…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_teammate_venti_01\", \"description\": \"风神的化身现在还叫这个名字吗？说实话，第一次见他就感觉他浑身透着和我一定相处不来的气质。然后就是，他的确很能喝酒。\", \"voicelineId\": 52039, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于布耶尔…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_teammate_nahida_01\", \"description\": \"我很欣赏她的谦逊，谦逊也的确是智者的美德。她的权能理应可以做到许多超乎想象的事，但布耶尔只是将它用在「纠正与守护」之上…真是个温柔的神明。\", \"voicelineId\": 52083, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_teammate_furina_01\", \"description\": \"「雷电将军」曾与我在意识世界中进行数百年的决斗，以确定我的意志不曾动摇。而你所说的这位芙宁娜，虽是人类之躯，但五百年间的表演也无异于每时每刻都在进行精神上的「实战」。我认可她，此等意志，可谓已臻神境。\", \"voicelineId\": 52084, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}, {\"paramList\": [1204209], \"unlockText\": \"完成「须臾百梦」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于梦见月瑞希…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_teammate_mizuki_01\", \"description\": \"梦见月瑞希是神子的旧识，不过，我有些看不明白她们两位的关系…既是彼此无可替代的友人，又不愿将感情置于台面。总是为某些计划相持不下，想要决出高低…鉴于这些计划的核心都是帮助民众享受生活，我便不多说什么了。\", \"voicelineId\": 52086, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1204209], \"unlockText\": \"完成「须臾百梦」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解雷电将军·其一\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_friendship_01\", \"description\": \"有什么事情，说来便是。\", \"voicelineId\": 52040, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解雷电将军·其二\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_friendship_02\", \"description\": \"民间都相信，雷雨天口念「桑原桑原」，便可以无恙。如是因我一念而起的雷暴，必不会加害于你。但是自然天气形成的雷雨就难说了。\", \"voicelineId\": 52041, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解影·其三\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_friendship_03\", \"description\": \"《珍说》一书所言大致都是真的。那时她正忙于周旋岛内之事，于是我作为影武者，假托她名出现在了平定海祇的军阵中。但是后面的剧情，就只是人们的一厢情愿罢了。我原本只是醉心剑技的武人，没有那种感化万民的德行。\", \"voicelineId\": 52042, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解影·其四\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_friendship_04\", \"description\": \"追求「永恒」可能也只是一种逃避罢了。最后我采取的方法也和缩壳乌龟一样。不过乌龟本来就是长寿的象征，说不定追求永恒就是会变成这样的形态。\", \"voicelineId\": 52043, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解影·其五\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_friendship_05\", \"description\": \"恐惧是因为我在五百年前目睹了她的消亡和「那个事物」。但，如果…如果是你的话，一定可以拯救所有人的。如果是你的话，一定会拯救世界的。就像是我记得稻妻的一切一样，只要你记得我，我就能永远地活着。\", \"voicelineId\": 52044, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"雷电将军的爱好…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_pref_hobby\", \"description\": \"愚问。只有必须要做的事情，和一定不能做的事情。\", \"voicelineId\": 52045, \"voicelineType\": \"6001\"}, {\"title\": \"影的烦恼…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_dialog_annoyed\", \"description\": \"你不要让我做饭啦。我什么都能办到，但是真的不会做饭。\", \"voicelineId\": 52046, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_pref_foodLike\", \"description\": \"你别听将军她的。甜点心！蛀牙什么的，换一套就好了。这怎么会影响对永恒的追求呢。\", \"voicelineId\": 52047, \"voicelineType\": \"6003\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_pref_foodDislike\", \"description\": \"愚问。只有维持身体营养必须吃的，和会损害身体的。\", \"voicelineId\": 52048, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_spice_pref_01\", \"description\": \"熟悉的味道。不坏。\", \"voicelineId\": 52077, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_spice_normal_01\", \"description\": \"放在这里吧，我会尝的。\", \"voicelineId\": 52078, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_spice_dislike_01\", \"description\": \"会损害身体机能，拿走。\", \"voicelineId\": 52079, \"voicelineType\": \"6009\"}, {\"title\": \"收到赠礼·其四\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_spice_pref_01\", \"description\": \"好吃。心情也放松了不少，谢谢你。\", \"voicelineId\": 52080, \"voicelineType\": \"6010\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"收到赠礼·其五\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_spice_normal_01\", \"description\": \"看起来不错，是怎么做出来的？\", \"voicelineId\": 52081, \"voicelineType\": \"6011\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"收到赠礼·其六\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_spice_dislike_01\", \"description\": \"恕我谢绝。\", \"voicelineId\": 52082, \"voicelineType\": \"6012\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"生辰…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_pref_birthday_01\", \"description\": \"今日是你的生辰之日吗？随我回城，我来对全体旗本众宣读祝词吧。嗯？「太丢人别这样。」…好吧。\", \"voicelineId\": 52049, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_pref_birthday_02\", \"description\": \"生日快乐！那今日就一起庆祝吧，使之成为可以铭记一年的美好瞬间。然后等到来年今日，便继续庆祝。如是便可得「永恒」的快乐。\", \"voicelineId\": 52050, \"voicelineType\": \"7002\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_starUp_01\", \"description\": \"我之流派里，「初传」之位，可以学习太刀的九向剑路之势，以及薙刀术的基本。与其他流派并无大差异。应该说，其他流派与我之流派并无差异。\", \"voicelineId\": 52051, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_starUp_02\", \"description\": \"我之流派里，「中传」之位，太刀术需要研习各种「构」位与变化，薙刀术则需熟练诸「切」与「返」之理。\", \"voicelineId\": 52052, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenShogun_starUp_03\", \"description\": \"我之流派里，「皆传」之位，需要研习诸般奥义。无奈大部分都需要配合元素之力，对凡人来说可能有些太难了。世间其余流派大多都无法触及此境。\", \"voicelineId\": 52053, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_raidenShogun/vo_raidenEi_starUp_04\", \"description\": \"奥义中的奥义，也就是「无想」又无双的一刀。有你作为陪练之宾，我好像能挥出更强更快的一剑。\", \"voicelineId\": 52054, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_battle_skill1_01\", \"description\": \"威光无赦！\", \"voicelineId\": 52055, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_battle_skill1_02\", \"description\": \"无处遁逃！\", \"voicelineId\": 52056, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_battle_skill1_03\", \"description\": \"泡影看破！\", \"voicelineId\": 52057, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_battle_skill3_01\", \"description\": \"无念，断绝！\", \"voicelineId\": 52058, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_battle_skill3_02\", \"description\": \"此刻，寂灭之时！\", \"voicelineId\": 52059, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_battle_skill3_03\", \"description\": \"稻光，亦是永恒！\", \"voicelineId\": 52060, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_chest_open_01\", \"description\": \"收下吧，于我无用。\", \"voicelineId\": 52061, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_chest_open_02\", \"description\": \"…不过须臾之梦。\", \"voicelineId\": 52062, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_chest_open_03\", \"description\": \"嗯？\", \"voicelineId\": 52063, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_life_less30_01\", \"description\": \"…枷锁当断。\", \"voicelineId\": 52064, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_life_less30_02\", \"description\": \"…诸恶当斩。\", \"voicelineId\": 52065, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_life_less30_03\", \"description\": \"…肃清阻碍。\", \"voicelineId\": 52066, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_life_less30_teammate_01\", \"description\": \"至我后方待命。\", \"voicelineId\": 52067, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_life_less30_teammate_02\", \"description\": \"退下。\", \"voicelineId\": 52068, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_life_die_01\", \"description\": \"浮世一梦…\", \"voicelineId\": 52069, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_life_die_02\", \"description\": \"无念，无执…\", \"voicelineId\": 52070, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_life_die_03\", \"description\": \"雷鸣，将歇…\", \"voicelineId\": 52071, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_battle_hit_H_01\", \"description\": \"无礼…\", \"voicelineId\": 52072, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_raidenShogun/vo_raidenShogun_battle_hit_H_02\", \"description\": \"荒谬…\", \"voicelineId\": 52073, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_raidenShogun_teamJoin_01\", \"description\": \"有什么事？\", \"voicelineId\": 52074, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_raidenShogun_teamJoin_02\", \"description\": \"随我左右即可。\", \"voicelineId\": 52075, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_raidenShogun_teamJoin_03\", \"description\": \"出征之时已至。\", \"voicelineId\": 52076, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000053, 'Sayu', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_draw_appear\", \"description\": \"「终末番」早柚，参上。\\n呼——如果没有什么事情的话，我先去睡觉了。对了，不准趁我睡觉的时候偷偷摸我的头。\", \"voicelineId\": 53036, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·睡着\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_character_idle_01\", \"description\": \"呼啊…呼噜呼噜——\", \"voicelineId\": 53037, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·工作\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_character_idle_02\", \"description\": \"工作还不如睡觉。\", \"voicelineId\": 53038, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·长高\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_character_idle_03\", \"description\": \"什么时候才能长高呢？\", \"voicelineId\": 53039, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_weather_heavyRain_01\", \"description\": \"快躲雨，被雨淋到就长不高了。\", \"voicelineId\": 53040, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_weather_thunder_01\", \"description\": \"好大的动静，不过只要整个人都钻到被子里就能安稳睡觉了。\", \"voicelineId\": 53041, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_weather_snowy_01\", \"description\": \"雪天很方便躲藏。比如说「雪降之隐」这种忍术，借助飘雪隐去身形，等别人察觉的时候，对方的眼前就只剩下飘落的雪花了。啊，你千万不要把这些告诉巫女姐姐。\", \"voicelineId\": 53042, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_weather_sunny_01\", \"description\": \"舒舒服服的好天气，啊——好困哦。\", \"voicelineId\": 53043, \"voicelineType\": \"1204\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_weather_breezy_01\", \"description\": \"风起之时，便是开溜的好时机。\", \"voicelineId\": 53044, \"voicelineType\": \"1205\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_weather_gale_01\", \"description\": \"风吹得眼睛睁不开了，不如就这样，闭起眼睛睡一觉吧。\", \"voicelineId\": 53045, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_greetingMorning\", \"description\": \"已经…已经早上了吗？再睡10分钟…就10分钟嘛…那、那5分钟也行…呼…\", \"voicelineId\": 53046, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_greetingNoon\", \"description\": \"好困，午睡时间还没到吗？\", \"voicelineId\": 53047, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_greetingNight\", \"description\": \"确认完毕，方圆十里内没有巫女姐姐的踪影。今晚可以睡个好觉啦~\", \"voicelineId\": 53048, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_greetingNight2\", \"description\": \"终于…可以睡觉了…晚…晚安…\", \"voicelineId\": 53049, \"voicelineType\": \"1004\"}, {\"title\": \"关于早柚自己·终末番\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_idle\", \"description\": \"我虽然属于「终末番」，但交给我的工作无非就是些情报收集、偷取物品之类的琐事。所以…所以不做也没有什么关系嘛。\", \"voicelineId\": 53050, \"voicelineType\": \"2001\"}, {\"title\": \"关于早柚自己·旷工\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_idle2\", \"description\": \"「终末番」的工作本来就没什么意义嘛，一直拖着不做，就会有更合适的人去做。但是睡觉不一样啊，只要睡得够久，说不定哪天就能长高了，这可是意义非凡的。\", \"voicelineId\": 53051, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·帮个忙\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_close\", \"description\": \"如果巫女姐姐来了，记得告诉我一声哦，我稍微睡…啊不，休息会儿。\", \"voicelineId\": 53052, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·摸摸头\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_close1\", \"description\": \"摸摸头？唔，如果是你的话...那好吧，我不会咬你的，但是不能摸太久了，否则会长不高的！\", \"voicelineId\": 53053, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_pendant\", \"description\": \"双手剑真的很重，光靠忍术的话，我肯定举不起来。但是有了「神之眼」就不一样了，所以不管怎么说，「神之眼」对我帮助很大。\", \"voicelineId\": 53054, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_share_01\", \"description\": \"老师说我是我们流派最后一代传人了。毕竟也不是什么特别适合战斗的流派，我学的也都是些逃跑和隐蔽气息用的忍术，这也是没办法的事情吧…\", \"voicelineId\": 53055, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_pref_gift\", \"description\": \"你知道貉吗？一种比狸猫可爱得多的小动物，下次带你一起去看看吧~\", \"voicelineId\": 53056, \"voicelineType\": \"3003\"}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_teammate_ayaka_01\", \"description\": \"神里家的大小姐优雅又端庄，但是她专门任命了一位巫女姐姐来监督我，不让我偷懒…怎会如此…\", \"voicelineId\": 53057, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫人…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_teammate_ayato_01\", \"description\": \"我在树上休息的时候，经常会听到巫女姐姐们在聊他，似乎是一位工作很忙的大人。真是奇怪，工作什么的明明旷掉就好了…\", \"voicelineId\": 53058, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于托马…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_teammate_thoma_01\", \"description\": \"明明都有神之眼了，他每次出现还是缠着我说想要学忍术，真是搞不懂。而且我睡觉的时间都不够，哪有时间教他嘛。\", \"voicelineId\": 53059, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_teammate_yoimiya_01\", \"description\": \"她每次碰到我就说什么，小狸猫我们一起去祭典玩之类的话。我才不是狸猫，也不想去祭典。说是一起去玩，其实就是想着在祭典上让我配合她的烟火表演忍术，但是这和「终末番」的工作有什么关联嘛！\", \"voicelineId\": 53060, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_teammate_raidenShogun_01\", \"description\": \"那位大人…不是我能见到的人物。想知道更多事情的话，或许问问绫华大小姐比较好。\", \"voicelineId\": 53061, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_teammate_yaeMiko_01\", \"description\": \"她总喜欢摸我的头，可是我不敢咬她，也不敢反抗，总感觉如果拒绝了她会发生很可怕的事情。但是，再这样被摸下去，我会不会真的长不高了？怎么办呀…\", \"voicelineId\": 53062, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_teammate_itto_01\", \"description\": \"怎么会有这么吵吵嚷嚷的人，而且他还能长这么高！\", \"voicelineId\": 53063, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于久岐忍…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_teammate_oniori_01\", \"description\": \"没什么印象的名字，让我想想…欸？她是荒泷一斗的小弟吗？那肯定也是干扰睡眠的人，毕竟有个词叫做一丘之貉，啊不对，是一丘之狸！\", \"voicelineId\": 53064, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绮良良…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_teammate_kirara_01\", \"description\": \"有次我午觉睡醒，感觉身后暖和和的，一转头就看见有只猫正蜷着睡觉，关键是有一对毛茸茸的尾巴！吓得我差点从树枝上掉下去。这，这也是变身术吗？\", \"voicelineId\": 53084, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于梦见月瑞希…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_teammate_mizuki_01\", \"description\": \"奇怪的紫色妖怪…被她盯着的时候，感觉好像要被吃掉一样…唔！惹不起，我还是躲着她走吧！\", \"voicelineId\": 53005, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解早柚·其一\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_friendship_01\", \"description\": \"呼——\", \"voicelineId\": 53065, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解早柚·其二\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_friendship_02\", \"description\": \"呃…你是问我忍术流派的名字吗？那个…想不起来了啦，我还没睡醒，我再去睡一觉，睡醒后说不定就能想起来了。\", \"voicelineId\": 53066, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解早柚·其三\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_friendship_03\", \"description\": \"好吧，告诉你也行。你先答应我不准笑，不然我就再也不理你了。我们流派叫做——呜呼流…\\n说是因为我们流派的忍术以戏弄敌人为长而取的名字，可是，可是…唉。\", \"voicelineId\": 53067, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解早柚·其四\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_friendship_04\", \"description\": \"你会爬树吗？我非常擅长这个，可以教你哦。还有，神社那边有棵树特别适合偷…啊不，特别适合小憩。下次你想睡午觉的时候，记得来找我，我们一起爬上去午睡吧。\", \"voicelineId\": 53068, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解早柚·其五\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_friendship_05\", \"description\": \"其实这套衣服是老师给我的，说是以貉为原型做的，还有助于我逃跑什么的…然后又说我已经长大了可以独当一面了，但也要保护好自己，说完老师就离开了我。可我这个身高，真的能独当一面吗…\\n唔…欸？你是说你会陪着我吗？你真的不会离开我吗？\", \"voicelineId\": 53069, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"早柚的爱好…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_pref_hobby\", \"description\": \"套上衣服上的帽子，不用担心会被巫女姐姐找到，然后睡个天昏地暗，这应该是世界上最幸福的事情了吧。\", \"voicelineId\": 53070, \"voicelineType\": \"6001\"}, {\"title\": \"早柚的烦恼·误会\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_annoyed_01\", \"description\": \"很多人第一次见到我的时候，都会大呼小叫，还把我当成狸猫。可早柚就是早柚，才不是狸猫。\", \"voicelineId\": 53071, \"voicelineType\": \"6002\"}, {\"title\": \"早柚的烦恼·身高\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_annoyed_02\", \"description\": \"什么时候才能长高呢？跟我同年的人身高都快是我的两倍了，可我还…不行，再睡久一点一定能长高的！我要睡觉了，晚安。\", \"voicelineId\": 53072, \"voicelineType\": \"6005\"}, {\"title\": \"早柚的烦恼·死循环\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_dialog_annoyed_03\", \"description\": \"我上次听人说，烦恼太多也会长不高…呜，我该怎么办才好…\", \"voicelineId\": 53073, \"voicelineType\": \"6006\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_pref_foodLike\", \"description\": \"能一下子提供很多能量的食物吧，比如说饭团。睡醒了吃一个就不会头晕眼花，然后又能继续睡觉了。\", \"voicelineId\": 53074, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_pref_foodDislike\", \"description\": \"想要长高的话，就不能挑食！说来最近好像身高也没有变化，是不是因为蔬菜吃少了，但是沙拉真的没有办法提供饱腹感，而且还苦苦的，呜欸——\", \"voicelineId\": 53075, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_spice_pref_01\", \"description\": \"肚子好饱。这下可以安心睡觉啦。\", \"voicelineId\": 53081, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_spice_normal_01\", \"description\": \"吃着吃着…就困了。\", \"voicelineId\": 53082, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_spice_dislike_01\", \"description\": \"要想个办法…逃走。\", \"voicelineId\": 53083, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_pref_birthday\", \"description\": \"你有什么想学的忍术吗？我可以教你！当然仅限于我会的。呃？你问我为什么不睡觉？嗯…我还不困，而且，而且今天是特别的日子，我不可以睡过去，因为我想亲口对你说——生日快乐呀。\", \"voicelineId\": 53076, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_starUp_01\", \"description\": \"我有长高一点点吗？\", \"voicelineId\": 53077, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_starUp_02\", \"description\": \"太好了，能溜得更快了，这下子肯定不会被抓住了。\", \"voicelineId\": 53078, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_starUp_03\", \"description\": \"谢谢你帮我收集了那么多材料，要是我自己来的话…肯定在路上就会睡着了。\", \"voicelineId\": 53079, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_sayu/vo_sayu_starUp_04\", \"description\": \"我好像确实像老师说的那样，可以独当一面了。这样子长不长高或许对我来说也没有那么重要了，因为现在重要的是…有你陪在我身边。\", \"voicelineId\": 53080, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_skill1_01\", \"description\": \"走啦…唔。\", \"voicelineId\": 53009, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_skill1_02\", \"description\": \"溜咯…啊。\", \"voicelineId\": 53010, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_skill1_03\", \"description\": \"咕噜，哈！…嘿呀。\", \"voicelineId\": 53011, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_skill1_04\", \"description\": \"极意遁走。\", \"voicelineId\": 53012, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_skill1_05\", \"description\": \"抓不住我…呜。\", \"voicelineId\": 53013, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_skill1_06\", \"description\": \"随风而遁…呜。\", \"voicelineId\": 53014, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_skill3_01\", \"description\": \"分身之术。\", \"voicelineId\": 53015, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_skill3_02\", \"description\": \"出来吧！\", \"voicelineId\": 53016, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_skill3_03\", \"description\": \"嘿咻…呜。\", \"voicelineId\": 53017, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_explore_sprint_start_01\", \"description\": \"疾风遁术。\", \"voicelineId\": 53018, \"voicelineType\": \"700001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_chest_open_01\", \"description\": \"这个箱子…好像可以睡进去。\", \"voicelineId\": 53019, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_chest_open_02\", \"description\": \"大丰收！可以睡觉了吗？\", \"voicelineId\": 53020, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_chest_open_03\", \"description\": \"是对长高有帮助的东西吗？\", \"voicelineId\": 53021, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_life_less30_01\", \"description\": \"逃跑的话，该用…\", \"voicelineId\": 53022, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_life_less30_02\", \"description\": \"头晕乎乎的。\", \"voicelineId\": 53023, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_life_less30_03\", \"description\": \"呼，好累。\", \"voicelineId\": 53024, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_life_less30_teammate_01\", \"description\": \"我来掩护。\", \"voicelineId\": 53025, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_life_less30_teammate_02\", \"description\": \"先退下休息。\", \"voicelineId\": 53026, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_life_die_01\", \"description\": \"没能...逃掉...\", \"voicelineId\": 53027, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_life_die_02\", \"description\": \"…晚、晚安了…\", \"voicelineId\": 53028, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_life_die_03\", \"description\": \"不该偷懒的…\", \"voicelineId\": 53029, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_hit_L_01\", \"description\": \"痛。\", \"voicelineId\": 53030, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_hit_H_01\", \"description\": \"没躲开。\", \"voicelineId\": 53031, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_sayu/vo_sayu_battle_hit_H_02\", \"description\": \"呜，要晕倒了。\", \"voicelineId\": 53032, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_sayu_teamJoin_01\", \"description\": \"好困。\", \"voicelineId\": 53033, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_sayu_teamJoin_02\", \"description\": \"可以睡觉吗？\", \"voicelineId\": 53034, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_sayu_teamJoin_03\", \"description\": \"呜，居然被抓住了。\", \"voicelineId\": 53035, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000054, 'Sangonomiya Kokomi', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_draw_appear\", \"description\": \"我是珊瑚宫心海，海祇岛的「现人神巫女」。此次与你一起出行，就当做是放松一下…咳，就当做是对外考察吧。不用担心，临行前我留下了不少锦囊，将海祇岛近期的发展计划布置完毕了。稍微离开一会儿，也没有关系。\", \"voicelineId\": 54012, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·阅读\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_character_idle_01\", \"description\": \"八重堂出版的许多作品，深入浅出地阐明了兵法原理，我很喜欢。\", \"voicelineId\": 54009, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·游鱼\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_character_idle_02\", \"description\": \"每个生灵的意志都值得尊重，就像海中的游鱼，也有自己的方向。\", \"voicelineId\": 54010, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·准备\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_character_idle_03\", \"description\": \"未雨绸缪，才能临危不乱。\", \"voicelineId\": 54011, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_weather_heavyRain_01\", \"description\": \"雨中行军，可以隐蔽声息，但对体能却是很大的考验…\", \"voicelineId\": 54013, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_weather_snowy_01\", \"description\": \"雪…真漂亮呀。\", \"voicelineId\": 54014, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_weather_sunny_01\", \"description\": \"天色真好，一起走走吧？\", \"voicelineId\": 54015, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_weather_gale_01\", \"description\": \"嗯…这么大的风，正适合用火攻之计。\", \"voicelineId\": 54016, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_greetingMorning\", \"description\": \"早安。我刚刚读到一段有趣的兵法，要一起研究一下吗？\", \"voicelineId\": 54017, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_greetingNoon\", \"description\": \"下午的作战方案要进行一些修正，这样可以保证更高的效率。\", \"voicelineId\": 54018, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_greetingNight\", \"description\": \"嗯？这么快就到晚上了？跟你在一起，时间总是会过得格外快。\", \"voicelineId\": 54019, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_greetingNight2\", \"description\": \"好好休息，养精蓄锐。晚安。\", \"voicelineId\": 54020, \"voicelineType\": \"1004\"}, {\"title\": \"关于珊瑚宫心海自己·锦囊\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_idle\", \"description\": \"战场局势千变万化，一念之差就可能葬送全局。所以在开战前，我会将所有情况纳入考量，写成锦囊交给将士们去执行。不过目前来看，他们对锦囊有些过于依赖了。我还是希望他们多读些兵书，靠自己的力量辨析战场的局势，这样才能更好地抓住战机。\", \"voicelineId\": 54021, \"voicelineType\": \"2001\"}, {\"title\": \"关于珊瑚宫心海自己·放松\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_idle2\", \"description\": \"真希望这次作战快点结束。八重堂出版的新印《沉秋拾剑录》已经可以买到了，好想呆在房间里一口气看完…\", \"voicelineId\": 54022, \"voicelineType\": \"2005\"}, {\"title\": \"关于我们·见闻\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_close\", \"description\": \"母亲曾教导过我，只有眼界开阔，才能成为合格的领袖。不过以前的我常年往返于珊瑚宫与军队之间，不曾亲自出来冒险，难免会有许多不懂的地方。嗯，这些就请你多担待啦。\", \"voicelineId\": 54023, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·困惑\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_close1\", \"description\": \"都说人心难测，但作为现人神巫女，我必须努力去理解每个人的想法才行。就从你开始吧，旅行者，让我猜猜…你现在在想些什么呢？\", \"voicelineId\": 54024, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_pendant\", \"description\": \"在我眼中，「神之眼」便是愿望的象征。我们之所以成立反抗军，反对眼狩令，就是因为愿望是非常宝贵的东西，不该被轻易放弃，更不该被强行剥夺。\", \"voicelineId\": 54025, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·刊物\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_share_01\", \"description\": \"八重堂出版的刊物中，我尤其喜欢这本《提瓦特战争艺术》。你看，上面记录了许多经典战役，以及兵法名家对此的解析。其中有几篇我特别欣赏，让我来念给你听…\", \"voicelineId\": 54026, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·潜水\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_share_02\", \"description\": \"水下的世界虽不如陆地上明亮，但每次呆在那里时，心都会慢慢沉静下来。鱼群在远处游动，水母在身旁起舞，让人不知不觉就会放下所有烦恼。有机会的话，我带你去看看吧？\", \"voicelineId\": 54027, \"voicelineType\": \"3004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_pref_gift\", \"description\": \"我很喜欢海祇珊瑚真珠，它为海祇岛带来了许多财富，是大海给予我们的馈赠。\", \"voicelineId\": 54028, \"voicelineType\": \"3003\"}, {\"title\": \"关于五郎…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_teammate_gorou_01\", \"description\": \"五郎是不可多得的优秀将领。他真诚、坚毅、果敢…能够与部下同食同寝，也能够提出许多出人意料的作战方案。但他也有一个小小的缺点，就是在战斗中容易亢奋上头。如果你和他一起行动的话，一定要在关键时候拉住他。\", \"voicelineId\": 54029, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_teammate_kujoSara_01\", \"description\": \"不得不承认，九条裟罗是一个难缠的对手。虽然她很少使用计策与谋略，但她在正面战场做得很好。幕府军对她非常信服，在她的带领下团结一致、悍不畏死，曾经几度给反抗军带来了巨大的威胁。\", \"voicelineId\": 54030, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_teammate_yaeMiko_01\", \"description\": \"八重宫司的许多事迹，我也有听说过。平心而论，我认为她是一位非常优秀的巫女，至少在「巫女」的本职上，她做到了无可挑剔的程度。听说她还负责八重堂轻小说出版事宜，真是个难以捉摸的人…\", \"voicelineId\": 54031, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_teammate_raidenShogun_01\", \"description\": \"眼狩令结束之后，海祇岛也回归了正常的生活。时至今日，我已经不想去评判将军的对错，我更在意的是海祇岛的未来。我希望将军能够信守承诺，我们与幕府相安无事。但若是有一天，将军再次无视民众的愿望，那我们也绝不会坐视不管。\", \"voicelineId\": 54032, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_teammate_beidou_01\", \"description\": \"当时与北斗一同伏击幕府军的时候，我也曾提出过「担心幕府军事先察觉」的担忧。不过北斗对我说，她的船队令行禁止，能够悄无声息地发动奇袭，事实证明果然如此。如今我们海祇岛的船队在训练时遇到了瓶颈，我倒真想请她来指导一番…\", \"voicelineId\": 54033, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_teammate_kazuha_01\", \"description\": \"万叶曾在反抗军待过一段时间。印象里，他跟五郎的关系很好，两个人经常并肩作战。万叶性格洒脱，不喜欢被约束，但身处军队的时候，他又会严格遵守各项纪律。在我看来，他不仅剑术高超，性格也非常成熟。\", \"voicelineId\": 54034, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鹿野院平藏…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_teammate_heizou_01\", \"description\": \"刚开始的时候，我非常诧异有人公开穿着天领奉行的制服来海祇岛。如果他是天领奉行的武士，就不该这么鲁莽；如果他是天领奉行的间谍，又不该这么招摇。不过接触过一段时间之后，我发现这位自称是「侦探」的鹿野院先生，对海祇岛的军事布防、政务商贸都不感兴趣，倒像是来旅游的。所以我只是加派了一些人手盯着他，并没有赶他离开。如果你见到他的话，倒是可以跟他聊上几句。\", \"voicelineId\": 54035, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于梦见月瑞希…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_teammate_mizuki_01\", \"description\": \"瑞希小姐的能力与才艺有目共睹。我曾想请她出任顾问，协力我一同发展海祇岛的各式文化项目。但几次交谈过后，我便明白，瑞希小姐的目光放眼在整个稻妻。我期待能够早日见证她的成就。如有任何需要，海祇岛也随时欢迎她的到来。\", \"voicelineId\": 54077, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解珊瑚宫心海·其一\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_friendship_01\", \"description\": \"越是情况紧迫，越要稳住心态。如果连我也陷入不安的话，其他人要怎么办呢？\", \"voicelineId\": 54036, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解珊瑚宫心海·其二\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_friendship_02\", \"description\": \"据说我们的祖先曾经生活在海底的渊下宫，是魔神奥罗巴斯将他们带到了地面上。我常常会猜想，海底的宫殿会不会很黑呢？每次想到这里，我就会倍加珍惜眼前的光亮。\", \"voicelineId\": 54037, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解珊瑚宫心海·其三\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_friendship_03\", \"description\": \"剑鱼二番队的士兵们，在你离开后也推选出了临时队长，但大家还是希望你能回去。我也只能跟他们说，你有一个重要的任务要独自完成，暂时没办法回来。有机会的话，你可以去看看他们，他们想必会很欢迎你的。\", \"voicelineId\": 54038, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解珊瑚宫心海·其四\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_friendship_04\", \"description\": \"其实很早以前，我并不想成为现人神巫女，只想每天读读兵书，做一个幕僚。这样就可以把自己隐藏在幕后，身上的担子也会减轻不少。不过最后还是事与愿违，毕竟血脉这种东西，是没办法违抗的…\", \"voicelineId\": 54039, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解珊瑚宫心海·其五\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_friendship_05\", \"description\": \"成为现人神巫女之后，我也慢慢习惯了这样的生活。起码当我看到不合理的事情时，我有力量去改变它。更重要的是，我因此和你相遇了不是吗？\", \"voicelineId\": 54040, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"珊瑚宫心海的爱好…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_pref_hobby_01\", \"description\": \"喜欢的事情？我想要找一个安静的地方读兵书，读一天都不会有人来打扰的那种。如果你想跟我一起研究兵法的话，我也是很欢迎的。不过…你得睡地板。\", \"voicelineId\": 54041, \"voicelineType\": \"6001\"}, {\"title\": \"珊瑚宫心海的烦恼…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_dialog_annoyed\", \"description\": \"我其实，并不擅长与人交流。虽然也可以端起「现人神巫女」的架子来应付，但对我来说，这是一件很消耗能量的事情。一旦能量用尽，我也会露出消极的一面。那种形象肯定不能被外人看到啦，民众需要的是一个完美的海祇岛领袖，而不是一个喜欢宅在家里的小姑娘。\", \"voicelineId\": 54042, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [1202405], \"unlockText\": \"完成「兵戈梦去，春草如茵」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_pref_foodLike\", \"description\": \"鸟蛋寿司，是我很喜欢的一道料理。它材料常见、做法简单，很适合在军中普及。虽然在战事激烈的时候，吃上一顿鸟蛋寿司也是一种奢侈，但绝大部分时间里，这种朴素的料理能给士兵们带来许多满足。\", \"voicelineId\": 54043, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_pref_foodDislike\", \"description\": \"嗯…非要说的话，我不太喜欢跟鱼有关的料理。不过这个还请你帮我保密啦，渔业在海祇岛的占比很重，如果让民众知道我不喜欢鱼料理的话，他们说不定会有一些奇怪的担心。\", \"voicelineId\": 54044, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_spice_pref_01\", \"description\": \"嗯，真好吃！能量似乎也…不、没什么…\", \"voicelineId\": 54074, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_spice_normal_01\", \"description\": \"分几口慢慢吃的话，幸福感也会持续得更久吧。\", \"voicelineId\": 54075, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_spice_dislike_01\", \"description\": \"嗯，你给我出了一个难题呢。\", \"voicelineId\": 54076, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_pref_birthday\", \"description\": \"生日快乐！今天有什么安排了吗？没有的话，我们一起在海祇岛庆祝吧。早晨我带你去看日出，白天一起去潜水，晚上的时候在珊瑚宫散步。如果下雨的话，我们就找个地方读兵书，然后一起去尝试做蛋糕。总之今天你不用多想，交给我这个「军师」来安排就好啦。\", \"voicelineId\": 54045, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_starUp_01\", \"description\": \"我虽然并不崇尚武力，但能够变强是一件好事。\", \"voicelineId\": 54046, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_starUp_02\", \"description\": \"力量在不断地涌出…想必下次作战，我们可以配合得更好。\", \"voicelineId\": 54047, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_starUp_03\", \"description\": \"沧海月明，潮起潮落。力量更进一步，心境也会有所不同。\", \"voicelineId\": 54048, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_kokomi/vo_kokomi_starUp_04\", \"description\": \"曾经，我也时常会陷入自我怀疑之中。像我这样的人，真的可以胜任现人神巫女的职位吗？不过现在，我已经很少再去想这些了。与你在一起的时候，任何困难都可以迎刃而解。\", \"voicelineId\": 54049, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_battle_skill1_01\", \"description\": \"帮帮忙！\", \"voicelineId\": 54050, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_battle_skill1_02\", \"description\": \"别担心。\", \"voicelineId\": 54051, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_battle_skill1_03\", \"description\": \"休养生息。\", \"voicelineId\": 54052, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_battle_skill3_01\", \"description\": \"沧海之约。\", \"voicelineId\": 54053, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_battle_skill3_02\", \"description\": \"翻涌吧！\", \"voicelineId\": 54054, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_battle_skill3_03\", \"description\": \"深海的加护！\", \"voicelineId\": 54055, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_explore_sprint_start_01\", \"description\": \"我们走吧。\", \"voicelineId\": 54056, \"voicelineType\": \"700001\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_explore_fly_start_01\", \"description\": \"风景真好。\", \"voicelineId\": 54057, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_chest_open_01\", \"description\": \"补给可是头等要事。\", \"voicelineId\": 54058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_chest_open_02\", \"description\": \"要好好规划一下如何使用。\", \"voicelineId\": 54059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_chest_open_03\", \"description\": \"嗯，这就是冒险的乐趣…\", \"voicelineId\": 54060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_life_less30_01\", \"description\": \"好累…\", \"voicelineId\": 54061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_life_less30_02\", \"description\": \"需要变更战术。\", \"voicelineId\": 54062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_life_less30_03\", \"description\": \"谨慎为上。\", \"voicelineId\": 54063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_life_less30_teammate_01\", \"description\": \"援军已至！\", \"voicelineId\": 54064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_life_less30_teammate_02\", \"description\": \"请到后方休息。\", \"voicelineId\": 54065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_life_die_01\", \"description\": \"计策…出问题了吗？\", \"voicelineId\": 54066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_life_die_02\", \"description\": \"失误了…\", \"voicelineId\": 54067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_life_die_03\", \"description\": \"不会再犯同样的错误。\", \"voicelineId\": 54068, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_battle_hit_H_01\", \"description\": \"失策！\", \"voicelineId\": 54069, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_kokomi/vo_kokomi_battle_hit_H_02\", \"description\": \"真难缠…\", \"voicelineId\": 54070, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_kokomi_teamJoin_01\", \"description\": \"这次的作战…让我想想。\", \"voicelineId\": 54071, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_kokomi_teamJoin_02\", \"description\": \"别紧张，我们一定会赢。\", \"voicelineId\": 54072, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_kokomi_teamJoin_03\", \"description\": \"万事俱备，出发吧。\", \"voicelineId\": 54073, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000055, 'Gorou', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_draw_appear\", \"description\": \"海祇岛反抗军大将，五郎，前来助阵！早就听说过你的威名了，我将与你齐驱并进，一同攻夺胜利！哈哈，怎么样，我刚刚这句话的气势，还不错吧？\", \"voicelineId\": 55000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·军略\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_character_idle_01\", \"description\": \"枕戈坐甲，才能应对变数。\", \"voicelineId\": 55001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·训练\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_character_idle_02\", \"description\": \"难得没有战事，来场体能训练吧！\", \"voicelineId\": 55002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·体格\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_character_idle_03\", \"description\": \"魁梧的体格是力量的象征，对鼓舞士气也很有帮助。我得再加把劲啊！\", \"voicelineId\": 55003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_weather_heavyRain_01\", \"description\": \"尾巴湿了…找堆篝火烤一烤吧。\", \"voicelineId\": 55004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_weather_thunder_01\", \"description\": \"有敌情吗！\", \"voicelineId\": 55005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_weather_snowy_01\", \"description\": \"好冷…这种天气不适合露天活动啊…\", \"voicelineId\": 55006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_weather_sunny_01\", \"description\": \"晒太阳虽好，士气却不能松懈啊。\", \"voicelineId\": 55007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_weather_gale_01\", \"description\": \"顺风进攻，我方占优。逆风作战，也不必畏惧！\", \"voicelineId\": 55008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_greetingMorning\", \"description\": \"晨练时间到了，要和我一起去登山吗？\", \"voicelineId\": 55009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_greetingNoon\", \"description\": \"午饭就吃鲜鱼炖萝卜和白米饭吧。这种搭配在反抗军中很流行，推荐你也试一试。\", \"voicelineId\": 55010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_greetingNight\", \"description\": \"晚上也不能怠懈，要让眼睛充分适应黑暗。毕竟，黑灯瞎火的地方，也有可能变成战场。\", \"voicelineId\": 55011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_greetingNight2\", \"description\": \"累了吗？那就安心休息吧。待在这里放哨的任务就交给我了！保证你回来的时候，一切都跟现在一模一样。\", \"voicelineId\": 55012, \"voicelineType\": \"1004\"}, {\"title\": \"关于五郎自己·大哥\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_idle\", \"description\": \"「五郎大哥」？你是从哪里听到的啊！唉…实不相瞒。平时，我和将士们的交流都很密切，有什么好东西也都大家一起分享。他们敬重我，私底下就大哥大哥地叫了起来。可实际上，他们的年纪都比我大啊…\", \"voicelineId\": 55013, \"voicelineType\": \"2001\"}, {\"title\": \"关于五郎自己·建议\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_idle2\", \"description\": \"大概因为我总是打胜仗吧，总感觉将士们把我想象成了特别厉害的人，哪怕是小事也会来问我的建议。他们的眼神让我没法拒绝，但我的计策也有限…只能讲些大道理，或是凭直觉给出答案了。唉，会不会对不起他们呢…\", \"voicelineId\": 55014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·倾诉\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_close\", \"description\": \"有什么烦恼，千万不要埋在心里，来和我说说吧。虽然我不是什么事情都在行，但我一定会尽力为你出谋划策的。就算…就算答案不够可靠，至少我也是你忠实的听众。\", \"voicelineId\": 55015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·同食同寝\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_close1\", \"description\": \"一起训练，一起吃饭，一起休息…方便随时交流，还能增进我们之间的默契。到了关键时刻，一个眼神就能传递重要的信息…欸？这样不合适吗？唔…我和其他兄弟都是这样熟悉起来的啊。\", \"voicelineId\": 55016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_pendant\", \"description\": \"「神之眼」为我的战斗提供了许多帮助，让我能在战场上承担更多责任，为战友们开辟道路。但我也明白，个人的力量再强，都没法左右战争的胜负。大家齐心协力才是关键。\", \"voicelineId\": 55017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·轻装上阵\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_share_01\", \"description\": \"轻装上阵正是我的风格。我擅长灵活游走，寻找战机。我的箭矢会优先对准敌方最强的将士，挫伤对方的锐气。\", \"voicelineId\": 55018, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·常胜将军\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_share_02\", \"description\": \"将士们给我取了个绰号，叫「常胜的尖耳将军」，还有些奇怪的传闻，说是「摸到五郎大哥的耳朵，就能获得常胜将军的好运」。唔…摸是绝对不行的！他们笑得再开心也不行！欸？你也想摸？喂，喂…\", \"voicelineId\": 55019, \"voicelineType\": \"3004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_pref_gift_01\", \"description\": \"听说璃月有着高耸入云的群山，真想亲眼去看看，再尽情攀登一番。\", \"voicelineId\": 55020, \"voicelineType\": \"3003\"}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_teammate_beidou_01\", \"description\": \"北斗船长重视情义、身手不凡，令人尊敬。她曾说不愿把同伴卷入纷争，我们也理解这一点。因此，只有到了必要的时候，才会请她来帮忙。\", \"voicelineId\": 55021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_teammate_kazuha_01\", \"description\": \"我见过形形色色的浮浪人，万叶绝对是他们之中最特殊的一位。他就像一缕风，不会在任何地方停留，但总能给身边人带来些什么。和他并肩战斗期间，我就从他身上学会了几分「洒脱」。总之，我和万叶相当合拍！\", \"voicelineId\": 55022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珊瑚宫心海·职责\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_teammate_kokomi_01\", \"description\": \"珊瑚宫大人作为海祇岛最高领袖，负责掌控大局，制定计划。我负责将细节落实，把控前线的形势。反抗军上下一心，只求胜利。\", \"voicelineId\": 55023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珊瑚宫心海·态度\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_teammate_kokomi_02\", \"description\": \"我对珊瑚宫大人抱有崇高的敬意。珊瑚宫大人神机妙算，没有她的谋略和统筹，反抗军不可能取得如今的战果。只不过，私底下她似乎更偏好安静的生活。没有军事要务的话，我不会主动打搅她。\", \"voicelineId\": 55024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_teammate_raidenShogun_01\", \"description\": \"雷电将军…不论理由如何，我无法认同她以前的做法。现在，海祇岛与幕府签订了和平条约，但我绝不会放松警惕。假如冲突再次爆发，我必定会重返前线。\", \"voicelineId\": 55025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_teammate_kujouSara_01\", \"description\": \"我对幕府军没有好感，但九条裟罗，也许是幕府军里最正直的一位将领了。我们之间进行过数次较量，各有胜负。我曾不成熟地想过，要是这样的人能够重视民众的愿望，不受幕府掌控就好了。\", \"voicelineId\": 55026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_teammate_yaeMiko_01\", \"description\": \"那个女人…我们可以不聊她吗？我来帮你干活，什么杂活都没有问题…呜…就当是为了我的身心健康着想，我们还是换个话题吧？\", \"voicelineId\": 55027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_teammate_ayaka_01\", \"description\": \"社奉行从属于幕府，但立场更倾向于民众。在这种两面为难的处境下，「白鹭公主」还能站稳脚跟，应该是特别冷静，又能把握做事分寸的人吧。这一点值得我学习。\", \"voicelineId\": 55028, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于早柚…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_teammate_sayu_01\", \"description\": \"我军情报显示，那位忍者精通潜入之法，也许她的忍术能够在珊瑚宫大人的某些奇策中发挥作用…不过，情报里又说很难掌握她的行踪，看来不好招募啊…欸？你说她是社奉行的人？…呃，那还是算了。\", \"voicelineId\": 55029, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鹿野院平藏…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_teammate_heizou_01\", \"description\": \"你说那个鬼鬼祟祟，游手好闲的侦探先生？毕竟是来自幕府的家伙，没办法完全信任，我会继续盯紧他的。说起来，他倒是有那么点探案的功夫。至于这是不是什么阴谋诡计…嗯，就得用时间来证明了。\", \"voicelineId\": 55030, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解五郎·其一\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_friendship_01\", \"description\": \"毕竟我大多时间都在战场上，我的故事，可能不算很有趣…但如果你想听的话，我就慢慢和你说，想到什么说什么。\", \"voicelineId\": 55031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解五郎·其二\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_friendship_02\", \"description\": \"我没有令人敬畏的智谋，只有一双手和一条命。也许我的手足够有力，命足够硬吧，这么多年来，经历了不知多少场恶战，都成功活了下来。有人说，只要跟着我，不管遇上多绝望的战局，都能平安无事。就这样，不知不觉，我得到了大家的认可，成为了将领。\", \"voicelineId\": 55032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解五郎·其三\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_friendship_03\", \"description\": \"最初，我们的敌人是流寇、海贼和魔物，但后来，雷电将军颁布了「眼狩令」。气焰嚣张的幕府军来到了我们的面前，被我们迎头痛击。哈哈，大概他们也没想到，会遭受如此激烈的抵抗吧。\", \"voicelineId\": 55033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解五郎·其四\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_friendship_04\", \"description\": \"珊瑚宫大人曾经说过，我有个致命的弱点，战斗的时候太过忘我，只顾着深入敌阵。她说勇猛是好事，但对于统率一军的将领而言，这样并不称职。我…努力在改进这一点！你…能够在我身边，监督我吗？\", \"voicelineId\": 55034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解五郎·其五\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_friendship_05\", \"description\": \"我需要抗争到底的对象，并非特定的团体或阵营，而是一种「恶意」。这种「恶意」曾践踏大家的愿望，破坏大家平静的生活，肆意伤害大家…彻底消除它们后，我就能安心放下武器了。等那时候，我就换上便服，和你在海祇岛上随意地散步吧。\", \"voicelineId\": 55035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"五郎的爱好…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_pref_hobby\", \"description\": \"我喜欢登山，越险峻的山越好。登山能锤炼我的肉体和精神，让我变得更强壮。还有，和同伴一起登山。在挥洒汗水后共同欣赏山间的美景，也是人生一大乐趣。不过，我不敢…不想攀爬稻妻的最高峰…\", \"voicelineId\": 55036, \"voicelineType\": \"6001\"}, {\"title\": \"五郎的烦恼…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_dialog_annoyed\", \"description\": \"轻装上阵也有不方便的时候，比如，一旦遇上火攻，我的尾巴就要格外小心。\", \"voicelineId\": 55037, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_pref_foodLike\", \"description\": \"我喜欢蛋糕和三彩团子！嗯…大概是因为我很少吃到这类精致的点心吧。军营里的饭菜强调简便快捷，通常也不会用到太多调味料，至于糖，就更是珍贵物资了。甜味…我无法拒绝！\", \"voicelineId\": 55038, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_pref_foodDislike\", \"description\": \"大部分食物我都不忌口，可洋葱是个例外。有一次，后勤兵往饭菜里加了洋葱末，让我在饭桌上痛哭流涕…啊，那次实在太丢人了！弄得后勤兵也很过意不去。\", \"voicelineId\": 55039, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_spice_pref_01\", \"description\": \"这种甜味，完全无法抵抗！\", \"voicelineId\": 55068, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_spice_normal_01\", \"description\": \"哦！心中气势大增！有什么需要我帮忙的吗！\", \"voicelineId\": 55069, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_spice_dislike_01\", \"description\": \"比想象中的还要辛辣…呜，我…我有些力不从心了。\", \"voicelineId\": 55070, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_pref_birthday_01\", \"description\": \"今天是你的生日，是意义重大的一天，请允许我来为你庆祝吧。我们在海边生一堆篝火，抓来最新鲜的鱼和螃蟹，我想给你亲手做一顿大将级别的「士气晚餐」！\", \"voicelineId\": 55040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_starUp_01\", \"description\": \"强大的力量，是为了保护同伴。\", \"voicelineId\": 55041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_starUp_02\", \"description\": \"要保护同伴，不能只是被动防守，必须积极进攻。\", \"voicelineId\": 55042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_starUp_03\", \"description\": \"攻夺胜利的要领，是牢记战斗的意义，遵循正确的战法，拿出锐不可当的气势。\", \"voicelineId\": 55043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_gorou/vo_gorou_starUp_04\", \"description\": \"有了锐不可当的气势，与战友们紧密配合，方可无往不胜。谢谢你的指点！这是属于你我二人共同的胜利。\", \"voicelineId\": 55044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_battle_skill1_01\", \"description\": \"进军！\", \"voicelineId\": 55045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_battle_skill1_02\", \"description\": \"强攻！\", \"voicelineId\": 55046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_battle_skill1_03\", \"description\": \"结阵！\", \"voicelineId\": 55047, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_battle_skill3_01\", \"description\": \"随我出征！\", \"voicelineId\": 55048, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_battle_skill3_02\", \"description\": \"势如破竹！\", \"voicelineId\": 55049, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_battle_skill3_03\", \"description\": \"兵贵先声！\", \"voicelineId\": 55050, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_chest_open_01\", \"description\": \"今日运势不错！\", \"voicelineId\": 55051, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_chest_open_02\", \"description\": \"和同伴们一起分享收获吧！\", \"voicelineId\": 55052, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_chest_open_03\", \"description\": \"这个宝箱…埋伏了我？\", \"voicelineId\": 55053, \"voicelineType\": \"300003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_explore_sprint_start_01\", \"description\": \"随我来。\", \"voicelineId\": 55054, \"voicelineType\": \"700001\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_life_less30_01\", \"description\": \"我还能战斗！\", \"voicelineId\": 55055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_life_less30_02\", \"description\": \"大意了！\", \"voicelineId\": 55056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_life_less30_03\", \"description\": \"没到认输的时候！\", \"voicelineId\": 55057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_life_less30_teammate_01\", \"description\": \"按甲休兵！\", \"voicelineId\": 55058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_life_less30_teammate_02\", \"description\": \"不要乱了阵脚！\", \"voicelineId\": 55059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_life_die_01\", \"description\": \"兵败了…\", \"voicelineId\": 55060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_life_die_02\", \"description\": \"海祇岛的…大家…\", \"voicelineId\": 55061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_life_die_03\", \"description\": \"全军…撤退…\", \"voicelineId\": 55062, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_battle_hit_L_02\", \"description\": \"不痛不痒！\", \"voicelineId\": 55063, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_gorou/vo_gorou_battle_hit_H_02\", \"description\": \"再来！\", \"voicelineId\": 55064, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_gorou_teamJoin_01\", \"description\": \"整装待发！\", \"voicelineId\": 55065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_gorou_teamJoin_02\", \"description\": \"准备进军！\", \"voicelineId\": 55066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_gorou_teamJoin_03\", \"description\": \"行兵列阵！\", \"voicelineId\": 55067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000056, 'Kujou Sara', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_draw_appear\", \"description\": \"我的名字是九条裟罗，你记不住也无妨，只需知道：我将永远护卫稻妻、践行鸣神的意志，不论神鬼，遇敌必除！呼…别紧张，既然答应与你并肩，我自当尽心尽职。大义外的事情，我不会计较的。\", \"voicelineId\": 56001, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·正鹄\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_character_idle_01\", \"description\": \"只有保持心、弓、箭三位一体，才能命中正鹄。\", \"voicelineId\": 56002, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·永恒\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_character_idle_02\", \"description\": \"为将军大人实现「永恒」，这就是我的「愿望」。\", \"voicelineId\": 56003, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·使命\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_character_idle_03\", \"description\": \"天狗的职责是护佑山林，九条家的使命是守卫稻妻，两者并无二致。\", \"voicelineId\": 56004, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_weather_heavyRain_01\", \"description\": \"雨滴的声音会掩盖脚步声，多加注意吧。\", \"voicelineId\": 56005, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_weather_thunder_01\", \"description\": \"听见了吗？鸣雷正是将军大人的意志。\", \"voicelineId\": 56006, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_weather_snowy_01\", \"description\": \"想要留住雪花。但在手心里，它只会融化得更快。\", \"voicelineId\": 56007, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_weather_sunny_01\", \"description\": \"天清气朗，适合演武。\", \"voicelineId\": 56008, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_greetingMorning\", \"description\": \"早上吗？对于我而言，这已经不早了。通常我睁开眼时，天还没亮。\", \"voicelineId\": 56009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_greetingNoon\", \"description\": \"我没有午休的习惯，但如果你想，我可以等你。\", \"voicelineId\": 56010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_greetingNight\", \"description\": \"晚上好。随口一提，花见坂的夜樱，是不可多得的景致。\", \"voicelineId\": 56011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_greetingNight2\", \"description\": \"去休息吧，这里有我看着就行。\", \"voicelineId\": 56012, \"voicelineType\": \"1004\"}, {\"title\": \"关于裟罗自己·天领奉行\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_idle\", \"description\": \"家主于我有恩，「天领奉行」是我唯一的依靠，我会倾尽一切来捍卫家族的荣誉。嗯？你问「天领奉行」的行事准则？那自然是忠于雷电将军大人，这也是我九条裟罗此生唯一的信条。\", \"voicelineId\": 56013, \"voicelineType\": \"2001\"}, {\"title\": \"关于裟罗自己·备战\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_idle2\", \"description\": \"「准备好了吗？」如果在出发前，你有这样确认的习惯。十次中，恐怕只有一次，你能听到我的答复。其余九次，我已经化身利刃，身处前线。这并非蛮勇或不忠，而是战场从来不会留给人喘息的时间。\", \"voicelineId\": 56014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于裟罗自己·愿望\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_close\", \"description\": \"我的愿望？我原以为你早已知道，辅佐将军大人实现「永恒」就是我的愿望。嗯？为自己所想的愿望？这种东西，我没有想过…\", \"voicelineId\": 56015, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·观察\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_close1\", \"description\": \"虽然你对于将军大人的「永恒」而言是个「不安定」的因素，但「不安定」也未必代表「阻碍」。我不会与你为敌，但，我会一直盯着你。\", \"voicelineId\": 56016, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·体会\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_close2\", \"description\": \"收缴神之眼时，我漠视了人们的愿望。在眼狩令已然结束的当下，我有责任作出弥补。听说你能听见千手百眼神像上那些神之眼蕴含的愿望？请跟我好好讲讲吧。还有…也跟我说说你的愿望吧，我想知道。\", \"voicelineId\": 56017, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_pendant\", \"description\": \"得到神明的注视，才能获得「神之眼」。既然我的「神之眼」是由将军大人所赐，最后，我也会将它还给将军大人，不怨不悔。\", \"voicelineId\": 56018, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·陀螺\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_share_01\", \"description\": \"上次执行任务时，花见坂的商户送给我一个名为「独乐」的陀螺，那是种「一个人也能玩」的玩具，我觉得挺有意思，就留在了身边。你说…一起玩？那岂不是违背了「独乐」的原则，请容我拒绝。\", \"voicelineId\": 56019, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·特产\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_share_02\", \"description\": \"知道稻妻最具代表性的特产是什么吗？不对，并非刀具。是「御建鸣神主尊大御所大人像」造型的漆器，由老练的漆器师傅手工打造，城内几乎每家每户都供奉着一座。我的屋里？有五座。\", \"voicelineId\": 56020, \"voicelineType\": \"3004\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_pref_gift\", \"description\": \"当我心中有难解之事时，我会伫立在神樱树下闭目养神，再次睁开眼时，飘落的花瓣就会为我指引方向。\", \"voicelineId\": 56021, \"voicelineType\": \"3003\"}, {\"title\": \"关于托马…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_thoma_01\", \"description\": \"「天领奉行」的宅邸很大，如果有像托马一样优秀的家政官就好了，一定能将家中纷繁事务打理妥当。要是什么时候，他不再想侍奉神里家了，我很希望他能过来帮忙。不过大概不会有这一天吧。\", \"voicelineId\": 56022, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_ayaka_01\", \"description\": \"平时在九条家，只有士兵们在道场训练的声响，而每次路过神里家，总会听见舞乐声、打闹声和笑声。听闻神里家的大小姐棋技了得，我一直等候时机，想要登门拜访，却又担心…像我这般严肃的人，是否会与那般氛围格格不入呢。\", \"voicelineId\": 56023, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_yoimiya_01\", \"description\": \"只要她不在我的军营里乱放烟花，我是不会找她麻烦的。哼，我知道，抛开别的不谈，她做的烟花的确流光溢彩，值得称赞。只不过烟花易逝，刹那光辉结束后，夜空上留下的依旧是黑暗。所以我时常提醒自己，想要贯彻护佑稻妻的使命，就不能沉沦在这些虚幻的光景中。\", \"voicelineId\": 56024, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鹿野院平藏…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_heizou_01\", \"description\": \"鹿野院…虽说这位是我的同僚，但我对他没什么好感。总感觉他有很多自己的盘算，没有把组织的事放在第一位。要不是看在他探案有功的份上，早该对他多加管束。\\n唉，真是头疼。\", \"voicelineId\": 56025, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军·相信\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_raidenShogun_01\", \"description\": \"你肯定从不少地方听说过吧？将军大人追求的是无念无执的永恒，舍弃尘世的执念，执着不变的永恒。将军大人的言行决断，我并非每一处都能参透。但既然这是她的决定，我便相信她。\", \"voicelineId\": 56026, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军·追随\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_raidenShogun_02\", \"description\": \"「眼狩令」废除…嗯，看来你才是对的。咳…但这并不说明将军大人是错的。只是追求「永恒」之路的方式将要改变罢了。不知那位千百年来守护着稻妻的将军大人，如今心中是否平静呢。我只知道，不管道路上有多少险阻，我都会一如既往追随她。\", \"voicelineId\": 56027, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_yaeMiko_01\", \"description\": \"八重宫司大人的所作所为，经常会让我产生误会…但她既然贵为鸣神大社的大巫女，不难得见将军大人对她的信任与默许，我自然也会敬重她。不过，如果哪天她做了忤逆将军意志的事情，那就恕我冒犯了。\", \"voicelineId\": 56028, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珊瑚宫心海…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_kokomi_01\", \"description\": \"比起「巫女」，她作为「军师」的才能更高。用锦囊打仗，此前实属闻所未闻。我是否也该学习着用这种方法来指挥幕府军呢？嗯…但这样恐怕会演变成双方把锦囊摆上台面，像卡牌一样逐张对战…想想还是不妥。\", \"voicelineId\": 56029, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于五郎…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_gorou_01\", \"description\": \"他之于珊瑚宫心海，正如我之于将军大人。同为坚守忠义之人，我很欣赏他。只可惜立场不同，注定没办法同行。但有这样值得敬佩的对手，还不赖。而且，「五郎」…可是个好名字。\", \"voicelineId\": 56030, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_itto_01\", \"description\": \"…说起这位，难免有些头疼。收缴他的神之眼时闹了不少动静，是我见过最聒噪的人…不，最聒噪的鬼。能堂堂正正认输算是有点男子气概，只不过他的复仇之约实在是…到此为止，我不想说了。你如果实在想知道，还是自己去问他吧。\", \"voicelineId\": 56031, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于久岐忍…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_shinobu_01\", \"description\": \"以她的才华和资质，留在那个名为「荒泷派」的组织实在有点可惜。但不得不说，有她在，至少有效地阻止了闲散人士滋事扰民，减轻了天领奉行的负担。\", \"voicelineId\": 56032, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绮良良…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_teammate_kirara_01\", \"description\": \"近来总觉得暗处有奇怪的视线，待我确认时又消失无踪。真是不明所以的恶作剧。你说…是只猫又？嗯…既然有事找我，堂堂正正报上名来就行。\", \"voicelineId\": 56074, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解裟罗·其一\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_friendship_01\", \"description\": \"了解我…请问是指什么？天领奉行的各项事务均为机密，将军大人的事情更是无可奉告，我不明白你有什么意图。嗯？了解我本身？倒也并非不可，只是…从未遇过这种情况。\", \"voicelineId\": 56033, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解裟罗·其二\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_friendship_02\", \"description\": \"我的生活还算简单，不用领队战斗时，我会准时在凌晨五点零五分起床，在庭院做五组深呼吸后走五圈，早饭习惯吃五口米饭…「五」是能为我带来幸运与胜利的数字，所以我会一直坚持「五」，请问你有什么异议吗？\", \"voicelineId\": 56034, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解裟罗·其三\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_friendship_03\", \"description\": \"执行眼狩令的过程中，最令我感到棘手的，是那些顶着幕府军头衔动用私刑的官兵。将军大人的任务固然要坚定执行，但我决不允许他们滥伤无辜！我已经三申五令禁止这种行为，就结果而言…依然难以杜绝。你若是有什么好办法，还望赐教。\", \"voicelineId\": 56035, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解裟罗·其四\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_friendship_04\", \"description\": \"虽然名义上是九条家的养子，但孝行大人看我的眼神，与看镰治时的不同。即使木讷如我，也会偶感寂寞，尤其…在看到部下与亲人相见的温暖场面后。\\n抱歉，家主于我有恩，原是不该说这种大不敬的话的…\", \"voicelineId\": 56036, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解裟罗·其五\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_friendship_05\", \"description\": \"现在回想起来，你我也算「不打不相识」。我们一度处于对立面，说势不两立也不为过，真没想到现在竟然能这样并肩而行，促膝长谈。这样想来，我还真是得到了命运的眷顾…不，没什么。\", \"voicelineId\": 56037, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"裟罗的爱好…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_pref_hobby_01\", \"description\": \"即使到了现在，素引练习和草靶练习依然是我每天必不可少的训练项目。从身法到瞄准再到听弦，绝不是枯燥的重复，而是对昨日的突破。与其说是爱好，不如说是一生的修行。\", \"voicelineId\": 56038, \"voicelineType\": \"6001\"}, {\"title\": \"裟罗的烦恼…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_dialog_annoyed\", \"description\": \"天狗的翅膀是固有的客观存在，并排站的话肯定会占据一定的空间，我不明白你说的「拉近距离」究竟要怎么实现。\", \"voicelineId\": 56039, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_pref_foodLike\", \"description\": \"长久以来，我已经习惯吃饭团之类方便携带、能够迅速饱腹的食物了，这也是战场上恢复体力的首选。不过，这只是个人习惯，我不会要求部下跟我一样。\", \"voicelineId\": 56040, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_pref_foodDislike\", \"description\": \"没有厌恶一说，只是我平日会避免吃甜食。问我原因吗？甜食会使人身心放松，一旦吃了就容易…呃，总之，我不能懈怠，话题到此结束，不要再追问了！\", \"voicelineId\": 56041, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_spice_pref_01\", \"description\": \"比饭团更美味的食物…值得记下它的名字。\", \"voicelineId\": 56071, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_spice_normal_01\", \"description\": \"我吃饱了。多谢款待。\", \"voicelineId\": 56072, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_spice_dislike_01\", \"description\": \"甜点还是不必了…\", \"voicelineId\": 56073, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_pref_birthday\", \"description\": \"来得正好，那我就免去礼节，直接问了。有什么生日愿望吗？只要不与将军大人的大义相悖，我都会竭尽全力帮你完成。为表诚意，今天你可以许五个生日愿望。\", \"voicelineId\": 56042, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_starUp_01\", \"description\": \"满意的弦音，看我一击即中。\", \"voicelineId\": 56043, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_starUp_02\", \"description\": \"力量已经融入我体内，随时听命。\", \"voicelineId\": 56044, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_starUp_03\", \"description\": \"我一个人，就是一支幕府军！\", \"voicelineId\": 56045, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_kujouSara/vo_kujouSara_starUp_04\", \"description\": \"磨炼自身，突破武艺，本是我的职责所在，但你却倾尽心力相助…我不会辜负这份力量，定将其用于大义！还有，天狗的情谊，与你同在！\", \"voicelineId\": 56046, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_battle_skill1_01\", \"description\": \"羽移！\", \"voicelineId\": 56047, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_battle_skill1_02\", \"description\": \"散！\", \"voicelineId\": 56048, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_battle_skill1_03\", \"description\": \"雷闪！\", \"voicelineId\": 56049, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_battle_skill3_01\", \"description\": \"常道恢弘，鸣神永恒！\", \"voicelineId\": 56050, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_battle_skill3_02\", \"description\": \"落雷…不悔！\", \"voicelineId\": 56051, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_battle_skill3_03\", \"description\": \"雷光千道！\", \"voicelineId\": 56052, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_chest_open_01\", \"description\": \"不错的宝物，能够提振士气！\", \"voicelineId\": 56053, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_chest_open_02\", \"description\": \"很好，没有放过任何角落。\", \"voicelineId\": 56054, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_chest_open_03\", \"description\": \"补充完就上路吧！\", \"voicelineId\": 56055, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_life_less30_01\", \"description\": \"我会坚持到底…\", \"voicelineId\": 56056, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_life_less30_02\", \"description\": \"必须寻找突破点！\", \"voicelineId\": 56057, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_life_less30_03\", \"description\": \"快到极限了…\", \"voicelineId\": 56058, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_life_less30_teammate_01\", \"description\": \"不要勉强！\", \"voicelineId\": 56059, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_life_less30_teammate_02\", \"description\": \"退下！\", \"voicelineId\": 56060, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_life_die_01\", \"description\": \"生命终非永恒。\", \"voicelineId\": 56061, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_life_die_02\", \"description\": \"我绝无怨言…\", \"voicelineId\": 56062, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_life_die_03\", \"description\": \"哼，是我败了。\", \"voicelineId\": 56063, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_battle_hit_L_01\", \"description\": \"再来！\", \"voicelineId\": 56064, \"voicelineType\": \"900001\"}, {\"title\": \"普通受击·其二\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_battle_hit_L_02\", \"description\": \"不错的对手…\", \"voicelineId\": 56065, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_battle_hit_H_01\", \"description\": \"怎么会！\", \"voicelineId\": 56066, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_kujouSara/vo_kujouSara_battle_hit_H_02\", \"description\": \"战况不顺…\", \"voicelineId\": 56067, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_kujouSara_teamJoin_01\", \"description\": \"我会带领你获得胜利。\", \"voicelineId\": 56068, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_kujouSara_teamJoin_02\", \"description\": \"哼，来吧。\", \"voicelineId\": 56069, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_kujouSara_teamJoin_03\", \"description\": \"与你并肩！\", \"voicelineId\": 56070, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000057, 'Arataki Itto', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_draw_appear\", \"description\": \"作为荒泷派的大哥大，本大爷的名号早就威震四方了。「荒泷天下独尊一斗」、「荒泷相扑鬼王一斗」、「荒泷鬼族骄傲一斗」、「荒泷鬼兜虫角斗士一斗」、「荒泷卡牌游戏王中王一斗」、「荒泷可以输但绝不认输名副其实男子汉一斗」…这些都是我常用的名字，你可以挑个喜欢的随便叫，不用客气，哈哈哈哈。\", \"voicelineId\": 57000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·到此一游\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_character_idle_01\", \"description\": \"嘿嘿，荒泷天下第一斗到此一游！ 哈哈哈哈…咳…\", \"voicelineId\": 57001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·零食\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_character_idle_02\", \"description\": \"轻易得到的东西哪有滋味？所以，零食我从来不会用摩拉买，都是堂堂正正地赢回来。\", \"voicelineId\": 57002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·斗虫\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_character_idle_03\", \"description\": \"不要小瞧斗虫啊。在一次次拼搏中，用汗和泪浇灌出更强的自己，这就是人生啊！\", \"voicelineId\": 57003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_weather_heavyRain_01\", \"description\": \"男子汉从不打伞…啊这雨也太大了吧，快，快，快开伞！\", \"voicelineId\": 57004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_weather_thunder_01\", \"description\": \"喂！雷电将军对吧？听着，本大爷就是不服！有本事，劈我啊！\", \"voicelineId\": 57005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_weather_snowy_01\", \"description\": \"喔吼…来滚雪球吧！你是赢不了我的！阿…阿嚏！…呼。\", \"voicelineId\": 57006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_weather_sunny_01\", \"description\": \"天气真好！该把我珍藏的鬼兜虫拉出来训练一番了！唔！\", \"voicelineId\": 57007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_weather_gale_01\", \"description\": \"风再大，发型也不能乱，这是男人的底线。\", \"voicelineId\": 57008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_greetingMorning\", \"description\": \"早啊！…已经没有摩拉了，但今天还是不想干活。不如想想去哪里玩吧？\", \"voicelineId\": 57009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_greetingNoon\", \"description\": \"吃饱了去哪里逛好呢？花见坂…都逛烂了，嗯，也不适合去天领奉行那闹…嗯算了，去离岛遛遛吧。\", \"voicelineId\": 57010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_greetingNight\", \"description\": \"嘘！是谁在讲话…？是鬼啊！哈哈哈…被吓到了吗？\", \"voicelineId\": 57011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_greetingNight2\", \"description\": \"累了就快睡吧，别逞强，我？哼，我睁着眼也能睡觉，嘿嘿。\", \"voicelineId\": 57012, \"voicelineType\": \"1004\"}, {\"title\": \"关于荒泷一斗自己·不务正业\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_idle\", \"description\": \"他们说我不务正业？哈哈哈哈！胡扯！本大爷是混混啊，混混的正业就是不务正业，有什么问题吗？咳，不好意思激动了些…哎呀，放心放心，我不偷不抢，快活不下去了，就去做点临时工赚摩拉，搬货送信都是小儿科，开业现场帮忙充场子也是常干的事，只要摩拉日结就行了，嘿嘿！\", \"voicelineId\": 57013, \"voicelineType\": \"2001\"}, {\"title\": \"关于荒泷一斗自己·鬼族\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_idle2\", \"description\": \"鬼族经历了很多事情，才迎来了现在这个好时代，可以与人类共同生活。只可惜啊，时至今日还有许多人对鬼族心存芥蒂。嗯？怎么办？当然要改变啦。哼，但我不会刻意去讨好他们，我要用自己的方式，赢得人类的尊重。\", \"voicelineId\": 57014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·合拍\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_close\", \"description\": \"喂，我看你总是东奔西跑地替人办事，图的不止是摩拉吧？你一定也是个豪爽仗义的人！哈正好，本大爷最喜欢跟仗义的人打交道，我们绝对能成为超级合拍的搭档！\", \"voicelineId\": 57015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·响应\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_close1\", \"description\": \"说实话，我很欣赏你，一直很欣赏你。当然希望你能留在荒泷派啦，欸，连给你的称号我都想好了，在你名字里添上「天下第二」，我俩就是「数一数二」组合！哈哈哈。哎呀…玩笑归玩笑，我知道你还有更重要的使命…去吧，去做你想做的事情。总之你记住，荒泷派会无条件响应你。\", \"voicelineId\": 57016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_pendant\", \"description\": \"别问，说起这个我就火大。那群幕府军夺走人们珍视的东西，罪大恶极，竟然还敢乱摆神之眼！欸，照理说，越强的人，神之眼就应该嵌在越上面才对吧，到底是哪个不识抬举的将本大爷的神之眼嵌在最下面啊！\", \"voicelineId\": 57017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·希娜小姐\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_share_01\", \"description\": \"你要是有什么烦恼，可以试着给《闲事月刊》的问答栏目投稿，希娜小姐一定会给你一个温暖人心的答案。啊…托她的福，我的灵魂已经不再迷茫了…对了，我还报名了希娜小姐的线下见面会，唉这日子怎么就过得那么慢呢。\", \"voicelineId\": 57018, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·双角\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_share_02\", \"description\": \"我头上的角，看久了会单调吗？要不用涂料把它弄成彩虹色吧，再抓点萤火虫绑在上面，走在街上炫彩夺目，想想就觉得很帅！本大爷果然是天才，我这就让兄弟们行动起来！\", \"voicelineId\": 57019, \"voicelineType\": \"3004\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_pref_gift_01\", \"description\": \"抓鬼兜虫的唯一秘诀就是——抓之前一定要擦亮双眼看清楚，尤其是在风乱吹雨乱下的雷雨天，一不小心就会把堇瓜和鬼兜虫弄混。\", \"voicelineId\": 57020, \"voicelineType\": \"3003\"}, {\"title\": \"关于托马…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_teammate_thoma_01\", \"description\": \"听弟兄们说，他是第一百颗神之眼狩眼仪式的主角？嗯？为什么他会有专属的仪式啊？欸，难道说第一百颗神之眼是比前九十九颗厉害吗？嘶…不对，真是那样的话，那应该是本大爷来当这第一百颗才对！\", \"voicelineId\": 57021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫人…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_teammate_ayato_01\", \"description\": \"哈哈哈哈，我跟绫人兄可以说是相见恨晚啊！如果不是他提醒我「让温顺的虫子燃起斗志」是我一生都该坚守的觉悟，也许早在第七百八十次战败时，我就放弃斗虫了…哈哈，果然只有男人最懂男人，哎呀，我和他之间无需多言，在打牌和斗虫时，默契就已经悉数体现了。\", \"voicelineId\": 57022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_teammate_yoimiya_01\", \"description\": \"那家伙，仗着自己会做烟花和小玩具，哄起小孩来一套一套的…不行，不能让她抢尽风头，「孩子王」本大爷是当定了！你也要站我这边…什么？你不是孩子？呵，在我眼里，比我矮的，全是孩子！\", \"voicelineId\": 57023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_teammate_kazuha_01\", \"description\": \"听说你从天守阁逃出来后，是他挡下了「无想的一刀」？帅啊！到底怎么做到的。你想，他是没落的贵族，我是没落的鬼族…某种意义上，我和他旗鼓相当啊。哈哈哈哈，那么，下一刀，本大爷替你挡了！\", \"voicelineId\": 57024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_teammate_raidenShogun_01\", \"description\": \"搞眼狩令的时候，需要出动她得意的天狗才能制服我，说明本大爷一定让她很头痛吧？不过，既然她决定废除眼狩令，也不算无可救药。哼，她最好记住这次的教训，别再有下次，不然，我一定会让她更头痛，哼。\", \"voicelineId\": 57025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于狐耳女人…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_teammate_yaeMiko_01\", \"description\": \"那场狐狸拉面比赛，是我赢了，就算面里有油豆腐，她也别想赢我！那之后…那之后我躺了一个多月，但我至少守住了胜者的荣耀！而她，就要承受付清三十二碗面钱的耻辱。哈哈哈哈…\", \"voicelineId\": 57026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_teammate_kujouSara_01\", \"description\": \"眼狩令那会我确实败给她了，呵，这也没什么好羞耻的，输了就堂堂正正投降，错了就老老实实挨打，这才是真男人！反倒是她，堂堂天狗，不敢应我的复仇之约。哼，不过是在十字路口相扑而已，这就怕了？她要是再不来应战我就不叫她九条天狗了，我要叫她——九条乌龟！\", \"voicelineId\": 57027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200711], \"unlockText\": \"完成「不动鸣神，恒常乐土」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于五郎…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_teammate_gorou_01\", \"description\": \"哦，反抗军的小狗大将嘛，身材小小但气魄非凡，不错不错！而且，他身上散发着一种让人内心温暖的熟悉感…奇怪，明明没见过他几面…\", \"voicelineId\": 57028, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于久岐忍…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_teammate_kukiShinobu_01\", \"description\": \"荒泷派的弟兄们一般都会顺着我意，唯独这个忍啊，老是跟我唱反调！本大爷辛辛苦苦赢来的战利品，竟然被她一件件还了回去。哎呀，算了，看在她每次都会把我从牢房里捞出来，还替我们收拾了不少烂摊子，就不计较了。毕竟惹怒了她，我也没有好日子过…\", \"voicelineId\": 57029, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于早柚…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_teammate_sayu_01\", \"description\": \"不过是趁她不注意的时候，摸了摸她的头而已，现在一见面就要跳起来打我。哈哈哈没办法，这么可爱的小狸猫，谁见了都会忍不住想去摸摸头吧？噢对了…喊她狸猫也会被揍。为什么啊，那不就是狸猫吗…？\", \"voicelineId\": 57030, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解荒泷一斗·其一\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_friendship_01\", \"description\": \"你一定很想问，为什么我只会斗虫和打牌，却能稳坐荒泷派老大的宝座？哼，的确，只会这些小儿科难以服众。干脆就一口气告诉你吧！我还会倒立吃拉面、睁着眼睡觉、用鼻孔吹口琴、用发梢拍苍蝇这类绝活。怎么样，消除你心中的疑惑了吧？\", \"voicelineId\": 57031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解荒泷一斗·其二\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_friendship_02\", \"description\": \"稻妻人每逢过节、搬家、生病，都爱撒豆子，一边撒还一边念念叨叨，「福豆撒落，鬼怪败挫」、「福来福来，鬼去鬼去」…我都听出耳茧了。关键是豆子还经常撒出路面来，害我过敏…可恶啊！我一定要为鬼族正名，鬼啥也没干！别有事没事就想着驱鬼驱魔的。\", \"voicelineId\": 57032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解荒泷一斗·其三\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_friendship_03\", \"description\": \"为了消除人类对鬼族的偏见，有次我让弟兄们把我温柔和蔼的形象用留影机拍成画片，贴在稻妻城的留言板上。欸，结果有些人竟敢在画片上乱涂乱画！更可恨的是，天领奉行的蠢货足轻说我引起社会治安恐慌，社奉行又说什么败坏风气，连勘定奉行的走狗都要来要什么广告营业税…嘶…真是不识好歹！\", \"voicelineId\": 57033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解荒泷一斗·其四\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_friendship_04\", \"description\": \"包容和理解这些有过不幸经历的人，这才是我荒泷派的「骄傲」。…你别听外面的人说什么怪不怪人的，在我眼里，他们每一位都是我重要的家人。呵，这群小子也抱着和我一样的想法，不管怎样都会和荒泷派同甘共苦。\", \"voicelineId\": 57034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解荒泷一斗·其五\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_friendship_05\", \"description\": \"我很敬佩青鬼「牺牲自己换取赤鬼延续」的行为，但绝不认同他们的理念。「更好地活下去」绝不该靠牺牲同类换取，应该是「一起更好地活着」才对。自顾自地牺牲…独自耍帅的行为算什么嘛…唉…过去已经没办法改变了。但今后，在我荒泷一斗的眼皮子底下，没有人可以随便牺牲自己。本大爷，要挡在你们前面！\", \"voicelineId\": 57035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1202618], \"unlockText\": \"完成「赤金魂」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"荒泷一斗的爱好…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_pref_hobby\", \"description\": \"斗虫、打牌、陀螺、剑玉、捉迷藏…总之你想得到的想不到的，我全都会！怎么样？要比什么？做好全盘皆输的准备吧！哈哈哈哈！\", \"voicelineId\": 57036, \"voicelineType\": \"6001\"}, {\"title\": \"荒泷一斗的烦恼…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_dialog_annoyed\", \"description\": \"「鬼婆婆」不是鬼，她可是世界上对我最好的人类，只是因为收养了我才会被叫鬼婆婆的。我怎么样都无所谓，反正我也不在乎别人的看法…唉，但我不想她因为我而被别人指指点点…\", \"voicelineId\": 57037, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_pref_foodLike\", \"description\": \"棒棒糖全身都是宝，不但糖好吃，棍子叼在嘴里还很帅，为我增添了一丝不羁的气质，来，你也试试吧。\", \"voicelineId\": 57038, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_pref_foodDislike\", \"description\": \"我是鬼我是鬼啊！最讨厌的当然是豆子啊！黄豆、绿豆通通不行，别说吃了，光是碰到身上都会过敏。唉，所以说，撒豆子这种陋习还是赶紧灭绝吧。\", \"voicelineId\": 57039, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_spice_pref_01\", \"description\": \"哈哈哈哈哈哈——已经三年没吃到那么好吃的菜了！\", \"voicelineId\": 57070, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_spice_normal_01\", \"description\": \"好！你今天孝敬本大爷的，我都记在账上了。\", \"voicelineId\": 57071, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_spice_dislike_01\", \"description\": \"喂，你…难不成…给我下毒了？！啊…\", \"voicelineId\": 57072, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_pref_birthday_01\", \"description\": \"今天是个重要的日子，我特意把弟兄们支开了，不然他们肯定要说我偏心。来，看看，我给你准备的生日礼物可是最高规格的！抓了三天三夜才抓到的特级鬼兜虫一只、大战了三百回合赢来的绝版卡牌一张，哦还有本大爷亲自演唱的生日歌一首——咳咳…祝你生日快乐…祝你生日快乐…\", \"voicelineId\": 57040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_starUp_01\", \"description\": \"喔喔…就是这样就是这样！力气更大了！\", \"voicelineId\": 57041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_starUp_02\", \"description\": \"好强的力量…胜率绝对会提升吧！\", \"voicelineId\": 57042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_starUp_03\", \"description\": \"这力气，一拳砸碎岩石，应该不在话下吧？\", \"voicelineId\": 57043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_itto/vo_itto_starUp_04\", \"description\": \"这样一来，我就是名副其实的荒泷天下第一斗了啊！你的功劳，本大爷不会忘。以后，就由本大爷来保护你了。\", \"voicelineId\": 57044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_battle_skill1_01\", \"description\": \"斗战岩牛！\", \"voicelineId\": 57045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_battle_skill1_02\", \"description\": \"给我砸！\", \"voicelineId\": 57046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_battle_skill1_03\", \"description\": \"就是你了！\", \"voicelineId\": 57047, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_battle_skill3_01\", \"description\": \"鬼王游巡，通通闪开！\", \"voicelineId\": 57048, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_battle_skill3_02\", \"description\": \"鬼蜮狂欢！\", \"voicelineId\": 57049, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_battle_skill3_03\", \"description\": \"哈哈，到我表演了！\", \"voicelineId\": 57050, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_chest_open_01\", \"description\": \"快看看有没有新鲜玩意儿？\", \"voicelineId\": 57051, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_chest_open_02\", \"description\": \"本大爷果然运气超凡！\", \"voicelineId\": 57052, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_chest_open_03\", \"description\": \"这些够我躺三天不干活了吧？\", \"voicelineId\": 57053, \"voicelineType\": \"300003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_explore_sprint_start_01\", \"description\": \"追不上我！\", \"voicelineId\": 57054, \"voicelineType\": \"700001\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_life_less30_01\", \"description\": \"别太小看鬼族了！\", \"voicelineId\": 57055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_life_less30_02\", \"description\": \"你以为我这就会认输吗？\", \"voicelineId\": 57056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_life_less30_03\", \"description\": \"区区小伤，不用管不用管！\", \"voicelineId\": 57057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_life_less30_teammate_01\", \"description\": \"站在本大爷身后！\", \"voicelineId\": 57058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_life_less30_teammate_02\", \"description\": \"我不允许你倒下！\", \"voicelineId\": 57059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_life_die_01\", \"description\": \"复仇之战，未完待续…\", \"voicelineId\": 57060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_life_die_02\", \"description\": \"倒下的姿势…得帅才行。\", \"voicelineId\": 57061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_life_die_03\", \"description\": \"辜负弟兄们的期待了…\", \"voicelineId\": 57062, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_battle_hit_L_01\", \"description\": \"胆子不小！\", \"voicelineId\": 57063, \"voicelineType\": \"900001\"}, {\"title\": \"普通受击·其二\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_battle_hit_L_02\", \"description\": \"用点力！\", \"voicelineId\": 57064, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_battle_hit_H_01\", \"description\": \"太用力了吧！\", \"voicelineId\": 57065, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_itto/vo_itto_battle_hit_H_02\", \"description\": \"偷袭可耻！\", \"voicelineId\": 57066, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_itto_teamJoin_01\", \"description\": \"都给本大爷让道！\", \"voicelineId\": 57067, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_itto_teamJoin_02\", \"description\": \"救世主来喽！\", \"voicelineId\": 57068, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_itto_teamJoin_03\", \"description\": \"多大点事，看我来摆平！\", \"voicelineId\": 57069, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000058, 'Yae Miko', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_draw_appear\", \"description\": \"我是鸣神大社的宫司，此番造访，自是为了确认你的一举一动，此为大社诏令…呵，不用那么紧张，场面话罢了，这样才有正当理由休沐嘛。快，去做些有趣的事让我看看吧。\", \"voicelineId\": 58000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·创作体裁\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_character_idle_01\", \"description\": \"最近八重堂穿越异世的小说也太多了，哼，就对自己的世界如此不满吗。\", \"voicelineId\": 58001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·故事\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_character_idle_02\", \"description\": \"很多人的一生，写于纸上也不过几行，大多都是些无聊的故事啊。\", \"voicelineId\": 58002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·尘世\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_character_idle_03\", \"description\": \"于我而言，不变也是一种美好，哎呀，可尘世哪是如此不变之物。\", \"voicelineId\": 58003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_weather_heavyRain_01\", \"description\": \"下起雨后，浑身的毛发都会变得湿漉漉的…\", \"voicelineId\": 58004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_weather_thunder_01\", \"description\": \"很多人会害怕打雷，不过我听到雷声只会觉得亲近。\", \"voicelineId\": 58005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_weather_snowy_01\", \"description\": \"未生灵智的小狐狸，往往会一头栽入雪地来觅食…想看我那样做？哼。\", \"voicelineId\": 58006, \"voicelineType\": \"1203\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_greetingMorning\", \"description\": \"早，嗯？怎么一副无精打采的样子，没有睡好吗？哎呀，昨晚是去做什么坏事了么？\", \"voicelineId\": 58007, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_greetingNoon\", \"description\": \"嗯~伤脑筋，中午吃些什么呢？油豆腐吃腻了，想吃点清淡的。话说好久没见到社奉行家的小姑娘了，我们不如就去吃她做的点心吧。\", \"voicelineId\": 58008, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_greetingNight\", \"description\": \"今夜的月光如此清亮，不做些什么真是浪费。随我一同去月下漫步吧，不许拒绝。\", \"voicelineId\": 58009, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_greetingNight2\", \"description\": \"该入眠了，呵，在夜里不听到连绵的雷声，甚至都会睡不安稳呢。\", \"voicelineId\": 58010, \"voicelineType\": \"1004\"}, {\"title\": \"关于八重神子自己·永恒\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_idle\", \"description\": \"所谓的永恒，就是不再失去已拥有之物，但从别的角度说，也放弃了得到更多的可能，不过世事总是如此，没人能够得到全部。\", \"voicelineId\": 58011, \"voicelineType\": \"2001\"}, {\"title\": \"关于八重神子自己·趣味\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_idle2\", \"description\": \"人类很有趣，所以我才如此喜欢人类。明明生命短暂，却能散发映昼光辉。他们之中，有些人的光芒，即使隔开久远时间长河都不曾黯淡。阅读这样的人生，是一大乐事啊。\", \"voicelineId\": 58012, \"voicelineType\": \"2005\"}, {\"title\": \"关于我们·作家\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_close\", \"description\": \"无聊，这本也无聊透顶…啊呀，这些人都是为了什么才成为作家的。欸，对了，不如你把自己的经历写下来投给八重堂吧，感觉一定能给我一点乐…一定能大受欢迎吧。\", \"voicelineId\": 58013, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·磨损\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_close1\", \"description\": \"将自己封闭起来，或许会更快地遭受「磨损」。只有自己的世界，无他人作镜以对映，可是很可怕的事…你我共处之时，重要的就是互相观照哦。\", \"voicelineId\": 58014, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_pendant\", \"description\": \"你说…你很喜欢我佩戴「神之眼」的方式？真有眼光。那么…要来摸摸看吗？\", \"voicelineId\": 58015, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_share_01\", \"description\": \"在油温到八成热时，沿锅下豆腐，再开成小火，等到煎至金黄的时候再夹出来，热乎乎的，这世上没有比油豆腐更好吃的东西了。咦，做法都已经告诉你了，你怎么还愣在这里呢？\", \"voicelineId\": 58016, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_pref_gift_01\", \"description\": \"虽然因为在鸣神大社，日日抬头都能得见，有时也会觉得厌烦。不过，那棵神樱毕竟已经是我命运所系之物了啊。\", \"voicelineId\": 58017, \"voicelineType\": \"3003\"}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_raidenShogun_01\", \"description\": \"明明想要出来，却一直把自己关在一心净土里，简直就是自我折磨嘛…从另一个角度来说，也挺可爱的不是吗。\", \"voicelineId\": 58018, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫人…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_ayato_01\", \"description\": \"社奉行家的那个小子啊，从小就不安分，别看他表面上笑得春风和煦，暗地里可不知道在盘算什么呢，令人讨厌…哼，我可跟他不是一类人，哪来同类相斥的说法。\", \"voicelineId\": 58019, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_ayaka_01\", \"description\": \"我很喜欢社奉行家的小姑娘，任何事都安排得井井有条。不过社奉行一直都在做些吃力不讨好的活，可怜，如果她不是神里家的人，我早就把她挖到八重堂了。\", \"voicelineId\": 58020, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200711], \"unlockText\": \"完成「不动鸣神，恒常乐土」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_kujouSara_01\", \"description\": \"这块愚笨的木头啊，远不如她那天狗爹爹心思活络…哎呀，怎么说呢，虽说木讷耿直也有木讷耿直的好处吧，不过还是希望下次不要在神社拦着我，一个劲追问影的事了。\", \"voicelineId\": 58021, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_yoimiya_01\", \"description\": \"长野原的烟花嘛，也是每年难得的值得期盼之物了。据说前些天她还大闹天领奉行，在敷地大放烟花。呵，九条家的人恐怕气得脸都变青了，真是可惜呀，没能亲眼看到那副场景。\", \"voicelineId\": 58022, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200711], \"unlockText\": \"完成「不动鸣神，恒常乐土」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_ganyu_01\", \"description\": \"这么说来，很久没有见过甘雨姐姐了。稻妻尚未锁国时，璃月与稻妻往来事务都是我与她接洽，真是相当可靠，下次若有机会去璃月，再给她带些新鲜的海灵芝吧。\", \"voicelineId\": 58023, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珊瑚宫心海…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_kokomi_01\", \"description\": \"现在的巫女，一个比一个可爱。不知道这孩子跳起太平神乐之舞会是什么样子，说不好群鱼也会跟着旋转吧。只要她肯叫我一声神子姐姐，呵呵…我倒有些心得愿意分享。\", \"voicelineId\": 58024, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于国崩…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_kunikuzushi_01\", \"description\": \"我当时就觉得那是个麻烦，不过她却说毕竟是自己创造之物不愿出手。早知变成现在这样，还不如当初就瞒着她处理掉算了。现在？呵…现在，已经变麻烦啦。\", \"voicelineId\": 58025, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_itto_01\", \"description\": \"他呀，鬼族的奇怪小子，呵，听说他找了九条家不少的麻烦。天领奉行的人想要以有伤风化为由将他写于街上的留言擦掉，是我找人保留的，呵，这么有趣的小鬼，这些年可是难能一见了。\", \"voicelineId\": 58026, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于五郎…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_gorou_01\", \"description\": \"五郎的尾巴色泽很漂亮，不过…还是我的更柔软一些。呵…\", \"voicelineId\": 58027, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于早柚…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_sayu_01\", \"description\": \"这个子小小的孩子，躲倒是挺会躲的，鹿野奈奈经常向我抱怨，得花很多时间找她，连看小说的时间都变少了。要我说啊，或许是有人在暗中帮助早柚呢？\", \"voicelineId\": 58028, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于久岐忍…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_kukiShinobu_01\", \"description\": \"听说阿幸的这位妹妹很有个性，虽说出自巫女世家，却远离神社，学了许多门手艺，甚至去过璃月留学，最后还加入了荒泷派…如此有趣的女孩子，应该让阿幸帮忙引荐一下，嗯，阿幸肯定不会拒绝我的。\", \"voicelineId\": 58029, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绮良良…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_kirara_01\", \"description\": \"最近对人类社会感兴趣的妖怪真是越来越多了。这种趋势，该说是好事吗？我的态度？哎呀，当然是劝大家及时行乐啦。再说，乖乖掏钱请客吃饭的小后辈，谁会不喜欢呢？\", \"voicelineId\": 58071, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于梦见月瑞希·产业竞争\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_mizuki_01\", \"description\": \"「焦虑劳累之人根本读不进小说」？唉，我们「八重堂」真是失败啊，旗下的小说还是趣味性不足，到现在为止，还没能推出足够获得瑞希小姐认可的小说。再给我的编辑和作家一点时间吧，要是接下来的作品还是没法让瑞希店长点头，我这个没用的主编，就只能亲自给瑞希小姐写一本小说咯，名字…就叫「梦貘记」好了。\", \"voicelineId\": 58072, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于梦见月瑞希·重遇\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_teammate_mizuki_02\", \"description\": \"瑞希刚回来稻妻那一会，总是一副揣着心事的样子，明明在路上看见了我，却还要把目光撇开…我？我当然没有主动搭讪她。还想多看一阵她那副别扭的模样呢。如果我没想错，等我们俩擦肩而过之后，她还要扭过头，瞪着眼睛瞅我两眼…要是我这时候再回头看她，只怕瑞希要被我吓得露出原形，捂着耳朵飘走了。\\n不过现在嘛…她都已经会在闲事月刊的读者来信里给我挑刺了。食梦貘的成长，真是迅速哪。\", \"voicelineId\": 58073, \"voicelineType\": \"4015\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [12048], \"unlockText\": \"完成「食梦者的忧郁」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解八重神子·其一\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_friendship_01\", \"description\": \"想知道更多我的事？也不是不行，不过世事都讲究一个互惠互利，想了解我，就拿你自己的事来交换如何？\", \"voicelineId\": 58030, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解八重神子·其二\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_friendship_02\", \"description\": \"狐斋宫大人啊，说着出一趟远门，就再也没有回来。唉，我那时可一点都不想接手鸣神大社的麻烦事，她对我说，说我要是当了神社的宫司，就可以随心所欲地吃油豆腐了。什么糟糕的理由呀，吵吵闹闹的，令人头疼的女人…\", \"voicelineId\": 58031, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解八重神子·其三\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_friendship_03\", \"description\": \"最开始建立八重堂的动机当然是为了看有趣的小说，不过到后来乐趣就变成看那些小说家殚精竭虑的样子了。呵，你永远想不出来那些人在拖稿的时候说出的理由，哎呀，比他们自己写的小说要有趣多了。\", \"voicelineId\": 58032, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解八重神子·其四\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_friendship_04\", \"description\": \"无论如何，魔神皆有消亡之时，若是他们的那些故事随时间一起散佚于天地，再无人忆起，那就太可惜了。以及，有资格写他们故事的人，必须得有上乘的文思与笔法…如果世上没有这样的人，那就培养出…培养出足以书写那些故事的作家吧。\", \"voicelineId\": 58033, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解八重神子·其五\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_friendship_05\", \"description\": \"说来，虽然看过许多人写的小说，我自己倒是从未动笔过，写小说毕竟还是很麻烦的事嘛。不过，如果你的冒险结束了，想要有人记录你的故事，而我那时正好有空的话…\", \"voicelineId\": 58034, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"八重神子的爱好…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_pref_hobby\", \"description\": \"我第一喜欢的是他人的故事，第二喜欢的就是看他人烦恼的神色，两者若是在一起，哈，那可是相得益彰的有趣啊。\", \"voicelineId\": 58035, \"voicelineType\": \"6001\"}, {\"title\": \"八重神子的烦恼…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_dialog_annoyed\", \"description\": \"过度安稳的日子实在是太过无聊了啊…\", \"voicelineId\": 58036, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_pref_foodLike\", \"description\": \"你有听说过一物，其名为「狐狸乌冬」吗，其实也就是加了油豆腐的乌冬啦。怎么样，油豆腐加乌冬，听上去就很好吃吧。\", \"voicelineId\": 58037, \"voicelineType\": \"6003\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_pref_foodDislike\", \"description\": \"不行，腌制过的东西不行，不管是花鳉还是腌海雀，不觉得都有一股不能让人接受的臭味吗？本宫身为鸣神大社的宫司，怎么能咽下如此不洁不净之物。\", \"voicelineId\": 58038, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_spice_pref_01\", \"description\": \"哎呀，小家伙，你对我的口味了解得很清楚嘛。\", \"voicelineId\": 58068, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_spice_normal_01\", \"description\": \"既然是你亲手做的，我就尝尝看吧，呵呵…\", \"voicelineId\": 58069, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_spice_dislike_01\", \"description\": \"怎么说呢…小家伙，需要努力的地方还有不少哦？\", \"voicelineId\": 58070, \"voicelineType\": \"6009\"}, {\"title\": \"生辰…\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_pref_birthday_01\", \"description\": \"今日是你的生辰啊…\\n「凡御岁之祝礼，以徒名之令，遇其其之所求，遂其其之所愿，正心明神，以受萌荫庇佑。」好了，就这样。祝你这一年能够诸事顺遂，得偿所愿吧。\", \"voicelineId\": 58039, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_starUp_01\", \"description\": \"所谓巫女修行阶位，在修习毕业之后，能准确开口念诵祭言即可称为「直阶」。对于人类来说很方便，不过对狐族来说倒是最困难的一步…毕竟是狐狸嘛。\", \"voicelineId\": 58040, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_starUp_02\", \"description\": \"成为宫司代理，也就是「正阶」的修行可是很辛苦的，要受诸多清修戒律，修行的秘诀唯有一条，就是晚上偷偷进食时，不要被人发现。\", \"voicelineId\": 58041, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_starUp_03\", \"description\": \"升为「明阶」，即要求进入天地明察的境界，神通宇内，世事洞明。只要进入了这个境界，一般都会受获神之眼，拥有远超一般狐族的悠长寿命了哦。\", \"voicelineId\": 58042, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_yaeMiko/vo_yaeMiko_starUp_04\", \"description\": \"鸣神大社的「净阶」，历来只有鸣神大社的宫司具有，仅此一位。「净阶」只是类似荣誉职位的东西，跟实力倒没什么关系，不过我若是自称实力最强的「净阶」，倒也无何不可。\", \"voicelineId\": 58043, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_battle_skill1_01\", \"description\": \"律令。\", \"voicelineId\": 58044, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_battle_skill1_02\", \"description\": \"咒禁。\", \"voicelineId\": 58045, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_battle_skill1_03\", \"description\": \"敕！\", \"voicelineId\": 58046, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_battle_skill1_04\", \"description\": \"显化。\", \"voicelineId\": 58047, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_battle_skill1_05\", \"description\": \"留形。\", \"voicelineId\": 58048, \"voicelineType\": \"100005\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_battle_skill3_01\", \"description\": \"真瞳显现！\", \"voicelineId\": 58049, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_battle_skill3_02\", \"description\": \"雷霆侘寂！\", \"voicelineId\": 58050, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_battle_skill3_03\", \"description\": \"雷光凄美啊。\", \"voicelineId\": 58051, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_chest_open_01\", \"description\": \"有什么有趣的东西吗？\", \"voicelineId\": 58052, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_chest_open_02\", \"description\": \"就只有这些么…\", \"voicelineId\": 58053, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_chest_open_03\", \"description\": \"快，打开来给我看看。\", \"voicelineId\": 58054, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_life_less30_01\", \"description\": \"这样下去可不行啊。\", \"voicelineId\": 58055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_life_less30_02\", \"description\": \"可不能再玩下去了。\", \"voicelineId\": 58056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_life_less30_03\", \"description\": \"好了，要认真一些了哦。\", \"voicelineId\": 58057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_life_less30_teammate_01\", \"description\": \"别再勉强了。\", \"voicelineId\": 58058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_life_less30_teammate_02\", \"description\": \"交给我就好。\", \"voicelineId\": 58059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_life_die_01\", \"description\": \"哎呀，玩过头了…\", \"voicelineId\": 58060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_life_die_02\", \"description\": \"结局真是糟糕啊…\", \"voicelineId\": 58061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_life_die_03\", \"description\": \"止步于此，何谈永恒…\", \"voicelineId\": 58062, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_battle_hit_L_02\", \"description\": \"就这样？\", \"voicelineId\": 58063, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_yaeMiko/vo_yaeMiko_battle_hit_H_02\", \"description\": \"真是麻烦。\", \"voicelineId\": 58064, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_yaeMiko_teamJoin_01\", \"description\": \"这时候想起我了？\", \"voicelineId\": 58065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_yaeMiko_teamJoin_02\", \"description\": \"去做点有意思的事吧。\", \"voicelineId\": 58066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_yaeMiko_teamJoin_03\", \"description\": \"好吧，既然你都来邀请我了…\", \"voicelineId\": 58067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000059, 'Shikanoin Heizou', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_draw_appear\", \"description\": \"我叫鹿野院平藏，是天领奉行里破案最多最快的侦探…哎呀呀，你身上一股麻烦缠身的味道。快坐下，这边坐，从头说给我听听吧。\", \"voicelineId\": 59000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·罪案\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_character_idle_01\", \"description\": \"唔…我好像闻到了罪案的味道。\", \"voicelineId\": 59001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·侦探\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_character_idle_02\", \"description\": \"侦探就要有侦探的样子，所以就得到处走走，搜集罪证才对嘛。\", \"voicelineId\": 59002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·直觉\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_character_idle_03\", \"description\": \"我的直觉告诉我，马上就要有精彩的事件发生了。\", \"voicelineId\": 59003, \"voicelineType\": \"1103\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_weather_afterRain_01\", \"description\": \"刚才那场雨，可别冲散了线索啊。\", \"voicelineId\": 59004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_weather_thunder_01\", \"description\": \"哦？是哪个狡猾的犯人在发誓吗？\", \"voicelineId\": 59005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_weather_snowy_01\", \"description\": \"你听说过吗？很久以前，发生在龙脊雪山上的午夜凶灵事件…\", \"voicelineId\": 59006, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_weather_gale_01\", \"description\": \"加油呀！这么点风力是成不了「风暴」的。\", \"voicelineId\": 59007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_greetingMorning\", \"description\": \"早呀，看你精神不好，没做噩梦吧？早知道的话，就该晚些再让你接触重案嘛。\", \"voicelineId\": 59008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_greetingNoon\", \"description\": \"吃饱了玩点锻炼脑力的游戏吧！继电石？哈哈，这个只能锻炼心态吧。\", \"voicelineId\": 59009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_greetingNight\", \"description\": \"太阳下班的时候，就轮到星星盯着犯人了。\", \"voicelineId\": 59010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_greetingNight2\", \"description\": \"真好啊，又到了睡觉时间！今天会做怎样的梦呢？\", \"voicelineId\": 59011, \"voicelineType\": \"1004\"}, {\"title\": \"关于鹿野院平藏自己·侦探\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_idle\", \"description\": \"侦探，就该用脑力摧毁那些犯人企图逃脱的侥幸，所以说，真正的侦探，根本犯不着使用武力嘛。\", \"voicelineId\": 59012, \"voicelineType\": \"2001\"}, {\"title\": \"关于鹿野院平藏自己·关键词\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_idle2\", \"description\": \"我习惯将见到的东西以关键词的形式记在脑子里，它们对推理大有帮助。你看这边这个人，干净裤腿上的猫毛，手腕处的抓痕，看来是想和动物玩，但却不太懂怎么逗猫。那位，很在意自己受伤的手，穿着和身份不符的新鞋…等等，说不定我要有新委托了。\", \"voicelineId\": 59013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·委托\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_close\", \"description\": \"我看你身边的委托，就像永不干涸的井口一样，捞都捞不完。那我就来沾点便宜吧。你懂的，打架、跑腿、找东西之类的活我是不做的。只做解谜推理，只解重案要案…嘿嘿，记得帮我留意哦。\", \"voicelineId\": 59014, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·必然结果\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_close1\", \"description\": \"「巧合」是个好词，听起来就像是命中注定。但可惜侦探不相信巧合，我和你的相遇，是此前每一个选择、每一次行动的必然结果，也就是说，是我们自己决定的哦。\", \"voicelineId\": 59015, \"voicelineType\": \"2002\"}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_pendant\", \"description\": \"有传言说我不用神之眼也能放倒同僚？唔…我更正一下。第一，我虽然是奉行所同心，但也只是个侦探，动的是脑力。第二，我们平时是不会打架的。第三…欸，蒙不过你啊。那算了~\", \"voicelineId\": 59016, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·成就感\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_share_01\", \"description\": \"把线索串联起来，一步步找出真凶，直到亲手为拼图嵌上最后一块。那种成就感，哎呀呀，实在是太迷人了。\", \"voicelineId\": 59017, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·同心\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_share_02\", \"description\": \"同心这个职位，既能带来声望，又离凶案现场最近，这舞台，比我在侦探社的时候大了不少。当然，当然…巡逻和抓捕这种活还是请厉害的人代劳吧，侦探的精力是有限的嘛。\", \"voicelineId\": 59018, \"voicelineType\": \"3005\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_pref_gift_01\", \"description\": \"你对木材有什么研究吗？啊，没错，说的就是那种路边随处可见的树木。犯人蹭到了树皮啦，刮到了木屑啦，踩到了树叶啦，说不好就会留下些什么。根据它们的生长区域，有时还能推断出重要的线索。完全可以说，树是侦探的好朋友啊。\", \"voicelineId\": 59019, \"voicelineType\": \"3003\"}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_teammate_kujouSara_01\", \"description\": \"九条裟罗大人啊…绝对是全天领奉行最严肃的人！真希望她能变得宽容一些，多多体谅下属，别再因为偶尔的缺勤责备我了。说到底，我也是为了查案嘛。\", \"voicelineId\": 59020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_teammate_itto_01\", \"description\": \"受人所托，我去牢里给他捎过几次烤堇瓜，有次还正巧听到他在唱歌。说实话，歌词很烂，但唱得不错。蹲牢房的人能有这样的精神状态，不算多见。\", \"voicelineId\": 59021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于久岐忍…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_teammate_shinobu_01\", \"description\": \"荒泷派真是个自由多元的组织呀，无论是怎样的风格都能接纳。了不起，了不起，多亏那位阿忍小姐管教有方。我是怎么知道的？哈哈，这已经简单到连推理都算不上了吧？\", \"voicelineId\": 59022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_teammate_yaeMiko_01\", \"description\": \"说起来，宫司大人的八重堂也会出版推理小说吧？什么时候能请你当面引荐一番？在这个时代，要成为名侦探，实力以外，宣传也不能落下。哎呀呀，我哪有别的心思啦。\", \"voicelineId\": 59023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶·共通点\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_teammate_kazuha_01\", \"description\": \"万叶他呀，太可靠了。在他的提醒下，线索就像装宝石的匣子被翻倒一样，滚落得满地都是了。我要是也有他那种对于自然的感知力…哦！我明白了！「风」之于他，就像是「直觉」之于我吧！\", \"voicelineId\": 59024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶·邀请\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_teammate_kazuha_02\", \"description\": \"好可惜呀！眼狩令废除后，我就不能堂堂正正地逮捕他了！不过这样一来，也就意味着…我可以光明正大地邀请他来天领奉行，跟我一起讨论案情了吧！\", \"voicelineId\": 59025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于五郎…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_teammate_gorou_01\", \"description\": \"在这位大将的叮嘱下，我的海祇岛之旅可是热闹了不少，到哪都有军士们盯着。天地良心，我不过是个平平无奇的观光群众，最多算个小小侦探，连白萝卜也不会惦记半根的呀。\", \"voicelineId\": 59026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珊瑚宫心海…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_teammate_kokomi_01\", \"description\": \"珊瑚宫大人我是没见过的。毕竟有她出席的场合，村民们会围个里三圈外三圈吧，我就不凑热闹啦。啊，对，最里面那层还要算上巫女！像我们这样的年轻人，想要获得大家的认可，总要多付出一点努力的。\", \"voicelineId\": 59027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_teammate_ayaka_01\", \"description\": \"我和神里家的大小姐，只能算点头之交吧。还好我的家族不是什么名门。那种生活，可不适合我呀。\", \"voicelineId\": 59028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解鹿野院平藏·其一\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_friendship_01\", \"description\": \"就算一个人保持沉默，也能从他的衣着、动作、表情来掌握信息哦。如果接下来我的话就此打住…你又能从我身上读到什么呢？\", \"voicelineId\": 59029, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解鹿野院平藏·其二\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_friendship_02\", \"description\": \"某次旁听时，我受脑海中的推导鼓动，阻止了判决的下达。如果当时提出的异议无效，那它就不会成为我当侦探的契机，而会是——鹿野院平藏，因扰乱庭审秩序受到拘留处罚，哈哈哈…\", \"voicelineId\": 59030, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解鹿野院平藏·其三\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_friendship_03\", \"description\": \"调查外遇、寻找宠物…从侦探社接到的案件总是那么几类，不够我挑战自己的呀。我只好找机会溜去天领奉行喽。另一部分的原因，是我跟珊瑚社长的理念不太合拍啦，这也没办法。\", \"voicelineId\": 59031, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解鹿野院平藏·其四\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_friendship_04\", \"description\": \"刚进天领奉行时，我拿未结案的卷宗来练手，不知不觉间，那座「卷宗山」也快被我咻地推平了…可惜啊，现在已经没时间再看以前的卷宗喽，很多案子都点名要我支援，忙得喘不过气啊…也没办法嘛。足够优秀的侦探，案子会自己找上门来。\", \"voicelineId\": 59032, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解鹿野院平藏·其五\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_friendship_05\", \"description\": \"面对犯罪的时候，侦探已经失败了。无论怎样还原真相，找出真正的犯人，都无法挽回事件发生造成的损失。所以，我才会想要扩大自己的名声，成为能让坏人想想就感到害怕的名侦探！也就是，扼杀犯罪在摇篮之中。好了，既然把这一点都告诉你了，就快来一起帮我的忙吧。\", \"voicelineId\": 59033, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"鹿野院平藏的爱好…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_pref_hobby\", \"description\": \"要来旁听天领奉行的法庭判决吗？看着真相就像碎裂的剪贴画一样被拼接完整…我可以替你占个绝好的观看席位。我们只要装作不认识就行了，装作。\", \"voicelineId\": 59034, \"voicelineType\": \"6001\"}, {\"title\": \"鹿野院平藏的烦恼…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_dialog_annoyed\", \"description\": \"总有人在最后关头暴力反抗，好像那就会管用一样。真是的，我明明期待的是对方在完整的证据和推理面前，认罪伏法的样子。侦探要是动手，不就已经输了吗。\", \"voicelineId\": 59035, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_pref_foodLike_01\", \"description\": \"被油炸过的食物就没有不好吃的吧？不管是肉还是蔬菜，只要是从油锅里捞上来的，我都爱吃！而且…这种香味，对那些饿肚子的人来说，也很难拒绝得了吧。\", \"voicelineId\": 59036, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_pref_foodDislike\", \"description\": \"我很讨厌奉行所的晚饭，总是固定的菜品，规规矩矩的，味道也说不上好。食物嘛，要想吃什么就能吃到什么才会开心。可怜的我，就只能溜出去垫肚子喽。\", \"voicelineId\": 59037, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_spice_pref_01\", \"description\": \"喔…好吃好吃！费了不少力气吧，太谢谢你啦。\", \"voicelineId\": 59065, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_spice_normal_01\", \"description\": \"烹饪该算体力活还是脑力活呢，或许都算吧，难怪你能做得这么好！\", \"voicelineId\": 59066, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_spice_dislike_01\", \"description\": \"让我想想…你是在哪个步骤出错了…\", \"voicelineId\": 59067, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_pref_birthday_01\", \"description\": \"在知道今天是你的生日之后，有那么一瞬间，我想把你带到一间摆满了机关与礼物的密室里，让你解出谜题后再出来…嘿嘿，开玩笑的啦，在确认你是否喜欢之前，我是不会这么做的。来，和我一起走吧，趁着太阳还没落山，有非常漂亮的景色想和你分享哦！\", \"voicelineId\": 59038, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_starUp_01\", \"description\": \"我的直觉告诉我…你想让我变强！\", \"voicelineId\": 59039, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_starUp_02\", \"description\": \"武力是增加了，脑力也有这样的增幅就好了…\", \"voicelineId\": 59040, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_starUp_03\", \"description\": \"哎呀呀，我真要变成大家口中的「风暴」了。\", \"voicelineId\": 59041, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_heizou/vo_heizou_starUp_04\", \"description\": \"谢谢你对我的信任和付出，我的搭档，能做到这一步多亏了你。来击掌吧，接下来也一起去解开更多的谜团！\", \"voicelineId\": 59042, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_battle_skill1_04\", \"description\": \"吃拳！\", \"voicelineId\": 59043, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_battle_skill1_05\", \"description\": \"别抵赖！\", \"voicelineId\": 59044, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_battle_skill1_06\", \"description\": \"来吧！\", \"voicelineId\": 59045, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_battle_skill3_01\", \"description\": \"认罪吧！\", \"voicelineId\": 59046, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_battle_skill3_02\", \"description\": \"风暴！\", \"voicelineId\": 59047, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_battle_skill3_03\", \"description\": \"破开迷雾！\", \"voicelineId\": 59048, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_chest_open_01\", \"description\": \"别让宝物翻箱出逃哦~\", \"voicelineId\": 59049, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_chest_open_02\", \"description\": \"就是这个，我的直觉不错吧？\", \"voicelineId\": 59050, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_chest_open_03\", \"description\": \"哇，好耀眼！\", \"voicelineId\": 59051, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_life_less30_01\", \"description\": \"唉，就非要动武吗？\", \"voicelineId\": 59052, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_life_less30_02\", \"description\": \"好猖狂哦。\", \"voicelineId\": 59053, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_life_less30_03\", \"description\": \"这在侦探的职能以外了吧？\", \"voicelineId\": 59054, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_life_less30_teammate_01\", \"description\": \"哎呀呀，小心哦！\", \"voicelineId\": 59055, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_life_less30_teammate_02\", \"description\": \"事关重大，换我来。\", \"voicelineId\": 59056, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_life_die_01\", \"description\": \"这不是真相…\", \"voicelineId\": 59057, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_life_die_02\", \"description\": \"呵，侦探变成受害人了…\", \"voicelineId\": 59058, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_life_die_03\", \"description\": \"我竟然会…失算…\", \"voicelineId\": 59059, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_battle_hit_L_02\", \"description\": \"别这样。\", \"voicelineId\": 59060, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_heizou/vo_heizou_battle_hit_H_02\", \"description\": \"真麻烦！\", \"voicelineId\": 59061, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_heizou_teamJoin_01\", \"description\": \"有新案子？\", \"voicelineId\": 59062, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_heizou_teamJoin_02\", \"description\": \"遇上难题了？和我说说。\", \"voicelineId\": 59063, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_heizou_teamJoin_03\", \"description\": \"出发吧，我的搭档。\", \"voicelineId\": 59064, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000060, 'Yelan', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_draw_appear\", \"description\": \"你好，旅行者，叫我夜兰就好。我想你或许会需要我的帮助，我恰好也对你所拥有的情报感兴趣。总之，让我们友好相处，互帮互助吧。\", \"voicelineId\": 60000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·线报\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_character_idle_01\", \"description\": \"线人来信了，嗯，看来又出现了新的变数。\", \"voicelineId\": 60001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·翘班\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_character_idle_02\", \"description\": \"点数不错，今天就继续翘班吧，等到状态好了，再去把活一次干完。\", \"voicelineId\": 60002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·身份\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_character_idle_03\", \"description\": \"在这世间行走，「身份」多一点才便利。需要我帮你捏造一些吗？\", \"voicelineId\": 60003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_weather_heavyRain_01\", \"description\": \"又下雨了？真是麻烦啊…痕迹一旦被雨水冲刷干净，就需要不少时间来还原了…\", \"voicelineId\": 60004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_weather_thunder_01\", \"description\": \"在打雷时会感到害怕的，要么是纯真的孩子，要么是心虚之人。你应该两者都不算吧？\", \"voicelineId\": 60005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_weather_snowy_01\", \"description\": \"有点冷嘛…不能把外套披在肩上了。\", \"voicelineId\": 60006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_weather_sunny_01\", \"description\": \"刺眼的阳光，好烦人啊。这样一来，我可没法打盹了。\", \"voicelineId\": 60007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_weather_gale_01\", \"description\": \"风里传来了躁动不安的情绪…嗯…\", \"voicelineId\": 60008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_greetingMorning\", \"description\": \"…嗯~这么早？没有必要的工作时，我习惯中午起床。\", \"voicelineId\": 60009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_greetingNoon\", \"description\": \"啊，有点困了，小睡一会儿吧，不用提醒我，到了工作时间，我自然会醒的。\", \"voicelineId\": 60010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_greetingNight\", \"description\": \"晚上好啊，晚饭吃了吗？吃了点什么？啊…我就随口问问，不要太在意。\", \"voicelineId\": 60011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_greetingNight2\", \"description\": \"把牛奶喝了，乖乖睡吧。嗯？你说你不是小孩子？呵呵…那就放在这里，喝不喝随便你了。我的话，一般会在后半夜入睡。万一你有讲梦话的习惯，我不能保证不把它们记下来哦。\", \"voicelineId\": 60012, \"voicelineType\": \"1004\"}, {\"title\": \"关于夜兰自己·职责\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_idle\", \"description\": \"七星对璃月各地的情况了如指掌，但总有一些情报需要通过特殊手段去收集。我算是这方面的行家，所以这类差事基本被我包揽了。\", \"voicelineId\": 60013, \"voicelineType\": \"2001\"}, {\"title\": \"关于夜兰自己·传闻\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_idle2\", \"description\": \"有人说，岩上茶室的现任老板是个一夜暴富的年轻商人；有人说，总务司有位体虚多病的高等雇员，隐居在城外；还有人说，不要接近涉密地区，会被蓝色的鬼魂缠上…当然，大多普通人完全没听说过「夜兰」这个名字。所以你把那些传闻当成笑话听就好。\", \"voicelineId\": 60014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·关系\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_close\", \"description\": \"嗯？你那是什么表情？跟我相处不用这么警惕，我啊，从来不算计自己认可的人。\", \"voicelineId\": 60015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·欺骗\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_close1\", \"description\": \"别过分期待他人的「肺腑之言」，滑头鬼只会说你爱听的话；也别轻易迎接他人的目光，眼神最容易出卖一个人的情绪。我们怎么说都是朋友，要是你被人骗，我也会有种吃了哑巴亏的感觉呢。\", \"voicelineId\": 60016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_pendant\", \"description\": \"重要情报所在的地点，往往隐藏着致命的杀机，无论有多少可靠的部下，都无法彻底排除风险，足够破局的武力才是关键。我还算走运，至少在悟出这个道理后几天，就获得了「神之眼」。否则，站在这里和你聊天的…就是蓬头垢面的鬼魂了。\", \"voicelineId\": 60017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·屏蔽噪音\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_share_01\", \"description\": \"仔细打磨鳅鳅宝玉后，可以将它当成耳塞，隔音效果很不错，哪怕有人在你耳边嘶声哀嚎，都不会打扰你的美梦。当然，希望你以后不必用到这种东西。\", \"voicelineId\": 60018, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·幽奇腕阑\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_share_02\", \"description\": \"右手的镯子？告诉你也无妨…它蕴含着我们家族的术法，能传递简单的信息。至于信息的含义，都隐藏在这蓝光中，只有我能看懂。\", \"voicelineId\": 60019, \"voicelineType\": \"3004\"}, {\"title\": \"有什么想要分享·追踪目标\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_share_03\", \"description\": \"在追踪目标时，我一般倾向于给对方施加心理压力。在试图摆脱我的过程中，他们会阵脚大乱、搬救兵、改变计划…直到把自己的老底都交待出来。呵…\", \"voicelineId\": 60020, \"voicelineType\": \"3005\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_pref_gift_01\", \"description\": \"你了解盗宝鼬吗？它们的智力平平，但经过人为驯化后，也能熟练地重复偷盗，甚至开锁撬锁。多鲜活的例子啊——只要方法得当，连动物都能作为趁手的棋子，勾心斗角的人们又何尝不是如此？\", \"voicelineId\": 60021, \"voicelineType\": \"3003\"}, {\"title\": \"关于凝光·关系\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_teammate_ningguang_01\", \"description\": \"我跟凝光认识得早，那时她还不是七星，我们合作了一段时间。她能提前当上七星，说不定也有我的功劳。呵，谁知道呢？总之，现在这份工作是她推荐给我的。确实不错，很适合我。\", \"voicelineId\": 60022, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光·期待\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_teammate_ningguang_02\", \"description\": \"凝光是个不错的合作对象。不过我平日在外行走，得注意身份。总务司雇员见到七星，难免要尊称一声大人了。\", \"voicelineId\": 60023, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_teammate_ganyu_01\", \"description\": \"那位秘书啊…我不可能像她那样，时刻不停地工作。何况她的效率同样无可挑剔。半仙的血统大概给了她不少便捷吧，不用睡觉也能保持精力。\", \"voicelineId\": 60024, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_teammate_keqing_01\", \"description\": \"我不太喜欢把日程排得很满的人，他们没有给自己留下调整的余地，只要碰上意外，就会手忙脚乱，连累同僚。但「玉衡」不同，她总是有条不紊地办事，每次与她共事，都令我相当愉快。\", \"voicelineId\": 60025, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于烟绯…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_teammate_yanfei_01\", \"description\": \"烟绯啊，我还挺喜欢她的。不谈以前的交情，作为鼎鼎有名的律法咨询师，她是璃月港内诸多情报的交汇点。每次帮她搞定麻烦，我都能顺带收获珍贵的线索。但她似乎对我有些敬重过度了。\", \"voicelineId\": 60026, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_teammate_xiao_01\", \"description\": \"家族的长辈们曾说，要对「护法夜叉」保持最大的敬畏。据说我那疯疯癫癫的先祖路过望舒客栈时，都会少见地安分下来，想必是被他那驱除邪祟的威压给照顾了。但若是有一天，我有幸与那位「降魔大圣」并肩作战，我还是会以任务为重，不可能因为他的身份而有所顾忌。\", \"voicelineId\": 60027, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_teammate_xiangling_01\", \"description\": \"香菱啊，讨人喜欢的小厨师，挑选食材的标准完全不输琉璃亭和新月轩。有时我会去她那里买些风干后的绝云椒椒。她似乎不理解我吃辣的方式，我也不想和她解释，这是家族的传统。\", \"voicelineId\": 60028, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_teammate_xingqiu_01\", \"description\": \"我当然记得他，飞云商会家的小少爷。我经常和他们家来往。也许以后，他也会成为眼观六路的能人呢？\", \"voicelineId\": 60029, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于达达利亚…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_teammate_tartaglia_01\", \"description\": \"那位愚人众的执行官？他在无意中给我带来了一些好处。我原本打算彻查「岩上茶室」的前任老板，但那位执行官下手更快，强硬地上门讨债，还公开了前任老板做的假账，让他获罪入狱。我也因此顺利接管了岩上茶室，得到了一个不错的据点。\", \"voicelineId\": 60030, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夜兰·其一\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_friendship_01\", \"description\": \"愿意在你身上下注，是考虑到你身份特殊，应当能为我找来不少通往「真相」的线索。呵，今天带来什么消息了吗？\", \"voicelineId\": 60031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解夜兰·其二\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_friendship_02\", \"description\": \"交换情报讲究平等，和你讲些往事也无妨。托家族的福，我从千岩军的斥候那里学到了一些本事，挺早就入行了。虽然收集情报的过程会受到各种阻挠，但只要丢不掉性命，最后的赢家，总归是我…\", \"voicelineId\": 60032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夜兰·其三\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_friendship_03\", \"description\": \"线索是一环扣一环的，沿着它们不断追查到一切的根源，才算是个了结。为此，我有必要将耳目散布到各行各业去。在这个过程中，难免就要扮演各种角色。有些人形容我「一人千面」，这种说法，我就当成夸奖收下了。\", \"voicelineId\": 60033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夜兰·其四\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_friendship_04\", \"description\": \"有人告诫过我，贸然探查某些往事，有可能惹来杀身之祸。呵，我可不想停下，更不会因为别人的话就停下。哪怕无法改变事实，我也绝不能待在迷雾中。你呢？你的选择会是什么？\", \"voicelineId\": 60034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夜兰·其五\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_friendship_05\", \"description\": \"说起来，你希望陪伴在你身边的我，是怎样的人？普通的合作对象？磨砺你的竞争对手？众多泛泛之交中的一位…还是说…重要的伙伴？依你的期望和态度，我可以「扮演」或「成为」他们中的任何人。\", \"voicelineId\": 60035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"夜兰的爱好…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_pref_hobby\", \"description\": \"闲暇之时，我会随机安排生活。方法很简单：列一张清单，投骰子来决定接下来要做的事。这种消遣能带来意想不到的乐趣，还能让我拓宽思维的边界，对于我的本职工作而言，也算有不小的帮助。\", \"voicelineId\": 60036, \"voicelineType\": \"6001\"}, {\"title\": \"夜兰的烦恼…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_dialog_annoyed\", \"description\": \"相较于一些武人，我的体能其实不算太好，这是家族遗传的毛病。处理某些不能怠慢的工作前，我会调整作息，积蓄精力，争取一次完事收工。除此之外的时间里，我会尽量保持悠哉的节奏。所以，体力活我会谢绝的。\", \"voicelineId\": 60037, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_pref_foodLike_01\", \"description\": \"将风干后的绝云椒椒和琉璃袋的花蕊一同研磨成粉，均匀混合在云来白毫之中，沏一壶酽茶，它馥郁的香气必定会让你沉醉。相比咖啡和烈酒，我更偏好这种回味悠长的饮品。\", \"voicelineId\": 60038, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_pref_foodDislike\", \"description\": \"对于甜食，可得保持警惕啊。那种强烈的满足感…会削弱人的意志力，让人放松警惕。只要吃过几次，就有可能上瘾。长期吃甜食的人，或许会在不知不觉中变得迟钝吧。\", \"voicelineId\": 60039, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_spice_pref_01\", \"description\": \"嗯，手艺不错，差点就要被你贿赂成功了。\", \"voicelineId\": 60068, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_spice_normal_01\", \"description\": \"吃惯辣味之后，其他菜总觉得不够劲。没办法啊。\", \"voicelineId\": 60069, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_spice_dislike_01\", \"description\": \"投个骰子吧？点数比我小的话…就你来吃？\", \"voicelineId\": 60070, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_pref_birthday_01\", \"description\": \"要是在这种日子里，我还警告你「别因为庆祝而松懈，会被人趁机暗算」，可就太不解风情了。总之，今天你可以尽情放松。来「岩上茶室」坐坐，尝尝我为你特意准备的点心吧？当然，点心不甜，只是微微辣。\", \"voicelineId\": 60040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_starUp_01\", \"description\": \"在我的工作中，战斗技巧从来不可或缺。\", \"voicelineId\": 60041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_starUp_02\", \"description\": \"唯有在必要时刻快准狠地出手，才能揭露某些谎言，排除沿途的干扰。\", \"voicelineId\": 60042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_starUp_03\", \"description\": \"探索「真相」听来简单，实则需要长期咬住线索的毅力，还有深入险境的实力。\", \"voicelineId\": 60043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_yelan/vo_yelan_starUp_04\", \"description\": \"我早已将你当成最为重要的线人。自然就要作好万全的准备，迎接你为我带来终极答案时附带的风险。走吧，我们去把它拿下！\", \"voicelineId\": 60044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_battle_skill1_01\", \"description\": \"收。\", \"voicelineId\": 60045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_battle_skill1_02\", \"description\": \"抓到了。\", \"voicelineId\": 60046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_battle_skill1_03\", \"description\": \"别喊疼。\", \"voicelineId\": 60047, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_battle_skill3_01\", \"description\": \"终场~收工！\", \"voicelineId\": 60048, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_battle_skill3_02\", \"description\": \"丝线，交织。\", \"voicelineId\": 60049, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_battle_skill3_03\", \"description\": \"点数如何呢？\", \"voicelineId\": 60050, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_explore_sprint_start_01\", \"description\": \"不必心急。\", \"voicelineId\": 60051, \"voicelineType\": \"700001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_chest_open_01\", \"description\": \"取财有方。\", \"voicelineId\": 60052, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_chest_open_02\", \"description\": \"宝箱，也能引蛇出洞。\", \"voicelineId\": 60053, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_chest_open_03\", \"description\": \"散落的财物，无声的线索。\", \"voicelineId\": 60054, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_life_less30_01\", \"description\": \"有点扫兴…\", \"voicelineId\": 60055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_life_less30_02\", \"description\": \"不能敷衍了事呢…\", \"voicelineId\": 60056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_life_less30_03\", \"description\": \"新的变数…\", \"voicelineId\": 60057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_life_less30_teammate_01\", \"description\": \"点到为止，你退下。\", \"voicelineId\": 60058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_life_less30_teammate_02\", \"description\": \"残局，让我来吧。\", \"voicelineId\": 60059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_life_die_01\", \"description\": \"哪一步…算错了？\", \"voicelineId\": 60060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_life_die_02\", \"description\": \"这种失误…不合理…\", \"voicelineId\": 60061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_life_die_03\", \"description\": \"真相…还没揭晓…\", \"voicelineId\": 60062, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_battle_hit_L_02\", \"description\": \"真有胆量。\", \"voicelineId\": 60063, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_yelan/vo_yelan_battle_hit_H_01\", \"description\": \"不对…\", \"voicelineId\": 60064, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_yelan_teamJoin_01\", \"description\": \"咬住目标了？\", \"voicelineId\": 60065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_yelan_teamJoin_02\", \"description\": \"去收网吧。\", \"voicelineId\": 60066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_yelan_teamJoin_03\", \"description\": \"走吧，去打听点新消息。\", \"voicelineId\": 60067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000061, 'Kirara', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_draw_appear_01\", \"description\": \"你好，我叫绮良良，稻妻「狛荷屋」的快递员。你放心，没有什么快递是我送不到的！什么？我的尾巴？哦，因为我是只妖怪嘛！被称作「猫又」的妖怪。\", \"voicelineId\": 61000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·包裹\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_character_idle_01\", \"description\": \"唔…包裹里装了什么呢？好好奇…不行不行，不能看客户的东西。\", \"voicelineId\": 61001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·订单\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_character_idle_02\", \"description\": \"让我看看订单…走吧走吧，下一个目的地还很远呢。\", \"voicelineId\": 61002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·工作\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_character_idle_03\", \"description\": \"哇！这里的景色真不错。嘿嘿，我算是选对工作了。\", \"voicelineId\": 61003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_weather_heavyRain_01\", \"description\": \"唔…！毛都湿掉了，你也要个箱子躲一躲吗？\", \"voicelineId\": 61004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_weather_thunder_01\", \"description\": \"喵嗷！呼…吓…吓得我都不会说人话了。\", \"voicelineId\": 61005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_weather_snowy_01\", \"description\": \"好冷，尾巴要冻成冰棍了…还是待在屋里烤火更舒服，只要离火盆远一些，毛就不会被烧焦了吧？\", \"voicelineId\": 61006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_weather_sunny_01\", \"description\": \"阳光真好啊，要是再有棵树的话…唔，想想都困了…\", \"voicelineId\": 61007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_weather_gale_01\", \"description\": \"呜啊！小包裹要被吹走了！\", \"voicelineId\": 61008, \"voicelineType\": \"1205\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_weather_desert_01\", \"description\": \"沙粒挤到肉垫里了…好奇怪的触感…\", \"voicelineId\": 61009, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_greetingMorning\", \"description\": \"早上好！看你还没醒，我就先去弄了些吃的。哎呀放心，不是小松鼠小团雀什么的。虽然那些也挺好吃…\", \"voicelineId\": 61010, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_greetingNoon\", \"description\": \"啊——等我再睡一会儿…尾巴…尾巴都抬不起来了…\", \"voicelineId\": 61011, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_greetingNight\", \"description\": \"晚上好，我已经准备好出发了。欸？你说该去睡觉了？可我现在正是最清醒的时候呀，赶路可快了，视野又清晰，路上人又少。\", \"voicelineId\": 61012, \"voicelineType\": \"1003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_greetingNight2\", \"description\": \"晚安，祝你有个好梦！不过…没有尾巴烦你的话，你应该天天做的都是美梦吧？\", \"voicelineId\": 61013, \"voicelineType\": \"1004\"}, {\"title\": \"关于绮良良自己·肉垫\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_idle\", \"description\": \"我的鞋子？哦，那就是我的脚啦。虽然我也能用妖力变出人类的脚，但果然还是要有肉垫和爪子，走起路来才安心嘛！呃…不行！不能摸！会很痒的！\", \"voicelineId\": 61014, \"voicelineType\": \"2001\"}, {\"title\": \"关于绮良良自己·名字\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_idle2\", \"description\": \"我的名字是奶奶给我取的。在我还没长出两条尾巴的时候，奶奶就经常挠挠我下巴，摸摸我头，夸我眼睛亮晶晶的，很好看。\", \"voicelineId\": 61015, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·旅行\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_close\", \"description\": \"你会到处旅行，而我则是到处送货。你不觉得这很像吗？都是从一个地方跑到另一个地方。不过，我花的是公司的钱，你花的是自己的…欸？没…没有！我没有在得意！\", \"voicelineId\": 61016, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·相遇\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_close1\", \"description\": \"送快递的工作让我认识了各式各样的人。有人成为了「狛荷屋」的回头客，有人和我交上了朋友。真好啊。每个包裹都有终点，但彼此的故事却可以一直延续下去。人与妖怪结下情谊，也不是什么难事嘛。\", \"voicelineId\": 61017, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_pendant\", \"description\": \"我到现在都记得自己第一次用妖力变成人类的感觉。那时我激动极了，想的全是「终于能亲自去人类社会看看了」！等回过神来，它就已经出现在了我的腰间。唔…难道这位神明也和我一样，想要去各种各样的地方吗？\", \"voicelineId\": 61018, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·捕猎\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_share_01\", \"description\": \"人类打造的武器的确不错，但我有时还是想凭自己的本事。当你看到一只小团雀的时候，难道就不想悄悄接近它的身后，趴低身子等待时机…然后「唰」地一下扑上去吗？这种捕猎的成就感，可是比送完一份快递还要开心的呀！\", \"voicelineId\": 61019, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·箱子\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_share_02\", \"description\": \"听奶奶说，这就是我小时候最喜欢钻的那个箱子。说来也有趣，那时只觉得这「狛荷屋」的箱子又大又暖和，如今居然在这儿干活了，身边全是数不清的箱子。哈哈，命运还真是奇妙呢。不过…最近感觉有些挤…啊！不是的！我没有胖！我才不会变成大黄那样子呢！\", \"voicelineId\": 61020, \"voicelineType\": \"3005\"}, {\"title\": \"感兴趣的见闻·树屋\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_pref_gift_01\", \"description\": \"告诉你哦！须弥有好多房子都是造在树上的！我的天，那每天晒太阳得多舒服？甚至不用专门下来觅食了！欸？你说你知道？好吧…那你知不知道它们是怎么造出来的？我上次送货用爪子爬上去都累得半死，那么高的树…当年的须弥人又没有爪子…建材和家具又要怎么运？唔，想不通。\", \"voicelineId\": 61021, \"voicelineType\": \"3003\"}, {\"title\": \"感兴趣的见闻·大房子\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_pref_gift_02\", \"description\": \"这份工作能让我见到好多好多大房子！比奶奶家大多了！都是什么什么宫、什么什么殿…房间多到数不过来。这么大的房子，住起来不会空荡荡的吗？我的话…只要早上有吃饭的地方、中午有晒太阳的地方、晚上再有个小箱子就满足了。哦！是不是有的人就喜欢睡在「大箱子」里？\", \"voicelineId\": 61022, \"voicelineType\": \"3004\"}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_teammate_yaeMiko_01\", \"description\": \"神子大人是稻妻远近闻名的大妖怪。我这样新生的妖怪，难免心生敬畏。但没想到，这位狐妖大人非常和蔼可亲，不仅主动来见我，还教会了我很多有用的知识。比如人类社会的礼仪、与人交往的方法、还有油豆腐的炸法什么的…咦？你说最后那个不知道也行？\", \"voicelineId\": 61023, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_teammate_raidenShogun_01\", \"description\": \"送到天守阁的快递都包装得特别精美，里三层外三层的。该说不愧是献给那位将军大人的吗…不过，里面装的到底是什么呢？有时还会散发出香香的味道…\", \"voicelineId\": 61024, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鹿野院平藏…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_teammate_heizou_01\", \"description\": \"我跟那位侦探在很久以前打过交道。他知道我是「猫又」之后，找过我帮忙打听离家出走的猫猫们去了哪儿。我刚开始还挺乐意的，但后来听到猫猫说什么「就是想到外面走走嘛」、「回去后好无聊啊」什么的，有些心软，就谎称没见过它们。可是那位侦探，好像看得出我在说谎。\", \"voicelineId\": 61025, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_teammate_kujouSara_01\", \"description\": \"我一直想找那位天狗大人聊聊天。可她是天领奉行的大将，一直都是充满威严的模样，到现在我都只敢趴在远远的地方看她。我…我就是好奇她的翅膀啦。平时会觉得不方便吗？还有那些掉下来的羽毛怎么办？唔…要是拿来垫在箱子里的话，睡起来一定很舒服吧？\", \"voicelineId\": 61026, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_teammate_itto_01\", \"description\": \"他明明是只鬼，却和人类混得那么熟，还有自己的帮派！唔，好厉害啊。我是不是也该向他请教请教呢？\", \"voicelineId\": 61027, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_teammate_lyney_01\", \"description\": \"我在枫丹见过一位魔术师，他能把各种东西变不见，还能把各种东西变出来！他用的一定也是妖力吧？一定是这样吧？这么说…他也是只妖怪？\", \"voicelineId\": 61028, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于千织…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_teammate_chiori_01\", \"description\": \"千织姐对我很好，以前经常遇见她外出研究布料的做法和配色。虽然她一直很担心我会抓坏那些衣料，但它们那么漂亮，我根本舍不得啦。她现在在枫丹开了家店，有时也会叫我去送货。嘿嘿，我身上这套衣服就是她帮我改良的。\", \"voicelineId\": 61029, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解绮良良·其一\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_friendship_01\", \"description\": \"在我还是一只小猫的时候，奶奶和我讲过很多很多故事。什么稻妻的妖怪啦、城里的庆典啦、其他国家的美食啦什么的…我就这么在奶奶腿上趴着，听着听着就睡着了。到现在，我都不知道哪些是真的故事，哪些是我的梦。\", \"voicelineId\": 61030, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解绮良良·其二\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_friendship_02\", \"description\": \"我喜欢这份工作，很适合我。而且，那位狐妖大人说过，要是不工作的话，是没法在人类社会待下去的。这可不行！我会送好每一份快递，我…我才不要回那个荒郊野岭做什么大妖怪呢！\", \"voicelineId\": 61031, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解绮良良·其三\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_friendship_03\", \"description\": \"大概是以为我看起来比较好欺负吧，我送货时，遇到过好多想来抢劫的盗贼。但他们无一例外全被我给打跑了！不过我没有用全力。毕竟…要是打伤了人算到公司头上的话，我可是会被开除的呀！\", \"voicelineId\": 61032, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解绮良良·其四\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_friendship_04\", \"description\": \"每到一个新城市，我总喜欢爬到高高的地方，俯瞰那里的景色。有时街道吹起微风，花瓣们就像一只只晶蝶一样从这头飘到那头；有时太阳落下，城市里就会亮起灯火，从高处看去，就像正午树荫下活泼的小光点。要不是赶着送货，我简直能趴上一天。哎，真想带老家的奶奶来看看这些。\", \"voicelineId\": 61033, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解绮良良·其五\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_friendship_05\", \"description\": \"享受生活是很重要的！我的话，会在长途旅行的最后几天，或是刚刚完成工作的那个晚上，找个最热闹的餐馆美餐一顿，再选个最舒服的屋顶趴着吹风，直到困了再香香甜甜地睡去…世上这么多值得细细品味的快乐，不好好享受可就亏大了！所以，我总是把每条鱼都啃得干干净净，也很好理解吧！\", \"voicelineId\": 61034, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"绮良良的爱好…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_pref_hobby\", \"description\": \"我喜欢到各个地方送货。只要收货地址是我没去过的地方，我就会激动得睡不着觉，恨不得马上出发。小时候身边全是林子灌木，看都看腻了。但外面我没见过的东西数都数不清。每个地方都充满了新鲜感！\", \"voicelineId\": 61035, \"voicelineType\": \"6001\"}, {\"title\": \"绮良良的烦恼…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_dialog_annoyed\", \"description\": \"尽管人类的生活丰富多样，但规矩也太多了。「不能在房檐上睡觉」、「不能抓景观池里的鱼」、「不能随便磨爪子」…但只要我变成原本的模样，就不会有人来管我这些。坏处就是「猫又」的身份有些显眼，还不方便进饭店点好吃的。\", \"voicelineId\": 61036, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_pref_foodLike_01\", \"description\": \"还是只猫的时候，我最喜欢奶奶做的饭，一次能闷头吃下一大碗！现在的话…嗯，果然还是刺身拼盘吧！又嫩又鲜的鱼肉直接端到面前，都不用我自己挑刺和去鳞了！就是每次啃鱼头的时候，店家总会用奇怪的眼神看着我。\", \"voicelineId\": 61037, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_pref_foodDislike\", \"description\": \"有次我在海边捉鱼，没注意身后，被一只螃蟹夹住了尾巴，疼死我了！当时还以为要断掉了呢。你说螃蟹这东西，肉又少，壳又厚，用爪子都打不开，有什么好吃的？哦对了，烫的东西我也受不了。当我听说有道菜叫「黄油蟹蟹」的时候，简直不敢相信！这听起来就又烫又硬的菜，到底要怎么吃啊？\", \"voicelineId\": 61038, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_spice_pref_01\", \"description\": \"哇…是从没尝过的味道，太好吃了吧！你…你不会是司掌料理的大妖怪吧？\", \"voicelineId\": 61039, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_spice_normal_01\", \"description\": \"唔~！好吃！还有吗还有吗？我想带点儿路上吃！\", \"voicelineId\": 61040, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_spice_dislike_01\", \"description\": \"想起了从前在野外流浪的日子…\", \"voicelineId\": 61041, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_pref_birthday_01\", \"description\": \"生日快乐！不管是人还是妖怪，来到这个世界都是一件值得庆祝的事！如果你愿意的话，待会儿带你去我小时候生活的地方看看。虽然不是什么热闹有趣的地方，但总让我觉得很安心。我还可以把最喜欢的箱子让给你，躺在里面很舒服的！\", \"voicelineId\": 61042, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_starUp_01\", \"description\": \"哦！好像妖力提升了！\", \"voicelineId\": 61043, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_starUp_02\", \"description\": \"咦？是不是尾巴也长长了一点？\", \"voicelineId\": 61044, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_starUp_03\", \"description\": \"身体变得更轻了！感觉能一口气送十份快递！\", \"voicelineId\": 61045, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_kirara/vo_kirara_starUp_04\", \"description\": \"哇，我现在的妖力，说不定连那个狐妖大人也…啊哈哈…还是算了，我也不想去比什么。只要能守护好每一份客户的快递，我就满足了。当然…还有一直陪伴着我的你。对了，要不要来摸摸我的尾巴？我真的感觉它们变长了欸！\", \"voicelineId\": 61046, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_battle_skill1_01\", \"description\": \"嘿咻！\", \"voicelineId\": 61047, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_battle_skill1_02\", \"description\": \"挠你哦！\", \"voicelineId\": 61048, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_battle_skill1_03\", \"description\": \"借过！\", \"voicelineId\": 61049, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_battle_skill3_01\", \"description\": \"快递到喽。\", \"voicelineId\": 61053, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_battle_skill3_02\", \"description\": \"记得好评。\", \"voicelineId\": 61054, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_battle_skill3_03\", \"description\": \"请您签收，喵。\", \"voicelineId\": 61055, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_chest_open_01\", \"description\": \"哇，好多没见过的东西！\", \"voicelineId\": 61056, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_chest_open_02\", \"description\": \"是谁掉的包裹吗？\", \"voicelineId\": 61057, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_chest_open_03\", \"description\": \"这箱子能钻吗？\", \"voicelineId\": 61058, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_life_less30_01\", \"description\": \"得保护好包裹…\", \"voicelineId\": 61059, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_life_less30_02\", \"description\": \"找找其他路…\", \"voicelineId\": 61060, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_life_less30_03\", \"description\": \"喵…\", \"voicelineId\": 61061, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_life_less30_teammate_01\", \"description\": \"快躲到箱子里！\", \"voicelineId\": 61062, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_life_less30_teammate_02\", \"description\": \"让我来帮你一手！\", \"voicelineId\": 61063, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_life_die_01\", \"description\": \"快递…送不到了…\", \"voicelineId\": 61064, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_life_die_02\", \"description\": \"想缩回…箱子里…\", \"voicelineId\": 61065, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_life_die_03\", \"description\": \"要被…开除了…\", \"voicelineId\": 61066, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_battle_hit_L_01\", \"description\": \"疼！\", \"voicelineId\": 61067, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_battle_hit_H_01\", \"description\": \"我的尾巴！\", \"voicelineId\": 61068, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_kirara/vo_kirara_battle_hit_H_02\", \"description\": \"包裹要紧！\", \"voicelineId\": 61069, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_kirara_teamJoin_01\", \"description\": \"有什么快递要送吗？\", \"voicelineId\": 61070, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_kirara_teamJoin_02\", \"description\": \"感谢选择「狛荷屋」！\", \"voicelineId\": 61071, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_kirara_teamJoin_03\", \"description\": \"公费出游？我去我去！\", \"voicelineId\": 61072, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000062, 'Aloy', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_draw_appear\", \"description\": \"我是埃洛伊，虽然对这个世界还不太了解，但我的弓和箭随时为你所用。如果你的队伍需要我，我会倾力相助。\", \"voicelineId\": 62001, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·动身\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_character_idle_01\", \"description\": \"别闲站着了，该动身了。\", \"voicelineId\": 62002, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·帮助\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_character_idle_02\", \"description\": \"现在不该停留，还有人需要我们帮助。\", \"voicelineId\": 62003, \"voicelineType\": \"1102\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_weather_heavyRain_01\", \"description\": \"雨，可以洗净脏污。\", \"voicelineId\": 62004, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_weather_afterRain_01\", \"description\": \"雨停了，该把自己晾一晾了。\", \"voicelineId\": 62005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_weather_snowy_01\", \"description\": \"下雪时，似乎整个世界都静下来了。\", \"voicelineId\": 62006, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_weather_breezy_01\", \"description\": \"又起风了，在风中呼吸的感觉真不错。\", \"voicelineId\": 62007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_weather_gale_01\", \"description\": \"风烈起来了，刮得脸上生疼。\", \"voicelineId\": 62008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_dialog_greetingMorning\", \"description\": \"早上好。世界又充满了活力，我也一样。\", \"voicelineId\": 62009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_dialog_greetingNoon\", \"description\": \"日已过半，我们还有不少事要忙。\", \"voicelineId\": 62010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_dialog_greetingNight\", \"description\": \"太阳落山了，再过不久星星就要出来了。\", \"voicelineId\": 62011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_dialog_greetingNight2\", \"description\": \"晚上好。该休息了，除非你想借着星光继续行动。\", \"voicelineId\": 62012, \"voicelineType\": \"1004\"}, {\"title\": \"关于埃洛伊自己…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_dialog_idle\", \"description\": \"我从小就是个流放者，那段日子很不好过。但在这里，即便是对待我这样的外人，大家也比我所降生的那个部落友好的多。感觉…很好。\", \"voicelineId\": 62013, \"voicelineType\": \"2001\"}, {\"title\": \"关于我们·行动\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_dialog_close\", \"description\": \"我的一切行动都是为了拯救生命，而非带来死亡。这就是我与你并肩战斗的原因。\", \"voicelineId\": 62014, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·誓约\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_dialog_close1\", \"description\": \"立誓什么的，有点太循规蹈矩了。不过如果你想要我的誓约，那我的誓言与你同在。\", \"voicelineId\": 62015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·前进\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_dialog_close2\", \"description\": \"我会尽全力与你一起前进，直到终点。我不会踌躇，也不会辜负。\", \"voicelineId\": 62016, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_dialog_share_01\", \"description\": \"如果说有什么可以分享的话，那一定是我的弓与箭，我只为扶助他人而使用。\", \"voicelineId\": 62017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_pref_gift\", \"description\": \"和我那边的世界一样，这片天地的过去也充满了秘密。如果能有足够的时间，我一定要把一切秘密都揭开。\", \"voicelineId\": 62018, \"voicelineType\": \"3003\"}, {\"title\": \"想要了解埃洛伊·其一\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_friendship_01\", \"description\": \"我不太擅长谈论自己的事情，眼下的任务才是重点。\", \"voicelineId\": 62019, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解埃洛伊·其二\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_friendship_02\", \"description\": \"我没有父母，是一个叫罗斯特的男人抚养我长大的。他有点严厉，不过心肠很好，也很大方。他教了我很多东西，嗯…我很想他。\", \"voicelineId\": 62020, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解埃洛伊·其三\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_friendship_03\", \"description\": \"以前，我花了很多时间在寻找我的生母，却没能找到「她」。取而代之的是，我找到了一些远古的留言，是我的…「克隆母体」留下的。听着那些留言，我觉得她似乎很了解我，也很会鼓励我。\", \"voicelineId\": 62021, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解埃洛伊·其四\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_friendship_04\", \"description\": \"在成长的过程中，我没有什么朋友。虽然后来在旅途中认识了一些人，但当我离开那个世界时，我和他们的关系还称不上熟络。所以，能和你一同度过这么多时间，成为朋友，我真的很开心。\", \"voicelineId\": 62022, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解埃洛伊·其五\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_friendship_05\", \"description\": \"我不会轻易信任他人，但我确定你是可以信任的。你是我真正的伙伴，我可不经常这样评价别人。\", \"voicelineId\": 62023, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"埃洛伊的爱好…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_pref_hobby\", \"description\": \"我不太清楚自己有什么爱好，「阅读古物」算一个吧。嗯，那就…历史？\", \"voicelineId\": 62024, \"voicelineType\": \"6001\"}, {\"title\": \"埃洛伊的烦恼…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_dialog_annoyed\", \"description\": \"除了我自己的世界，现在又多了一个世界需要拯救。唔…时间总是不够用。\", \"voicelineId\": 62025, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_pref_foodLike\", \"description\": \"我不挑食。只要不饿着肚子旅行，吃什么都行。\", \"voicelineId\": 62026, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_pref_foodDislike\", \"description\": \"我吃过一次「奥斯拉姆炖肉」，稠得都能当沥青铺路了，呕。\", \"voicelineId\": 62027, \"voicelineType\": \"6004\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_pref_birthday\", \"description\": \"我从来不怎么在意生日。在我出生的世界，大家都会纪念母亲，没人庆祝自己的生日。不过先不管那些。嗯…祝你生日快乐。\", \"voicelineId\": 62028, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_starUp_01\", \"description\": \"很好，咱们进展不错。但可不能止步于此。\", \"voicelineId\": 62029, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_starUp_02\", \"description\": \"有所成长，变得更强了，是件好事。\", \"voicelineId\": 62030, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_starUp_03\", \"description\": \"无论现在是多精湛的猎手，总还能更进一步。不要因为自满而止步，不要停止学习。\", \"voicelineId\": 62031, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_aloy/vo_aloy_starUp_04\", \"description\": \"我们刚开始搭伴旅行时，对我而言，你还只是一个陌生人，来自我所不熟悉的世界。但既然如今我们已经一同经历了这么多，我可以向你保证：我的弓永远与你同在。\", \"voicelineId\": 62032, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_battle_skill1_01\", \"description\": \"这玩意是会炸的。\", \"voicelineId\": 62033, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_battle_skill1_02\", \"description\": \"猎手的小玩具。\", \"voicelineId\": 62034, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_battle_skill1_03\", \"description\": \"见过这个吗？\", \"voicelineId\": 62035, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_battle_skill3_01\", \"description\": \"禁锢！\", \"voicelineId\": 62036, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_battle_skill3_02\", \"description\": \"一点新技巧。\", \"voicelineId\": 62037, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_battle_skill3_03\", \"description\": \"这里是我的猎场！\", \"voicelineId\": 62038, \"voicelineType\": \"200003\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_explore_fly_start_01\", \"description\": \"这玩意用着还不错。\", \"voicelineId\": 62039, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_chest_open_01\", \"description\": \"嗯…算是些有用的东西。\", \"voicelineId\": 62040, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_chest_open_02\", \"description\": \"这些能吃…这些能用…\", \"voicelineId\": 62041, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_chest_open_03\", \"description\": \"这些，到底是谁留在这的呢…\", \"voicelineId\": 62042, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_life_less30_01\", \"description\": \"棘手的猎物…\", \"voicelineId\": 62043, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_life_less30_02\", \"description\": \"弱点在哪…\", \"voicelineId\": 62044, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_life_less30_03\", \"description\": \"大意了…\", \"voicelineId\": 62045, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_life_less30_teammate_01\", \"description\": \"当心！\", \"voicelineId\": 62046, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_life_less30_teammate_02\", \"description\": \"别太冒进！\", \"voicelineId\": 62047, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_life_die_01\", \"description\": \"哪里…出了错…\", \"voicelineId\": 62048, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_life_die_02\", \"description\": \"抱歉…\", \"voicelineId\": 62049, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_life_die_03\", \"description\": \"失败的狩猎…\", \"voicelineId\": 62050, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_battle_hit_L_01\", \"description\": \"唔…\", \"voicelineId\": 62051, \"voicelineType\": \"900001\"}, {\"title\": \"普通受击·其二\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_battle_hit_L_02\", \"description\": \"小问题…\", \"voicelineId\": 62052, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_battle_hit_H_01\", \"description\": \"呃！\", \"voicelineId\": 62053, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_aloy/vo_aloy_battle_hit_H_02\", \"description\": \"有点麻烦…\", \"voicelineId\": 62054, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_aloy_teamJoin_01\", \"description\": \"这次要去哪转转？\", \"voicelineId\": 62055, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_aloy_teamJoin_02\", \"description\": \"埃洛伊，加入狩猎。\", \"voicelineId\": 62056, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_aloy_teamJoin_03\", \"description\": \"需要帮手吗？\", \"voicelineId\": 62057, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000063, 'Shenhe', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_draw_appear\", \"description\": \"我名申鹤，命格孤煞，易伤身边人，仙人叮嘱要以此红绳锁魂，控制杀心。若你不畏惧与我同行…很好，就请伸出手来吧。\", \"voicelineId\": 63000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·归宿\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_character_idle_01\", \"description\": \"人间的归宿是一种奢望，我早已习惯跟山川与鸟兽作伴了。\", \"voicelineId\": 63001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·要诀\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_character_idle_02\", \"description\": \"回向正道，保身护命…\", \"voicelineId\": 63002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·刀枪无眼\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_character_idle_03\", \"description\": \"刀枪无眼，红绳的力量也有极限，所以我才不喜欢人多的地方。\", \"voicelineId\": 63003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_weather_heavyRain_01\", \"description\": \"按照凡人的做法，这种时候，是否应该…撑伞？\", \"voicelineId\": 63004, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_weather_afterRain_01\", \"description\": \"天气变好，我也很开心。只希望没有人来打扰…如果有，就让他们消失好了。\", \"voicelineId\": 63005, \"voicelineType\": \"1202\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_weather_thunder_01\", \"description\": \"把魔物冻在原地，雷劈下来就能瞬间解决它们，还不会让衣服沾上尘土。\", \"voicelineId\": 63006, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_weather_gale_01\", \"description\": \"嗯…师父最喜欢庆云顶上的罡风。\", \"voicelineId\": 63007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_greetingMorning\", \"description\": \"早安。晨露很甜，要分一点给你吗？\", \"voicelineId\": 63008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_greetingNoon\", \"description\": \"若是午后困乏，不妨试试打坐养神，很有效果。\", \"voicelineId\": 63009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_greetingNight\", \"description\": \"不知道你是喜欢人间的灯火，还是山林的月光？\", \"voicelineId\": 63010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_greetingNight2\", \"description\": \"放心休息吧，我睡眠很浅，有什么动静，我会替你查看的。\", \"voicelineId\": 63011, \"voicelineType\": \"1004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于申鹤自己·本能\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_idle\", \"description\": \"磨砺自身，修炼方术，都是本能使然，想要保全自己而已。我没有兼济苍生的胸怀，惩奸除恶只是顺手，不必感谢我。\", \"voicelineId\": 63012, \"voicelineType\": \"2001\"}, {\"title\": \"关于申鹤自己·异类\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_idle2\", \"description\": \"受我恩惠的人叫我仙人，被我惩罚的人喊我魔女，呵…不管是仙是魔，终究都是跟凡人不同的异类罢了…\", \"voicelineId\": 63013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·待人接物\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_close\", \"description\": \"我很少下山，不懂得多少待人接物的道理。发生冲突的时候，我一律按自己的方式处理。但，如果你觉得不妥，都请告诉我，即使不理解，我也会听你的。\", \"voicelineId\": 63014, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·红绳\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_close1\", \"description\": \"师父赐我红绳用以压制心性，但这些日子你我同修，我才真正领悟到要诀，力量收放也更自在…你才是真正能锁住我的红绳。若你懂得这份心情，就请留在我身旁。\", \"voicelineId\": 63015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1101505], \"unlockText\": \"完成「风起鹤归」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_pendant\", \"description\": \"原来这颗闪耀的石头叫做「神之眼」？呵…有缘既得，无缘便失。日后倘若缘分消散，它也会熄灭吧。\", \"voicelineId\": 63016, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_share_01\", \"description\": \"邪祟易驱，心魔难除。若自身无法放下执念，仙法与术式都无从挽回。\", \"voicelineId\": 63017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_pref_gift_01\", \"description\": \"为什么说「初雪多浪漫」？那处山巅日日下雪，何日才算是初雪？我不理解，请你告诉我。\", \"voicelineId\": 63018, \"voicelineType\": \"3003\"}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_ningguang_01\", \"description\": \"人们所谓的财富，对我而言没什么用。但到了凝光小姐手里，却能解决连刀枪都无法处理的难题。她能掌握人间规则，洞察人心…师父说，这些连仙人都无法做到。我很佩服她。\", \"voicelineId\": 63019, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_beidou_01\", \"description\": \"与她相处不用讲究礼节，交谈时也不用揣测深意，让我轻松了不少。只是…她身边总是有人，听说船上还有诸多船员…我需要跟你一起，才能应对人多的场合。\", \"voicelineId\": 63020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于云堇…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_yunjin_01\", \"description\": \"云堇唱的…叫做「璃月戏」吧？我很喜欢这种形式。不必亲见其面，就能了解他人的事迹。如果将来她把你唱进戏里，那一定会是非常精彩的故事，我很期待。\", \"voicelineId\": 63021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_ganyu_01\", \"description\": \"我从师父那里听过许多有关她的事…她原先在我心中的形象，和实际差距还是挺大的。放心，我不会说出去。说起来，璃月港的工作竟这般繁忙…看来融入人间，也要付出一些代价。\", \"voicelineId\": 63022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于重云…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_chongyun_01\", \"description\": \"真没想到我在这世上…还有「亲缘」。他若是有什么修行上的困惑，我愿帮忙解答。不过，得请他上山来。他们一家太过热情，我不知道该如何回绝才符合礼数…\", \"voicelineId\": 63023, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_xingqiu_01\", \"description\": \"我曾见到他凑在你耳旁不知说些什么。若他敢威胁你，我一定会将他…嗯？只是朋友间的玩闹话？当真如此吗…\", \"voicelineId\": 63024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_zhongli_01\", \"description\": \"那位先生自称是凡人，却与身为仙人的师父很熟络。师父曾说，如果碰见他在仙府前的石凳上饮酒，莫要打扰，让他静静独坐一会。我照做了。\", \"voicelineId\": 63025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于白术…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_baizhu_01\", \"description\": \"他的药草品质很好，为人也随和周到。相比起来，脖子上的小蛇倒是口无遮拦…放心，我没有动手。我还不至于和一条蛇置气。\", \"voicelineId\": 63026, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_hutao_01\", \"description\": \"她在附近山林游荡时，经常会唱奇怪的歌。久而久之，我把她的歌断断续续听了个遍。听习惯了也还是觉得奇怪，但，我并不讨厌。\", \"voicelineId\": 63027, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_xiao_01\", \"description\": \"印象中他一直不苟言笑。近来见他，虽说沉默依旧，但…像是比从前轻松了不少。兴许是结识了哪位良人吧。\", \"voicelineId\": 63028, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于闲云…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_teammate_xianyun_01\", \"description\": \"上回，师父带漱玉来万民堂吃饭，漱玉言谈间已有了几分师父的神形…我也是在师父的呵护下如此成长，不知道我的举止，是否也带着些师父的样子呢…\", \"voicelineId\": 63072, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11035], \"unlockText\": \"完成「千里月明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解申鹤·其一\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_friendship_01\", \"description\": \"请不必在意人们对我的称呼，我不是仙人，也没什么神通。生于驱魔世家的旁系，长在远离璃月港的山间，只能算是个仙家弟子，仅此而已。\", \"voicelineId\": 63029, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解申鹤·其二\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_friendship_02\", \"description\": \"遇到恶意滋事的人，人们似乎都会选择上前说教，我不太明白。明明可以直接将这些拦路碍事、心存歹念的恶人斩草除根，为什么要这般麻烦？\", \"voicelineId\": 63030, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解申鹤·其三\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_friendship_03\", \"description\": \"我师从多位仙家，静心修炼。随着修为提升，他们不再传授我新的术式，而是改教我怎样收敛杀性。别紧张…像平地凿出深坑，树木连根拔起之类的事，只在远离人烟的山林中发生过，从未波及过无辜性命。况且，现在我也已经能控制自我了。\", \"voicelineId\": 63031, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解申鹤·其四\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_friendship_04\", \"description\": \"父亲想用我的血肉换回母亲的生命。自从被他丢在山洞，我一度期盼过他会回来救我。一天、两天、三天…我拼尽全力与魔物厮杀，直到倒下都没能等到他。我不知道，究竟是我命格孤煞才遭人遗弃，还是命途坎坷使得我萌生出这股煞气？\", \"voicelineId\": 63032, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1101505], \"unlockText\": \"完成「风起鹤归」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解申鹤·其五\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_friendship_05\", \"description\": \"有一回，我瞒着师父偷偷下山回到村里，却发现原本的村庄荒弃了，父亲早已去世。我突然明白，自己与血亲的缘分彻底断绝了。在乎的往事永无后话。自那日起，我一度舍弃人间种种…直到遇见你。\", \"voicelineId\": 63033, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1101505], \"unlockText\": \"完成「风起鹤归」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"申鹤的爱好…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_pref_hobby\", \"description\": \"打坐的要点在于「静」，需要摒弃杂念，用身体感受周遭气息，它能让我迅速回归自我。听师父说，修为达到足够境界后，打坐的姿势就不用再拘泥，仙人哪怕站立着都能打坐…我还远远不够。\", \"voicelineId\": 63034, \"voicelineType\": \"6001\"}, {\"title\": \"申鹤的烦恼…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_dialog_annoyed\", \"description\": \"害怕失去重要之人、想要拯救重要之人…这种心情会将整颗心紧紧揪住，以前从未体会过。这是困扰，但…也是寄托。\", \"voicelineId\": 63035, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_pref_foodLike\", \"description\": \"下山期间尝了不少菜，但都不太记得味道了。唯独从前在家吃的那碗面，永远忘不了…不该记住才对，不该记住才对…\", \"voicelineId\": 63036, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_pref_foodDislike\", \"description\": \"药草嚼得久了，只剩苦味与涩味…修行多年，我早已习惯这些清规戒律了。仙人们？「仙人不会被人间俗物阻碍修为，所以可以敞开吃各式菜肴。」…这是师父的原话。\", \"voicelineId\": 63037, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_spice_pref_01\", \"description\": \"这般滋味…真的是我能够享受的吗？\", \"voicelineId\": 63069, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_spice_normal_01\", \"description\": \"你做的饭菜，确实美味。无法割舍。\", \"voicelineId\": 63070, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_spice_dislike_01\", \"description\": \"也好。这样的味道，我早就熟悉了。\", \"voicelineId\": 63071, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_pref_birthday_01\", \"description\": \"我听说生辰是个值得铭记的日子，人们会向寿星送上礼品以示庆贺。身外之物，我不太了解。银河夜色，是我在山林中见过最美丽的事物。我将湖面冻成明镜，让浮云和星斗映照在眼前，跟你共贺生辰…希望你喜欢。\", \"voicelineId\": 63038, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_starUp_01\", \"description\": \"我能操控的力量…愈发强大了。\", \"voicelineId\": 63039, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_starUp_02\", \"description\": \"师父若知道了，怕是会让我多系几根红绳吧…\", \"voicelineId\": 63040, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_starUp_03\", \"description\": \"这段日子，我闭关修炼的时长有所削减，修为却不知不觉地增进…嗯，也许只有跟你一起才能做到。\", \"voicelineId\": 63041, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_shenhe/vo_shenhe_starUp_04\", \"description\": \"「心无杂念，方可超然」，这是我从前所想。经历种种才明白，唯有心存牵挂，才能唤醒守护的欲望，让力量…变得有意义。\", \"voicelineId\": 63042, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_skill1_01\", \"description\": \"听令！\", \"voicelineId\": 63043, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_skill1_02\", \"description\": \"显！\", \"voicelineId\": 63044, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_skill1_03\", \"description\": \"魂出！\", \"voicelineId\": 63045, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_skill1_04\", \"description\": \"炼气化神！\", \"voicelineId\": 63046, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_skill1_05\", \"description\": \"意生冰身！\", \"voicelineId\": 63047, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_skill1_06\", \"description\": \"付君真形！\", \"voicelineId\": 63048, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_skill3_01\", \"description\": \"天真敕奏！\", \"voicelineId\": 63049, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_skill3_02\", \"description\": \"寒冰变神！\", \"voicelineId\": 63050, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_skill3_03\", \"description\": \"依律奉行！\", \"voicelineId\": 63051, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_chest_open_01\", \"description\": \"这就是凡间的宝物吧。\", \"voicelineId\": 63052, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_chest_open_02\", \"description\": \"与仙人法宝有何区别？\", \"voicelineId\": 63053, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_chest_open_03\", \"description\": \"这些东西…该用到何处？\", \"voicelineId\": 63054, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_life_less30_01\", \"description\": \"休要怪我…\", \"voicelineId\": 63055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_life_less30_02\", \"description\": \"我不甘心…\", \"voicelineId\": 63056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_life_less30_03\", \"description\": \"必须…诛除！\", \"voicelineId\": 63057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_life_less30_teammate_01\", \"description\": \"不必勉强。\", \"voicelineId\": 63058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_life_less30_teammate_02\", \"description\": \"我来了结。\", \"voicelineId\": 63059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_life_die_01\", \"description\": \"难逃…宿命…\", \"voicelineId\": 63060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_life_die_02\", \"description\": \"死丧既定…\", \"voicelineId\": 63061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_life_die_03\", \"description\": \"劫煞为灾…\", \"voicelineId\": 63062, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_hit_L_02\", \"description\": \"不成气候。\", \"voicelineId\": 63063, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_hit_H_01\", \"description\": \"休想！\", \"voicelineId\": 63064, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_shenhe/vo_shenhe_battle_hit_H_02\", \"description\": \"别后悔！\", \"voicelineId\": 63065, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_shenhe_teamJoin_01\", \"description\": \"团队作战…是什么意思？\", \"voicelineId\": 63066, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_shenhe_teamJoin_02\", \"description\": \"明白，站在这里就行了是吧。\", \"voicelineId\": 63067, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_shenhe_teamJoin_03\", \"description\": \"…听君敕令。\", \"voicelineId\": 63068, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000064, 'Yun Jin', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_draw_appear\", \"description\": \"有道是闻名不如见面，今天终于有缘与你相会，实属荣幸。我姓云，单名一个堇字，不才正是云翰社当家主事的人。我们戏社最近挂靠在和裕茶馆，日后还请多多赏光，常来听戏。\", \"voicelineId\": 64000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·敏感话题\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_character_idle_01\", \"description\": \"这两天总觉得身上腰封有点紧，难道…我胖了？\", \"voicelineId\": 64001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·闲适\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_character_idle_02\", \"description\": \"不勒头，不画脸，今天乐得清闲。\", \"voicelineId\": 64002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·清唱\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_character_idle_03\", \"description\": \"云婵娟来花婵娟，风流尽在山水间。\", \"voicelineId\": 64003, \"voicelineType\": \"1103\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_weather_thunder_01\", \"description\": \"…嘶，你听、听见打雷没有？吓我一跳。\", \"voicelineId\": 64004, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_weather_snowy_01\", \"description\": \"喂呀，冻煞我了。\", \"voicelineId\": 64005, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_weather_sunny_01\", \"description\": \"暖阳和煦，真是好风光呀。\", \"voicelineId\": 64006, \"voicelineType\": \"1203\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_greetingMorning\", \"description\": \"早，清晨露水正好煎茶，喝完这杯茶再出发吧。\", \"voicelineId\": 64007, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_greetingNoon\", \"description\": \"午饭吃完之后，想睡一觉…哈…你不困吗？\", \"voicelineId\": 64008, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_greetingNight\", \"description\": \"一道去听听晚场说书吧，刘苏先生讲《裁雨声》是一绝。\", \"voicelineId\": 64009, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_greetingNight2\", \"description\": \"夜里寒气重，早点歇息，晚安。\", \"voicelineId\": 64010, \"voicelineType\": \"1004\"}, {\"title\": \"关于云堇自己·开蒙\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_idle\", \"description\": \"我开蒙早，刚记事的时候父亲就在教我读书了。可惜，他的本事要是有十分，我恐怕只学到了三分。写戏是够用了，但要和饱学之士相比，还差得太远。\", \"voicelineId\": 64011, \"voicelineType\": \"2001\"}, {\"title\": \"关于云堇自己·坐科\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_idle2\", \"description\": \"我母亲早年是璃月港内大有名气的角儿，我学的戏都是她教的。你是不知道她有多严厉，一想起以前学戏的经历…不不不，我还是别想了。\", \"voicelineId\": 64012, \"voicelineType\": \"2005\"}, {\"title\": \"关于我们·搭班\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_close\", \"description\": \"最近有几场大戏，正好缺一位擅长舞剑的演员，我觉得你各方面都挺适合。怎么样，有兴趣搭班吗？休息时，还能一起品茶。\", \"voicelineId\": 64013, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·摇滚\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_close1\", \"description\": \"欸，你还听摇滚？正好正好，下回我想出去听演唱会的时候，就找你一块去。回来的时候，我就说是拜访你去了，这下戏社里的老人肯定找不到借口唠叨我。\", \"voicelineId\": 64014, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_pendant\", \"description\": \"这神之眼嘛…说不定岩王爷也喜欢听戏呢？大概他老人家听得开心，就把神之眼送给我了，哈哈。\", \"voicelineId\": 64015, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·饮品\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_share_01\", \"description\": \"我最喜欢尝试各种各样的饮品。老一辈发明的那些讲究茶饮，什么松间露呀梅上雪的，都让我试了个遍。现在正愁没有新饮品可以喝呢，欸，你有什么推荐吗？\", \"voicelineId\": 64016, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·心愿\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_share_02\", \"description\": \"我偶尔也想脱下戏服，远游海外，去更大的世界看看。为了实现这个心愿，得更加努力才行。\", \"voicelineId\": 64017, \"voicelineType\": \"3004\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_pref_gift_01\", \"description\": \"每天天刚破晓就能听见莺雀鸣啭，心情总能变得很好。\", \"voicelineId\": 64018, \"voicelineType\": \"3003\"}, {\"title\": \"关于辛焱…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_teammate_xinyan_01\", \"description\": \"戏社里那几个老人天天念叨，说是听多了摇滚会被带坏，不让我去听辛焱的演唱会。嘴上说着为我好，哼，我看他们只是接受不了新事物而已。我才不会听他们的，辛焱的演唱会我每周都要去，就是这样。\", \"voicelineId\": 64019, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_teammate_hutao_01\", \"description\": \"胡桃她呀，表情丰富，脑筋还转得快，哪怕只是聊些家常都能「妙语连珠」。真让人羡慕。和这样的朋友在一起，无论做什么事情都很有趣。\", \"voicelineId\": 64020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_teammate_zhongli_01\", \"description\": \"我们这行的规矩代代相传，讲究多得很。有些事我只知其然，却不知其所以然。但钟离先生讲起这些竟能如数家珍，有这样懂行的观众，谁不开心呢？\", \"voicelineId\": 64021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_teammate_ningguang_01\", \"description\": \"天权星出手阔绰，没少资助我们戏社。领了她的情，自然也要回报给她最好的演出。\", \"voicelineId\": 64022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_teammate_xingqiu_01\", \"description\": \"原来你也认识行秋。哈哈，他聪明得很，鬼主意那么多，怕是一不留神就会捉弄你，可得留个心眼啊。\", \"voicelineId\": 64023, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于申鹤…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_teammate_shenhe_01\", \"description\": \"《神女劈观》的剧本我早就念得烂熟，但直到今天我才知道「神女」原来真有其人，世上缘分果然奇妙。惟愿她往后都有好友相伴，不再孤寂。\", \"voicelineId\": 64024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1101505], \"unlockText\": \"完成「风起鹤归」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_teammate_keqing_01\", \"description\": \"我倒没见过玉衡星来听戏。印象里，路边偶遇这位时，她也总是一副行色匆匆的样子。\", \"voicelineId\": 64025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_teammate_kazuha_01\", \"description\": \"爱听戏的外国人士也有不少，这位枫原万叶就是其中之一。不论台上演的是文场还是武场，他总是安安静静地听，是个规矩的好观众。\", \"voicelineId\": 64026, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解云堇·其一\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_friendship_01\", \"description\": \"我们戏社现在常唱的几出戏，有不少是我当家之后新写出来的。写也是我，唱也是我，一人多职，大概是因为这一点，我在璃月港有了些名气。\", \"voicelineId\": 64027, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解云堇·其二\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_friendship_02\", \"description\": \"按照传统，伶人登台之前要勒头、画脸、穿行头，还有其他一些零碎的准备工作。虽然这样「全副武装」之后扮相会更好看，但也累人。所以我能清唱时就清唱，非得彩唱的话，我往往会挑轻便点的行头。\\n幸好和我们戏社长期合作的和裕茶馆管得宽松，要不然我真是要累惨了。\", \"voicelineId\": 64028, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解云堇·其三\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_friendship_03\", \"description\": \"当初我刚登台唱戏，凭着观众抬爱，不免有些心高气傲。戏本不喜欢就不唱，戏台子小了也不唱，观众少了还是不唱。现在想来，那时候可真是…太傲慢了…以后万万不能这样。\", \"voicelineId\": 64029, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解云堇·其四\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_friendship_04\", \"description\": \"回想起来，云翰社传到我手上也有段时间了。原本我只懂得写戏、唱戏，从来没把心思放在经营交际上。做了戏社的当家之后，才不得不在这些事上多长点心眼，因此体味到不少人情冷暖…\\n这时候我才真知道，人生如戏，戏如人生啊。\", \"voicelineId\": 64030, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解云堇·其五\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_friendship_05\", \"description\": \"璃月多传说，大都是些魔神、仙人故事，所以璃月戏里最多的就是神仙戏。最近新演的《神女劈观》就属此类。虽然老戏迷们最爱听的就是这类故事，但如今是「人」的时代，我想多写些属于人类的故事，把天下人心唱给大家听。\\n这些想法，过去我不曾向人提起。多谢你能耐心听我说这些。有一知音，我很幸运。\", \"voicelineId\": 64031, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"云堇的爱好…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_pref_hobby\", \"description\": \"爱好？当然是戏了。我是打定主意要唱一辈子的。\", \"voicelineId\": 64032, \"voicelineType\": \"6001\"}, {\"title\": \"云堇的烦恼…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_dialog_annoyed\", \"description\": \"烦恼…唉，为了保持体型，我平时一口都不能多吃。人生在世，连美食都不能奢求，真是遗憾哪。\", \"voicelineId\": 64033, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_pref_foodLike\", \"description\": \"天枢肉、水煮黑背鲈、干锅腊肉…我都想吃。可惜平时基本吃不了，那个…我就随便问一问，你…会做这几道菜吗？\", \"voicelineId\": 64034, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_pref_foodDislike\", \"description\": \"天天都是清炒虾仁，天天都是…再怎么做都还是那个味道，我是真的吃腻了。\", \"voicelineId\": 64035, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_spice_pref_01\", \"description\": \"美食，总会让人倍感幸福…可惜只能点到为止，不能再多吃了。\", \"voicelineId\": 64066, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_spice_normal_01\", \"description\": \"看着就很丰盛！稍等，我去找些饮品来，配着饭菜一起享用吧。\", \"voicelineId\": 64067, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_spice_dislike_01\", \"description\": \"不好意思…这道菜肴呀，我是吃不了多少的。\", \"voicelineId\": 64068, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_pref_birthday_01\", \"description\": \"原来今天是你的生日吗？我没有置办宴席的本事，只能为你唱一曲了。不过，这一曲只为你一个人唱，要听什么？你来定。\", \"voicelineId\": 64036, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_starUp_01\", \"description\": \"俗语说：「业精于勤而荒于嬉。」\", \"voicelineId\": 64037, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_starUp_02\", \"description\": \"勤学苦练至今，总算是有了些成果。\", \"voicelineId\": 64038, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_starUp_03\", \"description\": \"学枪一事，原先是为了台上舞枪好看，后来是为了掌握傍身武技。如今这两个目标都已达到。\", \"voicelineId\": 64039, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_yunjin/vo_yunjin_starUp_04\", \"description\": \"枪术千变万化，奥妙无比，让我庆幸的是，练枪时一直有你相伴。我已经领悟到其中旨要。往后切磋时，你可得小心了。\", \"voicelineId\": 64040, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_skill1_01\", \"description\": \"着！\", \"voicelineId\": 64041, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_skill1_02\", \"description\": \"崩！\", \"voicelineId\": 64042, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_skill1_03\", \"description\": \"旗来！\", \"voicelineId\": 64043, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_skill1_04\", \"description\": \"飞云旗！\", \"voicelineId\": 64044, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_skill1_05\", \"description\": \"看枪！\", \"voicelineId\": 64045, \"voicelineType\": \"100005\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_skill3_01\", \"description\": \"听我号令！\", \"voicelineId\": 64046, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_skill3_02\", \"description\": \"勠力同心！\", \"voicelineId\": 64047, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_skill3_03\", \"description\": \"一鼓作气！\", \"voicelineId\": 64048, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_chest_open_01\", \"description\": \"我来瞧瞧。\", \"voicelineId\": 64049, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_chest_open_02\", \"description\": \"是旅行中用得上的物资吗？\", \"voicelineId\": 64050, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_chest_open_03\", \"description\": \"别客气，你收着就行。\", \"voicelineId\": 64051, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_life_less30_01\", \"description\": \"别把裙子弄坏了…\", \"voicelineId\": 64052, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_life_less30_02\", \"description\": \"得重整旗鼓才行。\", \"voicelineId\": 64053, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_life_less30_03\", \"description\": \"哼，好戏在后面。\", \"voicelineId\": 64054, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_life_less30_teammate_01\", \"description\": \"你先下场。\", \"voicelineId\": 64055, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_life_less30_teammate_02\", \"description\": \"我来救场。\", \"voicelineId\": 64056, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_life_die_01\", \"description\": \"曲终…人散…\", \"voicelineId\": 64057, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_life_die_02\", \"description\": \"罢了…\", \"voicelineId\": 64058, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_life_die_03\", \"description\": \"没办法…唱下去了…\", \"voicelineId\": 64059, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_hit_L_02\", \"description\": \"要沉住气…\", \"voicelineId\": 64060, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_hit_H_01\", \"description\": \"有点狼狈…\", \"voicelineId\": 64061, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_yunjin/vo_yunjin_battle_hit_H_02\", \"description\": \"下手好重…\", \"voicelineId\": 64062, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_yunjin_teamJoin_01\", \"description\": \"走——了——\", \"voicelineId\": 64063, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_yunjin_teamJoin_02\", \"description\": \"今天该唱哪出呢？\", \"voicelineId\": 64064, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_yunjin_teamJoin_03\", \"description\": \"你叫我，我当然要来了。\", \"voicelineId\": 64065, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000065, 'Kuki Shinobu', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_draw_appear\", \"description\": \"你好，我是荒泷派的二把手久岐忍。我们承包多种业务，货运物流、安保维持、房屋补漏、表演驻唱等等。需要我们请随时联系，这是我的名片，还请收下。\", \"voicelineId\": 65000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·麻烦事\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_character_idle_01\", \"description\": \"有麻烦事要处理的话，直接告诉我就好，我来摆平。\", \"voicelineId\": 65001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·证书\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_character_idle_02\", \"description\": \"执业证书考试都有固定评判标准，肯学肯练就能考过，没什么难的。\", \"voicelineId\": 65002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·荒泷派\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_character_idle_03\", \"description\": \"要是荒泷派犯了事，我会揪他们去认错的。\", \"voicelineId\": 65003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_weather_heavyRain_01\", \"description\": \"不用打伞了，腿脚快点就行。\", \"voicelineId\": 65004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_weather_thunder_01\", \"description\": \"当心点。这种天，应该没人会想引雷上身吧？\", \"voicelineId\": 65005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_weather_snowy_01\", \"description\": \"快点把事情办完就撤吧，别浪费时间。\", \"voicelineId\": 65006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_weather_sunny_01\", \"description\": \"嗯，天气真好，但总有种不祥的预感…希望是我多虑了吧。\", \"voicelineId\": 65007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_weather_gale_01\", \"description\": \"唔…这风还算不错。\", \"voicelineId\": 65008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_greetingMorning\", \"description\": \"早啊，看你的样子是准备去锻炼了？没想到你还挺勤快的。\", \"voicelineId\": 65009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_greetingNoon\", \"description\": \"想吃什么？最近攒了不少钱，午饭我请你。\", \"voicelineId\": 65010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_greetingNight\", \"description\": \"有些委托，在夜晚才好办。我不放心交给他们，都是我亲自上。\", \"voicelineId\": 65011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_greetingNight2\", \"description\": \"该休息的时候就去休息吧，不用管我。\", \"voicelineId\": 65012, \"voicelineType\": \"1004\"}, {\"title\": \"关于久岐忍自己·二把手\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_idle\", \"description\": \"招揽业务、维系成员安定是我的职责，除此之外还有——去奉行所捞人，归还零食和玩具，抓捕接了活却在暗处偷懒的成员…不过，这些额外工作属于荒泷派特色，其他任何组织的二把手，理论上都不需要做这些。当然，也做不到像我这样。\", \"voicelineId\": 65013, \"voicelineType\": \"2001\"}, {\"title\": \"关于久岐忍自己·退路\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_idle2\", \"description\": \"你说帮派解散？首先，那种事应该不会发生。其次，就算发生了，我有什么好担心的呢。饿肚子的人不可能是我。\", \"voicelineId\": 65014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·笔记\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_close\", \"description\": \"要是你心血来潮想考什么证，不如直接找我吧，我把笔记借你。备注和要点很详细，不愁你学不会。\", \"voicelineId\": 65015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·善后\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_close1\", \"description\": \"不管你是不是荒泷派的人，我都不会把你当外人。你就往前走吧，幕后的工作交给我。放心，这方面我是专业的，多复杂的事都能办妥。嗯？担心我的安危？呵，这方面你也放心吧，这些年的摸爬滚打，不是白经历的。\", \"voicelineId\": 65016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_pendant\", \"description\": \"和证书一样，这是对我能力的肯定和证明。但不同的是，我至今不知道它的考核标准。\", \"voicelineId\": 65017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·面铠\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_share_01\", \"description\": \"戴上面铠是不想被熟人认出来。尤其和荒泷派一起出任务时，要是熟人看见了，指指点点，那群家伙肯定会趁机起哄。啧，光是想想，就很烦。不能再有下次了…咳，没什么。\", \"voicelineId\": 65018, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·派中法度\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_share_02\", \"description\": \"我制定了荒泷派的「派中法度」，他们就应该谨遵法度行事。嗯？你问他们为什么愿意听话？因为我比他们更有说服力。我的语言和拳头，姑且还算是有点分量。\", \"voicelineId\": 65019, \"voicelineType\": \"3005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_pref_gift_01\", \"description\": \"神社中流传着一种说法，将鸣草织成一个圈缠在身上，就能祛灾祈福，你信吗？我倒觉得，鸣草，还是麻痹效果更实用。\", \"voicelineId\": 65020, \"voicelineType\": \"3003\"}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_teammate_raidenShogun_01\", \"description\": \"解除锁国后，雷电将军陆续颁布了不少法令支持各行各业的发展。我在锁国期间考的证书全都派上了用场，荒泷派也不那么拮据了。祸福相依，没想到到头来还得感谢她。\", \"voicelineId\": 65021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1204209], \"unlockText\": \"完成「须臾百梦」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_teammate_kujouSara_01\", \"description\": \"九条小姐啊，她是我的朋友。嗯？我认识她让你觉得很意外吗？噢，你可能误会了，我加入荒泷派之前就跟她有交情。我们俩的切磋，还难分胜负呢。\", \"voicelineId\": 65022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_teammate_yaeMiko_01\", \"description\": \"就连堂堂鸣神大社的宫司大人，都要靠副业来解闷，可见当巫女是有多无聊。我是绝对不会回去当巫女的。\", \"voicelineId\": 65023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_teammate_itto_01\", \"description\": \"老大有很多不算愉快的过去，却还能保持快乐阳光，挺难得的。他对我们很不错，他的纯粹也感染着荒泷派的大家。当然，这不能成为他横冲直撞影响别人的借口。如果他找你麻烦，尽管告诉我。我会好好收拾他，让他后悔对你无礼。\", \"voicelineId\": 65024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于烟绯…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_teammate_yanfei_01\", \"description\": \"那时候跟家里闹翻了，只想着有多远逃多远，就跑去璃月学律法了。得亏这样，有幸认识了烟绯师姐。在律法咨询这块，她简直就是活字典。我？执业证书倒是有的，不过这个职业的约束也不少，并不是最适合我的。\", \"voicelineId\": 65025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于鹿野院平藏…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_teammate_heizou_01\", \"description\": \"他和普通天领奉行同心不一样，从未见他做什么巡逻、抓捕的活。他偶尔会找我买线索，作为交换，我希望他能在我去奉行所捞人时帮我美言几句，他也爽快答应了。这笔交易还算值，毕竟让弟兄们收集点市井见闻是很简单的事。\", \"voicelineId\": 65026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解久岐忍·其一\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_friendship_01\", \"description\": \"我做过很多不同的工作，相关的执业证书也有不少。管理方面，带过小型团队，负责人员统筹和资源调配…呃，抱歉，面试多了就说习惯了，别介意。\", \"voicelineId\": 65027, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解久岐忍·其二\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_friendship_02\", \"description\": \"我家是巫女世家，但我不适合当巫女。刚逃出来那会儿，我觉得要多积累，以免没有傍身之技。什么厨师、裁缝、格斗、律法咨询、出版编辑…我都学了。没想到真正进了社会才发现，学的已经完全够用了。\", \"voicelineId\": 65028, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解久岐忍·其三\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_friendship_03\", \"description\": \"你说我社交场合很厉害？呵，毕竟在外流浪了那么久，总得学会察言观色。更何况在多数时候，理亏的那一方都是我们。我不讨厌摆出那些表情，但可以的话，我还是选择不笑的好。\", \"voicelineId\": 65029, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解久岐忍·其四\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_friendship_04\", \"description\": \"刚进荒泷派的时候，老大要我教小弟们怎么打架。所以我上来第一件事，就变成了把他们挨个揍趴下。没想到，一个个鼻青眼肿的，却睁大眼睛，张嘴就叫我「忍姐」，还要我好好带领他们。哼，那时候我就知道这是一群笨蛋。但没关系，笨蛋不会拖我后腿，我会解决一切问题。\", \"voicelineId\": 65030, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解久岐忍·其五\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_friendship_05\", \"description\": \"留在荒泷派是我自己的选择。收拾烂摊子难免令人火大，但他们也给了我无可替代的真诚。最好的东西都先留给我、从不泼我冷水、在我宣布决定后闹哄哄地鼓掌吹口哨…我知道外面对荒泷派的评价不太好，他们自己也不在乎，但我还是想努努力，改变别人对我们的印象。因为，对待「家人」，自己可以偶尔抱怨，但就是不想其他人说他们的不好。\", \"voicelineId\": 65031, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"久岐忍的爱好…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_pref_hobby\", \"description\": \"平时混帮派，闲着也是闲着，经常不小心读完一本书，不小心就把证考了。不也挺好吗？家里问起来，我也没虚度时光，出去谈工作，也算得上有资本。在这个凡事讲究实力的社会里，我这种有证书的混子，到哪里都能吃得饱饭。\", \"voicelineId\": 65032, \"voicelineType\": \"6001\"}, {\"title\": \"久岐忍的烦恼…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_dialog_annoyed\", \"description\": \"以前不想被抓回去当巫女，就决心只靠自己站稳脚跟。至少目前看来，我干得还不错。\", \"voicelineId\": 65033, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_pref_foodLike_01\", \"description\": \"就算刚吃过拉面或者饺子之类很管饱的食物，最后还是想以一小碗米饭结束。米饭好吃，没什么其他原因，有问题吗？\", \"voicelineId\": 65034, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_pref_foodDislike\", \"description\": \"厨师证到手后，我就更加坚定那个从璃月听来的说法：没有难吃的食物，只有不合格的厨师。\", \"voicelineId\": 65035, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_spice_pref_01\", \"description\": \"真不简单。咳…我就再多吃一口。\", \"voicelineId\": 65064, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_spice_normal_01\", \"description\": \"你做的？嗯…这种水平去考个厨师证应该绰绰有余。\", \"voicelineId\": 65065, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_spice_dislike_01\", \"description\": \"我直说吧，你是不是放错调料了？\", \"voicelineId\": 65066, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_pref_birthday_01\", \"description\": \"生日快乐，来，这个鸣草特制飞镖送给你。小心点，嗯，对，要像这样拿…投掷前记得计算弧度。呵呵，看你喜欢我就放心了。哦，别把它当玩具，还是有一定危险性的。想多训练一下的话，我来教你。\", \"voicelineId\": 65036, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_starUp_01\", \"description\": \"基本功不过关，就什么都不用谈了。这就是初级证书的意义。\", \"voicelineId\": 65037, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_starUp_02\", \"description\": \"中级证书到手，已经可以处理大多数麻烦了。有什么麻烦事需要我帮你解决？\", \"voicelineId\": 65038, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_starUp_03\", \"description\": \"高级证书绝不是轻易就能得到的，天赋和实战的累积缺一不可。\", \"voicelineId\": 65039, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_shinobu/vo_shinobu_starUp_04\", \"description\": \"证书只能用来评判技能的专业程度，无法对付出或情感的投入进行量化。你我的交情也不能只用一句感谢来表达，还是用我最擅长的行动来说明一切吧。\", \"voicelineId\": 65040, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_battle_skill1_01\", \"description\": \"鸣草结环！\", \"voicelineId\": 65041, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_battle_skill1_02\", \"description\": \"解厄！\", \"voicelineId\": 65042, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_battle_skill1_03\", \"description\": \"好好站稳了。\", \"voicelineId\": 65043, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_battle_skill3_01\", \"description\": \"给我…安分点！\", \"voicelineId\": 65044, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_battle_skill3_02\", \"description\": \"祈雷…祓除！\", \"voicelineId\": 65045, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_battle_skill3_03\", \"description\": \"别来碍事。\", \"voicelineId\": 65046, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_chest_open_01\", \"description\": \"嗯，积少成多。\", \"voicelineId\": 65047, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_chest_open_02\", \"description\": \"这票也稳了。\", \"voicelineId\": 65048, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_chest_open_03\", \"description\": \"你的了。\", \"voicelineId\": 65049, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_life_less30_01\", \"description\": \"给、我、站、住…\", \"voicelineId\": 65050, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_life_less30_02\", \"description\": \"算是惹怒我了…\", \"voicelineId\": 65051, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_life_less30_03\", \"description\": \"哼，该我了吧…\", \"voicelineId\": 65052, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_life_less30_teammate_01\", \"description\": \"我来善后。\", \"voicelineId\": 65053, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_life_less30_teammate_02\", \"description\": \"行了交给我，别硬撑。\", \"voicelineId\": 65054, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_life_die_01\", \"description\": \"这次…是给人添麻烦了啊…\", \"voicelineId\": 65055, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_life_die_02\", \"description\": \"荒泷派就拜托你了…\", \"voicelineId\": 65056, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_life_die_03\", \"description\": \"这是对我的…侮辱…\", \"voicelineId\": 65057, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_battle_hit_L_02\", \"description\": \"再来。\", \"voicelineId\": 65058, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_battle_hit_H_01\", \"description\": \"等着！\", \"voicelineId\": 65059, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_shinobu/vo_shinobu_battle_hit_H_02\", \"description\": \"找打是吧！\", \"voicelineId\": 65060, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_shinobu_teamJoin_01\", \"description\": \"看我眼色行动。\", \"voicelineId\": 65061, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_shinobu_teamJoin_02\", \"description\": \"这次是什么麻烦？\", \"voicelineId\": 65062, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_shinobu_teamJoin_03\", \"description\": \"希望不是烂摊子。\", \"voicelineId\": 65063, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000066, 'Kamisato Ayato', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_draw_appear\", \"description\": \"此前听绫华屡次提起阁下，不料公务繁忙，直至今日才有机会相见。神里家家主，神里绫人，今后请多指教了。\", \"voicelineId\": 66000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·大少爷\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_character_idle_01\", \"description\": \"好像忘带什么东西了…算了，等想起来的时候再差人送来好了。\", \"voicelineId\": 66001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·收网\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_character_idle_02\", \"description\": \"暗线已经布置妥当，嗯，差不多该收网了…\", \"voicelineId\": 66002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·恶趣味\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_character_idle_03\", \"description\": \"一想起家臣们一脸焦急却又不敢开口阻拦的样子，就忍不住觉得有趣。呵，出来走走是不错。\", \"voicelineId\": 66003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_weather_heavyRain_01\", \"description\": \"暂且先避下雨吧，不必着急，很快就会有人来送伞了。\", \"voicelineId\": 66004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_weather_thunder_01\", \"description\": \"绫华自小害怕打雷，直到家母告诉她雷声是大御所大人的倾诉。从那时起，每逢打雷她都会神色专注，仿佛这样就能听懂大御所大人的言语。\", \"voicelineId\": 66005, \"voicelineType\": \"1202\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_weather_snowy_01\", \"description\": \"如今的雪景，与多年前的那场雪…并无二致。\", \"voicelineId\": 66006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_weather_sunny_01\", \"description\": \"能悠闲晒太阳的时间可不多。\", \"voicelineId\": 66007, \"voicelineType\": \"1204\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_weather_breezy_01\", \"description\": \"有些「突发情况」，看似细小如微风，却会影响到最终结果…呵呵。\", \"voicelineId\": 66008, \"voicelineType\": \"1205\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_weather_gale_01\", \"description\": \"大多数人会因为大风迷眼而止步不前，只有少部分人能够借势而为。\", \"voicelineId\": 66009, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_greetingMorning\", \"description\": \"早上好。清晨适宜练剑，放松身心。我一般不会让人安排公务。如何？要过上几招么？\", \"voicelineId\": 66010, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_greetingNoon\", \"description\": \"午饭如果有偏好的菜色，提前和家仆说就好。你是我的贵客，他们也应对你尽心尽力。\", \"voicelineId\": 66011, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_greetingNight\", \"description\": \"既然在这个时间点找我，不如留下来吃晚饭吧。\", \"voicelineId\": 66012, \"voicelineType\": \"1003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_greetingNight2\", \"description\": \"到洗漱的时间了是吧，你先下去吧，我还不困…呃，是你？我最后再整理下今日的公务便好，你也早点休息。\", \"voicelineId\": 66013, \"voicelineType\": \"1004\"}, {\"title\": \"关于神里绫人自己·代价\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_idle\", \"description\": \"万事皆有代价。既然寻求常人无法企及之事，那就必然付出世人无法想象的代价。\", \"voicelineId\": 66014, \"voicelineType\": \"2001\"}, {\"title\": \"关于神里绫人自己·手段\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_idle2\", \"description\": \"我并不是拘泥于手段的人，无论采取怎样的方式，只要能够取得合适的结果就好。\", \"voicelineId\": 66015, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·趣事\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_close\", \"description\": \"呵，我听说了你们在天领奉行那边发生的趣事。能让九条老头气得掉头发的人，真不多见。只可惜没有亲眼见证这一幕啊…\", \"voicelineId\": 66016, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·信任\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_close1\", \"description\": \"信任他人不是一件容易的事，特别是对于位居高位的人来说。一旦错付了，付出生命的代价也不算少见。不过，你已经给了我信任，那我自然也不该辜负。\", \"voicelineId\": 66017, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_pendant\", \"description\": \"既然有「神之眼」这么方便的道具，自然是要好好利用了。能在我的手中像这样焕发光辉，它也是高兴的吧。\", \"voicelineId\": 66018, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_share_01\", \"description\": \"将落花投于暖炉之上，在炉火的炙烤下，花会短暂地恢复生机，最后一刻的红艳更是压火光一筹…倒也没有枉费短暂的一生。\", \"voicelineId\": 66019, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_pref_gift_01\", \"description\": \"说起宠物的话，嗯，我更喜欢狗。猫自我主义的特征是不错，但只有狗会乖乖听从主人的命令。忠诚而又坦率，呵，真是惹人喜爱啊。\", \"voicelineId\": 66020, \"voicelineType\": \"3003\"}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_teammate_ayaka_01\", \"description\": \"我相信绫华的能力，但我也希望她能够保持一颗纯粹的心。权力斗争她不必参与，人世阴暗她也不必直面，这些理应由作为兄长的我来一一扫清…不小心说太多了，就当是你我之间的秘密吧。\", \"voicelineId\": 66021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于托马…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_teammate_thoma_01\", \"description\": \"托马对神里家的忠心毋庸置疑。很久以前我曾试探过他，如果不想往后被卷入无尽纷争的话，最好早日离开。他却还是留了下来，一直跟随着神里家，让我也省心不少。…现在，我完全信得过的人很少，托马算是一个。\", \"voicelineId\": 66022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于早柚…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_teammate_sayu_01\", \"description\": \"她平时看起来是懒散了点，但在适当的时机，却总能给予重要帮助。你应该再清楚不过了吧？\", \"voicelineId\": 66023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_teammate_yoimiya_01\", \"description\": \"那位…为人爽朗的烟花店店主么？嗯…她和神里家往来还算密切。她和绫华年龄相仿，也很投缘。绫华恐怕也不会因为她的快人快语而困扰。毕竟绫华那孩子在小时候，就能坚定地守住本心。\", \"voicelineId\": 66024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_teammate_raidenShogun_01\", \"description\": \"为了追求「永恒」，将军大人以及整个稻妻，都付出了不小的代价。伤口需要时间来愈合，作为政局的调和者，我必然会尽到我的责任。\", \"voicelineId\": 66025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_teammate_yaeMiko_01\", \"description\": \"宫司大人于神里家有恩，可她却一直不太看得惯我，呵，恐怕你没少听她「那小子」「那小子」地称呼我吧。\\n由于业务交集，我们偶有碰面，虽说大家各怀心思，但工作起来也称得上融洽。我并不讨厌这种感觉。嗯，与聪明人一起办事，效率就是会高得多。况且就算她再讨厌我，也不得不承认如果没有我，就没人能实现得了她那些「奇思妙想」了。\", \"voicelineId\": 66026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_teammate_kujouSara_01\", \"description\": \"九条老头打得一手好算盘，磨砺出了一柄利剑。哼，只可惜，他没有算到，自己做不起这位执剑人。\", \"voicelineId\": 66027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_teammate_kazuha_01\", \"description\": \"枫原家曾是神里家的下属，神里家的先祖当年未能保护他们周全，到我这里，仍有义务照拂他。虽说无法助他重振家业，但帮他逃脱天领奉行的追捕这种事还是做得到的。\", \"voicelineId\": 66028, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于荒泷一斗…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_teammate_itto_01\", \"description\": \"那家伙实在是个有趣的人。让温顺的鬼兜虫相互争斗，哈哈，有意思。嗯，虽然那次点拨实则是不经意之举，但没想到的是，他竟会直接与我称兄道弟，而且时至今日都还没发现我这位「绫人兄」的身份。呵呵，这样也好，我并不讨厌…单纯的人。\", \"voicelineId\": 66029, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_teammate_ningguang_01\", \"description\": \"璃月七星中的那位「天权」大人，嗯，她的手段我也略有耳闻。说来，我还收藏有一套限量版的「璃月千年」，你感兴趣吗？我差人拿出来，我们下一盘如何？\", \"voicelineId\": 66030, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解神里绫人·其一\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_friendship_01\", \"description\": \"我的事情吗？有时候知道得太多不一定是好事，你应该也听说过类似的谚语吧。下次有机会再聊吧。\", \"voicelineId\": 66031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解神里绫人·其二\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_friendship_02\", \"description\": \"品味…奇特？看来你对我有什么误解，我得澄清一下才是。多数时候，我只是喜欢看人脸上为难的表情罢了。难道这很奇怪吗？你应该也没少逗你边上的小家伙吧？\", \"voicelineId\": 66032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解神里绫人·其三\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_friendship_03\", \"description\": \"三奉行之间，表面看起来风平浪静，实际上却暗潮涌动。哼，和那些老家伙们周旋，并不是什么愉快的事，不值得细说。你只需知道…昔日是为了神里家的稳定，今日是为了稻妻的大局，我从未行有愧于神里家家主之名之事。\", \"voicelineId\": 66033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解神里绫人·其四\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_friendship_04\", \"description\": \"终末番吗？和你说说倒也无妨。那是直属于神里家家主的一支秘密部队，家父去世后，便由我接手了。我不能直接出面解决的事情，有了终末番就方便不少。里面的成员大多是孤儿，从小就被组织收养，这样才能最大程度保证忠诚，也能让人放心。\", \"voicelineId\": 66034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解神里绫人·其五\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_friendship_05\", \"description\": \"除了终末番以外的底牌？呵，自然是有的，狡兔有三窟，更何况人呢？只是我的秘密已经说得差不多了，该来听听你的故事了吧。哦对了，在提瓦特大陆上旅行的部分就不用了，说些更久之前的吧。\", \"voicelineId\": 66035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"神里绫人的爱好…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_pref_hobby\", \"description\": \"爱好…小时候倒是略有一二，不过如今公务占据了大多数时间，不提也罢…嗯？你说有人把公务当成爱好？呵，这可真是…嗯…独特。\", \"voicelineId\": 66036, \"voicelineType\": \"6001\"}, {\"title\": \"神里绫人的烦恼…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_dialog_annoyed\", \"description\": \"烦恼吗？如果一件事让我烦恼，那就得尽快处理好。如果一个人让我烦恼，呵…\", \"voicelineId\": 66037, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物·个人喜好\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_pref_foodLike_01\", \"description\": \"新奇的事物能给枯燥的日常生活带来新鲜感。最近花见坂那边新出的什锦奶茶就很不错，你也该试试。不过…日常饭菜上我没有什么偏好。每日用餐有专门的下属制定计划。对方端来什么，我就吃什么。\", \"voicelineId\": 66038, \"voicelineType\": \"6003\"}, {\"title\": \"喜欢的食物·新的尝试\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_pref_foodLike_02\", \"description\": \"差不多可以告诉我你的口味了吧？嗯？原来是这样。嗯，我记下来了。下次被问起的时候，我也回答这个吧。\", \"voicelineId\": 66039, \"voicelineType\": \"6005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_pref_foodDislike\", \"description\": \"…啊，盐和糖弄错了。咸的水馒头…嗯，也行，给托马吃吧。\", \"voicelineId\": 66040, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_spice_pref_01\", \"description\": \"挺新奇的滋味。呵呵，很符合我的要求…\", \"voicelineId\": 66067, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_spice_normal_01\", \"description\": \"原来如此。你对这道菜的理解是这样的…\", \"voicelineId\": 66068, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_spice_dislike_01\", \"description\": \"给你个建议，下次把这道菜加进火锅游戏里吧。\", \"voicelineId\": 66069, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_pref_birthday_01\", \"description\": \"生日快乐！让你体验一日社奉行，如何？\\n哦，公务我提前处理完了，你只需要享受权力带来的乐趣就好。有我陪在你身边，料想家臣们也不敢说什么。呵，放心吧。\", \"voicelineId\": 66041, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_starUp_01\", \"description\": \"能力提高了？呵，那可真是好事。\", \"voicelineId\": 66042, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_starUp_02\", \"description\": \"力量这种东西，果然只有掌握在自己手中，才能安心。\", \"voicelineId\": 66043, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_starUp_03\", \"description\": \"呵，有些人怕是要寝食难安了吧。\", \"voicelineId\": 66044, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_ayato/vo_ayato_starUp_04\", \"description\": \"坐上家主之位以后，我少有松懈的时刻。有你在旁的这段日子，却有些奇妙。嗯…就好像在晒太阳一样吧。\", \"voicelineId\": 66045, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_battle_skill1_01\", \"description\": \"苍流水影。\", \"voicelineId\": 66046, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_battle_skill1_02\", \"description\": \"剑影。\", \"voicelineId\": 66047, \"voicelineType\": \"100002\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_battle_skill3_01\", \"description\": \"秋水三尺。\", \"voicelineId\": 66048, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_battle_skill3_02\", \"description\": \"呵…安息吧。\", \"voicelineId\": 66049, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_battle_skill3_03\", \"description\": \"神里流…水囿！\", \"voicelineId\": 66050, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_chest_open_01\", \"description\": \"对你有用便好。\", \"voicelineId\": 66051, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_chest_open_02\", \"description\": \"原来你需要这些吗？\", \"voicelineId\": 66052, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_chest_open_03\", \"description\": \"嗯…质量还行。\", \"voicelineId\": 66053, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_life_less30_01\", \"description\": \"真是有趣…\", \"voicelineId\": 66054, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_life_less30_02\", \"description\": \"那么，我也认真起来吧。\", \"voicelineId\": 66055, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_life_less30_03\", \"description\": \"不知鹿死谁手呢？\", \"voicelineId\": 66056, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_life_less30_teammate_01\", \"description\": \"暂且后退。\", \"voicelineId\": 66057, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_life_less30_teammate_02\", \"description\": \"冒进是大忌。\", \"voicelineId\": 66058, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_life_die_01\", \"description\": \"百密终是有一疏么…\", \"voicelineId\": 66059, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_life_die_02\", \"description\": \"花无百日红…\", \"voicelineId\": 66060, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_life_die_03\", \"description\": \"世事无常…\", \"voicelineId\": 66061, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_battle_hit_L_01\", \"description\": \"不过如此。\", \"voicelineId\": 66062, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_ayato/vo_ayato_battle_hit_H_02\", \"description\": \"不自量力…\", \"voicelineId\": 66063, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_ayato_teamJoin_01\", \"description\": \"哦？是邀请我去散步吗？\", \"voicelineId\": 66064, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_ayato_teamJoin_02\", \"description\": \"那么，公务就先放一边吧。\", \"voicelineId\": 66065, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_ayato_teamJoin_03\", \"description\": \"呵…余兴节目。\", \"voicelineId\": 66066, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000067, 'Collei', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_draw_appear\", \"description\": \"见习巡林员柯莱，前来报到！我会保障你在林间出行时的安全——呼，总算能说出这句出场词了，我没念错字吧…\", \"voicelineId\": 67000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·巡林路线图\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_character_idle_01\", \"description\": \"今天的巡林路线图…先往这里再拐到那里…嗯，字好多…\", \"voicelineId\": 67001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·状态\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_character_idle_02\", \"description\": \"呼，今天的状态不错，趁着这个机会，多做一点事吧。\", \"voicelineId\": 67002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·回忆\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_character_idle_03\", \"description\": \"手头没有事情，心里就容易东想西想——唔，一说就想起了不好的事…\", \"voicelineId\": 67003, \"voicelineType\": \"1103\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_weather_afterRain_01\", \"description\": \"雨虽然停了，还是要小心水洼。就像一些事，明明过去了还是会留下回忆…咳咳！\", \"voicelineId\": 67004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_weather_thunder_01\", \"description\": \"打雷的时候，最好避开大树。对巡林员来说，还要格外注意检查，谨防森林火灾。\", \"voicelineId\": 67005, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_weather_sunny_01\", \"description\": \"天气不错，多晒晒太阳，对身体也好。\", \"voicelineId\": 67006, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_weather_gale_01\", \"description\": \"嗯，风力正好。安柏应该会很喜欢趁这样的天气挑战自己吧。\", \"voicelineId\": 67007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_greetingMorning\", \"description\": \"早上好！哈…抱歉，昨晚又在补习…\", \"voicelineId\": 67008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_greetingNoon\", \"description\": \"巡林路线一长，中午回不来也很正常。我多准备了一些「口袋饼」，要来一份吗？\", \"voicelineId\": 67009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_greetingNight\", \"description\": \"天快黑了，走在林子里一定要加倍小心。\", \"voicelineId\": 67010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_greetingNight2\", \"description\": \"准备休息了吗？篝火已经生好了，我会为你守夜的。\", \"voicelineId\": 67011, \"voicelineType\": \"1004\"}, {\"title\": \"关于柯莱自己·巡林\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_idle\", \"description\": \"来须弥之前，我在野外流浪过一段日子，能吃不能吃的东西都尝过了好几遍，对野外还算熟悉，所以来这儿之后就做起了巡林的工作。如果「野外生存」也算一门课目的话，我还是有自信考到及格的…嗯，不做笔试的话。\", \"voicelineId\": 67012, \"voicelineType\": \"2001\"}, {\"title\": \"关于柯莱自己·补习\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_idle2\", \"description\": \"欸？你问我每天都在补习什么？跟着这么厉害的师父，是不是什么很高深的知识…呃…这个么…《提瓦特识字大全》…\", \"voicelineId\": 67013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·旧识\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_close\", \"description\": \"我听安柏在信里提起过你，没想到在蒙德又发生了这么多事。可惜跳着字读，好多细节都没弄懂…欸，你愿意再跟我讲一遍吗？\", \"voicelineId\": 67014, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [39604], \"unlockText\": \"完成「巨龙与自由之歌」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·新交\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_close1\", \"description\": \"我曾经以为「朋友」什么的，这辈子都不会和我扯上关系，直到去了蒙德…后来在须弥遇见了师父，现在又遇到了你。果然，我还是很幸运的啊。\", \"voicelineId\": 67015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_pendant\", \"description\": \"哈…真没想到，我也会有拿到神之眼的一天。以前总觉得神明会看的，都是那些生来就被大家喜欢的人…唔，我…我承认我有很多不好的偏见。是我不对。\", \"voicelineId\": 67016, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·技能名\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_share_01\", \"description\": \"师父常说最有效的学习就是实践，所以我偶尔也会找些轻小说来看，想多认些字…起码比师父的论文好读。不过，我最近读到的一本书里，主角有好多能力，起的名字全是我看不懂的词…嗯？书的名字？应该是叫…《鬼武道》？你也读过吗？\", \"voicelineId\": 67017, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·封印之力\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_share_02\", \"description\": \"唔哇…又是「被封印的力量在躁动」…还有什么「离我远点才是上策」…为什么稻妻人都能这么自然地说出这些话，他们以后不会觉得尴尬吗？啊…不行，不能再读下去了！\", \"voicelineId\": 67018, \"voicelineType\": \"3005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_pref_gift_01\", \"description\": \"花草动物吗…除了能不能吃，好像也没有太大区别。嘘，这话不能被师父听见。要问我的话，我比较喜欢有树洞的树？尤其是在想要「找个地方钻进去」的时候…每个人都会有的吧？不是吗？\", \"voicelineId\": 67019, \"voicelineType\": \"3003\"}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_tighnari_01\", \"description\": \"师父虽然平时说话有些严厉，还经常批评那些乱吃毒蘑菇的冒险家，但他其实是个很温柔的人。不仅会耐心地给我补课，还会为我读蒙德寄来的信。我一直很感激他！\", \"voicelineId\": 67020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于多莉…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_dori_01\", \"description\": \"有次我在巡林路上遇见了她，像是知道我口渴一样，她从袋子里掏出了一瓶看起来特别好喝的果汁…还好当时师父在场，制止了她。不然，我差点就一个冲动，把好不容易攒起来的摩拉都花出去了…\", \"voicelineId\": 67021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_nahida_01\", \"description\": \"草神啊…小时候我很多次想大声问问神明，为什么要让我经历这么多苦难。唉，说不定就连神明自己，也经历着各种无奈的事吧。\", \"voicelineId\": 67022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_cyno_01\", \"description\": \"欸…我们能不提他吗？不，大风纪官不是什么坏人，当初就是他带着我从蒙德回到了须弥，才让我有了安身的地方。只是一想起回须弥前那个「封印」的过程…唔…脖子后边又开始觉得痛了…\", \"voicelineId\": 67023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡维…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_kaveh_01\", \"description\": \"大风纪官曾带着他来我们这里吃过一顿饭。在餐前水果刚端上桌的时候，他就开始大谈他那个又不讲情理又固执的室友，我们连插话的时机都找不到。只能点点头，憋着笑，吃完了整顿饭。唉，真是不容易。\", \"voicelineId\": 67024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于妮露…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_nilou_01\", \"description\": \"感觉她有点迷迷糊糊的样子，如果来化城郭附近表演的话，不会走着走着就迷路在深林里吧…那我可一定要好好看着她，尽我见习巡林员的职责。\", \"voicelineId\": 67025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_ambor_01\", \"description\": \"安柏她真的很厉害，又热情又活泼，又勇敢又正义…是我最钦佩、最崇拜的人了！她总能像一团火一样照亮别人，要不是她，我肯定没法走到今天这一步…过了这么久，她现在一定变得更加沉稳、更加帅气了吧！真不知道什么时候才能赶上她。\", \"voicelineId\": 67026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_kaeya_01\", \"description\": \"蒙德的大家都还好吗？那阵子我可是惹了不少麻烦啊，要不要找个时间回去道歉呢…唔，但感觉一露面就会被那位骑兵队长捉弄…还是再等等吧，再等等…\", \"voicelineId\": 67027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_lisa_01\", \"description\": \"明明已经过去了那么久，丽莎给我写信的时候，还是在叫我「小柯莱」，总感觉…嗯？你说她也叫你小可爱？噗…对不起，我不是有意要笑出来的…一下子就开心了好多啊。\", \"voicelineId\": 67028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲谢尔…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_fischl_01\", \"description\": \"…「断罪之皇女」？抱歉，我在蒙德待的时间不长，没有听过这样的人物。不过这个名字…嘶…咳，没什么。\", \"voicelineId\": 67029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珐露珊…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_teammate_faruzan_01\", \"description\": \"呃…老实说，我不太擅长应付这位前辈…虽然她经常夸我勤奋好学，但我真的是因为学得太慢，没办法了，才总是在补习啊！还有一回，我不小心看到了她的研究笔记，虽然只瞟了一眼，但那绝对是全须弥最可怕的书！——上面全是古文，我连半个字都看不懂。\", \"voicelineId\": 67068, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解柯莱·其一\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_friendship_01\", \"description\": \"我的事情么？如果你问的是来须弥之前的…唔，要不…你写信问一下安柏？啊，不行，要是让凯亚发现了就全完了…不对，他肯定会发现的吧！还、还是我自己来说吧，呼——对不起！请先让我再做几天心理准备…\", \"voicelineId\": 67030, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解柯莱·其二\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_friendship_02\", \"description\": \"流浪到蒙德的时候，我对安柏他们说了很多不该说的话，现在回想起来还是会很羞愧…我这人真是的，怎么能对想帮我的人说那些话呢！他们那时候究竟是怎么看我的？想想就又…呜，抱歉，今天先到这里可以吗？不然等到明天…我又要为刚刚说过的话后悔了。\", \"voicelineId\": 67031, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解柯莱·其三\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_friendship_03\", \"description\": \"因为「魔鳞病」的关系，我曾经被送到「博士」手下治疗…不，那不是治疗，而是「实验」。在那种环境里待久了，我也不由开始想，自己到底做错了什么？为什么没有人来救我…渐渐地，就连「愚人众」以外的人也一并恨上了。现在想想…实在是，太幼稚了。\", \"voicelineId\": 67032, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解柯莱·其四\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_friendship_04\", \"description\": \"多亏有你们在，「魔鳞病」消失了，是我从前想都不敢想的奇迹。嗯…我一直对完全治愈不抱希望，只想在身体不能活动前，多做一些事情。起初是复仇，后来是巡林…现在，我终于可以自由地活下去了。\", \"voicelineId\": 67033, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解柯莱·其五\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_friendship_05\", \"description\": \"你接下来还会继续旅行吗，请让我多尽一份力吧。我会努力学习…不管是认字还是学医术，还有战斗、排查危险…甚至是检查路灯这种小事！希望这一路上，能有更多和我一样的人得到帮助——就像你拯救了我一样。\", \"voicelineId\": 67034, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"柯莱的爱好…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_pref_hobby\", \"description\": \"爱好嘛…缝纫、练习飞行，还有帮助他人！嗯？你说听着有点耳熟？因为…我也想成为「能照亮别人的人」。\", \"voicelineId\": 67035, \"voicelineType\": \"6001\"}, {\"title\": \"柯莱的烦恼…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_dialog_annoyed\", \"description\": \"「针对当前…农作物品种…单一化…避兔长期食用菌类…采取的进口错施…」——这都是什么和什么啊？为什么教令院的论文连「不想吃蘑菇」都能写得这么复杂啊！\", \"voicelineId\": 67036, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_pref_foodLike_01\", \"description\": \"「口袋饼」方便携带，又容易吃饱，应该是我最常吃的东西了？如果不考虑肚子的需要，我最喜欢的食物…嗯，应该是「炸萝卜丸子」吧。\", \"voicelineId\": 67037, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_pref_foodDislike\", \"description\": \"流浪的时候肚子饿了，连钩钩果都要掰碎了吃下去，所以我没有什么特别讨厌的食物。一定要说的话，我不会碰的只有各种蘑菇吧？和口味无关，只是不希望被师父长篇大论批评的人是自己而已…\", \"voicelineId\": 67038, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_spice_pref_01\", \"description\": \"嗯——真好吃！你能教教我吗？\", \"voicelineId\": 67039, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_spice_normal_01\", \"description\": \"有这手艺，流浪在外也不会饿肚子了吧。\", \"voicelineId\": 67040, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_spice_dislike_01\", \"description\": \"抱歉，师父交代过我，不能吃奇怪的东西。\", \"voicelineId\": 67041, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_pref_birthday_01\", \"description\": \"生、生日快乐！这个是我准备的蛋糕，这个是备用的蜡烛…安柏在信里说这样就行…啊，还有、还有这个是送给你的礼物！\\n…不好意思，我没什么办生日会的经验，也不知道合不合你的心意…弄得手忙脚乱的。有什么不足一定要跟我说，明年，我一定会准备得更好！\", \"voicelineId\": 67042, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_starUp_01\", \"description\": \"我这是在进步吗？\", \"voicelineId\": 67043, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_starUp_02\", \"description\": \"我能感觉得到，我已经…不再是以前的我了。\", \"voicelineId\": 67044, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_starUp_03\", \"description\": \"就算到生死关头，也不必再依靠「它们」的力量了。\", \"voicelineId\": 67045, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_collei/vo_collei_starUp_04\", \"description\": \"现在的我，即使解开被封印的力量，也可以驾驭自如了吧？嘿！\\n说笑的，和你一起辛苦冒险的经历，才是我现在拥有的力量啊。\", \"voicelineId\": 67046, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_battle_skill1_02\", \"description\": \"去。\", \"voicelineId\": 67047, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_battle_skill1_03\", \"description\": \"飞吧。\", \"voicelineId\": 67048, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_battle_skill1_01\", \"description\": \"嘿。\", \"voicelineId\": 67069, \"voicelineType\": \"100001\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_battle_skill3_01\", \"description\": \"拜托了，柯里安巴！\", \"voicelineId\": 67049, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_battle_skill3_02\", \"description\": \"试、试试这个！\", \"voicelineId\": 67050, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_battle_skill3_03\", \"description\": \"来跳舞吧！\", \"voicelineId\": 67051, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_chest_open_01\", \"description\": \"在野外要时刻注意补给。\", \"voicelineId\": 67052, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_chest_open_02\", \"description\": \"真幸运啊。\", \"voicelineId\": 67053, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_chest_open_03\", \"description\": \"嗯…箱里没长毒蘑菇吧。\", \"voicelineId\": 67054, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_life_less30_01\", \"description\": \"我…还撑得住！\", \"voicelineId\": 67055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_life_less30_02\", \"description\": \"这点小痛，不算什么！\", \"voicelineId\": 67056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_life_less30_03\", \"description\": \"需要…尽快治疗…\", \"voicelineId\": 67057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_life_less30_teammate_01\", \"description\": \"身体要紧！\", \"voicelineId\": 67058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_life_less30_teammate_02\", \"description\": \"这样下去不太妙啊。\", \"voicelineId\": 67059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_life_die_01\", \"description\": \"得做优秀的…巡林员。\", \"voicelineId\": 67060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_life_die_02\", \"description\": \"居然会…这么倒下…\", \"voicelineId\": 67061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_life_die_03\", \"description\": \"还是…到这一天了…\", \"voicelineId\": 67062, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_battle_hit_H_01\", \"description\": \"怎么会…\", \"voicelineId\": 67063, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_collei/vo_collei_battle_hit_H_02\", \"description\": \"别碰我！\", \"voicelineId\": 67064, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_collei_teamJoin_01\", \"description\": \"就由我来保护。\", \"voicelineId\": 67065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_collei_teamJoin_02\", \"description\": \"准备齐全，出发吧！\", \"voicelineId\": 67066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_collei_teamJoin_03\", \"description\": \"见习巡林员报到！\", \"voicelineId\": 67067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000068, 'Dori', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_draw_appear\", \"description\": \"哎呀呀，这不是大名鼎鼎的旅行者吗？我是旅行商人多莉·桑歌玛哈巴依。作为给你的见面礼，我这儿的商品全部限时九折优惠，赶快来挑选吧，我帮你打包~\", \"voicelineId\": 68000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·摩拉\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_character_idle_01\", \"description\": \"我爱摩拉，摩拉爱我，啦啦啦。\", \"voicelineId\": 68001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·双赢\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_character_idle_02\", \"description\": \"先把商品涨价百分之三十，然后再打八折卖出，不仅我赚得多了，顾客也会觉得划算，这就是双赢。\", \"voicelineId\": 68002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·财迷\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_character_idle_03\", \"description\": \"只要摩拉管够，和教令院对着干也没什么大不了的。\", \"voicelineId\": 68003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_weather_heavyRain_01\", \"description\": \"需要伞吗？我这里有一把特制雨伞，收集雨水的同时能够净化水质，把雨水变成饮用水储存在小罐子里，可以说是旅行必备品！只需要五十万摩拉喔。\", \"voicelineId\": 68004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_weather_thunder_01\", \"description\": \"这种天气，恐怕商队也不太好前进了。又要少赚好多摩拉…\", \"voicelineId\": 68005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_weather_snowy_01\", \"description\": \"哒啦，看我的全自动雪球机！想要吗想要吗？租金给你打九点五折喔！\", \"voicelineId\": 68006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_weather_sunny_01\", \"description\": \"摩拉在阳光下闪闪发光，真好看！嘿嘿。\", \"voicelineId\": 68007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_weather_gale_01\", \"description\": \"不会吧不会吧，不会真的有人选在大风天穿越沙漠吧。我当然有办法救这种蠢蘑菇，但费用…至少要翻三倍才行！\", \"voicelineId\": 68008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_greetingMorning\", \"description\": \"早安，昨晚的梦里全是圆滚滚的可爱摩拉，今天一定会是盆满钵满的一天。\", \"voicelineId\": 68009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_greetingNoon\", \"description\": \"想午睡吗？我可以给你一个软绵绵、蓬松松，完美贴合你背部曲线的靠垫。当然具体有多舒服就看摩拉有多少了。\", \"voicelineId\": 68010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_greetingNight\", \"description\": \"在夜色中赶路很有挑战性喔，不过这可难不倒常年在外行商的我！\", \"voicelineId\": 68011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_greetingNight2\", \"description\": \"你要睡觉了吗？嘿嘿，我就大发慈悲让你试试我的摩拉歌谣催眠法吧！一万摩拉入口袋，两万摩拉入口袋，三万摩拉入口袋，四、嘿四万…嘿嘿，摩拉，嘿嘿…\", \"voicelineId\": 68012, \"voicelineType\": \"1004\"}, {\"title\": \"关于多莉自己·吆喝\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_idle\", \"description\": \"万能的多莉商店，应有尽有，童叟无欺。只要摩拉够，只有想不到，没有买不到。需要任何东西，或者遇到任何困难，都可以来找我喔！\", \"voicelineId\": 68013, \"voicelineType\": \"2001\"}, {\"title\": \"关于多莉自己·妙论派\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_idle2\", \"description\": \"通常我会躲着教令院的人，他们的各种条条框框简直让人没办法做生意。不过呢，告诉你也没关系。妙论派有些人还算是头脑灵活，和我私下签了条约。我有摩拉，他们有技术和手艺，顺便还能让我的行商更加通畅。嘿嘿，大商人多莉，从不做亏本生意。\", \"voicelineId\": 68014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·推销\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_close\", \"description\": \"你要在须弥旅行吗？须弥的沙漠很危险喔，就让大善人多莉来帮你吧！锵锵，沙漠旅行大礼包，只需要五百万摩拉！现在购买还会免费附送雨林旅行大礼包！机不可失，时不再来喔。\", \"voicelineId\": 68015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·摩拉分配\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_close1\", \"description\": \"我的摩拉是我的，你的摩拉还是我的，嘿嘿。\", \"voicelineId\": 68016, \"voicelineType\": \"2002\"}, {\"title\": \"关于我们·实价\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_close2\", \"description\": \"好吧好吧，和你实话实说也行啦。沙漠和雨林的旅行大礼包，拆开来卖的话，分别都值二百五十万摩拉。但买一送一听起来比较划算嘛，你不觉得吗？\", \"voicelineId\": 68017, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_pendant\", \"description\": \"哎呀哎呀，我的神之眼亮晶晶的，很漂亮吧？既然看到了这么漂亮的东西，你是不是应该付摩拉呢？\", \"voicelineId\": 68018, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_share_01\", \"description\": \"以前也有些蠢蘑菇试图欠账不还，嘿嘿，也不看看我是谁。不如，你来猜猜看他们的下场如何吧？\", \"voicelineId\": 68019, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻·共同语言\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_pref_gift_01\", \"description\": \"如果盗宝鼬能开口说话的话，我们肯定很有共同语言。它们多有眼光呀！全提瓦特最惹人喜爱的，自然是亮闪闪金灿灿的摩拉。\", \"voicelineId\": 68020, \"voicelineType\": \"3003\"}, {\"title\": \"感兴趣的见闻·驮兽乐园\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_pref_gift_02\", \"description\": \"想见见驮兽吗？没问题！你想见多少我就有多少。只不过这个门票钱嘛，欸嘿嘿…\", \"voicelineId\": 68021, \"voicelineType\": \"3004\"}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_teammate_cyno_01\", \"description\": \"我和他算是有点私交。毕竟能为他拿到「七圣召唤」所有周边产品的人，全须弥只有我一个。很罕见吧！教令院里居然有他这种特行独立，眼光不错，又从不讲价的人。\", \"voicelineId\": 68022, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_teammate_tighnari_01\", \"description\": \"他热爱学术就和我热爱摩拉一样。听说他经常会做一些神奇的小玩意儿，只可惜会用什么公务繁忙作为理由，拒绝和我合作批量生产，要不然…可以赚上一大笔摩拉呢！\", \"voicelineId\": 68023, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾尔海森…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_teammate_alhaitham_01\", \"description\": \"他以前试探过我的手下。所以说，教令院的家伙真是又呆板又不诚恳。我又何必冒这个风险呢？懂了吗？小跟班。\", \"voicelineId\": 68024, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡维…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_teammate_kaveh_01\", \"description\": \"他是跟我有合作的妙论派的人之一，和某些教令院的死脑筋不一样，是个会为理想奋斗的人，我很欣赏他。我悄悄借了他一大——笔摩拉，让他造出了我的艾尔卡萨扎莱宫。可以说没有善良的多莉的资助，就没有今天的卡维。\", \"voicelineId\": 68025, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪希雅…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_teammate_dehya_01\", \"description\": \"有时候我会雇佣她帮忙保护商队。毕竟她实力不错，要价也不高，可以说是性价比最优之选。\", \"voicelineId\": 68026, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于岩王帝君…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_teammate_morax_01\", \"description\": \"岩王帝君离去之前，我每天起来第一件事就是默念：财神在上，保佑多莉日进斗金。现在嘛，求神不如求己。多莉在此，保佑自己日进斗金！\", \"voicelineId\": 68027, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_teammate_nahida_01\", \"description\": \"在须弥，小吉祥草王的信徒非常少。你问我吗？啊，如果她愿意给我摩拉的话，我就是她永恒的信徒。\", \"voicelineId\": 68028, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于妮露…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_teammate_nilou_01\", \"description\": \"她的舞跳得不错，但只留在须弥，还是不能最大程度上发挥出她的价值…我是说，有点屈才。你说你说，如果能把她带出去，在提瓦特举办巡回演出的话，一共能赚多少摩拉呢？\", \"voicelineId\": 68029, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾莉丝…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_teammate_alice_01\", \"description\": \"艾莉丝女士有源源不断的新奇东西，是我的最佳供货商，没有之一。嚯嚯，这种商业机密都告诉你了，你是不是应该交点学费，表示表示呢？\", \"voicelineId\": 68030, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绮良良…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_teammate_kirara_01\", \"description\": \"在我跨国收购物资的时候，她为我送过好几次货。服务又好，收费还便宜。哦，对了，她很喜欢各种漂亮的小饰品，我这刚好进了一些，须弥特色，纯手工制品，可精致了。怎么样，要不要买来送给她呀？我给你打折。\", \"voicelineId\": 68071, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解多莉·其一\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_friendship_01\", \"description\": \"想听故事？那就…给我一百万摩拉。嗯…看在我们交情的份上，给你打个九点九折好了，九十九万摩拉。怎么样？很划算吧！\", \"voicelineId\": 68031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解多莉·其二\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_friendship_02\", \"description\": \"嘿嘿，你可真有眼光。那我开始讲了！\\n这是一个商人的故事。很久很久以前，她在行商途中迷失了方向。这时候她遇到一只雾怪，雾怪要一口吞掉她。她连忙说，雾怪先生不要着急呀，我这里有个故事。您听听看，如果有趣的话，就请您不要吃掉我…\", \"voicelineId\": 68032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解多莉·其三\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_friendship_03\", \"description\": \"雾怪答应了。于是商人开始讲自己的故事，当年她的生意还不像如今这么红火，在她一筹莫展之时，正巧，她从库房里翻出了一个不知从哪儿来的魔灯。她恍惚间擦亮了魔灯。一团红雾从里面弥漫了出来，她自称是「人美心善的大魔王」，见着这位商人就想起了自己乖巧可爱的女儿，所以她说，可以实现商人一个愿望。\", \"voicelineId\": 68033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解多莉·其四\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_friendship_04\", \"description\": \"还有什么比摩拉更吸引商人的呢，于是商人许愿：希望接下来的日子，能赚到数也数不清的摩拉。「人美心善的大魔王」同意了，她成为了商人的供货商，为商人提供了源源不断的奇妙商品。商人也因此赚得盆满钵满…\", \"voicelineId\": 68034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解多莉·其五\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_friendship_05\", \"description\": \"雾怪听完这些觉得很神奇，明明自己和红雾大魔王也算同类，自己怎么没办法变出什么东西。商人呀，就夸了雾怪天赋异禀，说不定在同一个魔灯里待上一段时间，就能拥有大魔王的能力了。雾怪欣然同意，进入了商人的魔灯…\\n咳咳，你问我这个故事是不是真的？这是另外的价钱喽，再给我九十九万摩拉，我就告诉你！\", \"voicelineId\": 68035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"多莉的爱好…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_pref_hobby\", \"description\": \"我的爱好可多了，第一是赚摩拉，第二是数摩拉，第三是看摩拉，这世界上没有比摩拉更令人开心的东西了！\", \"voicelineId\": 68036, \"voicelineType\": \"6001\"}, {\"title\": \"多莉的烦恼…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_dialog_annoyed\", \"description\": \"总有些人，拿着才三成利的生意就来打扰我，唉，我也是很忙的。没有百分百的利润，我连听完的兴趣都没有。\", \"voicelineId\": 68037, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_pref_foodLike_01\", \"description\": \"我听说璃月有一种叫做摩拉肉的食物，名字里带摩拉，一定非常好吃。什、什么…你会做？咳咳，你当我的小跟班也有一段时间了，应该从我这儿学到了不少吧。作为交换，你要给我做摩拉肉吃！\", \"voicelineId\": 68038, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_pref_foodDislike\", \"description\": \"椰炭饼那种黑乎乎的东西，一点儿也不符合我的品味，我是绝对不会吃的！就算反过来给我摩拉，我…呃，我、我再考虑考虑。\", \"voicelineId\": 68039, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_spice_pref_01\", \"description\": \"好吃好吃，啊不如你跟着我一起行商，兼职私人厨师吧。\", \"voicelineId\": 68040, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_spice_normal_01\", \"description\": \"哇，我的小跟班做饭水平可以呀。能让我点餐吗？\", \"voicelineId\": 68041, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_spice_dislike_01\", \"description\": \"居然让我吃这种东西，嘿嘿，你要赔偿我精神损失费！\", \"voicelineId\": 68042, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_pref_birthday_01\", \"description\": \"今天我可以满足你一个心愿！毕竟我是无所不能的多莉。说吧说吧，想要什么？不过呢，先和你说好，「一辈子都用不完的摩拉」这种愿望可不行喔。\", \"voicelineId\": 68043, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_starUp_01\", \"description\": \"你这是在投资我吗？你可真有眼光。\", \"voicelineId\": 68044, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_starUp_02\", \"description\": \"多多益善，多多益善。\", \"voicelineId\": 68045, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_starUp_03\", \"description\": \"喔！我好像有了一个奇妙钱袋，能掏出源源不断的力量。\", \"voicelineId\": 68046, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_dori/vo_dori_starUp_04\", \"description\": \"恭喜你成为神通广大的桑歌玛哈巴依老爷的尊贵会员！以后你的订单一律八折，这种待遇你可是第一个喔。啊，好好珍惜吧。\", \"voicelineId\": 68047, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_battle_skill1_02\", \"description\": \"看我的！\", \"voicelineId\": 68048, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_battle_skill1_03\", \"description\": \"留下摩拉来！\", \"voicelineId\": 68049, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_battle_skill1_01\", \"description\": \"嘿哟！\", \"voicelineId\": 68072, \"voicelineType\": \"100001\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_battle_skill3_01\", \"description\": \"魔灯显灵！\", \"voicelineId\": 68050, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_battle_skill3_02\", \"description\": \"大显身手时间！\", \"voicelineId\": 68051, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_battle_skill3_03\", \"description\": \"一手交钱，一手交货。\", \"voicelineId\": 68052, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_chest_open_01\", \"description\": \"哇，分我一半！\", \"voicelineId\": 68053, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_chest_open_02\", \"description\": \"先让我看看。\", \"voicelineId\": 68054, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_chest_open_03\", \"description\": \"我来我来！\", \"voicelineId\": 68055, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_life_less30_01\", \"description\": \"休想抢走我一分摩拉！\", \"voicelineId\": 68056, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_life_less30_02\", \"description\": \"啊救命啊，抢劫啦！\", \"voicelineId\": 68057, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_life_less30_03\", \"description\": \"一定要保护好摩拉。\", \"voicelineId\": 68058, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_life_less30_teammate_01\", \"description\": \"救命之恩，记得给钱！\", \"voicelineId\": 68059, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_life_less30_teammate_02\", \"description\": \"呆头菇，命和摩拉一样重要。\", \"voicelineId\": 68060, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_life_die_01\", \"description\": \"摩拉…还没赚够呢…\", \"voicelineId\": 68061, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_life_die_02\", \"description\": \"又是…这样…\", \"voicelineId\": 68062, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_life_die_03\", \"description\": \"摩拉也不管用吗…\", \"voicelineId\": 68063, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_battle_hit_L_01\", \"description\": \"小问题。\", \"voicelineId\": 68064, \"voicelineType\": \"900001\"}, {\"title\": \"普通受击·其二\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_battle_hit_L_02\", \"description\": \"磕碰而已。\", \"voicelineId\": 68065, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_battle_hit_H_01\", \"description\": \"欺人太甚！\", \"voicelineId\": 68066, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_dori/vo_dori_battle_hit_H_02\", \"description\": \"列进黑名单！\", \"voicelineId\": 68067, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_dori_teamJoin_01\", \"description\": \"走吧走吧，赚笔大的！\", \"voicelineId\": 68068, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_dori_teamJoin_02\", \"description\": \"摩拉不等人，快跟上。\", \"voicelineId\": 68069, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_dori_teamJoin_03\", \"description\": \"是什么大生意？\", \"voicelineId\": 68070, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000069, 'Tighnari', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_draw_appear\", \"description\": \"你好，我叫提纳里，是道成林的巡林官，负责维护雨林生态与行人安全。若你初入此地，我的建议是先通读《道成林生存指南》，并重点阅读「如何分辨可食用蕈与有毒蕈类」一章。\", \"voicelineId\": 69000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·叶片书签\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_character_idle_01\", \"description\": \"将树叶夹在干燥的纸页之间简单压制，就能做成好看又好用的书签了。\", \"voicelineId\": 69001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·犯错\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_character_idle_02\", \"description\": \"不要害怕犯错，犯错也是学习过程中的一环。\", \"voicelineId\": 69002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·知识的价值\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_character_idle_03\", \"description\": \"知识的价值，是不能用金钱简单衡量的。\", \"voicelineId\": 69003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_weather_heavyRain_01\", \"description\": \"这种天气我已经习惯了，但你最好还是打个伞哦。\", \"voicelineId\": 69004, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_weather_afterRain_01\", \"description\": \"我的尾巴涂过用来防水的植物精油，甩甩就干啦。\", \"voicelineId\": 69005, \"voicelineType\": \"1202\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_weather_thunder_01\", \"description\": \"哎呦，好响的雷！呜…震得脑瓜疼。\", \"voicelineId\": 69006, \"voicelineType\": \"1203\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_weather_snowy_01\", \"description\": \"这种天气可真少见！哎，你冷吗？冷的话可以把手埋进我的尾巴毛里。\", \"voicelineId\": 69007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_weather_gale_01\", \"description\": \"耳朵！…耳朵要吹翻过去了。\", \"voicelineId\": 69008, \"voicelineType\": \"1205\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_weather_heat_01\", \"description\": \"…好热啊…这么毒的太阳下，哪怕是冰雾花也会融化的吧…啊，仔细想想，其实不会啦，啊哈哈…唉…\", \"voicelineId\": 69009, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_greetingMorning\", \"description\": \"听！是晨露滴落叶梢的声音。\", \"voicelineId\": 69010, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_greetingNoon\", \"description\": \"午休的时候我喜欢坐在树上，盯着从树枝缝隙间漏下来的阳光发呆，一不留神就会睡着…哈哈。\", \"voicelineId\": 69011, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_greetingNight\", \"description\": \"晚上好。我正准备去观察夜光植被，要一起来吗？\", \"voicelineId\": 69012, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_greetingNight2\", \"description\": \"你睡吧，我来守夜，顺便记录下今天的巡林日志。\", \"voicelineId\": 69013, \"voicelineType\": \"1004\"}, {\"title\": \"关于提纳里自己·专业\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_idle\", \"description\": \"我以前上学时从属生论派，主攻植物学。本来导师想让我毕业后留校任教，但说实话，我喜欢更自由一些的研究环境，而且就我的观察，教令院的某些行事作风令人不敢恭维。还好当时导师没有强求——…他强求也没用。\", \"voicelineId\": 69014, \"voicelineType\": \"2001\"}, {\"title\": \"关于提纳里自己·族人\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_idle2\", \"description\": \"确实有不少人觉得我这一族性格孤僻，也不怪他们这样想。我的族人确实数量很少，还大多是学者，总是为了研究到处跑，一年也见不到一根尾巴毛。像我爸就是昆虫学家，最近好像在沙漠里研究甲虫的古今演化过程，啊我就不跟着去凑热闹了。说来惭愧，我不擅长应付烈日。晒久了脑袋里就一团浆糊，晃晃荡荡的。\", \"voicelineId\": 69015, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·相处\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_close\", \"description\": \"我认为人与人之间相互了解的最好办法就是多花时间相处，其他的都不实际。所以不必急着自我介绍，时间会沉淀一切。\", \"voicelineId\": 69016, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·朋友\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_close1\", \"description\": \"你问我们算是朋友吗？怎么，原来这种事情是需要官方认证的吗？那赶紧把你的「朋友证书」拿出来，我必须在上面签字。\", \"voicelineId\": 69017, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_pendant\", \"description\": \"我记得自己小时候曾经祈祷过，如果能有幸拥有「神之眼」，可一定得是草元素呀。不过那时的原因不是为了搞研究，而是想要制造藤蔓梯子，爬上去摘高处的果子吃。\", \"voicelineId\": 69018, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·兰那罗\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_share_01\", \"description\": \"我对这种生物早有耳闻，却一直没有亲眼见过。有时树林深处会有一些窸窸窣窣的响动，等我靠近时却又消失不见。这样也好，至少它们懂得如何保护自己，比那些碰见丛林豹还要上去亲切慰问的笨蛋冒险家们强多了。\", \"voicelineId\": 69019, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·卡卡塔\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_share_02\", \"description\": \"卡卡塔的事情你不必担心。我已经跟认识的风纪官打过招呼，说卡卡塔是我研究工作中的助手，要动它的话得先找我过问——嗯怎么，看你还挺惦记它的，要不要去素论派选些课程学学？那样就算有一天我不在了，你也能继续照管它。\", \"voicelineId\": 69020, \"voicelineType\": \"3005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1300303], \"unlockText\": \"完成「没有答案的课题」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_pref_gift_01\", \"description\": \"你知道吗？植物会伪装术。有些会拟态成昆虫或者鸟类，恐吓天敌；有些会制造诱饵，吸引其他生物为自己传播花粉；还有一些则是纯粹的捕食者，用香味或蜜糖吸引猎物上门…嗯，说到这里，感觉已经不只是植物会这样了。\", \"voicelineId\": 69021, \"voicelineType\": \"3003\"}, {\"title\": \"关于柯莱…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_collei_01\", \"description\": \"这孩子刚被带过来的时候，可以说是大字不识一个。不过问题不大。她学习勤奋，态度也认真，进步很快。只是，距离她习得精湛医术的目标还有很远的路要走。她有时会给自己很大的压力…噢，你有机会的话也多帮帮她吧？就当是我这个做师父的拜托你啦，多谢。\", \"voicelineId\": 69022, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺·大风纪官\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_cyno_01\", \"description\": \"你想见赛诺？那我丑话说在前头，被他因为公事追在屁股后面可是要倒大霉的。大风纪官毕竟位高权重，平日里还真不好找。不过他偶尔会到化城郭附近偷偷看望柯莱，就算他不想让人看见，我也能听出是他。\", \"voicelineId\": 69023, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺·为什么呢\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_cyno_02\", \"description\": \"在导师被救出来后，我给他写了一封问候信，但没想到导师说已经有人以我的名义拜访过他了，并在回信的结尾附上了一个问题：「为什么大风纪官说要靠须弥『强威』重振贤者们的名望？」\\n…问得好，到底是为什么呢。\", \"voicelineId\": 69072, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾尔海森…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_alhaitham_01\", \"description\": \"小心艾尔海森。啊，倒不是说他是什么坏蛋啦，但他做事始终被理性主导，总会有让常人觉得无法接受的地方。不信的话可以去看看他的室友，经常被他气得比风史莱姆还鼓。\", \"voicelineId\": 69024, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡维…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_kaveh_01\", \"description\": \"卡维是须弥著名的建筑师，代表作就是那座醒目的卡萨扎莱宫。当初在设计建造的时候，他还来找我咨询过有没有合适的观赏植物推荐。但不知是怎么搞的，他在宫殿完工后却给自己欠了一屁股的债，目前正被学弟艾尔海森接济，借住在他家。这个…该说是幸，还是不幸呢…\", \"voicelineId\": 69025, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于多莉…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_dori_01\", \"description\": \"大名鼎鼎的桑歌玛哈巴依老爷——就是多莉啦。我能认识她，还是因为有次研究需要用到很稀有的材料，只有进货渠道成谜的多莉才能搞得到。啊那个…别问我找她买了什么，也别问我当时在研究什么，嗯。\", \"voicelineId\": 69026, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱依拉…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_layla_01\", \"description\": \"我听说过她，远近闻名的「梦游怪人」。关于她「梦游」的传闻真是千奇百怪，什么怪力千斤顶啦，夜闯阿如村啦，徒手翻越防沙壁啦…甚至还有说她能边睡边写完十万字论文的！这都什么跟什么，哪也不挨哪。\", \"voicelineId\": 69027, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_lisa_01\", \"description\": \"我听赛诺说过他的这位师姐，是难得一见的天才，博学多闻，才华横溢，只可惜早早就回到了蒙德。难道她在进修的过程中，见到了「知识」令人畏惧的一面吗…\", \"voicelineId\": 69028, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_nahida_01\", \"description\": \"我在上学的时候曾听过这样的说法：「植物的历史，便是草之国的历史。」也许说者无心，但我总觉得此话另有深意。如果我有一天能见到小草神大人，她会给我解释吗？\", \"voicelineId\": 69029, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪希雅…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_dehya_01\", \"description\": \"之前情况危急，都没来得及好好向她道谢。能有这样强大又可靠的同伴是件非常幸运的事情，想要拉拢她的人一定不少。不过迪希雅看上去不像是愿意加入教令院或者巡林队的样子，我就不去自讨没趣了。\", \"voicelineId\": 69073, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珐露珊…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_faruzan_01\", \"description\": \"珐露珊前辈见识广博，我经常邀请她来检查雨林里的机关…只是希望下次她来化城郭的时候，不要再给柯莱偷偷塞吃的了——营养就跟药剂一样得均衡适量，过剩了可没好处。\", \"voicelineId\": 69074, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛索斯…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_teammate_sethos_01\", \"description\": \"你说赛索斯？他很有意思，有点像赛诺的远房亲戚，而且很好相处。上次他来化城郭作客，抢着要秀一手搭帐篷的技术，还跟赛诺争着捞鱼，柯莱觉得自己的工作被替代了，很郁闷呢。\\n大家都说赛索斯很擅长逗自己开心，过得很快活，工作起来又很认真。噢，说工作好像不太贴切，缄默之殿的事对他而言，比起工作更像是义务。如果你在沙漠需要帮助，可以找他。\", \"voicelineId\": 69075, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解提纳里·其一\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_friendship_01\", \"description\": \"雨林生活还过得习惯吗？建议眼观六路，耳听八方，注意安全，有事记得找巡林员。\", \"voicelineId\": 69030, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解提纳里·其二\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_friendship_02\", \"description\": \"哎，有时还挺羡慕那些什么都搞不清楚，还敢到处乱摸乱吃的家伙——在他们的世界里，一定处处都有「奇迹」发生吧？\", \"voicelineId\": 69031, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解提纳里·其三\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_friendship_03\", \"description\": \"为了更好地管理道成林，我时不时会给巡林员们开设「培训」课程。要是逐字逐句深究的话，这些课程其实都算是在「传播知识」。不过教令院又能怎样呢？有本事就把我关起来，看看「健康之家」每天要多收多少千奇百怪的病患吧。\", \"voicelineId\": 69032, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解提纳里·其四\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_friendship_04\", \"description\": \"悄悄跟你说啊，其实我很喜欢城里大巴扎的氛围。买卖兴旺，生活热闹，还有人在剧场里唱歌跳舞。但是很遗憾，嘈杂的声音对我的耳朵太不友好了。嗯？你说可以在背后帮我捂住？哈哈，那也太难走路了，但是心意我领啦。\", \"voicelineId\": 69033, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解提纳里·其五\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_friendship_05\", \"description\": \"我小时候做过许多美妙又奇幻的梦，但它们在我长大后的某一天，永远地消散在了记忆中。你还可以做梦吗？给我讲讲你的梦吧。\", \"voicelineId\": 69034, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"提纳里的爱好…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_pref_hobby\", \"description\": \"道成林里经常有掉在地上的树叶和花朵，有些在掉落的时候还很完整，就这么扔在地上太可惜了…我总是忍不住把它们捡回来做成标本。既可以变成培训巡林员的教具，还可以当作漂亮的装饰品，一举多得。\", \"voicelineId\": 69035, \"voicelineType\": \"6001\"}, {\"title\": \"提纳里的烦恼…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_dialog_annoyed\", \"description\": \"烦恼吗？嗯，我想想…道成林中出现的污染、经常惹麻烦的冒险家、总是想要扑我尾巴的救援犬…但这些问题总有解决的办法。要说大的烦恼，还真没有。这么一看，巡林官的生活还挺简单的呢。\", \"voicelineId\": 69036, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_pref_foodLike_01\", \"description\": \"说来稀奇，我身体里虽然流淌着食肉动物的血脉，但最无法割舍的食物却是蘑菇。可食用的蘑菇种类繁多，无论是新鲜的还是晾干的，都会散发独特的香味。与肉类一起炖煮时，就连肉香也要为它们让步。\", \"voicelineId\": 69037, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_pref_foodDislike\", \"description\": \"因为嗅觉太灵敏，我无福享受添加了太多香料的佳肴。唉，这在须弥可以说是重大遗憾了。\", \"voicelineId\": 69038, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_spice_pref_01\", \"description\": \"食材优质，调味精妙，简而言之——非常好吃。\", \"voicelineId\": 69039, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_spice_normal_01\", \"description\": \"不错的搭配。可以请你抄份食谱给我吗？我想把它加入巡林小队下次聚餐的菜单里。\", \"voicelineId\": 69040, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_spice_dislike_01\", \"description\": \"…需要我教你一些新菜吗？\", \"voicelineId\": 69041, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_pref_birthday_01\", \"description\": \"生日快乐！我选了一盆今日花期正盛的盆栽给你，另附养花指南。万一它之后出现任何问题，都请不要客气，随时找我，它有「巡林官终生保育凭证」。\\n你知道吗，在你生日时开的花可多了，我挑了好久呢。等到明年，再送你新的品种吧！\", \"voicelineId\": 69042, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_starUp_01\", \"description\": \"种籽萌发，破土生根。\", \"voicelineId\": 69043, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_starUp_02\", \"description\": \"幼苗拔高，开枝展叶。\", \"voicelineId\": 69044, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_starUp_03\", \"description\": \"花蕾满枝，杏雨梨云。\", \"voicelineId\": 69045, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_tighnari/vo_tighnari_starUp_04\", \"description\": \"硕果丰熟，来日更盛。\", \"voicelineId\": 69046, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_battle_skill1_01\", \"description\": \"一叶障目。\", \"voicelineId\": 69047, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_battle_skill1_02\", \"description\": \"障眼法！\", \"voicelineId\": 69048, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_battle_skill1_03\", \"description\": \"看不清了吧？\", \"voicelineId\": 69049, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_battle_skill3_01\", \"description\": \"斩草除根！\", \"voicelineId\": 69050, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_battle_skill3_02\", \"description\": \"蔓引株连！\", \"voicelineId\": 69051, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_battle_skill3_03\", \"description\": \"声音，我听见了。\", \"voicelineId\": 69052, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_explore_sprint_start_01\", \"description\": \"跟紧了。\", \"voicelineId\": 69053, \"voicelineType\": \"700001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_chest_open_01\", \"description\": \"这里怎么会有宝箱？\", \"voicelineId\": 69054, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_chest_open_02\", \"description\": \"这个，应该不用写失物招领吧。\", \"voicelineId\": 69055, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_chest_open_03\", \"description\": \"闻起来有好东西哦。\", \"voicelineId\": 69056, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_life_less30_01\", \"description\": \"唉，真是麻烦。\", \"voicelineId\": 69057, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_life_less30_02\", \"description\": \"尾巴毛都乱了…\", \"voicelineId\": 69058, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_life_less30_03\", \"description\": \"该清杂草了。\", \"voicelineId\": 69059, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_life_less30_teammate_01\", \"description\": \"快去疗伤。\", \"voicelineId\": 69060, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_life_less30_teammate_02\", \"description\": \"救人要紧。\", \"voicelineId\": 69061, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_life_die_01\", \"description\": \"叶落…归根…\", \"voicelineId\": 69062, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_life_die_02\", \"description\": \"还有未完成的研究…\", \"voicelineId\": 69063, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_life_die_03\", \"description\": \"没能等到花开…\", \"voicelineId\": 69064, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_battle_hit_L_01\", \"description\": \"哎呦。\", \"voicelineId\": 69065, \"voicelineType\": \"900001\"}, {\"title\": \"普通受击·其二\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_battle_hit_L_02\", \"description\": \"行啊？\", \"voicelineId\": 69066, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_battle_hit_H_01\", \"description\": \"没完没了！\", \"voicelineId\": 69067, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_tighnari/vo_tighnari_battle_hit_H_02\", \"description\": \"等着入土吧！\", \"voicelineId\": 69068, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_tighnari_teamJoin_01\", \"description\": \"我来领路。\", \"voicelineId\": 69069, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_tighnari_teamJoin_02\", \"description\": \"唉！有谁又吃毒蘑菇了吗？\", \"voicelineId\": 69070, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_tighnari_teamJoin_03\", \"description\": \"走，去采些样本！\", \"voicelineId\": 69071, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000070, 'Nilou', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_draw_appear_01\", \"description\": \"你好，我是来自祖拜尔剧场的妮露。今天上演的剧目是这一支舞。请你不要眨眼哦，要开始了——\", \"voicelineId\": 70000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·练习\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_character_idle_01\", \"description\": \"先这样…下一个动作是…这样吧，嗯…嗯！\", \"voicelineId\": 70001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·困意\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_character_idle_02\", \"description\": \"深呼吸，吹一个大大的气球，把困意放进气球里，呼——气球飞走吧。\", \"voicelineId\": 70002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·休息\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_character_idle_03\", \"description\": \"这样清闲的日子倒也不错嘛，优哉游哉。\", \"voicelineId\": 70003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_weather_heavyRain_01\", \"description\": \"天气和心情一样，有时候会变得阴沉沉的，但是不用着急，雨后的天空会更加澄澈。\", \"voicelineId\": 70004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_weather_thunder_01\", \"description\": \"雷声有点恐怖呢，你会害怕吗？我可以分享你一个神奇的方法哦。\", \"voicelineId\": 70005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_weather_snowy_01\", \"description\": \"欸？哇——下雪了。你听，下雪的簌簌声，加上旋转着的雪花，像不像自然的精灵在跳舞？\", \"voicelineId\": 70006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_weather_sunny_01\", \"description\": \"阳光明媚的日子…晒得暖洋洋的。唔，会犯困…\", \"voicelineId\": 70007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_weather_gale_01\", \"description\": \"你还好吗？小心风沙哦。\", \"voicelineId\": 70008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_greetingMorning\", \"description\": \"早上好哦。欸？你盯着我看是…哦头、头发翘起来了吗？啊，先别看我，唔，我马上整理好。\", \"voicelineId\": 70009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_greetingNoon\", \"description\": \"唔…嗯…中午吃饼好呢，还是吃饭呢…要不吃豆泥吧？\", \"voicelineId\": 70010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_greetingNight\", \"description\": \"晚上好，今晚我在祖拜尔剧场有演出。给你两张剧票吧？\", \"voicelineId\": 70011, \"voicelineType\": \"1003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_greetingNight2\", \"description\": \"睡前把烦恼全部都倾诉掉，会睡得比较香哦。如果你愿意，我很乐意当你的听众。\", \"voicelineId\": 70012, \"voicelineType\": \"1004\"}, {\"title\": \"关于妮露自己·肢体语言\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_idle\", \"description\": \"有时候，舞蹈比语言更能传达出心情，不知道该说什么好的时候，就跳舞吧。\", \"voicelineId\": 70013, \"voicelineType\": \"2001\"}, {\"title\": \"关于妮露自己·舞蹈与知识\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_idle2\", \"description\": \"探究知识需要很高很高的天赋，很多人拼了命地努力，结果劳累又沮丧…但跳舞就不一样了，就算看不懂门道，也能看个热闹。要是能从这份肢体动作中品味到艺术的美丽与价值，那我就更开心了。\", \"voicelineId\": 70014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·缓解生气\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_close\", \"description\": \"你会生闷气吗？嗯，生闷气是不好的。来，跟着我做。先在身前用右手画一个大大的圆，然后，双手把讨厌的事都从胸口里取出来，放在圆里。接着，用力地推出去！怎么样，心情好起来了吗？\", \"voicelineId\": 70015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·外出冒险\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_close1\", \"description\": \"尽管我之前没离开过须弥城，但…我想和你一起去冒险。哦，到陌生的地方，我适应一下就好…唔，稻妻的沙滩下，真的不会有很大很大的沙虫，突然钻出来吗？\", \"voicelineId\": 70016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_pendant\", \"description\": \"我的神之眼是第一次登台跳舞时拿到的。我想，神明大人会成为我的观众，一定也认可了人类艺术的美丽之处吧。\", \"voicelineId\": 70017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_share_01\", \"description\": \"努力没有结果，也是很正常的。就像我不管怎么努力，也没办法理解明论派的知识。嗯，这个时候晃一晃脑袋，让大脑转个弯，换个方向就好了。\", \"voicelineId\": 70018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻·晶蝶之舞\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_pref_gift_01\", \"description\": \"晶蝶有各种各样的颜色，很漂亮。当你实在按捺不住好奇心，悄悄伸出手的时候，它们就会一下子跳起优美而迅疾的舞步，离你远去。啊，我要是会飞的话，就能学会晶蝶之舞了。\", \"voicelineId\": 70019, \"voicelineType\": \"3003\"}, {\"title\": \"感兴趣的见闻·帕蒂沙兰\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_pref_gift_02\", \"description\": \"花神大人跳舞的时候，真正的帕蒂沙兰会在她踏足过的地上盛开。…啊，听起来就非常美好，真想见一见这样的场景。\", \"voicelineId\": 70020, \"voicelineType\": \"3004\", \"unlockConditions\": [{\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_teammate_cyno_01\", \"description\": \"教令院的人，我不太敢接触，毕竟他们对歌舞艺术的印象都不好。我常常会想，那他们会通过什么来解闷呢？呃…你说赛诺的话，会玩「七圣召唤」？真是不可思议呢。\", \"voicelineId\": 70021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_teammate_tighnari_01\", \"description\": \"据说他是很厉害的植物学家。那他分辨蘑菇的本领肯定很厉害，至少不会吃到毒蘑菇…好羡慕呀。\", \"voicelineId\": 70022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于柯莱…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_teammate_collei_01\", \"description\": \"她偶尔会来看我的演出，是一位很热心的见习巡林员呢。她还提醒过我小心迷路，这是为什么呢？我也没有迷路过呀。\", \"voicelineId\": 70023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡维…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_teammate_kaveh_01\", \"description\": \"我听说是他建造了华美的艾尔卡萨扎莱宫，能建造出那样的作品，过程应该快乐又陶醉吧。就像我练舞的时候一样，只要一想到能跳给大家看，就充满了喜悦和动力呢。\", \"voicelineId\": 70024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪希雅…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_teammate_dehya_01\", \"description\": \"最近发生了那么多事情，总觉得很不可思议。我原本想为迪希雅和迪娜泽黛挑选一些合适的礼物。但我自己拿不定主意，嗯…要是把大巴扎朋友们推荐的品种全送去，又太多了。哎呀，到底该怎么办才好呢？\", \"voicelineId\": 70025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于多莉…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_teammate_dori_01\", \"description\": \"出手阔绰的多莉大商人也曾看过我跳舞。我记得，有一次她和祖拜尔先生商量了什么事情，之后就再也没来过了。会是什么事情呢？嗯…呃？你是说她可能想带我进行一场提瓦特巡演？不会吧，祖拜尔先生肯定帮忙拒绝了吧…应该拒绝了吧…\", \"voicelineId\": 70026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_teammate_nahida_01\", \"description\": \"大巴扎的大家都很喜欢小吉祥草王大人，好想听听她对我跳的花神之舞的评价呀…啊！不、不，还是算了算了。她真的来了，我肯定会紧张得不得了。\", \"voicelineId\": 70027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3012], \"unlockText\": \"完成「千朵玫瑰带来的黎明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解妮露·其一\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_friendship_01\", \"description\": \"唔——啊！抱歉，我在想等下去吃什么好呢？有点出神了…你需要帮忙吗？\", \"voicelineId\": 70028, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解妮露·其二\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_friendship_02\", \"description\": \"我的老师教过我很多跳舞的要领，但她说，最重要的还是要把情感都投入到舞蹈里，因为这样才是最能打动人的。有所感，才能抒发。想要传达美丽的话，我就要成为美丽本身吧。\", \"voicelineId\": 70029, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解妮露·其三\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_friendship_03\", \"description\": \"有时候我会收到观众们的来信，说他们因为我的舞蹈打起了精神。我会和祖拜尔剧场的大家共同分享这份快乐。虽然在观众眼里，我是在台前的那一个，但在我心中，这永远是靠所有人的努力才能取得的成果。\", \"voicelineId\": 70030, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解妮露·其四\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_friendship_04\", \"description\": \"大巴扎有时候会有一些杂技表演，比如说不停抛起球来又不停接住。以前我也试过这个，但是不知道怎么回事就是接不住球，反而全掉头上了。当时祖拜尔先生他们都笑了起来。嗯…好像在他们眼里，我的身体协调能力应该特别强一样…暴露短处了呢。\", \"voicelineId\": 70031, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解妮露·其五\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_friendship_05\", \"description\": \"以前有人说我就像是暖阳下的绿洲，让人感到治愈与温暖。我多多少少会高兴一下，但我的追求、我试图向大家呈现的价值不止在此。不过，和你相处久了我才知道，被人照顾和关怀是这样的感觉。现在…现在，我感觉那个比喻更适合你。\", \"voicelineId\": 70032, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"妮露的爱好…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_pref_hobby\", \"description\": \"我的人生就是跳舞，跳舞就是我的人生…到底该说哪个才比较好呢？哎呀，我果然不适合思考这些太有逻辑的东西。总之，我会一直跳下去的。用我的表演，让这份艺术之美被更多人看见。\", \"voicelineId\": 70033, \"voicelineType\": \"6001\"}, {\"title\": \"妮露的烦恼…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_dialog_annoyed\", \"description\": \"我还是搞不懂哪些蘑菇有毒，哪些又没有…据说，颜色不管是鲜艳还是朴素的蘑菇，都有可能有毒。唔，好像明白了什么，又好像什么都没明白…\", \"voicelineId\": 70034, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_pref_foodLike_01\", \"description\": \"甜食总能让人心情愉快，须弥大多数人都喜欢甜食哦！欸，你要不要也试试看？我可以给你一一介绍。\", \"voicelineId\": 70035, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_pref_foodDislike\", \"description\": \"我有点难以接受菌菇那一类，主要是害怕。不是那种见到了想逃走的害怕啦。我…我是小时候误吃过毒蘑菇，在床上躺了好几天…如果你想尝一尝须弥的菌菇美食，要记得确保是无毒蘑菇哦。\", \"voicelineId\": 70036, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_spice_pref_01\", \"description\": \"原来美食在舌尖起舞，指的就是这样的感觉…好神奇呀！\", \"voicelineId\": 70037, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_spice_normal_01\", \"description\": \"谢谢你。就像我不断练习跳舞一样，这道菜肴，一定也凝结着你的心血吧。\", \"voicelineId\": 70038, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_spice_dislike_01\", \"description\": \"抱歉，可能是我最近胃口不太好，你别介意。\", \"voicelineId\": 70039, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_pref_birthday_01\", \"description\": \"那个…生日快乐！我最近学会了一支新的舞蹈，想要跳给你看。呃，你问我紧张吗？呼——被你看出来了呀。因为，想要融合心意与技巧，不知不觉编得越来越难…总之，希望美好与快乐能永远留在你身边。\", \"voicelineId\": 70040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_starUp_01\", \"description\": \"啊，这是什么感觉？\", \"voicelineId\": 70041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_starUp_02\", \"description\": \"身体舒展开了，能比以往发挥得更出色吧。\", \"voicelineId\": 70042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_starUp_03\", \"description\": \"我就像躺在一只大大的风史莱姆背上，好轻好轻。\", \"voicelineId\": 70043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_nilou/vo_nilou_starUp_04\", \"description\": \"我喜欢和你待在一起。嗯…我也不知道为什么，总感觉好像有蝴蝶要从胸腔飞出来一般…还是让我跳一支舞给你看吧。\", \"voicelineId\": 70044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_battle_skill1_01\", \"description\": \"来了哟。\", \"voicelineId\": 70045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_battle_skill1_02\", \"description\": \"准备跳喽。\", \"voicelineId\": 70046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_battle_skill1_03\", \"description\": \"全力以赴。\", \"voicelineId\": 70047, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_battle_skill3_01\", \"description\": \"和浪花共舞吧。\", \"voicelineId\": 70048, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_battle_skill3_02\", \"description\": \"请看好了哦。\", \"voicelineId\": 70049, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_battle_skill3_03\", \"description\": \"这支舞，献给你。\", \"voicelineId\": 70050, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_chest_open_01\", \"description\": \"都给你。\", \"voicelineId\": 70051, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_chest_open_02\", \"description\": \"我来帮忙一起收吧。\", \"voicelineId\": 70052, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_chest_open_03\", \"description\": \"哇，是意外之喜。\", \"voicelineId\": 70053, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_life_less30_01\", \"description\": \"唔，不用担心我…\", \"voicelineId\": 70054, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_life_less30_02\", \"description\": \"真伤脑筋呀…\", \"voicelineId\": 70055, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_life_less30_03\", \"description\": \"得快点深呼吸…\", \"voicelineId\": 70056, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_life_less30_teammate_01\", \"description\": \"别急，我来了。\", \"voicelineId\": 70057, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_life_less30_teammate_02\", \"description\": \"请让我来抵挡一阵！\", \"voicelineId\": 70058, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_life_die_01\", \"description\": \"还没来得及…谢幕…\", \"voicelineId\": 70059, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_life_die_02\", \"description\": \"不能…继续跳舞了吗…\", \"voicelineId\": 70060, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_life_die_03\", \"description\": \"美丽之物，不要远去…\", \"voicelineId\": 70061, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_battle_hit_H_01\", \"description\": \"啊，要稳住平衡。\", \"voicelineId\": 70062, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_nilou/vo_nilou_battle_hit_H_02\", \"description\": \"有点…疼。\", \"voicelineId\": 70063, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_nilou_teamJoin_01\", \"description\": \"今天要去哪里跳舞呢？\", \"voicelineId\": 70064, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_nilou_teamJoin_02\", \"description\": \"有什么我能帮忙的吗？\", \"voicelineId\": 70065, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_nilou_teamJoin_03\", \"description\": \"啊…是叫我吗？来啦。\", \"voicelineId\": 70066, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000071, 'Cyno', '[{\"title\": \"初次见面·过往\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_draw_appear_01\", \"description\": \"我是赛诺，曾经的「大风纪官」。如今我正在以自己的力量审判罪恶，若你同样心系规则与正义，我可以助你一臂之力。\", \"voicelineId\": 71000, \"voicelineType\": \"1000\"}, {\"title\": \"初次见面·如今\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_draw_appear_02\", \"description\": \"我是赛诺，教令院的「大风纪官」。维护规则、审判罪恶是我的职责，今后的旅途中，我会保护好你的安全。\", \"voicelineId\": 71001, \"voicelineType\": \"1006\", \"unlockConditions\": [{\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"闲聊·称重\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_character_idle_01\", \"description\": \"善与恶，最终都会被称量。\", \"voicelineId\": 71002, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·牌运\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_character_idle_02\", \"description\": \"运势会左右某一场对决的胜负，但不会一直影响下去。\", \"voicelineId\": 71003, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·疑惑\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_character_idle_03\", \"description\": \"偶尔我也想缓解一下气氛，但我其实分不太清什么笑话能够引人发笑。\", \"voicelineId\": 71004, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_weather_heavyRain_01\", \"description\": \"又下雨了…\", \"voicelineId\": 71005, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_weather_thunder_01\", \"description\": \"在一些传说中，雷电是神明对人间降下的审判。\", \"voicelineId\": 71006, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_weather_snowy_01\", \"description\": \"我很喜欢下雪后的世界，安静却并非一片死寂。\", \"voicelineId\": 71007, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_weather_sunny_01\", \"description\": \"阳光终会照进每一个角落。\", \"voicelineId\": 71008, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_weather_gale_01\", \"description\": \"好大的风…当心。\", \"voicelineId\": 71009, \"voicelineType\": \"1205\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_weather_desert_01\", \"description\": \"熟悉的风景…\", \"voicelineId\": 71010, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_greetingMorning\", \"description\": \"打起精神，该出发了。\", \"voicelineId\": 71011, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_greetingNoon\", \"description\": \"需要我准备午饭吗？事先说好，我可不保证好吃。\", \"voicelineId\": 71012, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_greetingNight\", \"description\": \"还记得我跟你说过的话吗？夜晚总是伴随着危险，无论做什么都不要放松警惕。\", \"voicelineId\": 71013, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_greetingNight2\", \"description\": \"晚安。一些罪犯在附近活动，我去处理。\", \"voicelineId\": 71014, \"voicelineType\": \"1004\"}, {\"title\": \"关于赛诺自己·冷笑话\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_idle\", \"description\": \"有一个旅人在沙漠中口渴无比，于是祈祷自己遇到一只水史莱姆，没想到一只饿着肚子的水史莱姆也在祈祷自己遇见落单的旅人…嗯？你那是什么表情，不好笑吗？\", \"voicelineId\": 71015, \"voicelineType\": \"2001\"}, {\"title\": \"关于赛诺自己·散步\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_idle2\", \"description\": \"我偶尔会去夜晚的沙漠散步，寒冷而干涩的风让人头脑清醒。\", \"voicelineId\": 71016, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·决斗\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_close\", \"description\": \"要打一把「七圣召唤」吗？给你看看我的新卡组。\", \"voicelineId\": 71017, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·此刻\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_close1\", \"description\": \"过去无法更改，未来无法预料，所以我很珍惜眼前的时光。\", \"voicelineId\": 71018, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_pendant\", \"description\": \"凭依在我身上的非人之物也好，将视线投射于我的魔神也罢，我受神明青睐，但我无意为此而改变自己的道义。我只尽我应尽之责，做我应做之事。\", \"voicelineId\": 71019, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·求知欲\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_share_01\", \"description\": \"「欲望泛滥就会引发灾害」，这似乎已经是一种共识。然而提及「求知欲」的时候，人们却往往只愿意谈论它的正面作用…在我看来，求知欲也是欲望的一种，必须加以控制。\", \"voicelineId\": 71020, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·敬畏心\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_share_02\", \"description\": \"在执行任务时，我的任何一个判断都可能会改变他人的命运。所以我必须要求自己时刻对「风纪官」这个职位保持敬畏——就像我敬畏知识与力量一样。\", \"voicelineId\": 71021, \"voicelineType\": \"3005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_pref_gift_01\", \"description\": \"我喜欢生长在沙漠中的那些灌木。沙漠象征着归寂，一切文明都会被风沙掩埋。但就在这片荒凉的土地上，却能见到生命不断萌发的迹象，有时连我也会被它们的坚韧震撼。\", \"voicelineId\": 71022, \"voicelineType\": \"3003\"}, {\"title\": \"关于提纳里·知识\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_teammate_tighnari_01\", \"description\": \"提纳里和我见过的其他学者不同。他对知识同样有着很深的执着，却始终不会逾越那道红线。有些学者会将自己视为「实验室中的神明」，但提纳里不会，他一直平等地尊重每一种生命。听说他拒绝了教令院的聘请，我也站在他这一边。\", \"voicelineId\": 71023, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提纳里·笑话\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_teammate_tighnari_02\", \"description\": \"提纳里曾劝我不要在饭桌上讲笑话，说是根本笑不出来。我不以为然，连讲了三个压箱底的笑话，并逐一解释了笑点…然后我的饭菜凉了。\", \"voicelineId\": 71024, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于柯莱…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_teammate_collei_01\", \"description\": \"我曾经帮她封印了体内的魔神残骸，但封印的过程给她带来了很大的痛苦。那种程度的痛苦可能比死亡更让人害怕，她能够坚持下来，很了不起。\", \"voicelineId\": 71025, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾尔海森…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_teammate_alhaitham_01\", \"description\": \"我不太喜欢过于聪明的人，他们总是自认为能掌控一切，从而经常在危险的边缘游走。不过艾尔海森还算稳定，在绝大部分场合，他确实有掌控局面、化险为夷的能力。\", \"voicelineId\": 71026, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3021], \"unlockText\": \"完成「赤土之王与三朝圣者」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡维…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_teammate_kaveh_01\", \"description\": \"提纳里和柯莱没有亲口说出来，但他们之间的眼神交流已经说明了一切。卡维分享的亲身经历比我准备的笑话有趣多了。我的看法？我觉得他们会为这种事情发笑，反倒是挺好笑的。\", \"voicelineId\": 71027, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于纳西妲…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_teammate_nahida_01\", \"description\": \"评价神明…这在我看来是略微有些僭越的事情。不过在同行的那段时间里，我也亲眼见证了她的智慧、勇气与决心。相较于那些只靠臆想就对她指指点点的贤者，我应该更有资格下这个结论：她是一位优秀的、值得尊敬的神明。\", \"voicelineId\": 71028, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于妮露…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_teammate_nilou_01\", \"description\": \"我能从她身上感到对舞蹈的热情与执念，这份执念非常坚定，不会轻易改变。希望以后，她也可以用自己热爱的舞蹈为他人带去快乐。\", \"voicelineId\": 71029, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珐露珊…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_teammate_faruzan_01\", \"description\": \"我曾仔细翻阅过记载珐露珊前辈失踪的案卷，那时候我怀疑她进行了某种危险的研究…不过与她见面之后，我就彻底打消了这个念头。虽然相处起来有些困难，不过她就像一位喜欢絮絮叨叨的长辈，心里会为他人着想，不会做什么出格的事情。\", \"voicelineId\": 71030, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_teammate_lisa_01\", \"description\": \"丽莎和我曾向同一位贤者求学，我自然知道她的事。身为大风纪官，我也见过许多过分追求知识而引发的悲剧，所以能理解她的选择。\", \"voicelineId\": 71031, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛索斯…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_teammate_sethos_01\", \"description\": \"赛索斯很有责任心，我绝对认可他作为战士的能力，也钦佩他的勇气。他也帮了我很多，有他在，教令院与缄默之殿的合作一定会更顺利。\\n不过我觉得他身上还有一处欠缺，就是牌打得太少。每次见面我都邀请他打几局，他总有事在身，要吃饭了、有事要办、要去见朋友…全是借口！他在须弥城最熟的朋友不就我们几个吗？\", \"voicelineId\": 71075, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解赛诺·其一\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_friendship_01\", \"description\": \"你问关于我的事？也是，毕竟在很多人眼中我是一个无法忽视的「麻烦」…不用担心，只要你不做什么危险的事情，我就不会找你的麻烦。\", \"voicelineId\": 71032, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解赛诺·其二\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_friendship_02\", \"description\": \"以此身为容器，可以令非人之物的力量显现。这既得益于先天的体质，也是一种后天的交易。没什么可避讳的，我以风纪官的身份称量世间的罪恶，自然也要把我自己的灵魂放到审判之秤上一同称量。\", \"voicelineId\": 71033, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解赛诺·其三\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_friendship_03\", \"description\": \"比起「为什么做」，我更看重「做了什么」。因为这个世界上有成千上万种理由，有时你听到那些理由，会觉得做了错事的人情有可原，甚至觉得旁人对他们太过苛责。劣势方总是容易引起别人的同情，但审判者却要摒弃这种情绪。情有可原，但罪无可赦。\", \"voicelineId\": 71034, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解赛诺·其四\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_friendship_04\", \"description\": \"在幽暗的无知之海上，偶尔会泛起微光，吸引着不明真相的人靠近。常有人视其为灯塔，却看不到漆黑的海水中隐藏的巨大危险。将久居在黑暗中的人带离光明的指引，本身是一件残酷的事情，但我不得不这么做——直到未来有一天，我们能够战胜海水中潜藏的敌人为止。\", \"voicelineId\": 71035, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解赛诺·其五\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_friendship_05\", \"description\": \"我判断有价值的信息，已经如数分享了，你还在期待听我说什么？哈…你的好奇心真是不简单，那就由你提问吧。习惯了审问别人之后，这种被人询问的感觉…也算新奇。\", \"voicelineId\": 71036, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"赛诺的爱好…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_pref_hobby\", \"description\": \"闲暇的时候，我会和其他人打几局「七圣召唤」。这种建立在规则之上，却又充满灵活变通的游戏，在我看来更像是一种艺术。\", \"voicelineId\": 71037, \"voicelineType\": \"6001\"}, {\"title\": \"赛诺的烦恼…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_dialog_annoyed\", \"description\": \"前段时间，我看到了一本来自稻妻的轻小说。小说以「七圣召唤」为主题，里面的主角被逼入绝境的时候，忽然从卡组中抽到了一张原本不存在的卡。我深受震撼，同时也陷入困惑：通过对卡组进行特殊操作，创造出让人摸不着头脑的奇迹，这究竟是打破了规则，还是也算规则的一部分？\", \"voicelineId\": 71038, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_pref_foodLike_01\", \"description\": \"大米与肉类、干果混合，加酸奶进行烤制，不同的香味会混合到一起。敲开焦脆的外壳，香味就会随着蒸腾的热气一同冒出来。制作起来也不会花太长时间，是我很喜欢的菜肴。\", \"voicelineId\": 71039, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_pref_foodDislike\", \"description\": \"在沙漠中行走的时候，带的干粮通常坚硬无味，习惯之后就没有什么讨厌的东西了。非要说的话，跟虫子有关的食物还是有些难以接受…\", \"voicelineId\": 71040, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_spice_pref_01\", \"description\": \"味道很好，劳你费心了。\", \"voicelineId\": 71041, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_spice_normal_01\", \"description\": \"我收下了，多谢。\", \"voicelineId\": 71042, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_spice_dislike_01\", \"description\": \"给我的吗？是不是搞错了？\", \"voicelineId\": 71043, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_pref_birthday_01\", \"description\": \"嗯…先祝你生日快乐。虽然没有太多庆祝的经验，不过想到是你的生日，我还是提前做了一些准备。首先是一套我研究了几天后得到的卡组构筑，风格和你比较契合。另外我调整了这段时间的安排，你有什么想去的地方吗？我可以陪你一起去。虽然生日只有一天，但放松还是需要尽兴，行程安排在三天内即可。\", \"voicelineId\": 71044, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_starUp_01\", \"description\": \"我能感受到新的力量，这是变强的证明。\", \"voicelineId\": 71045, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_starUp_02\", \"description\": \"审判罪恶，维护规则。\", \"voicelineId\": 71046, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_starUp_03\", \"description\": \"不错的提升，多谢你了。\", \"voicelineId\": 71047, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_cyno/vo_cyno_starUp_04\", \"description\": \"力量已达顶峰，然而仅靠这一身武力，仍旧有许多做不到的事情。人情与规则许多时候相互冲突，如何更好地兼顾，我会在今后的旅途中寻找答案。\", \"voicelineId\": 71048, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_skill1_01\", \"description\": \"束手就擒吧。\", \"voicelineId\": 71049, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_skill1_02\", \"description\": \"徒劳的挣扎。\", \"voicelineId\": 71050, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_skill1_03\", \"description\": \"你无处可逃！\", \"voicelineId\": 71051, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_skill1_04\", \"description\": \"裁决已至。\", \"voicelineId\": 71052, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_skill1_05\", \"description\": \"该定罪了。\", \"voicelineId\": 71053, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_skill1_06\", \"description\": \"偿还罪业！\", \"voicelineId\": 71054, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_skill3_01\", \"description\": \"以此身…肃正万象！\", \"voicelineId\": 71055, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_skill3_02\", \"description\": \"判决，如期降临。\", \"voicelineId\": 71056, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_skill3_03\", \"description\": \"称量，你的罪孽。\", \"voicelineId\": 71057, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_chest_open_01\", \"description\": \"应得之物。\", \"voicelineId\": 71058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_chest_open_02\", \"description\": \"贵在恒心。\", \"voicelineId\": 71059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_chest_open_03\", \"description\": \"财富积累，成为文明的基石。\", \"voicelineId\": 71060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_life_less30_01\", \"description\": \"威胁程度…比预想中要高。\", \"voicelineId\": 71061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_life_less30_02\", \"description\": \"差不多也该习惯了。\", \"voicelineId\": 71062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_life_less30_03\", \"description\": \"咳…再来！\", \"voicelineId\": 71063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_life_less30_teammate_01\", \"description\": \"去休整，别逞强！\", \"voicelineId\": 71064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_life_less30_teammate_02\", \"description\": \"我来替你。\", \"voicelineId\": 71065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_life_die_01\", \"description\": \"轮到我了吗…\", \"voicelineId\": 71066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_life_die_02\", \"description\": \"覆灭…新生…终而复始。\", \"voicelineId\": 71067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_life_die_03\", \"description\": \"审判，失败了…\", \"voicelineId\": 71068, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_hit_L_01\", \"description\": \"无用的挣扎。\", \"voicelineId\": 71069, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_hit_H_01\", \"description\": \"真难对付。\", \"voicelineId\": 71070, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_cyno/vo_cyno_battle_hit_H_02\", \"description\": \"有两下子。\", \"voicelineId\": 71071, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_cyno_teamJoin_01\", \"description\": \"我会尽我所能。\", \"voicelineId\": 71072, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_cyno_teamJoin_02\", \"description\": \"行动开始。\", \"voicelineId\": 71073, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_cyno_teamJoin_03\", \"description\": \"这次的目标是谁？\", \"voicelineId\": 71074, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000072, 'Candace', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_draw_appear_01\", \"description\": \"你好呀，远道而来的旅行者，夜晚的沙漠可是很严酷的，不如就在敝处稍住一晚吧，由我来照看你的无梦之夜。\", \"voicelineId\": 72000, \"voicelineType\": \"1000\"}, {\"title\": \"闲聊·盾与枪\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_character_idle_01\", \"description\": \"为了保护珍贵之物，只有盾是不够的。所以…我才会握起枪。\", \"voicelineId\": 72001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·生活\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_character_idle_02\", \"description\": \"希望每个人都平安无事。只要能维持这样的生活，我就心满意足了…\", \"voicelineId\": 72002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·愿望\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_character_idle_03\", \"description\": \"无论以怎样的方法，我都希望守护住那些重要的东西。尽管有时…这会是一种奢望。\", \"voicelineId\": 72003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_weather_heavyRain_01\", \"description\": \"可别着凉了。\", \"voicelineId\": 72004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_weather_thunder_01\", \"description\": \"雷声隆隆——会让你害怕吗？\", \"voicelineId\": 72005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_weather_snowy_01\", \"description\": \"这些白色的东西，冰冰凉凉的…\", \"voicelineId\": 72006, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_weather_gale_01\", \"description\": \"在沙漠里，这样的风会吹起沙暴，得小心了。\", \"voicelineId\": 72007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_weather_desert_01\", \"description\": \"我就在你身旁。若你不放心的话，就请牵着我的手吧。\", \"voicelineId\": 72008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_greetingMorning\", \"description\": \"早上好啊，不知旅者昨夜可曾安然入眠？\", \"voicelineId\": 72009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_greetingNoon\", \"description\": \"已经是中午了，天上明眸之光灼然炫目，不如找个荫凉处歇息一下吧。\", \"voicelineId\": 72010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_greetingNight\", \"description\": \"夜晚啊，在那光芒褪尽的诸多帷帐之后，藏着多少难言的隐秘呢…\", \"voicelineId\": 72011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_greetingNight2\", \"description\": \"嗯，确实已经到休息的时间了，你先去睡吧。我吗？离我入睡的时候还早，夜晚虽然美丽却也危险，我得好好帮你守夜才行啊。\", \"voicelineId\": 72012, \"voicelineType\": \"1004\"}, {\"title\": \"关于坎蒂丝自己·瞳色\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_idle\", \"description\": \"很奇怪吗，不管是琥珀色还是蔚蓝色，应该都还算常见的瞳色吧…\", \"voicelineId\": 72013, \"voicelineType\": \"2001\"}, {\"title\": \"关于坎蒂丝自己·阿如村\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_idle2\", \"description\": \"我自小就在阿如村出生长大，在我尚且懵懂之时就知道，将来一定会从祖父手中接过守护阿如村的职责…如今，这已是我欣然接受的天职了。\", \"voicelineId\": 72014, \"voicelineType\": \"2005\"}, {\"title\": \"关于坎蒂丝自己·父母\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_idle3\", \"description\": \"我的父亲是教令院的学者，当时为了研究才到了阿如村，也由此和我的母亲相遇。关于母亲的事，我全是从父亲口中得知的…在我出生那日，母亲就走入永夜之中了…\", \"voicelineId\": 72015, \"voicelineType\": \"2004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·主客\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_close\", \"description\": \"你永远是阿如村的客人，无论何时，若是在旅途中觉得困倦疲累，你都可以到这儿来歇息一会儿。阿如村永远欢迎你…我永远会欢迎你。\", \"voicelineId\": 72016, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [3021], \"unlockText\": \"完成「赤土之王与三朝圣者」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·宝匣之中\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_close1\", \"description\": \"据说每个人心中都有一个宝匣，他们将珍视之物装入匣中，花上一生的时间好好守护。这样想要守护的东西，在我的宝匣之中也有许多，要猜猜看都有什么吗？\", \"voicelineId\": 72017, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_pendant\", \"description\": \"在我获得「神之眼」的时候，村里不少人都说这是阿赫玛尔的恩眷…但对我来说这并不重要。无论有没有神明的恩赐，我都会履行「守护者」的职责。\", \"voicelineId\": 72018, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_share_01\", \"description\": \"我很喜欢在阿如村度过的日子。同时，在这里度过的每一天也都在提醒我，如果我因为松懈失察而酿成大错的话，就再也无法回到这样的生活了。\", \"voicelineId\": 72019, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_pref_gift_01\", \"description\": \"你有在旅行的途中见过枣椰吗，村里的人经常把它们摘回来做成糖果吃，味道非常甜美。如果感兴趣的话，你也尝尝看吧。\", \"voicelineId\": 72020, \"voicelineType\": \"3003\"}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_teammate_nahida_01\", \"description\": \"草神啊…作为阿赫玛尔血脉延续的我既然能在此安然生存，或许也仰赖她的仁慈吧。不过，虽说心中怀有淡薄的感激之念，但我毕竟是沙漠的子嗣…\", \"voicelineId\": 72021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱依拉…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_teammate_layla_01\", \"description\": \"「状若梦游的古怪少女」么…我确实在防沙壁附近看到过，虽然完全听不懂她说的话和写在纸上的一堆算式…不过，她似乎说完那些心情变好了许多。或许这是她排解心中压力的方式吧。\", \"voicelineId\": 72022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾尔海森…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_teammate_alhaitham_01\", \"description\": \"真是奇怪的须弥学者，跟我接触过的其他学者都有些不太一样，他的想法与见解都很独到…希望他的这份锐利，不会打扰到阿如村的安宁吧。\", \"voicelineId\": 72023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_teammate_cyno_01\", \"description\": \"教令院的大风纪官…之前很少到防沙壁的这一侧来，最近却常常出现。关于他，镀金旅团里似乎流传着一些相当可怕的传说…\", \"voicelineId\": 72024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪希雅…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_teammate_dehya_01\", \"description\": \"迪希雅，她每次带着镀金旅团的人在阿如村寄宿的时候，都能约束好手下的行动，可以说…给我免了很多麻烦。迪希雅小姐，跟看上去大大咧咧的样子不同，是个非常可爱的人哦。\", \"voicelineId\": 72025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛索斯…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_teammate_sethos_01\", \"description\": \"赤王的子民永远保有骄傲，他也是如此。我听说了他的事，赫曼努比斯的威光将与有能力的人共存。听说他最近在须弥城很活跃，还跟赛诺他们提起阿如村，说是想来作客，我很期待。\", \"voicelineId\": 72069, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解坎蒂丝·其一\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_friendship_01\", \"description\": \"想要了解我的事情吗…那算不上是一个好故事，但要是你执意想听的话…那就在入夜之后，由我在篝火边为你讲述吧。\", \"voicelineId\": 72026, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解坎蒂丝·其二\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_friendship_02\", \"description\": \"我们是失去了神明庇护的一族，对我们而言，谎言不是什么敌人，没有明天才是。怀揣谎言行走于痛苦的荆棘之路上，说不定…说不定比自顾自拥抱真相死去的人要高尚一些呢…\", \"voicelineId\": 72027, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解坎蒂丝·其三\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_friendship_03\", \"description\": \"即使到现在，也有人相信赤王有朝一日能够复活，但那是不可能的。一切的过去都如同被吹拂的砂砾，对过往之事来说，随风而去才是最好的归宿。\", \"voicelineId\": 72028, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解坎蒂丝·其四\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_friendship_04\", \"description\": \"我的盾牌？喔，如果按照村外人的说法，这面盾牌上可是有着「贝努」的祝福呢，只要拿着这面盾牌，沙漠里的每一颗沙砾都是我的斥候，沙暴也任我驱使…这其实都是外人的臆想。但无论如何，对我来说…至少这面盾牌用得挺顺手的。\", \"voicelineId\": 72029, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解坎蒂丝·其五\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_friendship_05\", \"description\": \"我真想用这只琥珀色的眼睛，预见你的未来…我想，它大概会是一片金黄，介于阳光和黄金之间，是充满希望的颜色。你的前路一定会顺利，我由衷祝福着它。\", \"voicelineId\": 72030, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"坎蒂丝的爱好…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_pref_hobby\", \"description\": \"在村中散步就是我最喜欢做的事。看到一切都好，就让人觉得今日犹如昨天，昨天犹如过去，而过去又总是好的。\", \"voicelineId\": 72031, \"voicelineType\": \"6001\"}, {\"title\": \"坎蒂丝的烦恼…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_dialog_annoyed\", \"description\": \"偶尔还是会有不长眼的宵小之徒，企图打扰阿如村的宁静。或许…只将那些家伙赶进全是魔兽的山谷里还是太过仁慈了，怎么样，你有更好的建议吗？\", \"voicelineId\": 72032, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_pref_foodLike_01\", \"description\": \"对我来说…食物的分量比口味更重要。在沙漠里生活需要耗费比想象中更多的体力，一天的劳累过后，没有比吃饱肚子更为惬意的事了吧。\", \"voicelineId\": 72033, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_pref_foodDislike\", \"description\": \"倒也没到讨厌的程度，不过相较于肉，鱼吃起来确实非常麻烦…可能也是在沙漠中很少吃鱼的关系吧，我对于那种将刺从鱼肉中剔除的工作并不擅长…让你见笑了。\", \"voicelineId\": 72034, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_spice_pref_01\", \"description\": \"好吃极了，为做出这样的美食，你想必付出了相当的努力吧。\", \"voicelineId\": 72035, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_spice_normal_01\", \"description\": \"明明是四处漂泊的旅人，你做的饭，却有家的味道呢。\", \"voicelineId\": 72036, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_spice_dislike_01\", \"description\": \"或许是我对可食用之物的定义太过保守…\", \"voicelineId\": 72037, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_pref_birthday_01\", \"description\": \"祝你生日快乐！多了不起啊，你在过去某年某月的这一天出生了。有什么想要实现的愿望吗。如果要去险远之处，我就作你旅途的护卫。若是想稍作休息，那就来阿如村，我用最好的烤肉和饮料招待你。\", \"voicelineId\": 72038, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_starUp_01\", \"description\": \"感觉到了更坚实的力量，希望我可以保护更多…\", \"voicelineId\": 72039, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_starUp_02\", \"description\": \"更坚固的盾，和更锋利的枪。我曾听说过一个枪和盾的故事…不，我不会做出枪盾相击的尝试。\", \"voicelineId\": 72040, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_starUp_03\", \"description\": \"人在「现在」获得的力量，或许都是为了应对「将来」的不安。就像我过去锻炼枪术和持盾的技巧，实际上都是为了守护现在的安稳。\", \"voicelineId\": 72041, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_candace/vo_candace_starUp_04\", \"description\": \"现在的我，已经可以站在你的身前，替你挡下所有的危险。如果你相信我的话，就请闭上双眼，将敌人交给我吧。\", \"voicelineId\": 72042, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_skill1_01\", \"description\": \"破！\", \"voicelineId\": 72043, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_skill1_02\", \"description\": \"走开！\", \"voicelineId\": 72044, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_skill1_03\", \"description\": \"来吧！\", \"voicelineId\": 72045, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_skill1_04\", \"description\": \"坠刺！\", \"voicelineId\": 72046, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_skill1_05\", \"description\": \"不过如此！\", \"voicelineId\": 72047, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_skill1_06\", \"description\": \"有破绽！\", \"voicelineId\": 72048, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_skill3_01\", \"description\": \"听取我的战祷！\", \"voicelineId\": 72049, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_skill3_02\", \"description\": \"赐予我们祝福！\", \"voicelineId\": 72050, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_skill3_03\", \"description\": \"此为守护之战！\", \"voicelineId\": 72051, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_chest_open_01\", \"description\": \"都是些有用之物呀…\", \"voicelineId\": 72052, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_chest_open_02\", \"description\": \"怎么样，有看得上眼的么？\", \"voicelineId\": 72053, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_chest_open_03\", \"description\": \"希望里面有能帮上你的东西。\", \"voicelineId\": 72054, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_life_less30_01\", \"description\": \"不用手下留情了。\", \"voicelineId\": 72055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_life_less30_02\", \"description\": \"仍不悔改吗？\", \"voicelineId\": 72056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_life_less30_03\", \"description\": \"请你们，滚开…\", \"voicelineId\": 72057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_life_less30_teammate_01\", \"description\": \"好好休息一下…\", \"voicelineId\": 72058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_life_less30_teammate_02\", \"description\": \"站我身后吧！\", \"voicelineId\": 72059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_life_die_01\", \"description\": \"仍需磨炼…\", \"voicelineId\": 72060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_life_die_02\", \"description\": \"对不起，我没能守护…\", \"voicelineId\": 72061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_life_die_03\", \"description\": \"盾，破碎了…\", \"voicelineId\": 72062, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_hit_L_01\", \"description\": \"没问题。\", \"voicelineId\": 72063, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_hit_H_01\", \"description\": \"了不起。\", \"voicelineId\": 72064, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_candace/vo_candace_battle_hit_H_02\", \"description\": \"小伤罢了…\", \"voicelineId\": 72065, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_candace_teamJoin_01\", \"description\": \"怎么了，遇到危险了吗？\", \"voicelineId\": 72066, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_candace_teamJoin_02\", \"description\": \"记得跟紧我哦。\", \"voicelineId\": 72067, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_candace_teamJoin_03\", \"description\": \"我会保证你的安全。\", \"voicelineId\": 72068, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000073, 'Nahida', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_draw_appear_01\", \"description\": \"初次见面，我已经关注你很久了。我叫纳西妲，别看我像个孩子，我比任何一位大人都了解这个世界。所以，我可以用我的知识，换取你路上的见闻吗？\", \"voicelineId\": 73000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·邀请\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_character_idle_01\", \"description\": \"不知道干什么的话，要不要我带你去转转呀？\", \"voicelineId\": 73001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·心事\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_character_idle_02\", \"description\": \"又有心事吗？我来陪你一起想吧。\", \"voicelineId\": 73002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·感受\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_character_idle_03\", \"description\": \"果然要亲眼去看，才能感受到世界的美。\", \"voicelineId\": 73003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_weather_heavyRain_01\", \"description\": \"快去避雨吧，小心头顶上长出蘑菇哦。\", \"voicelineId\": 73004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_weather_thunder_01\", \"description\": \"你知道吗？雷鸣是生命的前奏，很快这片大地就会充满生机。\", \"voicelineId\": 73005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_weather_snowy_01\", \"description\": \"听见了吗？天空正对万物轻语：「睡觉时间到了哦。」\", \"voicelineId\": 73006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_weather_sunny_01\", \"description\": \"天气真好啊，暖洋洋的，我们的身边马上也要热闹起来了。\", \"voicelineId\": 73007, \"voicelineType\": \"1204\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_weather_breezy_01\", \"description\": \"宫殿里可不会起风呢…哦，抱歉，对你来说是理所当然的知识吧。\", \"voicelineId\": 73008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_greetingMorning\", \"description\": \"早上好，我们赶快出发吧，这世上有太多的东西都是「过时不候」的呢。\", \"voicelineId\": 73009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_greetingNoon\", \"description\": \"午休时间到，我想喝树莓薄荷饮。用两个和太阳有关的故事和你换，好不好？\", \"voicelineId\": 73010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_greetingNight\", \"description\": \"太阳落山啦，我们也该把舞台让给夜行的大家族了。\", \"voicelineId\": 73011, \"voicelineType\": \"1003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_greetingNight2\", \"description\": \"快去睡吧，放心，我已经为你准备好甜甜的梦啦。\", \"voicelineId\": 73012, \"voicelineType\": \"1004\"}, {\"title\": \"关于纳西妲自己·见识\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_idle\", \"description\": \"烬寂海啊，那里什么都没有，就像蕈猪的脑子一样空空如也，我当然知道。啊？我…我确实没有亲眼见过，那也是我所触及不到的地方呀。\", \"voicelineId\": 73013, \"voicelineType\": \"2001\"}, {\"title\": \"关于纳西妲自己·痴迷\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_idle2\", \"description\": \"神明只送给人类填饱肚子的知识，人类却借此制作了工具，书写了文字，壮大了城邦，现在又放眼星辰与深渊…他们每时每刻都在创造全新的「知识」，也令我再也无法移开双眼。\", \"voicelineId\": 73014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·故事会\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_close\", \"description\": \"你旅途中的见闻，比我学习到的知识要精彩太多，而且我还能随时提问，把所有的细节都了解到一清二楚…真是太满足了。好了好了，别浪费时间，我们快继续吧。\", \"voicelineId\": 73015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·旅行\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_close1\", \"description\": \"我早就不满足于当一个听众了，一直都想出去看看。你冒险经验这么丰富，当我的向导好不好啊？你之后所有的故事，我都想亲身感受。\", \"voicelineId\": 73016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_pendant\", \"description\": \"天空长出眼睛是为了见证大地的美好，而本来就拥有双眼的人类，是在什么样的情况下，才需要靠「神之眼」观察这个世界呢？这个问题的答案，聪明的你能够明白吗？\", \"voicelineId\": 73017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_share_01\", \"description\": \"很多时候，我们直到经受切肤之痛，才不得不直视自身的懒惰，愚昧，鲁莽或傲慢。但大可不必为此懊悔，我们无法观测未来的所有可能性，只能靠这样略显笨拙的方式获取知识。学费而已，再正常不过啦。\", \"voicelineId\": 73018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻·未见之花\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_pref_gift_01\", \"description\": \"须弥的沙漠看上去比雨林缺乏生机，但它也承载了久远的文明，孕育了稳定的生态。等哪天它不再和雨林吵架了，一定能开出我从来没见过的花吧。\", \"voicelineId\": 73019, \"voicelineType\": \"3003\"}, {\"title\": \"关于赛诺·笑话\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_cyno_01\", \"description\": \"他讲的笑话确实深奥，还挺有意思的。嗯？你有哪句没听懂吗？那我解释给你听吧。\", \"voicelineId\": 73020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺·职责\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_cyno_02\", \"description\": \"在面对秩序与正义的冲突之时，不是每一位「大风纪官」都能得出绝对坚定的答案。他应该最清楚，妥协的结果只有无路可退，所以他现在能回到属于他的位置上，对整个须弥而言都是一大幸事。\", \"voicelineId\": 73021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_tighnari_01\", \"description\": \"雨林能够对抗「死域」的侵蚀，至今都生机焕发，巡林官们的付出举足轻重，而提纳里又是他们之中的佼佼者。只是…希望他可以稍稍温柔一些，这样才更有利于巡林员招新纳贤嘛。\", \"voicelineId\": 73022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于柯莱…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_collei_01\", \"description\": \"我听说过她的故事，她的坚韧如宝石般璀璨夺目。她经历了太多，希望须弥的葱绿能够长久地庇护她，令她像普通的女孩子那样健康成长。\", \"voicelineId\": 73023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾尔海森…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_alhaitham_01\", \"description\": \"他拥有很超前的知识体系，并且每时每刻都在保持思考，或许这个世界上没有什么事能瞒过他吧。然而对智慧者而言，普通人的凡庸是一种与生俱来的错吗？那都是「我们」不可分割的一部分。\", \"voicelineId\": 73024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于妮露…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_nilou_01\", \"description\": \"我曾经借用别人的身体，问她想不想让小吉祥草王来看她的舞蹈…虽然我已经悄悄看了很多次，但按理来说，应该要我本人到场，才算是对她「花神诞祭」表演的尊重。结果我却被委婉地拒绝了…唔，有点伤心。\", \"voicelineId\": 73025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于多莉…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_dori_01\", \"description\": \"她见到我的第一句话就是，「我看上了你的宫殿，怎么卖啊？」净善宫怎么可能卖给她呢？不过她的问题确实把我问住了，我想了好久，也不知道净善宫该定价多少摩拉…\", \"voicelineId\": 73026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡维…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_kaveh_01\", \"description\": \"他对须弥推行智慧这一事的理解，已经非常接近本质了，很可惜的是，他掌握的真相无法成为这个国度的主流。什么？你说他和艾尔海森是室友？世上居然还有这种可能性…\", \"voicelineId\": 73027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珐露珊…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_faruzan_01\", \"description\": \"她的身体遭受了赤王遗迹中残留力量的影响，就像是被时间这只大乌龟不小心甩下了背，永远忘在了身后。如果你感兴趣的话，应该能从她身上窥见过去须弥的一角吧。\", \"voicelineId\": 73028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于尘世七执政·引荐\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_theSeven_01\", \"description\": \"好像尘世七执政之间在很久很久以前还会定期联络，只是我的情况比较特殊，已经不记得这段经历了…既然须弥的混乱告一段落，我觉得我该重新见他们一面。你熟识的那几位神明，能为我引荐一下吗？\", \"voicelineId\": 73029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于尘世七执政·游戏\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_theSeven_02\", \"description\": \"听说玩游戏能够快速缩短人与人之间的距离。神也是如此吧。不如，在和大家相聚之后，我就主动提议一起玩「跳房子」…好像也不合适。弄得像是我把房门做成了小小的洞口，仗着自己的优势欺负大家一样。\", \"voicelineId\": 73030, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于散兵…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_scaramouche_01\", \"description\": \"当他自认为追寻已久的愿望终于实现，他眼中所见的究竟是满足，还是更大的空虚呢？正是因为我们不会飞，才会无比向往天空…让他好好想想吧，在拥抱过空无一物的天空之后。\", \"voicelineId\": 73031, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_teammate_furina_01\", \"description\": \"人们常说，智慧并不取决于知道些什么，而是取决于可以改变些什么。毫无疑问，那个「预言」早就刻写在了世界树中…明明好像一切都没改变一样，但又好像什么都已经改变了。你我都知道，她是聪明到可以扭转世界命运的人呀。\", \"voicelineId\": 73074, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解纳西妲·其一\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_friendship_01\", \"description\": \"我的过往相当单调，估计你听上一会儿就会像炮鲀吸水那样打哈欠。不过好奇心是弥足珍贵的东西，我也不想浪费…既然这样，我给你分享一些我做过的梦吧。\", \"voicelineId\": 73032, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解纳西妲·其二\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_friendship_02\", \"description\": \"我的梦中总会出现一个花盆，每次浇水施肥就会长出相同的花。对于完全确定的收获，你还能享受养花的过程吗？呵呵，对我来说，至少每次开花之后飞过的蝴蝶，都有不一样的颜色，有时候还会有蜜蜂呢。\", \"voicelineId\": 73033, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解纳西妲·其三\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_friendship_03\", \"description\": \"我的梦中总会出现一个沙漏，我喜欢往里面加一点点水，搅匀之后看它走完一次需要多长时间，和上一次又差了多少。没有规律，也没有意义，却能带走我大脑积累的疲惫，我想「什么都没有」正是它的乐趣所在。\", \"voicelineId\": 73034, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解纳西妲·其四\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_friendship_04\", \"description\": \"我的梦中总会出现一片空地，无论周遭的景色如何变化，它都会占据最重要的位置，挺奇怪的吧？我觉得这里曾经应该存在过什么东西，可就算我驱使梦境的权能也无法获得答案。唔，居然梦中也有我不能掌控的东西…\", \"voicelineId\": 73035, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解纳西妲·其五\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_friendship_05\", \"description\": \"我的梦中什么都有，唯独缺少来来往往的人。但在与你相遇之后，这里渐渐变得热闹了。或许你在梦中扮演的是「向导」这样的角色，不仅让我的梦变得更有人情味，也带我走出了牢笼。呵呵，走吧，接下来的旅途也请你引路了。\", \"voicelineId\": 73036, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"纳西妲的爱好…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_pref_hobby\", \"description\": \"就这么看着你，算是爱好吗？因为你的一举一动都让我很好奇啊。作为世界的旅行者，你从哪里来，将到哪里去，会遇到什么人，战胜什么困难，都是我想寻求的答案。你不用太在意我，就让我一直观察你吧。\", \"voicelineId\": 73037, \"voicelineType\": \"6001\"}, {\"title\": \"纳西妲的烦恼…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_dialog_annoyed\", \"description\": \"我自认为我擅长提问和回答问题，但我渐渐明白，有很多人是揣着明白装糊涂，问题的答案并不能帮上他们的忙。是不是随着年龄增长，大家都会失去面对质问和答案的勇气呢…\", \"voicelineId\": 73038, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_pref_foodLike_01\", \"description\": \"当然是枣椰蜜糖了，只要吃上一小块，大脑就会噼里啪啦地飞速运转，没什么问题解决不了。唯一需要注意的是，装蜜糖的罐子不能放在太容易伸手够到的地方。\", \"voicelineId\": 73039, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_pref_foodDislike\", \"description\": \"那些海鲜，它们在无边无际的黑暗中出生，成长在我所不了解的海底深处。要我吃下它们，就好像要我咽下一团脏兮兮的乌云一样。\", \"voicelineId\": 73040, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_spice_pref_01\", \"description\": \"像这样的好味道，应该被世界永久记录下来。谢谢你。\", \"voicelineId\": 73041, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_spice_normal_01\", \"description\": \"呵呵，你的心意我收到了，味道也可圈可点。\", \"voicelineId\": 73042, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_spice_dislike_01\", \"description\": \"…怎么说呢？打比方的话，你不会给狗狗喝蔬菜汁吧？\", \"voicelineId\": 73043, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_pref_birthday_01\", \"description\": \"我想了想，要庆祝你的生日，至少也要像「花神诞祭」一样隆重…欸？太夸张了吗？可是我都让人准备好了，走吧走吧，仅限一次也好，绝对会让你满意的！\", \"voicelineId\": 73044, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_starUp_01\", \"description\": \"变聪明啦~\", \"voicelineId\": 73045, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_starUp_02\", \"description\": \"思路变得更开阔了，天空和大海都能装进去。\", \"voicelineId\": 73046, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_starUp_03\", \"description\": \"这种感觉，就像月莲找到了莲叶，珊瑚真珠找到了贝壳。\", \"voicelineId\": 73047, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_nahida/vo_nahida_starUp_04\", \"description\": \"感谢你愿意让我成为你的同伴，还教会了我那么多新的知识。我以智慧之神的名义为你赐福，从今往后不再会有困惑阻碍你的旅途。\", \"voicelineId\": 73048, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_skill1_01\", \"description\": \"记住你了。\", \"voicelineId\": 73049, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_skill1_02\", \"description\": \"蔓延吧。\", \"voicelineId\": 73050, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_skill1_03\", \"description\": \"等下有点痛哦。\", \"voicelineId\": 73051, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_skill1_04\", \"description\": \"嘿！\", \"voicelineId\": 73052, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_skill1_05\", \"description\": \"手牵手~\", \"voicelineId\": 73053, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_skill1_06\", \"description\": \"全都看见咯。\", \"voicelineId\": 73054, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_skill3_01\", \"description\": \"来我家做客吧~\", \"voicelineId\": 73055, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_skill3_02\", \"description\": \"知识，与你分享。\", \"voicelineId\": 73056, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_skill3_03\", \"description\": \"此即智慧之殿堂。\", \"voicelineId\": 73057, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_chest_open_01\", \"description\": \"好奇心值得嘉奖哦。\", \"voicelineId\": 73058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_chest_open_02\", \"description\": \"是源自谁的馈赠呢？\", \"voicelineId\": 73059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_chest_open_03\", \"description\": \"有你想要的吗？\", \"voicelineId\": 73060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_life_less30_01\", \"description\": \"换个策略吧。\", \"voicelineId\": 73061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_life_less30_02\", \"description\": \"别打啦！\", \"voicelineId\": 73062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_life_less30_03\", \"description\": \"这样不太明智…\", \"voicelineId\": 73063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_life_less30_teammate_01\", \"description\": \"让我来想想办法。\", \"voicelineId\": 73064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_life_less30_teammate_02\", \"description\": \"别再硬撑了。\", \"voicelineId\": 73065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_life_die_01\", \"description\": \"生命…终有尽时…\", \"voicelineId\": 73066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_life_die_02\", \"description\": \"枯萎之刻…\", \"voicelineId\": 73067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_life_die_03\", \"description\": \"我…不明白…\", \"voicelineId\": 73068, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_hit_H_01\", \"description\": \"好痛啊。\", \"voicelineId\": 73069, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_nahida/vo_nahida_battle_hit_H_02\", \"description\": \"被打晕了…\", \"voicelineId\": 73070, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_nahida_teamJoin_01\", \"description\": \"我等你好久啦。\", \"voicelineId\": 73071, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_nahida_teamJoin_02\", \"description\": \"没去过的地方还有很多呢。\", \"voicelineId\": 73072, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_nahida_teamJoin_03\", \"description\": \"又可以增长见识了。\", \"voicelineId\": 73073, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000074, 'Layla', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_draw_appear_01\", \"description\": \"哈…你好，我是梨多梵谛学院的在读学生莱依拉。…嗯？对不起，昨天没睡好我现在精神有点差，你刚才是在说「想和我组队」吗？\\n没有没有，我不是不愿意，只是怕你不习惯我的作息方式…那、那个…请多关照！\", \"voicelineId\": 74000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·注视\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_character_idle_01\", \"description\": \"就算我们不抬头仰望，星空，也永远注视着我们。\", \"voicelineId\": 74001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·梦游\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_character_idle_02\", \"description\": \"腿好酸…唉，大概昨天晚上又梦游了吧。\", \"voicelineId\": 74002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·哀叹\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_character_idle_03\", \"description\": \"…为什么报告和论文永远写不完？为什么？\", \"voicelineId\": 74003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_weather_heavyRain_01\", \"description\": \"天气好差，今晚没法观测星空的话…唉，我的星图课作业真的不能再拖了啊…\", \"voicelineId\": 74004, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_weather_snowy_01\", \"description\": \"雪地看起来亮晶晶的，很像天上的星星。\", \"voicelineId\": 74005, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_weather_sunny_01\", \"description\": \"太阳晒着…好困…对，保持这个感觉，赶快找个枕头睡一觉…我已经两天、两天没有…\", \"voicelineId\": 74006, \"voicelineType\": \"1203\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_weather_desert_01\", \"description\": \"白天晒，晚上冷，我、我要不行了。\", \"voicelineId\": 74007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_greetingMorning\", \"description\": \"你睡得饱吗？要是还困就回去再睡会儿吧…我？我…习惯了…\", \"voicelineId\": 74008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_greetingNoon\", \"description\": \"我在计算星轨呢，刚算到一半，午饭你就先吃好了…这里的角度不太对劲吧…不、不会吧…我是从哪儿开始算错了呢？\", \"voicelineId\": 74009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_greetingNight\", \"description\": \"今晚我要早早躺到床上去，争取早点睡着。伟大的智慧之神啊，求您庇护我的睡眠。好，我要闭上眼睛。\", \"voicelineId\": 74010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_greetingNight2\", \"description\": \"…哈，让我看看她又被什么难住了。嗯…要整理三年份的旧星表，中期报告的附录还缺几张星图没画…好吧，从这份开始。\\n嗯，你怎么来了？现在可是最重要的睡眠时间。我？我当然是在梦游了。\", \"voicelineId\": 74011, \"voicelineType\": \"1004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱依拉自己·理论星相学\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_idle\", \"description\": \"按照教科书上的说法：「利用理论星相学知识解决具体生活中的麻烦，这不是我们该关心的问题。」其实我觉得还有一个重要原因…就是…嗯，成本太高。我们测算的时候，一般会动用好多台星象仪，至少要查阅一年份的星图，才好给出一套…严谨的答案。但如果是为了算明天香料会不会涨价，怎么想都不太划算吧…\", \"voicelineId\": 74012, \"voicelineType\": \"2001\"}, {\"title\": \"关于莱依拉自己·理由\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_idle2\", \"description\": \"既然有了自己喜欢又能做得好的事，就得坚持下去，哪怕这条道路特别艰辛，哪怕一路上竞争极其激烈，哪怕不一定能顺利毕业，哪怕没能顺利毕业的话，就要把所有的奖学金还回去…啊，要不我还是回家吧。\", \"voicelineId\": 74013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·陪伴\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_close\", \"description\": \"嗯哼，我也不想熬夜补课题进度，可谁叫她总有那么多做不完的事。没办法，我当然得帮帮她咯。…你想陪我一起吗？\", \"voicelineId\": 74014, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·漫游世界\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_close1\", \"description\": \"如果毕业之后，我没有留在教令院工作，就和你一起去漫游世界吧。你觉得怎么样？\", \"voicelineId\": 74015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_pendant\", \"description\": \"哈…是什么在亮？我睡觉的时候忘了关灯吗…哦，是神之眼啊，我说呢…欸，不对，我睡觉之前…把它放在床头了吗？\", \"voicelineId\": 74016, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_share_01\", \"description\": \"我们学院主编的星表汇聚了所有生灵的命运，毫无疑问是占星知识的顶峰，第一次看到的时候我整个人都被吓得说不出话了！欸？你感兴趣吗？只是简单看看的话…我帮你提交申请吧，应该能被批准，应该…\", \"voicelineId\": 74017, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_pref_gift_01\", \"description\": \"有没有什么能捕虫的植物啊，快救救我吧。晚上本来就睡不着，房间里还有小飞虫，一直嗡嗡响个不停，但我、我怎么找都找不到它在哪里…呜呜…\", \"voicelineId\": 74018, \"voicelineType\": \"3003\"}, {\"title\": \"关于莫娜…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_teammate_mona_01\", \"description\": \"在明论派学者的小圈子里，阿斯托洛吉斯·莫娜·梅姬斯图斯发表在《蒸汽鸟报》上的星相学文章名气不小。那些文章专业性都很强，但却能被学者之外的群体喜欢，要做到这点还是挺不容易的…欸？我把她的名字念得很流利？因为…厉害的人…得多多尊敬。\", \"voicelineId\": 74019, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_teammate_lisa_01\", \"description\": \"啊，我知道你在说谁了。丽莎·敏兹，传说中只用了两年就学成毕业的素论派天才，要是我也能有这样的头脑…你在蒙德的时候见过她本人？真、真的吗？她平时都是怎么学习的？看些什么书，做些什么工作？我…我该从哪里向她学起？\", \"voicelineId\": 74020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于多莉…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_teammate_dori_01\", \"description\": \"多、莉、吗…我咬着牙、攥着拳头在她那里买过一次东西，她看我结账很痛快，好像误以为我是什么有钱人，后来还一直寄商品宣传单给我，唔…真是天大的误会！那次购物的代价…不仅把我的奖学金垫进去了，接下来的大半年里，我吃饭都不敢多要肉，买书还得等打折…\", \"voicelineId\": 74021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_teammate_cyno_01\", \"description\": \"「大风纪官」大人很擅长「七圣召唤」吗…啊我是在想，有机会的话，说不定可以和他打一局。像「七圣召唤」这种牌类游戏，熟练掌握运算技巧的人玩起来总是简单一点，我反而…不一定…或许不会输给他。\", \"voicelineId\": 74022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于坎蒂丝…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_teammate_candace_01\", \"description\": \"我第一次梦游醒来的时候，曾经见到过你描述的这个人，原来她叫坎蒂丝啊。我还记得自己醒来的那一刻…所有报告和文章都被完成了。当时的感觉就好像…好像我每天对着星空念叨，终于被星星听见了，它们派了一位使者来帮助我，呜呜…太感动了！\", \"voicelineId\": 74023, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾尔海森…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_teammate_alhaitham_01\", \"description\": \"职务达到书记官这种高度的人，应该就不用发愁能不能立项、能不能成功了吧。不对，既然都当了书记官，应该连项目都不用做了。真好啊…\", \"voicelineId\": 74024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_teammate_nahida_01\", \"description\": \"伟大的智慧之神，我最近每晚都在熬夜复习，考试就请让我通过吧！拜托了拜托了…\", \"voicelineId\": 74025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珐露珊…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_teammate_faruzan_01\", \"description\": \"珐露珊老师招到学生了吗？听知论派的人说，她的项目申请经费一直很难，招不到学生也很正常。唉…\", \"voicelineId\": 74026, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莱依拉·其一\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_friendship_01\", \"description\": \"我算不上有天赋，领悟力也不太够…拼命读书通过考试这才进了教令院。对不起，我…我先不跟你闲聊了，一说到教令院我就想起来，我的课题进度报告…到现在为止还没有进度呢。\", \"voicelineId\": 74027, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解莱依拉·其二\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_friendship_02\", \"description\": \"我和导师的关系吗？嗯…怎么说呢…啊，你不要误会了，其实导师对我挺好的，我入学的时候还得到了她的推荐呢。每次我觉得自己要撑不住了，她都会鼓励我，然后顺便多要求一篇论文…\", \"voicelineId\": 74028, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莱依拉·其三\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_friendship_03\", \"description\": \"整个须弥最有才能的人几乎都到教令院来了，而且这儿还有那么多聪明得让人发抖的外国学者，你想想，这里的竞争该有多大！和这些人一起学习…我真的够格吗？\", \"voicelineId\": 74029, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莱依拉·其四\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_friendship_04\", \"description\": \"嘘，小声点，不要吵醒她，就让她安心睡上一觉吧。你问我嘴里的「她」是谁？哦，当然是每天为课业抓耳挠腮的莱依拉呀。那我是谁？呵呵，我也是莱依拉呀。\", \"voicelineId\": 74030, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莱依拉·其五\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_friendship_05\", \"description\": \"我听别人提过，她好像以为所有写不完的课业总能在一场梦之后自动完成，都是「星空的赐福」。她呀，完全搞错了哦。…不过，你可别告诉她哦。\", \"voicelineId\": 74031, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"莱依拉的爱好…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_pref_hobby\", \"description\": \"画星图真的是件累人的事，如果不是因为喜欢，我恐怕也坚持不下来。一会儿要用尺、一会儿要拿纸算、一会儿要查历年的星象…不知不觉一天时间就过去了。但看着画得整整齐齐的巨大星图，总是很有成就感。\", \"voicelineId\": 74032, \"voicelineType\": \"6001\"}, {\"title\": \"莱依拉的烦恼…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_dialog_annoyed\", \"description\": \"从前我还没进入教令院念书的时候，睡眠质量还算过得去。但自从在这里学习之后…唔，压力实在是太恐怖了…我真的很想每天安安稳稳一觉到天亮，呜呜…\", \"voicelineId\": 74033, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_pref_foodLike_01\", \"description\": \"每晚我躺上床之前，都会为自己热一杯牛奶喝，希望夜里能有个好觉，希望夜里能有个好觉，希望夜里能有个好觉。\", \"voicelineId\": 74034, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_pref_foodDislike\", \"description\": \"有一次，我听人说，有个神奇商人在卖的「睡眠软糖」很有效。我花光了奖学金和攒下的零花钱试了试，确实有效，那阵子我也睡得很好。但一盒卖二十万摩拉…实在太贵了，我、我绝对不会再买了，买一送一也不行，买一送二的话…我就再考虑考虑。\", \"voicelineId\": 74035, \"voicelineType\": \"6004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_spice_pref_01\", \"description\": \"好厉害，好羡慕，你还真是什么都会呀。\", \"voicelineId\": 74036, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_spice_normal_01\", \"description\": \"…嗯，味道还算不错。\", \"voicelineId\": 74037, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_spice_dislike_01\", \"description\": \"要不…我们还是去店里买外带吧？\", \"voicelineId\": 74038, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_pref_birthday_01\", \"description\": \"生日快乐，我把这个袖珍星盘送给你。希望从过去到未来，见证了我们所有人类命运的星星能把目光分给你，伴随你走过沙漠、穿过海洋，到达你所探寻的终点。\", \"voicelineId\": 74039, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_starUp_01\", \"description\": \"莱依拉啊莱依拉，你还要更勤奋。\", \"voicelineId\": 74040, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_starUp_02\", \"description\": \"莱依拉啊莱依拉，你已经很勤奋了，不过你的知识还不够全面。\", \"voicelineId\": 74041, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_starUp_03\", \"description\": \"莱依拉啊莱依拉，你读书又勤奋又广博，这很好。但你可千万不能松懈，一时懈怠，就会落后于人，最后悲惨延毕。\", \"voicelineId\": 74042, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_layla/vo_layla_starUp_04\", \"description\": \"莱依拉啊莱依拉，要相信自己，也要相信帮了你那么多的那个人。你们一起，什么问题都能解决！\\n呼…好了，所有担心我都抛到脑后了，咱们出发吧！\", \"voicelineId\": 74043, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_battle_skill1_01\", \"description\": \"寒星！\", \"voicelineId\": 74044, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_battle_skill1_02\", \"description\": \"拒绝打扰！\", \"voicelineId\": 74045, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_battle_skill1_03\", \"description\": \"星星的加护。\", \"voicelineId\": 74046, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_battle_skill3_01\", \"description\": \"星辰，为我降下。\", \"voicelineId\": 74047, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_battle_skill3_02\", \"description\": \"极寒，任我驱使。\", \"voicelineId\": 74048, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_battle_skill3_03\", \"description\": \"别害怕。\", \"voicelineId\": 74049, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_chest_open_01\", \"description\": \"性价比不错。\", \"voicelineId\": 74050, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_chest_open_02\", \"description\": \"还是你眼睛尖。\", \"voicelineId\": 74051, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_chest_open_03\", \"description\": \"哇！突然感觉不困了。\", \"voicelineId\": 74052, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_life_less30_01\", \"description\": \"我好困…\", \"voicelineId\": 74053, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_life_less30_02\", \"description\": \"完了完了完了…\", \"voicelineId\": 74054, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_life_less30_03\", \"description\": \"现在逃还来得及吗？\", \"voicelineId\": 74055, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_life_less30_teammate_01\", \"description\": \"醒醒，别昏过去！\", \"voicelineId\": 74056, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_life_less30_teammate_02\", \"description\": \"糟了糟了，你、你受伤了！\", \"voicelineId\": 74057, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_life_die_01\", \"description\": \"永恒的睡眠…\", \"voicelineId\": 74058, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_life_die_02\", \"description\": \"老师，对不起…\", \"voicelineId\": 74059, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_life_die_03\", \"description\": \"拜托了，这是个…梦…\", \"voicelineId\": 74060, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_battle_hit_H_01\", \"description\": \"你不讲理！\", \"voicelineId\": 74061, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_layla/vo_layla_battle_hit_H_02\", \"description\": \"这是违反规定的！\", \"voicelineId\": 74062, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_layla_teamJoin_01\", \"description\": \"睡不着就四处走走吧。\", \"voicelineId\": 74063, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_layla_teamJoin_02\", \"description\": \"请好假了…没有忘的吧？\", \"voicelineId\": 74064, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_layla_teamJoin_03\", \"description\": \"唉，脑袋空空，出去放松。\", \"voicelineId\": 74065, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000075, 'Wanderer', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_draw_appear_01\", \"description\": \"要我报上名来？此行世间，我名号诸多，虽然随便一个对凡人来说都高不可及，但于我都已成过往。\\n想称呼什么就随你吧，让我见识下你的品味，可别让我失望。\", \"voicelineId\": 75000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·风\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_character_idle_01\", \"description\": \"这世上没有纯粹的自由。风也会有吹到头的时候。\", \"voicelineId\": 75001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·说话方式\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_character_idle_02\", \"description\": \"我说话刻薄吗？只是实话实说罢了，接受不了的人才该自己反思原因。\", \"voicelineId\": 75002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·寒暄\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_character_idle_03\", \"description\": \"寒暄就免了吧，没话找话的样子也太可笑了。\", \"voicelineId\": 75003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_weather_heavyRain_01\", \"description\": \"想用我的斗笠遮雨？亏你提得出这种要求。\", \"voicelineId\": 75004, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_weather_afterRain_01\", \"description\": \"见了点阳光就能高兴成这个样子？幼稚。\", \"voicelineId\": 75005, \"voicelineType\": \"1202\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_weather_thunder_01\", \"description\": \"啧…烦心。\", \"voicelineId\": 75006, \"voicelineType\": \"1203\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_weather_snowy_01\", \"description\": \"明明和雨没什么区别，却讨人喜欢多了…真是人各有命。\", \"voicelineId\": 75007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_weather_gale_01\", \"description\": \"这点程度，你都能做到吧？\", \"voicelineId\": 75008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_greetingMorning\", \"description\": \"「快醒醒——太阳要晒屁股咯——」…哈，你不会以为我会这么叫你起床吧？\", \"voicelineId\": 75009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_greetingNoon\", \"description\": \"我不需要吃饭。管好你自己和身边的小东西，就算是让我省心了。\", \"voicelineId\": 75010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_greetingNight\", \"description\": \"终于，无聊的一天就要结束了。\", \"voicelineId\": 75011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_greetingNight2\", \"description\": \"在我身边睡不着吗？呵呵。\", \"voicelineId\": 75012, \"voicelineType\": \"1004\"}, {\"title\": \"#关于{REALNAME[ID(1)]}自己·人偶\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_idle\", \"description\": \"烧掉一个人偶会留下灰烬。至于灰烬中会诞生什么…\", \"voicelineId\": 75013, \"voicelineType\": \"2001\"}, {\"title\": \"#关于{REALNAME[ID(1)]}自己·心\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_idle2\", \"description\": \"那种东西随便了。执着于注定不属于自己的事物只是在浪费时间，现在的我有更重要的事情要做。\", \"voicelineId\": 75014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3032], \"unlockText\": \"完成「倾落伽蓝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·对手\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_close\", \"description\": \"对你我以前的对峙耿耿于怀？哦。所以呢，你要怎么做？慢慢想，我不急。\", \"voicelineId\": 75015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·同伙\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_close1\", \"description\": \"我不可能皈依「正义」，但既然说过要偿还你的恩情，就定会做到。\\n倒是你，在和我接触的时候可能需要想想自己立场哦？万一被人撞见，说你与罪人「狼狈为奸」，我可概不负责。\", \"voicelineId\": 75016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3032], \"unlockText\": \"完成「倾落伽蓝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_pendant\", \"description\": \"所谓「神明的注视」令人不爽，但反正是可用的力量，我不挑。你觉得「风元素」有其深意？呵，为什么会这么想？神明行事蛮横又无理，我不是让你领教过吗？\", \"voicelineId\": 75017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3032], \"unlockText\": \"完成「倾落伽蓝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_share_01\", \"description\": \"没有。你想问什么就问吧，我看心情回答。\", \"voicelineId\": 75018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_pref_gift_01\", \"description\": \"看啊，鸟雀会炫耀羽毛，松鼠忙着囤积食物，人类为了柴米油盐整日奔走。头脑简单的生物活得就是比较容易呢。\", \"voicelineId\": 75019, \"voicelineType\": \"3003\"}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_nahida_01\", \"description\": \"她选择不除掉我，或许不只是因为我有利用价值。也许是因为她很贤明，又有至善之心，又或许，是她在我身上看到了孤独的影子…你说我是在恶意揣测？哈，这不是当然的事情嘛！我又不是什么好人。\", \"voicelineId\": 75020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3032], \"unlockText\": \"完成「倾落伽蓝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_raidenShogun_01\", \"description\": \"对自己的造物视若不见，却又美其名曰不忍心干预…\", \"voicelineId\": 75021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「女皇」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_tsaritsa_01\", \"description\": \"人人都称赞她的温柔与慈爱，却不知「爱」也是「罪」的一种。搞不好是代偿心理作祟哦？\", \"voicelineId\": 75022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「丑角」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_pierro_01\", \"description\": \"「丑角」是坎瑞亚的遗民——除此之外，我对他知之甚少，也从未与他有过什么密切的交流。但他似乎对我意有所求，以前给我指派过不少重要的任务，包括前往「深渊」。\", \"voicelineId\": 75023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「队长」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_capitano_01\", \"description\": \"「刚正不阿的『队长』」、「正直果敢的『队长』」、「战功累累的『队长』」…这些愚人众里流传的言论，就算是人偶的耳朵也要听出茧子来了。你不觉得，绝对的「正直」，其实是个极其危险的隐患吗？更不用提，「队长」拥有顶尖的实力。\", \"voicelineId\": 75024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「博士」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_dottore_01\", \"description\": \"真遗憾，小吉祥草王让他消除了那么多的切片，剥夺了我将他一片一片千刀万剐的快乐。\", \"voicelineId\": 75025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3032], \"unlockText\": \"完成「倾落伽蓝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「少女」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_columbina_01\", \"description\": \"试问：当遇到一名「无论何时」都懵懂无知，「无论做什么」都麻木平淡的「少女」时，该作何反应？我的话，尚可一战；你的话…因为太有良知，还是离她远些吧。\", \"voicelineId\": 75026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「仆人」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_arlecchino_01\", \"description\": \"道貌岸然的伪君子。她对人展露「优雅」与「亲切」都只是为了更好地「控制」罢了。而直面过她疯狂一面的人，大多已经…呼~。\", \"voicelineId\": 75027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「公鸡」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_pulcinella_01\", \"description\": \"也就是「公子」才会觉得「公鸡」是真心实意、不求回报地关心他和他的家人。虽然那位市长大人确实做了不少实事，但稍微有点脑子的人都能看出来，这里的潜台词是「你的家人都在我掌控之中」吧？\", \"voicelineId\": 75028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「木偶」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_sandrone_01\", \"description\": \"她除了自己的研究以外什么都不关心，性格恶劣得很。但即便做到如此极端的地步，却也只是制造了大量废品，在我仍是执行官时还低我一席，真是可怜。\", \"voicelineId\": 75029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「富人」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_pantalone_01\", \"description\": \"那个第九席啊，他对「公平交易」过分偏执，甚至试图推翻神与人之间天生的不平等。不过凡人就是这样，容易有不切实际的妄想，倒也没什么特别的，就像他平庸的能力和眼光一样——选择和「博士」密切合作，哼，是不会有好下场的。\", \"voicelineId\": 75030, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「公子」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_tartaglia_01\", \"description\": \"头脑简单，四肢也不甚发达。让他做最后一席都是在拉低执行官的整体水准。万幸，我已经不在其列了。\", \"voicelineId\": 75031, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「女士」…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_signora_01\", \"description\": \"她的灰烬里什么都没有。我对失去未来的人不感兴趣。\", \"voicelineId\": 75032, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_yaeMiko_01\", \"description\": \"油腔滑调的妖怪，为博神明的青睐，将自己伪装成关心人类的样子。其实，只是为了找乐子吧？\", \"voicelineId\": 75033, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [2021], \"unlockText\": \"完成「千手百眼，天下人间」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于枫原万叶…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_kazuha_01\", \"description\": \"你说枫原家的后人？那岂不是…哦？他也有风元素的「神之眼」，还扛下过雷电将军的一刀？呵呵…哈哈哈哈哈哈哈哈！\", \"voicelineId\": 75034, \"voicelineType\": \"4015\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3032], \"unlockText\": \"完成「倾落伽蓝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛索斯…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_teammate_sethos_01\", \"description\": \"你为什么觉得我会认识他？就因为他经常追在我后面吵着要看我的帽子吗？我们没怎么说过话，第一次见面他就问我是不是叫阿帽，这又何尝不是以貌取人？哼，阿帽，这个名字倒是流传开了…\", \"voicelineId\": 75084, \"voicelineType\": \"4016\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"#想要了解{REALNAME[ID(1)]}·其一\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_friendship_01\", \"description\": \"真稀奇，竟然想了解我。会招来麻烦哦？\", \"voicelineId\": 75035, \"voicelineType\": \"5001\"}, {\"title\": \"#想要了解{REALNAME[ID(1)]}·其二\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_friendship_02\", \"description\": \"啊，一定有很多、很多人想要找我清算前尘。无所谓，我来者不拒——或者说，还挺期待的呢。\", \"voicelineId\": 75036, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"#想要了解{REALNAME[ID(1)]}·其三\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_friendship_03\", \"description\": \"我曾以为成神便可摒弃无用的情感，现在不这么觉得了。至少「愤怒」，无论来自他人还是自我，都是方便使用的工具。\\n怎么会有人永远不生气呢？难以想象，这种人就没有一点脾气吗？\", \"voicelineId\": 75037, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3032], \"unlockText\": \"完成「倾落伽蓝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"#想要了解{REALNAME[ID(1)]}·其四\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_friendship_04\", \"description\": \"在进入世界树时，我心中只有一个念头：希望自己从未来到这个世上。\\n世界树回应了这个愿望，却没有带来我期盼的结果。这片土地的命运在捉弄它的囚徒方面一如往常。\", \"voicelineId\": 75038, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3032], \"unlockText\": \"完成「倾落伽蓝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"#想要了解{REALNAME[ID(1)]}·其五\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_friendship_05\", \"description\": \"你我有过交点，但终有一天会去往不同的地方。谁知道以后会发生什么呢？走着瞧吧。\", \"voicelineId\": 75039, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3032], \"unlockText\": \"完成「倾落伽蓝」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"#{REALNAME[ID(1)]}的爱好…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_pref_hobby\", \"description\": \"爱好？那是闲人才有空琢磨的东西吧，我看起来像是没事做吗？\", \"voicelineId\": 75040, \"voicelineType\": \"6001\"}, {\"title\": \"#{REALNAME[ID(1)]}的烦恼…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_dialog_annoyed\", \"description\": \"在想怎么才能把你甩掉，去胡作非为一番。——开玩笑的，你信了？\", \"voicelineId\": 75041, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_pref_foodLike_01\", \"description\": \"有茶吗？越苦越好，回味无穷。\", \"voicelineId\": 75042, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_pref_foodDislike\", \"description\": \"腻腻歪歪的甜东西，牙齿都要被黏在一起了。你自己留着吧。\", \"voicelineId\": 75043, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_spice_pref_01\", \"description\": \"还行吧，算是你为数不多的优点了。\", \"voicelineId\": 75044, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_spice_normal_01\", \"description\": \"不错，至少做出了能入口的食物。\", \"voicelineId\": 75045, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_spice_dislike_01\", \"description\": \"想害我？难不成你笨到忘了我非凡胎？\", \"voicelineId\": 75046, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_pref_birthday_01\", \"description\": \"把手给我。…呵，别紧张啊，只是带你去高处看看而已。\\n如何？应当是非凡的景色。感谢就免了，谢来谢去的没意思。\", \"voicelineId\": 75047, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_starUp_01\", \"description\": \"…看得出来，你尽力了。\", \"voicelineId\": 75048, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_starUp_02\", \"description\": \"风吹过来了…你做了什么？\", \"voicelineId\": 75049, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_starUp_03\", \"description\": \"给我力量，你不担心后果吗？…好吧。\", \"voicelineId\": 75050, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_wanderer/vo_wanderer_starUp_04\", \"description\": \"虽说我可以成为你的助力，但将我视作同伴仍是件危险的事情，希望你清楚自己在面对什么。若你不畏惧，便站到我身后吧。\", \"voicelineId\": 75051, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_skill1_01\", \"description\": \"风起！\", \"voicelineId\": 75052, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_skill1_02\", \"description\": \"俯瞰凡尘！\", \"voicelineId\": 75053, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_skill1_03\", \"description\": \"怒风腾天！\", \"voicelineId\": 75054, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_skill3_01\", \"description\": \"不度蝼蚁！\", \"voicelineId\": 75055, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_skill3_02\", \"description\": \"鼠雀之辈！\", \"voicelineId\": 75056, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_skill3_03\", \"description\": \"叫大声点！\", \"voicelineId\": 75057, \"voicelineType\": \"200003\"}, {\"title\": \"元素爆发·其四\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_skill3_04\", \"description\": \"把头低下！\", \"voicelineId\": 75058, \"voicelineType\": \"200004\"}, {\"title\": \"元素爆发·其五\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_skill3_05\", \"description\": \"毫无自知之明！\", \"voicelineId\": 75059, \"voicelineType\": \"200005\"}, {\"title\": \"元素爆发·其六\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_skill3_06\", \"description\": \"就凭你，也配直视我？\", \"voicelineId\": 75060, \"voicelineType\": \"200006\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_explore_sprint_start_01\", \"description\": \"风驰！\", \"voicelineId\": 75061, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺开始·其二\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_explore_sprint_start_02\", \"description\": \"疾风随行！\", \"voicelineId\": 75062, \"voicelineType\": \"700002\"}, {\"title\": \"冲刺开始·其三\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_explore_sprint_start_04\", \"description\": \"…真慢。\", \"voicelineId\": 75064, \"voicelineType\": \"700004\"}, {\"title\": \"冲刺开始·其四\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_explore_sprint_start_05\", \"description\": \"没叫你跟着。\", \"voicelineId\": 75065, \"voicelineType\": \"700005\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_chest_open_01\", \"description\": \"多余。\", \"voicelineId\": 75066, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_chest_open_02\", \"description\": \"啊？这你也要？\", \"voicelineId\": 75067, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_chest_open_03\", \"description\": \"你自己拿着玩吧。\", \"voicelineId\": 75068, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_life_less30_01\", \"description\": \"习惯了。\", \"voicelineId\": 75069, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_life_less30_02\", \"description\": \"不值一提。\", \"voicelineId\": 75070, \"voicelineType\": \"410002\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_life_less30_teammate_01\", \"description\": \"要你何用！\", \"voicelineId\": 75071, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_life_less30_teammate_02\", \"description\": \"也没指望你派上用场。\", \"voicelineId\": 75072, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_life_die_01\", \"description\": \"坠入…深渊…\", \"voicelineId\": 75073, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_life_die_02\", \"description\": \"皆为…徒劳…\", \"voicelineId\": 75074, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_life_die_03\", \"description\": \"罪业的报偿…\", \"voicelineId\": 75075, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_hit_H_02\", \"description\": \"不过如此。\", \"voicelineId\": 75076, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_hit_H_03\", \"description\": \"…可笑。\", \"voicelineId\": 75077, \"voicelineType\": \"910002\"}, {\"title\": \"重受击·其三\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_hit_H_06\", \"description\": \"…你死定了。\", \"voicelineId\": 75078, \"voicelineType\": \"910003\"}, {\"title\": \"重受击·其四\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_hit_H_07\", \"description\": \"等着求饶吧。\", \"voicelineId\": 75079, \"voicelineType\": \"910004\"}, {\"title\": \"重受击·其五\", \"voicefile\": \"VO_gameplay/VO_wanderer/vo_wanderer_battle_hit_H_08\", \"description\": \"做好付出代价的准备。\", \"voicelineId\": 75080, \"voicelineType\": \"910005\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_wanderer_teamJoin_01\", \"description\": \"没想到…叫我做什么？\", \"voicelineId\": 75081, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_wanderer_teamJoin_02\", \"description\": \"你最好有要事相求。\", \"voicelineId\": 75082, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_wanderer_teamJoin_03\", \"description\": \"非我不可？…行吧，勉为其难。\", \"voicelineId\": 75083, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000076, 'Faruzan', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_draw_appear_01\", \"description\": \"这是当年教令院的杰出学者奖，这是须弥解谜协会终身成就奖，还有遗迹机关研讨会的…如何，可有志愿拜入我门下？咳咳，顺带一提，珐露珊前辈我是知论派学者，找我请到室罗婆耽学院来，不是刹诃伐罗学院，别走错地了。\", \"voicelineId\": 76000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·规矩\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_character_idle_01\", \"description\": \"都过去一百年了，教令院的这些傻规矩怎么一点没改啊…\", \"voicelineId\": 76001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·前辈\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_character_idle_02\", \"description\": \"啊——？什么？年纪大，听不见。先叫声前辈听听吧。\", \"voicelineId\": 76002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·做学问\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_character_idle_03\", \"description\": \"做学问可不是赶潮流，没有冷门热门之说。\", \"voicelineId\": 76003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_weather_heavyRain_01\", \"description\": \"早不是小孩子了，下雨天有什么好兴奋的。\", \"voicelineId\": 76004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_weather_thunder_01\", \"description\": \"呜哇！？怎、怎么啦？年纪大就不可以害怕打雷了吗？\", \"voicelineId\": 76005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_weather_snowy_01\", \"description\": \"好美…让人着迷…阿嚏！好吧…也让人着凉…\", \"voicelineId\": 76006, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_weather_gale_01\", \"description\": \"太舒服了，还是空气流通的环境好啊。\", \"voicelineId\": 76007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_weather_desert_01\", \"description\": \"怎么兜兜转转又到这边来了…\", \"voicelineId\": 76008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_greetingMorning\", \"description\": \"年轻人，早上就该拿出点精气神来！快重新向我问候一遍。\", \"voicelineId\": 76009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_greetingNoon\", \"description\": \"有点饿了…去大巴扎吃点吗？我口味不挑，别太新潮就行。\", \"voicelineId\": 76010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_greetingNight\", \"description\": \"别大惊小怪，不管哪个时代的学者，都会彻夜做研究。夜晚是能够宁静思考的宝贵时段。\", \"voicelineId\": 76011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_greetingNight2\", \"description\": \"这篇古文看得我头昏眼花…今天就到这吧，早点休息，我也睡了，晚安。\", \"voicelineId\": 76012, \"voicelineType\": \"1004\"}, {\"title\": \"关于珐露珊自己·前辈\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_idle\", \"description\": \"想了解什么？压力机关的变体？元素方碑的底层设计？嗯，等等…你刚刚向我提问的时候，是不是忘了叫我前辈？\", \"voicelineId\": 76013, \"voicelineType\": \"2001\"}, {\"title\": \"关于珐露珊自己·光杆导师\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_idle2\", \"description\": \"我希望我的学生都能打心底里喜欢古文研究，要是遇不到这样的孩子，那就干脆当一辈子的光杆导师！啊、啊？找新生打下手的事？偶尔用课余时间帮助一下前辈很合理吧？说得像是谁不是这样过来的一样…\", \"voicelineId\": 76014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·招生\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_close\", \"description\": \"认真说，要不要当我的学生？我会针对实际给你定制课题，讲得比谁都要透彻。现代机关解谜是重点，相关文献解读作为拓展…我是过来人，这些知识对今后的冒险大有裨益，你还能不信我？\", \"voicelineId\": 76015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·解谜时光\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_close1\", \"description\": \"那一百年间，我不断重复着解谜，不知不觉变得麻木，连时间的流动都感受不到…现在好了，面对谜题，我不必再独自彷徨了。也许可以和你一起拓抄碑文、破译字符、解构机关…好好地品味每分每秒的钻研时光。\", \"voicelineId\": 76016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_pendant\", \"description\": \"我的学术水平，哼，就算不谈我过去的光辉履历，这可是连神明他老人家都认可的。至于为什么招不到学生…不是我的问题，也不是学科的问题，大概是契机吧…就像我获得神之眼也是在特定的契机下。\", \"voicelineId\": 76017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·妙论派\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_share_01\", \"description\": \"「刹诃伐罗学院是未来唯一有能力研究机关的学院」…哼，现如今，妙论派的宣言也未免太过自大了，我在须弥解谜的时候，他们还不知道在哪玩积木呢。\", \"voicelineId\": 76018, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·知论派\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_share_02\", \"description\": \"知论派那群家伙总喜欢以太过冷门、无人问津为由卡我的研究经费。按照这个评判标准，知论派至今都是人数最少的学派，干脆把室罗婆耽学院都关了算了。\", \"voicelineId\": 76019, \"voicelineType\": \"3005\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_pref_gift_01\", \"description\": \"我去过大大小小的遗迹，从有限的古代图文来解读，「遗迹龙兽」，确实是精妙绝伦的机关，唔…也许不能用「机关」二字来概括，说它们是一种从古代遗留至今的「生命」也不为过…\", \"voicelineId\": 76020, \"voicelineType\": \"3003\"}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_teammate_nahida_01\", \"description\": \"就像知论派的研究也会被用在妙论派上…知识本就是无法被限制的。所有学者都会感激小吉祥草王，让教令院，不，让须弥这个智慧的学城得以摆脱私欲的裹挟，让求知之人都有机会在学术之海中钩深索隐…\", \"voicelineId\": 76021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_teammate_tighnari_01\", \"description\": \"雨林遗迹研究算是最让我省心的项目，哦，得叫上提纳里。把活的《雨林生存指南》带在身边多有意思。哎呀，不得不说，虽然我年纪大，但吃过的蕈子远不如他见过的多呢。\", \"voicelineId\": 76022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于柯莱…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_teammate_collei_01\", \"description\": \"柯莱啊…这姑娘尊敬师长，又勤勉又好学，是一顶一的完美学生！对这样的孩子就该温柔激励才对，提纳里有必要这么严苛吗？真是的…得想办法把她抢过…咳咳！我是说…作为前辈…得想办法优化一下当今年轻人的求学环境才行…\", \"voicelineId\": 76023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_teammate_cyno_01\", \"description\": \"赛诺的笑话明明是由现代的文字和语言构成的，但我还是没法从文法和文义上推演出藏在话语中的意思…你是说就只是字面意思和谐音？真的…？那这些笑话也太没意思了…\", \"voicelineId\": 76025, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱依拉…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_teammate_layla_01\", \"description\": \"有时她看见我会低着头绕路走开，半夜里偶遇却又会大大方方地打招呼…搞不懂。算了，能挤进梨多梵谛的小崽子们大多都是天才，天才总有些自己的怪癖，我就不计较了。\", \"voicelineId\": 76026, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡维…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_teammate_kaveh_01\", \"description\": \"卡维这孩子是个好苗子。我跟他随便聊过一些机关构造原理，怎么说呢…尽管浪漫思想和艺术细胞都有些过甚，但还算有自己的想法，不容易。听说他日子过得有点紧，我一直等着哪天拿到经费就请他吃顿好的…等着吧。\", \"voicelineId\": 76027, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于妮露…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_teammate_nilou_01\", \"description\": \"有印象，是个有礼貌的姑娘。去了大巴扎几次就把我记住了，还劝别人不要和我吵架。说的很对嘛，现在的年轻人啊，就该多向妮露学习。\", \"voicelineId\": 76028, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛索斯…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_teammate_sethos_01\", \"description\": \"噢？那个新来的小子？来得正好！我还不知道他是哪个院的，最近老看到他晃来晃去，街上呀，商店里呀，餐馆里呀…哪儿都有他，这孩子说起话来一直点头，像个…像个小狗脑袋？能说会道得很呢，应该是个好苗子。哎，你要是认识他，记得劝他转到我门下来。前辈我呀，肯定不会让他吃亏的。\", \"voicelineId\": 76068, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解珐露珊·其一\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_friendship_01\", \"description\": \"珐露珊前辈我的故事都赶得上某些文献的跨度了，得从一百多年前讲起…还想听吗？很好，积极求知，是学者不可或缺的品质。你入门了。\", \"voicelineId\": 76029, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解珐露珊·其二\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_friendship_02\", \"description\": \"从前的那些机关解谜需要配合大量的文献解读研究。不是我吹嘘，跟你解过的谜题恐怕完全不在一个层次。不服？好啊，你挑些你觉得难的，摆出来看看。能思考超过半小时就算我输。\", \"voicelineId\": 76030, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解珐露珊·其三\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_friendship_03\", \"description\": \"要不是误入那个赤王遗迹，我还能为须弥贡献更多…好在之前的手稿和论述没有白费，现在都便宜了妙论派，成了机关学的学科基础。呵呵，这一声「前辈」，我还是担得起的。\", \"voicelineId\": 76031, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解珐露珊·其四\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_friendship_04\", \"description\": \"作为学者，原本就该坦然接受失败、承受后果…我绝不希望别人可怜我，无论是过去还是现在！再说了，我明明是凭实力解开了最后的谜题，逃出了那个鬼地方…比起可怜，不该多从我身上找点激励和启发吗？\", \"voicelineId\": 76032, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解珐露珊·其五\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_friendship_05\", \"description\": \"我研究方向的地位已经大不如从前了，知论派卡我经费也不是一次两次了…妙论派三番四次邀请我到那边当导师，那条件还真诱人啊，更高的经费额度、更多的学生…但我还是拒绝了。不管怎样，总要有人负责钻研那些无人问津的领域，将全人类的智慧往外推出一小步。\", \"voicelineId\": 76033, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"珐露珊的爱好…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_pref_hobby\", \"description\": \"有些黑心商贩和佣兵常常混进奥摩斯港，拿着不知从哪弄来的「古董」高价兜售，其实全是些用坏用旧的破烂！哼，我见一次就拆穿一次。论「鉴古」，除了「尘世七执政」，我还没觉得自己能差过谁的。\", \"voicelineId\": 76034, \"voicelineType\": \"6001\"}, {\"title\": \"珐露珊的烦恼…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_dialog_annoyed\", \"description\": \"一百年前，我最大的烦恼不过是解读不了遗迹碑文上的信息。一百年后，什么烦心事都比不过弄不到研究经费…唉！愁人…\", \"voicelineId\": 76035, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_pref_foodLike_01\", \"description\": \"面糊拿去烤一烤，香味倍增！有机会我给你露两手，让你也尝尝我那辈的做法和风味。「古法秘制」，保准你逛遍大巴扎都找不来。\", \"voicelineId\": 76036, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_pref_foodDislike\", \"description\": \"那个叫什么…帕蒂沙兰布丁，那是谁发明的做法啊？布丁不应该得用米饭做吗？现在的这些创意，越来越花里胡哨了。不…谢谢，我没有尝试的兴趣，即使是你做的也免了。\", \"voicelineId\": 76037, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_spice_pref_01\", \"description\": \"唔…唔…比许多老字号做得都好吃，难道美食界也在不断进步？\", \"voicelineId\": 76038, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_spice_normal_01\", \"description\": \"色香味样样不差，莫非你常看美食制作类的书籍吗？\", \"voicelineId\": 76039, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_spice_dislike_01\", \"description\": \"嗯？这什么东西，好晦涩的食物，你是想让我解读吗？\", \"voicelineId\": 76040, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_pref_birthday_01\", \"description\": \"生日快乐！给你做了个玩具，拿好。它集合了微缩机关装置，这里有按键和推杆…侧面有滚轮…你就随便放在手上拨弄吧，坏了包修。把你当小孩子？笑话。快乐和放松是每个人都需要的东西，管它什么孩子大人的。\", \"voicelineId\": 76041, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_starUp_01\", \"description\": \"哈，手脚很麻利呀年轻人，找起材料来都是风风火火的。\", \"voicelineId\": 76042, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_starUp_02\", \"description\": \"噢？你解开了什么机关吗？力量正源源不断地涌过来呢~\", \"voicelineId\": 76043, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_starUp_03\", \"description\": \"呵，你倒是挺卖力的…放心吧，引导与保护，是前辈的职责，我不会让你陷入困境的。\", \"voicelineId\": 76044, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_faruzan/vo_faruzan_starUp_04\", \"description\": \"在无边的智慧之海中，百年，也只能短暂地瞥见一角浪花…那些仍未深入的学问和没能解开的谜题，就靠你和我一起努力了。\", \"voicelineId\": 76045, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_battle_skill1_01\", \"description\": \"后悔也晚了。\", \"voicelineId\": 76046, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_battle_skill1_02\", \"description\": \"敢惹我？\", \"voicelineId\": 76047, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_battle_skill1_03\", \"description\": \"走着瞧。\", \"voicelineId\": 76048, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_battle_skill3_01\", \"description\": \"毗岚重机！\", \"voicelineId\": 76049, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_battle_skill3_02\", \"description\": \"送你，拿去玩吧！\", \"voicelineId\": 76050, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_battle_skill3_03\", \"description\": \"真理，复始周转。\", \"voicelineId\": 76051, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_chest_open_01\", \"description\": \"有文物出土？哦…这个啊。\", \"voicelineId\": 76052, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_chest_open_02\", \"description\": \"算没白跑一趟。\", \"voicelineId\": 76053, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_chest_open_03\", \"description\": \"给你拿去用好了，快说谢谢前辈。\", \"voicelineId\": 76054, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_life_less30_01\", \"description\": \"也不是第一次了！\", \"voicelineId\": 76055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_life_less30_02\", \"description\": \"这种困境…不算什么…\", \"voicelineId\": 76056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_life_less30_03\", \"description\": \"别小看我了…\", \"voicelineId\": 76057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_life_less30_teammate_01\", \"description\": \"注意安全，别送命了。\", \"voicelineId\": 76058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_life_less30_teammate_02\", \"description\": \"这种时候要学着依靠前辈！\", \"voicelineId\": 76059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_life_die_01\", \"description\": \"谜题…仍未解开…\", \"voicelineId\": 76060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_life_die_02\", \"description\": \"学者之路…不应有尽头…\", \"voicelineId\": 76061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_life_die_03\", \"description\": \"时间…没为我停留…\", \"voicelineId\": 76062, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_battle_hit_H_01\", \"description\": \"宵小狂徒！\", \"voicelineId\": 76063, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_faruzan/vo_faruzan_battle_hit_H_02\", \"description\": \"目无尊卑！\", \"voicelineId\": 76064, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_faruzan_teamJoin_01\", \"description\": \"还得靠前辈帮忙吧？\", \"voicelineId\": 76065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_faruzan_teamJoin_02\", \"description\": \"好久没舒展筋骨了。\", \"voicelineId\": 76066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_faruzan_teamJoin_03\", \"description\": \"行吧，陪陪年轻人。\", \"voicelineId\": 76067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000077, 'Yaoyao', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_draw_appear_01\", \"description\": \"初次见面，我是瑶瑶，忝列门墙，师从歌尘浪市真君。出门在外，若有不便…请叫上我！瑶瑶有礼了。对了，我这里有炸萝卜丸子，吃一点吧！但是不可以多吃哦，油腻的东西吃多了对身体的负担会增加的。如果没吃饱，我还带了洗干净的萝卜和醋，可以给你凉拌萝卜丝吃。\", \"voicelineId\": 77000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·大道理\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_character_idle_01\", \"description\": \"「明日复明日，明日何其多…」总之，快快行动起来吧。\", \"voicelineId\": 77001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·凑热闹\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_character_idle_02\", \"description\": \"那边好像有什么动静，偷偷看一眼的话，应该没事吧！\", \"voicelineId\": 77002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·寻仙问道\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_character_idle_03\", \"description\": \"真奇怪，为什么总有人想寻仙问道呢？仙人不是到处都是吗？\", \"voicelineId\": 77003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_weather_heavyRain_01\", \"description\": \"你听，青蛙的叫声，像不像在给雨声伴奏？呱呱呱。\", \"voicelineId\": 77004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_weather_thunder_01\", \"description\": \"呜、呜哇！我、我帮你捂住耳朵，害怕的话就抓紧我的手。\", \"voicelineId\": 77005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_weather_snowy_01\", \"description\": \"下——雪——啦——！你先穿上毛茸茸的外套，戴上厚厚的帽子和围巾，喏，别忘了还有手套，我们再去堆雪人吧。\", \"voicelineId\": 77006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_weather_sunny_01\", \"description\": \"天气很好呢，我们去璃月港的码头逛逛吧。\", \"voicelineId\": 77007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_weather_gale_01\", \"description\": \"小心哦，别被风吹走啦。\", \"voicelineId\": 77008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_greetingMorning\", \"description\": \"该起床啦，我已经准备好早饭了，你动作快些…欸、欸？回笼觉吗？那好吧，只能再多睡五分钟哦！五分钟后我再来叫你~哎，早知道就该提醒你早点睡…\", \"voicelineId\": 77009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_greetingNoon\", \"description\": \"你要记住哦~吃完午饭后，不要立刻躺下午睡，也不能马上动身冒险，这些都对消化不好。\", \"voicelineId\": 77010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_greetingNight\", \"description\": \"欸？晚上还要出门吗？唔…什么时候才能回来呀？天色已晚，小心为上哦~\", \"voicelineId\": 77011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_greetingNight2\", \"description\": \"睡前故事…上回和你…说、说到哪里来着…璃月自古时起…便有三眼五显仙人守护，其、其中…呼呼…\", \"voicelineId\": 77012, \"voicelineType\": \"1004\"}, {\"title\": \"关于瑶瑶自己·璃月码头\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_idle\", \"description\": \"你知道吗？璃月港的码头，总是人声鼎沸，可热闹了！和我家那种静到叶子掉在地上都能听见的感觉完全不一样呢！所以，我一有空就爱跑去码头看看。新来的船，新鲜的见闻…还有新玩具！\", \"voicelineId\": 77013, \"voicelineType\": \"2001\"}, {\"title\": \"关于瑶瑶自己·吃饱穿暖\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_idle2\", \"description\": \"所谓「仓廪实则知礼节，衣食足则知荣辱」，所以说，出门在外，要好好吃饭，衣裳穿暖…呃、欸？这句话不是这样的意思吗？那是什么意思呢？\", \"voicelineId\": 77014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·练枪\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_close\", \"description\": \"不是我偷懒，是枪太长，又很重，练枪真的挺辛苦的…好在师父对我的要求不高，嘿嘿。\", \"voicelineId\": 77015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·牵肠挂肚\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_close1\", \"description\": \"最近有按时吃饭吗？天冷了，有好好添衣裳吗？冒险的时候有没有遇到危险？有没有受伤？哎呀算了，要不你还是带上我吧，草行露宿，我实在有点放心不下你。\", \"voicelineId\": 77016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_pendant\", \"description\": \"师父是三眼五显仙人！但她告诉过我，神之眼代表着神明的认可。可我也没有做什么特别的呀？真想和神明大人聊聊天，听听她的想法呢！\", \"voicelineId\": 77017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_share_01\", \"description\": \"奥赛尔？说的是海里的那个超级大的云来大章鱼吗？啊！我不是想吃，只是…如果想吃的话一定记得要烤熟了再吃…呀！不一定非要烤，只是…只是我觉得烤着会很好吃…\", \"voicelineId\": 77018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_pref_gift_01\", \"description\": \"我喜欢小团雀哦，去找七七玩的时候，经常能在路上见到。我还会和它们打招呼呢！啾啾啾♪～哎呀，被你猜对了，真聪明！确实是早早早的意思哦。\", \"voicelineId\": 77019, \"voicelineType\": \"3003\"}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_xiangling_01\", \"description\": \"师姐她最近…没有去找什么奇怪的食材吧？上次她说要生吃云来大章鱼，可让我担心坏了，要是吃坏了肚子可怎么办呀？她又不喜欢吃白先生的苦药。我求了师父一起劝住了她，可不要又看上另一种危险的食材了…哎…\", \"voicelineId\": 77020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于七七·好朋友\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_qiqi_01\", \"description\": \"七七是我最好的朋友！她有时候会忘记我，但我知道她不是故意的，只要提醒她看一下笔记，她马上就能想起来。\", \"voicelineId\": 77021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于七七·一辈子\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_qiqi_02\", \"description\": \"其实我也悄悄问过白先生，有没有办法治好她…嗯…没关系的，就算要提醒她一辈子，我也没关系的。\", \"voicelineId\": 77022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于白术…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_baizhu_01\", \"description\": \"白先生开的方子可有效啦。虽然苦是有点苦，但这就是所谓的「良药苦口」吧！我理解的！哎呀，你怕苦吗？别担心，我这边有蜜枣，喝完药吃一颗就好了。\", \"voicelineId\": 77023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_ganyu_01\", \"description\": \"甘雨姐姐的工作一直很多，听说上次她还因为劳累，不小心趴在草地上睡着了，哎，让人担心！要不…我们进行一个「突击检查」！过去看看她有没有好好照顾自己吧？啊…稍等我一下，我去准备些甘雨姐姐喜欢吃的花花草草…\", \"voicelineId\": 77024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_keqing_01\", \"description\": \"刻晴姐姐为人细心，做事周全。逢年过节总会来问候师父，这就是所谓的「尊师重道」吧？还是说「知文达礼」比较合适？…总之，我也要向刻晴姐姐学习！\", \"voicelineId\": 77025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于云堇…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_yunjin_01\", \"description\": \"云堇姐姐呀，她舞枪舞得可好啦，她表演的璃月戏也非常受欢迎，师父偶尔也会带我去看哦。只要有云堇姐姐登台，场面必是座无虚席，门不停宾…但、但…她唱的是什么意思呀？\", \"voicelineId\": 77026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于北斗…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_beidou_01\", \"description\": \"北斗姐姐的船，好气派~要不是我和甘雨姐姐约好了不往船上跑，我连要在哪里搭个小小的床铺都想好了。\", \"voicelineId\": 77027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于申鹤…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_shenhe_01\", \"description\": \"申鹤姐姐远离世俗多年，这次好不容易回到了璃月港，难免有很多不适应的地方。我也想帮着甘雨姐姐一起照顾她…可我要怎么开口，才不会让她觉得不自在呢？\", \"voicelineId\": 77028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1101505], \"unlockText\": \"完成「风起鹤归」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于烟绯…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_yanfei_01\", \"description\": \"烟绯姐姐有一本厚厚的法典，就连休假来探望师父的时候，都随身带着呢，真厉害呀~能一直拿着这么重的东西，还要读这么难懂的东西…\", \"voicelineId\": 77029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于闲云…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_teammate_xianyun_01\", \"description\": \"那天我去找师父的时候，见到师父在和一位很有气质的姐姐聊天。她自称「闲云」，还想逗逗我呢，但我一眼就看出来她是留云阿姨啦！毕竟，看师父那高兴的样子，没有半点生分，分明是见到了一位老友嘛！\", \"voicelineId\": 77069, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11035], \"unlockText\": \"完成「千里月明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解瑶瑶·其一\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_friendship_01\", \"description\": \"瑶瑶的出身吗？我父母隐居于山郊，唔，按道理来说，我应该算是轻策庄人吧。\", \"voicelineId\": 77030, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解瑶瑶·其二\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_friendship_02\", \"description\": \"我家靠种植珍贵药草为生，家父家母忙碌的时候经常会忘记做家务，甚至连吃饭都会忘记…哎，这样怎么行呀！我得照顾好他们。\", \"voicelineId\": 77031, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解瑶瑶·其三\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_friendship_03\", \"description\": \"我从小在山间长大，花草树木，还有小动物们都是我的朋友哦！对了，你想和小团雀聊聊天吗？我可以带你去，也可以帮你传话。来吧，很有趣的~我们先去准备点米粒给它们当做礼物！\", \"voicelineId\": 77032, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解瑶瑶·其四\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_friendship_04\", \"description\": \"璃月到处都是仙人，我遇到过好多位呢！留云阿姨，理水叔叔…我最喜欢的就是留云阿姨啦！她送了我好多好玩的仙家物什，还细致地教我用法，让瑶瑶受益匪浅呢！\", \"voicelineId\": 77033, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解瑶瑶·其五\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_friendship_05\", \"description\": \"遇见师父之后，她说我有仙缘，收我做了弟子。其实我至今还不懂仙缘到底是什么呀？但能在大家身边热热闹闹的，听师父讲故事，和师姐一起偷懒…还有帮上璃月港大家的忙，我非常知足！\", \"voicelineId\": 77034, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"瑶瑶的爱好…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_pref_hobby\", \"description\": \"常言道，良宵苦短，胜事难逢！如果有什么好玩的事情，一定要过去看看才行呀…说不定还能遇上瑶瑶能帮上忙的事，你说对吧？\", \"voicelineId\": 77035, \"voicelineType\": \"6001\"}, {\"title\": \"瑶瑶的烦恼…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_dialog_annoyed\", \"description\": \"哎、哎呀，练枪真的有点枯燥…我就和月桂玩一小会儿，休息一会儿就接着再练…\", \"voicelineId\": 77036, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_pref_foodLike_01\", \"description\": \"轻策农家菜、来来菜、水煮鱼…这些璃月地道的味道不仅好吃，还能让人感到热闹。嗯？你也喜欢吗？太好了，那下次来我家吃饭吧，我来露一手！别担心，我帮师姐打过下手，在烹饪上也算「师出名门」呢！\", \"voicelineId\": 77037, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_pref_foodDislike\", \"description\": \"有次申鹤姐姐一顿清心吃多了，身体虚了好几天呢！瑶瑶要爱惜身体，不生吃清心。唔？你问我怎么知道的？是留云阿姨跟我说起的哦！\", \"voicelineId\": 77038, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_spice_pref_01\", \"description\": \"太好吃啦！这厨艺简直和师姐「难舍难分」？不对，好像是「不相上下」！嘿嘿，瑶瑶一时激动，「口不择言」了。\", \"voicelineId\": 77039, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_spice_normal_01\", \"description\": \"好吃！下次做饭记得喊上我哦，让我帮你打下手吧。\", \"voicelineId\": 77040, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_spice_dislike_01\", \"description\": \"…哎，你平时吃的都是这些吗？要不然还是让我来给你做饭吧！吃得不好怎么能出门冒险呢，要是累到了自己、身体垮了怎么办呀…\", \"voicelineId\": 77041, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_pref_birthday_01\", \"description\": \"今日是你的生辰，按照习俗，这样的日子要来一碗长寿面，我找师姐学了一手，一整条面都没有断哦！还打了个很圆很圆的鸡蛋进去，嘿嘿。快跟我来吧，要趁热吃才好。新的一岁，愿你身体健健康康，生活圆圆满满。\", \"voicelineId\": 77042, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_starUp_01\", \"description\": \"咦？枪怎么变轻了？要是能再变短点就更好了…\", \"voicelineId\": 77043, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_starUp_02\", \"description\": \"哇哇，我现在说不定都能拿起师姐的枪了！真想现在就把这个好消息告诉师父~\", \"voicelineId\": 77044, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_starUp_03\", \"description\": \"平时听大家说的「勤以立身」，就是这种感觉吧？欸？这个「勤」…不是勤奋的意思吗？\", \"voicelineId\": 77045, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_yaoyao/vo_yaoyao_starUp_04\", \"description\": \"原来被人挂念的感觉是这样的，嗯…我能有这样的成长与变化，都是你的功劳哦！所谓投之以桃，报之以李，你放心吧，我会护你安然无虞的！\", \"voicelineId\": 77046, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_battle_skill1_01\", \"description\": \"月桂！该上咯。\", \"voicelineId\": 77047, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_battle_skill1_02\", \"description\": \"不要乱动哦！\", \"voicelineId\": 77048, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_battle_skill1_03\", \"description\": \"不怕不怕。\", \"voicelineId\": 77049, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_battle_skill3_01\", \"description\": \"预备…跑！\", \"voicelineId\": 77050, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_battle_skill3_02\", \"description\": \"痛痛飞。\", \"voicelineId\": 77051, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_battle_skill3_03\", \"description\": \"要冲喽，月桂！\", \"voicelineId\": 77052, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_chest_open_01\", \"description\": \"都收好，不要落下哦！\", \"voicelineId\": 77053, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_chest_open_02\", \"description\": \"都整理好啦，请拿好。\", \"voicelineId\": 77054, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_chest_open_03\", \"description\": \"哇！这些够用好几天了吧。\", \"voicelineId\": 77055, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_life_less30_01\", \"description\": \"不行不行…\", \"voicelineId\": 77056, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_life_less30_02\", \"description\": \"我要撑下去…\", \"voicelineId\": 77057, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_life_less30_03\", \"description\": \"没事，我可以的…\", \"voicelineId\": 77058, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_life_less30_teammate_01\", \"description\": \"让瑶瑶保护你！\", \"voicelineId\": 77059, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_life_less30_teammate_02\", \"description\": \"人命关天，不要勉强！\", \"voicelineId\": 77060, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_life_die_01\", \"description\": \"没办法再照顾大家了…\", \"voicelineId\": 77061, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_life_die_02\", \"description\": \"有辱…师门…\", \"voicelineId\": 77062, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_life_die_03\", \"description\": \"枪好重…头也好重…\", \"voicelineId\": 77063, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_battle_hit_L_02\", \"description\": \"痛痛。\", \"voicelineId\": 77064, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_yaoyao/vo_yaoyao_battle_hit_H_02\", \"description\": \"好痛好痛…\", \"voicelineId\": 77065, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_yaoyao_teamJoin_01\", \"description\": \"我会照顾好大家的。\", \"voicelineId\": 77066, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_yaoyao_teamJoin_02\", \"description\": \"我来领路，跟我走吧！\", \"voicelineId\": 77067, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_yaoyao_teamJoin_03\", \"description\": \"我在，不用担心。\", \"voicelineId\": 77068, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000078, 'Alhaitham', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_draw_appear_01\", \"description\": \"我是教令院的书记官艾尔海森。想调阅档案的话，请把你的需求按照正规格式填好申请表后递交。\\n还没整理完？没关系。我的工作时间贴在办公室门外，等下个工作日再来吧。\", \"voicelineId\": 78000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·工作\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_character_idle_01\", \"description\": \"书记官的工作很简单，我就是因此才做了这个职位。\", \"voicelineId\": 78001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·读书\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_character_idle_02\", \"description\": \"读书并不会让人变聪明，看看教令院里的那些家伙就知道了。\", \"voicelineId\": 78002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·思考\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_character_idle_03\", \"description\": \"嗯…最近乱七八糟的申请表有点多，都驳回吧。\", \"voicelineId\": 78003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_weather_heavyRain_01\", \"description\": \"雨天出门是最麻烦的。\", \"voicelineId\": 78004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_weather_thunder_01\", \"description\": \"没什么可怕的，自然现象而已。除非你往大树下躲。\", \"voicelineId\": 78005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_weather_snowy_01\", \"description\": \"很冷吗？我还好。\", \"voicelineId\": 78006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_weather_sunny_01\", \"description\": \"这种好天气，最适合什么都不干。\", \"voicelineId\": 78007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_weather_desert_01\", \"description\": \"糟糕，鞋里进沙子了…\", \"voicelineId\": 78008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_greetingMorning\", \"description\": \"时间还早，我先去喝杯咖啡。\", \"voicelineId\": 78009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_greetingNoon\", \"description\": \"没什么事的话，我要戴着隔音耳机睡一会儿。\", \"voicelineId\": 78010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_greetingNight\", \"description\": \"接下来就是私人时间了。再见。\", \"voicelineId\": 78011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_greetingNight2\", \"description\": \"希望室友不要半夜敲敲打打做模型…或者他不在家最好。我不想晚上睡觉还得戴着耳机。\", \"voicelineId\": 78012, \"voicelineType\": \"1004\"}, {\"title\": \"关于艾尔海森自己·事实\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_idle\", \"description\": \"比起辞藻的包装，我更喜欢用事实说话。\", \"voicelineId\": 78013, \"voicelineType\": \"2001\"}, {\"title\": \"关于艾尔海森自己·流言\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_idle2\", \"description\": \"哦？听过不少关于我为人的传言吗？很在意？\\n没必要，因为我也并不在意你相信与否，只要别徒增额外的事端就好。\", \"voicelineId\": 78014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·打招呼\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_close\", \"description\": \"要是在街上和我打招呼我却没有反应的话，不要见怪。我只是开了耳机隔音而已。\", \"voicelineId\": 78015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·互助\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_close1\", \"description\": \"你是自理能力非常强的人，甚至能兼顾身边的伙伴。我没什么要给你的建议，你应该也不需要我的帮助。\", \"voicelineId\": 78016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_pendant\", \"description\": \"说实话，草元素「神之眼」对我的研究帮助不大。不过有了元素力后打人倒是更疼了，所以还算有用。\", \"voicelineId\": 78017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_share_01\", \"description\": \"真理诞生不是为了服务于谁。人类不是知识的载体，知识也不是人类的目的。\", \"voicelineId\": 78018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_pref_gift_01\", \"description\": \"这世上吸引人注意力的东西有很多，不要太相信自己的双眼。如果所见即为真实，人就不需要思考了。\", \"voicelineId\": 78019, \"voicelineType\": \"3003\"}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_teammate_nahida_01\", \"description\": \"过于小瞧或敬畏神明都是不可取的。神明需要信徒，同时神明也是生物链中的一环。所以我并不因为参与拯救过神明而自豪，希望小吉祥草王也不必介怀。\", \"voicelineId\": 78020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡维·关怀…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_teammate_kaveh_01\", \"description\": \"他对所有人和事都抱有过度的关怀心，可能是因为他自己太脆弱了吧，整天大惊小怪的。\", \"voicelineId\": 78021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡维·上当…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_teammate_kaveh_02\", \"description\": \"有人在路边摆摊，说只要卖出一个手工钥匙扣，就会有一个贫困家庭的孩子吃上饱饭。卡维买了十几个回来。\\n在医疗服务都免费提供的须弥…我不多说了。\", \"voicelineId\": 78022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_teammate_tighnari_01\", \"description\": \"好像很多人觉得他脾气不够好，我倒认为有失偏颇。当初卡维把房子建在死域上，搞出很大一个烂摊子，给巡林队添了不少麻烦。即使如此这位巡林官也没有记恨卡维，还愿意请他在家里吃饭…可能就是因为世界上有这样的好人，才能让卡维继续生存下去吧。\", \"voicelineId\": 78023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于多莉…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_teammate_dori_01\", \"description\": \"她精明又警觉，懂得如何将梦想落实到实际，是能把生活过得很好的聪明人。没有要包庇她的意思，但立场不同并不影响我认可她的生活态度。\", \"voicelineId\": 78024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_teammate_cyno_01\", \"description\": \"「集群意识」的案件增加了风纪官们的工作量，但我并没有什么心理压力。说到底，该起事件的根本成因并不在我。赛诺应该也是明白人，后来没再为这事找过我。\", \"voicelineId\": 78025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [13022], \"unlockText\": \"完成「乌合的虚像」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于妮露…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_teammate_nilou_01\", \"description\": \"艺术家的优点和缺点都很明显。妮露在扬长避短方面做得非常好，所以能过得简单又快乐。\", \"voicelineId\": 78026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪希雅…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_teammate_dehya_01\", \"description\": \"能力很强的人，留在镀金旅团里有些浪费。要是她能接受我的提议来教令院任职就好了，有这样的帮手，我们的工作也会轻松不少。不过她对安稳的生活不感兴趣，我能理解。可惜了。\", \"voicelineId\": 78027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解艾尔海森·其一\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_friendship_01\", \"description\": \"大部分人都不会主动与我接触，也许是因为忌惮，也许是因为性格不合。对此我很满意。\", \"voicelineId\": 78028, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解艾尔海森·其二\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_friendship_02\", \"description\": \"我向来对社交不感兴趣。如你所见，我的生活过得比大部分人舒适，这足够证明社交不是生活的必需品了。\", \"voicelineId\": 78029, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解艾尔海森·其三\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_friendship_03\", \"description\": \"每个人都应该有自己的主张，并始终保持清醒，不然很容易被各种突发状况绑架，甚至误入歧途。\", \"voicelineId\": 78030, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解艾尔海森·其四\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_friendship_04\", \"description\": \"一旦秩序被破坏，其后果会迅速蔓延。我不喜欢这样，会打扰到我现在的生活。\", \"voicelineId\": 78031, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解艾尔海森·其五\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_friendship_05\", \"description\": \"下班后我偶尔会去酒馆喝一杯。\\n不是想知道这个？什么，我还以为分享闲暇时间是比分享个人观点更隐私的事情。毕竟，无论谁都可以在留言板上侃侃而谈呢。\", \"voicelineId\": 78032, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"艾尔海森的爱好…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_pref_hobby\", \"description\": \"看晦涩难懂的书，欣赏其他人抓耳挠腮的样子。 \\n开玩笑的，别人的痛苦并不会给我带来快乐，我也很少碰到读不懂的书。\", \"voicelineId\": 78033, \"voicelineType\": \"6001\"}, {\"title\": \"艾尔海森的烦恼…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_dialog_annoyed\", \"description\": \"据我观察，很多人的烦恼都是自找的。生活中已经有不少难处，就别自添烦忧了。\", \"voicelineId\": 78034, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_pref_foodLike_01\", \"description\": \"美味程度高于美观程度的。很简单的要求吧？不然就是本末倒置了。\", \"voicelineId\": 78035, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_pref_foodDislike\", \"description\": \"有汤有水的菜肴很难在看书时吃。\", \"voicelineId\": 78036, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_spice_pref_01\", \"description\": \"嗯，可以看出对调味配比的精准把控。\", \"voicelineId\": 78037, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_spice_normal_01\", \"description\": \"是流行的味道，我不讨厌。\", \"voicelineId\": 78038, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_spice_dislike_01\", \"description\": \"不在这吃了。介意我打包回家吗？\", \"voicelineId\": 78039, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_pref_birthday_01\", \"description\": \"生日快乐。我总觉得人们在庆祝出生这一天上付出了不必要的热情，不如把这些精力用在让自己生活中的每一天过得更愉快上来得实际。你这方面做得还可以。\\n不知道送什么礼物合适，就给你预留一次申请表的特批通道吧。\", \"voicelineId\": 78040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_starUp_01\", \"description\": \"谢谢。\", \"voicelineId\": 78041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_starUp_02\", \"description\": \"原来不是一次性的。\", \"voicelineId\": 78042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_starUp_03\", \"description\": \"在奋进这件事上，你比我要热心。\", \"voicelineId\": 78043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_alhaitham/vo_alhaitham_starUp_04\", \"description\": \"不能让教令院那些喜欢偷懒的家伙知道我又在进步，否则他们会想方设法把麻烦事推给我。我当然不会接了，但沟通起来总要浪费些时间。\", \"voicelineId\": 78044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_battle_skill1_01\", \"description\": \"接好了。\", \"voicelineId\": 78045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_battle_skill1_02\", \"description\": \"镜闪。\", \"voicelineId\": 78046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_battle_skill1_03\", \"description\": \"哼。\", \"voicelineId\": 78066, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_battle_skill3_01\", \"description\": \"散射。\", \"voicelineId\": 78047, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_battle_skill3_02\", \"description\": \"分光。\", \"voicelineId\": 78048, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_battle_skill3_03\", \"description\": \"理论的推演。\", \"voicelineId\": 78049, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_chest_open_02\", \"description\": \"你自己收好。\", \"voicelineId\": 78050, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_chest_open_03\", \"description\": \"动作快，东西掉远就难捡了。\", \"voicelineId\": 78051, \"voicelineType\": \"300003\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_chest_open_01\", \"description\": \"哦。\", \"voicelineId\": 78065, \"voicelineType\": \"300001\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_life_less30_01\", \"description\": \"麻烦事。\", \"voicelineId\": 78052, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_life_less30_02\", \"description\": \"计划有变。\", \"voicelineId\": 78053, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_life_less30_03\", \"description\": \"要多花时间了。\", \"voicelineId\": 78054, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_life_less30_teammate_01\", \"description\": \"我来吧。\", \"voicelineId\": 78055, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_life_less30_teammate_02\", \"description\": \"不意外。\", \"voicelineId\": 78056, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_life_die_01\", \"description\": \"预期之外…\", \"voicelineId\": 78057, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_life_die_02\", \"description\": \"失策。\", \"voicelineId\": 78058, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_life_die_03\", \"description\": \"我的误算。\", \"voicelineId\": 78059, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_battle_hit_H_01\", \"description\": \"啧，谁啊。\", \"voicelineId\": 78060, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_alhaitham/vo_alhaitham_battle_hit_H_02\", \"description\": \"呃…行。\", \"voicelineId\": 78061, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_alhaitham_teamJoin_01\", \"description\": \"有事？\", \"voicelineId\": 78062, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_alhaitham_teamJoin_02\", \"description\": \"公事公办吧。\", \"voicelineId\": 78063, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_alhaitham_teamJoin_03\", \"description\": \"不需要太长时间吧？\", \"voicelineId\": 78064, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000079, 'Dehya', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_draw_appear_01\", \"description\": \"我叫迪希雅，就是你想要雇佣的那位佣兵。你有什么委托？打架？护送？无论是什么事，只要开口就行。\", \"voicelineId\": 79000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·佣兵\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_character_idle_01\", \"description\": \"你问佣兵的工作原则？嗯…很简单，谁出的钱多，就给谁办事。\", \"voicelineId\": 79001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·沙漠\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_character_idle_02\", \"description\": \"沙漠是个难相处的对手，但至少它足够光明磊落，把所有艰险挑战都放在台面上给你看。\", \"voicelineId\": 79002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·我们的人\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_character_idle_03\", \"description\": \"我们的人已经习惯了沙漠…但我还是希望他们在某天能够告别风沙，在某处绿洲更愉快地生活。\", \"voicelineId\": 79003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_weather_heavyRain_01\", \"description\": \"听佣兵团里的老人说，沙漠里偶尔也会下雨，而且雨势比这猛烈得多。\", \"voicelineId\": 79004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_weather_thunder_01\", \"description\": \"这雷鸣声可够大的…可以掩盖住很多声音。\", \"voicelineId\": 79005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_weather_snowy_01\", \"description\": \"呼…这里简直比夜晚的沙漠还冷。\", \"voicelineId\": 79006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_weather_sunny_01\", \"description\": \"天气很好，要是我手里的活也能轻松点就好喽。\", \"voicelineId\": 79007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_weather_breezy_01\", \"description\": \"起风了，我们去下风口扎营比较安全。\", \"voicelineId\": 79008, \"voicelineType\": \"1205\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_weather_desert_01\", \"description\": \"跟紧我，不要乱走，沙漠可不会对任何人留情。\", \"voicelineId\": 79009, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_greetingMorning\", \"description\": \"你看起来精神不错，那我们等会就拔营出发吧。\", \"voicelineId\": 79010, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_greetingNoon\", \"description\": \"已经中午了…等我找到合适的位置，就可以搭灶做饭了。\", \"voicelineId\": 79011, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_greetingNight\", \"description\": \"这么晚了你还在工作？真是比我们佣兵都辛苦啊。\", \"voicelineId\": 79012, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_greetingNight2\", \"description\": \"时间不早了，今夜的值守就交给我，你快去休息吧。\", \"voicelineId\": 79013, \"voicelineType\": \"1004\"}, {\"title\": \"关于迪希雅自己·镀金旅团\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_idle\", \"description\": \"镀金旅团只是一个「头衔」，任何须弥的佣兵都可以自称为「镀金旅团」的一员。有些佣兵就用这头衔来唬骗外地人。哼，拜这帮人所赐，现在「镀金旅团」的名号已经越来越招人厌了。\", \"voicelineId\": 79014, \"voicelineType\": \"2001\"}, {\"title\": \"关于迪希雅自己·老爹\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_idle2\", \"description\": \"库塞拉…他是个吊儿郎当，喜欢装模作样的佣兵。是他从沙漠里救了我，又用尽全力，将他一切能够给予我的东西，都给了我。\\n但正是因为他，我才能成长为现在的我。\", \"voicelineId\": 79015, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [13026], \"unlockText\": \"完成「狮之血」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·伟大事迹\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_close\", \"description\": \"你最近可是大显身手啊，我所在的佣兵团里都有不少人一直在讲你的事迹，甚至还有几个人来问我，能不能向你引见一下他们。\", \"voicelineId\": 79016, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [13026], \"unlockText\": \"完成「狮之血」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·战友\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_close1\", \"description\": \"朋友？嗯…我们一起经历了那么多事，共同闯过了那么多场战斗，用「朋友」来形容我们之间的关系，总感觉有点轻飘飘的。\\n我想想…不如，用「战友」吧，这种感情只能从并肩的战斗中锤炼而出，是最不可动摇的东西。\", \"voicelineId\": 79017, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_pendant\", \"description\": \"「神之眼」给我带来了什么？嗯…老实说，比起战斗时的便利，这枚「神之眼」更大的作用，是让更多的佣兵慕名而来加入「炽光猎兽」。\", \"voicelineId\": 79018, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [13026], \"unlockText\": \"完成「狮之血」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_share_01\", \"description\": \"你知道枣椰吗？我小时候最喜欢吃这种果子。但老爹完全不知道拆枣椰的方法，就拿着刀胡乱地戳来戳去，把里面的果肉都弄得乱七八糟，完全没办法下口吃。最后只能把果肉都刮下来，混在牛奶里，勉强给我当做粥来吃。\\n我有时候也会怀念这种粥的味道，还有那个拆枣椰都能拆得手忙脚乱的老爹。\", \"voicelineId\": 79019, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [13026], \"unlockText\": \"完成「狮之血」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_pref_gift_01\", \"description\": \"在一些人眼里，啃食残骸的赤鹫是带来死亡与灾厄的生物。但在我看来，这些翱翔在沙海之上的鹫鸟，有着最热烈的生命力。\\n不知道当它们从天空往下俯瞰时，大赤沙海会是一个什么模样。\", \"voicelineId\": 79020, \"voicelineType\": \"3003\"}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_teammate_tighnari_01\", \"description\": \"哈哈哈，你别说，我还真的差点和这位巡林官做成过一笔生意。之前我经人介绍，要做他进沙漠考察时的向导。不过后来不知道为什么这单生意取消了，我记得…好像是这位巡林官实在耐不住热，还是其他什么原因来着。\", \"voicelineId\": 79021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_teammate_nahida_01\", \"description\": \"哼，我之前还以为，教令院里顶多是有一群自私自利的鬣狗在蝇营狗苟，结果…居然还有这么几匹喂不熟的白眼狼在作乱。依我看，那位小吉祥草王真是慈悲得有些过头了，对付这种劣兽，最好是连骨头都锤碎掉！就这么放他们去林子里歇着，真是太便宜他们了。\", \"voicelineId\": 79022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于坎蒂丝…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_teammate_candace_01\", \"description\": \"你说坎蒂丝啊，她什么都好，就是性子犟得和驮兽一样。我和她说了好多次，别老是绷着弦，偶尔也要给自己放个假，比如去须弥城里逛逛，买点漂亮衣服首饰…但她总是说不放心村子，拒绝了我好多次。唉，实在不行，下次我帮她守村子，然后再拜托团里的妹子们带她进城玩玩好了。\", \"voicelineId\": 79023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾尔海森…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_teammate_alhaitham_01\", \"description\": \"他曾经邀请我过去教令院任职，但我过不惯那种死水一潭般的生活，就拒绝了。不过这位书记官说话时那种七拐八绕，又夹枪带棒的腔调，倒是很符合我对教令院学者的印象…\", \"voicelineId\": 79024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_teammate_cyno_01\", \"description\": \"那位「大风纪官」？是个雷厉风行的狠角色，处理某些事情的方法，也挺对我胃口的。\", \"voicelineId\": 79025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于妮露…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_teammate_nilou_01\", \"description\": \"解决了那件事之后，妮露也能更加自由地跳舞了吧。哦她上次还说，要把自己用的香粉捎一份给我，但我经常在外面奔波，就只能让她先送去坎蒂丝那里。唔…我也该找个时间过去看看了。\", \"voicelineId\": 79026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于多莉…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_teammate_dori_01\", \"description\": \"那个商人啊。据说她那里什么都有得卖，只是价钱贵了点？哈哈，那我还挺希望和她见几面的，毕竟…有些佣兵需要的东西，在市场上真是拿钱都买不到啊。\", \"voicelineId\": 79027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱依拉…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_teammate_layla_01\", \"description\": \"那个成天迷迷糊糊的小丫头啊，我有印象。之前我在沙漠边缘的一个绿洲碰见过她，她好像是跟着教令院的什么队伍来观察星象，不过我也没有太留意。啥？坎蒂丝…星空的使者…这都什么乱七八糟的？这丫头不会还没睡醒吧。\", \"voicelineId\": 79028, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛索斯…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_teammate_sethos_01\", \"description\": \"我也是最近才知道他来自缄默之殿。哎呀，不好意思，我对缄默之殿这类神秘组织了解很少嘛。以前倒是在沙漠里见过他几回，他很好沟通，我的佣兵兄弟在沙漠遇到麻烦，他还把饮用水分给他们过。是个不错的人。\", \"voicelineId\": 79068, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪希雅·其一\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_friendship_01\", \"description\": \"我自小就在佣兵团里生活，玩具是木刀木剑，认识的人要么是佣兵，要么准备做佣兵，就连吃饭的木碗都是团里的人拿刀削出来的木碗。在这种环境下长大，要是我不做佣兵反而有点奇怪，对吧？\", \"voicelineId\": 79029, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解迪希雅·其二\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_friendship_02\", \"description\": \"我是哪里人？这我可不知道，我从来都没想过这方面的问题。但硬要说的话，我一直生活在沙漠里，应该算是「沙漠这边」的人吧。\", \"voicelineId\": 79030, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪希雅·其三\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_friendship_03\", \"description\": \"佣兵的工作可不容易，先不说接受的委托难度如何，更让人头疼的是完成委托后如何让客户迅速地结清钱款。教令院结钱最爽快，冒险家协会其次，结钱最不爽快的是那些做货物贸易的商人，他们总是说自己的资金正在周转，暂时拿不出多少现钱，让我再等等。\\n嘁，拿不出钱，那他们车上那么多货是怎么来的？\", \"voicelineId\": 79031, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪希雅·其四\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_friendship_04\", \"description\": \"在之前那件事过后，教令院对于我们的态度也有了改变，据说还推出了一大堆帮助沙漠子民的条款。呃，那一大堆文件我是看不懂了，我只希望「防沙壁」从今往后只隔绝风沙，不要再阻断希望。\", \"voicelineId\": 79032, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解迪希雅·其五\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_friendship_05\", \"description\": \"大部分佣兵的抱负就是扬名立万，他们不断地接受高难度的委托，赚取财富和名声。有的人幸运地活下来，成为了传奇，有些人就在沙漠里默默无闻的消失。\\n但我可没有那么「远大」的抱负，我只想要保护周围的人，让他们能安心地生活，这就足够了。要是能再赚点钱，那就更好了，哈哈。\", \"voicelineId\": 79033, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"迪希雅的爱好…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_pref_hobby\", \"description\": \"我有空的时候，最喜欢打理我的「妆匣」。里面的香粉和粉刷可都是我花大价钱收来的，你瞧瞧这粉质，多细腻啊！不管是流了汗，还是淋了雨，妆都不会花。哼哼，真是一分钱一分货。\", \"voicelineId\": 79034, \"voicelineType\": \"6001\"}, {\"title\": \"迪希雅的烦恼…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_dialog_annoyed\", \"description\": \"又有几笔委托的钱款没结清，还有几个兄弟执行委托的时候闯了祸…唉，我明明不是团里的一把手，为什么还要操心这种事？\", \"voicelineId\": 79035, \"voicelineType\": \"6002\", \"unlockConditions\": [{\"paramList\": [13026], \"unlockText\": \"完成「狮之血」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_pref_foodLike_01\", \"description\": \"那当然是「枣椰蜜糖」了，既容易携带，味道又好。\", \"voicelineId\": 79036, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_pref_foodDislike\", \"description\": \"可别让我吃那种味道很苦的东西，我可受不了。\", \"voicelineId\": 79037, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_spice_pref_01\", \"description\": \"这道菜味道真不错！再多吃几口的话，我说不定以后就吃不下那些干粮啦。\", \"voicelineId\": 79038, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_spice_normal_01\", \"description\": \"唔，如果当做干粮来看的话，味道还是不错的。\", \"voicelineId\": 79039, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_spice_dislike_01\", \"description\": \"至少…至少能填饱肚子，能安全填饱肚子的食物就是好食物！哈哈…\", \"voicelineId\": 79040, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_pref_birthday_01\", \"description\": \"生日快乐！摸摸你的兜，礼物已经放在里面了。怎么做到的？一点佣兵的小把戏而已。先别管这些了，我在兰巴德酒馆已经订了一桌上好的酒席，咱们赶紧过去吧。嗯？放心，我没有让团里的其他人过来，这帮人吵吵嚷嚷的只会起哄，好不容易过个生日，我来陪你就够了，走吧走吧。\", \"voicelineId\": 79041, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_starUp_01\", \"description\": \"哦？力量真的在成长。\", \"voicelineId\": 79042, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_starUp_02\", \"description\": \"感觉不错啊，这样挥起剑来也更有力了。\", \"voicelineId\": 79043, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_starUp_03\", \"description\": \"这种力量…真想立刻去试试手，不然我们俩直接来过几招吧？\", \"voicelineId\": 79044, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_dehya/vo_dehya_starUp_04\", \"description\": \"没想到我居然还能有这样的成长，这都多亏了你。接下来有什么委托吗？无论是什么委托，只要你开口，我就会和你同行。\", \"voicelineId\": 79045, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_battle_skill1_01\", \"description\": \"开打吧！\", \"voicelineId\": 79046, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_battle_skill1_02\", \"description\": \"不用留情。\", \"voicelineId\": 79047, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_battle_skill1_03\", \"description\": \"一起上！\", \"voicelineId\": 79048, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_battle_skill3_01\", \"description\": \"你撑得住吗？\", \"voicelineId\": 79049, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_battle_skill3_02\", \"description\": \"在这，打垮你！\", \"voicelineId\": 79050, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_battle_skill3_03\", \"description\": \"把牙咬紧点！\", \"voicelineId\": 79051, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_chest_open_01\", \"description\": \"居然还有意外收获…\", \"voicelineId\": 79052, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_chest_open_02\", \"description\": \"哈哈哈，这个不错啊。\", \"voicelineId\": 79053, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_chest_open_03\", \"description\": \"也许能卖个好价钱。\", \"voicelineId\": 79054, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_life_less30_01\", \"description\": \"哼…有点本事！\", \"voicelineId\": 79055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_life_less30_02\", \"description\": \"该动真格的了！\", \"voicelineId\": 79056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_life_less30_03\", \"description\": \"这不是正好？\", \"voicelineId\": 79057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_life_less30_teammate_01\", \"description\": \"稳住！别慌张！\", \"voicelineId\": 79058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_life_less30_teammate_02\", \"description\": \"退后，让我来！\", \"voicelineId\": 79059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_life_die_01\", \"description\": \"这下…糟了…\", \"voicelineId\": 79060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_life_die_02\", \"description\": \"真是…大意了…\", \"voicelineId\": 79061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_life_die_03\", \"description\": \"佣兵的…宿命…\", \"voicelineId\": 79062, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_battle_hit_L_01\", \"description\": \"小花招！\", \"voicelineId\": 79063, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_dehya/vo_dehya_battle_hit_H_01\", \"description\": \"有两下子…\", \"voicelineId\": 79064, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_dehya_teamJoin_01\", \"description\": \"你说了算。\", \"voicelineId\": 79065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_dehya_teamJoin_02\", \"description\": \"有什么委托吗？\", \"voicelineId\": 79066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_dehya_teamJoin_03\", \"description\": \"该开始干活了。\", \"voicelineId\": 79067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000080, 'Mika', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_draw_appear_01\", \"description\": \"西风骑士团游击小队所属，前进测绘员米卡，向你报到。与你并肩作战是我的荣幸，请随意差遣我吧…我会竭尽全力，为你探清前路，查明敌情！\", \"voicelineId\": 80000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·目标\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_character_idle_01\", \"description\": \"赶快调整好状态，不知道下个任务什么时候会来。\", \"voicelineId\": 80001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·记录状况\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_character_idle_02\", \"description\": \"核对当前位置、向目标扇区测距…嗯，地理状况记录完毕。\", \"voicelineId\": 80002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·探明道路\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_character_idle_03\", \"description\": \"无论处在什么环境里，只要仔细探索，应该都可以找到通畅的道路。\", \"voicelineId\": 80003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_weather_heavyRain_01\", \"description\": \"好大的雨…希望地面不要变得泥泞，不然就要帮大家擦靴子了…做饭的时间要不够了。\", \"voicelineId\": 80004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_weather_thunder_01\", \"description\": \"雷声可以掩盖行动的声响，是我们的好朋友。\", \"voicelineId\": 80005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_weather_snowy_01\", \"description\": \"积雪很漂亮，但又会把原来的地貌覆盖掉，我不太喜欢。\", \"voicelineId\": 80006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_weather_sunny_01\", \"description\": \"阳光柔和，视距充足，观察条件良好。嗯，心情真舒畅！\", \"voicelineId\": 80007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_weather_gale_01\", \"description\": \"这风…是出自风神的旨意，还是地形对大气的作用呢？\", \"voicelineId\": 80008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_greetingMorning\", \"description\": \"哦！早啊，我准备了远征队常吃的早饭，不介意的话，请一边用餐，一边和我说说今天的行动计划吧？\", \"voicelineId\": 80009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_greetingNoon\", \"description\": \"请稍等，游击小队最爱的三号野战午餐很快就准备好。待会儿我再看看，附近有没有适合午休的地方。\", \"voicelineId\": 80010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_greetingNight\", \"description\": \"晚饭完成了，虽然还是行军餐，有点简陋…但提供的营养肯定管够，请不要介意…如果有需要维护的装备，也请交给我吧。\", \"voicelineId\": 80011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_greetingNight2\", \"description\": \"时间还早，我要整理一下今天的勘测记录。行军床已经准备好了，请你先休息吧。等到你的精力恢复，夜宵应该也做好了，到时候，我们可以交替值岗。\", \"voicelineId\": 80012, \"voicelineType\": \"1004\"}, {\"title\": \"关于米卡自己·工作\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_idle\", \"description\": \"前进测绘员？这个岗位的职责是率先进入未知的区域，探明地形，寻找最有价值的阵位，有时还要对付敌方的哨兵。所以，除了测绘地形，我也得掌握战斗、医疗和野外生存的技巧。\", \"voicelineId\": 80013, \"voicelineType\": \"2001\"}, {\"title\": \"关于米卡自己·琐事\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_idle2\", \"description\": \"搭建营帐、生火做饭、维护装备，这些事总得有人来做嘛。如果别人嫌这些事麻烦，而我做得还勉强合格，那我至少可以…让大家轻松一点，开心一点？\", \"voicelineId\": 80014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·传闻\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_close\", \"description\": \"对不起，刚回蒙德那几天，我听说了你们的事迹。像你和派蒙这样的超级强者，总有自己独特的原则。有些强者的脾气不太好，也许我说错一个词，就会让他们不高兴…好在你们都很和善，我根本不用担心！\", \"voicelineId\": 80015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·暗语\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_close1\", \"description\": \"有的前锋会用「奥克塔维」表示「弩箭耗尽，正在返回营地」；用「薇拉」表示「状况良好，可以交战」。要不然，我们也约定几个暗语？毕竟我们会长期合作，这样更方便。哦，你说了算，我都听你的！\", \"voicelineId\": 80016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_pendant\", \"description\": \"说实话，能够得到「神之眼」，我也很吃惊。它的确能为我提供不少帮助，但我不能依赖它的力量，而是要把它当成一种保险手段。作为骑士团的一员，我更应该重视团队合作，想办法和同伴们一起战胜困难。\", \"voicelineId\": 80017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_share_01\", \"description\": \"有个简单的测距法，应该对你们有用：伸直手臂，竖起拇指对准目标，分别用右眼和拇指的轴线对准目标的左侧，左眼对准目标右侧，把两侧间的距离乘以一个数，就能提前确认山有多高，河有多宽，能不能一口气爬上山顶，游到对岸。\", \"voicelineId\": 80018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_pref_gift_01\", \"description\": \"听可莉前辈说，世上有种传递声音的植物，要是这种植物可以被随身携带就好了。这样一来，我就能实时汇报地形情况，甚至待在前方，为后方的同伴提供指引，用弩箭远远地抛射，早早排除威胁。\", \"voicelineId\": 80019, \"voicelineType\": \"3003\"}, {\"title\": \"关于凯亚…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_kaeya_01\", \"description\": \"入团之前，我接受了许多测试，主考官就是凯亚队长。凯亚队长一直支持着我，给我各种建议…不过，有时我不太理解他的话，担心自己跟不上他的节奏，让他扫兴。\", \"voicelineId\": 80020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽·教诲\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_varka_01\", \"description\": \"法尔伽大团长是万分可敬的强者，也是我在战斗方面的老师。他觉得我个子小，体力没优势，教导我「打架的理念要灵活」，「避免和敌人短兵相接」。所以，我才学着用长枪和手弩对付敌人，这样的战法的确更适合我。\", \"voicelineId\": 80021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于法尔伽·队长\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_varka_02\", \"description\": \"大团长还说，我要树立更高的目标，不断磨练本领，我一直是这么想的，但直到远征期间，我才明白事情的严重性。有一天，我们遇见了自称「队长」的愚人众执行官。我完全没法想象，该怎么招架那样的对手。强者的境界，对我来说实在太遥远了。\", \"voicelineId\": 80022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琴…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_qin_01\", \"description\": \"副团长…代理团长是让人安心的好前辈，一直守护着大家的强者。在工作排期、战地医疗、还有下厨这几个领域，我能向她学习的东西，简直无穷无尽。\", \"voicelineId\": 80023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于安柏…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_ambor_01\", \"description\": \"安柏长官…安柏前辈是最可靠的前锋，侦察领域的强者！前进测绘员和侦察骑士的阵位很接近，总是提前于主力部队行动。安柏前辈的经验太丰富了，我从她那里学到了很多野外生存的技巧，还有维护弩弦和箭矢的窍门。\", \"voicelineId\": 80024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于优菈·任务\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_eula_01\", \"description\": \"优菈队长是战斗风格独树一帜的强者，她一直很照顾我。我刚刚入队时，她就给我安排各种各样的任务，数量是其他队员的好几倍，更快地锻炼了我的适应力。只要习惯了她的表达方式，和她相处起来就很愉快！\", \"voicelineId\": 80025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于优菈·作风\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_eula_02\", \"description\": \"其实，我很羡慕优菈队长，她为人友善，作风洒脱，内心特别强大。要是我也被别人用奇怪的目光盯住，还在背后不停议论，我大概会不敢出门吧。\", \"voicelineId\": 80026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于丽莎…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_lisa_01\", \"description\": \"在我自学测绘的时候，丽莎长官一直在帮我，为我找到了好多有用的书，要是我也像她那样博学就好了。知识总归是不嫌多的，也许哪天就能用到呢？\", \"voicelineId\": 80027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于可莉…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_klee_01\", \"description\": \"可莉前辈？她的性格特别开朗，好像还是…和大团长旗鼓相当的强者？她好几次邀请我一起冒险，我们玩得超开心！虽然她偶尔会试验厉害的武器，让我重画很多地方的地图…不过，我也觉得很值得！\", \"voicelineId\": 80028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于温迪…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_venti_01\", \"description\": \"好喜欢那位吟游诗人，他是演奏乐器的强者，他的曲调总让我有种回到家里的亲切感。如果要选出最能代表蒙德的曲子，我一定投他的作品一票。可惜我平常待在城里的时间不多，不然就可以每天送他一些礼物了。\", \"voicelineId\": 80029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于阿贝多…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teammate_albedo_01\", \"description\": \"阿贝多长官对我有恩，我常用的测绘装备就是他帮我制作的，还有一种绘图笔，就算倒挂在树上，也能正常使用。嗯不过，测绘地图和画画好像并不相通？之前我对着目标区域画过几张写生，作为补充的情报，听说阿贝多长官看见之后，沉默了好久。\", \"voicelineId\": 80030, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解米卡·其一\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_friendship_01\", \"description\": \"我自己的事？我只是个普通人，没什么有意思的故事。如果只聊我以前的经历，你愿意听吗？\", \"voicelineId\": 80031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解米卡·其二\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_friendship_02\", \"description\": \"从小时候起，我就想当一个地图测绘员，描绘出提瓦特每个角落的轮廓。后来我发现，骑士团正好有这样的岗位，就在哥哥和爸爸的支持下参加了选拔，当上了前进测绘员。这份工作让我过上了理想中的生活，我已经心满意足了。\", \"voicelineId\": 80032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解米卡·其三\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_friendship_03\", \"description\": \"骑士团的大家都好强，每个人都有值得我学习的地方。我从大家身上学到了新的本领，也应该给大家回报，如果大家有需要我的地方，我都会尽全力帮忙。\", \"voicelineId\": 80033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解米卡·其四\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_friendship_04\", \"description\": \"不过，帮大团长和优菈队长跑过几次腿后，有的同伴已经把我当成两位长官的信使了。如果我说错了话，给两位长官带来了困扰，那可就是我的过错了。所以，每次和不太熟悉的同伴交谈，我多少都有点拘束，让大家觉得我很胆小，这算是一种误解吗？\", \"voicelineId\": 80034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解米卡·其五\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_friendship_05\", \"description\": \"好在，经历过远征后，我没那么担心了。只要不给其他人添麻烦，就算大家对我有什么看法，我也不会介意。骑士团就像是我的第二个家，我要把前进测绘员的工作干得完美无缺，让我的家人们平平安安地完成任务，轻松愉快地度过每一天。\", \"voicelineId\": 80035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"米卡的爱好…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_pref_hobby\", \"description\": \"爱好吗…除了工作，我最喜欢的应该是…在陌生的地方野营了。沉浸在新鲜的美景里，搭一个舒舒服服的营地，升起篝火做一顿好吃的饭菜，真的很愉快！\", \"voicelineId\": 80036, \"voicelineType\": \"6001\"}, {\"title\": \"米卡的烦恼…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_dialog_annoyed\", \"description\": \"说实在的，我不擅长和陌生人打交道，也许是我不懂说话的技巧吧。这方面的窍门，能请你教一教我吗？\", \"voicelineId\": 80037, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_pref_foodLike_01\", \"description\": \"大团长说，我这种年轻人就该多吃肉，把力量和体能练得棒棒的。虽然我怎么也不可能长出一身结实的肌肉啦，但我确实很喜欢肉类料理，这一点倒是和游击小队的大家很合拍。\", \"voicelineId\": 80038, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_pref_foodDislike\", \"description\": \"不像我的哥哥，我完全欣赏不了酒的风味，只要喝上一小口，我就会醉得不省人事，给大家添麻烦。碰上有的陈年烈酒，光是打开瓶塞后的气味，都能让我脚步发晃。\", \"voicelineId\": 80039, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_spice_pref_01\", \"description\": \"太感谢了，这道料理实在太珍贵，我怎么舍得吃！可以把它收藏起来吗？\", \"voicelineId\": 80040, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_spice_normal_01\", \"description\": \"口味和份量都无可挑剔，让你为我费心了。\", \"voicelineId\": 80041, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_spice_dislike_01\", \"description\": \"唔…不管怎么样，这可是你为我做的饭菜，我一定会吃完的。\", \"voicelineId\": 80042, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_pref_birthday_01\", \"description\": \"这种时候应该怎么说才好呢…嗯，今天是最特别的日子！应该用最热烈、最盛大的方式来庆祝！我为你准备了一本「蒙德绝景游览手册」，手册上记录了很多风景优美的地点，但没什么人知道这些地方哦。希望你从今天到明年的今天，每天都开开心心！\", \"voicelineId\": 80043, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_starUp_01\", \"description\": \"虽然比起你还差得远，但我现在有一点信心了，至少不会再拖你的后腿。\", \"voicelineId\": 80044, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_starUp_02\", \"description\": \"希望我能给你带来更多有用的情报，真真切切地帮你分担压力！\", \"voicelineId\": 80045, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_starUp_03\", \"description\": \"请允许我…一直和你同行，一起丈量脚下的大地！\", \"voicelineId\": 80046, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_starUp_04\", \"description\": \"实在感谢！这下，我就距离目标更近了——让大家安安心心地前进，不必在崎岖的地形受苦受累，也不用惧怕角落里隐藏的危险！\", \"voicelineId\": 80047, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_skill1_01\", \"description\": \"速射牵制。\", \"voicelineId\": 80048, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_skill1_02\", \"description\": \"试探攻击。\", \"voicelineId\": 80049, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_skill1_03\", \"description\": \"请你后退。\", \"voicelineId\": 80050, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_skill1_04\", \"description\": \"精确射击！\", \"voicelineId\": 80051, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_skill1_05\", \"description\": \"对不起了！\", \"voicelineId\": 80052, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_skill1_06\", \"description\": \"肃清威胁！\", \"voicelineId\": 80053, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_skill3_01\", \"description\": \"大家，请振作！\", \"voicelineId\": 80054, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_skill3_02\", \"description\": \"我负责医疗！\", \"voicelineId\": 80055, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_skill3_03\", \"description\": \"打开突破口！\", \"voicelineId\": 80056, \"voicelineType\": \"200003\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_explore_fly_start_01\", \"description\": \"从高处观察…\", \"voicelineId\": 80057, \"voicelineType\": \"800001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_chest_open_01\", \"description\": \"是新的收获！\", \"voicelineId\": 80058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_chest_open_02\", \"description\": \"有战利品吗？\", \"voicelineId\": 80059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_chest_open_03\", \"description\": \"找到了宝藏，恭喜大家！\", \"voicelineId\": 80060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_life_less30_01\", \"description\": \"有点麻烦…\", \"voicelineId\": 80061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_life_less30_02\", \"description\": \"要改变战术吗？\", \"voicelineId\": 80062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_life_less30_03\", \"description\": \"对手…很强啊。\", \"voicelineId\": 80063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_life_less30_teammate_01\", \"description\": \"请后撤，我来顶住！\", \"voicelineId\": 80064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_life_less30_teammate_02\", \"description\": \"要快点治疗…\", \"voicelineId\": 80065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_life_die_01\", \"description\": \"早知道…就迂回了…\", \"voicelineId\": 80066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_life_die_02\", \"description\": \"对不起，大家…\", \"voicelineId\": 80067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_life_die_03\", \"description\": \"完了…我搞砸了…\", \"voicelineId\": 80068, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_hit_L_01\", \"description\": \"要忍住！\", \"voicelineId\": 80069, \"voicelineType\": \"900001\"}, {\"title\": \"普通受击·其二\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_hit_L_02\", \"description\": \"没问题的！\", \"voicelineId\": 80070, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_hit_H_01\", \"description\": \"不痛…不痛！\", \"voicelineId\": 80071, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_mika/vo_mika_battle_hit_H_02\", \"description\": \"不能慌张…\", \"voicelineId\": 80072, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teamJoin_01\", \"description\": \"清点装备…一切就位。\", \"voicelineId\": 80073, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teamJoin_02\", \"description\": \"嗯，长枪和弩箭都准备好了。\", \"voicelineId\": 80074, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_friendship/VO_mika/vo_mika_teamJoin_03\", \"description\": \"我…我来为队伍探路！\", \"voicelineId\": 80075, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000081, 'Kaveh', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_draw_appear_01\", \"description\": \"能像这样见面是件好事，眼光相近的人才能共同开启一段愉快的对话。\\n初次见面，你好，我是建筑设计师卡维，有什么事需要我帮忙的话，请先详细说明你的需求。\", \"voicelineId\": 81000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·美学\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_character_idle_01\", \"description\": \"懂得欣赏美是一种好的品德。\", \"voicelineId\": 81001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·解闷\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_character_idle_02\", \"description\": \"人不能老是闷在家里，多出去走走吧。\", \"voicelineId\": 81002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·完善\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_character_idle_03\", \"description\": \"上次的方案还能优化一下，趁没到截止日再改改好了…\", \"voicelineId\": 81003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_weather_heavyRain_01\", \"description\": \"欸？怎么下雨了？糟糕，没带伞…\", \"voicelineId\": 81004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_weather_thunder_01\", \"description\": \"你看到了吗？刚才那道闪电的形状好特别！\", \"voicelineId\": 81005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_weather_snowy_01\", \"description\": \"嘶…背后有点漏风的感觉…胸口也有…\", \"voicelineId\": 81006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_weather_sunny_01\", \"description\": \"太阳晒久了就想睡觉，跟熬夜工作的感觉差不多，都是头晕。\", \"voicelineId\": 81007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_weather_desert_01\", \"description\": \"不是第一次来了，可每次都这么热…唉，有没有阴凉的地方…\", \"voicelineId\": 81008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_greetingMorning\", \"description\": \"睡得好吗？希望你今天顺利，别遇到那种一大早就能惹你生气的人。\", \"voicelineId\": 81009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_greetingNoon\", \"description\": \"正午阳光好烈，我晒在外面的材料怎么样了…\", \"voicelineId\": 81010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_greetingNight\", \"description\": \"今晚能看到许多星星呢，不觉得是个好兆头吗？\", \"voicelineId\": 81011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_greetingNight2\", \"description\": \"放空大脑忘掉所有烦心事，晚安。\", \"voicelineId\": 81012, \"voicelineType\": \"1004\"}, {\"title\": \"关于卡维自己·专业\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_idle\", \"description\": \"谈到专业领域，我算是个骄傲的人。学者面对自己的专长大多如此，不如说，这是我们的根基。假如连这份骄傲都失去了，我就不可能再对自己和别人提出什么要求。\", \"voicelineId\": 81013, \"voicelineType\": \"2001\"}, {\"title\": \"关于卡维自己·艺术\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_idle2\", \"description\": \"艺术性不是也不该是我工作的第一追求，质量和安全性才是。但我从未放弃它，它是将我区别于他人的根本。\", \"voicelineId\": 81014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·欣赏\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_close\", \"description\": \"你应该见过卡萨扎莱宫吧？那是我最得意的作品。我为它付出了很多，多到别人难以理解…哈哈，你们不是我，又不从事这个行业，无法理解也正常。唔…不过偶尔还是希望别人能理解一下。\", \"voicelineId\": 81015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·理想\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_close1\", \"description\": \"看透一个人的理想才能真正触摸到他，我一直这么想。但理想、美梦这种东西…接触自己的或他人的都是在冒险，会开启某些可能。不是每个人都有能力面对那些。\", \"voicelineId\": 81016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_pendant\", \"description\": \"可以的话，我不想把这句话说出口…拥有愿望有时是一件令人痛苦的事。幸好，我不讨厌我的「神之眼」。\", \"voicelineId\": 81017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_share\", \"description\": \"明白自己为什么而进行创造的人值得尊重。你应该也这么觉得吧？\", \"voicelineId\": 81018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_pref_gift_01\", \"description\": \"外行经常认为妙论派建筑设计师的专业领域就是土块、木材什么的，这种观点肤浅到没必要与之辩论。假如把各种材料拼在一起就叫造房子，那就是在否定这门学科的意义。建筑设计是人文的一环，也是艺术，艺术无法脱离人单独存在。使用者的感受，观看者的心境…我会考虑这些。啊对，怎么更好地融合艺术表达与人文需求也很重要。\", \"voicelineId\": 81019, \"voicelineType\": \"3003\"}, {\"title\": \"关于小吉祥草王…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_teammate_nahida_01\", \"description\": \"小吉祥草王是一位非常贤明的神，充满智慧，更拥有常人无法匹敌的美德。她能理解包容他人，在须弥这样的学术之国里，她的沉稳叫我钦佩。\\n偶尔我会想，神明难道就毫无烦恼吗？智慧时常伴随困惑而生，那什么才算得上真正的幸福？\", \"voicelineId\": 81020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾尔海森·脾气\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_teammate_alhaitham_01\", \"description\": \"谁都不可能从人群中找出第二个像他一样令人无语的家伙！这话就算他本人来了我也敢说。\\n你也知道他很聪明，都说聪明人容易脾气差，这话算是对了一半吧，可他不一样…他完全清楚怎么表现得更符合大众定义的友好，只是不想。\\n假如你觉得他脾气很好，或者觉得他死板教条像台机器，那说明你们还不够熟。他就是太有性格，普通人理解不了。\", \"voicelineId\": 81021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾尔海森·复杂\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_teammate_alhaitham_02\", \"description\": \"艾尔海森帮了我一些忙，如果我们的关系还像学生时代那么好，我肯定会三天两头感谢他。现在嘛…说不出口，也不想就这么承认。\\n该说是有好有坏吗？很多事就像命运的恶作剧…不是重来几次就能看清的。当然，能认识这样一个人也算难得，他要是能收起性格中比较恶劣的部分就更好了。好吧不可能。\", \"voicelineId\": 81022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_teammate_tighnari_01\", \"description\": \"提纳里啊，你见到他就会明白的，他是非常好的人，善良又渊博，而且从不将知识当成炫耀的资本。他是真心喜欢他的工作。\\n建造卡萨扎莱宫那段时间我向他请教过挑选园艺花卉的办法，他回信给我，后来还帮我处理了一些别的问题。噢对，赛诺也是我通过他认识的。\", \"voicelineId\": 81023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于多莉…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_teammate_dori_01\", \"description\": \"多莉是卡萨扎莱宫的主人…你说什么？废话，卡萨扎莱宫当然不是我的…别说了别说了！\\n她很精明，懂得如何控制别人为自己办事。我…呃…我因为一些原因欠她钱，那件事很复杂…反、反正，还是希望她手下留情，别总是为钱的问题折腾我。她明明可以成为更善良的好人的啊，怎么会这样呢？\", \"voicelineId\": 81024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_teammate_cyno_01\", \"description\": \"赛诺看似冷酷无情，其实很热心肠。记得当初提纳里说要给我介绍他最好的朋友，我一回头就看见一个气势惊人的风纪官走进门…真没想到，本来以为那种类型的风纪官不会跟学者走得太近。\\n不过赛诺的冷笑话我受不了，冬天听到那些会汗毛倒竖。他约你一起去提纳里家吃饭的话，你最好多穿件外套。\", \"voicelineId\": 81025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于柯莱…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_teammate_collei_01\", \"description\": \"我和柯莱见过不少次了，她一直跟在提纳里身边，既是助手也是学生。柯莱做事很认真，又有耐心，比同龄人可靠不少。\\n嗯…不过能看出来，她的心事不少。\", \"voicelineId\": 81026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于妮露…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_teammate_nilou_01\", \"description\": \"妮露作为舞蹈家的实力毋容置疑，祖拜尔剧场能招到这样一位演员未免太走运了点。\\n听说她性格也很好，跳舞时一直在笑，对每个观众都说鼓励的话。等有时间，我也会去看她的演出。\", \"voicelineId\": 81027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珐露珊…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_teammate_faruzan_01\", \"description\": \"珐露珊前辈心直口快，听说教令院有些学生怕她，能理解，不过她从来没有什么坏心思，就是一心扑在自己感兴趣的学问上。有人觉得知论派都难相处，这个嘛…哈哈。\\n她应该也请你当她的学生了吧？的确，珐露珊前辈有时像个疯狂的推销员…学问倒都是真的，这点不会错。\", \"voicelineId\": 81028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解卡维·其一\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_friendship_01\", \"description\": \"听说我在须弥小有名气？哈哈哈，都是大家随口说的，我自己觉得还好。在这里生活久了谁都有可能出名，保持低调才难。\\n但愿你不是通过破产丑闻认识我的，哼。如果你想听，我也可以给你讲讲我的优点。\", \"voicelineId\": 81029, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解卡维·其二\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_friendship_02\", \"description\": \"你应该不会去教令院当学生吧？从务实的角度出发，我建议你就算要去也别选设计，设计很有意思，累也是真的累。刚毕业那会儿我在前辈手底下打工，每天做牛做马，被人使唤来使唤去，坚持了好久，差点把自己累死。\", \"voicelineId\": 81030, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解卡维·其三\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_friendship_03\", \"description\": \"人的审美很难统一，但美是一种相对具体的概念，我认为美学之中存在基础标准。审美本身也不是不能提升，就是费时，需要大量积累。你需要这方面参考的话，可以来找我。\", \"voicelineId\": 81031, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解卡维·其四\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_friendship_04\", \"description\": \"有人说我经常惹麻烦，这算什么话？只要一个人还在前进，难免会跟其他人事物发生摩擦，不能因为怕麻烦就对很多事视而不见。\", \"voicelineId\": 81032, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解卡维·其五\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_friendship_05\", \"description\": \"休息时我会去喝酒，酒能冲淡烦恼。嗯？噢，是啊，只是为了打发时间。\\n呃…咳！别这么看着我…好吧好吧我承认我就是有很多烦恼！没做完的工作，解决不了的困难，人和人的隔阂…难道你不会考虑这些吗？\", \"voicelineId\": 81033, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"卡维的爱好…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_pref_hobby\", \"description\": \"音乐，建筑，雕塑，绘画艺术，都是值得花时间欣赏的东西。\\n不敢说我都会，但有了兴趣，以后说不定能全部精通的吧。你看，至少我会弹琴。\", \"voicelineId\": 81034, \"voicelineType\": \"6001\"}, {\"title\": \"卡维的烦恼…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_dialog_annoyed\", \"description\": \"烦恼啊…唔，最直观的烦恼还是经济问题。\\n我不是赚不到钱，而是留不住钱。生活中有太多可能用到钱的场合了，一不小心就…不过别担心，我比以前好多了，会提高警惕避免陷入困境。\", \"voicelineId\": 81035, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_pref_foodLike_01\", \"description\": \"酒、热汤、有奶油和奶酪的菜肴，这些我都喜欢。还有新鲜水果也不错。\", \"voicelineId\": 81036, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_pref_foodDislike\", \"description\": \"太辣太烫的东西很难入口，我不行，至少也要等放凉了才能吃。\", \"voicelineId\": 81037, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_spice_pref_01\", \"description\": \"真不错！能教教我怎么做吗？\", \"voicelineId\": 81038, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_spice_normal_01\", \"description\": \"拿来下酒不错哦。\", \"voicelineId\": 81039, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_spice_dislike_01\", \"description\": \"…嗯？唔…呃…呃…\", \"voicelineId\": 81040, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_pref_birthday_01\", \"description\": \"今天是你生日吗？恭喜你，生日是很重要的日子，也是一年之中最容易想起家人的日子。希望你能在这天有好心情。\", \"voicelineId\": 81041, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_starUp_01\", \"description\": \"感觉不错，谢谢。\", \"voicelineId\": 81042, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_starUp_02\", \"description\": \"嗯？还能再来一次吗？\", \"voicelineId\": 81043, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_starUp_03\", \"description\": \"视野变得更开阔了…我想把这份感觉延续下去。\", \"voicelineId\": 81044, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_kaveh/vo_kaveh_starUp_04\", \"description\": \"拥有的力量越多，能做到的事就更多。哪怕完成这些事需要代价，哪怕理想从来都建立在痛苦之上，我也…不想后退。\", \"voicelineId\": 81045, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_battle_skill1_01\", \"description\": \"扫描！\", \"voicelineId\": 81046, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_battle_skill1_02\", \"description\": \"来吧！\", \"voicelineId\": 81047, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_battle_skill1_03\", \"description\": \"障碍清除！\", \"voicelineId\": 81048, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_battle_skill3_01\", \"description\": \"看好了！\", \"voicelineId\": 81049, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_battle_skill3_02\", \"description\": \"工程开始。\", \"voicelineId\": 81050, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_battle_skill3_03\", \"description\": \"万众瞩目！\", \"voicelineId\": 81051, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_chest_open_01\", \"description\": \"新发现！\", \"voicelineId\": 81052, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_chest_open_02\", \"description\": \"捡到好东西了，很开心吧？\", \"voicelineId\": 81053, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_chest_open_03\", \"description\": \"该说是意外之喜还是超乎想象…\", \"voicelineId\": 81054, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_life_less30_01\", \"description\": \"真是麻烦！\", \"voicelineId\": 81055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_life_less30_02\", \"description\": \"没有下一次了。\", \"voicelineId\": 81056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_life_less30_03\", \"description\": \"唔…走开！\", \"voicelineId\": 81057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_life_less30_teammate_01\", \"description\": \"这里交给我！\", \"voicelineId\": 81058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_life_less30_teammate_02\", \"description\": \"到后面去。\", \"voicelineId\": 81059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_life_die_01\", \"description\": \"还有…没完成的事…\", \"voicelineId\": 81060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_life_die_02\", \"description\": \"为什么…\", \"voicelineId\": 81061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_life_die_03\", \"description\": \"不许…践踏我的理想…\", \"voicelineId\": 81062, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_battle_hit_H_01\", \"description\": \"呜！别这样…\", \"voicelineId\": 81063, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_kaveh/vo_kaveh_battle_hit_H_02\", \"description\": \"咳！没什么的。\", \"voicelineId\": 81064, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_kaveh_teamJoin_01\", \"description\": \"需要帮忙？\", \"voicelineId\": 81065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_kaveh_teamJoin_02\", \"description\": \"放着我来好了。\", \"voicelineId\": 81066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_kaveh_teamJoin_03\", \"description\": \"是甲方吗？还是…哦！不是啊。\", \"voicelineId\": 81067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000082, 'Baizhu', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_draw_appear_01\", \"description\": \"嗯，我是「不卜庐」的大夫白术。身体哪里不适，有几天了，和我说说吧…哦？不是来问诊而是专程来找我的？抱歉，恐怕要请你稍候了，我接待完后面的病人就来和你详谈。\", \"voicelineId\": 82000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·慢节奏\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_character_idle_01\", \"description\": \"白术：这一路上的无限风光，得慢慢欣赏才有意趣。\\n长生：你是不是跑不动了？\", \"voicelineId\": 82001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·天道\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_character_idle_02\", \"description\": \"生死有道，天行有常…呵呵，不试一试，谁能知道这天道的边界在哪里呢？\", \"voicelineId\": 82002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·体质\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_character_idle_03\", \"description\": \"咳…咳…老毛病了，不是什么大事，你别担心。\", \"voicelineId\": 82003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_weather_heavyRain_01\", \"description\": \"雨天湿寒，还是找个地方避避吧。\", \"voicelineId\": 82004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_weather_thunder_01\", \"description\": \"别怕，小心看路，不要在树下行走，雷电伤不了我们。\", \"voicelineId\": 82005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_weather_snowy_01\", \"description\": \"长生：…好冷，好困。\\n白术：长生？这就睡着了吗…\", \"voicelineId\": 82006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_weather_sunny_01\", \"description\": \"白术：好天气，「不卜庐」新收的药草…\\n长生：放心啦，就算七七忘记晾药草，阿桂也不会忘的，好好晒太阳吧。\\n白术：的确。\", \"voicelineId\": 82007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_weather_gale_01\", \"description\": \"碰上这么大的风你也不躲吗？唉，要爱惜自己的身体啊。\", \"voicelineId\": 82008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_greetingMorning\", \"description\": \"早上好。我习惯餐前一杯茶，要给你倒一杯吗？\", \"voicelineId\": 82009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_greetingNoon\", \"description\": \"午餐后不要久坐，最好起身走一走，有助于消食。\", \"voicelineId\": 82010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_greetingNight\", \"description\": \"晚上好，如果是来看病的话，抱歉了，今天「不卜庐」大夫的坐诊时间已经结束。不过，你有紧急情况的话那自然另当别论。如果只是来找我的话，正好，现在是我的私人时间。\", \"voicelineId\": 82011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_greetingNight2\", \"description\": \"还不想睡吗？可你已经在打哈欠了。\", \"voicelineId\": 82012, \"voicelineType\": \"1004\"}, {\"title\": \"关于白术自己·今方古方\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_idle\", \"description\": \"师父的确留下了不少古人总结出的千金良方。不过古方虽然久经考验，我们这些今人却不能一味泥古。古时与今时，环境不同，风俗有异，过去管用的方子今天不一定管用。还守着过去的千金良方，最终是要耽误病患性命的。\", \"voicelineId\": 82013, \"voicelineType\": \"2001\"}, {\"title\": \"关于白术自己·医心\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_idle2\", \"description\": \"久病的人精神萎靡，如果得的是重症，更是全凭一口气吊着。这时候最要紧的事不是医治他的身体，而是稳固他的信心。毕竟病人要是认定自己活不成，也不想活了，再高明的医术也都无能为力了。\", \"voicelineId\": 82014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·医患\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_close\", \"description\": \"凡是来「不卜庐」求医的，不论贵贱，我都会一视同仁，尽力救治，你也不例外。\", \"voicelineId\": 82015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·试药\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_close1\", \"description\": \"甲之毒药，乙之蜜糖。对某些人来说百害无一利的毒物，对另一些人来说却恰好是救命的良药，这在药理上也是成立的。只是这些话却不能对普通病患说，要是让他们知道我开的方子里有毒药，恐怕以后就再也不敢来这里了吧。\\n知道了这件事却毫不恐惧的，你还是第一个。不愧是见多识广的旅行者，那么以后我也可以放心给你开些猛药了吧？正愁找不到试药的人呢，呵呵。\", \"voicelineId\": 82016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_pendant\", \"description\": \"呵呵，神也允许我这狂妄之人探索生死之道呢。这神之眼来得正好，多谢了。\", \"voicelineId\": 82017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·蜜饯\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_share_01\", \"description\": \"说了不怕你笑话，其实我自己也不爱喝苦药。我的体质你也知道，常年喝药是免不了了，没办法，只能喝完药多吃点蜜饯缓解一下嘴里的苦味。\", \"voicelineId\": 82018, \"voicelineType\": \"3002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·秘药\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_share_02\", \"description\": \"我曾遇上一些人，身体略有不适，便以为自己得了重病，以理相劝仍是不依不饶。后来，我干脆以甜甜花和清心为原料，调制出了一批白色无味的药丸，配给这批疑心过重的「患者」。他们得到安慰后，「病情」有所缓和，转而称赞起了我「秘药」的效力。像这类情况，我也是能够理解的。\", \"voicelineId\": 82019, \"voicelineType\": \"3005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_pref_gift_01\", \"description\": \"据说须弥雨林中的蘑菇种类众多，有些品种甚至能让人产生幻觉，大概有些药用价值。不过我一直没有机会详细考察一番，要是以后能有闲暇亲眼看看就好了。\", \"voicelineId\": 82020, \"voicelineType\": \"3003\"}, {\"title\": \"关于七七…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_teammate_qiqi_01\", \"description\": \"你猜得没错，封住七七一缕神智的的确是仙人的秘法。也是多亏七七，我才摸索出了保住将死之人的方法。既然仙人都怜悯这孩子，施法将她留在「此岸」，那我顺水推舟收留她，又有何不妥呢？\", \"voicelineId\": 82021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃·道不同\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_teammate_hutao_01\", \"description\": \"观念不同而已，我对胡堂主本人并无意见。非要说的话，应该是她防备我居多吧。\", \"voicelineId\": 82022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃·疲惫\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_teammate_hutao_02\", \"description\": \"白术：有可能的话，我还是希望胡堂主做生意时注意些方式方法。\\n长生：哦，原来你还记着她到「不卜庐」门口打广告的事啊。\\n白术：唉，没事的时候，也别总是惦记七七了。\\n长生：你其实对她有意见吧？\\n白术：我又怎么会真跟她计较呢，只是每次她把七七带走，我都要费劲拜托总务司寻人，实在太累人了。\", \"voicelineId\": 82023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_teammate_ganyu_01\", \"description\": \"仙家体质强健，即便身体有恙，不需药物也能自愈。不像凡夫俗子，一旦伤筋动骨，没有医治非落下残疾不可。\", \"voicelineId\": 82024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_teammate_keqing_01\", \"description\": \"从面部状态来看，玉衡星应该是习惯了熬夜，且思虑过多，才会时不时显露疲态。想要保养好身体的话，还得放下工作，静养为宜。可惜她太过上进，似乎是打定了主意要用健康换事业，我这话说了她未必听得进去。\", \"voicelineId\": 82025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于瑶瑶…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_teammate_yaoyao_01\", \"description\": \"…这孩子每次来找七七玩耍时都要和我抱怨药苦，问我有没有不苦的药。治病救人的药，哪有不苦的呢？\", \"voicelineId\": 82026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_teammate_zhongli_01\", \"description\": \"钟离先生这样的博学多闻之士，哪怕是聊起偏门的古医方也能从容应答，肯定自有一套养生调理的讲究。普通的头疼脑热他自己就能解决了，的确没必要到我这里来开方子。\", \"voicelineId\": 82027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_teammate_xiao_01\", \"description\": \"白术：降魔大圣杀生为护生，心有大慈悲。我曾有幸亲眼见过他本人，还将昏迷的他带回庐中照顾了一天，只可惜当时我不识仙师真身，又没来得及多交谈几句，他就独自离开了。\\n长生：后来你们不是又见过嘛，不用遗憾啦。\\n白术：说得也是。\", \"voicelineId\": 82028, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11029], \"unlockText\": \"完成「医心」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_teammate_tighnari_01\", \"description\": \"原来须弥教令院里有你的相识？那能否麻烦你帮我与这位提纳里先生联络一番，我有不少药草方面的事情想要请教。\", \"voicelineId\": 82029, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于嘉明…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_teammate_gaming_01\", \"description\": \"比起这个年纪的寻常少年，他身上有更多伤痕旧患，每每过来又常添不少淤青扭损…唉，劝恐怕是劝不住的。我教过他一些包扎和养护的方法，希望对他有帮助。\", \"voicelineId\": 82070, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解白术·其一\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_friendship_01\", \"description\": \"我一个治病的大夫，身上能有什么有趣的故事。你要是对传奇故事感兴趣，不如去和裕茶馆请说书先生讲几段。\", \"voicelineId\": 82030, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解白术·其二\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_friendship_02\", \"description\": \"非要说什么惊心动魄的故事，我这里实在没有。当初我拜师学医时，也没经历什么重大考验，师父他老人家看我不算太笨，让我发了简单的誓，也就入门了。\", \"voicelineId\": 82031, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11029], \"unlockText\": \"完成「医心」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解白术·其三\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_friendship_03\", \"description\": \"誓言不算复杂，我还记得个大概：\\n「…若有疾厄来求救者，不得问其贵贱贫富，亦不得瞻前顾后，自虑吉凶。见彼苦恼，若己有之，如此可为苍生大医。」\", \"voicelineId\": 82032, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11029], \"unlockText\": \"完成「医心」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解白术·其四\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_friendship_04\", \"description\": \"师父的意思我明白，他是希望我勿为外物所动，多为病患考虑。唉，他老人家的确是宅心仁厚，一心舍己救人，可惜未享天年便早早去了。\", \"voicelineId\": 82033, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11029], \"unlockText\": \"完成「医心」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解白术·其五\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_friendship_05\", \"description\": \"医者普救世人，但我以为医者自身也在世人之列。身为医者，既要救人也要救己，舍己为人固然值得钦佩，但没有人生来就是要为他人牺牲的，不该这样。\", \"voicelineId\": 82034, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11029], \"unlockText\": \"完成「医心」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"白术的爱好…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_pref_hobby\", \"description\": \"分拣药材，再依其各自特性炮制成药丸或是药膏，这其中的过程我再熟悉不过。世人都觉得制药过程繁难，但在我看来，其实乐趣无穷。试想，竟有人能将天地造化之功凝聚于小小一剂药中，挽救苍生性命，不是很奇妙吗？\", \"voicelineId\": 82035, \"voicelineType\": \"6001\"}, {\"title\": \"白术的烦恼…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_dialog_annoyed\", \"description\": \"为病人看诊时最麻烦的从来不是配药，而是找对病因。唉，病人们身体不适的原因真是千奇百怪，有和人比赛吃绝云椒椒吃到肠胃受损而不自知的，有过量饮水导致头晕恶心的…我只盼望世人都能以健康为重，没事不要胡乱折腾自己的身体。\", \"voicelineId\": 82036, \"voicelineType\": \"6002\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_pref_foodLike_01\", \"description\": \"挑食可不是好事。肉、蛋、奶、蔬菜、水果…凡是有营养的食物都要吃，但也不能吃得太多，暴饮暴食同样对身体有害。你别嫌我唠叨，正因我是大夫，才深刻地明白祸从口入的道理。\", \"voicelineId\": 82037, \"voicelineType\": \"6005\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_pref_foodDislike\", \"description\": \"怎么买了这么多糖？你别一口气吃太多，糖吃多了容易蛀牙。我？我对甜味的摄入很有分寸，辛辣的食物也不常吃。你说的没错，我的确非常注意饮食管理。毕竟，如果我连自己的饮食都管不好，又怎么好意思给病人提饮食建议呢。\", \"voicelineId\": 82038, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_spice_pref_01\", \"description\": \"长生：还有吗？多来点！\\n白术：味道的确不错。\", \"voicelineId\": 82039, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_spice_normal_01\", \"description\": \"你的厨艺有进步，恭喜。\", \"voicelineId\": 82040, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_spice_dislike_01\", \"description\": \"不用担心，味道总比药好些。\", \"voicelineId\": 82041, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_pref_birthday_01\", \"description\": \"长生：那话怎么说来着…哎呀，白术，提醒我一下。\\n白术：过生日时的吉利话吗？\\n长生：对对对。\\n白术：愿你年年有今日，岁岁有今朝。旅行者，生日快乐。\\n长生：话都被你说了，那我说什么？算了，我再想点别的。我祝旅行者…嗯…嗯…唉，想不出来了，祝你心情愉快吧。\\n长生：你们笑什么嘛，人就是麻烦，比蛇还会弯弯绕。\", \"voicelineId\": 82042, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_starUp_01\", \"description\": \"凡事需循序渐进，不必急躁。\", \"voicelineId\": 82043, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_starUp_02\", \"description\": \"多劳你费心，感觉身体比以前强健了不少。\", \"voicelineId\": 82044, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_starUp_03\", \"description\": \"大概是最近体质有所变化的缘故，精神比从前好了许多，坐诊一天下来也不觉得疲惫。这都是你的功劳。\", \"voicelineId\": 82045, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_baizhu/vo_baizhu_starUp_04\", \"description\": \"连日来辛苦你了。明明我自己就是大夫，却还要麻烦你为我的身体忙前忙后，咳咳…惭愧。放心，往后不会有这种事了，我会照顾你。\", \"voicelineId\": 82046, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_battle_skill1_01\", \"description\": \"长生：得治治。\", \"voicelineId\": 82047, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_battle_skill1_02\", \"description\": \"良药苦口啊。\", \"voicelineId\": 82048, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_battle_skill1_03\", \"description\": \"是药三分毒。\", \"voicelineId\": 82049, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_battle_skill3_01\", \"description\": \"病宜速救。\", \"voicelineId\": 82050, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_battle_skill3_02\", \"description\": \"须知惜命。\", \"voicelineId\": 82051, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_battle_skill3_03\", \"description\": \"且尝，苦尽甘来。\", \"voicelineId\": 82052, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_explore_sprint_start_01\", \"description\": \"咳…咳。\", \"voicelineId\": 82053, \"voicelineType\": \"700001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_chest_open_01\", \"description\": \"长生：捣鼓了半天是为了这个啊。\\n白术：长生…\", \"voicelineId\": 82054, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_chest_open_02\", \"description\": \"冒险生活不容易啊。\", \"voicelineId\": 82055, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_chest_open_03\", \"description\": \"回头擦擦手吧，这箱子我怕不够干净。\", \"voicelineId\": 82056, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_life_less30_01\", \"description\": \"…我还能撑。\", \"voicelineId\": 82057, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_life_less30_02\", \"description\": \"长生：不妙不妙！\", \"voicelineId\": 82058, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_life_less30_03\", \"description\": \"我不能…先倒下。\", \"voicelineId\": 82059, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_life_less30_teammate_01\", \"description\": \"不可冒进。\", \"voicelineId\": 82060, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_life_less30_teammate_02\", \"description\": \"留心伤口…\", \"voicelineId\": 82061, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_life_die_01\", \"description\": \"人死灯灭…\", \"voicelineId\": 82062, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_life_die_02\", \"description\": \"长生，抱歉…\", \"voicelineId\": 82063, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_life_die_03\", \"description\": \"愧为医者啊…\", \"voicelineId\": 82064, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_battle_hit_L_02\", \"description\": \"啧，眼镜。\", \"voicelineId\": 82065, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_baizhu/vo_baizhu_battle_hit_H_01\", \"description\": \"这点痛，哼。\", \"voicelineId\": 82066, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_baizhu_teamJoin_01\", \"description\": \"伤口由我处理。\", \"voicelineId\": 82067, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_baizhu_teamJoin_02\", \"description\": \"这就出诊。\", \"voicelineId\": 82068, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_baizhu_teamJoin_03\", \"description\": \"希望别走太远…\", \"voicelineId\": 82069, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000083, 'Lynette', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_draw_appear_01\", \"description\": \"初次见面，我是林尼的魔术助手，工作事宜请咨询林尼。观看演出请咨询售票处。找我？…请长话短说。\", \"voicelineId\": 83000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·喝茶\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_character_idle_01\", \"description\": \"茶泡好了，接下来可以休息一会儿了。\", \"voicelineId\": 83001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·哥哥\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_character_idle_02\", \"description\": \"林尼好像又在说什么奇怪的话了…真让人放心不下。\", \"voicelineId\": 83002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·发呆\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_character_idle_03\", \"description\": \"进入待机模式…希望不要有人来打扰我。\", \"voicelineId\": 83003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_weather_heavyRain_01\", \"description\": \"雨天适合发呆…\", \"voicelineId\": 83004, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_weather_afterRain_01\", \"description\": \"这就天晴了，可惜。\", \"voicelineId\": 83005, \"voicelineType\": \"1202\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_weather_thunder_01\", \"description\": \"唔…耳朵疼。\", \"voicelineId\": 83006, \"voicelineType\": \"1203\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_weather_snowy_01\", \"description\": \"冷…把你藏到帽子里吧。\", \"voicelineId\": 83007, \"voicelineType\": \"1204\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_weather_sunny_01\", \"description\": \"太阳底下没有新鲜事…真是这样吗？\", \"voicelineId\": 83008, \"voicelineType\": \"1205\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_weather_gale_01\", \"description\": \"风里传来的气息…不，没什么。\", \"voicelineId\": 83009, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_greetingMorning\", \"description\": \"早安…充能尚未完成，即将再次休眠。\", \"voicelineId\": 83010, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_greetingNoon\", \"description\": \"我习惯工作之前喝一杯茶，能转换心情，也能保持清醒。\", \"voicelineId\": 83011, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_greetingNight\", \"description\": \"太阳下山之后，人们内心潜藏的欲望，就会浮上水面…我是说，晚上的演出会很精彩。要给你留票吗？\", \"voicelineId\": 83012, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_greetingNight2\", \"description\": \"快睡吧，我还要处理白天没做完的事情…（还要把弄坏的吸尘器修好。）\", \"voicelineId\": 83013, \"voicelineType\": \"1004\"}, {\"title\": \"关于琳妮特自己·魔术\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_idle\", \"description\": \"表演的时候，我一般担任林尼的助手，因为一直不说话也不做表情，有人以为我是魔术人偶…这种误解能避免不必要的交际，倒也不错。\", \"voicelineId\": 83014, \"voicelineType\": \"2001\"}, {\"title\": \"关于琳妮特自己·情报\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_idle2\", \"description\": \"沉默有助于集中精神，看清有用情报。曾经来看演出的某位贵客，掏出了不属于他太太的手帕…至于情报的具体用途，嗯…就看那位大人的意思了。\", \"voicelineId\": 83015, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·倾听\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_close\", \"description\": \"我不习惯主动表达，但应该算是个不错的听众。如果有什么烦恼，就来找我吧。我会为你保密。\", \"voicelineId\": 83016, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·兴趣\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_close1\", \"description\": \"我曾经以为，金色的「太阳」和夜色的「暗影」，是无法互相理解的，可你身上有着奇特的复杂性，让我产生了不必要的好奇心…今后也让我继续观察你吧。\", \"voicelineId\": 83017, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_pendant\", \"description\": \"比起武力，我更喜欢用自己的眼睛掌握现状，找到合适的解决方法。不过，拥有力量就会拥有更多底牌，就能在危急情况下保护重要的人。\", \"voicelineId\": 83018, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_share_01\", \"description\": \"泡茶是一件看似简单实则费心的事情，茶叶的品质、茶水的温度、冲泡的次数，只有所有的变量都控制恰当，才能泡出味道最纯正的茶。要来一杯吗？\", \"voicelineId\": 83019, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_pref_gift_01\", \"description\": \"小动物们也会表达自己的情绪，如果仔细聆听的话就会知道它们现在的状态。对于小猫来说，「喵~」比起「喵喵喵！」，前者心情更好，这时候不管怎么摸它都不会逃走哦。\", \"voicelineId\": 83020, \"voicelineType\": \"3003\"}, {\"title\": \"关于林尼·默契\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_lyney_01\", \"description\": \"我和林尼一直都待在一起，我们即使不开口也能明白对方的想法，所以单独相处时，他会比平时要安静。你问我他说的哪些是真话，哪些是假话？其实我都知道，但这是最高保密事项。\", \"voicelineId\": 83021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼·担忧\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_lyney_02\", \"description\": \"林尼平时总是自信不疑，做起事来游刃有余，或者说，他让所有人都以为他一直如此，所以在遇到麻烦的时候，他也总会想要一个人完美地解决…如果遇到这种情况，还请多多关照他吧。\", \"voicelineId\": 83022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲米尼…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_freminet_01\", \"description\": \"他是个细腻温柔的孩子，却有些喜欢妄自菲薄…或许是和之前的经历有关吧。有时候他给我的感觉就像是林尼的反面…既然两边都是我的家人，意见不合时，我会负责弥合分歧。\", \"voicelineId\": 83023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「父亲」…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_arlecchino_01\", \"description\": \"「父亲」表达爱意的方式…不一定能被每个人接受，但就是因为有「父亲」在，家…才得以为家。\", \"voicelineId\": 83024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_neuvillette_01\", \"description\": \"最高审判官总给我一种奇怪的疏离感，明明言行谈吐都很谦和…还是说，他也不怎么喜欢跟人打交道呢？不过他和美露莘们说话的时候，倒是很亲切。\", \"voicelineId\": 83025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_furina_01\", \"description\": \"芙宁娜大人的行为太难解读了，也观察不出什么有用的情报，总觉得她一举一动像是在扮演不同的人…不愧是神明，不能用普通人的角度来揣测。\", \"voicelineId\": 83026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于娜维娅…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_navia_01\", \"description\": \"虽然是「刺玫会」的新会长，作风却像邻居家爱管闲事的大姐姐呢。要是「家」里真有这么一位姐姐就好了…啊，这话好像不太合适…\", \"voicelineId\": 83027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_clorinde_01\", \"description\": \"我曾经奉命观摩过她的决斗，仅仅是从旁观察，就能感觉到令人害怕的寒意…真不知道在决斗场上直面她会是什么感觉…嗯，希望这辈子都不要知道。\", \"voicelineId\": 83028, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于千织…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_chiori_01\", \"description\": \"我跟林尼的演出服都是请她定制的。有一次林尼用小刀表演魔术，不小心划到了袖口，后来被她数落了好久…真可怕。幸好每次去她店里，都可以躲到林尼背后。\", \"voicelineId\": 83029, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_charlotte_01\", \"description\": \"呃…我后来也被她抓着采访过几次。明明被林尼拒绝了那么多次，真是毅力可嘉…可惜她准备了这么多问题，我一个也没回答。\", \"voicelineId\": 83030, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾梅莉埃…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_teammate_emilie_01\", \"description\": \"这位香水设计师小姐的作品热门到需要凌晨排队抢购。但我对香水的味道太敏感，打出喷嚏来就太失礼了…所以只能绕着走。\", \"voicelineId\": 83031, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解琳妮特·其一\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_friendship_01\", \"description\": \"如果要解释魔术，就会失去看表演的乐趣，人际关系也是这样，想了解我的话，不妨一点点收集信息，拼凑答案吧。\", \"voicelineId\": 83032, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解琳妮特·其二\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_friendship_02\", \"description\": \"人是很复杂的生物，即便不是有意欺瞒，也会不自觉地隐藏自己的真实一面。虽然我总能注意到一些「多余」的细节，但除非必要情况，我不会拆穿别人的伪装。\", \"voicelineId\": 83033, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解琳妮特·其三\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_friendship_03\", \"description\": \"魔术曾经是我和林尼的谋生手段，现在更多是一种便利的社会身份，以魔术表演的名义，我们就能融入这座城市，成为家的「眼睛」。\", \"voicelineId\": 83034, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解琳妮特·其四\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_friendship_04\", \"description\": \"在来到新家之前，我和林尼一直到处流浪，经历了许多艰难和危险的状况。从那时起，我便习惯时刻注意一切危险的迹象，也逐渐学会解读他人的所思所想。好在，如今我们拥有了一个安身之所。\", \"voicelineId\": 83035, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解琳妮特·其五\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_friendship_05\", \"description\": \"建立人际关系是一种赌局，无论掌握多少信息，都难以预测人心的变化。一直以来我习惯待在安全的距离，但如果是你的话…我愿意承担输掉的风险。\", \"voicelineId\": 83036, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"琳妮特的爱好…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_pref_hobby\", \"description\": \"人的精神和弓弦一样，如果一直绷得太紧，就会有断裂的风险。所以在工作之外，我会做一些能放松神经的事情，比如泡茶、喂猫、发呆。平时心情越是平静，就越能应对将来的危险。\", \"voicelineId\": 83037, \"voicelineType\": \"6001\"}, {\"title\": \"琳妮特的烦恼…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_dialog_annoyed_01\", \"description\": \"我不是很习惯操作机械，一旦不注意就会出现意外状况，有一次在雨天搞坏了烘干机…还好菲米尼很擅长修理东西。\", \"voicelineId\": 83038, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_pref_foodLike\", \"description\": \"撬开贝壳，在新鲜贝肉上挤点柠檬汁，连餐盘都不需要了。完美。\", \"voicelineId\": 83039, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_pref_foodDislike\", \"description\": \"调料过重的食物，不行。食材就是要保留原始的口味才好。\", \"voicelineId\": 83040, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_spice_pref_01\", \"description\": \"好吃，配方我已经记下来了。\", \"voicelineId\": 83041, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_spice_normal_01\", \"description\": \"谢谢招待。\", \"voicelineId\": 83042, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_spice_dislike_01\", \"description\": \"调料的比例，再斟酌一下吧？\", \"voicelineId\": 83043, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_pref_birthday_01\", \"description\": \"生日快乐！卡片给你…这不是贺卡，当然没写东西了。写下你想要的礼物，放进我的帽子里，不管是什么，都会为你准备的。\", \"voicelineId\": 83044, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_starUp_01\", \"description\": \"感知更敏锐了。\", \"voicelineId\": 83045, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_starUp_02\", \"description\": \"思考速度…继续上升。\", \"voicelineId\": 83046, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_starUp_03\", \"description\": \"看到了，胜利的条件。\", \"voicelineId\": 83047, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_lynette/vo_lynette_starUp_04\", \"description\": \"我竟然能获得这样的力量…这样我也能站在你的身前了吧。\", \"voicelineId\": 83048, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_battle_skill1_01\", \"description\": \"一点把戏。\", \"voicelineId\": 83049, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_battle_skill1_02\", \"description\": \"在这里。\", \"voicelineId\": 83050, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_battle_skill1_03\", \"description\": \"惊喜。\", \"voicelineId\": 83051, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_battle_skill3_01\", \"description\": \"魔术开场。\", \"voicelineId\": 83052, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_battle_skill3_02\", \"description\": \"来点灯光。\", \"voicelineId\": 83053, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_battle_skill3_03\", \"description\": \"请看这边。\", \"voicelineId\": 83054, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_chest_open_01\", \"description\": \"宝物的气息。\", \"voicelineId\": 83055, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_chest_open_02\", \"description\": \"不出所料。\", \"voicelineId\": 83056, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_chest_open_03\", \"description\": \"轻松到手。\", \"voicelineId\": 83057, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_life_less30_01\", \"description\": \"保持冷静。\", \"voicelineId\": 83058, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_life_less30_02\", \"description\": \"我得集中精神。\", \"voicelineId\": 83059, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_life_less30_03\", \"description\": \"启动应敌模式…\", \"voicelineId\": 83060, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_life_less30_teammate_01\", \"description\": \"快退后。\", \"voicelineId\": 83061, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_life_less30_teammate_02\", \"description\": \"我来吸引火力。\", \"voicelineId\": 83062, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_life_die_01\", \"description\": \"我…看漏了什么…\", \"voicelineId\": 83063, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_life_die_02\", \"description\": \"魔术失误了…\", \"voicelineId\": 83064, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_life_die_03\", \"description\": \"林尼…\", \"voicelineId\": 83065, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_battle_hit_L_01\", \"description\": \"还好。\", \"voicelineId\": 83066, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_lynette/vo_lynette_battle_hit_H_01\", \"description\": \"啊，没躲开。\", \"voicelineId\": 83067, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_lynette_teamJoin_01\", \"description\": \"魔术要开演了吗？\", \"voicelineId\": 83068, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_lynette_teamJoin_02\", \"description\": \"下午茶时间到了。\", \"voicelineId\": 83069, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_lynette_teamJoin_03\", \"description\": \"你带路吧。\", \"voicelineId\": 83070, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000084, 'Lyney', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_draw_appear_01\", \"description\": \"是我哟，全提瓦特最棒的大魔术师——林尼。惊喜吗？意外吗？想知道我是怎么出现在你面前的吗？嗯——你那双像黄宝石一般晶莹剔透的眼睛，让我很中意哦！让我再为你表演一次吧。看好了哦，这回，千万不要眨眼。\", \"voicelineId\": 84000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·分心\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_character_idle_01\", \"description\": \"大魔术师就在面前，还有心思东张西望吗？这样可就要错过最精彩的一幕咯！\", \"voicelineId\": 84001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·妹妹\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_character_idle_02\", \"description\": \"我亲爱的妹妹——琳妮特此刻在做什么呢？肯定想我想得不得了吧！\", \"voicelineId\": 84002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·眼见为实\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_character_idle_03\", \"description\": \"我希望观众们都相信「眼见为实」的道理，那我就能变出数不尽的戏法。\", \"voicelineId\": 84003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_weather_heavyRain_01\", \"description\": \"哎呀，这种天气，看来今晚没办法看到星星了。除非…我试着把星星变出来？\", \"voicelineId\": 84004, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_weather_afterRain_01\", \"description\": \"真幸运，天晴了，该不会天上有谁在变魔术吧？\", \"voicelineId\": 84005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_weather_snowy_01\", \"description\": \"啊嚏…呼…我听过一种说法，说打喷嚏是有人在想自己。琳妮特吗？哦——还是你呢？\", \"voicelineId\": 84006, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_weather_breezy_01\", \"description\": \"呼，好险。要是帽子被风吹跑的话，里面的道具就会哗啦啦砸在我脑袋上了。\", \"voicelineId\": 84007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_weather_gale_01\", \"description\": \"这风也太大了，我的纸牌都——等等，哎，别迷路啊！你的主人在这边！\", \"voicelineId\": 84008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_greetingMorning\", \"description\": \"…唔，再让我睡会儿…嗯？是你呀——嗯，我说怎么今天的阳光那么好，原来是你来了。\", \"voicelineId\": 84009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_greetingNoon\", \"description\": \"下午我需要检查一下魔术用品，构思新的魔术创意。你要一起来吗？来嘛，别推脱啦！你可以试着喂喂我的动物助手们，我想你们一定合得来。\", \"voicelineId\": 84010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_greetingNight\", \"description\": \"晚上好。今晚有大魔术师的演出，你肯定没忘吧？\", \"voicelineId\": 84011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_greetingNight2\", \"description\": \"晚安。要是睡不着的话，我有些催眠小道具可以用…啊，还是算了吧。睡吧，愿美梦陪你到天亮。\", \"voicelineId\": 84012, \"voicelineType\": \"1004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼自己·嘴甜\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_idle\", \"description\": \"对了，有件事情，我必须强调一下。我可不是对所有人都这样说话的哦，主要还是因为对象是你。\", \"voicelineId\": 84013, \"voicelineType\": \"2001\"}, {\"title\": \"关于林尼自己·搭档\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_idle2\", \"description\": \"啊——琳妮特不在，我要进入待机模式了。虽然一个人也能处理好身边的事，但还是会有些不习惯。你能理解的吧？毕竟你也…我是说，毕竟派蒙总陪着你。\", \"voicelineId\": 84014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·隐瞒\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_close\", \"description\": \"哇，好尖锐的话题…这么说吧，甜美的浆果通常出没于荆棘丛生之地，不然就会被馋嘴的狐狸一口吃完…这都是为了保护自己呀！好吧，我承认我确实不介意偶尔对别人撒点小谎，但我们之间最多只能算是有所隐瞒吧？不是吗？\", \"voicelineId\": 84015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·原则\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_close1\", \"description\": \"魔术师一般不会透露魔术的核心秘密…但如果你愿意喊我「林尼老师」，成为我的学生，那么「原则」就产生了变化。也不知道你的领悟力和耐心到底能有几分呢？真让人期待。\", \"voicelineId\": 84016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_pendant\", \"description\": \"魔术师佩戴着神之眼上台，难免会遭到质疑，所以我习惯了提前摘下它。既然你有兴趣，要不下次我表演的时候，就由你帮我保管它吧？要看紧一点哦，可千万别让它又偷偷滑到我手上了。\", \"voicelineId\": 84017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_share_01\", \"description\": \"魔术不仅是一种表演形式，也是一种思维方式。世界上有很多看似平平无奇的东西，其中大有玄机。\", \"voicelineId\": 84018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_pref_gift_01\", \"description\": \"猫咪的耳朵能表达情绪，向后翻折说明恐惧或者警戒，向前竖起，偶尔朝外多半表明心情愉快，快速晃动则是在警觉地判断四周情况…多观察就有经验了。\", \"voicelineId\": 84019, \"voicelineType\": \"3003\"}, {\"title\": \"关于「父亲」·家\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_arlecchino_01\", \"description\": \"「父亲」给了我们一个家，教导我们成长，告诉我们每个人应该努力的方向。我能做的也很简单。保持忠诚之心，以及…守护我们的家。\", \"voicelineId\": 84020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「父亲」·王\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_arlecchino_02\", \"description\": \"在这座只有孩子们构成的王国里，「父亲」是我们的王。我知道国王早晚会选继承者，也知道那会是我…但同时，我对那样的情况感到恐惧…请不要告诉任何人，尤其是妹妹和菲米尼。\", \"voicelineId\": 84021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琳妮特·模式\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_lynette_01\", \"description\": \"你觉得妹妹她话很少？明白了，那是运行模式不对。下次，先对她说「激活，聊天模式」，运气好的话，她会和你说上很长一段话。你问运气不好要怎么办？别担心呀，就算被她瞪几眼，你也见到了和平时不一样的琳妮特！\", \"voicelineId\": 84022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琳妮特·双子\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_lynette_02\", \"description\": \"我和妹妹从小到大都在一起，艰难的时光只要有彼此就能度过，开心的时候也会和对方共享。家人，就是我们最宝贵的归宿。我们都能理解你与家人分别的痛苦…如果发现了任何线索，一定会告诉你的。\", \"voicelineId\": 84023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲米尼…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_freminet_01\", \"description\": \"我这位天真的弟弟，至今还相信童话故事。真让人有些羡慕。哦，这不是他自己告诉我的，是有次我不小心看到了他锁在秘密抽屉里的东西…真的是不小心哦！所以还请你不要告诉他，不然他肯定会生我气的。\", \"voicelineId\": 84024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_neuvillette_01\", \"description\": \"那维莱特先生很少公开露面，似乎刻意和人们保持着距离。一开始我还以为是我的错觉，但观察最最敏锐的琳妮特也有同感，那看来确实是这样了。\", \"voicelineId\": 84025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_furina_01\", \"description\": \"水神芙宁娜大人的行事作风不可捉摸，说得更露骨些，她平时说话也像是一种表演。枫丹人对精彩的舞台演出情有独钟，因此崇敬她的人也有不少。\", \"voicelineId\": 84026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于千织…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_chiori_01\", \"description\": \"恭维话在她那里是行不通的，只有真正懂得欣赏的人，才能让她另眼相待。你问她怎么看我？这问题可让我有些伤心哦，我可是既懂欣赏，又对大家真心相待的人呀。\", \"voicelineId\": 84027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于娜维娅…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_navia_01\", \"description\": \"没想到她在不认识我的情况下愿意出手相助。要是没有你们的话，我和琳妮特肯定无法脱身…总之，非常感谢你们。就请让我等待一个阳光灿烂的日子，邀请大家去露泽咖啡厅吃最美味的茶点吧。\", \"voicelineId\": 84028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_charlotte_01\", \"description\": \"自从那次见面之后，夏洛蒂小姐多次邀请我接受专访，呃…好像快有个二十次了吧。她对新闻有种与生俱来的敏锐，个性还异常执着。但说老实话，我可不想成为她笔下「爆炸性新闻」的主角，只好一次又一次用不同的理由婉拒了。\", \"voicelineId\": 84029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_clorinde_01\", \"description\": \"作为决斗代理人，克洛琳德小姐颇有名望。但我最近在报纸上看到，她似乎麻烦缠身…媒体非常喜欢挖掘她的故事，至于她本人…应该相当厌恶这种行为吧。\", \"voicelineId\": 84030, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾梅莉埃…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_teammate_emilie_01\", \"description\": \"你闻过她设计的香水吗？我还挺喜欢的，原本想买一瓶试试…但琳妮特的尾巴似乎有不同的意见。那我也只好算喽。\", \"voicelineId\": 84031, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解林尼·其一\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_friendship_01\", \"description\": \"看来我们彼此都对对方很感兴趣呢，我的荣幸！哈哈，放心吧，只要看到你那令人着迷的眼睛，我就舍不得对你撒谎。\", \"voicelineId\": 84032, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解林尼·其二\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_friendship_02\", \"description\": \"魔术表演当然没办法保证永远不出现纰漏。对我而言，演出的重点也不是百分之百避免穿帮，而是时时刻刻保持镇定，随机应变。就算露出了小破绽，只要能让观众相信那也是表演的一环，依旧能成为一场精彩难忘的演出。\", \"voicelineId\": 84033, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解林尼·其三\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_friendship_03\", \"description\": \"没有父母遮风挡雨，从小流落街头的孤儿，总要经历比常人更多的磨难。但正因为那些事情，才造就了如今的我和琳妮特。现在，我们都过得不错…「家人」、观众…我的帽子里装着很多很多人的期待呢！\", \"voicelineId\": 84034, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解林尼·其四\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_friendship_04\", \"description\": \"哈哈，到现在还没办法完全相信我说的话吗？看来你警惕心很强，这是好事，我就不用担心你被别人骗了。另外嘛，你可要负起责任来，盯着我，谨慎挑选眨眼时机…不然的话，趁你不注意，我就去撒弥天大谎咯！到时候你也脱不开干系。\", \"voicelineId\": 84035, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解林尼·其五\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_friendship_05\", \"description\": \"「真实」的我，并没有我所表现出得那么外向、健谈。更多时候，我是为了跟大家拉近关系，才使用了语言上的「魔术」…你会同情原本的我吗？还是会觉得这种戏法…很愚蠢呢。\", \"voicelineId\": 84036, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"林尼的爱好…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_pref_hobby\", \"description\": \"嘿，看这儿——可爱的小白兔，喜欢吗？好奇它是什么时候来到这里的吗？那就对了！观众脸上惊喜的表情，正是每一位魔术师的最爱。\", \"voicelineId\": 84037, \"voicelineType\": \"6001\"}, {\"title\": \"林尼的烦恼·掩饰\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_annoyed_01\", \"description\": \"怎么办呢？我最大的烦恼就是——你在我这样的大魔术师面前，还能想到烦心的事情。\", \"voicelineId\": 84038, \"voicelineType\": \"6012\"}, {\"title\": \"林尼的烦恼·鸽子\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_dialog_annoyed_02\", \"description\": \"过去，我总是放养我的鸽子，它们也总会飞回我的身边。后来有一次，回家的鸽子少了几只，等我们循着痕迹找到的时候，它们已经变成了鸽子派。至今我也不知道，我要怎样同时带给它们「自由」和「安全」。\", \"voicelineId\": 84039, \"voicelineType\": \"6011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_pref_foodLike\", \"description\": \"看到这个鱼缸了吗？来，你可以把手伸进去感受一下，是不是真的只有水。确认好了吗？那就开始咯！看这块布，现在盖上去了…嘿呀，鱼变出来咯！怎么样？这精彩的表演，能换一道你亲手制作的鱼肉菜肴吗？\", \"voicelineId\": 84040, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_pref_foodDislike\", \"description\": \"出于表演需要，我和琳妮特得保持身形相似，我们会尽量不吃油炸食品。我倒是无所谓，妹妹就比较辛苦了——街头的炸鱼实在很香嘛！\", \"voicelineId\": 84041, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_spice_pref_01\", \"description\": \"能吃到你亲手制作的美味，真是荣幸之至。\", \"voicelineId\": 84042, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_spice_normal_01\", \"description\": \"你的厨艺不错嘛，很好吃哦！多谢款待。\", \"voicelineId\": 84043, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_spice_dislike_01\", \"description\": \"想看魔术吗？来吧，看我把布盖在上面，你跟着我一起念——三、二、一！食物消失咯！\", \"voicelineId\": 84044, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_pref_birthday_01\", \"description\": \"这里有一根羽毛，请伸出手来确认一下，它的确是一片普通的羽毛。好了吗？啪嚓——其实是礼花哦，生日快乐！看到了吗？礼花里飘下的一片彩纸，被我抓住了。在我点燃它的同时，你就可以许愿了，顺带想象一下你的生日礼物。三、二、一——嗯，很~好~我已经明白你的想法了。来吧，把手伸进我的帽子里——如何？这份礼物是你想要的吗？\", \"voicelineId\": 84045, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_starUp_01\", \"description\": \"哎呀，我还以为你想让我用这些素材变魔术呢。\", \"voicelineId\": 84046, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_starUp_02\", \"description\": \"要是什么变化都没有，会不会让你更加吃惊？\", \"voicelineId\": 84047, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_starUp_03\", \"description\": \"你愿意信任我，没有比这个更令我开心的事情了。\", \"voicelineId\": 84048, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_lyney/vo_lyney_starUp_04\", \"description\": \"为我付出这么多，是想要偷走我的心吗？那就让我恭喜你、祝贺你吧！我亲爱的学徒，或者说伙伴——你已经做到咯。\", \"voicelineId\": 84049, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_battle_skill1_01\", \"description\": \"一点小把戏。\", \"voicelineId\": 84050, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_battle_skill1_02\", \"description\": \"看看这个吧！\", \"voicelineId\": 84051, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_battle_skill1_03\", \"description\": \"惊喜连连。\", \"voicelineId\": 84052, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_battle_skill3_01\", \"description\": \"压轴表演！\", \"voicelineId\": 84053, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_battle_skill3_02\", \"description\": \"好戏开演！\", \"voicelineId\": 84054, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_battle_skill3_03\", \"description\": \"响起你的掌声！\", \"voicelineId\": 84055, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_chest_open_01\", \"description\": \"用这个道具，把它们全部变走…开玩笑的啦。\", \"voicelineId\": 84056, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_chest_open_02\", \"description\": \"装进魔术口袋里吧。\", \"voicelineId\": 84057, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_chest_open_03\", \"description\": \"这也算是一种宝箱魔术吗？\", \"voicelineId\": 84058, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_life_less30_01\", \"description\": \"这是要我表演诈死魔术吗？\", \"voicelineId\": 84059, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_life_less30_02\", \"description\": \"不错的戏法…\", \"voicelineId\": 84060, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_life_less30_03\", \"description\": \"不会有事的。\", \"voicelineId\": 84061, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_life_less30_teammate_01\", \"description\": \"可别忘了还有我啊！\", \"voicelineId\": 84062, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_life_less30_teammate_02\", \"description\": \"节奏已经乱了哦？\", \"voicelineId\": 84063, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_life_die_01\", \"description\": \"琳妮特…\", \"voicelineId\": 84064, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_life_die_02\", \"description\": \"我的表演，不会失败！…\", \"voicelineId\": 84065, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_life_die_03\", \"description\": \"幕布…快点拉上…\", \"voicelineId\": 84066, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_battle_hit_L_01\", \"description\": \"没事。\", \"voicelineId\": 84067, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_lyney/vo_lyney_battle_hit_H_02\", \"description\": \"冷静…\", \"voicelineId\": 84068, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_lyney_teamJoin_01\", \"description\": \"噢！「旅行魔术团」。\", \"voicelineId\": 84069, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_lyney_teamJoin_02\", \"description\": \"乐意效劳。\", \"voicelineId\": 84070, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_lyney_teamJoin_03\", \"description\": \"能被你邀请是我的荣幸。\", \"voicelineId\": 84071, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000085, 'Freminet', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_draw_appear_01\", \"description\": \"你好，我叫菲米尼，是一名潜水员…啊，握手的话就不必了…我是说，不用那么客气。咳、如果你需要勘测水下遗迹或者打捞素材的话，我能为你所用…但其他方面的指派，我可能会让你失望…\", \"voicelineId\": 85000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·海底\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_character_idle_01\", \"description\": \"想去无人的海底，一个人安静地待着…\", \"voicelineId\": 85001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·原理\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_character_idle_02\", \"description\": \"熟悉机械装置的构造与原理，就能够排查故障…但要熟悉一个人却难得多。\", \"voicelineId\": 85002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·家\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_character_idle_03\", \"description\": \"无论我在何处漂流，只要那盏炉火亮着，我就有家可归…\", \"voicelineId\": 85003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_weather_heavyRain_01\", \"description\": \"每到雨天，心情都会沉重不少…\", \"voicelineId\": 85004, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_weather_afterRain_01\", \"description\": \"雨停了吗？那就好。\", \"voicelineId\": 85005, \"voicelineType\": \"1202\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_weather_thunder_01\", \"description\": \"佩伊，我会保护你的。不要怕。\", \"voicelineId\": 85006, \"voicelineType\": \"1203\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_weather_snowy_01\", \"description\": \"我是不是应该把潜水头盔戴上…保暖…\", \"voicelineId\": 85007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_weather_gale_01\", \"description\": \"想钻进海里。\", \"voicelineId\": 85008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_greetingMorning\", \"description\": \"早。请问，有需要我执行的任务吗？没有的话，我准备出门了。\", \"voicelineId\": 85009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_greetingNoon\", \"description\": \"机械内部没有故障，是发条老化了吗？那修起来简单…抱歉，我…呃…你刚才和我说了什么吗？\", \"voicelineId\": 85010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_greetingNight\", \"description\": \"要来一碗海鲜汤吗？是用今天现捕的虾和贝类做的。我不怎么会做饭，但食材新鲜，味道…应该不会太差。\", \"voicelineId\": 85011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_greetingNight2\", \"description\": \"你休息吧。我还想看一会儿书再睡。欸？什么书？这个…唔，是有关潜、潜水的书，有很多技术要点要学…总之，先道晚安了！\", \"voicelineId\": 85012, \"voicelineType\": \"1004\"}, {\"title\": \"关于菲米尼自己·潜水\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_idle\", \"description\": \"如你所知，我为数不多的强项是潜水，我和汐藻打交道的时间比和人说话的时间还多。它们不会责问，不会流露失望，只安静地陪你一同漂流…水下的世界要比陆上简单许多。\", \"voicelineId\": 85013, \"voicelineType\": \"2001\"}, {\"title\": \"关于菲米尼自己·发条企鹅\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_idle2\", \"description\": \"在我感到孤独的夜晚，是佩伊给了我最珍贵的陪伴。我想，或许有其他孩子像我一样，需要一位陪在身边的玩具伙伴。于是，我做了一批发条企鹅，拿去莱舒的发条工坊寄售…听说口碑不错，但销量一般，来购买的反倒是成年人居多…唉。\", \"voicelineId\": 85014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·命令\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_close\", \"description\": \"「命令」就像是背在我身后的发条，离开它反而令我不习惯。如果有任何对我的安排，请你一定不要顾虑。\", \"voicelineId\": 85015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·同伴\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_close1\", \"description\": \"让我多了解一点你的事吧。你的爱好、口味，喜欢的颜色，想养的动物…既然你是我的「同伴」，那我们之间的联结，就比齿轮与机关更紧密了。\", \"voicelineId\": 85016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_pendant\", \"description\": \"自从有了「神之眼」，我潜水已经不再需要使用头盔。但我却离不开它。它将我与外界的嘈杂隔绝，让我感到安全。「神之眼」、头盔…还有佩伊，我的呼吸，一直在借助它们的力量。\", \"voicelineId\": 85017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_share_01\", \"description\": \"透过海水望天，阳光也不会那么刺眼。所以，我才总是愿意待在水里。\", \"voicelineId\": 85018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻·苍晶螺\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_pref_gift_01\", \"description\": \"我曾在水下见到过许多苍晶螺，盯着那些精致细巧的纹路，不知不觉就忘记了时间。这么美丽的生物已经变成了化石，那我们周围的景色，是不是早晚也会沉入深海之下呢？\", \"voicelineId\": 85019, \"voicelineType\": \"3003\"}, {\"title\": \"感兴趣的见闻·幽光星星\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_pref_gift_02\", \"description\": \"幽光星星总是会依附在其他东西之上，有时是礁石，有时是码头，更多时候则是庞大的水下建筑群。你说，它们是不是就像飞萤靠近光源那样，对人类心存向往呢？\", \"voicelineId\": 85020, \"voicelineType\": \"3004\"}, {\"title\": \"关于「父亲」·眼泪\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_arlecchino_01\", \"description\": \"「父亲」不喜欢孩子们哭，说眼泪是感性和软弱的混合物。被「父亲」训斥过后，我总要忍到水下才敢哭出来。还好海露花会陪着我。\", \"voicelineId\": 85021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「父亲」·教导\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_arlecchino_02\", \"description\": \"小时候，我受到的教育是：为了家，我们应该献出自己的生命。自从「父亲」掌权后，这一理念产生了变化。「父亲」说我们每一个人都很重要，必须得重视自己的生命，发挥所有力量，在这个世界上站稳脚跟…说实话，这比单纯服从命令难多了。\", \"voicelineId\": 85022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼·表演\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_lyney_01\", \"description\": \"在家里，林尼时常会向我表演一些小魔术。一旦我笑了的话，他就会特别开心，说那个魔术肯定会让观众都满意…我平时真的笑那么少吗？\", \"voicelineId\": 85023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼·面具\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_lyney_02\", \"description\": \"林尼是我们小队中的领袖，总是以哥哥的身份自居…我能看出他硬撑的时候，也尝试过劝他不要一直戴着面具…但他不肯承认，我们还起过争执…从那之后，我就不再触碰这个话题了。\", \"voicelineId\": 85024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琳妮特…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_lynette_01\", \"description\": \"同样的任务，如果交给林尼或者琳妮特，他们就能完成得很出色，而我却办不好。琳妮特总宽慰我说大家各有所长，家里那些突然出故障的器械都在靠我维修…哈，我在其他方面也能这么得心应手就好了。\", \"voicelineId\": 85025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_neuvillette_01\", \"description\": \"有次我浮出海面时，正巧见到最高审判官大人独自站在海边。他或许在想心事，或许在看风景…我当然没问。我只和他匆匆对了一眼就潜回海里了。事后想想像是做了亏心事一样…唉。\", \"voicelineId\": 85026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜·回避\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_furina_01\", \"description\": \"我…我没法客观地评价水神大人，还是…不说了吧。况且我和她接触得也不多…看法肯定会有偏颇。\", \"voicelineId\": 85027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜·判断\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_furina_02\", \"description\": \"好吧，我见过水神大人坐在观众席上的样子。在我看来，她说话的时候非常引人瞩目，沉默的时候反倒更耐人寻味…她的眼睛，就像不透光的海底那样，藏着深深的秘密，害怕他人的碰触…我、我乱说的…对不起。\", \"voicelineId\": 85028, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于娜维娅…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_navia_01\", \"description\": \"我听林尼聊了事情经过，很感谢你和娜维娅小姐的慷慨与热心，也请代我向她转达…欸？当面道谢？我、我有点…唔，肚子突然疼起来了，抱歉先走一步。\", \"voicelineId\": 85029, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_charlotte_01\", \"description\": \"不知道为什么，夏洛蒂小姐始终不愿相信我是一名普通的潜水员，反倒觉得我的身世藏有值得报道的「新闻」…是我说谎的时候不够自然吗？\", \"voicelineId\": 85030, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_clorinde_01\", \"description\": \"克洛琳德小姐对我有救命之恩，却说不需要我做任何「报答」。给别人添了麻烦，到头来只能空洞地道谢…这种感觉，真不好受啊。\", \"voicelineId\": 85031, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏沃蕾…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_teammate_chevreuse_01\", \"description\": \"听说夏沃蕾小姐常去博蒙特工坊，为火枪购置最昂贵精细的零件。我要是能挣到很多钱的话，说不定也能给佩伊换上性能更好的零件了吧。\", \"voicelineId\": 85032, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解菲米尼·其一\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_friendship_01\", \"description\": \"请原谅。我讲不出什么有趣的故事…说了也会扫你兴致…\", \"voicelineId\": 85033, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解菲米尼·其二\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_friendship_02\", \"description\": \"要是你答应不看着我，或者允许我戴上头盔的话…我可以试着说下去。心理素质是一方面…但更主要的原因，恐怕是我习惯了逃避自己的过去…\", \"voicelineId\": 85034, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解菲米尼·其三\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_friendship_03\", \"description\": \"书上说，人死后会化作天上的星辰，遥望人世…我讨厌自己的亲生父亲，他抛下了我和母亲，我不在乎他…但如果母亲在天上看见她用生命保护下来的孩子如此怯弱，躲在另一个屋檐下那么久，也没有成长为独当一面的样子，她会不会…对我感到失望呢？\", \"voicelineId\": 85035, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解菲米尼·其四\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_friendship_04\", \"description\": \"我不太想回忆前任院长管理时期的「家」。只能说…躲进海里的习惯，就是那时候养成的…但「父亲」不仅改变了我，也改变了我对「家」的看法…后来林尼和琳妮特也成为了我们的「家人」…那是我第一次遇到能交心的伙伴。\", \"voicelineId\": 85036, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解菲米尼·其五\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_friendship_05\", \"description\": \"我曾发誓，我会不惜一切地守护现在这个家，一丝一毫都不退让。它不再是前任院长的命令，或者「父亲」的期待…而是我自己的愿望。请你保守「家」的秘密…还有我的愿望。\", \"voicelineId\": 85037, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"菲米尼的爱好…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_pref_hobby\", \"description\": \"除了潜水之外，我还喜欢拆解和改造机械，有时也会把收集来的材料制作成新的发条玩具。佩伊？它更像是我的家人，和我一起长大…是真的。我一直在为它增添更多功能…真希望未来有一天，它能够自由地飞上高空。\", \"voicelineId\": 85038, \"voicelineType\": \"6001\"}, {\"title\": \"菲米尼的烦恼…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_dialog_annoyed_01\", \"description\": \"…真难回答啊。既可以说我没有亟待解决的问题，又可以说我身上麻烦重重。即使将我自己看作一台橱窗里的发条玩偶，我也想不出要从哪里开始维修…症结可能还是会落回…我太弱小了吧。\", \"voicelineId\": 85039, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_pref_foodLike\", \"description\": \"鱼、虾之类的海鲜…螃蟹也可以。我很高兴自己和林尼、琳妮特他们口味相近，大家能吃到一起去…在烹饪形式的选择上，我会尊重他们的意见。\", \"voicelineId\": 85040, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_pref_foodDislike\", \"description\": \"我不太能喝咖啡。一旦超过半杯，没过多久，心脏就会跳得很快，呼吸也没法恢复平稳。人们常说咖啡有提神的效用，但对我来说，它更像是一种折磨…\", \"voicelineId\": 85041, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_spice_pref_01\", \"description\": \"好吃。好吃到让人舍不得吃完。\", \"voicelineId\": 85042, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_spice_normal_01\", \"description\": \"烹饪是你的爱好吗？所以你才会不断投入心血，做出这些美味的菜肴。\", \"voicelineId\": 85043, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_spice_dislike_01\", \"description\": \"对不起，刚才我有一瞬间想要逃走。明明是你辛苦做出来的东西…\", \"voicelineId\": 85044, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_pref_birthday_01\", \"description\": \"你愿意跟我去个地方吗？我知道一片水域，景色特别漂亮，甚至比书里描绘的世界更加梦幻。我在那里有个秘密基地，还养了一些会发光的海洋生物…我想陪你度过一个不一样的生日，最后再说出那句祝福…能给我这个机会吗？\", \"voicelineId\": 85045, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_starUp_01\", \"description\": \"真的…可以吗？\", \"voicelineId\": 85046, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_starUp_02\", \"description\": \"即使不为我做这些，我也会服从你的。\", \"voicelineId\": 85047, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_starUp_03\", \"description\": \"你的时间和精力非常宝贵，拿去陪别人会更好…吧。\", \"voicelineId\": 85048, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_freminet/vo_freminet_starUp_04\", \"description\": \"我不知道如何才能报答你，要怎样表达才足够传递自己的想法…我…我平时练习太少，现在非常害怕会说错话…让你不开心，让你觉得后悔…对不起，我可以什么都不说，就在你身边待一会儿吗？\", \"voicelineId\": 85049, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_battle_skill1_01\", \"description\": \"佩伊！\", \"voicelineId\": 85050, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_battle_skill1_02\", \"description\": \"运转吧。\", \"voicelineId\": 85051, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_battle_skill1_03\", \"description\": \"寒潮将至。\", \"voicelineId\": 85052, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_battle_skill3_01\", \"description\": \"下潜…就绪。\", \"voicelineId\": 85053, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_battle_skill3_02\", \"description\": \"清剿…开始。\", \"voicelineId\": 85054, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_battle_skill3_03\", \"description\": \"该道别了。\", \"voicelineId\": 85055, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_chest_open_01\", \"description\": \"如果有你不需要的金属碎片或者零件，可以丢给我。\", \"voicelineId\": 85056, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_chest_open_02\", \"description\": \"好多宝藏。\", \"voicelineId\": 85057, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_chest_open_03\", \"description\": \"分类存放吧。\", \"voicelineId\": 85058, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_life_less30_01\", \"description\": \"区区疼痛而已。\", \"voicelineId\": 85059, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_life_less30_02\", \"description\": \"我还能承受…\", \"voicelineId\": 85060, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_life_less30_03\", \"description\": \"要恢复…呼吸节奏。\", \"voicelineId\": 85061, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_life_less30_teammate_01\", \"description\": \"你的伤口…\", \"voicelineId\": 85062, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_life_less30_teammate_02\", \"description\": \"你…要不要…\", \"voicelineId\": 85063, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_life_die_01\", \"description\": \"我还是…无处可归…\", \"voicelineId\": 85064, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_life_die_02\", \"description\": \"要沉入海底了吗？…\", \"voicelineId\": 85065, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_life_die_03\", \"description\": \"「父亲」…\", \"voicelineId\": 85066, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_battle_hit_H_01\", \"description\": \"不好…\", \"voicelineId\": 85067, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_freminet/vo_freminet_battle_hit_H_02\", \"description\": \"不要…\", \"voicelineId\": 85068, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_freminet_teamJoin_01\", \"description\": \"带我走吧。\", \"voicelineId\": 85069, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_freminet_teamJoin_02\", \"description\": \"命令我吧。\", \"voicelineId\": 85070, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_freminet_teamJoin_03\", \"description\": \"我还能去哪里呢…\", \"voicelineId\": 85071, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000086, 'Wriothesley', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_draw_appear_01\", \"description\": \"你好，请尽量简洁地说明你的来意。嗯？不是公事？那我反而更紧张了。\\n坐下详谈吧。顺便一提，你可以称呼我「公爵」，他们都是这么叫的，我也听习惯了。\", \"voicelineId\": 86000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·贴纸\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_character_idle_01\", \"description\": \"如果看到我背后粘着美露莘画的贴纸，帮我揭掉吧？\", \"voicelineId\": 86001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·宠物\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_character_idle_02\", \"description\": \"我曾经考虑过要不要在办公室里养宠物，但小猫小狗在不见阳光的地方生活太可怜了。还是算了吧。\", \"voicelineId\": 86002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·忠告\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_character_idle_03\", \"description\": \"不要违法。还有什么需要叮嘱的吗？哦对了，不要违法。\", \"voicelineId\": 86003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_weather_heavyRain_01\", \"description\": \"下雨了？还好。要是在梅洛彼得堡感到头顶滴水的话，问题可就大了。\", \"voicelineId\": 86004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_weather_thunder_01\", \"description\": \"心中无罪的人，在这种天气下也能安睡吧。\", \"voicelineId\": 86005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_weather_snowy_01\", \"description\": \"嗯…和水下的冷不太一样。\", \"voicelineId\": 86006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_weather_sunny_01\", \"description\": \"「太阳之下无新事」，但可以找个好地方野餐。\", \"voicelineId\": 86007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_greetingMorning\", \"description\": \"早。晨报上的天气预测怎么说？\", \"voicelineId\": 86008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_greetingNoon\", \"description\": \"现在特许食堂人正多，我叫人送餐到办公室来吧。\", \"voicelineId\": 86009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_greetingNight\", \"description\": \"都这个时间了？总觉得才刚刚喝过下午茶。\", \"voicelineId\": 86010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_greetingNight2\", \"description\": \"晚安。我要等会儿再睡，趁夜深人静正好算几笔账。\", \"voicelineId\": 86011, \"voicelineType\": \"1004\"}, {\"title\": \"关于莱欧斯利自己·误解\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_idle\", \"description\": \"他们不是把我想得太神秘，就是太全能了。我只有一双眼睛、一对耳朵，怎么可能照顾到梅洛彼得堡的每一个角落呢。\", \"voicelineId\": 86012, \"voicelineType\": \"2001\"}, {\"title\": \"关于莱欧斯利自己·小憩\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_idle2\", \"description\": \"我早已服完刑，现在是自由公民，当然可以来水上闲逛。\\n不必担忧。要是梅洛彼得堡必须要我一直待在下面才能稳定运转，那也太不健康了。\", \"voicelineId\": 86013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14006], \"unlockText\": \"完成「于怨嗟之地重生」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·收监\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_close\", \"description\": \"我对很多人的第一印象都是从收监登记表开始的，看来你也没能例外。\", \"voicelineId\": 86014, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·出狱\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_close1\", \"description\": \"都说没了利益牵扯才好做朋友，我们可以现在开始。\", \"voicelineId\": 86015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_pendant\", \"description\": \"我以前跟一些罪人学过借助化学药剂使用元素的方法。无论「神之眼」的发放归哪个部门管，他们似乎不是很介意这点僭越之举。\", \"voicelineId\": 86016, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_share_01\", \"description\": \"知道怎么做更容易逃脱警备队的抓捕吗？给自己起个又长又难记的名字，然后他们在大喊「那个谁，把手举起来！」时就会卡壳。\", \"voicelineId\": 86017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_pref_gift_01\", \"description\": \"「不劳动者不得食」，这句话很久以前就刷在梅洛彼得堡墙上了。我也不知道是谁安排的，在水下的确很实用。\", \"voicelineId\": 86018, \"voicelineType\": \"3003\"}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_teammate_neuvillette_01\", \"description\": \"记得有次被那维莱特叫去上面谈事情，走到沫芒宫门口正好看到他在路边淋雨。我替他打了伞，他礼貌地道了谢，表情却不大自然。我大概是打扰到了什么吧。\", \"voicelineId\": 86019, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_teammate_furina_01\", \"description\": \"可能是因为我认罪太快，芙宁娜小姐在当年的审判中看起来兴致索然，早早就退场了。让水神大人失望可是大事，只好今后多给她送些好茶了。\", \"voicelineId\": 86020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14006], \"unlockText\": \"完成「于怨嗟之地重生」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于希格雯…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_teammate_sigewinne_01\", \"description\": \"希格雯护士长具备一名医护人员所需的全部美德，并关心着身边每一位同伴。\\n不过她似乎从我身上学走了一些坏习惯，比如时常和她的美露莘朋友们打赌，看谁能偷偷在我的东西上贴更多贴纸。不，我并不觉得困扰。\", \"voicelineId\": 86021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_teammate_clorinde_01\", \"description\": \"克洛琳德应该是你能找到的最好的决斗代理人了，实力有目共睹。我从未和她比试过，没有那个必要。\", \"voicelineId\": 86022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_teammate_lyney_01\", \"description\": \"我承认，拔除「壁炉之家」安插在水下的眼线是种挑衅。而他们的回应是只派几个孩子下来，的确令我有些难办。是真心觉得他们也可以被牺牲，还是看准了我不会对小孩下狠手呢…唉。\", \"voicelineId\": 86023, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于娜维娅…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_teammate_navia_01\", \"description\": \"梅洛彼得堡和刺玫会有一些物资方面的合作，但仅限于此。并不是不信任娜维娅小姐或是质疑她的能力——实际上恰恰相反——只不过，我们之间水下水上的事务互不干涉是我与卡雷斯先生约好的规矩，维持不变就好。\", \"voicelineId\": 86024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾梅莉埃…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_teammate_emilie_01\", \"description\": \"梅洛彼得堡应该用不上她的服务，有些痕迹就是作为「前车之鉴」被留下来的。…气味也是痕迹的一种，不是吗？\", \"voicelineId\": 86025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏沃蕾…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_teammate_chevreuse_01\", \"description\": \"被特巡队关照过的犯人大多挺老实的，这位队长功不可没。\", \"voicelineId\": 86026, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莱欧斯利·其一\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_friendship_01\", \"description\": \"理论上来讲，完全不认识我的人会比较幸福。\", \"voicelineId\": 86027, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解莱欧斯利·其二\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_friendship_02\", \"description\": \"身上的疤痕？曾有深海巨兽企图占领梅洛彼得堡，我和它搏斗时被抓伤了。…当然是假的，不要信。\", \"voicelineId\": 86028, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莱欧斯利·其三\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_friendship_03\", \"description\": \"你知道吗，手铐只要型号相近，大部分都能用通用的钥匙打开。只有我这副不一样。\", \"voicelineId\": 86029, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莱欧斯利·其四\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_friendship_04\", \"description\": \"我的个人能力其实很有限。你看，我既不会治病，也不会搞发明，更不会造大船。我只是知道该去哪里找人做这些事，而他们恰好愿意卖我这个面子而已。\", \"voicelineId\": 86030, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解莱欧斯利·其五\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_friendship_05\", \"description\": \"我现在过上了还不错的生活，但也仍然羡慕一些我得不到的东西——比如安逸快乐的童年，和轻易信赖他人的能力。可能有人认为这很矛盾，或者难以启齿，我倒觉得没什么不好承认的——何必和自己的本心过不去呢？\", \"voicelineId\": 86031, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14006], \"unlockText\": \"完成「于怨嗟之地重生」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"莱欧斯利的爱好…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_pref_hobby\", \"description\": \"拳击？不算是爱好吧，只是生活所需。你有什么其他推荐吗？\", \"voicelineId\": 86032, \"voicelineType\": \"6001\"}, {\"title\": \"莱欧斯利的烦恼…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_dialog_annoyed_01\", \"description\": \"我确实有着枫丹人的长相，但没法百分之百肯定——只能跳胎海水确认咯？\", \"voicelineId\": 86033, \"voicelineType\": \"6012\", \"unlockConditions\": [{\"paramList\": [14006], \"unlockText\": \"完成「于怨嗟之地重生」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_pref_foodLike\", \"description\": \"喝咖啡时我习惯加奶，茶的话，两块糖就好了。\", \"voicelineId\": 86034, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_pref_foodDislike\", \"description\": \"你喝过护士长做的奶昔吗？能从中尝出…「荒芜」的味道。\", \"voicelineId\": 86035, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_spice_pref_01\", \"description\": \"完美的调味，我就不擅长这个。\", \"voicelineId\": 86036, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_spice_normal_01\", \"description\": \"好吃。下次换我请客。\", \"voicelineId\": 86037, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_spice_dislike_01\", \"description\": \"等我去泡杯茶。\", \"voicelineId\": 86038, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_pref_birthday_01\", \"description\": \"枫丹的孩子是伴随着双亲的心愿与祝福诞生的，不过我愿意相信这世上的每一个人都是如此。和这个比起来，我的祝愿就有些微不足道了。\\n不，如果你犯事的话我是没办法帮你减刑的，只能在今天给你安排一份特殊的福利餐。所以生日期间还是安分一点，保证我们可以在水上庆祝，好吗？\", \"voicelineId\": 86039, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_starUp_01\", \"description\": \"能获得你的信任，是我的荣幸。\", \"voicelineId\": 86040, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_starUp_02\", \"description\": \"这下必须还你一个人情了。\", \"voicelineId\": 86041, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_starUp_03\", \"description\": \"哈，你怎么看起来比我要得意？\", \"voicelineId\": 86042, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_wriothesley/vo_wriothesley_starUp_04\", \"description\": \"我喜欢力量和希望的信号，会让我感觉未来一切向好。这并非悲观，只是陈述事实，因为现实本就不可能一帆风顺。但有个好消息，就是当坏事发生时，我们可以站在同一阵线，对吧？\", \"voicelineId\": 86043, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_battle_skill1_01\", \"description\": \"开始吧。\", \"voicelineId\": 86044, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_battle_skill1_02\", \"description\": \"别跑啊。\", \"voicelineId\": 86045, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_battle_skill1_03\", \"description\": \"请留步。\", \"voicelineId\": 86046, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_battle_skill3_01\", \"description\": \"一路顺风。\", \"voicelineId\": 86047, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_battle_skill3_02\", \"description\": \"注意防寒。\", \"voicelineId\": 86048, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_battle_skill3_03\", \"description\": \"无需畏惧，直面罪责。\", \"voicelineId\": 86049, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_chest_open_01\", \"description\": \"没有锁吗？真方便啊。\", \"voicelineId\": 86050, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_chest_open_02\", \"description\": \"先收好吧，总能派上用场。\", \"voicelineId\": 86051, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_chest_open_03\", \"description\": \"无主之物最好归公…所以这里什么都没有，对吧？\", \"voicelineId\": 86052, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_life_less30_01\", \"description\": \"不慌。\", \"voicelineId\": 86053, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_life_less30_02\", \"description\": \"不叫增援？也行。\", \"voicelineId\": 86054, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_life_less30_03\", \"description\": \"见机行事。\", \"voicelineId\": 86055, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_life_less30_teammate_01\", \"description\": \"退后。\", \"voicelineId\": 86056, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_life_less30_teammate_02\", \"description\": \"去医务室。\", \"voicelineId\": 86057, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_life_die_01\", \"description\": \"抱歉，没能守住…\", \"voicelineId\": 86058, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_life_die_02\", \"description\": \"孤注一掷的后果…\", \"voicelineId\": 86059, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_life_die_03\", \"description\": \"我没有异议。\", \"voicelineId\": 86060, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_battle_hit_L_01\", \"description\": \"这么客气？\", \"voicelineId\": 86061, \"voicelineType\": \"900001\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_wriothesley/vo_wriothesley_battle_hit_H_02\", \"description\": \"…还可以。\", \"voicelineId\": 86062, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_wriothesley_teamJoin_01\", \"description\": \"开工。\", \"voicelineId\": 86063, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_wriothesley_teamJoin_02\", \"description\": \"请我出外勤？走。\", \"voicelineId\": 86064, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_wriothesley_teamJoin_03\", \"description\": \"我尽力，但不保证赢。\", \"voicelineId\": 86065, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000087, 'Neuvillette', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_draw_appear_01\", \"description\": \"您好，我是枫丹的最高审判官，称呼我的姓氏那维莱特就可以。并不是想要疏远您的意思，但太过亲近会被人怀疑司法体系的不公。\\n有什么诉求的话——当然，合法范围内——我们可以坐下来谈一谈，一起品尝一下翘英庄运来的水。\", \"voicelineId\": 87000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·审判\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_character_idle_01\", \"description\": \"我既认可我自身工作的价值，也认同枫丹大众所作所为的意义。我想，我还是会以我的责任为荣的。\", \"voicelineId\": 87001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·品水\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_character_idle_02\", \"description\": \"水的味道是很有讲究的。蒙德的水清冽，璃月的水回味悠长，稻妻的水口味幽邃深远，须弥的水味道虽然丰富但需要细品。\", \"voicelineId\": 87002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·美露莘\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_character_idle_03\", \"description\": \"美露莘是枫丹引以为傲的美丽生灵。你一定要和她们做好朋友，也不要伤害她们。\", \"voicelineId\": 87003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_weather_heavyRain_01\", \"description\": \"啊，抱歉。雨这么大，对你来说想必是个麻烦吧…\", \"voicelineId\": 87004, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_weather_afterRain_01\", \"description\": \"结束了…\", \"voicelineId\": 87005, \"voicelineType\": \"1202\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_weather_thunder_01\", \"description\": \"对你们来说，是不是有句话叫晴天霹雳？对我来说就是这个感觉。\", \"voicelineId\": 87006, \"voicelineType\": \"1203\", \"unlockConditions\": [{\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_weather_snowy_01\", \"description\": \"雪本身也是一种水的自洁手段。但是人类活动让雪不那么干净了，不要吃。\", \"voicelineId\": 87007, \"voicelineType\": \"1204\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_weather_sunny_01\", \"description\": \"这种天气最适合在室内窗边，嗯，欣赏阳光。\", \"voicelineId\": 87008, \"voicelineType\": \"1205\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_weather_desert_01\", \"description\": \"这是…您对我谋杀计划的一环吗？\", \"voicelineId\": 87009, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_greetingMorning\", \"description\": \"早上好。希望你今天过得愉快。\", \"voicelineId\": 87010, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_greetingNoon\", \"description\": \"午安。你一定很期待红茶或者咖啡的时间吧，我也是。\", \"voicelineId\": 87011, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_greetingNight\", \"description\": \"晚上好。希望今天你没有遇到什么难以释怀的坏事。\", \"voicelineId\": 87012, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_greetingNight2\", \"description\": \"晚安。对我来说平静的水面是美好的意象，所以我祝你今夜收获无梦的安眠。不要有任何梦的涟漪撩拨你的心绪。\", \"voicelineId\": 87013, \"voicelineType\": \"1004\"}, {\"title\": \"关于那维莱特自己·审判\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_idle\", \"description\": \"我又不是什么狂热的审判爱好者。「审判」只是我职责所在，是我被委任的目的。\", \"voicelineId\": 87014, \"voicelineType\": \"2001\"}, {\"title\": \"关于那维莱特自己·哭泣的水龙\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_idle2\", \"description\": \"你也听说过枫丹的这句民谣是吗？唉，这是谁教你的，又是谁让它流传开的…嗯，没什么。我觉得水龙不会哭，他只是品尝到了在大地之心里汇聚的泪水与所有的情绪，所以有所触动而已。\", \"voicelineId\": 87015, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特自己·审判的意义\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_idle3\", \"description\": \"这是一个说烂的话题了。并非我要把自己置身人类之外，但是你看，「正义」、「公平」、「平等」、「法律」，这几个概念互相之间其实无法等同。水天然有「如水之平」的本性。前代水神厄歌莉娅希望以爱来联系众生，实现平等。如今这位选择了平等的「法律」，最后却因为种种外因扭曲成了一切只为「审判」的遗憾结果。不过这也另有原因，不该谴责。\", \"voicelineId\": 87016, \"voicelineType\": \"2006\", \"unlockConditions\": [{\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·见证者\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_close\", \"description\": \"既然你是天地外之人，那就由你见证吧，我对于这个倒错世界的审判。「本应由天父统治的雄邦，如今王位上坐的却是雉鸡。时代已然错乱脱节，而我就是为了扭整乾坤而生」。\", \"voicelineId\": 87017, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·人间\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_close1\", \"description\": \"与枫丹人民长久的相处以及与你的同行早已让我改观。再加上我早已赦免了人的罪，我可以与你约定，接下来的审判不会危害到普通人。但是我与僭主尚有未结清的恩怨，还有未得偿还的血仇。\", \"voicelineId\": 87018, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·其一\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_pendant_01\", \"description\": \"曾经有人建议我佩戴一个假的玻璃珠，这样方便危急时刻出手。说实话这个提议让我很不愉快，行使自己的力量却要带着假的面具去伪装。不过和持有神之眼的人相处久了，也明白他们的渴望与意志也是如此难能可贵。\", \"voicelineId\": 87019, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」·其二\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_pendant_02\", \"description\": \"什么，你说最古老的七神有几个也得带着假玻璃珠行走在人间吗？噗。对不起失态了，这件事有些好笑。\", \"voicelineId\": 87020, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·法律\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_share_01\", \"description\": \"枫丹确实有很多奇妙的法律，比如「每个月前三天不能放飞飞行物」、「枯水期搁浅的双壳贝类都属于水神，螺贝则属于人民」、「禁止给家养动物取名『芙宁娜』」、「禁止在食堂与餐厅单吃番茄酱」、「对美露莘称呼必须使用人格意味的『她』，不能用『它』」…最后一条是我推动立法的。\", \"voicelineId\": 87021, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·雨天\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_share_02\", \"description\": \"时常在想，什么时候可以走入一场雨中。啊，你误会了，并不是压力太大。\", \"voicelineId\": 87022, \"voicelineType\": \"3005\"}, {\"title\": \"感兴趣的见闻·龙蜥\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_pref_gift_01\", \"description\": \"正是因它们同为原海所出之嫡系，所以对于进化之事十分擅长。我想起曾经龙中的风俗：我们啜饮一口早夭族类的血。当月与星的运行搅扰潮汐，我们水族体内的水也向上行去，我们便知道逝去的族人正在复活。\", \"voicelineId\": 87023, \"voicelineType\": \"3003\", \"unlockConditions\": [{\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"感兴趣的见闻·人类\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_pref_gift_02\", \"description\": \"就我的观察而言，人习惯将自己与自然对立。此时总会有人出来呼吁人也是自然的一部分。但在知道些许真相的我看来，人类的文明世界和这个星球的自然，应该算是需要寻求共处之道吧。\", \"voicelineId\": 87024, \"voicelineType\": \"3004\"}, {\"title\": \"关于岩之神…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_teammate_zhongli_01\", \"description\": \"我将对诸神行使裁决，没有任何事情可以改变这点。贵金之神赢取了岩之大权，他自然也在受审者之列。如果有谁不希望看到我们发生争执，也不必担心，我还需要在枫丹停留很久，说不定就要四百多年呢。而且最后的判决也不一定会导致兵戎相见。\", \"voicelineId\": 87025, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于风之神…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_teammate_venti_01\", \"description\": \"纵使天地翻覆，也无法停止我对于僭位七神的巡游审判。微风与希望之神获赠了风之大权，他也需要列席候审。你说他大部分时间都只是个醉汉，没有什么危险的了？那也得先见见吧。\", \"voicelineId\": 87026, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷之神…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_teammate_raidenShogun_01\", \"description\": \"我作为重获全龙之格的孑遗，就算是让大海所有的水逆行回天，也需要履行我的誓言与责任。鸣神赢取了雷之大权，注定留名于僭权者之列。嗯，你说她现在蛰居于心成净土之中，极少现身？那我过几百年再去吧。\", \"voicelineId\": 87027, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于草之神…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_teammate_nahida_01\", \"description\": \"即便将来会有审判她的一天，我也认可草木之神的责任感。世间难有完美的人与事，可专注和溺爱也证明了一个责任者不断前行。听说她曾遭到约五百年的冷遇，我很为她的经历遗憾。\", \"voicelineId\": 87028, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱欧斯利…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_teammate_wriothesley_01\", \"description\": \"莱欧斯利确实是一个值得信赖的人。他的头衔和名誉都是我给他争取的。是不是觉得我被他的话术和向上经营欺骗了？稻妻有句话叫「不说即是花」。\", \"voicelineId\": 87029, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_teammate_clorinde_01\", \"description\": \"克洛琳德凭借其超群实力成为了现任决斗代理人中的实力巅峰。她是逐影猎人这一行业的后继者，有她在，审判庭的公正更有保障。另外她会比外观看上去更有人情味一些。\", \"voicelineId\": 87030, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼和琳妮特…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_teammate_lyney&lynette_01\", \"description\": \"很有意思的演出，不是吗？这就是林尼和琳妮特的魔术世界，一切都假得出奇，但是只要你愿意相信，一切都可以成真。\", \"voicelineId\": 87031, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于希格雯…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_teammate_sigewinne_01\", \"description\": \"希格雯不知道过得好不好。要是她受欺负了我一定要把莱欧斯利喊进城里质问。她是那么脆弱，又那么的善良。上次她回来还给我带了留影机底片，还说想要听我继续点评纳塔的水…距离她下一个假期还要多久？\", \"voicelineId\": 87032, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_teammate_furina_01\", \"description\": \"时至今日，她的「演出」终于落幕。「表演」是想象的产物，但芙宁娜却凭此完成了自己的职责…怯懦之人用疯癫让自己勇敢，一直以来辛苦她了。\\n有机会的话，应当为她的舞台献上掌声…嗯，一旦有机会的话。\", \"voicelineId\": 87033, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于娜维娅…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_teammate_navia_01\", \"description\": \"虽然这么说很对不起她，但无论是当时无意的触怒她、接受她的道歉还是我此时感受到的内疚，全部有种疏离的感觉，仿佛沉卧湖底看星星。我并不是有意的，我也知道很难有机会弥补。情绪并不像是水，能迅速地修复自己，恢复平静。\", \"voicelineId\": 87034, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解那维莱特·其一\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_friendship_01\", \"description\": \"我会尽量避免与他人有私交以及有流程外的协作。不过阁下的品行值得信任，与枫丹的势力也没有什么纠缠。很乐意与你同行。\", \"voicelineId\": 87035, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解那维莱特·其二\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_friendship_02\", \"description\": \"这话只能私下说，公共场合我绝对无法做此表态。枫达这个东西，能流行起来对我来说有点莫名其妙。不过人们很喜欢它也不是不能理解：你看，一边喝水一边补充糖分，而且它还价格低廉。\", \"voicelineId\": 87036, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解那维莱特·其三\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_friendship_03\", \"description\": \"最近看过一出戏剧。一个已经逝去的夫人凭借个人魅力与恶意的安排，如同无法驱散的鬼魅一般笼罩着她已不在其中的豪宅。演员无可挑剔，故事也很精巧，而且让我想到了世界的现状。\", \"voicelineId\": 87037, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解那维莱特·其四\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_friendship_04\", \"description\": \"出于某些原因，我离开枫丹的次数屈指可数，因此，我所品尝的名泉虽是来自世界各地，但都是从外地送来，而非我亲临当地。至于不同饮用水里面的细微味道，我自然能够区分出来。言已至此，还不相信我吗？我是最高审判官，不骗人。\", \"voicelineId\": 87038, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解那维莱特·其五\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_friendship_05\", \"description\": \"不得不说，我时常遇到一些令人无奈的事，例如坐下的时候踩到衣摆，偶尔压到头发，往后靠头部也可能被座椅装饰品卡住。为了维持最高审判官的威严，我保持这类装束，自然要忍受它带来的麻烦。世间几乎也遵循着如此的道理——接受一种身份，忍耐它，理解它，与它共存。这正是我一直在做的。\", \"voicelineId\": 87039, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"那维莱特的爱好…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_pref_hobby\", \"description\": \"品水是一门学问。用火元素加热的水味道就是自然界最标准的味道，而木炭烧开的水则有田园的味道。同理，冰元素处理的水是一种平淡无奇的清冽，但是至冬积冰所化之水就完全不一样。\", \"voicelineId\": 87040, \"voicelineType\": \"6001\"}, {\"title\": \"那维莱特的烦恼…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_dialog_annoyed_01\", \"description\": \"下雨天不打伞是不是看起来有些奇怪…\", \"voicelineId\": 87041, \"voicelineType\": \"6012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_pref_foodLike\", \"description\": \"动物不进食尚能活些时日，不喝水可活不了几天。什么美食都比不过纯净的水。所以汤水多的食物就是第二好的。\", \"voicelineId\": 87042, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_pref_foodDislike\", \"description\": \"油炸或者无酱烤制的食物真的能吃吗？我想点名批评须弥椰炭饼，往人胃里塞干燥剂也不过如此。\", \"voicelineId\": 87043, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_spice_pref_01\", \"description\": \"美味。菜肴最重要的汁水不仅很多，而且处理得很好。\", \"voicelineId\": 87044, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_spice_normal_01\", \"description\": \"不错的尝试。只不过这道菜是不是可以多加点汤汁，再滤一点油脂出来。\", \"voicelineId\": 87045, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_spice_dislike_01\", \"description\": \"太干了。没有汁水的菜品尝不出厨师的心情。\", \"voicelineId\": 87046, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_pref_birthday_01\", \"description\": \"今天是你的生日啊，祝你生日快乐。不知道今天下不下雨，我会想想办法的。\", \"voicelineId\": 87047, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_starUp_01\", \"description\": \"稍微熟悉些了。我可以配合你的动作。\", \"voicelineId\": 87048, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_starUp_02\", \"description\": \"看来需要拿出些真的本事了。没想到你这么容易身处险境。\", \"voicelineId\": 87049, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_starUp_03\", \"description\": \"你的真正实力居然有如此地步吗？看来我不认真的话还无法跟上你了。\", \"voicelineId\": 87050, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_neuvillette/vo_neuvillette_starUp_04\", \"description\": \"从僭位者那里回收了七之大权一角，这才是我本来的身姿。我已是「完全之龙」，足以审判其余众神。我的命运将是审判高天的僭位之王。但在那之前，我就将力量借与你吧。\", \"voicelineId\": 87051, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_battle_skill1_01\", \"description\": \"肃静！\", \"voicelineId\": 87052, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_battle_skill1_02\", \"description\": \"低头。\", \"voicelineId\": 87053, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_battle_skill1_03\", \"description\": \"不得喧哗。\", \"voicelineId\": 87054, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_battle_skill3_01\", \"description\": \"潮水啊，我已归来。\", \"voicelineId\": 87055, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_battle_skill3_02\", \"description\": \"化作，浮沫吧。\", \"voicelineId\": 87056, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_battle_skill3_03\", \"description\": \"凡高大者，我无不蔑视。\", \"voicelineId\": 87057, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_chest_open_01\", \"description\": \"当你第一个找到无主的它时，它就属于你了。嗯，合法的。\", \"voicelineId\": 87058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_chest_open_02\", \"description\": \"是不错的东西吗？至少打开它那一瞬的期待是不错的心绪吧。\", \"voicelineId\": 87059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_chest_open_03\", \"description\": \"我以口头约定的方式将这些让渡与你。\", \"voicelineId\": 87060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_life_less30_01\", \"description\": \"并无妨害，不必担心。\", \"voicelineId\": 87061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_life_less30_02\", \"description\": \"风险渐涨，不过我没什么问题。\", \"voicelineId\": 87062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_life_less30_03\", \"description\": \"哼，衣服似乎刮坏了。\", \"voicelineId\": 87063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_life_less30_teammate_01\", \"description\": \"让我来吧。\", \"voicelineId\": 87064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_life_less30_teammate_02\", \"description\": \"你先休息一下。\", \"voicelineId\": 87065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_life_die_01\", \"description\": \"潮汐再起时，我必将归来…\", \"voicelineId\": 87066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_life_die_02\", \"description\": \"看到了…我诞生前的温暖之海…\", \"voicelineId\": 87067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_life_die_03\", \"description\": \"万籁…俱静…\", \"voicelineId\": 87068, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_battle_hit_H_01\", \"description\": \"角度意外啊…\", \"voicelineId\": 87069, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_neuvillette/vo_neuvillette_battle_hit_H_02\", \"description\": \"是我疏忽了。\", \"voicelineId\": 87070, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_neuvillette_teamJoin_01\", \"description\": \"感谢你许可…嗯，邀请我同行。\", \"voicelineId\": 87071, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_neuvillette_teamJoin_02\", \"description\": \"十分乐意。\", \"voicelineId\": 87072, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_neuvillette_teamJoin_03\", \"description\": \"一起走走吧，去水畔之类的地方。\", \"voicelineId\": 87073, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000088, 'Charlotte', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_draw_appear_01\", \"description\": \"初次见面，我是《蒸汽鸟报》记者夏洛蒂，很高兴见到你。有空的话，你愿意接受我的专项访谈吗？记者的直觉告诉我，你的身上能挖掘出不少爆炸性新闻。\", \"voicelineId\": 88000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·新闻\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_character_idle_01\", \"description\": \"只要眼睛够尖，脑子够快，每天都能找到好新闻。\", \"voicelineId\": 88001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·记者\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_character_idle_02\", \"description\": \"枫丹廷里有许多记者，但并不是每一位都拥有合格的职业素质。如果你想接受采访的话，最好还是来找我喔。\", \"voicelineId\": 88002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·蒸汽鸟报\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_character_idle_03\", \"description\": \"《蒸汽鸟报》是一家优秀的报社，有一位开明的主编和许多出色的记者。最重要的是，稿费也结得非常迅速。\", \"voicelineId\": 88003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_weather_heavyRain_01\", \"description\": \"留影机镜头可不能进水！\", \"voicelineId\": 88004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_weather_thunder_01\", \"description\": \"欸！可惜，又没抓拍到闪电…\", \"voicelineId\": 88005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_weather_snowy_01\", \"description\": \"…真是够冷的，手指都摁不动快门了。\", \"voicelineId\": 88006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_weather_sunny_01\", \"description\": \"哇，这光线真不错！来，快摆个姿势，我给你拍张画片！\", \"voicelineId\": 88007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_greetingMorning\", \"description\": \"早上好，今天的报纸看了吗？没有？那我念给你听。\", \"voicelineId\": 88008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_greetingNoon\", \"description\": \"是午饭时间了呀，我知道一家餐厅很不错，跟我来吧。\", \"voicelineId\": 88009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_greetingNight\", \"description\": \"晚上最适合谈心了，你有什么故事愿意和我分享吗？放心，我们事先说好能不能登报，我一定遵守约定。\", \"voicelineId\": 88010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_greetingNight2\", \"description\": \"晚安，赶紧休息吧。我还要去报社校对稿件，明天见啦。\", \"voicelineId\": 88011, \"voicelineType\": \"1004\"}, {\"title\": \"关于夏洛蒂自己·职业\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_idle\", \"description\": \"记者并不是一个讨人喜欢的职业。毕竟就像那句话说的：「谎言处处圆滑，真相棱角分明。」\", \"voicelineId\": 88012, \"voicelineType\": \"2001\"}, {\"title\": \"关于夏洛蒂自己·留影\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_idle2\", \"description\": \"只有在拍摄有趣的东西时，我才能拍出一张好画片。对于某些无聊透顶的留影对象…我能摁下快门，就已经足够有耐心了。\", \"voicelineId\": 88013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·长篇专题\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_close\", \"description\": \"嗨，准备好接受专访，成为最耀眼的大明星了吗？来，听我指挥，先摆一个好看的姿势…派蒙也飞得好看一点！\", \"voicelineId\": 88014, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·扉页人物\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_close1\", \"description\": \"好消息！我已经说服了欧芙小姐，下一刊《蒸汽鸟报》的「扉页人物」就是你们了，而且还会搭配本记者亲自撰写的专题报道。欸…不用了？我可是求了欧芙小姐好久啊！再考虑一下吧？我…我可以再请你们吃一顿大餐！\", \"voicelineId\": 88015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_pendant_01\", \"description\": \"说到这个…其实我更想要一枚「风元素」神之眼的呢。那样的话，也许我就能借助风飞来飞去，轻松地去各地采访了。但这枚「冰元素」的神之眼也不错，至少我不用担心留影机内部机关过热的问题了。\", \"voicelineId\": 88016, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_share_01\", \"description\": \"真实至上，故事超群。这就是我的工作原则，欸？哪一个是重点？那当然是「真实性」啦，「故事性」只是一种帮助读者们理解新闻的辅助手段。唉，但据我观察…比起「真相」，读者更愿意为「故事」付钱啦。\", \"voicelineId\": 88017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_pref_gift_01\", \"description\": \"为你介绍，我最好的伙伴和助手，独一无二的留影机「温亨廷先生」。瞧瞧他的帽子和领带，都是我专门找千织小姐订做的，是不是特别好看？我还给他订做了好几套不同风格的服饰，以应对不同的采访场合呢。\", \"voicelineId\": 88018, \"voicelineType\": \"3003\"}, {\"title\": \"关于娜维娅…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_teammate_navia_01\", \"description\": \"娜维娅的父亲沉冤得雪，「少女连环失踪案」也结了案，她总算可以稍微放下点心了。真不知道为什么，她最近总是成为各种坏新闻的主角，还好我把报社里所有关于她的报道都揽了过来，尽量控制着稿件内容。\\n虽然…因为这件事我也被欧芙小姐训了很多次，但为了帮上她，还有和她约好的那篇深度独家访谈，我挨点骂也值得了！\", \"voicelineId\": 88019, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_teammate_lyney_01\", \"description\": \"好吧，林尼先生又拒绝了我一次。这是第几次了来着…没关系！林尼先生越是拒绝我，我就越能确定，他的身上藏着某些富有巨大价值的故事，这个故事的爆炸性一定是前所未有的。我一定要挖掘出来！\", \"voicelineId\": 88020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琳妮特…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_teammate_lynette_01\", \"description\": \"无论被问的是什么问题，琳妮特小姐都只是安安静静地垂下眼眸，脸上没有任何表情，就像一个…一个发条人偶。我真想写一篇报道，就叫做《魔术的诀窍——天才魔术师的「人偶助手」》！但我觉得，她就算看见这篇报道也不会有任何反应…\", \"voicelineId\": 88021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_teammate_clorinde_01\", \"description\": \"克洛琳德小姐可是枫丹廷里最著名，也最神秘的「决斗代理人」，我从私人渠道打听到，她会用一些神秘的仪式维护自己的武器。也许这就是她在决斗中常胜不败的关键？可她曾公开表示过不想接受记者的采访…我应该没法当面问她这个问题了。\", \"voicelineId\": 88022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱欧斯利…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_teammate_wriothesley_01\", \"description\": \"最近有见到那位「公爵」吗？有没有帮我留意和他有关的信息呀？特许券、特许食堂…「不劳动者不得食」…这种大路消息就算了，有没有关于「公爵」个人的故事？什么，保密…怎么连你的口风也那么紧！把我的那顿大餐还来！哼，骗子！你干脆回去接着服刑啦！\", \"voicelineId\": 88023, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾梅莉埃…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_teammate_emilie_01\", \"description\": \"艾梅莉埃小姐的香水是整个枫丹廷里最好的！前两天她还向我推荐一款兼具驱虫、快速止汗、遮蔽汗水味的香水呢，这款香水对我这种经常出外勤的人可太重要了。我今天还喷了一些在手腕上…喏，你闻闻，可香了。\", \"voicelineId\": 88024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于千织…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_teammate_chiori_01\", \"description\": \"我曾经仔细观察过「千织屋」。店里除了枫丹贵妇人和慕名而至的外国游客之外，还经常会来一些看起来就不好惹的角色！有的一身肌肉、脸上留疤，有的蒙面戴帽、怀里揣刀…但不管怎样，他们手上几乎都提着礼物样式的东西，态度也毕恭毕敬。呃…那些态度不好的，出门时都是飞出来的，我还抓拍过那样的瞬间呢！\", \"voicelineId\": 88025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲米尼…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_teammate_freminet_01\", \"description\": \"在那之后，我和菲米尼又见了几次面。他对我的留影机助手「温亨廷先生」很感兴趣，还帮我改良了镜头。说实话…他三两下就把「温亨廷先生」拆解成零件的时候，我的心可是提到了嗓子眼…没想到他安装的手法也一样干净、娴熟。我差点都以为他是枫丹科学院出来的了，但他否认了。\", \"voicelineId\": 88026, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_teammate_neuvillette_01\", \"description\": \"如果有记者要去采访「最高审判官」的话，得提前定好所有采访问题，并且把这些问题送去给沫芒宫里的有关部门审定，只有通过审定的问题才能出现在采访中…以此保证整场采访不会出现任何问题。这样的流程实在是太繁琐了，光是想到这些我就精疲力尽了。\", \"voicelineId\": 88027, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_teammate_furina_01\", \"description\": \"水神芙宁娜大人的言行举止都十分富有感染力，是一个天生的大明星。欧芙小姐之前还指派了一位记者专门去跟访她呢，但是他没过多久就辞职了。\\n至于辞职的原因…据我打听到的消息，是因为这位记者每拍一张画片，都要拿去给芙宁娜大人看，如果她不满意就得重拍。最夸张的一次，这位老兄对着芙宁娜大人的一个姿势整整重拍了一百二十七次…\", \"voicelineId\": 88028, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夏洛蒂·其一\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_friendship_01\", \"description\": \"我很清楚地知道，追寻「真相」这种行为伴随着风险啦，不过，一个「独家真相」也意味着一篇「独家新闻」，我可不会放过…咳！我的意思是，我可不会放过这个…这个履行记者职责的大好机会。我一定要将最真实、最有力、最有趣的独家新闻报道带给所有人！\", \"voicelineId\": 88029, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解夏洛蒂·其二\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_friendship_02\", \"description\": \"刚做记者的时候，我对写报道文章一窍不通，只能通过阅读其他报道来学习。除了《蒸汽鸟报》之外，还有一些在小范围印发的私人刊物。比如专门报道枫丹廷内各种明星八卦的《观窥者报》、持续关注各种娱乐活动和赛事的《娱乐家周刊》、评论美食的《主厨》、只会胡说八道和造谣传谣的《惊奇！》等等。\\n这些报纸都给了我很大的启发，让我学会了…嗯，驾驭许多不同的行文风格。\", \"voicelineId\": 88030, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夏洛蒂·其三\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_friendship_03\", \"description\": \"为了揭示真相，我曾经假扮成游民，混进了一家伪劣食品商的后厨做了六个月的杂工，在搜集到足够的第一手资料后，我就将他们干的事都写成报道，登在了报纸上。\\n报道的反响十分强烈，那家伪劣食品商也受到了惩罚，但他们的报复也随之而来，我每天回家时床头柜上都放着一封恐吓信，报社的门口也总是被人泼泥巴…\\n报社很快报了警，而我则被指派去蒙德做「七圣召唤」报道，过了好一阵子才回枫丹。\\n唉，这样的事发生了很多次，真不知道欧芙小姐是怎么把它们全摆平的…\", \"voicelineId\": 88031, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夏洛蒂·其四\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_friendship_04\", \"description\": \"在小时候，我还没入记者这行的时候，我的好奇心特别重，总觉得万事万物后都隐藏着秘密。\\n对我来说，这个世界是一片巨大的藏宝地，藏匿着无数不为人知的故事等待发掘。每当遇见那些我觉得藏匿有秘密的事物，就会拿出留影机拍下一张画片，放在我的画片集里。\\n这些画片都是只属于我的「藏宝图」…而我也一直不断用各种方法解读着它们，试图揭示出隐藏在画片中的「真相」。\", \"voicelineId\": 88032, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夏洛蒂·其五\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_friendship_05\", \"description\": \"我不在意这些「真相」究竟有什么价值、代表着什么、或者说和什么事有关…我只是想要将它们揭示出来。如果用冒险家的说法，我应该是属于那种…专注于享受寻宝过程的人吧，至于最后究竟能寻到什么宝，我倒是不怎么执着啦。\\n在求证的过程中，我认识了许多人。枫丹的朋友们，认为我天生就是做记者的料的欧芙小姐，还有陪我一起探寻和见证「真相」的你。没有大家的帮助，我恐怕还是那个只会到处拍照的野丫头吧。\\n总之…我很高兴能接受你的「特殊采访」。\", \"voicelineId\": 88033, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"夏洛蒂的爱好…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_pref_hobby\", \"description\": \"我最喜欢收藏各种各样的留影机镜头了。有些镜头有着超高的缩放焦距，有些镜头的视野非常广阔。对了，还有一些镜头有着特别功能，拍出来的画片会带着各种特别效果，你看这个镜头，用它拍摄人像的话，会把人的脸拍得胖乎乎的。来！我给你拍一张，派蒙也来！\", \"voicelineId\": 88034, \"voicelineType\": \"6001\"}, {\"title\": \"夏洛蒂的烦恼…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_dialog_annoyed_01\", \"description\": \"也许是因为我有时提问的态度会有些…激烈，导致一部分人对我的印象不太好。我每次去采访的时候，大家都是一副防备我的样子…唉，但对于某些采访对象，我必须得用这种态度来提问啊。\", \"voicelineId\": 88035, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_pref_foodLike\", \"description\": \"嘿嘿，我最喜欢甜甜的东西了。无论正餐吃多少东西，都能继续吃甜点。用我妈妈的话来说就是…我的胃里永远给甜点留着空呢。\", \"voicelineId\": 88036, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_pref_foodDislike\", \"description\": \"我吃不了辣的东西。我的胃里就像是装着一部超敏感的辣味监测机关一样，无论辣味有多淡，只要我敢吃，它就敢痛…而且一痛就是一整天，呜…\", \"voicelineId\": 88037, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_spice_pref_01\", \"description\": \"哇，你的手艺真好！要不要在报纸上做一个厨艺专栏？我都想好排版和构图了。\", \"voicelineId\": 88038, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_spice_normal_01\", \"description\": \"味道不错呀，有空的话…下次也教教我吧？\", \"voicelineId\": 88039, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_spice_dislike_01\", \"description\": \"唉…这道菜的味道…还有品尝这道菜的我，都足够上新闻了…\", \"voicelineId\": 88040, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_pref_birthday_01\", \"description\": \"生日快乐！你读了今天的《蒸汽鸟报》吗？我对你的生日祝福已经登载在上面啦。欸…你没买吗？没关系，我离开报社的时候顺手拿了一份，你瞧瞧，就在这里，这是我能争取到的最好版面啦。\", \"voicelineId\": 88041, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_starUp_01\", \"description\": \"这感觉真奇妙，得记录下来。\", \"voicelineId\": 88042, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_starUp_02\", \"description\": \"这些东西居然真能助人成长？我之前只是听说，没想到今天能亲身体验。\", \"voicelineId\": 88043, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_starUp_03\", \"description\": \"你之前也用这种方式帮过其他人吗？所用的材料有什么不同？还有…呃，不好意思，又犯职业病了。\", \"voicelineId\": 88044, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_charlotte/vo_charlotte_starUp_04\", \"description\": \"喔！我能感觉到，思考的速度变快了，身体里也全是劲…我一定能抓住更多独家新闻！但在那之前，我们先合张影吧，给这个美好时刻留下点纪念。\", \"voicelineId\": 88045, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_battle_skill1_01\", \"description\": \"看镜头！\", \"voicelineId\": 88046, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_battle_skill1_02\", \"description\": \"笑一个。\", \"voicelineId\": 88047, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_battle_skill1_03\", \"description\": \"摆个好姿势！\", \"voicelineId\": 88048, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_battle_skill3_01\", \"description\": \"真实至上！\", \"voicelineId\": 88049, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_battle_skill3_02\", \"description\": \"爆炸新闻！\", \"voicelineId\": 88050, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_battle_skill3_03\", \"description\": \"夏洛蒂，为您报道！\", \"voicelineId\": 88051, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_chest_open_01\", \"description\": \"喔！看上去不错。\", \"voicelineId\": 88052, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_chest_open_02\", \"description\": \"真想采访一下把箱子放在这里的人。\", \"voicelineId\": 88053, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_chest_open_03\", \"description\": \"这些东西应该不在失物招领列表上吧？\", \"voicelineId\": 88054, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_life_less30_01\", \"description\": \"我、我还能记录…\", \"voicelineId\": 88055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_life_less30_02\", \"description\": \"还有新闻要报道！\", \"voicelineId\": 88056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_life_less30_03\", \"description\": \"留影机还能用！\", \"voicelineId\": 88057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_life_less30_teammate_01\", \"description\": \"小心点！\", \"voicelineId\": 88058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_life_less30_teammate_02\", \"description\": \"喂！我可不想写讣告！\", \"voicelineId\": 88059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_life_die_01\", \"description\": \"把报道…带回报社…\", \"voicelineId\": 88060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_life_die_02\", \"description\": \"至少…记录下来了…\", \"voicelineId\": 88061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_life_die_03\", \"description\": \"标题，还没想…\", \"voicelineId\": 88062, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_battle_hit_L_02\", \"description\": \"真不礼貌。\", \"voicelineId\": 88063, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_charlotte/vo_charlotte_battle_hit_H_02\", \"description\": \"我的镜头！\", \"voicelineId\": 88064, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_charlotte_teamJoin_01\", \"description\": \"采访开始喽！\", \"voicelineId\": 88065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_charlotte_teamJoin_02\", \"description\": \"有什么新闻吗？\", \"voicelineId\": 88066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_charlotte_teamJoin_03\", \"description\": \"靠得越近，报道越真实。\", \"voicelineId\": 88067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000089, 'Furina', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_draw_appear_01\", \"description\": \"呆站在那里做什么？该不会是因为过于激动，说不出话了吧？没错，站在你面前的就是枫丹人人皆知的大明星——芙宁娜哦。我的档期可是很紧的，能约到我，说明你运气不错嘛。\", \"voicelineId\": 89000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·茶会\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_character_idle_01\", \"description\": \"茶会是淑女的必修课。如果你想学习茶会礼仪的话，我可以教你喔。\", \"voicelineId\": 89001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·乐子\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_character_idle_02\", \"description\": \"好无聊啊，没有什么更有趣的事吗？\", \"voicelineId\": 89002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·人气\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_character_idle_03\", \"description\": \"唉，人气太高也是一种苦恼，谁让我这么受欢迎呢？\", \"voicelineId\": 89003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_weather_heavyRain_01\", \"description\": \"好大的雨！等等，水应该不会淹上来吧？\", \"voicelineId\": 89004, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_weather_snowy_01\", \"description\": \"哇哦，这地方很适合映影取景。\", \"voicelineId\": 89005, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_weather_sunny_01\", \"description\": \"这阳光的热度，都快赶上我平时用的影室灯了。还好太阳只有一个。\", \"voicelineId\": 89006, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_weather_gale_01\", \"description\": \"「听，风中传来不安的低语，那是被遗忘的海兽做噩梦时的梦呓。」你问为什么是做噩梦？呃…因为，恐惧感是会向外传递的？\", \"voicelineId\": 89007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_weather_desert_01\", \"description\": \"真是一派荒芜的景象，让我赐予你们水的恩泽吧！\", \"voicelineId\": 89008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_greetingMorning\", \"description\": \"早安…需要起这么早吗？再多睡一会儿也没关系吧…\", \"voicelineId\": 89009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_greetingNoon\", \"description\": \"午安！我的蛋糕在哪里？什么什么，你说早上刚吃过？那已经隔了好——久啦！\", \"voicelineId\": 89010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_greetingNight\", \"description\": \"晚上好。唉，谢贝蕾妲小姐最近总嘀咕着减肥，还说要拉上我一起。哼，比起上个月我肚子都瘦了一圈还不止呢，我已经很努力在控制体态了。喂，你，看得出来么？\", \"voicelineId\": 89011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_greetingNight2\", \"description\": \"呼…正好我也困了。明天见，记得准时叫我起来…\", \"voicelineId\": 89012, \"voicelineType\": \"1004\"}, {\"title\": \"关于芙宁娜自己·亲友团\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_idle\", \"description\": \"你问我参加茶会的这几个小家伙？它们可是我忠实的追随者，咳，今天就破例为你介绍一下吧！这位是谢贝蕾妲小姐，最可爱的女仆，虽然有时会不小心剪坏我的衣服；这位是海薇玛夫人，可靠的管理人，将我的生活打理得井井有条；最后这位喜欢说教的是乌瑟勋爵，负责一切礼仪相关的事情。呵呵，虽然我已允许你参加我的茶会，但想要得到它们的认可，你还要多多努力才行！\", \"voicelineId\": 89013, \"voicelineType\": \"2001\"}, {\"title\": \"关于芙宁娜自己·歌唱\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_idle2\", \"description\": \"我对自己的歌唱水平还是很有自信的，不过值得我开口唱诵的段落可不多。希望那些剧团里的创作者们加把劲，不要让我等太久。\", \"voicelineId\": 89014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·关系\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_close\", \"description\": \"咳。以我们之间的关系，你在我面前无需太过恭敬，可以更随意一些。等等，你那是什么表情，该不会是想说你从一开始就没有「敬仰」过我吧？\", \"voicelineId\": 89015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·同行\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_close1\", \"description\": \"「我」的故事已然落幕，接下来开场的是「我们」的故事了…这么说的话，出场费是不是也该翻倍啦？好开心哦！\", \"voicelineId\": 89016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14012], \"unlockText\": \"完成「水的女儿」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_pendant_01\", \"description\": \"当那古老的预言终结、一切落幕之后，我曾经陷入很长时间的消沉。站在舞台上的人受到观众的追捧，同时也承受着更多的注视与期待。但我很清楚，他们期待的并不是我，而是我扮演的那位「神明」…在这个过程中，我真正得到的只有孤独。所以我一度厌恶任何跟表演有关的事，把自己关在房间里，直到再次站上舞台、再次面对观众的时候，我才发现不知不觉我内心的不安已经消失了。现在的我可以坦然承受他们的目光，也许是因为…我终于开始「扮演」我自己了。\", \"voicelineId\": 89017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14012], \"unlockText\": \"完成「水的女儿」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·歌剧\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_share_01\", \"description\": \"枫丹的歌剧经历过几次革新，每次革新都会有许多反对的声音。在我印象里，经常有很多人聚在歌剧院吵来吵去，吵得我耳朵嗡嗡响。于是我吓唬他们说，「不准再争论这些无关紧要的问题」，那维莱特也顺势敲了一下他的手杖，歌剧院立刻就安静了。没办法，我总会不经意间表露出充满威严的一面，希望他们能够理解。\", \"voicelineId\": 89018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻·幽光星星\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_pref_gift_01\", \"description\": \"我很喜欢幽光星星，这种生物在无人注视的地方也能发出自己的光亮，是我心目中最真实的「明星」。如果有让幽光星星当主角的歌剧就好了，我可以真情实感地在舞台上演绎一只可爱的离群海星。\", \"voicelineId\": 89019, \"voicelineType\": \"3003\"}, {\"title\": \"关于林尼与琳妮特…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_teammate_lyney&lynette_01\", \"description\": \"林尼与琳妮特我当然知道，以前我就经常光临他们的演出。他们的人气虽然高，但跟我比起来还是差了不少，有我出场的演出才是真正的座无虚席，连站票都卖得干干净净。至于现在…呃…现在我已经退隐了，人气下滑也很正常嘛！\", \"voicelineId\": 89020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_teammate_neuvillette_01\", \"description\": \"我很感谢那维莱特这几百年间为枫丹的辛苦付出，他似乎也不打算追究我欺骗民众的罪责。反正现在我们已经不需要对接什么工作，我也很久没去沫芒宫了，这对我们双方来说都是一件好事吧？\", \"voicelineId\": 89021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于娜维娅·甜点\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_teammate_navia_01\", \"description\": \"你尝过娜维娅烤的马卡龙吗？不得不承认，她对甜点的造诣已经非常深厚，完全不在我之下。口感和甜度暂且不提，她画在马卡龙上的图案也太可爱了吧？简直就是艺术品！她到底是怎么做到的，难道真的只是天赋？我的内心中竟然会产生一种挫败感…下次一定要向她好好打听一下！\", \"voicelineId\": 89022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于娜维娅·内心\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_teammate_navia_02\", \"description\": \"她是一个很坚强的人。坚强的人不管发生什么都会很快振作起来，装作没事的样子，这样身边的人就无需背负额外的压力。我见证过卡雷斯与克洛琳德的决斗，娜维娅她…在这方面越来越像自己的父亲了。\", \"voicelineId\": 89023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「仆人」…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_teammate_arlecchino_01\", \"description\": \"「仆人」？谁，谁呀？我已经忘掉了哦，把那么可怕的身影留在脑海中，晚上睡觉都会做噩梦的。\", \"voicelineId\": 89024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_teammate_charlotte_01\", \"description\": \"最近经常见到夏洛蒂忙忙碌碌的身影。她好像很想找我约一期独家专访。哪怕我多次拒绝，她也并不放弃。我本来有点生气的，但是她很坚定地对我说——她希望民众能够了解到一个更加真实的我，也相信民众可以理解我的苦衷。我不知道该如何回应她的好意，也许她说的有道理，但我还没有做好准备…\", \"voicelineId\": 89025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱欧斯利…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_teammate_wriothesley_01\", \"description\": \"我跟他交流不多，那维莱特说他值得信赖，所以我想他大概是个好人吧！哦对了，以前还收到过他寄来的茶，味道不错。\", \"voicelineId\": 89026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_teammate_clorinde_01\", \"description\": \"在我印象里，克洛琳德平时不喜交谈。但她几次站在我的身旁，保护我的安全，我对她非常信任。嗯…我还真有一点想念她，不过现在没什么去见她的理由了。对了！下次邀请她来一起开茶会吧！\", \"voicelineId\": 89027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解芙宁娜·其一\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_friendship_01\", \"description\": \"对我的事感兴趣？唉，真没办法，毕竟我曾经也是枫丹最受关注的大明星嘛！每天都有无数记者挖空心思想要探听我的隐私，我可是有丰富的经验将他们拒之门外。当然，我并不打算将这些经验用在你的身上，你可以用足够好吃的点心来和我交换秘密。\", \"voicelineId\": 89028, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解芙宁娜·其二\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_friendship_02\", \"description\": \"最近有人向我推荐了「冲浪」这项运动，我也去体验了一番。在惊涛骇浪中保持平衡并不是一件容易的事情，但我很快就掌握了技巧。也许是因为我有这方面的天赋？总之在海天相接的地方近距离地感受风与浪是一件还不错的事情，你也可以试一试。\", \"voicelineId\": 89029, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解芙宁娜·其三\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_friendship_03\", \"description\": \"有空的话，多和我讲讲旅行的见闻吧？我挺喜欢听你讲那些稀奇古怪的故事。怎么说呢…我很容易对各种事物产生兴趣，但用不了多久就会感到无聊。或许「热情」这种东西，越容易产生就越容易失去。跟你在一起时，我似乎能一直保持愉快的心情，真不可思议。\", \"voicelineId\": 89030, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解芙宁娜·其四\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_friendship_04\", \"description\": \"最近我一直在想，过去我是不是有点亏待自己了？为了保持神明的矜持，几乎没有享受过生活。所以最近我迷上了购物，买了好多新奇的宝贝。像什么七色炫彩茶包、全自动伸缩刀叉、海马专用马鞍…最后发现大部分东西都用不上，我全部送去剧团当演出道具了。奇怪，付款前我明明觉得这些很有用的…\", \"voicelineId\": 89031, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14012], \"unlockText\": \"完成「水的女儿」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解芙宁娜·其五\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_friendship_05\", \"description\": \"人们很喜欢谈论过去，为那些逝去的美好感到惋惜；也很喜欢谈论未来，仿佛为了缥缈的明天可以牺牲一切。我并不认同他们的做法，但也感到非常羡慕：因为我曾经生活在既没有过去、也没有未来的世界里。为了应对那种恐慌，我尝试塑造并扮演了一个更坚强、更像神明的自己，几百年的时间过去，我曾扮演的「形象」逐渐与真实的自己融为一体。如今连我也无法分辨…或许也没有分辨的必要了，过去的种种经历组成了现在的我，那场并不完美的演出也是我最重要的一部分啊。\", \"voicelineId\": 89032, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"芙宁娜的爱好…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_pref_hobby\", \"description\": \"《王后的荣冠》还没有出续作吗？真遗憾，这种正义战胜邪恶的经典作品总是让人百看不厌。\", \"voicelineId\": 89033, \"voicelineType\": \"6001\"}, {\"title\": \"芙宁娜的烦恼…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_dialog_annoyed_01\", \"description\": \"今晚的通心粉选什么酱好呢…\", \"voicelineId\": 89034, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_pref_foodLike\", \"description\": \"每个人都不会讨厌精致的糕点，但想要做到让我「喜欢」的程度，还需要多多努力才行。听好了，甜品就像歌剧，从「选角」到「布景」都需要花费心思，才能在最后的「演出」中大放异彩！\", \"voicelineId\": 89035, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_pref_foodDislike\", \"description\": \"简单来说，我讨厌大部分「创意菜」。这些年我品尝过许多奇妙的料理，除了给我留下心理阴影外毫无用处。\", \"voicelineId\": 89036, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_spice_pref_01\", \"description\": \"哦？香味浓郁、口感细腻…没想到你对烹饪也有研究，很有品味嘛。\", \"voicelineId\": 89037, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_spice_normal_01\", \"description\": \"太「普通」了！哼，这种缺乏特色的料理得不到我的认可！\", \"voicelineId\": 89038, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_spice_dislike_01\", \"description\": \"你平时只吃这些吗？唉，我的通心粉分你一些好了。\", \"voicelineId\": 89039, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_pref_birthday_01\", \"description\": \"生日快乐！喏，作为生日礼物，这张票给你。这可是《欢乐日》的头等座哦，记得过来看。你问我《欢乐日》是什么？唉，本来还想留一点惊喜的…这是我亲自排练的一场歌剧，内容嘛，是很多人聚集在一起，为某个重要的人做庆贺。这么说你应该明白了吧？一定要来啊！\", \"voicelineId\": 89040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_starUp_01\", \"description\": \"神之眼用起来还真不太习惯。你来教教我吧？呃…差点忘了，你也没用过神之眼啊。\", \"voicelineId\": 89041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_starUp_02\", \"description\": \"靠自己锻炼得到的力量果然很充实。哼哼，多谢了。\", \"voicelineId\": 89042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_starUp_03\", \"description\": \"渐入佳境！不愧是我，在任何情况下都能展现出闪耀的一面。\", \"voicelineId\": 89043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_furina/vo_furina_starUp_04\", \"description\": \"没想到你会对我的事这么上心，这是否意味着你仍然需要我的「力量」呢？然而如今的我…或许无法给你足够的回报…你说看重的是我「本人」？既然这样，就让你我共同出演我们的未来吧。\", \"voicelineId\": 89044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_skill1_01\", \"description\": \"为我歌颂！\", \"voicelineId\": 89045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_skill1_02\", \"description\": \"亮相啦！\", \"voicelineId\": 89046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_skill1_03\", \"description\": \"噔噔！\", \"voicelineId\": 89047, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_skill1_04\", \"description\": \"开幕。\", \"voicelineId\": 89048, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_skill1_05\", \"description\": \"光芒啊。\", \"voicelineId\": 89049, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_skill1_06\", \"description\": \"为你献上。\", \"voicelineId\": 89050, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_skill3_01\", \"description\": \"让世界热闹起来吧。\", \"voicelineId\": 89051, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_skill3_02\", \"description\": \"闪耀时刻！\", \"voicelineId\": 89052, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_skill3_03\", \"description\": \"欢唱，以我之名！\", \"voicelineId\": 89053, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_chest_open_01\", \"description\": \"意外之喜，就像蛋糕上的王冠。\", \"voicelineId\": 89054, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_chest_open_02\", \"description\": \"收下吧。咳…我准许了！\", \"voicelineId\": 89055, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_chest_open_03\", \"description\": \"有趣的东西当然是越多越好。\", \"voicelineId\": 89056, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_life_less30_01\", \"description\": \"总之先休战…\", \"voicelineId\": 89057, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_life_less30_02\", \"description\": \"情况不妙呀！\", \"voicelineId\": 89058, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_life_less30_03\", \"description\": \"救命啊——\", \"voicelineId\": 89059, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_life_less30_teammate_01\", \"description\": \"见识下我的实力！\", \"voicelineId\": 89060, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_life_less30_teammate_02\", \"description\": \"换我登场了！\", \"voicelineId\": 89061, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_life_die_01\", \"description\": \"算是…一种解脱吗？\", \"voicelineId\": 89062, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_life_die_02\", \"description\": \"我还是没能做到…\", \"voicelineId\": 89063, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_life_die_03\", \"description\": \"别看我…丢人的样子…\", \"voicelineId\": 89064, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_hit_H_01\", \"description\": \"干什么啊！\", \"voicelineId\": 89065, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_furina/vo_furina_battle_hit_H_02\", \"description\": \"别打了！\", \"voicelineId\": 89066, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_furina_teamJoin_01\", \"description\": \"果然还是离不开我啊。\", \"voicelineId\": 89067, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_furina_teamJoin_02\", \"description\": \"希望是一次尽兴的旅途。\", \"voicelineId\": 89068, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_furina_teamJoin_03\", \"description\": \"瞧好了。\", \"voicelineId\": 89069, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000090, 'Chevreuse', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_draw_appear_01\", \"description\": \"我是枫丹特巡队队长夏沃蕾，寒暄就免了，有什么棘手的案件需要处理吗？\", \"voicelineId\": 90000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·铳枪\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_character_idle_01\", \"description\": \"铳枪是我最喜欢的武器，它具有强大的杀伤力和威慑力。有些时候，后者甚至比前者更有用。\", \"voicelineId\": 90001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·巡逻\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_character_idle_02\", \"description\": \"我们特巡队并不参与枫丹廷的日常巡视工作，我们追捕的人，也不可能在大街上露面。\", \"voicelineId\": 90002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·食物\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_character_idle_03\", \"description\": \"「圈圈圆圆」这种零食便于携带，还可以搭配酱汁，尝出不同风味…等着，我去买几份回来。\", \"voicelineId\": 90003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_weather_heavyRain_01\", \"description\": \"放心，即使是在雨里，我的铳枪依旧能够正常开火。\", \"voicelineId\": 90004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_weather_thunder_01\", \"description\": \"有些罪犯会用雷鸣声来掩盖枪声，但这骗不过我的耳朵。\", \"voicelineId\": 90005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_weather_snowy_01\", \"description\": \"…等等，我要维护一下铳枪。以免它的机关结构被冻住。\", \"voicelineId\": 90006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_weather_sunny_01\", \"description\": \"天气不错，视野良好。\", \"voicelineId\": 90007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_weather_gale_01\", \"description\": \"这种风速…只怕连出膛的子弹也会被吹歪。\", \"voicelineId\": 90008, \"voicelineType\": \"1205\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_weather_desert_01\", \"description\": \"广阔的沙漠，很适合掩埋某些事物。\", \"voicelineId\": 90009, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_greetingMorning\", \"description\": \"早上好，我刚准备去做几组体能训练，要一起吗？\", \"voicelineId\": 90010, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_greetingNoon\", \"description\": \"中午好，要和我一起去特巡队食堂吃饭吗？那里的饭菜很适合填饱肚子。\", \"voicelineId\": 90011, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_greetingNight\", \"description\": \"今天的工作总算结束了，而且没出什么大乱子，我们去吃点夜宵吧，我来带路。\", \"voicelineId\": 90012, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_greetingNight2\", \"description\": \"晚安。我稍后也会去休息，希望…今晚不要发生太多紧急事态。\", \"voicelineId\": 90013, \"voicelineType\": \"1004\"}, {\"title\": \"关于夏沃蕾自己·特巡队\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_idle\", \"description\": \"特巡队专门应对各类危急凶案和恶劣罪犯，所以，我们在执法时会相对…强硬一些。\", \"voicelineId\": 90014, \"voicelineType\": \"2001\"}, {\"title\": \"关于夏沃蕾自己·帽子\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_idle2\", \"description\": \"在特巡队里，有一个不成文的规定。如果一个队员牺牲了，那我们就会将他的帽子保存起来，如果他的后代也成为了特巡队员，我们会将这顶帽子授予他的后代…这也算是一种「传承」吧。\", \"voicelineId\": 90015, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·兴趣\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_close\", \"description\": \"我会在空闲时读一些「犯罪小说」。和推理小说不同的是，犯罪小说并不会去设计复杂的犯罪手法，而是着重描写围绕罪案发生的各色人情纠葛和情绪冲突，在我看来还挺有趣的。\", \"voicelineId\": 90016, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·法理\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_close1\", \"description\": \"如果你对法理有什么疑问，可以随时来问我，或者说…当你的脑子里出现「也许这件事并不算违法」的念头时，必须第一时间来和我商量。\\n每年都有不少蠢货因为侥幸心理而踏过红线，我可不愿意看见你成为那种人。\", \"voicelineId\": 90017, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_pendant\", \"description\": \"在我的工作中，「神之眼」确实是一种不可忽视的武力辅助。有了它之后，我的铳枪再也没有发生过严重故障。\\n「同时持有神之眼和铳枪的特巡队队长」，这些名头加起来，应该能够吓倒一些胆小的嫌疑人了。\", \"voicelineId\": 90018, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_share_01\", \"description\": \"汉考特竟然真的逮捕了米莉丝…面对挚爱之人也能下得去手，让人钦佩。但是米莉丝做错了什么呢？她只是变卖了一件捡到的首饰而已，就变成了贵族口中十恶不赦的罪人…正义真让人捉摸不透，你觉得呢？\", \"voicelineId\": 90019, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻·警卫机关\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_pref_gift_01\", \"description\": \"虽然我们隶属于执律庭，但特巡队执行任务时，并不会大量启用警卫机关。至于为什么…呵，那些笨重的机关，只会挡住我们射出的子弹。\", \"voicelineId\": 90020, \"voicelineType\": \"3003\"}, {\"title\": \"关于娜维娅…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_navia_01\", \"description\": \"我听说过和娜维娅小姐父亲有关的那件谋杀案，当时在执律庭也闹得沸沸扬扬，不少人都因为这件案件而吵个不停…\\n好在如今案件已然昭雪，真正的凶犯也已经伏法…「正义」总算是正式入席了。\", \"voicelineId\": 90021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_lyney_01\", \"description\": \"我认识这位大魔术师。有一次我们逮捕了一位涉嫌故意伤害、拐骗和谋杀的魔术师，却一直弄不清他的犯罪手法。最后还是请来了林尼先生做顾问，才找到了关键物证，顺利将嫌疑人定了罪。听说一位小说家对这件罪案很感兴趣，写了一本用魔术手法犯罪的推理小说。\\n不过…小说的细节描述实在太过详细，现在还处于脱敏期，暂时是无法出版了。\", \"voicelineId\": 90022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲米尼…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_freminet_01\", \"description\": \"我有一次出门买零件的时候遇见过这位潜水员，当时我们都想要买下店里剩下的唯一一个通用零件。我刚想说把那枚零件让给他，但他却一下子缩回了手，低着头一路小跑出了店里。说难听点，简直像个犯人一样…\", \"voicelineId\": 90023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_clorinde_01\", \"description\": \"这位决斗代理人在枫丹廷可是大名鼎鼎啊。我们两人职务不同，我不会随意评价她的工作。但我相信，她接下那些代理决斗的原因，都是发自她内心的「正义」。\", \"voicelineId\": 90024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱欧斯利…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_wriothesley_01\", \"description\": \"莱欧斯利先生的工作卓有成效。至少罪人们都清楚地知道，「梅洛彼得堡」并不是一个养老的好去处。这对我们的审讯工作提供了很大帮助。\", \"voicelineId\": 90025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾梅莉埃…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_emilie_01\", \"description\": \"我俩私交不错，我有好几次请她用专业的化学知识来帮我分析物证、追缉凶犯。她还能帮忙发现很多看不见的信息，比如犯人用了什么香水、送过什么花，甚至去过什么地方、踩过什么泥土…她从没错过。\", \"voicelineId\": 90026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于千织…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_chiori_01\", \"description\": \"千织处理纠纷的方式有些激进。但她凭借自己的门路和人脉，为特巡队提供过很多次情报。作为回礼，我会在她把人丢出店门、或是掀翻恶性竞争对手的店铺时睁一只眼闭一只眼。事后调查你会发现，千织总是有理的那一方。她只是懒得和人废话罢了。\", \"voicelineId\": 90027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_charlotte_01\", \"description\": \"这是一位让人头疼的记者小姐。每次重案发生后，无论我们怎么封锁现场，她都能第一时间出现在最近的地方…有次我的一名手下甚至把她列为了第一嫌疑人，羁押了足足半个月，但她还是在拘留室里写完了报道…我要找个时间，正式和她的主编谈谈了。\", \"voicelineId\": 90028, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于希格雯…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_sigewinne_01\", \"description\": \"特巡队和美露莘的交情由来已久。我们经常和逐影庭里的美露莘合作。她们善良、诚实又可靠，在处理某些重案时，还能发挥无可替代的作用…而我个人，也和几位美露莘关系不错。希格雯护士长就是其中一位。\\n从过去到现在，美露莘都是我们不可或缺的同伴。如果…再有任何人胆敢用任何方式污蔑中伤她们，那么特巡队的枪口，绝不会留情。\", \"voicelineId\": 90029, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14009], \"unlockText\": \"完成「往日留痕」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_neuvillette_01\", \"description\": \"众人皆知，最高审判官大人在审判时全无私情。有人说他少了点人情味，但在我看来，正义本就不该被人情干扰。违律者即有罪，仅此而已。\", \"voicelineId\": 90030, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_teammate_furina_01\", \"description\": \"芙宁娜大人…有段时间突然指定我们进行什么…花枪表演训练。她不仅要求我们全员装配一种特制的「礼仪铳枪」，还要接受特殊的舞枪训练…还好，因为她始终找不到喜欢的仪仗曲，这件事就草草作罢了。\", \"voicelineId\": 90031, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夏沃蕾·其一\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_friendship_01\", \"description\": \"抱歉，我并不擅长和人交际。或者说…和正常人交际。如果你有什么想问的，直接问就是。\", \"voicelineId\": 90032, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解夏沃蕾·其二\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_friendship_02\", \"description\": \"特巡队是隶属于执律庭的多个执法部门之一。因为我们的行事风格和人员组成都非常大胆，在执律庭某些先生嘴里，我们是「最不守规矩」的部门。\\n但是，我认为特巡队的行事准则不应受外界影响。我们要对付的恶徒可不是沫芒宫里的好好先生。如果罪人的违法乱纪来得像暴雨一样突然，那我们也绝不能慢他们半拍。\", \"voicelineId\": 90033, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夏沃蕾·其三\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_friendship_03\", \"description\": \"我接触的犯罪者，并非全是穷凶极恶的歹徒或恶匪。\\n更多的人，最开始都只是犯下了一个小错，他们害怕为此负责，想要悄悄补救，却在不自觉中陷入了谎言的漩涡，最后…在无数谎言的挟裹下，身不由己地走上了犯罪的歧途。\\n我最喜欢的那位剧作家曾经在一台歌剧里写道：「谎言是生发罪行的恶土」。\\n但是，他自己却在几年后因为剽窃罪而被捕…真是给那台歌剧做了一个戏剧性的注脚。\", \"voicelineId\": 90034, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夏沃蕾·其四\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_friendship_04\", \"description\": \"我的父亲受过牢狱之灾，我曾被称作「罪人的女儿」。我还在灰河长大，见过不少太阳光照不到的角落。托这些经历的福，讨厌我的人有不少，但我学会的东西更多。\\n执法者要相信自己心中的「正义」，并且将其付诸在自己的行动中…这是父亲教导我的话。\\n我也深以为然。\", \"voicelineId\": 90035, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解夏沃蕾·其五\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_friendship_05\", \"description\": \"实不相瞒，作为特巡队队长，我见过很多毫无道德底线可言的恶人胡作非为，也见过无辜与善良之人卷入事件受伤，甚至付出生命。我常常感到愤怒与无力。\\n我坚信「罪人」应当受到惩罚，但这并不意味着无尽的复仇循环。\\n如果我们蒙蔽双眼，任由情感驱使自身的行为，迟早都会溺亡在冬天的海水里。\\n越是掌握权力，就越该警惕这一点。坚定追寻自己心中的「正义」，但万不可迷失在追寻它的路上。\", \"voicelineId\": 90036, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"夏沃蕾的爱好…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_pref_hobby\", \"description\": \"训练？射击？非要说的话…看犯罪小说吧。对了，我要去拿最新一期的《谜案寻踪》了。\", \"voicelineId\": 90037, \"voicelineType\": \"6001\"}, {\"title\": \"夏沃蕾的烦恼…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_dialog_annoyed_01\", \"description\": \"不要再让我学习那些繁琐的礼仪了，与其将时间浪费在这上面，我宁愿去盯防凶犯。\", \"voicelineId\": 90038, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_pref_foodLike\", \"description\": \"富含油脂和糖分的食物，可以在工作日为我提供充足的能量，还有好心情。休息日？休息日的话，它们就沦为了会增长体重的「罪恶食品」，而将此等「罪恶」消灭，同样能带给我一天的好心情。\", \"voicelineId\": 90039, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_pref_foodDislike\", \"description\": \"我…不太能接受生冷食物。既然是要入口的东西，至少要做得全熟才行…\", \"voicelineId\": 90040, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_spice_pref_01\", \"description\": \"很不错。不过…呵，就是我不由自主地吃太多，等会要加练了。\", \"voicelineId\": 90041, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_spice_normal_01\", \"description\": \"嗯，比特巡队食堂的饭菜味道好多了。\", \"voicelineId\": 90042, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_spice_dislike_01\", \"description\": \"足够填饱肚子，也不会勾起额外的食欲…这道菜对我来说非常优秀。\", \"voicelineId\": 90043, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_pref_birthday_01\", \"description\": \"生日快乐。嗯…立正！站直一些，不要屈膝。我要测量一下你的身体数据，给你订做一柄便携的小型铳枪，还有速拔枪套…\\n好了，放松。在铳枪做好之前，我先带着你用训练铳枪打一段时间的靶。现在就开始，跟我走。\", \"voicelineId\": 90044, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_starUp_01\", \"description\": \"不错。端枪的手更稳了。\", \"voicelineId\": 90045, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_starUp_02\", \"description\": \"这样的话，也许能狙击到更远的敌人…\", \"voicelineId\": 90046, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_starUp_03\", \"description\": \"多谢，有了这样的力量，追缉恶徒就更有效率了。\", \"voicelineId\": 90047, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_chevreuse/vo_chevreuse_starUp_04\", \"description\": \"感谢你为我提供的所有帮助…虽然我不能承诺特巡队随时听你差遣，但就我个人来说，只要你开口，我就会与你同行。\", \"voicelineId\": 90048, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_battle_skill1_01\", \"description\": \"不许动！\", \"voicelineId\": 90049, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_battle_skill1_02\", \"description\": \"放下武器！\", \"voicelineId\": 90050, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_battle_skill1_03\", \"description\": \"最后通牒！\", \"voicelineId\": 90051, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_battle_skill3_01\", \"description\": \"必要武力。\", \"voicelineId\": 90052, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_battle_skill3_02\", \"description\": \"绳之以法。\", \"voicelineId\": 90053, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_battle_skill3_03\", \"description\": \"束手就擒！\", \"voicelineId\": 90054, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_chest_open_01\", \"description\": \"不错。\", \"voicelineId\": 90055, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_chest_open_02\", \"description\": \"希望里面没有赃物。\", \"voicelineId\": 90056, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_chest_open_03\", \"description\": \"这不算是违法所得，放心吧。\", \"voicelineId\": 90057, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_life_less30_01\", \"description\": \"恶徒…！\", \"voicelineId\": 90058, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_life_less30_02\", \"description\": \"目无法纪。\", \"voicelineId\": 90059, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_life_less30_03\", \"description\": \"你，无权申辩了。\", \"voicelineId\": 90060, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_life_less30_teammate_01\", \"description\": \"稳住队列！\", \"voicelineId\": 90061, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_life_less30_teammate_02\", \"description\": \"保持阵型！\", \"voicelineId\": 90062, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_life_die_01\", \"description\": \"正义…何在…\", \"voicelineId\": 90063, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_life_die_02\", \"description\": \"罪人…尚未…\", \"voicelineId\": 90064, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_life_die_03\", \"description\": \"这就是…结局吗…\", \"voicelineId\": 90065, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_chevreuse/vo_chevreuse_battle_hit_H_02\", \"description\": \"无用顽抗…！\", \"voicelineId\": 90066, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_chevreuse_teamJoin_01\", \"description\": \"出动吧。\", \"voicelineId\": 90067, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_chevreuse_teamJoin_02\", \"description\": \"就当是加练。\", \"voicelineId\": 90068, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_chevreuse_teamJoin_03\", \"description\": \"我随时准备着。\", \"voicelineId\": 90069, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000091, 'Navia', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_draw_appear_01\", \"description\": \"大名鼎鼎的刺玫会现任会长、领导者、总指挥、话事人、老板娜维娅，很高兴认识你！看你才貌出众、气度不凡，我有种预感，我们的缘分会像我的名号一样长呢。\", \"voicelineId\": 91000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·旅行\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_character_idle_01\", \"description\": \"好想去旅游呀——！去哪无所谓啦，主要是想跟朋友们一起玩，嘿嘿。\", \"voicelineId\": 91001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·经验之谈\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_character_idle_02\", \"description\": \"多年的帮派经验告诉我，身边有一把不称手的武器会比没有更危险。\", \"voicelineId\": 91002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·会标\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_character_idle_03\", \"description\": \"刺玫会的标志是母亲设计的，我非常喜欢。你看，轮廓像颗心脏一样呢。\", \"voicelineId\": 91003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_weather_heavyRain_01\", \"description\": \"啊…又是雨天…\", \"voicelineId\": 91004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_weather_thunder_01\", \"description\": \"哎呀！刚才看到闪电就该捂住耳朵的！\", \"voicelineId\": 91005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_weather_snowy_01\", \"description\": \"是不是应该摘掉帽子，让雪花落在脸上？感觉一定很清爽。\", \"voicelineId\": 91006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_weather_sunny_01\", \"description\": \"就是现在，立刻，马上，抬头！你看天上，是不是烈日炎炎，骄阳似火！知道这说明什么吗？\\n说明我们现在应当立刻，马上，去买最大号的超级冰冰凉甜筒，然后比赛谁能在它融化前全部吃完！\", \"voicelineId\": 91007, \"voicelineType\": \"1204\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_weather_afterRain_01\", \"description\": \"太好了，雨停了！\", \"voicelineId\": 91008, \"voicelineType\": \"1205\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_weather_gale_01\", \"description\": \"帽子和裙摆…好难取舍！\", \"voicelineId\": 91009, \"voicelineType\": \"1206\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_weather_desert_01\", \"description\": \"戴上墨镜就不会被沙子迷住眼睛了！但天黑时会看不清路…\", \"voicelineId\": 91010, \"voicelineType\": \"1207\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_greetingMorning\", \"description\": \"早上好！想好今天要做什么了吗？没想好的话，要不要跟我来？\", \"voicelineId\": 91011, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_greetingNoon\", \"description\": \"听说最近出了一种新口味的千层面，你有没有兴趣？感觉一定不会好吃，但我还是想去试试！\", \"voicelineId\": 91012, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_greetingNight\", \"description\": \"晚间新闻播报：「今天的刺玫会会长也和她的好搭档度过了完美的一天。」真棒！\", \"voicelineId\": 91013, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_greetingNight2\", \"description\": \"快，速速清空大脑，睡个好觉！明天见。\", \"voicelineId\": 91014, \"voicelineType\": \"1004\"}, {\"title\": \"关于娜维娅自己·乐观\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_idle\", \"description\": \"盲目乐观可不行，幸福的生活要靠自己的双手去争取！所以，来，握住我的双手，左右摇晃几下——怎么样，是不是很开心？\", \"voicelineId\": 91015, \"voicelineType\": \"2001\"}, {\"title\": \"关于娜维娅自己·运气\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_idle2\", \"description\": \"了解我经历的人可能会觉得我运气不好吧，但我不这么认为哦。\\n能得到这么多的爱，是我一生最幸运的事情了吧。\", \"voicelineId\": 91016, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14017], \"unlockText\": \"完成「共渡潮落」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·搭档\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_close\", \"description\": \"他们有人叫我老板，有人叫我大小姐，我都无所谓啦。最开心的还是你称呼我为「搭档」的时候，所以请多叫几次，满足我的虚荣心吧！\", \"voicelineId\": 91017, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·保密\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_close1\", \"description\": \"有人说秘密一旦说出口就不是秘密了，但能和朋友分享的秘密不是更加珍贵吗？\\n…什么啊，我不是在威胁你啦！虽然身为刺玫会的会长，我当然知道很多让人保守秘密的诀窍，但我是不会用在你身上的，安心啦。\", \"voicelineId\": 91018, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14017], \"unlockText\": \"完成「共渡潮落」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_pendant_01\", \"description\": \"给你看，这就是我的神之眼！亮晶晶，很称我衣服的颜色吧？\\n不过还是你比较厉害，不需要神之眼就能使用很多种元素，应该不是靠练习就能做到的吧？\", \"voicelineId\": 91019, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享·狗狗\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_share_01\", \"description\": \"在所有的品种里，我最喜欢深栗猎犬。你看它们眼睛上方的花纹，是不是很像眉毛？所以它们总是一副憨厚又认真的样子呢。\\n不过这件事还请帮我保密，千万不要告诉别的狗狗！\", \"voicelineId\": 91020, \"voicelineType\": \"3002\"}, {\"title\": \"有什么想要分享·可靠的刺玫会\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_share_02\", \"description\": \"假如你在灰河待过一段时间，应该会发现枫丹还是有不少其他帮派的。他们的目的不一，并不都像刺玫会那样友善，你可要多加留心。如有必要，可以向酒保泰托先生求助。若是对方不愿意坐下来谈的话…嗯，那就只好请我们可靠的白手套先生出马咯。\", \"voicelineId\": 91021, \"voicelineType\": \"3005\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_pref_gift_01\", \"description\": \"久雨莲的颜色真好看啊。而且当你看到它们纷纷绽放的时候，就说明漫长的雨季终于过去了。\", \"voicelineId\": 91022, \"voicelineType\": \"3003\"}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_teammate_clorinde_01\", \"description\": \"她平时话不多，表情也不多，但还是能看出来喜怒哀乐的。之前老爹的事卡在我们之间，唔…有些隔阂吧，就算是那段日子，我也不爱她小心翼翼的样子…还是现在这样比较好。\", \"voicelineId\": 91023, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_teammate_charlotte_01\", \"description\": \"比起跑新闻时的热情和速度，夏洛蒂的拍照技术更让我惊讶。她之前随手给我拍过一张半身照，光影效果好像精心绘制的油画一样。既能写出意想不到的报道，又能拍出最能抓人眼球的画片，她大概天生就是要做记者的吧。\", \"voicelineId\": 91024, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于千织…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_teammate_chiori_01\", \"description\": \"这位为枫丹时尚带来异国风情的服装设计师，私下里帮过刺玫会不少忙呢。她说我的奇思妙想给她提供了好多创作灵感，以我对她的了解来看，应该不是客气话。但当我请她做一个十米高的礼帽时，她却严词拒绝了。唉，要是能摆在店门前，应该是很惹眼的宣传手段呀！\", \"voicelineId\": 91025, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_teammate_furina_01\", \"description\": \"小时候有幸观看过一次芙宁娜大人参与义演的歌剧，票可难买了！虽然扮演的是别的角色，但她看起来反而比平常站在高处演讲时更自然些…现在回想起来，竟然不是错觉。\", \"voicelineId\": 91026, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_teammate_neuvillette_01\", \"description\": \"那维莱特先生啊，既复杂又简单。怎么说呢…就像海里的礁石，磕磕绊绊的，但假如理解了其中的规律，也不是完全没法观测。\", \"voicelineId\": 91027, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4002], \"unlockText\": \"完成「仿若无因飘落的轻雨」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱欧斯利…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_teammate_wriothesley_01\", \"description\": \"想和他谈点东西可费劲了。克洛琳德说在既定的合约基础上可以放心与他合作，但千万不要相信他说的每一句话。怪不得老爹以前从不插手水下的事，保险起见，还是维持原样吧。\", \"voicelineId\": 91028, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「仆人」…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_teammate_arlecchino_01\", \"description\": \"她是一位威严却又慈爱的领导者，有「一家之主」的风范。不过能成为愚人众的执行官，她一定也有手段狠厉的一面。\\n所以放心吧，我会永远记得她帮助过白淞镇的恩情，但在其他方面也会留心的。\", \"voicelineId\": 91029, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼和琳妮特…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_teammate_lyney_01\", \"description\": \"我知道大魔术师说话总会有些浮夸啦，但能看出，林尼是真心对待身边亲友的。有时候他表现出的责任感，可比他的年纪大多了…\\n哦对了，他之前免费给白淞镇的小朋友们变过魔术呢！有机会的话，下次也请他和琳妮特小姐一起来吃马卡龙吧。琳妮特小姐经常凭空变出茶杯来喝茶，那应该不会讨厌甜点吧？\", \"voicelineId\": 91030, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解娜维娅·其一\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_friendship_01\", \"description\": \"刺玫会的工作嘛，杂七杂八的什么都有吧，不过核心目的都是帮助大家解决各种麻烦。这里的「麻烦」只用来指代问题本身，不代表我觉得这些事情烦心哦。相反，能帮到大家会让我觉得神清气爽呢。\", \"voicelineId\": 91031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解娜维娅·其二\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_friendship_02\", \"description\": \"人还是要有些浪漫情怀才行。春天的花，夏天的海，还有朋友的笑容，都不该是被忽略的景色。\", \"voicelineId\": 91032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解娜维娅·其三\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_friendship_03\", \"description\": \"有时我会找个人迹罕至的野外，摆一些物件作为目标，然后练习打靶。\\n很解压的！你想试试吗？我来手把手教你。虽然你是我的第一个学生，但我觉得我会成为一名好老师的。老爹还有布莱卡利奶奶教我的东西我都还没忘呢！\", \"voicelineId\": 91033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解娜维娅·其四\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_friendship_04\", \"description\": \"我不会变成和老爹一样的人。有刺玫会里的老干部觉得我和老爹越来越像了，但我认为那只是很小的倾斜，要归因为有些问题只能用固定的几种办法来解决。刺玫会已经不是当年的样子了，那么会长也不会相同。\", \"voicelineId\": 91034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14017], \"unlockText\": \"完成「共渡潮落」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解娜维娅·其五\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_friendship_05\", \"description\": \"我觉得我也不会变成和母亲一样的人。虽然很多人都说我性格和她很像，我也大约能想象到她当年做出很多选择的理由，但是…\\n哎，突然很想去坐一次克莱门汀线。就现在，可以陪我吗？倒也没什么特别的目的，就当是我邀请你去城里闲逛吧？\", \"voicelineId\": 91035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14017], \"unlockText\": \"完成「共渡潮落」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"娜维娅的爱好…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_pref_hobby\", \"description\": \"我从小就喜欢烘焙。看着一堆零散的食材按照比例融合在一起，就能在烘烤的过程中一点点膨胀、定型，变成香喷喷的样子，是不是很神奇？\\n对了，有机会一起来烤姜饼吧？比比看谁能用饼干搭出最高最漂亮的小屋！\", \"voicelineId\": 91036, \"voicelineType\": \"6001\"}, {\"title\": \"娜维娅的烦恼…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_dialog_annoyed_01\", \"description\": \"呃，烤完蛋糕以后散落的面粉好难收拾啊，还有粘在容器里的蛋清和奶油…我、我去叫帮手来！\", \"voicelineId\": 91037, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_pref_foodLike\", \"description\": \"我喜欢能带来惊喜的食物，但请不要怀疑我的味觉。我只是欣赏其中包含的创意，但这也不会改变很多菜品难吃的事实就是了。\", \"voicelineId\": 91038, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_pref_foodDislike\", \"description\": \"我不喜欢存放了很久的剩菜，感觉辜负了新鲜食材的一生…\", \"voicelineId\": 91039, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_spice_pref_01\", \"description\": \"惊人的厨艺！跟你出门的话，我才是应该带着食材和厨具的那个。\", \"voicelineId\": 91040, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_spice_normal_01\", \"description\": \"味道真不错，再让我加些摆盘艺术就更完美了。\", \"voicelineId\": 91041, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_spice_dislike_01\", \"description\": \"不要气馁，世界需要这种创新精神。\", \"voicelineId\": 91042, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_pref_birthday_01\", \"description\": \"你相信许愿吗？向泉水中丢一枚摩拉，然后等待好运降临在头上。我想，只要摩拉丢得够多，其中总有一个愿望能够实现吧？\\n所以与其寄希望于这样的随机事件，我决定直接用一袋摩拉为你实现今天的愿望。只要是我娜维娅力所能及的，一定都帮你办到！\", \"voicelineId\": 91043, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_starUp_01\", \"description\": \"这种感觉…好像柠檬乳酪蛋糕！\", \"voicelineId\": 91044, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_starUp_02\", \"description\": \"奶油融化在舌尖，压力也跟着消散了。\", \"voicelineId\": 91045, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_starUp_03\", \"description\": \"你知道有一种子弹形状的巧克力糖吗？它的甜度能瞬间让你全身充满力量，就像我现在的感受一样！\", \"voicelineId\": 91046, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_navia/vo_navia_starUp_04\", \"description\": \"最后再来一壶熨帖的奶茶，属于你我的茶歇时间就可以开始了。不过你为我做了这么多，用一顿茶点作为感谢还是不太够呀。以后你在枫丹要是有什么需要帮忙的，就来找刺玫会吧！\", \"voicelineId\": 91047, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_skill1_01\", \"description\": \"小心咯！\", \"voicelineId\": 91048, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_skill1_02\", \"description\": \"正面偷袭！\", \"voicelineId\": 91049, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_skill1_03\", \"description\": \"你好呀！\", \"voicelineId\": 91050, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_skill1_04\", \"description\": \"试着躲躲看？\", \"voicelineId\": 91051, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_skill1_05\", \"description\": \"猜我还有几颗子弹？\", \"voicelineId\": 91052, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_skill1_06\", \"description\": \"是…伞弹枪？\", \"voicelineId\": 91053, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_skill3_01\", \"description\": \"开火！虽然是岩元素啦。\", \"voicelineId\": 91054, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_skill3_02\", \"description\": \"玫瑰礼花！刺玫会特别定制版。\", \"voicelineId\": 91055, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_skill3_03\", \"description\": \"持续打击！嗯嗯，就是这样。\", \"voicelineId\": 91056, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_chest_open_01\", \"description\": \"喔！好运连连！\", \"voicelineId\": 91057, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_chest_open_02\", \"description\": \"快，快收好！\", \"voicelineId\": 91058, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_chest_open_03\", \"description\": \"寻宝大成功！\", \"voicelineId\": 91059, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_life_less30_01\", \"description\": \"再…再撑一会儿！\", \"voicelineId\": 91060, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_life_less30_02\", \"description\": \"…得尽到责任！\", \"voicelineId\": 91061, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_life_less30_03\", \"description\": \"注意力集中。\", \"voicelineId\": 91062, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_life_less30_teammate_01\", \"description\": \"交给会长吧！\", \"voicelineId\": 91063, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_life_less30_teammate_02\", \"description\": \"增援到了！\", \"voicelineId\": 91064, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_life_die_01\", \"description\": \"就当是…回家了…\", \"voicelineId\": 91065, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_life_die_02\", \"description\": \"是我的错吗…\", \"voicelineId\": 91066, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_life_die_03\", \"description\": \"就连我也…\", \"voicelineId\": 91067, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_hit_L_02\", \"description\": \"怎么了？\", \"voicelineId\": 91068, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_hit_H_01\", \"description\": \"哪来的？！\", \"voicelineId\": 91069, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_navia/vo_navia_battle_hit_H_02\", \"description\": \"啊…不算什么！\", \"voicelineId\": 91070, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_navia_teamJoin_01\", \"description\": \"说走就走。\", \"voicelineId\": 91071, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_navia_teamJoin_02\", \"description\": \"刺玫会出马！\", \"voicelineId\": 91072, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_navia_teamJoin_03\", \"description\": \"今天我带路！\", \"voicelineId\": 91073, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000092, 'Gaming', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_draw_appear_01\", \"description\": \"老板你好呀，我是和记厅的镖师，叫我嘉明就行，要运货吗你？请坐请坐，饮杯茶先，我帮你打包好货就可以排期出发咯！哦！如果是找我舞兽的话即刻可以出发！「威水舞兽队」我就是话事人，嘿嘿，失礼失礼。\", \"voicelineId\": 92000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·舞兽\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_character_idle_01\", \"description\": \"咚咚锵，睁眼！咚咚咚咚锵，洗须！唔…不好不好，还要练多点先。\", \"voicelineId\": 92001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·走镖\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_character_idle_02\", \"description\": \"水路山路陆路，走镖时什么路没走过啊我？放心啦，金牌镖师不是浪得虚名的。\", \"voicelineId\": 92002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·早茶\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_character_idle_03\", \"description\": \"一盅两件，再加个白灼时蔬和生滚靓粥，嗯…正啊…\", \"voicelineId\": 92003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_weather_heavyRain_01\", \"description\": \"下雨啦！收衫啦！\", \"voicelineId\": 92004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_weather_thunder_01\", \"description\": \"嗱嗱嗱，你听，坏人发誓天打雷劈啊！\", \"voicelineId\": 92005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_weather_snowy_01\", \"description\": \"啊——咦？为什么下不到我嘴里的？\", \"voicelineId\": 92006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_weather_sunny_01\", \"description\": \"晒点太阳好啊，去去湿气。\", \"voicelineId\": 92007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_weather_desert_01\", \"description\": \"这种地方买水喝肯定很贵吧？好在我自己带水了。\", \"voicelineId\": 92008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_greetingMorning\", \"description\": \"我练完功了，准备去喝早茶，一起？\", \"voicelineId\": 92009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_greetingNoon\", \"description\": \"虽然叫早茶，其实中午也能喝的，怎么说，走？\", \"voicelineId\": 92010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_greetingNight\", \"description\": \"我定到一间菜馆，夜晚才开门，听说只做熟客生意的，来都来了，不吃就走宝了，出发？\", \"voicelineId\": 92011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_greetingNight2\", \"description\": \"要睡了吗？饿不饿啊？不如吃个宵夜先？\", \"voicelineId\": 92012, \"voicelineType\": \"1004\"}, {\"title\": \"关于嘉明自己·老家\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_idle\", \"description\": \"翘英庄，去过吗？我老家。我们那里茶叶很出名的，有「松萝仙芽」，还有「游韵单丛」。这样这样，择日不如撞日，我这里有盒靓单丛，我现在带去茶楼，给你泡一壶，走走走，我埋单！\", \"voicelineId\": 92013, \"voicelineType\": \"2001\"}, {\"title\": \"关于嘉明自己·今时今日\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_idle2\", \"description\": \"我嘉明今时今日，有口饭吃，还能有时间精力钻研舞兽戏，真的要多谢周围好多人的理解和提携。将心比心，我肯定会打醒十二分精神做好这份工。还有余力，就多跑跑腿啊、请人饮茶啊，又不会少块肉咯，哈哈。\", \"voicelineId\": 92014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·赏脸\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_close\", \"description\": \"不用运货的时候我一般在璃月港路边表演舞兽戏，赏个脸来看看？不要钱的不要钱的，只要街坊朋友看得开心我就很满足啦。\", \"voicelineId\": 92015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·得闲饮茶\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_close1\", \"description\": \"记住啊，出门靠朋友，有什么困难不要硬顶喔你，需要我帮手随时出声！欸，大吉利是！最好就别听到你有难的消息啦，出门在外，最紧要是平平安安顺顺利利，我更希望听到你约我得闲饮茶咯。\", \"voicelineId\": 92016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_pendant_01\", \"description\": \"武侠小说有写，打通任督二脉之后就会变成武林高手，拿到神之眼的瞬间就是这种感觉…哈哈，讲笑而已！我不是什么武林高手，不过是多了点精力，那就顺手帮衬下街坊咯。不过讲开又讲，你没有神之眼都这么厉害，有了还得了？\", \"voicelineId\": 92017, \"voicelineType\": \"3001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_share_01\", \"description\": \"「文仔」好调皮的，本来咧，我想他文静一点才起的这个名，呃…如你所见，好像没什么用哈哈。不过也好，生生猛猛才能将舞兽戏做得风生水起嘛。看着文仔，我也慢慢能模仿出猊兽的神态动作，一戴上兽首，感觉就来了喂，吼！\", \"voicelineId\": 92018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_pref_gift_01\", \"description\": \"有很多花花草草，或者树皮树枝，晒干后用来煲水喝，生津解渴，清热降燥，好有益的！我阿婆阿婶都跟我讲过，吃煎炸食物前后，一定要记得喝这种「凉茶」，清清体内的热气喔。\", \"voicelineId\": 92019, \"voicelineType\": \"3003\"}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_xiangling_01\", \"description\": \"香菱大师傅有好多拿手菜，我最喜欢那味水煮黑背鲈，虽然每次都用水涮了两次先吃，还是辣得我「嘶哈嘶哈」，哈哈哈，不愧是万民堂的生招牌，用料真足火候真猛！下次我还吃！\", \"voicelineId\": 92020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_xingqiu_01\", \"description\": \"飞云商会是镖局的老主顾了，印象中一直都是他们的大少爷在打理生意上的事情，有次行秋少爷难得主动问起镖物的事，我就一五一十地将飞云商会最近货物的路线和收发日子告诉他，结果他问的是能不能透露一下万文集舍最新那批货什么时候到，哈哈哈。\", \"voicelineId\": 92021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于重云…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_chongyun_01\", \"description\": \"听说那位仁兄有「纯阳之体」，按照我们那边的说法，他体内可能虚火很旺啊，应该多喝点凉茶喔他。\", \"voicelineId\": 92022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_keqing_01\", \"description\": \"多得玉衡星大人，她带头整治完遗珑埠跟璃月港之间的运输路段之后，盗贼都不敢那么猖獗了。我会不会失业？哈哈，那又未必，就算不用跟贼人打架了，担担抬抬这种粗重工夫总要有人干的嘛。\", \"voicelineId\": 92023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于白术…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_baizhu_01\", \"description\": \"走镖也好舞兽也好，跌打损伤都是家常便饭。好在有白大夫，他配的药真是舟车劳顿、居家旅行的必备良药，镖局的兄弟们都托我来璃月港的时候帮手带点回去的。\", \"voicelineId\": 92024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于七七…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_qiqi_01\", \"description\": \"七七小妹妹非常热心，见我每次来不卜庐都抓很多药，觉得我是因为身体僵硬才会摔跤受伤，所以教我做了柔软体操，哈哈，好简单的，你也试试？来，一二七七…二二七七…\", \"voicelineId\": 92025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于云堇…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_yunjin_01\", \"description\": \"云堇大师是我榜样啊！不管内行外行，听过她的曲的都说好。真是不得了，什么时候「威水队」能做到「云翰社」一半的影响力…我做梦都会笑醒！\", \"voicelineId\": 92026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于辛焱…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_xinyan_01\", \"description\": \"辛焱的演唱实在是太有感染力了！文仔听的时候也一直摇头晃脑的，喜欢得不得了！有机会的话真想请她一起办一个「火爆摇滚舞兽会」，你见识多，你觉得有没有搞头？\", \"voicelineId\": 92027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于闲云…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_xianyun_01\", \"description\": \"闲云姨很关照我，见我的兽首磨损了，马上说要做十个八个比我人还高的兽首给我，我讲到口水都干了，她才同意在我原来这个上改良…现在我这个兽首，又威武又轻便，兽披随时随地都能飘起来，就像有仙风托住一样！我超喜欢！\", \"voicelineId\": 92028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_zhongli_01\", \"description\": \"我猜那位钟离先生一定是位出身富贵的文人雅士。不管我运货到茶馆还是戏台，都能撞见他在喝茶听书，一看就懂很多的样子。哇，有次无意中听到他跟别人讲茶，当时我就觉得他跟我老爸肯定可以讲通宵了…\", \"voicelineId\": 92029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_charlotte_01\", \"description\": \"哦，那位记者小姐啊嘛！我知道她！遗珑埠的枫丹人都喜欢看蒸汽鸟报，我也经常蹭着看看，有很多不得了的新闻都是她写的喔！哦！我记得你还上过头条啊！是不是？\", \"voicelineId\": 92030, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于蓝砚…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_teammate_lanyan_01\", \"description\": \"认识她，你有食神啦！你让蓝砚带你去山里吃农家菜，点名要去可以自带食材加工的农庄，你说是嘉明指定那家，她就知道了。那条山路特别难走，没有她这样有经验的本地人带路，我怕你走到天黑都找不到。你们尽管去吃，报我名字就行，老板认识我的，吃完入我数！\", \"voicelineId\": 92070, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解嘉明·其一\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_friendship_01\", \"description\": \"镖师里最会舞兽的，舞兽师傅里运过最多镖的，怎么样？这样介绍不知道能不能让你记住我咧？\", \"voicelineId\": 92031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解嘉明·其二\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_friendship_02\", \"description\": \"是不是三脚猫功夫看基本功就知道了，扎马、踢腿、劈叉、弹跳、翻滚…连这些都半桶水，轻则从高桩上跌下来，躺他个一头半个月。重则运镖打不过人，失镖丧命…吓不吓人？吓人就对了嘛，当初我就是这样说服镖局的兄弟每日同我一起练功的，哈哈哈。\", \"voicelineId\": 92032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解嘉明·其三\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_friendship_03\", \"description\": \"兽首兽披啊、锣鼓钹镲啊，练得多了旧得也快，要勤力点养护，这里面得花不少钱呢。再加上平时请人吃饭喝茶、过时过节送送礼、兄弟们周转不灵借点钱…七七八八加起来，一个月走镖赚的钱就没几多剩了…\", \"voicelineId\": 92033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解嘉明·其四\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_friendship_04\", \"description\": \"老爸一直想我跟他学做生意，不是没想过啊我，正是因为想清楚了才离家出走的。一来要证明给他看，我舞兽不是三分钟热度，一定会出人头地！二来嘛，也可以跟老爸少打点仗…两父子哪有隔夜仇的，我不是恨他，只是他每次开口火药味都很重，我避得到就避咯。\", \"voicelineId\": 92034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解嘉明·其五\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_friendship_05\", \"description\": \"嗱，这里，前两日练踢腿，淤了一片…这个包，上个月练翻滚的时候撞的，已经快好咯~这个疤就厉害了，是我第一次上高桩时摔下来弄的，那时流了好多好多血，差点以为我的舞兽生涯刚刚开始就要结束了…不过好彩，这么多年来都是有惊无险，我还能继续…嗯，一定要继续。\", \"voicelineId\": 92035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"嘉明的爱好…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_pref_hobby\", \"description\": \"早茶不只有茶啦，还有各种甜点咸点，有即点即上的也有现点现做的，每次喝完早茶我都不用吃午饭了。你得闲就叫我，我请你饮茶！想吃什么就点什么，没所谓的吃不完打包回去嘛。\", \"voicelineId\": 92036, \"voicelineType\": \"6001\"}, {\"title\": \"嘉明的烦恼…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_dialog_annoyed_01\", \"description\": \"什么？！茶位费就算了，擦手帕都要另外收钱的？好在我自己有带，退掉退掉。\", \"voicelineId\": 92037, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_pref_foodLike\", \"description\": \"小时候很顽皮的我，还记得每次闯祸后我不听教，我老妈都会气得骂一句「生块叉烧好过生你」，现在每次吃叉烧，还挺想老妈的…\", \"voicelineId\": 92038, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_pref_foodDislike\", \"description\": \"他们总说我口味刁钻，我的要求很简单啊——禽肉有禽肉味，鱼肉有鱼肉味，很过分吗？\", \"voicelineId\": 92039, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_spice_pref_01\", \"description\": \"这个味道——难道阁下的真实身份就是「神」？没说错吧？「厨神」阁下。\", \"voicelineId\": 92040, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_spice_normal_01\", \"description\": \"你亲手做的？有心了有心了！这样的烹饪水平，摆到明是高手啦！\", \"voicelineId\": 92041, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_spice_dislike_01\", \"description\": \"错就要认，打就要立正！如果我哪里行差踏错了不如你还是直接打我一顿吧！\", \"voicelineId\": 92042, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_pref_birthday_01\", \"description\": \"不是吧你，生日这么好的日子都不提前告诉我？好在我已经在新月轩订好一桌子菜啦，八菜一汤白饭任装，还有寿包和糖水，叫多点朋友一起来贺一贺呀。另外咧，我还准备了一小段祝寿舞兽戏，小小意思，不成敬意，希望你钟意啦。\", \"voicelineId\": 92043, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_starUp_01\", \"description\": \"哇，这些都给我了？这么大手笔，怎么好意思啊？\", \"voicelineId\": 92044, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_starUp_02\", \"description\": \"哈哈，真看得起我啊，那我不练个砂煲那么大的拳头有点对不住你喔。\", \"voicelineId\": 92045, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_starUp_03\", \"description\": \"走镖也是镖，保镖也是镖，信得过我的话，以后我来当你保镖咯？\", \"voicelineId\": 92046, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_gaming/vo_gaming_starUp_04\", \"description\": \"多谢你为我的兽首点睛，接下来的旅途，不敢说包你顺风顺水，但我一定会落力豁出去，帮你采青！\", \"voicelineId\": 92047, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_battle_skill1_01\", \"description\": \"对不住咯。\", \"voicelineId\": 92048, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_battle_skill1_02\", \"description\": \"采青先！\", \"voicelineId\": 92049, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_battle_skill1_03\", \"description\": \"中头奖啦！\", \"voicelineId\": 92050, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_battle_skill3_01\", \"description\": \"鸿运当头。\", \"voicelineId\": 92051, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_battle_skill3_02\", \"description\": \"文仔，到你出马！\", \"voicelineId\": 92052, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_battle_skill3_03\", \"description\": \"威水舞兽！\", \"voicelineId\": 92053, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_chest_open_01\", \"description\": \"哇，好靓喔这批货！\", \"voicelineId\": 92054, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_chest_open_02\", \"description\": \"这趟镖要运去哪呢老板？\", \"voicelineId\": 92055, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_chest_open_03\", \"description\": \"淡淡定定，有财进。\", \"voicelineId\": 92056, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_life_less30_01\", \"description\": \"小小痛楚等于激励…\", \"voicelineId\": 92057, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_life_less30_02\", \"description\": \"呵，小意思啦…\", \"voicelineId\": 92058, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_life_less30_03\", \"description\": \"顶得住！继续！\", \"voicelineId\": 92059, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_life_less30_teammate_01\", \"description\": \"歇一阵先，包在我身上！\", \"voicelineId\": 92060, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_life_less30_teammate_02\", \"description\": \"喂！不要硬顶啊！\", \"voicelineId\": 92061, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_life_die_01\", \"description\": \"呵，我走先啦…\", \"voicelineId\": 92062, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_life_die_02\", \"description\": \"还没「采青」呢…\", \"voicelineId\": 92063, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_life_die_03\", \"description\": \"快点走…不用理我…\", \"voicelineId\": 92064, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_battle_hit_H_01\", \"description\": \"不是吧你！\", \"voicelineId\": 92065, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_gaming/vo_gaming_battle_hit_H_02\", \"description\": \"停手！\", \"voicelineId\": 92066, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_gaming_teamJoin_01\", \"description\": \"走镖去喽。\", \"voicelineId\": 92067, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_gaming_teamJoin_02\", \"description\": \"收到，开桩！\", \"voicelineId\": 92068, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_gaming_teamJoin_03\", \"description\": \"急吗？不急喝个早茶先？\", \"voicelineId\": 92069, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000093, 'Xianyun', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_draw_appear_01\", \"description\": \"怎么，第一次看见本仙这般姿态，认不出来了？本仙漫无羁束，快意自在。想去哪里，想陪谁一同旅行，还不是本仙自己说了算。咳咳，鉴于本仙声名在外，人前，你还是唤本仙「闲云」就好。\", \"voicelineId\": 93000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·机关术\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_character_idle_01\", \"description\": \"机关术奥妙无穷，并非三言两语能道明。但为什么每次都会把人聊困呢？\", \"voicelineId\": 93001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·人间\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_character_idle_02\", \"description\": \"天下承平，万象更新，正是人间好时节啊。\", \"voicelineId\": 93002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·趣闻\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_character_idle_03\", \"description\": \"既然无事，不妨来本仙家中坐坐，讲讲最近的趣闻吧。\", \"voicelineId\": 93003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_weather_heavyRain_01\", \"description\": \"如今人间风调雨顺，也就无须本仙呼风唤雨了。\", \"voicelineId\": 93004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_weather_thunder_01\", \"description\": \"哎哟，有点吵耳朵…\", \"voicelineId\": 93005, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_weather_sunny_01\", \"description\": \"视野不错，适合登高望远的好天气。哦，本仙不会丢下你一人飞走的。\", \"voicelineId\": 93006, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_weather_gale_01\", \"description\": \"这风真是舒畅，不如为你贴些仙家符箓，随本仙飞上云霄如何？\", \"voicelineId\": 93007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_greetingMorning\", \"description\": \"本仙早就醒了，闭着眼是在静心冥想，对修行有益，你也可以试试。\", \"voicelineId\": 93008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_greetingNoon\", \"description\": \"嗯？看本仙做什么，今天不是轮到你准备午饭了吗？\", \"voicelineId\": 93009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_greetingNight\", \"description\": \"找本仙去逛夜市？呵，那里有什么好逛的。想要什么稀奇玩意，本仙给你做一个就是了。\", \"voicelineId\": 93010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_greetingNight2\", \"description\": \"本仙还精神着呢…看你倒是眼皮打架，快去休息吧。\", \"voicelineId\": 93011, \"voicelineType\": \"1004\"}, {\"title\": \"关于闲云自己·师徒\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_idle\", \"description\": \"本仙向来逍遥自在，无拘无束，徒弟们自然也有样学样，一个个的忙得没影，十天半月也没个信…本仙心中并无寂寞之情！嗯…若是出于关心，抽空去看看她们，应该不会添什么麻烦吧？\", \"voicelineId\": 93012, \"voicelineType\": \"2001\"}, {\"title\": \"关于闲云自己·烹饪\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_idle2\", \"description\": \"虽然机关做菜不如人力精巧，但省下做饭的时间，就可以用去研制新的烹饪神机，新的机关又会节省更多时间…呵，如此循环下去，终有一日，本仙可以将世间美味尽收囊中。\", \"voicelineId\": 93013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·旅伴\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_close\", \"description\": \"为了今后出行便利，本仙特意飞到空中勘测地形，做了这个指路罗盘，怎么样，没见过做事如此周到的旅伴吧？你说你对附近地形很熟悉？呵…人的记忆总会有误差，等你迷路的时候，就会感谢本仙未雨绸缪了。\", \"voicelineId\": 93014, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·牵绊\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_close1\", \"description\": \"本仙虽不在意身外之物，亦深谙「牵绊」二字。这二字写起来容易，个中真意却难以言说。就像本仙与那些老家伙们，有时几年才相见一次，见了面也经常吵架斗嘴，但不论彼此身在何处，都不会有漂泊无依之感。你是本仙认可的人，自然也在本仙的朋友之列，不知道你是否和本仙一样珍惜这份「牵绊」呢？\", \"voicelineId\": 93015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_pendant_01\", \"description\": \"帝君曾言，「神之眼」代表的是一份责任，无论隐于山林还是居于闹市，都不可忘记看护人间之责。从今以后是人的时代，本仙会心怀这份责任继续走下去。\", \"voicelineId\": 93016, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_share_01\", \"description\": \"这机关鸟是个试作品，本仙想做只大鸟，中间镂空变成座驾，就能和那帮老友一起出去游山玩水了…但是动力和操作问题是个难事，既要能升降，还要能变形，还要兼顾必要的安全措施…哎，若是归终还在，她或许能想出不少异想天开的解决方案吧。\", \"voicelineId\": 93017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_pref_gift_01\", \"description\": \"奥藏山尽敛风华，蕴天地灵气，是适合修行的好地方。当初本仙在山中静思时，常有好奇的生灵前来张望，动辄叽叽喳喳、吵吵闹闹的…倒让人一点也不讨厌。\", \"voicelineId\": 93018, \"voicelineType\": \"3003\"}, {\"title\": \"关于甘雨…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_ganyu_01\", \"description\": \"本仙问甘雨平时加班都在忙些什么，她说了一堆拗口的词，什么会议纪要、工作总结、年度报告、财务预算…哼，若非她的仙麟血脉，又有本仙传授的养生之法，可应付不来这些繁文缛节…你下次记得替本仙问她，有没有每天喝本仙研制的明目清心茶？\", \"voicelineId\": 93019, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于申鹤…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_shenhe_01\", \"description\": \"申鹤说她有一次给万民堂送外卖，为了节省时间，直接踩着屋顶过去，从屋顶跳到人家门口，把顾客吓了一跳，差点要喊千岩军…好在她来去如风，没等顾客喊出口，早已放下外卖消失不见了。申鹤这孩子处理危机的能力真是越来越强，本仙很是欣慰。\", \"voicelineId\": 93020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1101505], \"unlockText\": \"完成「风起鹤归」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于钟离…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_zhongli_01\", \"description\": \"帝君听说本仙要在璃月港置办住宅，便跟本仙细数家居装潢与家具购置的注意事项。采光通风、木材定制、瓷器选购、还有花卉摆放…本仙听得头都快大了，在人间居住竟要这般费心吗？\", \"voicelineId\": 93021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11035], \"unlockText\": \"完成「千里月明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于魈…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_xiao_01\", \"description\": \"降魔大圣比本仙还安静，千百年的聚会，就没几次他愿意出面的。本仙倒是听说你和他交情不错，平时你都跟他聊些什么？要不然，下次你找他的时候，本仙做一份「豆腐布丁」让你带去吧。\", \"voicelineId\": 93022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_hutao_01\", \"description\": \"那丫头年纪轻轻，说话稀奇古怪，但看「往生堂」的人却对她毕恭毕敬，连帝君都客气，还给她当那什么「客卿」…听说她对食物的品味也不同寻常，这号奇人，倒让本仙有些兴趣。\", \"voicelineId\": 93023, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_xiangling_01\", \"description\": \"本仙闲聊时跟她说起过机关烹饪神机的事，那丫头竟然说，做菜还是得亲自动手才地道…哼，本仙造机关也是亲自动手，怎么就不地道了？本仙可得跟她比比…不过她做的璃月菜肴确实风味极佳…待本仙想想怎么改进机关…\", \"voicelineId\": 93024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于凝光…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_ningguang_01\", \"description\": \"这位「天权星」做起事还算八面玲珑，讲话也滴水不漏。哼，不得不说，璃月港在他们七星的治理下也算欣欣向荣。本仙也在细心观察，研究其中奥秘…咳，此事你知道即可，不要对她讲。\", \"voicelineId\": 93025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [102510], \"unlockText\": \"完成「迫近的客星」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_keqing_01\", \"description\": \"她逢年过节便会代表七星来拜访本仙，给本仙送来节日贺礼，真是个有心的孩子。看她做事干练，考虑又周全，甘雨与她共事，应该也不用本仙过于操心…\", \"voicelineId\": 93026, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于云堇…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_yunjin_01\", \"description\": \"「璃月戏」有不少以仙人传说为蓝本的故事，其中也有以本仙的经历改编的戏曲…本仙当然未曾看过，看别人在台上演自己，难道不会尴尬吗？至于她以申鹤的经历创作的戏，待本仙空闲，倒是可以去品鉴一番。\", \"voicelineId\": 93027, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1101505], \"unlockText\": \"完成「风起鹤归」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于瑶瑶…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_yaoyao_01\", \"description\": \"有一次，瑶瑶把我的眼镜借了过去，戴在了自己的鼻梁上，一个人乐呵呵地笑了半天…孩子啊，总能找到独属于孩子的乐趣。\", \"voicelineId\": 93028, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于嘉明…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_teammate_gaming_01\", \"description\": \"嘉明这小伙为人热情，说话有趣，也从来不会夸夸其谈，本仙很是看重。说起最初和他相遇的时候，看到本仙在池边歇脚，他还主动拿出吃食与本仙分享呢。后来他说在他眼里，比起仙人，本仙更像是一位可敬的长辈。呵呵，那本仙自然也该以长辈的身份照顾他喽。\", \"voicelineId\": 93029, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解闲云·其一\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_friendship_01\", \"description\": \"想要知道本仙的过往？都是些陈年旧事，有什么好说的。倒是你四处游历，想必遇到不少趣事。其他国家的神仙是何样貌？可有哪位像本仙一样喜欢聊天？沏壶好茶，跟本仙细细说来。\", \"voicelineId\": 93030, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解闲云·其二\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_friendship_02\", \"description\": \"有段时间，璃月盛行寻仙问道之法，也不知道他们如何得知本仙的洞府所在，隔三岔五便有人在奥藏山设坛供奉食物…哼，本仙岂会因凡间美食扰了清修？不过是念在他们一片诚心，才不得已等到旁边没人的时候，略加品…咳，略加回应罢了。\", \"voicelineId\": 93031, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解闲云·其三\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_friendship_03\", \"description\": \"曾经也有其他人找到本仙的洞府，想要本仙收他们为徒。本仙闭门不见，他们便赖着不走，奥藏山都快成了露营公园…本仙便在洞府外贴了张便条，想要拜师者先想出清心的九十九种烹饪之法，每天做出一种…果然没有人能坚持下来。哼，无论是仙家术法还是机关造诣，都需资质极佳，心性极静之人方能领悟，如果连三个月也坚持不住，也就不必白费力气了。\", \"voicelineId\": 93032, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解闲云·其四\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_friendship_04\", \"description\": \"机关术虽有诸多神妙用途，但有时不过是本仙消磨时间的游乐产物。有一年璃月大雪，奥藏山积雪很深，本仙见众人终日待在洞府，无所事事，便造了个「追风滑雪神机」。削月那老家伙见本仙和归终、歌尘等人玩得起劲，也要加入，可他出师不利，第一次试滑便脱了轨道，连人带机关砸进了旁边的积雪里。我们铲了半天才将他挖出来…后来本仙特地给他在防护性上加固了不少，便是三岁稚子也能安稳操控，只是速度慢些罢了。\", \"voicelineId\": 93033, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解闲云·其五\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_friendship_05\", \"description\": \"本仙搬来璃月港之后，看了不少流行读物，其中一些侠义小说颇为有趣。若是将本仙认识的形形色色人物写进去，岂不比那些凭空想象的角色更为精彩？可惜本仙的徒弟们，似乎都不喜欢本仙跟其他人讲她们的故事…那不如就写你跟本仙聊过的旅途趣事如何？\", \"voicelineId\": 93034, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [11035], \"unlockText\": \"完成「千里月明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"闲云的爱好…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_pref_hobby\", \"description\": \"闲来无事，坐在山野之间吹吹罡风，总能让人平心静气。\", \"voicelineId\": 93035, \"voicelineType\": \"6001\"}, {\"title\": \"闲云的烦恼…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_dialog_annoyed_01\", \"description\": \"自从本仙搬来璃月港，前来拜访、宴请本仙的新朋旧友一茬接一茬。如此往来，本仙手上的摩拉也未必够用…\", \"voicelineId\": 93036, \"voicelineType\": \"6012\", \"unlockConditions\": [{\"paramList\": [11035], \"unlockText\": \"完成「千里月明」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_pref_foodLike\", \"description\": \"与好友一起吃饭，无论是何种菜肴，都令人回味无穷。\", \"voicelineId\": 93037, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_pref_foodDislike\", \"description\": \"仙人不会被人间俗物阻碍修为，比起食物的种类，本仙更在乎味道…要是你自己尝着都不够可口，就不要拿到本仙面前了。还不如本仙来下厨…\", \"voicelineId\": 93038, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_spice_pref_01\", \"description\": \"食材用得新鲜，口感也恰到好处。你偷学过本仙的烹饪技巧？\", \"voicelineId\": 93039, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_spice_normal_01\", \"description\": \"味道倒是其次，能想起请本仙吃饭，心意可嘉。\", \"voicelineId\": 93040, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_spice_dislike_01\", \"description\": \"本仙的机关烹饪神机近来闲置了，可以借你一用。\", \"voicelineId\": 93041, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_pref_birthday_01\", \"description\": \"来，打开这个木匣。这个机关小人是本仙闲暇时所做，你拿去玩吧。你看，只要像这样拍拍手，莲花的花瓣就会打开，彩灯一圈圈亮起，随后奏响的是小辈们最喜欢的生日快乐歌…这样办生日宴时，想必会平添几分热闹吧。祝你过得开心。\", \"voicelineId\": 93042, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_starUp_01\", \"description\": \"久居家中，偶尔出来活动筋骨倒也不错。\", \"voicelineId\": 93043, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_starUp_02\", \"description\": \"有些仙法多年不用，一朝拾起难免有些生疏。\", \"voicelineId\": 93044, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_starUp_03\", \"description\": \"唉，既然你露出这般期待的眼神，本仙也只好再拿出些本事了。\", \"voicelineId\": 93045, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_xianyun/vo_xianyun_starUp_04\", \"description\": \"在世间行走多了便有经验。比起力量多寡，还是与人交往的技巧更为重要。若你有空，我们去找个风景开阔的地方，赏赏景、聊聊天，放慢脚步，好好享受享受生活吧。\", \"voicelineId\": 93046, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_battle_skill1_01\", \"description\": \"喝！\", \"voicelineId\": 93047, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_battle_skill1_02\", \"description\": \"御风！\", \"voicelineId\": 93048, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_battle_skill1_03\", \"description\": \"云散！\", \"voicelineId\": 93049, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_battle_skill3_01\", \"description\": \"八风儛翮。\", \"voicelineId\": 93050, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_battle_skill3_02\", \"description\": \"仙人来哉！\", \"voicelineId\": 93051, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_battle_skill3_03\", \"description\": \"风汇，孤云与归。\", \"voicelineId\": 93052, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_chest_open_01\", \"description\": \"能当零件用用。\", \"voicelineId\": 93053, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_chest_open_02\", \"description\": \"什么稀奇玩意，让本仙看看。\", \"voicelineId\": 93054, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_chest_open_03\", \"description\": \"本仙是不是该研发个…「奇物搜觅神机」？\", \"voicelineId\": 93055, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_life_less30_01\", \"description\": \"大胆！\", \"voicelineId\": 93056, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_life_less30_02\", \"description\": \"身法不错。\", \"voicelineId\": 93057, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_life_less30_03\", \"description\": \"本仙奉陪到底。\", \"voicelineId\": 93058, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_life_less30_teammate_01\", \"description\": \"量力而行。\", \"voicelineId\": 93059, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_life_less30_teammate_02\", \"description\": \"怎么不叫本仙？\", \"voicelineId\": 93060, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_life_die_01\", \"description\": \"肚子空着…这次不算…\", \"voicelineId\": 93061, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_life_die_02\", \"description\": \"一着不慎…\", \"voicelineId\": 93062, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_life_die_03\", \"description\": \"机关…还未使出…\", \"voicelineId\": 93063, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_battle_hit_H_01\", \"description\": \"雕虫小技。\", \"voicelineId\": 93064, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_xianyun/vo_xianyun_battle_hit_H_02\", \"description\": \"不过如此。\", \"voicelineId\": 93065, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_xianyun_teamJoin_01\", \"description\": \"机关调试完毕，动身吧。\", \"voicelineId\": 93066, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_xianyun_teamJoin_02\", \"description\": \"吃食可备好了？\", \"voicelineId\": 93067, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_xianyun_teamJoin_03\", \"description\": \"本仙日行千里，你可别跟丢了。\", \"voicelineId\": 93068, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000094, 'Chiori', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_draw_appear_01\", \"description\": \"我叫千织，「千织屋」的老板。有服装定制类需求的话，欢迎找我。其他需求，就看你有没有足够用来交换的东西了，有来有回才叫「生意」嘛。另外，「千织屋」内严禁抽烟喝酒，寻衅闹事。「顾客即是神明」那一套在我这里不管用，就算来的真是神明，不守规矩被丢出去的时候，也一样是屁股着地。\", \"voicelineId\": 94000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·评价\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_character_idle_01\", \"description\": \"我来决定自己该怎么走，要成为谁。没人能对我指手画脚。\", \"voicelineId\": 94001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·裁缝刀\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_character_idle_02\", \"description\": \"谁说裁衣服一定要用剪刀？那些死板的规矩由它去吧，我喜欢自己用着顺手的刀具。\", \"voicelineId\": 94002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·模特\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_character_idle_03\", \"description\": \"真要站着不动的话，干脆来当我的模特吧。给你设计款好看的衣服。\", \"voicelineId\": 94003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_weather_heavyRain_01\", \"description\": \"比起下雨，我更讨厌地上泥水，溅到衣服上就很难洗掉。\", \"voicelineId\": 94004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_weather_thunder_01\", \"description\": \"…想起了家乡往日的风景。\", \"voicelineId\": 94005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_weather_snowy_01\", \"description\": \"清高却令人向往…落到手上的一瞬，这份美丽又随之消散…雪花这东西，和「时尚」还真像…\", \"voicelineId\": 94006, \"voicelineType\": \"1203\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_weather_desert_01\", \"description\": \"真难想象这种地方要怎么推行时尚。\", \"voicelineId\": 94007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_greetingMorning\", \"description\": \"早，别指望我会给你变出早饭来。你如果去咖啡厅的话就帮我带一杯咖啡来吧，不加奶，不加糖。\", \"voicelineId\": 94008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_greetingNoon\", \"description\": \"已经这个点了？肚子完全不饿啊…我不打算停下手头的活。午饭你自己吃就好。\", \"voicelineId\": 94009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_greetingNight\", \"description\": \"外面好吵。全枫丹廷的人都出来逛街了吗？\", \"voicelineId\": 94010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_greetingNight2\", \"description\": \"我要去好好泡个澡放松一下。不多聊了，明天见。\", \"voicelineId\": 94011, \"voicelineType\": \"1004\"}, {\"title\": \"关于自己·直接\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_idle\", \"description\": \"很多人明里暗里表达过我的性格不够好，说话不够委婉，容易伤人。依我说，那种谁都看得出来的寒暄、客套和恭维才是在浪费彼此的时间吧？要是挑明事实就会受伤，那人也太脆弱了。\", \"voicelineId\": 94012, \"voicelineType\": \"2001\"}, {\"title\": \"关于自己·理念\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_idle2\", \"description\": \"最初构想品牌理念的时候，我想到了很多过去的经历，也由此提炼出了不少关键词。取舍是一件难事，尤其是你发现每一枚宝石都折射着你的一种想法…而你只能挑选最能代表你的那一枚。\\n「永不认输」。那才是我，才是我的品牌。\", \"voicelineId\": 94013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·试衣\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_close\", \"description\": \"听我的，这件适合你。什么？之前没见过这样的款式？呵，那是你之前遇到的设计师没品味。\", \"voicelineId\": 94014, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·交换\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_close1\", \"description\": \"事到如今再说这话有点晚了，但我向来是想说什么就说什么，你恐怕也习惯了。我不打算改变自己直来直往的作风，你也尽管在我面前表露最真实的自己吧，无须掩藏。我保证不会对你有所指摘。不信？你认识我那么久，我有说到但做不到的时候吗？\", \"voicelineId\": 94015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_pendant_01\", \"description\": \"因为我的出身，枫丹人称呼我为「鸣雷的裁锦师」。爱怎么称呼怎么称呼吧，我对故乡没什么依恋的感情，毕竟就连我的「神之眼」，都是在我决定离开稻妻时获得的。\\n但我也不讨厌那个晒不干布料的地方，对我来说，只是没必要回去而已。\", \"voicelineId\": 94016, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_share_01\", \"description\": \"为了治我小时候好动的性格，父母送我去学过很多东西，「剑道」就是其中之一。但学了一阵子后，我突然觉得双手用刀很称我意，也很厉害，结果却被剑道老师制止了。我问他为什么，他只说这不是主流刀法，有些「不伦不类」。自那之后，我就再没去上过他的课。现在想想，当初坚持自己喜欢的用法真是太好了。或许，我天生就是两只手都闲不下来吧。\", \"voicelineId\": 94017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_pref_gift_01\", \"description\": \"「袖」是我的第一件作品，那时只想缝一个跟自己差不多模样的女孩，作为模特和帮手。嗯？陪伴？我没这种需要。\", \"voicelineId\": 94018, \"voicelineType\": \"3003\"}, {\"title\": \"关于娜维娅…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_teammate_navia_01\", \"description\": \"她曾经很认真地「拜托」我设计各种奇奇怪怪的东西，比如为船舵的每个把手都设计一个不同的头冠。那时我忍不住翻了个白眼，说我最多把她的帽子设计成一条船。\\n那些说我想法超前的人恐怕是没跟娜维娅聊过天。\", \"voicelineId\": 94019, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_teammate_lyney_01\", \"description\": \"我做不出一顶能隐藏秘密的礼帽，但他通过魔术可以。有时我很好奇，他的帽子里装了那么多的秘密，戴起来会是什么感觉。对我来说，还是想到什么就说出来会比较轻松。\", \"voicelineId\": 94020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琳妮特…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_teammate_lynette_01\", \"description\": \"这位助手小姐不太说话，但她很信任我。我似乎很讨猫喜欢啊…\", \"voicelineId\": 94021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_teammate_charlotte_01\", \"description\": \"有次夏洛蒂来店里想采访我，我说别了又没什么新鲜事。结果她刚一出门，就有个醉汉来店里闹事，被她记录下了全程…真是见了鬼了。只听说过记者追新闻，现在还有新闻会追记者？\", \"voicelineId\": 94022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏沃蕾…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_teammate_chevreuse_01\", \"description\": \"和夏沃蕾的合作与谈话都很省力。这导致每次跟她告别，重新面对顾客的时候，我都有种不适应的感觉。\", \"voicelineId\": 94023, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾梅莉埃…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_teammate_emilie_01\", \"description\": \"艾梅莉埃的香水很受欢迎。出于商业合作，我会请她将试做中的香水小样送到「千织屋」，让爱洛芙悄悄喷在顾客们使用的试衣间，然后我再将顾客们的反馈告诉她。但这么长时间下来，没有一位顾客说我试衣间里的味道奇怪，反倒是纷纷来问我店里的香水哪里有卖。出于好奇，每次她发售香水成品的时候，我也会买一瓶来闻闻。不得不说，那种每次都能品出新鲜感的香味，实为天才之作。\", \"voicelineId\": 94024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱欧斯利…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_teammate_wriothesley_01\", \"description\": \"一些朋友和合作者向我聊起过他，我很佩服他的手腕，但我也没打算改变自己的做事方式。\", \"voicelineId\": 94025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于绮良良…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_teammate_kirara_01\", \"description\": \"从前在稻妻，我到野外找设计灵感的时候，总有只绿眼睛的猫喜欢跟在我身边。那家伙好像对我手上布料的颜色和花纹很感兴趣，心情好了还会蹭蹭我的小腿。\\n后来，我一眼就认出了这个绿眼睛、背后还长着两条尾巴的女孩。她看那些新奇东西的眼神，这么多年就没有变过。\", \"voicelineId\": 94026, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_teammate_ayaka_01\", \"description\": \"如果不是儿时贪玩，我恐怕也不会有机会认识这位神里家的大小姐。有次我翻进了神里家的院子，她的手鞠恰好滚到墙边。她见到我时既惊讶又兴奋，我陪她玩了好一会儿，又聊了很久的天…但最后我还是被人发现了，于是这短暂的友情就以我被人提了出去而告终。\", \"voicelineId\": 94027, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解千织·其一\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_friendship_01\", \"description\": \"我自认为脾气没有人们说的那么差，我只是不喜欢在破事上浪费时间而已。但不知是什么原因，那些「破事」总是缠着我不放。久而久之，就落得了个不好的名声，我才想叫冤枉呢。\", \"voicelineId\": 94028, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解千织·其二\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_friendship_02\", \"description\": \"我从小就不喜欢被管教，有段时间特别讨厌「规矩」这东西，一定要和它对着干。托这倔脾气的福，我吃了不少苦头。但后来我渐渐明白，「规矩」不全是坏事。我真正讨厌的，是那种不能按自己想法做出决定的感觉。\", \"voicelineId\": 94029, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解千织·其三\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_friendship_03\", \"description\": \"小时候最期待的，就是家乡夏日的祭典。每到那时，人们就会穿上最好看的衣服上街…\\n腰带上五颜六色的水球、怎么都捞不起的金鱼、还有甜到腻人的苹果糖和长野原家的烟花…那时玩得很开心，但回到家后，却总觉得少了什么。现在才知道，那时的我，是不想只做「观众」…\\n就像提到烟花，人们就想到「长野原」一样。我希望有一天，人们想穿上祭典的，都是「千织屋」的衣服。\\n…哈，光是这么想想，就感觉心中充满激情。嗯，我要回店里做衣服去了。\", \"voicelineId\": 94030, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解千织·其四\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_friendship_04\", \"description\": \"虽然工作起来很投入，但我也喜欢享受当下的时光。闲下来的时候，我会一个人带上些吃的，找个风景好的地方静静睡个午觉，晚上再听些喜欢的音乐，美美睡去…有时候则是叫上朋友们吃顿饭，大家在一起谈天说地，开个不醉不归的派对…想怎么做全看当时的心情。正如「时尚」只存在于「当下」一样，我也喜欢活在当下。怎么样？不如今晚我们就出去狠狠放松一下？\", \"voicelineId\": 94031, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解千织·其五\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_friendship_05\", \"description\": \"我喜欢稻妻的点心、喜欢清淡的食物…我喜欢家乡布料的触感、喜欢每天结束后泡个澡…但我也喜欢枫丹温柔的海水、喜欢海里美不胜收的景色…\\n我常常会想，自己是否并没有摆脱「过去」对我造成的影响，是否今天的一切都是命中注定…\\n但那又如何呢？我就是我，活在此刻。就算过去的一切塑造了如今的我，未来的路，也依旧由我自己选择，谁都无法改变这点。\", \"voicelineId\": 94032, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"千织的爱好…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_pref_hobby\", \"description\": \"我在工作中追寻梦想，在爱好中探索自由。如果我每天做的事不是自己热爱的，那还有什么意思？\", \"voicelineId\": 94033, \"voicelineType\": \"6001\"}, {\"title\": \"千织的烦恼…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_dialog_annoyed_01\", \"description\": \"我偶尔烦恼，追求理想的进度比预期更缓慢，这样下去不知我的品牌什么时候才能风靡世界。但我绝不会向现实妥协，烦恼又有什么帮助呢？还不如省下这个时间，多做几件衣服。\", \"voicelineId\": 94034, \"voicelineType\": \"6012\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_pref_foodLike\", \"description\": \"我忘不了小时候吃过的那些稻妻点心。但比起品尝时的喜悦，我更享受制作的过程。要不是布料的色彩与变化更丰富一些，恐怕这世上，就要多一个点心师傅了。\", \"voicelineId\": 94035, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_pref_foodDislike\", \"description\": \"就拿羊杂哈吉斯举例吧，我吃不惯味道浓厚的菜。就像是好好地走在路上，冷不防被岩飘浮灵糊了一脸一样…我这么形容你能理解吧？\", \"voicelineId\": 94036, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_spice_pref_01\", \"description\": \"嗯，这味道我很喜欢，下次再带给我点。放心，我也会给你回礼的。\", \"voicelineId\": 94037, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_spice_normal_01\", \"description\": \"不错的手艺，适合工作累了之后，坐在店里慢慢品尝。\", \"voicelineId\": 94038, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_spice_dislike_01\", \"description\": \"这味道我不喜欢，下次换个清淡点的。\", \"voicelineId\": 94039, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_pref_birthday_01\", \"description\": \"生日快乐。我懒得猜了，想要什么礼物就直说。嗯？太直接了？好吧，那就叫上娜维娅和绮良良她们，再约几个你的朋友，晚上来「千织屋」开派对。我参考参考他们会送你什么，然后当场做一个适合你的首饰送给你，保证你喜欢。我有这个自信。\", \"voicelineId\": 94040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_starUp_01\", \"description\": \"…不行，还是太普通。\", \"voicelineId\": 94041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_starUp_02\", \"description\": \"…还不错，但少了点引人驻足的亮点。\", \"voicelineId\": 94042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_starUp_03\", \"description\": \"…好，我抓到我想要的了。\", \"voicelineId\": 94043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_chiori/vo_chiori_starUp_04\", \"description\": \"我的手是不会抖的，这是我的专业性…但我得承认，此时此刻我的心跳声实在有些吵了。感谢你一路帮助我完成我的作品，它对我有着无比重要的意义。今后的路，我会更有把握。\", \"voicelineId\": 94044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_battle_skill1_01\", \"description\": \"袖。\", \"voicelineId\": 94045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_battle_skill1_02\", \"description\": \"下一位？\", \"voicelineId\": 94046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_battle_skill1_03\", \"description\": \"搭把手。\", \"voicelineId\": 94047, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_battle_skill3_01\", \"description\": \"风尚，由我裁定。\", \"voicelineId\": 94048, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_battle_skill3_02\", \"description\": \"脆如绸锦。\", \"voicelineId\": 94049, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_battle_skill3_03\", \"description\": \"千红零落。\", \"voicelineId\": 94050, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_chest_open_01\", \"description\": \"这工艺还行吧，我做过比这更好的。\", \"voicelineId\": 94051, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_chest_open_02\", \"description\": \"原来你喜欢这种？\", \"voicelineId\": 94052, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_chest_open_03\", \"description\": \"嗯…我参考参考。\", \"voicelineId\": 94053, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_life_less30_01\", \"description\": \"衣服都破了…\", \"voicelineId\": 94054, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_life_less30_02\", \"description\": \"闹够了没有…\", \"voicelineId\": 94055, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_life_less30_03\", \"description\": \"得给你点教训…\", \"voicelineId\": 94056, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_life_less30_teammate_01\", \"description\": \"喂，别逞强。\", \"voicelineId\": 94057, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_life_less30_teammate_02\", \"description\": \"我可不做寿衣。\", \"voicelineId\": 94058, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_life_die_01\", \"description\": \"裁剪不当…\", \"voicelineId\": 94059, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_life_die_02\", \"description\": \"我不认输…\", \"voicelineId\": 94060, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_life_die_03\", \"description\": \"我的品牌…还没有…\", \"voicelineId\": 94061, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_battle_hit_L_02\", \"description\": \"就这点？\", \"voicelineId\": 94062, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_battle_hit_H_01\", \"description\": \"没品味的家伙…\", \"voicelineId\": 94063, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_chiori/vo_chiori_battle_hit_H_02\", \"description\": \"你惹错人了…\", \"voicelineId\": 94064, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_chiori_teamJoin_01\", \"description\": \"欢迎光临「千织屋」。\", \"voicelineId\": 94065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_chiori_teamJoin_02\", \"description\": \"需要定制服务吗？\", \"voicelineId\": 94066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_chiori_teamJoin_03\", \"description\": \"出门找找灵感吧。\", \"voicelineId\": 94067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000095, 'Sigewinne', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_draw_appear_01\", \"description\": \"怎么啦？别紧张，我是梅洛彼得堡的护士长希格雯，让我看看…这里疼吗？这里呢？哦哦…不是来看病的？那太好啦，呼…这么可爱，可要好好爱护身体，不要弄坏自己了哦。\", \"voicelineId\": 95000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·贴纸\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_character_idle_01\", \"description\": \"没有哦，我没有在你背后贴贴纸。\", \"voicelineId\": 95001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·关心\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_character_idle_02\", \"description\": \"啊呀！哪里磕着碰着了吗？不舒服要随时叫我哟。\", \"voicelineId\": 95002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·保养\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_character_idle_03\", \"description\": \"保养身体很重要，同样不能忽视的，是保养好自己的内心。\", \"voicelineId\": 95003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_weather_heavyRain_01\", \"description\": \"啊…不知道那维莱特先生此刻在想些什么呢…\", \"voicelineId\": 95004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_weather_thunder_01\", \"description\": \"十分新奇，是只有在水面之上才能听到的声响。\", \"voicelineId\": 95005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_weather_snowy_01\", \"description\": \"买了一双新的防寒手套。看，美露莘的小圆手回来啦。\", \"voicelineId\": 95006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_weather_sunny_01\", \"description\": \"叮咚，来自「海露花」的小提示：晒太阳前先涂好防晒霜可以保护皮肤哟。\", \"voicelineId\": 95007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_weather_desert_01\", \"description\": \"请注意补充水分哦。还好那维莱特先生有爱喝水的好习惯。\", \"voicelineId\": 95008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_greetingMorning\", \"description\": \"早上好，睡得好吗？洗脸的时候建议用温水，这样对皮肤的刺激最小。\", \"voicelineId\": 95009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_greetingNoon\", \"description\": \"啊呀，午饭时间快到了，我得暂时离开一下下。嘘…请替我保守秘密哦。\", \"voicelineId\": 95010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_greetingNight\", \"description\": \"几点啦？在水下待久了，下意识要看看钟表才能区分白天黑夜了…不哦，我不觉得压抑，与其说习惯了…不如说我喜欢黑漆漆的地方。\", \"voicelineId\": 95011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_greetingNight2\", \"description\": \"感觉入睡很困难？照理说…你的身体没有异样。唔…明白了。来聊聊心事吧，一起试着找出阻碍你休息的病源。\", \"voicelineId\": 95012, \"voicelineType\": \"1004\"}, {\"title\": \"关于希格雯自己·双手\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_idle\", \"description\": \"我很喜欢人类的双手，不管是剪绷带还是拿针管都很灵活，麻醉枪拿起来也特别趁手。\", \"voicelineId\": 95013, \"voicelineType\": \"2001\"}, {\"title\": \"关于希格雯自己·「海露花」\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_idle2\", \"description\": \"「海露花」是我在《花容美谭》撰稿用的笔名，这个名字其实是大家票选出来的。当时我跟几位美露莘朋友拟了三个备选项，贴在公告板上请大家投票。事实证明，在人类的审美中，比起「坚盾重甲蟹」和「泡泡雄海马」，「海露花」更能跟美容护肤的主题挂钩呢。\", \"voicelineId\": 95014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·招呼\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_close\", \"description\": \"嗨嗨~嗯？似曾相识的动作？呵呵，看来你已经见过一些美露莘朋友了。没错哦，身体微微前倾，迅速地摆摆手…这样打招呼表示友好，你好你好呀。\", \"voicelineId\": 95015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·信任\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_close1\", \"description\": \"我记得的哦，你不喜欢苦味所以把药剂藏起来没有喝。其实，后来我请你吃的那盒糖果里，除了糖丸还有我掺进去的药丸，经过重新调制，苦味应该不明显…你说你当时就尝出来了？哈…谢谢你，愿意这样信任我。那么，以后我也会继续为你的健康着想，也请你继续乖乖配合啦。\", \"voicelineId\": 95016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_pendant_01\", \"description\": \"神之眼能让我更轻松地放倒阻碍，抢回不少宝贵的治疗时间。会有什么阻碍？根据经验…有些是不怀好意想要阻挠治疗的人，有的是不肯配合的患者本人…不过除了个别极端情况外，我更倾向于借助它的力量制造轻盈多彩的泡泡，安抚身心之余又可以点缀氛围，在泡泡的环绕下我和美露莘朋友们拍出过不少好看的画片呢。\", \"voicelineId\": 95017, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_share_01\", \"description\": \"人类在生病时会变得尤其脆弱。平时会叫嚣着去拳力斗技场比试的高高大大的人，被告知需要打针时也会露出膨膨兽一样的表情。我准备了很多糖果和贴纸来安慰这类爱哭的病人，每次都十分奏效，他们脸上很快就阴雨转晴了。\", \"voicelineId\": 95018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_pref_gift_01\", \"description\": \"喜欢游泳吗？梅洛彼得堡外面的水域，同样是黑漆漆、乱糟糟的，我猜你也喜欢吧。啊，眉间的肌肉收紧了，说明你有点为难…明白了，那我们去塞洛海原潜泳吧！好久没去看悠悠海獭玩耍了，我可以看一整天。但请注意不要伤害它们，也不要抢它们手上的小贝壳哦。\", \"voicelineId\": 95019, \"voicelineType\": \"3003\"}, {\"title\": \"关于那维莱特·敬爱\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_neuvillette_01\", \"description\": \"那维莱特先生将美露莘们带来枫丹廷，给我们安排了合适的工作。我们跟他一起尝试着融入枫丹，发掘着人类的美好。就我而言，我非常敬爱他，也很喜爱人类。嗯？你问那维莱特先生和人类同时掉进水里先救谁？很简单，他一定会跟我一起合力救人类上岸哦。\", \"voicelineId\": 95020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特·眷属\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_neuvillette_02\", \"description\": \"美露莘是那维莱特先生的眷属，但不代表他会给予我们超出律法和公正的偏爱。当初我乖乖接受了那维莱特先生的审判，我认同他的判决。还记得出发去梅洛彼得堡那天下了好大好大的雨，但我一点都不觉得雨点冰冷，反而非常温润，就像那维莱特先生的目光一样…\", \"voicelineId\": 95021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14030], \"unlockText\": \"完成「谎言的温度」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱欧斯利…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_wriothesley_01\", \"description\": \"公爵是我见过最能忍受疼痛的人，那时他还没这么高大和强壮，每次来医务室缝合伤口时都拒绝打麻醉针，说着要保持清醒之类的话，真是个很了不起的小大人呢。现在嘛，当然是个了不起的大大人咯。\", \"voicelineId\": 95022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_clorinde_01\", \"description\": \"克洛琳德小姐讲话时不会有太多面部表情，很难通过她的面部神态读懂她的心情…你说她用了我送的唇膏？真的吗？呵呵，她能喜欢那真的太好了，那个颜色果然很适合她对吧！\", \"voicelineId\": 95023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于娜维娅…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_navia_01\", \"description\": \"枫丹美容协会定期会举办交流会，我很珍惜跟大家聊天的机会。大部分人听到我的夸赞后都会低着头红着脸说哪有哪有，只有娜维娅小姐每次都会高兴大方地接受夸奖，然后握着我的手邀请我一起合影留念。她就像株光芒四射的黄玫瑰，不管白天黑夜晴天阴天都那么的耀眼呢。\", \"voicelineId\": 95024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_charlotte_01\", \"description\": \"我喜欢看夏洛蒂小姐拍的画片，可以很好地观察到大家在不同情景下的面部肌肉，紧绷的、松弛的、上扬的、垮下来的…嘿嘿，非常值得回味。\", \"voicelineId\": 95025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_lyney_01\", \"description\": \"我很抱歉对林尼先生打出了那枪麻醉针…在当时那种紧急的情况下，那的确是让他受到最少伤害的办法…庆幸的是，后来他了解到我没有恶意后，也放心地让我治疗了菲米尼先生。\", \"voicelineId\": 95026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琳妮特…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_lynette_01\", \"description\": \"琳妮特小姐兼具了人类和猫猫的双重可爱！我稍微观察了一下，她在喝茶和吃蛋糕时耳朵会微微向前，呵呵，真想摸摸她的头…你也一样？下次我们一起去征求她的同意吧？\", \"voicelineId\": 95027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲米尼…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_freminet_01\", \"description\": \"他的身体恢复后主动找到了我道谢，是个很有礼貌的孩子呢。讲话轻声细语的…看得出平时大概不太擅长主动跟别人打交道，但我能感受到他的内心世界一定非常丰富而细腻，因为他仔细地翻看了美露莘们画的画，看得极其入神。\", \"voicelineId\": 95028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于千织…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_chiori_01\", \"description\": \"美露莘的身体跟人类不同，很难买到合适的衣服。就算是我，试穿人类的童装时也会烦恼尾巴应该怎么摆放…不过好在千织小姐推出了针对美露莘的定制服务，现在所有美露莘朋友都有机会穿上喜欢的漂亮衣服啦。\", \"voicelineId\": 95029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾梅莉埃…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_teammate_emilie_01\", \"description\": \"艾梅莉埃小姐设计的香水经常登上各种美容杂志的推荐榜单上。我已经计划好了，下次休假我会提早结束在沫芒宫的拜访，抽出时间在枫丹廷好好逛逛，多买一些艾梅莉埃小姐的香水回去，送给可爱的女孩子们，嘻嘻。\", \"voicelineId\": 95030, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解希格雯·其一\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_friendship_01\", \"description\": \"在我的医务室，没有什么「负罪的人在他应在的路上」，只有「生病的人在他应躺的床上」。不管是谁，把身体养好了才能继续坐牢赎罪不是吗？\", \"voicelineId\": 95031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解希格雯·其二\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_friendship_02\", \"description\": \"很多病痛都是累积而来的，平时爱护身体至关重要，可惜很少人懂得这个道理。明明累得眼睛都快睁不开了，还要咬着牙在生产区工作…我只好悄悄给他们加餐，如果还是不肯乖乖休息，使用麻醉枪之类的强硬治疗手段也是没有办法的事。唉，特许券是赚不完的，还是不要勉强自己为妙哦。\", \"voicelineId\": 95032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解希格雯·其三\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_friendship_03\", \"description\": \"工作不忙的时候我会邀请奥蒂涅和梅莘她们来医务室喝茶，我们有时会聊最近的案件，有时聊美容杂志上推荐的护肤品，更多的时候会一起画画，把我们觉得可爱的东西画下来做成贴纸，再找机会送给可爱的人…啊，请稍等一下，我这里有一张要送给你。\", \"voicelineId\": 95033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解希格雯·其四\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_friendship_04\", \"description\": \"在很久以前的枫丹，人类跟美露莘的关系并不像今天这样融洽。有些人听说美露莘是从厄里那斯的血肉中诞生的，对我们又恨又怕…有的人出于对那维莱特先生的不信任，连带不会相信美露莘…还有的人也许并没有想太多，光是看我们跟人类长得不一样，就会下意识疏远…那个时候想跟人类做朋友真的是很困难的事情呢，所以我很珍惜那位明知我是美露莘还愿意牵起我的小圆手的人类女孩…\", \"voicelineId\": 95034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14030], \"unlockText\": \"完成「谎言的温度」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解希格雯·其五\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_friendship_05\", \"description\": \"我的老师告诫过我「医生最大的责任是治好自己能治好的病」。我明白医生不是神明，再了不起的医生也会有攻克不了的疾病。但没关系，美露莘的生命很长，只要我不断钻研医术，我能治好的病就会越来越多，病痛的苦难就会越来越少。我会以老师为榜样，用尽我所掌握的医术去救我能触及的人…只要结局是好的，只要没伤害别人，我愿意采用任何手段，并承受过程中产生的风险。\", \"voicelineId\": 95035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14030], \"unlockText\": \"完成「谎言的温度」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"希格雯的爱好…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_pref_hobby\", \"description\": \"在我读过的所有书里，我最喜欢《笑的意义》，里面提到的知识不仅有趣，还能在日常中很好地辅助我诊断病情。比如，有些人从拳力斗技场出来时，嘴上挂着笑但脸上其他肌肉都非常扭曲，这种笑通常是为了掩饰自己挨完揍的伤痛。遇到这种情况就请悄悄地叫他来我这包扎吧。不过记得要「悄悄地」，否则他的强颜欢笑就失去「笑的意义」了，嘻嘻。\", \"voicelineId\": 95036, \"voicelineType\": \"6001\"}, {\"title\": \"希格雯的烦恼…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_dialog_annoyed_01\", \"description\": \"奇怪。储藏间的空间越来越不够用了，机关零件快放不下了。我明明还挺会收纳东西的呀？嗯嗯…看来得找个时间跟公爵商量一下扩容的问题了呢。\", \"voicelineId\": 95037, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_pref_foodLike\", \"description\": \"好的食材有很多，各有各的营养价值，我想了一个把它们全部混在一起的好办法，要尝尝我特制的营养奶昔吗？\", \"voicelineId\": 95038, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_pref_foodDislike\", \"description\": \"喝茶虽好，但过量的话对健康是弊大于利的。唉，这个道理我跟公爵说过很多遍了…\", \"voicelineId\": 95039, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_spice_pref_01\", \"description\": \"能尝出来用了很多新鲜的食材…嗯，说不定可以将这些绞碎加进营养奶昔里…\", \"voicelineId\": 95040, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_spice_normal_01\", \"description\": \"要是韦尔赛先生能有你这位助手做帮厨，美味料理的占比一定能大大提升。\", \"voicelineId\": 95041, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_spice_dislike_01\", \"description\": \"这是给我的「加餐」吗？很感谢哦，你愿意跟我一起分享吗？\", \"voicelineId\": 95042, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_pref_birthday_01\", \"description\": \"生日快乐！根据我的观察，你平时要出入不同场合，所以我专门为你调制了一套兼顾便捷性和实用性的护肤套装。来来，请躺下，闭上眼睛，我来示范一次怎么用吧。先帮你湿敷一下脸蛋，平时要是赶时间，稍微把脸打湿就可以了哦…然后挤上适量的洁面膏，沿着肌肉走向轻轻打圈按摩再冲洗干净…最后一步，涂上加了汐藻成分的保湿霜…好啦，容光焕发，请可爱的人尽情享受属于你的节日吧！\", \"voicelineId\": 95043, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_starUp_01\", \"description\": \"今天也请继续对自己的可爱负责哦，别担心，我也会帮忙的。\", \"voicelineId\": 95044, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_starUp_02\", \"description\": \"没看错哦，满足的时候美露莘的尾巴会一摇一摆，真的很谢谢你送我这些。\", \"voicelineId\": 95045, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_starUp_03\", \"description\": \"哇…握麻醉枪的手更稳了，想试试单手开枪的准度…我们出门找些目标怎么样？\", \"voicelineId\": 95046, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_sigewinne/vo_sigewinne_starUp_04\", \"description\": \"也许美露莘和人类看到的世界不太一样，但我始终相信我们对情谊的感知是相通的，它是可以跨越种族的。请握住我的掌心，能感受到吗？我真心的温度。\", \"voicelineId\": 95047, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_skill1_01\", \"description\": \"别动哟。\", \"voicelineId\": 95048, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_skill1_02\", \"description\": \"我看看。\", \"voicelineId\": 95049, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_skill1_03\", \"description\": \"冷静。\", \"voicelineId\": 95050, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_skill1_04\", \"description\": \"吹泡泡。\", \"voicelineId\": 95051, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_skill1_05\", \"description\": \"晃悠悠。\", \"voicelineId\": 95052, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_skill1_06\", \"description\": \"飘乎乎。\", \"voicelineId\": 95053, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_skill3_01\", \"description\": \"谨誓！精研医理。\", \"voicelineId\": 95054, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_skill3_02\", \"description\": \"别紧张哦，放松。\", \"voicelineId\": 95055, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_skill3_03\", \"description\": \"医嘱：即刻注射。\", \"voicelineId\": 95056, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_explore_sprint_start_01\", \"description\": \"别摔跤哟。\", \"voicelineId\": 95057, \"voicelineType\": \"700001\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_chest_open_01\", \"description\": \"请尽量控制住笑肌哟。\", \"voicelineId\": 95058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_chest_open_02\", \"description\": \"如果有机关零件的话，能让给我吗？\", \"voicelineId\": 95059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_chest_open_03\", \"description\": \"可爱的人值得最好的宝物。\", \"voicelineId\": 95060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_life_less30_01\", \"description\": \"我能治疗自己！\", \"voicelineId\": 95061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_life_less30_02\", \"description\": \"还有止痛药。\", \"voicelineId\": 95062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_life_less30_03\", \"description\": \"没关系的…\", \"voicelineId\": 95063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_life_less30_teammate_01\", \"description\": \"看来得强制治疗了…\", \"voicelineId\": 95064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_life_less30_teammate_02\", \"description\": \"救援到了！\", \"voicelineId\": 95065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_life_die_01\", \"description\": \"还有病人在等我…\", \"voicelineId\": 95066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_life_die_02\", \"description\": \"好冷…好痛…\", \"voicelineId\": 95067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_life_die_03\", \"description\": \"治不好了…\", \"voicelineId\": 95068, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_hit_L_02\", \"description\": \"不。\", \"voicelineId\": 95069, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_hit_H_01\", \"description\": \"生气了！\", \"voicelineId\": 95070, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_sigewinne/vo_sigewinne_battle_hit_H_02\", \"description\": \"你不可爱！\", \"voicelineId\": 95071, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_sigewinne_teamJoin_01\", \"description\": \"我来负责监测健康吧。\", \"voicelineId\": 95072, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_sigewinne_teamJoin_02\", \"description\": \"麻醉剂…嗯，够了。\", \"voicelineId\": 95073, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_sigewinne_teamJoin_03\", \"description\": \"打扰了哟。\", \"voicelineId\": 95074, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000096, 'Arlecchino', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_draw_appear_01\", \"description\": \"我是愚人众执行官第四席，「仆人」阿蕾奇诺，也是壁炉之家的孩子们口中的「父亲」。希望我们相处愉快——这并非什么难事，现在的我们还没有冲突的理由，不是吗？\", \"voicelineId\": 96000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·眼睛\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_character_idle_01\", \"description\": \"不要一直盯着我的眼睛，不保证你会看到什么。\", \"voicelineId\": 96001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·家庭\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_character_idle_02\", \"description\": \"孩子们在做什么？算了，由他们去吧。\", \"voicelineId\": 96002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·汇报\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_character_idle_03\", \"description\": \"有事情向我汇报？说吧，我在听。\", \"voicelineId\": 96003, \"voicelineType\": \"1103\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_weather_thunder_01\", \"description\": \"无需畏惧，雷光也要避让我们。\", \"voicelineId\": 96004, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_weather_snowy_01\", \"description\": \"身处寒冷之中，人们才会怀念火焰的温暖。\", \"voicelineId\": 96005, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_weather_sunny_01\", \"description\": \"这个天气更适合待在树荫下。\", \"voicelineId\": 96006, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_weather_gale_01\", \"description\": \"不要轻易讲述自己的秘密，你不知道风会把它们带去什么地方。\", \"voicelineId\": 96007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_greetingMorning\", \"description\": \"早安，今天有什么计划吗？\", \"voicelineId\": 96008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_greetingNoon\", \"description\": \"正午回到家，总能见到孩子们横七竖八地睡在地上。这个时间很容易犯困，休息一下再走吧。\", \"voicelineId\": 96009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_greetingNight\", \"description\": \"有人说月亮就像俯瞰人间的眼睛，只是我们已经习惯被它注视。\", \"voicelineId\": 96010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_greetingNight2\", \"description\": \"睡觉的时间到了。「睡不着」？那你得自己想想办法了。我猜你不会喜欢我的方案。\", \"voicelineId\": 96011, \"voicelineType\": \"1004\"}, {\"title\": \"关于自己·认知\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_idle\", \"description\": \"清醒地认识自己并不容易。通常来说，做不到的人反而活得比较开心。\", \"voicelineId\": 96012, \"voicelineType\": \"2001\"}, {\"title\": \"关于自己·冷血\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_idle2\", \"description\": \"偶尔，我会听到其他人在暗处的议论，说我是个感情淡漠、手段狠辣的人。对此我无意澄清，偏见会将真相包裹起来，对我来说是件好事。不过，我确实需要采取一些手段，来「满足」他们的期待…希望他们有足够的实力和地位，能从我手上活下来。\", \"voicelineId\": 96013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·让步\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_close\", \"description\": \"你我所持理念不尽相同，想要并肩而行，彼此都要做出让步。我可以分享一些秘密，至于隐瞒的那部分——不要深究，这也是为了你好。\", \"voicelineId\": 96014, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·做客\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_close1\", \"description\": \"孩子们很喜欢听你讲故事。时常问我你什么时候会再来。期望落空总需要支付代价，希望你能将它纳入到考虑之中。\", \"voicelineId\": 96015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_pendant_01\", \"description\": \"很长时间里，我没有什么愿望，直到某天产生了「刺杀库嘉维娜」的想法。这个主意当时看来很荒诞，毕竟她是成名已久的执行官，而我的武艺几乎都是她教出来的。\\n不过神明似乎只看愿望是否强烈，最终我得到了神之眼，在付出一些代价之后，成功掌控了这份力量。徒弟想要战胜老师，总要做出些意料之外的事情。\", \"voicelineId\": 96016, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14026], \"unlockText\": \"完成「炉火熄灭之际」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_share_01\", \"description\": \"「火焰如血液般在我的身体中流淌」…对普通人来说，这是一句蹩脚的小诗，对我来说却是一种无奈的现实。\", \"voicelineId\": 96017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻·极光\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_pref_gift_01\", \"description\": \"至冬的极光很美丽，可以去看看。\", \"voicelineId\": 96018, \"voicelineType\": \"3003\"}, {\"title\": \"感兴趣的见闻·蜘蛛\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_pref_gift_02\", \"description\": \"我曾养过一只叫「斑比」的蜘蛛。饲养蜘蛛是件有趣的事情，相较于猫狗一类的宠物，蜘蛛是养不熟的。它并不会给你回报，你也不会在它身上寄托多余的情感。这样的关系对我正好。\", \"voicelineId\": 96019, \"voicelineType\": \"3004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_lyney_01\", \"description\": \"克雷薇曾问过我一个问题：什么是真正的「家」？我无法回答，因为构成壁炉之家的，正是一群「无家可归」的人。\\n我否定家中不合理的地方，制定新的规矩，杀死库嘉维娜，成为了孩子们的「父亲」。但我很清楚，这仍然算不上真正的家。我会把这个问题保留下去。期待有一天，林尼能够给我全新的答案。\", \"voicelineId\": 96020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14026], \"unlockText\": \"完成「炉火熄灭之际」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于琳妮特…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_lynette_01\", \"description\": \"沉静的性格是琳妮特的特点，也是她的优势。我相信她足够聪明理解到这一点。她在那支小队中有着无可替代的作用，而这么做，也令她感到幸福。作为「父亲」，我会给她足够的空间施展才华。\", \"voicelineId\": 96021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲米尼…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_freminet_01\", \"description\": \"菲米尼的内心非常复杂，藏着各种各样的感情。他会将许多无关的问题归因到自己，并为此感到很难过，其他孩子未必能理解他在想什么。我注意到你的情感也很细腻，或许你能和他成为很好的朋友。\", \"voicelineId\": 96022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_neuvillette_01\", \"description\": \"工作，以及私下，那维莱特先生刻意维持着一种「距离感」。很多人说他不近人情，我认为恰恰相反，就像律法的冰冷源于其庇护众生的公平，这本质上是一种特殊的善意。\", \"voicelineId\": 96023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_furina_01\", \"description\": \"我托林尼帮忙带去了一些蛋糕，分给剧团的人做茶点。蛋糕是孩子们亲手做的，用「热心观众」的名义赠送，希望她喜欢。\", \"voicelineId\": 96024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「女皇」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_tsaritsa_01\", \"description\": \"在我入狱时，是女皇大人赦免了我的罪过，赐予我执行官的身份。相较于伪善之人冠冕堂皇的话术，我能从她身上感受到真正的「慈爱」。然而…这份慈爱能否融化辽阔的冰雪，没有人清楚答案。我只知道，如果有一天我们被迫决裂，我会毫不犹豫地向她挥剑，这是我能给出的最高敬意。\", \"voicelineId\": 96025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「丑角」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_jester_01\", \"description\": \"作为最初的执行官，他的一切都很神秘。初次见面他就能轻易看出我的身世，而我时至今日仍然对他所知甚少。\", \"voicelineId\": 96026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「队长」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_capitano_01\", \"description\": \"他所拥有的力量让他背负着更多的责任，不过在我看来，即使没有强悍的力量，他仍然是一位值得尊敬的人。\", \"voicelineId\": 96027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「博士」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_dottore_01\", \"description\": \"我刚接手壁炉之家，他就向我提出了许多合作计划，让我将「淘汰的孩子」交给他去做实验，他则向我共享实验成果。听说他跟前代「仆人」合作得很愉快，如果不是同为执行官，我很想送他去见前代「仆人」。\", \"voicelineId\": 96028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「少女」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_damselette_01\", \"description\": \"她是一位非常特别的执行官。如果你向她提问，她不会给你「预料之中的回答」，有时甚至不会给出「正式的回答」，但那一定是个「有趣的回答」。\", \"voicelineId\": 96029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「公鸡」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_pulcinella_01\", \"description\": \"就像「公鸡」先生不喜欢我一样，我对他也没什么好印象。他是一位合格的市长，甚至可以用出色来形容。他能用很小的代价换取巨大的收益，在政要圈子中广受好评。可惜这「很小的代价」中经常出现壁炉之家的影子，我们早晚…哼。\", \"voicelineId\": 96030, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「木偶」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_marionette_01\", \"description\": \"我对她没什么兴趣。她热衷于研究，很少公开露面，许多士官甚至都没有见过她。相较于另一个把自己切成很多份、满世界乱跑的人，她算是另一个极端。\", \"voicelineId\": 96031, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「富人」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_pantalone_01\", \"description\": \"不可否认，他既有想法也有手腕，但我认为他并不「清醒」。他可以制定宏伟的计划、操控冰冷的经济，但驱使他行动的仍是内心深处压抑的仇恨与憎恶。理性的人往往自认为能控制情感，这种自信就是最大的弱点。\", \"voicelineId\": 96032, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「女士」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_signora_01\", \"description\": \"她与皮耶罗是我最先认识的两位执行官。她第一次来壁炉之家做客，一副趾高气昂的做派，不受孩子们喜欢。那之后她每次来访都会带些礼物，堂而皇之地表示「不喜欢我的人没份」。为了礼物，孩子们很快学会了逢场作戏，她也照单全收。我猜测她很享受孩子们围在身旁的感觉，这或许源于她内心的孤独…对于她的牺牲，我深感遗憾，愿她能与死去的爱人重逢。\", \"voicelineId\": 96033, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「公子」…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_teammate_tartaglia_01\", \"description\": \"平心而论，他的性格并不适合做执行官。他常以善意揣测别人，也常被别人利用。当然，他的天赋很好，仍然在不断成长，对他的评价不必急于一时。\", \"voicelineId\": 96034, \"voicelineType\": \"4015\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解阿蕾奇诺·其一\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_friendship_01\", \"description\": \"想要了解我的事情？当然可以。本着互信的原则，我不会对你有太多隐瞒。不过你真的做好准备了吗？秘密比刀剑更锋利，危险往往源于不起眼的好奇心。\", \"voicelineId\": 96035, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解阿蕾奇诺·其二\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_friendship_02\", \"description\": \"当你刺出手中的利刃，你会意识到生命有不同的分量。有的人看似荣耀等身，却不过是一具无聊的空壳，临终前最后的思考仍是求饶与苟活。有的人外表平平无奇，灵魂却意外地沉重。即使如此，死亡对于每个人都是平等的。残酷？我只不过说了现实。\", \"voicelineId\": 96036, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解阿蕾奇诺·其三\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_friendship_03\", \"description\": \"雪奈茨维奇、雪奈茨芙娜…敢于在阴影中睁开明亮双眼的孩子们，敢于在火焰旁起舞的孩子们，我尽己所能，教他们如何面对生活。壁炉之家无需讨好他人，我们像蜘蛛那样狩猎。\", \"voicelineId\": 96037, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解阿蕾奇诺·其四\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_friendship_04\", \"description\": \"人们无法选择自己的出身，世界就是这样不公；但世界又是公平的，每个人都有抗争的权力。我收留孩子并非为了获得回报。只要愿意付出代价，想要离开的孩子可以追求新的生活。\", \"voicelineId\": 96038, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14026], \"unlockText\": \"完成「炉火熄灭之际」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解阿蕾奇诺·其五\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_friendship_05\", \"description\": \"命运是种很奇妙的东西。小时候，我就能使用一些特别的力量，「母亲」因此对我格外偏爱。但那时没有人知道这份力量的本质是什么——包括我自己，都将它视为延续在血脉中的诅咒。它让我变得强大，也给我带来痛苦。直到我成为执行官，才从「丑角」口中得知真相。他说自己很惊讶，原来「赤月」的血脉仍未断绝，而壁炉之家兜兜转转，居然又重新回到了赤月遗孤的手里。\\n命运会将我导向怎样的未来？总有一天它会给我答案。而我，也做好了斩破它的准备。\", \"voicelineId\": 96039, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"阿蕾奇诺的爱好…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_pref_hobby\", \"description\": \"空闲时，我会独自观察丛林中的昆虫。它们之间的博弈很有意思，捕食、竞争、合作…看似强大的个体未必能存活到最后，一着不慎就可能丢掉性命。我会把它垂死前的挣扎慢慢记下，一如我记下那些败者的结局。\", \"voicelineId\": 96040, \"voicelineType\": \"6001\"}, {\"title\": \"阿蕾奇诺的烦恼…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_dialog_annoyed_01\", \"description\": \"孩子们会讲很多只有彼此能听懂的流行词，就像执行任务用的暗语。他们需要一些安全的空间，对此，我充分理解。\", \"voicelineId\": 96041, \"voicelineType\": \"6012\", \"unlockConditions\": [{\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_pref_foodLike\", \"description\": \"家里会不定期举办烧烤晚会，食材交由孩子们自己准备。他们很喜欢参加这种活动，我也一样。毕竟谁都无法预料，下次举办晚会的时候，人群中又会减少哪些熟悉的面孔。\", \"voicelineId\": 96042, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_pref_foodDislike\", \"description\": \"我不喜欢调味复杂的食物，它们会让嗅觉与味觉变得迟钝。让食材保持原有的味道，也算是对它们的一种尊重。\", \"voicelineId\": 96043, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_spice_pref_01\", \"description\": \"好手艺，有兴趣来壁炉之家开烹饪课吗？\", \"voicelineId\": 96044, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_spice_normal_01\", \"description\": \"尝起来还不错，或许孩子们会喜欢。\", \"voicelineId\": 96045, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_spice_dislike_01\", \"description\": \"感谢你的一片心意，不过在味道上还有很大的提升空间。\", \"voicelineId\": 96046, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_pref_birthday_01\", \"description\": \"备忘录上写着今天是你的生日，对吗？生日还是要过得热闹些，人们总是需要理由让自己从繁忙的事务中抽出身，或是为自己庆祝，或是为别人庆祝。走吧，我在壁炉之家中准备了宴会，孩子们已经在等你了。\", \"voicelineId\": 96047, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_starUp_01\", \"description\": \"不要停下前进的脚步，也不要为力量所困。\", \"voicelineId\": 96048, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_starUp_02\", \"description\": \"愤怒带来冲动，伤感让人犹豫。时刻记住调整自己的心态。\", \"voicelineId\": 96049, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_starUp_03\", \"description\": \"有些人说我过于严格，事实上，我对自己也一样。\", \"voicelineId\": 96050, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_arlecchino/vo_arlecchino_starUp_04\", \"description\": \"这段时间我从你身上学到了许多，希望你也有所收获。就让我们继续保持这份友好关系吧…或许将来，我们会共同应对某些棘手的麻烦。\", \"voicelineId\": 96051, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_battle_skill1_01\", \"description\": \"贯穿。\", \"voicelineId\": 96052, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_battle_skill1_02\", \"description\": \"否决。\", \"voicelineId\": 96053, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_battle_skill1_03\", \"description\": \"展现。\", \"voicelineId\": 96054, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_battle_skill3_01\", \"description\": \"于此坠落。\", \"voicelineId\": 96055, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_battle_skill3_02\", \"description\": \"于此升起。\", \"voicelineId\": 96056, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_battle_skill3_03\", \"description\": \"如月长存。\", \"voicelineId\": 96057, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_chest_open_01\", \"description\": \"意外是最大的乐趣。\", \"voicelineId\": 96058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_chest_open_02\", \"description\": \"不错的收获。\", \"voicelineId\": 96059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_chest_open_03\", \"description\": \"纪念此刻的欢愉。\", \"voicelineId\": 96060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_life_less30_01\", \"description\": \"不错的进攻。\", \"voicelineId\": 96061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_life_less30_02\", \"description\": \"该反击了。\", \"voicelineId\": 96062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_life_less30_03\", \"description\": \"看来要再认真一点。\", \"voicelineId\": 96063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_life_less30_teammate_01\", \"description\": \"退后。\", \"voicelineId\": 96064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_life_less30_teammate_02\", \"description\": \"计划变更。\", \"voicelineId\": 96065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_life_die_01\", \"description\": \"炉火，熄灭了…\", \"voicelineId\": 96066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_life_die_02\", \"description\": \"我听见…孩子们的歌声…\", \"voicelineId\": 96067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_life_die_03\", \"description\": \"我不会接受这样的命运。\", \"voicelineId\": 96068, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_battle_hit_H_01\", \"description\": \"平庸。\", \"voicelineId\": 96069, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_arlecchino/vo_arlecchino_battle_hit_H_02\", \"description\": \"继续。\", \"voicelineId\": 96070, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_arlecchino_teamJoin_01\", \"description\": \"别担心，我会处理好。\", \"voicelineId\": 96071, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_arlecchino_teamJoin_02\", \"description\": \"遇到解决不了的麻烦了？\", \"voicelineId\": 96072, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_arlecchino_teamJoin_03\", \"description\": \"希望是一次有价值的合作。\", \"voicelineId\": 96073, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000097, 'Sethos', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_draw_appear_01b\", \"description\": \"这位{M#先生},{F#小姐}，是在叫我吗？你好你好，我叫赛索斯。你呢，找我有什么事吗？哎呀，也别干站着了，我知道一个适合坐下来聊天的好地方，跟我来吧。\", \"voicelineId\": 97000, \"voicelineType\": \"1006\", \"voicefile_male\": \"VO_friendship/VO_sethos/vo_sethos_draw_appear_01a\", \"hasGenderedVoicefile\": true}, {\"title\": \"闲聊·思考\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_character_idle_01\", \"description\": \"过度思考「为什么」很容易钻牛角尖，不如放过自己。\", \"voicelineId\": 97001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·动静\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_character_idle_02\", \"description\": \"你听到了吗？那边有动静。先下手为强，我想去凑凑热闹。\", \"voicelineId\": 97002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·上学\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_character_idle_03\", \"description\": \"教令院里面怪人真多，搞得我都想考进去上个学了。\", \"voicelineId\": 97003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_weather_heavyRain_01\", \"description\": \"沙漠里极少下雨，所以就让我享受一会儿这样的天气吧，不用帮我打伞啦。\", \"voicelineId\": 97004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_weather_thunder_01\", \"description\": \"糟了糟了糟了，快去地势低的地方…\", \"voicelineId\": 97005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_weather_snowy_01\", \"description\": \"嘶…快快快，跑起来，跑起来就不冷了！\", \"voicelineId\": 97006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_weather_sunny_01\", \"description\": \"天气真好，不找个地方露营可就太浪费了。走吗，一起去绿洲钓鱼？\", \"voicelineId\": 97007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_weather_desert_01\", \"description\": \"你试过在沙地上画画吗？从高处看会很壮观哦！就是要找个风小的地方。\", \"voicelineId\": 97008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_greetingMorning\", \"description\": \"早早早，要跟我去吃点东西吗？我从昨晚就惦记着做几个烤肉卷了。\", \"voicelineId\": 97009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_greetingNoon\", \"description\": \"现在喝咖啡的话，就没法享受午觉了哦。\", \"voicelineId\": 97010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_greetingNight\", \"description\": \"虽然沙漠白天没什么生机，但晚上总有很好看的星星。\", \"voicelineId\": 97011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_greetingNight2\", \"description\": \"睡了睡了，准备迎接明天的太阳！\", \"voicelineId\": 97012, \"voicelineType\": \"1004\"}, {\"title\": \"关于赛索斯自己·印象\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_idle\", \"description\": \"有些长辈说我像野生动物一样难以控制。倒不是说他们的印象有错，但首先，想要控制别人的想法有点不太对，你说是吧？\", \"voicelineId\": 97013, \"voicelineType\": \"2001\"}, {\"title\": \"关于赛索斯自己·首领\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_idle2\", \"description\": \"老实说，做首领还是有些压力的，更别提是在缄默之殿。不过和爷爷耳濡目染了这么多年，我清楚那些最不能让步的底线。而且经历了之前的决斗之仪，又认识了那么多新朋友，我也明白了缄默之殿之后要走的路在哪。放心吧，不会搞砸的。\", \"voicelineId\": 97014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [13039], \"unlockText\": \"完成「守诺者」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·闲聊\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_close\", \"description\": \"抱着想要和对方打好关系的目的刻意谈话，很容易陷入僵局。就像这样一起走走，随便聊聊，反而更容易熟悉起来呢。\", \"voicelineId\": 97015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·篝火\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_close1\", \"description\": \"夜晚的篝火，既能为人提供温度，又能防范野兽。你给我的感觉就像篝火一样。\\n说得太抽象了？哎呀，就是拿你当朋友的意思啦。\", \"voicelineId\": 97016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [13039], \"unlockText\": \"完成「守诺者」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_pendant_01\", \"description\": \"沙漠人获得神之眼时，大伙儿都会说这是谁谁的恩赐，具体人选视各自信仰而定。看一群人为了别人的神之眼争论赫曼努比斯大人和索贝克大人究竟谁更强，怪好玩的。\", \"voicelineId\": 97017, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_share_01\", \"description\": \"如果去沙漠旅行，夜间赶路是个不错的选择。气温确实寒冷，但可以避免在炎热的光照下流失过多水分。多带件衣服总比四处寻找水源方便多了。\", \"voicelineId\": 97018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_pref_gift_01\", \"description\": \"「悼灵花」这名字不知道是谁起的，还挺浪漫。换我来看，也许只会以为它是被太阳晒蔫了才垂头丧气的呢。\", \"voicelineId\": 97019, \"voicelineType\": \"3003\"}, {\"title\": \"关于赛诺…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_teammate_cyno_01\", \"description\": \"赛诺很优秀，无愧于赫曼努比斯力量的传承。作为「大风纪官」，他对知识与智慧有着至高的敬畏之心。如果教令院能与缄默之殿再次合作，有他在我会放心很多。\\n哦对了，他还有个难得的优点，就是讲话很好笑。\", \"voicelineId\": 97020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [13039], \"unlockText\": \"完成「守诺者」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_teammate_tighnari_01\", \"description\": \"提纳里挺厉害的。我后来才听说他不太适应沙漠的气候，决斗之仪那时可完全没看出来啊。我也没想到他会写信邀请我去化城郭做客，说是让我有机会见见赛诺的朋友们。你说，他们平常吃饭都会讲那种笑话吗？真期待！\", \"voicelineId\": 97021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [13039], \"unlockText\": \"完成「守诺者」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾尔海森和卡维…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_teammate_alhaitham&kaveh_01\", \"description\": \"我在酒馆见过他俩。也在咖啡馆见过。…好像在大巴扎也有一次。那位建筑师总是嘀嘀咕咕一些不想被别人知道的事情，但实际上嘛…哎，可不是我故意偷听，这样两位先生凑在一起，很难不引人注意吧。\", \"voicelineId\": 97022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于流浪者…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_teammate_wanderer_01\", \"description\": \"这位小哥，是不是外国来的留学生啊？帽子挺别致的。有次我想凑近了仔细看看，但眨眼的功夫他就咻地一下消失了。可惜，下次不会再让他跑了。而且听人说那哥们很有想法，我要和他多聊聊！\", \"voicelineId\": 97023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于迪希雅…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_teammate_dehya_01\", \"description\": \"「炽鬃之狮」，沙漠里人人都听说过这个名号。你也知道，镀金旅团里可不都是好人，像迪希雅这样正直可靠的就更少了。如果你要来大赤沙海探险，迪希雅是做向导第二好的人选。第一嘛，当然是我咯？\", \"voicelineId\": 97024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于坎蒂丝…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_teammate_candace_01\", \"description\": \"你被坎蒂丝招待过吗？她做饭超大份的，连我都差点没吃完。不过吃饭就好了，千万别吃她的拳头。\", \"voicelineId\": 97025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珐露珊…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_teammate_faruzan_01\", \"description\": \"很少见到比我还自来熟的人！在教令院附近闲逛时被她当成了新生，非要带我进去参观，还说什么现在加入知论派就能享受二十种语言教材大礼包，包教包会，吓我一大跳。问了别的学生才知道这是他们院的内部笑话，根本没有这种毕业要求。所以到底哪里好笑？只会让人更不想加入吧。\", \"voicelineId\": 97026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于妮露…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_teammate_nilou_01\", \"description\": \"我是个闲不住的人，但不介意在祖拜尔剧场多站一会儿，看看这位小姐的舞蹈。能让人内心宁静也是一种很难得的能力。\", \"voicelineId\": 97027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解赛索斯·其一\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_friendship_01\", \"description\": \"想打听事情？你找对人了。万一有我不知道的东西，也可以帮你四处问问。\", \"voicelineId\": 97028, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解赛索斯·其二\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_friendship_02\", \"description\": \"你要是有什么装备或者工具坏掉了，可以叫我来修。你问我是做什么工作的？哎呀，当然是无业游民了，不然哪有这么多闲工夫做手工呢。\", \"voicelineId\": 97029, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解赛索斯·其三\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_friendship_03\", \"description\": \"我喜欢徒步旅行。提前规划好路线，整理行囊，挑选好的日子踏上旅途，这种有条不紊的感觉很不错。当然，我不会把行程排得很满，也要享受突如其来的邂逅嘛。\", \"voicelineId\": 97030, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解赛索斯·其四\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_friendship_04\", \"description\": \"在大巴扎闲逛可有意思了。我会挑选各种香料混在一起，搭配现烤的肉类食用。我不会特意去记录配方，所以很多时候都是「一次性食谱」。怎么样，有没有兴趣尝尝这种限时限量、独一无二的美味？\", \"voicelineId\": 97031, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解赛索斯·其五\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_friendship_05\", \"description\": \"自记事起，我就在缄默之殿生活，老实说没有太多的选择。能承受赫曼努比斯的力量对个人而言不知是福多还是祸多，但确实为我的生活赋予了更崇高的意义。\\n人生中的遗憾有千千万，能圆满解决一件事，我就很满足了。现在我成了缄默之殿的新首领，赫曼努比斯之力也有了合适的归属，爷爷应该也很欣慰吧。\", \"voicelineId\": 97032, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [13039], \"unlockText\": \"完成「守诺者」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"赛索斯的爱好…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_pref_hobby\", \"description\": \"老是待在屋子里挺没意思的，无论天气好坏，我都喜欢出门跑跑。\", \"voicelineId\": 97033, \"voicelineType\": \"6001\"}, {\"title\": \"赛索斯的烦恼…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_dialog_annoyed_01\", \"description\": \"出远门前一定要做好准备，尤其是前往没去过的地方。当初第一次在树林里过夜不知道要带防潮垫，给我害惨了。\", \"voicelineId\": 97034, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_pref_foodLike\", \"description\": \"我喜欢调配香料，是为了能让肉变得更好吃，可不要本末倒置了哦。\", \"voicelineId\": 97035, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_pref_foodDislike\", \"description\": \"绿色植物是很养眼啦，但吃起来就…\", \"voicelineId\": 97036, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_spice_pref_01\", \"description\": \"好香好香好香。我食量有点大，你不介意吧？\", \"voicelineId\": 97037, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_spice_normal_01\", \"description\": \"真不错，怎么做的？下次徒步旅行我也弄点带上。\", \"voicelineId\": 97038, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_spice_dislike_01\", \"description\": \"唔…嗯…好像没什么味道，我再尝尝…\", \"voicelineId\": 97039, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_pref_birthday_01\", \"description\": \"你的头发…按照沙漠人的风格编一下应该会非常好看。马上就要步入人生新一年了，想不想试试新发型？怎么样，交给我，保证给你扎个魅力四射的。\", \"voicelineId\": 97040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_starUp_01\", \"description\": \"原来你们都是这样锻炼的吗？\", \"voicelineId\": 97041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_starUp_02\", \"description\": \"噢…原来连看三天书是这种感觉…\", \"voicelineId\": 97042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_starUp_03\", \"description\": \"厉害啊，感觉可以一口气从阿如村跑到赤王陵。不是开玩笑哦，要试试吗？\", \"voicelineId\": 97043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_sethos/vo_sethos_starUp_04\", \"description\": \"没想到你会帮我到这种地步。有时太依赖古老的智慧，会让人忘记自己和同伴本身的力量。谢谢你，让我回想起了这些。\", \"voicelineId\": 97044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"普通攻击·其一\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_battle_skill1_05\", \"description\": \"小心背后！\", \"voicelineId\": 97049, \"voicelineType\": \"120001\"}, {\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_battle_skill1_01\", \"description\": \"先手为赢。\", \"voicelineId\": 97045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_battle_skill1_02\", \"description\": \"打扰了！\", \"voicelineId\": 97046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_battle_skill1_03\", \"description\": \"各退一步如何？\", \"voicelineId\": 97047, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_battle_skill3_01\", \"description\": \"众贤的智慧。\", \"voicelineId\": 97051, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_battle_skill3_02\", \"description\": \"阿赫玛尔的遗荣！\", \"voicelineId\": 97052, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_battle_skill3_03\", \"description\": \"抱歉，你挡路了。\", \"voicelineId\": 97053, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_chest_open_01\", \"description\": \"快看看，有合你心意的东西吗？\", \"voicelineId\": 97054, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_chest_open_02\", \"description\": \"是旅途中的惊喜呢。\", \"voicelineId\": 97055, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_chest_open_03\", \"description\": \"啊！里面有怪物！…欸，不上当吗？\", \"voicelineId\": 97056, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_life_less30_01\", \"description\": \"不会认输的。\", \"voicelineId\": 97057, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_life_less30_02\", \"description\": \"还行，再撑一会儿…\", \"voicelineId\": 97058, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_life_less30_03\", \"description\": \"哎呀哎呀…\", \"voicelineId\": 97059, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_life_less30_teammate_01\", \"description\": \"换我了哦？\", \"voicelineId\": 97060, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_life_less30_teammate_02\", \"description\": \"逞什么强呢。\", \"voicelineId\": 97061, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_life_die_01\", \"description\": \"可惜，前功尽弃…\", \"voicelineId\": 97062, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_life_die_02\", \"description\": \"太阳…也会落下…\", \"voicelineId\": 97063, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_life_die_03\", \"description\": \"对不起了，爷爷…\", \"voicelineId\": 97064, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_battle_hit_L_02\", \"description\": \"好吧好吧。\", \"voicelineId\": 97065, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_battle_hit_H_01\", \"description\": \"别别别。\", \"voicelineId\": 97066, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_sethos/vo_sethos_battle_hit_H_02\", \"description\": \"哎哟，是我慢了！\", \"voicelineId\": 97067, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_sethos_teamJoin_01\", \"description\": \"来了来了。\", \"voicelineId\": 97068, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_sethos_teamJoin_02\", \"description\": \"好好好，听你的。\", \"voicelineId\": 97069, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_sethos_teamJoin_03\", \"description\": \"嗯，带好行囊了。\", \"voicelineId\": 97070, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000098, 'Clorinde', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_draw_appear_01\", \"description\": \"枫丹廷决斗代理人，克洛琳德，向你致意。如需雇佣我进行代理决斗，请先陈述你所陷之纠纷…无需赘述人情，这与我无关。\", \"voicelineId\": 98000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·对手\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_character_idle_01\", \"description\": \"我在决斗中遇见过不少对手，他们大部分都落败了，剩下的则主动投降…我有没有输过？没有。\", \"voicelineId\": 98001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·决斗代理人\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_character_idle_02\", \"description\": \"决斗代理人是我的职业，我怎么想并不重要。因为握紧长剑之时，我代表的是枫丹的律法与规则。\", \"voicelineId\": 98002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·制胜诀窍\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_character_idle_03\", \"description\": \"决斗是意志的对战，剑则是决斗者心灵的延伸。如果你的心已然畏缩，那你的剑也会如同裹鞘一般，无法斩败任何人。\", \"voicelineId\": 98003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_weather_heavyRain_01\", \"description\": \"猎物会在雨天休息，但猎人不能。\", \"voicelineId\": 98004, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_weather_afterRain_01\", \"description\": \"看来风和云的对决分出胜负了。\", \"voicelineId\": 98005, \"voicelineType\": \"1202\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_weather_thunder_01\", \"description\": \"希望世界上能少个恶徒。\", \"voicelineId\": 98006, \"voicelineType\": \"1203\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_weather_snowy_01\", \"description\": \"真新奇。但也够冷清的。\", \"voicelineId\": 98007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_weather_desert_01\", \"description\": \"我从来没这么想念过枫丹。\", \"voicelineId\": 98008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_greetingMorning\", \"description\": \"早上好。我正准备去喝杯咖啡，一起吗？我自带咖啡杯，如果你需要，我可以借你一个。\", \"voicelineId\": 98009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_greetingNoon\", \"description\": \"抱歉，现在还是我的工作时间。这份三明治给你，先吃点垫垫吧。\", \"voicelineId\": 98010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_greetingNight\", \"description\": \"很抱歉不能和你分享品酒心得，但我可以向你推荐几家颇具特色的冷门餐馆。\", \"voicelineId\": 98011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_greetingNight2\", \"description\": \"晚安。我维护好武器后也会休息。\", \"voicelineId\": 98012, \"voicelineType\": \"1004\"}, {\"title\": \"关于克洛琳德自己·新闻报道\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_idle\", \"description\": \"报纸上总是存在着一些谈不上公正，也绝不算正义的报道。撰写它们的人都被人情与摩拉带偏了心。\\n如果你想知道某件事的真相，最好的方法是去找相关的人，用你自己的嘴发问，用你自己的心去理解。\\n至少，别让其他人的舌头代替你的头脑。\", \"voicelineId\": 98013, \"voicelineType\": \"2001\"}, {\"title\": \"关于克洛琳德自己·铳枪与长剑\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_idle2\", \"description\": \"我的武器装备遵循逐影猎人的传统制式。铳枪用来驱赶猎物，长剑给予它们致命一击。\\n当然，代理决斗时我一般只用长剑，踏上决斗场的人已经无路可逃，用不着再做驱赶。\", \"voicelineId\": 98014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14034], \"unlockText\": \"完成「夜色无声」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·仪式\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_close\", \"description\": \"在每次决斗开始前，我会用浸了特制药水的软布擦拭武器，一方面是为了保养，另一方面是为了让自己保持沉静，排除杂念。\\n作为执剑者，你应该也有自己的仪式吧？\", \"voicelineId\": 98015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·人与魔影\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_close1\", \"description\": \"我的许多习惯都承袭自逐影猎人的传统。他们对抗的是邪恶魔物，而我对抗的则是不法凶徒。但魔物本就生来邪毒，这是它们的本能，那些堕落的人本来有行善的能力与机会，但他们却自寻恶孽。\\n你呢？你持剑的理由是什么？\", \"voicelineId\": 98016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_pendant_01\", \"description\": \"在我获得「神之眼」后，在决斗中向我投降的人数明显增加了不少。有的代理人说，这枚「神之眼」是我进行决斗时的「震慑手段」。\\n我还以为我从未败北的决斗战绩才是「震慑手段」，或许我以后的决斗应该赢得更有表现力一些。\", \"voicelineId\": 98017, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_share_01\", \"description\": \"我曾多次见证某些矛盾琐事，被当事人基于纯粹的感性反复咀嚼，最终演变成一桩事关人身尊严，不可退让的惊天耻辱，闹上审判庭，甚至引发一场荒诞的决斗。\\n作为决斗代理人，我对于用决斗来维护名誉这件事没有意见。但是…怎么说呢，从一个普通的枫丹市民角度来看，咖啡里到底该不该加茉洁草，实在不见得是一件非要用剑来论证的事情…\", \"voicelineId\": 98018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_pref_gift_01\", \"description\": \"见过蓬蓬果吧？它们飘飞的速度和位置不易捉摸，很适合作为枪靶练习射击。但是，去野外找蓬蓬果很不方便，要是有人愿意人工培育蓬蓬果就好了…\", \"voicelineId\": 98019, \"voicelineType\": \"3003\"}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_charlotte_01\", \"description\": \"夏洛蒂小姐是一位识趣的记者，我对她没什么坏印象。\\n毕竟，夏洛蒂小姐既不会在上班的路上堵截拍摄我，也不会跟踪我去咖啡馆，记录我今天喝了什么咖啡。最值得称赞的是，她明确地知道，我不接受记者采访，所以不会来自讨没趣。\", \"voicelineId\": 98020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于芙宁娜…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_furina_01\", \"description\": \"从前参加茶会的时候，我总是扶着剑站在她背后，现在我却能在长桌对面就座，与她分享茶点。\\n位置变化之后，我开始理解为什么她会成天念叨着「控制体态」了。\", \"voicelineId\": 98021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4025], \"unlockText\": \"完成「罪人舞步旋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于娜维娅…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_navia_01\", \"description\": \"娜维娅最近心情很好，隔几天就会拉我去「桌上剧团」玩新剧本。\\n选材五花八门。除了担任了几次剧本主持人，我也作为玩家和她共同参与了几场冒险。但我会尽量避免扮演和审判庭有关的角色，防止气氛变得太过严肃…\", \"voicelineId\": 98022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [14034], \"unlockText\": \"完成「夜色无声」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_neuvillette_01\", \"description\": \"最高审判官的权威无可置疑，他总是能做出最公正的判决。必要的时候，我也会用剑再次强调判决的公正性。\", \"voicelineId\": 98023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏沃蕾…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_chevreuse_01\", \"description\": \"夏沃蕾队长，我听说过她的大名。她曾经因为抓捕凶犯时的手段太过强硬，而遭到过几次起诉。她应诉时态度依然十分强硬，将对方驳得哑口无言，实在出色。\", \"voicelineId\": 98024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于林尼…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_lyney_01\", \"description\": \"这位大魔术师的职业素养值得称赞。如果有空的话，我会以观众的身份享受他的魔术表演。\", \"voicelineId\": 98025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于菲米尼…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_freminet_01\", \"description\": \"有天我收到了一个包裹，装着迷你机械玩具和表达谢意的卡片。那份玩具十分精致，下次有机会，我会对菲米尼先生当面表达一下感谢…最好不要当面？好吧，那我也写份卡片，请你帮我带给他。\", \"voicelineId\": 98026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [4019], \"unlockText\": \"完成「谕示胎动的终焉之刻」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于千织…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_chiori_01\", \"description\": \"我买过她家的衣服，质量不错。但平时，我更习惯穿现在这套工作制服，一方面它可以明确地阐述出我的身份，另一方面是因为我喜欢熟悉的事物。这套制服就像是我的剑，熟悉且适用，不必多做更换。\", \"voicelineId\": 98027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱欧斯利…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_wriothesley_01\", \"description\": \"梅洛彼得堡并不是一处好打理的地方。能让那个地方保持相对的稳定，莱欧斯利的手腕无可置疑。\\n其中应该不乏一些不能明说的手段，这就不是我们能知道的了。\", \"voicelineId\": 98028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于希格雯…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_sigewinne_01\", \"description\": \"希格雯小姐是一位优秀的护士，既擅长治疗身体的伤痛，又懂得如何疗愈人的内心。即使是梅洛彼得堡里的那些心怀恶孽的凶徒，想必也会被她的美德和善心感动，内心涌起一丝善念。\\n这一丝善念，或许就能成为他们踏上改邪归正之路的契机。\", \"voicelineId\": 98029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于艾梅莉埃…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_teammate_emilie_01\", \"description\": \"我听说过这名香水设计师小姐，对她真正的职业也有所耳闻。偶尔一次，我遇到她正在抚摸一只路边的小狗，脸上挂着温和的笑意。我们互相点头后就道别了。\", \"voicelineId\": 98030, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解克洛琳德·其一\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_friendship_01\", \"description\": \"决斗代理人的工作并不繁杂，甚至可以说十分简单。遵循审判庭的要求，击败对手就好。除此之外，无需多想。\\n…也许这就是外面有些人把我称为「刽子手」的原因。\", \"voicelineId\": 98031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解克洛琳德·其二\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_friendship_02\", \"description\": \"进行代理决斗时，我会尽可能保证与对手公平较量。如果对手有眼疾，我就会蒙住眼睛，如果对手腿脚不便，我则会限定自己的移动范围。无论如何，我所参与的必须是一场公平的决斗。\", \"voicelineId\": 98032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解克洛琳德·其三\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_friendship_03\", \"description\": \"我见过太多人临阵投降。连拔出武器的勇气都没有，所谓的冤屈和名誉受损，想必也只是自私的一家之言罢了。\\n他们早已被自己击败，无需我动手，就自愿变成了心灵的囚徒。\", \"voicelineId\": 98033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解克洛琳德·其四\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_friendship_04\", \"description\": \"你见过审判庭上的罪人吗？在我所经历过的审判里，罪人们总会强词夺理，将自己伪装成好人。在他们口中，暴行变成义举，罪恶变为正义…但他们狡辩的终点却总是一句话——自己虽然一时糊涂，但这罪过人人都会犯，实在无可指责。\\n他们掩盖自身污秽的方法，就是污染整片水源。\\n而击碎这群罪人们的谎言，为正义之廷激浊扬清，正是我成为决斗代理人的理由。\", \"voicelineId\": 98034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解克洛琳德·其五\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_friendship_05\", \"description\": \"我见过许多想要在审判庭上寻求温和人情的人。我并无不敬，但他们来错了地方。\\n审判庭是昭示公理正义的场所，而正义总是…也必须冷漠，否则它就无从延续。\\n如果正义掺杂了人情，那么它有时候就容易被误导偏折，让基于公理执行的「审判」变为由人情驱使的「私刑」。而审判庭中的「私刑」，与那些违律的凶恶暴行无异。\", \"voicelineId\": 98035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"克洛琳德的爱好…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_pref_hobby\", \"description\": \"与代理决斗不同，「桌上剧团」主持人的身份，能够让我游离于故事之外，在不卷入人情冷暖的情况下观察人们的种种反应，为他们搭建出一个受我掌控的世界。嗯？你说听起来像看着笼子里的猎物？有道理…是我没有思考过的角度，不过我从来不会为难玩家，尽量都让他们开心地体验故事，这点和打猎还是很不一样的。\", \"voicelineId\": 98036, \"voicelineType\": \"6001\", \"unlockConditions\": [{\"paramList\": [14034], \"unlockText\": \"完成「夜色无声」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"克洛琳德的烦恼…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_dialog_annoyed_01\", \"description\": \"希望那些记者不要再打扰我喝咖啡、买花和看书。否则我会考虑抓两个典型向审判庭起诉。如果他们申请代理决斗，我会让他们带着留影机上场的。公平起见，我也会只带留影机。\", \"voicelineId\": 98037, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_pref_foodLike\", \"description\": \"用肉类做的菜肴都不错，但肉一定要新鲜。刚猎下的肉用盐简单调味后烤制，旁边搭配上微酸的水果，味道十分不错。下次有机会的话，随我去打猎，我做给你尝尝。\", \"voicelineId\": 98038, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_pref_foodDislike\", \"description\": \"鱼类不合我的胃口，一方面是刺太多，另一方面则是有一股腥味…或许我在儿时已经吃够了。\", \"voicelineId\": 98039, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_spice_pref_01\", \"description\": \"完美的味道，很合我口味。别让记者和美食家发现，他们只会用镜头和报纸享受美食。\", \"voicelineId\": 98040, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_spice_normal_01\", \"description\": \"嗯，不错的美食，很适合慢慢品尝。\", \"voicelineId\": 98041, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_spice_dislike_01\", \"description\": \"…幸好这道菜并非出自餐馆，避免了一些厨师和食客之间的矛盾。\", \"voicelineId\": 98042, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_pref_birthday_01b\", \"description\": \"生日快乐。这短剑样式的项链由我亲手打造，送给你作为礼物。\\n按照逐影猎人的传统，在新成员作为逐影猎人度过第一次生日时，教导这位猎人的导师会为{M#他},{F#她}亲手打造一柄刻有姓名的短剑项链，并让{M#他},{F#她}把它时刻挂在胸口。这象征着用剑锋指问自己的内心，是否涉足恶孽，是否心有旁骛，是否有决心逐灭邪魔。\\n虽然你不是逐影猎人，但我相信你和我们一样，有着惩恶扬善的决心。\\n为什么样式不是铳枪？因为铳枪会走火，指问内心的手段太直接了也不行。\", \"voicelineId\": 98043, \"voicelineType\": \"7001\", \"voicefile_male\": \"VO_friendship/VO_clorinde/vo_clorinde_pref_birthday_01a\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true, \"hasGenderedVoicefile\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_starUp_01\", \"description\": \"原来如此，的确有所长进。\", \"voicelineId\": 98044, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_starUp_02\", \"description\": \"剑挥舞时的手感更好了，完全能适应。\", \"voicelineId\": 98045, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_starUp_03\", \"description\": \"眼力有所提升？让我朝那片落叶试射一下。\", \"voicelineId\": 98046, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_clorinde/vo_clorinde_starUp_04\", \"description\": \"在武力层面，我并不认为你会需要我的帮助。但倘若你希望借助我的力量，我会尽我所能，一如既往。\", \"voicelineId\": 98047, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_battle_skill1_01\", \"description\": \"预备。\", \"voicelineId\": 98048, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_battle_skill1_02\", \"description\": \"上膛。\", \"voicelineId\": 98049, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_battle_skill1_03\", \"description\": \"猎影！\", \"voicelineId\": 98050, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_battle_skill3_01\", \"description\": \"射猎邪魔！\", \"voicelineId\": 98051, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_battle_skill3_02\", \"description\": \"你的自证时刻。\", \"voicelineId\": 98052, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_battle_skill3_03\", \"description\": \"洞见恶孽，逐灭鬼影！\", \"voicelineId\": 98053, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_chest_open_01\", \"description\": \"路遇好运，不错。\", \"voicelineId\": 98054, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_chest_open_02\", \"description\": \"没有归属的物品，不会引发纠纷。\", \"voicelineId\": 98055, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_chest_open_03\", \"description\": \"先到者得，合理。\", \"voicelineId\": 98056, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_life_less30_01\", \"description\": \"…速决胜负。\", \"voicelineId\": 98057, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_life_less30_02\", \"description\": \"骄纵轻狂。\", \"voicelineId\": 98058, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_life_less30_03\", \"description\": \"…可笑。\", \"voicelineId\": 98059, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_life_less30_teammate_01\", \"description\": \"退场！\", \"voicelineId\": 98060, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_life_less30_teammate_02\", \"description\": \"由我接手，后退。\", \"voicelineId\": 98061, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_life_die_01\", \"description\": \"胜负…已分…\", \"voicelineId\": 98062, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_life_die_02\", \"description\": \"败者…当如此…\", \"voicelineId\": 98063, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_life_die_03\", \"description\": \"你已证明了名誉…\", \"voicelineId\": 98064, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_battle_hit_L_02\", \"description\": \"还算精准。\", \"voicelineId\": 98065, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_clorinde/vo_clorinde_battle_hit_H_02\", \"description\": \"够了！\", \"voicelineId\": 98066, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_clorinde_teamJoin_01\", \"description\": \"如你所邀。\", \"voicelineId\": 98067, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_clorinde_teamJoin_02\", \"description\": \"需要我为你代理决斗吗？\", \"voicelineId\": 98068, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_clorinde_teamJoin_03\", \"description\": \"剑锋，直指暗影。\", \"voicelineId\": 98069, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000099, 'Emilie', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_draw_appear_01\", \"description\": \"你好，我是艾梅莉埃。请问是因为香水设计相关的事宜来找我的吗？\\n如果是其他事由，还请移步安静处详谈。\", \"voicelineId\": 99000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·灵感\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_character_idle_01\", \"description\": \"突然有了新的灵感…请稍等片刻，容我记录下来。\", \"voicelineId\": 99001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·香扇\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_character_idle_02\", \"description\": \"不少枫丹廷的淑女喜欢将香水喷在小巧的蕾丝折扇上，扇动时便会有阵阵幽香。的确是十分巧妙的做法。\", \"voicelineId\": 99002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·报纸\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_character_idle_03\", \"description\": \"若你方便，可以陪我去买一份今天的报纸吗？\", \"voicelineId\": 99003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_weather_heavyRain_01\", \"description\": \"雨水会冲洗掉许多痕迹，有时是件麻烦事。\", \"voicelineId\": 99004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_weather_thunder_01\", \"description\": \"雷电产生时，空气中会有一种特别的气味。\", \"voicelineId\": 99005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_weather_snowy_01\", \"description\": \"在这种特殊的地理环境下，会有更珍贵的材料吧。\", \"voicelineId\": 99006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_weather_sunny_01\", \"description\": \"太阳真好，希望一切如常。\", \"voicelineId\": 99007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_weather_desert_01\", \"description\": \"即使在贫瘠的沙漠，人们也能从沙虫的体脂中提取出高级香料。\", \"voicelineId\": 99008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_greetingMorning\", \"description\": \"我喜欢起床后喝一杯冰水，可以让自己迅速清醒。\", \"voicelineId\": 99009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_greetingNoon\", \"description\": \"餐后适当散步有助于促进食物消化和血液循环。想和我一起走走吗？\", \"voicelineId\": 99010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_greetingNight\", \"description\": \"一些调香的原料必须得在特定的时间段采集，所以有时我需要深夜出行。\", \"voicelineId\": 99011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_greetingNight2\", \"description\": \"晚安。虽然我有很多助眠香薰可以推荐给你，但自然放松地入睡才是最好的选择。\", \"voicelineId\": 99012, \"voicelineType\": \"1004\"}, {\"title\": \"关于艾梅莉埃自己·分享\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_idle\", \"description\": \"我不算非常健谈的人，也不太擅长主动寻找话题，但如果你有想要分享的故事，无论好坏，我都愿意聆听。\", \"voicelineId\": 99013, \"voicelineType\": \"2001\"}, {\"title\": \"关于艾梅莉埃自己·现场清理人\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_idle2\", \"description\": \"凶案或事故现场调查结束后，需要有人做收尾和打扫工作：清理人体组织等残留物，洗去血迹，消毒杀菌…这些便是「现场清理人」的职责。我并不隶属于枫丹廷的任何组织，正以个人身份从事着这项工作，既和警备队有着长期合作，也偶尔接私人委托。\\n关于这份工作，我要介绍的就是这些了。你还有什么想知道的吗？请问吧。\", \"voicelineId\": 99014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·推荐\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_close\", \"description\": \"想知道我平常最喜欢用哪种香水？可能要让你失望了，为了避免其他香味的干扰，我平时工作并不常喷涂香水。不过请告诉我你现在的心情吧，我可以为你推荐一二。\", \"voicelineId\": 99015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·参观\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_close1\", \"description\": \"想参观我的工作室？当然欢迎。不仅可以教你简单的调香方法，还有一个很大的香水收藏库可供体验。我母亲也是一位香水爱好者，我的收藏中有很多都是她买给我的。如果时间充足，我们可以每瓶都试一下。\", \"voicelineId\": 99016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_pendant_01\", \"description\": \"我曾想借助神之眼，创造一株无需汲取营养也能生长的植物。很遗憾，尝试以失败告终。看来哪怕有了神之眼的力量，有些超出自然规则以外的事情还是无法实现的。\", \"voicelineId\": 99017, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_share_01\", \"description\": \"人的五感并不是完全分离的。比如看到红色会感到温暖，香气也有类似的规律。这种规律大多会被用在推销上，当顾客心情低落时，就很容易被推荐具有芳草香或者蜜甜香的香水。\", \"voicelineId\": 99018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_pref_gift_01b\", \"description\": \"{M#没有什么比新鲜事物更能引发人的兴趣了。你游历诸国，见识之广一定非我能及。可以向你提一个请求吗？你是否见过令你印象深刻的香料或者花卉，能否告知与我？\\n「因提瓦特」…如此宏大的名字，我从未听说过。嗯，我记下了，如果我有缘见到这种花，一定马上联系你。},{F#可以请问你一个问题吗？你头上的花…我此前从未见过。你将它们制成头饰始终佩戴，那它们对你来说一定意义深刻吧。\\n「因提瓦特」…听上去是如此宏大。能取得这种花的你，对这个世界来说应该是十分重要的存在吧。}\", \"voicelineId\": 99019, \"voicelineType\": \"3003\", \"voicefile_male\": \"VO_friendship/VO_emelie/vo_emelie_pref_gift_01a\", \"unlockConditions\": [{\"paramList\": [8007], \"unlockText\": \"完成「回响渊底的安魂曲」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true, \"hasGenderedVoicefile\": true}, {\"title\": \"关于夏沃蕾…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_teammate_chevreuse_01\", \"description\": \"不知她有没有向你提起过，我们是通过工作认识的。不过大部分时间我们并不会进行特别严肃的对话，记得有次她看了一本小说，讲的是有人使用人体组织制作香水的故事。按照书中的想象，最后的成品是惊为天人的杰作，但以我的经验，实际上大概不会有这么美妙的结果…\\n不过夏沃蕾的重点不在这里，她当时正在努力盘算其中各方应当承担的法律责任呢。\", \"voicelineId\": 99020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于千织…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_teammate_chiori_01\", \"description\": \"千织小姐是位对流行趋势很敏锐的设计师。尽管我们的工作内容完全不同，我还是很喜欢听她介绍服装设计的思路与创意。她选香水的眼光也很不错，经常在试做样品的阶段就挑中了上市后会大卖的那款。\", \"voicelineId\": 99021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于夏洛蒂…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_teammate_charlotte_01\", \"description\": \"这是一位活力四射的小姐呢。会有不少人觉得她很「麻烦」吧，但这位记者小姐在知道了我的真实工作后却没有大范围地传播。这并不是她必须要帮我的忙，甚至与她的职业需求有所冲突，所以我对她印象不错。如果她需要帮助，我是不会拒绝的。\", \"voicelineId\": 99022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于克洛琳德…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_teammate_clorinde_01\", \"description\": \"枫丹廷大概没有人不知道这位实力顶尖的决斗代理人吧。但我不觉得克洛琳德小姐会不好相处，越是武力强大的人，反而越不抗拒沟通。\", \"voicelineId\": 99023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于希格雯…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_teammate_sigewinne_01\", \"description\": \"如果没记错的话，希格雯小姐应该在我还不记事的时候就见过我了…对了，我是不是没说过，因为家父就职于逐影庭，我家常有美露莘来做客，听说我出生后被很多美露莘小姐们关照过。\\n不过希格雯小姐并没有拿我当后辈看待，还对我的香水一直赞赏有加。我做了新的样品时，常常会给她多留一份。\", \"voicelineId\": 99024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于那维莱特…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_teammate_neuvillette_01\", \"description\": \"调香师在嗅觉疲劳时有一种很简单的缓解方法，就是饮用清水。我对水的品质并无苛刻的要求，但出于好奇，我参加过一次那维莱特先生举办的品水会。\\n他对每种水的特征都有着缥缈却又十分独到的见解，就像杂志上对香水的评价文章一样。他在了解到我的需求后，向我推荐水源的态度也十分真诚。出于敬重，我时不时会专门购买他推荐的种类。\", \"voicelineId\": 99025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于莱欧斯利…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_teammate_wriothesley_01\", \"description\": \"你认识莱欧斯利先生？呵呵，你果然不是一般人，据我所知，这位公爵大人十分低调，甚至不太有人知道他的存在。那维莱特先生曾想将我引荐给他，不过他似乎表示梅洛彼得堡没有需要我工作的场合。\\n我从未当面见过这位先生，对他自然不甚了解，但恕我冒然揣度…也许他是不想将某些痕迹清洗得太过干净，从而留作警示吧。\", \"voicelineId\": 99026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于提纳里…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_teammate_tighnari_01\", \"description\": \"我和他见面不多，但常有书信往来。一开始是他不知通过什么渠道，辗转联系到我，字里行间十分客气。一位知名植物学家向我请教花卉知识，着实令我受宠若惊。不过我也就此抓住机会，向他咨询了很多关于须弥香料的知识，他都帮我一一解答了。\\n现在我们之间的书信就随意了很多，他还时常提起他身边的同伴们。我很开心能通过这样的机会结交到更多有趣的朋友。\", \"voicelineId\": 99027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解艾梅莉埃·其一\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_friendship_01\", \"description\": \"人们常为香水赋上浪漫与诗意，但实际的调制过程却与科学紧密相关，本质上和化学试验并无二致。如何做好这二者间的桥梁，就要看调香师的本事了。\", \"voicelineId\": 99028, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解艾梅莉埃·其二\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_friendship_02\", \"description\": \"人也许能说出香味带给他的感受，但很难依照文字描述精确反推出那种气味的原貌。我也不例外，所以很抱歉，我不接定制工作。但如果我调制的那些香水中能有一款合顾客的心意，那将是我莫大的荣幸。\", \"voicelineId\": 99029, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解艾梅莉埃·其三\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_friendship_03\", \"description\": \"一款香水在出品前，需要经历一系列测试，其中一项便是闲置试验。它能存放多久，是否容易变质，会不会在一段时间后产生有毒物质，或者直接消散殆尽？\\n话说到这里，有没有觉得人与人之间的关系也需要这种检验呢？\", \"voicelineId\": 99030, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解艾梅莉埃·其四\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_friendship_04\", \"description\": \"我没有刻意隐瞒过我的真正职业，但还是倾向于不要太过声张。并非担心买香水的客人们对我的作品心生疑虑，而是现场清理人的工作会接触很多不便公开的信息。委托方因为信任才将工作交到我的手中，我自然也不希望给他们引来不必要的关注。\", \"voicelineId\": 99031, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解艾梅莉埃·其五\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_friendship_05\", \"description\": \"调香始终是我的一项爱好。就像有人会在业余时间学习某种乐器，有人会制作手工艺品，调香对我来说也是如此。\\n不过，我的人生目标的确发生过转变。我的母亲是一位专业法医，我从小也希望和母亲一样从事和刑侦有关的工作。我非常擅长与化学相关的学科，曾想成为一名痕迹鉴定专家。不过随着学习的深入，我接触到了一些真实的事发现场。曾有一名孩童惨遭杀害，血液浸透地毯与墙纸，警官调查后结案离开，但孩子的父母要以什么样的心情收拾房间呢？\\n就这样，我开始了这份工作。\", \"voicelineId\": 99032, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"艾梅莉埃的爱好…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_pref_hobby\", \"description\": \"我喜欢剪报，将我觉得不可思议的事件报道收集起来，慢慢有了好几个厚本子，翻起来就像夏沃蕾喜欢的那种短篇小说集一样呢。\", \"voicelineId\": 99033, \"voicelineType\": \"6001\"}, {\"title\": \"艾梅莉埃的烦恼…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_dialog_annoyed_01\", \"description\": \"公园里的小狗们都非常热情。想要感受它们柔顺的皮毛，往往得先纵容它们的扑闹。呵呵，真是甜蜜的烦恼。\", \"voicelineId\": 99034, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_pref_foodLike\", \"description\": \"新鲜虾肉用撒过海盐的水煮熟，再蘸上融化的黄油，简单又美味，你也可以试试。\", \"voicelineId\": 99035, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_pref_foodDislike\", \"description\": \"我不常吃红肉，还请见谅。\", \"voicelineId\": 99036, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_spice_pref_01\", \"description\": \"味道和闻起来一样好。谢谢你愿意与我分享，我很喜欢。\", \"voicelineId\": 99037, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_spice_normal_01\", \"description\": \"嗯，色泽不错，口感也很好。\", \"voicelineId\": 99038, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_spice_dislike_01\", \"description\": \"原来有人喜欢这种味道…\", \"voicelineId\": 99039, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_pref_birthday_01\", \"description\": \"生日快乐。虽说香味是种十分私人的喜好，但我还是冒昧为你选择了一瓶香水，是我的个人作品之一，并未在市场上售卖。\\n我尽力融合了这段时间内自然界特有的花香与果香，它不是一款个性十分突出的香水，我衷心希望它能陪你度过一段和缓又安逸的时光。\", \"voicelineId\": 99040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_starUp_01\", \"description\": \"非常感谢。无需推辞，这是必要的礼节。\", \"voicelineId\": 99041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_starUp_02\", \"description\": \"谢谢你的提议，为我提供了更多思路。\", \"voicelineId\": 99042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_starUp_03\", \"description\": \"能力要掌握在正确的对象手中才能发挥作用。希望我不会辜负你的信任。\", \"voicelineId\": 99043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_emelie/vo_emelie_starUp_04\", \"description\": \"很多事物必须要在强光下才能让人看清，而你现在将这束光交到了我的手中。是想邀我同行的意思吗？那么请吧，我就在你身边。\", \"voicelineId\": 99044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_battle_skill1_01\", \"description\": \"重组。\", \"voicelineId\": 99045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_battle_skill1_02\", \"description\": \"单离。\", \"voicelineId\": 99046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_battle_skill1_03\", \"description\": \"清理开始。\", \"voicelineId\": 99047, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_battle_skill3_01\", \"description\": \"芬馥之语。\", \"voicelineId\": 99048, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_battle_skill3_02\", \"description\": \"雾散吧。\", \"voicelineId\": 99049, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_battle_skill3_03\", \"description\": \"予我辉光。\", \"voicelineId\": 99050, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_chest_open_01\", \"description\": \"呵呵，是符合期待的收获吗？\", \"voicelineId\": 99051, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_chest_open_02\", \"description\": \"需要我帮你收纳吗？\", \"voicelineId\": 99052, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_chest_open_03\", \"description\": \"似乎没留下失主的信息…\", \"voicelineId\": 99053, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_life_less30_01\", \"description\": \"嗅觉疲劳了…\", \"voicelineId\": 99054, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_life_less30_02\", \"description\": \"难道是过敏反应？\", \"voicelineId\": 99055, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_life_less30_03\", \"description\": \"需要重新评估现场。\", \"voicelineId\": 99056, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_life_less30_teammate_01\", \"description\": \"放松。\", \"voicelineId\": 99057, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_life_less30_teammate_02\", \"description\": \"我在。\", \"voicelineId\": 99058, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_life_die_01\", \"description\": \"泥土的气息…\", \"voicelineId\": 99059, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_life_die_02\", \"description\": \"如灯之熄…\", \"voicelineId\": 99060, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_life_die_03\", \"description\": \"到我了吗…\", \"voicelineId\": 99061, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_battle_hit_L_02\", \"description\": \"我的破绽。\", \"voicelineId\": 99062, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_battle_hit_H_01\", \"description\": \"防备不足。\", \"voicelineId\": 99063, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_emelie/vo_emelie_battle_hit_H_02\", \"description\": \"理应更加谨慎。\", \"voicelineId\": 99064, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_emelie_teamJoin_01\", \"description\": \"荣幸之至。\", \"voicelineId\": 99065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_emelie_teamJoin_02\", \"description\": \"向你致意。\", \"voicelineId\": 99066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_emelie_teamJoin_03\", \"description\": \"感谢你出面邀请。\", \"voicelineId\": 99067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000100, 'Kachina', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_draw_appear_01\", \"description\": \"你好呀，我是「回声之子」的卡齐娜。喜欢吃颗粒果，想要变强，不擅长打架。啊…不是说这些的时候？那、那…请问你接下来想去哪里走走？我挺熟悉这一带的，就让我来带路吧。\", \"voicelineId\": 100000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·整理癖\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_character_idle_01\", \"description\": \"啊…我刚刚发现有块砖没有堆整齐。怎么办？现在感觉心里有只小龙在不停地挠啊挠。\", \"voicelineId\": 100001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·行不行\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_character_idle_02\", \"description\": \"我可以、我不行、我可以、我…唔唔，没事的，我可以的，一定没问题的…对吧？\", \"voicelineId\": 100002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·收藏品\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_character_idle_03\", \"description\": \"无聊的话，要不要一起来看看我包里的收藏？看上什么拿走也没关系哦。\", \"voicelineId\": 100003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_weather_heavyRain_01\", \"description\": \"雨水会让泥土变得松软，所以雨天挖矿一定要比平时更加更加小心哦。\", \"voicelineId\": 100004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_weather_thunder_01\", \"description\": \"呀——啊…我、我不是害怕，只是被吓了一跳而已。\", \"voicelineId\": 100005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_weather_snowy_01\", \"description\": \"我们一起去雪地上打滚吧，嘿嘿。你放心，我不会像阿尤一样，钻到雪里又突然冒出来吓你的。\", \"voicelineId\": 100006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_weather_sunny_01\", \"description\": \"快看这块宝石！在太阳的照射下，它里面好像藏着彩虹。\", \"voicelineId\": 100007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_weather_desert_01\", \"description\": \"这下面会不会藏着金闪闪的矿石？要不要挖挖看？\", \"voicelineId\": 100008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_greetingMorning\", \"description\": \"早呀，我已经整理好背包啦，我们随时可以出发。\", \"voicelineId\": 100009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_greetingNoon\", \"description\": \"我不困，但如果你想午睡一会儿的话，我可以帮你望风。虽然我有许多不擅长的事情，但…我的耳朵还算灵敏。远处的风吹草动，我都能感觉到。\", \"voicelineId\": 100010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_greetingNight\", \"description\": \"玛拉妮邀请我晚上去山洞试胆，我我我，好紧张，怎么办？我不想拒绝朋友，就…就闭上眼睛答应了…不、不管发生什么事情，我都应该和她一起面对。欸？你也一起来吗？太、太好了！呜…\", \"voicelineId\": 100011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_greetingNight2\", \"description\": \"今天怎么又把事情给搞砸了，呜呜呜…怎么办，明明不想哭的，但眼泪完全停不下来了，呜呜…噫——，刚、刚刚我们不是互相说了晚安，要去睡觉了吗？但谢谢你安慰我…\", \"voicelineId\": 100012, \"voicelineType\": \"1004\"}, {\"title\": \"关于卡齐娜自己·冲天转转\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_idle\", \"description\": \"这个名字是我和阿尤一起取的。我先想好了前半部分，又根据阿尤的动作定下了后半。我常常会乘着它和阿尤比赛跑步，我们各有输赢呢。\", \"voicelineId\": 100013, \"voicelineType\": \"2001\"}, {\"title\": \"关于卡齐娜自己·死亡\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_idle2\", \"description\": \"能在「巡夜者战争」中死去，对纳塔战士们来说是一种荣光，身为其中一员的我也不该例外…但当时我一边这样告诉自己，一边在心里害怕得要命…你们冒着巨大的危险从夜神之国把我带回来，我真的非常感激！呜呜，谢谢你们每个人…\", \"voicelineId\": 100014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·传说\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_close\", \"description\": \"纳塔流传着很多英雄传说，其中我最喜欢的就是陶奥鲁大人的事迹，居然能以血肉之躯把深渊给封入地下，实在太厉害了！对了对了，你走过了那么多国家，一定也知道很多传说故事吧？我真的很好奇…有空的时候可以和我讲讲吗？\", \"voicelineId\": 100015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·小礼物\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_close1\", \"description\": \"来挑一个你喜欢的吧！作为我们是好朋友的证明。我能收集到的最好看、最闪亮的矿石全都在这里啦。如果你愿意选一颗收下的话，我会很开心的！\", \"voicelineId\": 100016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_pendant_01\", \"description\": \"在我第一次看到这枚亮晶晶神之眼的时候，我还以为自己眼花了呢，它比我见过的任何一块石头都要闪亮。虽然我现在与那些传说中的英雄相比，还差得很远，但如果有一天，我的故事也能激励别人，哪怕只有一个人也好，那也会成为我最大的幸福…\", \"voicelineId\": 100017, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_share_01\", \"description\": \"阿尤是我很重要的伙伴，别看它现在模样乖巧，它再小些的时候，表达喜欢的方式是冲过来用头撞人。它力气可大了，有时候我都会被它撞得摔倒。不过这也没办法嘛，毕竟嵴锋龙是一种很亲人的龙。哎呀，别撞我呀，阿尤，好好好，我不揭你短啦。\", \"voicelineId\": 100018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_pref_gift_01\", \"description\": \"澄晶实的果实形状就像宝石一样，如果它也能像宝石一样长时间存放就好了…\", \"voicelineId\": 100019, \"voicelineType\": \"3003\"}, {\"title\": \"关于玛拉妮…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_teammate_mualani_01\", \"description\": \"玛拉妮是我的第一个好朋友。遇到她之前，我都不知道这个世界上有这么好的人，还有这么多好玩的事情。看，这是我们合影的画片。她说是要在合影时一起往上跳…你说我动作看着有点僵硬？嘿嘿…被你发现了…当时镜头外有很多人在看着我们，让我有点紧张…\", \"voicelineId\": 100020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于基尼奇…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_teammate_kinich_01\", \"description\": \"基尼奇哥哥还是玛拉妮介绍给我认识的呢。不瞒你说，一开始我有点害怕他，因为他的眼神看起来…稍微有一点凶。我后来才知道，他私底下教训过欺负我的坏蛋。但在我送他回礼的时候，他又不肯收下，说是已经得到了足额的报酬…\", \"voicelineId\": 100021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于恰斯卡…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_teammate_chasca_01\", \"description\": \"她是纳塔有名的「调停人」，据说任何争斗都能被她轻松摆平。她会这么做，恐怕是像我一样，很讨厌人与人之间起什么冲突吧…\", \"voicelineId\": 100022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊安珊…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_teammate_iansan_01\", \"description\": \"之前为了变强，我拜托伊安珊带我训练。她安排了各种各样高强度的锻炼方式，我常常需要咬紧牙关才能坚持下去。好在她给我安排的训练量非常精准，每次结束后都留出了供我走回家的体力…我还是很感谢她的。\", \"voicelineId\": 100023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于茜特菈莉…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_teammate_citlali_01\", \"description\": \"玛拉妮和我说了，你们能救出我，还多亏了她的发明。「灵觉髓石」坏掉了，我也有不可推脱的责任…后来我鼓起勇气去找她道歉了，并且让她在我收藏的石头里挑几块，她挠着头说：「这，我不挑一个是不是很麻烦啊。拿个差不多的我们就两清，是吧？」最后只拿走了最不起眼的一块黑曜石，就摆了摆手让我走了。你说，我要不要再帮她找点什么？她喜欢什么，你知道吗？\", \"voicelineId\": 100024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于希诺宁…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_teammate_xilonen_01\", \"description\": \"在我获得古名后，帕加尔叔叔带我去找了希诺宁姐姐，请她帮我打造了冲天转转，她的手艺简直出神入化。\\n后来，我们交流过宝石收藏与存储的经验，还欣赏了彼此的珍品。她的收藏品状态非常好，肯定照顾得十分细致。但她自己的生活…似乎要更加随性？有一次我找了她很久都没找到，最后发现她在一棵大树上晒着太阳睡着了…\", \"voicelineId\": 100025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于火神大人…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_teammate_mavuika_01\", \"description\": \"我做梦都想不到，居然有一天能被火神大人亲口认可为「纳塔的英雄」，火神大人是每一位纳塔战士的偶像，我…我得到了偶像的…呜…我一想起来就太感动了，呜呜呜…对不起，对不起对不起。不该在这时候哭的…\", \"voicelineId\": 100026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊法…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_teammate_ifa_01\", \"description\": \"伊法哥哥是个很厉害的龙医生！凡是给他看过病的小龙，回来后都作息规律、不乱吃乱跑，几乎再没生过病啦。所以每当大家发现有龙身体不舒服，第一反应都是请他飞过来看一看。\", \"voicelineId\": 100027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解卡齐娜·其一\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_friendship_01\", \"description\": \"「乌沙博蒂」是我的古名，它的意思是坚强，唉，可很多时候我都想不明白为什么这个古名会给我。我那么弱小，不管是在家里，还是在部族里，存在感都不算高…有那么多优秀的人在身边，我真的有拥有它的资格吗？\", \"voicelineId\": 100028, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解卡齐娜·其二\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_friendship_02\", \"description\": \"要说我家人的话…我在家中排行第二。我知道爸爸把期许主要寄托在了姐姐身上，而妈妈现在又要照顾年幼的妹妹。我们的生活有些辛苦，所以我需要管好自己，早点长大…至少让爸爸妈妈少操点心。\", \"voicelineId\": 100029, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解卡齐娜·其三\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_friendship_03\", \"description\": \"帕加尔叔叔待我很好。部族里其他人议论我的时候，他总会帮我说话。其实…他那样做，我心里反而过意不去。我只有靠自己的实力赢得大家认可才行啊…\", \"voicelineId\": 100030, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解卡齐娜·其四\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_friendship_04\", \"description\": \"我一直知道，流泪并不能解决任何问题。传说故事里，我从来没听过有英雄会在大家面前哭啊。我很想忍住眼泪，但我总是失败…欸？你说没关系？流泪是一种很重要的发泄方式？你…你真的这么想吗？呜呜呜，谢谢你，呜…我怎么又哭了。\", \"voicelineId\": 100031, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解卡齐娜·其五\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_friendship_05\", \"description\": \"我之前一直觉得自己很弱小，被人忽视也是理所当然…但，听到大灵女士那番话之后，我不再那么想了。「乌沙博蒂」是我的古名，我…已经决定要变成更好的「自己」。这个世界上一定有我才能做到的事。我会…继续努力。希望这块黑曜石有朝一日也能容纳我的事迹，成为一颗…更加璀璨的宝石。\", \"voicelineId\": 100032, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"卡齐娜的爱好…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_pref_hobby\", \"description\": \"这块是我第一次挖出来的宝石，翠绿翠绿的，很好看吧？最初它们是一对，另外一块我送给了玛拉妮，你看，它的花纹像流水一样。对了，还有这块，别看它是黑色的，但放在太阳下面就会有五彩斑斓的感觉…嘿嘿，这些全都是我一块一块收集起来的。\", \"voicelineId\": 100033, \"voicelineType\": \"6001\"}, {\"title\": \"卡齐娜的烦恼…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_dialog_annoyed_01\", \"description\": \"之前玛拉妮送了我一顶很大的帽子，太酷了，还能完美地遮住太阳，我真的好喜欢，但戴着戴着，它就成了一顶毡帽…后来我只能换成现在这顶不会粘毛的帽子了。\", \"voicelineId\": 100034, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_pref_foodLike\", \"description\": \"粒果片片是我的最爱，要是能堆得整齐一点，那就更加完美了。\", \"voicelineId\": 100035, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_pref_foodDislike\", \"description\": \"欸？分量这么大吗？但、但我吃不完的话，不就浪费了厨师的劳动成果吗？唔唔，没关系…我一定可以吃完的！小口小口慢慢吃…\", \"voicelineId\": 100036, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_spice_pref_01\", \"description\": \"哇——真的是送给我的吗？太好吃了！我要慢慢吃，让美味停留得更久一点。\", \"voicelineId\": 100037, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_spice_normal_01\", \"description\": \"又香又好吃，摆盘也很精致。如果有「厨艺战争」的话，你一定会赢吧！\", \"voicelineId\": 100038, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_spice_dislike_01\", \"description\": \"谢谢你愿意为我花时间！我、我一定会吃完的，请再多给我一点时间。\", \"voicelineId\": 100039, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_pref_birthday_01\", \"description\": \"生日快乐！这个送给你，是虹闪石雕成的鼠兔。虹闪石的触感温润，但在地下很不起眼，一不留神就会错过…不过带在身边久了，它的光泽就会越来越漂亮的。这是我最喜欢的宝石之一，希望你也喜欢。\", \"voicelineId\": 100040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_starUp_01\", \"description\": \"我的耳朵在抖吗？不是紧张…而是开心。对不起，它们现在激动得不得了，我控制不住。我…我捂住它们吧。\", \"voicelineId\": 100041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_starUp_02\", \"description\": \"你真的非常重视我…呜…呃、我没有想哭的，就是太感动了…\", \"voicelineId\": 100042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_starUp_03\", \"description\": \"「王庭焚弃，火却未曾殄熄。明晨它要再度燃起，比昨日更为辉熠。」这是陶奥鲁大人说过的话中，我最喜欢的一句。我，我必须要努力才行…\", \"voicelineId\": 100043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_kachina/vo_kachina_starUp_04\", \"description\": \"你带我一起见识了种种新奇的事物，让我成长了很多，我不知道该怎么回报你才好…但这次我想自己找到答案。接下来就让我来当英雄吧，保护你的英雄！\", \"voicelineId\": 100044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_skill1_01\", \"description\": \"旋转！\", \"voicelineId\": 100045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_skill1_02\", \"description\": \"嘿——哟！\", \"voicelineId\": 100046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_skill1_03\", \"description\": \"来咯！\", \"voicelineId\": 100047, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_skill1_04\", \"description\": \"开转咯！\", \"voicelineId\": 100048, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_skill1_05\", \"description\": \"冲地波！\", \"voicelineId\": 100049, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_skill1_06\", \"description\": \"冲天转转，出发！\", \"voicelineId\": 100050, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_skill3_01\", \"description\": \"清退！\", \"voicelineId\": 100051, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_skill3_02\", \"description\": \"矿石采集。\", \"voicelineId\": 100052, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_skill3_03\", \"description\": \"切勿靠近。\", \"voicelineId\": 100053, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_chest_open_01\", \"description\": \"哇哇，有亮晶晶的石头！\", \"voicelineId\": 100054, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_chest_open_02\", \"description\": \"你也喜欢收集石头吗？我懂我懂，这些石头太好看了。\", \"voicelineId\": 100055, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_chest_open_03\", \"description\": \"需要帮忙整理吗？我很拿手！\", \"voicelineId\": 100056, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_life_less30_01\", \"description\": \"没事，小伤罢了。\", \"voicelineId\": 100057, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_life_less30_02\", \"description\": \"我要…振作起来。\", \"voicelineId\": 100058, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_life_less30_03\", \"description\": \"我、我一定可以的！\", \"voicelineId\": 100059, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_life_less30_teammate_01\", \"description\": \"不要忘了还有我呀！\", \"voicelineId\": 100060, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_life_less30_teammate_02\", \"description\": \"我在！交给我吧！\", \"voicelineId\": 100061, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_life_die_01\", \"description\": \"对不起，是我逞强了。\", \"voicelineId\": 100062, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_life_die_02\", \"description\": \"不能愧对…「乌沙博蒂」…\", \"voicelineId\": 100063, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_life_die_03\", \"description\": \"呜…又搞砸了吗…\", \"voicelineId\": 100064, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_hit_L_02\", \"description\": \"擦伤而已。\", \"voicelineId\": 100065, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_kachina/vo_kachina_battle_hit_H_02\", \"description\": \"唔，不要紧。\", \"voicelineId\": 100066, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_kachina_teamJoin_01\", \"description\": \"呜哇？我可以参加吗？\", \"voicelineId\": 100067, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_kachina_teamJoin_02\", \"description\": \"太好了！一起动身吧。\", \"voicelineId\": 100068, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_kachina_teamJoin_03\", \"description\": \"又能向你学习战斗技巧了。\", \"voicelineId\": 100069, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000101, 'Kinich', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_draw_appear_01\", \"description\": \"基尼奇：「马力卜」的基尼奇，初次见面，告知委托内容时请附上你的出价。\\n阿乔：…这就没了？哎呀，真急死我了！你该先宣扬自己干活多么迅速漂亮，说点你过往的优秀战绩，抬高对方的心理预期，然后再说「这值得配上一个更好的价码！」你到底会不会做生意？\\n阿乔：一想到我伟大圣龙库胡勒阿乔竟然和你这个臭脸的呆瓜签订了契约，啊，真是丢人丢回上个时代了！\", \"voicelineId\": 101000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·阿乔\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_character_idle_01\", \"description\": \"基尼奇：阿乔性情乖戾，多数时候，不必听信它的话。\\n阿乔：基尼奇！！你有本事就放我出来——！\", \"voicelineId\": 101001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·代价\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_character_idle_02\", \"description\": \"激励与抚慰是别人的强项，度量「代价」则是我的做法。\", \"voicelineId\": 101002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·分配\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_character_idle_03\", \"description\": \"七成调查，一成判断，剩下的用于出击。这是我分配精力的方式。\", \"voicelineId\": 101003, \"voicelineType\": \"1103\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_weather_afterRain_01\", \"description\": \"啧，裤脚还在滴水…\", \"voicelineId\": 101004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_weather_thunder_01\", \"description\": \"阿乔：是屁股会发光的虫子从天上掉下来了吗？才这么点光亮。\\n基尼奇：我看你还没这只虫子亮。\\n阿乔：你再说一遍？！\", \"voicelineId\": 101005, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_weather_sunny_01\", \"description\": \"阿乔：我有一副墨镜，但谁都不借。\", \"voicelineId\": 101006, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_weather_breezy_01\", \"description\": \"阿乔：待壤土与沉云交汇，黑暗吞并旷野，吾将役使狂风呼啸，焚灼尘世！\\n基尼奇：哼，你就「吹」吧。\", \"voicelineId\": 101007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_weather_gale_01\", \"description\": \"基尼奇：天气因素会提高极限运动的挑战性。\\n阿乔：快跳一个嘛…我都忍不住看你去试了，呵呵呵呵。\", \"voicelineId\": 101008, \"voicelineType\": \"1205\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_weather_desert_01\", \"description\": \"记得喝水。\", \"voicelineId\": 101009, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_greetingMorning\", \"description\": \"早。我正准备出门，天亮前不会回来。不用等我。\", \"voicelineId\": 101010, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_greetingNoon\", \"description\": \"既然来了，随便吃点再走？给，用这个擦擦手。\", \"voicelineId\": 101011, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_greetingNight\", \"description\": \"「今天」快要过去了。无论我是否对成果满意，事实都不会因此改变…接下去，该加快脚步了。\", \"voicelineId\": 101012, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_greetingNight2\", \"description\": \"篝火太呛了？稍等…好了，你休息吧。\", \"voicelineId\": 101013, \"voicelineType\": \"1004\"}, {\"title\": \"关于基尼奇自己·追捧\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_idle\", \"description\": \"阿乔：基尼奇，你有没有反思过自己不受人们追捧的原因？看着月亮翻来覆去睡不着觉的时候，心里一定很苦恼吧？智慧圣龙库胡勒阿乔就在面前，汝为何不匍匐在地，乞求吾降下谕旨，为汝指点迷津呢？\\n基尼奇：你一定是因为自己做得太好，才会让追随者们都想把你狠揍一顿。\", \"voicelineId\": 101014, \"voicelineType\": \"2001\"}, {\"title\": \"关于基尼奇自己·猎龙人\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_idle2\", \"description\": \"身为猎龙人，我的职业特殊，并不能获得所有人的理解。但当矛盾难以化解，两全其美之策只存在于幻想中时，总得有人弄脏双手。只要价格合适，我不介意这个人是我自己。\", \"voicelineId\": 101015, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·委托\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_close\", \"description\": \"基尼奇：如有需要，我可以为你分担冒险家协会的委托。\\n阿乔：记得要最棘手、最刁钻，最好有生命危险的那种！\", \"voicelineId\": 101016, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·朋友\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_close1\", \"description\": \"我知道阿乔另有图谋，但我并不介意为你涉险。我将凡事的代价挂在嘴边，但我相信这世上有些事可以不惜代价。\", \"voicelineId\": 101017, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [15004], \"unlockText\": \"完成「尤潘基的回火」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_pendant_01\", \"description\": \"使用「神之眼」无需代价。但不被置于明面的价格，结算时往往最为深重。\", \"voicelineId\": 101018, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_share_01\", \"description\": \"「悬木人」崇尚不受约束的绝对自由，人与龙之间重在认可与帮助，不存在契约关系。我是个例外。\", \"voicelineId\": 101019, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_pref_gift_01\", \"description\": \"基尼奇：摘青蜜莓的时候，记得确认周围没有碍事的龙。\\n阿乔：你这只吝啬的绿斑点蜥蜴！斤斤计较的爬虫！小气鬼！要不是我饿得前胸贴后背，谁看得起你手里那几个发烂发馊的破果子！\\n基尼奇：那我自己吃了。\\n阿乔：啊啊啊——你把我气红了！\", \"voicelineId\": 101020, \"voicelineType\": \"3003\"}, {\"title\": \"关于玛薇卡…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_teammate_mavuika_01\", \"description\": \"一直以来，都是我索取别人的代价，直到火神大人用「还魂诗」将我从夜神之国送归。当作为支付「代价」的一方…我才完全体会到了它的含义。其于强者为筹码，其于弱者为赌注。关键的是，你是否有下注的胆量。\", \"voicelineId\": 101021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于玛拉妮…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_teammate_mualani_01\", \"description\": \"我接过她的委托。她出钱让我担任「战斗顾问」，金额不菲，我答应了。但合作几次后，却看出她身手不赖。再三追问下，才知道所谓「战斗顾问」是要教授卡齐娜野外生存技巧…\\n原来是和「自然」战斗。嗯，在我概念里，这叫「生活」。\\n总之，这笔生意做完，我多了两位熟客。\", \"voicelineId\": 101022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡齐娜…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_teammate_kachina_01\", \"description\": \"我见过和她有关的委托。「回声之子」里有些差劲的家伙嫉妒她拥有「古名」，拐弯抹角地雇人对她的龙伙伴下手。我已让他们付出了代价。\", \"voicelineId\": 101023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于恰斯卡…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_teammate_chasca_01\", \"description\": \"我见过她处理委托。我们对于解决争端的手段存在分歧。通常我会让一方彻底闭嘴，但她会让两方都说不出话，等到他们终于能在病床上开口的时候，早就忘了为何争执。\", \"voicelineId\": 101024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于希诺宁…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_teammate_xilonen_01\", \"description\": \"有次我路过「回声之子」，看到了一个奇怪的委托。委托人希望得到一种好养的植物。我把肉龙掌的种子送了过去，配了花盆和肥料。这种植物分布广泛，在荒野上都长势旺盛。可我过段时间去拿报酬的时候，才发现盆里连小苗都没长出来。\\n我为高估希诺宁的园艺能力支付了代价。这是我为数不多以失败而告终的委托。\", \"voicelineId\": 101025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊安珊…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_teammate_iansan_01\", \"description\": \"基尼奇：我接过她的委托，或说合作…这位运动教练经常为学员制作健身餐，计算热量精确到个位数，为此需要进购质量达标、规格精确的果实。稍微长了点斑，或者被虫咬过一口都不行。其他人觉得委托内容过于挑剔，但我恰好拥有不错的眼力，以及稳定的残次品消耗渠道。\\n阿乔：等等？你是说…我的果汁？\", \"voicelineId\": 101026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于茜特菈莉…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_teammate_citlali_01\", \"description\": \"或许你猜到了，我也接过她的委托，帮她从一位稻妻商人处购买一摞摞沉重的纸制阅读品。我无意打探雇主隐私，可「烟谜主」的读物，不是缝在织物上的吗？\", \"voicelineId\": 101027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊法…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_teammate_ifa_01\", \"description\": \"基尼奇：我委托过他。有次阿乔说自己「病」了，大哭大闹不肯停下。既然如此，理应送它去看最好的龙医生。他医术的确不错，阿乔被请进诊所后没一会儿就痊愈了。\\n阿乔：你…你知道什么啊你！他就是个庸医，庸医！…你、你都不知道他说了什么你都！\", \"voicelineId\": 101028, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解基尼奇·其一\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_friendship_01\", \"description\": \"我是个猎龙人。无龙可猎的时候，也接其他委托。和你算是同行。\", \"voicelineId\": 101029, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解基尼奇·其二\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_friendship_02\", \"description\": \"从前我替人跑腿送信，收件人经常喊我「顺手帮个忙」。那么「顺手」值多少钱呢？往往我一开价，忙就不用帮了。\", \"voicelineId\": 101030, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解基尼奇·其三\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_friendship_03\", \"description\": \"第一次猎龙，我做了数以周计的准备。光观察、跟踪和蹲守就花费数日，制作了不下三种陷阱，还记录了它的生活规律和食物偏好…\\n很多努力是浪费，但浪费是必要的。\", \"voicelineId\": 101031, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解基尼奇·其四\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_friendship_04\", \"description\": \"基尼奇：阿乔曾被封印在古老的遗迹中，我与它签订契约，将它放了出来。\\n阿乔：谁知道你这个看起来就会一头栽进泥水沟的家伙，现在还活得好好的…算了算了，我烈焰之国至高领主有的是与地位相衬的美德与涵养。\\n基尼奇：美德与涵养催促你天天盼我死？\\n阿乔：我指的是有耐心和时间！\\n基尼奇：…总之，只要掐准软肋，邪恶之物也能加以利用。\\n阿乔：你个可恶的基尼奇！我今天就要借别人的手弄死你！\", \"voicelineId\": 101032, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解基尼奇·其五\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_friendship_05\", \"description\": \"迄今我都在和「代价」打交道，从大灵处获得古名「回火」——也就是「马力卜」，我并不意外。\\n生存才能创造价值，我不会期待一切走向终结的那一天。但作为「回火」的持有者，我早有接受它灼烧的准备。\\n它大可审视我的一生，而我不会留下遗憾。\", \"voicelineId\": 101033, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [15004], \"unlockText\": \"完成「尤潘基的回火」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"基尼奇的爱好…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_pref_hobby\", \"description\": \"我会尝试各类极限运动，玩腻了就换一种。在磨炼技巧的同时与恐惧感博弈…先是「面对」，而后「习惯」，最终「征服」。\", \"voicelineId\": 101034, \"voicelineType\": \"6001\"}, {\"title\": \"基尼奇的烦恼…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_dialog_annoyed_01\", \"description\": \"我见过有烦恼的人不是想得太多就是想得太少。我总在为自己寻找下一个目标与落点，没闲心烦恼。\", \"voicelineId\": 101035, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_pref_foodLike\", \"description\": \"基尼奇：在野外，我一般什么方便吃什么。最好的选择自然是肉和水果。\\n阿乔：哟，装得像个不挑食的好孩子，我怎么从不见你摘颗粒果呀？\\n基尼奇：背着重。\", \"voicelineId\": 101036, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_pref_foodDislike\", \"description\": \"阿乔：生冷辛辣侵蚀尊贵圣躯，热油浊气有害五脏六腑。硬实之物不便咀嚼，酥软烂糊食之无味…\\n基尼奇：你到底要吃什么？\\n阿乔：当然是你的灵魂喽，噢呵呵呵。\", \"voicelineId\": 101037, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_spice_pref_01\", \"description\": \"基尼奇：很美味。我应该给你相应酬劳，或是其他你中意的回礼。\\n阿乔：吐出来！你这个贪婪的蝮蛇！那里面肯定有给我的份！\", \"voicelineId\": 101038, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_spice_normal_01\", \"description\": \"基尼奇：还不错，比我预想中的味道更好。\\n阿乔：这话难道不是在嘲笑你吗？在他心中，你就像个不会做饭的家伙呢。\", \"voicelineId\": 101039, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_spice_dislike_01\", \"description\": \"基尼奇：…可以不付钱吗？\\n阿乔：别还回去啊！我还没尝过呢！\", \"voicelineId\": 101040, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_pref_birthday_01\", \"description\": \"基尼奇：阿乔？\\n阿乔：知道了知道了，嘁，差使别人干活的时候积极得就跟拿钱一样，有本事你自己长出翅膀飞上天啊。你，说的就是你，还不快点到我背上来？能乘上伟大圣龙库胡勒阿乔可是值得你称道一生的殊荣。\\n基尼奇：放心，只是一次轻松的丛林旅行。跟着我就好。路线我设计过，保证安全。\\n阿乔：别忘了你答应我的好处！\\n基尼奇：现在，第一步是跳上去…生日快乐。\", \"voicelineId\": 101041, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_starUp_01\", \"description\": \"选刀，只需要坚硬、锋利。\", \"voicelineId\": 101042, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_starUp_02\", \"description\": \"理包，优先考虑精简、轻便…好比这柄伞就是多余的。\", \"voicelineId\": 101043, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_starUp_03\", \"description\": \"行动前，我会绑紧头巾，提醒自己保持冷静和矫健。\", \"voicelineId\": 101044, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_kinich/vo_kinich_starUp_04\", \"description\": \"你为我做了很多，我不会白白收下。你可以主动开价，或是接受我提供的回报…我以「马力卜」之名许诺，哪种选择都不会亏待你。\", \"voicelineId\": 101045, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_ajaw_battle_skill1_01\", \"description\": \"阿乔：算你灵活。\", \"voicelineId\": 101046, \"voicelineType\": \"10000101\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_ajaw_battle_skill1_02\", \"description\": \"阿乔：这就溜了？\", \"voicelineId\": 101047, \"voicelineType\": \"10000102\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_ajaw_battle_skill1_03\", \"description\": \"阿乔：用来用去就这两招…\", \"voicelineId\": 101048, \"voicelineType\": \"10000103\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill1_04\", \"description\": \"目标上钩。\", \"voicelineId\": 101049, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill1_05\", \"description\": \"发现猎物。\", \"voicelineId\": 101050, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill1_06\", \"description\": \"封锁退路。\", \"voicelineId\": 101051, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill3_01\", \"description\": \"报偿夜神。\", \"voicelineId\": 101052, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill3_02\", \"description\": \"领他们上路。\", \"voicelineId\": 101053, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill3_03\", \"description\": \"往昔之影，奉我之命。\", \"voicelineId\": 101054, \"voicelineType\": \"200003\"}, {\"title\": \"元素爆发·其四\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill3_04\", \"description\": \"阿乔：圣龙君临！\", \"voicelineId\": 101055, \"voicelineType\": \"20000101\"}, {\"title\": \"元素爆发·其五\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill3_05\", \"description\": \"阿乔：原灵现示！\", \"voicelineId\": 101056, \"voicelineType\": \"20000102\"}, {\"title\": \"元素爆发·其六\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill3_06\", \"description\": \"阿乔：圣龙烈焰，将照彻汝等腐朽。\\n阿乔：我烧烧烧烧烧。\\n阿乔：啊哈！真是快活！\", \"voicelineId\": 101057, \"voicelineType\": \"20000201\"}, {\"title\": \"元素爆发·其七\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill3_07\", \"description\": \"阿乔：汝之灵魂，应当供奉于吾。\\n阿乔：哈？连声都不敢吭？\\n阿乔：那就再也别吭声啦！\", \"voicelineId\": 101058, \"voicelineType\": \"20000202\"}, {\"title\": \"元素爆发·其八\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_skill3_08\", \"description\": \"阿乔：吾之威光，无人能及！无可比拟！\\n阿乔：更何况我现在心情不好。\\n阿乔：渺小虫豸，付出代价吧！\", \"voicelineId\": 101059, \"voicelineType\": \"20000203\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_chest_open_01\", \"description\": \"基尼奇：见者有份？\\n阿乔：这种破烂你居然想要。\", \"voicelineId\": 101060, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_chest_open_02\", \"description\": \"基尼奇：万物皆有其用。\\n阿乔：你是从小吃不饱饭？\", \"voicelineId\": 101061, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_chest_open_03\", \"description\": \"阿乔：嘁，才这么点穷酸玩意。\\n基尼奇：不拿就走，话真多。\", \"voicelineId\": 101062, \"voicelineType\": \"300003\"}, {\"title\": \"打开风之翼·其一\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_explore_fly_start_01\", \"description\": \"…非用不可吗？\", \"voicelineId\": 101063, \"voicelineType\": \"800001\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_life_less30_01\", \"description\": \"该你偿还代价了。\", \"voicelineId\": 101064, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_life_less30_02\", \"description\": \"将计就计…\", \"voicelineId\": 101065, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_life_less30_03\", \"description\": \"阿乔：基尼奇，快完蛋，快完蛋。\", \"voicelineId\": 101066, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_life_less30_teammate_01\", \"description\": \"你知道自己处境不妙吧？\", \"voicelineId\": 101067, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_life_less30_teammate_02\", \"description\": \"我们来谈谈价格吧？\", \"voicelineId\": 101068, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_life_die_01\", \"description\": \"不要…回头…\", \"voicelineId\": 101069, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_life_die_02\", \"description\": \"凡事皆有代价…\", \"voicelineId\": 101070, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_life_die_03\", \"description\": \"阿乔：呵呵…不错的交易…\", \"voicelineId\": 101071, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_hit_H_01\", \"description\": \"失手。\", \"voicelineId\": 101072, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_kinich/vo_kinich_battle_hit_H_02\", \"description\": \"意外…\", \"voicelineId\": 101073, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_kinich_teamJoin_01\", \"description\": \"成交，我接手了。\", \"voicelineId\": 101074, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_kinich_teamJoin_02\", \"description\": \"我来解决。\", \"voicelineId\": 101075, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_kinich_teamJoin_03\", \"description\": \"祝我们合作愉快。\", \"voicelineId\": 101076, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000102, 'Mualani', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_draw_appear_01\", \"description\": \"尊敬的旅行者，欢迎你参加本次旅行，我是「流泉之众」的向导，玛拉妮，有什么需求请随时伸长手臂向我示意哦！现在，请收好武器，保管好随身物品，在身前抱紧派蒙，最最重要的，是放下烦恼，踏上我给你准备的鲨鲨冲浪板，站稳啦——美妙之旅要开始咯！\", \"voicelineId\": 102000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·出来玩\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_character_idle_01\", \"description\": \"「出来玩」最重要的就是「出来」，只要你来了，剩下的全都交给我来安排吧。\", \"voicelineId\": 102001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·逐浪\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_character_idle_02\", \"description\": \"你试过追着海浪奔跑吗？想试吗？要试吗？就现在就现在！我陪你找片海。\", \"voicelineId\": 102002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·团结\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_character_idle_03\", \"description\": \"一个人挑战，有很多不可能，但一群人就能挑战很多不可能！\", \"voicelineId\": 102003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_weather_heavyRain_01\", \"description\": \"哟吼！湿滑的地面好适合滑铲进场呀！\", \"voicelineId\": 102004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_weather_thunder_01\", \"description\": \"哇哦！劈哪了劈哪了？\", \"voicelineId\": 102005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_weather_snowy_01\", \"description\": \"呃…干完正事就赶紧回去泡温泉吧…\", \"voicelineId\": 102006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_weather_sunny_01\", \"description\": \"想原地躺下晒太阳，晒完一面再翻个面。\", \"voicelineId\": 102007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_weather_gale_01\", \"description\": \"风越大，浪越大，正是挑战高难度动作的好时候！\", \"voicelineId\": 102008, \"voicelineType\": \"1205\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_weather_desert_01\", \"description\": \"在沙子上冲浪一定很刺激吧！「流泉之众」的玛拉妮，来挑战喽！\", \"voicelineId\": 102009, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_greetingMorning\", \"description\": \"好消息，今天没有睡过头！奖励我自己吃顿超豪华早餐吧。\", \"voicelineId\": 102010, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_greetingNoon\", \"description\": \"啊，果然还是起太早了么…不行不行，眼前在闪摩拉，中午得补补觉…\", \"voicelineId\": 102011, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_greetingNight\", \"description\": \"需要送餐服务吗？保证让你吃进嘴的时候还是烫的，相信我冲浪板的速度。\", \"voicelineId\": 102012, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_greetingNight2\", \"description\": \"糟糕…在篝火晚会上跳舞跳精神了，今晚肯定睡不着了…呜。\", \"voicelineId\": 102013, \"voicelineType\": \"1004\"}, {\"title\": \"关于玛拉妮自己·镇店之宝\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_idle\", \"description\": \"店里上架的商品从种类、质量，到功能和颜色全都是我精心挑选过的，但要说我心目中的镇店之宝，就不得不提这件「豚豚泳装」了。水性不好的朋友一定要考虑它，它可以瞬间充气，变成固定在身上的救生豚豚球，这样游泳可就安全多了！\\n就算不游泳的时候也可以穿哦，我喜欢穿上它参加派对，非常抓人眼球！就像这样，弹来弹去…弹来弹去…\\n顺带一提，配色也是好运款！\", \"voicelineId\": 102014, \"voicelineType\": \"2001\"}, {\"title\": \"关于玛拉妮自己·舞蹈\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_idle2\", \"description\": \"「流泉之众」是最好的度假胜地，这里的草木山川似乎能和大家产生共鸣，成为我们的朋友！\\n涌动的波浪，摇曳的海草，飘摆的树叶…它们全都是我崇拜的舞蹈老师，跟着它们的节奏和律动，摇一摇，扭一扭，转个圈，甩起来！怎么样？别愣着看呀，你也一起来试试嘛！\", \"voicelineId\": 102015, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·招呼\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_close\", \"description\": \"看看冲浪板吧！有各种材质和花纹，颜色也很多哦！你的幸运色是什么？没有吗？那我给你挑一块好啦。\", \"voicelineId\": 102016, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·互相托付\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_close1\", \"description\": \"一起去过夜神之国，也并肩遥望过神秘岛的光芒，我们早就是可以互相托付生命的伙伴了。如果哪天你在旅途中突然找不到方向，一定要告诉我！我可是超级厉害的向导，就算用冲浪板撞也会给你撞出条路来！\", \"voicelineId\": 102017, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}, {\"paramList\": [15010], \"unlockText\": \"完成「流泉所归之处」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_pendant_01\", \"description\": \"有段时间，我把「神之眼」挂在了豚豚球身上，这海水一般的湛蓝色，怎么看都很配它。但后来和朋友玩排球的时候我完全忘了这回事，豚豚球落在沙滩上，发出非常清脆的一声「哐嘡」，呼…竟然没摔碎，这肯定是好运的预兆！\", \"voicelineId\": 102018, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_share_01\", \"description\": \"你害怕小狗吗？不怕的话就请和我们家的小狗交朋友吧！它可喜欢跟人玩了，不管见到谁都要跑上前打招呼，盼望着抚摸。哦对了，我们经常一起去玩水，它已经学会冲浪了，不愧是我的好狗狗，青出于我胜于我！\\n有机会介绍你们俩认识呀，它那尾巴啊肯定会甩成螺旋桨。你可当心别被甩到了，还挺疼的，哈哈。\", \"voicelineId\": 102019, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_pref_gift_01\", \"description\": \"在「流泉之众」，鳍游龙跟我们一样喜欢温泉。很多时候，它们还会跟我们泡在同一个池子里。如果不确定面前的小家伙脾气是好是坏，最好先保持距离。\\n你问我怎么判断鳍游龙的脾气？哈哈，我的方法很简单，慢慢地靠近过去，一点点试探。不咬人的话说明脾气挺好的…要是被咬了…就当是亲密接触喽？\", \"voicelineId\": 102020, \"voicelineType\": \"3003\"}, {\"title\": \"关于玛薇卡…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_teammate_mavuika_01\", \"description\": \"火神大人是纳塔最备受敬仰的头号人物，我很崇拜她，不仅因为她是火神大人，更因为…她冲浪的样子真的很帅！\\n我邀请过她参加水上竞速项目…嗯？你好奇我们的输赢？那你和我先比一场吧，你赢过我我就告诉你！\", \"voicelineId\": 102021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡齐娜…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_teammate_kachina_01\", \"description\": \"卡齐娜说话会考虑很多，性格又很温和善良。明明很出色，却因为不争辩而被周围的人看轻。唉，我从不怀疑她的实力，唯一担心的，是她不够自信，容易听信那些抨击她的话…所以，除了鼓励她，我还要把她的优点告诉其他人。相信总有一天，大家会做出改变的！\", \"voicelineId\": 102022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于基尼奇…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_teammate_kinich_01\", \"description\": \"阿乔一天讲的话比基尼奇一年的话还多，在这种情况下，基尼奇居然不受一点干扰，总能做出自己的判断，这还挺不容易的。回想起来，好像只有在聊运势话题的时候，他俩才会出奇一致地呈现出一副不关心的态度…\", \"voicelineId\": 102023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于恰斯卡…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_teammate_chasca_01\", \"description\": \"我小时候就跟恰斯卡见过面，我们还因为争夺玩具之类的原因打过几次架呢…在得知她成为「调停人」之后，我还挺意外的。听说有的人是慢慢长大的，有的人就蜕变得很快。我的成长期…是不是还没到啊？\", \"voicelineId\": 102024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于茜特菈莉…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_teammate_citlali_01\", \"description\": \"茜特菈莉奶奶绝对是「烟谜主」最最资深的祭司，不是小前辈不是中前辈，是一等一的大前辈！她给我预测过的事情都超灵验的，很久之前她说过我在生意上的幸运色是粉色和蓝色，果不其然，现在店里销量最高的就是粉色蓝色搭配售卖的豚豚球。\\n最近我去缠着她，哦不，探望她，她还提到有一个外来者能给我带来吉兆…等等，欸，你不就是外来者嘛！\", \"voicelineId\": 102025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊安珊…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_teammate_iansan_01\", \"description\": \"伊安珊不仅是「沃陆之邦」的骄傲，更是纳塔的骄傲，她参加过好多回「归火圣夜巡礼」，至今都保持着全胜战绩！我还报了她的训练班，培训费早就交好了，只是…只是一直在忙没空去训练…\\n好吧，我坦白，有次看到卡齐娜接受完训练的样子，我心里就浮现一个声音：「哎呀我擅长的都是些水上项目，在陆地上活动太久要搁浅的」…嗯，我要尊重内心的建议。\", \"voicelineId\": 102026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于希诺宁…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_teammate_xilonen_01\", \"description\": \"连火神大人都认可的工匠实力毋庸置疑，就算古名变得稀碎，她也绝对能修得天衣无缝吧？啊！我刚刚是不是说了很不吉利的话？这么重要的东西怎么能弄碎！呸呸呸，刚刚我什么都没说过，你也什么都没听到，好吗？\", \"voicelineId\": 102027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊法…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_teammate_ifa_01\", \"description\": \"伊法这个人可上道了！无论叫他出来玩什么他都乐呵呵的，而且做什么都又快又利索。要不是因为他已经干了医生这一行，我倒是挺希望他能来当水上运动教练。部族差异？小意思啦，根本不成问题！\", \"voicelineId\": 102028, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于梦见月瑞希…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_teammate_mizuki_01\", \"description\": \"你的人脉还挺广嘛！瑞希是我们「流泉之众」的朋友，虽然模样看起来文静，但她有可多话能聊啦。无论什么话题，她都能轻松接住话头，然后和人一直聊下去…嘿嘿，有时候，和她聊着聊着都会忘记时间…\\n噢对了！她在我们这儿的分店铺最近要开张了，有空的话，也来给她的店捧捧场吧？我给她带了紫色的豚豚球作为开业礼物，希望她喜欢！\", \"voicelineId\": 102074, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解玛拉妮·其一\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_friendship_01\", \"description\": \"你有空吗？来我家边坐边聊？边泡温泉边聊也不错！还是说你有想去的地方？我都可以。机会难得，留影机我都带上了，动作我也可以先做示范，放心，今天我们一定能拍出有趣的合影！\", \"voicelineId\": 102029, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解玛拉妮·其二\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_friendship_02\", \"description\": \"向导是一门很依赖经验的工作，好在先祖们给我们留下了大大小小的宝贵习俗，让我们可以少走弯路。不过放心，我不会一股脑就只认老规矩啦，我遵守的都是我已经尝试过，并且行之有效的习惯。\\n有哪些行不通的？嗯…就比如说，有次我想去探索一个新地点，眼前明明有桥，地图却提示需要划船渡河到达对岸。我又是测水流，又是检查桥上有没有机关和隐患…最后终于发现，先祖没推荐走桥是因为——那时候根本没有这个桥嘛！\\n啊…向导果然很依赖经验啊…\", \"voicelineId\": 102030, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解玛拉妮·其三\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_friendship_03\", \"description\": \"我很喜欢接待外地来的游客。每次结束导览后，他们都会感谢我介绍了纳塔的风土人情，而我也会感谢他们。谢谢他们一路上跟我分享见闻，聊自己的家乡，还有我听都没听过的奇闻轶事…对我来说，这同样是一场不可多得的心灵之旅。\", \"voicelineId\": 102031, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解玛拉妮·其四\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_friendship_04\", \"description\": \"虽然我尽量会用大家都能接受的方式交朋友，但…呵呵…有时候也会有人委婉地告诉我，我太热情了，反而不好招架…所以，现在我在刚认识新朋友时都会收敛一点，熟了再热起来…\\n哦，如果你跟我相处过程中有任何不愉快的地方，请不要犹豫，也不要有心理顾虑，直接告诉我！不想当面说，写个匿名纸条也可以哦？我一定会改正的！\", \"voicelineId\": 102032, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解玛拉妮·其五\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_friendship_05\", \"description\": \"面对困境，每个人都有巨大潜能，参加过「归火圣夜巡礼」后，我无比赞同这一点！但我依然觉得，「两个人」总比「一个人」有更多选择，「三个人」又比「两个人」更有赢面…所有人团结一心，一定能创造不可思议的奇迹！\\n就拿「巡夜者战争」来说吧，不仅是现在的我们，还有世代以来保卫纳塔的英杰们，以及此后继续为之奋斗的后辈们，所有的努力积攒起来，才会有越来越好的纳塔。我想，这就是「沃摩延」的意义吧…\", \"voicelineId\": 102033, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"玛拉妮的爱好…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_pref_hobby\", \"description\": \"游泳，跳水，滑水，冲浪，水上滑翔伞，沙滩排球，划船、潜水、水上排球还有水下憋气…哎呀，我喜欢的项目借豚豚球的手都数不来。玩累了我就躺在水上休息，有好几次都睡着了，舒服是舒服，但代价就是醒来后不知道漂到哪里去了，被部族里的长辈训了好久…\", \"voicelineId\": 102034, \"voicelineType\": \"6001\"}, {\"title\": \"玛拉妮的烦恼…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_dialog_annoyed_01\", \"description\": \"不开心的时候，我会告诉自己「哎呀，没关系的，运势不太好而已，这只是糟糕的一天，不是糟糕的一生」，心情就能慢慢调整过来。要是还不管用，我会乘着游隙灵道，在高速的弯道上痛快地放声呼喊，几个来回下来，烦恼就被甩在身后啦，根本追不上我。\", \"voicelineId\": 102035, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_pref_foodLike\", \"description\": \"那种一盘子端上来，不带一点蔬菜，也没有禽肉和兽肉的纯海鲜大餐，吃上一口，就像扎进海里一样，化作一条小鱼，游来游去…唔…太满足了。\", \"voicelineId\": 102036, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_pref_foodDislike\", \"description\": \"我还挺后悔小时候偷偷把牛奶倒进温泉里的，不然我应该还能再长高一些…没关系，我答应过阿伽娅阿姨，再也不会那么做了！现在我会好好喝牛奶的，长高还来得及！你也是哦，我们都要引以为戒啊！\", \"voicelineId\": 102037, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_spice_pref_01\", \"description\": \"怎么会这么好吃！美味程度让人想要踩着冲浪板翻转三周…不落地那种！\", \"voicelineId\": 102038, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_spice_normal_01\", \"description\": \"还有吗还有吗？这个放在派对上绝对会被一扫而空。\", \"voicelineId\": 102039, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_spice_dislike_01\", \"description\": \"要不要试试用温泉泡一下？那样口感更好哦！\", \"voicelineId\": 102040, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_pref_birthday_01b\", \"description\": \"生日快乐！礼物请等会再拆吧，我特意选了这家人气最旺的餐厅…朋友的祝福你肯定收到不少了，但如果说能请旅途的有缘人一起帮你庆祝，你想要体验一下吗？\\n嘿嘿，请坐请坐，请接受大家给你的祝福吧。咳咳——打扰一下，大家请看向我！今天是我朋友的生日，就是这位实力超群，品格高尚，击退过最凶猛的巨兽，也治愈过最纤细的灵魂的大英雄！能请在场的大家送给{M#他},{F#她}最美好的祝福吗？来，这边的朋友跟我念，祝你——寻宝好运气！好，那边的朋友——战斗不费力！很好，最后大家一起——生日快乐，健康幸福！\", \"voicelineId\": 102041, \"voicelineType\": \"7001\", \"voicefile_male\": \"VO_friendship/VO_mualani/vo_mualani_pref_birthday_01a\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true, \"hasGenderedVoicefile\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_starUp_01\", \"description\": \"哦哟，正是我想要的！那就不客气啦。\", \"voicelineId\": 102042, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_starUp_02\", \"description\": \"手劲在噌噌噌往上涨，想来一场精彩激烈的沙滩排球友谊赛吗？\", \"voicelineId\": 102043, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_starUp_03\", \"description\": \"运势来了…我有手感！现在完全可以征服上次拍翻我的巨浪了，事不宜迟，现在就去挑战。\", \"voicelineId\": 102044, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_mualani/vo_mualani_starUp_04\", \"description\": \"为了旅客的安全，通常我会阻止他们去危险的地方。但我知道你有不得已的情况，也免不了主动踏入危险境地，所以为了你的安全，请让我一路陪着你，肩并肩克服这些险境吧。\", \"voicelineId\": 102045, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_skill1_01\", \"description\": \"起乘！\", \"voicelineId\": 102046, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_skill1_02\", \"description\": \"甩尾。\", \"voicelineId\": 102047, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_skill1_03\", \"description\": \"加速咯！\", \"voicelineId\": 102048, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_skill1_04\", \"description\": \"哟呼！\", \"voicelineId\": 102049, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_skill1_05\", \"description\": \"超棒！\", \"voicelineId\": 102050, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_skill1_06\", \"description\": \"浪来咯！\", \"voicelineId\": 102051, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_skill3_01\", \"description\": \"巨浪——哗啦哗啦。\", \"voicelineId\": 102052, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_skill3_02\", \"description\": \"飞澜鲨鲨！\", \"voicelineId\": 102053, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_skill3_03\", \"description\": \"看我看我！祝你好运！\", \"voicelineId\": 102054, \"voicelineType\": \"200003\"}, {\"title\": \"冲刺开始·其一\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_explore_sprint_start_01\", \"description\": \"快跑。\", \"voicelineId\": 102055, \"voicelineType\": \"700001\"}, {\"title\": \"冲刺开始·其二\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_explore_sprint_start_02\", \"description\": \"需要借你我的冲浪板吗？\", \"voicelineId\": 102056, \"voicelineType\": \"700002\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_chest_open_01\", \"description\": \"我就说今天是幸运日吧！\", \"voicelineId\": 102057, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_chest_open_02\", \"description\": \"好东西总是压箱底。\", \"voicelineId\": 102058, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_chest_open_03\", \"description\": \"哎呀掉地上了，快捡起来。希望不要掉财运…\", \"voicelineId\": 102059, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_life_less30_01\", \"description\": \"我还要保护我的旅客。\", \"voicelineId\": 102060, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_life_less30_02\", \"description\": \"今天的运势不太好…\", \"voicelineId\": 102061, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_life_less30_03\", \"description\": \"我会赢…我会赢！\", \"voicelineId\": 102062, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_life_less30_teammate_01\", \"description\": \"你不是一个人在战斗！\", \"voicelineId\": 102063, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_life_less30_teammate_02\", \"description\": \"过分，换我来揍它！\", \"voicelineId\": 102064, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_life_die_01\", \"description\": \"向导怎么能掉队…\", \"voicelineId\": 102065, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_life_die_02\", \"description\": \"「我们不会孤军奋战」…\", \"voicelineId\": 102066, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_life_die_03\", \"description\": \"终点是…回家…\", \"voicelineId\": 102067, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_hit_L_02\", \"description\": \"好了好了。\", \"voicelineId\": 102068, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_hit_H_01\", \"description\": \"别太过分！\", \"voicelineId\": 102069, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_mualani/vo_mualani_battle_hit_H_02\", \"description\": \"我的冲浪板——\", \"voicelineId\": 102070, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_mualani_teamJoin_01\", \"description\": \"哇，这个组合，赢定了！\", \"voicelineId\": 102071, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_mualani_teamJoin_02\", \"description\": \"你好你好，全体队友都好吗？\", \"voicelineId\": 102072, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_mualani_teamJoin_03\", \"description\": \"呜呼！冲冲冲。\", \"voicelineId\": 102073, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000103, 'Xilonen', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_draw_appear_01\", \"description\": \"你好，我是「回声之子」的希诺宁。如果想要委托我锻造普通器具的话，直说就好。但我手里还堆积了不少单子，你现在下委托的话，可能要等一阵了。\", \"voicelineId\": 103000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·绿植\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_character_idle_01\", \"description\": \"唉，阳台上的那盆花又枯了，我明明每天都给它浇水…难道这次是浇太多了？\", \"voicelineId\": 103001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·休息时间\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_character_idle_02\", \"description\": \"奔波这么久，也该歇一歇了…就在这坐一会吧。\", \"voicelineId\": 103002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·锻造事务\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_character_idle_03\", \"description\": \"…还有几份锻造委托没完成来着？呃…一份…两份…不算多嘛，明天再说吧。\", \"voicelineId\": 103003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_weather_heavyRain_01\", \"description\": \"这天气，就适合待在屋里睡觉。\", \"voicelineId\": 103004, \"voicelineType\": \"1201\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_weather_snowy_01\", \"description\": \"阿嚏！…哎呀，瞌睡虫走了。\", \"voicelineId\": 103005, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_weather_sunny_01\", \"description\": \"呼啊…睡个午觉吧。欸？我的墨镜去哪了。\", \"voicelineId\": 103006, \"voicelineType\": \"1203\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_weather_desert_01\", \"description\": \"温度刚刚好…唔，但这里不太适合躺下呢。\", \"voicelineId\": 103007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_greetingMorning\", \"description\": \"早上好，昨晚睡得好么？这杯饮料给你，早晨喝点甜的，一天都会有好心情。\", \"voicelineId\": 103008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_greetingNoon\", \"description\": \"中午了，是…呼啊…是午休时间了…我去睡会，有事再叫醒我。\", \"voicelineId\": 103009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_greetingNight\", \"description\": \"都这个点了，收工收工。走，一起去吃点好吃的，庆祝一天的工作顺利结束。\", \"voicelineId\": 103010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_greetingNight2\", \"description\": \"晚安了，睡前记得把枕头弄松软，不然第二天早上起来会脖子疼。\", \"voicelineId\": 103011, \"voicelineType\": \"1004\"}, {\"title\": \"关于希诺宁自己·劳逸结合\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_idle\", \"description\": \"无论有多忙，也要为自己挤出休息的时间。一直工作个不停的话，身体和头脑就会接连罢工，在这种状态下，是不会做出好成果的。\\n挤不出来时间？那你就说…我临时找你有事，到我的工坊来睡一会吧，我会帮你瞒过去的。\", \"voicelineId\": 103012, \"voicelineType\": \"2001\"}, {\"title\": \"关于希诺宁自己·迟钝\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_idle2\", \"description\": \"我的几位朋友有时候会说我有些迟钝，很难被感动。比如有一次我去一个朋友家里参加聚会，聊着聊着就谈到了结婚的事，有个朋友问我们，如果她结婚了大家会不会哭，然后大家讨论了一会之后就哭成了一团，一边哭一边说不想失去她这个朋友…\\n我是完全不懂大家为什么哭啦。结婚不是一件好事吗？她只是去结婚，又不是去见大灵，大家有空还是能再见啊。\\n如果是即将被迫结婚，难过地哭怎么办？噢，我想过了。\\n如果是这样的话，我就会直接把她从婚礼现场抢回来，我跑得很快，一定来得及。\", \"voicelineId\": 103013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·锻造之用\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_close\", \"description\": \"无论是锻造什么东西，炉子内火焰的温度都至关重要。太低的话，就无法软化——或者融化——原材料，也无法剔除各类杂质。太高的话，又会让某些原材料无法发挥作用。\\n工匠们调控炉内火焰的方法，就是炉内温度高了就抽薪，温度低了就加柴。\\n至于我嘛，一般会使用含有燃素的宝石来直接调控炉内温度，用燃素助燃的火焰，比一般的火焰可厉害多了…\\n啊？燃素用完之后的宝石怎么办？就只能找个地方堆起来喽。燃素都没了，它们唯一的作用就只有好看。你想要的话，就去挑几块吧。\", \"voicelineId\": 103014, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·祝福\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_close1\", \"description\": \"特拉佐莉婶婶之前说，要给你们打造一枚「燃晶名刻」做礼物，对吧？看现在的情况，她是没这个功夫了。\\n所以这份工作现在就由我代劳。就当作是你们帮我救了妮佩卡的谢礼吧。\\n我已经给你们做过一枚「古名」了？\\n哈哈哈，那不算。那枚「古名」里包含的是大家对你的「祝福」，这枚「名刻」则是我个人对你的「祝福」。\\n别客气了，做好了之后我告诉你。至于上面刻什么字…到时候就由你自己决定吧。\", \"voicelineId\": 103015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}, {\"paramList\": [15016], \"unlockText\": \"完成「祈祝福愿，倾告嵴锋」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_pendant_01\", \"description\": \"你说「神之眼」啊，还挺好用的。有了它之后，我可以更准确地判断矿石中「岩」元素的含量与分布情况，从而快速地筛选出好矿与废矿。\\n意义？嗯…我倒是没想那么多，它能派上用场就行，其余的我不在意。\", \"voicelineId\": 103016, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_share_01\", \"description\": \"为了锻炼精细加工的能力，我经常会尝试锻造一些带有复杂结构的小型饰品。比如编织网状的吊坠，织卷形式的耳环，做出来之后，我一般就会把这些小饰品送给朋友或者邻居。\\n会不会做戒指？当然会做啊，前几天我刚做出了一枚灼灼彩菊式样的戒指，光是画设计图就费了我不少功夫。\\n你想要？行啊，把手伸出来，我给你量一下指围，花不了多少时间就能做好。\", \"voicelineId\": 103017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_pref_gift_01\", \"description\": \"我是搞不懂养绿植这件事了…我明明按照要求，三天浇一次水，五天除一次草，每周施肥两次，而且也严格保证了它们受到日照的时长…但我手里的这些绿植还是全都枯萎了。\\n唉…难道养花种草这件事也要看运气？\", \"voicelineId\": 103018, \"voicelineType\": \"3003\"}, {\"title\": \"关于卡齐娜…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_teammate_kachina_01\", \"description\": \"之前卡齐娜拜托我打造一枚钻探器，而且这枚钻探器要同时兼顾钻探和弹跳功能。造起来倒是不复杂，反倒是调整座椅角度时花了不少时间。最后，卡齐娜还是同意了我的意见，拆除了座椅，采用了和钻探器的动力核心联动的手动操作装置…\\n呃…为什么卡齐娜操作「冲天转转」的时候，自己也会跳来跳去？\\n这是卡齐娜的要求。她说自己很喜欢操纵钻探器跳跃时的颠簸感，所以特地让我削减了一部分减震系统。\\n不然，我下次再给卡齐娜做一套咬具吧。要是她在蹦蹦跳跳的时候咬伤自己的舌头就糟糕了…\", \"voicelineId\": 103019, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于玛拉妮…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_teammate_mualani_01\", \"description\": \"玛拉妮很擅长运动，无论是冲浪，还是在「游隙灵道」滑行，我都没见过比她动作更顺畅，表情更轻松的人。而且，直到现在为止，我都没见过玛拉妮出过失误。\\n如果有人或者龙挡路怎么办？唔…她应该会拎起对方继续滑走吧。\", \"voicelineId\": 103020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于恰斯卡…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_teammate_chasca_01\", \"description\": \"为了能飞上天，恰斯卡的「枪」可费了我不少功夫。首先要尽可能保证枪体在高速机动中的稳定性，其次就是要特制出适应高空作战的普通弹药和特种弹药，最后，还要考虑到空中开火的后坐力和瞄准问题…\\n但恰斯卡对我说，最后两个问题不用担心，我只需要在枪上装载最基础的机械瞄具，剩下的她会靠自己的能力解决。\\n事实证明，恰斯卡确实把她的「枪」驾驭得很好，真不愧是「花羽会」的空中王牌。\", \"voicelineId\": 103021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于玛薇卡…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_teammate_mavuika_01\", \"description\": \"玛薇卡向我提出过不少异想天开的委托。\\n比如，要我打造一柄耐热的剑，剑的整体都要耐得住她的火焰，不至于她一发力，整柄剑都会在她手里融化；还有拜托我打造一副特制的墨镜，这样她操纵火焰战斗的时候，能更好地看清周围的敌人…\\n最莫名其妙的还是那台驰轮车。那段时间她天天跑到我的工坊里念叨，非要我给她做一台用燃素驱动的代步驾具，还塞给我了一大堆不知道从哪弄来的设计图…最后我实在受不了了，花了整整三个月，帮她做好了那台驰轮车。结果我听说，这家伙天天开着驰轮车在纳塔的野外到处狂奔，还没人能去管她…\\n…比起这些事，为一位外来的旅行者打造「古名」，反倒像是一件相对来说比较靠谱的事务了。\", \"voicelineId\": 103022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于基尼奇…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_teammate_kinich_01\", \"description\": \"基尼奇人还不错，但那个阿乔实在让人喜欢不起来。\\n话说回来，阿乔到底是从哪出现的？要是它来源于某台仪器，那我也许还真能让它永远闭嘴。唔，要不然我挑个时间，去和基尼奇说说吧…\", \"voicelineId\": 103023, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于茜特菈莉…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_teammate_citlali_01\", \"description\": \"茜特菈莉有时候会来我的工坊买矿石。据她说，有些矿石磨成粉后能够做成可服用的药物，帮助她进行占卜和祭祀。我有没有拜托她进行过占卜？没有，我对尚未发生的事情没有兴趣。当下的事务就够我操心的了，而且我总是会在占卜仪式上犯困…\", \"voicelineId\": 103024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊法…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_teammate_ifa_01\", \"description\": \"伊法来部族里治疗过嵴锋龙，手法非常不错，也很会照顾。无论是多调皮的小龙，在他面前都乖乖地不乱动。\\n伊法说，多亏了我给他打造的那一套龙用注射器，就算不套上针管，对龙和人也非常有威慑力。你想看看吗？我还留了一套样品呢。\\n你等会啊，我把最大的那根注射器拿出来…哎，你别往后退啊，上面没套针管，很安全的。\", \"voicelineId\": 103025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于欧洛伦…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_teammate_olorun_01\", \"description\": \"按照负负得正的理论，一群怪人里的怪人应该是正常人才对，但显然欧洛伦另辟蹊径了。\\n不过他人还不错，后来托伊法给「回声之子」送来不少水果和蜂蜜，大概是觉得给大家添麻烦了吧。我都不知道还能通过燃素蜜虫获得这么甜的蜜呢，看来他确实有些本事。\\n…唉，怎么会有人养什么活什么呢？\", \"voicelineId\": 103026, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊安珊…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_teammate_iansan_01\", \"description\": \"我曾经帮「沃陆之邦」的人做过一批重得要命的「杠铃片」和「哑铃壶」。\\n那边来收货的时候，就是伊安珊带队验收，她就那么赤手空拳地把每一个器具都提起来称量，再挨个装车。装到最后，伊安珊只是略略有些气喘，脸也红了一些。\\n说实话有点羡慕她们部族的人，不仅力气大，还很会种地…\", \"voicelineId\": 103027, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解希诺宁·其一\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_friendship_01\", \"description\": \"虽然我是「铸名师」，但铸造「古名」并不是我的主业。相对来说，帮部族内外的人锻造器具和武器，才是我主要的工作。\\n毕竟「古名」稀少，但大家的锻造委托可是无穷无尽啊…\", \"voicelineId\": 103028, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解希诺宁·其二\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_friendship_02\", \"description\": \"在接受大家的锻造委托时，最让我疲惫的并不是工作本身，而是一部分委托人含糊不清的用语。在开始打造之前，我必须花费大量的精力帮助委托人捋清思路，让他们弄清楚，自己究竟想要什么。\\n每次看见委托人恍然大悟的欣喜表情，我的胃都会有些发痛，吃饭的时候都会不由自主地少吃一些。\", \"voicelineId\": 103029, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解希诺宁·其三\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_friendship_03\", \"description\": \"没有锻造委托时，我经常会做一些小玩意。比如我脚下的这双鞋，采用了最新的燃素推进系统，和许多新型合成金属，既轻便又坚固。还有我戴着的耳塞，可以和唱片机连接，戴上它，我就可以一边听唱片一边锻造了…\\n复杂？还好吧。做自己喜欢的东西时，总归比工作要更有热情。\", \"voicelineId\": 103030, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解希诺宁·其四\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_friendship_04\", \"description\": \"我之所以会成为「铸名师」，主要原因还是我爸是「铸名师」，我妈也是「铸名师」，我的同族们大部分都成为了「铸名师」。我小时候爸妈一直和我说，整个纳塔里只有我们这一族能够担当起为诸部族铸造「古名」的重任，希望我长大以后也能够继续接过他们的衣钵，继续铸造「古名」。\\n我答应了，事情就是这么简单。\", \"voicelineId\": 103031, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解希诺宁·其五\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_friendship_05\", \"description\": \"但是，在成为「铸名师」之前，我也认真想过，到底要不要沾上这份麻烦。毕竟还有很多轻松的工作供我选择，就算是做一名普通的工匠，也比做「铸名师」轻松多了，而且以我的手艺，赚得也应该更多。\\n不过…我最终还是选择了「铸名师」。\\n铸造「古名」是一份必须要找人来承担的重任，我正好有与之对应的能力，就有将它接下来的义务。就和我爸经常说的那句话一样：「当每一位纳塔人都担起自己能够担负的责任时，纳塔就能屹立万世。」\\n这件事无关我的个人喜恶，只是责任，仅此而已。\\n而且，在族内那一批学习铸造「古名」技术的人里，我学得是最好的。如果我不做「铸名师」，肯定就要换其他人，这帮家伙在课上就成天问我问题，抄我作业，要是去铸造「古名」，他们肯定还是要每天过来搅我清净。与其这么麻烦，我还不如直接做「铸名师」，这样对大家都方便，也省得我成天为分外的工作操心。\", \"voicelineId\": 103032, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"希诺宁的爱好…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_pref_hobby\", \"description\": \"睡觉，发呆，晒太阳。不干活时，连盯着白纸都很有趣。\", \"voicelineId\": 103033, \"voicelineType\": \"6001\"}, {\"title\": \"希诺宁的烦恼…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_dialog_annoyed_01\", \"description\": \"在和人谈锻造委托的时候，我最怕听见一句话：「这件事既不紧急，也不重要，听你安排，尽快就好。」\\n在我的工作经验中，这句话一般就等于说：「我随时都可能来催你。」\\n唉，想想就头痛，我还是再睡会吧。\", \"voicelineId\": 103034, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_pref_foodLike\", \"description\": \"糖，巧克力。我的工作可是锻造，必须要多吃这些，才会有力气挥锤子。\", \"voicelineId\": 103035, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_pref_foodDislike\", \"description\": \"没味道的水。好啦好啦，我知道多喝纯净的水有益身体健康，但我就是喝不下去嘛，至少要加点糖吧？实在不行，挤点柠檬汁进去也好。\", \"voicelineId\": 103036, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_spice_pref_01\", \"description\": \"好吃，还有么？什么时候吃完的…就在刚刚，我吃东西很快的。吃美食的时候会更快。\", \"voicelineId\": 103037, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_spice_normal_01\", \"description\": \"味道不错啊，下次请你尝尝我的手艺。\", \"voicelineId\": 103038, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_spice_dislike_01\", \"description\": \"嗯…先不用了，东西吃多了容易犯困。\", \"voicelineId\": 103039, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_pref_birthday_01\", \"description\": \"生日快乐。这套「全尺寸万用工具套装」给你，里面有各种尺寸的钻子和锤子，还有三把手工锯和五柄特型撬刀，应该足够你在野外使用了。哦对了，还有一套混合了金属线和皮革线的绳索，强度足够吊起一只成年嵴锋龙，你会打绳结吗？不会的话我现在教你，看好了啊，先抓住绳头，这么绕过来。\", \"voicelineId\": 103040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_starUp_01\", \"description\": \"…喵？\", \"voicelineId\": 103041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_starUp_02\", \"description\": \"嗯，真金尚需火炼，谢啦。\", \"voicelineId\": 103042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_starUp_03\", \"description\": \"眼睛好像更敏锐了，挥舞锤子的手也更有力气。稍等，我去找点东西练练手，你离远点。\", \"voicelineId\": 103043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_xilonen/vo_xilonen_starUp_04\", \"description\": \"你帮了我这么多忙，我可不能让你白跑一趟。拿着，我把自己的「名字」刻在了这块宝石上，凭这个你随时都可以来找我帮忙。无论是让我的炉火专门为你燃起，还是拜托我和你一起去踏足险地，都没有问题。直到我的「名字」和这块宝石一起风化之前，这份承诺一直有效。\", \"voicelineId\": 103044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_battle_skill1_01\", \"description\": \"来吧。\", \"voicelineId\": 103045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_battle_skill1_02\", \"description\": \"哼。\", \"voicelineId\": 103046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_battle_skill1_03\", \"description\": \"呼…\", \"voicelineId\": 103047, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_battle_skill3_01\", \"description\": \"回荡吧，壑之声！\", \"voicelineId\": 103048, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_battle_skill3_02\", \"description\": \"沸腾吧，山之血！\", \"voicelineId\": 103049, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_battle_skill3_03\", \"description\": \"深壑荡响，铭集火渊。\", \"voicelineId\": 103050, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_chest_open_01\", \"description\": \"我盯着旁边呢，没有埋伏，放心吧。\", \"voicelineId\": 103051, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_chest_open_02\", \"description\": \"好东西不少，分我一份？开玩笑的，你拿着就行。\", \"voicelineId\": 103052, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_chest_open_03\", \"description\": \"唔…这些东西应该能值点钱，赶紧收着吧。\", \"voicelineId\": 103053, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_life_less30_01\", \"description\": \"麻烦…\", \"voicelineId\": 103054, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_life_less30_02\", \"description\": \"够了。\", \"voicelineId\": 103055, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_life_less30_03\", \"description\": \"…哼！\", \"voicelineId\": 103056, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_life_less30_teammate_01\", \"description\": \"我来接手。\", \"voicelineId\": 103057, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_life_less30_teammate_02\", \"description\": \"交给我。\", \"voicelineId\": 103058, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_life_die_01\", \"description\": \"…燃烧…殆尽…\", \"voicelineId\": 103059, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_life_die_02\", \"description\": \"冷下去了…\", \"voicelineId\": 103060, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_life_die_03\", \"description\": \"呵…也该…睡了…\", \"voicelineId\": 103061, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_battle_hit_L_02\", \"description\": \"又来麻烦了…\", \"voicelineId\": 103062, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_xilonen/vo_xilonen_battle_hit_H_02\", \"description\": \"…够烦人的！\", \"voicelineId\": 103063, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_xilonen_teamJoin_01\", \"description\": \"要出发了？\", \"voicelineId\": 103064, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_xilonen_teamJoin_02\", \"description\": \"尽快解决吧。\", \"voicelineId\": 103065, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_xilonen_teamJoin_03\", \"description\": \"那就走吧，我跟着你。\", \"voicelineId\": 103066, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000104, 'Chasca', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_draw_appear_01\", \"description\": \"「花羽会」，恰斯卡。有什么「矛盾」需要我调停吗？视情况而定可能要费点面子，花些钱酒，或者…耗几枚子弹。\", \"voicelineId\": 104000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·俯瞰\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_character_idle_01\", \"description\": \"如果迷失了方向，不如飞到高处去看看吧。\", \"voicelineId\": 104001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·声音\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_character_idle_02\", \"description\": \"倘若任由深渊的声音牵引，我早就不是我自己了。比生存更难的是克服本能。\", \"voicelineId\": 104002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·调解\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_character_idle_03\", \"description\": \"最近有点手生了…嗯…哪里有「矛盾」可以调解调解吗？\", \"voicelineId\": 104003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_weather_heavyRain_01\", \"description\": \"雨水…会打湿头发跟羽毛，回头要好好护理。\", \"voicelineId\": 104004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_weather_thunder_01\", \"description\": \"嚯？在这种天气里飞行，是想跟闪电比谁快吗？\", \"voicelineId\": 104005, \"voicelineType\": \"1202\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_weather_breezy_01\", \"description\": \"风里有猎物的气味…做好准备。\", \"voicelineId\": 104006, \"voicelineType\": \"1203\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_weather_gale_01\", \"description\": \"风向正好——全速前进！\", \"voicelineId\": 104007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_greetingMorning\", \"description\": \"「早起的绒翼龙有肉吃。」——所以我准备了一点早餐，有什么任务都先填饱肚子再说吧。\", \"voicelineId\": 104008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_greetingNoon\", \"description\": \"午安。中午的日头正盛，可以先休息一下。\", \"voicelineId\": 104009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_greetingNight\", \"description\": \"晚餐准备怎么解决？要不去「花羽会」吧，宴请「强者」的酒和肉永远管够。\", \"voicelineId\": 104010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_greetingNight2\", \"description\": \"你要休息了吗？嗯…飞了一整天，我也该保养一下我的枪械了。\", \"voicelineId\": 104011, \"voicelineType\": \"1004\"}, {\"title\": \"关于恰斯卡自己·自信\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_idle\", \"description\": \"「花羽会」曾经承担梭巡援护纳塔全境的职责，飞行队里更集结了全纳塔最精锐、最迅猛的战士。\\n时至今日，这份孤高与骄傲依旧铭刻在许多绒翼龙骑士的心里…嗯？我吗？我并不「孤傲」，只是「自信」而已。\", \"voicelineId\": 104012, \"voicelineType\": \"2001\"}, {\"title\": \"关于恰斯卡自己·花羽会\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_idle2\", \"description\": \"…刚回「花羽会」的时候，我跟整个人类世界格格不入，像是一个突然被丢进人群的异类…但是葵可，还有她的…不，还有我们的父母，接受了那时的我。\\n跟他们相遇是值得我庆幸一生的事，所以我也会用一生…去守护他们所爱的「花羽会」。\", \"voicelineId\": 104013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·摆平\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_close\", \"description\": \"以你的身手，在纳塔应该不会有谁敢主动招惹。但凡事都有个万一，如果遇上什么不太好直接通过动手摆平的麻烦，记得来找我。\", \"voicelineId\": 104014, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·家人\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_close1\", \"description\": \"柯娅的事…真是多谢了。如果那时候没有你在，也不知道会怎么收场。\\n姐姐现在已经没那么抵触人类了，但要改变这么多年来的习惯，恐怕还要花上一点时间来适应。\\n奇梅倒是很喜欢来「花羽会」玩，现在跟娅特兰他们处得不错…呵，有时候看着他们，就像是看到了小时候的我跟姐姐一样。\\n最麻烦的反而是妈妈那边…她最近总爱催我学姐姐早点筑什么巢？还说要看看身边有什么合适的家人？真搞不明白她是想表达什么意思…嗯？你在笑什么？\", \"voicelineId\": 104015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [15023], \"unlockText\": \"完成「花之归尘，羽之将坠」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_pendant_01\", \"description\": \"这枚「神之眼」在我与深渊的对抗中意义重大。如果不是它及时出现，不知道现在的我会是什么样子。\", \"voicelineId\": 104016, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_share_01\", \"description\": \"经常会有人觉得小时候做错的事难以启齿…这是为什么呢？人类也好绒翼龙也好，不都是靠着认清过去的错误来成长的吗？\\n所以我从不回避小时候动手打架不经思考的事实。至于现在，我在拔枪前都会思考几秒…或者零点几秒。\", \"voicelineId\": 104017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_pref_gift_01\", \"description\": \"纳塔有不少高耸的树木，站在上面能获得良好的视野和起飞高度，你要不要也来试试？别怕，真掉下去了我会接住你的。\", \"voicelineId\": 104018, \"voicelineType\": \"3003\"}, {\"title\": \"关于卡齐娜…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_teammate_kachina_01\", \"description\": \"「每只绒翼龙在学会飞行前都曾跌落山崖。」卡齐娜的胜利不是一朝一夕突然降临的奇迹，而是长久努力积累出的结果。像她这样的战士，理应获得更多尊重和荣誉。\", \"voicelineId\": 104019, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于玛拉妮…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_teammate_mualani_01\", \"description\": \"玛拉妮说我们小时候因为争抢玩具的原因打过架，不过我已经没什么印象了。\\n嗯…难道是因为我小时候打过的架实在太多？还是说那时候我想要抢夺的并不是什么「玩具」…而是盯上了冲浪板的水上狩猎性能…\\n呵，不管是因为什么而起，跟玛拉妮闹的矛盾，都留不到下一天。\", \"voicelineId\": 104020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于希诺宁…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_teammate_xilonen_01\", \"description\": \"希诺宁她看着总是提不起劲，但真要较起劲来可比谁都认真。\\n我请她帮忙打造枪械的时候没想太多，只是给了最基本的需求，就把这事放在了脑后。等到她正式开始动工，她抓着我问了一整天平时的飞行习惯和使用预期，出了满地的图纸跟废案…真没想到我也会有比她先困到睡着的一天。\\n后来她还硬是让我背下了她写的《枪械维护手册》，说是免得我以后天天来烦她…不过她真正的意思，大概是让我「注意安全，谨慎飞行」吧。\", \"voicelineId\": 104021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于玛薇卡…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_teammate_mavuika_01\", \"description\": \"有人因为我在「归火圣夜巡礼」中的胜率高，就拿我和火神大人进行比较。这太片面了。如果把我比作树梢上的一只鹫，那火神大人便是天上的太阳。实力越强，越是知道她的深不可测。我只是赢了几场比赛，而她…却冠绝了整个时代。\\n——但也正因为这样，我才能清晰地看见，自己想要飞向的高度，到底在哪里。\", \"voicelineId\": 104022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于基尼奇…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_teammate_kinich_01\", \"description\": \"我最早见到阿乔的时候，还以为它跟基尼奇也是情同家人的关系，没想到错得离谱…原来人跟龙还能这么相处。\\n不过阿乔会人类语言这点倒是挺让我羡慕的，要是「妈妈」也能开口说话，我们就不用靠比划跟猜测来聊天了。\", \"voicelineId\": 104023, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于茜特菈莉…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_teammate_citlali_01\", \"description\": \"听老爹说，当年他们请教了全纳塔最富学识的长老们，来为我制定控制深渊影响的方案。当时他们各执己见、争论不休，都没人留意到茜特菈莉一声不吭地走出了门。等她回来，只见她把酒和菜往自己面前一放，自顾自地吃了起来…一时间全桌人鸦雀无声。\\n光看外表，还真难想象她有这么高的资历跟辈分。\", \"voicelineId\": 104024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊法…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_teammate_ifa_01\", \"description\": \"葵可跟老爹经常找他讨论医术。从空中工坊回来之后，我第一时间就去找伊法来检查姐姐的情况。但他只是看了一眼，撂下一句「没多大问题，库斯可能解决」就转头去治别的病号了…唉，事实也证明他的眼光确实毒辣，是我关心则乱了。\", \"voicelineId\": 104025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [15023], \"unlockText\": \"完成「花之归尘，羽之将坠」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊安珊…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_teammate_iansan_01\", \"description\": \"我一直觉得「让自己变得更强」和「让别人也变得更强」是两种不同的才能。能兼具这两者的人少之又少，伊安珊就是其一。\\n比如我就不太懂该怎么教人。每次给飞行队的成员讲解示范，总是要在一些简单枯燥又显而易见的技巧上说明半天…还会反复被问「这怎么就显而易见了？」\\n要是换了伊安珊来，「花羽会」每年通过飞行试炼的人估计能翻上一番吧…可惜她的培训项目里向来没有飞行。\", \"voicelineId\": 104026, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解恰斯卡·其一\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_friendship_01\", \"description\": \"身为一名调停人，我很清楚用武力无法解决所有矛盾。但很多时候持有武力本身，就是让人愿意听你说话的前提。\", \"voicelineId\": 104027, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解恰斯卡·其二\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_friendship_02\", \"description\": \"「花羽会」的战士向来高傲，但绒翼龙却比他们更高傲。即使是像我这样从小跟绒翼龙相伴着长大的人，要想登上龙背成为骑士，都要经过严苛的训练，再取得绒翼龙的认可。毕竟让实力不济的人乘着龙飞向天空，不管是对龙还是对人而言，都是不负责任的。\", \"voicelineId\": 104028, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解恰斯卡·其三\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_friendship_03\", \"description\": \"一些屡次在飞行试炼中失利，没有被绒翼龙认可的人，最后会失去斗志，放弃挑战。这些人在「花羽会」里会被称作「失翼者」…不过曾经挑战飞行试炼的人，往往已是出类拔萃的战士。即便战意一度熄灭，也终会有重燃的一天。我们会一直默默关照这些人，就像绒翼龙关照还没学会飞行的幼崽。\", \"voicelineId\": 104029, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解恰斯卡·其四\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_friendship_04\", \"description\": \"我从出生起就失去了普通人应有的童年…但「妈妈」在我濒死垂危时给了我新的生命，葵可在我迷茫不前时给了我新的信念…在我的背后，有人与龙两个家庭，还有纳塔无数生命牵系的家庭——所以我绝不能被吞没，「深渊」也好「苦难」也好…都由我来「超越」！\", \"voicelineId\": 104030, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解恰斯卡·其五\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_friendship_05\", \"description\": \"葵可她…希望我成为「英雄」，所以我不能为她停下脚步，不能让自己变得软弱…\\n可在「遗物」爆炸，姐姐冲到我面前的时候，我…我还是忍不住会想起，失去家人的恐惧…\\n…抱歉，这些话我不知道能说给谁听，一直试图留在脑后…不过现在我感觉好多了。\\n既然忘不掉这份恐惧…那就试着记住它，然后…「超越」它吧。\", \"voicelineId\": 104031, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [15023], \"unlockText\": \"完成「花之归尘，羽之将坠」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"恰斯卡的爱好…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_pref_hobby\", \"description\": \"如果我喜欢的是「争斗」，就容易惹是生非；但如果我喜欢的是「调解争斗」，「争斗」就容易自己找上门…呵，玩笑而已。\", \"voicelineId\": 104032, \"voicelineType\": \"6001\"}, {\"title\": \"恰斯卡的烦恼…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_dialog_annoyed_01\", \"description\": \"深渊的力量——倒不是因为它现在会怎么影响到我，而是因为身边有许多人，会为了它过度地担心我。\", \"voicelineId\": 104033, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_pref_foodLike\", \"description\": \"小时候住在海边，最常吃的是生鱼；来「花羽会」后我最喜欢的是快火炙烤的肉排…人类跟绒翼龙的饮食区别很大，不过我不管在哪边都吃得很开心。\", \"voicelineId\": 104034, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_pref_foodDislike\", \"description\": \"酒精含量过高的食物吧。不是因为不喜欢酒，只是飞行前要严格控制饮酒量，偏偏有些食物看起来可口，气味也被香气掩盖，吃进嘴里才发现不妙。\", \"voicelineId\": 104035, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_spice_pref_01\", \"description\": \"要是能拿这道菜下酒，调停的成功率应该能上升个三成吧？哼，美食和美酒总是让人心情愉悦。\", \"voicelineId\": 104036, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_spice_normal_01\", \"description\": \"挺不错的，谢了。\", \"voicelineId\": 104037, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_spice_dislike_01\", \"description\": \"嗯…难道是做给绒翼龙吃的吗？…恐怕也不会合他们的胃口。\", \"voicelineId\": 104038, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_pref_birthday_01\", \"description\": \"来，这把枪里有六发子弹，其中有一发是特别的。找片空旷的地方试试枪吧，飞到天上去试的话效果更好。\\n哦？第一发就开出了特制的礼炮吗？你的运气还真不错…这是我亲手为你做的，为你的诞辰鸣炮敬礼！\\n嗯…你问剩下五发子弹是什么？当然也是礼炮啊，不过是刚刚那枚之前试做的，颜色不一样，算不上完美。来年我尽量六发都换上最好的。\", \"voicelineId\": 104039, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_starUp_01\", \"description\": \"哦？是新的子弹？\", \"voicelineId\": 104040, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_starUp_02\", \"description\": \"想要我为你调停什么？部族纷争？还是一场大战？\", \"voicelineId\": 104041, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_starUp_03\", \"description\": \"心与血都在渴望着「争斗」…但现在，已经能让这种渴望为我所用了。\", \"voicelineId\": 104042, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/Vo_chasca/vo_chasca_starUp_04\", \"description\": \"「有恩必报，有德必酬。」不管是在绒翼龙还是人类的世界，它都是不变不移的公理。从今往后，无论你想去往哪里，我的「羽翼」与「枪火」都随时为你待命。\", \"voicelineId\": 104043, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_battle_skill1_01\", \"description\": \"飞吧。\", \"voicelineId\": 104044, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_battle_skill1_02\", \"description\": \"喝！\", \"voicelineId\": 104045, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_battle_skill1_03\", \"description\": \"要起风了。\", \"voicelineId\": 104046, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_battle_skill3_01\", \"description\": \"全弹…发射！\", \"voicelineId\": 104047, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_chasca/vo_chasca_battle_skill3_02\", \"description\": \"风湮狙破！\", \"voicelineId\": 104048, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_battle_skill3_03\", \"description\": \"啸尘尽灭。\", \"voicelineId\": 104049, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_chest_open_01\", \"description\": \"分赃不均是起矛盾的大头。好在我用不上，你拿着就好。\", \"voicelineId\": 104050, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_chest_open_02\", \"description\": \"能用钱财调停的事都不算事——所以钱财多多益善，不是么？\", \"voicelineId\": 104051, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_chest_open_03\", \"description\": \"唔…亮晶晶的东西…真漂亮呢。\", \"voicelineId\": 104052, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_life_less30_01\", \"description\": \"值得一战…！\", \"voicelineId\": 104053, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_life_less30_02\", \"description\": \"该认真点了。\", \"voicelineId\": 104054, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_life_less30_03\", \"description\": \"要战…那就来战吧！\", \"voicelineId\": 104055, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_life_less30_teammate_01\", \"description\": \"…不许死！\", \"voicelineId\": 104056, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_life_less30_teammate_02\", \"description\": \"到我身后。\", \"voicelineId\": 104057, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_life_die_01\", \"description\": \"妈…妈…\", \"voicelineId\": 104058, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_life_die_02\", \"description\": \"无法…超越…\", \"voicelineId\": 104059, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_life_die_03\", \"description\": \"我也…坠落了吗…\", \"voicelineId\": 104060, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_battle_hit_H_01\", \"description\": \"这下麻烦了。\", \"voicelineId\": 104061, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/Vo_chasca/vo_chasca_battle_hit_H_02\", \"description\": \"…再来！\", \"voicelineId\": 104062, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_chasca_teamJoin_01\", \"description\": \"这次又是谁在闹事？\", \"voicelineId\": 104063, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_chasca_teamJoin_02\", \"description\": \"今天的风声，不太安静呢。\", \"voicelineId\": 104064, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_chasca_teamJoin_03\", \"description\": \"走吧，子弹已经上膛了。\", \"voicelineId\": 104065, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000105, 'Ororon', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_draw_appear_01\", \"description\": \"你好，我是来自「烟谜主」的欧洛伦。我不是卖菜的，但是可以送你一些。\\n别担心，没什么特别的原因，也没有想从你这里换取什么。我只是好奇每颗种子最终会长成什么样，所以越种越多。希望它们都能在中意它们的胃里安度晚年。\", \"voicelineId\": 105000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·怪人\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_character_idle_01\", \"description\": \"你听谁说的烟谜主里都是怪人？我以为只有我一个。还有谁啊？\", \"voicelineId\": 105001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·目标\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_character_idle_02\", \"description\": \"每个人都应该有一种自己最喜欢的动物，或者蔬菜，或者水果。这样才能知道自己想要成为什么样的人。\", \"voicelineId\": 105002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·迷烟\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_character_idle_03\", \"description\": \"不是所有的迷烟都能穿过。如果野心太大，就会被烟雾呛到。\", \"voicelineId\": 105003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_weather_heavyRain_01\", \"description\": \"跑起来泥水会溅到衣摆上，飞的话…浸水的披风又太沉了。还是找个地方蹲会儿吧。\", \"voicelineId\": 105004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_weather_thunder_01\", \"description\": \"闪电很像蛇。不知道有没有人利用它们的颜色和形状占卜…说实话，有点担心这些人的安全。\", \"voicelineId\": 105005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_weather_snowy_01\", \"description\": \"…雪下面葬着什么。轻一点，不要惊醒它们。\", \"voicelineId\": 105006, \"voicelineType\": \"1203\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_weather_sunny_01\", \"description\": \"太阳是永燃之火，纳塔人从不惧怕直视烈日。当然，实在受不了可以戴墨镜。\", \"voicelineId\": 105007, \"voicelineType\": \"1204\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_weather_desert_01\", \"description\": \"这地方…感觉很难种出东西来。要不还是走吧？\", \"voicelineId\": 105008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_greetingMorning\", \"description\": \"抱歉，虽然睁着眼睛，但我还没醒…正事可以晚点说吗？\", \"voicelineId\": 105009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_greetingNoon\", \"description\": \"胃说时间到了，应该去吃点东西。但我想不出要吃什么…也可能是脑子还没醒。\", \"voicelineId\": 105010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_greetingNight\", \"description\": \"突然想喝肉龙掌气泡咖啡，不加奶。你说太晚了？那…早上好。\", \"voicelineId\": 105011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_greetingNight2\", \"description\": \"一到这个时候大脑就会活跃起来。我很早就放弃强迫自己睡眠了，所以你先休息吧，我带上夜灯去看看地里的萝卜。\", \"voicelineId\": 105012, \"voicelineType\": \"1004\"}, {\"title\": \"关于欧洛伦自己·交流\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_idle\", \"description\": \"我知道自己说话有时很难懂。你如果有哪里没听明白，请直接提问，我不介意的。\", \"voicelineId\": 105013, \"voicelineType\": \"2001\"}, {\"title\": \"关于欧洛伦自己·未解之谜\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_idle2\", \"description\": \"我不知道自己是从哪来的，但似乎也并不好奇…比起这个，我更想知道自己该往何处去。\", \"voicelineId\": 105014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·道歉\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_close\", \"description\": \"抱歉…嗯…我是说，真的很抱歉。一上来就骗你，的确不是什么好的开局。原因已经都告诉你了，绝无虚言。如果你不想接受也没关系，那我会尽量不出现在你面前。\", \"voicelineId\": 105015, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·谢礼\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_close1\", \"description\": \"这是「凌晨四点」的肉龙掌，「比头大」的青蜜莓，「截至上周为止第一甜」的蜜…还有…哦，还有「咔库库免费问诊券」。\\n怎么露出疑惑的表情，这些是送给你的，请收下。你帮了我的忙，但看上去并不缺什么，我只好按照自己的喜好准备了礼物。\\n咔库库是谁？咔库库是龙。有机会介绍你们认识。\", \"voicelineId\": 105016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_pendant_01\", \"description\": \"听人说打雷有助于作物生长。我试了下在菜地中央驱动「神之眼」，很遗憾，卷心菜和番茄都不太开心，所以就没继续了。\", \"voicelineId\": 105017, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_share_01\", \"description\": \"一个小窍门：不要做第一个提出建议的人。就像先长出来的果实容易被盯上，第一个出头的人经常输得很惨。\", \"voicelineId\": 105018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_pref_gift_01\", \"description\": \"飞鼯其实并不总像它们在高空滑翔时那样目中无人。它们会突然飞过来，扒在你身上不走。这种时候很难不给它们点好处。从某种角度来看，算是一群狡猾的家伙。\", \"voicelineId\": 105019, \"voicelineType\": \"3003\"}, {\"title\": \"关于希诺宁…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_teammate_xilonen_01\", \"description\": \"她好像很喜欢待在高处，尤其是树上。我发现倒挂在树枝上会比躺在上面更解压，有机会可以和她交流下心得。欸，不好吗？大家总说要换个角度看世界，像希诺宁这样的发明家，应该很需要吧。\", \"voicelineId\": 105020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于基尼奇…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_teammate_kinich_01\", \"description\": \"那个阿乔很有意思。它年纪很大，却又年纪很小。基尼奇正好相反，他年纪很小，但年纪很大。你…你能明白我的意思对吧？\", \"voicelineId\": 105021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于恰斯卡…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_teammate_chasca_01\", \"description\": \"恰斯卡很厉害，也很出名。只要她一来，人们就都不吵架了，开始和和气气地握手。最讲理的家伙原来叫「武力威慑」，是个不错的名字。\", \"voicelineId\": 105022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊法…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_teammate_ifa_01\", \"description\": \"别看伊法经常教训病号，他和龙们的关系其实很好。闲下来他会在诊所门口弹吉他，让围上来的龙一个一个跟着唱。\\n但其实就是呜呜叫啦。我如果碰到了也会加入。我是说加入龙。\", \"voicelineId\": 105023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于茜特菈莉…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_teammate_citlali_01\", \"description\": \"奶奶其实是个很直白的人，高兴或者不高兴都会直接表现出来，也不太擅长掩饰自己的情感。你看上去像是她的同辈，或者…甚至比她更大？\\n抱歉，这样好像不太礼貌，我不多问了。但如果真是这样，就请你多和她聊聊天吧，奶奶大概受够了身边都是晚辈，见到你会很开心的。\", \"voicelineId\": 105024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊安珊…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_teammate_iansan_01\", \"description\": \"只能说，还好火神大人没有派她来抓我。她是远近闻名的运动教练，虽然我有身高优势，但很可能跑不过她。障眼法？用多了就不管用了啊。\", \"voicelineId\": 105025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于玛薇卡…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_teammate_mavuika_01\", \"description\": \"我之前并不认识火神大人。\\n我的意思是，我当然知道火神是谁，但并不像当面对过话的那种「认识」。在这之前，火神大人对我来说更像一种刻写着力量的图腾，一个象征着掌控全局的标志。这在我心中并不算切实的了解，所以我产生了疑问。\\n现在疑问消失了不少，我很开心，也有些心虚和羞愧…她似乎从不迷茫，知道火焰为何长燃，所以无论如何不能让其熄灭。我希望…希望自己能成为帮得上纳塔的人。\\n当然，关于她我还有一些思考…上次在宴会上见到她吃了很多很多绿叶蔬菜，我们还聊了这件事，她说她很喜欢营养均衡的感觉。总觉得，是比想象中更细致的人。\", \"voicelineId\": 105026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「队长」…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_teammate_capitano_01\", \"description\": \"真是一段奇异又仓促的缘分。\\n都说烟谜主的人擅长预知未来，但我在路边遇到「队长」时，从没想过事情会变得这样复杂。在你看来，人情是可以简单两清的吗？如果是，我心中为何仍保留感激与亏欠？\\n…又或许是我考虑得太多了。无论之前发生了什么，他帮助拯救了纳塔岌岌可危的地脉，是一位值得尊敬的英雄。我会一直记得他的。\", \"voicelineId\": 105027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解欧洛伦·其一\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_friendship_01\", \"description\": \"你好。要握手吗？纳塔人打招呼一般不会这样正式，但你想要也可以。其实在远处喊一声就够了，我听力很好，会察觉到的。\", \"voicelineId\": 105028, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解欧洛伦·其二\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_friendship_02\", \"description\": \"你似乎总是很忙，我也希望像你一样，一直有事可做。但有时，我又很喜欢清闲度日。人的心情真多变啊，我自己也控制不了，真为难。\", \"voicelineId\": 105029, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解欧洛伦·其三\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_friendship_03\", \"description\": \"纳塔的白天很热，所以除非必要，我更喜欢晚上出门。你见过夜晚的水面吗？月光让水波闪着光，看起来十分清亮。但只有在阳光下你才能看清它是不是真的干净，所以，尽量不要触碰夜晚漆黑的水。\", \"voicelineId\": 105030, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解欧洛伦·其四\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_friendship_04\", \"description\": \"我对灵魂的感知天生比其他人强一些。怎么描述呢…人的灵魂有些像一团团莫测的能量，如果世界上有形态各异的小龙棉花糖，那大概就是灵魂的样子吧。你的灵魂很温暖，是烤过的那种。\", \"voicelineId\": 105031, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解欧洛伦·其五\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_friendship_05\", \"description\": \"老实说，我自己对自己也不甚了解。我总是有很多疑问；已有的问题还没得到解决，马上又会有新的加入进来。\\n好像没有什么特别好的解决办法…只能尽量往前走，对吧？\", \"voicelineId\": 105032, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"欧洛伦的爱好…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_pref_hobby\", \"description\": \"除了种菜和观察蜜虫以外的爱好？有的。…当然有，给我点时间，会想出来的。\", \"voicelineId\": 105033, \"voicelineType\": \"6001\"}, {\"title\": \"欧洛伦的烦恼…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_dialog_annoyed_01\", \"description\": \"有时，想要和做到之间的距离真的很难跨越。\", \"voicelineId\": 105034, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_pref_foodLike\", \"description\": \"吃塔塔可时，在下面放一张空饼皮。只要吃得足够多，掉下来的食材就能变成一个新的塔塔可了。\", \"voicelineId\": 105035, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_pref_foodDislike\", \"description\": \"军用食品…尤其是压缩饼干。它们就像「队长」的灵魂一样沉重…品质很好，只是太硬了。\", \"voicelineId\": 105036, \"voicelineType\": \"6004\", \"unlockConditions\": [{\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_spice_pref_01\", \"description\": \"厉害，比我自己做的好吃。\", \"voicelineId\": 105037, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_spice_normal_01\", \"description\": \"不多不少，正正好的味道。\", \"voicelineId\": 105038, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_spice_dislike_01\", \"description\": \"我不太明白…这是什么艺术？\", \"voicelineId\": 105039, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_pref_birthday_01\", \"description\": \"在纳塔，有种说法是，一个人的出生日期决定了他的命运。如果他的生日和某位大英雄是同一天，那他就会得到这位英雄的庇佑，拥有和他一样的品质。\\n我想，和你共享生日的人一定很幸运。生日快乐。\", \"voicelineId\": 105040, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_starUp_01\", \"description\": \"你刚刚拿给我的是什么？能再让我看一下吗？\", \"voicelineId\": 105041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_starUp_02b\", \"description\": \"我是不是应该叫你声老师？谢谢你，{M#爷爷},{F#奶奶}老师，我学到很多。\", \"voicelineId\": 105042, \"voicelineType\": \"8002\", \"voicefile_male\": \"VO_friendship/VO_olorun/vo_olorun_starUp_02a\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true, \"hasGenderedVoicefile\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_starUp_03\", \"description\": \"身体很轻，看来可以一下子去到更高的地方了。但要控制好力道，因为磕到头会很疼。\", \"voicelineId\": 105043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_olorun/vo_olorun_starUp_04\", \"description\": \"我还没能力窥探死亡的界限，但你的帮助似乎将死亡推得更远了一些。放心，我不会因此就去随心所欲做坏事的，我保证。\", \"voicelineId\": 105044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_battle_skill1_01\", \"description\": \"别跑太远。\", \"voicelineId\": 105045, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_battle_skill1_02\", \"description\": \"再见咯。\", \"voicelineId\": 105046, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_battle_skill1_03\", \"description\": \"放生！\", \"voicelineId\": 105047, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_battle_skill3_01\", \"description\": \"去吧，你自由了。\", \"voicelineId\": 105048, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_battle_skill3_02\", \"description\": \"来，跟大家问好。\", \"voicelineId\": 105049, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_battle_skill3_03\", \"description\": \"帮我四处看看。\", \"voicelineId\": 105050, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_chest_open_01\", \"description\": \"你对宝箱的热情正在威胁它们的生存环境。\", \"voicelineId\": 105051, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_chest_open_02\", \"description\": \"敲上去的声音很清脆，应该是颗不错的果实。\", \"voicelineId\": 105052, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_chest_open_03\", \"description\": \"小心哦，有些龙喜欢躲在箱子里。可能是内向吧。\", \"voicelineId\": 105053, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_life_less30_01\", \"description\": \"跑不动了…\", \"voicelineId\": 105054, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_life_less30_02\", \"description\": \"警惕…！\", \"voicelineId\": 105055, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_life_less30_03\", \"description\": \"坏兆头。\", \"voicelineId\": 105056, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_life_less30_teammate_01\", \"description\": \"要带你去看医生吗？\", \"voicelineId\": 105057, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_life_less30_teammate_02\", \"description\": \"我先补上。\", \"voicelineId\": 105058, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_life_die_01\", \"description\": \"先走一步…\", \"voicelineId\": 105059, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_life_die_02\", \"description\": \"看不清了…\", \"voicelineId\": 105060, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_life_die_03\", \"description\": \"听见了…不该存在的声音…\", \"voicelineId\": 105061, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_battle_hit_H_01\", \"description\": \"呃，跑慢了…\", \"voicelineId\": 105062, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_olorun/vo_olorun_battle_hit_H_02\", \"description\": \"这不对吧？\", \"voicelineId\": 105063, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_olorun_teamJoin_01\", \"description\": \"要我加入吗？\", \"voicelineId\": 105064, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_olorun_teamJoin_02\", \"description\": \"去哪？\", \"voicelineId\": 105065, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_olorun_teamJoin_03\", \"description\": \"能不能先说，是好事还是坏事？\", \"voicelineId\": 105066, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000106, 'Mavuika', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_draw_appear_01\", \"description\": \"追寻火焰在时间长河中的足迹，我们将至黑之地以血泪铸成家园，而今，长路向前延续，旅途正待新篇。现任火神玛薇卡，助你的视野中再无漆黑。\", \"voicelineId\": 106000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·冒险\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_character_idle_01\", \"description\": \"探索与挑战…嗯，冒险家的生活很合我的胃口。\", \"voicelineId\": 106001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·体验\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_character_idle_02\", \"description\": \"神明总是在天上待着，不常来地上走走可不行。\", \"voicelineId\": 106002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·循光\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_character_idle_03\", \"description\": \"许多昆虫有循光而行的本能，人类也是如此，只是我们称那道光为「希望」。\", \"voicelineId\": 106003, \"voicelineType\": \"1103\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_weather_snowy_01\", \"description\": \"嗯——好凉快啊，纳塔可没有这样的好地方。\", \"voicelineId\": 106004, \"voicelineType\": \"1201\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_weather_sunny_01\", \"description\": \"天气真好，很适合户外观光。走，上车，跟我去跑两圈？\", \"voicelineId\": 106005, \"voicelineType\": \"1202\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_weather_afterRain_01\", \"description\": \"湿漉漉的很不舒服吧？正好休息片刻，我用火帮你烘干一下。\", \"voicelineId\": 106006, \"voicelineType\": \"1203\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_weather_desert_01\", \"description\": \"沙子是火焰与文明的天敌，唯有断壁残垣还在讲述着过往。\", \"voicelineId\": 106007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_greetingMorning\", \"description\": \"醒过来的时候，我会把一天的计划在脑中快速过一次，然后…就会失望地发现，我必须起床了。\", \"voicelineId\": 106008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_greetingNoon\", \"description\": \"吃过午饭了吗？「沃陆之邦」送来了新鲜的水果，我感觉是很棒的餐后甜点，尝尝看吧。\", \"voicelineId\": 106009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_greetingNight\", \"description\": \"「回声之子」道路整修的方案及预算，嗯…哦，晚上好，已经这个时间了啊。\", \"voicelineId\": 106010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_greetingNight2\", \"description\": \"晚安，我还要再忙一些事，就当是休息了。啊，我的意思是，「忙碌」对我而言是一种享受。\", \"voicelineId\": 106011, \"voicelineType\": \"1004\"}, {\"title\": \"关于玛薇卡自己·头发\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_idle\", \"description\": \"好奇我的头发？放心吧，这是种非常友善的火，一点都不烫，也不会引燃任何物品，它只会在敌人的身上展现出全部的威力——你明白我的意思吧？\", \"voicelineId\": 106012, \"voicelineType\": \"2001\"}, {\"title\": \"关于玛薇卡自己·留言\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_idle2\", \"description\": \"纳塔历史上存在很多火神，他们都会选出最关键的知识与记忆放入圣火，提供给继位者学习。由于信息量很大，有时候甚至会影响到学习者的神智，所以我在火中留下了一句话——「成为火之前，请先为自我的存在而骄傲。」\", \"voicelineId\": 106013, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·执剑\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_close\", \"description\": \"计划是最可靠的指引，但也绝非不可改动的神圣律令，我在五百年前无法预知你的到来，但当我见到并了解你之后，我就知道计划值得因你而变动。从结果上看，与你一同执剑，是无比正确的决断。\", \"voicelineId\": 106014, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·古名\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_close1\", \"description\": \"你可能还没有意识到「杜麦尼」这个全新的古名会在未来的纳塔留下多么重要的影响：之后的每一代人讲起「杜麦尼」的故事，就会提到这场战斗，提及每一位英雄，而「杜麦尼」会和「基扬戈兹」紧密相连，我们将会和纳塔一同存续到永远。\", \"voicelineId\": 106015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_pendant_01\", \"description\": \"对人类来说，「神之眼」和「古名」都是来自神明的馈赠，区别在于前者赐予了元素力，而后者提供的则是精神上的支持。但我始终认为，有无身外之物的加持都不妨碍一个人变得伟大，成为英雄，因为更重要的东西，是炽热的「心」。\", \"voicelineId\": 106016, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_share_01\", \"description\": \"小时候我父亲告诉我，一个木桶能装多少水，取决于最短的那块木板，但如果想要不断进步，就要甘愿成为那块最短的木板——承认自我的不足，向优秀者请教，这样的人并不是失败者，而是进取者。\", \"voicelineId\": 106017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_pref_gift_01\", \"description\": \"幼年的匿叶龙特别可爱，我的龙伙伴希塔塔特别特别黏人，只要看见我，不管离我多远，都会开心地冲进我怀里来。这让我妹妹伊妮有点嫉妒，所以她看到希塔塔跑过来的时候，她也会跑过来，我得同时接住他们两个，哈哈哈。\", \"voicelineId\": 106018, \"voicelineType\": \"3003\"}, {\"title\": \"关于希诺宁…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_xilonen_01\", \"description\": \"希诺宁是纳塔最优秀的工匠之一，不仅掌握古名的打造方法，还对秘源技术颇有研究，就算是需要创造前所未有的东西，她也勇于挑战，总能拿出好的结果，虽然过程通常会有点波折…嗯，比如改设计之类的。\", \"voicelineId\": 106019, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于茜特菈莉…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_citlali_01\", \"description\": \"很多人觉得她脾气古怪，难以相处，我认为只是普通的琐事不配让她放在心上。当真正需要她担心的事出现，她会有多认真，你们应该已经见识过了…有时候我觉得像她这样的性格很容易被卷入险境，所以我会向她隐瞒一些东西，可是…想要不被她洞察到也很难，她太敏锐了。\", \"voicelineId\": 106020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于恰斯卡…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_chasca_01\", \"description\": \"能在深渊的影响下存活，本就是种奇迹，更令人感动的是，她在纳塔邂逅的人与龙，共同帮助她找到了活下去的「理由」。现在我已无须担心她的坚韧，但我还是想要尽我所能，为她留出一个更加温柔的「居所」——再坚强的人，也需要休息。\", \"voicelineId\": 106021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于欧洛伦…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_olorun_01\", \"description\": \"在我看来，他的真实性格和外在表现出的东西相去甚远，他就像是一块被冰块包裹的熔岩，让他冷静下来的东西是族人与朋友，让他躁动不安的则是守护他们的冲动，与成为英雄的使命感…这种情绪并不理智，但又难能可贵。\", \"voicelineId\": 106022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊安珊·纠缠\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_iansan_01\", \"description\": \"伊安珊刚刚获得古名参加归火圣夜巡礼的时候，总是被人当成软柿子，所以在团体赛的时候找她战斗的人非常多，虽然她每次都能赢，但也会消耗大量的体能，这也让她起初的成绩并不好。而越是这样，她就越容易被人缠上…\", \"voicelineId\": 106023, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊安珊·证明\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_iansan_02\", \"description\": \"我给了她建议，只要大家都知道她是个强者，就不会有那么多人找麻烦了。但我没想到的是，伊安珊沉思片刻，想到的方法竟然是在归火圣夜巡礼的时候和我打一场。哈哈哈，她的实力远超我的预料，这一场也很有效果，再也不会有人瞧不起她了。\", \"voicelineId\": 106024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于玛拉妮…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_mualani_01\", \"description\": \"她和图帕克的性格完全不同，却都继承了「沃摩延」之名。「团结」重要的并不是方式，而是内心中珍视友人与家园，愿意为此献出全力的精神…虽然我这么说，但当时的玛拉妮一定没想这么多，她只是很清楚，卡齐娜与她自己的生命同等重要。\", \"voicelineId\": 106025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于基尼奇…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_kinich_01\", \"description\": \"「马力卜」除了回火还有一个含义是「代价」，你们可能会疑问，相较于其他古名，这并非是一个表达积极含义的词语。但其实「代价」象征着时刻保持清醒，敢于分析现状，提出问题，哪怕是泼冷水和说丧气话，如果没有这样的人在，众人很容易因情绪而陷入死局，因小失大。\", \"voicelineId\": 106026, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于卡齐娜…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_kachina_01\", \"description\": \"在你们帮助卡齐娜从夜神之国平安归来之后，我去了她家，和首领一起再次表达了歉意，还送去了一些慰问品。迷失在夜神之国的这段经历会在卡齐娜的成长中残留很多影响，而这些影响本不应该发生…我对此负有责任。\", \"voicelineId\": 106027, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于瓦雷莎…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_varesa_01\", \"description\": \"归火圣夜巡礼举办期间，「倦意之屋」的消费都由我个人承担，但每次去结账的时候，都会发现有个客人点了八十人份的套餐。起初我还以为是大型的亲朋好友观光团，结果没想到…居然就是她一个人。\", \"voicelineId\": 106028, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊法…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_ifa_01\", \"description\": \"除了精湛的医术外，一个好医生往往拥有很强的沟通能力。而当与医患语言不通时，就需要更敏锐的观察力和同理心。这就是为什么伊法总是能和不同性格的人交上朋友吧。\\n所以说，如有人或者龙和伊法关系不好…哈哈，我想应该不是伊法的问题。\", \"voicelineId\": 106029, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「队长」…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_capitano_01\", \"description\": \"同样是五百年的时间，我想对他而言会更加漫长，当死亡的权利被剥夺，人生就成为了没有终点的旅途，人类的精神很容易就在这种虚无中耗竭。可是他依然抓住了唯一的胜利机会，获得了他所追求的圆满。我对像他这般的战士充满敬意。\", \"voicelineId\": 106030, \"voicelineType\": \"4012\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于尘世七执政…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_theSeven_01\", \"description\": \"很遗憾，我对他们的了解甚至还不如你多，但我相信只有最优秀的领导者，才能让国度存续至今并且向前发展。在纳塔抗击深渊的历史告一段落之后，我也打算和其他国家建立更多联系，并为纳塔接下来的发展做好准备。\", \"voicelineId\": 106031, \"voicelineType\": \"4013\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于梦见月瑞希…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_teammate_mizuki_01\", \"description\": \"我对这位稻妻客人印象不错。听说她初来纳塔的时候，对「流泉之众」那边的温泉颇为上心，还四处打听和温泉有关的技艺。但她的钻研不为谋利，而是旨在改善人们的精神状态。如此纯粹的目的，理应获得我们的敬重与帮助。\\n说起来…稻妻的现任执政也喜欢泡温泉吗？要是此事属实，我似乎知道该如何和她拉近关系了。\", \"voicelineId\": 106073, \"voicelineType\": \"4014\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解玛薇卡·其一\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_friendship_01\", \"description\": \"哦？没问题，我还挺喜欢讲故事的，只不过就这么讲未免单调了点，我们先去来上两杯吧。\", \"voicelineId\": 106032, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解玛薇卡·其二\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_friendship_02\", \"description\": \"驰轮车的操控并不复杂，只要稍加练习就能驾驭，不过如果想要高速行驶，还需要加装许多安全配件。什么？你说我现在已经骑得很快了？用希诺宁的原话来解释——「你身强体壮，用不着这个。」\", \"voicelineId\": 106033, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解玛薇卡·其三\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_friendship_03\", \"description\": \"我的遗憾当然也有很多。因为使命在身，我无法为任何人驻足停留，我所积累的知识和力量能最有效率地解决问题，但很多时候人们需要的只是「陪伴」…在这方面，我让很多人失望过。优柔寡断只会带来更深重的痛苦，我唯一能做的就是克制。\", \"voicelineId\": 106034, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5007], \"unlockText\": \"完成「黑石湮落白石下」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解玛薇卡·其四\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_friendship_04\", \"description\": \"解放神座之力升上高空之后，我的灵魂也和地脉紧紧相连，我能感受到战士的热血，普通人的坚强，以及受害者的伤痛…亲历这些情绪，已经是第二次了，所幸有你和英雄们的帮助，这次的结局完全不同，这也证明了我们的坚持是有价值的。\", \"voicelineId\": 106035, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5014], \"unlockText\": \"完成「命定将焚的虹光」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解玛薇卡·其五\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_friendship_05\", \"description\": \"我作为火神最重要的职责已经告一段落，原本在这崭新的纳塔里并没有我的位置，我在几百年前就接受了这一切，而现在这种状态，反而让我有点手足无措…不过在你的身上，我已经看到了我应该前往的方向——去探寻，去学习，去拯救。\", \"voicelineId\": 106036, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"玛薇卡的爱好…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_pref_hobby\", \"description\": \"变强。比如完成艰难的挑战，解开复杂的谜题，战胜强大的敌人…比起重复相同的事，成就感才是我的快乐源泉。\", \"voicelineId\": 106037, \"voicelineType\": \"6001\"}, {\"title\": \"玛薇卡的烦恼…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_dialog_annoyed_01\", \"description\": \"「『恐龙与遗迹侦探』由于人气不佳，决定不再制作拓展内容和解密合集…」这可是我最喜欢的桌面谜题，不能因为它的题目太难，规则难以理解，就认为它做得不好吧。唉，不过既然是销量原因也没办法，写一封匿名信鼓励作者吧，希望以后还能玩到他的新作。\", \"voicelineId\": 106038, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_pref_foodLike\", \"description\": \"哪怕是最简单的家常菜，每家人做出来的味道也不一样，有时候差别还很大。我在圣火竞技场吃过好几种炖肉，每种都很好吃，做法都有独到之处，但轮到我自己做的时候，我还是会选择我家的味道。\", \"voicelineId\": 106039, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_pref_foodDislike\", \"description\": \"我没有不喜欢的食材，但我比较反感形式大于内容的食物，比如要花三个小时才能走完全程的「正餐」…虽然能感受到厨师的创意与巧思，但我还是愿意将时间投入到更有效率的事情上。\", \"voicelineId\": 106040, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_spice_pref_01\", \"description\": \"谢谢你，相当合我的口味，你有菜谱吗？我也想学学看。\", \"voicelineId\": 106041, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_spice_normal_01\", \"description\": \"我大体满意，不过还能想到几个改进点。\", \"voicelineId\": 106042, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_spice_dislike_01\", \"description\": \"没想到吃起来还不坏，我能够接受。\", \"voicelineId\": 106043, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_pref_birthday_01\", \"description\": \"从今天开始，你可以把每个值得纪念的成就都写在纸上，保存到下一次生日的时候再拿出来，这样你就会拥有一份来自自己的生日礼物。希望这些记录，能够让你时刻记住，你有多么了不起，生日快乐。\", \"voicelineId\": 106044, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_starUp_01\", \"description\": \"舒展筋骨的感觉，我喜欢。\", \"voicelineId\": 106045, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_starUp_02\", \"description\": \"力量越来越强，不过我的实力还远不止此。\", \"voicelineId\": 106046, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_starUp_03\", \"description\": \"火焰愈发澄澈，我的灵魂与肉体也愈发契合，这等力量，才是践行「领袖」职责的保证。\", \"voicelineId\": 106047, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_mavuika/vo_mavuika_starUp_04\", \"description\": \"自从与你相遇，我的力量再次获得了质的飞跃。我们各自拥有不同的使命，是责任感与正义感将我们相连。对于你所提供的帮助，我感激不尽。\", \"voicelineId\": 106048, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_battle_skill1_01\", \"description\": \"点燃吧。\", \"voicelineId\": 106049, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_battle_skill1_02\", \"description\": \"焚灭不净！\", \"voicelineId\": 106050, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_battle_skill1_03\", \"description\": \"烈日随我。\", \"voicelineId\": 106051, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_battle_skill1_04\", \"description\": \"要加速了。\", \"voicelineId\": 106052, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_battle_skill1_05\", \"description\": \"动力全开！\", \"voicelineId\": 106053, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_battle_skill1_06\", \"description\": \"谁要阻拦？\", \"voicelineId\": 106054, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_battle_skill3_01\", \"description\": \"恭听太阳的轰鸣！\", \"voicelineId\": 106055, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_battle_skill3_02\", \"description\": \"无赦天火！\", \"voicelineId\": 106056, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_battle_skill3_03\", \"description\": \"埋葬于赤焰之下！\", \"voicelineId\": 106057, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_chest_open_01\", \"description\": \"冒险的嘉奖，很有纪念意义。\", \"voicelineId\": 106058, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_chest_open_02\", \"description\": \"多了一份能加入收藏的东西。\", \"voicelineId\": 106059, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_chest_open_03\", \"description\": \"还不错，我很喜欢。\", \"voicelineId\": 106060, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_life_less30_01\", \"description\": \"不能再失误了。\", \"voicelineId\": 106061, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_life_less30_02\", \"description\": \"需要调整。\", \"voicelineId\": 106062, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_life_less30_03\", \"description\": \"也该认真起来了。\", \"voicelineId\": 106063, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_life_less30_teammate_01\", \"description\": \"战斗的事交给我。\", \"voicelineId\": 106064, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_life_less30_teammate_02\", \"description\": \"不要勉强自己。\", \"voicelineId\": 106065, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_life_die_01\", \"description\": \"火，不会熄灭…\", \"voicelineId\": 106066, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_life_die_02\", \"description\": \"传承，终结了吗？\", \"voicelineId\": 106067, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_life_die_03\", \"description\": \"命运，如此？\", \"voicelineId\": 106068, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_mavuika/vo_mavuika_battle_hit_H_01\", \"description\": \"不错啊。\", \"voicelineId\": 106069, \"voicelineType\": \"910001\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_mavuika_teamJoin_01\", \"description\": \"火神玛薇卡，参战。\", \"voicelineId\": 106070, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_mavuika_teamJoin_02\", \"description\": \"当然没问题。\", \"voicelineId\": 106071, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_mavuika_teamJoin_03\", \"description\": \"我随时准备就绪。\", \"voicelineId\": 106072, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000107, 'Citlali', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_draw_appear_01\", \"description\": \"「烟谜主」的茜特菈莉，已经透过迷烟看到了未来的道路。诸恶曜必不会伤害你，诸吉星必环绕你。你会拥有强大的「盟友」。请让我也同行。——呃，见到认真的我很奇怪吗？不要用这种眼神看着我啦！\", \"voicelineId\": 107000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·小说\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_character_idle_01\", \"description\": \"基、基本上八重堂出版过的小说我都看过。也、也不奇怪吧！\", \"voicelineId\": 107001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·喝酒\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_character_idle_02\", \"description\": \"岁月献给小酒杯，借钱九出十三归。\", \"voicelineId\": 107002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·出神\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_character_idle_03\", \"description\": \"「出神仪式」对旁人来说还是挺不稳定的，就不要太好奇了吧。\", \"voicelineId\": 107003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_weather_heavyRain_01\", \"description\": \"在家里看小说的好日子。\", \"voicelineId\": 107004, \"voicelineType\": \"1201\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_weather_afterRain_01\", \"description\": \"今晚应该能看到星星了。\", \"voicelineId\": 107005, \"voicelineType\": \"1202\"}, {\"title\": \"下雪的时候…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_weather_snowy_01\", \"description\": \"呜啊，从来没有见过！\", \"voicelineId\": 107006, \"voicelineType\": \"1203\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_weather_desert_01\", \"description\": \"呸——啊，我不是在随地吐痰，我怎么可能那么没有素质？是嘴里进飞沙了！你相信我！\", \"voicelineId\": 107007, \"voicelineType\": \"1204\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_greetingMorning\", \"description\": \"啊——早上好啊。上次这么早起床都是出师以前了。独当一面之后，我都是睡到自然醒。说吧，什么事？\", \"voicelineId\": 107008, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_greetingNoon\", \"description\": \"中午好啊。其实我还是很节制的，起床到中午的时间内是不会喝酒的…至于熬夜主持仪式结果彻夜不眠直到第二天天亮就是另一码事了…\", \"voicelineId\": 107009, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_greetingNight\", \"description\": \"晚上好啊。纳塔有些荒野晚上会有很大幅度的降温，别凉着了。燃素活跃的地方倒是白天晚上都一样。你没问？没问也听着！\", \"voicelineId\": 107010, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_greetingNight2\", \"description\": \"晚安。今晚恶曜不显，地灵微眠，迷烟浅睡。是个好夜晚。我的枕头怎么掉地上了…\", \"voicelineId\": 107011, \"voicelineType\": \"1004\"}, {\"title\": \"关于茜特菈莉自己·蜃楼战记\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_idle\", \"description\": \"哦，你感兴趣啊。《蜃楼战记》是稻妻八重堂中岛纯先生所著的幻想小说，算是八重堂活化石级别的老系列了。故事发生在名叫「苇之原」的幻想岛国。大部分章节的主角都是东渡而来的猫头道士「东之山君」，其真身正是超古代诸侯东王公。小说的篇幅很长很长，中间换过三次作者，最终还是没有揭开「方壶」的真相…\", \"voicelineId\": 107012, \"voicelineType\": \"2001\"}, {\"title\": \"关于茜特菈莉自己·终结\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_idle2\", \"description\": \"纵使「还魂诗」可以唤回血气之身，但星曜、太阳尚有终结，何况生命。你问死亡是什么样的？那就像是在永恒的午后，你骑着龙驰骋在大平原上，天际线那边有一张看不清的脸。无论你速度多快，它都在天边不动。突然某一刻它动了起来，以恐怖的速度和你迎面撞上。你来不及躲避，当看清那张脸时，一切都结束了。\", \"voicelineId\": 107013, \"voicelineType\": \"2005\"}, {\"title\": \"关于我们·帮助\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_close\", \"description\": \"欸，除了辈分虚高，我也不知道我在纳塔能帮你什么。你的「盟友」强大，前途光明。在这方面我已经没什么能为你做的了，更何况像我这种年纪的奶奶，一般不都该在家里找把椅子躺着了吗？除非你真的要我帮忙用辈分去压人…你不会真的需要这种吧…\", \"voicelineId\": 107014, \"voicelineType\": \"2003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [15029], \"unlockText\": \"完成「流淌着色彩的回忆」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·局促\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_close1\", \"description\": \"我、我对你的态度和对其他人一样啊。没、没什么差别吧。呼…好吧，村里人对我的误会已经传了几代人，我早就放弃努力了。但是你不一样，你面前的我才是真正的我。对外无所顾忌、大大咧咧的模样，都是我努力装出来去迎合外界忌惮的…在你面前的局促才是真的我。我就是一个谨小慎微的人啊。我从来都不骗你，但是这个真心话我只说一次。\", \"voicelineId\": 107015, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [15029], \"unlockText\": \"完成「流淌着色彩的回忆」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_pendant_01\", \"description\": \"获得神之眼就是获得了另一种强大的「盟友」。不过当我们说某人「盟友」强大的时候，本质上还是在说其人本身超凡。毕竟「盟友」只是协助你的力量，只有你自己拥有无坚不摧的意志，才能把力量发挥出来。\", \"voicelineId\": 107016, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_share_01\", \"description\": \"稻妻的小说连载运到纳塔会晚两周，而合订本要整整晚一年。不知道背后有什么深意。这时间差的两周内，各种稀奇古怪的内部消息、先行透露满天飞，不知道多少是造谣、多少是自己编的。\", \"voicelineId\": 107017, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_pref_gift_01\", \"description\": \"传说纳塔曾有一种特殊的仙人掌，被我老师的老师称呼为「梅斯卡利脱」。据说食用它能让凡目也看到另一重世界。我也就说说，现在不知道「梅斯卡利脱」灭绝没有。你遇到了可千万别吃。\", \"voicelineId\": 107018, \"voicelineType\": \"3003\"}, {\"title\": \"关于欧洛伦…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_teammate_olorun_01\", \"description\": \"哼哼。\", \"voicelineId\": 107019, \"voicelineType\": \"4001\"}, {\"title\": \"关于玛拉妮…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_teammate_mualani_01\", \"description\": \"玛拉妮和我之间有笔算不清楚的账。她应该付我的报酬、弄坏我家门的赔偿、实付报酬、蹭我零食、给我带的小吃…总之算不清了。如果她不介意的话，我倒是想就此两清。正应该睡觉的周末上午十一点…啊，没什么！总之，突然被她咚咚咚锤门，太可怕了。\", \"voicelineId\": 107020, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于希诺宁…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_teammate_xilonen_01\", \"description\": \"像她这样既不在乎关于我的奇怪谣言，又不会过分热情的人相处起来最轻松不过了。啊，不是——在你面前我也很轻松。我拘谨的本性都不自觉流露了！\", \"voicelineId\": 107021, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于玛薇卡…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_teammate_mavuika_01\", \"description\": \"玛薇卡这家伙…咳咳，不好意思，火神大人她前些日子突然过来找我说了一大堆话。后来我半夜吃宵夜时才明白她过来炫耀了什么。有一句异邦的古话，想想还挺适合她的。「圣者谦卑，只有谈到自己责任时，会骄傲地加一句『我说句大话…』」。\", \"voicelineId\": 107022, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"对神里绫华…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_teammate_ayaka_01\", \"description\": \"…哈，小妹，你转过来给我看看。嘶，这是《奥西兹小姐事件簿》啊，嗨，我还以为是《赫尔洛克》系列的女二号呢。枫丹的衣服在我看来都一样。行了，你继续吧，我没事了。\", \"voicelineId\": 107023, \"voicelineType\": \"4005\"}, {\"title\": \"关于基尼奇…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_teammate_kinich_01\", \"description\": \"他身边的那个小东西有点烦人。他是你朋友吗？那我想想还有什么别的印象…他本人还是挺可靠的。嗯。\", \"voicelineId\": 107024, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于伊安珊…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_teammate_iansan_01\", \"description\": \"好像对她没什么更深了解。不过根据八重堂小说的套路来看，这人能力这么强，个子这么小，是不是遇到紧急情况会有一个两米三的百分之二百出力模式啊？\", \"voicelineId\": 107025, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解茜特菈莉·其一\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_friendship_01\", \"description\": \"啊？你怎么突然过来和我说这个？是听到了关于我的传闻？唉，对对，我就是萨满里的老妖怪，想信就信吧。我已经放弃解释了。\", \"voicelineId\": 107026, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解茜特菈莉·其二\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_friendship_02\", \"description\": \"你还是想听我解释吗？唉。「烟谜主」有一个秘而不宣的传统：为了敦促后辈进步，老师会故意算计徒弟，让他们和师叔们结下梁子。为了不挨长辈的揍，后辈就必须拼命努力反超长辈。如今「烟谜主」大半都是我朋友的谱系。他们所有人都喜欢找我来当这个坏人巫婆。怎么办呢？我根本没想为难后生，可这么多年没有一个人能赢过我！唉！于是关于我多恐怖、脾气多差的谣言就根深蒂固了。\", \"voicelineId\": 107027, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解茜特菈莉·其三\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_friendship_03\", \"description\": \"没错。我在人前的状态是装出来的，这才是我本来的性格。这也很好理解吧，所有人都期待着你说话带着口音和过时表达的时候，你说出了优雅、字正腔圆的标准口音，对面也会愣住的。你说的没错，这就是一种不自知的愚蠢。但是这种愚蠢很难从习性上摒弃，你看，我一开始还以为你也和其他人一样呢，嘿嘿。\", \"voicelineId\": 107028, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解茜特菈莉·其四\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_friendship_04\", \"description\": \"你想知道「烟谜主」的后辈是怎么被他们师父算计，和我结下梁子的吗？最传统的做法就是师父骗徒弟自己被骗了，要去骗子家门口涂鸦。一般徒弟听了就会义愤填膺，捋起袖子就涂。真的很过分欸，对吧？不过最近大家都知道我家在哪里了，所以这招不怎么能见到了。\", \"voicelineId\": 107029, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解茜特菈莉·其五\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_friendship_05\", \"description\": \"这些龙遗迹研究协会送回来的酒瓶…啊，这，这是，对，是欧洛伦他喝完了随地乱扔的，和我没关系。对吧，欧洛伦，快出来认错！我酒量还不错，不会轻易喝醉的，就算醉了也不会乱扔垃圾。何况协会说是野外找到的在野外也没有给别人添麻烦而且这也不是我丢的…啊，解释不清楚了！请你相信我！\", \"voicelineId\": 107030, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [15029], \"unlockText\": \"完成「流淌着色彩的回忆」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"茜特菈莉的爱好…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_pref_hobby\", \"description\": \"我的生命太过无意义，只剩下喝酒的迷醉、看小说的妄想和睡觉的昏沉了。\", \"voicelineId\": 107031, \"voicelineType\": \"6001\"}, {\"title\": \"茜特菈莉的烦恼…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_dialog_annoyed_01\", \"description\": \"这你还看不出来吗？看起来什么都不在乎只是我的保护色，其实我什么都很在乎。\", \"voicelineId\": 107032, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_pref_foodLike\", \"description\": \"我喜欢五成熟的肉，比较接近祭祀品本来的味道。然后就是吃起来简单，可以一只手拿着另一只手翻小说的东西。再然后就是，你推荐的我都喜欢！\", \"voicelineId\": 107033, \"voicelineType\": \"6003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_pref_foodDislike\", \"description\": \"就是…稍微有些不理解酸味的食物。饿了就吃东西，困了就睡觉，渴了就喝水。既然需要酸味开胃，那不就是不饿不需要吃东西吗？\", \"voicelineId\": 107034, \"voicelineType\": \"6004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_spice_pref_01\", \"description\": \"呜啊，太好吃了。「烟谜主」附近的吃食我都尝过了，全都没你做的好吃。真的真的。\", \"voicelineId\": 107035, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_spice_normal_01\", \"description\": \"平常吃这种东西不多…不不不，不是说不好吃的意思！就是…现在感觉吃出来了另一番风味。是夸奖，真的是夸奖！\", \"voicelineId\": 107036, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_spice_dislike_01\", \"description\": \"怎、怎么会不好吃呢。啊哈哈哈…\", \"voicelineId\": 107037, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_pref_birthday_01\", \"description\": \"生日快乐！我也不知道有什么可以送你的，你的前途上灾星恶曜不显，爱情、功业、武勋的运势也很通畅。米克特兰式的祝福对你效果甚微。之前本想送你我传教用的《菲谢尔皇女夜谭》，但是看到你好像有很多八重堂藏书，我都羡慕…这可为难了，送你什么好呢？\", \"voicelineId\": 107038, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_starUp_01\", \"description\": \"不像是提瓦特外面世界的占卜技术，我——至少我这一系不依靠天，反而更依靠大地。天上虚假的凶星恶曜显露之时，我就依靠迷烟、大地之灵和动物骨头将其绑缚。\", \"voicelineId\": 107039, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_starUp_02\", \"description\": \"天上对人间命运的操控如同木偶提线，这些恶曜本身并没有自我意志。但是这些力量被封进布偶体内之后，凭着小动物骨头附着的念头，它们呈现出了意识。我把这些玩意…咳…小家伙叫做「星魔」，可以说是凶星恶曜的化现吧。\", \"voicelineId\": 107040, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_starUp_03\", \"description\": \"每个布偶里都有小动物的骨头，仔细想想确实也有点瘆人吧。用这样的秘术，被其他人所恐惧，可能有十分之一的责任确实在我。但是这都是我游历野外时收捡的，我可没有伤害小动物！你可不能误会我！\", \"voicelineId\": 107041, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_citlali/vo_citlali_starUp_04\", \"description\": \"从今以后，我会一直与你同行。直到所有星辰消隐，直到所有的火熄灭，直到迷烟散尽。\", \"voicelineId\": 107042, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_skill1_01\", \"description\": \"出来干活！\", \"voicelineId\": 107043, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_skill1_02\", \"description\": \"履行盟约吧，星魔们。\", \"voicelineId\": 107044, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_skill1_03\", \"description\": \"不必留情。\", \"voicelineId\": 107045, \"voicelineType\": \"100003\"}, {\"title\": \"元素战技·其四\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_skill1_04\", \"description\": \"小心…小心地…\", \"voicelineId\": 107046, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其五\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_skill1_05\", \"description\": \"不会手抖的。\", \"voicelineId\": 107047, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其六\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_skill1_06\", \"description\": \"好的。\", \"voicelineId\": 107048, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_skill3_01\", \"description\": \"灭口交给你们俩了！\", \"voicelineId\": 107049, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_skill3_02\", \"description\": \"茜特菈琳、伊兹帕帕，给我上！\", \"voicelineId\": 107050, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_skill3_03\", \"description\": \"让你见识见识恶曜伤人！\", \"voicelineId\": 107051, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_chest_open_01\", \"description\": \"挺好的，收下吧。\", \"voicelineId\": 107052, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_chest_open_02\", \"description\": \"先收下，答谢诸星的祈祷我替你做。\", \"voicelineId\": 107053, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_chest_open_03\", \"description\": \"两只手都抱不下的话我来帮你。\", \"voicelineId\": 107054, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_life_less30_01\", \"description\": \"不该出门的…\", \"voicelineId\": 107055, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_life_less30_02\", \"description\": \"唉，想回家啊。\", \"voicelineId\": 107056, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_life_less30_03\", \"description\": \"不能…在你面前…\", \"voicelineId\": 107057, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_life_less30_teammate_01\", \"description\": \"…不许死！\", \"voicelineId\": 107058, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_life_less30_teammate_02\", \"description\": \"给奶奶我小心点。\", \"voicelineId\": 107059, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_life_die_01\", \"description\": \"天上的诸曜啊…\", \"voicelineId\": 107060, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_life_die_02\", \"description\": \"大地的迷烟啊…\", \"voicelineId\": 107061, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_life_die_03\", \"description\": \"对不起…\", \"voicelineId\": 107062, \"voicelineType\": \"500003\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_hit_H_01\", \"description\": \"好胆子！\", \"voicelineId\": 107063, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_citlali/vo_citlali_battle_hit_H_02\", \"description\": \"疼疼！\", \"voicelineId\": 107064, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_citlali_teamJoin_01\", \"description\": \"我可没迟到…\", \"voicelineId\": 107065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_citlali_teamJoin_02\", \"description\": \"哈？干什——啊，没事的，准备好了！\", \"voicelineId\": 107066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_citlali_teamJoin_03\", \"description\": \"那我肯定帮忙呀。\", \"voicelineId\": 107067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000108, 'Lan Yan', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_draw_appear_01\", \"description\": \"你好，我是沉玉谷手工艺工会的蓝砚。是想做点摆件、篮子还是花瓶、家具之类的呢？呃，备用的藤枝藤条不多了，得先去山里采一趟…你也想帮忙？嘻嘻，你人真好，我多送你一顶藤编遮阳帽可好？\", \"voicelineId\": 108000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·每日计划\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_character_idle_01\", \"description\": \"今天的计划？嗯…听随当下的心意而动。明天也是，每天都是，嘻嘻。\", \"voicelineId\": 108001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·传家宝\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_character_idle_02\", \"description\": \"好的藤器经篾薄如绸，纬条细若丝，经久不坏…说它能跟银器一样当传家宝一点都不夸张。\", \"voicelineId\": 108002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·燕子\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_character_idle_03\", \"description\": \"天暖燕子么搭窝窝，升雷扯闪么我家躲。\", \"voicelineId\": 108003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_weather_heavyRain_01\", \"description\": \"赶不及躲雨了，那——安心淋雨吧，还省了跑步的力气。\", \"voicelineId\": 108004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_weather_thunder_01\", \"description\": \"呜哇！借、借你手握一会！\", \"voicelineId\": 108005, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_weather_sunny_01\", \"description\": \"看，阳光扫到的地方都镀上了一层金欸。\", \"voicelineId\": 108006, \"voicelineType\": \"1203\"}, {\"title\": \"起风的时候…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_weather_breezy_01\", \"description\": \"听见吗？我头上的银饰叮铃…叮铃…风很温柔呢！\", \"voicelineId\": 108007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_weather_gale_01\", \"description\": \"叮叮叮叮叮——风有点生气了啊。\", \"voicelineId\": 108008, \"voicelineType\": \"1205\"}, {\"title\": \"在沙漠的时候…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_weather_desert_01\", \"description\": \"喝点水吗？尝尝我瓶子里的吧，泡薄荷叶子果然是明智的选择呢。\", \"voicelineId\": 108009, \"voicelineType\": \"1206\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_greetingMorning\", \"description\": \"被鸟叫吵醒了？哈哈，我去跟它们商量商量，但不一定奏效哦，它们有时也不听我的话。\", \"voicelineId\": 108010, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_greetingNoon\", \"description\": \"采了些很新鲜的花，我这就带回去给妈妈做好吃的…你也来嘛，我家里人见到你肯定高兴！\", \"voicelineId\": 108011, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_greetingNight\", \"description\": \"夜市里有碳烤小昆虫！想一起去尝尝吗？\", \"voicelineId\": 108012, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_greetingNight2\", \"description\": \"我好困…先睡了先睡了，就不陪你熬夜了。\", \"voicelineId\": 108013, \"voicelineType\": \"1004\"}, {\"title\": \"关于蓝砚自己·幸福感\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_idle\", \"description\": \"幸福感就是…每一口都细嚼慢咽直到吃完碗里最后一粒米，躺在草地上听着耳边的呼呼风声睡午觉，不被打扰地看完整整十册的志怪连载小说！\", \"voicelineId\": 108014, \"voicelineType\": \"2001\"}, {\"title\": \"关于蓝砚自己·奇门世家\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_idle2\", \"description\": \"那位万象风角灵官在蓝氏的族谱中确有记载，可我家这一脉早已从宗家分枝散叶了。奇门术法纷繁复杂，我也只是学了个皮毛而已，有很多难题我还要向前辈们请教呢…但唯独扎藤人的手艺就连爷爷都要向我看齐，哈哈…这能算一种「独当一面」吗？\", \"voicelineId\": 108015, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·握手？\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_close\", \"description\": \"坐好。朋友。握手~\\n啊不不，我是让小动物们看我，不是叫你坐下啦！快请起来…这句话的意思是「大家看过来哦，今天有一位新朋友跟我们一起玩！」有点难懂吗？唔…「坐好」可以是「先别动」或者「听我说」，也可以是「停下来」…规律吗？哎呀总之你多来山里跟我们玩，自然就懂啦。\", \"voicelineId\": 108016, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·握手！\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_close1\", \"description\": \"来呀，握个手，抱一个吧。\\n嗯…？来握手呀？哈哈，这回真的是我想要跟你握手的意思啦！好朋友之间不是这样相互鼓励的吗？对不起哦，怪我没有事先说清楚。但也没关系，我会多去找你玩，这样自然你也懂我我也懂你啦。\", \"voicelineId\": 108017, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_pendant_01\", \"description\": \"感谢神之眼的助力，我居然能毫不费力地将环刃抛起又稳稳接住…啊，环刃非常锋利，小朋友切勿模仿！但如果是你…要上手试试吗？身要定，臂要稳，手要疾，你的话一定能做到！\", \"voicelineId\": 108018, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_share_01\", \"description\": \"想吃野蕈真的不能马虎，许多有毒的蕈子根本吃不得。另一些，则必须在处理的时候加工到位，用油炒熟！如果一顿吃不完，第二顿也要再次炒熟炒透，很多人就是在第二次中的招！如果吃两口后看到家里的鸡来找你借火，或者院子里的狗喊你去收衣服了，那么不要犹豫，赶快叫它们带你去看医生吧。\", \"voicelineId\": 108019, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_pref_gift_01\", \"description\": \"有一回，我坐在树上编小摆件，伸个懒腰的功夫，刚编的藤制松果就被小松鼠全偷走了！还好后来我用双倍数量的真松果跟它们换回来了…东西被拿走是小事，但破坏小松鼠一天的好心情就不好了！忙活了一天采松果，回家发现是假的！唔…说不定还会被别的小松鼠嘲笑呢…\", \"voicelineId\": 108020, \"voicelineType\": \"3003\"}, {\"title\": \"关于香菱…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_teammate_xiangling_01\", \"description\": \"都说第一印象很重要，在万民堂吃过在璃月港的第一顿饭后，我就后悔了。后悔怎么没有早点来璃月港，这样说不定能早点认识香菱！她听说我老家山里有许多罕见食材后，忙不迭就开始计划来沉玉谷的行程了，到时我一定得让她满载而归。\", \"voicelineId\": 108021, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于胡桃…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_teammate_hutao_01\", \"description\": \"胡堂主给人感觉总是嘻嘻哈哈的，哪怕在危急的困境中她都没有忘记说玩笑话来安抚我…我跟她认识的时间不长，她一直都这样乐观积极吗？嗯…不管怎样，至少从今天开始，祝愿她笑的时候是真的很开心，而不是为了不让身边的人担心。\", \"voicelineId\": 108022, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于刻晴…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_teammate_keqing_01\", \"description\": \"玉衡大人什么时候能闲下来呢？海灯节期间看她东奔西跑忙个不停，也没能找到机会请她吃顿饭，好好感谢她的招待…我还想拜托她帮我梳一对跟她一样的猫猫耳朵呢…会不会很僭越？但直觉告诉我她不会介意欸…\", \"voicelineId\": 108023, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于行秋…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_teammate_xingqiu_01\", \"description\": \"我曾在山林里偶遇过行秋少爷几回，他身边没有飞云商会的伙计跟着，看起来不像在办公事…在那以后他时不时会给我送几本最新出版的志怪小说，请我帮他保守秘密。完了…我是不是不小心说出来了…这下请你帮我们俩都保守住秘密啊！\", \"voicelineId\": 108024, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于重云…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_teammate_chongyun_01\", \"description\": \"有一次我跟着爷爷上门占卦，正巧碰到他从事主家中沮丧离开…我本以为屋里头的情况不容乐观，就连他也无计可施了。可我进屋后并没有感受到任何不妙的气息，爷爷这边得出的也是吉卦…兴许是他费了大功夫，累到没力气说话了。你说他很可能什么都没做？那我就更不懂了…\", \"voicelineId\": 108025, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于嘉明…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_teammate_gaming_01\", \"description\": \"我跟嘉明从小就认识，还记得他小时候是家喻户晓的淘气大魔王，现在完全看不出来？哈哈，也许这就是成长吧，我也跟小时候不太一样呢。但有一点他始终没变——就是走到哪总会带点好吃的在身上，每次回来都不会忘记给家乡朋友带些外地的点心。当然，更不会忘记打包一堆家乡小吃带走…\", \"voicelineId\": 108026, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于七七…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_teammate_qiqi_01\", \"description\": \"七七姑娘喜欢小团雀对吗？想用藤皮编一只送给她…你知道她喜欢什么颜色吗？\", \"voicelineId\": 108027, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解蓝砚·其一\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_friendship_01\", \"description\": \"先别说话！稍等一下…马上…编完这个把手就好…呼…搞定！嘻嘻别见怪，我脑筋比较简单，一时只能干一件事。但现在可以专心跟你聊天啦。\", \"voicelineId\": 108028, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解蓝砚·其二\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_friendship_02\", \"description\": \"要来山里面玩吗？可以和柔柔羊玩躲避头槌，或者让朱喙鹈鹕扮演大嘴巴强盗，在限定时间内从它嘴里解救可怜的玉玉心羽鲈…想玩风行迷踪？你当猎手？哼哼，很自信嘛。好吧，要是你急得打转，我会摇响银铃给你提示的，摸到我的发尖就算你赢，我也是很自信的哦。\", \"voicelineId\": 108029, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解蓝砚·其三\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_friendship_03\", \"description\": \"我头上的银饰是「银翎翦玉玄鸟」，是家中祖传的宝贝。银簪、银项圈、胸兜坠是爸爸妈妈给我的庆生礼物…噢，银手镯是有一年海灯节爷爷送的，银耳坠好像是逐月节的礼物…还有庆祝我学会用风之翼送的、庆祝我拿到神之眼送的、庆祝我吃了满满三大碗米饭送的…\\n呵呵，在我们家族的传统里，银器有避邪解毒，护佑平安的作用，所以家人们总会想着法子给我添置…\\n一套行头下来确实很沉呢…是沉甸甸又令人安心的爱哦。\", \"voicelineId\": 108030, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解蓝砚·其四\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_friendship_04\", \"description\": \"小时候，家里放的藤人常常让我发怵，该怎么描述好呢…黑黑灰灰的枯草随便一扎，是小孩子看了就会做噩梦的程度！当时我觉得爷爷一定是中邪了，才把我送去跟宗家的姐姐学害人的法术呢！于是半夜壮着胆子，把能找到的藤人统统烧掉了。好在吸收了病气的藤人本来就是要被焚毁的，算是没捅大篓子…\\n从那时我就开始思考，如果把藤人做得可爱一些，是不是就不容易被人误解成歪门邪术了呢？\", \"voicelineId\": 108031, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解蓝砚·其五\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_friendship_05\", \"description\": \"藤编不难的，我真没骗你！再怎么复杂精妙的工艺，也离不开最简单的一行一竖，一经一纬，只要稍微有点耐心都能编出东西来！比起手艺，更难的是「细心」，再难一些，是要有「恒心」…但在我看来这些都不是最关键的，要我说，最最重要的，是「开心」。要是做起来不开心，什么事情都做不好的，我讲的不止是藤编…总之，要开心呀！我也是，你也是！\", \"voicelineId\": 108032, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"蓝砚的爱好…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_pref_hobby\", \"description\": \"之前我特别想要求证溺鬼的传说，就用棍子伸进闹水鬼的湖里…结果棍子真的被拽住了！水下面全是水草！要是下去游泳不被缠住才怪了…\\n我还听说，日落后不要吃日落果，半夜时分不能对着镜子削苹果，这里头到底有什么依据呢…唔…\", \"voicelineId\": 108033, \"voicelineType\": \"6001\"}, {\"title\": \"蓝砚的烦恼…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_dialog_annoyed_01\", \"description\": \"剪毛刺可真累人啊，既费眼睛又费手…把我十个指头都扎了个遍…呜。\", \"voicelineId\": 108034, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_pref_foodLike\", \"description\": \"新鲜的花不仅好看好闻，做成糕饼还很好吃！清新不甜腻，再泡上一壶花茶…唔…走吧，一起去采花？不用找花篮啦，去到山里我现编一个。\", \"voicelineId\": 108035, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_pref_foodDislike\", \"description\": \"「糖也只在开心的时候吃才甜」，没心情的话吃什么都觉得差点意思…嘻嘻，好在这种情况很少发生。\", \"voicelineId\": 108036, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_spice_pref_01\", \"description\": \"好吃欸！稍等，我去把珍藏的纯银餐具拿出来，这才配得上这道菜嘛！\", \"voicelineId\": 108037, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_spice_normal_01\", \"description\": \"噢，谢谢。这里有蘸水哦，蘸着吃更美味。\", \"voicelineId\": 108038, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_spice_dislike_01\", \"description\": \"你尝过了？肚子疼吗？眼前有小人在打转吗？\", \"voicelineId\": 108039, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_pref_birthday_01b\", \"description\": \"按照家里的传统，生日嘛，总得收点银器傍傍身的。喏，这两个小藤人送你，头上有银燕的是我，{M#拿着小银剑的是你},{F#戴着花的是你}，嘻嘻，像不像？\\n藤草我提前熏制过，挂在背包上可以帮你驱蚊除虫。小银饰样式也是我自己设计的，从银匠师傅手里拿回来后又仔细打磨了边角，绝对不会刮手。\\n那么，祝你生辰快乐，愿福气运气常伴你左右！\", \"voicelineId\": 108040, \"voicelineType\": \"7001\", \"voicefile_male\": \"VO_friendship/VO_lanyan/vo_lanyan_pref_birthday_01a\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true, \"hasGenderedVoicefile\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_starUp_01\", \"description\": \"等等，我才编了两个结你怎么就…是你太快了还是我太慢了呢…\", \"voicelineId\": 108041, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_starUp_02\", \"description\": \"银器要时常擦拭才能焕发光亮，人果然也要不断磨练才能「身轻如燕」呀。\", \"voicelineId\": 108042, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_starUp_03\", \"description\": \"握手~握手~握手~还记得吗？意思是表示开心，表示感谢，表示一切好的事情好的心情。\", \"voicelineId\": 108043, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_lanyan/vo_lanyan_starUp_04\", \"description\": \"「燕衔泥，莫与齐」…别小瞧我哟，我的实力一路增长，如今要保护你也算绰绰有余了吧。哎呀，我知道这有不少你的功劳在里头…很感谢你！\", \"voicelineId\": 108044, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_battle_skill1_04\", \"description\": \"翻飞。\", \"voicelineId\": 108045, \"voicelineType\": \"100004\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_battle_skill1_05\", \"description\": \"穿织。\", \"voicelineId\": 108046, \"voicelineType\": \"100005\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_battle_skill1_06\", \"description\": \"跃风。\", \"voicelineId\": 108047, \"voicelineType\": \"100006\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_battle_skill3_01\", \"description\": \"搬疾运厄。\", \"voicelineId\": 108048, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_battle_skill3_02\", \"description\": \"玄燕传喜。\", \"voicelineId\": 108049, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_battle_skill3_03\", \"description\": \"漫卷翩翩。\", \"voicelineId\": 108050, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_chest_open_01\", \"description\": \"可以分我一些吗？沾沾喜气。\", \"voicelineId\": 108051, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_chest_open_02\", \"description\": \"好消息！你快看里面有什么？\", \"voicelineId\": 108052, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_chest_open_03\", \"description\": \"别急，我来数数…\", \"voicelineId\": 108053, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_life_less30_01\", \"description\": \"给我点时间…\", \"voicelineId\": 108054, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_life_less30_02\", \"description\": \"有人帮忙吗？\", \"voicelineId\": 108055, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_life_less30_03\", \"description\": \"难办了…\", \"voicelineId\": 108056, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_life_less30_teammate_01\", \"description\": \"不能硬撑了，快撤下来！\", \"voicelineId\": 108057, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_life_less30_teammate_02\", \"description\": \"换我来吧，它们抓不住我。\", \"voicelineId\": 108058, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_life_die_01\", \"description\": \"唯独现在…不能倒下…\", \"voicelineId\": 108059, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_life_die_02\", \"description\": \"银铃…不响了…\", \"voicelineId\": 108060, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_life_die_03\", \"description\": \"飞不起来…\", \"voicelineId\": 108061, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_battle_hit_L_02\", \"description\": \"别。\", \"voicelineId\": 108062, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_battle_hit_H_01\", \"description\": \"不对头！\", \"voicelineId\": 108063, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_lanyan/vo_lanyan_battle_hit_H_02\", \"description\": \"脾气真差！\", \"voicelineId\": 108064, \"voicelineType\": \"910002\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_lanyan_teamJoin_01\", \"description\": \"去哪都行，不去也行。\", \"voicelineId\": 108065, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_lanyan_teamJoin_02\", \"description\": \"赶街子去喽。\", \"voicelineId\": 108066, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_lanyan_teamJoin_03\", \"description\": \"来啦来啦。\", \"voicelineId\": 108067, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
INSERT INTO `voiceovers` VALUES (10000109, 'Yumemizuki Mizuki', '[{\"title\": \"初次见面…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_draw_appear_01\", \"description\": \"您好。我是梦见月瑞希，一名「心理诊疗师」。如果您有什么烦心事，尽可以来找我倾诉。无论是多么深沉的「噩梦」，我都会将它从您的心里驱除，绝不会留下一丝阴霾。不相信吗？那如果不耽误您的时间…现在要来我的诊室看看吗？\", \"voicelineId\": 109000, \"voicelineType\": \"1006\"}, {\"title\": \"闲聊·心理诊疗\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_character_idle_01\", \"description\": \"昨晚的梦境…味道很美妙，感谢你与我分享。\", \"voicelineId\": 109001, \"voicelineType\": \"1101\"}, {\"title\": \"闲聊·股东事务\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_character_idle_02\", \"description\": \"上个季度的财务报表还没看完…有点头疼呀。\", \"voicelineId\": 109002, \"voicelineType\": \"1102\"}, {\"title\": \"闲聊·郁结\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_character_idle_03\", \"description\": \"如果心里郁闷的话，就先放下手头的事，出去呼吸一下新鲜空气吧。\", \"voicelineId\": 109003, \"voicelineType\": \"1103\"}, {\"title\": \"下雨的时候…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_weather_heavyRain_01\", \"description\": \"阴翳的天气，容易勾起人心深处的负面情绪…\", \"voicelineId\": 109004, \"voicelineType\": \"1201\"}, {\"title\": \"打雷的时候…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_weather_thunder_01\", \"description\": \"莫非…将军大人今天的心情不好？\", \"voicelineId\": 109005, \"voicelineType\": \"1202\"}, {\"title\": \"阳光很好…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_weather_sunny_01\", \"description\": \"阳光太过耀眼，倒也不是完完全全的好事，照得我有点眩晕…\", \"voicelineId\": 109006, \"voicelineType\": \"1203\"}, {\"title\": \"雨过天晴…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_weather_afterRain_01\", \"description\": \"天上的乌云散去了，是时候收拾心头的阴霾了。\", \"voicelineId\": 109007, \"voicelineType\": \"1204\"}, {\"title\": \"刮大风了…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_weather_gale_01\", \"description\": \"嗯，风力刚好，神清气爽，心情也好。\", \"voicelineId\": 109008, \"voicelineType\": \"1205\"}, {\"title\": \"早上好…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_greetingMorning\", \"description\": \"我已经把窗户打开，给房间通过风了。日出时分的清新空气、逐渐明亮的天色、还有微凉的早风，都会让人心情明朗…早上好。\", \"voicelineId\": 109009, \"voicelineType\": \"1001\"}, {\"title\": \"中午好…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_greetingNoon\", \"description\": \"在中午时分，可以略微午睡一会补充精神…但别睡太久，会头晕的。需要我稍后叫醒你吗？\", \"voicelineId\": 109010, \"voicelineType\": \"1002\"}, {\"title\": \"晚上好…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_greetingNight\", \"description\": \"快到夜晚了，希望大家都能按时入睡，别熬夜玩游戏、看小说或者跳舞了…如果熬一个大夜，在凌晨才睡觉的话，睡眠的意义就大打折扣了…\", \"voicelineId\": 109011, \"voicelineType\": \"1003\"}, {\"title\": \"晚安…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_greetingNight2\", \"description\": \"你要睡了么？正好，请把这杯牛奶喝了吧，我在里面加了一些草药，能让你睡得更好。晚安，你一定会做个好梦。\", \"voicelineId\": 109012, \"voicelineType\": \"1004\"}, {\"title\": \"关于梦见月瑞希自己·温泉的差别\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_idle\", \"description\": \"纳塔的温泉池开在了广阔的临海位置。一边享受凉快又清新的海风，一边和伙伴们玩耍的体验十分有趣。\\n但想在稻妻推广的话，大家只会说：「和相熟的邻居一起泡澡倒是不错，但要和不认识的陌生人在温泉池里见面，感觉会很不好意思啊…」\\n你看，就连温泉也有水土不服的说法。\", \"voicelineId\": 109013, \"voicelineType\": \"2001\"}, {\"title\": \"关于梦见月瑞希自己·「秋沙钱汤」\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_idle2\", \"description\": \"你听说过稻妻的室内温泉「秋沙钱汤」么？其实，我投资它的时候正在设计一套全新的心理疗愈计划，在计划里，我想先利用加入了各种草药和香精的温泉让客人放松身体，进而放松心神，然后我再为客人进行进一步的诊疗。\\n但是…「秋沙钱汤」的温泉泡起来太舒服，客人泡着泡着就容易直接睡着。醒来之后，还一个劲地夸我诊疗手段高超。\\n我根本没进行任何诊疗啊，客人感觉那么好，只是单纯因为好好睡了一觉而已…\\n明明是好好睡一觉就能解决的问题，为什么会拖成那么严重的疾病呢？\\n唉，大家就别勉强自己了，该睡觉的时候，还是要好好睡觉呀…\", \"voicelineId\": 109014, \"voicelineType\": \"2005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于我们·旅程\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_close\", \"description\": \"我也算是一位旅者，造访过提瓦特七国中的五国。即便如今定居稻妻，我也得时常去往纳塔，处理生意上的事务。所以，我们是同路人，可以多多结伴同行。\", \"voicelineId\": 109015, \"voicelineType\": \"2003\"}, {\"title\": \"关于我们·美梦\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_close1\", \"description\": \"食梦貘一族有条规定：未经允许，绝对不能吞食他人的美梦，那是人们珍贵的宝物，稍有损失便会催生失落的情绪。\\n但你是个特例，你的美梦就像是富饶的宝库，几百年来，我还从没见过像你一样明亮的人…\", \"voicelineId\": 109016, \"voicelineType\": \"2002\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于「神之眼」…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_pendant_01\", \"description\": \"我听人说，「神之眼」是被神明注视之人的证明。在神明的视线下，才会有如此神迹出现。但我也听那些未曾被神明注视的人说…他们也期待着拥有「神之眼」。\\n渴求着不可求之物的人，就算在梦中获得了期冀的宝物，在梦醒时分，反而会更加怅然失怀吧。\\n希望他们…不要为了追寻梦中的虚影，而把现实当作急于摆脱的噩梦。\", \"voicelineId\": 109017, \"voicelineType\": \"3006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"有什么想要分享…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_share_01\", \"description\": \"小安和小彻是我的伙伴，也是我的一部分——她们由我的妖力化形而成，分别代表着我的「智」和「灵」，是我心中理性和感性的显化。她们偶尔会协助我诊疗，在不得不战斗时，也非常下得去手呢。\", \"voicelineId\": 109018, \"voicelineType\": \"3002\"}, {\"title\": \"感兴趣的见闻…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_pref_gift_01\", \"description\": \"在「流泉之众」遇袭的前一天，我正从纳塔赶回稻妻，事后才从玛拉妮的来信中听说，你是改变局面的关键人物。这么一想，结合神子的描述，我曾在稻妻和纳塔两次错失与你见面的机会。好在如今，我总算与你这位传说中的旅者相识了。\", \"voicelineId\": 109019, \"voicelineType\": \"3003\", \"unlockConditions\": [{\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子·旧事\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_yaeMiko_01\", \"description\": \"几百年前，我们曾是邻居。神子那家伙…以前可没这么沉迷于各种乐子。有时我还挺怀念的——她刚刚学会化为人形，天真单纯的那段时光…那个时候，她每天都要过来找我，让我尝尝她今天的梦是什么味道。\\n我记得…有樱花、纸张、墨水、三彩团子，还有油豆腐。每次她都要抓着我化成人形，跑到城里寻找和梦里滋味对应的东西，要是被人发现了，我们就会唰地一下变成原来的模样，掉头就跑。我常常还跟不上她。\", \"voicelineId\": 109020, \"voicelineType\": \"4001\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于八重神子·现状\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_yaeMiko_02\", \"description\": \"现在，她已经是「八重宫司」大人了，不知道她如今的梦境，还留有多少原来的气味。\\n当然，我没有再尝过她的梦境。擅自吞吃他人的梦，是我们一族的绝对禁忌。就算宫司大人来找我，请我再尝尝她梦境的味道，我…恐怕也会拒绝吧。如今的我们，已经是彼此的竞争对手了。这次我必须跟上她。\", \"voicelineId\": 109021, \"voicelineType\": \"4002\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于雷电将军…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_raidenShogun_01\", \"description\": \"三川花祭后，我鼓起勇气邀请将军大人共浴。那时，她的一缕侧发飘进了温泉水里。我很想伸手帮她挽起来，却又担心这样的肢体接触会显得冒昧。一想到神子会面不改色地这么做，我就不由沮丧…我的修行，还需精进。\", \"voicelineId\": 109022, \"voicelineType\": \"4003\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [1204209], \"unlockText\": \"完成「须臾百梦」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于珊瑚宫心海…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_kokomi_01\", \"description\": \"海祇岛的那位现人神巫女举止端庄，与她交谈总是让我心情舒畅。今后，若是要在海祇岛拓展「秋沙钱汤」或其他店铺的业务，我还想与她多多合作…\", \"voicelineId\": 109023, \"voicelineType\": \"4004\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于宵宫…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_yoimiya_01\", \"description\": \"你是说那位「夏祭的女王」么？嗯，我对她的印象很深。\\n每隔一段时间，我都会做一次诊疗统计，看看稻妻哪里的居民最容易心力憔悴，哪里的居民心情还算开朗，哪里的居民又经常做噩梦…\\n而宵宫小姐家附近的人们，几乎没有来诊疗过，我想，应该是宵宫小姐帮助了他们吧，有这么一位开朗活泼的邻居作伴，想不开心都难啊。\", \"voicelineId\": 109024, \"voicelineType\": \"4005\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于神里绫华…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_ayaka_01\", \"description\": \"绫华小姐…在我离开稻妻前，她还只是个小女孩，那时她就在练习花道和剑道了。我有一次曾经被她的兄长暗中请去，为她消解忧郁。\\n她的梦境里…尽是老旧的木料味，混合着湿重的雨水气息，就像是一座摇摇欲坠的木亭，孤零零地伫立在暴雨里。我尽力为她诊疗，总算让她得以平和入睡。\\n不知道绫华小姐心里的那座木亭，如今是否已经找到了支撑，能够安然呆在暴雨里了呢…\", \"voicelineId\": 109025, \"voicelineType\": \"4006\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于九条裟罗…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_kujouSara_01\", \"description\": \"在之前，九条将军会定期请我去为天领奉行的人员做诊疗，其他人的心境有时候会有一些动摇，但在九条将军的梦里，我一直都只闻见了冷冷的金属味，既没有雨，也没有太阳，就像是满满堆放着「玉钢」的库房一样。\\n我对九条将军这样心智刚强的人非常敬重。\\n一个人，到底吃多少苦，要怎么做…才能把自己的心锻炼成如今这样呢？\", \"voicelineId\": 109026, \"voicelineType\": \"4007\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于早柚…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_sayu_01\", \"description\": \"呵呵，除了长高的烦恼外，几乎无忧无虑的小貉…她的梦境一定很甜美。要不是她有预感般绕着我走，我还真想请她来「秋沙钱汤」工作。\", \"voicelineId\": 109027, \"voicelineType\": \"4008\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于玛薇卡…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_mavuika_01\", \"description\": \"火神玛薇卡女士？怎么说呢…她是那种，光是看一眼都会让人觉得想要戴上墨镜的人。她就像是真正的太阳那样，只要她握住你的手，你心中所有阴霾和忧郁都会在一瞬间被燃烧殆尽。\\n尝、尝过梦境的味道没有？没有没有没有没有没有，我可不敢细致地尝，之前玛薇卡女士亲切地邀请我，但我一踏进她的梦里，就和跳进了火山一样，烫得我直咳嗽…\\n可能是我的妖力还不够吧…\", \"voicelineId\": 109028, \"voicelineType\": \"4009\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于玛拉妮…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_mualani_01\", \"description\": \"玛拉妮啊…她是我见过最热心的人了，长住纳塔期间，我定居的地方正是「流泉之众」，要是没有她的帮助，我在「流泉之众」的店铺可开不起来。当时她直接带着我去「话事处」找火神女士，确实吓了我一跳…\\n不过，她的性格也像是海浪一样，有时候飞上浪尖，有时候沉在浪底，还有时候潜进暗流里，我根本捉摸不透她…\\n心理？不用担心她，她是我见过心理状态最好的人之一。我可能还需要向她倾诉呢…\", \"voicelineId\": 109029, \"voicelineType\": \"4010\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"关于纳西妲…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_teammate_nahida_01\", \"description\": \"我造访过须弥，在那位神明的权能范围内，我无法触及任何人的梦境，更不必谈影响和吞食。但那种感觉并非被压制，不曾令我难受，更像一种心平气和的约定…我想，她一定是位友善的神明。\", \"voicelineId\": 109030, \"voicelineType\": \"4011\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [3026], \"unlockText\": \"完成「虚空鼓动，劫火高扬」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解梦见月瑞希·其一\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_friendship_01\", \"description\": \"「吞食梦境」是我们食梦貘一族特有的能力，无论美梦还是噩梦，都能成为我们的食粮，只是味道的好坏有别。以往，我的同族大多出于本能，将这种能力用于饱腹，但随着见闻增长，我意识到，这种能力可以帮助多愁善感的人类消解烦恼，发挥更大的价值…\", \"voicelineId\": 109031, \"voicelineType\": \"5001\"}, {\"title\": \"想要了解梦见月瑞希·其二\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_friendship_02\", \"description\": \"其实，食梦貘一族的妖力并不强大。当年，漆黑的灾厄涌来时，我们只能惶恐地躲藏。邻家的狐斋宫姐姐在那场灾厄中牺牲了，我非常伤心，但无力改变什么…许多人也失去了重要的家人和伙伴，内心遍布疮痍…从那时起，我就有了为人们进行心理诊疗的想法，于是我出国求学，先后游历了璃月、须弥和纳塔，结合我的能力和人类的学术理论，慢慢确立了如今的诊疗之道。\", \"voicelineId\": 109032, \"voicelineType\": \"5002\", \"unlockConditions\": [{\"paramList\": [3], \"unlockText\": \"好感等级达到3后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解梦见月瑞希·其三\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_friendship_03\", \"description\": \"这几年，我虽然不在稻妻，但好在我出资建设的温泉经营得小有名气，大家一听说我是「秋沙钱汤」的大股东，多少会给我些面子。我尽力综合了多国见闻的「心理诊疗」服务才得以推行下去。当然，遇上的挑战也不少…\", \"voicelineId\": 109033, \"voicelineType\": \"5003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"好感等级达到4后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解梦见月瑞希·其四\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_friendship_04\", \"description\": \"于我而言，最大的挑战便是消化噩梦残留下来的负面情绪。唯有面对常规诊疗无法治愈的烦恼时，我才会直接吞食患者的噩梦，这也导致我吞下的噩梦都有着不小的烈性，令我相当困扰…以前，我会找个无人的地方缓慢「消化」它们的余威，要是被人撞见，我会非常难堪…\", \"voicelineId\": 109034, \"voicelineType\": \"5004\", \"unlockConditions\": [{\"paramList\": [5], \"unlockText\": \"好感等级达到5后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [200908], \"unlockText\": \"完成「无念无想，泡影断灭」剧情\", \"conditionType\": \"FETTER_COND_FINISH_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"想要了解梦见月瑞希·其五\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_friendship_05\", \"description\": \"但作为心理诊疗师，帮助患者消解「噩梦」，就是我的职责。\\n…或者说，这是我作为「食梦貘」的存在意义。\\n我之前一直在想，我们「食梦貘」究竟为什么被赋予了这样的能力呢？能做到什么事情呢？如果「吞梦」只是为了饱腹，那梦境对我们来说，也只不过是以另一种形式存在的堇瓜而已，而我们，也和那些只知道叮咬堇瓜，既不知生也不知死的虫孑没有区别。\\n直到做了诊疗师之后，我才找到了我能够做的事，那就是为了稻妻…不，为所有人驱除噩梦。\\n呵…我本来以为，我一生都要独自面对这些「噩梦」了。但是，我却遇见了一位能够破除世间所有困境，连神明都认可，连神明的想法都能改变的人，愿意接受我脆弱的一面，与我分享近乎无尽的美梦…某种意义上，我也是你的「患者」了。\", \"voicelineId\": 109035, \"voicelineType\": \"5005\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"好感等级达到6后开启\", \"conditionType\": \"FETTER_COND_FETTER_LEVEL\"}, {\"paramList\": [5029], \"unlockText\": \"完成「炽烈的还魂诗」剧情\", \"conditionType\": \"FETTER_COND_FINISH_PARENT_QUEST\"}], \"hasUnlockConditions\": true}, {\"title\": \"梦见月瑞希的爱好…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_pref_hobby\", \"description\": \"悠扬轻快的音乐对放松身心尤为有益，在纳塔时，我经常去「流泉之众」的科隆切广场听音乐，享受「悠可琴」那音色饱满的旋律…听说你也会许多乐器，要是有机会，能听你演奏一曲吗？\", \"voicelineId\": 109036, \"voicelineType\": \"6001\"}, {\"title\": \"梦见月瑞希的烦恼…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_dialog_annoyed_01\", \"description\": \"太过强大的噩梦，有时会超出我的接受极限，甚至成为致命的毒物…比如，经历过漆黑灾厄的稻妻将士，在夜神之国与深渊战斗过的纳塔勇士，他们的潜意识或许刻入了绝望和恐惧的色彩，他们的噩梦也如刀割般难以下咽…我曾为一名「巡夜者战争」归来的勇士做过心理诊疗，在吞食她的噩梦后，我一连昏迷了几天…\", \"voicelineId\": 109037, \"voicelineType\": \"6012\"}, {\"title\": \"喜欢的食物…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_pref_foodLike\", \"description\": \"我最喜欢的食物？当然是完美无瑕的梦境了。开玩笑的，我可不会轻易去吃掉别人的美梦…最多，吃些甜食，弥补一下给患者治疗后的精神亏空。\", \"voicelineId\": 109038, \"voicelineType\": \"6003\"}, {\"title\": \"讨厌的食物…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_pref_foodDislike\", \"description\": \"我不能接受潦草的食物，比如…干巴巴的面包、几片萝卜和卷心菜，配上冷冰冰的火腿…要知道，吃饭也是改善心境的重要环节，连一天三餐都随便应付，要如何维持心态健康呢？每个人都该对自己好一点，先从认真对待吃饭这件小事开始吧。\", \"voicelineId\": 109039, \"voicelineType\": \"6004\"}, {\"title\": \"收到赠礼·其一\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_spice_pref_01\", \"description\": \"呜…这道料理的风味，是我做梦也没尝到过的味道。享受这种美味之后，今晚我肯定也能睡得香甜…\", \"voicelineId\": 109040, \"voicelineType\": \"6007\"}, {\"title\": \"收到赠礼·其二\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_spice_normal_01\", \"description\": \"嗯…既平稳又美好的味道，就像我平时入睡时的梦境一样。谢谢你，我很喜欢。\", \"voicelineId\": 109041, \"voicelineType\": \"6008\"}, {\"title\": \"收到赠礼·其三\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_spice_dislike_01\", \"description\": \"你昨晚是不是做了糟糕的梦，没怎么睡好？这样的话…味觉确实可能稍稍失灵…菜肴我晚些再吃，请让我先为你诊疗。\", \"voicelineId\": 109042, \"voicelineType\": \"6009\"}, {\"title\": \"生日…\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_pref_birthday_01\", \"description\": \"今天对你我而言都相当重要，有你来到了这个世界，我才能探访无尽的美梦，见识到瑰丽美妙的天地…不如，就用只属于我们二人的梦境来庆祝吧？当然，要构筑这梦境，还需我们二人一同出力，请向我细致描述你的期望…\", \"voicelineId\": 109043, \"voicelineType\": \"7001\", \"unlockConditions\": [{\"paramList\": [], \"conditionType\": \"FETTER_COND_PLAYER_BIRTHDAY\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·起\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_starUp_01\", \"description\": \"不止武力，我的心力也有所增进，这样一来，我便能面对更为强大的负面情绪了。\", \"voicelineId\": 109044, \"voicelineType\": \"8001\", \"unlockConditions\": [{\"paramList\": [1], \"unlockText\": \"突破等级「1」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·承\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_starUp_02\", \"description\": \"由衷感谢你，在你的支援下，我有信心承受一切诊疗残留的烦恼。\", \"voicelineId\": 109045, \"voicelineType\": \"8002\", \"unlockConditions\": [{\"paramList\": [2], \"unlockText\": \"突破等级「2」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·转\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_starUp_03\", \"description\": \"得到了你的鼓舞，我便能探究脆弱的自我，解析自己的弱点——心理诊疗师的心病，因你而走向康复，这是前所未有的创举。\", \"voicelineId\": 109046, \"voicelineType\": \"8003\", \"unlockConditions\": [{\"paramList\": [4], \"unlockText\": \"突破等级「4」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}, {\"title\": \"突破的感受·合\", \"voicefile\": \"VO_friendship/VO_mizuki/vo_mizuki_starUp_04\", \"description\": \"负面情绪也属于「自我」的一部分。我们焦虑、躁动，以至于恐慌，究其根本是没有信心面对它们，无法在它们与积极的情绪之间找到平衡点。如今，有你在我身旁，我已将这平衡点深深刻入意识底层，再烈再毒的噩梦，我都不会畏惧。\", \"voicelineId\": 109047, \"voicelineType\": \"8004\", \"unlockConditions\": [{\"paramList\": [6], \"unlockText\": \"突破等级「6」阶后开启\", \"conditionType\": \"FETTER_COND_AVATAR_PROMOTE_LEVEL\"}], \"hasUnlockConditions\": true}]', '[{\"title\": \"元素战技·其一\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_battle_skill1_01\", \"description\": \"别皱眉呀。\", \"voicelineId\": 109048, \"voicelineType\": \"100001\"}, {\"title\": \"元素战技·其二\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_battle_skill1_02\", \"description\": \"美梦疗法。\", \"voicelineId\": 109049, \"voicelineType\": \"100002\"}, {\"title\": \"元素战技·其三\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_battle_skill1_03\", \"description\": \"镇定下来。\", \"voicelineId\": 109050, \"voicelineType\": \"100003\"}, {\"title\": \"元素爆发·其一\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_battle_skill3_01\", \"description\": \"噩梦噩梦快离开…\", \"voicelineId\": 109051, \"voicelineType\": \"200001\"}, {\"title\": \"元素爆发·其二\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_battle_skill3_02\", \"description\": \"来吧，小安，小彻。\", \"voicelineId\": 109052, \"voicelineType\": \"200002\"}, {\"title\": \"元素爆发·其三\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_battle_skill3_03\", \"description\": \"「…晓时枕貘醒春风。」\", \"voicelineId\": 109053, \"voicelineType\": \"200003\"}, {\"title\": \"打开宝箱·其一\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_chest_open_01\", \"description\": \"令人愉悦的收获。\", \"voicelineId\": 109054, \"voicelineType\": \"300001\"}, {\"title\": \"打开宝箱·其二\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_chest_open_02\", \"description\": \"心情很不错，更有干劲了。\", \"voicelineId\": 109055, \"voicelineType\": \"300002\"}, {\"title\": \"打开宝箱·其三\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_chest_open_03\", \"description\": \"财富是改善情绪的良药。\", \"voicelineId\": 109056, \"voicelineType\": \"300003\"}, {\"title\": \"生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_life_less30_01\", \"description\": \"不能逞强…\", \"voicelineId\": 109057, \"voicelineType\": \"410001\"}, {\"title\": \"生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_life_less30_02\", \"description\": \"似乎该让步了…\", \"voicelineId\": 109058, \"voicelineType\": \"410002\"}, {\"title\": \"生命值低·其三\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_life_less30_03\", \"description\": \"不妙啊…\", \"voicelineId\": 109059, \"voicelineType\": \"410003\"}, {\"title\": \"同伴生命值低·其一\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_life_less30_teammate_01\", \"description\": \"请退下。\", \"voicelineId\": 109060, \"voicelineType\": \"400001\"}, {\"title\": \"同伴生命值低·其二\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_life_less30_teammate_02\", \"description\": \"请暂时避战。\", \"voicelineId\": 109061, \"voicelineType\": \"400002\"}, {\"title\": \"倒下·其一\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_life_die_01\", \"description\": \"噩梦…蔓延了。\", \"voicelineId\": 109062, \"voicelineType\": \"500001\"}, {\"title\": \"倒下·其二\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_life_die_02\", \"description\": \"无边的漆黑…\", \"voicelineId\": 109063, \"voicelineType\": \"500002\"}, {\"title\": \"倒下·其三\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_life_die_03\", \"description\": \"痛苦…没有散去。\", \"voicelineId\": 109064, \"voicelineType\": \"500003\"}, {\"title\": \"普通受击·其一\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_battle_hit_L_02\", \"description\": \"真粗鲁。\", \"voicelineId\": 109065, \"voicelineType\": \"900002\"}, {\"title\": \"重受击·其一\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_battle_hit_H_01\", \"description\": \"好失态…\", \"voicelineId\": 109066, \"voicelineType\": \"910001\"}, {\"title\": \"重受击·其二\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_battle_hit_H_02\", \"description\": \"麻烦的病患…\", \"voicelineId\": 109067, \"voicelineType\": \"910002\"}, {\"title\": \"重受击·其三\", \"voicefile\": \"VO_gameplay/VO_mizuki/vo_mizuki_battle_hit_H_03\", \"description\": \"如此恶毒的一击…\", \"voicelineId\": 109068, \"voicelineType\": \"910003\"}, {\"title\": \"加入队伍·其一\", \"voicefile\": \"VO_teamJoin/vo_mizuki_teamJoin_01\", \"description\": \"有烦恼要倾诉吗？\", \"voicelineId\": 109069, \"voicelineType\": \"600001\"}, {\"title\": \"加入队伍·其二\", \"voicefile\": \"VO_teamJoin/vo_mizuki_teamJoin_02\", \"description\": \"诊疗时间到了。\", \"voicelineId\": 109070, \"voicelineType\": \"600002\"}, {\"title\": \"加入队伍·其三\", \"voicefile\": \"VO_teamJoin/vo_mizuki_teamJoin_03\", \"description\": \"周围…好像没有噩梦的味道。\", \"voicelineId\": 109071, \"voicelineType\": \"600003\"}]', '2026-05-20 19:41:26');
